SET check_function_bodies = off;
-- @@
CREATE OR REPLACE FUNCTION administration_imports.check_expense_actor(p_country text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL OR NOT coalesce(public.app_is_active(),false)
    OR NOT coalesce(public.app_is_elevated(),false)
    OR nullif(btrim(p_country),'') IS NULL OR lower(btrim(p_country))='all'
    OR NOT coalesce(public.app_write_country_ok(p_country),false) THEN
  RAISE EXCEPTION 'Expense import is not permitted in this country' USING ERRCODE='42501';
 END IF;
 RETURN v_org;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION administration_imports.expense_baseline(p_org uuid, p_country text)
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT md5(coalesce(string_agg(md5(to_jsonb(p)::text),'' ORDER BY p.id),''))
 FROM public.parts_consumption p WHERE p.organisation_id=p_org AND p.country=p_country;
$function$;
-- @@
CREATE OR REPLACE FUNCTION administration_imports.guard_upload_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_reversal administration_imports.upload_reversals;
BEGIN
 IF TG_OP='INSERT' THEN
  IF auth.uid() IS NOT NULL THEN
   NEW.organisation_id:=public.app_current_org(); NEW.uploaded_by:=auth.uid();
  END IF;
 ELSIF NEW.organisation_id IS DISTINCT FROM OLD.organisation_id OR NEW.batch_id IS DISTINCT FROM OLD.batch_id
    OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by THEN
  RAISE EXCEPTION 'Upload history ownership is immutable' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_reversal FROM administration_imports.upload_reversals WHERE batch_id=NEW.batch_id;
 IF FOUND THEN
  NEW.reversed_at:=v_reversal.reversed_at; NEW.reversed_by:=v_reversal.actor;
  NEW.reversed_count:=(v_reversal.result->>'removed')::integer;
 ELSE
  NEW.reversed_at:=NULL; NEW.reversed_by:=NULL; NEW.reversed_count:=NULL;
 END IF;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION ai_tyre_private.backfill_inspections(p_since timestamp with time zone, p_until timestamp with time zone, p_limit integer DEFAULT 100)
 RETURNS TABLE(inspections_scanned integer, jobs_added integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare item public.inspections; n int:=0; added int:=0;
begin
 if p_since is null or p_until is null or p_since>=p_until
 or p_limit<1 or p_limit>250 then raise exception 'Invalid backfill range'; end if;
 for item in select * from public.inspections
 where created_at>=p_since and created_at<p_until
 order by created_at,id limit p_limit
 loop
  n:=n+1;
  added:=added+ai_tyre_private.collect_evidence(item);
 end loop;
 return query select n,added;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION ai_tyre_private.queue_after_inspection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
 perform ai_tyre_private.collect_evidence(new);
 return new;
end $function$;
