CREATE OR REPLACE FUNCTION anum_integration.add_reader_table(p_table text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_rel oid;
  v_rls boolean;
begin
  if p_table !~ '^[a-z_][a-z0-9_]*$' then
    return 'SKIPPED: not a plain table name';
  end if;
  if anum_integration.is_excluded_table(p_table) then
    return 'SKIPPED: accounts, security or personal data are never readable';
  end if;
  select c.oid, c.relrowsecurity into v_rel, v_rls
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname = p_table and c.relkind in ('r', 'p');
  if v_rel is null then
    return 'SKIPPED: no such table in public';
  end if;
  if not v_rls then
    return 'SKIPPED: row level security is off, so the reader could not be pinned to its organisation';
  end if;
  if not exists (select 1 from pg_attribute a
                 where a.attrelid = v_rel and a.attname = 'organisation_id'
                   and not a.attisdropped and a.atttypid = 'uuid'::regtype) then
    return 'SKIPPED: no uuid organisation_id column, so the reader could not be pinned to its organisation';
  end if;
  insert into anum_integration.reader_tables (table_name) values (p_table) on conflict do nothing;
  return 'added: own organisation only, GET only, no writes';
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.apply_reader_policies()
 RETURNS TABLE(table_name text, outcome text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  t record;
  v_select text;
  v_deny constant text := 'not (select anum_integration.is_reader())';
begin
  for t in
    select n.nspname as schema_name, c.relname,
           exists (select 1 from anum_integration.reader_tables a
                   where n.nspname = 'public' and a.table_name = c.relname) as allowed,
           exists (select 1 from pg_attribute at
                   where at.attrelid = c.oid and at.attname = 'organisation_id'
                     and not at.attisdropped and at.atttypid = 'uuid'::regtype) as has_org
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where c.relkind in ('r', 'p') and c.relrowsecurity
      and (n.nspname = 'public' or (n.nspname = 'storage' and c.relname = 'objects'))
    order by n.nspname, c.relname
  loop
    if t.allowed and t.has_org then
      v_select := v_deny || ' or organisation_id = (select anum_integration.reader_org())';
    else
      v_select := v_deny;
    end if;
    begin
      execute format('drop policy if exists anum_reader_select_scope on %I.%I', t.schema_name, t.relname);
      execute format('drop policy if exists anum_reader_no_insert on %I.%I', t.schema_name, t.relname);
      execute format('drop policy if exists anum_reader_no_update on %I.%I', t.schema_name, t.relname);
      execute format('drop policy if exists anum_reader_no_delete on %I.%I', t.schema_name, t.relname);
      execute format('create policy anum_reader_select_scope on %I.%I as restrictive for select to authenticated using (%s)',
                     t.schema_name, t.relname, v_select);
      execute format('create policy anum_reader_no_insert on %I.%I as restrictive for insert to authenticated with check (%s)',
                     t.schema_name, t.relname, v_deny);
      execute format('create policy anum_reader_no_update on %I.%I as restrictive for update to authenticated using (%s) with check (%s)',
                     t.schema_name, t.relname, v_deny, v_deny);
      execute format('create policy anum_reader_no_delete on %I.%I as restrictive for delete to authenticated using (%s)',
                     t.schema_name, t.relname, v_deny);
      table_name := t.schema_name || '.' || t.relname;
      outcome := case when t.allowed and t.has_org then 'read: own organisation only; writes denied'
                      when t.allowed then 'NOT READABLE: allowed but has no uuid organisation_id; writes denied'
                      else 'no reads; writes denied' end;
      return next;
    exception when insufficient_privilege then
      table_name := t.schema_name || '.' || t.relname;
      outcome := 'SKIPPED: not owner (' || sqlerrm || ')';
      return next;
    end;
  end loop;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.is_excluded_table(p_table text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select p_table ~* '^(profiles|users?|auth.*|login.*|.*_logins?|sessions?|.*_sessions?|devices?|.*_devices?|api_keys?.*|.*audit.*|access_.*|.*_access_log.*|notifications?|.*_notifications?|ai_.*|cron_.*|system_.*|password.*|.*_passwords?|console_.*|user_.*|.*_users?|drivers?|driver_.*|.*_drivers?|invitations?|.*_tokens?|secrets?|.*_secrets?)$';
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.is_reader()
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select exists (select 1 from anum_integration.readers r where r.user_id = (select auth.uid()));
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.pre_request()
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_method text := upper(coalesce(current_setting('request.method', true), ''));
  v_path   text := coalesce(current_setting('request.path', true), '');
  v_table  text;
begin
  -- Two steps: anon and service requests carry no user and must not touch the registry.
  if (select auth.uid()) is null then
    return;
  end if;
  if not anum_integration.is_reader() then
    return;
  end if;
  -- PostgREST passes the path under the API root: '/tyre_records' (or 'tyre_records').
  v_table := substring(v_path from '^/?([a-z_][a-z0-9_]*)/?$');
  if v_method not in ('GET', 'HEAD')
     or v_table is null
     or not exists (select 1 from anum_integration.reader_tables a where a.table_name = v_table) then
    raise sqlstate 'PT403' using
      message = 'ANUM reader: read-only access to the allowed tables only',
      hint = 'This user may only GET the tables in anum_integration.reader_tables.';
  end if;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.reader_org()
 RETURNS uuid
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select r.organisation_id from anum_integration.readers r where r.user_id = (select auth.uid());
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.register_reader(p_email text, p_organisation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, organisation_id uuid, role text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user    uuid;
  v_profile jsonb;
  v_org     uuid;
begin
  select u.id into v_user from auth.users u where lower(u.email) = lower(btrim(p_email));
  if v_user is null then
    raise exception 'No Supabase user has the e-mail %: create the TyrePulse user first', p_email;
  end if;
  select to_jsonb(p) into v_profile from public.profiles p where p.id = v_user;
  if v_profile is null then
    raise exception 'User % has no TyrePulse profile: create it through TyrePulse''s user management', p_email;
  end if;
  v_org := coalesce(nullif(v_profile ->> 'org_id', ''), nullif(v_profile ->> 'organisation_id', ''))::uuid;
  if v_org is null then
    raise exception 'User % belongs to no organisation: set its organisation in TyrePulse first', p_email;
  end if;
  if p_organisation_id is not null and p_organisation_id <> v_org then
    raise exception 'User % belongs to organisation %, not %: use a user of the organisation ANUM may read', p_email, v_org, p_organisation_id;
  end if;
  if coalesce((v_profile ->> 'is_super_admin')::boolean, false) or v_profile ->> 'role' = 'Admin' then
    raise exception 'User % is an administrator: use a dedicated user with a read-only role (for example Reporter)', p_email;
  end if;

  insert into anum_integration.readers as r (user_id, organisation_id)
  values (v_user, v_org)
  on conflict on constraint readers_pkey do update set organisation_id = excluded.organisation_id;

  user_id := v_user; organisation_id := v_org; role := v_profile ->> 'role';
  return next;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION anum_integration.verify_reader(p_email text)
 RETURNS TABLE(check_name text, status text, detail text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user  uuid;
  v_org   uuid;
  v_claims text;
  t       record;
  v_n     bigint;
  v_m     bigint;
  v_state text;
  v_guard text;
  v_other text;
begin
  select r.user_id, r.organisation_id into v_user, v_org
  from anum_integration.readers r join auth.users u on u.id = r.user_id
  where lower(u.email) = lower(btrim(p_email));
  if v_user is null then
    check_name := 'registered'; status := 'fail';
    detail := 'Not registered: select * from anum_integration.register_reader(''' || p_email || ''');';
    return next; return;
  end if;
  check_name := 'registered'; status := 'pass'; detail := 'organisation ' || v_org; return next;
  v_claims := json_build_object('sub', v_user, 'role', 'authenticated')::text;

  for t in
    select a.table_name from anum_integration.reader_tables a
    where to_regclass('public.' || quote_ident(a.table_name)) is not null
    order by a.table_name
  loop
    -- Reads: rows of the reader's organisation, and none of any other.
    v_n := null; v_m := null; v_state := null;
    begin
      perform set_config('role', 'authenticated', true);
      perform set_config('request.jwt.claims', v_claims, true);
      execute format('select count(*), count(*) filter (where organisation_id is distinct from %L::uuid) from public.%I',
                     v_org, t.table_name) into v_n, v_m;
      raise exception using errcode = 'P0001', message = 'anum_verify_rollback';
    exception when others then
      if sqlerrm <> 'anum_verify_rollback' then v_state := sqlstate || ' ' || sqlerrm; end if;
    end;
    check_name := 'read ' || t.table_name;
    status := case when v_state is not null then 'fail' when v_m = 0 and v_n > 0 then 'pass' when v_m = 0 then 'warn' else 'fail' end;
    detail := coalesce(v_state, v_n || ' rows visible, ' || v_m || ' of another organisation'
              || case when v_n = 0 then ' (none visible: check the user''s organisation, country and site scope in TyrePulse)' else '' end);
    return next;

    -- Insert must be refused by policy (42501).
    v_state := null;
    begin
      perform set_config('role', 'authenticated', true);
      perform set_config('request.jwt.claims', v_claims, true);
      execute format('insert into public.%I default values', t.table_name);
      raise exception using errcode = 'P0001', message = 'anum_verify_inserted';
    exception when others then
      v_state := case when sqlerrm = 'anum_verify_inserted' then 'inserted' else sqlstate end;
    end;
    check_name := 'insert ' || t.table_name;
    status := case when v_state = '42501' then 'pass' when v_state = 'inserted' then 'fail' else 'warn' end;
    detail := case when v_state = '42501' then 'refused by row level security (rolled back)'
                   when v_state = 'inserted' then 'A ROW WAS ACCEPTED (rolled back): the write policy is missing'
                   else 'refused with ' || v_state || ' before the policy check (rolled back)' end;
    return next;

    -- Update and delete must touch nothing.
    foreach v_other in array array['update', 'delete'] loop
      v_n := null; v_state := null;
      begin
        perform set_config('role', 'authenticated', true);
        perform set_config('request.jwt.claims', v_claims, true);
        if v_other = 'update' then
          execute format('update public.%I set organisation_id = organisation_id', t.table_name);
        else
          execute format('delete from public.%I', t.table_name);
        end if;
        get diagnostics v_n = row_count;
        raise exception using errcode = 'P0001', message = 'anum_verify_rollback';
      exception when others then
        if sqlerrm <> 'anum_verify_rollback' then v_state := sqlstate; end if;
      end;
      check_name := v_other || ' ' || t.table_name;
      status := case when v_state = '42501' or v_n = 0 then 'pass' when v_state is not null then 'warn' else 'fail' end;
      detail := case when v_state is not null then 'refused with ' || v_state || ' (rolled back)'
                     when v_n = 0 then '0 rows changed'
                     else v_n || ' ROWS WOULD CHANGE (rolled back): the write policy is missing' end;
      return next;
    end loop;
  end loop;

  -- A table outside the allow-list (profiles) shows nothing.
  if to_regclass('public.profiles') is not null then
    v_n := null; v_state := null;
    begin
      perform set_config('role', 'authenticated', true);
      perform set_config('request.jwt.claims', v_claims, true);
      execute 'select count(*) from public.profiles' into v_n;
      raise exception using errcode = 'P0001', message = 'anum_verify_rollback';
    exception when others then
      if sqlerrm <> 'anum_verify_rollback' then v_state := sqlstate; end if;
    end;
    check_name := 'read profiles (not allowed)';
    status := case when v_n = 0 or v_state = '42501' then 'pass' else 'fail' end;
    detail := coalesce('refused with ' || v_state, v_n || ' rows visible');
    return next;
  end if;

  -- The API guard: GET on an allowed table passes, anything else is refused.
  select split_part(cfg, '=', 2) into v_guard
  from pg_db_role_setting s join pg_roles r on r.oid = s.setrole, unnest(s.setconfig) cfg
  where r.rolname = 'authenticator' and cfg like 'pgrst.db_pre_request=%';
  check_name := 'api guard installed';
  status := case when v_guard = 'anum_integration.pre_request' then 'pass' else 'fail' end;
  detail := coalesce('PostgREST pre-request = ' || v_guard, 'not set: /rpc and views are not blocked for the reader');
  return next;
  foreach v_other in array array['GET /tyre_records', 'POST /tyre_records', 'PATCH /tyre_records', 'DELETE /tyre_records',
                                 'POST /rpc/anything', 'GET /rpc/anything', 'GET /profiles', 'POST /graphql'] loop
    v_state := 'allowed';
    begin
      perform set_config('role', 'authenticated', true);
      perform set_config('request.jwt.claims', v_claims, true);
      perform set_config('request.method', split_part(v_other, ' ', 1), true);
      perform set_config('request.path', split_part(v_other, ' ', 2), true);
      perform anum_integration.pre_request();
      raise exception using errcode = 'P0001', message = 'anum_verify_rollback';
    exception when others then
      if sqlerrm <> 'anum_verify_rollback' then v_state := 'refused'; end if;
    end;
    check_name := 'api ' || v_other;
    status := case when (v_other = 'GET /tyre_records') = (v_state = 'allowed') then 'pass' else 'fail' end;
    detail := v_state;
    return next;
  end loop;

  -- Tables the policies do not cover: public tables without RLS, and RLS tables added
  -- since this file last ran.
  select string_agg(c.relname, ', ' order by c.relname) into v_other
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity;
  check_name := 'public tables without row level security';
  status := case when v_other is null then 'pass' else 'warn' end;
  detail := coalesce(v_other || ': any signed-in user (the reader too) is limited only by grants there; the API guard still blocks the reader', 'none');
  return next;
  select string_agg(c.relname, ', ' order by c.relname) into v_other
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and c.relrowsecurity
    and not exists (select 1 from pg_policy p where p.polrelid = c.oid and p.polname = 'anum_reader_no_insert');
  check_name := 'reader policies on every RLS table';
  status := case when v_other is null then 'pass' else 'fail' end;
  detail := coalesce('missing on ' || v_other || ': run this file again', 'all covered');
  return next;

  check_name := 'old anum_reader login removed';
  status := case when exists (select 1 from pg_roles where rolname = 'anum_reader' and rolcanlogin) then 'fail' else 'pass' end;
  detail := case when status = 'pass' then 'no anum_reader login' else 'anum_reader can still log in' end;
  return next;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.assert_scope(p_type text, p_org uuid, p_country text, p_site text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(app_is_active(),false) OR p_org IS DISTINCT FROM app_current_org() OR NOT approval_private.caller_module_access(p_type)
 OR NOT coalesce(p_country IS NULL OR is_super_admin() OR app_sees_all_countries() OR lower(btrim(p_country))=ANY(coalesce(app_country_scope(),'{}'::text[])),false)
 OR NOT coalesce(nullif(btrim(p_site),'') IS NULL OR app_sees_all_sites() OR upper(btrim(p_site))=ANY(coalesce(app_site_scope(),'{}'::text[])),false) THEN
  RAISE EXCEPTION 'Execution request unavailable in your scope' USING ERRCODE='42501'; END IF;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.caller_module_access(p_type text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT coalesce(approval_policy_is_admin() OR EXISTS(SELECT 1 FROM unnest(approval_private.module_keys(p_type)) k WHERE app_user_can(k,'view')),false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.can_execute(p_type text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT coalesce(app_is_active(),false) AND coalesce(approval_policy_is_admin() OR app_user_can(CASE WHEN p_type='work_order' THEN 'work_orders' ELSE 'tyre_records' END,'edit'),false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.content(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
 SELECT p-ARRAY['updated_at','approval_status','approver_name','approver_email','approver_signature','approved_by','approved_at',
 'supervisor_name','supervisor_signature','supervisor_by','supervisor_at','review_note','locked','locked_at','status','approval_workflow_id','approval_outcome','executed_at','executed_by','execution_operation_id','execution_result']
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.context(p_type text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w workflow_instances; stage jsonb; eligible boolean; token text; history jsonb; revision bigint; represented uuid; status text:=d->>'approval_status';
BEGIN
 revision:=('x'||substr(md5(approval_private.content(d)::text),1,13))::bit(52)::bigint;
 IF d->>'approval_workflow_id' IS NOT NULL THEN
  SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid AND organisation_id=app_current_org();
  stage:=w.steps->w.current_step; token:=w.id::text||':'||w.current_step::text||':'||w.approval_route_revision::text;
  represented:=approval_private.represented_actor(w);
  eligible:=w.status IN ('pending','in_review') AND w.context->>'routing_status'='matched'
   AND represented IS NOT NULL
   AND w.started_by IS DISTINCT FROM auth.uid()
   AND (NOT coalesce((stage->>'distinct_reviewer')::boolean,true) OR NOT EXISTS(SELECT 1 FROM workflow_step_events WHERE instance_id=w.id AND action='approved'
    AND (actor_id IN(auth.uid(),represented) OR device_info->>'represented_actor_id' IN(auth.uid()::text,represented::text))));
  SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]'::jsonb) INTO history FROM workflow_step_events e WHERE instance_id=w.id;
 ELSE token:=status; eligible:=NOT coalesce((d->>'approval_policy_required')::boolean,false); history:='[]'::jsonb; END IF;
 eligible:=coalesce(eligible,false) AND CASE WHEN p_type='inspection' THEN status='pending_approval' AND (is_super_admin() OR get_my_role()=ANY(ARRAY['Admin','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager','Tyre Data Collector']))
 ELSE status IN ('pending','pending_area_manager') AND checklist_is_supervisor() AND (status<>'pending_area_manager' OR checklist_is_area_manager()) END;
 RETURN jsonb_build_object('entity_type',p_type,'entity_id',d->>'id','mode',CASE WHEN w.id IS NULL AND NOT coalesce((d->>'approval_policy_required')::boolean,false) THEN 'legacy' ELSE 'enforced' END,
 'revision',revision,'stage_token',token,'status',status,'document',d,'policy',w.context->'policy','stages',coalesce(w.steps,'[]'::jsonb),
 'current_stage',coalesce(w.current_step,0),'can_decide',coalesce(eligible AND (p_type<>'checklist' OR w.id IS NULL OR w.context->'template' IS NOT DISTINCT FROM d->'checklist_templates') AND (p_type NOT IN ('work_order','tyre_change') OR approval_private.source_matches(p_type,d->'source_snapshot',d->'current_source_snapshot')),false),
 'can_return',coalesce(eligible,false),'workflow_status',coalesce(w.status,d->>'approval_outcome',status),
 'represented_actor_id',represented,'routing_status',w.context->>'routing_status','history',history,
 'can_recover',coalesce(approval_policy_is_admin() AND w.status='pending' AND w.current_step=0 AND w.context->>'routing_status'<>'matched',false),
 'can_reassign',coalesce(approval_policy_is_admin() AND w.status IN ('pending','in_review') AND w.context->>'routing_status'='matched',false),
 'can_delegate',coalesce(eligible AND represented=auth.uid(),false),
 'delegations',coalesce((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('delegator_name',p.full_name,'delegate_name',q.full_name,'can_revoke',a.active AND (a.delegator_id=auth.uid() OR approval_policy_is_admin())) ORDER BY a.created_at)
  FROM approval_delegations a JOIN profiles p ON p.id=a.delegator_id JOIN profiles q ON q.id=a.delegate_id WHERE a.approval_workflow_id=w.id),'[]'::jsonb));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.decision_fields(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
 SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(p) WHERE key=ANY(ARRAY[
 'approval_status','approver_name','approver_email','approver_signature','approved_by','approved_at',
 'supervisor_name','supervisor_signature','supervisor_by','supervisor_at','review_note','locked','locked_at','status'])
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.document(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; tpl jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(app_is_active(),false) OR app_current_org() IS NULL THEN RAISE EXCEPTION 'Approval access denied' USING ERRCODE='42501'; END IF;
 IF p_type='inspection' THEN
  SELECT to_jsonb(i) INTO d FROM inspections i WHERE id=p_id AND organisation_id=app_current_org() FOR UPDATE;
 ELSIF p_type='checklist' THEN
  SELECT to_jsonb(c) INTO d FROM checklist_submissions c WHERE id=p_id AND organisation_id=app_current_org() FOR UPDATE;
  IF d IS NOT NULL THEN SELECT to_jsonb(t) INTO tpl FROM checklist_templates t WHERE id=(d->>'template_id')::uuid FOR SHARE; d:=d||jsonb_build_object('checklist_templates',tpl); END IF;
 ELSIF p_type IN ('work_order','tyre_change') THEN d:=approval_private.execution_document(p_type,p_id);
 ELSE RAISE EXCEPTION 'Unsupported approval module' USING ERRCODE='22023'; END IF;
 IF d IS NULL THEN RAISE EXCEPTION 'Approval record unavailable' USING ERRCODE='42501'; END IF;
 IF NOT ((d->>'country' IS NULL) OR is_super_admin() OR app_sees_all_countries() OR lower(btrim(d->>'country'))=ANY(coalesce(app_country_scope(),'{}'::text[])))
 OR NOT (nullif(btrim(d->>'site'),'') IS NULL OR app_sees_all_sites() OR upper(btrim(d->>'site'))=ANY(coalesce(app_site_scope(),'{}'::text[]))) THEN
  RAISE EXCEPTION 'Approval record unavailable' USING ERRCODE='42501'; END IF;
 IF NOT approval_private.caller_module_access(p_type) THEN
  RAISE EXCEPTION 'Approval module access denied' USING ERRCODE='42501'; END IF;
 RETURN d;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.document_region(p_org uuid, p_country text, p_asset text, p_site text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 WITH v AS (
  SELECT f.site FROM vehicle_fleet f
   WHERE f.organisation_id=p_org AND nullif(btrim(p_asset),'') IS NOT NULL
     AND upper(btrim(f.asset_no))=upper(btrim(p_asset))
   ORDER BY (f.country IS NOT DISTINCT FROM p_country) DESC, (coalesce(f.status,'Active')='Active') DESC, f.id
   LIMIT 1
 ), r AS (
  SELECT (SELECT site FROM v) AS base_site,
         approval_private.site_region(p_org,p_country,(SELECT site FROM v)) AS vehicle_region,
         approval_private.site_region(p_org,p_country,p_site) AS site_region
 )
 SELECT jsonb_build_object(
  'region', coalesce(vehicle_region, site_region),
  'basis', CASE WHEN vehicle_region IS NOT NULL THEN 'vehicle_base_site' WHEN site_region IS NOT NULL THEN 'document_site' ELSE 'none' END,
  'base_site', base_site)
 FROM r
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.enforced(p_type text, p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT EXISTS(SELECT 1 FROM approval_policies WHERE organisation_id=p_org AND entity_type=p_type AND effective_at<=now())
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.execution_decide(p_type text, p_id uuid, p_decision text, p_note text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- cap-guard:approve
  if public.app_cap_revoked(CASE WHEN p_type='work_order' THEN 'work_orders' ELSE 'tyre_records' END,'approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
 UPDATE approval_execution_requests SET approval_status=p_decision,approved_by=auth.uid(),approved_at=clock_timestamp(),
 approver_signature=p_signature,approver_name=(SELECT coalesce(full_name,username) FROM profiles WHERE id=auth.uid()),review_note=p_note
 WHERE id=p_id AND entity_type=p_type AND organisation_id=app_current_org() AND approval_status='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'Execution approval stage changed' USING ERRCODE='PT409'; END IF;
 RETURN jsonb_build_object('ok',true,'status',p_decision);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.execution_document(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r approval_execution_requests; source jsonb;
BEGIN
 SELECT * INTO r FROM approval_execution_requests WHERE id=p_id AND entity_type=p_type AND organisation_id=app_current_org();
 IF NOT FOUND THEN RAISE EXCEPTION 'Execution request unavailable' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope(p_type,r.organisation_id,r.country,r.site);
 IF p_type='work_order' THEN
  SELECT to_jsonb(w) INTO source FROM work_orders w WHERE id=r.work_order_id AND organisation_id=app_current_org() FOR UPDATE;
 ELSE
  IF r.executed_at IS NULL THEN source:=approval_private.tyre_source(r.vehicle_id,r.payload); ELSE source:=r.source_snapshot; END IF;
 END IF;
 IF source IS NULL THEN RAISE EXCEPTION 'Source record unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM approval_execution_requests WHERE id=p_id FOR UPDATE;
 RETURN to_jsonb(r)||jsonb_build_object('current_source_snapshot',source);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.guard_delegation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE instance uuid; w workflow_instances;
BEGIN
 instance:=CASE WHEN TG_OP='DELETE' THEN OLD.approval_workflow_id ELSE NEW.approval_workflow_id END;
 IF TG_OP='UPDATE' THEN instance:=coalesce(OLD.approval_workflow_id,instance); END IF;
 IF instance IS NOT NULL THEN
  SELECT * INTO w FROM workflow_instances WHERE id=instance;
  IF NOT EXISTS(SELECT 1 FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=w.entity_type AND entity_id=w.entity_id::uuid) THEN
   RAISE EXCEPTION 'Use the scoped approval delegation service' USING ERRCODE='42501'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.guard_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE kind text:=coalesce(to_jsonb(NEW)->>'entity_type',CASE WHEN TG_TABLE_NAME='inspections' THEN 'inspection' ELSE 'checklist' END);
 old_json jsonb; new_json jsonb; permit boolean; governed boolean;
BEGIN
 new_json:=to_jsonb(NEW);
 SELECT EXISTS(SELECT 1 FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=kind AND entity_id=NEW.id) INTO permit;
 IF TG_OP='INSERT' THEN
  NEW.approval_revision:=1; NEW.approval_workflow_id:=NULL; NEW.approval_outcome:=NULL;
  NEW.approval_policy_required:=TG_TABLE_NAME='approval_execution_requests' OR EXISTS(SELECT 1 FROM approval_policies WHERE organisation_id=NEW.organisation_id AND entity_type=kind AND effective_at<=now());
  IF NEW.approval_policy_required
   AND NEW.approval_status IN ('approved','pending_area_manager') THEN RAISE EXCEPTION 'Submit for approval before a decision' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 old_json:=to_jsonb(OLD); governed:=OLD.approval_workflow_id IS NOT NULL OR OLD.approval_policy_required;
 NEW.approval_policy_required:=OLD.approval_policy_required;
 IF NOT permit THEN
  NEW.approval_outcome:=OLD.approval_outcome;
  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
   NEW.approval_outcome:=CASE WHEN NEW.approval_status IN ('approved','rejected') THEN NEW.approval_status ELSE NULL END;
  END IF;
 END IF;
 IF NEW.approval_status IN ('pending','pending_approval') AND NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
  NEW.approval_policy_required:=EXISTS(SELECT 1 FROM approval_policies WHERE organisation_id=NEW.organisation_id AND entity_type=kind AND effective_at<=now());
 END IF;
 IF NOT permit AND (NEW.approval_workflow_id IS DISTINCT FROM OLD.approval_workflow_id) THEN RAISE EXCEPTION 'Approval workflow is server controlled' USING ERRCODE='42501'; END IF;
 NEW.approval_revision:=OLD.approval_revision;
 IF approval_private.content(old_json)-'approval_revision'-'approval_policy_required' IS DISTINCT FROM approval_private.content(new_json)-'approval_revision'-'approval_policy_required'
  OR (NEW.approval_status IS DISTINCT FROM OLD.approval_status AND NEW.approval_status IN ('pending','pending_approval')) THEN
  NEW.approval_revision:=OLD.approval_revision+1;
  IF governed AND (OLD.approval_status IN ('pending','pending_area_manager','pending_approval','approved')
   OR EXISTS(SELECT 1 FROM workflow_instances WHERE id=OLD.approval_workflow_id AND status='rejected')) THEN
   RAISE EXCEPTION 'Submitted approval content is immutable; reject and resubmit a corrected revision' USING ERRCODE='PT409'; END IF;
 END IF;
 IF governed AND NOT permit AND approval_private.decision_fields(new_json) IS DISTINCT FROM approval_private.decision_fields(old_json) THEN
  -- Existing rejected submissions may start a new revision through normal submission writes.
  IF NOT(OLD.approval_status='rejected' AND NEW.approval_status IN ('pending','pending_approval')
   AND EXISTS(SELECT 1 FROM workflow_instances WHERE id=OLD.approval_workflow_id AND status='returned')) THEN
   RAISE EXCEPTION 'Use the versioned approval decision service' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.guard_tyre_execution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE enabled boolean; changes_live boolean;
BEGIN
 enabled:=approval_private.enforced('tyre_change',NEW.organisation_id) OR EXISTS(SELECT 1 FROM approval_execution_requests WHERE entity_type='tyre_change' AND organisation_id=NEW.organisation_id AND upper(btrim(asset_no))=upper(btrim(coalesce(NEW.asset_no,NEW.asset_number))) AND executed_at IS NULL);
 IF NOT enabled THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NOT tyre_status_is_active(NEW.status) THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM approval_private.tyre_execution_permits WHERE transaction_id=txid_current() AND may_insert
   AND asset_no=upper(btrim(coalesce(NEW.asset_no,NEW.asset_number))) AND country IS NOT DISTINCT FROM NEW.country AND position=upper(btrim(coalesce(NEW.tyre_position,NEW.position)))) THEN
   RAISE EXCEPTION 'An approved tyre-change request is required before fitting a tyre' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 changes_live:=(tyre_status_is_active(OLD.status) OR tyre_status_is_active(NEW.status)) AND
  (to_jsonb(OLD)-ARRAY['pressure_reading','tread_depth','findings','photos','remarks','remarks_cleaned']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['pressure_reading','tread_depth','findings','photos','remarks','remarks_cleaned']);
 IF changes_live AND NOT EXISTS(SELECT 1 FROM approval_private.tyre_execution_permits WHERE transaction_id=txid_current() AND record_id=OLD.id) THEN
  RAISE EXCEPTION 'Execute an approved tyre-change request before changing active fitment' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.guard_work_start()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r approval_execution_requests; starting boolean; enabled boolean;
BEGIN
 enabled:=approval_private.enforced('work_order',NEW.organisation_id) OR EXISTS(SELECT 1 FROM approval_execution_requests WHERE work_order_id=NEW.id);
 IF TG_OP='INSERT' THEN
  NEW.execution_approval_id:=NULL;
  IF enabled AND (NEW.started_at IS NOT NULL OR NEW.completed_at IS NOT NULL OR lower(NEW.status) NOT IN ('open','new','draft','pending','cancelled','canceled')) THEN
   RAISE EXCEPTION 'Create the work order and obtain approval before starting work' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 NEW.execution_approval_id:=OLD.execution_approval_id;
 IF NOT enabled THEN RETURN NEW; END IF;
 IF OLD.execution_approval_id IS NULL AND OLD.created_at<(SELECT min(effective_at) FROM approval_policies WHERE organisation_id=OLD.organisation_id AND entity_type='work_order' AND effective_at<=now())
  AND (OLD.started_at IS NOT NULL OR lower(OLD.status) NOT IN ('open','new','draft','pending')) THEN RETURN NEW; END IF;
 IF OLD.organisation_id IS DISTINCT FROM NEW.organisation_id THEN RAISE EXCEPTION 'Work-order organisation is immutable' USING ERRCODE='42501'; END IF;
 starting:=(OLD.started_at IS NULL AND NEW.started_at IS NOT NULL)
  OR (OLD.completed_at IS NULL AND NEW.completed_at IS NOT NULL)
  OR (lower(OLD.status) IN ('open','new','draft','pending') AND lower(NEW.status) NOT IN ('open','new','draft','pending','cancelled','canceled'));
 IF NOT starting OR OLD.execution_approval_id IS NOT NULL THEN RETURN NEW; END IF;
 PERFORM approval_private.assert_scope('work_order',NEW.organisation_id,NEW.country,NEW.site);
 IF NOT approval_private.can_execute('work_order') THEN RAISE EXCEPTION 'Work-order edit permission is required to start execution' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM approval_execution_requests WHERE work_order_id=NEW.id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND OR r.approval_status<>'approved' OR r.approval_outcome<>'approved' OR NOT approval_private.source_matches('work_order',r.source_snapshot,to_jsonb(NEW)) THEN
  RAISE EXCEPTION 'This work order needs approval of its current scope before work can start' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM workflow_instances WHERE id=r.approval_workflow_id AND status='approved') THEN RAISE EXCEPTION 'Approval has not completed all stages' USING ERRCODE='42501'; END IF;
 NEW.execution_approval_id:=r.id; NEW.started_at:=coalesce(OLD.started_at,clock_timestamp());
 INSERT INTO approval_private.permits VALUES(txid_current(),'work_order',r.id) ON CONFLICT DO NOTHING;
 UPDATE approval_execution_requests SET executed_at=clock_timestamp(),executed_by=auth.uid(),status='executed',execution_result=jsonb_build_object('work_order_id',NEW.id) WHERE id=r.id;
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type='work_order' AND entity_id=r.id;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.guard_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w workflow_instances; allowed boolean;
BEGIN
 IF TG_TABLE_NAME='workflow_instances' THEN
  IF TG_OP='INSERT' THEN
   IF coalesce((NEW.context->>'approval_matrix')::boolean,false) AND NOT EXISTS(SELECT 1 FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=NEW.entity_type AND entity_id=NEW.entity_id::uuid) THEN
    RAISE EXCEPTION 'Approval snapshots are server controlled' USING ERRCODE='42501'; END IF;
   RETURN NEW;
  END IF;
  w:=OLD;
 ELSE SELECT * INTO w FROM workflow_instances WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.instance_id ELSE NEW.instance_id END; END IF;
 IF coalesce((w.context->>'approval_matrix')::boolean,false) THEN
  SELECT EXISTS(SELECT 1 FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=w.entity_type AND entity_id=w.entity_id::uuid) INTO allowed;
  IF NOT allowed THEN
   IF TG_TABLE_NAME='workflow_step_events' AND TG_OP='INSERT' THEN
    -- Existing hourly cron records overdue alerts, never approval authority.
    IF NEW.action='escalated' AND auth.uid() IS NULL AND session_user IN ('postgres','supabase_admin') THEN RETURN NEW; END IF;
   END IF;
   RAISE EXCEPTION 'Use the versioned approval decision service' USING ERRCODE='42501';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.module_keys(p_type text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT CASE p_type WHEN 'inspection' THEN ARRAY['inspections','mobile:inspections'] WHEN 'checklist' THEN ARRAY['checklists','my_checklists','mobile:checklists']
 WHEN 'work_order' THEN ARRAY['work_orders','mobile:workorders','mobile:work_orders'] WHEN 'tyre_change' THEN ARRAY['tyre_records','mobile:tyreChange','mobile:tyre_records'] ELSE '{}'::text[] END
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.notify_stage(p_instance uuid, p_event text DEFAULT 'assigned'::text, p_user uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w workflow_instances; recipients jsonb; recipient record; label text; message text; event_id bigint;
BEGIN
 SELECT * INTO w FROM workflow_instances WHERE id=p_instance;
 IF NOT FOUND THEN RETURN; END IF;
 INSERT INTO approval_private.stage_deliveries(delivery_key) VALUES(w.id::text||':'||w.current_step::text||':'||w.approval_route_revision::text||':'||p_event||':'||coalesce(p_user::text,'')) ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN; END IF;
 label:=CASE WHEN w.context->>'routing_status'='matched' THEN 'Approval required' ELSE 'Approval routing exception' END;
 message:=coalesce(w.entity_label,w.entity_type)||' ? '||coalesce(w.steps->w.current_step->>'name','publish and recover a matching route');
 recipients:='[]'::jsonb;
 FOR recipient IN SELECT u.id,u.push_token FROM profiles u WHERE u.org_id=w.organisation_id AND u.id IS DISTINCT FROM w.started_by
  AND approval_private.person_eligible(u.id,w.organisation_id,w.entity_type,w.context#>>'{content,country}',w.context#>>'{content,site}')
  AND CASE WHEN p_user IS NOT NULL THEN u.id=p_user
   WHEN w.context->>'routing_status'<>'matched' THEN u.role='Admin' OR u.is_super_admin
   ELSE w.steps->w.current_step->>'approver_user_id'=u.id::text OR w.steps->w.current_step->>'approver_role'=u.role END
 LOOP
  INSERT INTO notifications(user_id,type,title,body,entity_type,entity_id)
  VALUES(recipient.id,'approval',label,message,w.entity_type,w.entity_id::uuid);
  IF nullif(btrim(recipient.push_token),'') IS NOT NULL THEN
   recipients:=recipients||jsonb_build_array(jsonb_build_object('user_id',recipient.id,'push_token',recipient.push_token));
  END IF;
 END LOOP;
 IF jsonb_array_length(recipients)>0 THEN
  INSERT INTO domain_events(event_type,entity_type,entity_id,organisation_id,actor_id,payload,status,processed_at)
  VALUES('approval.matrix_notification',w.entity_type,w.entity_id,w.organisation_id,auth.uid(),jsonb_build_object('instance_id',w.id,'stage',w.current_step,'event',p_event),'processed',clock_timestamp()) RETURNING id INTO event_id;
  -- Persist to the existing deliverer's outbox. Network delivery happens outside this transaction.
  INSERT INTO workflow_notifications(event_id,organisation_id,instance_id,event_type,payload,recipient_count,status)
  VALUES(event_id,w.organisation_id,w.id,'workflow.step_advanced',jsonb_build_object('event_type','workflow.step_advanced','instance_id',w.id,
   'definition_name',w.definition_name,'entity_type',w.entity_type,'entity_label',w.entity_label,'step_name',label,'recipients',recipients,
   'approval_matrix',true,'stage_token',w.id::text||':'||w.current_step::text||':'||w.approval_route_revision::text),jsonb_array_length(recipients),'pending');
 END IF;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.person_eligible(p_user uuid, p_org uuid, p_type text, p_country text, p_site text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT coalesce((SELECT u.approved IS TRUE AND u.locked IS NOT TRUE AND u.org_id=p_org
  AND (u.is_super_admin OR u.role=ANY(CASE WHEN p_type='inspection' THEN ARRAY['Admin','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager','Tyre Data Collector']
   ELSE ARRAY['Admin','Maintenance Supervisor','Workshop Supervisor','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager','Tyre Data Collector'] END))
  AND (p_country IS NULL OR u.is_super_admin OR EXISTS(SELECT 1 FROM unnest(coalesce(u.country,u.countries)) x WHERE lower(btrim(x)) IN ('all',lower(btrim(p_country)))))
  AND (nullif(btrim(p_site),'') IS NULL OR u.is_super_admin OR u.role='Admin' OR EXISTS(SELECT 1 FROM unnest(coalesce(u.sites,ARRAY[u.site])) x WHERE upper(btrim(x)) IN ('ALL','*',upper(btrim(p_site)))))
  AND (u.role='Admin' OR u.is_super_admin OR EXISTS(
   SELECT 1 FROM unnest(approval_private.module_keys(p_type)) k
    WHERE NOT EXISTS(SELECT 1 FROM user_access_grants g WHERE g.user_id=u.id AND g.module_key=k AND g.capability='view' AND g.effect='revoke' AND (g.expires_at IS NULL OR g.expires_at>now()))
    AND (coalesce((SELECT m.enabled FROM module_permissions m WHERE m.org_id IS NULL AND m.role=u.role AND m.module_key=k ORDER BY m.updated_at DESC NULLS LAST LIMIT 1),false)
     OR EXISTS(SELECT 1 FROM user_access_grants g WHERE g.user_id=u.id AND g.module_key=k AND g.capability='view' AND g.effect='grant' AND (g.expires_at IS NULL OR g.expires_at>now())))))
 FROM profiles u WHERE u.id=p_user),false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.resolve(p_org uuid, p_type text, p_country text, p_site text, p_role text, p_user uuid, p_draft uuid DEFAULT NULL::uuid, p_region text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 WITH ctx AS (
  SELECT coalesce(upper(nullif(btrim(p_region),'')),approval_private.site_region(p_org,p_country,p_site)) AS region
 ), candidates AS (
 SELECT p.*,num_nonnulls(p.match_country,p.match_region,p.match_site,p.match_role,p.match_user_id) specificity,
 dense_rank() OVER(ORDER BY p.priority DESC,num_nonnulls(p.match_country,p.match_region,p.match_site,p.match_role,p.match_user_id) DESC) rank
 FROM approval_policies p CROSS JOIN ctx
 WHERE p.organisation_id=p_org AND p.entity_type=p_type AND ((p.state='published' AND p.effective_at<=now()) OR (p.id=p_draft AND p.state='draft'))
 AND (p.match_country IS NULL OR p.match_country=p_country)
 AND (p.match_region IS NULL OR p.match_region=ctx.region)
 AND (p.match_site IS NULL OR p.match_site=p_site)
 AND (p.match_role IS NULL OR p.match_role=p_role) AND (p.match_user_id IS NULL OR p.match_user_id=p_user))
 SELECT jsonb_build_object('mode',CASE WHEN EXISTS(SELECT 1 FROM approval_policies WHERE organisation_id=p_org AND entity_type=p_type AND effective_at<=now()) THEN 'enforced' ELSE 'legacy' END,
 'status',CASE count(*) FILTER(WHERE rank=1) WHEN 0 THEN 'no_route' WHEN 1 THEN 'matched' ELSE 'ambiguous' END,
 'region',(SELECT region FROM ctx),
 'policy',CASE WHEN count(*) FILTER(WHERE rank=1)=1 THEN (jsonb_agg(to_jsonb(candidates)-'rank'-'specificity' ORDER BY rank,id)->0) ELSE NULL END,
 'candidates',coalesce(jsonb_agg(to_jsonb(candidates) ORDER BY rank,id),'[]'::jsonb)) FROM candidates
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.site_region(p_org uuid, p_country text, p_site text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT upper(btrim(s.region)) FROM sites s
  WHERE s.organisation_id=p_org AND nullif(btrim(p_site),'') IS NOT NULL
    AND upper(btrim(s.name))=upper(btrim(p_site))
    AND nullif(btrim(s.region),'') IS NOT NULL
    AND (p_country IS NULL OR s.country=p_country OR NOT EXISTS(
      SELECT 1 FROM sites t WHERE t.organisation_id=p_org AND upper(btrim(t.name))=upper(btrim(p_site)) AND t.country=p_country))
  ORDER BY (s.country IS NOT DISTINCT FROM p_country) DESC, s.active DESC NULLS LAST, s.id
  LIMIT 1
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.source_matches(p_type text, p_original jsonb, p_current jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT CASE WHEN p_type='work_order' THEN approval_private.work_order_content(p_original)=approval_private.work_order_content(p_current)
 ELSE p_original=p_current END
$function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.start_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE kind text:=coalesce(to_jsonb(NEW)->>'entity_type',CASE WHEN TG_TABLE_NAME='inspections' THEN 'inspection' ELSE 'checklist' END);
 route jsonb; requestor uuid; requestor_role text; w uuid; previous uuid; snapshot jsonb; pending boolean; tpl jsonb; place jsonb;
BEGIN
 pending:=NEW.approval_status=CASE WHEN kind='inspection' THEN 'pending_approval' ELSE 'pending' END;
 IF NOT pending OR (TG_OP='UPDATE' AND OLD.approval_status IS NOT DISTINCT FROM NEW.approval_status) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME<>'approval_execution_requests' AND NOT EXISTS(SELECT 1 FROM approval_policies WHERE organisation_id=NEW.organisation_id AND entity_type=kind AND effective_at<=now()) THEN RETURN NEW; END IF;
 requestor:=nullif(CASE WHEN kind='inspection' THEN to_jsonb(NEW)->>'created_by' ELSE to_jsonb(NEW)->>'submitted_by' END,'')::uuid;
 IF requestor IS NULL OR (auth.uid() IS NOT NULL AND requestor<>auth.uid()) THEN RAISE EXCEPTION 'Submitter identity must match the signed-in user' USING ERRCODE='42501'; END IF;
 SELECT role INTO requestor_role FROM profiles WHERE id=requestor AND org_id=NEW.organisation_id AND approved IS TRUE AND locked IS NOT TRUE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Submitting user is unavailable in this organisation' USING ERRCODE='42501'; END IF;
 place:=approval_private.document_region(NEW.organisation_id,NEW.country,to_jsonb(NEW)->>'asset_no',NEW.site);
 route:=approval_private.resolve(NEW.organisation_id,kind,NEW.country,NEW.site,requestor_role,requestor,NULL,place->>'region');
 IF kind='checklist' THEN SELECT to_jsonb(t) INTO tpl FROM checklist_templates t WHERE id=(to_jsonb(NEW)->>'template_id')::uuid; END IF;
 snapshot:=route->'policy'; previous:=NEW.approval_workflow_id;
 INSERT INTO approval_private.permits VALUES(txid_current(),kind,NEW.id) ON CONFLICT DO NOTHING;
 INSERT INTO workflow_instances(organisation_id,entity_type,entity_id,entity_label,definition_name,steps,current_step,status,context,started_by,step_started_at,approval_policy_id)
 VALUES(NEW.organisation_id,kind,NEW.id::text,coalesce(NEW.title,NEW.asset_no),'Approval Matrix',
 coalesce((SELECT jsonb_agg(s||jsonb_build_object('assignee_type',CASE WHEN nullif(s->>'approver_user_id','') IS NOT NULL THEN 'user' ELSE 'role' END)) FROM jsonb_array_elements(snapshot->'stages') s),'[]'::jsonb),0,'pending',
 jsonb_build_object('approval_matrix',true,'policy',snapshot,'routing_status',route->>'status','template',tpl,'content',approval_private.content(to_jsonb(NEW)),
  'region',place->>'region','region_basis',place->>'basis','vehicle_base_site',place->>'base_site'),requestor,clock_timestamp(),nullif(snapshot->>'id','')::uuid) RETURNING id INTO w;
 IF kind='inspection' THEN UPDATE inspections SET approval_workflow_id=w WHERE id=NEW.id; ELSIF kind='checklist' THEN UPDATE checklist_submissions SET approval_workflow_id=w WHERE id=NEW.id; ELSE UPDATE approval_execution_requests SET approval_workflow_id=w WHERE id=NEW.id; END IF;
 INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment)
 VALUES(w,NEW.organisation_id,0,'Approval Matrix','started',requestor,CASE WHEN route->>'status'='matched' THEN 'Published route selected' ELSE 'Routing exception: '||(route->>'status') END);
 PERFORM approval_private.notify_stage(w);
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=kind AND entity_id=NEW.id;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.tyre_source(p_vehicle uuid, p_change jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v vehicle_fleet; dest vehicle_fleet; src tyre_records; occupant tyre_records; source_id uuid; position_text text; target_asset text;
BEGIN
 SELECT * INTO v FROM vehicle_fleet WHERE id=p_vehicle AND organisation_id=app_current_org();
 IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle unavailable' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope('tyre_change',v.organisation_id,v.country,v.site);
 target_asset:=coalesce(nullif(upper(btrim(p_change->>'to_asset_no')),''),upper(btrim(v.asset_no)));
 SELECT * INTO dest FROM vehicle_fleet WHERE organisation_id=v.organisation_id AND upper(btrim(asset_no))=target_asset AND country IS NOT DISTINCT FROM v.country;
 IF NOT FOUND THEN RAISE EXCEPTION 'Destination vehicle unavailable in the same country' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope('tyre_change',dest.organisation_id,dest.country,dest.site);
 IF dest.site IS DISTINCT FROM v.site THEN RAISE EXCEPTION 'Cross-site tyre transfer requires a separate transfer workflow' USING ERRCODE='22023'; END IF;
 -- A stable fleet lock serializes empty-position installs and opposite-direction swaps.
 PERFORM id FROM vehicle_fleet WHERE id IN(v.id,dest.id) ORDER BY id FOR UPDATE;
 SELECT * INTO v FROM vehicle_fleet WHERE id=v.id; SELECT * INTO dest FROM vehicle_fleet WHERE id=dest.id;
 source_id:=nullif(coalesce(p_change->>'tyre_id',p_change->>'removed_record_id'),'')::uuid;
 position_text:=nullif(upper(btrim(coalesce(p_change->>'to_position',p_change->>'position'))),'');
 PERFORM id FROM tyre_records WHERE organisation_id=v.organisation_id AND country IS NOT DISTINCT FROM v.country
  AND (id=source_id OR (upper(btrim(coalesce(asset_no,asset_number)))=target_asset AND upper(btrim(coalesce(tyre_position,position)))=position_text AND tyre_status_is_active(status))) ORDER BY id FOR UPDATE;
 IF source_id IS NOT NULL THEN
  SELECT * INTO src FROM tyre_records WHERE id=source_id AND organisation_id=v.organisation_id AND country IS NOT DISTINCT FROM v.country AND upper(btrim(coalesce(asset_no,asset_number)))=upper(btrim(v.asset_no));
  IF NOT FOUND OR NOT tyre_status_is_active(src.status) THEN RAISE EXCEPTION 'Source tyre is no longer active on this vehicle' USING ERRCODE='PT409'; END IF;
 END IF;
 SELECT * INTO occupant FROM tyre_records WHERE organisation_id=v.organisation_id AND country IS NOT DISTINCT FROM v.country
  AND upper(btrim(coalesce(asset_no,asset_number)))=target_asset AND upper(btrim(coalesce(tyre_position,position)))=position_text AND tyre_status_is_active(status) AND id IS DISTINCT FROM source_id LIMIT 1;
 RETURN jsonb_build_object('vehicle',to_jsonb(v),'source_tyre',CASE WHEN src.id IS NULL THEN NULL ELSE to_jsonb(src) END,
 'destination_tyre',CASE WHEN occupant.id IS NULL THEN NULL ELSE to_jsonb(occupant) END,'destination_vehicle',to_jsonb(dest));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION approval_private.work_order_content(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT p-ARRAY['updated_at','status','started_at','completed_at','execution_approval_id']
$function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_fine_dispatch_reminders(p_as_of date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f public.driver_fines%ROWTYPE; reminder_kind text; reminder_id uuid; recipient_total integer; sent_total integer:=0; skipped_total integer:=0;
BEGIN
  FOR f IN SELECT * FROM public.driver_fines WHERE status='open' AND due_date IS NOT NULL AND superseded_by_fine_id IS NULL
    AND (due_date=p_as_of+7 OR due_date=p_as_of OR due_date<p_as_of) ORDER BY id FOR UPDATE SKIP LOCKED LOOP
    reminder_kind:=CASE WHEN f.due_date=p_as_of+7 THEN 'due_7_days' WHEN f.due_date=p_as_of THEN 'due_today' ELSE 'overdue' END;
    INSERT INTO public.driver_fine_reminders(fine_id,driver_id,organisation_id,reminder_date,kind,status)
      VALUES(f.id,f.driver_id,f.organisation_id,p_as_of,reminder_kind,'skipped') ON CONFLICT DO NOTHING RETURNING id INTO reminder_id;
    IF reminder_id IS NULL THEN CONTINUE; END IF;
    INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
      SELECT recipient,'driver_workspace','Traffic fine reminder',CASE reminder_kind WHEN 'due_7_days' THEN 'A traffic fine is due in seven days.' WHEN 'due_today' THEN 'A traffic fine is due today.' ELSE 'A traffic fine is overdue.' END,'driver_workspace',f.driver_id::text
      FROM (SELECT l.user_id recipient FROM public.driver_account_links l WHERE l.driver_id=f.driver_id
        UNION SELECT a.supervisor_id FROM public.driver_team_assignments a WHERE a.driver_id=f.driver_id AND a.ends_at IS NULL
        UNION SELECT a.manager_id FROM public.driver_team_assignments a WHERE a.driver_id=f.driver_id AND a.ends_at IS NULL
        UNION SELECT p.id FROM public.profiles p WHERE p.org_id=f.organisation_id AND p.approved AND NOT coalesce(p.locked,false) AND lower(btrim(p.role)) IN ('finance','admin')) q
      JOIN public.profiles p ON p.id=recipient WHERE recipient IS NOT NULL AND p.approved AND NOT coalesce(p.locked,false);
    GET DIAGNOSTICS recipient_total=ROW_COUNT;
    UPDATE public.driver_fine_reminders SET status=CASE WHEN recipient_total>0 THEN 'sent' ELSE 'skipped' END,recipient_count=recipient_total WHERE id=reminder_id;
    INSERT INTO public.driver_workspace_events(organisation_id,driver_id,fine_id,actor_id,action,details)
      VALUES(f.organisation_id,f.driver_id,f.id,NULL,'automated_reminder',jsonb_build_object('kind',reminder_kind,'reminder_date',p_as_of,'recipient_count',recipient_total));
    IF recipient_total>0 THEN sent_total:=sent_total+1; ELSE skipped_total:=skipped_total+1; END IF;
  END LOOP;
  RETURN jsonb_build_object('sent',sent_total,'skipped',skipped_total,'as_of',p_as_of);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_fine_enterprise_command(p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid:=auth.uid(); org uuid:=public.app_current_org(); d public.drivers%ROWTYPE; target_driver public.drivers%ROWTYPE;
  f public.driver_fines%ROWTYPE; vehicle public.vehicle_fleet%ROWTYPE; previous private.driver_workspace_requests%ROWTYPE;
  access_mode text; choice text; target_id uuid; new_fine_id uuid; answer jsonb; detail jsonb:=p_payload; stage_name text;
BEGIN
  IF actor IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false) OR p_request_id IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,0));
  SELECT * INTO previous FROM private.driver_workspace_requests WHERE actor_id=actor AND request_id=p_request_id;
  IF FOUND THEN
    IF previous.action<>p_action OR previous.payload<>p_payload THEN RAISE EXCEPTION 'Request key already used' USING ERRCODE='22023'; END IF;
    IF private.driver_workspace_access((previous.result->>'driver_id')::uuid)='none' THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
    RETURN previous.result;
  END IF;
  SELECT * INTO d FROM public.drivers WHERE id=(p_payload->>'driver_id')::uuid AND organisation_id=org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Driver unavailable' USING ERRCODE='42501'; END IF;
  access_mode:=private.driver_workspace_access(d.id);
  IF access_mode='none' OR EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=actor) THEN RAISE EXCEPTION 'Independent staff action required' USING ERRCODE='42501'; END IF;
  SELECT * INTO f FROM public.driver_fines WHERE id=(p_payload->>'fine_id')::uuid AND driver_id=d.id FOR UPDATE;
  IF NOT FOUND OR f.version IS DISTINCT FROM (p_payload->>'version')::integer THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='PT409'; END IF;
  IF length(btrim(coalesce(p_payload->>'reason',''))) < 3 THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;

  IF p_action='review_fine' THEN
    choice:=p_payload->>'decision';
    IF choice='approve' AND f.status='open' AND f.review_stage='supervisor' AND access_mode IN ('manager','supervisor') THEN
      stage_name:='supervisor';
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET review_stage='finance',version=version+1,updated_at=now() WHERE id=f.id;
    ELSIF choice='approve' AND f.status='open' AND f.review_stage='finance' AND private.driver_workspace_is_finance_reviewer() THEN
      IF EXISTS(SELECT 1 FROM public.driver_fine_reviews WHERE fine_id=f.id AND stage='supervisor' AND decision='approve' AND reviewer_id=actor) THEN RAISE EXCEPTION 'A different finance reviewer is required' USING ERRCODE='42501'; END IF;
      stage_name:='finance';
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET response_status='approved',review_stage='complete',version=version+1,updated_at=now() WHERE id=f.id;
    ELSIF choice='return' AND f.status='open' AND ((f.review_stage='supervisor' AND access_mode IN ('manager','supervisor')) OR (f.review_stage='finance' AND private.driver_workspace_is_finance_reviewer())) THEN
      stage_name:=f.review_stage;
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET response_status='returned',review_stage='driver',version=version+1,updated_at=now() WHERE id=f.id;
    ELSIF choice='payment' AND f.status='open' AND f.review_stage='complete' AND f.response_status='approved' AND private.driver_workspace_is_finance_reviewer() THEN
      IF length(btrim(coalesce(p_payload->>'payment_reference',''))) < 3 OR (p_payload->>'payment_amount')::numeric IS NULL OR (p_payload->>'payment_amount')::numeric<=0 OR (p_payload->>'payment_amount')::numeric>f.amount-f.paid_amount THEN RAISE EXCEPTION 'Valid payment amount and reference required' USING ERRCODE='22023'; END IF;
      stage_name:='finance';
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET paid_amount=paid_amount+(p_payload->>'payment_amount')::numeric,
        status=CASE WHEN paid_amount+(p_payload->>'payment_amount')::numeric=amount THEN 'settled' ELSE 'open' END,
        version=version+1,updated_at=now() WHERE id=f.id;
    ELSIF choice='cancel' AND f.status='open' AND f.paid_amount=0 AND access_mode IN ('manager','supervisor') THEN
      stage_name:=CASE WHEN f.review_stage='finance' THEN 'finance' ELSE 'supervisor' END;
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET status='cancelled',review_stage='complete',version=version+1,updated_at=now() WHERE id=f.id;
    ELSIF choice='reopen' AND f.status<>'open' AND access_mode='manager' THEN
      stage_name:='supervisor';
      INSERT INTO public.driver_fine_reviews(fine_id,driver_id,organisation_id,stage,decision,reason,reviewer_id,notice_version,details)
        VALUES(f.id,d.id,org,stage_name,choice,p_payload->>'reason',actor,f.version,p_payload) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET status='open',response_status=CASE WHEN EXISTS(SELECT 1 FROM public.driver_fine_responses WHERE fine_id=f.id) THEN 'submitted' ELSE 'awaiting_response' END,
        review_stage=CASE WHEN EXISTS(SELECT 1 FROM public.driver_fine_responses WHERE fine_id=f.id) THEN 'supervisor' ELSE 'driver' END,version=version+1,updated_at=now() WHERE id=f.id;
    ELSE RAISE EXCEPTION 'Invalid review transition' USING ERRCODE='22023'; END IF;
    detail:=p_payload||jsonb_build_object('review_stage',stage_name,'review_id',target_id);
    target_id:=f.id;
  ELSIF p_action='correct_fine' THEN
    IF NOT coalesce(public.app_user_can('fleet_master','edit'),false) OR f.status<>'open' OR f.superseded_by_fine_id IS NOT NULL THEN RAISE EXCEPTION 'Correction not permitted' USING ERRCODE='42501'; END IF;
    IF p_payload ? 'vehicle_id' THEN
      SELECT * INTO vehicle FROM public.vehicle_fleet WHERE id=(p_payload->>'vehicle_id')::uuid;
      IF NOT FOUND OR vehicle.organisation_id<>org OR NOT private.driver_workspace_scope(vehicle.organisation_id,vehicle.country,vehicle.site) OR vehicle.country IS DISTINCT FROM d.country THEN RAISE EXCEPTION 'Vehicle outside scope' USING ERRCODE='42501'; END IF;
    END IF;
    IF p_payload ? 'amount' AND ((p_payload->>'amount')::numeric<=0 OR (p_payload->>'amount')::numeric<f.paid_amount) THEN RAISE EXCEPTION 'Amount must cover verified payments' USING ERRCODE='22023'; END IF;
    detail:=jsonb_build_object('reason',p_payload->>'reason','before',to_jsonb(f)-'created_by','changes',p_payload-'reason'-'driver_id'-'fine_id'-'version');
    UPDATE public.driver_fines SET
      vehicle_id=CASE WHEN p_payload ? 'vehicle_id' THEN (p_payload->>'vehicle_id')::uuid ELSE vehicle_id END,
      authority=CASE WHEN p_payload ? 'authority' THEN btrim(p_payload->>'authority') ELSE authority END,
      notice_reference=CASE WHEN p_payload ? 'notice_reference' THEN btrim(p_payload->>'notice_reference') ELSE notice_reference END,
      incident_at=CASE WHEN p_payload ? 'incident_at' THEN (p_payload->>'incident_at')::timestamptz ELSE incident_at END,
      due_date=CASE WHEN p_payload ? 'due_date' THEN nullif(p_payload->>'due_date','')::date ELSE due_date END,
      amount=CASE WHEN p_payload ? 'amount' THEN (p_payload->>'amount')::numeric ELSE amount END,
      description=CASE WHEN p_payload ? 'description' THEN p_payload->>'description' ELSE description END,
      assignment_reason=CASE WHEN p_payload ? 'assignment_reason' THEN p_payload->>'assignment_reason' ELSE assignment_reason END,
      response_status=CASE WHEN EXISTS(SELECT 1 FROM public.driver_fine_responses WHERE fine_id=f.id) THEN 'awaiting_response' ELSE response_status END,
      review_stage='driver',version=version+1,updated_at=now() WHERE id=f.id;
    target_id:=f.id;
  ELSIF p_action='reassign_fine' THEN
    IF NOT coalesce(public.app_user_can('fleet_master','edit'),false) OR f.status<>'open' OR f.paid_amount<>0 OR f.superseded_by_fine_id IS NOT NULL THEN RAISE EXCEPTION 'Reassignment not permitted' USING ERRCODE='42501'; END IF;
    SELECT * INTO target_driver FROM public.drivers WHERE id=(p_payload->>'target_driver_id')::uuid AND organisation_id=org AND status='active';
    IF NOT FOUND OR target_driver.id=d.id OR NOT private.driver_workspace_scope(target_driver.organisation_id,target_driver.country,target_driver.site) THEN RAISE EXCEPTION 'Target driver unavailable' USING ERRCODE='42501'; END IF;
    SELECT * INTO vehicle FROM public.vehicle_fleet WHERE id=coalesce((p_payload->>'vehicle_id')::uuid,f.vehicle_id);
    IF NOT FOUND OR vehicle.organisation_id<>org OR vehicle.country IS DISTINCT FROM target_driver.country OR NOT private.driver_workspace_scope(vehicle.organisation_id,vehicle.country,vehicle.site) THEN RAISE EXCEPTION 'Vehicle outside target scope' USING ERRCODE='42501'; END IF;
    new_fine_id:=gen_random_uuid();
    UPDATE public.driver_fines SET status='cancelled',review_stage='complete',superseded_by_fine_id=new_fine_id,version=version+1,updated_at=now() WHERE id=f.id;
    INSERT INTO public.driver_fines(id,organisation_id,driver_id,vehicle_id,country,site,authority,notice_reference,incident_at,due_date,amount,currency,description,assignment_reason,status,response_status,paid_amount,version,created_by,review_stage,supersedes_fine_id)
      VALUES(new_fine_id,org,target_driver.id,vehicle.id,target_driver.country,target_driver.site,f.authority,f.notice_reference,f.incident_at,f.due_date,f.amount,f.currency,f.description,p_payload->>'reason','open','awaiting_response',0,1,actor,'driver',f.id);
    INSERT INTO public.driver_workspace_events(organisation_id,driver_id,fine_id,actor_id,action,details)
      VALUES(org,target_driver.id,new_fine_id,actor,'fine_reassigned_in',jsonb_build_object('previous_fine_id',f.id,'previous_driver_id',d.id,'reason',p_payload->>'reason'));
    detail:=jsonb_build_object('reason',p_payload->>'reason','replacement_fine_id',new_fine_id,'target_driver_id',target_driver.id);
    INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
      SELECT l.user_id,'driver_workspace','Traffic fine assigned','Open your driver workspace to review and acknowledge the reassigned notice.','driver_workspace',target_driver.id::text
      FROM public.driver_account_links l JOIN public.profiles p ON p.id=l.user_id WHERE l.driver_id=target_driver.id AND p.approved AND NOT coalesce(p.locked,false);
    target_id:=new_fine_id;
  ELSE RAISE EXCEPTION 'Unsupported enterprise action' USING ERRCODE='22023'; END IF;

  INSERT INTO public.driver_workspace_events(organisation_id,driver_id,fine_id,actor_id,action,details)
    VALUES(org,d.id,f.id,actor,p_action,detail);
  INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
    SELECT recipient,'driver_workspace','Driver fine workflow updated','Open the driver workspace to review the latest case action.','driver_workspace',d.id::text
    FROM (SELECT l.user_id recipient FROM public.driver_account_links l WHERE l.driver_id=d.id
      UNION SELECT a.supervisor_id FROM public.driver_team_assignments a WHERE a.driver_id=d.id AND a.ends_at IS NULL
      UNION SELECT a.manager_id FROM public.driver_team_assignments a WHERE a.driver_id=d.id AND a.ends_at IS NULL
      UNION SELECT p.id FROM public.profiles p WHERE p.org_id=org AND p.approved AND NOT coalesce(p.locked,false) AND lower(btrim(p.role)) IN ('finance','admin')) q
    WHERE recipient IS NOT NULL AND recipient<>actor;
  answer:=jsonb_build_object('driver_id',CASE WHEN p_action='reassign_fine' THEN target_driver.id ELSE d.id END,'id',target_id,'action',p_action);
  INSERT INTO private.driver_workspace_requests VALUES(actor,p_request_id,p_action,p_payload,answer);
  RETURN answer;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_fine_storage_access(p_path text, p_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE parts text[]; f public.driver_fines%ROWTYPE; mode text;
BEGIN
  IF p_path !~ '^[a-f0-9-]{36}/[a-f0-9-]{36}/[a-f0-9-]{36}/[a-f0-9-]{36}\.(png|jpg|pdf)$' THEN RETURN false; END IF;
  parts:=string_to_array(p_path,'/');
  SELECT * INTO f FROM public.driver_fines WHERE id::text=parts[3] AND organisation_id::text=parts[1] AND driver_id::text=parts[2];
  IF NOT FOUND THEN RETURN false; END IF;
  mode:=private.driver_workspace_access(f.driver_id);
  RETURN mode<>'none' AND (NOT p_write OR (mode IN ('driver','supervisor','manager') AND f.status='open'));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_fine_sync_review_stage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.response_status='submitted' AND OLD.response_status IS DISTINCT FROM NEW.response_status THEN NEW.review_stage:='supervisor';
  ELSIF NEW.response_status='returned' AND OLD.response_status IS DISTINCT FROM NEW.response_status THEN NEW.review_stage:='driver';
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_import_matches_batch(p_user_id uuid, p_batch_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce((SELECT raw_app_meta_data->>'driver_import_batch'=p_batch_id
    FROM auth.users WHERE id=p_user_id),false);
$function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_record_summary(p_type text, p_id uuid, p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;
BEGIN
  IF p_type NOT IN ('driver_documents','driver_training','driver_coaching','driver_safety_events','driver_expenses','tyre_records','accidents','wo_tasks','checklist_submissions','odometer_logs','wash_records') THEN RAISE EXCEPTION 'Unsupported record type' USING ERRCODE='22023'; END IF;
  EXECUTE format('SELECT to_jsonb(r) FROM public.%I r WHERE id=$1 AND organisation_id=$2',p_type) INTO r USING p_id,p_org;
  IF r IS NULL THEN RETURN NULL; END IF;
  RETURN (SELECT coalesce(jsonb_object_agg(key,value),'{}') FROM jsonb_each(r)
    WHERE key IN ('id','country','site','asset_no','driver_name','title','doc_type','doc_number','expiry_date','course_name','result','completed_date','coaching_status','period','event_type','severity','event_at','category','amount','currency','expense_date','status','incident_date','accident_type','due_date','created_at','reading_date','odometer_km','wash_date','template_name','approval_status','brand','serial_no','issue_date','qty','cost_per_tyre'));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_workspace_access(p_driver_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.drivers%ROWTYPE;
BEGIN
  SELECT * INTO d FROM public.drivers WHERE id=p_driver_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false)
     OR d.organisation_id IS DISTINCT FROM public.app_current_org() THEN RETURN 'none'; END IF;
  IF (public.is_super_admin() OR public.app_sees_all_countries()
      OR lower(btrim(d.country))=ANY(public.app_country_scope()))
     AND EXISTS(SELECT 1 FROM public.driver_account_links l WHERE l.driver_id=d.id
       AND l.user_id=auth.uid() AND l.organisation_id=d.organisation_id) THEN RETURN 'driver';
  END IF;
  IF NOT private.driver_workspace_scope(d.organisation_id,d.country,d.site) THEN RETURN 'none'; END IF;
  IF public.app_user_can('fleet_master','edit') THEN RETURN 'manager'; END IF;
  IF EXISTS(SELECT 1 FROM public.driver_team_assignments a WHERE a.driver_id=d.id AND a.organisation_id=d.organisation_id
    AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) AND auth.uid() IN (a.supervisor_id,a.manager_id)) THEN RETURN 'supervisor'; END IF;
  IF private.driver_workspace_is_finance_reviewer() THEN RETURN 'finance'; END IF;
  IF public.app_user_can('driver_workspace','view') THEN RETURN 'viewer'; END IF;
  RETURN 'none';
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_workspace_command(p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); org uuid:=public.app_current_org();
  d public.drivers%ROWTYPE; f public.driver_fines%ROWTYPE; v public.vehicle_fleet%ROWTYPE;
  previous private.driver_workspace_requests%ROWTYPE; answer jsonb; detail jsonb:=p_payload;
  access_mode text; target_user uuid; target_id uuid; record_data jsonb; choice text;
BEGIN
  IF actor IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
  IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>600000 THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,0));
  SELECT * INTO previous FROM private.driver_workspace_requests WHERE actor_id=actor AND request_id=p_request_id;
  IF FOUND THEN
    IF previous.action<>p_action OR previous.payload<>p_payload THEN RAISE EXCEPTION 'Request already used' USING ERRCODE='22023'; END IF;
    IF private.driver_workspace_access((previous.result->>'driver_id')::uuid)='none' THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
    RETURN previous.result;
  END IF;
  IF p_action='create_driver' THEN
    IF NOT coalesce(public.app_user_can('fleet_master','edit'),false) OR NOT private.driver_workspace_scope(org,p_payload->>'country',p_payload->>'site') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
    IF length(btrim(coalesce(p_payload->>'driver_id',''))) NOT BETWEEN 1 AND 80 OR length(btrim(coalesce(p_payload->>'driver_name',''))) NOT BETWEEN 2 AND 160 THEN RAISE EXCEPTION 'Driver name and employee ID required' USING ERRCODE='22023'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(org::text||lower(btrim(p_payload->>'driver_id')),0));
    IF EXISTS(SELECT 1 FROM public.drivers WHERE organisation_id=org AND lower(btrim(driver_id))=lower(btrim(p_payload->>'driver_id'))) THEN RAISE EXCEPTION 'Employee ID already exists' USING ERRCODE='22023'; END IF;
    INSERT INTO public.drivers(driver_id,driver_name,country,site,organisation_id,created_by)
      VALUES(btrim(p_payload->>'driver_id'),btrim(p_payload->>'driver_name'),p_payload->>'country',p_payload->>'site',org,actor) RETURNING * INTO d;
  ELSE
    SELECT * INTO d FROM public.drivers WHERE id=(p_payload->>'driver_id')::uuid FOR UPDATE;
    access_mode:=private.driver_workspace_access(d.id);
    IF NOT FOUND OR access_mode='none' THEN RAISE EXCEPTION 'Driver unavailable' USING ERRCODE='42501'; END IF;
    IF p_action IN ('link_account','assign_team','link_record','unlink_record') AND access_mode<>'manager' THEN RAISE EXCEPTION 'Assignment management not permitted' USING ERRCODE='42501'; END IF;
    IF p_action IN ('create_fine','review_fine') AND (access_mode NOT IN ('manager','supervisor') OR EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=actor)) THEN RAISE EXCEPTION 'Independent reviewer required' USING ERRCODE='42501'; END IF;
    CASE p_action
    WHEN 'link_account' THEN
      IF length(btrim(coalesce(p_payload->>'reason',''))) < 3 THEN RAISE EXCEPTION 'Link reason required' USING ERRCODE='22023'; END IF;
      target_user:=(p_payload->>'user_id')::uuid;
      IF target_user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=target_user AND p.org_id=org AND p.approved AND NOT coalesce(p.locked,false)) THEN RAISE EXCEPTION 'Approved account in this organisation required' USING ERRCODE='22023'; END IF;
      detail:=p_payload||jsonb_build_object('previous_user_id',(SELECT user_id FROM public.driver_account_links WHERE driver_id=d.id));
      DELETE FROM public.driver_account_links WHERE driver_id=d.id;
      IF target_user IS NOT NULL THEN INSERT INTO public.driver_account_links VALUES(d.id,target_user,org,actor,now()); END IF;
    WHEN 'assign_team' THEN
      IF length(btrim(coalesce(p_payload->>'reason',''))) < 3 THEN RAISE EXCEPTION 'Assignment reason required' USING ERRCODE='22023'; END IF;
      FOREACH target_user IN ARRAY ARRAY[(p_payload->>'supervisor_id')::uuid,(p_payload->>'manager_id')::uuid] LOOP
        IF target_user IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=target_user AND p.org_id=org AND p.approved AND NOT coalesce(p.locked,false)) OR EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=target_user)) THEN RAISE EXCEPTION 'Independent active team member required' USING ERRCODE='22023'; END IF;
      END LOOP;
      IF p_payload->>'vehicle_id' IS NOT NULL THEN
        SELECT * INTO v FROM public.vehicle_fleet WHERE id=(p_payload->>'vehicle_id')::uuid;
        IF NOT FOUND OR NOT private.driver_workspace_scope(v.organisation_id,v.country,v.site) OR v.country IS DISTINCT FROM d.country THEN RAISE EXCEPTION 'Vehicle outside scope' USING ERRCODE='42501'; END IF;
      END IF;
      UPDATE public.driver_team_assignments SET ends_at=now() WHERE driver_id=d.id AND ends_at IS NULL;
      INSERT INTO public.driver_team_assignments(driver_id,organisation_id,supervisor_id,manager_id,vehicle_id,reason,assigned_by)
        VALUES(d.id,org,(p_payload->>'supervisor_id')::uuid,(p_payload->>'manager_id')::uuid,(p_payload->>'vehicle_id')::uuid,p_payload->>'reason',actor) RETURNING id INTO target_id;
    WHEN 'create_fine' THEN
      SELECT * INTO v FROM public.vehicle_fleet WHERE id=(p_payload->>'vehicle_id')::uuid;
      IF NOT FOUND OR NOT private.driver_workspace_scope(v.organisation_id,v.country,v.site) OR v.country IS DISTINCT FROM d.country THEN RAISE EXCEPTION 'Vehicle outside scope' USING ERRCODE='42501'; END IF;
      IF (p_payload->>'incident_at')::timestamptz>now() THEN RAISE EXCEPTION 'Incident cannot be in the future' USING ERRCODE='22023'; END IF;
      INSERT INTO public.driver_fines(organisation_id,driver_id,vehicle_id,country,site,authority,notice_reference,incident_at,due_date,amount,currency,description,assignment_reason,created_by)
        VALUES(org,d.id,v.id,d.country,d.site,btrim(p_payload->>'authority'),btrim(p_payload->>'notice_reference'),(p_payload->>'incident_at')::timestamptz,(p_payload->>'due_date')::date,(p_payload->>'amount')::numeric,upper(p_payload->>'currency'),p_payload->>'description',p_payload->>'assignment_reason',actor) RETURNING * INTO f;
      target_id:=f.id;
    WHEN 'respond_fine' THEN
      IF NOT EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=actor) THEN RAISE EXCEPTION 'Only the linked driver may sign' USING ERRCODE='42501'; END IF;
      SELECT * INTO f FROM public.driver_fines WHERE id=(p_payload->>'fine_id')::uuid AND driver_id=d.id FOR UPDATE;
      IF NOT FOUND OR f.status<>'open' OR f.response_status NOT IN ('awaiting_response','returned') OR f.version IS DISTINCT FROM (p_payload->>'version')::integer THEN RAISE EXCEPTION 'Notice changed; refresh and review again' USING ERRCODE='PT409'; END IF;
      IF (p_payload->>'acknowledged')::boolean IS DISTINCT FROM true OR p_payload->>'statement_version' IS DISTINCT FROM 'receipt-v1' THEN RAISE EXCEPTION 'Review and acknowledge the statement' USING ERRCODE='22023'; END IF;
      choice:=p_payload->>'resolution';
      IF choice='already_paid' AND length(btrim(coalesce(p_payload->>'payment_reference',''))) < 3 THEN RAISE EXCEPTION 'Payment reference required' USING ERRCODE='22023'; END IF;
      IF choice='direct_payment' AND ((p_payload->>'proposed_date')::date IS NULL OR (p_payload->>'proposed_date')::date<current_date) THEN RAISE EXCEPTION 'Proposed payment date required' USING ERRCODE='22023'; END IF;
      -- PNG or this application's path-only SVG format; never active SVG content.
      IF NOT (coalesce(p_payload->>'signature','') ~ '^data:image/png;base64,[A-Za-z0-9+/=]+$' OR
        coalesce(p_payload->>'signature','') ~ '^<svg xmlns="http://www.w3.org/2000/svg" width="[0-9]+" height="[0-9]+" viewBox="[0-9 .]+">(<path d="[ML0-9 .-]+" fill="none" stroke="#[a-fA-F0-9]{6}" stroke-width="[0-9.]+" stroke-linecap="round" stroke-linejoin="round"/>)+</svg>$') THEN RAISE EXCEPTION 'Valid signature required' USING ERRCODE='22023'; END IF;
      INSERT INTO public.driver_fine_responses(fine_id,driver_id,organisation_id,notice_version,signer_id,statement_language,resolution,explanation,payment_reference,proposed_date,signature,notice_snapshot)
        VALUES(f.id,d.id,org,f.version,actor,coalesce(p_payload->>'statement_language','en'),choice,p_payload->>'explanation',p_payload->>'payment_reference',(p_payload->>'proposed_date')::date,p_payload->>'signature',to_jsonb(f)||jsonb_build_object('evidence',(SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') FROM public.driver_fine_evidence e WHERE e.fine_id=f.id))) RETURNING id INTO target_id;
      UPDATE public.driver_fines SET response_status='submitted',version=version+1,updated_at=now() WHERE id=f.id;
      detail:=p_payload-'signature'||jsonb_build_object('response_id',target_id);
    WHEN 'review_fine' THEN
      SELECT * INTO f FROM public.driver_fines WHERE id=(p_payload->>'fine_id')::uuid AND driver_id=d.id FOR UPDATE;
      IF NOT FOUND OR f.version IS DISTINCT FROM (p_payload->>'version')::integer THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='PT409'; END IF;
      IF length(btrim(coalesce(p_payload->>'reason',''))) < 3 THEN RAISE EXCEPTION 'Review reason required' USING ERRCODE='22023'; END IF;
      choice:=p_payload->>'decision';
      IF choice='reopen' AND f.status<>'open' THEN
        UPDATE public.driver_fines SET status='open',version=version+1,updated_at=now() WHERE id=f.id;
      ELSIF f.status<>'open' THEN RAISE EXCEPTION 'Case is closed' USING ERRCODE='PT409';
      ELSIF choice='return' AND f.response_status IN ('submitted','approved') THEN
        UPDATE public.driver_fines SET response_status='returned',version=version+1,updated_at=now() WHERE id=f.id;
      ELSIF choice='approve' AND f.response_status='submitted' THEN
        UPDATE public.driver_fines SET response_status='approved',version=version+1,updated_at=now() WHERE id=f.id;
      ELSIF choice='cancel' AND f.paid_amount=0 THEN
        UPDATE public.driver_fines SET status='cancelled',version=version+1,updated_at=now() WHERE id=f.id;
      ELSIF choice='payment' THEN
        IF length(btrim(coalesce(p_payload->>'payment_reference',''))) < 3 OR (p_payload->>'payment_amount')::numeric IS NULL OR (p_payload->>'payment_amount')::numeric<=0 OR (p_payload->>'payment_amount')::numeric>f.amount-f.paid_amount THEN RAISE EXCEPTION 'Valid payment amount and reference required' USING ERRCODE='22023'; END IF;
        UPDATE public.driver_fines SET paid_amount=paid_amount+(p_payload->>'payment_amount')::numeric,
          status=CASE WHEN paid_amount+(p_payload->>'payment_amount')::numeric=amount THEN 'settled' ELSE 'open' END,version=version+1,updated_at=now() WHERE id=f.id;
      ELSE RAISE EXCEPTION 'Invalid transition' USING ERRCODE='22023'; END IF;
      target_id:=f.id;
    WHEN 'attach_evidence' THEN
      SELECT * INTO f FROM public.driver_fines WHERE id=(p_payload->>'fine_id')::uuid AND driver_id=d.id FOR UPDATE;
      IF NOT FOUND OR f.status<>'open' OR access_mode='viewer' THEN RAISE EXCEPTION 'Evidence upload not permitted' USING ERRCODE='42501'; END IF;
      IF p_payload->>'kind'='notice' AND (access_mode NOT IN ('manager','supervisor') OR f.response_status NOT IN ('awaiting_response','returned')) THEN RAISE EXCEPTION 'Signed notice cannot be changed' USING ERRCODE='PT409'; END IF;
      IF p_payload->>'object_path' NOT LIKE org::text||'/'||d.id::text||'/'||f.id::text||'/%'
        OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='driver-fine-evidence' AND o.name=p_payload->>'object_path' AND o.owner_id=actor::text) THEN RAISE EXCEPTION 'Uploaded file unavailable' USING ERRCODE='42501'; END IF;
      INSERT INTO public.driver_fine_evidence(fine_id,driver_id,organisation_id,object_path,file_name,kind,uploaded_by)
        VALUES(f.id,d.id,org,p_payload->>'object_path',p_payload->>'file_name',p_payload->>'kind',actor) RETURNING id INTO target_id;
      IF p_payload->>'kind'='notice' THEN UPDATE public.driver_fines SET version=version+1,updated_at=now() WHERE id=f.id; END IF;
    WHEN 'link_record' THEN
      record_data:=private.driver_record_summary(p_payload->>'source_type',(p_payload->>'source_id')::uuid,org);
      IF record_data IS NULL OR (record_data->>'country' IS NOT NULL AND record_data->>'country' IS DISTINCT FROM d.country)
        OR (nullif(record_data->>'site','') IS NOT NULL AND record_data->>'site' IS DISTINCT FROM d.site) THEN RAISE EXCEPTION 'Record unavailable in driver scope' USING ERRCODE='42501'; END IF;
      INSERT INTO public.driver_record_links(driver_id,organisation_id,source_type,source_id,reason,linked_by)
        VALUES(d.id,org,p_payload->>'source_type',(p_payload->>'source_id')::uuid,p_payload->>'reason',actor) RETURNING id INTO target_id;
    WHEN 'unlink_record' THEN
      IF length(btrim(coalesce(p_payload->>'reason',''))) < 3 THEN RAISE EXCEPTION 'Reason required' USING ERRCODE='22023'; END IF;
      DELETE FROM public.driver_record_links WHERE id=(p_payload->>'link_id')::uuid AND driver_id=d.id RETURNING to_jsonb(driver_record_links) INTO record_data;
      IF NOT FOUND THEN RAISE EXCEPTION 'Link unavailable' USING ERRCODE='42501'; END IF;
      detail:=p_payload||jsonb_build_object('previous_link',record_data);
    ELSE RAISE EXCEPTION 'Unsupported action' USING ERRCODE='22023';
    END CASE;
  END IF;
  INSERT INTO public.driver_workspace_events(organisation_id,driver_id,fine_id,actor_id,action,details)
    VALUES(org,d.id,f.id,actor,p_action,detail);
  -- Inbox notifications are part of the same transaction as the action.
  INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
    SELECT recipient,'driver_workspace','Driver workspace updated','Open your driver workspace to review the latest action.','driver_workspace',d.id::text
    FROM (SELECT l.user_id recipient FROM public.driver_account_links l WHERE l.driver_id=d.id
      UNION SELECT a.supervisor_id FROM public.driver_team_assignments a WHERE a.driver_id=d.id AND a.ends_at IS NULL
      UNION SELECT a.manager_id FROM public.driver_team_assignments a WHERE a.driver_id=d.id AND a.ends_at IS NULL) q
    WHERE recipient IS NOT NULL AND recipient<>actor;
  answer:=jsonb_build_object('driver_id',d.id,'id',coalesce(target_id,d.id),'action',p_action);
  INSERT INTO private.driver_workspace_requests VALUES(actor,p_request_id,p_action,p_payload,answer);
  RETURN answer;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_workspace_is_finance_reviewer()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(public.app_is_active() AND public.app_current_org() IS NOT NULL AND (
    public.app_user_can('driver_workspace','finance') OR EXISTS(
      SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND lower(btrim(p.role))='finance'
        AND p.approved AND NOT coalesce(p.locked,false)
    )),false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_workspace_read(p_driver_id uuid, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; access_mode text; d public.drivers%ROWTYPE; page_size integer:=100;
  -- per-call invariants of the access decision, evaluated once for the list
  v_uid uuid; v_super boolean; v_allc boolean; v_cs text[]; v_alls boolean; v_ss text[];
  v_mgr boolean; v_fin boolean; v_view boolean;
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR public.app_current_org() IS NULL THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
  IF p_offset IS NULL OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='22023'; END IF;
  IF p_driver_id IS NULL THEN
    -- The list used to call private.driver_workspace_access() twice per driver,
    -- and each call re-ran about ten profile lookups, so the list cost ~3 ms
    -- per driver in the organisation even when it returned nothing. The same
    -- decision is evaluated here with the per-user parts computed once; the
    -- per-driver parts (country, site, own link, active assignment) stay per row.
    v_uid := auth.uid(); v_super := public.is_super_admin(); v_allc := public.app_sees_all_countries();
    v_cs := public.app_country_scope(); v_alls := public.app_sees_all_sites(); v_ss := public.app_site_scope();
    v_mgr := public.app_user_can('fleet_master','edit'); v_fin := private.driver_workspace_is_finance_reviewer();
    v_view := public.app_user_can('driver_workspace','view');
    SELECT jsonb_build_object('can_manage',coalesce(public.app_user_can('fleet_master','edit'),false),
      'can_finance',private.driver_workspace_is_finance_reviewer(),
      'drivers',coalesce(jsonb_agg(x ORDER BY x->>'driver_name',x->>'id'),'[]')) INTO result FROM (
      SELECT jsonb_build_object('id',drv.id,'driver_id',drv.driver_id,'driver_name',drv.driver_name,'position',nullif(btrim(drv.custom_data->>'position'),''),'country',drv.country,'site',drv.site,'status',drv.status,
        'access',acc.mode,'user_id',l.user_id,
        'open_fines',(SELECT count(*) FROM public.driver_fines f WHERE f.driver_id=drv.id AND f.status='open'),
        'awaiting_response',(SELECT count(*) FROM public.driver_fines f WHERE f.driver_id=drv.id AND f.status='open' AND f.review_stage='driver'),
        'pending_supervisor',(SELECT count(*) FROM public.driver_fines f WHERE f.driver_id=drv.id AND f.status='open' AND f.review_stage='supervisor'),
        'pending_finance',(SELECT count(*) FROM public.driver_fines f WHERE f.driver_id=drv.id AND f.status='open' AND f.review_stage='finance'),
        'overdue_fines',(SELECT count(*) FROM public.driver_fines f WHERE f.driver_id=drv.id AND f.status='open' AND f.due_date<current_date)) x
      FROM public.drivers drv LEFT JOIN public.driver_account_links l ON l.driver_id=drv.id
      CROSS JOIN LATERAL (SELECT CASE
        WHEN coalesce(v_super OR v_allc OR lower(btrim(drv.country))=ANY(v_cs),false)
          AND EXISTS(SELECT 1 FROM public.driver_account_links dl WHERE dl.driver_id=drv.id
            AND dl.user_id=v_uid AND dl.organisation_id=drv.organisation_id) THEN 'driver'
        WHEN NOT coalesce((v_super OR v_allc OR lower(btrim(drv.country))=ANY(v_cs))
          AND (v_super OR v_alls OR upper(btrim(drv.site))=ANY(v_ss)),false) THEN 'none'
        WHEN coalesce(v_mgr,false) THEN 'manager'
        WHEN EXISTS(SELECT 1 FROM public.driver_team_assignments a WHERE a.driver_id=drv.id AND a.organisation_id=drv.organisation_id
          AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) AND v_uid IN (a.supervisor_id,a.manager_id)) THEN 'supervisor'
        WHEN coalesce(v_fin,false) THEN 'finance'
        WHEN coalesce(v_view,false) THEN 'viewer'
        ELSE 'none' END AS mode) acc
      WHERE drv.organisation_id=public.app_current_org() AND acc.mode<>'none'
      ORDER BY drv.driver_name,drv.id LIMIT page_size+1 OFFSET p_offset
    ) q;
    RETURN result;
  END IF;
  access_mode:=private.driver_workspace_access(p_driver_id);
  IF access_mode='none' THEN RAISE EXCEPTION 'Driver unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO d FROM public.drivers WHERE id=p_driver_id;
  RETURN jsonb_build_object('access',access_mode,'driver',jsonb_build_object('id',d.id,'driver_id',d.driver_id,'driver_name',d.driver_name,'position',nullif(btrim(d.custom_data->>'position'),''),'country',d.country,'site',d.site,'status',d.status),
    'can_respond',EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=auth.uid()),
    'can_review',access_mode IN ('manager','supervisor','finance') AND NOT EXISTS(SELECT 1 FROM public.driver_account_links WHERE driver_id=d.id AND user_id=auth.uid()),
    'can_finance',private.driver_workspace_is_finance_reviewer(),
    'can_manage',coalesce(public.app_user_can('fleet_master','edit'),false),
    'assignments',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'starts_at' DESC),'[]') FROM (
      SELECT to_jsonb(a)||jsonb_build_object('supervisor_name',s.full_name,'manager_name',m.full_name,'asset_no',v.asset_no) x
      FROM public.driver_team_assignments a LEFT JOIN public.profiles s ON s.id=a.supervisor_id LEFT JOIN public.profiles m ON m.id=a.manager_id LEFT JOIN public.vehicle_fleet v ON v.id=a.vehicle_id
      WHERE a.driver_id=d.id ORDER BY a.starts_at DESC,a.id LIMIT page_size+1 OFFSET p_offset) q),
    'fines',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'created_at' DESC,x->>'id'),'[]') FROM (
      SELECT to_jsonb(f)||jsonb_build_object('asset_no',v.asset_no,
        'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at),'[]') FROM public.driver_fine_evidence e WHERE e.fine_id=f.id),
        'responses',(SELECT coalesce(jsonb_agg(to_jsonb(r)-'signature' ORDER BY r.signed_at),'[]') FROM public.driver_fine_responses r WHERE r.fine_id=f.id),
        'reviews',(SELECT coalesce(jsonb_agg(to_jsonb(rv)||jsonb_build_object('reviewer_name',p.full_name) ORDER BY rv.created_at,rv.id),'[]') FROM public.driver_fine_reviews rv LEFT JOIN public.profiles p ON p.id=rv.reviewer_id WHERE rv.fine_id=f.id),
        'reminders',(SELECT coalesce(jsonb_agg(to_jsonb(rm) ORDER BY rm.created_at,rm.id),'[]') FROM public.driver_fine_reminders rm WHERE rm.fine_id=f.id)) x
      FROM public.driver_fines f LEFT JOIN public.vehicle_fleet v ON v.id=f.vehicle_id WHERE f.driver_id=d.id ORDER BY f.created_at DESC,f.id LIMIT page_size+1 OFFSET p_offset) q),
    'records',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'linked_at' DESC,x->>'id'),'[]') FROM (
      SELECT to_jsonb(l)||jsonb_build_object('record',private.driver_record_summary(l.source_type,l.source_id,l.organisation_id)) x FROM public.driver_record_links l WHERE l.driver_id=d.id ORDER BY l.linked_at DESC,l.id LIMIT page_size+1 OFFSET p_offset) q),
    'work',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM (
      SELECT jsonb_build_object('id',t.id,'title',t.title,'status',t.status,'source_type','wo_tasks','job_id',t.job_id) x
      FROM public.wo_tasks t JOIN public.driver_account_links l ON l.user_id=t.assignee_user_id AND l.driver_id=d.id
      WHERE t.organisation_id=d.organisation_id AND private.driver_workspace_scope(t.organisation_id,t.country,t.site)
      ORDER BY t.id LIMIT page_size+1 OFFSET p_offset) q),
    'events',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'created_at' DESC,x->>'id'),'[]') FROM (
      SELECT to_jsonb(e)||jsonb_build_object('actor_name',p.full_name) x FROM public.driver_workspace_events e LEFT JOIN public.profiles p ON p.id=e.actor_id WHERE e.driver_id=d.id ORDER BY e.created_at DESC,e.id LIMIT page_size+1 OFFSET p_offset) q),
    'balances',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT currency,sum(amount-paid_amount) outstanding FROM public.driver_fines WHERE driver_id=d.id AND status='open' GROUP BY currency) x));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.driver_workspace_scope(p_org uuid, p_country text, p_site text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(auth.uid() IS NOT NULL AND public.app_is_active()
    AND p_org=public.app_current_org()
    AND (public.is_super_admin() OR public.app_sees_all_countries() OR lower(btrim(p_country))=ANY(public.app_country_scope()))
    AND (public.is_super_admin() OR public.app_sees_all_sites() OR upper(btrim(p_site))=ANY(public.app_site_scope())),false);
$function$;
-- @@
CREATE OR REPLACE FUNCTION private.refresh_web_meter_vehicle(p_vehicle_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.vehicle_fleet%ROWTYPE; last_hours numeric;
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false)
    OR NOT coalesce(public.app_user_can('odometer_logs','view'),false) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM public.vehicle_fleet
    WHERE id=p_vehicle_id AND organisation_id=public.app_current_org()
      AND (country IS NULL OR public.is_super_admin() OR public.app_sees_all_countries()
        OR lower(btrim(country))=ANY(coalesce(public.app_country_scope(),'{}'::text[])))
      AND (site IS NULL OR btrim(site)='' OR public.app_sees_all_sites()
        OR upper(btrim(site))=ANY(coalesce(public.app_site_scope(),'{}'::text[])))
    FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle unavailable' USING ERRCODE='42501'; END IF;
  SELECT engine_hours INTO last_hours FROM public.engine_hours_logs
    WHERE organisation_id=v.organisation_id AND asset_no=v.asset_no
      AND country IS NOT DISTINCT FROM v.country
    ORDER BY reading_date DESC NULLS LAST,created_at DESC,id DESC LIMIT 1;
  last_hours := greatest(last_hours,v.current_engine_hours,v.current_hours);
  IF last_hours IS DISTINCT FROM v.current_engine_hours THEN
    UPDATE public.vehicle_fleet SET current_engine_hours=last_hours,updated_at=now() WHERE id=v.id;
  END IF;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION private.release_work_order_stock_internal(p_work_order_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_actor uuid := auth.uid();
  v_reservation public.work_order_stock_reservations;
  v_line record;
begin
  if v_actor is null or v_org is null then
    raise exception 'Authentication and organisation membership are required' using errcode = '42501';
  end if;
  select * into v_reservation from public.work_order_stock_reservations
   where organisation_id = v_org and work_order_id = p_work_order_id and status = 'reserved'
   for update;
  if not found then
    return jsonb_build_object('work_order_id', p_work_order_id, 'status', 'not_reserved', 'released', false);
  end if;

  for v_line in
    select stock_id, quantity from public.work_order_stock_reservation_lines
    where reservation_id = v_reservation.id order by stock_id
  loop
    perform 1 from public.stock where id = v_line.stock_id and organisation_id = v_org for update;
    if not found then
      raise exception 'Reserved stock item % is no longer available to this tenant', v_line.stock_id
        using errcode = 'P0002';
    end if;
    update public.stock set quantity = coalesce(quantity, 0) + v_line.quantity,
      updated_at = now() where id = v_line.stock_id and organisation_id = v_org;
  end loop;
  update public.work_order_stock_reservations
  set status = 'released', released_by = v_actor, released_at = now(),
      release_reason = nullif(left(btrim(p_reason), 500), '')
  where id = v_reservation.id;
  return jsonb_build_object('reservation_id', v_reservation.id,
    'work_order_id', p_work_order_id, 'status', 'released', 'released', true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION private.reserve_work_order_stock_internal(p_work_order_id uuid, p_lines jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_actor uuid := auth.uid();
  v_reservation public.work_order_stock_reservations;
  v_line record;
  v_stock public.stock;
begin
  if v_actor is null or v_org is null then
    raise exception 'Authentication and organisation membership are required' using errcode = '42501';
  end if;
  if p_work_order_id is null or nullif(btrim(p_idempotency_key), '') is null
     or length(p_idempotency_key) > 160 then
    raise exception 'A work order and valid idempotency key are required' using errcode = '22023';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'At least one stock item is required' using errcode = '22023';
  end if;

  -- Confirm the parent belongs to this tenant before touching inventory.
  perform 1 from public.work_orders
   where id = p_work_order_id and organisation_id = v_org for update;
  if not found then
    raise exception 'Work order not found or inaccessible' using errcode = 'P0002';
  end if;

  select * into v_reservation from public.work_order_stock_reservations
   where organisation_id = v_org and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('reservation_id', v_reservation.id,
      'work_order_id', v_reservation.work_order_id, 'status', v_reservation.status,
      'idempotent', true);
  end if;

  if exists (select 1 from public.work_order_stock_reservations
             where organisation_id = v_org and work_order_id = p_work_order_id and status = 'reserved') then
    raise exception 'This work order already has an active stock reservation' using errcode = '23505';
  end if;

  insert into public.work_order_stock_reservations
    (organisation_id, work_order_id, idempotency_key, reserved_by)
  values (v_org, p_work_order_id, btrim(p_idempotency_key), v_actor)
  returning * into v_reservation;

  -- Aggregate duplicate stock IDs, lock in UUID order to avoid deadlocks, then
  -- deduct and record each line in the same transaction.
  for v_line in
    select (x->>'stock_id')::uuid as stock_id, sum((x->>'qty')::numeric) as qty
    from jsonb_array_elements(p_lines) x
    group by (x->>'stock_id')::uuid
    order by (x->>'stock_id')::uuid
  loop
    if v_line.qty is null or v_line.qty <> trunc(v_line.qty) or v_line.qty <= 0 or v_line.qty > 100000 then
      raise exception 'Reservation quantity must be a whole number between 1 and 100000'
        using errcode = '22023';
    end if;
    select * into v_stock from public.stock
     where id = v_line.stock_id and organisation_id = v_org for update;
    if not found then
      raise exception 'Stock item % not found or inaccessible', v_line.stock_id using errcode = 'P0002';
    end if;
    if coalesce(v_stock.quantity, 0) < v_line.qty then
      raise exception 'Insufficient stock for item % (available %, requested %)',
        v_line.stock_id, coalesce(v_stock.quantity, 0), v_line.qty using errcode = '23514';
    end if;
    update public.stock set quantity = coalesce(quantity, 0) - v_line.qty::integer,
      updated_at = now() where id = v_line.stock_id and organisation_id = v_org;
    insert into public.work_order_stock_reservation_lines(reservation_id, stock_id, quantity)
      values (v_reservation.id, v_line.stock_id, v_line.qty::integer);
  end loop;

  return jsonb_build_object('reservation_id', v_reservation.id,
    'work_order_id', p_work_order_id, 'status', 'reserved', 'idempotent', false,
    'line_count', (select count(*) from public.work_order_stock_reservation_lines
                   where reservation_id = v_reservation.id));
exception when unique_violation then
  select * into v_reservation from public.work_order_stock_reservations
   where organisation_id = v_org and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('reservation_id', v_reservation.id,
      'work_order_id', v_reservation.work_order_id, 'status', v_reservation.status,
      'idempotent', true);
  end if;
  raise;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_arr_add(p_arr text[], p_elem text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p_elem = any(coalesce(p_arr,'{}')) then p_arr else array_append(p_arr, p_elem) end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_case_status_for(p_ws_key text, p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_ws_key
    when 'fleet_validation' then 'under_fleet_validation'
    when 'liability'        then 'liability_assessment'
    when 'insurance' then case p_status
      when 'in_progress'      then 'insurance_review'
      when 'waiting_approval' then 'claim_registration_pending'
      when 'waiting_external' then 'awaiting_insurer_response'
      else 'insurance_review' end
    when 'assessment' then 'technical_assessment'
    when 'repair' then case p_status
      when 'in_progress'      then 'repair_in_progress'
      when 'waiting_approval' then 'awaiting_fleet_approval'
      when 'waiting_external' then 'awaiting_external_workshop'
      when 'waiting_info'     then 'awaiting_parts'
      else 'repair_decision_pending' end
    when 'workshop_qc' then 'workshop_quality_inspection'
    when 'handover'    then 'fleet_inspection'
    when 'finance'     then 'financial_closure_pending'
    when 'corrective'  then 'corrective_actions_pending'
    else null end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_closure_review_approved(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public._acc_truthy(p_case -> 'closure_review_approved')
      or public._acc_str(p_case -> 'closure_approved_by') <> '';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_closure_satisfied(p_case jsonb, p_rows jsonb, p_ws_key text, p_profile jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_status text := public.accident_workstream_status(p_ws_key, p_case, p_rows);
        v_req_appr boolean;
begin
  if v_status = 'completed' then return true; end if;
  if v_status in ('not_required','cancelled') then
    if p_ws_key in ('incident_evidence','liability','finance') then return false; end if;
    v_req_appr := case when p_profile is null then true
                       else public._acc_truthy(p_profile -> 'na_requires_approval') end;
    return public._acc_marked_na(p_case, p_rows, p_ws_key, v_req_appr);
  end if;
  return false;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_field_filled(p_case jsonb, p_key text, p_money boolean DEFAULT false, p_kind text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_money then (public._acc_num(p_case -> p_key) is not null
                       and public._acc_num(p_case -> p_key) <> 0)
    when p_kind = 'bool' then jsonb_typeof(p_case -> p_key) = 'boolean'
    when jsonb_typeof(p_case -> p_key) = 'array'  then jsonb_array_length(p_case -> p_key) > 0
    when jsonb_typeof(p_case -> p_key) = 'object' then
         (select count(*) from jsonb_object_keys(p_case -> p_key)) > 0
    else public._acc_str(p_case -> p_key) <> ''
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_first_ws_row(p_rows jsonb, p_ws_key text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select value
  from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) with ordinality as t(value, ord)
  where value ->> 'workstream' = p_ws_key or value ->> 'key' = p_ws_key
  order by ord
  limit 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_is_closed_case(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select lower(case when public._acc_str(p_case -> 'case_status') <> ''
                    then public._acc_str(p_case -> 'case_status')
                    else public._acc_str(p_case -> 'status') end) = 'closed';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_marked_na(p_case jsonb, p_rows jsonb, p_ws_key text, p_require_approval boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public.accident_na_envelope_valid(
           public._acc_na_envelope_for(p_case, p_ws_key, p_rows), p_require_approval);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_na_envelope_for(p_case jsonb, p_ws_key text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_row jsonb; v_nr jsonb; v_na jsonb; v_stage text;
begin
  v_row := public._acc_first_ws_row(p_rows, p_ws_key);
  if v_row is not null then
    v_nr := v_row -> 'na_reason';
    v_na := v_row -> 'na';
    if public._acc_truthy_json(v_nr) or public._acc_truthy_json(v_na) then
      return case when public._acc_truthy_json(v_nr) then v_nr else v_na end;
    end if;
  end if;
  v_stage := public.accident_workstream_stage(p_ws_key);
  if v_stage is null then return null; end if;
  return p_case #> array['stage_waivers', v_stage];
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_num(v jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when v is null then null
    when jsonb_typeof(v) = 'null'    then null
    when jsonb_typeof(v) = 'number'  then (v #>> '{}')::numeric
    when jsonb_typeof(v) = 'boolean' then case when v = 'true'::jsonb then 1 else 0 end
    when jsonb_typeof(v) = 'string'  then
      case when btrim(v #>> '{}') = '' then null
           when btrim(v #>> '{}') ~ '^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$'
                then btrim(v #>> '{}')::numeric
           else null end
    else null end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_present(v jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select v is not null and jsonb_typeof(v) <> 'null';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_rule_eq(p_col jsonb, p_val jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p_col is null or jsonb_typeof(p_col) = 'null' then return true; end if;
  if jsonb_typeof(p_col) = 'string' and public._acc_str(p_col) = '' then return true; end if;
  if jsonb_typeof(p_col) = 'array'  and jsonb_array_length(p_col) = 0 then return true; end if;
  if jsonb_typeof(p_col) = 'array' then
    return public._acc_str(p_val) in (select public._acc_str(e) from jsonb_array_elements(p_col) e);
  end if;
  return public._acc_str(p_col) = public._acc_str(p_val);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_scored(p_case jsonb, p_rows jsonb, p_ws_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_status text := public.accident_workstream_status(p_ws_key, p_case, p_rows);
begin
  if v_status = 'completed' then return true; end if;
  if v_status in ('not_required','cancelled') then
    return public._acc_marked_na(p_case, p_rows, p_ws_key, false);
  end if;
  return false;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_stage_completion(p_case jsonb, p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_total int := 0; v_filled int := 0; r record;
begin
  for r in select field_key, is_money from public._acc_stage_required(p_stage) loop
    v_total := v_total + 1;
    if public._acc_field_filled(p_case, r.field_key, r.is_money, null) then
      v_filled := v_filled + 1;
    end if;
  end loop;
  return jsonb_build_object('total', v_total, 'filled', v_filled,
                            'complete', (v_total > 0 and v_filled = v_total));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_stage_required(p_stage text)
 RETURNS TABLE(field_key text, is_money boolean)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select f.field_key, f.is_money from (values
    ('reported','incident_date',false),
    ('reported','asset_no',false),
    ('reported','site',false),
    ('reported','description',false),
    ('initial_review','responsible_owner_id',false),
    ('initial_review','target_date',false),
    ('hse_investigation','root_cause',false),
    ('hse_investigation','corrective_action',false),
    ('workshop_assessment','estimated_damage_cost',true),
    ('workshop_assessment','repair_type',false),
    ('insurance_claim','insurer',false),
    ('insurance_claim','claim_amount',true),
    ('repair_approval','approved_repair_amount',true),
    ('repair_approval','estimate_approved_by',false),
    ('repair_in_progress','repair_cost',true),
    ('final_inspection','closure_evidence',false),
    ('vehicle_release','release_date',false),
    ('cost_recovery','recovered_amount',true),
    ('cost_recovery','recovery_status',false),
    ('closed','closure_evidence',false)
  ) f(stage, field_key, is_money)
  where f.stage = p_stage;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_str(v jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when v is null then ''
    when jsonb_typeof(v) = 'null' then ''
    else coalesce(btrim(v #>> '{}'), '') end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_to_ts(v jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare t text := public._acc_str(v);
begin
  if t = '' then return null; end if;
  return t::timestamptz;
exception when others then
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._acc_transition_targets(p_from text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case coalesce(btrim(p_from),'')
    when 'draft'                       then array['submitted','draft']
    when 'submitted'                   then array['evidence_incomplete','under_fleet_validation']
    when 'evidence_incomplete'         then array['submitted']
    when 'under_fleet_validation'      then array['evidence_incomplete','liability_assessment']
    when 'liability_assessment'        then array['insurance_review','technical_assessment']
    when 'insurance_review'            then array['claim_registration_pending','technical_assessment']
    when 'claim_registration_pending'  then array['awaiting_insurer_response']
    when 'awaiting_insurer_response'   then array['technical_assessment','awaiting_insurer_response']
    when 'technical_assessment'        then array['repair_decision_pending','total_loss_processing']
    when 'total_loss_processing'       then array['insurance_settlement_pending','financial_closure_pending']
    when 'repair_decision_pending'     then array['repair_planning','operationally_completed']
    when 'repair_planning'             then array['awaiting_fleet_approval']
    when 'awaiting_fleet_approval'     then array['awaiting_parts','awaiting_quotation','repair_in_progress']
    when 'awaiting_quotation'          then array['awaiting_po']
    when 'awaiting_po'                 then array['awaiting_external_workshop']
    when 'awaiting_parts'              then array['repair_in_progress']
    when 'awaiting_external_workshop'  then array['repair_in_progress']
    when 'repair_in_progress'          then array['workshop_quality_inspection']
    when 'workshop_quality_inspection' then array['fleet_inspection','repair_in_progress']
    when 'fleet_inspection'            then array['operationally_completed','rectification_required']
    when 'rectification_required'      then array['repair_in_progress']
    when 'operationally_completed'     then array['insurance_settlement_pending','financial_closure_pending','closure_review']
    when 'insurance_settlement_pending' then array['financial_closure_pending']
    when 'financial_closure_pending'   then array['corrective_actions_pending','closure_review']
    when 'corrective_actions_pending'  then array['closure_review']
    when 'closure_review'              then array['closed']
    when 'closed'                      then array['reopened']
    when 'reopened'                    then array['technical_assessment']
    when 'legal_hold'                  then array['closure_review']
    else array[]::text[] end;
$function$;
