CREATE OR REPLACE FUNCTION public._access_review_require_super()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.is_super_admin(), false) then
    raise exception 'Only a super admin can run access reviews.' using errcode = '42501';
  end if;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._accident_rpc_context(p_accident_id uuid, OUT org uuid, OUT country text, OUT site text)
 RETURNS record
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cur uuid;
begin
  if p_accident_id is null then
    raise exception 'An incident is required.' using errcode = '22023';
  end if;

  select a.organisation_id, a.country, a.site
    into org, country, site
    from public.accidents a
   where a.id = p_accident_id;

  if org is null then
    raise exception 'Incident % not found.', p_accident_id using errcode = 'P0002';
  end if;

  v_cur := public.app_current_org();
  if not ((org = v_cur) or public.is_super_admin()) then
    raise exception 'Not permitted for this organisation.' using errcode = '42501';
  end if;

  if not (public.app_write_country_ok(country) is not false and public.app_can_see_site(site)) then
    raise exception 'Not permitted for this case country/site scope.' using errcode = '42501';
  end if;
end
$function$;
