CREATE OR REPLACE FUNCTION public._approval_canonical(p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v jsonb := coalesce(p_payload, '{}'::jsonb); v_ids jsonb;
begin
  if p_action = 'admin_data_cleanup_run' then
    if nullif(btrim(v->>'key'), '') is null or nullif(btrim(v->>'before'), '') is null then
      raise exception 'A cleanup approval needs a target and a cutoff date.' using errcode = '22023';
    end if;
    return jsonb_build_object('key', btrim(v->>'key'), 'before', (v->>'before')::date::text);
  elsif p_action = 'backup_restore_missing' then
    if nullif(btrim(v->>'snapshot_id'), '') is null or nullif(btrim(v->>'table'), '') is null then
      raise exception 'A restore approval needs a snapshot and a table.' using errcode = '22023';
    end if;
    return jsonb_build_object('snapshot_id', (v->>'snapshot_id')::uuid::text, 'table', btrim(v->>'table'));
  elsif p_action = 'admin_bulk_set_role' then
    if nullif(btrim(v->>'role'), '') is null or jsonb_typeof(v->'user_ids') is distinct from 'array' then
      raise exception 'A role-change approval needs a role and a list of users.' using errcode = '22023';
    end if;
    select coalesce(jsonb_agg(u order by u), '[]'::jsonb) into v_ids
      from (select distinct lower(e::uuid::text) u from jsonb_array_elements_text(v->'user_ids') e) s;
    if jsonb_array_length(v_ids) = 0 then
      raise exception 'A role-change approval needs at least one user.' using errcode = '22023';
    end if;
    return jsonb_build_object('role', btrim(v->>'role'), 'user_ids', v_ids);
  elsif p_action = 'dual_control_disable' then
    return '{}'::jsonb;
  end if;
  raise exception 'This action cannot be sent for approval.' using errcode = '22023';
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._audit_day_digest(p_source text, p_day date, OUT row_count bigint, OUT digest text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'UTC');
  v_to   timestamptz := ((p_day + 1)::timestamp at time zone 'UTC');
  v_agg  text;
begin
  if p_source = 'audit_log_v2' then
    select count(*), string_agg(encode(extensions.digest(row_to_json(t)::text, 'sha256'), 'hex'), '' order by t.created_at, t.id)
      into row_count, v_agg
      from public.audit_log_v2 t where t.created_at >= v_from and t.created_at < v_to;
  elsif p_source = 'access_audit' then
    select count(*), string_agg(encode(extensions.digest(row_to_json(t)::text, 'sha256'), 'hex'), '' order by t.at, t.id)
      into row_count, v_agg
      from public.access_audit t where t.at >= v_from and t.at < v_to;
  elsif p_source = 'console_sessions' then
    select count(*), string_agg(encode(extensions.digest(row_to_json(t)::text, 'sha256'), 'hex'), '' order by t.created_at, t.id)
      into row_count, v_agg
      from public.console_sessions t where t.created_at >= v_from and t.created_at < v_to;
  else
    raise exception 'Unknown audit source' using errcode = '22023';
  end if;
  digest := encode(extensions.digest(coalesce(v_agg, ''), 'sha256'), 'hex');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._clean_brand_logos(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_allowed text[] := ARRAY[
    'app_icon','login','favicon','report_cover',
    'email_header','mobile_splash','pdf_watermark'
  ];
  v_out jsonb := '{}'::jsonb;
  v_key text;
  v_val text;
BEGIN
  IF p IS NULL OR jsonb_typeof(p) <> 'object' THEN
    RETURN '{}'::jsonb;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p) LOOP
    CONTINUE WHEN NOT (v_key = ANY (v_allowed));
    IF jsonb_typeof(p->v_key) <> 'string' THEN CONTINUE; END IF;

    v_val := btrim(p->>v_key);
    CONTINUE WHEN v_val IS NULL OR v_val = '';
    IF length(v_val) > 512 THEN
      RAISE EXCEPTION 'Logo value for % is too long', v_key;
    END IF;

    IF v_val ~ '^[a-z0-9-]{1,64}$'
       OR v_val ~ '^https?://'
       OR v_val ~ '^/[^ ]*$' THEN
      v_out := v_out || jsonb_build_object(v_key, v_val);
    ELSE
      RAISE EXCEPTION 'Invalid logo value for %: must be an asset id, URL or /path', v_key;
    END IF;
  END LOOP;

  RETURN v_out;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._console_audit(p_action text, p_target uuid DEFAULT NULL::uuid, p_target_type text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ip inet;
begin
  begin
    v_ip := public._request_client_ip();
  exception when others then
    v_ip := null;
  end;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details, ip_address)
  values (auth.uid(), p_action, p_target, p_target_type,
          coalesce(p_details, '{}'::jsonb) || jsonb_build_object('source', 'server'), v_ip);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._console_ip_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_hdr text; v_ip inet;
begin
  begin
    if auth.uid() is null then return true; end if;
    if not coalesce(public.is_super_admin(), false) then return true; end if;
    if not public._ip_allowlist_on() then return true; end if;
    if not exists (select 1 from public.console_ip_allowlist where active) then return true; end if;
    v_hdr := nullif(current_setting('request.headers', true), '');
    if v_hdr is null then return true; end if;
    v_ip := public._request_client_ip();
    if v_ip is null then return false; end if;
    return public._ip_covered(v_ip);
  exception when others then
    return true;  -- fail open: a bug in the check must never lock the owner out
  end;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._consume_approval(p_action text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_canon jsonb; v_id uuid;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if not public._dual_control_on() then
    return null;
  end if;
  v_canon := public._approval_canonical(p_action, p_payload);

  update public.console_approval_requests set status = 'expired'
   where status in ('pending','approved') and expires_at <= now();

  select id into v_id from public.console_approval_requests
   where action = p_action and payload = v_canon and status = 'approved'
     and executed_at is null and expires_at > now()
     and (requested_by = auth.uid() or decided_by = auth.uid())
   order by decided_at
   limit 1
   for update skip locked;

  if v_id is null then
    raise exception 'This action needs a second super admin to approve it first. Request approval in Console, Approvals, then run it again.'
      using errcode = 'P0001', hint = 'dual_control_required';
  end if;

  update public.console_approval_requests
     set status = 'executed', executed_at = now(), executed_by = auth.uid()
   where id = v_id;
  perform public.log_console_event('dual_control_executed', v_id::text, 'console_approval',
                                   jsonb_build_object('action', p_action));
  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cost_cpk(p_org uuid, p_country text, p_site text, p_from date, p_to date, p_min numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_km numeric := 0; v_assets int := 0;
  v_matched numeric := 0; v_total numeric := 0; v_cov numeric;
  v_list text[];
begin
  select coalesce(sum(km_run),0), count(*), coalesce(array_agg(asset_no), '{}')
    into v_km, v_assets, v_list
    from public.fleet_km_by_asset(p_org, p_country, p_from, p_to) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));

  select coalesce(round(sum(line_cost) filter (
           where upper(btrim(asset_code)) = any(v_list)), 0), 0),
         coalesce(round(sum(line_cost)), 0)
    into v_matched, v_total
    from public.parts_consumption
   where organisation_id = p_org
     and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and (p_site is null or site = p_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
     and event_date between p_from and p_to;

  v_cov := case when v_total > 0 then round(v_matched / v_total, 4) end;

  return jsonb_build_object(
    'km', round(v_km),
    'assets_measured', v_assets,
    'spend_matched', v_matched,
    'spend_total', v_total,
    'coverage_pct', v_cov,
    -- null, never zero: an unmeasured fleet has an unknown cost per km
    'cpk', case when v_km > 0 then round(v_matched / v_km, 3) end,
    'comparable', coalesce(v_cov, 0) >= p_min);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cost_dim(p_org uuid, p_country text, p_site text, p_from date, p_to date, p_pf date, p_pt date, p_dim text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare result jsonb; v_sql text;
begin
  -- p_dim is never user input: the caller passes one of this fixed set, and
  -- anything else returns empty rather than reaching format().
  if p_dim not in ('site','cost_center','asset_type','asset_code','item_description','brand','store_code') then
    return '[]'::jsonb;
  end if;
  v_sql := format($f$
    select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
      select coalesce(nullif(btrim(%1$I::text),''),'Unspecified') label,
             coalesce(round(sum(line_cost) filter (where event_date between $4 and $5)),0) spend,
             coalesce(round(sum(line_cost) filter (where event_date between $6 and $7)),0) prev_spend,
             count(*) filter (where event_date between $4 and $5) lines
        from public.parts_consumption
       where organisation_id = $1
         and ($2 is null or country = $2) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and ($3 is null or site = $3) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and (event_date between $4 and $5 or event_date between $6 and $7)
       group by 1
       order by 2 desc, 3 desc, 1
       limit 25) x $f$, p_dim);
  execute v_sql into result using p_org, p_country, p_site, p_from, p_to, p_pf, p_pt;
  return coalesce(result, '[]'::jsonb);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cost_totals(p_org uuid, p_country text, p_site text, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select jsonb_build_object(
    'tyre',  coalesce(round(sum(tyre_cost)),0),
    'spare', coalesce(round(sum(spare_cost)),0),
    'oil',   coalesce(round(sum(oil_cost)),0),
    'total', coalesce(round(sum(line_cost)),0),
    'lines', count(*),
    'assets', count(distinct upper(btrim(asset_code))))
    from public.parts_consumption
   where organisation_id = p_org
     and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and (p_site is null or site = p_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
     and event_date between p_from and p_to;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._cost_var_dim(p_org uuid, p_country text, p_site text, p_cf date, p_ct date, p_pf date, p_pt date, p_dim text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb; v_sql text;
begin
  if p_dim not in ('site','cost_center','asset_type','asset_code','item_description','store_code') then
    return '{"rows":[],"tail":null}'::jsonb;
  end if;

  v_sql := format($f$
    with g as (
      select coalesce(nullif(btrim(%1$I::text),''),'Unspecified') label,
             coalesce(sum(line_cost) filter (where event_date between $4 and $5),0) cur,
             coalesce(sum(line_cost) filter (where event_date between $6 and $7),0) prev,
             count(*) filter (where event_date between $4 and $5) lines
        from public.parts_consumption
       where organisation_id = $1
         and ($2 is null or country = $2) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and ($3 is null or site = $3) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and (event_date between $4 and $5 or event_date between $6 and $7)
       group by 1),
    r as (select g.*, (cur - prev) d,
                 row_number() over (order by abs(cur - prev) desc, label) rn
            from g where cur <> prev)
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'label', label, 'current', round(cur,2), 'previous', round(prev,2),
                 'delta', round(d,2), 'lines', lines) order by rn)
               from r where rn <= $8), '[]'::jsonb),
      'tail', (select jsonb_build_object(
                 'count', count(*), 'current', round(coalesce(sum(cur),0),2),
                 'previous', round(coalesce(sum(prev),0),2),
                 'delta', round(coalesce(sum(d),0),2))
                 from r where rn > $8),
      'unchanged', (select count(*) from g where cur = prev))
  $f$, p_dim);

  execute v_sql into result
    using p_org, p_country, p_site, p_cf, p_ct, p_pf, p_pt, p_limit;
  return coalesce(result, '{"rows":[],"tail":null}'::jsonb);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._coverage_quiet(p_expect_daily boolean, p_days_since_last integer, p_typical_gap integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    not coalesce(p_expect_daily, false)
    and p_days_since_last is not null
    and p_days_since_last > greatest(coalesce(p_typical_gap, 1), 1),
  false);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._cron_health(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  v_days int := least(greatest(coalesce(p_days, 7), 1), 30);
  v_pol jsonb := public._cron_policy();
  v_grace int := (v_pol ->> 'grace_min')::int;
  v_stuck int := (v_pol ->> 'stuck_min')::int;
  v_ws timestamptz := now() - make_interval(days => v_days);
  v_jobs jsonb;
begin
  if to_regclass('cron.job') is null or to_regclass('cron.job_run_details') is null then
    return jsonb_build_object('ok', false, 'reason', 'pg_cron is not installed');
  end if;

  with jobs as (
    select j.jobid, j.jobname::text as jobname, j.schedule::text as schedule, j.active,
           public._cron_period_minutes(j.schedule) as period
      from cron.job j
     where coalesce(j.jobname, '') not like 'console-run-now-%'
  ),
  runs as (
    select d.jobid, d.start_time, d.end_time, d.status::text as status,
           extract(epoch from (d.end_time - d.start_time)) * 1000 as ms,
           lag(d.start_time) over (partition by d.jobid order by d.start_time) as prev_start
      from cron.job_run_details d
     where d.start_time >= v_ws and d.jobid in (select jobid from jobs)
  ),
  agg as (
    select r.jobid,
           count(*) filter (where r.start_time >= now() - interval '24 hours') as runs_24h,
           count(*) filter (where r.start_time >= now() - interval '24 hours' and r.status = 'failed') as failed_24h,
           count(*) as runs_nd,
           count(*) filter (where r.status = 'failed') as failed_nd,
           round(avg(r.ms) filter (where r.status = 'succeeded' and r.end_time is not null))::int as avg_ms,
           round(max(r.ms) filter (where r.end_time is not null))::int as max_ms,
           min(r.start_time) as first_in_window,
           max(r.start_time) as last_start
      from runs r group by r.jobid
  ),
  gaps as (
    select r.jobid,
           sum(greatest(0, round(extract(epoch from (r.start_time - r.prev_start)) / 60.0 / j.period) - 1))::int as gap_missed
      from runs r join jobs j using (jobid)
     where r.prev_start is not null and j.period is not null
       and r.start_time - r.prev_start > make_interval(mins => j.period + v_grace)
     group by r.jobid
  ),
  latest as (
    select distinct on (d.jobid) d.jobid, d.start_time, d.end_time, d.status::text as status
      from cron.job_run_details d
     where d.jobid in (select jobid from jobs) and d.start_time >= v_ws
     order by d.jobid, d.start_time desc, d.runid desc
  ),
  streak as (
    select x.jobid, count(*) as fails
      from (
        select d.jobid, d.status::text as status,
               sum(case when d.status::text <> 'failed' then 1 else 0 end)
                 over (partition by d.jobid order by d.start_time desc, d.runid desc) as seen_ok
          from cron.job_run_details d
         where d.start_time >= v_ws and d.jobid in (select jobid from jobs)
      ) x
     where x.seen_ok = 0 and x.status = 'failed'
     group by x.jobid
  ),
  older as (
    select j.jobid,
           exists (select 1 from cron.job_run_details d where d.jobid = j.jobid and d.start_time < v_ws) as has_older
      from jobs j
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'jobid', j.jobid,
           'jobname', j.jobname,
           'schedule', j.schedule,
           'active', j.active,
           'period_min', j.period,
           'runs_24h', coalesce(a.runs_24h, 0),
           'failed_24h', coalesce(a.failed_24h, 0),
           'runs_nd', coalesce(a.runs_nd, 0),
           'failed_nd', coalesce(a.failed_nd, 0),
           'avg_ms', a.avg_ms,
           'max_ms', a.max_ms,
           'last_start', l.start_time,
           'last_end', l.end_time,
           'last_status', l.status,
           'first_in_window', a.first_in_window,
           'new_in_window', not o.has_older,
           'fail_streak', coalesce(s.fails, 0),
           'stuck', (l.status in ('running', 'starting') and l.start_time < now() - make_interval(mins => v_stuck)),
           'missed_nd', case
              when j.period is null then null
              when a.last_start is null then case when o.has_older and j.active
                then floor(extract(epoch from (now() - v_ws)) / 60.0 / j.period)::int else 0 end
              else coalesce(g.gap_missed, 0)
                 + case when o.has_older and a.first_in_window - v_ws > make_interval(mins => j.period + v_grace)
                        then floor(extract(epoch from (a.first_in_window - v_ws)) / 60.0 / j.period)::int else 0 end
                 + case when j.active and now() - a.last_start > make_interval(mins => j.period + v_grace)
                        then floor(extract(epoch from (now() - a.last_start)) / 60.0 / j.period)::int else 0 end
            end,
           'expected_nd', case when j.period is null then null
              else floor(extract(epoch from (now() - case when o.has_older then v_ws else coalesce(a.first_in_window, now()) end)) / 60.0 / j.period)::int + case when o.has_older then 0 else 1 end end,
           'overdue', (j.active and j.period is not null and a.last_start is not null
                       and now() - a.last_start > make_interval(mins => j.period + v_grace))
         ) order by j.jobname), '[]'::jsonb)
    into v_jobs
    from jobs j
    left join agg a using (jobid)
    left join gaps g using (jobid)
    left join latest l using (jobid)
    left join streak s using (jobid)
    left join older o using (jobid);

  return jsonb_build_object('ok', true, 'generated_at', now(), 'days', v_days, 'policy', v_pol, 'jobs', v_jobs);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cron_period_minutes(p_schedule text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare f text[];
begin
  f := regexp_split_to_array(btrim(coalesce(p_schedule, '')), '\s+');
  if array_length(f, 1) is distinct from 5 then return null; end if;
  if f[3] <> '*' or f[4] <> '*' then return null; end if;
  if f[1] = '*' and f[2] = '*' and f[5] = '*' then return 1; end if;
  if f[1] ~ '^\*/\d+$' and f[2] = '*' and f[5] = '*' then return substring(f[1] from 3)::int; end if;
  if f[1] ~ '^\d+$' and f[2] = '*' and f[5] = '*' then return 60; end if;
  if f[1] ~ '^\d+$' and f[2] ~ '^\d+$' and f[5] = '*' then return 1440; end if;
  if f[1] ~ '^\d+$' and f[2] ~ '^\d+$' and f[5] ~ '^\d$' then return 10080; end if;
  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cron_policy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'enabled',    coalesce((select lower(btrim(value, ' "')) from system_config where key = 'cron_alert_enabled'), 'true') = 'true',
    'grace_min',  coalesce((select nullif(btrim(value, ' "'), '')::int from system_config where key = 'cron_alert_grace_min'), 5),
    'fail_streak',coalesce((select nullif(btrim(value, ' "'), '')::int from system_config where key = 'cron_alert_fail_streak'), 2),
    'stuck_min',  coalesce((select nullif(btrim(value, ' "'), '')::int from system_config where key = 'cron_alert_stuck_min'), 5),
    'recover_ok', coalesce((select nullif(btrim(value, ' "'), '')::int from system_config where key = 'cron_alert_recover_ok'), 2)
  )
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._cron_runid_since(p_ts timestamp with time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare lo bigint; hi bigint; mid bigint; st timestamptz;
begin
  select min(runid), max(runid) into lo, hi from cron.job_run_details;
  if lo is null then return 0; end if;
  while lo < hi loop
    mid := lo + (hi - lo) / 2;
    select d.start_time into st from cron.job_run_details d where d.runid >= mid order by d.runid limit 1;
    if st is not null and st < p_ts then lo := mid + 1; else hi := mid; end if;
  end loop;
  return lo;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._cron_watch_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  v_pol jsonb := public._cron_policy();
  v_grace int := (v_pol ->> 'grace_min')::int;
  v_stuck int := (v_pol ->> 'stuck_min')::int;
  v_ws timestamptz := now() - interval '1 day';
  v_min bigint := public._cron_runid_since(now() - interval '1 day' - interval '30 minutes');
  v_jobs jsonb;
begin
  with jobs as (
    select j.jobid, j.jobname::text as jobname, j.active, public._cron_period_minutes(j.schedule) as period
      from cron.job j where coalesce(j.jobname, '') not like 'console-run-now-%'
  ),
  recent as materialized (
    select d.jobid, d.runid, d.start_time, d.end_time, d.status::text as status
      from cron.job_run_details d
     where d.runid >= v_min and d.start_time >= v_ws and d.jobid in (select jobid from jobs)
  ),
  latest as (
    select distinct on (r.jobid) r.jobid, r.start_time, r.status from recent r
     order by r.jobid, r.start_time desc, r.runid desc
  ),
  streak as (
    select x.jobid, count(*) fails from (
      select r.jobid, r.status,
             sum(case when r.status <> 'failed' then 1 else 0 end)
               over (partition by r.jobid order by r.start_time desc, r.runid desc) seen_ok
        from recent r) x
     where x.seen_ok = 0 and x.status = 'failed' group by x.jobid
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'jobid', j.jobid, 'jobname', j.jobname, 'active', j.active,
      'last_status', l.status,
      'fail_streak', coalesce(s.fails, 0),
      'stuck', (l.status in ('running', 'starting') and l.start_time < now() - make_interval(mins => v_stuck)),
      'overdue', (j.active and j.period is not null and l.start_time is not null
                  and now() - l.start_time > make_interval(mins => j.period + v_grace))
    ) order by j.jobname), '[]'::jsonb)
    into v_jobs
    from jobs j left join latest l using (jobid) left join streak s using (jobid);
  return jsonb_build_object('ok', true, 'jobs', v_jobs);
end $function$;
