CREATE OR REPLACE FUNCTION public._dup_scan_spec(p_key text DEFAULT NULL::text)
 RETURNS TABLE(key text, tbl text, bkey_cols text[], date_col text, money_col text, src_col text, kind text, label text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select s.key, s.tbl, s.bkey_cols, s.date_col, s.money_col, s.src_col, s.kind, s.label
  from (values
    ('parts_expense', 'parts_consumption',
     array['issue_number','work_order_no','item_code','item_description','qty',
