CREATE OR REPLACE FUNCTION public._erp_country_from_prefix(p_code text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_code is null or btrim(p_code) = '' then null
    when upper(btrim(p_code)) like 'AFKR%' then 'KSA'
    when upper(btrim(p_code)) like 'GCKR%' then 'KSA'
    when upper(btrim(p_code)) like 'RM%'   then 'UAE'
    when upper(btrim(p_code)) like 'EG%'   then 'Egypt'
    else null
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._erp_promote_guard()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid;
begin
  if not (public.is_super_admin() or public.app_is_elevated()) then
    raise exception 'Only an Admin, Manager, Director or super admin can promote imports.' using errcode = '42501';
  end if;
  v_org := public.app_current_org();
  if v_org is null then
    raise exception 'No active organisation in this session.' using errcode = '42501';
  end if;
  return v_org;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._erp_promote_guard_c(p_staging text, p_batch uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public._erp_promote_guard(); v_bad text;
begin
  if p_staging not in ('erp_asset_import','erp_tyre_change_import','erp_tyre_expense_import') then
    raise exception 'Unknown staging table %', p_staging using errcode = '22023';
  end if;
  execute format(
    'select string_agg(distinct s.country, '', '')
       from public.%I s
      where s.batch_id = $1 and s.organisation_id = $2
        and s.country is not null
        and public.app_write_country_ok(s.country) is false', p_staging)
    into v_bad using p_batch, v_org;
  if v_bad is not null then
    raise exception 'Cross-country promotion denied (%).', v_bad using errcode = '42501';
  end if;
  return v_org;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._first_nonblank(VARIADIC p_vals text[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(v), '')
    from unnest(p_vals) as v
   where nullif(btrim(v), '') is not null
   limit 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._flag_state_valid(p_type text, p_state text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_type = 'module' then p_state in ('live', 'maintenance', 'disabled')
    when p_type = 'config' then p_state in ('true', 'false')
    else false end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._flutter_version_cmp(a text, b text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  pa int[] := string_to_array(regexp_replace(btrim(coalesce(a, '')), '^[vV]', ''), '.')::int[];
  pb int[] := string_to_array(regexp_replace(btrim(coalesce(b, '')), '^[vV]', ''), '.')::int[];
  n int := greatest(coalesce(array_length(pa, 1), 0), coalesce(array_length(pb, 1), 0));
  x int; y int;
begin
  for i in 1..n loop
    x := coalesce(pa[i], 0);
    y := coalesce(pb[i], 0);
    if x <> y then
      return case when x < y then -1 else 1 end;
    end if;
  end loop;
  return 0;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._import_batches_derive_row_counters()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE r.validation_status = 'ready')::integer,
    count(*) FILTER (WHERE r.validation_status = 'warning')::integer,
    count(*) FILTER (WHERE r.validation_status = 'error')::integer,
    count(*) FILTER (WHERE r.dup_status = 'duplicate')::integer,
    count(*) FILTER (WHERE r.dup_status = 'conflict')::integer
  INTO
    NEW.total_rows,
    NEW.ready_rows,
    NEW.warning_rows,
    NEW.error_rows,
    NEW.duplicate_rows,
    NEW.conflict_rows
  FROM public.import_rows AS r
  WHERE r.batch_id = NEW.id;

  RETURN NEW;
END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._import_rows_sync_counters_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_batch_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT o.batch_id ORDER BY o.batch_id)
    INTO v_batch_ids
  FROM old_rows AS o;

  PERFORM public._sync_import_batch_counters(v_batch_ids);
  RETURN NULL;
END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._import_rows_sync_counters_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_batch_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT n.batch_id ORDER BY n.batch_id)
    INTO v_batch_ids
  FROM new_rows AS n;

  PERFORM public._sync_import_batch_counters(v_batch_ids);
  RETURN NULL;
END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._import_rows_sync_counters_after_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  PERFORM public._sync_import_batch_counters(NULL);
  RETURN NULL;
END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._import_rows_sync_counters_after_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_batch_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT affected.batch_id ORDER BY affected.batch_id)
    INTO v_batch_ids
  FROM (
    SELECT o.batch_id FROM old_rows AS o
    UNION
    SELECT n.batch_id FROM new_rows AS n
  ) AS affected;

  PERFORM public._sync_import_batch_counters(v_batch_ids);
  RETURN NULL;
END
$function$;
