CREATE OR REPLACE FUNCTION public._raise_checklist_corrective_actions(p_submission_id uuid, p_dry_run boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.checklist_submissions;
  v_blocking jsonb; v_fields jsonb; v_tname text;
  a record; v_label text; v_n integer := 0;
begin
  select * into s from public.checklist_submissions where id = p_submission_id;
  if not found then return 0; end if;
  -- The legend the record was filled against wins over the current form.
  select coalesce(s.template_snapshot #> '{option_sets,legend,blocking}', t.option_sets #> '{legend,blocking}'),
         coalesce(s.template_snapshot->'fields', t.fields), t.name
    into v_blocking, v_fields, v_tname
    from public.checklist_templates t where t.id = s.template_id;
  if v_blocking is null or jsonb_typeof(v_blocking) <> 'array' then return 0; end if;

  for a in select key, value from jsonb_each_text(coalesce(s.answers, '{}'::jsonb))
            where jsonb_exists(v_blocking, value) loop
    v_label := public.checklist_field_label(v_fields, a.key);
    continue when exists (
      select 1 from public.corrective_actions c
       where c.source_type = 'checklist' and c.source_id = s.id and c.source_detail = v_label);
    v_n := v_n + 1;
    if not p_dry_run then
      insert into public.corrective_actions
        (organisation_id, title, description, priority, status, site, asset_no, country, region,
         source_type, source_id, source_detail, created_by)
      values
        (s.organisation_id,
         left('Checklist fault: ' || v_label || ' (' || coalesce(s.document_no, v_tname, 'checklist') || ')', 240),
         'Recorded "' || a.value || '" on ' || coalesce(v_tname, 'a checklist')
           || coalesce(' ' || s.document_no, '')
           || coalesce(' for asset ' || s.asset_no, '')
           || ' on ' || to_char(coalesce(s.submitted_at, s.created_at), 'YYYY-MM-DD') || '.',
         'High', 'Open', s.site, s.asset_no, coalesce(s.country, 'KSA'), coalesce(s.country, 'KSA'),
         'checklist', s.id, v_label, s.submitted_by);
    end if;
  end loop;
  return v_n;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._report_cost_block(p_org uuid, p_site text, p_country text, p_from date, p_to date, p_months text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_by jsonb;
  v_curs text[];
  v_one boolean;
  v_internal numeric; v_tyre numeric; v_maint numeric;
  v_sco numeric; v_sany numeric; v_total numeric;
  v_km numeric; v_hours numeric; v_m3 numeric;
  v_dropped int;
  v_days int := greatest(1, (p_to - p_from) + 1);
begin
  -- Per country, each in its own currency, internal + SCO + SANY so the board
  -- and the Cost per M3 screen answer the same question the same way.
  select coalesce(jsonb_agg(jsonb_build_object(
           'country', c.country, 'currency', c.currency,
           'total', c.internal + c.sco + c.sany,
           'internal', c.internal, 'tyre', c.tyre, 'maintenance', c.maint,
           'sco', c.sco, 'sany', c.sany
         ) ORDER BY c.country), '[]'::jsonb),
         coalesce(array_agg(distinct c.currency) filter (where c.currency is not null), '{}')
    into v_by, v_curs
    from (
      select p.country,
             max(p.currency) as currency,
             round(sum(coalesce(p.line_cost, 0))) as internal,
             round(sum(coalesce(p.tyre_cost, 0))) as tyre,
             round(sum(coalesce(p.spare_cost, 0) + coalesce(p.oil_cost, 0))) as maint,
             coalesce((select round(sum(s.amount)) from public.sco_costs s
                        where s.organisation_id = p_org and s.country = p.country
                          and (p_site is null or s.site = p_site)
                          and s.period_date between p_from and p_to), 0) as sco,
             coalesce((select round(sum(y.amount)) from public.sany_invoices y
                        where y.organisation_id = p_org and y.country = p.country
                          and (p_site is null or y.site = p_site)
                          and coalesce(y.doc_type, '') <> 'detail'
                          and y.period_date between p_from and p_to), 0) as sany
        from public.parts_consumption p
       where p.organisation_id = p_org
         and (p_site is null or p.site = p_site)
         and (p_country is null or p.country = p_country)
         and p.event_date between p_from and p_to
       group by p.country
    ) c;

  v_one := coalesce(array_length(v_curs, 1), 0) = 1;

  if v_one then
    select coalesce((v_by->0->>'internal')::numeric, 0),
           coalesce((v_by->0->>'tyre')::numeric, 0),
           coalesce((v_by->0->>'maintenance')::numeric, 0),
           coalesce((v_by->0->>'sco')::numeric, 0),
           coalesce((v_by->0->>'sany')::numeric, 0)
      into v_internal, v_tyre, v_maint, v_sco, v_sany;
    v_total := v_internal + v_sco + v_sany;
  end if;

  select coalesce(sum(d.km), 0) into v_km from (
    select max(odometer_km) - min(odometer_km) as km
      from public.odometer_logs
     where organisation_id = p_org and (p_site is null or site = p_site)
       and (p_country is null or country = p_country)
       and odometer_km is not null and reading_date between p_from and p_to
     group by asset_no having count(*) >= 2
  ) d;

  -- An asset cannot run more hours than the window has. A span above that is a
  -- bad reading; it is dropped and counted, never quietly folded into the total.
  select coalesce(sum(d.h) filter (where d.h <= v_days * 24), 0),
         count(*) filter (where d.h > v_days * 24)
    into v_hours, v_dropped
    from (
      select max(engine_hours) - min(engine_hours) as h
        from public.engine_hours_logs
       where organisation_id = p_org and (p_site is null or site = p_site)
         and (p_country is null or country = p_country)
         and engine_hours is not null and reading_date between p_from and p_to
       group by asset_no having count(*) >= 2
    ) d;

  select coalesce(sum(coalesce(approved_m3, m3, 0)), 0) into v_m3
    from public.production_logs
   where organisation_id = p_org and (p_site is null or site = p_site)
     and (p_country is null or country = p_country)
     and period_date between p_from and p_to;

  return jsonb_build_object(
    'from', p_from, 'to', p_to,
    'basis', 'expense grid + SCO + SANY',
    'by_country', v_by,
    'currencies', to_jsonb(v_curs),
    'mixed_currency', not v_one,
    'tyre_cost', case when v_one then v_tyre else null end,
    'maintenance_cost', case when v_one then v_maint else null end,
    'internal_cost', case when v_one then v_internal else null end,
    'sco_cost', case when v_one then v_sco else null end,
    'sany_cost', case when v_one then v_sany else null end,
    'total_cost', case when v_one then v_total else null end,
    'km', round(coalesce(v_km, 0)),
    'engine_hours', round(coalesce(v_hours, 0), 1),
    'hours_assets_dropped', coalesce(v_dropped, 0),
    'm3', round(coalesce(v_m3, 0), 1),
    'cost_per_km',   case when v_one and coalesce(v_km, 0) > 0    then round(v_total / v_km, 2)    end,
    'cost_per_hour', case when v_one and coalesce(v_hours, 0) > 0 then round(v_total / v_hours, 2) end,
    -- Same floor the Cost per M3 screen uses: below it the rate is arithmetic,
    -- not a measurement.
    'cost_per_m3',   case when v_one and coalesce(v_m3, 0) >= 1000 then round(v_total / v_m3, 2) end,
    'm3_too_thin',   coalesce(v_m3, 0) > 0 and coalesce(v_m3, 0) < 1000,
    'tyre_cpk',      case when v_one and coalesce(v_km, 0) > 0    then round(v_tyre / v_km, 2)     end,
    'trend', jsonb_build_object(
      'total', (select jsonb_agg(round(coalesce(s.v, 0)) order by m.k) from unnest(p_months) m(k)
                 left join (
                   select to_char(event_date, 'YYYY-MM') k, sum(coalesce(line_cost, 0)) v
                     from public.parts_consumption
                    where organisation_id = p_org and (p_site is null or site = p_site)
                      and (p_country is null or country = p_country)
                    group by 1
                 ) s on s.k = m.k),
      'm3', (select jsonb_agg(round(coalesce(s.v, 0), 1) order by m.k) from unnest(p_months) m(k)
              left join (
                select to_char(period_date, 'YYYY-MM') k, sum(coalesce(approved_m3, m3, 0)) v
                  from public.production_logs
                 where organisation_id = p_org and (p_site is null or site = p_site)
                   and (p_country is null or country = p_country)
                 group by 1
              ) s on s.k = m.k)
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._request_client_ip()
 RETURNS inet
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare h json; v text;
begin
  begin
    h := nullif(current_setting('request.headers', true), '')::json;
  exception when others then return null;
  end;
  if h is null then return null; end if;
  v := nullif(btrim(h->>'cf-connecting-ip'), '');
  if v is null then v := nullif(btrim(split_part(coalesce(h->>'x-forwarded-for', ''), ',', 1)), ''); end if;
  if v is null then v := nullif(btrim(h->>'x-real-ip'), ''); end if;
  if v is null then return null; end if;
  begin
    return host(v::inet)::inet;
  exception when others then return null;
  end;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._scope_split_countries(p_countries text[], OUT allowed text[], OUT refused text[])
 RETURNS record
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with req as (
    -- one row per DISTINCT country asked for, first spelling and position win
    select distinct on (lower(btrim(c))) btrim(c) as c, ord
      from unnest(coalesce(p_countries, '{}'::text[])) with ordinality as u(c, ord)
     where c is not null and btrim(c) <> ''
     order by lower(btrim(c)), ord
  ), split as (
    select c, ord, public.app_can_see_country(c) as visible from req
  )
  select
    coalesce((select array_agg(c order by ord) from split where visible),     '{}'::text[]),
    coalesce((select array_agg(c order by ord) from split where not visible), '{}'::text[]);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._security_posture_compute()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_checks jsonb := '[]'::jsonb;
  v_items  jsonb;
  v_n      int;
  v_allow  text[] := array[
    'get_email_by_identifier','get_public_config','login_attempt_status',
    'record_login_failure','reset_login_attempts','get_report_snapshot',
    'get_report_tyre_maintenance','get_workshop_snapshot',
    'get_accident_portal_snapshot','get_display_snapshot'];
  v_weights jsonb := '{"critical":25,"high":10,"medium":4,"low":1}';
  v_score  int := 100;
  c jsonb;
begin
  select coalesce(jsonb_agg(c.relname order by c.relname), '[]'), count(*)
    into v_items, v_n
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind in ('r','p') and not c.relrowsecurity;
  v_checks := v_checks || jsonb_build_object('id','rls_disabled','category','Data isolation',
    'title','Tables without row-level security','severity','critical',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','Every table the app can reach must enforce row-level security, or any signed-in user can read all of it.',
    'fix','Enable RLS and add an organisation isolation policy.');

  select coalesce(jsonb_agg(distinct table_name), '[]'), count(distinct table_name)
    into v_items, v_n
    from information_schema.role_table_grants
   where table_schema = 'public' and grantee = 'anon';
  v_checks := v_checks || jsonb_build_object('id','anon_table_grants','category','Data isolation',
    'title','Tables reachable without signing in','severity','critical',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','Anonymous visitors must reach data only through reviewed token functions, never a table.',
    'fix','Revoke the grant from anon.');

  select coalesce(jsonb_agg(p.proname order by p.proname), '[]'), count(*)
    into v_items, v_n
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prosecdef
     and has_function_privilege('anon', p.oid, 'EXECUTE')
     and p.proname <> all (v_allow);
  v_checks := v_checks || jsonb_build_object('id','anon_definer_functions','category','Data isolation',
    'title','Privileged functions open to anonymous callers','severity','high',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','Ten functions are open by design (sign-in and public share links). Anything else runs with owner rights for anyone on the internet.',
    'fix','Revoke EXECUTE from PUBLIC, then from anon by name.');

  select coalesce(jsonb_agg(p.proname order by p.proname), '[]'), count(*)
    into v_items, v_n
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prosecdef
     and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) cfg where cfg like 'search_path=%');
  v_checks := v_checks || jsonb_build_object('id','definer_search_path','category','Code hardening',
    'title','Privileged functions without a fixed search path','severity','high',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','A privileged function that resolves names through the caller''s search path can be tricked into running someone else''s object.',
    'fix','ALTER FUNCTION ... SET search_path = public.');

  select coalesce(jsonb_agg(c.relname order by c.relname), '[]'), count(*)
    into v_items, v_n
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'v'
     and not coalesce(c.reloptions @> array['security_invoker=on'] or c.reloptions @> array['security_invoker=true'], false)
     and has_table_privilege('authenticated', c.oid, 'SELECT');
  v_checks := v_checks || jsonb_build_object('id','owner_views','category','Data isolation',
    'title','Views that bypass row-level security','severity','high',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','A view runs as its owner unless security_invoker is set, so it can show rows the reader could never read directly.',
    'fix','ALTER VIEW ... SET (security_invoker = on).');

  select coalesce(jsonb_agg(distinct table_name), '[]'), count(distinct table_name)
    into v_items, v_n
    from information_schema.role_table_grants
   where table_schema = 'public' and grantee in ('authenticated','anon')
     and privilege_type in ('TRUNCATE','TRIGGER');
  v_checks := v_checks || jsonb_build_object('id','truncate_grants','category','Data isolation',
    'title','Client roles that can empty a table','severity','high',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','TRUNCATE is not covered by row-level security, so one statement would erase every company''s rows.',
    'fix','REVOKE TRUNCATE, TRIGGER from authenticated, anon.');

  select coalesce(jsonb_agg(coalesce(p.email, p.full_name, p.id::text) order by p.email), '[]'), count(*)
    into v_items, v_n
    from public.profiles p
   where coalesce(p.is_super_admin,false) and not coalesce(p.locked,false)
     and not exists (select 1 from auth.mfa_factors f where f.user_id = p.id and f.status = 'verified');
  v_checks := v_checks || jsonb_build_object('id','super_admin_mfa','category','Identity',
    'title','Super admins without two-factor sign-in','severity','high',
    'status', case when v_n = 0 then 'pass' else 'fail' end, 'count', v_n, 'items', v_items,
    'explain','A super admin controls every company. A password alone is not enough for that account.',
    'fix','Enrol an authenticator app in Console > Security.');

  select count(*) into v_n from public.profiles where coalesce(is_super_admin,false) and not coalesce(locked,false);
  v_checks := v_checks || jsonb_build_object('id','super_admin_count','category','Identity',
    'title','Number of super admins','severity','medium',
    'status', case when v_n between 2 and 5 then 'pass' else 'warn' end, 'count', v_n, 'items', '[]'::jsonb,
    'explain','Keep two to five: one is a single point of failure, more than five is more power than anyone needs.',
    'fix','Promote a second trusted person, or demote extras, in Console > Users.');

  select coalesce(jsonb_agg(coalesce(email, full_name) order by email), '[]'), count(*)
    into v_items, v_n
    from public.profiles where role = 'Admin' and not coalesce(is_super_admin,false) and coalesce(approved,false);
  v_checks := v_checks || jsonb_build_object('id','plain_admins','category','Identity',
    'title','Admins who are not super admins','severity','medium',
    'status', case when v_n = 0 then 'pass' else 'warn' end, 'count', v_n, 'items', v_items,
    'explain','An Admin sees every module and all company data. Access changes are super-admin only, but check each one is intended.',
    'fix','Review in Console > Users.');

  select coalesce(jsonb_agg(identifier order by identifier), '[]'), count(*)
    into v_items, v_n
    from public.login_attempts where locked_until > now();
  v_checks := v_checks || jsonb_build_object('id','locked_logins','category','Identity',
    'title','Sign-ins locked after failed attempts','severity','medium',
    'status', case when v_n = 0 then 'pass' else 'warn' end, 'count', v_n, 'items', v_items,
    'explain','Repeated wrong passwords lock an identifier for 15 minutes. Several at once can mean someone is guessing.',
    'fix','Check the identifiers. Real users unlock automatically.');

  select coalesce(jsonb_agg(name order by name), '[]'), count(*)
    into v_items, v_n
    from storage.buckets where public;
  v_checks := v_checks || jsonb_build_object('id','public_buckets','category','Files',
    'title','File buckets open to the internet','severity','medium',
    'status', case when v_n = 0 then 'pass' else 'warn' end, 'count', v_n, 'items', v_items,
    'explain','A public bucket serves every file to anyone who has the link, with no sign-in.',
    'fix','Make the bucket private and serve signed URLs.');

  select coalesce(jsonb_agg(c.relname order by c.relname), '[]'), count(*)
    into v_items, v_n
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
     and not exists (select 1 from pg_policy pol where pol.polrelid = c.oid);
  v_checks := v_checks || jsonb_build_object('id','rls_no_policy','category','Data isolation',
    'title','Locked tables with no access rule','severity','low',
    'status', 'info', 'count', v_n, 'items', v_items,
    'explain','Row-level security with no policy denies everyone. That is correct for snapshots and staging, and only a problem if the app needs the table.',
    'fix','None needed unless a screen reads the table.');

  select coalesce(jsonb_agg(e.extname order by e.extname), '[]'), count(*)
    into v_items, v_n
    from pg_extension e join pg_namespace n on n.oid = e.extnamespace
   where n.nspname = 'public';
  v_checks := v_checks || jsonb_build_object('id','extensions_public','category','Code hardening',
    'title','Database extensions in the public schema','severity','low',
    'status', case when v_n = 0 then 'pass' else 'warn' end, 'count', v_n, 'items', v_items,
    'explain','Known and low risk. Moving vector or pg_net breaks existing columns and jobs, so it is left deliberately.',
    'fix','Leave unless a planned maintenance window moves them.');

  v_checks := v_checks || jsonb_build_object('id','leaked_password','category','Identity',
    'title','Block known leaked passwords','severity','medium',
    'status', 'manual', 'count', null, 'items', '[]'::jsonb,
    'explain','Supabase can refuse passwords that appear in public breach lists. It is a dashboard setting, so this page cannot check it.',
    'fix','Supabase dashboard > Authentication > Passwords > enable leaked password protection.');

  for c in select * from jsonb_array_elements(v_checks) loop
    if c->>'status' = 'fail' then
      v_score := v_score - (v_weights->>(c->>'severity'))::int;
    elsif c->>'status' = 'warn' then
      v_score := v_score - ceil((v_weights->>(c->>'severity'))::numeric / 2)::int;
    end if;
  end loop;

  return jsonb_build_object(
    'generated_at', now(),
    'score', greatest(v_score, 0),
    'checks', v_checks,
    'activity', jsonb_build_object(
      'console_logins_7d', (select count(*) from public.console_sessions where action = 'login' and created_at > now() - interval '7 days'),
      'access_changes_7d', (select count(*) from public.access_audit where at > now() - interval '7 days'),
      'super_admin_changes_30d', (select count(*) from public.access_audit where entity = 'super_admin' and at > now() - interval '30 days'),
      'errors_7d', (select count(*) from public.system_logs where severity in ('error','critical') and created_at > now() - interval '7 days'),
      'locked_accounts', (select count(*) from public.profiles where coalesce(locked,false)),
      'pending_approvals', (select count(*) from public.profiles where not coalesce(approved,false) and not coalesce(locked,false))
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._security_scan_record(p_trigger text, p_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_res jsonb := public._security_posture_compute();
  v_failing text[];
  v_prev text[];
  v_new text[];
  v_counts jsonb;
begin
  select coalesce(array_agg(c->>'id'), '{}') into v_failing
    from jsonb_array_elements(v_res->'checks') c where c->>'status' in ('fail','warn');
  select jsonb_build_object(
      'critical', count(*) filter (where c->>'severity'='critical' and c->>'status' in ('fail','warn')),
      'high',     count(*) filter (where c->>'severity'='high'     and c->>'status' in ('fail','warn')),
      'medium',   count(*) filter (where c->>'severity'='medium'   and c->>'status' in ('fail','warn')),
      'low',      count(*) filter (where c->>'severity'='low'      and c->>'status' in ('fail','warn')))
    into v_counts from jsonb_array_elements(v_res->'checks') c;
  select failing into v_prev from public.security_scan_runs order by ran_at desc limit 1;
  select coalesce(array_agg(x), '{}') into v_new
    from unnest(v_failing) x where x <> all (coalesce(v_prev, '{}'));
  insert into public.security_scan_runs (trigger, ran_by, score, critical, high, medium, low, failing, result)
  values (p_trigger, p_by, (v_res->>'score')::int, (v_counts->>'critical')::int, (v_counts->>'high')::int,
          (v_counts->>'medium')::int, (v_counts->>'low')::int, v_failing, v_res);
  if cardinality(v_new) > 0 then
    insert into public.notifications (user_id, type, title, body, entity_type)
    select p.id, 'security', 'New security finding',
           'Security audit found: ' || array_to_string(v_new, ', ') || '. Open Console > Security Audit.',
           'security_audit'
      from public.profiles p where coalesce(p.is_super_admin,false) and not coalesce(p.locked,false);
    insert into public.system_logs (severity, source, module_id, message, detail)
    values ('warning', 'security_audit', 'security_audit', 'New security finding: ' || array_to_string(v_new, ', '),
            jsonb_build_object('new', v_new, 'score', v_res->'score'));
  end if;
  return v_res || jsonb_build_object('new_findings', to_jsonb(v_new));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._sso_enforced_domains(p_org uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(distinct d), '{}'::text[]) from (
    select lower(btrim(x)) d
      from public.sso_connections c, unnest(string_to_array(coalesce(c.domains, ''), ',')) x
     where c.organisation_id = p_org and c.status = 'active' and c.enforce_sso
  ) s where d <> ''
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._stg_country_pipe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_country text := tg_argv[0];
  v_target  text := tg_argv[1];
  v_row     jsonb;
  v_org     uuid;
begin
  v_org := public.app_current_org();

  if v_org is null then
    select o.id
      into v_org
    from public.organisations o
    where o.country = v_country
    order by o.created_at asc
    limit 1;
  end if;

  if v_org is null then
    raise exception 'No organisation_id resolved for country %', v_country;
  end if;

  v_row := (to_jsonb(new) - 'id' - 'created_at' - 'organisation_id')
           || jsonb_build_object('country', v_country, 'organisation_id', v_org);

  -- Monthly-tyre country tables accept either canonical API columns or the
  -- ERP's original quoted headers. Read through JSON so this generic trigger
  -- remains valid for every other country staging table as well.
  if v_target = 'stg_monthly_tyres' then
    v_row := v_row || jsonb_build_object(
      'job_card_no', coalesce(v_row ->> 'job_card_no', v_row ->> 'Job Card No.'),
      'job_card_date', coalesce(v_row ->> 'job_card_date', v_row ->> 'Job Card Date'),
      'veh_no', coalesce(v_row ->> 'veh_no', v_row ->> 'VEH.NO'),
      'veh_type', coalesce(v_row ->> 'veh_type', v_row ->> 'VEH TYPE/CATEGORY'),
      'item_tyre', coalesce(v_row ->> 'item_tyre', v_row ->> 'ITEM/TYRE'),
      'tyre_position', coalesce(v_row ->> 'tyre_position', v_row ->> 'TYRE POSITION'),
      'tyre_no', coalesce(v_row ->> 'tyre_no', v_row ->> 'TYRE No.'),
      'tyre_fix_date', coalesce(v_row ->> 'tyre_fix_date', v_row ->> 'TYRE FIX DATE'),
      'fixed_km', coalesce(v_row ->> 'fixed_km', v_row ->> 'FIXED KM'),
      'fixed_hrs', coalesce(v_row ->> 'fixed_hrs', v_row ->> 'FIXED HRS'),
      'tyre_removed_date', coalesce(v_row ->> 'tyre_removed_date', v_row ->> 'TYRE REMOVED DATE'),
      'removed_km', coalesce(v_row ->> 'removed_km', v_row ->> 'REMOVED KM'),
      'removed_hrs', coalesce(v_row ->> 'removed_hrs', v_row ->> 'REMOVED HRS'),
      'reason', coalesce(v_row ->> 'reason', v_row ->> 'REASON'),
      'total_km', coalesce(v_row ->> 'total_km', v_row ->> 'TOTAL KM '),
      'total_hrs', coalesce(v_row ->> 'total_hrs', v_row ->> 'TOTAL HRS')
    );
  end if;

  execute format(
    'insert into public.%I select * from jsonb_populate_record(null::public.%I, $1)',
    v_target, v_target
  ) using v_row;

  return null;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._stg_pick(p_row jsonb, p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(kv.value), '')
    from jsonb_each_text(p_row) as kv(key, value)
   where lower(btrim(regexp_replace(replace(kv.key, chr(160), ' '), '\s+', ' ', 'g')))
       = lower(btrim(regexp_replace(replace(p_key,  chr(160), ' '), '\s+', ' ', 'g')))
     and nullif(btrim(kv.value), '') is not null
   limit 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._sync_import_batch_counters(p_batch_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_batch_ids uuid[];
BEGIN
  IF p_batch_ids IS NULL THEN
    v_batch_ids := NULL; -- NULL intentionally means every historical batch.
  ELSE
    SELECT array_agg(DISTINCT u.batch_id ORDER BY u.batch_id)
      INTO v_batch_ids
    FROM unnest(p_batch_ids) AS u(batch_id)
    WHERE u.batch_id IS NOT NULL;

    IF COALESCE(cardinality(v_batch_ids), 0) = 0 THEN
      RETURN;
    END IF;
  END IF;

  -- Deterministic lock order prevents two multi-batch updates deadlocking.
  PERFORM b.id
  FROM public.import_batches AS b
  WHERE v_batch_ids IS NULL OR b.id = ANY(v_batch_ids)
  ORDER BY b.id
  FOR UPDATE;

  WITH actual AS (
    SELECT
      b.id AS batch_id,
      count(r.id)::integer AS total_rows,
      count(r.id) FILTER (WHERE r.validation_status = 'ready')::integer AS ready_rows,
      count(r.id) FILTER (WHERE r.validation_status = 'warning')::integer AS warning_rows,
      count(r.id) FILTER (WHERE r.validation_status = 'error')::integer AS error_rows,
      count(r.id) FILTER (WHERE r.dup_status = 'duplicate')::integer AS duplicate_rows,
      count(r.id) FILTER (WHERE r.dup_status = 'conflict')::integer AS conflict_rows
    FROM public.import_batches AS b
    LEFT JOIN public.import_rows AS r ON r.batch_id = b.id
    WHERE v_batch_ids IS NULL OR b.id = ANY(v_batch_ids)
    GROUP BY b.id
  )
  UPDATE public.import_batches AS b
  SET total_rows     = a.total_rows,
      ready_rows     = a.ready_rows,
      warning_rows   = a.warning_rows,
      error_rows     = a.error_rows,
      duplicate_rows = a.duplicate_rows,
      conflict_rows  = a.conflict_rows
  FROM actual AS a
  WHERE b.id = a.batch_id
    AND ROW(
      COALESCE(b.total_rows, 0),
      COALESCE(b.ready_rows, 0),
      COALESCE(b.warning_rows, 0),
      COALESCE(b.error_rows, 0),
      COALESCE(b.duplicate_rows, 0),
      COALESCE(b.conflict_rows, 0)
    ) IS DISTINCT FROM ROW(
      a.total_rows,
      a.ready_rows,
      a.warning_rows,
      a.error_rows,
      a.duplicate_rows,
      a.conflict_rows
    );
END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_due_for_purge(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'job_id', j.id, 'org_id', j.org_id, 'status', j.status,
           'finished_at', coalesce(j.completed_at, j.updated_at, j.created_at),
           'prefix', j.org_id::text || '/' || j.id::text,
           'files', jsonb_array_length(coalesce(j.files, '[]'::jsonb)))
         order by coalesce(j.completed_at, j.updated_at, j.created_at)), '[]'::jsonb)
    from (select * from public.tenant_export_jobs j
           where j.mode = 'server'
             and j.status in ('completed','partial','failed')
             and j.expired_at is null
             and coalesce(j.completed_at, j.updated_at, j.created_at)
                 < now() - make_interval(days => public._tenant_export_retention_days())
           order by coalesce(j.completed_at, j.updated_at, j.created_at)
           limit least(greatest(coalesce(p_limit, 50), 1), 200)) j;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_mark_expired(p_job uuid, p_objects integer, p_bytes bigint, p_trigger text, p_actor uuid, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job public.tenant_export_jobs%rowtype;
  v_trigger text := case when p_trigger in ('cron','manual') then p_trigger else 'cron' end;
  v_days int := public._tenant_export_retention_days();
begin
  select * into v_job from public.tenant_export_jobs where id = p_job for update;
  if not found or v_job.mode <> 'server' then
    raise exception 'Export job not found' using errcode = 'P0002';
  end if;

  if p_error is not null then
    insert into public.system_logs (organisation_id, module_id, severity, source, message, detail)
    values (v_job.org_id, 'tenant_export', 'warning', 'tenant-export-retention',
            'Tenant export files could not be deleted; will retry',
            jsonb_build_object('job_id', p_job, 'error', left(p_error, 300),
                               'removed_objects', coalesce(p_objects, 0), 'trigger', v_trigger));
    return jsonb_build_object('ok', false, 'job_id', p_job);
  end if;

  if v_job.status = 'expired' then
    return jsonb_build_object('ok', true, 'job_id', p_job, 'already', true);
  end if;
  if v_job.status = 'running' then
    raise exception 'That export is still running' using errcode = '55P03';
  end if;

  update public.tenant_export_jobs
     set status = 'expired', expired_at = now(), updated_at = now(),
         progress = coalesce(progress, '{}'::jsonb) || jsonb_build_object(
           'purge', jsonb_build_object('at', now(), 'objects', coalesce(p_objects, 0),
                                       'bytes', coalesce(p_bytes, 0), 'trigger', v_trigger,
                                       'status_before', v_job.status))
   where id = p_job;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (p_actor, 'tenant_export_purge', v_job.org_id, 'organisation',
          jsonb_build_object('job_id', p_job, 'objects', coalesce(p_objects, 0),
                             'bytes', coalesce(p_bytes, 0), 'trigger', v_trigger,
                             'retention_days', v_days, 'status_before', v_job.status));

  insert into public.system_logs (organisation_id, module_id, severity, source, message, detail, user_id)
  values (v_job.org_id, 'tenant_export', 'info', 'tenant-export-retention',
          'Expired tenant export files deleted',
          jsonb_build_object('job_id', p_job, 'objects', coalesce(p_objects, 0),
                             'bytes', coalesce(p_bytes, 0), 'trigger', v_trigger,
                             'retention_days', v_days),
          p_actor);

  return jsonb_build_object('ok', true, 'job_id', p_job);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_ndjson(p_org uuid, p_table text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit int := least(greatest(coalesce(p_limit, 5000), 1), 10000);
  v_body text; v_n int; v_last uuid;
begin
  if p_org is null or p_table is null or not (p_table = any (public._tenant_export_tables())) then
    raise exception 'That table cannot be exported' using errcode = '22023';
  end if;
  execute format(
    'select coalesce(string_agg(to_jsonb(x)::text, E''\n'' order by x.id), ''''), count(*)::int, '
    || '(array_agg(x.id order by x.id desc))[1] '
    || 'from (select * from public.%I t where t.organisation_id = $1 '
    || 'and ($2::uuid is null or t.id > $2) order by t.id limit $3) x', p_table)
  into v_body, v_n, v_last using p_org, p_after, v_limit;
  return jsonb_build_object('body', v_body, 'n', v_n, 'last', v_last, 'done', v_n < v_limit);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_request_purge(p_trigger text, p_actor uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_secret text;
  v_id bigint;
begin
  select value into v_secret from public.cron_config where name = 'cron_secret';
  if v_secret is null or v_secret = '' then
    raise exception 'Cleanup is not configured (no cron secret)' using errcode = '55000';
  end if;
  select net.http_post(
    url := 'https://staging-project-ref.supabase.co/functions/v1/tenant-export',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secret),
    body := jsonb_build_object('action', 'cleanup',
                               'trigger', case when p_trigger = 'manual' then 'manual' else 'cron' end,
                               'actor', p_actor),
    timeout_milliseconds := 60000
  ) into v_id;
  return v_id;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_retention_days()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text; n int;
begin
  select trim(both '"' from btrim(value)) into v from public.system_config
   where key = 'tenant_export_retention_days';
  if v is null or v !~ '^\d{1,6}$' then return 7; end if;
  n := v::int;
  return least(greatest(n, 1), 90);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tenant_export_tables()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array[
    'accidents','alerts','asset_breakdowns','asset_disposals','budgets',
    'checklist_submissions','corrective_actions','drivers','engine_hours_logs',
    'gate_passes','goods_receipts','inspections','insurance_policies',
    'material_issues','material_master','odometer_logs','parts_consumption',
    'parts_requests','pm_programs','pm_service_records','production_logs',
    'purchase_orders','rca_records','repair_requests','sany_invoices','sco_costs',
    'sites','stock_records','suppliers','tyre_records','tyre_rotations',
    'tyre_status_marks','vehicle_fleet','warranty_claims','wash_records',
    'work_order_line_items','work_orders'
  ]::text[]
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._to_num(t text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE s text;
BEGIN
  s := regexp_replace(coalesce(t,''), '[^0-9.\-]', '', 'g');
  IF s IS NULL OR s = '' OR s = '-' OR s = '.' THEN RETURN NULL; END IF;
  RETURN s::numeric;
EXCEPTION WHEN others THEN RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public._tyre_close_replaced(p_org uuid, p_country text, p_asset text, p_position text, p_serial text, p_fit_date date, p_fit_km numeric, p_fit_hrs numeric, p_source text, p_batch uuid, p_dry_run boolean DEFAULT false, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_asset  text := nullif(upper(regexp_replace(coalesce(p_asset, ''), '\s+', '', 'g')), '');
  v_pos    text := nullif(upper(btrim(coalesce(p_position, ''))), '');
  v_serial text := nullif(upper(btrim(coalesce(p_serial, ''))), '');
  v_cnt int; v_prev public.tyre_records%rowtype; v_prev_date date; v_later int; v_rem_date date;
  v_rem_km numeric; v_rem_hrs numeric; v_total_km numeric; v_total_hrs numeric; v_new jsonb;
begin
  if p_fit_date is null or v_asset is null or v_pos is null or v_pos = '0' then
    return jsonb_build_object('status', 'not_applicable');
  end if;
  select count(*) into v_cnt from public.tyre_records t
  where t.organisation_id is not distinct from p_org and coalesce(t.country, '') = coalesce(p_country, '')
    and upper(regexp_replace(coalesce(t.asset_no, t.asset_number, ''), '\s+', '', 'g')) = v_asset
    and upper(btrim(coalesce(t.tyre_position, t.position, ''))) = v_pos
    and public.tyre_status_is_active(t.status);
  if v_cnt = 0 then return jsonb_build_object('status', 'no_previous'); end if;
  if v_cnt > 1 then return jsonb_build_object('status', 'ambiguous_multiple_active'); end if;
  select t.* into v_prev from public.tyre_records t
  where t.organisation_id is not distinct from p_org and coalesce(t.country, '') = coalesce(p_country, '')
    and upper(regexp_replace(coalesce(t.asset_no, t.asset_number, ''), '\s+', '', 'g')) = v_asset
    and upper(btrim(coalesce(t.tyre_position, t.position, ''))) = v_pos
    and public.tyre_status_is_active(t.status)
  for update;
  if v_serial is not null and upper(btrim(coalesce(v_prev.serial_no, ''))) = v_serial then
    return jsonb_build_object('status', 'same_tyre', 'tyre_id', v_prev.id);
  end if;
  v_prev_date := coalesce(v_prev.issue_date, v_prev.fitment_date);
  if not p_force then
    if v_prev_date is null then return jsonb_build_object('status', 'ambiguous_previous_undated', 'tyre_id', v_prev.id); end if;
    -- Same day: the latest upload is the latest information about the wheel.
    if v_prev_date > p_fit_date then return jsonb_build_object('status', 'ambiguous_not_later', 'tyre_id', v_prev.id); end if;
    -- 20261109150000: same day is only "latest wins" when nothing says the
    -- incoming row is older than the tyre already on the wheel.
    if v_prev_date = p_fit_date then
      if v_serial is not null and exists (
        select 1 from public.tyre_records t
        where t.organisation_id is not distinct from p_org and coalesce(t.country, '') = coalesce(p_country, '')
          and upper(regexp_replace(coalesce(t.asset_no, t.asset_number, ''), '\s+', '', 'g')) = v_asset
          and upper(btrim(coalesce(t.tyre_position, t.position, ''))) = v_pos
          and upper(btrim(coalesce(t.serial_no, ''))) = v_serial
          and not public.tyre_status_is_active(t.status)) then
        return jsonb_build_object('status', 'ambiguous_same_day_stale', 'reason', 'serial_already_removed_from_wheel', 'tyre_id', v_prev.id);
      end if;
      if v_serial is not null and exists (
        select 1 from public.tyre_replacement_log l
        where l.organisation_id is not distinct from p_org and coalesce(l.country, '') = coalesce(p_country, '')
          and upper(regexp_replace(coalesce(l.asset_no, ''), '\s+', '', 'g')) = v_asset
          and l.position = v_pos and l.undone_at is null
          and upper(btrim(coalesce(l.old_serial, ''))) = v_serial
          and upper(btrim(coalesce(l.new_serial, ''))) = upper(btrim(coalesce(v_prev.serial_no, '')))) then
        return jsonb_build_object('status', 'ambiguous_same_day_stale', 'reason', 'logged_as_replaced_by_current', 'tyre_id', v_prev.id);
      end if;
      if (p_fit_km > 1 and v_prev.km_at_fitment > 1 and p_fit_km < v_prev.km_at_fitment)
         or (p_fit_hrs > 0 and v_prev.hrs_at_fitment > 0 and p_fit_hrs < v_prev.hrs_at_fitment) then
        return jsonb_build_object('status', 'ambiguous_same_day_stale', 'reason', 'meter_below_current_fitment', 'tyre_id', v_prev.id);
      end if;
    end if;
    select count(*) into v_later from public.tyre_records t
    where t.organisation_id is not distinct from p_org and coalesce(t.country, '') = coalesce(p_country, '')
      and upper(regexp_replace(coalesce(t.asset_no, t.asset_number, ''), '\s+', '', 'g')) = v_asset
      and upper(btrim(coalesce(t.tyre_position, t.position, ''))) = v_pos
      and t.id <> v_prev.id and coalesce(t.issue_date, t.fitment_date) > p_fit_date;
    if v_later > 0 then return jsonb_build_object('status', 'ambiguous_backdated', 'tyre_id', v_prev.id); end if;
  end if;
  v_rem_date := greatest(p_fit_date, coalesce(v_prev_date, p_fit_date));
  if p_fit_km is not null and p_fit_km > 1 and (v_prev.km_at_fitment is null or p_fit_km >= v_prev.km_at_fitment) then
    v_rem_km := p_fit_km; end if;
  if p_fit_hrs is not null and p_fit_hrs > 0 and (v_prev.hrs_at_fitment is null or p_fit_hrs >= v_prev.hrs_at_fitment) then
    v_rem_hrs := p_fit_hrs; end if;
  v_total_km := public.tyre_km_life(v_prev.km_at_fitment, v_rem_km, null, v_prev.vehicle_type);
  if v_rem_hrs is not null and v_prev.hrs_at_fitment is not null then v_total_hrs := v_rem_hrs - v_prev.hrs_at_fitment; end if;
  v_new := jsonb_strip_nulls(jsonb_build_object('removal_date', v_rem_date, 'km_at_removal', v_rem_km,
    'hrs_at_removal', v_rem_hrs, 'total_km', v_total_km, 'total_hrs', v_total_hrs, 'status', 'Removed'));
  if p_dry_run then
    return jsonb_build_object('status', 'would_close', 'tyre_id', v_prev.id, 'old_serial', v_prev.serial_no, 'removal', v_new);
  end if;
  insert into public.tyre_replacement_log (organisation_id, batch_id, tyre_id, country, asset_no, position, old_serial, new_serial, replaced_on, old_values, new_values, source)
  values (p_org, p_batch, v_prev.id, v_prev.country, v_prev.asset_no, v_pos, v_prev.serial_no, p_serial, v_rem_date,
    jsonb_build_object('removal_date', v_prev.removal_date, 'km_at_removal', v_prev.km_at_removal, 'hrs_at_removal', v_prev.hrs_at_removal,
      'total_km', v_prev.total_km, 'total_hrs', v_prev.total_hrs, 'status', v_prev.status, 'extra_fields', v_prev.extra_fields),
    v_new, p_source);
  update public.tyre_records t set removal_date = v_rem_date, km_at_removal = coalesce(v_rem_km, t.km_at_removal),
    hrs_at_removal = coalesce(v_rem_hrs, t.hrs_at_removal), total_km = coalesce(t.total_km, v_total_km),
    total_hrs = coalesce(t.total_hrs, v_total_hrs), status = 'Removed',
    extra_fields = coalesce(t.extra_fields, '{}'::jsonb) || jsonb_build_object('replaced_by_serial', p_serial, 'replaced_on', v_rem_date, 'replacement_source', p_source, 'replacement_batch', p_batch)
  where t.id = v_prev.id;
  return jsonb_build_object('status', 'closed', 'tyre_id', v_prev.id, 'old_serial', v_prev.serial_no);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tyre_close_serial_elsewhere(p_org uuid, p_country text, p_asset text, p_serial text, p_fit_date date, p_source text, p_batch uuid, p_dry_run boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_asset text := nullif(upper(regexp_replace(coalesce(p_asset, ''), '\s+', '', 'g')), '');
  r public.tyre_records%rowtype; v_n int := 0;
begin
  if p_fit_date is null or v_asset is null or not public.tyre_serial_is_strong(p_serial) then return 0; end if;
  for r in
    select t.* from public.tyre_records t
    where t.organisation_id is not distinct from p_org and coalesce(t.country, '') = coalesce(p_country, '')
      and upper(btrim(t.serial_no)) = upper(btrim(p_serial))
      and upper(regexp_replace(coalesce(t.asset_no, t.asset_number, ''), '\s+', '', 'g')) <> v_asset
      and public.tyre_status_is_active(t.status)
      and coalesce(t.issue_date, t.fitment_date, p_fit_date) <= p_fit_date
    for update
  loop
    v_n := v_n + 1;
    if p_dry_run then continue; end if;
    insert into public.tyre_replacement_log (organisation_id, batch_id, tyre_id, country, asset_no, position, old_serial, new_serial, replaced_on, old_values, new_values, source)
    values (p_org, p_batch, r.id, r.country, r.asset_no, upper(btrim(coalesce(r.tyre_position, r.position, ''))), r.serial_no, p_serial, p_fit_date,
      jsonb_build_object('removal_date', r.removal_date, 'km_at_removal', r.km_at_removal, 'hrs_at_removal', r.hrs_at_removal,
        'total_km', r.total_km, 'total_hrs', r.total_hrs, 'status', r.status, 'extra_fields', r.extra_fields),
      jsonb_build_object('removal_date', p_fit_date, 'status', 'Removed', 'moved_to_asset', p_asset), p_source);
    update public.tyre_records t set removal_date = p_fit_date, status = 'Removed',
      extra_fields = coalesce(t.extra_fields, '{}'::jsonb) || jsonb_build_object('moved_to_asset', p_asset,
        'replaced_on', p_fit_date, 'replacement_source', p_source, 'replacement_batch', p_batch)
    where t.id = r.id;
  end loop;
  return v_n;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._tyre_exception_rows(p_country text DEFAULT NULL::text, p_kind text DEFAULT NULL::text)
 RETURNS TABLE(exception_key text, kind text, country text, record_ids uuid[], serial text, asset text, tyre_position text, reason text, proposed text, impact_km numeric, impact_cost numeric, detail jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
with t as (
  select r.id, r.organisation_id, r.country, r.asset_no, upper(regexp_replace(coalesce(r.asset_no, ''), '\s+', '', 'g')) as asset,
         upper(btrim(coalesce(r.tyre_position, r.position, ''))) as pos, r.serial_no, upper(btrim(r.serial_no)) as serial,
         public.tyre_serial_is_strong(r.serial_no) as strong, public.tyre_status_is_active(r.status) as active,
         r.status, r.site, r.size, r.vehicle_type, coalesce(r.issue_date, r.fitment_date) as fit_date, r.removal_date,
         r.km_at_fitment, r.km_at_removal, r.total_km, r.hrs_at_fitment, r.hrs_at_removal, r.cost_per_tyre, r.created_at
  from public.tyre_records r
  where (p_country is null or r.country = p_country)
),
invalid_serial as (
  select 'invalid_serial|' || t.id, 'invalid_serial', t.country, array[t.id], t.serial_no, t.asset_no, t.pos,
    case when t.serial is null or t.serial = '' then 'Active fitment with no serial'
         when t.strong then 'A remark is typed into the serial cell'
         else 'Active fitment whose serial is not a real tyre serial (rule T6)' end,
    case when t.strong then 'Move the remark to notes and keep only the serial'
         else 'Read the serial from the tyre sidewall and correct this record' end,
    null::numeric, nullif(t.cost_per_tyre, 0),
    jsonb_build_object('status', t.status, 'fitted', t.fit_date)
  from t where t.active and (not t.strong or t.serial ~ '[\s(]') and (p_kind is null or p_kind = 'invalid_serial')
),
dup as (
  select t.country, t.serial, array_agg(t.id order by t.fit_date nulls first, t.id) ids,
         count(distinct t.asset) assets, count(distinct t.fit_date) dates, max(t.serial_no) serial_no,
         jsonb_agg(jsonb_build_object('id', t.id, 'asset', t.asset_no, 'position', t.pos, 'fitted', t.fit_date) order by t.fit_date nulls first) rows
  from t where t.active and t.strong and (p_kind is null or p_kind = 'duplicate_active')
  group by t.country, t.serial having count(*) > 1
),
duplicate_active as (
  select 'duplicate_active|' || upper(btrim(coalesce(d.country, ''))) || '|' || d.serial, 'duplicate_active', d.country, d.ids,
    d.serial_no, (select string_agg(distinct x->>'asset', ' / ') from jsonb_array_elements(d.rows) x), null::text,
    case when d.assets > 1 then 'One tyre is active on ' || d.assets || ' vehicles at once'
         else 'One tyre is active on two wheels of one vehicle on the same day' end,
    'Check the vehicles and close the fitment the tyre is no longer on (one tyre, one wheel, rule T3/T5)',
    null::numeric, null::numeric, jsonb_build_object('rows', d.rows)
  from dup d where d.assets > 1 or d.dates <= 1
),
missing_readings as (
  select 'missing_readings|' || t.id, 'missing_readings', t.country, array[t.id], t.serial_no, t.asset_no, t.pos,
    case when t.km_at_fitment is null and t.hrs_at_fitment is null and (t.removal_date is not null and t.km_at_removal is null and t.hrs_at_removal is null)
           then 'No odometer or hour reading at fitment or at removal'
         when t.km_at_fitment is null and t.hrs_at_fitment is null then 'No odometer or hour reading at fitment'
         else 'Removed, but no odometer or hour reading at removal' end,
    'Take the reading from the job card of that day and enter it',
    null::numeric, null::numeric, jsonb_build_object('fitted', t.fit_date, 'removed', t.removal_date, 'total_km', t.total_km)
  from t
  where (p_kind is null or p_kind = 'missing_readings') and coalesce(t.total_km, 0) <= 0
    and ((t.km_at_fitment is null and t.hrs_at_fitment is null)
      or (t.removal_date is not null and t.km_at_removal is null and t.hrs_at_removal is null))
),
invalid_reading as (
  select 'invalid_reading|' || t.id, 'invalid_reading', t.country, array[t.id], t.serial_no, t.asset_no, t.pos,
    case when t.km_at_fitment = 1 then 'Fitment odometer is the placeholder 1, so km is unknown (rule T7)'
         when t.km_at_removal > 0 and t.km_at_fitment > 1 and t.km_at_removal < t.km_at_fitment then 'Odometer at removal is below the odometer at fitment'
         when t.hrs_at_removal > 0 and t.hrs_at_fitment > 0 and t.hrs_at_removal < t.hrs_at_fitment then 'Hour meter at removal is below the hour meter at fitment'
         else 'Tyre life above the class limit of ' || public.tyre_life_km_cap(t.vehicle_type) || ' km (rule T7)' end,
    case when t.km_at_fitment = 1 then 'Enter the real odometer at fitment from the job card'
         when t.km_at_removal > 0 and t.km_at_fitment > 1 and t.km_at_removal < t.km_at_fitment then 'Check whether the two readings were swapped or the meter was replaced'
         when t.hrs_at_removal > 0 and t.hrs_at_fitment > 0 and t.hrs_at_removal < t.hrs_at_fitment then 'Check whether the two readings were swapped or the meter was replaced'
         else 'Check the fitment and removal odometer; the km stays unknown until corrected' end,
    case when t.km_at_removal > 0 and t.km_at_fitment > 1 and t.km_at_removal > t.km_at_fitment then t.km_at_removal - t.km_at_fitment
         when coalesce(t.total_km, 0) > 0 then t.total_km end,
    null::numeric,
    jsonb_build_object('km_at_fitment', t.km_at_fitment, 'km_at_removal', t.km_at_removal, 'total_km', t.total_km,
      'hrs_at_fitment', t.hrs_at_fitment, 'hrs_at_removal', t.hrs_at_removal, 'vehicle_type', t.vehicle_type)
  from t
  where (p_kind is null or p_kind = 'invalid_reading') and (t.km_at_fitment = 1
     or (t.km_at_removal > 0 and t.km_at_fitment > 1 and t.km_at_removal < t.km_at_fitment)
     or (t.hrs_at_removal > 0 and t.hrs_at_fitment > 0 and t.hrs_at_removal < t.hrs_at_fitment)
     or (public.tyre_km_life(t.km_at_fitment, t.km_at_removal, t.total_km, t.vehicle_type) is null
         and (case when t.km_at_fitment > 1 and t.km_at_removal > t.km_at_fitment then t.km_at_removal - t.km_at_fitment
                   when coalesce(t.km_at_fitment, 0) <> 1 and t.total_km > 0 then t.total_km end) > public.tyre_life_km_cap(t.vehicle_type)))
),
reset as (
  select x.* from (
    select t.*, max(t.km_at_fitment) filter (where t.km_at_fitment > 1)
             over (partition by t.organisation_id, t.country, t.asset order by t.fit_date, t.id rows between unbounded preceding and 1 preceding) as prev_max
    from t where t.fit_date is not null and (p_kind is null or p_kind = 'invalid_reading')
  ) x where x.km_at_fitment > 1 and x.prev_max is not null and x.km_at_fitment < x.prev_max - 1000
),
meter_reset as (
  select 'invalid_reading|reset|' || r.id, 'invalid_reading', r.country, array[r.id], r.serial_no, r.asset_no, r.pos,
    'Odometer at fitment (' || r.km_at_fitment || ') is below an earlier fitment on this vehicle (' || r.prev_max || '): meter reset or typing error',
    'Confirm whether the vehicle meter was replaced; if not, correct the reading',
    null::numeric, null::numeric, jsonb_build_object('km_at_fitment', r.km_at_fitment, 'earlier_max_km', r.prev_max, 'fitted', r.fit_date)
  from reset r
),
missing_site as (
  select 'missing_site|' || t.id, 'missing_site', t.country, array[t.id], t.serial_no, t.asset_no, t.pos,
    'Fitment has no site, so it cannot be counted in any site report',
    'Use the vehicle''s registered site on the fitment date (proposal only)',
    null::numeric, nullif(t.cost_per_tyre, 0), jsonb_build_object('vehicle_site_now', fl.site, 'fitted', t.fit_date)
  from t
  left join (
    select distinct on (f.country, upper(regexp_replace(coalesce(f.asset_no, ''), '\s+', '', 'g')))
           f.country, upper(regexp_replace(coalesce(f.asset_no, ''), '\s+', '', 'g')) as asset, f.site
    from public.vehicle_fleet f
    where (p_kind is null or p_kind = 'missing_site') and nullif(btrim(f.site), '') is not null
    order by f.country, upper(regexp_replace(coalesce(f.asset_no, ''), '\s+', '', 'g')), f.updated_at desc nulls last
  ) fl on coalesce(fl.country, '') = coalesce(t.country, '') and fl.asset = t.asset
  where (p_kind is null or p_kind = 'missing_site') and (t.site is null or btrim(t.site) = '')
),
nxt as (
  select t.*, lead(t.fit_date) over (partition by t.organisation_id, t.country, t.asset, t.pos order by t.fit_date nulls first, t.id) next_fit,
              lead(t.id) over (partition by t.organisation_id, t.country, t.asset, t.pos order by t.fit_date nulls first, t.id) next_id
  from t where t.pos <> '' and t.asset <> '' and (p_kind is null or p_kind = 'conflicting_dates')
),
conflicting_dates as (
  select 'conflicting_dates|' || n.id, 'conflicting_dates', n.country,
    case when n.next_id is not null and n.removal_date > n.next_fit then array[n.id, n.next_id] else array[n.id] end,
    n.serial_no, n.asset_no, n.pos,
    case when n.removal_date < n.fit_date then 'Removal date is before the fitment date'
         when n.fit_date > current_date then 'Fitment date is in the future'
         when n.removal_date > current_date then 'Removal date is in the future'
         else 'Removed on ' || n.removal_date || ' but the next tyre on this wheel was fitted on ' || n.next_fit end,
    case when n.removal_date < n.fit_date then 'Check the job card; the two dates are probably swapped (rule T12)'
         when n.fit_date > current_date or n.removal_date > current_date then 'Correct the date from the job card'
         else 'Set the removal date to the next fitment date if the job card agrees' end,
    null::numeric, null::numeric, jsonb_build_object('fitted', n.fit_date, 'removed', n.removal_date, 'next_fitted', n.next_fit)
  from nxt n
  where n.removal_date < n.fit_date or n.fit_date > current_date or n.removal_date > current_date
     or (n.next_fit is not null and n.removal_date is not null and n.removal_date > n.next_fit)
),
overlapping_fitment as (
  select 'overlapping_fitment|' || o.id, 'overlapping_fitment', o.country, array[o.id], o.serial_no, o.asset_no, o.position,
    'Fitment starts on ' || o.fit_date || ' before an earlier fitment of the same tyre ended (rule T18)',
    'Close the earlier fitment, or remove the duplicate row if the meters are identical',
    public.tyre_km_life(o.km_at_fitment, o.km_at_removal, o.total_km, o.vehicle_type), null::numeric,
    jsonb_build_object('fitted', o.fit_date, 'earlier_fitment_ends', case when o.prev_end = 'infinity'::date then null else o.prev_end end,
      'earlier_still_open', o.prev_end = 'infinity'::date)
  from public.v_tyre_lifetime_fitments o
  where (p_kind is null or p_kind = 'overlapping_fitment') and o.is_overlap and (p_country is null or o.country = p_country)
),
lifetime_missing as materialized (
  select l.country, l.serial_no, l.latest_id, l.asset_no, l.km_known, l.fitments, l.first_fit_date, l.size
  from public.v_tyre_lifetime l
  where l.strong and l.purchase_cost_status = 'MISSING'
),
price_missing as (
  select 'price_missing|' || upper(btrim(coalesce(l.country, ''))) || '|' || upper(btrim(l.serial_no)), 'price_missing', l.country,
    array[l.latest_id], l.serial_no, l.asset_no, null::text,
    'Physical tyre has no purchase price on any fitment',
    'Find the purchase on the expense grid by job card and record it (never estimate without saying so)',
    l.km_known, null::numeric, jsonb_build_object('fitments', l.fitments, 'first_fitted', l.first_fit_date, 'size', l.size)
  from lifetime_missing l
  where (p_kind is null or p_kind = 'price_missing') and (p_country is null or l.country = p_country)
),
priced as (
  select t.country, t.serial, max(t.serial_no) serial_no, array_agg(t.id order by t.created_at, t.id) ids,
         sum(t.cost_per_tyre) total, (array_agg(t.cost_per_tyre order by t.fit_date nulls last, t.created_at))[1] first_cost,
         jsonb_agg(jsonb_build_object('id', t.id, 'asset', t.asset_no, 'fitted', t.fit_date, 'cost', t.cost_per_tyre, 'uploaded', t.created_at)
                   order by t.created_at) rows
  from t where t.strong and coalesce(t.cost_per_tyre, 0) > 0 and (p_kind is null or p_kind = 'price_assigned_twice')
  group by t.country, t.serial having count(*) > 1
),
price_assigned_twice as (
  select 'price_assigned_twice|' || upper(btrim(coalesce(p.country, ''))) || '|' || p.serial, 'price_assigned_twice', p.country, p.ids,
    p.serial_no, (select string_agg(distinct x->>'asset', ' / ') from jsonb_array_elements(p.rows) x), null::text,
    'One physical tyre carries ' || jsonb_array_length(p.rows) || ' purchase prices (rule T1)',
    'Keep the price on the latest uploaded row (rule T2) unless the job cards show two real purchases',
    null::numeric, p.total - p.first_cost, jsonb_build_object('rows', p.rows)
  from priced p
),
size_price as (
  select t.country, upper(regexp_replace(coalesce(t.size, ''), '\s+', '', 'g')) sz,
         percentile_cont(0.5) within group (order by t.cost_per_tyre)::numeric med, count(*) n
  from t where coalesce(t.cost_per_tyre, 0) > 0 and coalesce(t.size, '') <> '' and (p_kind is null or p_kind = 'price_incorrect')
  group by 1, 2 having count(*) >= 5
),
price_incorrect as (
  select 'price_incorrect|' || t.id, 'price_incorrect', t.country, array[t.id], t.serial_no, t.asset_no, t.pos,
    'Price ' || t.cost_per_tyre || ' is more than 3 times away from the usual ' || round(s.med, 2) || ' for size ' || t.size,
    'Check the invoice; correct the price if it was typed wrong or is a line total',
    null::numeric, round(t.cost_per_tyre - s.med, 2), jsonb_build_object('price', t.cost_per_tyre, 'usual_price', round(s.med, 2), 'size', t.size, 'samples', s.n)
  from t join size_price s on coalesce(s.country, '') = coalesce(t.country, '') and s.sz = upper(regexp_replace(coalesce(t.size, ''), '\s+', '', 'g'))
  where t.cost_per_tyre > 0 and (t.cost_per_tyre > s.med * 3 or t.cost_per_tyre < s.med / 3)
),
pairs as (
  select o.country, o.id old_id, n.id new_id, o.serial_no, o.asset_no, o.pos, o.removal_date, o.km_at_removal, o.cost_per_tyre oc, n.cost_per_tyre nc
  from t o join t n
    on coalesce(n.organisation_id::text, '') = coalesce(o.organisation_id::text, '') and coalesce(n.country, '') = coalesce(o.country, '')
   and n.serial = o.serial and n.asset_no = o.asset_no and n.pos = o.pos
   and o.removal_date = n.fit_date and o.km_at_removal = n.km_at_fitment and o.id <> n.id
  where o.serial is not null and o.serial <> '' and (p_kind is null or p_kind = 'uncertain_previous_tyre')
),
fix_handled as materialized (
  select r.exception_key from public.tyre_exception_refs r
  where r.ref_kind = 'fix_handled' and (p_kind is null or p_kind = 'uncertain_previous_tyre')
),
uncertain_previous_tyre as (
  select 'uncertain_previous_tyre|' || p.old_id || '|' || p.new_id, 'uncertain_previous_tyre', p.country, array[p.old_id, p.new_id],
    p.serial_no, p.asset_no, p.pos,
    'The same serial is recorded both as the tyre removed and the tyre fitted on ' || p.removal_date || ' at ' || p.km_at_removal || ' km',
    'Read the old serial from the job card; put it on the removed row and keep the price on the tyre that was bought',
    null::numeric, coalesce(nullif(p.oc, 0), nullif(p.nc, 0)),
    jsonb_build_object('removed_row', p.old_id, 'fitted_row', p.new_id, 'removed_row_price', p.oc, 'fitted_row_price', p.nc)
  from pairs p
  left join fix_handled fh on fh.exception_key = 'uncertain_previous_tyre|' || p.old_id || '|' || p.new_id
  where fh.exception_key is null
),
unlinked_repair_retread as (
  select 'unlinked_repair_retread|' || e.id, 'unlinked_repair_retread', e.country, array[e.id], null::text, e.asset_code, null::text,
    'Tyre repair or retread line with no tyre serial, so it is not in any tyre''s lifetime cost',
    'Link it to the tyre named on job card ' || coalesce(e.work_order_no, '(none)') || ' if the job card names one',
    null::numeric, e.tyre_cost, jsonb_build_object('job_card', e.work_order_no, 'item', e.item_description, 'date', e.event_date, 'currency', e.currency)
  from public.parts_consumption e
  where (p_kind is null or p_kind = 'unlinked_repair_retread') and coalesce(e.tyre_cost, 0) > 0 and e.item_description ~* '(repair|retread|re-tread|resol|vulcan)'
    and (p_country is null or e.country = p_country)
),
dup_exp as (
  select e.country, array_agg(e.id order by e.created_at, e.id) ids, count(*) n, max(e.line_cost) lc,
         max(e.work_order_no) wo, max(e.item_description) item, max(e.asset_code) asset, max(e.event_date) d, max(e.currency) cur
  from public.parts_consumption e
  where (p_kind is null or p_kind = 'duplicate_expense') and (p_country is null or e.country = p_country) and coalesce(e.tyre_cost, 0) > 0
  group by e.organisation_id, e.country, e.issue_number, e.work_order_no, e.item_code, e.item_description, e.qty, e.value_amount,
           e.txn_date, e.store_code, e.cost_center, e.asset_code
  having count(*) > 1 and count(distinct e.source_row) <= 1
),
duplicate_expense as (
  select 'duplicate_expense|' || d.ids[1] || '|' || d.n, 'duplicate_expense', d.country, d.ids, null::text, d.asset, null::text,
    'The same tyre expense line is recorded ' || d.n || ' times (rule T11)',
    'Keep one line and archive the copies in Duplicate Control',
    null::numeric, round((d.n - 1) * d.lc, 2), jsonb_build_object('job_card', d.wo, 'item', d.item, 'date', d.d, 'currency', d.cur)
  from dup_exp d
)
select * from invalid_serial
union all select * from duplicate_active
union all select * from missing_readings
union all select * from invalid_reading
union all select * from meter_reset
union all select * from missing_site
union all select * from conflicting_dates
union all select * from overlapping_fitment
union all select * from price_missing
union all select * from price_assigned_twice
union all select * from price_incorrect
union all select * from uncertain_previous_tyre
union all select * from unlinked_repair_retread
union all select * from duplicate_expense
$function$;
-- @@
CREATE OR REPLACE FUNCTION public._upload_coverage_detail_for_org(p_org uuid, p_days integer DEFAULT 30, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n    int := least(greatest(coalesce(p_days, 30), 7), 365);
  v_base int := greatest(180, v_n);
  v_raw  text;
  v_sql  text;
  v_out  jsonb;
begin
  if p_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  select string_agg(
           format(
             'select %L::text as src, t.country, %s as site, (t.%I)::date as d, count(*)::bigint as rows'
             || ' from public.%I t'
             || ' where t.organisation_id = $1'
             || '   and t.country is not null and ($4::text is null or t.country = $4::text)'
             || coalesce(nullif(public._upload_feed_window_sql(f.table_name, f.date_column, '$2'), ''),
                  format(' and t.%I is not null and (t.%I)::date > current_date - $2 and (t.%I)::date <= current_date',
                         f.date_column, f.date_column, f.date_column))
             || ' group by 1,2,3,4',
             f.src,
             case when f.site_column is null
                  then '''Not stated''::text'
                  else format('coalesce(nullif(btrim(t.%I), ''''), ''Not stated'')', f.site_column)
             end,
             f.date_column, f.table_name
           ),
           ' union all '
           order by f.sort_order, f.src)
    into v_raw
    from public.upload_feeds f
   where f.active;
  if v_raw is null then
    return jsonb_build_object(
      'ok', true, 'generated_at', now(), 'today', current_date,
      'days', v_n, 'baseline_days', v_base, 'country', p_country,
      'countries', '[]'::jsonb, 'files', '[]'::jsonb, 'no_feeds', true);
  end if;
  v_sql :=
  'with days as (
     select generate_series(current_date - $3 + 1, current_date, interval ''1 day'')::date as d
   ),
   base as materialized (
     select * from (' || v_raw || ') raw where country is not null and ($4::text is null or country = $4::text)
   ),
   scoped as materialized (
     select * from base where d > current_date - $3
   ),
   srcs as (
     select f.src, f.label, f.table_name as tbl, f.sort_order as ord,
            f.date_basis, f.site_day_policed
       from public.upload_feeds f where f.active
   ),
   pairs as materialized (select distinct country, src from base),
   base_days as materialized (
     select distinct country, src, d from base where d < current_date
   ),
   base_gaps as (
     select country, src, d, d - lag(d) over (partition by country, src order by d) as gap
       from base_days
   ),
   gap_p90 as (
     select country, src, percentile_disc(0.9) within group (order by gap) as p90
       from base_gaps where gap is not null group by 1,2
   ),
   cadence as (
     select bd.country, bd.src,
            count(*) as base_data_days,
            (current_date - 1) - min(bd.d) + 1 as base_elapsed,
            max(bd.d) as last_data_date
       from base_days bd group by 1,2
   ),
   cadence2 as (
     select c.*,
            coalesce(g.p90, 1) as typical_gap,
            (c.base_elapsed > 0 and c.base_data_days::numeric / c.base_elapsed >= 0.5) as expect_daily,
            current_date - c.last_data_date as days_since_last
       from cadence c
       left join gap_p90 g on g.country = c.country and g.src = c.src
   ),
   cadence3 as materialized (
     select c.country, c.src, c.base_data_days, c.base_elapsed, c.last_data_date, c.typical_gap,
            c.expect_daily, c.days_since_last,
            public._coverage_quiet(c.expect_daily, c.days_since_last, c.typical_gap) as quiet
       from cadence2 c
   ),
   scoped_day as (
     select country, src, d, sum(rows) as rows,
            count(distinct site) filter (where rows > 0) as sites
       from scoped group by 1,2,3
   ),
   cs_day as materialized (
     select p.country, p.src, d.d, coalesce(s.rows, 0) as rows, coalesce(s.sites, 0) as sites
       from pairs p cross join days d
       left join scoped_day s on s.country = p.country and s.src = p.src and s.d = d.d
   ),
   cs_weekday_rate as materialized (
     select p.country, p.src, extract(isodow from g.d)::int as dow,
            count(*) filter (where b.d is not null)::numeric / nullif(count(*), 0) as hit_rate
       from pairs p
       cross join (select generate_series(current_date - $2 + 1, current_date - 1, interval ''1 day'')::date d) g
       left join base_days b on b.country = p.country and b.src = p.src and b.d = g.d
      group by 1,2,3
   ),
   cs_stats as (
     select c.country, c.src,
            count(*) filter (where c.rows > 0 and c.d < current_date) as days_with_data,
            count(*) filter (where c.d < current_date)                as days_elapsed,
            sum(c.rows)                                               as total_rows
       from cs_day c group by 1,2
   ),
   cs_gaps as materialized (
     select c.country, c.src, c.d
       from cs_day c
       join cadence3 e on e.country = c.country and e.src = c.src
       join cs_weekday_rate w on w.country = c.country and w.src = c.src
                             and w.dow = extract(isodow from c.d)::int
      where e.expect_daily and c.rows = 0 and c.d < current_date
        and coalesce(w.hit_rate, 0) >= 0.3
   ),
   cs_gap_agg as (
     select country, src, count(*) as n, jsonb_agg(d order by d desc) as days
       from cs_gaps group by 1,2
   ),
   cs_day_agg as (
     select country, src,
            jsonb_agg(jsonb_build_object(''d'', d, ''rows'', rows, ''sites'', sites) order by d) as by_day
       from cs_day group by 1,2
   ),
   site_stats as (
     select s.country, s.src, s.site,
            sum(s.rows) as rows,
            count(distinct s.d) filter (where s.d < current_date) as days_with_data,
            min(s.d) as first_data_date,
            max(s.d) as last_data_date,
            max(s.d) filter (where s.d > current_date - greatest($3 / 2, 3)) is not null as active_recently
       from scoped s group by 1,2,3
   ),
   site_daily as materialized (
     select ss.*,
            (coalesce((select sd.site_day_policed from srcs sd where sd.src = ss.src), false)
             and ss.days_with_data >= 5
             and ss.days_with_data::numeric
                 / nullif(greatest(least(current_date - 1, ss.last_data_date) - ss.first_data_date + 1, 1), 0) >= 0.5
            ) as expect_daily_site
       from site_stats ss
   ),
   site_gaps as (
     select ss.country, ss.src, ss.site, c.d
       from site_daily ss
       join cs_day c on c.country = ss.country and c.src = ss.src
       join cadence3 e on e.country = ss.country and e.src = ss.src
      where e.expect_daily and ss.active_recently and ss.expect_daily_site
        and c.rows > 0 and c.d < current_date
        and c.d between ss.first_data_date and ss.last_data_date
        and (ss.country, ss.src, ss.site, c.d) not in (select x.country, x.src, x.site, x.d from scoped x)
   ),
   site_gap_agg as (
     select country, src, site, count(*) as n, jsonb_agg(d order by d desc) as days
       from site_gaps group by 1,2,3
   ),
   site_json as (
     select ss.country, ss.src,
            jsonb_agg(jsonb_build_object(
                ''site'', ss.site, ''rows'', ss.rows,
                ''days_with_data'', ss.days_with_data,
                ''last_data_date'', ss.last_data_date,
                ''days_since_last'', current_date - ss.last_data_date,
                ''dormant'', not ss.active_recently,
                ''occasional'', not ss.expect_daily_site,
                ''missing_count'', coalesce(sg.n, 0),
                ''missing_days'', coalesce(sg.days, ''[]''::jsonb))
              order by coalesce(sg.n, 0) desc, ss.rows desc, ss.site) as sites
       from site_daily ss
       left join site_gap_agg sg on sg.country = ss.country and sg.src = ss.src and sg.site = ss.site
      group by 1,2
   ),
   country_gaps as (
     select country, count(*) as n from cs_gaps group by 1
   )
   select jsonb_build_object(
     ''ok'', true, ''generated_at'', now(), ''today'', current_date,
     ''days'', $3, ''baseline_days'', $2, ''country'', $4,
     ''watched_feeds'', (select count(*) from srcs),
     ''countries'', coalesce((
       select jsonb_agg(jsonb_build_object(
         ''country'', q.country,
         ''total_rows'', q.total_rows,
         ''missing_count'', q.missing_count,
         ''quiet_count'', q.quiet_count,
         ''watched_sources'', q.watched_sources,
         ''sources'', q.sources) order by q.missing_count + q.quiet_count desc, q.country)
       from (
         select e.country,
                sum(coalesce(st.total_rows, 0)) as total_rows,
                coalesce(max(cg.n), 0) as missing_count,
                count(*) filter (where e.quiet) as quiet_count,
                count(*) filter (where e.expect_daily) as watched_sources,
                jsonb_agg(jsonb_build_object(
                  ''src'', e.src,
                  ''label'', sr.label,
                  ''table'', sr.tbl,
                  ''date_basis'', sr.date_basis,
                  ''expect_daily'', e.expect_daily,
                  ''typical_gap_days'', e.typical_gap,
                  ''quiet'', e.quiet,
                  ''base_data_days'', e.base_data_days,
                  ''days_with_data'', coalesce(st.days_with_data, 0),
                  ''days_elapsed'', coalesce(st.days_elapsed, 0),
                  ''total_rows'', coalesce(st.total_rows, 0),
                  ''last_data_date'', e.last_data_date,
                  ''days_since_last'', e.days_since_last,
                  ''missing_count'', coalesce(ga.n, 0),
                  ''missing_days'', coalesce(ga.days, ''[]''::jsonb),
                  ''by_day'', coalesce(da.by_day, ''[]''::jsonb),
                  ''sites'', coalesce(sj.sites, ''[]''::jsonb)
                ) order by sr.ord) as sources
           from cadence3 e
           left join srcs sr on sr.src = e.src
           left join cs_stats st on st.country = e.country and st.src = e.src
           left join cs_gap_agg ga on ga.country = e.country and ga.src = e.src
           left join cs_day_agg da on da.country = e.country and da.src = e.src
           left join site_json sj on sj.country = e.country and sj.src = e.src
           left join country_gaps cg on cg.country = e.country
          group by e.country
       ) q), ''[]''::jsonb),
     ''files'', coalesce((
       select jsonb_agg(jsonb_build_object(
         ''filename'', f.original_filename, ''country'', f.country,
         ''uploaded_at'', f.created_at, ''size_bytes'', f.size_bytes,
         ''source_system'', f.source_system) order by f.created_at desc)
         from public.import_files f
        where f.organisation_id = $1
          and f.created_at >= current_date - $3
          and ($4::text is null or f.country = $4::text)), ''[]''::jsonb)
   )';
  execute v_sql into v_out using p_org, v_base, v_n, p_country;
  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._upload_coverage_for_org(p_org uuid, p_days integer DEFAULT 30, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n   int := least(greatest(coalesce(p_days, 30), 7), 180);
  v_raw text;
  v_sql text;
  v_out jsonb;
begin
  if p_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;

  select string_agg(
           format(
             'select %L::text as src, (t.%I)::date as d, count(*)::bigint as rows'
             || ' from public.%I t'
             || ' where t.organisation_id = $1'
             || '   and ($3 is null or t.country = $3)'
             || coalesce(nullif(public._upload_feed_window_sql(f.table_name, f.date_column, '$2'), ''),
                  format(' and t.%I is not null and (t.%I)::date > current_date - $2 and (t.%I)::date <= current_date',
                         f.date_column, f.date_column, f.date_column))
             || ' group by 1,2',
             f.src, f.date_column, f.table_name
           ),
           ' union all ' order by f.sort_order, f.src)
    into v_raw
    from public.upload_feeds f
   where f.active;

  if v_raw is null then
    return jsonb_build_object('ok', true, 'generated_at', now(), 'today', current_date,
      'days', v_n, 'country', p_country,
      'sources', '[]'::jsonb, 'alerts', '[]'::jsonb, 'no_feeds', true);
  end if;

  v_sql :=
  'with days as (
     select generate_series(current_date - $2 + 1, current_date, interval ''1 day'')::date as d
   ), raw as (' || v_raw || '
   ), srcs as (
     select f.src, f.label, f.table_name as tbl, f.sort_order as ord
       from public.upload_feeds f where f.active
   ), grid as (
     select s.src, s.label, s.tbl, s.ord, d.d, coalesce(r.rows, 0) as rows
       from srcs s cross join days d
       left join raw r on r.src = s.src and r.d = d.d
   ), weekday_activity as (
     select src, extract(isodow from d)::int as dow,
            count(*) filter (where rows > 0)::numeric / nullif(count(*), 0) as hit_rate
       from grid where d < current_date group by 1, 2
   ), src_stats as (
     select g.src, g.label, g.tbl, g.ord,
            count(*) filter (where g.rows > 0 and g.d < current_date) as days_with_data,
            count(*) filter (where g.d < current_date)                as days_elapsed,
            max(g.d) filter (where g.rows > 0)                        as last_data_date,
            sum(g.rows)                                               as total_rows
       from grid g group by 1,2,3,4
   ), expectation as (
     select st.*, (st.days_elapsed > 0
              and st.days_with_data::numeric / st.days_elapsed >= 0.5) as expect_daily
       from src_stats st
   ), gaps as (
     select g.src, g.d
       from grid g
       join expectation e on e.src = g.src
       join weekday_activity wa on wa.src = g.src and wa.dow = extract(isodow from g.d)::int
      where e.expect_daily and g.rows = 0 and g.d < current_date
        and coalesce(wa.hit_rate, 0) >= 0.3
   )
   select jsonb_build_object(
     ''ok'', true, ''generated_at'', now(), ''today'', current_date,
     ''days'', $2, ''country'', $3,
     ''sources'', (
       select coalesce(jsonb_agg(x order by x.expect_daily desc, x.ord), ''[]''::jsonb) from (
         select e.src, e.label, e.tbl, e.ord, e.expect_daily,
                e.days_with_data, e.days_elapsed, e.total_rows, e.last_data_date,
                case when e.last_data_date is null then null
                     else (current_date - e.last_data_date) end as days_since_last,
                (select coalesce(jsonb_agg(jsonb_build_object(''d'', g.d, ''rows'', g.rows) order by g.d), ''[]''::jsonb)
                   from grid g where g.src = e.src) as by_day,
                (select coalesce(jsonb_agg(gp.d order by gp.d desc), ''[]''::jsonb)
                   from gaps gp where gp.src = e.src) as missing_days,
                (select count(*) from gaps gp where gp.src = e.src) as missing_count
           from expectation e) x),
     ''alerts'', (
       select coalesce(jsonb_agg(jsonb_build_object(
                ''src'', e.src, ''label'', e.label,
                ''last_data_date'', e.last_data_date,
                ''days_since_last'', current_date - e.last_data_date)
              order by (current_date - e.last_data_date) desc), ''[]''::jsonb)
         from expectation e
        where e.expect_daily and e.last_data_date is not null
          and e.last_data_date < current_date - 1)
   )';

  execute v_sql into v_out using p_org, v_n, p_country;
  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public._upload_feed_window_sql(p_table text, p_col text, p_param text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
           when t.typ in ('date', 'timestamp with time zone', 'timestamp without time zone')
           then format(' and t.%I >= ((current_date - %s + 1))::%s and t.%I < ((current_date + 1))::%s',
                       p_col, p_param, t.typ, p_col, t.typ)
           else ''
         end
    from (select format_type(a.atttypid, a.atttypmod) as typ
            from pg_attribute a
           where a.attrelid = ('public.' || quote_ident(p_table))::regclass
             and a.attname = p_col and not a.attisdropped) t
$function$;
