CREATE OR REPLACE FUNCTION public.access_audit_actor_email()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT nullif(coalesce(auth.jwt() ->> 'email', ''), '');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.access_unused_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_idle_days constant int := 30;
  v_out jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;

  with base as (
    select p.id, p.full_name, p.role, coalesce(p.is_super_admin, false) as is_super_admin,
           p.created_at, u.last_sign_in_at, u.email,
           (p.approved is not false and not coalesce(p.locked, false)) as can_sign_in
      from public.profiles p
      left join auth.users u on u.id = p.id
  ), g as (
    select user_id,
           count(*) as n,
           count(*) filter (where effect = 'revoke') as blocks,
           count(*) filter (where effect <> 'revoke') as grants,
           count(*) filter (where expires_at is not null) as with_end
      from public.user_access_grants
     group by user_id
  ), people as (
    select b.*, coalesce(g.n, 0) as rules
      from base b left join g on g.user_id = b.id
     where b.can_sign_in
  ), role_counts as (
    select role, count(*) as n from people group by role
  )
  select jsonb_build_object(
    'generated_at', now(),
    'idle_days', v_idle_days,
    'can_sign_in', (select count(*) from people),
    'active_30d', (select count(*) from people where last_sign_in_at >= now() - make_interval(days => v_idle_days)),
    'never_signed_in', (select count(*) from people where last_sign_in_at is null),
    'never_by_role', coalesce((select jsonb_object_agg(role, n) from (
        select coalesce(role, 'No role') as role, count(*) as n from people where last_sign_in_at is null group by 1) x), '{}'::jsonb),
    'never_first_created', (select min(created_at) from people where last_sign_in_at is null),
    'idle', (select count(*) from people where last_sign_in_at < now() - make_interval(days => v_idle_days)),
    'idle_by_role', coalesce((select jsonb_object_agg(role, n) from (
        select coalesce(role, 'No role') as role, count(*) as n from people
         where last_sign_in_at < now() - make_interval(days => v_idle_days) group by 1) x), '{}'::jsonb),
    'role_totals', coalesce((select jsonb_object_agg(coalesce(role, 'No role'), n) from role_counts), '{}'::jsonb),
    'admins', (select count(*) from people where is_super_admin or role = 'Admin'),
    'rules_total', (select coalesce(sum(n), 0) from g),
    'rules_grants', (select coalesce(sum(grants), 0) from g),
    'rules_blocks', (select coalesce(sum(blocks), 0) from g),
    'rules_with_end', (select coalesce(sum(with_end), 0) from g),
    'rules_people', (select count(*) from g),
    'empty_custom_roles', coalesce((select jsonb_agg(cr.name order by cr.name)
        from public.custom_roles cr
       where coalesce(cr.active, true)
         and not exists (select 1 from public.profiles p where p.role = cr.name)), '[]'::jsonb),
    'reviews_ever', (select count(*) from public.access_review_campaigns),
    'reviews_closed', (select count(*) from public.access_review_campaigns where status = 'closed'),
    'page_views_recorded', false,
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id,
        'name', coalesce(nullif(btrim(full_name), ''), public._mask_email(email), 'No name'),
        'email', public._mask_email(email),
        'role', role,
        'is_super_admin', is_super_admin,
        'created_at', created_at,
        'last_sign_in_at', last_sign_in_at,
        'rules', rules
      ) order by last_sign_in_at desc nulls last, full_name) from people), '[]'::jsonb)
  ) into v_out;

  return v_out;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_allowed_transitions(p_from text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_from text := coalesce(btrim(p_from),''); v_out text[];
begin
  v_out := public._acc_transition_targets(v_from);
  if v_from <> all(array['closed','cancelled_duplicate']) then
    if v_from <> 'cancelled_duplicate' then v_out := public._acc_arr_add(v_out,'cancelled_duplicate'); end if;
    if v_from <> 'legal_hold'          then v_out := public._acc_arr_add(v_out,'legal_hold'); end if;
  end if;
  return v_out;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_build_case_route(p_case jsonb, p_rules jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare r jsonb; v_best jsonb := null; v_best_pri numeric := null; v_pri numeric; v_key text;
begin
  for r in select value from jsonb_array_elements(coalesce(p_rules,'[]'::jsonb)) loop
    if public.accident_rule_matches(r, p_case) then
      v_pri := coalesce(public._acc_num(r -> 'priority'), 1e9);
      if v_best is null or v_pri < v_best_pri then
        v_best := r; v_best_pri := v_pri;
      end if;
    end if;
  end loop;

  if v_best is not null then
    return jsonb_build_object(
      'key', coalesce(nullif(public._acc_str(v_best -> 'route_key'), ''), 'standard'),
      'source', 'rule', 'profile', v_best);
  end if;

  v_key := 'standard';
  if public.accident_is_total_loss(p_case) then v_key := 'total_loss';
  elsif public.accident_is_injury(p_case) then v_key := 'injury';
  elsif public.accident_insurance_involved(p_case) then
    v_key := case when lower(public._acc_str(p_case -> 'repair_type')) = 'external'
                  then 'external_repair_insurance' else 'internal_repair_insurance' end;
  elsif public.accident_is_minor_severity(p_case) then v_key := 'minor_no_insurance';
  end if;
  return jsonb_build_object('key', v_key, 'source', 'fallback', 'profile', null);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_can_fully_close(p_case jsonb, p_ws jsonb DEFAULT '[]'::jsonb, p_route text DEFAULT NULL::text, p_profile jsonb DEFAULT NULL::jsonb, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_req text[] := public.accident_required_workstreams(p_route, p_case, p_profile);
  v_block jsonb := '[]'::jsonb;
  v_now timestamptz := coalesce(p_now, now());
  ws text; v_status text;
  v_overdue int; v_pending int; v_have text[]; v_missing text[];
begin
  foreach ws in array coalesce(public.accident_pipeline_order(),'{}') loop
    if ws <> all(coalesce(v_req,'{}')) then continue; end if;
    if public._acc_closure_satisfied(p_case, p_ws, ws, p_profile) then continue; end if;
    v_status := public.accident_workstream_status(ws, p_case, p_ws);
    v_block := v_block || jsonb_build_object(
      'workstream', ws,
      'reason', public.accident_workstream_name(ws) || ' is not complete ('
                || replace(v_status, '_', ' ') || ')');
  end loop;

  if public.accident_repair_occurred(p_case)
     and 'workshop_qc' <> all(coalesce(v_req,'{}')) then
    v_block := v_block || jsonb_build_object('check','workshop_qc',
      'reason','Workshop quality control required where repair occurred');
  end if;

  v_overdue := (
    select count(*) from jsonb_array_elements(
      case when jsonb_typeof(p_case -> 'tasks') = 'array' then p_case -> 'tasks' else '[]'::jsonb end) t
    where public._acc_truthy(t -> 'mandatory')
      and not (public._acc_truthy(t -> 'resolved')
               or lower(public._acc_str(t -> 'status')) in ('done','resolved'))
      and public._acc_to_ts(t -> 'due') is not null
      and public._acc_to_ts(t -> 'due') < v_now);
  if v_overdue > 0 then
    v_block := v_block || jsonb_build_object('check','mandatory_task',
      'reason', v_overdue || ' mandatory task(s) overdue and unresolved');
  end if;

  v_pending := case when jsonb_typeof(p_case -> 'pending_approvals') = 'array'
                    then jsonb_array_length(p_case -> 'pending_approvals') else 0 end;
  if v_pending = 0 then
    v_pending := (
      select count(*) from jsonb_array_elements(
        case when jsonb_typeof(p_case -> 'approvals') = 'array' then p_case -> 'approvals' else '[]'::jsonb end) a
      where lower(public._acc_str(a -> 'status')) = 'pending');
  end if;
  if v_pending > 0 then
    v_block := v_block || jsonb_build_object('check','pending_approval',
      'reason', v_pending || ' approval(s) still pending');
  end if;

  if p_profile is not null and jsonb_typeof(p_profile -> 'required_documents') = 'array' then
    v_have := array(
      select case when jsonb_typeof(d) = 'string' then public._acc_str(d)
                  else public._acc_str(case when public._acc_truthy_json(d -> 'type') then d -> 'type'
                                            when public._acc_truthy_json(d -> 'key')  then d -> 'key'
                                            else d -> 'name' end) end
      from jsonb_array_elements(
        case when jsonb_typeof(p_case -> 'documents') = 'array' then p_case -> 'documents' else '[]'::jsonb end) d);
    v_missing := array(
      select nd from (
        select public._acc_str(x) nd from jsonb_array_elements(p_profile -> 'required_documents') x
      ) n where nd <> '' and nd <> all(coalesce(v_have,'{}')));
    if array_length(v_missing, 1) is not null then
      v_block := v_block || jsonb_build_object('check','required_document',
        'reason', 'Missing required document(s): ' || array_to_string(v_missing, ', '));
    end if;
  end if;

  if not public._acc_closure_review_approved(p_case) then
    v_block := v_block || jsonb_build_object('check','closure_review',
      'reason','Closure review not approved');
  end if;

  return jsonb_build_object('ok', jsonb_array_length(v_block) = 0, 'blockers', v_block);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_can_transition(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(btrim(p_to),'') = any(public.accident_allowed_transitions(p_from));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_case_status_stage(p_token text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_token
    when 'draft' then 'reported' when 'submitted' then 'reported'
    when 'evidence_incomplete' then 'reported'
    when 'under_fleet_validation' then 'initial_review'
    when 'liability_assessment' then 'hse_investigation'
    when 'insurance_review' then 'insurance_claim'
    when 'claim_registration_pending' then 'insurance_claim'
    when 'awaiting_insurer_response' then 'insurance_claim'
    when 'technical_assessment' then 'workshop_assessment'
    when 'repair_decision_pending' then 'repair_approval'
    when 'repair_planning' then 'repair_approval'
    when 'awaiting_fleet_approval' then 'repair_approval'
    when 'awaiting_parts' then 'repair_approval'
    when 'awaiting_quotation' then 'repair_approval'
    when 'awaiting_po' then 'repair_approval'
    when 'awaiting_external_workshop' then 'repair_approval'
    when 'repair_in_progress' then 'repair_in_progress'
    when 'workshop_quality_inspection' then 'repair_in_progress'
    when 'fleet_inspection' then 'final_inspection'
    when 'rectification_required' then 'final_inspection'
    when 'operationally_completed' then 'vehicle_release'
    when 'insurance_settlement_pending' then 'cost_recovery'
    when 'financial_closure_pending' then 'cost_recovery'
    when 'corrective_actions_pending' then 'cost_recovery'
    when 'closure_review' then 'closed' when 'closed' then 'closed'
    when 'cancelled_duplicate' then 'cancelled'
    when 'total_loss_processing' then 'insurance_claim'
    when 'legal_hold' then null when 'reopened' then null
    else null end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_case_status_tokens()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['draft','submitted','evidence_incomplete','under_fleet_validation',
    'liability_assessment','insurance_review','claim_registration_pending',
    'awaiting_insurer_response','technical_assessment','repair_decision_pending',
    'repair_planning','awaiting_fleet_approval','awaiting_parts','awaiting_quotation',
    'awaiting_po','awaiting_external_workshop','repair_in_progress',
    'workshop_quality_inspection','fleet_inspection','rectification_required',
    'operationally_completed','insurance_settlement_pending','financial_closure_pending',
    'corrective_actions_pending','closure_review','closed','reopened',
    'cancelled_duplicate','total_loss_processing','legal_hold'];
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_claim_decision(p_claim_id uuid, p_decision text, p_approved_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org         uuid;
  v_country     text;
  v_site        text;
  v_decision    text := lower(btrim(coalesce(p_decision, '')));
  v_reason      text := nullif(btrim(coalesce(p_reason, '')), '');
  v_claim       public.accident_insurance_claims%rowtype;
  v_row         public.accident_insurance_decisions%rowtype;
  v_claim_dec   text;
begin
  if p_claim_id is null then
    raise exception 'A claim is required.' using errcode = '22023';
  end if;

  select * into v_claim from public.accident_insurance_claims where id = p_claim_id;
  if v_claim.id is null then
    raise exception 'Claim % not found.', p_claim_id using errcode = 'P0002';
  end if;

  -- Re-assert org + country + site scope via the claim's parent case.
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_claim.accident_id);

  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'edit_insurance')) then
    raise exception 'Not permitted to record a claim decision.' using errcode = '42501';
  end if;

  -- Decision token must be one of the accident_insurance_decisions CHECK values.
  if v_decision <> all (array[
       'fully_approved','partially_approved','rejected','withdrawn','documents_requested',
       'survey_ordered','acknowledged','settled','disputed']) then
    raise exception 'Invalid claim decision "%".', p_decision using errcode = '22023';
  end if;

  -- Money validation + the approve-needs-an-amount rule.
  if p_approved_amount is not null and p_approved_amount < 0 then
    raise exception 'Approved amount cannot be negative.' using errcode = '22023';
  end if;
  if v_decision in ('fully_approved','partially_approved') and p_approved_amount is null then
    raise exception 'An approved amount is required for a "%" decision.', v_decision
      using errcode = '22023';
  end if;

  -- Record the decision on the ledger.
  insert into public.accident_insurance_decisions
    (organisation_id, accident_id, claim_id, country, site, decision, amount,
     decided_at, remarks, created_by, created_at, updated_at)
  values
    (v_org, v_claim.accident_id, p_claim_id, v_country, v_site, v_decision, p_approved_amount,
     now(), v_reason, auth.uid(), now(), now())
  returning * into v_row;

  -- Map the decision token onto the parent claim's status vocabulary (02 B5). The
  -- shared tokens carry through unchanged; the workflow-only tokens map to the
  -- claim's equivalent waiting state.
  v_claim_dec := case v_decision
    when 'documents_requested' then 'documents_incomplete'
    when 'survey_ordered'      then 'awaiting_surveyor'
    when 'acknowledged'        then 'awaiting_acknowledgement'
    else v_decision   -- fully_approved / partially_approved / rejected / withdrawn / settled / disputed
  end;

  update public.accident_insurance_claims c set
     decision         = v_claim_dec,
     approved_amount  = case
                          when v_decision in ('fully_approved','partially_approved')
                            then p_approved_amount
                          else c.approved_amount
                        end,
     rejection_reason = case
                          when v_decision = 'rejected'
                            then coalesce(v_reason, c.rejection_reason)
                          else c.rejection_reason
                        end,
     updated_at       = now()
   where c.id = p_claim_id
  returning * into v_claim;

  return jsonb_build_object('ok', true, 'decision', to_jsonb(v_row), 'claim', to_jsonb(v_claim));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_claim_register(p_accident_id uuid, p_insurer text, p_policy_no text, p_claim_no text, p_claim_amount numeric, p_deductible numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org       uuid;
  v_country   text;
  v_site      text;
  v_insurer   text := nullif(btrim(coalesce(p_insurer, '')), '');
  v_policy_no text := nullif(btrim(coalesce(p_policy_no, '')), '');
  v_claim_no  text := nullif(btrim(coalesce(p_claim_no, '')), '');
  v_existing  public.accident_insurance_claims%rowtype;
  v_claim     public.accident_insurance_claims%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  -- Capability gate: elevated OR the insurance-owning capability.
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'edit_insurance')) then
    raise exception 'Not permitted to register an insurance claim.' using errcode = '42501';
  end if;

  -- Money validation: a claimed amount / deductible can never be negative.
  if p_claim_amount is not null and p_claim_amount < 0 then
    raise exception 'Claim amount cannot be negative.' using errcode = '22023';
  end if;
  if p_deductible is not null and p_deductible < 0 then
    raise exception 'Deductible cannot be negative.' using errcode = '22023';
  end if;

  -- The case row exists even before its first claim. Serialize callers here
  -- before looking for a claim; locking the child lookup cannot lock absence.
  -- This order also matches closure operations: case first, child rows second.
  perform 1 from public.accidents where id = p_accident_id for update;
  if not found then
    raise exception 'Incident % not found.', p_accident_id using errcode = 'P0002';
  end if;
  -- A concurrent case-scope edit may have committed while the lock waited.
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  -- Resolve the case's existing claim (latest first), if any.
  select * into v_existing
    from public.accident_insurance_claims c
   where c.accident_id = p_accident_id
   order by c.created_at desc, c.id desc
   limit 1;

  if v_existing.id is null then
    insert into public.accident_insurance_claims
      (organisation_id, accident_id, country, site, insurance_applicable,
       insurer, policy_no, claim_no, deductible, decision, claim_registered_date,
       created_by, created_at, updated_at)
    values
      (v_org, p_accident_id, v_country, v_site, true,
       v_insurer, v_policy_no, v_claim_no, p_deductible, 'registered', current_date,
       auth.uid(), now(), now())
    returning * into v_claim;
  else
    update public.accident_insurance_claims c set
       insurer               = coalesce(v_insurer, c.insurer),
       policy_no             = coalesce(v_policy_no, c.policy_no),
       claim_no              = coalesce(v_claim_no, c.claim_no),
       deductible            = coalesce(p_deductible, c.deductible),
       decision              = case
                                 when c.decision in ('not_required','under_review','documents_incomplete')
                                   then 'registered'
                                 else c.decision
                               end,
       claim_registered_date = coalesce(c.claim_registered_date, current_date),
       updated_at            = now()
     where c.id = v_existing.id
    returning * into v_claim;
  end if;

  -- Persist the claimed amount on the case root (its only real home; see header).
  if p_claim_amount is not null then
    update public.accidents
       set claim_amount = p_claim_amount
     where id = p_accident_id;
  end if;

  -- Move the insurance workstream to in_progress in the same transaction, so a
  -- registered claim never sits against an untouched insurance section.
  insert into public.accident_case_workstreams
    (organisation_id, accident_id, country, site, workstream_key, status,
     started_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, 'insurance', 'in_progress',
     now(), auth.uid(), now(), now())
  on conflict (accident_id, workstream_key) do update set
     status     = case
                    when public.accident_case_workstreams.status
                         in ('not_required','not_started','assigned')
                      then 'in_progress'
                    else public.accident_case_workstreams.status
                  end,
     started_at = coalesce(public.accident_case_workstreams.started_at, now()),
     updated_at = now();

  return jsonb_build_object('ok', true, 'claim', to_jsonb(v_claim));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_claim_settlement(p_claim_id uuid, p_settled_amount numeric, p_settled_at date, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org        uuid;
  v_country    text;
  v_site       text;
  v_reference  text := nullif(btrim(coalesce(p_reference, '')), '');
  v_claim      public.accident_insurance_claims%rowtype;
  v_row        public.accident_insurance_settlements%rowtype;
begin
  if p_claim_id is null then
    raise exception 'A claim is required.' using errcode = '22023';
  end if;

  select * into v_claim from public.accident_insurance_claims where id = p_claim_id;
  if v_claim.id is null then
    raise exception 'Claim % not found.', p_claim_id using errcode = 'P0002';
  end if;

  -- Re-assert org + country + site scope via the claim's parent case.
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_claim.accident_id);

  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'edit_insurance')) then
    raise exception 'Not permitted to record a settlement.' using errcode = '42501';
  end if;

  if p_settled_amount is null then
    raise exception 'A settlement amount is required.' using errcode = '22023';
  end if;
  if p_settled_amount < 0 then
    raise exception 'Settlement amount cannot be negative.' using errcode = '22023';
  end if;
  if p_settled_at is null then
    raise exception 'A settlement date is required.' using errcode = '22023';
  end if;

  insert into public.accident_insurance_settlements
    (organisation_id, accident_id, claim_id, country, site, settlement_type, amount,
     settled_at, payment_reference, created_by, created_at, updated_at)
  values
    (v_org, v_claim.accident_id, p_claim_id, v_country, v_site, 'claim_payment', p_settled_amount,
     p_settled_at, v_reference, auth.uid(), now(), now())
  returning * into v_row;

  -- Money has moved: advance the parent claim to 'settled' (valid claim token).
  update public.accident_insurance_claims c set
     decision   = 'settled',
     updated_at = now()
   where c.id = p_claim_id
  returning * into v_claim;

  return jsonb_build_object('ok', true, 'settlement', to_jsonb(v_row), 'claim', to_jsonb(v_claim));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_closure_blockers(p_case jsonb, p_ws jsonb DEFAULT '[]'::jsonb, p_route text DEFAULT NULL::text, p_profile jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_req text[] := public.accident_required_workstreams(p_route, p_case, p_profile);
        v_out jsonb := '[]'::jsonb; ws text; v_status text;
begin
  foreach ws in array coalesce(public.accident_pipeline_order(),'{}') loop
    if ws <> all(coalesce(v_req,'{}')) then continue; end if;
    if public._acc_closure_satisfied(p_case, p_ws, ws, p_profile) then continue; end if;
    v_status := public.accident_workstream_status(ws, p_case, p_ws);
    v_out := v_out || jsonb_build_object(
      'workstream', ws,
      'name', public.accident_workstream_name(ws),
      'dimension', public.accident_workstream_dimension(ws),
      'status', v_status,
      'reason', public.accident_workstream_name(ws) || ' is ' || replace(v_status, '_', ' '));
  end loop;
  return v_out;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_closure_level(p_case jsonb, p_ws jsonb DEFAULT '[]'::jsonb, p_route text DEFAULT NULL::text, p_profile jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_req text[]; v_money_done boolean;
begin
  if public._acc_is_closed_case(p_case) then return 'fully_closed'; end if;
  v_req := public.accident_required_workstreams(p_route, p_case, p_profile);
  if not public.accident_operationally_complete(p_case, p_ws, v_req, p_profile) then
    return null;
  end if;
  v_money_done := public.accident_financially_complete(p_case, p_ws, v_req, p_profile)
              and public.accident_corrective_complete(p_case, p_ws, v_req, p_profile);
  if not v_money_done then return 'financially_open'; end if;
  return case when public._acc_closure_review_approved(p_case)
              then 'fully_closed' else 'operationally_completed' end;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_completeness(p_case jsonb, p_ws jsonb DEFAULT '[]'::jsonb, p_route text DEFAULT NULL::text, p_profile jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_req text[] := public.accident_required_workstreams(p_route, p_case, p_profile);
  ws text; dim text; ok boolean;
  ri int:=0; si int:=0; rin int:=0; sin int:=0; rr int:=0; sr int:=0; rf int:=0; sf int:=0;
begin
  foreach ws in array coalesce(v_req,'{}') loop
    dim := public.accident_workstream_dimension(ws);
    if dim is null then continue; end if;
    ok := public._acc_scored(p_case, p_ws, ws);
    if    dim = 'incident'  then ri  := ri +1; if ok then si  := si +1; end if;
    elsif dim = 'insurance' then rin := rin+1; if ok then sin := sin+1; end if;
    elsif dim = 'repair'    then rr  := rr +1; if ok then sr  := sr +1; end if;
    elsif dim = 'financial' then rf  := rf +1; if ok then sf  := sf +1; end if;
    end if;
  end loop;

  return jsonb_build_object(
    'incident',  case when ri  = 0 then null else round(100.0 * si  / ri )::int end,
    'insurance', case when rin = 0 then null else round(100.0 * sin / rin)::int end,
    'repair',    case when rr  = 0 then null else round(100.0 * sr  / rr )::int end,
    'financial', case when rf  = 0 then null else round(100.0 * sf  / rf )::int end,
    'overall',   case when (ri+rin+rr+rf) = 0 then null
                      else round(100.0 * (si+sin+sr+sf) / (ri+rin+rr+rf))::int end
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_corrective_complete(p_case jsonb, p_ws jsonb, p_required text[], p_profile jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when 'corrective' <> all(coalesce(p_required,'{}')) then true
              else public._acc_closure_satisfied(p_case, p_ws, 'corrective', p_profile) end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_corrective_required(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public._acc_truthy(p_case -> 'corrective_action_required')
      or public._acc_truthy(p_case -> 'injuries')
      or coalesce(public._acc_num(p_case -> 'injury_count'), 0) > 0;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_decide_closure(p_accident_id uuid, p_level text, p_decision text, p_reviewer_id uuid DEFAULT NULL::uuid, p_remarks text DEFAULT NULL::text, p_blockers jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_country  text;
  v_site     text;
  v_level    text := lower(btrim(coalesce(p_level, '')));
  v_decision text := lower(btrim(coalesce(p_decision, '')));
  v_case     jsonb;
  v_ws       jsonb;
  v_route    text;
  v_gate     jsonb;
  v_row      public.accident_closure_reviews%rowtype;
begin
  -- cap-guard:approve
  if public.app_cap_revoked('accidents','approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if v_level <> all (array['operationally_completed','financially_open','fully_closed']) then
    raise exception 'Invalid closure level "%".', p_level using errcode = '22023';
  end if;
  if v_decision <> all (array['approved','rejected','returned']) then
    raise exception 'Invalid closure decision "%".', p_decision using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_blockers, '[]'::jsonb)) is distinct from 'array' then
    raise exception 'Blockers must be a JSON array.' using errcode = '22023';
  end if;

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'close_case')) then
    raise exception 'Not permitted to decide closure.' using errcode = '42501';
  end if;

  if v_decision = 'approved' and v_level = 'fully_closed'
     and to_regprocedure(
           'public.accident_can_fully_close(jsonb,jsonb,text,jsonb,timestamptz)') is not null then
    select to_jsonb(a) into v_case from public.accidents a where a.id = p_accident_id;
    select coalesce(jsonb_agg(to_jsonb(w)), '[]'::jsonb) into v_ws
      from public.accident_case_workstreams w where w.accident_id = p_accident_id;
    v_route := coalesce((v_case ->> 'route_key'), 'standard');

    execute
      'select public.accident_can_fully_close($1,$2,$3,$4,$5)'
      into v_gate
      using v_case, v_ws, v_route, null::jsonb, now();

    if v_gate is not null and coalesce((v_gate ->> 'ok')::boolean, false) is not true then
      raise exception 'Closure gate not satisfied: %',
        coalesce(v_gate -> 'blockers', '[]'::jsonb)::text
        using errcode = '42501';
    end if;
  end if;

  insert into public.accident_closure_reviews
    (organisation_id, accident_id, country, site, level, reviewer_id, reviewed_at,
     decision, blockers, remarks, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_level, coalesce(p_reviewer_id, auth.uid()),
     now(), v_decision, coalesce(p_blockers, '[]'::jsonb),
     nullif(btrim(coalesce(p_remarks, '')), ''), auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'review', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_derive_case_status(p_case jsonb, p_ws jsonb DEFAULT '[]'::jsonb, p_route text DEFAULT NULL::text, p_profile jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_req text[]; ws text; v_status text; v_m text;
begin
  if public._acc_truthy(p_case -> 'legal_hold_active') or public._acc_truthy(p_case -> 'legal_hold')
     then return 'legal_hold'; end if;
  if public._acc_truthy(p_case -> 'cancelled') or public._acc_truthy(p_case -> 'cancelled_duplicate')
     then return 'cancelled_duplicate'; end if;
  if public._acc_is_closed_case(p_case) then return 'closed'; end if;
  if public._acc_truthy(p_case -> 'reopened_flag') or public._acc_truthy(p_case -> 'reopened')
     then return 'reopened'; end if;
  if public._acc_truthy(p_case -> 'total_loss_route') or public._acc_truthy(p_case -> 'total_loss')
     then return 'total_loss_processing'; end if;

  v_req := public.accident_required_workstreams(p_route, p_case, p_profile);

  if not public._acc_truthy(p_case -> 'submitted') then
    return case when public._acc_truthy(p_case -> 'returned') then 'evidence_incomplete' else 'draft' end;
  end if;
  if ('incident_evidence' = any(coalesce(v_req,'{}')))
     and not public.accident_workstream_satisfied(
               public.accident_workstream_status('incident_evidence', p_case, p_ws)) then
    return case when public._acc_truthy(p_case -> 'returned') then 'evidence_incomplete' else 'submitted' end;
  end if;

  foreach ws in array coalesce(public.accident_pipeline_order(),'{}') loop
    if ws = 'incident_evidence' or ws <> all(coalesce(v_req,'{}')) then continue; end if;
    v_status := public.accident_workstream_status(ws, p_case, p_ws);
    if public.accident_workstream_satisfied(v_status) then continue; end if;
    v_m := public._acc_case_status_for(ws, v_status);
    if v_m is null then continue; end if;
    return v_m;
  end loop;

  if not public.accident_financially_complete(p_case, p_ws, v_req, p_profile) then
    return case when ('insurance' = any(coalesce(v_req,'{}')))
                     and not public._acc_closure_satisfied(p_case, p_ws, 'insurance', p_profile)
                then 'insurance_settlement_pending' else 'financial_closure_pending' end;
  end if;
  if not public.accident_corrective_complete(p_case, p_ws, v_req, p_profile) then
    return 'corrective_actions_pending';
  end if;
  if not public._acc_closure_review_approved(p_case) then return 'closure_review'; end if;
  return 'closed';
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_derive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year text;
  v_seq  int;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- reference number ACC-YYYY-####
    IF NEW.reference_no IS NULL OR btrim(NEW.reference_no) = '' THEN
      v_year := to_char(COALESCE(NEW.incident_date, current_date), 'YYYY');
      v_seq := public.next_accident_reference(NEW.organisation_id, v_year);
      NEW.reference_no := 'ACC-' || v_year || '-' || lpad(v_seq::text, 4, '0');
    END IF;
    -- stage <- status when a stage was not supplied
    IF NEW.workflow_stage IS NULL THEN
      NEW.workflow_stage := public.accident_stage_from_status(COALESCE(NEW.status, 'reported'));
    ELSE
      -- keep legacy status consistent with an explicitly supplied stage
      NEW.status := public.accident_status_from_stage(NEW.workflow_stage);
    END IF;
    IF NEW.vor IS TRUE AND NEW.vor_since IS NULL THEN
      NEW.vor_since := now();
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.workflow_stage IS DISTINCT FROM OLD.workflow_stage THEN
    -- explicit stage change wins -> sync legacy status
    NEW.status := public.accident_status_from_stage(NEW.workflow_stage);
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    -- legacy writer (mobile/imports) changed status -> derive stage
    NEW.workflow_stage := public.accident_stage_from_status(NEW.status);
  END IF;

  -- VOR timestamp management
  IF NEW.vor IS TRUE AND (OLD.vor IS DISTINCT FROM TRUE) AND NEW.vor_since IS NULL THEN
    NEW.vor_since := now();
  ELSIF NEW.vor IS FALSE THEN
    NEW.vor_since := NULL;
  END IF;

  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_document_add(p_accident_id uuid, p_doc_type text, p_storage_ref text, p_reference_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_country  text;
  v_site     text;
  v_doc_type text := nullif(btrim(coalesce(p_doc_type, '')), '');
  v_ref      text := nullif(btrim(coalesce(p_storage_ref, '')), '');
  v_refno    text := nullif(btrim(coalesce(p_reference_no, '')), '');
  v_received boolean;
  v_notes    text;
  v_row      public.accident_claim_documents%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if v_doc_type is null then
    raise exception 'A document type is required.' using errcode = '22023';
  end if;

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'edit_insurance')) then
    raise exception 'Not permitted to add claim documents to this case.' using errcode = '42501';
  end if;

  v_received := v_ref is not null;                       -- a stored file means received
  v_notes    := case when v_refno is not null
                     then 'Reference: ' || v_refno
                     else null end;

  insert into public.accident_claim_documents
    (organisation_id, accident_id, country, site, doc_type, storage_ref,
     required, received, received_at, notes, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_doc_type, v_ref,
     true, v_received, case when v_received then now() end, v_notes,
     auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'document', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_document_mark_received(p_accident_id uuid, p_document_id uuid, p_storage_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_ref     text := nullif(btrim(coalesce(p_storage_ref, '')), '');
  v_row     public.accident_claim_documents%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'edit_insurance')) then
    raise exception 'Not permitted to update claim documents on this case.' using errcode = '42501';
  end if;

  update public.accident_claim_documents d set
     received    = true,
     received_at = coalesce(d.received_at, now()),
     storage_ref = coalesce(v_ref, d.storage_ref),
     updated_at  = now()
   where d.id = p_document_id
     and d.accident_id = p_accident_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Document % not found on this case.', p_document_id using errcode = 'P0002';
  end if;

  return jsonb_build_object('ok', true, 'document', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_downtime_set(p_accident_id uuid, p_vehicle_status text, p_offroad_start date DEFAULT NULL::date, p_expected_return_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_country  text;
  v_site     text;
  v_status   text := nullif(btrim(coalesce(p_vehicle_status, '')), '');
  v_existing uuid;
  v_row      public.accident_vehicle_downtime%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'execute_repair')
          or public.app_user_can('accidents', 'validate')) then
    raise exception 'Not permitted to set vehicle downtime.' using errcode = '42501';
  end if;

  if v_status is not null and v_status <> all (array[
       'operational','restricted','awaiting_recovery','off_road_accident','under_inspection',
       'under_repair','ready_for_inspection','rejected_after_repair','returned_to_operation',
       'total_loss','disposed']) then
    raise exception 'Invalid vehicle status "%".', p_vehicle_status using errcode = '22023';
  end if;

  select id into v_existing
    from public.accident_vehicle_downtime
   where accident_id = p_accident_id
   order by created_at desc, id desc
   limit 1;

  if v_existing is not null then
    update public.accident_vehicle_downtime set
       vehicle_status      = coalesce(v_status, vehicle_status),
       offroad_start       = coalesce(p_offroad_start, offroad_start),
       expected_return_date = coalesce(p_expected_return_date, expected_return_date),
       updated_at          = now()
     where id = v_existing
    returning * into v_row;
  else
    insert into public.accident_vehicle_downtime
      (organisation_id, accident_id, country, site, vehicle_status, offroad_start,
       expected_return_date, created_by, created_at, updated_at)
    values
      (v_org, p_accident_id, v_country, v_site, v_status, p_offroad_start,
       p_expected_return_date, auth.uid(), now(), now())
    returning * into v_row;
  end if;

  return jsonb_build_object('ok', true, 'downtime', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_evidence_add(p_accident_id uuid, p_kind text, p_storage_ref text, p_caption text DEFAULT NULL::text, p_workstream_key text DEFAULT NULL::text, p_requirement_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_kind    text := lower(btrim(coalesce(p_kind, '')));
  v_ref     text := nullif(btrim(coalesce(p_storage_ref, '')), '');
  v_caption text := nullif(btrim(coalesce(p_caption, '')), '');
  v_ws      text := nullif(btrim(coalesce(p_workstream_key, '')), '');
  v_req     text := nullif(btrim(coalesce(p_requirement_key, '')), '');
  v_row     public.accident_evidence%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if v_kind <> all (array['photo','video','document']) then
    raise exception 'Invalid evidence kind "%".', p_kind using errcode = '22023';
  end if;

  if v_ref is null then
    raise exception 'A storage reference is required to record evidence.'
      using errcode = '22023';
  end if;

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'submit')) then
    raise exception 'Not permitted to add evidence to this case.' using errcode = '42501';
  end if;

  insert into public.accident_evidence
    (organisation_id, accident_id, country, site, workstream_key, requirement_key,
     kind, storage_ref, caption, uploaded_by, uploaded_at,
     created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_ws, v_req,
     v_kind, v_ref, v_caption, auth.uid(), now(),
     auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'evidence', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_evidence_checklist(p_accident_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_route   text;
  v_type    text;
  v_items   jsonb;
  v_total   integer;
  v_received integer;
  v_mand_total integer;
  v_mand_missing integer;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  select a.route_key, a.accident_type
    into v_route, v_type
    from public.accidents a
   where a.id = p_accident_id;

  with reqs as (
    -- one row per requirement_key that applies to this case, most-specific /
    -- mandatory row wins if the same key is defined at more than one scope.
    select distinct on (r.requirement_key)
           r.requirement_key,
           r.label,
           r.category,
           r.kind,
           r.mandatory,
           r.sort_order
      from public.accident_evidence_requirements r
     where r.organisation_id = v_org
       and r.active
       and (r.route_key is null     or r.route_key = v_route)
       and (r.accident_type is null or r.accident_type = v_type)
       and (r.country is null       or r.country = v_country)
     order by r.requirement_key,
              r.mandatory desc,
              r.route_key nulls last,
              r.accident_type nulls last,
              r.sort_order
  ),
  recv as (
    select e.requirement_key,
           count(*)                                          as evidence_count,
           bool_or(e.verification_status = 'verified')       as any_verified,
           max(e.uploaded_at)                                as last_uploaded_at
      from public.accident_evidence e
     where e.accident_id = p_accident_id
       and e.requirement_key is not null
     group by e.requirement_key
  ),
  merged as (
    select req.requirement_key,
           req.label,
           req.category,
           req.kind,
           req.mandatory,
           req.sort_order,
           coalesce(recv.evidence_count, 0)          as evidence_count,
           (coalesce(recv.evidence_count, 0) > 0)    as received,
           coalesce(recv.any_verified, false)        as verified,
           recv.last_uploaded_at
      from reqs req
      left join recv on recv.requirement_key = req.requirement_key
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'requirement_key', m.requirement_key,
        'label',           m.label,
        'category',        m.category,
        'kind',            m.kind,
        'mandatory',       m.mandatory,
        'sort_order',      m.sort_order,
        'received',        m.received,
        'verified',        m.verified,
        'evidence_count',  m.evidence_count,
        'last_uploaded_at', m.last_uploaded_at
      ) order by m.sort_order, m.requirement_key
    ), '[]'::jsonb),
    count(*),
    count(*) filter (where m.received),
    count(*) filter (where m.mandatory),
    count(*) filter (where m.mandatory and not m.received)
    into v_items, v_total, v_received, v_mand_total, v_mand_missing
  from merged m;

  return jsonb_build_object(
    'ok',           true,
    'accident_id',  p_accident_id,
    'route_key',    v_route,
    'accident_type', v_type,
    'items',        v_items,
    'summary', jsonb_build_object(
      'total',            v_total,
      'received',         v_received,
      'missing',          v_total - v_received,
      'mandatory_total',  v_mand_total,
      'mandatory_missing', v_mand_missing,
      'complete',         (v_mand_missing = 0)
    )
  );
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_evidence_verify(p_accident_id uuid, p_evidence_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_country  text;
  v_site     text;
  v_decision text := lower(btrim(coalesce(p_decision, '')));
  v_note     text := nullif(btrim(coalesce(p_note, '')), '');
  v_row      public.accident_evidence%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if v_decision <> all (array['verified','rejected','unverified']) then
    raise exception 'Invalid verification decision "%".', p_decision using errcode = '22023';
  end if;

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'submit')) then
    raise exception 'Not permitted to verify evidence on this case.' using errcode = '42501';
  end if;

  update public.accident_evidence e set
     verification_status = v_decision,
     verified_by         = case when v_decision = 'unverified' then null else auth.uid() end,
     verified_at         = case when v_decision = 'unverified' then null else now() end,
     caption             = case when v_note is not null then v_note else e.caption end,
     updated_at          = now()
   where e.id = p_evidence_id
     and e.accident_id = p_accident_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Evidence % not found on this case.', p_evidence_id using errcode = 'P0002';
  end if;

  return jsonb_build_object('ok', true, 'evidence', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_finance_txn_add(p_accident_id uuid, p_txn_type text, p_direction text, p_amount numeric, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org       uuid;
  v_country   text;
  v_site      text;
  v_txn_type  text := lower(btrim(coalesce(p_txn_type, '')));
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_row       public.accident_financial_transactions%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'post_cost')) then
    raise exception 'Not permitted to post a financial transaction.' using errcode = '42501';
  end if;

  if v_txn_type <> all (array[
       'repair_estimate','internal_labour','internal_parts','external_repair','towing',
       'storage','third_party_cost','po_amount','invoice_amount','insurer_approved',
       'deductible','insurance_payment','third_party_recovery','unrecovered','company_loss']) then
    raise exception 'Invalid transaction type "%".', p_txn_type using errcode = '22023';
  end if;

  if v_direction <> all (array['cost','recovery','neutral']) then
    raise exception 'Invalid transaction direction "%".', p_direction using errcode = '22023';
  end if;

  if p_amount is null then
    raise exception 'A transaction amount is required.' using errcode = '22023';
  end if;
  if p_amount < 0 then
    raise exception 'Transaction amount cannot be negative.' using errcode = '22023';
  end if;

  insert into public.accident_financial_transactions
    (organisation_id, accident_id, country, site, txn_type, direction, amount,
     description, posted_by, posted_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_txn_type, v_direction, p_amount,
     nullif(btrim(coalesce(p_description, '')), ''), auth.uid(), now(),
     auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'transaction', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_financially_complete(p_case jsonb, p_ws jsonb, p_required text[], p_profile jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare ws text;
begin
  foreach ws in array coalesce(p_required,'{}') loop
    if public.accident_workstream_dimension(ws) in ('insurance','financial') then
      if not public._acc_closure_satisfied(p_case, p_ws, ws, p_profile) then return false; end if;
    end if;
  end loop;
  return true;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_insurance_involved(p_case jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if (p_case -> 'insurance_involved') = 'false'::jsonb then return false; end if;
  if public._acc_truthy(p_case -> 'insurance_involved') then return true; end if;
  return public._acc_str(p_case -> 'insurer') <> ''
      or public._acc_str(p_case -> 'policy_no') <> ''
      or coalesce(public._acc_num(p_case -> 'claim_amount'), 0) > 0;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_is_injury(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public._acc_truthy(p_case -> 'injuries')
      or coalesce(public._acc_num(p_case -> 'injury_count'), 0) > 0
      or public._acc_str(p_case -> 'accident_type') ~* 'injur|fatal';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_is_minor_severity(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select lower(public._acc_str(p_case -> 'severity')) in ('minor','low','small');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_is_total_loss(p_case jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select public._acc_truthy(p_case -> 'total_loss_route')
      or public._acc_truthy(p_case -> 'total_loss')
      or public._acc_truthy(p_case -> 'total_loss_possibility')
      or lower(public._acc_str(p_case -> 'repair_type')) = 'total loss'
      or public._acc_str(p_case -> 'accident_type') ~* 'total.?loss';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_log_stage_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_from  int;
  v_to    int;
  v_stage text;
  i       int;
begin
  if TG_OP = 'INSERT' then
    insert into public.accident_stage_events
      (organisation_id, accident_id, country, site, stage, department, entered_by)
    values (NEW.organisation_id, NEW.id, NEW.country, NEW.site,
            NEW.workflow_stage, public.accident_stage_department(NEW.workflow_stage), v_actor);
    return null;
  end if;

  if NEW.workflow_stage is not distinct from OLD.workflow_stage then
    return null;
  end if;

  -- Close whatever was open. There should be exactly one; closing all of them
  -- is the safe shape if an earlier write ever left two.
  update public.accident_stage_events
     set exited_at = now(), exited_by = v_actor
   where accident_id = NEW.id and exited_at is null;

  -- Record the stages that were passed over. A forward jump of more than one
  -- step means every stage in between was never worked.
  v_from := public.accident_stage_order(OLD.workflow_stage);
  v_to   := public.accident_stage_order(NEW.workflow_stage);
  if v_from is not null and v_to is not null and v_to > v_from + 1 then
    for i in (v_from + 1)..(v_to - 1) loop
      select s into v_stage from (
        select unnest(array['reported','initial_review','hse_investigation','workshop_assessment',
                            'insurance_claim','repair_approval','repair_in_progress','final_inspection',
                            'vehicle_release','cost_recovery','closed']) as s,
               generate_series(1, 11) as n
      ) t where t.n = i;
      insert into public.accident_stage_events
        (organisation_id, accident_id, country, site, stage, department,
         entered_at, exited_at, entered_by, exited_by, skipped, note)
      values (NEW.organisation_id, NEW.id, NEW.country, NEW.site,
              v_stage, public.accident_stage_department(v_stage),
              now(), now(), v_actor, v_actor, true,
              'Passed over when the case moved from ' || OLD.workflow_stage || ' to ' || NEW.workflow_stage);
    end loop;
  end if;

  insert into public.accident_stage_events
    (organisation_id, accident_id, country, site, stage, department, entered_by)
  values (NEW.organisation_id, NEW.id, NEW.country, NEW.site,
          NEW.workflow_stage, public.accident_stage_department(NEW.workflow_stage), v_actor);
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_log_stage_waiver()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k text;
  was boolean;
  now_ boolean;
begin
  if NEW.stage_waivers is not distinct from OLD.stage_waivers then return null; end if;
  for k in select jsonb_object_keys(coalesce(NEW.stage_waivers, '{}'::jsonb))
                  union
                  select jsonb_object_keys(coalesce(OLD.stage_waivers, '{}'::jsonb))
  loop
    was  := coalesce((OLD.stage_waivers -> k ->> 'required')::boolean, true);
    now_ := coalesce((NEW.stage_waivers -> k ->> 'required')::boolean, true);
    if was is distinct from now_ then
      insert into public.accident_audit_log (accident_id, action, old_values, new_values, changed_by)
      values (
        NEW.id,
        case when now_ then 'stage_reinstated' else 'stage_waived' end,
        jsonb_build_object('stage', k, 'required', was),
        jsonb_build_object('stage', k, 'required', now_,
                           'remark', NEW.stage_waivers -> k ->> 'remark'),
        auth.uid()
      );
    end if;
  end loop;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_na_envelope_valid(p_entry jsonb, p_require_approval boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select p_entry is not null
     and jsonb_typeof(p_entry) = 'object'
     and public._acc_str(p_entry -> 'reason') <> ''
     and public._acc_str(p_entry -> 'by')     <> ''
     and public._acc_str(p_entry -> 'at')     <> ''
     and (not p_require_approval or public._acc_str(p_entry -> 'approved_by') <> '');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_operationally_complete(p_case jsonb, p_ws jsonb, p_required text[], p_profile jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare ws text; dim text;
begin
  foreach ws in array coalesce(p_required,'{}') loop
    dim := public.accident_workstream_dimension(ws);
    if dim in ('incident','repair') then
      if ws = 'corrective' then continue; end if;
      if not public._acc_closure_satisfied(p_case, p_ws, ws, p_profile) then return false; end if;
    end if;
  end loop;
  return true;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_pending_action(p_stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_stage
    WHEN 'reported' THEN 'Review the report and assign an owner'
    WHEN 'initial_review' THEN 'Complete initial review'
    WHEN 'hse_investigation' THEN 'Complete HSE investigation'
    WHEN 'workshop_assessment' THEN 'Complete workshop assessment and estimate'
    WHEN 'insurance_claim' THEN 'Submit / progress the insurance claim'
    WHEN 'repair_approval' THEN 'Approve the repair estimate'
    WHEN 'repair_in_progress' THEN 'Complete the repair'
    WHEN 'final_inspection' THEN 'Carry out final inspection'
    WHEN 'vehicle_release' THEN 'Release the vehicle back to operations'
    WHEN 'cost_recovery' THEN 'Complete cost recovery'
    WHEN 'closed' THEN 'None - case closed'
    ELSE 'Review the case' END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_pipeline_order()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['incident_evidence','fleet_validation','liability','insurance',
               'assessment','repair','workshop_qc','handover','finance','corrective'];
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_portal_create(p_accident_id uuid, p_password text DEFAULT NULL::text, p_expires timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_token   text;
  v_row     public.accident_portal_shares%rowtype;
begin
  -- org + country + site scope re-check on the target case (raises if out of scope).
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  -- Capability gate: elevated OR the accident-owning capability.
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'edit')) then
    raise exception 'Not permitted to create an external portal link.' using errcode = '42501';
  end if;

  v_token := 'acp_' || encode(gen_random_bytes(18), 'hex');

  insert into public.accident_portal_shares
    (organisation_id, accident_id, token, password_hash, expires_at,
     active, created_by, created_at, view_count)
  values
    (v_org, p_accident_id, v_token,
     case
       when p_password is not null and btrim(p_password) <> ''
         then crypt(p_password, gen_salt('bf'))
       else null
     end,
     p_expires, true, auth.uid(), now(), 0)
  returning * into v_row;

  return jsonb_build_object('ok', true, 'id', v_row.id, 'token', v_token);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_portal_revoke(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_share public.accident_portal_shares%rowtype;
begin
  if p_id is null then
    raise exception 'A portal link id is required.' using errcode = '22023';
  end if;

  select * into v_share
    from public.accident_portal_shares
   where id = p_id;

  if v_share.id is null then
    raise exception 'Portal link % not found.', p_id using errcode = 'P0002';
  end if;

  -- org scope re-check (DEFINER bypasses RLS).
  if not ((v_share.organisation_id = public.app_current_org()) or public.is_super_admin()) then
    raise exception 'Not permitted for this organisation.' using errcode = '42501';
  end if;

  -- Capability gate: elevated OR the accident-owning capability.
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', 'edit')) then
    raise exception 'Not permitted to revoke an external portal link.' using errcode = '42501';
  end if;

  update public.accident_portal_shares
     set active = false
   where id = p_id
  returning * into v_share;

  return jsonb_build_object('ok', true, 'id', v_share.id, 'active', v_share.active);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_recovery_record(p_accident_id uuid, p_source text, p_amount numeric, p_status text, p_recovered_at date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_source  text := lower(btrim(coalesce(p_source, '')));
  v_status  text := lower(btrim(coalesce(p_status, '')));
  v_row     public.accident_claim_recoveries%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'post_cost')) then
    raise exception 'Not permitted to record a recovery.' using errcode = '42501';
  end if;

  if v_source <> all (array['insurer','third_party','driver','other']) then
    raise exception 'Invalid recovery source "%".', p_source using errcode = '22023';
  end if;

  if v_status <> all (array[
       'pending','in_progress','partial','recovered','written_off','not_applicable']) then
    raise exception 'Invalid recovery status "%".', p_status using errcode = '22023';
  end if;

  if p_amount is not null and p_amount < 0 then
    raise exception 'Recovery amount cannot be negative.' using errcode = '22023';
  end if;

  -- A recovery marked recovered must carry the date it was recovered (evidence).
  if v_status = 'recovered' and p_recovered_at is null then
    raise exception 'A recovered date is required to mark a recovery as recovered.'
      using errcode = '22023';
  end if;

  insert into public.accident_claim_recoveries
    (organisation_id, accident_id, country, site, source, amount, status,
     recovered_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_source, p_amount, v_status,
     p_recovered_at, auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'recovery', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_complete(p_repair_order_id uuid, p_actual_completion date, p_approved_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org        uuid;
  v_country    text;
  v_site       text;
  v_ro         public.accident_repair_orders%rowtype;
  v_qc_required boolean := true;
  v_has_pass   boolean;
  v_row        public.accident_repair_orders%rowtype;
begin
  if p_repair_order_id is null then
    raise exception 'A repair order is required.' using errcode = '22023';
  end if;
  if p_actual_completion is null then
    raise exception 'An actual completion date is required.' using errcode = '22023';
  end if;

  select * into v_ro from public.accident_repair_orders where id = p_repair_order_id;
  if v_ro.id is null then
    raise exception 'Repair order % not found.', p_repair_order_id using errcode = 'P0002';
  end if;

  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_ro.accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'execute_repair')) then
    raise exception 'Not permitted to complete this repair order.' using errcode = '42501';
  end if;

  if v_ro.status = 'cancelled' then
    raise exception 'A cancelled repair order cannot be completed.' using errcode = '42501';
  end if;
  if v_ro.status = 'completed' then
    return jsonb_build_object('ok', true, 'repair_order', to_jsonb(v_ro), 'unchanged', true);
  end if;
  if p_approved_amount is not null and p_approved_amount < 0 then
    raise exception 'Approved amount cannot be negative.' using errcode = '22023';
  end if;

  -- Is QC required for this case? Waived only when the workshop_qc workstream is
  -- explicitly switched off (mirrors the engine's workshop_qc gate).
  select not (ws.status = 'not_required' or ws.not_applicable)
    into v_qc_required
    from public.accident_case_workstreams ws
   where ws.accident_id = v_ro.accident_id
     and ws.workstream_key = 'workshop_qc';
  v_qc_required := coalesce(v_qc_required, true);

  if v_qc_required then
    select exists (
      select 1 from public.accident_repair_quality_checks q
       where q.repair_order_id = p_repair_order_id
         and q.result = 'pass'
    ) into v_has_pass;

    if not v_has_pass then
      raise exception
        'Repair cannot be completed: a passing quality check is required.'
        using errcode = '42501';
    end if;
  end if;

  update public.accident_repair_orders set
     status            = 'completed',
     actual_completion = p_actual_completion,
     approved_amount   = coalesce(p_approved_amount, approved_amount),
     approved_by       = case when p_approved_amount is not null then auth.uid() else approved_by end,
     approved_at       = case when p_approved_amount is not null then now() else approved_at end,
     updated_at        = now()
   where id = p_repair_order_id
  returning * into v_row;

  return jsonb_build_object('ok', true, 'repair_order', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_occurred(p_case jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare rt text := lower(public._acc_str(p_case -> 'repair_type'));
begin
  if public._acc_truthy(p_case -> 'no_repair')
     or rt in ('none','no repair','temporary') then return false; end if;
  if rt in ('internal','external') then return true; end if;
  if coalesce(public._acc_num(p_case -> 'repair_cost'), 0) > 0 then return true; end if;
  if coalesce(public._acc_num(p_case -> 'approved_repair_amount'), 0) > 0 then return true; end if;
  return public._acc_truthy(p_case -> 'repair_started');
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_order_upsert(p_accident_id uuid, p_repair_route text, p_workshop_type text, p_workshop_name text, p_quotation_amount numeric DEFAULT NULL::numeric, p_planned_completion date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_country  text;
  v_site     text;
  v_route    text := nullif(btrim(coalesce(p_repair_route, '')), '');
  v_wtype    text := nullif(btrim(coalesce(p_workshop_type, '')), '');
  v_wname    text := nullif(btrim(coalesce(p_workshop_name, '')), '');
  v_existing uuid;
  v_row      public.accident_repair_orders%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'execute_repair')) then
    raise exception 'Not permitted to open a repair order on this case.' using errcode = '42501';
  end if;

  if v_route is not null and v_route <> all (array[
       'none','temporary','internal','external','insurer_approved','dealer','specialist',
       'replacement','total_loss','disposal','under_review']) then
    raise exception 'Invalid repair route "%".', p_repair_route using errcode = '22023';
  end if;

  if v_wtype is not null and v_wtype <> all (array[
       'internal','external','insurer_approved','dealer','specialist']) then
    raise exception 'Invalid workshop type "%".', p_workshop_type using errcode = '22023';
  end if;

  if p_quotation_amount is not null and p_quotation_amount < 0 then
    raise exception 'Quotation amount cannot be negative.' using errcode = '22023';
  end if;

  -- Latest OPEN repair order for this case, if any (repair is one workstream).
  select id into v_existing
    from public.accident_repair_orders
   where accident_id = p_accident_id
     and status not in ('completed', 'cancelled')
   order by created_at desc, id desc
   limit 1;

  if v_existing is not null then
    update public.accident_repair_orders set
       repair_route     = coalesce(v_route, repair_route),
       workshop_type    = coalesce(v_wtype, workshop_type),
       workshop_name    = coalesce(v_wname, workshop_name),
       quotation_amount = coalesce(p_quotation_amount, quotation_amount),
       planned_completion = coalesce(p_planned_completion, planned_completion),
       updated_at       = now()
     where id = v_existing
    returning * into v_row;
  else
    insert into public.accident_repair_orders
      (organisation_id, accident_id, country, site, repair_route, workshop_type,
       workshop_name, quotation_amount, planned_completion, status,
       recommended_by, created_by, created_at, updated_at)
    values
      (v_org, p_accident_id, v_country, v_site, v_route, v_wtype,
       v_wname, p_quotation_amount, p_planned_completion, 'planned',
       auth.uid(), auth.uid(), now(), now())
    returning * into v_row;
  end if;

  return jsonb_build_object('ok', true, 'repair_order', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_qc(p_repair_order_id uuid, p_result text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_ro      public.accident_repair_orders%rowtype;
  v_result  text := lower(btrim(coalesce(p_result, '')));
  v_row     public.accident_repair_quality_checks%rowtype;
begin
  if p_repair_order_id is null then
    raise exception 'A repair order is required.' using errcode = '22023';
  end if;

  select * into v_ro from public.accident_repair_orders where id = p_repair_order_id;
  if v_ro.id is null then
    raise exception 'Repair order % not found.', p_repair_order_id using errcode = 'P0002';
  end if;

  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_ro.accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'qc_repair')) then
    raise exception 'Not permitted to record a quality check.' using errcode = '42501';
  end if;

  if v_result <> all (array['pass','fail','conditional']) then
    raise exception 'Invalid quality-check result "%".', p_result using errcode = '22023';
  end if;

  insert into public.accident_repair_quality_checks
    (organisation_id, accident_id, repair_order_id, country, site, inspector_id,
     inspected_at, result, remarks, created_by, created_at, updated_at)
  values
    (v_org, v_ro.accident_id, p_repair_order_id, v_country, v_site, auth.uid(),
     now(), v_result, nullif(btrim(coalesce(p_notes, '')), ''),
     auth.uid(), now(), now())
  returning * into v_row;

  -- Reflect the QC outcome onto the repair order (never marks it 'completed' - that
  -- is the deliberate accident_repair_complete action, which itself re-checks QC).
  update public.accident_repair_orders set
     status = case v_result
                when 'pass'        then 'qc_passed'
                when 'fail'        then 'qc_failed'
                when 'conditional' then 'qc_pending'
              end,
     updated_at = now()
   where id = p_repair_order_id;

  return jsonb_build_object(
    'ok', true,
    'quality_check', to_jsonb(v_row),
    'passed', (v_result = 'pass')
  );
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_task_add(p_repair_order_id uuid, p_title text, p_description text DEFAULT NULL::text, p_estimated_hours numeric DEFAULT NULL::numeric, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_ro      public.accident_repair_orders%rowtype;
  v_title   text := nullif(btrim(coalesce(p_title, '')), '');
  v_row     public.accident_repair_tasks%rowtype;
begin
  if p_repair_order_id is null then
    raise exception 'A repair order is required.' using errcode = '22023';
  end if;

  select * into v_ro from public.accident_repair_orders where id = p_repair_order_id;
  if v_ro.id is null then
    raise exception 'Repair order % not found.', p_repair_order_id using errcode = 'P0002';
  end if;

  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_ro.accident_id);

  if not (public.app_is_elevated() or public.app_user_can('accidents', 'execute_repair')) then
    raise exception 'Not permitted to add a repair task on this case.' using errcode = '42501';
  end if;

  if v_title is null then
    raise exception 'A task title is required.' using errcode = '22023';
  end if;
  if p_estimated_hours is not null and p_estimated_hours < 0 then
    raise exception 'Estimated hours cannot be negative.' using errcode = '22023';
  end if;

  insert into public.accident_repair_tasks
    (organisation_id, accident_id, repair_order_id, country, site, title, description,
     estimated_hours, assignee_id, assignee_name, status, created_by, created_at, updated_at)
  values
    (v_org, v_ro.accident_id, p_repair_order_id, v_country, v_site, v_title,
     nullif(btrim(coalesce(p_description, '')), ''),
     p_estimated_hours, p_assignee_id, nullif(btrim(coalesce(p_assignee_name, '')), ''),
     case when p_assignee_id is not null then 'assigned' else 'open' end,
     auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'task', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_repair_task_complete(p_task_id uuid, p_actual_hours numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_task    public.accident_repair_tasks%rowtype;
  v_uid     uuid := auth.uid();
begin
  if p_task_id is null then
    raise exception 'A task is required.' using errcode = '22023';
  end if;

  select * into v_task from public.accident_repair_tasks where id = p_task_id;
  if v_task.id is null then
    raise exception 'Task % not found.', p_task_id using errcode = 'P0002';
  end if;

  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(v_task.accident_id);

  if not (public.app_is_elevated()
          or (v_task.assignee_id is not null and v_task.assignee_id = v_uid)
          or public.app_user_can('accidents', 'execute_repair')) then
    raise exception 'Not permitted to complete this repair task.' using errcode = '42501';
  end if;

  if p_actual_hours is not null and p_actual_hours < 0 then
    raise exception 'Actual hours cannot be negative.' using errcode = '22023';
  end if;

  if v_task.status in ('completed', 'cancelled') then
    return jsonb_build_object('ok', true, 'task', to_jsonb(v_task), 'unchanged', true);
  end if;

  update public.accident_repair_tasks set
     status      = 'completed',
     actual_hours = coalesce(p_actual_hours, actual_hours),
     description = case
                     when nullif(btrim(coalesce(p_note, '')), '') is not null
                       then coalesce(description, '') ||
                            case when coalesce(description, '') = '' then '' else E'\n' end ||
                            btrim(p_note)
                     else description
                   end,
     updated_at  = now()
   where id = p_task_id
  returning * into v_task;

  return jsonb_build_object('ok', true, 'task', to_jsonb(v_task));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_request_closure(p_accident_id uuid, p_level text, p_remarks text DEFAULT NULL::text, p_reviewer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_level   text := lower(btrim(coalesce(p_level, '')));
  v_row     public.accident_closure_reviews%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if v_level <> all (array['operationally_completed','financially_open','fully_closed']) then
    raise exception 'Invalid closure level "%".', p_level using errcode = '22023';
  end if;

  if v_level = 'fully_closed' then
    if not (public.app_is_elevated() or public.app_user_can('accidents', 'close_case')) then
      raise exception 'Not permitted to request full closure.' using errcode = '42501';
    end if;
  else
    if not (public.app_is_elevated()
            or public.app_user_can('accidents', 'close_case')
            or public.app_user_can('accidents', 'submit')) then
      raise exception 'Not permitted to request closure review.' using errcode = '42501';
    end if;
  end if;

  insert into public.accident_closure_reviews
    (organisation_id, accident_id, country, site, level, reviewer_id, decision,
     blockers, remarks, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, v_level, p_reviewer_id, 'returned',
     '[]'::jsonb, nullif(btrim(coalesce(p_remarks, '')), ''),
     auth.uid(), now(), now())
  returning * into v_row;

  return jsonb_build_object('ok', true, 'review', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_required_workstreams(p_route text, p_case jsonb, p_profile jsonb DEFAULT NULL::jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_route text; v_req text[];
begin
  if p_profile is not null and (p_profile ? 'required_workstreams')
     and jsonb_typeof(p_profile -> 'required_workstreams') = 'array' then
    return array(
      select k from jsonb_array_elements_text(p_profile -> 'required_workstreams') as k
      where public.accident_workstream_stage(k) is not null
    );
  end if;

  v_route := coalesce(nullif(btrim(p_route), ''), 'standard');
  if v_route not in ('standard','minor_no_insurance','internal_repair_insurance',
                     'external_repair_insurance','total_loss','injury') then
    v_route := 'standard';
  end if;

  v_req := case v_route
    when 'minor_no_insurance' then
      array['incident_evidence','fleet_validation','liability','assessment','repair','handover','finance']
    when 'internal_repair_insurance' then
      array['incident_evidence','fleet_validation','liability','insurance','assessment','repair','workshop_qc','handover','finance']
    when 'external_repair_insurance' then
      array['incident_evidence','fleet_validation','liability','insurance','assessment','repair','workshop_qc','handover','finance']
    when 'total_loss' then
      array['incident_evidence','fleet_validation','liability','insurance','assessment','finance']
    when 'injury' then
      array['incident_evidence','fleet_validation','liability','insurance','corrective','finance']
    else
      array['incident_evidence','fleet_validation','liability','assessment','repair','handover','finance']
  end;

  if v_route = 'standard' and public.accident_repair_occurred(p_case) then
    v_req := public._acc_arr_add(v_req, 'workshop_qc');
  end if;
  if v_route in ('standard','minor_no_insurance','internal_repair_insurance',
                 'external_repair_insurance','total_loss')
     and public.accident_corrective_required(p_case) then
    v_req := public._acc_arr_add(v_req, 'corrective');
  end if;
  if v_route = 'injury' and public.accident_repair_occurred(p_case) then
    v_req := public._acc_arr_add(v_req, 'assessment');
    v_req := public._acc_arr_add(v_req, 'repair');
    v_req := public._acc_arr_add(v_req, 'workshop_qc');
    v_req := public._acc_arr_add(v_req, 'handover');
  end if;
  return v_req;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_rule_matches(p_rule jsonb, p_case jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p_rule is null then return false; end if;
  if (p_rule -> 'active') = 'false'::jsonb then return false; end if;
  if not public._acc_rule_eq(p_rule -> 'country',       p_case -> 'country')       then return false; end if;
  if not public._acc_rule_eq(p_rule -> 'accident_type', p_case -> 'accident_type') then return false; end if;
  if not public._acc_rule_eq(p_rule -> 'severity',      p_case -> 'severity')      then return false; end if;
  if not public._acc_rule_eq(p_rule -> 'vehicle_type',  p_case -> 'vehicle_type')  then return false; end if;
  if public._acc_present(p_rule -> 'insurance_involved')
     and (public._acc_truthy(p_rule -> 'insurance_involved') <> public.accident_insurance_involved(p_case))
     then return false; end if;
  if public._acc_present(p_rule -> 'injury_involved')
     and (public._acc_truthy(p_rule -> 'injury_involved') <> public.accident_is_injury(p_case))
     then return false; end if;
  if public._acc_present(p_rule -> 'third_party_involved')
     and (public._acc_truthy(p_rule -> 'third_party_involved') <> public._acc_truthy(p_case -> 'third_party_involved'))
     then return false; end if;
  return true;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_severity_label(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p WHEN 'minor' THEN 'Minor' WHEN 'moderate' THEN 'Moderate'
                WHEN 'severe' THEN 'Major' WHEN 'fatal' THEN 'Fatal' ELSE COALESCE(p,'-') END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_sla_pause(p_instance_id uuid, p_reason text, p_expected_resume_at timestamp with time zone, p_comments text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_i   record;
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  if p_expected_resume_at is null then
    raise exception 'A pause requires an expected resume date.'
      using errcode = '22023';
  end if;

  select si.* into v_i
  from public.accident_sla_instances si
  where si.id = p_instance_id
    and (si.organisation_id = v_org or public.is_super_admin())
  for update;

  if not found then
    raise exception 'SLA timer not found in your organisation.'
      using errcode = 'P0002';
  end if;

  if v_i.state <> 'running' then
    raise exception 'Only a running SLA timer can be paused (current state: %).', v_i.state
      using errcode = '22023';
  end if;

  -- The pause event carries the reason + expected_resume_at (CHECK-constrained
  -- reason vocabulary lives on the table). This is the audit trail of WHY the
  -- clock stopped (waiting_external et al).
  insert into public.accident_sla_pause_events (
    organisation_id, accident_id, sla_instance_id, country, site,
    reason, comments, paused_at, expected_resume_at, paused_by
  )
  values (
    v_i.organisation_id, v_i.accident_id, v_i.id, v_i.country, v_i.site,
    p_reason, p_comments, now(), p_expected_resume_at, auth.uid()
  );

  update public.accident_sla_instances
     set state = 'paused',
         paused = true,
         updated_at = now()
   where id = v_i.id;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_sla_resume(p_instance_id uuid, p_comments text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org        uuid := public.app_current_org();
  v_i          record;
  v_pause      record;
  v_now        timestamptz := now();
  v_paused_min integer;
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select si.* into v_i
  from public.accident_sla_instances si
  where si.id = p_instance_id
    and (si.organisation_id = v_org or public.is_super_admin())
  for update;

  if not found then
    raise exception 'SLA timer not found in your organisation.'
      using errcode = 'P0002';
  end if;

  if v_i.state <> 'paused' then
    raise exception 'Only a paused SLA timer can be resumed (current state: %).', v_i.state
      using errcode = '22023';
  end if;

  -- Close the open pause window (the latest one with no resumed_at). If for some
  -- reason none is open, resume anyway rather than trapping the timer paused.
  select pe.* into v_pause
  from public.accident_sla_pause_events pe
  where pe.sla_instance_id = v_i.id
    and pe.resumed_at is null
  order by pe.paused_at desc
  limit 1;

  if found then
    v_paused_min := greatest(0, ceil(extract(epoch from (v_now - v_pause.paused_at)) / 60.0)::int);
    update public.accident_sla_pause_events
       set resumed_at = v_now,
           comments   = coalesce(p_comments, comments),
           updated_at = now()
     where id = v_pause.id;
  else
    v_paused_min := 0;
  end if;

  -- Shift every future target forward by the paused duration so the elapsed clock
  -- excludes the pause. total_paused_minutes accumulates for reporting.
  update public.accident_sla_instances
     set state = 'running',
         paused = false,
         total_paused_minutes = total_paused_minutes + v_paused_min,
         due_at        = due_at        + make_interval(mins => v_paused_min),
         warning_at    = case when warning_at    is not null then warning_at    + make_interval(mins => v_paused_min) else warning_at end,
         escalation_at = case when escalation_at is not null then escalation_at + make_interval(mins => v_paused_min) else escalation_at end,
         updated_at = now()
   where id = v_i.id;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_sla_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now      timestamptz := now();
  v_warned   integer := 0;
  v_breached integer := 0;
  r          record;
begin
  -- 1. Flip genuinely-overdue RUNNING timers to breached. Only running + not paused
  --    + not already breached are eligible - a paused or terminal timer is never
  --    touched. warning_at may be null (business_hours=false definitions); the
  --    warning branch below guards for that.
  update public.accident_sla_instances si
     set state         = 'breached',
         breached       = true,
         breached_at    = coalesce(si.breached_at, v_now),
         breach_minutes = greatest(0, ceil(extract(epoch from (v_now - si.due_at)) / 60.0)::int),
         updated_at     = v_now
   where si.state = 'running'
     and si.paused = false
     and si.breached = false
     and si.due_at is not null
     and si.due_at < v_now;

  -- 2. Mark a warning on running timers past their warning threshold but not yet
  --    breached. This is separate state bookkeeping used only to fire the warning
  --    notice once; it does NOT change the 'running' state.
  for r in
    select si.id, si.accident_id, si.organisation_id, si.sla_key, si.name,
           si.workstream_key, si.team, si.due_at, si.warning_at, si.target_minutes
    from public.accident_sla_instances si
    where si.state = 'running'
      and si.paused = false
      and si.warned_notified = false
      and si.warning_at is not null
      and si.warning_at < v_now
  loop
    perform public.emit_domain_event(
      'accident.sla_warning', 'accident', r.accident_id::text,
      jsonb_build_object(
        'sla_instance_id', r.id,
        'sla_key', r.sla_key,
        'name', r.name,
        'workstream_key', r.workstream_key,
        'team', r.team,
        'due_at', r.due_at,
        'level', 1
      ),
      r.organisation_id, null);

    update public.accident_sla_instances
       set warned_notified = true,
           warned_at = coalesce(warned_at, v_now),
           updated_at = v_now
     where id = r.id;

    v_warned := v_warned + 1;
  end loop;

  -- 3. Emit one breach notice per newly-breached timer (structural once-only via
  --    breached_notified). A timer breached in step 1 above, or already breached on
  --    a prior run but never notified (e.g. a mid-flight failure), is caught here.
  for r in
    select si.id, si.accident_id, si.organisation_id, si.sla_key, si.name,
           si.workstream_key, si.team, si.due_at, si.breach_minutes
    from public.accident_sla_instances si
    where si.state = 'breached'
      and si.breached = true
      and si.breached_notified = false
  loop
    perform public.emit_domain_event(
      'accident.sla_breach', 'accident', r.accident_id::text,
      jsonb_build_object(
        'sla_instance_id', r.id,
        'sla_key', r.sla_key,
        'name', r.name,
        'workstream_key', r.workstream_key,
        'team', r.team,
        'due_at', r.due_at,
        'breach_minutes', r.breach_minutes,
        'level', 2
      ),
      r.organisation_id, null);

    update public.accident_sla_instances
       set breached_notified = true,
           updated_at = v_now
     where id = r.id;

    v_breached := v_breached + 1;
  end loop;

  return jsonb_build_object(
    'scanned_at', v_now,
    'warned', v_warned,
    'breached', v_breached);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_sla_start(p_accident_id uuid, p_workstream_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid := public.app_current_org();
  v_country  text;
  v_site     text;
  v_created  integer := 0;
  d          record;
  v_start    timestamptz := now();
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  if p_accident_id is null or coalesce(btrim(p_workstream_key), '') = '' then
    raise exception 'accident id and workstream key are required.'
      using errcode = '22023';
  end if;

  -- The case must belong to the caller org (or a super admin). country / site are
  -- denormalized onto every case-scoped row from the parent accident.
  select a.country, a.site
    into v_country, v_site
  from public.accidents a
  where a.id = p_accident_id
    and (a.organisation_id = v_org or public.is_super_admin());

  if not found then
    raise exception 'Accident not found in your organisation.'
      using errcode = 'P0002';
  end if;

  -- One instance per active definition matching this workstream. Skip a definition
  -- that already has a live (running / paused) timer on this case so re-entering a
  -- workstream never double-counts the clock.
  for d in
    select sd.*
    from public.accident_sla_definitions sd
    where sd.organisation_id = v_org
      and sd.active
      and sd.workstream_key = p_workstream_key
  loop
    if exists (
      select 1 from public.accident_sla_instances si
      where si.accident_id = p_accident_id
        and si.sla_key = d.sla_key
        and si.state in ('running', 'paused')
    ) then
      continue;
    end if;

    insert into public.accident_sla_instances (
      organisation_id, accident_id, country, site,
      sla_key, sla_definition_id, name, workstream_key,
      team, start_at, target_minutes, due_at, warning_at, escalation_at,
      state, paused
    )
    values (
      v_org, p_accident_id, v_country, v_site,
      d.sla_key, d.id, d.name, d.workstream_key,
      d.responsible_team, v_start, d.target_minutes,
      v_start + make_interval(mins => d.target_minutes),
      v_start + make_interval(mins => greatest(0, round(d.target_minutes * coalesce(d.warning_pct, 80) / 100.0))::int),
      v_start + make_interval(mins => greatest(0, round(d.target_minutes * coalesce(d.escalation_pct, 100) / 100.0))::int),
      'running', false
    );

    v_created := v_created + 1;
  end loop;

  return v_created;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_stage_department(p_stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_stage
    when 'reported'            then 'Site Management'
    when 'initial_review'      then 'Operations'
    when 'hse_investigation'   then 'HSE / Safety'
    when 'workshop_assessment' then 'Workshop'
    when 'insurance_claim'     then 'Insurance'
    when 'repair_approval'     then 'Fleet / PMV'
    when 'repair_in_progress'  then 'Workshop'
    when 'final_inspection'    then 'Workshop'
    when 'vehicle_release'     then 'Operations'
    when 'cost_recovery'       then 'Finance'
    when 'closed'              then 'Site Management'
    when 'cancelled'           then 'Operations'
    else null end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_stage_from_status(p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_status
    WHEN 'reported'           THEN 'reported'
    WHEN 'under_review'       THEN 'initial_review'
    WHEN 'awaiting_approval'  THEN 'repair_approval'
    WHEN 'awaiting_parts'     THEN 'repair_in_progress'
    WHEN 'repair_in_progress' THEN 'repair_in_progress'
    WHEN 'insurance_claim'    THEN 'insurance_claim'
    WHEN 'released'           THEN 'vehicle_release'
    WHEN 'closed'             THEN 'closed'
    ELSE 'reported' END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_stage_label(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p
    WHEN 'reported' THEN 'Reported'
    WHEN 'initial_review' THEN 'Initial Review'
    WHEN 'hse_investigation' THEN 'HSE Investigation'
    WHEN 'workshop_assessment' THEN 'Workshop Assessment'
    WHEN 'insurance_claim' THEN 'Insurance Claim'
    WHEN 'repair_approval' THEN 'Repair Approval'
    WHEN 'repair_in_progress' THEN 'Repair In Progress'
    WHEN 'final_inspection' THEN 'Final Inspection'
    WHEN 'vehicle_release' THEN 'Vehicle Release'
    WHEN 'cost_recovery' THEN 'Cost Recovery'
    WHEN 'closed' THEN 'Closed'
    WHEN 'cancelled' THEN 'Cancelled'
    ELSE COALESCE(p,'-') END;
$function$;
