CREATE OR REPLACE FUNCTION public.accident_status_from_stage(p_stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_stage
    WHEN 'reported'            THEN 'reported'
    WHEN 'initial_review'      THEN 'under_review'
    WHEN 'hse_investigation'   THEN 'under_review'
    WHEN 'workshop_assessment' THEN 'under_review'
    WHEN 'insurance_claim'     THEN 'insurance_claim'
    WHEN 'repair_approval'     THEN 'awaiting_approval'
    WHEN 'repair_in_progress'  THEN 'repair_in_progress'
    WHEN 'final_inspection'    THEN 'repair_in_progress'
    WHEN 'vehicle_release'     THEN 'released'
    WHEN 'cost_recovery'       THEN 'released'
    WHEN 'closed'              THEN 'closed'
    WHEN 'cancelled'           THEN 'closed'
    ELSE 'reported' END;
$function$;
