 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array['not_required','not_started','assigned','in_progress','waiting_info',
               'waiting_approval','waiting_external','on_hold','completed','rejected',
               'reopened','cancelled'];
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_ws_assign(p_accident_id uuid, p_workstream_key text, p_owner_id uuid, p_owner_role text DEFAULT NULL::text, p_team text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_cap     text;
  v_row     public.accident_case_workstreams%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if p_workstream_key is null or p_workstream_key <> all (array[
       'incident_evidence','fleet_validation','liability','insurance','assessment',
       'repair','workshop_qc','handover','finance','corrective']) then
    raise exception 'Unknown workstream "%".', p_workstream_key using errcode = '22023';
  end if;

  v_cap := coalesce(public._accident_ws_cap(p_workstream_key), 'validate');
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', v_cap)
          or public.app_user_can('accidents', 'validate')) then
    raise exception 'Not permitted to assign this workstream.' using errcode = '42501';
  end if;

  insert into public.accident_case_workstreams
    (organisation_id, accident_id, country, site, workstream_key, status,
     owner_id, owner_role, team, assigned_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, p_workstream_key, 'assigned',
     p_owner_id, nullif(btrim(coalesce(p_owner_role, '')), ''),
     nullif(btrim(coalesce(p_team, '')), ''), now(), auth.uid(), now(), now())
  on conflict (accident_id, workstream_key) do update set
     owner_id    = excluded.owner_id,
     owner_role  = coalesce(excluded.owner_role, public.accident_case_workstreams.owner_role),
     team        = coalesce(excluded.team, public.accident_case_workstreams.team),
     assigned_at = coalesce(public.accident_case_workstreams.assigned_at, now()),
     status      = case
                     when public.accident_case_workstreams.status in ('not_started')
                       then 'assigned'
                     else public.accident_case_workstreams.status
                   end,
     updated_at  = now()
  returning * into v_row;

  return jsonb_build_object('ok', true, 'workstream', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_ws_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_action text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'created';
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_action := CASE
      WHEN NEW.status = 'not_required' THEN 'na_marked'
      WHEN OLD.status = 'completed' AND NEW.status <> 'completed' THEN 'reopened'
      ELSE 'status_changed' END;
  ELSIF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    v_action := 'assigned';
  ELSE
    RETURN NEW;  -- nothing audit-worthy changed
  END IF;

  INSERT INTO public.accident_case_workstream_events
    (organisation_id, accident_id, country, site, workstream_key, action,
     from_status, to_status, from_owner, to_owner, note, actor_id, at)
  VALUES
    (NEW.organisation_id, NEW.accident_id, NEW.country, NEW.site, NEW.workstream_key, v_action,
     CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END, NEW.status,
     CASE WHEN TG_OP = 'UPDATE' THEN OLD.owner_id END, NEW.owner_id,
     NEW.na_reason, COALESCE(auth.uid(), NEW.updated_by, NEW.created_by), now());
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_ws_mark_na(p_accident_id uuid, p_workstream_key text, p_reason text, p_approved_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_cap     text;
  v_reason  text := nullif(btrim(coalesce(p_reason, '')), '');
  v_row     public.accident_case_workstreams%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if p_workstream_key is null or p_workstream_key <> all (array[
       'incident_evidence','fleet_validation','liability','insurance','assessment',
       'repair','workshop_qc','handover','finance','corrective']) then
    raise exception 'Unknown workstream "%".', p_workstream_key using errcode = '22023';
  end if;

  if p_workstream_key = any (array['incident_evidence','liability','finance']) then
    raise exception
      'Workstream "%" is mandatory and cannot be marked not applicable.', p_workstream_key
      using errcode = '42501';
  end if;

  if v_reason is null then
    raise exception 'A reason is required to mark a workstream not applicable.'
      using errcode = '22023';
  end if;

  if p_approved_by is null then
    raise exception 'An approver is required to mark a workstream not applicable.'
      using errcode = '42501';
  end if;

  v_cap := coalesce(public._accident_ws_cap(p_workstream_key), 'validate');
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', v_cap)
          or public.app_user_can('accidents', 'validate')) then
    raise exception 'Not permitted to waive this workstream.' using errcode = '42501';
  end if;

  insert into public.accident_case_workstreams
    (organisation_id, accident_id, country, site, workstream_key, status, required,
     not_applicable, na_reason, na_by, na_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, p_workstream_key, 'not_required', false,
     true, v_reason, auth.uid(), now(), auth.uid(), now(), now())
  on conflict (accident_id, workstream_key) do update set
     status         = 'not_required',
     required       = false,
     not_applicable = true,
     na_reason      = excluded.na_reason,
     na_by          = excluded.na_by,
     na_at          = now(),
     updated_at     = now()
  returning * into v_row;

  insert into public.accident_case_approvals
    (organisation_id, accident_id, country, site, approval_type, workstream_key,
     requested_by, requested_at, decided_by, decided_at, decision, reason,
     created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, 'na_waiver', p_workstream_key,
     auth.uid(), now(), p_approved_by, now(), 'approved', v_reason,
     auth.uid(), now(), now());

  return jsonb_build_object('ok', true, 'workstream', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_ws_set_status(p_accident_id uuid, p_workstream_key text, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_country text;
  v_site    text;
  v_cap     text;
  v_status  text := lower(btrim(coalesce(p_status, '')));
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_row     public.accident_case_workstreams%rowtype;
begin
  select org, country, site
    into v_org, v_country, v_site
    from public._accident_rpc_context(p_accident_id);

  if p_workstream_key is null or p_workstream_key <> all (array[
       'incident_evidence','fleet_validation','liability','insurance','assessment',
       'repair','workshop_qc','handover','finance','corrective']) then
    raise exception 'Unknown workstream "%".', p_workstream_key using errcode = '22023';
  end if;

  if v_status <> all (array[
       'not_required','not_started','assigned','in_progress','waiting_info',
       'waiting_approval','waiting_external','on_hold','completed','rejected',
       'reopened','cancelled']) then
    raise exception 'Invalid workstream status "%".', p_status using errcode = '22023';
  end if;

  v_cap := coalesce(public._accident_ws_cap(p_workstream_key), 'validate');
  if not (public.app_is_elevated()
          or public.app_user_can('accidents', v_cap)
          or public.app_user_can('accidents', 'validate')) then
    raise exception 'Not permitted to update this workstream.' using errcode = '42501';
  end if;

  insert into public.accident_case_workstreams
    (organisation_id, accident_id, country, site, workstream_key, status, notes,
     assigned_at, started_at, completed_at, created_by, created_at, updated_at)
  values
    (v_org, p_accident_id, v_country, v_site, p_workstream_key, v_status, v_note,
     case when v_status = 'assigned'    then now() end,
     case when v_status = 'in_progress' then now() end,
     case when v_status = 'completed'   then now() end,
     auth.uid(), now(), now())
  on conflict (accident_id, workstream_key) do update set
     status       = excluded.status,
     notes        = coalesce(excluded.notes, public.accident_case_workstreams.notes),
     assigned_at  = coalesce(public.accident_case_workstreams.assigned_at, excluded.assigned_at),
     started_at   = coalesce(public.accident_case_workstreams.started_at, excluded.started_at),
     completed_at = case
                      when excluded.status = 'completed'
                        then coalesce(public.accident_case_workstreams.completed_at, now())
                      else public.accident_case_workstreams.completed_at
                    end,
     updated_at   = now()
  returning * into v_row;

  return jsonb_build_object('ok', true, 'workstream', to_jsonb(v_row));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_ws_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
  IF NEW.owner_id IS NOT NULL AND NEW.assigned_at IS NULL THEN
    NEW.assigned_at := now();
  END IF;
  IF NEW.status IS NOT NULL
     AND NEW.status NOT IN ('not_started', 'not_required')
     AND NEW.started_at IS NULL THEN
    NEW.started_at := now();
  END IF;
  IF NEW.status = 'completed' THEN
    IF NEW.completed_at IS NULL THEN NEW.completed_at := now(); END IF;
  ELSE
    NEW.completed_at := NULL;
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ack_trust_alert(p_id bigint, p_status text DEFAULT 'resolved'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if p_status not in ('open','ack','resolved') then raise exception 'bad status'; end if;
  update public.trust_alerts set status=p_status, acked_by=auth.uid(), acked_at=now()
   where id=p_id and organisation_id=v_org;
  if not found then raise exception 'alert not found'; end if;
  return json_build_object('ok',true,'id',p_id,'status',p_status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.action_item_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_allowed boolean;
  v_role text;
begin
  if tg_op = 'UPDATE' and new.organisation_id is distinct from old.organisation_id then
    raise exception 'organisation_id is immutable' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' then
    if auth.uid() is not null then
      new.organisation_id := public.app_current_org();
    else
      new.organisation_id := coalesce(public.app_current_org(), new.organisation_id);
    end if;
    if new.organisation_id is null then
      raise exception 'An organisation membership is required' using errcode = '42501';
    end if;
    return new;
  end if;

  if new.status is not distinct from old.status and
     (new.approval_status is distinct from old.approval_status or
      new.approval_requested_at is distinct from old.approval_requested_at or
      new.approval_requested_by is distinct from old.approval_requested_by or
      new.approved_at is distinct from old.approved_at or
      new.approved_by is distinct from old.approved_by or
      new.completed_at is distinct from old.completed_at or
      new.escalated_at is distinct from old.escalated_at or
      new.escalated_by is distinct from old.escalated_by) then
    raise exception 'Lifecycle audit fields may only change through a status transition'
      using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    v_allowed := case old.status
      when 'open' then new.status in ('acknowledged','in_progress','blocked','escalated','dismissed')
      when 'acknowledged' then new.status in ('open','in_progress','blocked','escalated','dismissed')
      when 'in_progress' then new.status in ('blocked','escalated','pending_approval','resolved','dismissed')
      when 'blocked' then new.status in ('in_progress','escalated','dismissed')
      when 'escalated' then new.status in ('in_progress','blocked','pending_approval','resolved','dismissed')
      when 'pending_approval' then new.status in ('in_progress','resolved','dismissed')
      when 'resolved' then new.status in ('open','in_progress')
      when 'dismissed' then new.status = 'open'
      else false end;
    if not v_allowed and new.status = 'open'
       and current_setting('tp.action_sync', true) = 'on' then
      v_allowed := true;
    end if;
    if not v_allowed then
      raise exception 'Invalid action item transition: % -> %', old.status, new.status
        using errcode = '23514';
    end if;

    if old.status = 'pending_approval' then
      v_role := public.get_my_role();
      if v_role not in ('Admin','Manager','Director') then
        raise exception 'Supervisor approval requires Admin, Manager, or Director role'
          using errcode = '42501';
      end if;
      if new.status in ('in_progress','dismissed') then
        new.approval_status := 'rejected';
      end if;
    end if;

    if new.status = 'escalated' then
      new.escalated_at := coalesce(new.escalated_at, now());
      new.escalated_by := coalesce(new.escalated_by, auth.uid());
    elsif new.status = 'pending_approval' then
      new.approval_status := 'pending';
      new.approval_requested_at := coalesce(new.approval_requested_at, now());
      new.approval_requested_by := coalesce(new.approval_requested_by, auth.uid());
    elsif new.status = 'resolved' then
      if old.status = 'pending_approval' then
        new.approval_status := 'approved';
        new.approved_at := coalesce(new.approved_at, now());
        new.approved_by := coalesce(new.approved_by, auth.uid());
      end if;
      new.completed_at := coalesce(new.completed_at, now());
    elsif old.status in ('resolved','dismissed') then
      new.completed_at := null;
      new.approval_status := 'not_required';
      new.approved_at := null;
      new.approved_by := null;
    end if;
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.action_item_record_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event text;
begin
  if tg_op = 'INSERT' then
    v_event := 'created';
  elsif new.status is distinct from old.status then
    v_event := case new.status
      when 'acknowledged' then 'acknowledged'
      when 'in_progress' then case when old.status = 'pending_approval' then 'rejected'
                                   when old.status in ('resolved','dismissed') then 'reopened' else 'started' end
      when 'blocked' then 'blocked'
      when 'escalated' then 'escalated'
      when 'pending_approval' then 'approval_requested'
      when 'resolved' then case when old.status = 'pending_approval' then 'approved' else 'resolved' end
      when 'dismissed' then 'dismissed'
      when 'open' then 'reopened'
      else 'updated' end;
  elsif new.assigned_user_id is distinct from old.assigned_user_id then
    v_event := 'assigned';
  else
    v_event := 'updated';
  end if;
  insert into public.action_item_history
    (organisation_id, action_item_id, actor_id, event_type, from_status, to_status, reason, metadata)
  values
    (new.organisation_id, new.id, auth.uid(), v_event,
     case when tg_op = 'UPDATE' then old.status end, new.status,
     coalesce(new.blocked_reason, new.escalated_reason, new.approval_note, new.resolution),
     jsonb_build_object('assigned_user_id', new.assigned_user_id, 'site', new.site,
                        'shift_id', new.shift_id, 'sla_due_at', new.sla_due_at));
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.add_release_impact(p_release uuid, p_asset text DEFAULT NULL::text, p_metric text DEFAULT NULL::text, p_impact text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.is_super_admin() or public.app_role()='Admin') then raise exception 'forbidden' using errcode='42501'; end if;
  insert into public.release_impacts (release_id, asset_id, metric_id, impact_type, note)
  values (p_release, p_asset, p_metric, p_impact, p_note);
  return json_build_object('ok',true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_accounts_without_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read sign-in accounts' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', u.id,
           'email_masked', public._mask_email(u.email),
           'created_at', u.created_at,
           'last_sign_in_at', u.last_sign_in_at
         ) order by u.created_at desc), '[]'::jsonb)
    into v
    from auth.users u
   where not exists (select 1 from public.profiles p where p.id = u.id);
  return jsonb_build_object('ok', true, 'accounts', v);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_app_flutter_adoption(p_app text DEFAULT 'flutter'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb;
  v_expo boolean;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read app adoption' using errcode = '42501';
  end if;
  if coalesce(p_app, 'flutter') not in ('flutter', 'expo') then
    raise exception 'Choose flutter or expo' using errcode = '22023';
  end if;
  v_expo := coalesce(p_app, 'flutter') = 'expo';

  with d as (
    select *
      from public.user_devices
     where not coalesce(revoked, false)
       and ((coalesce(push_token, '') like 'ExponentPushToken%' or coalesce(push_token, '') like 'ExpoPushToken%') = v_expo)
  )
  select jsonb_build_object(
    'ok', true,
    'app', coalesce(p_app, 'flutter'),
    'installs', (select count(*) from d),
    'active_7d', (select count(*) from d where last_seen_at >= now() - interval '7 days'),
    'by_version', coalesce((
      select jsonb_agg(jsonb_build_object('app_version', app_version, 'platform', platform,
                                          'installs', n, 'active_7d', a7, 'last_seen', ls)
                       order by n desc, app_version)
        from (select nullif(btrim(app_version), '') as app_version,
                     nullif(btrim(lower(platform)), '') as platform,
                     count(*) as n,
                     count(*) filter (where last_seen_at >= now() - interval '7 days') as a7,
                     max(last_seen_at) as ls
                from d
               group by 1, 2) s), '[]'::jsonb)
  ) into v;
  return v;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_app_version_adoption()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read app adoption' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'ok', true,
    'installs', (select count(*) from public.user_devices where not coalesce(revoked, false)),
    'active_7d', (select count(*) from public.user_devices where not coalesce(revoked, false) and last_seen_at >= now() - interval '7 days'),
    'by_version', coalesce((
      select jsonb_agg(jsonb_build_object('app_version', app_version, 'platform', platform,
                                          'installs', n, 'active_7d', a7, 'last_seen', ls)
                       order by n desc, app_version)
        from (select nullif(btrim(app_version), '') as app_version,
                     nullif(btrim(lower(platform)), '') as platform,
                     count(*) as n,
                     count(*) filter (where last_seen_at >= now() - interval '7 days') as a7,
                     max(last_seen_at) as ls
                from public.user_devices
               where not coalesce(revoked, false)
               group by 1, 2) s), '[]'::jsonb)
  ) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_apply_access_review(p_campaign uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text; r record; v_results jsonb := '[]'::jsonb; v_res text;
  v_summary jsonb; v_actor uuid := auth.uid(); v_actor_email text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  perform public._access_review_require_super();
  select status into v_status from public.access_review_campaigns where id = p_campaign for update;
  if v_status is null then raise exception 'Review not found.' using errcode = 'P0002'; end if;
  if v_status <> 'open' then raise exception 'This review is already closed.' using errcode = '22023'; end if;
  select email into v_actor_email from public.profiles where id = v_actor;

  for r in select * from public.access_review_items
            where campaign_id = p_campaign and decision = 'revoke' order by full_name loop
    if r.user_id = v_actor then
      v_res := 'refused: you cannot lock your own account';
    else
      begin
        update public.profiles set locked = true where id = r.user_id and coalesce(locked,false) = false;
        if found then
          v_res := 'locked';
          insert into public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
          values (v_actor, v_actor_email, 'access_review_revoke', r.user_id, 'profiles',
                  jsonb_build_object('locked', false),
                  jsonb_build_object('locked', true, 'campaign_id', p_campaign, 'item_id', r.id),
                  r.decision_note);
        elsif exists (select 1 from public.profiles where id = r.user_id) then
          v_res := 'already locked';
        else
          v_res := 'user no longer exists';
        end if;
      exception when others then
        v_res := 'refused: ' || sqlerrm;
      end;
    end if;
    update public.access_review_items set apply_result = v_res, applied_at = now() where id = r.id;
    v_results := v_results || jsonb_build_object('item', r.id, 'user_id', r.user_id, 'result', v_res);
  end loop;

  select jsonb_build_object(
           'total',    count(*),
           'kept',     count(*) filter (where decision = 'keep'),
           'revoked',  count(*) filter (where decision = 'revoke'),
           'modified', count(*) filter (where decision = 'modify'),
           'pending',  count(*) filter (where decision = 'pending'),
           'locked',   count(*) filter (where apply_result = 'locked'),
           'refused',  count(*) filter (where apply_result like 'refused%'))
    into v_summary from public.access_review_items where campaign_id = p_campaign;

  update public.access_review_campaigns
     set status = 'closed', closed_at = now(), closed_by = v_actor, summary = v_summary
   where id = p_campaign;

  return jsonb_build_object('ok', true, 'summary', v_summary, 'results', v_results);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_approve_flag_change(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.flag_changes;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can approve a flag change' using errcode = '42501';
  end if;
  select * into v from public.flag_changes where id = p_id for update;
  if v.id is null or v.status <> 'awaiting_approval' then
    raise exception 'This change is not waiting for approval.' using errcode = '22023';
  end if;
  if v.requested_by = auth.uid() then
    raise exception 'A second super admin must approve this change.' using errcode = '42501';
  end if;
  update public.flag_changes set status = 'scheduled', approved_by = auth.uid(), approved_at = now() where id = p_id;
  perform public.log_console_event('flag_change_approved', null, 'flag_change', jsonb_build_object('id', p_id));
  return jsonb_build_object('ok', true, 'id', p_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_archive_empty_org(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_hit boolean;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can archive an organization' using errcode = '42501';
  end if;
  perform 1 from public.organisations where id = p_org_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if exists (select 1 from public.profiles where org_id = p_org_id or organisation_id = p_org_id) then
    return jsonb_build_object('ok', false, 'reason', 'has_members');
  end if;
  for r in
    select c.table_name, c.data_type
      from information_schema.columns c
      join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public' and c.column_name = 'organisation_id'
       and t.table_type = 'BASE TABLE' and c.table_name not in ('organisations', 'profiles')
       and c.table_name !~ '(audit|_log$|_logs$|_log_|^system_logs$|_events$|^notifications$|_sessions$)'
  loop
    if r.data_type = 'uuid' then
      execute format('select exists (select 1 from public.%I where organisation_id = $1)', r.table_name)
        into v_hit using p_org_id;
    else
      execute format('select exists (select 1 from public.%I where organisation_id::text = $1)', r.table_name)
        into v_hit using p_org_id::text;
    end if;
    if v_hit then
      return jsonb_build_object('ok', false, 'reason', 'has_records', 'table', r.table_name);
    end if;
  end loop;
  update public.organisations set active = false where id = p_org_id;
  perform public.log_console_event('org_archive', null, 'organisation', jsonb_build_object('org_id', p_org_id));
  return jsonb_build_object('ok', true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_attest_control(p_control_id text, p_note text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_email text;
  v_id    uuid;
  v_ctrl  text := upper(btrim(coalesce(p_control_id, '')));
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can attest a control' using errcode = '42501';
  end if;
  if v_ctrl !~ '^[A-Z0-9][A-Z0-9_.-]{1,63}$' then
    raise exception 'A valid control id is required' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'An attestation needs a note (at least 3 characters)' using errcode = '22023';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'An attestation needs an expiry date in the future' using errcode = '22023';
  end if;
  if p_expires_at > now() + interval '400 days' then
    raise exception 'An attestation cannot last longer than 400 days' using errcode = '22023';
  end if;

  select email into v_email from auth.users where id = v_uid;

  insert into public.compliance_attestations (control_id, note, attested_by, attested_by_email, expires_at)
  values (v_ctrl, btrim(p_note), v_uid, v_email, p_expires_at)
  returning id into v_id;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'compliance_attest', v_id, 'compliance_attestation',
          jsonb_build_object('control_id', v_ctrl, 'expires_at', p_expires_at));

  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_bulk_set_grant(p_user_ids uuid[], p_module_key text, p_capability text, p_effect text, p_expires_at timestamp with time zone, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid; v_n integer := 0;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only a Super Admin can change access grants.' USING errcode = '42501'; END IF;
  IF COALESCE(p_effect, 'grant') NOT IN ('grant','revoke') THEN RAISE EXCEPTION 'effect must be grant or revoke.'; END IF;
  IF p_user_ids IS NULL THEN RETURN 0; END IF;
  FOREACH v_uid IN ARRAY p_user_ids LOOP
    PERFORM public.set_user_access_grant(v_uid, p_module_key, COALESCE(NULLIF(p_capability, ''), 'view'), COALESCE(p_effect, 'grant'), NULL, p_expires_at);
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_bulk_set_role(p_user_ids uuid[], p_role text, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid; v_n integer := 0; v_is_super boolean; v_super_cnt integer;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only a Super Admin can change roles.' USING errcode = '42501'; END IF;
  IF p_role IS NULL OR btrim(p_role) = '' THEN RAISE EXCEPTION 'role is required.'; END IF;
  IF p_user_ids IS NULL THEN RETURN 0; END IF;
  PERFORM public._consume_approval('admin_bulk_set_role', jsonb_build_object('role', p_role, 'user_ids', to_jsonb(p_user_ids)));
  SELECT count(*) INTO v_super_cnt FROM public.profiles WHERE COALESCE(is_super_admin, false) = true AND COALESCE(locked, false) = false;
  FOREACH v_uid IN ARRAY p_user_ids LOOP
    SELECT COALESCE(is_super_admin, false) INTO v_is_super FROM public.profiles WHERE id = v_uid;
    IF v_is_super IS TRUE AND (v_super_cnt <= 1 OR p_role <> 'Admin') THEN CONTINUE; END IF;
    UPDATE public.profiles SET role = p_role WHERE id = v_uid;
    IF FOUND THEN v_n := v_n + 1; END IF;
  END LOOP;
  RETURN v_n;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cancel_approval(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.console_approval_requests%rowtype;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select * into r from public.console_approval_requests where id = p_id for update;
  if not found then raise exception 'Approval request not found.' using errcode = '22023'; end if;
  if r.requested_by <> auth.uid() then
    raise exception 'Only the person who asked can cancel a request.' using errcode = '42501';
  end if;
  if r.status not in ('pending','approved') then
    raise exception 'This request is already %.', r.status using errcode = '22023';
  end if;
  update public.console_approval_requests set status = 'cancelled' where id = p_id;
  perform public.log_console_event('dual_control_cancelled', p_id::text, 'console_approval',
                                   jsonb_build_object('action', r.action));
  return jsonb_build_object('id', p_id, 'status', 'cancelled');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cancel_flag_change(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can cancel a flag change' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  update public.flag_changes
     set status = 'cancelled', cancelled_by = auth.uid(), cancel_reason = btrim(p_reason)
   where id = p_id and status in ('scheduled', 'awaiting_approval');
  if not found then
    raise exception 'This change already ran or was cancelled.' using errcode = '22023';
  end if;
  perform public.log_console_event('flag_change_cancelled', null, 'flag_change',
    jsonb_build_object('id', p_id, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'id', p_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_check_import_fingerprint(p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row record; v_org uuid := public.app_current_org();
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if coalesce(btrim(p_sha256), '') = '' then
    return jsonb_build_object('seen', false);
  end if;

  select f.id, f.original_filename, f.created_at, f.created_by,
         b.module, b.imported_rows
    into v_row
    from public.import_files f
    left join public.import_batches b on b.file_id = f.id
   where f.sha256 = btrim(p_sha256)
     and (f.organisation_id = v_org or public.is_super_admin())
     and (f.country is null
          or (select public.is_super_admin())
          or (select public.app_sees_all_countries())
          or lower(btrim(f.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
   order by f.created_at asc
   limit 1;

  if v_row.id is null then
    return jsonb_build_object('seen', false);
  end if;

  return jsonb_build_object('seen', true, 'file_id', v_row.id,
    'filename', v_row.original_filename, 'imported_at', v_row.created_at,
    'module', v_row.module, 'imported_rows', v_row.imported_rows);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_clean_tyre_records(p_changes jsonb, p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_action text DEFAULT 'classify'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  change jsonb; patch jsonb; expected jsonb; old_row jsonb; new_row jsonb;
  row_id uuid; ids jsonb := '[]'::jsonb; allowed text[];
  v public.tyre_records%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR
    NOT (coalesce(public.get_my_role()='Admin',false) OR coalesce(public.is_super_admin(),false)) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('classify','undo','serial','odometer','review')
    OR jsonb_typeof(p_changes) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid correction' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(p_changes) NOT BETWEEN 1 AND 200
    OR (SELECT count(DISTINCT e->>'id') FROM jsonb_array_elements(p_changes) e) <> jsonb_array_length(p_changes) THEN
    RAISE EXCEPTION 'Invalid correction batch' USING ERRCODE='22023';
  END IF;
  allowed := CASE p_action WHEN 'serial' THEN ARRAY['tyre_serial']
    WHEN 'odometer' THEN ARRAY['km_at_fitment','km_at_removal']
    WHEN 'review' THEN ARRAY['remarks'] ELSE ARRAY['category','risk_level','remarks_cleaned','cleaned'] END;

  -- A stable lock order prevents two overlapping batches acquiring inverse locks.
  FOR change IN SELECT e FROM jsonb_array_elements(p_changes) e ORDER BY e->>'id' LOOP
    row_id := (change->>'id')::uuid;
    patch := change->'patch'; expected := change->'expected';
    IF row_id IS NULL OR jsonb_typeof(patch) IS DISTINCT FROM 'object'
      OR jsonb_typeof(expected) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Invalid correction payload' USING ERRCODE='22023';
    END IF;
    IF patch = '{}'::jsonb OR EXISTS(SELECT 1 FROM jsonb_object_keys(patch) k WHERE NOT k=ANY(allowed) OR NOT expected ? k)
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(expected) k WHERE NOT k=ANY(allowed || ARRAY['description','remarks'])) THEN
      RAISE EXCEPTION 'Invalid correction fields' USING ERRCODE='22023';
    END IF;
    IF p_action IN ('classify','undo') AND (NOT patch ?& allowed OR NOT expected ?& ARRAY['description','remarks']) THEN
      RAISE EXCEPTION 'Classification snapshot required' USING ERRCODE='22023';
    END IF;
    SELECT to_jsonb(r) INTO old_row FROM public.tyre_records r
      WHERE id=row_id AND organisation_id=public.app_current_org()
        AND (p_country IS NULL OR country=p_country) AND (p_site IS NULL OR site=p_site) FOR UPDATE;
    IF old_row IS NULL THEN RAISE EXCEPTION 'Record unavailable in selected scope' USING ERRCODE='42501'; END IF;

    -- Retrying an already-applied value succeeds without adding duplicate history.
    -- Non-patched source fields must still match the reviewed snapshot.
    IF old_row @> patch AND NOT EXISTS(SELECT 1 FROM jsonb_each(expected) e WHERE NOT patch ? e.key AND old_row->e.key IS DISTINCT FROM e.value) THEN
      ids := ids || jsonb_build_array(row_id); CONTINUE;
    END IF;
    IF NOT old_row @> expected THEN
      RAISE EXCEPTION 'Record changed; refresh before correcting' USING ERRCODE='PT409';
    END IF;
    SELECT * INTO v FROM jsonb_populate_record(NULL::public.tyre_records,old_row || patch);
    IF p_action='classify' AND (v.cleaned IS DISTINCT FROM true OR nullif(btrim(v.category),'') IS NULL
      OR v.risk_level IS NULL OR v.risk_level NOT IN ('Critical','High','Medium','Low') OR length(v.category)>200 OR length(v.remarks_cleaned)>5000) THEN
      RAISE EXCEPTION 'Invalid classification' USING ERRCODE='22023';
    END IF;
    IF p_action='undo' AND patch IS DISTINCT FROM '{"category":null,"risk_level":null,"remarks_cleaned":null,"cleaned":false}'::jsonb THEN
      RAISE EXCEPTION 'Invalid reversal' USING ERRCODE='22023';
    END IF;
    IF p_action='serial' AND (nullif(btrim(v.tyre_serial),'') IS NULL OR length(v.tyre_serial)>100) THEN
      RAISE EXCEPTION 'Invalid serial' USING ERRCODE='22023';
    END IF;
    IF p_action='odometer' AND (v.km_at_fitment < 0 OR v.km_at_removal < 0 OR v.km_at_removal < v.km_at_fitment
      OR v.km_at_fitment::text IN ('NaN','Infinity','-Infinity') OR v.km_at_removal::text IN ('NaN','Infinity','-Infinity')
      OR EXISTS(SELECT 1 FROM jsonb_each(patch) e WHERE jsonb_typeof(e.value)<>'number')) THEN
      RAISE EXCEPTION 'Invalid odometer values' USING ERRCODE='22023';
    END IF;
    IF p_action='review' AND (nullif(btrim(v.remarks),'') IS NULL OR length(v.remarks)>5000) THEN
      RAISE EXCEPTION 'Invalid review note' USING ERRCODE='22023';
    END IF;
    UPDATE public.tyre_records r SET category=v.category,risk_level=v.risk_level,remarks_cleaned=v.remarks_cleaned,
      cleaned=v.cleaned,tyre_serial=v.tyre_serial,km_at_fitment=v.km_at_fitment,km_at_removal=v.km_at_removal,remarks=v.remarks
      WHERE id=row_id RETURNING to_jsonb(r) INTO new_row;
    IF new_row IS NULL OR NOT new_row @> patch THEN
      RAISE EXCEPTION 'Correction was not persisted' USING ERRCODE='42501';
    END IF;
    INSERT INTO public.audit_log(table_name,record_id,action,old_data,new_data,changed_by,organisation_id,details)
      VALUES('tyre_records',row_id,'UPDATE',old_row,new_row,auth.uid(),v.organisation_id,
        jsonb_build_object('channel','Data Cleaning','operation',p_action,'country',v.country,'site',v.site));
    IF p_action='classify' THEN
      INSERT INTO public.cleaning_log(original_text,cleaned_text,category,tyre_record_id,cleaned_by_model)
        VALUES(concat_ws(' | ',v.description,v.remarks),v.remarks_cleaned,v.category,row_id,'rule-based-v1');
    END IF;
    -- Undo appends the reversal to audit_log; previous cleaning history remains.
    ids := ids || jsonb_build_array(row_id);
  END LOOP;
  RETURN jsonb_build_object('ids',ids);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_clear_push_token(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  UPDATE public.profiles
     SET push_token = NULL, push_token_updated_at = now()
   WHERE id = p_user_id;
  UPDATE public.user_devices
     SET revoked = true, last_seen_at = now()
   WHERE user_id = p_user_id AND NOT coalesce(revoked, false);
  PERFORM public._console_audit('clear_push_token', p_user_id, 'user', NULL);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_clone_role(p_source text, p_new_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only a Super Admin can clone a role.' USING errcode = '42501'; END IF;
  IF p_source IS NULL OR btrim(p_source) = '' OR p_new_name IS NULL OR btrim(p_new_name) = '' THEN RAISE EXCEPTION 'source and new name are required.'; END IF;
  INSERT INTO public.custom_roles (organisation_id, name, description, created_by)
  VALUES (public.app_current_org(), p_new_name, 'Cloned from ' || p_source, v_uid)
  ON CONFLICT (organisation_id, name) DO NOTHING;
  INSERT INTO public.module_permissions (module_key, role, org_id, enabled, updated_by, updated_at)
  SELECT src.module_key, p_new_name, NULL, src.enabled, v_uid, now()
    FROM public.module_permissions src
   WHERE src.role = p_source AND src.org_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.module_permissions dst WHERE dst.role = p_new_name AND dst.org_id IS NULL AND dst.module_key = src.module_key);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cron_health(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read scheduled job health' using errcode = '42501';
  end if;
  return public._cron_health(p_days);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cron_job_runs(p_jobid bigint, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read scheduled job runs' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'started', r.start_time, 'ended', r.end_time, 'status', r.status,
           'ms', round(extract(epoch from (r.end_time - r.start_time)) * 1000)::int,
           'output', left(coalesce(r.return_message, ''), 160)
         ) order by r.start_time desc), '[]'::jsonb)
    into v
    from (
      select d.start_time, d.end_time, d.status::text as status, d.return_message
        from cron.job_run_details d
       where d.jobid = p_jobid
       order by d.start_time desc, d.runid desc
       limit least(greatest(coalesce(p_limit, 8), 1), 50)
    ) r;
  return jsonb_build_object('ok', true, 'runs', v);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cron_last_failures()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read scheduled job history' using errcode = '42501';
  end if;
  if to_regclass('cron.job_run_details') is null then
    return jsonb_build_object('ok', false, 'reason', 'pg_cron is not installed');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('jobid', jobid, 'last_failure_at', last_fail, 'failed_kept', n)), '[]'::jsonb)
    into v
    from (select d.jobid, max(d.start_time) as last_fail, count(*) as n
            from cron.job_run_details d
           where d.status::text = 'failed'
           group by d.jobid) s;
  return jsonb_build_object('ok', true, 'items', v);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cron_run_now(p_jobid bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  v_job record;
  v_at timestamp := date_trunc('minute', (now() at time zone 'GMT') + interval '1 minute');
  v_name text;
  v_sched text;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can run scheduled jobs' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  select jobid, jobname, command into v_job from cron.job where jobid = p_jobid;
  if v_job.jobid is null then
    raise exception 'That scheduled job does not exist.' using errcode = '22023';
  end if;
  if exists (select 1 from cron.job where jobname like 'console-run-now-' || p_jobid || '-%') then
    raise exception 'A run of this job is already queued. Wait a minute and refresh.' using errcode = '22023';
  end if;
  v_name := 'console-run-now-' || p_jobid || '-' || extract(epoch from v_at)::bigint;
  v_sched := extract(minute from v_at)::int || ' ' || extract(hour from v_at)::int || ' '
          || extract(day from v_at)::int || ' ' || extract(month from v_at)::int || ' *';
  perform cron.schedule(v_name, v_sched, v_job.command);
  perform public.log_console_event('cron_run_now', null, 'cron_job',
    jsonb_build_object('jobid', p_jobid, 'jobname', v_job.jobname, 'reason', btrim(p_reason), 'runs_at_utc', v_at));
  return jsonb_build_object('ok', true, 'jobid', p_jobid, 'jobname', v_job.jobname, 'runs_at', v_at at time zone 'GMT');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_cron_set_active(p_jobid bigint, p_active boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare v_name text;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can pause or resume scheduled jobs' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  select jobname into v_name from cron.job where jobid = p_jobid;
  if v_name is null then
    raise exception 'That scheduled job does not exist.' using errcode = '22023';
  end if;
  perform cron.alter_job(job_id := p_jobid, active := coalesce(p_active, true));
  perform public.log_console_event(case when p_active then 'cron_resume' else 'cron_pause' end,
    null, 'cron_job', jsonb_build_object('jobid', p_jobid, 'jobname', v_name, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'jobid', p_jobid, 'jobname', v_name, 'active', coalesce(p_active, true));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_data_cleanup_preview(p_key text, p_before date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s record; v_count bigint;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then raise exception 'super admin only'; end if;
  if p_before is null then raise exception 'a cutoff date is required'; end if;
  select * into s from public._data_cleanup_spec(p_key);
  if s.tbl is null then raise exception 'unknown cleanup target'; end if;
  execute format('select count(*) from public.%I where %I < $1', s.tbl, s.date_col)
    into v_count using p_before;
  return jsonb_build_object('key', p_key, 'table', s.tbl, 'kind', s.kind, 'before', p_before, 'count', v_count);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_data_cleanup_run(p_key text, p_before date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
declare s record; v_deleted bigint; v_snap jsonb; v_snap_id text := null;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then raise exception 'super admin only'; end if;
  if p_before is null then raise exception 'a cutoff date is required'; end if;
  if p_before > current_date then raise exception 'cutoff date cannot be in the future'; end if;
  perform public._consume_approval('admin_data_cleanup_run', jsonb_build_object('key', p_key, 'before', p_before));
  select * into s from public._data_cleanup_spec(p_key);
  if s.tbl is null then raise exception 'unknown cleanup target'; end if;

  begin
    v_snap := public.create_backup_snapshot('data-cleanup: '||p_key||' before '||p_before);
    v_snap_id := coalesce(v_snap->>'id', v_snap->>'snapshot_id', v_snap::text);
  exception when others then v_snap_id := null; end;

  execute format('delete from public.%I where %I < $1', s.tbl, s.date_col) using p_before;
  get diagnostics v_deleted = row_count;

  begin
    insert into public.system_logs(severity, source, message, detail, created_at)
    values ('warning', 'data-cleanup',
      'Deleted '||v_deleted||' old '||s.label||' (before '||p_before||')',
      jsonb_build_object('key', p_key, 'table', s.tbl, 'before', p_before, 'deleted', v_deleted, 'snapshot', v_snap_id),
      now());
  exception when others then null; end;
  begin
    insert into public.access_audit(actor, actor_email, action, entity, after, at)
    values (auth.uid(), null, 'data_cleanup', s.tbl,
      jsonb_build_object('key', p_key, 'before', p_before, 'deleted', v_deleted, 'snapshot', v_snap_id), now());
  exception when others then null; end;

  return jsonb_build_object('key', p_key, 'table', s.tbl, 'before', p_before, 'deleted', v_deleted, 'snapshot', v_snap_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_data_cleanup_run_with_reason(p_key text, p_before date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_res jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'super admin only' using errcode = '42501';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'Give a short reason for this cleanup' using errcode = '22023';
  end if;

  v_res := public.admin_data_cleanup_run(p_key, p_before);

  perform public.log_console_event('data_cleanup', null, p_key,
    jsonb_build_object('before', p_before, 'deleted', v_res->'deleted',
                       'snapshot', v_res->'snapshot', 'reason', btrim(p_reason)));

  return v_res;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_data_cleanup_targets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; out jsonb := '[]'::jsonb; v_total bigint; v_min timestamptz; v_max timestamptz;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then raise exception 'super admin only'; end if;
  for r in
    select sp.* from unnest(array[
      'audit_logs','system_logs','access_audit','ai_token_logs','ai_usage_log',
      'odometer_logs','engine_hours','accidents','tyre_records','inspections','work_orders'
    ]) k, lateral public._data_cleanup_spec(k) sp
  loop
    begin
      execute format('select count(*), min(%I)::timestamptz, max(%I)::timestamptz from public.%I', r.date_col, r.date_col, r.tbl)
        into v_total, v_min, v_max;
    exception when others then v_total := null; v_min := null; v_max := null; end;
    out := out || jsonb_build_object(
      'key', r.key, 'table', r.tbl, 'label', r.label, 'kind', r.kind, 'date_col', r.date_col,
      'total', v_total, 'oldest', v_min, 'newest', v_max);
  end loop;
  return out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_database_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v jsonb;
  v_conn jsonb;
  v_mig jsonb;
  v_tables jsonb;
  v_cron jsonb;
  v_cache numeric;
  v_table_count int;
  v_all_bytes bigint;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'total', count(*),
    'client_active', count(*) filter (where backend_type = 'client backend' and state = 'active'),
    'client_idle', count(*) filter (where backend_type = 'client backend' and state is distinct from 'active'),
    'background', count(*) filter (where backend_type is distinct from 'client backend'),
    'max', current_setting('max_connections')::int
  ) into v_conn
  from pg_stat_activity where datname = current_database() or datname is null;

  select round(100.0 * sum(blks_hit) / nullif(sum(blks_hit) + sum(blks_read), 0), 2)
    into v_cache from pg_stat_database where datname = current_database();

  begin
    select jsonb_build_object(
      'total', (select count(*) from supabase_migrations.schema_migrations),
      'today', (select count(*) from supabase_migrations.schema_migrations
                 where version like to_char(now() at time zone 'utc', 'YYYYMMDD') || '%'),
      'latest', (select coalesce(jsonb_agg(m order by m.version desc), '[]'::jsonb) from (
                   select version, name from supabase_migrations.schema_migrations
                   order by version desc limit 12) m)
    ) into v_mig;
  exception when others then
    v_mig := null;
  end;

  begin
    select jsonb_build_object('schedule', schedule, 'active', active) into v_cron
      from cron.job where jobname = 'nightly-backup' limit 1;
  exception when others then
    v_cron := null;
  end;

  select count(*), sum(pg_total_relation_size(c.oid)) into v_table_count, v_all_bytes
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where c.relkind in ('r','p') and n.nspname not in ('pg_catalog','information_schema','pg_toast')
     and n.nspname not like 'pg_temp%';

  select coalesce(jsonb_agg(t order by t.bytes desc), '[]'::jsonb) into v_tables from (
    select n.nspname as schema, c.relname as name,
           case when c.reltuples > 0 and c.relpages > 0
                then round(c.reltuples / c.relpages * (pg_relation_size(c.oid) / current_setting('block_size')::numeric))::bigint
                else greatest(coalesce(s.n_live_tup, 0), 0) end as rows,
           pg_total_relation_size(c.oid) as bytes,
           coalesce(s.n_dead_tup, 0) as dead_rows
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      left join pg_stat_all_tables s on s.relid = c.oid
     where c.relkind in ('r','p')
       and n.nspname not in ('pg_catalog','information_schema','pg_toast')
       and n.nspname not like 'pg_temp%'
     order by pg_total_relation_size(c.oid) desc
     limit 40
  ) t;

  v := jsonb_build_object(
    'generated_at', now(),
    'db_bytes', pg_database_size(current_database()),
    'connections', v_conn,
    'cache_hit_pct', v_cache,
    'migrations', v_mig,
    'nightly_backup_job', v_cron,
    'table_count', v_table_count,
    'all_table_bytes', v_all_bytes,
    'tables', v_tables
  );
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_columns(p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT (p_table = ANY (public._admin_db_safelist())) THEN RAISE EXCEPTION 'Table not available'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('column_name', column_name, 'data_type', data_type) ORDER BY ordinal_position), '[]'::jsonb)
    INTO v FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table;
  RETURN v;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_delete_row(p_table text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before jsonb;
  v_org    uuid := public.app_current_org();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if not (p_table = any (public._admin_db_safelist())) then
    raise exception 'Table not available.' using errcode = '22023';
  end if;

  execute format('delete from public.%I t where t.id = $1 and (t.organisation_id = $2 or $3) returning to_jsonb(t)',
                 p_table)
    into v_before using p_id, v_org, public.is_super_admin();

  if v_before is null then
    raise exception 'Row not found.' using errcode = '22023';
  end if;

  insert into public.admin_row_changes
    (organisation_id, tbl, row_id, action, before_data)
  values (v_org, p_table, p_id, 'delete', v_before);

  return jsonb_build_object('ok', true, 'deleted', 1, 'before', v_before);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_query(p_table text, p_column text DEFAULT NULL::text, p_op text DEFAULT NULL::text, p_value text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; v_sql text; v_opsql text; v_col text;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT (p_table = ANY (public._admin_db_safelist())) THEN RAISE EXCEPTION 'Table not available'; END IF;
  v_sql := format('SELECT COALESCE(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT * FROM public.%I t', p_table);
  IF p_column IS NOT NULL AND p_op IS NOT NULL AND p_value IS NOT NULL THEN
    -- validate column belongs to the table
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=p_table AND column_name=p_column) THEN
      RAISE EXCEPTION 'Unknown column'; END IF;
    v_col := quote_ident(p_column);
    v_opsql := CASE p_op
      WHEN 'eq' THEN v_col||' = $1' WHEN 'neq' THEN v_col||' <> $1'
      WHEN 'gt' THEN v_col||'::text > $1' WHEN 'gte' THEN v_col||'::text >= $1'
      WHEN 'lt' THEN v_col||'::text < $1' WHEN 'lte' THEN v_col||'::text <= $1'
      WHEN 'ilike' THEN v_col||'::text ILIKE ''%''||$1||''%'''
      ELSE NULL END;
    IF v_opsql IS NULL THEN RAISE EXCEPTION 'Unsupported operator'; END IF;
    v_sql := v_sql || ' WHERE ' || v_opsql;
  END IF;
  v_sql := v_sql || format(' LIMIT %s) t', GREATEST(1, LEAST(1000, COALESCE(p_limit,100))));
  EXECUTE v_sql INTO v USING p_value;
  RETURN v;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_revert_change(p_change_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_c    record;
  v_cols text;
  v_sel  text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select * into v_c from public.admin_row_changes
   where id = p_change_id and reverted_at is null;
  if v_c.id is null then
    return jsonb_build_object('ok', false, 'reason', 'nothing to revert');
  end if;
  if not (v_c.tbl = any (public._admin_db_safelist())) then
    raise exception 'Table not available.' using errcode = '22023';
  end if;

  -- Generated columns must be excluded from an explicit insert list, which is how
  -- the V320 approve_pending_upload path broke.
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg('r.' || quote_ident(column_name), ', ' order by ordinal_position)
    into v_cols, v_sel
    from information_schema.columns
   where table_schema = 'public' and table_name = v_c.tbl and is_generated = 'NEVER';

  if v_c.action = 'delete' then
    execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1) r',
                   v_c.tbl, v_cols, v_sel, v_c.tbl)
      using v_c.before_data;
  else
    execute format('update public.%I t set (%s) = (select %s from jsonb_populate_record(null::public.%I, $1) r) where t.id = $2',
                   v_c.tbl, v_cols, v_sel, v_c.tbl)
      using v_c.before_data, v_c.row_id;
  end if;

  update public.admin_row_changes
     set reverted_at = now(), reverted_by = auth.uid()
   where id = p_change_id;

  return jsonb_build_object('ok', true, 'action', v_c.action, 'tbl', v_c.tbl);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_tables()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb := '[]'::jsonb; t text; c bigint;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  FOREACH t IN ARRAY public._admin_db_safelist() LOOP
    IF to_regclass('public.'||t) IS NULL THEN CONTINUE; END IF;
    EXECUTE format('SELECT count(*) FROM public.%I', t) INTO c;
    v := v || jsonb_build_object('table_name', t, 'row_count', c);
  END LOOP;
  RETURN v;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_db_update_row(p_table text, p_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allowed text[];
  v_sets    text[] := '{}';
  v_key     text;
  v_before  jsonb;
  v_after   jsonb;
  v_org     uuid := public.app_current_org();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if not (p_table = any (public._admin_db_safelist())) then
    raise exception 'Table not available.' using errcode = '22023';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'Nothing to change.' using errcode = '22023';
  end if;

  v_allowed := public._admin_editable_cols(p_table);

  for v_key in select jsonb_object_keys(p_patch) loop
    if not (v_key = any (v_allowed)) then
      raise exception 'Column % cannot be edited here.', v_key using errcode = '22023';
    end if;
    -- %I quotes the identifier; the value is bound as a parameter below.
    v_sets := v_sets || format('%I = ($1 ->> %L)::text', v_key, v_key);
  end loop;

  execute format('select to_jsonb(t) from public.%I t where t.id = $1 and (t.organisation_id = $2 or $3)',
                 p_table)
    into v_before using p_id, v_org, public.is_super_admin();

  if v_before is null then
    raise exception 'Row not found.' using errcode = '22023';
  end if;

  execute format('update public.%I set %s where id = $2 returning to_jsonb(%I.*)',
                 p_table, array_to_string(v_sets, ', '), p_table)
    into v_after using p_patch, p_id;

  insert into public.admin_row_changes
    (organisation_id, tbl, row_id, action, before_data, after_data)
  values (v_org, p_table, p_id, 'update', v_before, v_after);

  return jsonb_build_object('ok', true, 'before', v_before, 'after', v_after);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_decide_access_item(p_item uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_status text; v_dec text := lower(btrim(coalesce(p_decision,'')));
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  perform public._access_review_require_super();
  if v_dec not in ('pending','keep','revoke','modify') then
    raise exception 'Decision must be keep, revoke, modify or pending.' using errcode = '22023';
  end if;
  if v_dec = 'revoke' and length(btrim(coalesce(p_note,''))) = 0 then
    raise exception 'A revoke decision needs a reason.' using errcode = '22023';
  end if;
  select c.status into v_status
    from public.access_review_items i join public.access_review_campaigns c on c.id = i.campaign_id
   where i.id = p_item;
  if v_status is null then
    raise exception 'Review item not found.' using errcode = 'P0002';
  end if;
  if v_status <> 'open' then
    raise exception 'This review is closed; decisions can no longer change.' using errcode = '22023';
  end if;
  update public.access_review_items
     set decision = v_dec,
         decision_note = nullif(btrim(coalesce(p_note,'')), ''),
         decided_by = case when v_dec = 'pending' then null else auth.uid() end,
         decided_at = case when v_dec = 'pending' then null else now() end
   where id = p_item;
  return jsonb_build_object('ok', true, 'item', p_item, 'decision', v_dec);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_decide_approval(p_id uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.console_approval_requests%rowtype;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select * into r from public.console_approval_requests where id = p_id for update;
  if not found then raise exception 'Approval request not found.' using errcode = '22023'; end if;
  if r.requested_by = auth.uid() then
    raise exception 'You cannot decide your own request. A second super admin must do it.' using errcode = '42501';
  end if;
  if r.status <> 'pending' then
    raise exception 'This request has already been %.', r.status using errcode = '22023';
  end if;
  if r.expires_at <= now() then
    update public.console_approval_requests set status = 'expired' where id = p_id;
    return jsonb_build_object('id', p_id, 'status', 'expired');
  end if;
  if not coalesce(p_approve, false) and char_length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'Say why you are rejecting it.' using errcode = '22023';
  end if;

  update public.console_approval_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = auth.uid(), decided_at = now(),
         decision_note = nullif(btrim(coalesce(p_note, '')), ''),
         expires_at = case when p_approve then now() + interval '24 hours' else expires_at end
   where id = p_id;

  perform public.log_console_event(
    case when p_approve then 'dual_control_approved' else 'dual_control_rejected' end,
    p_id::text, 'console_approval',
    jsonb_build_object('action', r.action, 'requested_by', r.requested_by, 'note', nullif(btrim(coalesce(p_note, '')), '')));

  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    values (r.requested_by, 'security',
            case when p_approve then 'Your console request was approved' else 'Your console request was rejected' end,
            replace(r.action, '_', ' ') || case when p_approve then ' can now be run for the next 24 hours.'
                                                else '. Note: ' || left(btrim(coalesce(p_note, '')), 200) end,
            'console_approval', p_id);
  exception when others then null;
  end;

  return jsonb_build_object('id', p_id, 'status', case when p_approve then 'approved' else 'rejected' end);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_decide_elevation(p_id uuid, p_approve boolean, p_note text DEFAULT NULL::text, p_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.jit_elevation_requests%rowtype; v_min int; v_gid uuid; v_note text := nullif(btrim(coalesce(p_note,'')),'');
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select * into r from public.jit_elevation_requests where id = p_id for update;
  if not found then raise exception 'Request not found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then return jsonb_build_object('ok', false, 'reason', 'not_pending', 'status', r.status); end if;
  if r.requested_by = auth.uid() then
    raise exception 'You cannot decide your own request' using errcode = '42501';
  end if;

  if not coalesce(p_approve, false) then
    if v_note is null or length(v_note) < 5 then
      raise exception 'A denial reason of at least 5 characters is required' using errcode = '22023';
    end if;
    update public.jit_elevation_requests
       set status = 'denied', decided_by = auth.uid(), decided_at = now(),
           decision_note = left(v_note, 500), updated_at = now()
     where id = p_id;
    perform public._jit_audit('jit_elevation_deny', p_id, jsonb_build_object('status','pending'),
      jsonb_build_object('status','denied','module_key',r.module_key,'capability',r.capability), v_note);
    begin
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      values (r.requested_by, 'security', 'Elevation request denied',
              r.capability || ' on ' || r.module_key || ': ' || left(v_note, 200), 'jit_elevation', p_id);
    exception when others then null; end;
    return jsonb_build_object('ok', true, 'id', p_id, 'status', 'denied');
  end if;

  v_min := coalesce(p_minutes, r.requested_minutes);
  if v_min < 5 or v_min > r.requested_minutes then
    raise exception 'Approved duration must be between 5 minutes and the requested % minutes', r.requested_minutes using errcode = '22023';
  end if;
  perform public._jit_validate_target(r.target_user_id, r.module_key, r.capability);
  v_gid := public._jit_activate(p_id, v_min, v_note);

  perform public._jit_audit('jit_elevation_approve', p_id, jsonb_build_object('status','pending'),
    jsonb_build_object('status','approved','module_key',r.module_key,'capability',r.capability,
                       'minutes',v_min,'grant_id',v_gid,'target_user_id',r.target_user_id), v_note);
  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    values (r.target_user_id, 'security', 'Elevation approved',
            r.capability || ' on ' || r.module_key || ' for ' || v_min || ' minutes.', 'jit_elevation', p_id);
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'approved', 'grant_id', v_gid,
                            'expires_at', now() + make_interval(mins => v_min));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_delete_empty_org(p_org_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_hit boolean;
  v_name text;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can delete an organization' using errcode = '42501';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  select name into v_name from public.organisations where id = p_org_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if exists (select 1 from public.profiles where org_id = p_org_id or organisation_id = p_org_id) then
    return jsonb_build_object('ok', false, 'reason', 'has_members');
  end if;
  for r in
    select c.table_name, c.data_type
      from information_schema.columns c
      join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public' and c.column_name = 'organisation_id'
       and t.table_type = 'BASE TABLE' and c.table_name not in ('organisations', 'profiles')
       and c.table_name !~ '(audit|_log$|_logs$|_log_|^system_logs$|_events$|^notifications$|_sessions$)'
  loop
    if r.data_type = 'uuid' then
      execute format('select exists (select 1 from public.%I where organisation_id = $1)', r.table_name)
        into v_hit using p_org_id;
    else
      execute format('select exists (select 1 from public.%I where organisation_id::text = $1)', r.table_name)
        into v_hit using p_org_id::text;
    end if;
    if v_hit then
      return jsonb_build_object('ok', false, 'reason', 'has_records', 'table', r.table_name);
    end if;
  end loop;
  begin
    delete from public.organisations where id = p_org_id;
  exception when foreign_key_violation then
    return jsonb_build_object('ok', false, 'reason', 'referenced');
  end;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'delete_org', p_org_id, 'organisation', jsonb_build_object('name', v_name, 'reason', v_reason));
  return jsonb_build_object('ok', true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_delivery_reach()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read delivery reach' using errcode = '42501';
  end if;
  with d as (
    select user_id, last_seen_at, app_version,
           (push_token like 'ExponentPushToken%') as is_expo
      from public.user_devices
     where not coalesce(revoked, false)
       and nullif(btrim(push_token), '') is not null
  )
  select jsonb_build_object(
    'ok', true,
    'flutter_devices', count(*) filter (where not is_expo),
    'flutter_people', count(distinct user_id) filter (where not is_expo),
    'flutter_seen_7d', count(*) filter (where not is_expo and last_seen_at >= now() - interval '7 days'),
    'retired_devices', count(*) filter (where is_expo),
    'retired_people', count(distinct user_id) filter (where is_expo),
    'total_devices', count(*),
    'total_people', count(distinct user_id)
  ) into v from d;
  return v;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_dup_preview(p_key text, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_spec   record;
  v_bkey   text;
  v_src    text;
  v_org    uuid := public.app_current_org();
  v_money  text;
  v_out    jsonb;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select * into v_spec from public._dup_scan_spec(p_key);
  if v_spec.key is null then
    raise exception 'Unknown duplicate target.' using errcode = '22023';
  end if;

  v_bkey  := public._dup_bkey_expr(v_spec.bkey_cols);
  v_src   := case when v_spec.src_col is null then 'null::text'
                  else format('%I::text', v_spec.src_col) end;
  v_money := case when v_spec.money_col is null then '0::numeric'
                  else format('coalesce(%I::numeric,0)', v_spec.money_col) end;

  execute format($f$
    with g as (
      select %s as bkey, %I as ts, %s as src, %s as money, id
        from public.%I
       where (organisation_id = $1 or $2)
         and ($3 is null or country = $3)
    ), grp as (
      select bkey, count(*) as n, count(distinct src) as dsrc
        from g group by bkey having count(*) > 1
    ), ranked as (
      select g.id, g.money, grp.dsrc,
             row_number() over (partition by g.bkey order by g.ts, g.id) as rn
        from g join grp on grp.bkey = g.bkey
    )
    select jsonb_build_object(
      'groups_total',      (select count(*) from grp),
      'groups_deletable',  (select count(*) from grp where dsrc <= 1),
      'groups_protected',  (select count(*) from grp where dsrc > 1),
      'extra_deletable',   (select count(*) from ranked where rn > 1 and dsrc <= 1),
      'extra_protected',   (select count(*) from ranked where rn > 1 and dsrc > 1),
      'money_deletable',   (select round(coalesce(sum(money),0),2) from ranked where rn > 1 and dsrc <= 1)
    )
  $f$, v_bkey, v_spec.date_col, v_src, v_money, v_spec.tbl)
  into v_out
  using v_org, public.is_super_admin(), nullif(btrim(coalesce(p_country,'')), '');

  return coalesce(v_out, '{}'::jsonb)
         || jsonb_build_object('key', v_spec.key, 'tbl', v_spec.tbl,
                               'label', v_spec.label, 'country', p_country,
                               'money_col', v_spec.money_col);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_dup_resolve(p_key text, p_country text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_spec    record;
  v_bkey    text;
  v_src     text;
  v_org     uuid := public.app_current_org();
  v_batch   uuid := gen_random_uuid();
  v_deleted bigint := 0;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select * into v_spec from public._dup_scan_spec(p_key);
  if v_spec.key is null then
    raise exception 'Unknown duplicate target.' using errcode = '22023';
  end if;

  v_bkey := public._dup_bkey_expr(v_spec.bkey_cols);
  v_src  := case when v_spec.src_col is null then 'null::text'
                 else format('%I::text', v_spec.src_col) end;

  execute format($f$
    with g as (
      select id, %s as bkey, %I as ts, %s as src
        from public.%I
       where (organisation_id = $1 or $2)
         and ($3 is null or country = $3)
    ), grp as (
      select bkey from g group by bkey
      having count(*) > 1 and count(distinct src) <= 1
    ), ranked as (
      select g.id, row_number() over (partition by g.bkey order by g.ts, g.id) as rn
        from g join grp on grp.bkey = g.bkey
    ), gone as (
      delete from public.%I t
       where t.id in (select id from ranked where rn > 1)
      returning t.*
    )
    insert into public.dup_resolve_archive
      (batch_id, organisation_id, target_key, tbl, country, row_data, reason)
    select $4, $1, $5, $6, (to_jsonb(gone.*) ->> 'country'), to_jsonb(gone.*), $7
      from gone
  $f$, v_bkey, v_spec.date_col, v_src, v_spec.tbl, v_spec.tbl)
  using v_org, public.is_super_admin(), nullif(btrim(coalesce(p_country,'')), ''),
        v_batch, v_spec.key, v_spec.tbl,
        coalesce(nullif(btrim(coalesce(p_reason,'')), ''), 'Duplicate import rows removed');

  select count(*) into v_deleted from public.dup_resolve_archive where batch_id = v_batch;

  insert into public.system_logs (severity, source, message, detail)
  values ('warning', 'duplicate-control',
          format('Removed %s duplicate row(s) from %s', v_deleted, v_spec.tbl),
          jsonb_build_object('batch_id', v_batch, 'target', v_spec.key,
                             'country', p_country, 'deleted', v_deleted));

  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'deleted', v_deleted,
                            'tbl', v_spec.tbl, 'target', v_spec.key);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_dup_restore(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tbl      text;
  v_cols     text;
  v_sel      text;
  v_restored bigint := 0;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select distinct tbl into v_tbl
    from public.dup_resolve_archive
   where batch_id = p_batch_id and restored_at is null;

  if v_tbl is null then
    return jsonb_build_object('ok', false, 'reason', 'nothing to restore');
  end if;

  if not exists (select 1 from public._dup_scan_spec(null) s where s.tbl = v_tbl) then
    raise exception 'Refusing to restore into an unlisted table.' using errcode = '22023';
  end if;

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
         string_agg('r.' || quote_ident(column_name), ', ' order by ordinal_position)
    into v_cols, v_sel
    from information_schema.columns
   where table_schema = 'public' and table_name = v_tbl
     and is_generated = 'NEVER';

  execute format($f$
    insert into public.%I (%s)
    select %s
      from public.dup_resolve_archive a
      cross join lateral jsonb_populate_record(null::public.%I, a.row_data) as r
     where a.batch_id = $1 and a.restored_at is null
  $f$, v_tbl, v_cols, v_sel, v_tbl)
  using p_batch_id;

  update public.dup_resolve_archive
     set restored_at = now()
   where batch_id = p_batch_id and restored_at is null;

  select count(*) into v_restored
    from public.dup_resolve_archive where batch_id = p_batch_id;

  insert into public.system_logs (severity, source, message, detail)
  values ('info', 'duplicate-control',
          format('Restored %s row(s) into %s', v_restored, v_tbl),
          jsonb_build_object('batch_id', p_batch_id, 'restored', v_restored));

  return jsonb_build_object('ok', true, 'restored', v_restored, 'tbl', v_tbl);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_dup_scan(p_key text, p_country text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS TABLE(bkey text, copies bigint, distinct_source_rows bigint, verdict text, first_seen timestamp with time zone, last_seen timestamp with time zone, money numeric, sample_country text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_spec  record;
  v_bkey  text;
  v_src   text;
  v_money text;
  v_org   uuid := public.app_current_org();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select * into v_spec from public._dup_scan_spec(p_key);
  if v_spec.key is null then
    raise exception 'Unknown duplicate target.' using errcode = '22023';
  end if;

  v_bkey  := public._dup_bkey_expr(v_spec.bkey_cols);
  v_src   := case when v_spec.src_col is null then 'null::text'
                  else format('%I::text', v_spec.src_col) end;
  v_money := case when v_spec.money_col is null then '0::numeric'
                  else format('coalesce(%I::numeric,0)', v_spec.money_col) end;

  return query execute format($f$
    with g as (
      select %s as bkey, %I as ts, %s as src, %s as money, country
        from public.%I
       where (organisation_id = $1 or $2)
         and ($3 is null or country = $3)
    )
    select g.bkey,
           count(*) as copies,
           count(distinct g.src) as distinct_source_rows,
           case when count(distinct g.src) > 1 then 'genuine' else 'duplicate' end as verdict,
           min(g.ts) as first_seen,
           max(g.ts) as last_seen,
           round(sum(g.money) - min(g.money), 2) as money,
           min(g.country) as sample_country
      from g
     group by g.bkey
    having count(*) > 1
     order by count(*) desc, sum(g.money) desc nulls last
     limit $4
  $f$, v_bkey, v_spec.date_col, v_src, v_money, v_spec.tbl)
  using v_org, public.is_super_admin(),
        nullif(btrim(coalesce(p_country,'')), ''), greatest(1, least(coalesce(p_limit,200), 2000));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_dup_targets()
 RETURNS TABLE(key text, tbl text, label text, kind text, has_source_row boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  return query
  select s.key, s.tbl, s.label, s.kind, (s.src_col is not null)
  from public._dup_scan_spec(null) s
  order by (s.kind = 'money') desc, s.label;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_end_support_sessions(p_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_ids uuid[];
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can end support sessions' using errcode = '42501';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  with ended as (
    update public.support_sessions
       set active = false, ended_at = coalesce(ended_at, now())
     where ended_at is null and active
       and (case when p_id is not null then id = p_id else expires_at is not null and expires_at <= now() end)
    returning id
  )
  select coalesce(array_agg(id), '{}') into v_ids from ended;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), case when p_id is null then 'support_sessions_close_lapsed' else 'support_session_force_end' end,
          p_id, 'support_session',
          jsonb_build_object('reason', v_reason, 'ended', cardinality(v_ids), 'ids', to_jsonb(v_ids)));
  return jsonb_build_object('ok', true, 'ended', cardinality(v_ids));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_export_audit(p_source text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0)
 RETURNS TABLE(ts timestamp with time zone, id uuid, data jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_from timestamptz := case when p_from is null then '-infinity'::timestamptz else (p_from::timestamp at time zone 'UTC') end;
  v_to   timestamptz := case when p_to   is null then  'infinity'::timestamptz else ((p_to + 1)::timestamp at time zone 'UTC') end;
  v_lim  int := least(greatest(coalesce(p_limit, 1000), 1), 5000);
  v_off  int := greatest(coalesce(p_offset, 0), 0);
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not coalesce(public.is_super_admin(), false) then
    raise exception 'Only a super admin can export audit logs' using errcode = '42501';
  end if;
  if p_source = 'audit_log_v2' then
    return query select t.created_at, t.id, to_jsonb(t) from public.audit_log_v2 t
      where t.created_at >= v_from and t.created_at < v_to order by t.created_at, t.id limit v_lim offset v_off;
  elsif p_source = 'access_audit' then
    return query select t.at, t.id, to_jsonb(t) from public.access_audit t
      where t.at >= v_from and t.at < v_to order by t.at, t.id limit v_lim offset v_off;
  elsif p_source = 'console_sessions' then
    return query select t.created_at, t.id, to_jsonb(t) from public.console_sessions t
      where t.created_at >= v_from and t.created_at < v_to order by t.created_at, t.id limit v_lim offset v_off;
  else
    raise exception 'Unknown audit source' using errcode = '22023';
  end if;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_export_audit_count(p_source text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_from timestamptz := case when p_from is null then '-infinity'::timestamptz else (p_from::timestamp at time zone 'UTC') end;
  v_to   timestamptz := case when p_to   is null then  'infinity'::timestamptz else ((p_to + 1)::timestamp at time zone 'UTC') end;
  v_n bigint;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not coalesce(public.is_super_admin(), false) then
    raise exception 'Only a super admin can export audit logs' using errcode = '42501';
  end if;
  if p_source = 'audit_log_v2' then
    select count(*) into v_n from public.audit_log_v2 where created_at >= v_from and created_at < v_to;
  elsif p_source = 'access_audit' then
    select count(*) into v_n from public.access_audit where at >= v_from and at < v_to;
  elsif p_source = 'console_sessions' then
    select count(*) into v_n from public.console_sessions where created_at >= v_from and created_at < v_to;
  else
    raise exception 'Unknown audit source' using errcode = '22023';
  end if;
  return v_n;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_flag_usage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read flag usage' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'ok', true,
    'roles', coalesce((select jsonb_agg(jsonb_build_object('role', role, 'people', n) order by n desc, role)
                         from (select role, count(*) n from public.profiles
                                where coalesce(approved, false) and not coalesce(locked, false) and role is not null
                                group by role) r), '[]'::jsonb),
    'orgs', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name,
                                'members', (select count(*) from public.profiles p where p.org_id = o.id),
                                'overrides', case when jsonb_typeof(o.settings -> 'feature_flags') = 'object'
                                                  then (select count(*) from jsonb_object_keys(o.settings -> 'feature_flags')) else 0 end)
                                order by o.name)
                        from public.organisations o), '[]'::jsonb),
    'wash_30d', (select count(*) from public.wash_records where created_at >= now() - interval '30 days'),
    'ai_calls_35d', (select count(*) from public.ai_token_logs where created_at >= now() - interval '35 days'),
    'ai_last', (select max(created_at) from public.ai_token_logs),
    'subscriptions', (select count(*) from public.org_subscriptions),
    'new_24h', jsonb_build_object(
      'tyre_records', (select count(*) from public.tyre_records where created_at >= now() - interval '24 hours'),
      'inspections', (select count(*) from public.inspections where created_at >= now() - interval '24 hours'),
      'work_orders', (select count(*) from public.work_orders where created_at >= now() - interval '24 hours'),
      'accidents', (select count(*) from public.accidents where created_at >= now() - interval '24 hours')
    ),
    'dual_control', public._dual_control_on(),
    'dual_control_changed_at', (select updated_at from public.system_config where key = 'dual_control_enabled')
  ) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_get_access_policies()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_ip inet := public._request_client_ip(); v jsonb;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'ip', jsonb_build_object(
      'enabled', public._ip_allowlist_on(),
      'caller_ip', host(v_ip),
      'caller_covered', public._ip_covered(v_ip),
      'entries', coalesce((select jsonb_agg(jsonb_build_object(
          'id', a.id, 'label', a.label, 'cidr', a.cidr::text, 'active', a.active,
          'created_at', a.created_at,
          'created_by_name', (select coalesce(p.full_name, p.email) from public.profiles p where p.id = a.created_by),
          'covers_caller', v_ip is not null and family(a.cidr) = family(v_ip) and v_ip <<= a.cidr)
          order by a.created_at) from public.console_ip_allowlist a), '[]'::jsonb)),
    'sso', jsonb_build_object(
      'registered_providers', (select count(*) from auth.sso_providers),
      'registered_domains', coalesce((select jsonb_agg(lower(domain) order by domain) from auth.sso_domains), '[]'::jsonb),
      'orgs', coalesce((select jsonb_agg(o order by o->>'name') from (
        select jsonb_build_object(
          'id', g.id, 'name', g.name,
          'connections', (select count(*) from public.sso_connections c where c.organisation_id = g.id),
          'active_connections', (select count(*) from public.sso_connections c where c.organisation_id = g.id and c.status = 'active'),
          'active_domains', coalesce((select jsonb_agg(distinct lower(btrim(x)))
              from public.sso_connections c, unnest(string_to_array(coalesce(c.domains, ''), ',')) x
             where c.organisation_id = g.id and c.status = 'active' and btrim(x) <> ''), '[]'::jsonb),
          'enforced_domains', to_jsonb(public._sso_enforced_domains(g.id)),
          'required', cardinality(public._sso_enforced_domains(g.id)) > 0,
          'affected_users', (select count(*) from public.profiles p join auth.users u on u.id = p.id
              where coalesce(p.organisation_id, p.org_id) = g.id and not coalesce(p.is_super_admin, false)
                and lower(split_part(u.email, '@', 2)) = any(public._sso_enforced_domains(g.id)))
        ) o from public.organisations g) s), '[]'::jsonb))
  ) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_get_access_review(p_campaign uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_c jsonb;
begin
  perform public._access_review_require_super();
  select to_jsonb(c) || jsonb_build_object(
           'created_by_email', (select email from public.profiles p where p.id = c.created_by),
           'closed_by_email',  (select email from public.profiles p where p.id = c.closed_by))
    into v_c from public.access_review_campaigns c where c.id = p_campaign;
  if v_c is null then raise exception 'Review not found.' using errcode = 'P0002'; end if;
  return jsonb_build_object('campaign', v_c, 'items', coalesce((
    select jsonb_agg(to_jsonb(i) || jsonb_build_object(
             'decided_by_email', (select email from public.profiles p where p.id = i.decided_by))
           order by i.full_name nulls last, i.user_email)
    from public.access_review_items i where i.campaign_id = p_campaign), '[]'::jsonb));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_get_effective_access(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text; v_super boolean; v_country text[]; v_modules jsonb;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a Super Admin can inspect effective access.' USING errcode = '42501';
  END IF;
  SELECT role, COALESCE(is_super_admin, false), country INTO v_role, v_super, v_country FROM public.profiles WHERE id = p_user_id;
  WITH keys AS (
    SELECT DISTINCT module_key FROM public.module_permissions WHERE role = v_role AND org_id IS NULL
    UNION
    SELECT DISTINCT module_key FROM public.user_access_grants WHERE user_id = p_user_id
  ),
  ra AS (
    SELECT module_key, bool_or(enabled) AS role_allows FROM public.module_permissions WHERE role = v_role AND org_id IS NULL GROUP BY module_key
  ),
  vov AS (
    SELECT module_key, effect FROM (
      SELECT DISTINCT ON (module_key) module_key, effect FROM public.user_access_grants
       WHERE user_id = p_user_id AND capability = 'view' AND (expires_at IS NULL OR expires_at > now())
       ORDER BY module_key, (effect = 'revoke') DESC
    ) z
  ),
  capov AS (
    SELECT module_key, jsonb_object_agg(capability, effect) AS caps FROM (
      SELECT DISTINCT ON (module_key, capability) module_key, capability, effect FROM public.user_access_grants
       WHERE user_id = p_user_id AND (expires_at IS NULL OR expires_at > now())
       ORDER BY module_key, capability, (effect = 'revoke') DESC
    ) z GROUP BY module_key
  )
  SELECT jsonb_agg(row_obj ORDER BY module_key) INTO v_modules
  FROM (
    SELECT k.module_key,
      jsonb_build_object(
        'key', k.module_key,
        'role_allows', COALESCE(ra.role_allows, false),
        'override', vov.effect,
        'caps', COALESCE(capov.caps, '{}'::jsonb),
        'final', CASE WHEN v_super OR v_role = 'Admin' THEN true WHEN vov.effect = 'revoke' THEN false WHEN COALESCE(ra.role_allows, false) THEN true WHEN vov.effect = 'grant' THEN true ELSE false END,
        'reason', CASE WHEN v_super OR v_role = 'Admin' THEN 'admin override' WHEN vov.effect = 'revoke' THEN 'per-user revoke' WHEN COALESCE(ra.role_allows, false) THEN 'role allows' WHEN vov.effect = 'grant' THEN 'per-user grant' ELSE 'denied by default' END
      ) AS row_obj
    FROM keys k
    LEFT JOIN ra ON ra.module_key = k.module_key
    LEFT JOIN vov ON vov.module_key = k.module_key
    LEFT JOIN capov ON capov.module_key = k.module_key
  ) assembled;
  RETURN jsonb_build_object('role', v_role, 'is_super', COALESCE(v_super, false), 'country', COALESCE(to_jsonb(v_country), '[]'::jsonb), 'modules', COALESCE(v_modules, '[]'::jsonb));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_grant_elevation(p_user_id uuid, p_module_key text, p_capability text, p_minutes integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid; v_id uuid; v_gid uuid;
  v_key text := lower(btrim(coalesce(p_module_key,'')));
  v_cap text := lower(btrim(coalesce(p_capability,'')));
  v_reason text := btrim(coalesce(p_reason,''));
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'Super admins already hold every capability' using errcode = '22023';
  end if;
  if p_minutes is null or p_minutes < 5 or p_minutes > 480 then
    raise exception 'Duration must be between 5 minutes and 8 hours' using errcode = '22023';
  end if;
  if length(v_reason) < 10 then
    raise exception 'A reason of at least 10 characters is required' using errcode = '22023';
  end if;
  v_org := public._jit_validate_target(p_user_id, v_key, v_cap);

  insert into public.jit_elevation_requests (organisation_id, target_user_id, requested_by, module_key,
                                             capability, requested_minutes, reason)
  values (v_org, p_user_id, auth.uid(), v_key, v_cap, p_minutes, left(v_reason, 1000))
  returning id into v_id;
  v_gid := public._jit_activate(v_id, p_minutes, 'Granted directly by a super admin');

  perform public._jit_audit('jit_elevation_grant', v_id, null,
    jsonb_build_object('status','approved','module_key',v_key,'capability',v_cap,'minutes',p_minutes,
                       'grant_id',v_gid,'target_user_id',p_user_id,'direct',true), v_reason);
  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    values (p_user_id, 'security', 'Temporary access granted',
            v_cap || ' on ' || v_key || ' for ' || p_minutes || ' minutes.', 'jit_elevation', v_id);
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'id', v_id, 'status', 'approved', 'grant_id', v_gid);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_import_history(p_limit integer DEFAULT 100)
 RETURNS TABLE(file_id uuid, filename text, module text, country text, sha256 text, size_bytes bigint, uploaded_by uuid, uploaded_at timestamp with time zone, batch_id uuid, approval_status text, import_status text, total_rows integer, imported_rows integer, duplicate_rows integer, error_rows integer, reupload_of uuid, reupload_first_seen timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  return query
  select f.id, f.original_filename, b.module, coalesce(b.country, f.country), f.sha256,
         f.size_bytes, f.created_by, f.created_at,
         b.id, b.approval_status, b.import_status,
         b.total_rows, b.imported_rows, b.duplicate_rows, b.error_rows,
         prior.id, prior.created_at
    from public.import_files f
    left join public.import_batches b on b.file_id = f.id
    -- an EARLIER file with the same content hash = this exact file was imported before
    left join lateral (
      select f2.id, f2.created_at
        from public.import_files f2
       where f2.sha256 = f.sha256
         and f2.sha256 is not null
         and f2.id <> f.id
         and f2.created_at < f.created_at
       order by f2.created_at asc
       limit 1
    ) prior on true
   where (f.organisation_id = v_org or public.is_super_admin())
   order by f.created_at desc
   limit greatest(1, least(coalesce(p_limit, 100), 1000));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_ip_allowlist_add(p_label text, p_cidr text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cidr cidr; v_id uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_label, ''))) not between 1 and 120 then
    raise exception 'Give the range a label of 1 to 120 characters.' using errcode = '22023';
  end if;
  begin
    v_cidr := network(btrim(p_cidr)::inet)::cidr;
  exception when others then
    raise exception 'That is not a valid IP address or CIDR range.' using errcode = '22023';
  end;
  if masklen(v_cidr) = 0 then
    raise exception 'A /0 range allows every address. Turn the allowlist off instead.' using errcode = '22023';
  end if;
  if exists (select 1 from public.console_ip_allowlist where cidr = v_cidr) then
    raise exception 'That range is already on the list.' using errcode = '22023';
  end if;
  insert into public.console_ip_allowlist (label, cidr) values (btrim(p_label), v_cidr) returning id into v_id;
  perform public._access_policy_audit('ip_allowlist_add', v_id, 'console_ip_allowlist',
    jsonb_build_object('label', btrim(p_label), 'cidr', v_cidr::text));
  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_ip_allowlist_delete(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.console_ip_allowlist; v_ip inet := public._request_client_ip();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  delete from public.console_ip_allowlist where id = p_id returning * into v_row;
  if v_row.id is null then raise exception 'That range no longer exists.' using errcode = '22023'; end if;
  if public._ip_allowlist_on() and not public._ip_covered(v_ip) then
    raise exception 'That would lock you out: your current IP would no longer be covered. Add a range for it first, or turn the allowlist off.'
      using errcode = '22023';
  end if;
  perform public._access_policy_audit('ip_allowlist_delete', p_id, 'console_ip_allowlist',
    jsonb_build_object('label', v_row.label, 'cidr', v_row.cidr::text));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_ip_allowlist_set_active(p_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.console_ip_allowlist; v_ip inet := public._request_client_ip();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select * into v_row from public.console_ip_allowlist where id = p_id for update;
  if not found then raise exception 'That range no longer exists.' using errcode = '22023'; end if;
  update public.console_ip_allowlist set active = coalesce(p_active, false), updated_at = now() where id = p_id;
  if public._ip_allowlist_on() and not public._ip_covered(v_ip) then
    raise exception 'That would lock you out: your current IP would no longer be covered. Add a range for it first, or turn the allowlist off.'
      using errcode = '22023';
  end if;
  perform public._access_policy_audit(case when p_active then 'ip_allowlist_activate' else 'ip_allowlist_deactivate' end,
    p_id, 'console_ip_allowlist', jsonb_build_object('label', v_row.label, 'cidr', v_row.cidr::text));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_access_reviews()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public._access_review_require_super();
  return coalesce((
    select jsonb_agg(to_jsonb(c) || jsonb_build_object(
             'total',    (select count(*) from public.access_review_items i where i.campaign_id = c.id),
             'pending',  (select count(*) from public.access_review_items i where i.campaign_id = c.id and i.decision = 'pending'),
             'kept',     (select count(*) from public.access_review_items i where i.campaign_id = c.id and i.decision = 'keep'),
             'revoked',  (select count(*) from public.access_review_items i where i.campaign_id = c.id and i.decision = 'revoke'),
             'modified', (select count(*) from public.access_review_items i where i.campaign_id = c.id and i.decision = 'modify'),
             'created_by_email', (select email from public.profiles p where p.id = c.created_by),
             'closed_by_email',  (select email from public.profiles p where p.id = c.closed_by))
           order by c.created_at desc)
    from public.access_review_campaigns c), '[]'::jsonb);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_api_keys()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_keys   jsonb;
  v_series jsonb;
  v_max    int;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;

  select nullif(btrim(value, ' "'), '')::int into v_max
    from public.system_config
   where key = 'api_key_max_age_days'
     and btrim(value, ' "') ~ '^[0-9]+$';

  select coalesce(jsonb_agg(row_to_json(k)::jsonb order by k.created_at desc), '[]'::jsonb)
    into v_keys
  from (
    select a.id, a.name, a.key_prefix, a.scopes, a.active, a.rate_per_minute,
           a.organisation_id, o.name as organisation_name,
           a.created_by, coalesce(cp.full_name, cp.email) as created_by_name,
           a.created_at, a.last_used_at, a.expires_at,
           a.revoked_at, a.revoked_by, coalesce(rp.full_name, rp.email) as revoked_by_name,
           a.revoke_reason,
           coalesce((select sum(u.count) from public.api_key_usage u
                      where u.key_id = a.id
                        and u.minute >= now() - interval '1 hour'), 0)::int as requests_last_hour
      from public.api_keys a
      left join public.organisations o on o.id = a.organisation_id
      left join public.profiles cp on cp.id = a.created_by
      left join public.profiles rp on rp.id = a.revoked_by
  ) k;

  select coalesce(jsonb_agg(jsonb_build_object('minute', s.minute, 'count', s.cnt) order by s.minute), '[]'::jsonb)
    into v_series
  from (select minute, sum(count)::int as cnt
          from public.api_key_usage
         where minute >= now() - interval '1 hour'
         group by minute) s;

  return jsonb_build_object(
    'keys', v_keys,
    'usage_last_hour', v_series,
    'usage_window', 'last_hour',
    'max_age_days', v_max,
    'generated_at', now()
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_approvals(p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows jsonb; v_supers int;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  update public.console_approval_requests set status = 'expired'
   where status in ('pending','approved') and expires_at <= now();

  select coalesce(jsonb_agg(to_jsonb(x) order by x.requested_at desc), '[]'::jsonb) into v_rows
    from (
      select a.*, rp.email as requested_by_email, coalesce(rp.full_name, rp.email) as requested_by_name,
             dp.email as decided_by_email, coalesce(dp.full_name, dp.email) as decided_by_name,
             (a.requested_by = auth.uid()) as is_mine
        from public.console_approval_requests a
        left join public.profiles rp on rp.id = a.requested_by
        left join public.profiles dp on dp.id = a.decided_by
       where p_status is null or p_status = '' or a.status = p_status
          or (p_status = 'open' and a.status in ('pending','approved'))
          or (p_status = 'decided' and a.status in ('approved','rejected','executed','expired','cancelled'))
       order by a.requested_at desc
       limit 500
    ) x;

  select count(*) into v_supers from public.profiles
   where coalesce(is_super_admin, false) and coalesce(approved, false) and not coalesce(locked, false);

  return jsonb_build_object('enabled', public._dual_control_on(), 'active_super_admins', v_supers,
                            'me', auth.uid(), 'rows', v_rows);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_elevations(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows jsonb; v_total int; v_lim int := least(greatest(coalesce(p_limit,1000),1),1000);
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  perform public.expire_jit_elevations();

  select count(*) into v_total from public.jit_elevation_requests
   where p_status is null or status = p_status;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc, x.id), '[]'::jsonb) into v_rows
  from (
    select r.*, coalesce(t.full_name, t.email) as target_name, t.role as target_role,
           coalesce(q.full_name, q.email) as requested_by_name,
           coalesce(d.full_name, d.email) as decided_by_name,
           coalesce(v.full_name, v.email) as revoked_by_name,
           o.name as organisation_name
      from public.jit_elevation_requests r
      left join public.profiles t on t.id = r.target_user_id
      left join public.profiles q on q.id = r.requested_by
      left join public.profiles d on d.id = r.decided_by
      left join public.profiles v on v.id = r.revoked_by
      left join public.organisations o on o.id = r.organisation_id
     where p_status is null or r.status = p_status
     order by r.created_at desc, r.id
     limit v_lim offset greatest(coalesce(p_offset,0),0)
  ) x;

  return jsonb_build_object('rows', v_rows, 'total', v_total, 'limit', v_lim,
                            'offset', greatest(coalesce(p_offset,0),0), 'generated_at', now());
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_incidents(p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_out jsonb;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can list incidents' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(s.j order by s.started_at desc), '[]'::jsonb) into v_out
  from (
    select jsonb_build_object(
      'id', i.id, 'title', i.title, 'severity', i.severity, 'status', i.status,
      'impact', i.impact, 'affected_modules', to_jsonb(i.affected_modules),
      'started_at', i.started_at, 'acknowledged_at', i.acknowledged_at, 'resolved_at', i.resolved_at,
      'commander', i.commander,
      'commander_name', (select coalesce(p.full_name, p.email) from public.profiles p where p.id = i.commander),
      'source_type', i.source_type, 'source_ref', i.source_ref,
      'created_by', i.created_by, 'created_at', i.created_at,
      'postmortem_summary', i.postmortem_summary,
      'postmortem_root_cause', i.postmortem_root_cause,
      'postmortem_actions', coalesce(i.postmortem_actions, '[]'::jsonb),
      'postmortem_at', i.postmortem_at,
      'postmortem_by', i.postmortem_by,
      'postmortem_by_name', (select coalesce(p.full_name, p.email) from public.profiles p where p.id = i.postmortem_by),
      'updates', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id', u.id, 'status', u.status, 'message', u.message, 'author', u.author,
                 'author_name', (select coalesce(p.full_name, p.email) from public.profiles p where p.id = u.author),
                 'created_at', u.created_at) order by u.created_at)
          from public.platform_incident_updates u where u.incident_id = i.id), '[]'::jsonb)
    ) as j, i.started_at
    from public.platform_incidents i
    where p_since is null or i.started_at >= p_since or i.status <> 'resolved'
    order by i.started_at desc
    limit greatest(1, least(coalesce(p_limit, 200), 1000))
  ) s;
  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_restore_tests(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'backups', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(t order by t.started_at desc), '[]'::jsonb) into v from (
    select id, snapshot_id, snapshot_taken_at, started_at, finished_at, tables_tested,
           rows_expected, rows_restored, status, detail
      from backups.restore_tests order by started_at desc limit greatest(1, least(coalesce(p_limit, 10), 100))
  ) t;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_security_scans(p_limit integer DEFAULT 26)
 RETURNS TABLE(id uuid, ran_at timestamp with time zone, trigger text, score integer, critical integer, high integer, medium integer, low integer, failing text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a Super Admin can view the security audit.' using errcode = '42501';
  end if;
  return query
    select r.id, r.ran_at, r.trigger, r.score, r.critical, r.high, r.medium, r.low, r.failing
      from public.security_scan_runs r order by r.ran_at desc limit greatest(1, least(p_limit, 200));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_user_devices()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can list devices' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', d.id,
      'user_id', d.user_id,
      'full_name', p.full_name,
      'username', p.username,
      'role', p.role,
      'organisation_id', d.organisation_id,
      'platform', d.platform,
      'app', case
        when d.push_token like 'ExponentPushToken%' then 'retired_expo'
        when d.app_version ~ '^0\.' then 'flutter'
        when d.push_token is not null and d.push_token <> '' then 'flutter'
        else 'unknown' end,
      'app_version', d.app_version,
      'device_tail', case when d.device_id is null or d.device_id = '' then null else right(d.device_id, 4) end,
      'last_seen_at', d.last_seen_at,
      'revoked', coalesce(d.revoked, false),
      'created_at', d.created_at
    ) order by d.last_seen_at desc nulls last, d.id), '[]'::jsonb)
    into v
    from public.user_devices d
    left join public.profiles p on p.id = d.user_id;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_webhook_deliveries(p_limit integer DEFAULT 50, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit int := greatest(1, least(coalesce(p_limit, 50), 500));
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'total', (select count(*) from public.webhook_deliveries d where p_status is null or d.status = p_status),
    'rows', coalesce((
      select jsonb_agg(x order by (x->>'id')::bigint desc) from (
        select jsonb_build_object(
          'id', d.id,
          'subscription_id', d.subscription_id,
          'subscription_name', s.name,
          'subscription_active', s.active,
          'event_type', d.event_type,
          'status', d.status,
          'attempts', d.attempts,
          'response_status', d.response_status,
          'last_error', left(d.last_error, 200),
          'created_at', d.created_at,
          'next_attempt_at', d.next_attempt_at,
          'delivered_at', d.delivered_at
        ) as x
          from public.webhook_deliveries d
          left join public.webhook_subscriptions s on s.id = d.subscription_id
         where p_status is null or d.status = p_status
         order by d.id desc
         limit v_limit) q), '[]'::jsonb));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_webhooks()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id,
      'name', s.name,
      'host', nullif(substring(s.url from '^[a-z]+://([^/?#]+)'), ''),
      'event_types', s.event_types,
      'active', s.active,
      'consecutive_failures', s.consecutive_failures,
      'disabled_reason', s.disabled_reason,
      'last_success_at', s.last_success_at,
      'last_failure_at', s.last_failure_at,
      'created_at', s.created_at,
      'organisation_id', s.organisation_id,
      'organisation_name', (select o.name from public.organisations o where o.id = s.organisation_id),
      'delivered', (select count(*) from public.webhook_deliveries d where d.subscription_id = s.id and d.status = 'delivered'),
      'pending', (select count(*) from public.webhook_deliveries d where d.subscription_id = s.id and d.status = 'pending'),
      'failed', (select count(*) from public.webhook_deliveries d where d.subscription_id = s.id and d.status = 'failed')
    ) order by s.created_at desc)
    from public.webhook_subscriptions s), '[]'::jsonb);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_mobile_user_action(p_user_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller       uuid := auth.uid();
  v_is_super     boolean;
  v_caller_role  text;
  v_caller_org   uuid;
  v_caller_lock  boolean;
  v_caller_appr  boolean;
  v_t_role       text;
  v_t_super      boolean;
  v_t_org        uuid;
  v_t_appr       boolean;
  v_t_lock       boolean;
  v_action       text := lower(btrim(coalesce(p_action, '')));
  v_reason       text := nullif(btrim(coalesce(p_reason, '')), '');
  v_new_role     text := btrim(coalesce(p_role, ''));
  v_target_priv  boolean;
  v_new_priv     boolean;
  v_others       integer;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  PERFORM pg_advisory_xact_lock(821746013);
  SELECT COALESCE(is_super_admin, false), role, org_id,
         COALESCE(locked, false), COALESCE(approved, true)
    INTO v_is_super, v_caller_role, v_caller_org, v_caller_lock, v_caller_appr
    FROM public.profiles WHERE id = v_caller FOR SHARE;

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not signed in.' USING errcode = '42501';
  END IF;

  IF NOT coalesce(public.app_is_active(),false) OR NOT coalesce(v_is_super,false) THEN
    RAISE EXCEPTION 'You do not have permission to manage users.' USING errcode = '42501';
  END IF;

  IF v_action NOT IN ('approve','lock','unlock','deactivate','set_role') THEN
    RAISE EXCEPTION 'Unknown action.' USING errcode = '22023';
  END IF;

  SELECT role, COALESCE(is_super_admin, false), org_id,
         COALESCE(approved, false), COALESCE(locked, false)
    INTO v_t_role, v_t_super, v_t_org, v_t_appr, v_t_lock
    FROM public.profiles WHERE id = p_user_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'That user could not be found.' USING errcode = 'P0002';
  END IF;

  IF p_user_id = v_caller THEN
    IF v_action IN ('lock','deactivate') THEN
      RAISE EXCEPTION 'You cannot lock or deactivate your own account.' USING errcode = '42501';
    END IF;
    IF v_action = 'set_role' THEN
      RAISE EXCEPTION 'You cannot change your own role.' USING errcode = '42501';
    END IF;
  END IF;

  IF NOT v_is_super AND v_t_org IS DISTINCT FROM v_caller_org THEN
    RAISE EXCEPTION 'That user belongs to another organisation.' USING errcode = '42501';
  END IF;

  v_target_priv := v_t_super OR (lower(coalesce(v_t_role, '')) = 'admin');
  v_new_priv    := (v_action = 'set_role' AND lower(v_new_role) = 'admin');

  IF NOT v_is_super THEN
    IF v_t_super THEN
      RAISE EXCEPTION 'Only a super admin can manage a super admin.' USING errcode = '42501';
    END IF;
    IF v_target_priv AND v_action IN ('lock','deactivate','set_role') THEN
      RAISE EXCEPTION 'Only a super admin can change an administrator.' USING errcode = '42501';
    END IF;
    IF v_new_priv THEN
      RAISE EXCEPTION 'Only a super admin can grant the Admin role.' USING errcode = '42501';
    END IF;
  END IF;

  IF v_action IN ('lock','deactivate','set_role') THEN
    IF v_t_super THEN
      SELECT count(*) INTO v_others FROM public.profiles
        WHERE id <> p_user_id AND COALESCE(is_super_admin, false) AND COALESCE(locked, false) = false AND COALESCE(approved, false);
      IF v_others = 0 THEN
        RAISE EXCEPTION 'You cannot lock, deactivate or demote the last super admin.' USING errcode = '42501';
      END IF;
    END IF;
    IF lower(coalesce(v_t_role, '')) = 'admin'
       AND NOT v_t_lock AND v_t_appr
       AND (v_action IN ('lock','deactivate') OR (v_action = 'set_role' AND lower(v_new_role) <> 'admin')) THEN
      SELECT count(*) INTO v_others FROM public.profiles
        WHERE id <> p_user_id AND role = 'Admin'
          AND org_id IS NOT DISTINCT FROM v_t_org
          AND COALESCE(locked, false) = false AND COALESCE(approved, true);
      IF v_others = 0 THEN
        RAISE EXCEPTION 'You cannot remove the last administrator of this organisation.' USING errcode = '42501';
      END IF;
    END IF;
  END IF;

  IF v_action IN ('set_role','deactivate') AND v_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required for this action.' USING errcode = '22023';
  END IF;
  IF v_action = 'set_role' AND v_new_role = '' THEN
    RAISE EXCEPTION 'A role is required.' USING errcode = '22023';
  END IF;

  IF v_action = 'approve' THEN
    UPDATE public.profiles SET approved = true, updated_at = now() WHERE id = p_user_id;
  ELSIF v_action = 'lock' THEN
    UPDATE public.profiles SET locked = true, updated_at = now() WHERE id = p_user_id;
  ELSIF v_action = 'unlock' THEN
    UPDATE public.profiles SET locked = false, updated_at = now() WHERE id = p_user_id;
  ELSIF v_action = 'deactivate' THEN
    UPDATE public.profiles SET approved = false, locked = true, updated_at = now() WHERE id = p_user_id;
  ELSIF v_action = 'set_role' THEN
    UPDATE public.profiles SET role = v_new_role, updated_at = now() WHERE id = p_user_id;
  END IF;

  INSERT INTO public.access_audit
    (actor, actor_email, action, target_user, entity, before, after, reason)
  VALUES (
    v_caller,
    public.access_audit_actor_email(),
    'UPDATE',
    p_user_id,
    'mobile_' || v_action,
    jsonb_build_object('role', v_t_role, 'approved', v_t_appr, 'locked', v_t_lock, 'is_super_admin', v_t_super),
    jsonb_build_object('action', v_action, 'role', CASE WHEN v_action = 'set_role' THEN v_new_role ELSE v_t_role END),
    v_reason
  );

  RETURN jsonb_build_object('success', true, 'action', v_action);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_open_incident(p_title text, p_severity text, p_impact text DEFAULT NULL::text, p_affected_modules text[] DEFAULT '{}'::text[], p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_commander uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_ref text DEFAULT NULL::text, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_id      uuid;
  v_sev     text := lower(btrim(coalesce(p_severity, '')));
  v_title   text := btrim(coalesce(p_title, ''));
  v_start   timestamptz := coalesce(p_started_at, now());
  v_mods    text[];
  v_who     text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can open an incident' using errcode = '42501';
  end if;
  if char_length(v_title) < 3 or char_length(v_title) > 200 then
    raise exception 'An incident needs a title of 3 to 200 characters' using errcode = '22023';
  end if;
  if v_sev not in ('sev1','sev2','sev3','sev4') then
    raise exception 'Severity must be sev1, sev2, sev3 or sev4' using errcode = '22023';
  end if;
  if v_start > now() + interval '5 minutes' then
    raise exception 'An incident cannot start in the future' using errcode = '22023';
  end if;
  if p_source_type is not null and p_source_type not in ('system_log','trust_alert','security_scan','crash','manual','sentry') then
    raise exception 'Unknown incident source' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct m order by m), '{}') into v_mods
    from unnest(coalesce(p_affected_modules, '{}')) as u(m0),
         lateral (select lower(btrim(m0)) as m) x
   where m <> '';

  insert into public.platform_incidents
    (title, severity, impact, affected_modules, started_at, commander, source_type, source_ref, created_by)
  values
    (v_title, v_sev, nullif(btrim(coalesce(p_impact, '')), ''), v_mods, v_start,
     coalesce(p_commander, v_uid), p_source_type, nullif(btrim(coalesce(p_source_ref, '')), ''), v_uid)
  returning id into v_id;

  insert into public.platform_incident_updates (incident_id, status, message, author)
  values (v_id, 'investigating', coalesce(nullif(btrim(coalesce(p_message, '')), ''), 'Incident opened.'), v_uid);

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'incident_open', v_id, 'platform_incident',
          jsonb_build_object('severity', v_sev, 'title', v_title, 'source_type', p_source_type, 'source_ref', p_source_ref));

  if v_sev in ('sev1','sev2') then
    select coalesce(full_name, email) into v_who from public.profiles where id = v_uid;
    begin
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      select p.id, 'security',
             upper(v_sev) || ' incident opened: ' || v_title,
             coalesce(v_who, 'A super admin') || ' opened it at '
               || to_char(v_start at time zone 'Asia/Riyadh', 'DD Mon YYYY HH24:MI') || ' (Riyadh).',
             'platform_incident', v_id
        from public.profiles p
       where coalesce(p.is_super_admin, false) and not coalesce(p.locked, false);
    exception when others then
      null;
    end;
  end if;

  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_org_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the organization overview' using errcode = '42501';
  end if;

  with mem as (
    select coalesce(p.organisation_id, p.org_id) as org,
           count(*) as members,
           count(*) filter (where u.last_sign_in_at > now() - interval '30 days') as active_30d,
           count(*) filter (where u.last_sign_in_at > now() - interval '7 days') as active_7d,
           count(*) filter (where u.last_sign_in_at is not null) as ever_signed_in
      from public.profiles p left join auth.users u on u.id = p.id
     group by 1
  ), veh as (
    select organisation_id as org, count(*) as n, max(created_at) as last_at,
           array_remove(array_agg(distinct country), null) as countries
      from public.vehicle_fleet group by 1
  ), tyr as (select organisation_id as org, count(*) as n, max(created_at) as last_at from public.tyre_records group by 1),
     wo  as (select organisation_id as org, count(*) as n, max(created_at) as last_at from public.work_orders group by 1),
     exp as (select organisation_id as org, count(*) as n, max(created_at) as last_at from public.parts_consumption group by 1),
     ins as (select organisation_id as org, count(*) as n, max(created_at) as last_at from public.inspections group by 1)
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id,
           'members', coalesce(mem.members, 0),
           'active_30d', coalesce(mem.active_30d, 0),
           'active_7d', coalesce(mem.active_7d, 0),
           'ever_signed_in', coalesce(mem.ever_signed_in, 0),
           'vehicles', coalesce(veh.n, 0),
           'tyre_records', coalesce(tyr.n, 0),
           'job_cards', coalesce(wo.n, 0),
           'expense_lines', coalesce(exp.n, 0),
           'inspections', coalesce(ins.n, 0),
           'data_countries', to_jsonb(coalesce(veh.countries, '{}'::text[])),
           'last_write_at', nullif(greatest(
               coalesce(veh.last_at, '-infinity'), coalesce(tyr.last_at, '-infinity'),
               coalesce(wo.last_at, '-infinity'), coalesce(exp.last_at, '-infinity'),
               coalesce(ins.last_at, '-infinity')), '-infinity'::timestamptz)
         ) order by o.created_at), '[]'::jsonb)
    into v
    from public.organisations o
    left join mem on mem.org = o.id
    left join veh on veh.org = o.id
    left join tyr on tyr.org = o.id
    left join wo  on wo.org  = o.id
    left join exp on exp.org = o.id
    left join ins on ins.org = o.id;

  return jsonb_build_object('ok', true, 'generated_at', now(), 'orgs', v);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_org_storage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  with f as (
    select o.bucket_id, coalesce((o.metadata->>'size')::bigint, 0) as bytes,
           coalesce(p.org_id, p.organisation_id) as org_id
      from storage.objects o
      left join public.profiles p on p.id = o.owner
  )
  select jsonb_build_object(
    'orgs', coalesce((select jsonb_agg(jsonb_build_object('org_id', s.org_id, 'files', s.n, 'bytes', s.b, 'by_bucket', s.bb))
      from (select x.org_id, sum(x.nb)::bigint n, sum(x.sb)::bigint b, jsonb_object_agg(x.bucket_id, x.nb) bb
              from (select org_id, bucket_id, count(*) nb, sum(bytes) sb from f where org_id is not null group by 1, 2) x
             group by x.org_id) s), '[]'::jsonb),
    'unattributed_files', (select count(*) from f where org_id is null),
    'unattributed_bytes', (select coalesce(sum(bytes), 0) from f where org_id is null),
    'total_files', (select count(*) from f),
    'total_bytes', (select coalesce(sum(bytes), 0) from f)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_post_incident_update(p_incident_id uuid, p_status text, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_inc   public.platform_incidents%rowtype;
  v_to    text := lower(btrim(coalesce(p_status, '')));
  v_msg   text := btrim(coalesce(p_message, ''));
  v_upd   uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can update an incident' using errcode = '42501';
  end if;
  if char_length(v_msg) < 1 or char_length(v_msg) > 4000 then
    raise exception 'An update needs a message' using errcode = '22023';
  end if;
  select * into v_inc from public.platform_incidents where id = p_incident_id for update;
  if not found then
    raise exception 'Incident not found' using errcode = 'P0002';
  end if;
  if v_to not in ('investigating','identified','monitoring','resolved') then
    raise exception 'Unknown incident status' using errcode = '22023';
  end if;
  if not public.incident_status_allowed(v_inc.status, v_to) then
    raise exception 'An incident cannot move from % to %', v_inc.status, v_to using errcode = '22023';
  end if;

  update public.platform_incidents
     set status = v_to,
         acknowledged_at = coalesce(acknowledged_at, now()),
         resolved_at = case
           when v_to = 'resolved' and v_inc.status <> 'resolved' then greatest(now(), started_at)
           when v_to = 'resolved' then resolved_at
           else null end
   where id = p_incident_id;

  insert into public.platform_incident_updates (incident_id, status, message, author)
  values (p_incident_id, v_to, v_msg, v_uid)
  returning id into v_upd;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'incident_update', p_incident_id, 'platform_incident',
          jsonb_build_object('from', v_inc.status, 'to', v_to, 'update_id', v_upd));

  return jsonb_build_object('id', v_upd, 'from', v_inc.status, 'to', v_to);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_query_time_reset(p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  perform extensions.pg_stat_statements_reset();
  insert into public.console_sessions (admin_id, action, target_type, details)
  values (auth.uid(), 'query_counters_reset', 'database', jsonb_build_object('reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'reset_at', now());
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_query_time_top(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
declare
  v_total double precision;
  v_since timestamptz;
  v_rows jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  begin
    select stats_reset into v_since from extensions.pg_stat_statements_info();
    select sum(total_exec_time) into v_total from extensions.pg_stat_statements(true);
  exception when others then
    return jsonb_build_object('ok', false, 'reason', 'unavailable');
  end;

  select coalesce(jsonb_agg(r order by r.total_ms desc), '[]'::jsonb) into v_rows from (
    select q.queryid::text as id,
           q.calls,
           round(q.total_exec_time::numeric, 1) as total_ms,
           round(q.mean_exec_time::numeric, 2) as mean_ms,
           round((100.0 * q.total_exec_time / nullif(v_total, 0))::numeric, 2) as share_pct,
           left(regexp_replace(regexp_replace(q.query, '''[^'']*''', '''?''', 'g'), '\s+', ' ', 'g'), 220) as shape
      from extensions.pg_stat_statements(true) q
     where q.query ~* '^\s*(select|insert|update|delete|with)\y'
     order by q.total_exec_time desc
     limit greatest(1, least(coalesce(p_limit, 12), 50))
  ) r;

  return jsonb_build_object('ok', true, 'since', v_since, 'total_ms', round(coalesce(v_total, 0)::numeric, 1), 'rows', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_recent_migrations(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'supabase_migrations'
AS $function$
declare v jsonb; v_today text := to_char(now() at time zone 'Asia/Riyadh', 'YYYYMMDD');
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the migration history' using errcode = '42501';
  end if;
  if to_regclass('supabase_migrations.schema_migrations') is null then
    return jsonb_build_object('ok', false, 'reason', 'Migration history is not available');
  end if;
  select jsonb_build_object(
    'ok', true,
    'total', (select count(*) from supabase_migrations.schema_migrations),
    'today', (select count(*) from supabase_migrations.schema_migrations where version like v_today || '%'),
    'latest', (select max(version) from supabase_migrations.schema_migrations),
    'items', coalesce((select jsonb_agg(jsonb_build_object('version', m.version, 'name', m.name) order by m.version desc)
                         from (select version, name from supabase_migrations.schema_migrations
                                order by version desc limit least(greatest(coalesce(p_limit, 12), 1), 100)) m), '[]'::jsonb)
  ) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_record_rollback(p_platform text, p_from text, p_to text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can record a rollback' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_to), '') = '' then
    raise exception 'Name the build you are rolling back to.' using errcode = '22023';
  end if;
  insert into public.releases (version, notes, released_by, kind, platform, from_version, to_version, reason)
  values (btrim(p_to), 'Rollback from ' || coalesce(nullif(btrim(p_from), ''), 'unknown') || ' to ' || btrim(p_to),
          auth.uid(), 'rollback', coalesce(nullif(btrim(p_platform), ''), 'web'), nullif(btrim(p_from), ''),
          btrim(p_to), btrim(p_reason))
  returning id into v_id;
  perform public.log_console_event('release_rollback', null, 'release',
    jsonb_build_object('release_id', v_id, 'platform', p_platform, 'from', p_from, 'to', p_to, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'id', v_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_release_error_windows(p_at timestamp with time zone[], p_hours numeric DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can compare release errors' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'at', t.at,
           'window_hours', round(extract(epoch from t.win) / 3600.0, 2),
           'complete', t.win >= make_interval(secs => greatest(coalesce(p_hours, 12), 0.25) * 3600),
           'before', (select count(*) from public.system_logs s
                       where s.severity in ('error', 'critical') and s.created_at >= t.at - t.win and s.created_at < t.at),
           'after',  (select count(*) from public.system_logs s
                       where s.severity in ('error', 'critical') and s.created_at >= t.at and s.created_at < t.at + t.win)
         ) order by t.at desc), '[]'::jsonb)
    into v
    from (
      select a as at,
             least(make_interval(secs => greatest(coalesce(p_hours, 12), 0.25) * 3600), greatest(now() - a, interval '0')) as win
        from unnest(coalesce(p_at, '{}'::timestamptz[])) a
       where a is not null and a <= now()
       limit 60
    ) t;
  return jsonb_build_object('ok', true, 'items', v);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_remove_storage_retention_rule(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_before jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  select to_jsonb(r) into v_before from public.storage_retention_rules r where r.id = p_id;
  if v_before is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  delete from public.storage_retention_rules where id = p_id;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'storage_retention_rule_removed', p_id, 'storage_retention_rule',
          jsonb_build_object('reason', btrim(p_reason), 'before', v_before));
  return jsonb_build_object('ok', true);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_request_approval(p_action text, p_payload jsonb, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_canon jsonb; v_id uuid; v_who text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  v_canon := public._approval_canonical(p_action, p_payload);
  if p_action = 'dual_control_disable' and not public._dual_control_on() then
    raise exception 'Dual control is already off.' using errcode = '22023';
  end if;

  update public.console_approval_requests set status = 'expired'
   where status in ('pending','approved') and expires_at <= now();
  if exists (select 1 from public.console_approval_requests
              where action = p_action and payload = v_canon and requested_by = auth.uid()
                and status in ('pending','approved') and expires_at > now()) then
    raise exception 'You already have an open request for exactly this action.' using errcode = '22023';
  end if;

  insert into public.console_approval_requests (action, payload, reason, requested_by)
  values (p_action, v_canon, btrim(p_reason), auth.uid())
  returning id into v_id;

  perform public.log_console_event('dual_control_requested', v_id::text, 'console_approval',
                                   jsonb_build_object('action', p_action, 'payload', v_canon));

  select coalesce(full_name, email) into v_who from public.profiles where id = auth.uid();
  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    select p.id, 'security', 'Console action waiting for your approval',
           coalesce(v_who, 'A super admin') || ' asked to run ' || replace(p_action, '_', ' ')
             || '. Reason: ' || left(btrim(p_reason), 200),
           'console_approval', v_id
      from public.profiles p
     where coalesce(p.is_super_admin, false) and coalesce(p.approved, false)
       and not coalesce(p.locked, false) and p.id <> auth.uid();
  exception when others then null;
  end;
  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_resend_webhook_delivery(p_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.webhook_deliveries%rowtype;
  v_active boolean;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if v_reason is null or length(v_reason) < 3 then
    raise exception 'A reason is required to resend a delivery.' using errcode = '22023';
  end if;
  select * into v_row from public.webhook_deliveries where id = p_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_row.status = 'delivered' then
    return jsonb_build_object('ok', false, 'reason', 'already_delivered');
  end if;
  if v_row.request_id is not null then
    return jsonb_build_object('ok', false, 'reason', 'in_flight');
  end if;
  select active into v_active from public.webhook_subscriptions where id = v_row.subscription_id;

  update public.webhook_deliveries
     set status = 'pending',
         attempts = least(attempts, 5),
         next_attempt_at = now()
   where id = p_id;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'webhook_resend', null, 'webhook_delivery',
          jsonb_build_object('delivery_id', p_id, 'subscription_id', v_row.subscription_id,
                             'previous_status', v_row.status, 'previous_attempts', v_row.attempts,
                             'webhook_active', coalesce(v_active, false), 'reason', left(v_reason, 500)));

  return jsonb_build_object('ok', true, 'will_send', coalesce(v_active, false),
                            'previous_status', v_row.status);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_retry_failed_notifications(p_ids bigint[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := 0;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can retry deliveries' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then
    raise exception 'Choose at least one failed delivery.' using errcode = '22023';
  end if;
  if cardinality(p_ids) > 500 then
    raise exception 'Retry at most 500 deliveries at a time.' using errcode = '22023';
  end if;
  update public.workflow_notifications
     set status = 'pending', attempts = 0, next_attempt_at = now(),
         request_id = null, last_error = null
   where id = any(p_ids) and status = 'failed';
  get diagnostics n = row_count;
  perform public.log_console_event('push_retry_failed', null, 'workflow_notifications',
    jsonb_build_object('requested', cardinality(p_ids), 'requeued', n, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'requeued', n, 'requested', cardinality(p_ids));
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_revoke_api_key(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before public.api_keys%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_email  text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if v_reason is null or length(v_reason) < 5 then
    raise exception 'A revoke reason of at least 5 characters is required' using errcode = '22023';
  end if;

  select * into v_before from public.api_keys where id = p_id for update;
  if not found then
    raise exception 'API key not found' using errcode = 'P0002';
  end if;
  if not v_before.active then
    return jsonb_build_object('ok', false, 'reason', 'already_revoked');
  end if;

  update public.api_keys
     set active = false, revoked_at = now(), revoked_by = auth.uid(),
         revoke_reason = left(v_reason, 500)
   where id = p_id;

  select email into v_email from public.profiles where id = auth.uid();

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'api_key_revoke', p_id, 'api_key',
          jsonb_build_object('name', v_before.name, 'prefix', v_before.key_prefix,
                             'organisation_id', v_before.organisation_id,
                             'reason', left(v_reason, 500)));

  insert into public.access_audit (actor, actor_email, action, entity, before, after, reason)
  values (auth.uid(), v_email, 'api_key_revoke', 'api_key',
          jsonb_build_object('id', p_id, 'prefix', v_before.key_prefix, 'active', true,
                             'organisation_id', v_before.organisation_id),
          jsonb_build_object('id', p_id, 'prefix', v_before.key_prefix, 'active', false),
          left(v_reason, 500));

  return jsonb_build_object('ok', true, 'id', p_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_revoke_elevation(p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.jit_elevation_requests%rowtype; v_reason text := btrim(coalesce(p_reason,''));
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if length(v_reason) < 5 then
    raise exception 'A revoke reason of at least 5 characters is required' using errcode = '22023';
  end if;
  select * into r from public.jit_elevation_requests where id = p_id for update;
  if not found then raise exception 'Request not found' using errcode = 'P0002'; end if;
  if r.status <> 'approved' then return jsonb_build_object('ok', false, 'reason', 'not_active', 'status', r.status); end if;

  delete from public.user_access_grants
   where id = r.grant_id and expires_at is not null and expires_at <= r.expires_at + interval '1 second';

  update public.jit_elevation_requests
     set status = 'revoked', revoked_by = auth.uid(), revoked_at = now(),
         revoke_reason = left(v_reason, 500), updated_at = now()
   where id = p_id;
  perform public._jit_audit('jit_elevation_revoke', p_id, jsonb_build_object('status','approved','expires_at',r.expires_at),
    jsonb_build_object('status','revoked','module_key',r.module_key,'capability',r.capability,'target_user_id',r.target_user_id), v_reason);
  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    values (r.target_user_id, 'security', 'Temporary access ended early',
            r.capability || ' on ' || r.module_key || ': ' || left(v_reason, 200), 'jit_elevation', p_id);
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'revoked');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_revoke_user_device(p_device_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_row public.user_devices%rowtype;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can stop push to a device' using errcode = '42501';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  update public.user_devices set revoked = true
   where id = p_device_id and not coalesce(revoked, false)
  returning * into v_row;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found_or_already_stopped');
  end if;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'revoke_user_device', v_row.user_id, 'user_device',
          jsonb_build_object('device_id', v_row.id, 'reason', v_reason,
            'app', case when v_row.push_token like 'ExponentPushToken%' then 'retired_expo' else 'flutter' end));
  return jsonb_build_object('ok', true, 'user_id', v_row.user_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_revoke_user_sessions(p_actor uuid, p_target uuid, p_reason text, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
declare
  v_actor      public.profiles%rowtype;
  v_target     public.profiles%rowtype;
  v_reason     text := nullif(btrim(coalesce(p_reason, '')), '');
  v_count      integer := 0;
  v_locked     boolean := false;
  v_was_locked boolean;
  v_email      text;
begin
  if p_actor is null or p_target is null then
    raise exception 'Missing actor or target.' using errcode = '22023';
  end if;
  if v_reason is null or length(v_reason) < 3 then
    raise exception 'A reason is required.' using errcode = '22023';
  end if;
  if length(v_reason) > 500 then
    v_reason := left(v_reason, 500);
  end if;
  if p_actor = p_target then
    raise exception 'You cannot revoke your own sessions here.' using errcode = '22023';
  end if;

  select * into v_actor from public.profiles where id = p_actor;
  if not found or not coalesce(v_actor.is_super_admin, false) or coalesce(v_actor.locked, false) then
    raise exception 'Not authorized.' using errcode = '42501';
  end if;

  select * into v_target from public.profiles where id = p_target;
  if not found then
    raise exception 'User not found.' using errcode = 'P0002';
  end if;
  v_was_locked := coalesce(v_target.locked, false);

  select email into v_email from auth.users where id = p_actor;

  perform set_config('request.jwt.claims',
    jsonb_build_object('sub', p_actor::text, 'role', 'authenticated')::text, true);

  if coalesce(p_lock, false) and not v_was_locked then
    update public.profiles set locked = true where id = p_target;
    v_locked := true;
  elsif v_was_locked then
    v_locked := true;
  end if;

  v_count := public.revoke_user_sessions(p_target);

  insert into public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
  values (p_actor, v_email, 'REVOKE', p_target, 'session_revoke',
          jsonb_build_object('locked', v_was_locked),
          jsonb_build_object('sessions_revoked', v_count, 'locked', v_locked),
          v_reason);

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (p_actor, 'revoke_sessions', p_target, 'user',
          jsonb_build_object('sessions_revoked', v_count, 'locked', v_locked,
                             'lock_requested', coalesce(p_lock, false), 'reason', v_reason));

  return jsonb_build_object('ok', true, 'sessions_revoked', v_count, 'locked', v_locked);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_run_restore_test(p_snapshot_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'backups', 'pg_catalog'
AS $function$
declare
  v_snap uuid := p_snapshot_id;
  v_taken timestamptz;
  v_test uuid;
  r record;
  v_tmp text;
  v_restored bigint;
  v_expected bigint := 0;
  v_total bigint := 0;
  v_detail jsonb := '[]'::jsonb;
  v_failed boolean := false;
  v_tables int := 0;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if v_snap is null then
    select id, taken_at into v_snap, v_taken from backups.snapshots order by taken_at desc limit 1;
  else
    select taken_at into v_taken from backups.snapshots where id = v_snap;
  end if;
  if v_taken is null then
    return jsonb_build_object('ok', false, 'reason', 'no_snapshot');
  end if;

  insert into backups.restore_tests (snapshot_id, snapshot_taken_at) values (v_snap, v_taken) returning id into v_test;

  for r in
    select st.table_name, sum(st.row_count) filter (where st.status = 'ok') as expected,
           bool_or(st.status <> 'ok') as partial
      from backups.snapshot_tables st
     where st.snapshot_id = v_snap
     group by st.table_name order by st.table_name
  loop
    v_tables := v_tables + 1;
    v_tmp := 'restore_test_' || replace(v_test::text, '-', '') || '_' || v_tables;
    begin
      if to_regclass('public.' || quote_ident(r.table_name)) is null then
        raise exception 'table no longer exists';
      end if;
      execute format('create temp table %I (like public.%I)', v_tmp, r.table_name);
      execute format(
        'insert into %I select b.* from backups.snapshot_tables st
           cross join lateral jsonb_populate_recordset(null::public.%I, st.data) b
          where st.snapshot_id = %L and st.table_name = %L and st.status = ''ok''',
        v_tmp, r.table_name, v_snap, r.table_name);
      execute format('select count(*) from %I', v_tmp) into v_restored;
      execute format('drop table %I', v_tmp);
      v_expected := v_expected + coalesce(r.expected, 0);
      v_total := v_total + v_restored;
      if v_restored <> coalesce(r.expected, 0) then v_failed := true; end if;
      v_detail := v_detail || jsonb_build_array(jsonb_build_object(
        'table', r.table_name, 'expected', coalesce(r.expected, 0), 'restored', v_restored,
        'skipped_part', coalesce(r.partial, false),
        'ok', v_restored = coalesce(r.expected, 0)));
    exception when others then
      v_failed := true;
      begin execute format('drop table if exists %I', v_tmp); exception when others then null; end;
      v_detail := v_detail || jsonb_build_array(jsonb_build_object(
        'table', r.table_name, 'expected', coalesce(r.expected, 0), 'restored', 0, 'ok', false,
        'error', 'Rows could not be rebuilt from this copy'));
    end;
  end loop;

  update backups.restore_tests
     set finished_at = now(), tables_tested = v_tables, rows_expected = v_expected,
         rows_restored = v_total, detail = v_detail,
         status = case when v_failed or v_tables = 0 then 'failed' else 'passed' end
   where id = v_test;

  insert into public.console_sessions (admin_id, action, target_type, details)
  values (auth.uid(), 'restore_test_run', 'backup',
          jsonb_build_object('snapshot_id', v_snap, 'tables', v_tables, 'rows_expected', v_expected,
                             'rows_restored', v_total, 'passed', not (v_failed or v_tables = 0)));

  return jsonb_build_object('ok', true, 'test_id', v_test, 'snapshot_id', v_snap, 'snapshot_taken_at', v_taken,
    'tables_tested', v_tables, 'rows_expected', v_expected, 'rows_restored', v_total,
    'status', case when v_failed or v_tables = 0 then 'failed' else 'passed' end, 'detail', v_detail);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_run_security_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a Super Admin can run the security audit.' using errcode = '42501';
  end if;
  return public._security_scan_record('manual', auth.uid());
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_save_storage_retention_rule(p_id uuid, p_bucket text, p_prefix text, p_min_bytes bigint, p_older_than_days integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v_id uuid := p_id; v_before jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  if not exists (select 1 from storage.buckets where id = p_bucket) then
    raise exception 'Unknown bucket' using errcode = '22023';
  end if;
  if p_bucket in ('tyre-photos', 'accident-photos', 'driver-fine-evidence', 'inspection-photos') then
    raise exception 'Photos and evidence are kept. A rule on this bucket needs an owner decision.' using errcode = '22023';
  end if;
  if p_bucket = 'tenant-exports' then
    raise exception 'Tenant exports already have their own 7-day rule. Change it with the export retention setting.' using errcode = '22023';
  end if;
  if p_older_than_days is null or p_older_than_days < 1 or p_older_than_days > 3650 then
    raise exception 'Keep days must be between 1 and 3650' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.storage_retention_rules (bucket, prefix, min_bytes, older_than_days, reason)
    values (p_bucket, nullif(btrim(p_prefix), ''), p_min_bytes, p_older_than_days, btrim(p_reason))
    returning id into v_id;
  else
    select to_jsonb(r) into v_before from public.storage_retention_rules r where r.id = v_id;
    if v_before is null then raise exception 'Rule not found' using errcode = '22023'; end if;
    update public.storage_retention_rules
       set bucket = p_bucket, prefix = nullif(btrim(p_prefix), ''), min_bytes = p_min_bytes,
           older_than_days = p_older_than_days, reason = btrim(p_reason),
           updated_by = auth.uid(), updated_at = now()
     where id = v_id;
  end if;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'storage_retention_rule_saved', v_id, 'storage_retention_rule',
          jsonb_build_object('bucket', p_bucket, 'prefix', nullif(btrim(p_prefix), ''), 'min_bytes', p_min_bytes,
                             'older_than_days', p_older_than_days, 'reason', btrim(p_reason), 'before', v_before));
  return jsonb_build_object('ok', true, 'id', v_id, 'enabled', false);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_schedule_flag_change(p_target_type text, p_target_key text, p_new_state text, p_run_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_status text;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can schedule a flag change' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  if not public._flag_state_valid(p_target_type, p_new_state) then
    raise exception 'That state is not valid for this item.' using errcode = '22023';
  end if;
  if p_target_type = 'module' and not exists (select 1 from public.modules where module_id = p_target_key) then
    raise exception 'That module does not exist.' using errcode = '22023';
  end if;
  if p_target_type = 'config' and not exists (select 1 from public.system_config where key = p_target_key) then
    raise exception 'That platform switch does not exist.' using errcode = '22023';
  end if;
  if p_target_type = 'config' and p_target_key in ('dual_control_enabled', 'console_ip_allowlist_enabled', 'maintenance_mode') then
    raise exception 'This switch has its own guarded screen and cannot be scheduled here.' using errcode = '22023';
  end if;
  if p_run_at is null or p_run_at < now() - interval '1 minute' then
    raise exception 'Pick a time that is now or later.' using errcode = '22023';
  end if;
  v_status := case when public._dual_control_on() then 'awaiting_approval' else 'scheduled' end;
  insert into public.flag_changes (target_type, target_key, new_state, run_at, status, reason, requested_by)
  values (p_target_type, p_target_key, p_new_state, p_run_at, v_status, btrim(p_reason), auth.uid())
  returning id into v_id;
  perform public.log_console_event('flag_change_scheduled', null, 'flag_change',
    jsonb_build_object('id', v_id, 'target_type', p_target_type, 'target', p_target_key, 'state', p_new_state,
                       'run_at', p_run_at, 'status', v_status, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'id', v_id, 'status', v_status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_security_posture()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a Super Admin can view the security audit.' using errcode = '42501';
  end if;
  return public._security_posture_compute();
end $function$;
