CREATE OR REPLACE FUNCTION public.admin_send_person_reminder(p_user uuid, p_title text, p_body text, p_reason text, p_copy_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_title text := left(btrim(coalesce(p_title, '')), 120);
  v_body  text := left(btrim(coalesce(p_body, '')), 1000);
  v_sent  integer := 0;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can send a reminder from the console' using errcode = '42501';
  end if;
  if p_user is null or not exists (select 1 from public.profiles where id = p_user) then
    raise exception 'That person could not be found' using errcode = 'P0002';
  end if;
  if length(v_title) < 3 or length(v_body) < 3 then
    raise exception 'Write a short title and message' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'Give a short reason for this reminder' using errcode = '22023';
  end if;

  insert into public.notifications(user_id, type, title, body, entity_type, read)
  values (p_user, 'info', v_title, v_body, 'console_reminder', false);
  v_sent := 1;

  if p_copy_to is not null and p_copy_to <> p_user and exists (select 1 from public.profiles where id = p_copy_to) then
    insert into public.notifications(user_id, type, title, body, entity_type, read)
    values (p_copy_to, 'info', 'Copy: ' || v_title, v_body, 'console_reminder', false);
    v_sent := 2;
  end if;

  insert into public.console_sessions(admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'send_person_reminder', p_user, 'user',
          jsonb_build_object('title', v_title, 'reason', left(btrim(p_reason), 500), 'copied', p_copy_to is not null));

  return jsonb_build_object('ok', true, 'sent', v_sent);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_admin_user(p_user_id uuid, p_role text, p_regions text[] DEFAULT '{}'::text[], p_note text DEFAULT NULL::text, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.admin_users%ROWTYPE;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF p_role NOT IN ('super_admin','regional_admin','viewer') THEN RAISE EXCEPTION 'Invalid role'; END IF;
  INSERT INTO public.admin_users (user_id, admin_role, regions, note, active)
    VALUES (p_user_id, p_role, COALESCE(p_regions,'{}'), p_note, COALESCE(p_active,true))
  ON CONFLICT (user_id) DO UPDATE SET
    admin_role = EXCLUDED.admin_role, regions = EXCLUDED.regions,
    note = EXCLUDED.note, active = EXCLUDED.active, updated_at = now()
  RETURNING * INTO v_row;
  PERFORM public._console_audit('admin_set_admin_user', p_user_id, 'admin_user',
    jsonb_build_object('admin_role', p_role, 'regions', to_jsonb(COALESCE(p_regions,'{}')), 'active', COALESCE(p_active,true)));
  RETURN to_jsonb(v_row);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_api_key_expiry(p_id uuid, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before public.api_keys%rowtype;
  v_email  text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'Expiry must be in the future (revoke the key instead)' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at > now() + interval '5 years' then
    raise exception 'Expiry cannot be more than 5 years ahead' using errcode = '22023';
  end if;

  select * into v_before from public.api_keys where id = p_id for update;
  if not found then
    raise exception 'API key not found' using errcode = 'P0002';
  end if;
  if not v_before.active then
    raise exception 'A revoked key cannot be given a new expiry' using errcode = '22023';
  end if;

  update public.api_keys set expires_at = p_expires_at where id = p_id;

  select email into v_email from public.profiles where id = auth.uid();

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'api_key_set_expiry', p_id, 'api_key',
          jsonb_build_object('name', v_before.name, 'prefix', v_before.key_prefix,
                             'from', v_before.expires_at, 'to', p_expires_at));

  insert into public.access_audit (actor, actor_email, action, entity, before, after, reason)
  values (auth.uid(), v_email, 'api_key_set_expiry', 'api_key',
          jsonb_build_object('id', p_id, 'prefix', v_before.key_prefix, 'expires_at', v_before.expires_at),
          jsonb_build_object('id', p_id, 'prefix', v_before.key_prefix, 'expires_at', p_expires_at),
          null);

  return jsonb_build_object('ok', true, 'id', p_id, 'expires_at', p_expires_at);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_bucket_file_limit(p_bucket text, p_bytes bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v_before bigint;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  if p_bytes is null or p_bytes < 1024 * 1024 or p_bytes > 500 * 1024 * 1024 then
    raise exception 'The limit must be between 1 MB and 500 MB' using errcode = '22023';
  end if;
  select file_size_limit into v_before from storage.buckets where id = p_bucket;
  if not found then raise exception 'Unknown bucket' using errcode = '22023'; end if;
  update storage.buckets set file_size_limit = p_bytes, updated_at = now() where id = p_bucket;
  insert into public.console_sessions (admin_id, action, target_type, details)
  values (auth.uid(), 'storage_file_limit_changed', 'storage_bucket',
          jsonb_build_object('bucket', p_bucket, 'before_bytes', v_before, 'after_bytes', p_bytes, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'bucket', p_bucket, 'before_bytes', v_before, 'after_bytes', p_bytes);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_config(p_key text, p_value text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old text;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can change platform settings' using errcode = '42501';
  end if;
  if p_key is null or btrim(p_key) = '' then
    raise exception 'Choose a setting' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'Give a short reason for this change' using errcode = '22023';
  end if;
  select value into v_old from public.system_config where key = p_key;
  perform set_config('app.config_reason', left(btrim(p_reason), 500), true);
  insert into public.system_config(key, value)
  values (p_key, p_value)
  on conflict (key) do update set value = excluded.value;
  return jsonb_build_object('ok', true, 'key', p_key, 'old_value', v_old, 'new_value', p_value);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_console_ip_allowlist(p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ip inet := public._request_client_ip(); v_was boolean := public._ip_allowlist_on();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  if coalesce(p_enabled, false) then
    if v_ip is null then
      raise exception 'Your current IP cannot be read, so turning this on could lock you out. It has not been turned on.' using errcode = '22023';
    end if;
    if not public._ip_covered(v_ip) then
      raise exception 'Your current IP (%) is not covered by an active range. Add it first, or you would lock yourself out.', host(v_ip)
        using errcode = '22023';
    end if;
  end if;
  perform set_config('app.access_policy_rpc', 'on', true);
  update public.system_config set value = case when p_enabled then 'true' else 'false' end,
         updated_at = now(), updated_by = auth.uid()
   where key = 'console_ip_allowlist_enabled';
  if not found then
    insert into public.system_config (key, value, category, description)
    values ('console_ip_allowlist_enabled', case when p_enabled then 'true' else 'false' end, 'security',
            'Only allow the super-admin console from listed IP ranges. Change it from Console, Access Policies.');
  end if;
  perform set_config('app.access_policy_rpc', '', true);
  perform public._access_policy_audit(case when p_enabled then 'ip_allowlist_enable' else 'ip_allowlist_disable' end,
    null, 'system_config', jsonb_build_object('was', v_was, 'now', coalesce(p_enabled, false), 'reason', btrim(p_reason)));
  return jsonb_build_object('enabled', coalesce(p_enabled, false), 'ip', host(v_ip));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_dual_control(p_enabled boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_on boolean := public._dual_control_on(); v_supers int; v_others int; v_breakglass boolean := false;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select count(*) into v_supers from public.profiles
   where coalesce(is_super_admin, false) and coalesce(approved, false) and not coalesce(locked, false);
  select count(*) into v_others from public.profiles
   where coalesce(is_super_admin, false) and coalesce(approved, false) and not coalesce(locked, false)
     and id <> auth.uid();

  if coalesce(p_enabled, false) = v_on then
    return jsonb_build_object('enabled', v_on, 'changed', false);
  end if;

  if p_enabled then
    if v_supers < 2 then
      raise exception 'Dual control needs at least two active super admins. Add a second one first.' using errcode = '22023';
    end if;
  else
    if v_others >= 1 then
      perform public._consume_approval('dual_control_disable', '{}'::jsonb);
    else
      v_breakglass := true;
    end if;
  end if;

  perform set_config('app.dual_control_rpc', 'on', true);
  insert into public.system_config (key, value, category, description, updated_by, updated_at)
  values ('dual_control_enabled', case when p_enabled then 'true' else 'false' end, 'security',
          'Four-eyes approval for destructive console actions (data cleanup, backup restore, bulk role change). Change it from Console, Approvals.',
          auth.uid(), now())
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();
  perform set_config('app.dual_control_rpc', '', true);

  perform public.log_console_event(case when p_enabled then 'dual_control_enabled' else 'dual_control_disabled' end,
    null, 'system_config',
    jsonb_build_object('reason', nullif(btrim(coalesce(p_reason, '')), ''), 'break_glass', v_breakglass,
                       'active_super_admins', v_supers));
  return jsonb_build_object('enabled', p_enabled, 'changed', true, 'break_glass', v_breakglass);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_flutter_version(p_which text, p_value text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_value  text := btrim(coalesce(p_value, ''));
  v_min    text;
  v_latest text;
  v_key    text;
  v_res    jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can change the Flutter app versions' using errcode = '42501';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'Give a short reason for this change' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('flutter_version_pair'));
  select btrim(btrim(coalesce(value, '')), '"') into v_min
    from public.system_config where key = 'flutter_min_version';
  select btrim(btrim(coalesce(value, '')), '"') into v_latest
    from public.system_config where key = 'flutter_latest_version';
  v_min := coalesce(v_min, '');
  v_latest := coalesce(v_latest, '');

  if p_which = 'min' then
    v_key := 'flutter_min_version';
    if v_value <> '' then
      if v_value !~ '^[vV]?\d+(\.\d+)*$' then
        raise exception 'That is not a version number. The app would ignore it, so it was not saved' using errcode = '22023';
      end if;
      if v_latest !~ '^[vV]?\d+(\.\d+)*$' then
        raise exception 'Record the newest released Flutter version first' using errcode = '22023';
      end if;
      if public._flutter_version_cmp(v_value, v_latest) > 0 then
        raise exception 'The minimum cannot be above the newest release (%). That would lock every phone out', v_latest using errcode = '22023';
      end if;
    end if;
  elsif p_which = 'latest' then
    v_key := 'flutter_latest_version';
    if v_value !~ '^[vV]?\d+(\.\d+)*$' then
      raise exception 'Enter the version name that is live on Google Play, for example 0.1.1' using errcode = '22023';
    end if;
    if v_min ~ '^[vV]?\d+(\.\d+)*$' and public._flutter_version_cmp(v_min, v_value) > 0 then
      raise exception 'The forced-update minimum is %. Lower it before recording an older release', v_min using errcode = '22023';
    end if;
  else
    raise exception 'Choose min or latest' using errcode = '22023';
  end if;

  v_res := public.admin_set_config(v_key, v_value, p_reason);
  return v_res || jsonb_build_object('which', p_which);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_module_status(p_ids text[], p_status text, p_until timestamp with time zone, p_note text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int; v_maint boolean := p_status = 'maintenance';
begin
  if not public.is_super_admin() then raise exception 'Only a super admin can change module status' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('live','maintenance','disabled','beta') then raise exception 'Choose Live, Maintenance or Off' using errcode = '22023'; end if;
  if p_ids is null or cardinality(p_ids) = 0 then raise exception 'Choose at least one module' using errcode = '22023'; end if;
  if cardinality(p_ids) > 500 then raise exception 'At most 500 modules at a time' using errcode = '22023'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'Give a short reason for this change' using errcode = '22023'; end if;
  perform set_config('app.module_reason', left(btrim(p_reason), 500), true);
  update public.modules set status = p_status,
    maintenance_until = case when v_maint then p_until else null end,
    maintenance_note = case when v_maint then nullif(left(btrim(coalesce(p_note, '')), 200), '') else null end
  where module_id = any(p_ids);
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'updated', v_n, 'status', p_status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_sso_required(p_org uuid, p_required boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_doms text[]; v_missing text[]; v_n int;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Give a reason of at least 5 characters.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.organisations where id = p_org) then
    raise exception 'That organisation does not exist.' using errcode = '22023';
  end if;
  if coalesce(p_required, false) then
    select coalesce(array_agg(distinct d), '{}') into v_doms from (
      select lower(btrim(x)) d from public.sso_connections c, unnest(string_to_array(coalesce(c.domains, ''), ',')) x
       where c.organisation_id = p_org and c.status = 'active') s where d <> '';
    if cardinality(v_doms) = 0 then
      raise exception 'This organisation has no active SSO connection with email domains. Requiring SSO now would lock everyone out.'
        using errcode = '22023';
    end if;
    select coalesce(array_agg(d), '{}') into v_missing from unnest(v_doms) d
     where not exists (select 1 from auth.sso_domains sd where lower(sd.domain) = d);
    if cardinality(v_missing) > 0 then
      raise exception 'These domains are not registered with Supabase Auth, so nobody could sign in with SSO: %', array_to_string(v_missing, ', ')
        using errcode = '22023';
    end if;
    update public.sso_connections set enforce_sso = true
     where organisation_id = p_org and status = 'active';
  else
    update public.sso_connections set enforce_sso = false where organisation_id = p_org;
  end if;
  get diagnostics v_n = row_count;
  perform public._access_policy_audit(case when p_required then 'sso_required_on' else 'sso_required_off' end,
    p_org, 'organisation', jsonb_build_object('connections', v_n, 'reason', btrim(p_reason)));
  return jsonb_build_object('org', p_org, 'required', coalesce(p_required, false), 'connections', v_n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_user_country(p_user_id uuid, p_countries text[], p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only a Super Admin can change a user country.' USING errcode = '42501'; END IF;
  UPDATE public.profiles SET country = p_countries WHERE id = p_user_id;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_user_password(p_user_id uuid, p_password text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_caller      uuid := auth.uid();
  v_is_super    boolean := public.is_super_admin();
  v_caller_org  uuid := public.app_current_org();
  v_caller_role text := public.app_role();
  v_caller_mail text;
  v_target      record;
  v_min_len     int;
  v_audited     boolean := false;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if v_caller is null then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if not (v_is_super or lower(coalesce(v_caller_role, '')) = 'admin') then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  select p.id, p.full_name, p.username, p.role, p.is_super_admin, p.employee_id,
         coalesce(p.organisation_id, p.org_id) as org
    into v_target
    from public.profiles p where p.id = p_user_id;

  if v_target.id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_such_user');
  end if;
  if not v_is_super and (v_target.org is distinct from v_caller_org) then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if coalesce(v_target.is_super_admin, false) and not v_is_super then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if v_target.id = v_caller then
    return jsonb_build_object('ok', false, 'reason', 'use_change_password');
  end if;

  v_min_len := greatest(coalesce(
    nullif(regexp_replace(coalesce(
      (select value from public.system_config where key = 'password_min_length'), '8'), '\D', '', 'g'), '')::int, 8), 6);

  if p_password is null or length(p_password) < v_min_len then
    return jsonb_build_object('ok', false, 'reason', 'too_short', 'min_length', v_min_len);
  end if;

  select email into v_caller_mail from public.profiles where id = v_caller;

  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         updated_at = now()
   where id = p_user_id;

  begin
    delete from auth.refresh_tokens where user_id = p_user_id::text;
  exception when others then null;
  end;
  begin
    delete from auth.sessions where user_id = p_user_id;
  exception when others then null;
  end;

  begin
    delete from public.login_attempts
     where lower(identifier) in (lower(coalesce(v_target.username, '')),
                                 lower(coalesce(v_target.employee_id, '')));
  exception when others then null;
  end;

  begin
    insert into public.access_audit (actor, actor_email, action, target_user, entity, after, reason)
    values (v_caller, v_caller_mail, 'password_set', p_user_id, 'user',
            jsonb_build_object('target_name', v_target.full_name,
                               'target_username', v_target.username,
                               'target_role', v_target.role),
            nullif(btrim(coalesce(p_reason, '')), ''));
    v_audited := true;
  exception when others then
    -- A locked-out worker must not stay locked out because the audit table is
    -- unavailable, but the gap must not be invisible either.
    begin
      insert into public.system_logs (severity, source, message, detail)
      values ('error', 'admin_set_user_password',
              'Password was set but the audit row could not be written',
              jsonb_build_object('target_user', p_user_id, 'actor', v_caller));
    exception when others then null;
    end;
  end;

  return jsonb_build_object('ok', true, 'user_id', p_user_id,
                            'full_name', v_target.full_name,
                            'username', v_target.username,
                            'audited', v_audited);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_user_sites(p_user_id uuid, p_sites text[], p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_clean text[];
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT (public.is_super_admin() OR public.get_my_role() = 'Admin') THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(array_agg(DISTINCT upper(btrim(s))) FILTER (WHERE btrim(s) <> ''), NULL)
    INTO v_clean FROM unnest(COALESCE(p_sites, ARRAY[]::text[])) s;
  ALTER TABLE public.profiles DISABLE TRIGGER trg_guard_profile_privileged;
  UPDATE public.profiles SET sites = v_clean WHERE id = p_user_id;
  ALTER TABLE public.profiles ENABLE TRIGGER trg_guard_profile_privileged;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_set_web_access(p_user_id uuid, p_web boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT (public.is_super_admin() OR public.get_my_role() = 'Admin') THEN
    RAISE EXCEPTION 'Not authorized to change web access.' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A target user is required.';
  END IF;
  UPDATE public.profiles SET web_access = COALESCE(p_web, true) WHERE id = p_user_id;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_start_access_review(p_name text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_n int;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  perform public._access_review_require_super();
  if p_name is null or length(btrim(p_name)) = 0 then
    raise exception 'A campaign name is required.' using errcode = '22023';
  end if;
  if p_due_at is not null and p_due_at < now() - interval '1 day' then
    raise exception 'The due date cannot be in the past.' using errcode = '22023';
  end if;

  insert into public.access_review_campaigns (name, due_at, created_by, status, scope)
  values (btrim(p_name), p_due_at, auth.uid(), 'open',
          jsonb_build_object('population','approved_profiles','snapshot_at', now()))
  returning id into v_id;

  insert into public.access_review_items
    (campaign_id, user_id, user_email, full_name, role, is_super_admin, country, sites,
     approved, locked, grants, last_sign_in_at)
  select v_id, p.id, coalesce(p.email, u.email), p.full_name, p.role, coalesce(p.is_super_admin,false),
         p.country, p.sites, p.approved, p.locked,
         coalesce((select jsonb_agg(jsonb_build_object(
                     'module_key', g.module_key, 'capability', g.capability, 'effect', g.effect,
                     'expires_at', g.expires_at, 'note', g.note) order by g.module_key)
                   from public.user_access_grants g where g.user_id = p.id), '[]'::jsonb),
         u.last_sign_in_at
  from public.profiles p
  left join auth.users u on u.id = p.id
  where coalesce(p.approved, false) = true;

  get diagnostics v_n = row_count;
  update public.access_review_campaigns
     set scope = scope || jsonb_build_object('users', v_n)
   where id = v_id;
  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_storage_duplicates(p_bucket text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(g order by g.extra_bytes desc), '[]'::jsonb) into v from (
    select bucket_id as bucket, bytes,
           count(*) as copies,
           (count(*) - 1) * bytes as extra_bytes,
           (array_agg(name order by created_at, name))[1] as kept,
           (array_agg(name order by created_at, name))[2:] as extras,
           min(created_at) as first_at, max(created_at) as last_at
      from (select bucket_id, name, created_at, metadata->>'eTag' as etag,
                   coalesce((metadata->>'size')::bigint, 0) as bytes
              from storage.objects) o
     where etag is not null and bytes > 0 and (p_bucket is null or bucket_id = p_bucket)
     group by bucket_id, etag, bytes
    having count(*) > 1
     order by (count(*) - 1) * bytes desc
     limit greatest(1, least(coalesce(p_limit, 200), 1000))
  ) g;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_storage_list(p_bucket text, p_prefix text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v jsonb; v_total bigint;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select count(*) into v_total from storage.objects o
   where o.bucket_id = p_bucket
     and (p_prefix is null or o.name like replace(replace(p_prefix, '%', '\%'), '_', '\_') || '%')
     and (p_search is null or o.name ilike '%' || replace(replace(p_search, '%', '\%'), '_', '\_') || '%');
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v from (
    select o.name, coalesce((o.metadata->>'size')::bigint, 0) as bytes, o.created_at,
           o.metadata->>'mimetype' as mime
      from storage.objects o
     where o.bucket_id = p_bucket
       and (p_prefix is null or o.name like replace(replace(p_prefix, '%', '\%'), '_', '\_') || '%')
       and (p_search is null or o.name ilike '%' || replace(replace(p_search, '%', '\%'), '_', '\_') || '%')
     order by o.created_at desc, o.name
     limit greatest(1, least(coalesce(p_limit, 100), 500)) offset greatest(0, coalesce(p_offset, 0))
  ) x;
  return jsonb_build_object('total', v_total, 'rows', v);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_storage_orphan_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v jsonb; v_id uuid;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  with o as (
    select bucket_id, name, created_at, coalesce((metadata->>'size')::bigint, 0) as bytes,
           split_part(name, '/', 1) as folder
      from storage.objects
  ),
  unrecorded_imports as (
    select o.* from o where o.bucket_id = 'import-files'
       and not exists (select 1 from public.import_files f where f.storage_path = o.name)
  ),
  unrecorded_exports as (
    select o.* from o where o.bucket_id = 'tenant-exports'
       and not exists (select 1 from public.tenant_export_jobs j
                        where j.files is not null and j.files::text like '%' || o.name || '%')
  ),
  memberless as (
    select o.*, org.name as org_name from o join public.organisations org on org.id::text = o.folder
     where not exists (select 1 from public.profiles p where p.org_id = org.id)
  )
  select jsonb_build_object(
    'scanned_files', (select count(*) from o),
    'unrecorded_imports', jsonb_build_object('files', (select count(*) from unrecorded_imports),
        'bytes', (select coalesce(sum(bytes), 0) from unrecorded_imports),
        'sample', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (select name, bytes, created_at from unrecorded_imports order by created_at limit 10) s)),
    'unrecorded_exports', jsonb_build_object('files', (select count(*) from unrecorded_exports),
        'bytes', (select coalesce(sum(bytes), 0) from unrecorded_exports),
        'sample', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (select name, bytes, created_at from unrecorded_exports order by created_at limit 10) s)),
    'memberless_company_files', jsonb_build_object('files', (select count(*) from memberless),
        'bytes', (select coalesce(sum(bytes), 0) from memberless),
        'sample', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (select bucket_id as bucket, name, bytes, org_name, created_at from memberless order by created_at limit 10) s)),
    'empty_buckets', (select coalesce(jsonb_agg(b.id order by b.id), '[]'::jsonb) from storage.buckets b
                       where not exists (select 1 from storage.objects x where x.bucket_id = b.id)),
    'photos_not_checked', true
  ) into v;

  insert into public.storage_scan_runs (kind, result) values ('orphans', v) returning id into v_id;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'storage_orphan_scan', v_id, 'storage_scan', jsonb_build_object(
    'unrecorded_imports', v->'unrecorded_imports'->'files', 'unrecorded_exports', v->'unrecorded_exports'->'files',
    'memberless_company_files', v->'memberless_company_files'->'files'));
  return v || jsonb_build_object('scan_id', v_id, 'ran_at', now());
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_storage_retention_preview(p_bucket text, p_prefix text, p_min_bytes bigint, p_older_than_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if p_older_than_days is null or p_older_than_days < 1 then
    raise exception 'Choose how many days to keep files' using errcode = '22023';
  end if;
  with m as (
    select name, created_at, coalesce((metadata->>'size')::bigint, 0) as bytes
      from storage.objects
     where bucket_id = p_bucket
       and created_at < now() - make_interval(days => p_older_than_days)
       and (nullif(btrim(p_prefix), '') is null or name like replace(replace(btrim(p_prefix), '%', '\%'), '_', '\_') || '%')
       and (p_min_bytes is null or coalesce((metadata->>'size')::bigint, 0) >= p_min_bytes)
  )
  select jsonb_build_object(
    'files', (select count(*) from m),
    'bytes', (select coalesce(sum(bytes), 0) from m),
    'bucket_files', (select count(*) from storage.objects where bucket_id = p_bucket),
    'oldest', (select min(created_at) from m),
    'sample', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (select name, bytes, created_at from m order by created_at limit 10) s)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_storage_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_catalog'
AS $function$
declare
  v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;

  with o as (
    select bucket_id, name, created_at,
           coalesce((metadata->>'size')::bigint, 0) as bytes,
           metadata->>'eTag' as etag,
           coalesce(metadata->>'mimetype', 'unknown') as mime,
           split_part(name, '/', 1) as folder
      from storage.objects
  ),
  dup as (
    select bucket_id, bytes, row_number() over (partition by bucket_id, etag, bytes order by created_at, name) as rn
      from o where etag is not null and bytes > 0
  ),
  pol as (
    select b.id,
           exists (select 1 from pg_policies p
                    where p.schemaname = 'storage' and p.tablename = 'objects' and p.cmd = 'DELETE'
                      and p.qual like '%''' || b.id || '''%') as has_delete_policy
      from storage.buckets b
  )
  select jsonb_build_object(
    'generated_at', now(),
    'buckets', (select coalesce(jsonb_agg(x order by x.bytes desc, x.id), '[]'::jsonb) from (
        select b.id, b.public, b.file_size_limit, b.allowed_mime_types, b.created_at,
               count(o.name) as files, coalesce(sum(o.bytes), 0) as bytes,
               max(o.created_at) as last_upload,
               coalesce(max(o.bytes), 0) as largest_bytes,
               count(o.name) filter (where o.created_at >= date_trunc('day', now())) as files_today,
               count(o.name) filter (where o.created_at >= now() - interval '7 days') as files_7d,
               count(o.name) filter (where o.created_at >= date_trunc('month', now())) as files_month,
               count(o.name) filter (where o.created_at < now() - interval '60 days') as older_60_files,
               coalesce(sum(o.bytes) filter (where o.created_at < now() - interval '60 days'), 0) as older_60_bytes,
               (select count(*) from dup d where d.bucket_id = b.id and d.rn > 1) as duplicate_files,
               (select coalesce(sum(d.bytes), 0) from dup d where d.bucket_id = b.id and d.rn > 1) as duplicate_bytes,
               (select p.has_delete_policy from pol p where p.id = b.id) as has_delete_policy,
               (select coalesce(jsonb_object_agg(m.mime, m.n), '{}'::jsonb) from (
                   select mime, count(*) n from o o2 where o2.bucket_id = b.id group by mime order by count(*) desc limit 6) m) as mimes
          from storage.buckets b left join o on o.bucket_id = b.id
         group by b.id, b.public, b.file_size_limit, b.allowed_mime_types, b.created_at) x),
    'folders', (select coalesce(jsonb_agg(f order by f.bytes desc), '[]'::jsonb) from (
        select bucket_id as bucket, folder, count(*) as files, sum(bytes) as bytes
          from o group by bucket_id, folder order by sum(bytes) desc limit 40) f),
    'growth', (select coalesce(jsonb_agg(g order by g.month), '[]'::jsonb) from (
        select to_char(date_trunc('month', created_at), 'YYYY-MM') as month, count(*) as files, sum(bytes) as bytes
          from o where created_at >= date_trunc('month', now()) - interval '11 months'
         group by 1) g),
    'largest', (select coalesce(jsonb_agg(l order by l.bytes desc), '[]'::jsonb) from (
        select o.bucket_id as bucket, o.name, o.bytes, o.created_at, o.mime,
               (select count(*) from o o3 where o3.bucket_id = o.bucket_id and o3.etag = o.etag and o3.bytes = o.bytes) > 1 as has_copy
          from o order by o.bytes desc limit 12) l),
    'companies', (select coalesce(jsonb_agg(c order by c.bytes desc), '[]'::jsonb) from (
        select o.folder, org.name as org_name, count(*) as files, sum(o.bytes) as bytes,
               string_agg(distinct o.bucket_id, ', ') as buckets,
               min(o.created_at) as first_at, max(o.created_at) as last_at,
               (select count(*) from public.profiles p where p.org_id = org.id) as members
          from o join public.organisations org on org.id::text = o.folder
         where o.bucket_id in ('import-files', 'tenant-exports')
         group by o.folder, org.id, org.name) c),
    'retention_rules', (select coalesce(jsonb_agg(r order by r.created_at desc), '[]'::jsonb) from public.storage_retention_rules r),
    'tenant_export_days', (select public._tenant_export_retention_days()),
    'last_orphan_scan', (select to_jsonb(s) from public.storage_scan_runs s where s.kind = 'orphans' order by s.ran_at desc limit 1)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_table_detail(p_schema text, p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_oid oid;
  v jsonb;
  v_exact bigint;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  select c.oid into v_oid from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = p_schema and c.relname = p_table and c.relkind in ('r','p');
  if v_oid is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if pg_total_relation_size(v_oid) < 300 * 1024 * 1024 then
    begin
      execute format('select count(*) from %I.%I', p_schema, p_table) into v_exact;
    exception when others then
      v_exact := null;
    end;
  end if;
  select jsonb_build_object(
    'ok', true,
    'schema', p_schema, 'name', p_table,
    'rows', v_exact,
    'rows_estimate', (select case when c.reltuples > 0 and c.relpages > 0
                       then round(c.reltuples / c.relpages * (pg_relation_size(c.oid) / current_setting('block_size')::numeric))::bigint
                       else greatest(coalesce(s.n_live_tup, 0), 0) end from pg_class c where c.oid = v_oid),
    'dead_rows', coalesce(s.n_dead_tup, 0),
    'total_bytes', pg_total_relation_size(v_oid),
    'heap_bytes', pg_relation_size(v_oid),
    'index_bytes', pg_indexes_size(v_oid),
    'toast_bytes', greatest(pg_total_relation_size(v_oid) - pg_relation_size(v_oid) - pg_indexes_size(v_oid), 0),
    'columns', (select count(*) from pg_attribute a where a.attrelid = v_oid and a.attnum > 0 and not a.attisdropped),
    'last_vacuum', greatest(s.last_vacuum, s.last_autovacuum),
    'last_analyze', greatest(s.last_analyze, s.last_autoanalyze),
    'inserts', coalesce(s.n_tup_ins, 0), 'updates', coalesce(s.n_tup_upd, 0), 'deletes', coalesce(s.n_tup_del, 0),
    'seq_scans', coalesce(s.seq_scan, 0), 'index_scans', coalesce(s.idx_scan, 0),
    'rls', (select relrowsecurity from pg_class where oid = v_oid),
    'in_nightly_copy', case when p_schema = 'public' then (p_table = any (backups._core_tables())) else false end,
    'indexes', (select coalesce(jsonb_agg(jsonb_build_object(
                  'name', ic.relname, 'bytes', pg_relation_size(ic.oid),
                  'scans', coalesce(si.idx_scan, 0), 'unique', i.indisunique) order by pg_relation_size(ic.oid) desc), '[]'::jsonb)
                  from pg_index i join pg_class ic on ic.oid = i.indexrelid
                  left join pg_stat_all_indexes si on si.indexrelid = i.indexrelid
                 where i.indrelid = v_oid)
  ) into v
  from (select 1) x left join pg_stat_all_tables s on s.relid = v_oid;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_table_freshness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_ts timestamptz;
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  for r in select * from (values
      ('tyre_records', 'Tyre fitments'),
      ('inspections', 'Inspections'),
      ('parts_consumption', 'Expense lines'),
      ('work_orders', 'Job cards'),
      ('vehicle_fleet', 'Asset register'),
      ('production_logs', 'Concrete m3'),
      ('accidents', 'Accidents')) t(tbl, label)
  loop
    begin
      execute format('select max(created_at) from public.%I', r.tbl) into v_ts;
      v := v || jsonb_build_array(jsonb_build_object('table', r.tbl, 'label', r.label, 'last_row_at', v_ts));
    exception when others then
      v := v || jsonb_build_array(jsonb_build_object('table', r.tbl, 'label', r.label, 'last_row_at', null, 'unreadable', true));
    end;
  end loop;
  return jsonb_build_object('generated_at', now(), 'rows', v);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_download_log(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_job public.tenant_export_jobs%rowtype;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can download tenant data' using errcode = '42501';
  end if;
  select * into v_job from public.tenant_export_jobs where id = p_job;
  if not found or v_job.mode <> 'server' then
    raise exception 'Export job not found' using errcode = 'P0002';
  end if;
  if v_job.status = 'running' then
    raise exception 'That export is still running' using errcode = '55P03';
  end if;
  if v_job.status = 'expired' then
    raise exception 'That export has expired and its files were deleted' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(v_job.files, '[]'::jsonb)) = 0 then
    raise exception 'That export produced no files' using errcode = '22023';
  end if;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'tenant_export_download', v_job.org_id, 'organisation',
          jsonb_build_object('job_id', v_job.id, 'files', jsonb_array_length(v_job.files),
                             'status', v_job.status));

  return jsonb_build_object('job_id', v_job.id, 'org_id', v_job.org_id, 'status', v_job.status,
                            'files', v_job.files);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_log(p_org uuid, p_reason text, p_tables jsonb, p_counts jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_status text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can export tenant data' using errcode = '42501';
  end if;
  if p_org is null or not exists (select 1 from public.organisations where id = p_org) then
    raise exception 'Organisation not found' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'A reason of at least 5 characters is required' using errcode = '22023';
  end if;
  v_status := coalesce(nullif(p_counts->>'_status', ''), 'completed');
  if v_status not in ('completed','partial','failed') then v_status := 'partial'; end if;
  insert into public.tenant_export_jobs (org_id, requested_by, reason, tables, status, row_counts, completed_at)
  values (p_org, auth.uid(), btrim(p_reason), coalesce(p_tables, '[]'::jsonb), v_status,
          coalesce(p_counts, '{}'::jsonb) - '_status', now())
  returning id into v_id;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'tenant_export', p_org, 'organisation',
          jsonb_build_object('job_id', v_id, 'reason', btrim(p_reason), 'status', v_status,
                             'tables', coalesce(p_tables, '[]'::jsonb),
                             'row_counts', coalesce(p_counts, '{}'::jsonb) - '_status'));
  return v_id;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_manifest(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_t text; v_n bigint; v_out jsonb := '[]'::jsonb; v_total bigint := 0; v_name text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can export tenant data' using errcode = '42501';
  end if;
  if p_org is null then
    raise exception 'An organisation is required' using errcode = '22023';
  end if;
  select name into v_name from public.organisations where id = p_org;
  if not found then
    raise exception 'Organisation not found' using errcode = '22023';
  end if;
  foreach v_t in array public._tenant_export_tables() loop
    begin
      if to_regclass('public.' || quote_ident(v_t)) is null then
        v_out := v_out || jsonb_build_array(jsonb_build_object('table', v_t, 'rows', null, 'error', 'missing'));
        continue;
      end if;
      execute format('select count(*) from public.%I where organisation_id = $1', v_t)
        into v_n using p_org;
      v_total := v_total + v_n;
      v_out := v_out || jsonb_build_array(jsonb_build_object('table', v_t, 'rows', v_n, 'error', null));
    exception when others then
      v_out := v_out || jsonb_build_array(jsonb_build_object('table', v_t, 'rows', null, 'error', 'count_failed'));
    end;
  end loop;
  return jsonb_build_object('org_id', p_org, 'org_name', v_name, 'generated_at', now(),
    'total_rows', v_total, 'tables', v_out);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_page(p_org uuid, p_table text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit int := least(greatest(coalesce(p_limit, 1000), 1), 1000);
  v_rows jsonb; v_n int; v_last uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can export tenant data' using errcode = '42501';
  end if;
  if p_org is null then
    raise exception 'An organisation is required' using errcode = '22023';
  end if;
  if p_table is null or not (p_table = any (public._tenant_export_tables())) then
    raise exception 'That table cannot be exported' using errcode = '22023';
  end if;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(x) order by x.id), ''[]''::jsonb), count(*)::int, '
    || '(array_agg(x.id order by x.id desc))[1] '
    || 'from (select * from public.%I t where t.organisation_id = $1 '
    || 'and ($2::uuid is null or t.id > $2) order by t.id limit $3) x',
    p_table)
  into v_rows, v_n, v_last
  using p_org, p_after, v_limit;
  return jsonb_build_object('table', p_table, 'rows', v_rows, 'count', v_n,
    'next_after', case when v_n = v_limit then v_last else null end,
    'done', v_n < v_limit);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_purge_now()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_due jsonb; v_req bigint;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can manage tenant exports' using errcode = '42501';
  end if;
  v_due := public._tenant_export_due_for_purge(200);
  insert into public.console_sessions (admin_id, action, target_type, details)
  values (auth.uid(), 'tenant_export_purge_request', 'tenant_export_job',
          jsonb_build_object('due', jsonb_array_length(v_due),
                             'retention_days', public._tenant_export_retention_days()));
  if jsonb_array_length(v_due) = 0 then
    return jsonb_build_object('queued', false, 'due', 0);
  end if;
  v_req := public._tenant_export_request_purge('manual', auth.uid());
  return jsonb_build_object('queued', true, 'due', jsonb_array_length(v_due), 'request_id', v_req);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_retention_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_days int; v_due jsonb;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can manage tenant exports' using errcode = '42501';
  end if;
  v_days := public._tenant_export_retention_days();
  v_due := public._tenant_export_due_for_purge(200);
  return jsonb_build_object(
    'days', v_days,
    'due_count', jsonb_array_length(v_due),
    'due', v_due,
    'stored_jobs', (select count(*) from public.tenant_export_jobs
                     where mode = 'server' and status in ('completed','partial','failed')),
    'expired_jobs', (select count(*) from public.tenant_export_jobs where status = 'expired'),
    'last_purge_at', (select max(created_at) from public.console_sessions where action = 'tenant_export_purge'),
    'next_run', 'daily 02:40 UTC');
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_server_start(p_org uuid, p_reason text, p_tables text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_safe    text[] := public._tenant_export_tables();
  v_tables  text[];
  v_bad     text[];
  v_id      uuid;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can export tenant data' using errcode = '42501';
  end if;
  if p_org is null or not exists (select 1 from public.organisations where id = p_org) then
    raise exception 'Organisation not found' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'A reason of at least 5 characters is required' using errcode = '22023';
  end if;

  if p_tables is null or cardinality(p_tables) = 0 then
    v_tables := v_safe;
  else
    select array_agg(t) into v_bad from unnest(p_tables) t where not (t = any (v_safe));
    if v_bad is not null then
      raise exception 'That table cannot be exported' using errcode = '22023';
    end if;
    select array_agg(s order by ord) into v_tables
      from unnest(v_safe) with ordinality as u(s, ord)
     where s = any (p_tables);
  end if;

  update public.tenant_export_jobs
     set status = 'failed', error = coalesce(error, 'Stalled: no progress for 30 minutes'),
         completed_at = now(), updated_at = now()
   where org_id = p_org and mode = 'server' and status = 'running'
     and updated_at < now() - interval '30 minutes';

  if exists (select 1 from public.tenant_export_jobs
              where org_id = p_org and mode = 'server' and status = 'running') then
    raise exception 'A server export for this organisation is already running' using errcode = '55P03';
  end if;

  insert into public.tenant_export_jobs
    (org_id, requested_by, reason, tables, status, mode, row_counts, progress, started_at, updated_at)
  values
    (p_org, v_uid, btrim(p_reason), to_jsonb(v_tables), 'running', 'server', '{}'::jsonb,
     jsonb_build_object('idx', 0, 'after', null, 'part', 0, 'table_rows', 0, 'errors', '{}'::jsonb,
                        'expected', '{}'::jsonb, 'invocations', 0),
     now(), now())
  returning id into v_id;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'tenant_export_server', p_org, 'organisation',
          jsonb_build_object('job_id', v_id, 'reason', btrim(p_reason), 'tables', to_jsonb(v_tables)));

  return jsonb_build_object('job_id', v_id, 'tables', to_jsonb(v_tables));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_tenant_export_set_retention(p_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old int;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can manage tenant exports' using errcode = '42501';
  end if;
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'Retention must be between 1 and 90 days' using errcode = '22023';
  end if;
  v_old := public._tenant_export_retention_days();
  insert into public.system_config (key, value, description, category, updated_by, updated_at)
  values ('tenant_export_retention_days', p_days::text,
          'Days a server tenant export stays in Storage before its files are deleted (1 to 90).',
          'security', auth.uid(), now())
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();

  insert into public.console_sessions (admin_id, action, target_type, details)
  values (auth.uid(), 'tenant_export_retention_set', 'system_config',
          jsonb_build_object('key', 'tenant_export_retention_days', 'from', v_old, 'to', p_days));
  return jsonb_build_object('days', p_days, 'previous', v_old);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_unlogged_imports(p_key text DEFAULT 'parts_expense'::text, p_limit integer DEFAULT 60)
 RETURNS TABLE(tbl text, country text, inserted_at timestamp with time zone, rows bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_spec record;
  v_org  uuid := public.app_current_org();
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  -- Reuse the V362 safelist so this cannot be pointed at an arbitrary table.
  select * into v_spec from public._dup_scan_spec(p_key);
  if v_spec.key is null then
    raise exception 'Unknown import target.' using errcode = '22023';
  end if;

  return query execute format($f$
    select %L::text as tbl, country,
           date_trunc('second', %I) as inserted_at,
           count(*) as rows
      from public.%I
     where (organisation_id = $1 or $2)
     group by country, date_trunc('second', %I)
     order by date_trunc('second', %I) desc
     limit $3
  $f$, v_spec.tbl, v_spec.date_col, v_spec.tbl, v_spec.date_col, v_spec.date_col)
  using v_org, public.is_super_admin(), greatest(1, least(coalesce(p_limit, 60), 500));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_update_profile(p_user_id uuid, p_full_name text DEFAULT NULL::text, p_username text DEFAULT NULL::text, p_employee_id text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_country text[] DEFAULT NULL::text[], p_region text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_approved boolean DEFAULT NULL::boolean, p_locked boolean DEFAULT NULL::boolean, p_org_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role text;
  v_is_super    boolean;
  v_caller_org  uuid;
  v_target_org  uuid;
  v_org uuid := p_org_id;
  v_priv boolean;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  SELECT role, COALESCE(is_super_admin, false), org_id
    INTO v_caller_role, v_is_super, v_caller_org
    FROM public.profiles WHERE id = auth.uid() LIMIT 1;

  IF NOT coalesce(v_is_super, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Admin role required');
  END IF;

  IF p_user_id = auth.uid() AND p_locked = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'You cannot lock your own account');
  END IF;

  IF v_org IS NULL AND p_country IS NOT NULL AND array_length(p_country, 1) = 1 THEN
    SELECT id INTO v_org FROM public.organisations WHERE country = p_country[1] LIMIT 1;
  END IF;
  IF v_org IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.organisations WHERE id = v_org) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unknown organisation');
  END IF;

  v_priv := (p_role IS NOT NULL) OR (p_approved IS NOT NULL) OR (p_locked IS NOT NULL) OR (v_org IS NOT NULL);
  IF NOT v_is_super THEN
    IF v_priv THEN
      RETURN jsonb_build_object('success', false,
        'error', 'Permission denied: super admin required for role, approval, lock or organisation changes');
    END IF;
    SELECT org_id INTO v_target_org FROM public.profiles WHERE id = p_user_id;
    IF v_target_org IS DISTINCT FROM v_caller_org THEN
      RETURN jsonb_build_object('success', false,
        'error', 'Permission denied: target user is in another organisation');
    END IF;
  END IF;

  UPDATE public.profiles SET
    full_name   = COALESCE(p_full_name,   full_name),
    username    = COALESCE(p_username,    username),
    employee_id = COALESCE(p_employee_id, employee_id),
    role        = COALESCE(p_role,        role),
    country     = CASE WHEN p_country IS NOT NULL THEN p_country ELSE country END,
    region      = COALESCE(p_region,      region),
    site        = COALESCE(p_site,        site),
    phone       = COALESCE(p_phone,       phone),
    notes       = COALESCE(p_notes,       notes),
    approved    = COALESCE(p_approved,    approved),
    locked      = COALESCE(p_locked,      locked),
    org_id          = COALESCE(v_org, org_id),
    organisation_id = COALESCE(v_org, organisation_id),
    updated_at  = now()
  WHERE id = p_user_id;

  RETURN jsonb_build_object('success', true, 'org_id', v_org);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_user_directory()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the user directory' using errcode = '42501';
  end if;

  with dev as (
    select user_id,
           count(*) filter (where not revoked) as phones,
           max(last_seen_at) filter (where not revoked) as last_seen,
           (array_agg(app_version order by last_seen_at desc nulls last) filter (where not revoked))[1] as app_version,
           bool_or(push_token is not null and not revoked) as has_push
      from public.user_devices group by user_id
  ), ret as (
    select user_id, count(*) as returned_unopened
      from public.notifications
     where type = 'approval_decision' and read = false and title ilike '%returned%'
     group by user_id
  ), logs as (
    select user_id, count(*) as web_errors_30d
      from public.system_logs
     where user_id is not null and created_at > now() - interval '30 days'
       and severity in ('error', 'critical')
     group by user_id
  ), rej as (
    select created_by as user_id, count(*) as sent_back_30d
      from public.inspections
     where approval_status = 'rejected' and created_at > now() - interval '30 days'
     group by created_by
  ), iss as (
    select reporter_id as user_id, count(*) as issues_open
      from public.user_issues
     where status not in ('fixed', 'closed', 'wont_fix')
     group by reporter_id
  ), mfa as (
    select user_id, bool_or(status = 'verified') as mfa
      from auth.mfa_factors group by user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', p.id,
           'last_sign_in_at', u.last_sign_in_at,
           'auth_created_at', u.created_at,
           'mfa', coalesce(mfa.mfa, false),
           'phones', coalesce(dev.phones, 0),
           'last_seen_at', dev.last_seen,
           'app_version', dev.app_version,
           'has_push', coalesce(dev.has_push, false) or p.push_token is not null,
           'returned_unopened', coalesce(ret.returned_unopened, 0),
           'web_errors_30d', coalesce(logs.web_errors_30d, 0),
           'sent_back_30d', coalesce(rej.sent_back_30d, 0),
           'issues_open', coalesce(iss.issues_open, 0)
         )), '[]'::jsonb)
    into v
    from public.profiles p
    left join auth.users u on u.id = p.id
    left join dev  on dev.user_id  = p.id
    left join ret  on ret.user_id  = p.id
    left join logs on logs.user_id = p.id
    left join rej  on rej.user_id  = p.id
    left join iss  on iss.user_id  = p.id
    left join mfa  on mfa.user_id  = p.id;

  return jsonb_build_object('ok', true, 'generated_at', now(), 'people', v);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_user_health(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_role text;
  v_out jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read a person''s record' using errcode = '42501';
  end if;
  if p_user is null then
    raise exception 'Choose a person' using errcode = '22023';
  end if;
  select role into v_role from public.profiles where id = p_user;

  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'auth', (select jsonb_build_object(
                'email_masked', public._mask_email(u.email),
                'created_at', u.created_at,
                'last_sign_in_at', u.last_sign_in_at,
                'confirmed', u.email_confirmed_at is not null)
               from auth.users u where u.id = p_user),
    'mfa', (select jsonb_build_object(
                'verified', coalesce(bool_or(status = 'verified'), false),
                'factors', count(*))
              from auth.mfa_factors where user_id = p_user),
    'devices', (select coalesce(jsonb_agg(jsonb_build_object(
                  'id', d.id, 'platform', d.platform, 'device_id', d.device_id,
                  'app_version', d.app_version, 'last_seen_at', d.last_seen_at,
                  'created_at', d.created_at, 'revoked', d.revoked,
                  'has_push', d.push_token is not null) order by d.last_seen_at desc nulls last), '[]'::jsonb)
                from public.user_devices d where d.user_id = p_user),
    'records', jsonb_build_object(
        'all_time', (select count(*) from public.inspections where created_by = p_user),
        'last_30d', (select count(*) from public.inspections where created_by = p_user and created_at > now() - interval '30 days'),
        'last_at', (select max(created_at) from public.inspections where created_by = p_user),
        'daily_90d', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'n', n) order by d), '[]'::jsonb)
                        from (select (created_at at time zone 'Asia/Riyadh')::date as d, count(*) as n
                                from public.inspections
                               where created_by = p_user and created_at > now() - interval '90 days'
                               group by 1) x),
        'role_rank', (select jsonb_build_object('rank', r.rnk, 'of', r.total)
                        from (select created_by, rank() over (order by count(*) desc) as rnk,
                                     count(*) over () as total
                                from public.inspections i
                                join public.profiles pr on pr.id = i.created_by and pr.role = v_role
                               where i.created_at > now() - interval '30 days'
                               group by created_by) r
                       where r.created_by = p_user)),
    'returned', jsonb_build_object(
        'all_time', (select count(*) from public.inspections where created_by = p_user and approval_status = 'rejected'),
        'last_30d', (select count(*) from public.inspections where created_by = p_user and approval_status = 'rejected' and created_at > now() - interval '30 days'),
        'decided_30d', (select count(*) from public.inspections where created_by = p_user and approval_status in ('rejected', 'approved', 'done') and created_at > now() - interval '30 days'),
        'team_returned_30d', (select count(*) from public.inspections i join public.profiles pr on pr.id = i.created_by and pr.role = v_role
                               where i.approval_status = 'rejected' and i.created_at > now() - interval '30 days'),
        'team_decided_30d', (select count(*) from public.inspections i join public.profiles pr on pr.id = i.created_by and pr.role = v_role
                              where i.approval_status in ('rejected', 'approved', 'done') and i.created_at > now() - interval '30 days'),
        'first_at', (select min(created_at) from public.inspections where created_by = p_user and approval_status = 'rejected'),
        'repeat_assets', (select coalesce(jsonb_agg(jsonb_build_object('asset_no', asset_no, 'n', n) order by n desc, asset_no), '[]'::jsonb)
                            from (select asset_no, count(*) as n from public.inspections
                                   where created_by = p_user and approval_status = 'rejected' and asset_no is not null
                                   group by asset_no) a),
        'recent', (select coalesce(jsonb_agg(jsonb_build_object('at', created_at, 'asset_no', asset_no) order by created_at desc), '[]'::jsonb)
                     from (select created_at, asset_no from public.inspections
                            where created_by = p_user and approval_status = 'rejected'
                            order by created_at desc limit 25) r)),
    'notices', jsonb_build_object(
        'returned_total', (select count(*) from public.notifications where user_id = p_user and type = 'approval_decision' and title ilike '%returned%'),
        'returned_unread', (select count(*) from public.notifications where user_id = p_user and type = 'approval_decision' and title ilike '%returned%' and read = false),
        'total', (select count(*) from public.notifications where user_id = p_user),
        'unread', (select count(*) from public.notifications where user_id = p_user and read = false),
        'last_read', (select jsonb_build_object('at', created_at, 'type', type, 'title', title)
                        from public.notifications where user_id = p_user and read = true
                        order by created_at desc limit 1),
        'recent_returned', (select coalesce(jsonb_agg(jsonb_build_object('at', created_at, 'title', title, 'body', left(body, 160), 'read', read) order by created_at desc), '[]'::jsonb)
                              from (select created_at, title, body, read from public.notifications
                                     where user_id = p_user and type = 'approval_decision' and title ilike '%returned%'
                                     order by created_at desc limit 25) n)),
    'errors', jsonb_build_object(
        'web_30d', (select count(*) from public.system_logs where user_id = p_user and created_at > now() - interval '30 days' and severity in ('error', 'critical')),
        'recent', (select coalesce(jsonb_agg(jsonb_build_object('at', created_at, 'severity', severity, 'module', module_id, 'platform', platform, 'reference_id', reference_id) order by created_at desc), '[]'::jsonb)
                     from (select created_at, severity, module_id, platform, reference_id from public.system_logs
                            where user_id = p_user and created_at > now() - interval '30 days' and severity in ('error', 'critical')
                            order by created_at desc limit 25) l)),
    'issues', jsonb_build_object(
        'total', (select count(*) from public.user_issues where reporter_id = p_user),
        'open', (select count(*) from public.user_issues where reporter_id = p_user and status not in ('fixed', 'closed', 'wont_fix')),
        'recent', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'at', created_at, 'category', category, 'severity', severity, 'status', status, 'platform', platform) order by created_at desc), '[]'::jsonb)
                     from (select id, created_at, category, severity, status, platform from public.user_issues
                            where reporter_id = p_user order by created_at desc limit 25) i)),
    'deletion_request', (select jsonb_build_object('status', status, 'requested_at', requested_at)
                           from public.account_deletion_requests where user_id = p_user
                           order by requested_at desc limit 1)
  ) into v_out;

  return v_out;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_user_signin_facts(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_username text; v_email text; v_emp text; v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  select lower(username), lower(email), lower(employee_id) into v_username, v_email, v_emp
    from public.profiles where id = p_user;
  select jsonb_build_object(
    'logins_30d', (select count(*) from auth.audit_log_entries a
                    where a.payload->>'action' = 'login' and a.payload->>'actor_id' = p_user::text
                      and a.created_at >= now() - interval '30 days'),
    'logins_all', (select count(*) from auth.audit_log_entries a
                    where a.payload->>'action' = 'login' and a.payload->>'actor_id' = p_user::text),
    'first_login_logged', (select min(a.created_at) from auth.audit_log_entries a
                    where a.payload->>'action' = 'login' and a.payload->>'actor_id' = p_user::text),
    'mfa_checks_30d', (select count(*) from auth.audit_log_entries a
                    where a.payload->>'action' = 'verification_attempted' and a.payload->>'actor_id' = p_user::text
                      and a.created_at >= now() - interval '30 days'),
    'failed_burst', (select jsonb_build_object('attempts', la.attempt_count, 'started_at', la.window_started_at,
                            'locked_until', la.locked_until, 'locked_now', coalesce(la.locked_until > now(), false))
                       from public.login_attempts la
                      where lower(la.identifier) in (v_username, v_email, v_emp)
                      order by la.window_started_at desc nulls last limit 1)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_verify_audit_seals(p_source text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(day date, row_count_then bigint, row_count_now bigint, digest_match boolean, chain_ok boolean, match boolean, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  r        record;
  v_cnt    bigint;
  v_dig    text;
  v_prevc  text := null;
  v_first  boolean := true;
  v_ret    int;
  v_cutoff date;
  v_chain  boolean;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not coalesce(public.is_super_admin(), false) then
    raise exception 'Only a super admin can verify audit seals' using errcode = '42501';
  end if;
  if p_source not in ('audit_log_v2','access_audit','console_sessions') then
    raise exception 'Unknown audit source' using errcode = '22023';
  end if;
  begin
    select nullif(regexp_replace(value::text, '[^0-9]', '', 'g'), '')::int into v_ret
      from public.system_config where key = 'audit_retention_days';
  exception when others then v_ret := null;
  end;
  v_cutoff := case when coalesce(v_ret, 0) > 0
                   then ((now() - make_interval(days => v_ret)) at time zone 'UTC')::date
                   else null end;

  for r in select s.* from public.audit_seals s where s.source = p_source order by s.day loop
    v_chain := (r.prev_digest is not distinct from v_prevc)
           and r.chain_digest = encode(extensions.digest(coalesce(r.prev_digest,'GENESIS') || r.digest, 'sha256'), 'hex');
    v_prevc := r.chain_digest;
    v_first := false;
    if (p_from is not null and r.day < p_from) or (p_to is not null and r.day > p_to) then
      continue;
    end if;
    select d.row_count, d.digest into v_cnt, v_dig from public._audit_day_digest(p_source, r.day) d;
    day := r.day;
    row_count_then := r.row_count;
    row_count_now := v_cnt;
    digest_match := (v_dig = r.digest);
    chain_ok := v_chain;
    if digest_match and chain_ok then
      match := true; status := 'match';
    elsif chain_ok and v_cutoff is not null and r.day <= v_cutoff and v_cnt < r.row_count then
      match := true; status := 'purged_by_retention';
    else
      match := false; status := 'mismatch';
    end if;
    return next;
  end loop;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_withdraw_attestation(p_id uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_ctrl text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can withdraw an attestation' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A withdrawal needs a reason (at least 3 characters)' using errcode = '22023';
  end if;
  update public.compliance_attestations
     set withdrawn_at = now(), withdrawn_by = v_uid, withdraw_reason = btrim(p_reason)
   where id = p_id and withdrawn_at is null
  returning control_id into v_ctrl;
  if v_ctrl is null then
    return false;
  end if;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'compliance_withdraw', p_id, 'compliance_attestation',
          jsonb_build_object('control_id', v_ctrl, 'reason', btrim(p_reason)));
  return true;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_feedback_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_reviewer boolean := coalesce(public.get_my_role() in ('Admin','Manager','Director'), false)
                        or coalesce(public.is_super_admin(), false);
  v_conv uuid;
  v_role text;
  v_content text;
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then
      new.user_id := auth.uid();
    end if;
    new.expert_verified := false;
    new.verified_by := null;
    new.verified_at := null;
    new.review_note := null;
    if new.assistant_message_id is not null then
      select m.conversation_id, m.role, m.content
        into v_conv, v_role, v_content
        from public.ai_messages m
       where m.id = new.assistant_message_id;
      if v_conv is null or v_role <> 'assistant' then
        raise exception 'Feedback must reference one of your own assistant answers'
          using errcode = '42501';
      end if;
      new.conversation_id := v_conv;
      new.answer := left(v_content, 12000);
      new.question := (
        select left(u.content, 4000) from public.ai_messages u
         where u.conversation_id = v_conv and u.role = 'user'
           and u.id < new.assistant_message_id
         order by u.id desc limit 1);
    else
      new.answer := null;
      new.question := null;
    end if;
    return new;
  end if;
  if new.user_id is distinct from old.user_id
     or new.organisation_id is distinct from old.organisation_id
     or new.assistant_message_id is distinct from old.assistant_message_id
     or new.conversation_id is distinct from old.conversation_id
     or new.question is distinct from old.question
     or new.answer is distinct from old.answer then
    raise exception 'Feedback provenance cannot be changed' using errcode = '42501';
  end if;
  if (new.expert_verified is distinct from old.expert_verified
      or new.review_note is distinct from old.review_note
      or new.verified_by is distinct from old.verified_by
      or new.verified_at is distinct from old.verified_at)
     and not v_reviewer then
    raise exception 'Only a reviewer can verify feedback' using errcode = '42501';
  end if;
  if new.expert_verified and not old.expert_verified then
    new.verified_by := auth.uid();
    new.verified_at := now();
  elsif not new.expert_verified then
    new.verified_by := null;
    new.verified_at := null;
  else
    new.verified_by := old.verified_by;
    new.verified_at := old.verified_at;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_month_spend_usd(p_unknown_job_usd numeric DEFAULT 0.01)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_since timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
        v_bad integer; v_other numeric; v_tyre numeric; v_orch numeric;
begin
 select count(*) into v_bad from public.ai_token_logs where created_at >= v_since and cost_usd < 0;
 if v_bad > 0 then return null; end if;
 select coalesce(sum(cost_usd), 0) into v_other from public.ai_token_logs
  where created_at >= v_since and coalesce(feature, '') <> 'ai_tyre_inspection' and cost_usd is not null;
 select coalesce(sum(
          (case
             when provider_called_at >= v_since then coalesce(cost_usd, reserved_usd, p_unknown_job_usd)
             when provider_called_at is null and reserved_usd is not null and budget_settled_at is null then reserved_usd
             else 0 end) + coalesce(prior_billed_usd, 0)), 0)
   into v_tyre from public.ai_tyre_inspection_jobs
  where provider_called_at >= v_since or last_retry_at >= v_since
     or (provider_called_at is null and reserved_usd is not null and budget_settled_at is null);
 select coalesce(sum(case status
          when 'reserved' then reserved_usd
          when 'unknown'  then greatest(reserved_usd, coalesce(actual_usd, 0))
          else 0 end), 0)
   into v_orch from public.ai_budget_reservations
  where created_at >= v_since and status in ('reserved', 'unknown');
 return v_other + v_tyre + v_orch;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_orchestrator_reserve_budget(p_attempt uuid, p_org uuid, p_user uuid, p_estimate numeric, p_feature text DEFAULT 'orchestrator'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_row public.ai_budget_reservations; v_enabled text; v_feat text; v_limit_raw text;
        v_limit numeric := 0; v_spent numeric;
begin
 if p_attempt is null or p_estimate is null or p_estimate <= 0 or p_estimate > 5 then
  return jsonb_build_object('ok', false, 'state', 'invalid', 'reason', 'Invalid reservation request');
 end if;
 select * into v_row from public.ai_budget_reservations where id = p_attempt;
 if found then
  return jsonb_build_object('ok', v_row.status = 'reserved', 'idempotent', true, 'attempt_id', v_row.id,
    'state', v_row.status, 'reserved_usd', v_row.reserved_usd);
 end if;
 v_enabled := lower(coalesce(public._ai_cfg_text('ai_enabled'), 'true'));
 v_feat    := lower(coalesce(public._ai_cfg_text('ai_orchestrator_enabled'), 'true'));
 if v_enabled in ('false', '0', 'off', 'no') or v_feat in ('false', '0', 'off', 'no') then
  return jsonb_build_object('ok', false, 'state', 'disabled', 'reason', 'AI is switched off by an administrator');
 end if;
 v_limit_raw := public._ai_cfg_text('ai_monthly_budget_usd');
 if v_limit_raw is not null then
  begin
   v_limit := v_limit_raw::numeric;
  exception when others then
   return jsonb_build_object('ok', false, 'state', 'unavailable', 'reason', 'AI monthly budget setting is invalid');
  end;
  if v_limit < 0 then
   return jsonb_build_object('ok', false, 'state', 'unavailable', 'reason', 'AI monthly budget setting is invalid');
  end if;
 end if;
 perform pg_advisory_xact_lock(hashtext('ai_tyre_month_budget'));
 select * into v_row from public.ai_budget_reservations where id = p_attempt;
 if found then
  return jsonb_build_object('ok', v_row.status = 'reserved', 'idempotent', true, 'attempt_id', v_row.id,
    'state', v_row.status, 'reserved_usd', v_row.reserved_usd);
 end if;
 if v_limit > 0 then
  v_spent := public.ai_month_spend_usd(p_estimate);
  if v_spent is null then
   return jsonb_build_object('ok', false, 'state', 'unavailable', 'reason', 'AI monthly spend could not be read');
  end if;
  if v_spent + p_estimate > v_limit + 0.000000001 then
   return jsonb_build_object('ok', false, 'state', 'reached', 'limit_usd', v_limit, 'spent_usd', round(v_spent, 6),
     'reason', format('Monthly AI budget reached (%s of %s USD)', round(v_spent, 2), round(v_limit, 2)));
  end if;
 end if;
 insert into public.ai_budget_reservations (id, feature, organisation_id, user_id, reserved_usd)
 values (p_attempt, coalesce(nullif(btrim(p_feature), ''), 'orchestrator'), p_org, p_user, p_estimate);
 return jsonb_build_object('ok', true, 'idempotent', false, 'attempt_id', p_attempt,
   'state', case when v_limit > 0 then 'ok' else 'uncapped' end,
   'reserved_usd', p_estimate, 'limit_usd', nullif(v_limit, 0), 'spent_usd', round(v_spent, 6));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_orchestrator_settle_budget(p_attempt uuid, p_outcome text, p_actual_usd numeric, p_cost_known boolean, p_model text, p_prompt_tokens integer, p_completion_tokens integer, p_http_status integer, p_error text, p_latency_ms integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_row public.ai_budget_reservations; v_log uuid; v_status text; v_cost numeric;
begin
 if p_attempt is null or p_outcome is null or p_outcome not in ('success', 'error', 'released') then
  return jsonb_build_object('ok', false, 'reason', 'Invalid settle request');
 end if;
 if p_actual_usd is not null and p_actual_usd < 0 then
  return jsonb_build_object('ok', false, 'reason', 'Invalid cost');
 end if;
 select * into v_row from public.ai_budget_reservations where id = p_attempt for update;
 if not found then
  return jsonb_build_object('ok', false, 'reason', 'Unknown attempt');
 end if;
 if v_row.status <> 'reserved' then
  return jsonb_build_object('ok', true, 'already', true, 'state', v_row.status, 'token_log_id', v_row.token_log_id);
 end if;
 if p_outcome = 'released' then
  update public.ai_budget_reservations
     set status = 'released', actual_usd = 0, settled_at = now(), error = left(p_error, 500)
   where id = p_attempt;
  return jsonb_build_object('ok', true, 'already', false, 'state', 'released');
 end if;
 if p_outcome = 'success' or coalesce(p_cost_known, false) then
  v_status := 'settled'; v_cost := coalesce(p_actual_usd, 0);
 else
  v_status := 'unknown'; v_cost := null;
 end if;
 insert into public.ai_token_logs (user_id, organisation_id, model, feature, prompt_tokens, completion_tokens,
   cost_usd, status, http_status, error, latency_ms)
 values (v_row.user_id, v_row.organisation_id, coalesce(nullif(p_model, ''), 'unknown'), v_row.feature,
   greatest(coalesce(p_prompt_tokens, 0), 0), greatest(coalesce(p_completion_tokens, 0), 0),
   v_cost, case when p_outcome = 'success' then 'success' else 'error' end, p_http_status,
   case when v_status = 'unknown'
        then left(coalesce(p_error, 'AI request failed') || ' (cost unknown, reservation kept)', 500)
        else left(p_error, 500) end,
   p_latency_ms)
 returning id into v_log;
 update public.ai_budget_reservations
    set status = v_status, actual_usd = p_actual_usd, token_log_id = v_log, settled_at = now(),
        error = left(p_error, 500)
  where id = p_attempt;
 return jsonb_build_object('ok', true, 'already', false, 'state', v_status, 'token_log_id', v_log);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_proposal_decide(p_id uuid, p_decision text, p_note text DEFAULT NULL::text, p_create_action boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_uid uuid := auth.uid();
  p public.ai_proposals%rowtype;
  v_ca uuid;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if v_org is null or not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_decision not in ('accepted','rejected') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_decision');
  end if;
  if p_decision = 'rejected' and v_note is null then
    return jsonb_build_object('ok', false, 'reason', 'note_required');
  end if;
  select * into p from public.ai_proposals where id = p_id and organisation_id = v_org for update;
  if not found or (p.country is not null and public.app_can_see_country(p.country) is false) then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if p.status <> 'proposed' then
    raise exception 'This proposal was already %', p.status using errcode = 'PT409';
  end if;
  if p_decision = 'accepted' and coalesce(p_create_action, false) then
    insert into public.corrective_actions
      (organisation_id, title, description, priority, status, site, asset_no, country, region,
       source_type, source_id, source_detail, created_by)
    values
      (v_org,
       left('AI proposal: ' || p.title, 240),
       concat_ws(E'\n', p.summary,
                 case when p.recommended_action is not null then 'Recommended: ' || p.recommended_action end,
                 case when v_note is not null then 'Decision note: ' || v_note end),
       case p.severity when 'critical' then 'High' when 'high' then 'High'
                       when 'medium' then 'Medium' else 'Low' end,
       'Open', p.site, nullif(p.entity_refs->>'asset_no', ''),
       coalesce(p.country, 'KSA'), coalesce(p.country, 'KSA'),
       'ai_proposal', p.id, left(p.dedupe_key, 300), v_uid)
    returning id into v_ca;
  end if;
  update public.ai_proposals set
    status = p_decision, decided_by = v_uid, decided_at = now(),
    decision_note = v_note, corrective_action_id = v_ca
  where id = p.id;
  insert into public.ai_proposal_events (proposal_id, organisation_id, event, actor, note, detail)
  values (p.id, v_org, p_decision, v_uid, v_note,
          jsonb_build_object('corrective_action_id', v_ca, 'created_action', v_ca is not null));
  return jsonb_build_object('ok', true, 'status', p_decision, 'corrective_action_id', v_ca);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_proposal_events_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'Proposal history is append-only' using errcode = '42501';
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_proposals_expire(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_n int := 0;
  r record;
begin
  if v_org is null or not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  for r in select id from public.ai_proposals
            where organisation_id = v_org and status = 'proposed'
              and last_seen_at < now() - make_interval(days => greatest(coalesce(p_days, 30), 7))
            for update loop
    update public.ai_proposals set status = 'expired', decided_at = now() where id = r.id;
    insert into public.ai_proposal_events (proposal_id, organisation_id, event, note)
    values (r.id, v_org, 'expired', 'Not detected for ' || greatest(coalesce(p_days, 30), 7) || ' days');
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'expired', v_n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_proposals_record(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_uid uuid := auth.uid();
  it jsonb;
  v_key text; v_type text; v_sev text; v_country text;
  v_open public.ai_proposals%rowtype;
  v_id uuid;
  v_created int := 0; v_refreshed int := 0; v_skipped int := 0; v_invalid int := 0;
begin
  if v_org is null or not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return jsonb_build_object('ok', false, 'reason', 'invalid');
  end if;
  if jsonb_array_length(p_items) > 500 then
    return jsonb_build_object('ok', false, 'reason', 'too_many');
  end if;
  for it in select value from jsonb_array_elements(p_items) loop
    v_key := nullif(btrim(it->>'dedupe_key'), '');
    v_type := it->>'proposal_type';
    v_sev := it->>'severity';
    v_country := nullif(btrim(it->>'country'), '');
    if v_key is null or nullif(btrim(it->>'title'), '') is null
       or v_type not in ('critical_finding_no_action','repeated_failure','cpk_spike',
                         'abnormal_consumption','premature_removal','warranty_opportunity',
                         'overdue_corrective_action','tyre_overdue_no_action','data_integrity')
       or v_sev not in ('critical','high','medium','low') then
      v_invalid := v_invalid + 1; continue;
    end if;
    if v_country is not null and public.app_can_see_country(v_country) is false then
      v_invalid := v_invalid + 1; continue;
    end if;
    select * into v_open from public.ai_proposals
     where organisation_id = v_org and dedupe_key = v_key and status = 'proposed'
     for update;
    if found then
      if v_open.evidence is distinct from coalesce(it->'evidence', '[]'::jsonb)
         or v_open.severity is distinct from v_sev
         or v_open.metrics is distinct from coalesce(it->'metrics', '{}'::jsonb) then
        update public.ai_proposals set
          severity = v_sev,
          title = left(it->>'title', 300),
          summary = left(it->>'summary', 2000),
          recommended_action = left(it->>'recommended_action', 2000),
          entity_refs = coalesce(it->'entity_refs', '{}'::jsonb),
          evidence = coalesce(it->'evidence', '[]'::jsonb),
          evidence_total = coalesce((it->>'evidence_total')::int, 0),
          metrics = coalesce(it->'metrics', '{}'::jsonb),
          detector_version = it->>'detector_version',
          last_seen_at = now()
        where id = v_open.id;
        insert into public.ai_proposal_events (proposal_id, organisation_id, event, actor, detail)
        values (v_open.id, v_org, 'refreshed', v_uid,
                jsonb_build_object('severity', v_sev, 'evidence_total', it->'evidence_total'));
        v_refreshed := v_refreshed + 1;
      else
        update public.ai_proposals set last_seen_at = now() where id = v_open.id;
        v_skipped := v_skipped + 1;
      end if;
      continue;
    end if;
    if exists (select 1 from public.ai_proposals
                where organisation_id = v_org and dedupe_key = v_key
                  and status = 'rejected' and decided_at > now() - interval '30 days') then
      v_skipped := v_skipped + 1; continue;
    end if;
    insert into public.ai_proposals
      (organisation_id, country, site, proposal_type, severity, dedupe_key, title, summary,
       recommended_action, entity_refs, evidence, evidence_total, metrics, detector_version, created_by)
    values
      (v_org, v_country, nullif(btrim(it->>'site'), ''), v_type, v_sev, v_key,
       left(it->>'title', 300), left(it->>'summary', 2000), left(it->>'recommended_action', 2000),
       coalesce(it->'entity_refs', '{}'::jsonb), coalesce(it->'evidence', '[]'::jsonb),
       coalesce((it->>'evidence_total')::int, 0), coalesce(it->'metrics', '{}'::jsonb),
       it->>'detector_version', v_uid)
    returning id into v_id;
    insert into public.ai_proposal_events (proposal_id, organisation_id, event, actor)
    values (v_id, v_org, 'created', v_uid);
    v_created := v_created + 1;
  end loop;
  return jsonb_build_object('ok', true, 'created', v_created, 'refreshed', v_refreshed,
                            'skipped', v_skipped, 'invalid', v_invalid);
end $function$;
