CREATE OR REPLACE FUNCTION public.ai_tyre_auto_requeue(p_max_retries integer DEFAULT 3, p_base_minutes integer DEFAULT 10, p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n integer;
begin
 with due as (
  select id from public.ai_tyre_inspection_jobs
   where status = 'failed' and failure_kind in ('photo_unavailable', 'provider_rate_limited')
     and retry_count < greatest(0, least(coalesce(p_max_retries, 3), 10))
     and updated_at <= now() - make_interval(mins => greatest(1, coalesce(p_base_minutes, 10)) * (power(2, retry_count))::int)
   order by updated_at asc limit greatest(1, least(coalesce(p_limit, 50), 200))
   for update skip locked)
 update public.ai_tyre_inspection_jobs j set
    status = 'pending', attempts = 0, provider_attempts = 0, provider_called_at = null,
    failure_kind = null, error_message = null, reserved_usd = null, budget_day = null, budget_settled_at = null,
    cost_usd = null, input_tokens = null, output_tokens = null, total_tokens = null,
    retry_count = j.retry_count + 1, last_retry_at = now(), updated_at = now()
  from due where j.id = due.id;
 get diagnostics n = row_count;
 return n;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_dispatch_worker()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE jwt_secret text; worker_secret text;
BEGIN
 SELECT decrypted_secret INTO jwt_secret FROM vault.decrypted_secrets
 WHERE name='tyre_ai_worker_jwt' LIMIT 1;
 SELECT decrypted_secret INTO worker_secret FROM vault.decrypted_secrets
 WHERE name='tyre_ai_worker_secret' LIMIT 1;
 IF jwt_secret IS NULL OR worker_secret IS NULL THEN RETURN; END IF;
 PERFORM net.http_post(
  url := 'https://staging-project-ref.supabase.co/functions/v1/ai-tyre-inspection',
  headers := jsonb_build_object(
   'Content-Type','application/json','Authorization','Bearer ' || jwt_secret,
   'x-worker-secret',worker_secret
  ),
  body := '{"action":"work"}'::jsonb,
  timeout_milliseconds := 30000
 );
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_expert_label_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare j record; v_serial text;
begin
  select organisation_id, inspection_id, tyre_position, photo_ref, model_version, prompt_version, status
    into j from public.ai_tyre_inspection_jobs where id = new.job_id;
  if not found then raise exception 'AI job not found' using errcode = '23503'; end if;
  if j.status <> 'completed' then raise exception 'Only completed AI analyses can be labelled' using errcode = '22023'; end if;
  if tg_op = 'UPDATE' and new.job_id is distinct from old.job_id then
    raise exception 'A label cannot be moved to another photograph' using errcode = '22023';
  end if;
  if auth.uid() is not null then
    if tg_op = 'INSERT' then new.reviewer_id := auth.uid();
    elsif new.reviewer_id is distinct from old.reviewer_id then
      raise exception 'The reviewer of a label cannot be changed' using errcode = '42501';
    end if;
    if not public.is_super_admin() and j.organisation_id is distinct from public.app_current_org() then
      raise exception 'AI job belongs to another organisation' using errcode = '42501';
    end if;
  end if;
  new.organisation_id := j.organisation_id;
  new.inspection_id := j.inspection_id;
  new.tyre_position := j.tyre_position;
  new.photo_ref := j.photo_ref;
  new.model_version := j.model_version;
  new.prompt_version := j.prompt_version;
  v_serial := nullif(upper(btrim(coalesce(new.tyre_serial, ''), E' \t\r\n')), '');
  new.tyre_serial := v_serial;
  new.group_key := coalesce(v_serial, 'insp:' || j.inspection_id::text);
  new.split := public.ai_tyre_split_for(new.group_key);
  if not new.assessable then new.expected_defects := '{}'; end if;
  new.updated_at := now();
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_fail_stale_processing(p_minutes integer DEFAULT 15)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r record; n integer := 0;
begin
 for r in select id, reserved_usd, budget_settled_at from public.ai_tyre_inspection_jobs
          where status = 'processing' and updated_at < now() - make_interval(mins => greatest(1, p_minutes))
          for update skip locked
 loop
  update public.ai_tyre_inspection_jobs
     set status = 'failed', failure_kind = 'stalled', updated_at = now(),
         error_message = 'Stalled while processing; provider may have been called and billed; manual review required'
   where id = r.id;
  if r.reserved_usd is not null and r.budget_settled_at is null then
   perform public.ai_tyre_settle_budget(r.id, null, true);
  end if;
  n := n + 1;
 end loop;
 return n;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_fnv1a(p text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare
  b bytea := convert_to(p, 'UTF8');
  h bigint := 2166136261;
  i int;
begin
  for i in 0 .. length(b) - 1 loop
    h := (h # get_byte(b, i)) & 4294967295;
    h := (h * 16777619) & 4294967295;
  end loop;
  return h;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_has_photo(p jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select coalesce(bool_or(
   p -> k is not null
   and (p -> k) not in ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb)
 ), false)
 from unnest(array['photo_url','photo_uri','photo','photos','photo_refs','evidence']) k
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_register_page(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_condition text DEFAULT NULL::text, p_photos boolean DEFAULT NULL::boolean, p_ai_status text DEFAULT NULL::text, p_review text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, total bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
 with params as (
   select least(greatest(coalesce(p_limit, 50), 1), 200) as lim,
          greatest(coalesce(p_offset, 0), 0) as off,
          nullif(btrim(replace(replace(replace(coalesce(p_search, ''), '\', ''), '%', ''), '_', '')), '') as term
 ), matched as (
   select i.id, i.inspection_date,
          count(*) over () as total
     from public.inspections i, params
    where (p_country is null or p_country = 'All' or i.country = p_country)
      and (p_from is null or i.inspection_date >= p_from)
      and (p_to is null or i.inspection_date < p_to + 1)
      and (p_site is null or p_site = 'all' or i.site = p_site)
      and (p_status is null or p_status = 'all' or i.status = p_status)
      and (params.term is null or i.asset_no ilike '%' || params.term || '%' or i.site ilike '%' || params.term || '%')
      and (p_condition is null or p_condition = 'all' or exists (
            select 1 from jsonb_each(case when jsonb_typeof(i.tyre_conditions) = 'object' then i.tyre_conditions else '{}'::jsonb end) e
             where jsonb_typeof(e.value) = 'object' and e.value ->> 'condition' = p_condition))
      and (p_photos is not true or exists (
            select 1 from jsonb_each(case when jsonb_typeof(i.tyre_conditions) = 'object' then i.tyre_conditions else '{}'::jsonb end) e
             where jsonb_typeof(e.value) = 'object'
               and lower(coalesce(e.value ->> 'condition', e.value ->> 'status', e.value ->> 'risk', ''))
                   ~ '(worn|wear|damag|cut|crack|bulg|punct|flat|separat|cord|burst)'
               and public.ai_tyre_has_photo(e.value)))
      and (p_ai_status is null or p_ai_status = 'all'
           or (p_ai_status = 'none' and not exists (select 1 from public.ai_tyre_inspection_jobs j where j.inspection_id = i.id))
           or (p_ai_status <> 'none' and exists (select 1 from public.ai_tyre_inspection_jobs j where j.inspection_id = i.id and j.status = p_ai_status)))
      and (p_review is null or p_review = 'all'
           or exists (select 1 from public.ai_tyre_inspection_jobs j where j.inspection_id = i.id and coalesce(j.review_status, 'unreviewed') = p_review))
 )
 select m.id, m.total from matched m, params
  order by m.inspection_date desc nulls last, m.id asc
  offset (select off from params) limit (select lim from params)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_requeue_jobs(p_org uuid, p_job_ids uuid[], p_include_billed boolean DEFAULT false, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.ai_tyre_inspection_jobs; n integer := 0; v_skipped jsonb := '[]'::jsonb;
        v_safe boolean; v_carry numeric;
begin
 if p_org is null or p_job_ids is null or cardinality(p_job_ids) = 0 or cardinality(p_job_ids) > 100 then
  return jsonb_build_object('ok', false, 'reason', 'Between 1 and 100 job ids required');
 end if;
 for r in select * from public.ai_tyre_inspection_jobs
           where id = any(p_job_ids) and organisation_id = p_org for update
 loop
  if r.status <> 'failed' then
   v_skipped := v_skipped || jsonb_build_object('id', r.id, 'reason', 'not_failed'); continue;
  end if;
  v_safe := coalesce(r.failure_kind, '') in ('photo_unavailable', 'provider_rate_limited', 'photo_unusable');
  if not v_safe and p_include_billed is not true then
   v_skipped := v_skipped || jsonb_build_object('id', r.id, 'reason', 'may_have_been_billed'); continue;
  end if;
  v_carry := 0;
  if not v_safe and r.provider_called_at is not null then
   v_carry := coalesce(r.cost_usd, r.reserved_usd, 0.01);
  end if;
  update public.ai_tyre_inspection_jobs set
    status = 'pending', attempts = 0, provider_attempts = 0, provider_called_at = null,
    failure_kind = null, error_message = null, reserved_usd = null, budget_day = null, budget_settled_at = null,
    cost_usd = null, input_tokens = null, output_tokens = null, total_tokens = null,
    prior_billed_usd = prior_billed_usd + v_carry, retry_count = retry_count + 1,
    last_retry_at = now(), retried_by = p_actor, updated_at = now()
  where id = r.id;
  n := n + 1;
 end loop;
 return jsonb_build_object('ok', true, 'requeued', n, 'skipped', v_skipped);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_reserve_budget(p_job uuid, p_estimate numeric, p_limit numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_day date := (now() at time zone 'utc')::date; v_job public.ai_tyre_inspection_jobs; v_hit boolean;
begin
 if p_estimate is null or p_estimate <= 0 or p_limit is null or p_limit < 0 then
  return jsonb_build_object('ok', false, 'reason', 'Invalid reservation request');
 end if;
 select * into v_job from public.ai_tyre_inspection_jobs where id = p_job for update;
 if not found or v_job.status <> 'processing' then
  return jsonb_build_object('ok', false, 'reason', 'Job is not in processing state');
 end if;
 if v_job.reserved_usd is not null or v_job.provider_attempts > 0 then
  return jsonb_build_object('ok', false, 'reason', 'Job already reserved or attempted; no second paid call');
 end if;
 insert into public.ai_tyre_daily_budget(day) values (v_day) on conflict (day) do nothing;
 update public.ai_tyre_daily_budget
    set reserved_usd = reserved_usd + p_estimate, updated_at = now()
  where day = v_day and reserved_usd + settled_usd + p_estimate <= p_limit
  returning true into v_hit;
 if v_hit is not true then
  return jsonb_build_object('ok', false, 'reason', 'Daily AI spending limit reached');
 end if;
 update public.ai_tyre_inspection_jobs set reserved_usd = p_estimate, budget_day = v_day where id = p_job;
 return jsonb_build_object('ok', true, 'reserved', p_estimate, 'day', v_day);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_reserve_budget_atomic(p_job uuid, p_estimate numeric, p_daily_limit numeric, p_month_limit numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_spent numeric; v_res jsonb;
begin
 if p_estimate is null or p_estimate <= 0 then
  return jsonb_build_object('ok', false, 'reason', 'Invalid reservation request');
 end if;
 if p_month_limit is not null and p_month_limit > 0 then
  perform pg_advisory_xact_lock(hashtext('ai_tyre_month_budget'));
  v_spent := public.ai_month_spend_usd(p_estimate);
  if v_spent is null then
   return jsonb_build_object('ok', false, 'scope', 'monthly', 'reason', 'AI monthly spend could not be read');
  end if;
  if v_spent + p_estimate > p_month_limit + 0.000000001 then
   return jsonb_build_object('ok', false, 'scope', 'monthly',
    'reason', format('Monthly AI budget reached (%s of %s USD)', round(v_spent, 2), round(p_month_limit, 2)));
  end if;
 end if;
 v_res := public.ai_tyre_reserve_budget(p_job, p_estimate, coalesce(p_daily_limit, 0));
 return v_res;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_settle_budget(p_job uuid, p_actual numeric, p_provider_called boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job public.ai_tyre_inspection_jobs; v_charge numeric;
begin
 select * into v_job from public.ai_tyre_inspection_jobs where id = p_job for update;
 if not found then return jsonb_build_object('ok', false, 'reason', 'Job not found'); end if;
 if v_job.reserved_usd is null or v_job.budget_day is null then
  return jsonb_build_object('ok', true, 'note', 'Nothing reserved');
 end if;
 if v_job.budget_settled_at is not null then
  return jsonb_build_object('ok', true, 'note', 'Already settled');
 end if;
 if p_provider_called is not true then
  update public.ai_tyre_daily_budget
     set reserved_usd = greatest(0, reserved_usd - v_job.reserved_usd), updated_at = now()
   where day = v_job.budget_day;
  update public.ai_tyre_inspection_jobs set reserved_usd = null, budget_day = null where id = p_job;
  return jsonb_build_object('ok', true, 'charged', 0);
 end if;
 v_charge := greatest(0, coalesce(p_actual, v_job.reserved_usd));
 update public.ai_tyre_daily_budget
    set reserved_usd = greatest(0, reserved_usd - v_job.reserved_usd),
        settled_usd = settled_usd + v_charge,
        unknown_cost_calls = unknown_cost_calls + (case when p_actual is null then 1 else 0 end),
        updated_at = now()
  where day = v_job.budget_day;
 update public.ai_tyre_inspection_jobs set budget_settled_at = now() where id = p_job;
 return jsonb_build_object('ok', true, 'charged', v_charge, 'usage_known', p_actual is not null);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_split_for(p_group text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select case when public.ai_tyre_fnv1a(p_group) % 100 < 60 then 'train'
              when public.ai_tyre_fnv1a(p_group) % 100 < 80 then 'validation'
              else 'holdout' end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_try_acquire_worker_lock(p_ttl_seconds integer DEFAULT 45)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare got int;
begin
  update public.ai_tyre_worker_lock
     set locked_until = now() + make_interval(secs => greatest(5, least(coalesce(p_ttl_seconds, 45), 300)))
   where id = 1 and locked_until <= now();
  get diagnostics got = row_count;
  return got = 1;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.ai_tyre_validate_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE inspection_org uuid;
BEGIN
 SELECT organisation_id INTO inspection_org FROM public.inspections WHERE id=NEW.inspection_id;
 IF inspection_org IS NULL OR inspection_org IS DISTINCT FROM NEW.organisation_id THEN
  RAISE EXCEPTION 'Inspection organisation mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.alert_console_break_glass()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_who text;
  v_title text;
  v_risky text[] := array['bulk_set_role','update_permissions','update_config','duplicate_resolve',
                          'data_cleanup','backup_restore','restore_missing','delete_user','set_super_admin',
                          'enable_2fa','disable_2fa','set_mobile_min_version','support_session_start','revoke_sessions','api_key_revoke'];
begin
  if NEW.action <> 'login' and NEW.action <> all (v_risky) then
    return NEW;
  end if;
  select coalesce(full_name, email, NEW.admin_id::text) into v_who from public.profiles where id = NEW.admin_id;
  v_title := case when NEW.action = 'login' then 'Super admin signed in to the console'
                  else 'High-risk console action: ' || replace(NEW.action, '_', ' ') end;
  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    select p.id, 'security', v_title,
           coalesce(v_who, 'Unknown') || ' at ' || to_char(NEW.created_at at time zone 'Asia/Riyadh', 'DD Mon YYYY HH24:MI') || ' (Riyadh).',
           'console_session', NEW.id
      from public.profiles p where coalesce(p.is_super_admin,false) and not coalesce(p.locked,false);
    insert into public.system_logs (severity, source, module_id, message, user_id, detail)
    values (case when NEW.action = 'login' then 'info' else 'warning' end, 'break_glass', 'security_audit',
            v_title || ' by ' || coalesce(v_who, 'unknown'), NEW.admin_id,
            jsonb_build_object('action', NEW.action, 'target_type', NEW.target_type, 'target_id', NEW.target_id));
  exception when others then
    null;
  end;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.alert_super_admin_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if NEW.entity is distinct from 'super_admin' then
    return NEW;
  end if;
  begin
    insert into public.notifications (user_id, type, title, body, entity_type)
    select p.id, 'security', 'Super admin access changed',
           coalesce(NEW.actor_email, 'System') || ' changed super-admin access for a user. Review in Console > Audit.',
           'access_audit'
      from public.profiles p where coalesce(p.is_super_admin,false) and not coalesce(p.locked,false);
    insert into public.system_logs (severity, source, module_id, message, detail)
    values ('critical', 'break_glass', 'security_audit', 'Super admin access changed',
            jsonb_build_object('actor', NEW.actor_email, 'target', NEW.target_user, 'before', NEW.before, 'after', NEW.after));
  exception when others then
    null;
  end;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.announcement_audience(p_roles text[] DEFAULT NULL::text[], p_countries text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can size an announcement audience' using errcode = '42501';
  end if;
  with aud as (
    select p.id from public.profiles p
    where coalesce(p.approved, false) and not coalesce(p.locked, false)
      and (p_roles is null or cardinality(p_roles) = 0 or p.role = any(p_roles))
      and (p_countries is null or cardinality(p_countries) = 0 or p.country && p_countries)
  )
  select jsonb_build_object(
    'ok', true,
    'accounts', (select count(*) from aud),
    'signed_in_30d', (select count(*) from aud a join auth.users u on u.id = a.id
                       where u.last_sign_in_at >= now() - interval '30 days'),
    'push_reachable', (select count(distinct d.user_id) from public.user_devices d join aud a on a.id = d.user_id
                        where not coalesce(d.revoked, false) and nullif(btrim(d.push_token), '') is not null)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.api_key_authenticate(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row    public.api_keys%ROWTYPE;
  v_minute timestamptz := date_trunc('minute', now());
  v_count  int;
BEGIN
  SELECT * INTO v_row FROM public.api_keys
   WHERE key_hash = encode(digest(COALESCE(p_key, ''), 'sha256'), 'hex');
  IF NOT FOUND OR NOT v_row.active
     OR (v_row.expires_at IS NOT NULL AND v_row.expires_at < now()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_key');
  END IF;
  INSERT INTO public.api_key_usage AS u (key_id, minute, count)
  VALUES (v_row.id, v_minute, 1)
  ON CONFLICT (key_id, minute) DO UPDATE SET count = u.count + 1
  RETURNING count INTO v_count;
  DELETE FROM public.api_key_usage WHERE minute < now() - interval '1 hour';
  UPDATE public.api_keys SET last_used_at = now() WHERE id = v_row.id;
  IF v_count > v_row.rate_per_minute THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rate_limited', 'limit', v_row.rate_per_minute);
  END IF;
  RETURN jsonb_build_object('ok', true, 'key_id', v_row.id,
                            'organisation_id', v_row.organisation_id,
                            'scopes', to_jsonb(v_row.scopes),
                            'remaining', v_row.rate_per_minute - v_count);
END;
$function$;
