CREATE OR REPLACE FUNCTION public.app_can_admin_delete()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select p.is_super_admin is true or lower(btrim(coalesce(p.role, ''))) = 'admin'
    from public.profiles p
    where p.id = auth.uid()
      and p.locked is false
      and coalesce(p.approved, true) is true
    limit 1
  ), false);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_can_see_country(p_country text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p_country is null
    or public.is_super_admin()
    or exists (
      select 1 from public.profiles pr
      where pr.id = auth.uid()
        and pr.country is not null
        and cardinality(pr.country) > 0
        and exists (
          select 1 from unnest(pr.country) x
          where lower(btrim(x)) = 'all'
             or lower(btrim(x)) = lower(btrim(p_country))
        )
    );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_can_see_site(p_site text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_site is null or btrim(p_site) = '' then true
    else coalesce((
      select p.is_super_admin
             or p.role = 'Admin'
             or (p.sites is not null and exists (
                   select 1 from unnest(p.sites) s where upper(btrim(s)) in ('ALL', '*')))
             or (p.sites is not null and cardinality(p.sites) > 0
                 and upper(btrim(p_site)) in (select upper(btrim(s)) from unnest(p.sites) s))
      from public.profiles p where p.id = auth.uid()
    ), false)
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_cap_granted(p_key text, p_cap text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when auth.uid() is null then false
    when exists (select 1 from public.user_access_grants g
                  where g.user_id = auth.uid() and g.module_key = p_key and g.capability = p_cap
                    and g.effect = 'revoke' and (g.expires_at is null or g.expires_at > now())) then false
    else exists (select 1 from public.user_access_grants g
                  where g.user_id = auth.uid() and g.module_key = p_key and g.capability = p_cap
                    and g.effect = 'grant' and (g.expires_at is null or g.expires_at > now()))
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_cap_revoked(p_key text, p_cap text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN public.is_super_admin() OR public.get_my_role() = 'Admin' THEN false
    ELSE EXISTS (
      SELECT 1 FROM public.user_access_grants g
      WHERE g.user_id = auth.uid() AND g.module_key = p_key AND g.capability = p_cap
        AND g.effect = 'revoke' AND (g.expires_at IS NULL OR g.expires_at > now()))
  END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_country_scope()
 RETURNS text[]
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select array_agg(lower(btrim(x))) from public.profiles pr, unnest(pr.country) x
    where pr.id = auth.uid() and x is not null and btrim(x) <> ''
