CREATE OR REPLACE FUNCTION public.app_site_scope()
 RETURNS text[]
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select array_agg(upper(btrim(s))) from public.profiles p, unnest(p.sites) s
    where p.id = auth.uid() and s is not null and btrim(s) <> ''
  ), '{}'::text[]);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_user_can(p_key text, p_cap text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_role text; v_super boolean := false;
  v_cap text := coalesce(nullif(btrim(p_cap), ''), 'view');
  v_default boolean := false; v_revoked boolean; v_granted boolean;
  v_json jsonb; v_ov jsonb;
begin
  if v_uid is null then return false; end if;
  select role, coalesce(is_super_admin, false) into v_role, v_super
    from public.profiles
   where id = v_uid
     and coalesce(approved, true) = true
     and coalesce(locked, false) = false;
  if not found then return false; end if;

  if v_super is true or v_role = 'Admin' then return true; end if;
  if v_cap = 'delete' then return false; end if;

  if v_cap = 'view' then
    v_default := coalesce((
      select enabled from public.module_permissions
       where org_id is null and role = v_role and module_key = p_key
       order by updated_at desc nulls last limit 1
    ), false);
  else
    begin
      select (settings->'app_settings'->>'permission_overrides')::jsonb into v_json from public.organisations where id=public.app_current_org();
      v_ov := coalesce(v_json -> 'overrides', v_json);
      v_default := coalesce((v_ov -> v_role -> p_key ->> v_cap)::boolean, false);
    exception when others then v_default := false;
    end;
  end if;

  v_revoked := exists (
    select 1 from public.user_access_grants g
     where g.user_id = v_uid and g.module_key = p_key and g.capability = v_cap
       and g.effect = 'revoke' and (g.expires_at is null or g.expires_at > now())
  );
  if v_revoked then return false; end if;
  if v_default then return true; end if;
  v_granted := exists (
    select 1 from public.user_access_grants g
     where g.user_id = v_uid and g.module_key = p_key and g.capability = v_cap
       and g.effect = 'grant' and (g.expires_at is null or g.expires_at > now())
  );
  return v_granted;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.app_write_country_ok(p_country text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Byte-for-byte the V542 <t>_country_write policy expression. A SECURITY
  -- DEFINER write is judged by exactly the rule the table enforces on an
  -- ordinary writer. Unlike app_can_see_country this has NO app_is_org_admin()
  -- bypass: only the platform owner crosses a country boundary (V498).
  select p_country is null
      or public.is_super_admin()
      or public.app_sees_all_countries()
      or lower(btrim(p_country)) = any (coalesce(public.app_country_scope(), '{}'::text[]));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_due_flag_changes()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.flag_changes; n int := 0; f int := 0;
begin
  for r in select * from public.flag_changes where status = 'scheduled' and run_at <= now() order by run_at limit 50 for update skip locked loop
    begin
      if r.target_type = 'module' then
        update public.modules set status = r.new_state, last_updated = now(),
          maintenance_note = case when r.new_state = 'maintenance' then left(r.reason, 500) else maintenance_note end
         where module_id = r.target_key;
      else
        update public.system_config set value = r.new_state, updated_at = now() where key = r.target_key;
      end if;
      update public.flag_changes set status = 'applied', applied_at = now() where id = r.id;
      n := n + 1;
    exception when others then
      update public.flag_changes set status = 'failed', error = left(sqlerrm, 300), applied_at = now() where id = r.id;
      f := f + 1;
    end;
  end loop;
  return jsonb_build_object('ok', true, 'applied', n, 'failed', f);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_learned_rule(p_token text, p_category text, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_token text := lower(btrim(coalesce(p_token, '')));
  v_status text;
  v_items int := 0;
  v_lines bigint := 0;
  v_value numeric := 0;
begin
  if v_org is null then
    raise exception 'No organisation in session' using errcode = '42501';
  end if;
  if public.app_role() not in ('admin', 'manager', 'director')
     and not public.is_super_admin() then
    raise exception 'You do not have permission to apply classification rules'
      using errcode = '42501';
  end if;

  select status into v_status
    from public.classification_learned_rules
   where organisation_id = v_org and token = v_token and category = p_category;

  if v_status is distinct from 'active' then
    raise exception 'This rule has not been accepted' using errcode = '42501';
  end if;

  drop table if exists _learn_apply;

  -- Candidates: unidentified item codes whose description carries the token as a
  -- WHOLE WORD (the 'Shell RIMula matched rim' lesson - never a substring), that
  -- the veto allows, and that NO human has already reviewed. A reviewed decision
  -- outranks every token, including a learned one.
  create temp table _learn_apply as
  select pc.country, pc.item_code,
         min(pc.item_description) as item_name,
         count(*) as lines,
         coalesce(sum(pc.line_cost), 0) as value
  from public.parts_consumption pc
  where pc.organisation_id = v_org
    and pc.classified_by = 'default'
    and public.brain_has_any_word(pc.item_description, array[v_token])
    and not public.learned_rule_vetoed(pc.item_description, p_category)
    and not exists (
      select 1 from public.material_master mm
      where mm.organisation_id = v_org
        and mm.country = pc.country
        and mm.item_code = pc.item_code
        and mm.reviewed is true)
  group by pc.country, pc.item_code;

  select count(*), coalesce(sum(lines), 0), coalesce(sum(value), 0)
    into v_items, v_lines, v_value from _learn_apply;

  if p_dry_run then
    return jsonb_build_object(
      'ok', true, 'dry_run', true, 'token', v_token, 'category', p_category,
      'items', v_items, 'lines', v_lines, 'value', round(v_value, 2),
      'preview', coalesce((
        select jsonb_agg(jsonb_build_object('country', country, 'item_code', item_code,
                                            'item_name', item_name, 'lines', lines,
                                            'value', round(value, 2))
                          order by value desc)
        from (select * from _learn_apply order by value desc limit 25) t), '[]'::jsonb));
  end if;

  insert into public.material_master
         (organisation_id, country, item_code, item_name, category,
          reviewed, reviewed_by, reviewed_at, proposed_from)
  select v_org, country, item_code, item_name, p_category,
         true, auth.uid(), now(), 'learned:' || v_token
  from _learn_apply
  on conflict (organisation_id, country, item_code) do update
     set category = excluded.category,
         reviewed = true,
         reviewed_by = excluded.reviewed_by,
         reviewed_at = excluded.reviewed_at,
         proposed_from = excluded.proposed_from
   where public.material_master.reviewed is not true;

  return jsonb_build_object(
    'ok', true, 'dry_run', false, 'token', v_token, 'category', p_category,
    'items', v_items, 'lines', v_lines, 'value', round(v_value, 2),
    'next', 'Run reclassify_from_master to move the loaded money.');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_production_station_map(p_country text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_would int;
  v_done int;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'not_allowed');
  end if;
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;

  select count(*) into v_would
    from public.production_logs p
    join public.production_station_map m
      on m.organisation_id = p.organisation_id
     and (m.country is null or m.country = p.country)
     and upper(btrim(m.station)) = upper(btrim(coalesce(p.station, p.site)))
   where p.organisation_id = v_org
     and (p_country is null or p.country = p_country)
     and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
     and p.site is distinct from m.site;

  if p_dry_run then
    return jsonb_build_object('ok', true, 'dry_run', true, 'rows', v_would);
  end if;

  -- The trigger does the resolving, so touching the row is enough and the rule
  -- lives in exactly one place.
  update public.production_logs p
     set station = coalesce(nullif(btrim(p.station), ''), nullif(btrim(p.site), ''))
    from public.production_station_map m
   where m.organisation_id = p.organisation_id
     and (m.country is null or m.country = p.country)
     and upper(btrim(m.station)) = upper(btrim(coalesce(p.station, p.site)))
     and p.organisation_id = v_org
     and (p_country is null or p.country = p_country)
     and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
     and p.site is distinct from m.site;
  get diagnostics v_done = row_count;

  return jsonb_build_object('ok', true, 'dry_run', false, 'rows', v_done);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_station_proposals(p_country text, p_stations jsonb, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_written int := 0;
  v_preview jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_country is null or btrim(p_country) = '' then
    return jsonb_build_object('ok', false, 'reason', 'country_required');
  end if;
  if public.app_write_country_ok(p_country) is false then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_stations is null or jsonb_typeof(p_stations) <> 'array' then
    return jsonb_build_object('ok', false, 'reason', 'no_stations');
  end if;

  with want as (
    select btrim(e->>'station') station,
           nullif(btrim(e->>'site'), '') site,
           nullif(btrim(e->>'region'), '') region,
           nullif(btrim(e->>'confidence'), '') confidence,
           nullif(btrim(e->>'evidence'), '') evidence
    from jsonb_array_elements(p_stations) e
    where coalesce(btrim(e->>'station'), '') <> ''
      and (nullif(btrim(e->>'site'), '') is not null or nullif(btrim(e->>'region'), '') is not null)
  ),
  -- What this would do to the region split, computed from the same rows
  -- get_cost_per_m3 will read.
  moved as (
    select coalesce(w.region, s.region) region,
           count(*) loads,
           sum(coalesce(pl.approved_m3, 0)) approved_m3
    from public.production_logs pl
    join want w on upper(btrim(w.station)) = upper(btrim(pl.station))
    left join public.sites s
      on s.organisation_id = v_org and s.country = p_country
     and upper(btrim(s.name)) = upper(btrim(w.site))
    where pl.organisation_id = v_org and pl.country = p_country
    group by 1
  )
  select jsonb_agg(jsonb_build_object(
           'region', coalesce(region, 'Unassigned'),
           'loads', loads, 'approved_m3', round(approved_m3))
         order by approved_m3 desc)
  into v_preview from moved;

  if p_dry_run then
    return jsonb_build_object('ok', true, 'dry_run', true,
      'stations', jsonb_array_length(p_stations),
      'would_move', coalesce(v_preview, '[]'::jsonb));
  end if;

  with want as (
    select btrim(e->>'station') station,
           nullif(btrim(e->>'site'), '') site,
           nullif(btrim(e->>'region'), '') region,
           nullif(btrim(e->>'confidence'), '') confidence,
           nullif(btrim(e->>'evidence'), '') evidence
    from jsonb_array_elements(p_stations) e
    where coalesce(btrim(e->>'station'), '') <> ''
      and (nullif(btrim(e->>'site'), '') is not null or nullif(btrim(e->>'region'), '') is not null)
  ),
  del as (
    delete from public.production_station_map m
    using want w
    where m.organisation_id = v_org and m.country = p_country
      and upper(btrim(m.station)) = upper(btrim(w.station))
    returning 1
  ),
  ins as (
    insert into public.production_station_map
      (organisation_id, country, station, site, region, confidence, evidence, note, created_by)
    select v_org, p_country, w.station, w.site, w.region, w.confidence, w.evidence,
           'Confirmed from the station mapping proposal', auth.uid()
    from want w
    returning 1
  )
  select count(*) into v_written from ins;

  return jsonb_build_object('ok', true, 'dry_run', false,
    'written', v_written, 'moved', coalesce(v_preview, '[]'::jsonb));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_tyre_change(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_org uuid := public.app_current_org();
  v_removed_id uuid; v_removed public.tyre_records%rowtype; v_new_id uuid;
  v_asset    text := nullif(btrim(p->>'asset_no'), '');
  v_position text := nullif(btrim(p->>'position'), '');
  v_site     text := nullif(btrim(p->>'site'), '');
  v_reason   text := nullif(btrim(p->>'removal_reason'), '');
  v_rem_date date := coalesce((p->>'removal_date')::date, current_date);
  v_issue_date date := coalesce((p->>'issue_date')::date, (p->>'fitment_date')::date, current_date);
  v_occupied uuid;
begin
  if public.app_cap_revoked('tyre_records','edit') then
    raise exception 'Not authorised to change tyres.' using errcode = '42501'; end if;
  if not public.is_approved_and_unlocked() then
    raise exception 'Not authorised.' using errcode = '42501'; end if;
  if v_asset is null then raise exception 'asset_no is required.' using errcode = '22004'; end if;
  if v_position is null then raise exception 'position is required.' using errcode = '22004'; end if;
  if nullif(btrim(p->>'country'),'') is not null
     and not public.app_write_country_ok(nullif(btrim(p->>'country'),'')) then
    raise exception 'Cross-country tyre change denied.' using errcode = '42501'; end if;
  v_removed_id := nullif(p->>'removed_record_id','')::uuid;

  if v_removed_id is not null then
    select * into v_removed from public.tyre_records where id = v_removed_id for update;
    if not found then raise exception 'Removed tyre record % not found.', v_removed_id using errcode = 'P0002'; end if;
    if v_removed.organisation_id is not null and v_removed.organisation_id is distinct from v_org then
      raise exception 'Cross-organisation tyre change denied.' using errcode = '42501'; end if;
    if v_removed.country is not null and not public.app_write_country_ok(v_removed.country) then
      raise exception 'Cross-country tyre change denied.' using errcode = '42501'; end if;
    if not public.tyre_status_is_active(v_removed.status) then
      raise exception 'Tyre % is not currently active.', v_removed_id using errcode = '23514'; end if;
    if nullif(upper(btrim(coalesce(v_removed.asset_no, v_removed.asset_number))),'') is distinct from upper(v_asset) then
      raise exception 'Removed tyre is on a different asset.' using errcode = '23514'; end if;
    if nullif(upper(btrim(coalesce(v_removed.tyre_position, v_removed.position))),'') is distinct from upper(v_position) then
      raise exception 'Removed tyre is at a different position.' using errcode = '23514'; end if;
    update public.tyre_records
      set km_at_removal = coalesce((p->>'km_at_removal')::numeric, km_at_removal),
          removal_date  = v_rem_date,
          removal_reason = coalesce(v_reason, removal_reason),
          status = 'Removed'
      where id = v_removed_id;
  else
    select id into v_occupied from public.tyre_records
    where organisation_id is not distinct from v_org
      and nullif(upper(btrim(coalesce(asset_no, asset_number))),'') = upper(v_asset)
      and nullif(upper(btrim(coalesce(tyre_position, position))),'') = upper(v_position)
      and public.tyre_status_is_active(status)
    for update limit 1;
    if v_occupied is not null then
      raise exception 'Position % on asset % already has an active tyre; specify removed_record_id.', v_position, v_asset
        using errcode = '23505'; end if;
  end if;

  insert into public.tyre_records
    (asset_no, serial_no, brand, site, country, cost_per_tyre, qty,
     position, tyre_position, km_at_fitment, removal_reason,
     issue_date, status, risk_level, category, uploaded_by, organisation_id)
  values
    (v_asset, nullif(btrim(p->>'serial_no'),''), nullif(btrim(p->>'brand'),''), v_site,
     nullif(btrim(p->>'country'),''), (p->>'cost_per_tyre')::numeric, coalesce((p->>'qty')::int,1),
     v_position, v_position, (p->>'km_at_fitment')::numeric, v_reason,
     v_issue_date,
     coalesce(nullif(btrim(p->>'status'),''),'Active'),
     coalesce(nullif(btrim(p->>'risk_level'),''),'Low'),
     coalesce(nullif(btrim(p->>'category'),''),'Tyre Change'),
     v_uid, v_org)
  returning id into v_new_id;

  perform public.record_audit_event('tyre_change','tyre_records', v_new_id::text,
    case when v_removed_id is null then null else jsonb_build_object(
      'removed_record_id', v_removed_id, 'asset_no', v_removed.asset_no,
      'serial_no', v_removed.serial_no, 'position', v_removed.position,
      'km_at_removal', coalesce((p->>'km_at_removal')::numeric, v_removed.km_at_removal),
      'removal_reason', v_reason, 'status', 'Removed') end,
    jsonb_build_object('fitment_record_id', v_new_id, 'asset_no', v_asset,
      'serial_no', nullif(btrim(p->>'serial_no'),''), 'brand', nullif(btrim(p->>'brand'),''),
      'position', v_position, 'site', v_site, 'cost_per_tyre', (p->>'cost_per_tyre')::numeric,
      'km_at_fitment', (p->>'km_at_fitment')::numeric, 'fitment_date', v_issue_date));
  return v_new_id;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.apply_tyre_learned_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  -- brand
  if NEW.brand is null or btrim(NEW.brand)='' then
    select target_value into v from public.tyre_learned_facts where active and target_field='brand' and match_type='serial'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.serial_no))
      order by confidence desc, updated_at desc limit 1;
    if v is not null then NEW.brand:=v; end if;
  else
    select target_value into v from public.tyre_learned_facts where active and target_field='brand' and match_type='alias'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.brand))
      order by updated_at desc limit 1;
    if v is not null then NEW.brand:=v; end if;
  end if;
  -- size
  if NEW.size is null or btrim(NEW.size)='' then
    select target_value into v from public.tyre_learned_facts where active and target_field='size' and match_type='serial'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.serial_no))
      order by confidence desc, updated_at desc limit 1;
    if v is not null then NEW.size:=v; end if;
  else
    select target_value into v from public.tyre_learned_facts where active and target_field='size' and match_type='alias'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.size))
      order by updated_at desc limit 1;
    if v is not null then NEW.size:=v; end if;
  end if;
  -- removal_reason
  if NEW.removal_reason is null or btrim(NEW.removal_reason)='' then
    select target_value into v from public.tyre_learned_facts where active and target_field='removal_reason' and match_type='serial'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.serial_no))
      order by confidence desc, updated_at desc limit 1;
    if v is not null then NEW.removal_reason:=v; end if;
  else
    select target_value into v from public.tyre_learned_facts where active and target_field='removal_reason' and match_type='alias'
      and organisation_id=NEW.organisation_id and (country is null or lower(btrim(country))=lower(btrim(NEW.country))) and upper(btrim(match_value))=upper(btrim(NEW.removal_reason))
      order by updated_at desc limit 1;
    if v is not null then NEW.removal_reason:=v; end if;
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org  uuid := public.app_current_org();
  v_role text := lower(regexp_replace(COALESCE(public.get_my_role(), ''), '\s+', '_', 'g'));
  v_out  jsonb;
BEGIN
  IF v_role = '' THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  WITH scoped AS (
    SELECT wi.*,
           (wi.status IN ('pending','in_review','returned')
            AND (wi.steps -> wi.current_step) ? 'sla_hours'
            AND wi.step_started_at
                + make_interval(mins => round(
                    (wi.steps -> wi.current_step ->> 'sla_hours')::numeric * 60)::int)
                < now()) AS is_overdue
      FROM public.workflow_instances wi
     WHERE (wi.organisation_id IS NULL OR wi.organisation_id = v_org)
       AND public.approval_workflow_visible(wi.organisation_id,wi.entity_type,wi.context)
  ),
  proj AS (
    SELECT id, definition_id, definition_name, entity_type, entity_id, entity_label,
           status, current_step, approval_policy_id,
           coalesce(context->>'approval_matrix','false')='true' AS governed,
           context#>>'{content,country}' AS country, context#>>'{content,site}' AS site,
           (steps -> current_step ->> 'name')         AS current_step_name,
           (steps -> current_step ->> 'approver_role') AS current_approver_role,
           (steps -> current_step ->> 'sla_hours')     AS current_sla_hours,
           step_started_at, started_at, completed_at, is_overdue
      FROM scoped
  ),
  metrics AS (
    SELECT
      count(*) FILTER (WHERE status IN ('pending','in_review'))         AS pending_count,
      count(*) FILTER (WHERE is_overdue)                                AS overdue_count,
      count(*) FILTER (WHERE status = 'returned')                       AS returned_count,
      count(*) FILTER (WHERE status = 'rejected')                       AS rejected_count,
      count(*) FILTER (WHERE status = 'approved')                       AS approved_count,
      count(*) FILTER (WHERE status = 'cancelled')                      AS cancelled_count,
      count(*)                                                          AS total_count,
      round(avg(EXTRACT(EPOCH FROM (completed_at - started_at)) / 3600.0)
            FILTER (WHERE status = 'approved' AND completed_at IS NOT NULL)::numeric, 2)
                                                                        AS avg_approval_hours
    FROM proj
  )
  SELECT jsonb_build_object(
    'metrics', (SELECT to_jsonb(m) FROM metrics m),
    'buckets', jsonb_build_object(
      'pending', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.step_started_at ASC)
          FROM (SELECT * FROM proj WHERE status IN ('pending','in_review')
                 ORDER BY step_started_at ASC LIMIT 25) p), '[]'::jsonb),
      'overdue', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.step_started_at ASC)
          FROM (SELECT * FROM proj WHERE is_overdue
                 ORDER BY step_started_at ASC LIMIT 25) p), '[]'::jsonb),
      'returned', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.step_started_at DESC)
          FROM (SELECT * FROM proj WHERE status = 'returned'
                 ORDER BY step_started_at DESC LIMIT 25) p), '[]'::jsonb),
      'rejected', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.completed_at DESC)
          FROM (SELECT * FROM proj WHERE status = 'rejected'
                 ORDER BY completed_at DESC NULLS LAST LIMIT 25) p), '[]'::jsonb),
      'recently_approved', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.completed_at DESC)
          FROM (SELECT * FROM proj WHERE status = 'approved'
                 ORDER BY completed_at DESC NULLS LAST LIMIT 25) p), '[]'::jsonb)
    )
  ) INTO v_out;
  RETURN v_out;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_delegate_stage(p_entity_type text, p_entity_id uuid, p_expected_stage text, p_delegate_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; c jsonb; w workflow_instances; a approval_delegations;
BEGIN
 IF nullif(btrim(p_reason),'') IS NULL OR p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at<=p_starts_at OR p_ends_at<=now() OR p_ends_at-p_starts_at>interval '90 days' THEN
  RAISE EXCEPTION 'A reason and valid delegation period of at most 90 days are required' USING ERRCODE='22023'; END IF;
 d:=approval_private.document(p_entity_type,p_entity_id); c:=approval_private.context(p_entity_type,d);
 IF c->>'stage_token' IS DISTINCT FROM p_expected_stage THEN RAISE EXCEPTION 'Approval stage changed; reload before delegation' USING ERRCODE='PT409'; END IF;
 SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid FOR UPDATE;
 IF NOT FOUND OR NOT coalesce((c->>'can_decide')::boolean,false) OR c->>'represented_actor_id' IS DISTINCT FROM auth.uid()::text THEN
  RAISE EXCEPTION 'Only the directly assigned reviewer may delegate; delegation chains are not supported' USING ERRCODE='42501'; END IF;
 IF p_delegate_id IN (auth.uid(),w.started_by) OR NOT approval_private.person_eligible(p_delegate_id,w.organisation_id,w.entity_type,d->>'country',d->>'site')
 OR (coalesce((w.steps->w.current_step->>'distinct_reviewer')::boolean,true) AND EXISTS(SELECT 1 FROM workflow_step_events WHERE instance_id=w.id AND action='approved' AND (actor_id=p_delegate_id OR device_info->>'represented_actor_id'=p_delegate_id::text))) THEN
  RAISE EXCEPTION 'Delegate is not eligible for this stage' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM approval_delegations WHERE approval_workflow_id=w.id AND approval_stage_token=p_expected_stage AND active AND starts_at<p_ends_at AND ends_at>p_starts_at) THEN
  RAISE EXCEPTION 'An overlapping delegation already exists for this stage' USING ERRCODE='22023'; END IF;
 INSERT INTO approval_private.permits VALUES(txid_current(),p_entity_type,p_entity_id);
 INSERT INTO approval_delegations(organisation_id,delegator_id,delegate_id,entity_type,reason,starts_at,ends_at,active,created_by,approval_workflow_id,approval_stage_token)
 VALUES(w.organisation_id,auth.uid(),p_delegate_id,w.entity_type,p_reason,p_starts_at,p_ends_at,true,auth.uid(),w.id,p_expected_stage) RETURNING * INTO a;
 INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment,device_info)
 VALUES(w.id,w.organisation_id,w.current_step,w.steps->w.current_step->>'name','delegated',auth.uid(),p_reason,jsonb_build_object('delegation_id',a.id,'delegate_id',p_delegate_id,'starts_at',p_starts_at,'ends_at',p_ends_at));
 PERFORM approval_private.notify_stage(w.id,'delegated:'||a.id::text,p_delegate_id);
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=p_entity_type AND entity_id=p_entity_id;
 RETURN to_jsonb(a);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT auth.uid() IS NOT NULL AND app_current_org() IS NOT NULL AND coalesce(app_is_active(),false)
 AND (get_my_role()='Admin' OR is_super_admin())
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_people()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'full_name',coalesce(nullif(full_name,''),username),'role',role,
 'countries',coalesce(country,countries),'sites',coalesce(sites,ARRAY[site])) ORDER BY full_name,id)
 FROM profiles WHERE org_id=app_current_org() AND approved IS TRUE AND locked IS NOT TRUE),'[]'::jsonb);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_publish(p_policy_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_effective_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p approval_policies;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Publication reason is required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(app_current_org()::text,13));
 SELECT * INTO p FROM approval_policies WHERE id=p_policy_id AND organisation_id=app_current_org() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Policy unavailable' USING ERRCODE='42501'; END IF;
 IF p.state<>'draft' OR p_expected_updated_at IS NULL OR p.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Policy changed; reload before publishing' USING ERRCODE='PT409'; END IF;
 IF p.created_by=auth.uid() THEN RAISE EXCEPTION 'A different administrator must review and publish this policy' USING ERRCODE='42501'; END IF;
 p_effective_at:=coalesce(p_effective_at,clock_timestamp());
 IF p_effective_at<statement_timestamp()-interval '5 minutes' THEN RAISE EXCEPTION 'Effective time must be now or in the future' USING ERRCODE='22023'; END IF;
 PERFORM approval_private.validate_policy(p);
 IF EXISTS(SELECT 1 FROM approval_policies q WHERE q.organisation_id=p.organisation_id AND q.entity_type=p.entity_type AND q.state='published'
  AND q.priority=p.priority
  AND num_nonnulls(q.match_country,q.match_region,q.match_site,q.match_role,q.match_user_id)=num_nonnulls(p.match_country,p.match_region,p.match_site,p.match_role,p.match_user_id)
  AND (q.match_country IS NULL OR p.match_country IS NULL OR q.match_country=p.match_country)
  AND (q.match_region IS NULL OR p.match_region IS NULL OR q.match_region=p.match_region)
  AND (q.match_site IS NULL OR p.match_site IS NULL OR q.match_site=p.match_site)
  AND (q.match_role IS NULL OR p.match_role IS NULL OR q.match_role=p.match_role)
  AND (q.match_user_id IS NULL OR p.match_user_id IS NULL OR q.match_user_id=p.match_user_id)) THEN
  RAISE EXCEPTION 'Equally ranked published policies overlap; change priority or retire the conflicting policy' USING ERRCODE='22023'; END IF;
 UPDATE approval_policies SET state='published',version=(SELECT coalesce(max(version),0)+1 FROM approval_policies WHERE organisation_id=p.organisation_id AND entity_type=p.entity_type AND state<>'draft'),
 published_by=auth.uid(),published_at=clock_timestamp(),effective_at=p_effective_at,updated_at=clock_timestamp(),change_reason=btrim(p_reason) WHERE id=p.id RETURNING * INTO p;
 INSERT INTO approval_policy_events(policy_id,organisation_id,action,actor_id,reason,snapshot) VALUES(p.id,p.organisation_id,'published',auth.uid(),p_reason,to_jsonb(p));
 RETURN to_jsonb(p);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_retire(p_policy_id uuid, p_expected_updated_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p approval_policies;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Retirement reason is required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(app_current_org()::text,13));
 SELECT * INTO p FROM approval_policies WHERE id=p_policy_id AND organisation_id=app_current_org() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Policy unavailable' USING ERRCODE='42501'; END IF;
 IF p.state='retired' OR p_expected_updated_at IS NULL OR p.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Policy changed; reload before retiring' USING ERRCODE='PT409'; END IF;
 UPDATE approval_policies SET state='retired',updated_at=clock_timestamp(),change_reason=btrim(p_reason) WHERE id=p.id RETURNING * INTO p;
 INSERT INTO approval_policy_events(policy_id,organisation_id,action,actor_id,reason,snapshot) VALUES(p.id,p.organisation_id,'retired',auth.uid(),p_reason,to_jsonb(p));
 RETURN to_jsonb(p);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_save(p_policy jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p approval_policies; existing approval_policies;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_policy)<>'object' OR (p_policy-'id'-'name'-'entity_type'-'priority'-'match_country'-'match_region'-'match_site'-'match_role'-'match_user_id'-'stages'-'change_reason')<>'{}'::jsonb THEN
  RAISE EXCEPTION 'Unsupported policy field' USING ERRCODE='22023'; END IF;
 p:=jsonb_populate_record(NULL::approval_policies,p_policy);
 IF p.id IS NOT NULL THEN
  SELECT * INTO existing FROM approval_policies WHERE id=p.id AND organisation_id=app_current_org() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Policy unavailable' USING ERRCODE='42501'; END IF;
  IF existing.state<>'draft' THEN RAISE EXCEPTION 'Published policy is immutable; clone a new draft' USING ERRCODE='22023'; END IF;
  IF p_expected_updated_at IS NULL OR existing.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Policy changed; reload before saving' USING ERRCODE='PT409'; END IF;
 END IF;
 p.id:=coalesce(p.id,gen_random_uuid()); p.organisation_id:=app_current_org(); p.state:='draft'; p.version:=coalesce(existing.version,1);
 p.priority:=coalesce(p.priority,0); p.name:=btrim(p.name); p.match_country:=nullif(btrim(p.match_country),''); p.match_site:=nullif(btrim(p.match_site),'');
 p.match_region:=upper(nullif(btrim(p.match_region),''));
 -- A site policy always carries its own site's region so it outranks a regional policy.
 IF p.match_site IS NOT NULL THEN p.match_region:=approval_private.site_region(p.organisation_id,p.match_country,p.match_site); END IF;
 p.match_role:=nullif(btrim(p.match_role),''); p.created_by:=coalesce(existing.created_by,auth.uid()); p.created_at:=coalesce(existing.created_at,clock_timestamp()); p.updated_at:=clock_timestamp();
 PERFORM approval_private.validate_policy(p);
 INSERT INTO approval_policies SELECT p.* ON CONFLICT(id) DO UPDATE SET name=excluded.name,entity_type=excluded.entity_type,priority=excluded.priority,
 match_country=excluded.match_country,match_region=excluded.match_region,match_site=excluded.match_site,match_role=excluded.match_role,match_user_id=excluded.match_user_id,
 stages=excluded.stages,updated_at=excluded.updated_at,change_reason=excluded.change_reason;
 INSERT INTO approval_policy_events(policy_id,organisation_id,action,actor_id,reason,snapshot)
 VALUES(p.id,p.organisation_id,'draft_saved',auth.uid(),p.change_reason,to_jsonb(p));
 RETURN to_jsonb(p);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_policy_simulate(p_entity_type text, p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_draft_id uuid DEFAULT NULL::uuid, p_region text DEFAULT NULL::text, p_asset_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE place jsonb;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF p_entity_type NOT IN ('inspection','checklist','work_order','tyre_change') THEN RAISE EXCEPTION 'Unsupported approval module' USING ERRCODE='22023'; END IF;
 IF p_draft_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM approval_policies WHERE id=p_draft_id AND organisation_id=app_current_org() AND entity_type=p_entity_type AND state='draft') THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM profiles WHERE id=p_user_id AND org_id=app_current_org()) THEN RAISE EXCEPTION 'Submitting person unavailable' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_asset_no),'') IS NOT NULL THEN
  place:=approval_private.document_region(app_current_org(),p_country,p_asset_no,p_site);
  RETURN approval_private.resolve(app_current_org(),p_entity_type,p_country,p_site,p_role,p_user_id,p_draft_id,coalesce(place->>'region',p_region))
   || jsonb_build_object('region_basis',place->>'basis','vehicle_base_site',place->>'base_site');
 END IF;
 RETURN approval_private.resolve(app_current_org(),p_entity_type,p_country,p_site,p_role,p_user_id,p_draft_id,p_region);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_reassign_stage(p_entity_type text, p_entity_id uuid, p_expected_stage text, p_approver_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; c jsonb; w workflow_instances; old_stage jsonb; new_stage jsonb;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'A reassignment reason is required' USING ERRCODE='22023'; END IF;
 d:=approval_private.document(p_entity_type,p_entity_id); c:=approval_private.context(p_entity_type,d);
 IF c->>'stage_token' IS DISTINCT FROM p_expected_stage THEN RAISE EXCEPTION 'Approval stage changed; reload before reassignment' USING ERRCODE='PT409'; END IF;
 SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid FOR UPDATE;
 IF NOT FOUND OR w.status NOT IN ('pending','in_review') OR w.context->>'routing_status'<>'matched' THEN RAISE EXCEPTION 'Only a pending routed stage can be reassigned' USING ERRCODE='22023'; END IF;
 old_stage:=w.steps->w.current_step;
 IF p_approver_id=w.started_by OR NOT approval_private.person_eligible(p_approver_id,w.organisation_id,w.entity_type,d->>'country',d->>'site')
 OR (coalesce((old_stage->>'distinct_reviewer')::boolean,true) AND EXISTS(SELECT 1 FROM workflow_step_events WHERE instance_id=w.id AND action='approved' AND (actor_id=p_approver_id OR device_info->>'represented_actor_id'=p_approver_id::text))) THEN
  RAISE EXCEPTION 'Replacement reviewer is not eligible for this stage' USING ERRCODE='42501'; END IF;
 IF p_entity_type='checklist' AND d->>'approval_status'='pending_area_manager' AND NOT EXISTS(SELECT 1 FROM profiles WHERE id=p_approver_id AND (is_super_admin OR role=ANY(ARRAY['Admin','Director','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager']))) THEN
  RAISE EXCEPTION 'Final checklist review requires an area manager' USING ERRCODE='42501'; END IF;
 new_stage:=old_stage||jsonb_build_object('approver_user_id',p_approver_id,'approver_role',NULL,'assignee_type','user');
 INSERT INTO approval_private.permits VALUES(txid_current(),p_entity_type,p_entity_id);
 UPDATE workflow_instances SET steps=jsonb_set(steps,ARRAY[current_step::text],new_stage),approval_route_revision=approval_route_revision+1,last_actor_id=auth.uid() WHERE id=w.id;
 INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment,device_info)
 VALUES(w.id,w.organisation_id,w.current_step,old_stage->>'name','reassigned',auth.uid(),p_reason,jsonb_build_object('previous_assignment',old_stage,'new_assignment',new_stage));
 PERFORM approval_private.notify_stage(w.id,'reassigned');
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=p_entity_type AND entity_id=p_entity_id;
 RETURN approval_private.context(p_entity_type,d);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_recover_route(p_entity_type text, p_entity_id uuid, p_expected_stage text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; c jsonb; w workflow_instances; route jsonb; requestor_role text; previous jsonb; place jsonb;
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'A recovery reason is required' USING ERRCODE='22023'; END IF;
 d:=approval_private.document(p_entity_type,p_entity_id); c:=approval_private.context(p_entity_type,d);
 IF c->>'stage_token' IS DISTINCT FROM p_expected_stage THEN RAISE EXCEPTION 'Approval stage changed; reload before recovery' USING ERRCODE='PT409'; END IF;
 SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid FOR UPDATE;
 IF NOT FOUND OR w.status<>'pending' OR w.current_step<>0 OR w.context->>'routing_status'='matched'
 OR EXISTS(SELECT 1 FROM workflow_step_events WHERE instance_id=w.id AND action IN ('approved','rejected')) THEN
  RAISE EXCEPTION 'Only unresolved routing exceptions can be recovered' USING ERRCODE='22023'; END IF;
 SELECT role INTO requestor_role FROM profiles WHERE id=w.started_by AND org_id=w.organisation_id;
 place:=approval_private.document_region(w.organisation_id,d->>'country',d->>'asset_no',d->>'site');
 route:=approval_private.resolve(w.organisation_id,w.entity_type,d->>'country',d->>'site',requestor_role,w.started_by,NULL,place->>'region');
 IF route->>'status'<>'matched' THEN RAISE EXCEPTION 'Publish a single matching policy before recovering this request' USING ERRCODE='22023'; END IF;
 previous:=w.context;
 INSERT INTO approval_private.permits VALUES(txid_current(),p_entity_type,p_entity_id);
 UPDATE workflow_instances SET approval_policy_id=(route#>>'{policy,id}')::uuid,
  steps=(SELECT jsonb_agg(s||jsonb_build_object('assignee_type',CASE WHEN nullif(s->>'approver_user_id','') IS NOT NULL THEN 'user' ELSE 'role' END)) FROM jsonb_array_elements(route#>'{policy,stages}') s),
  context=context||jsonb_build_object('policy',route->'policy','routing_status','matched','region',place->>'region','region_basis',place->>'basis','vehicle_base_site',place->>'base_site'),
  approval_route_revision=approval_route_revision+1,last_actor_id=auth.uid(),step_started_at=clock_timestamp() WHERE id=w.id;
 INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment,device_info)
 VALUES(w.id,w.organisation_id,0,'Routing recovery','route_recovered',auth.uid(),p_reason,jsonb_build_object('previous_routing',previous->>'routing_status','policy',route->'policy'));
 PERFORM approval_private.notify_stage(w.id,'recovered');
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=p_entity_type AND entity_id=p_entity_id;
 RETURN approval_private.context(p_entity_type,d);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_region_coverage(p_entity_type text DEFAULT 'inspection'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid:=app_current_org();
BEGIN
 IF NOT coalesce(approval_policy_is_admin(),false) THEN RAISE EXCEPTION 'Approval configuration access denied' USING ERRCODE='42501'; END IF;
 RETURN (WITH f AS (
   SELECT f.country, f.site, approval_private.site_region(v_org,f.country,f.site) AS region
   FROM vehicle_fleet f WHERE f.organisation_id=v_org AND coalesce(f.status,'Active')='Active')
  SELECT jsonb_build_object(
   'regions', coalesce((SELECT jsonb_agg(x ORDER BY x->>'country', x->>'region') FROM (
     SELECT jsonb_build_object('country',country,'region',coalesce(region,''),'vehicles',count(*),
       'sites',(SELECT jsonb_agg(DISTINCT s.site) FROM f s WHERE s.country=f.country AND s.region IS NOT DISTINCT FROM f.region),
       'route',approval_private.resolve(v_org,p_entity_type,country,NULL,NULL,NULL,NULL,region)->'policy'->>'name',
       'route_status',approval_private.resolve(v_org,p_entity_type,country,NULL,NULL,NULL,NULL,region)->>'status') x
     FROM f GROUP BY country, region) q),'[]'::jsonb),
   'unmapped_sites', coalesce((SELECT jsonb_agg(jsonb_build_object('country',country,'site',site,'vehicles',n) ORDER BY n DESC)
     FROM (SELECT country, site, count(*) n FROM f WHERE region IS NULL AND country IN (SELECT DISTINCT country FROM f WHERE region IS NOT NULL) GROUP BY 1,2) u),'[]'::jsonb)));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_review_context(p_entity_type text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN RETURN approval_private.context(p_entity_type,approval_private.document(p_entity_type,p_entity_id)); END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_review_people(p_entity_type text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; c jsonb; w workflow_instances;
BEGIN
 d:=approval_private.document(p_entity_type,p_entity_id); c:=approval_private.context(p_entity_type,d);
 IF NOT coalesce(approval_policy_is_admin(),false) AND NOT coalesce((c->>'can_decide')::boolean,false) THEN RAISE EXCEPTION 'Reviewer lookup is unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'full_name',coalesce(nullif(u.full_name,''),u.username),'role',u.role,'countries',coalesce(u.country,u.countries),'sites',coalesce(u.sites,ARRAY[u.site])) ORDER BY u.full_name,u.id)
  FROM profiles u WHERE u.org_id=app_current_org() AND u.id IS DISTINCT FROM w.started_by
  AND approval_private.person_eligible(u.id,app_current_org(),p_entity_type,d->>'country',d->>'site')
  AND (p_entity_type<>'checklist' OR d->>'approval_status'<>'pending_area_manager' OR u.is_super_admin OR u.role=ANY(ARRAY['Admin','Director','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager']))
  AND (NOT coalesce((w.steps->w.current_step->>'distinct_reviewer')::boolean,true) OR NOT EXISTS(SELECT 1 FROM workflow_step_events e WHERE e.instance_id=w.id AND e.action='approved' AND (e.actor_id=u.id OR e.device_info->>'represented_actor_id'=u.id::text)))),'[]'::jsonb);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.approval_revoke_delegation(p_delegation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a approval_delegations; w workflow_instances; d jsonb;
BEGIN
 IF nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'A revocation reason is required' USING ERRCODE='22023'; END IF;
 SELECT * INTO a FROM approval_delegations WHERE id=p_delegation_id AND organisation_id=app_current_org();
 IF NOT FOUND OR a.approval_workflow_id IS NULL OR (a.delegator_id<>auth.uid() AND NOT coalesce(approval_policy_is_admin(),false)) THEN RAISE EXCEPTION 'Delegation unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO w FROM workflow_instances WHERE id=a.approval_workflow_id;
 d:=approval_private.document(w.entity_type,w.entity_id::uuid);
 PERFORM 1 FROM workflow_instances WHERE id=w.id FOR UPDATE;
 SELECT * INTO a FROM approval_delegations WHERE id=p_delegation_id FOR UPDATE;
 IF NOT a.active THEN RETURN to_jsonb(a); END IF;
 INSERT INTO approval_private.permits VALUES(txid_current(),w.entity_type,w.entity_id::uuid);
 UPDATE approval_delegations SET active=false,updated_at=clock_timestamp() WHERE id=a.id RETURNING * INTO a;
 INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment,device_info)
 VALUES(w.id,w.organisation_id,w.current_step,w.steps->w.current_step->>'name','delegation_revoked',auth.uid(),p_reason,jsonb_build_object('delegation_id',a.id));
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=w.entity_type AND entity_id=w.entity_id::uuid;
 RETURN to_jsonb(a);
END $function$;
-- @@
