 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT coalesce((SELECT approval_workflow_visible(organisation_id,entity_type,context) FROM workflow_instances WHERE id=p_instance),false)
$function$;
