CREATE OR REPLACE FUNCTION public.approval_workflow_visible(p_org uuid, p_type text, p_context jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT CASE WHEN coalesce(p_context->>'approval_matrix','false')<>'true' THEN true ELSE
  p_org=app_current_org() AND coalesce(app_is_active(),false)
  AND (p_context#>>'{content,country}' IS NULL OR is_super_admin() OR app_sees_all_countries()
   OR lower(btrim(p_context#>>'{content,country}'))=ANY(coalesce(app_country_scope(),'{}'::text[])))
  AND (nullif(btrim(p_context#>>'{content,site}'),'') IS NULL OR app_sees_all_sites()
   OR upper(btrim(p_context#>>'{content,site}'))=ANY(coalesce(app_site_scope(),'{}'::text[])))
  AND approval_private.caller_module_access(p_type)
 END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.approve_accident_closure(p_accident_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name      text;
  v_requester uuid;
  v_closure_status text;
BEGIN
  -- cap-guard:approve
  if public.app_cap_revoked('accidents','approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'Only Admin, Manager or Director can approve closures';
  END IF;

  -- V570: tenant wall. Refuses a case outside the caller's org/country/site.
  PERFORM public._accident_rpc_context(p_accident_id);

  SELECT COALESCE(full_name, username, 'Approver') INTO v_name FROM public.profiles WHERE id = auth.uid();
  -- Lock the current case state before deciding or creating audit/notifications.
  SELECT close_requested_by, closure_status
    INTO v_requester, v_closure_status
    FROM public.accidents
   WHERE id = p_accident_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Incident % not found.', p_accident_id USING ERRCODE = 'P0002';
  END IF;
  -- Recheck scope after waiting for any concurrent case update.
  PERFORM public._accident_rpc_context(p_accident_id);
  IF v_closure_status IS DISTINCT FROM 'pending_closure' THEN
    RAISE EXCEPTION 'Accident closure is no longer pending review.'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.accidents
     SET closure_status      = 'closed',
         status              = 'closed',
         closure_approved_by = auth.uid(),
         closure_approved_at = now()
   WHERE id = p_accident_id;

  INSERT INTO public.accident_remarks (accident_id, author_id, author_name, remark, remark_type)
  VALUES (p_accident_id, auth.uid(), v_name, 'Closure approved', 'closure_approved');

  IF v_requester IS NOT NULL AND v_requester <> auth.uid() THEN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    VALUES (v_requester, 'closure_approved', 'Closure approved',
            'Your accident closure was approved by ' || v_name || '.', 'accident', p_accident_id);
  END IF;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.approve_pending_upload(p_upload_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  batch public.pending_uploads%ROWTYPE;
  target text; allowed text[]; payload jsonb; row_data jsonb; cols text;
  imported integer := 0; row_country text; actor uuid := auth.uid(); org uuid := public.app_current_org();
BEGIN
  IF actor IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false)
     OR NOT coalesce(public.is_elevated_user(),false) THEN
    RAISE EXCEPTION 'Only active Admin, Manager or Director may approve uploads.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO batch FROM public.pending_uploads WHERE id=p_upload_id FOR UPDATE;
  IF NOT FOUND OR batch.organisation_id IS DISTINCT FROM org THEN
    RAISE EXCEPTION 'Upload not found or outside your organisation.' USING ERRCODE='42501';
  END IF;
  IF NOT coalesce(public.app_write_country_ok(batch.country),false) THEN
    RAISE EXCEPTION 'Upload country is outside your scope.' USING ERRCODE='42501';
  END IF;
  target := CASE lower(batch.upload_type) WHEN 'tyres' THEN 'tyre_records' WHEN 'stock' THEN 'stock_records' END;
  IF target IS NULL THEN RAISE EXCEPTION 'Unsupported upload type.' USING ERRCODE='22023'; END IF;
  IF batch.status='approved' AND batch.import_status='imported' THEN
    RETURN jsonb_build_object('ok',true,'imported',batch.imported_count,'target',target,'already_imported',true);
  END IF;
  IF batch.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'This upload already has a review decision.' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(batch.rows) IS DISTINCT FROM 'array' OR jsonb_array_length(batch.rows)=0 THEN
    RAISE EXCEPTION 'The upload must contain at least one data row.' USING ERRCODE='22023';
  END IF;
  allowed := CASE target WHEN 'tyre_records' THEN ARRAY[
    'sr','issue_date','description','brand','serial_no','qty','job_card','mis_number','asset_no','site',
    'remarks','remarks_cleaned','category','risk_level','source_sheet','source_file','region','cost_per_tyre',
    'km_at_fitment','km_at_removal','extra_fields','position','serial_number','pressure_reading','tread_depth',
    'size','driver_name','reason_for_removal','removal_date','tyre_serial','supplier','asset_number','findings',
    'removal_reason','driver_id','tyre_position','vehicle_type','hrs_at_fitment','hrs_at_removal','total_km','total_hrs','photos','status']
  ELSE ARRAY['site','description','stock_qty','min_level','critical_level','stock_status','reorder_qty','management_action','region','custom_data'] END;
  FOR row_data IN SELECT value FROM jsonb_array_elements(batch.rows) LOOP
    IF jsonb_typeof(row_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Each uploaded row must be an object.' USING ERRCODE='22023'; END IF;
    row_country := coalesce(nullif(btrim(row_data->>'country'),''),nullif(btrim(batch.country),''));
    IF row_country IS NULL OR NOT coalesce(public.app_write_country_ok(row_country),false) THEN
      RAISE EXCEPTION 'Each row requires a country within your scope.' USING ERRCODE='42501';
    END IF;
    IF nullif(btrim(row_data->>'site'),'') IS NOT NULL
       AND NOT coalesce(public.app_sees_all_sites(),false)
       AND NOT coalesce(upper(btrim(row_data->>'site'))=ANY(coalesce(public.app_site_scope(),'{}'::text[])),false) THEN
      RAISE EXCEPTION 'An uploaded site is outside your scope.' USING ERRCODE='42501';
    END IF;
    SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) INTO payload
      FROM jsonb_each(row_data) WHERE key=ANY(allowed);
    payload := payload || jsonb_build_object('organisation_id',org,'country',row_country);
    IF target='tyre_records' THEN
      payload := payload || jsonb_build_object('uploaded_by',batch.uploaded_by,'upload_batch_id',batch.batch_id,'data_source','upload');
    ELSE payload := payload || jsonb_build_object('updated_by',actor);
    END IF;
    -- Only supplied writable fields appear in INSERT. Defaults and generated
    -- columns belong to PostgreSQL, never to uploaded JSON.
    SELECT string_agg(quote_ident(c.column_name),', ' ORDER BY c.ordinal_position) INTO cols
    FROM information_schema.columns c
    WHERE c.table_schema='public' AND c.table_name=target AND c.is_generated='NEVER'
      AND c.identity_generation IS NULL AND payload ? c.column_name;
    EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(null::public.%I,$1)',target,cols,cols,target) USING payload;
    imported := imported+1;
  END LOOP;
  UPDATE public.pending_uploads SET status='approved',reviewed_by=actor,reviewed_at=now(),
    import_status='imported',imported_count=imported,imported_at=now(),import_error=NULL WHERE id=batch.id;
  RETURN jsonb_build_object('ok',true,'imported',imported,'target',target);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.asset_site_at(p_asset text, p_country text, p_date date)
 RETURNS TABLE(site text, provisional boolean, evidence text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with h as materialized (
    select v.site, v.confidence, v.evidence, v.valid_from, v.valid_to
    from public.v_asset_site_history v
    where v.asset_no = upper(btrim(p_asset)) and (p_country is null or v.country = p_country)
  )
  select x.site, x.provisional, x.evidence from (
    select h.site, h.confidence <> 'confirmed' as provisional, h.evidence, 1 as pri, h.valid_from
    from h
    where (h.valid_from is null or h.valid_from <= p_date) and (h.valid_to is null or p_date <= h.valid_to)
    union all
    select h.site, true, 'before_first_evidence', 2, h.valid_from
    from h where h.valid_from > p_date
  ) x
  order by x.pri, case when x.pri = 1 then x.valid_from end desc nulls last, x.valid_from
  limit 1
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.assign_user_issue(p_id uuid, p_assignee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v     public.user_issues%rowtype;
  v_uid uuid := auth.uid();
  v_ok  boolean;
begin
  v := public._user_issue_for_admin(p_id);
  if p_assignee_id is not null then
    select (coalesce(is_super_admin, false)
            or (role = 'Admin' and coalesce(org_id, organisation_id) = v.organisation_id))
           and not coalesce(locked, false)
      into v_ok from public.profiles where id = p_assignee_id;
    if not coalesce(v_ok, false) then
      raise exception 'Only an administrator of this company can own a problem' using errcode = '22023';
    end if;
  end if;
  if p_assignee_id is not distinct from v.assignee_id then
    return jsonb_build_object('ok', true, 'changed', false);
  end if;
  update public.user_issues set
    assignee_id = p_assignee_id,
    first_response_at = coalesce(first_response_at, now()),
    status = case when status = 'new' and p_assignee_id is not null then 'triaged' else status end,
    updated_at = now()
  where id = v.id;
  insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, from_value, to_value)
  values (v.id, v.organisation_id, v_uid, 'assign', v.assignee_id::text, p_assignee_id::text);
  if v.status = 'new' and p_assignee_id is not null then
    insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, from_value, to_value)
    values (v.id, v.organisation_id, v_uid, 'status', 'new', 'triaged');
  end if;
  return jsonb_build_object('ok', true, 'changed', true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.audit_import_batch_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' or old.approval_status is distinct from new.approval_status
     or old.import_status is distinct from new.import_status
     or old.imported_rows is distinct from new.imported_rows
     or old.skipped_rows is distinct from new.skipped_rows then
    insert into public.import_audit_events(organisation_id, batch_id, actor, action, detail)
    values (
      new.organisation_id, new.id, auth.uid(),
      case when tg_op = 'INSERT' then 'BATCH_CREATED' else 'BATCH_TRANSITION' end,
      jsonb_build_object(
        'before', case when tg_op = 'INSERT' then null else jsonb_build_object(
          'approval_status', old.approval_status, 'import_status', old.import_status,
          'imported_rows', old.imported_rows, 'skipped_rows', old.skipped_rows) end,
        'after', jsonb_build_object(
          'approval_status', new.approval_status, 'import_status', new.import_status,
          'imported_rows', new.imported_rows, 'skipped_rows', new.skipped_rows)
      )
    );
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.audit_stamp_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare h json;
begin
  begin
    if new.ip_address is null then
      new.ip_address := public._request_client_ip();
    end if;
    if new.user_agent is null then
      h := nullif(current_setting('request.headers', true), '')::json;
      if h is not null then
        new.user_agent := left(nullif(btrim(h->>'user-agent'), ''), 400);
      end if;
    end if;
  exception when others then
    null;
  end;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.audit_wash_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare k text;
begin
  foreach k in array array['site','area','asset_no','vehicle_type','wash_date','wash_time','wash_type',
    'bay','washed_by','water_liters','cost','duration_min','status','odometer_km','notes','wash_details'] loop
    if (to_jsonb(old)->k) is distinct from (to_jsonb(new)->k) then
      insert into public.wash_record_corrections(organisation_id,wash_id,field,old_value,new_value,reason,corrected_by)
      values(new.organisation_id,new.id,k,to_jsonb(old)->>k,to_jsonb(new)->>k,
        coalesce(nullif(current_setting('app.wash_correction_reason',true),''),'Record updated'),auth.uid());
    end if;
  end loop;
  return new;
end $function$;
