CREATE OR REPLACE FUNCTION public.backfill_tyre_prices_from_grid()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); n integer;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'not authorized'; END IF;
  WITH price AS (
    SELECT work_order_no, asset_code, round(avg(tyre_cost)) AS unit_price
    FROM public.parts_consumption
    WHERE organisation_id = v_org AND cost_category='tyre' AND tyre_cost > 0
    GROUP BY work_order_no, asset_code
  )
  UPDATE public.tyre_records t
     SET cost_per_tyre = p.unit_price
    FROM price p
   WHERE t.organisation_id = v_org
     AND t.job_card = p.work_order_no
     AND upper(t.asset_no) = upper(p.asset_code)
     AND (t.cost_per_tyre IS NULL OR t.cost_per_tyre = 0)
     AND p.unit_price > 0;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.backup_restore_missing(p_snapshot_id uuid, p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
DECLARE v_cols text; v_cols_b text; v_n int; v_status text;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT (p_table = ANY (backups._core_tables())) THEN RAISE EXCEPTION 'Unknown table'; END IF;
  PERFORM public._consume_approval('backup_restore_missing', jsonb_build_object('snapshot_id', p_snapshot_id, 'table', p_table));

  SELECT max(st.status) FILTER (WHERE st.status <> 'ok') INTO v_status
    FROM backups.snapshot_tables st
   WHERE st.snapshot_id = p_snapshot_id AND st.table_name = p_table;
  IF v_status = 'skipped_too_large' THEN
    RAISE EXCEPTION 'This table was not captured in that snapshot (too large for row snapshots) - use platform point-in-time recovery';
  END IF;

  -- Non-generated columns only (a GENERATED column cannot be inserted into).
  SELECT string_agg(quote_ident(column_name), ','),
         string_agg('b.' || quote_ident(column_name), ',')
    INTO v_cols, v_cols_b
    FROM information_schema.columns
   WHERE table_schema='public' AND table_name=p_table AND is_generated='NEVER';

  EXECUTE format(
    'INSERT INTO public.%I (%s)
     SELECT %s FROM backups.snapshot_tables st
       CROSS JOIN LATERAL jsonb_populate_recordset(null::public.%I, st.data) b
      WHERE st.snapshot_id = %L AND st.table_name = %L AND st.status = ''ok''
        AND NOT EXISTS (SELECT 1 FROM public.%I c WHERE c.id = b.id)
     ON CONFLICT (id) DO NOTHING',
    p_table, v_cols, v_cols_b, p_table, p_snapshot_id, p_table, p_table);

  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM public._console_audit('backup_restore_missing', p_snapshot_id, 'backup_snapshot',
    jsonb_build_object('table', p_table, 'restored', v_n));
  RETURN jsonb_build_object('table', p_table, 'restored', v_n);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.backup_restore_preview(p_snapshot_id uuid, p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
DECLARE v_taken timestamptz; v_snap_rows bigint; v_cur int; v_missing int; v_newer int;
        v_status text; v_note text; v_has_created boolean;
BEGIN
  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT (p_table = ANY (backups._core_tables())) THEN RAISE EXCEPTION 'Unknown table'; END IF;

  SELECT sn.taken_at INTO v_taken FROM backups.snapshots sn WHERE sn.id = p_snapshot_id;
  IF v_taken IS NULL THEN RAISE EXCEPTION 'Snapshot not found'; END IF;

  SELECT coalesce(sum(st.row_count) FILTER (WHERE st.status = 'ok'), 0),
         max(st.status) FILTER (WHERE st.status <> 'ok'),
         max(st.note)
    INTO v_snap_rows, v_status, v_note
    FROM backups.snapshot_tables st
   WHERE st.snapshot_id = p_snapshot_id AND st.table_name = p_table;

  EXECUTE format('SELECT count(*) FROM public.%I', p_table) INTO v_cur;

  -- rows present in the snapshot whose id is NOT present now (recoverable)
  EXECUTE format(
    'SELECT count(*) FROM backups.snapshot_tables st
       CROSS JOIN LATERAL jsonb_populate_recordset(null::public.%I, st.data) b
      WHERE st.snapshot_id = %L AND st.table_name = %L AND st.status = ''ok''
        AND NOT EXISTS (SELECT 1 FROM public.%I c WHERE c.id = b.id)',
    p_table, p_snapshot_id, p_table, p_table) INTO v_missing;

  -- informational: current rows created AFTER the snapshot are never touched.
  -- stock_records has no created_at, so this is guarded rather than assumed.
  SELECT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema='public' AND table_name=p_table AND column_name='created_at')
    INTO v_has_created;
  IF v_has_created THEN
    EXECUTE format('SELECT count(*) FROM public.%I WHERE created_at > %L', p_table, v_taken) INTO v_newer;
  ELSE
    v_newer := NULL;
  END IF;

  RETURN jsonb_build_object(
    'table', p_table, 'taken_at', v_taken, 'snapshot_rows', v_snap_rows,
    'current_rows', v_cur, 'missing_rows', v_missing, 'newer_current_rows', v_newer,
    'status', coalesce(v_status, 'ok'), 'note', v_note);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.begin_expense_import(p_request_id uuid, p_country text, p_replace boolean, p_rows integer, p_expected_count bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_batch administration_imports.expense_batches; v_count bigint;
BEGIN
 v_org := administration_imports.check_expense_actor(p_country);
 IF p_request_id IS NULL OR p_replace IS NULL OR p_rows IS NULL OR p_rows NOT BETWEEN 1 AND 300000 THEN
  RAISE EXCEPTION 'Invalid expense import request' USING ERRCODE='22023';
 END IF;
 IF p_replace AND NOT coalesce(public.app_can_admin_delete(),false) THEN
  RAISE EXCEPTION 'Only administrators may replace expense data' USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
 SELECT * INTO v_batch FROM administration_imports.expense_batches WHERE id=p_request_id;
 IF FOUND THEN
  IF v_batch.organisation_id<>v_org OR v_batch.actor<>auth.uid() OR v_batch.country<>p_country
    OR v_batch.replace_existing<>p_replace OR v_batch.expected_rows<>p_rows THEN
   RAISE EXCEPTION 'Import request identity conflicts; start a new import' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('ok',true,'result',v_batch.result);
 END IF;
 LOCK TABLE public.parts_consumption IN SHARE MODE;
 SELECT count(*) INTO v_count FROM public.parts_consumption WHERE organisation_id=v_org AND country=p_country;
 IF p_replace AND (p_expected_count IS NULL OR v_count<>p_expected_count) THEN
  RAISE EXCEPTION 'Stored expense data changed; refresh the count before replacing' USING ERRCODE='PT409';
 END IF;
 INSERT INTO administration_imports.expense_batches(id,organisation_id,actor,country,replace_existing,expected_rows,baseline)
 VALUES(p_request_id,v_org,auth.uid(),p_country,p_replace,p_rows,administration_imports.expense_baseline(v_org,p_country));
 RETURN jsonb_build_object('ok',true);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_classify(p_item_code text, p_description text, p_reviewed_category text DEFAULT NULL::text, p_on_tyre_jobcard boolean DEFAULT false)
 RETURNS TABLE(category text, bucket text, confidence numeric, decided_by text)
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
declare
  v_code_cat text;
  v_says_tyre boolean;
begin
  if p_reviewed_category is not null
     and p_reviewed_category in ('tyre','spare_part','filter','lubricant','fuel',
                                 'consumable','service','labour','capital','unclassified') then
    return query select p_reviewed_category,
                        public.material_category_bucket(p_reviewed_category),
                        1.00::numeric, 'reviewed-master';
    return;
  end if;

  v_code_cat := public.brain_code_category(p_item_code);

  -- coalesce: v_code_cat is NULL for most codes, and NULL = 'tyre' would make this
  -- whole guard NULL rather than false.
  if public.brain_has_any_word(p_description, public.brain_tokens('accessory')) then
    if not (coalesce(v_code_cat,'') = 'tyre'
            and public.brain_has_tyre_size(p_description)) then
      return query select 'spare_part', 'spare', 0.90::numeric, 'accessory';
      return;
    end if;
  end if;

  if public.brain_is_lubricant(p_description) then
    return query select 'lubricant', 'oil', 0.90::numeric, 'description-lubricant';
    return;
  end if;

  -- A named mechanical assembly beats the code range. No size escape hatch:
  -- the size belongs to whatever the part fits, not to a tyre.
  if public.brain_has_any_word(p_description, public.brain_tokens('non_tyre_part')) then
    return query select 'spare_part', 'spare', 0.92::numeric, 'non-tyre-part';
    return;
  end if;

  if v_code_cat is not null then
    return query select v_code_cat, public.material_category_bucket(v_code_cat),
                        0.95::numeric, 'code-range';
    return;
  end if;

  v_says_tyre := coalesce(p_description,'') ~* '\y(tyre|tire)\y';
  if v_says_tyre or (public.brain_has_any_word(p_description, public.brain_tokens('tyre_brand'))
                     and public.brain_has_tyre_size(p_description)) then
    return query select 'tyre', 'tyre', 0.85::numeric,
                        case when v_says_tyre then 'description-tyre' else 'brand-and-size' end;
    return;
  end if;

  if coalesce(p_on_tyre_jobcard, false) and public.brain_has_tyre_size(p_description) then
    return query select 'tyre', 'tyre', 0.70::numeric, 'job-card';
    return;
  end if;

  return query select 'spare_part', 'spare', 0.30::numeric, 'default';
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_classify_cached(p_org uuid, p_country text, p_item_code text, p_desc text, p_reviewed text, p_jobcard boolean)
 RETURNS TABLE(bucket text, decided_by text, confidence numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := upper(btrim(coalesce(p_item_code, '')));
  v_hash text := md5(upper(btrim(coalesce(p_desc, ''))));
  v_rev  text := coalesce(p_reviewed, '');
  v_jc   boolean := coalesce(p_jobcard, false);
  v_ver  int := public.brain_rules_version();
  v_caller uuid := public.app_current_org();
begin
  -- V555: p_org was inserted unchecked, so any authenticated caller could
  -- write a cache row into ANOTHER tenant. Reject an argument that
  -- contradicts the caller; permit it when there is no caller identity to
  -- contradict (service_role bulk import: auth.uid() and therefore
  -- app_current_org() are NULL). NOT a revoke - the non-definer trigger
  -- classify_parts_consumption needs the authenticated grant.
  if v_caller is not null and p_org is distinct from v_caller
     and not public.is_super_admin() then
    raise exception 'Cross-organisation classification denied.' using errcode = '42501';
  end if;
  select c.bucket, c.decided_by, c.confidence into bucket, decided_by, confidence
    from public.brain_cache c
   where c.organisation_id = p_org and c.country = p_country
     and c.item_code = v_code and c.desc_hash = v_hash
     and c.reviewed = v_rev and c.jobcard = v_jc and c.rules_version = v_ver;
  if found then return next; return; end if;

  select b.bucket, b.decided_by, b.confidence into bucket, decided_by, confidence
    from public.brain_classify(p_item_code, p_desc, nullif(v_rev, ''), v_jc) b;

  insert into public.brain_cache (organisation_id, country, item_code, desc_hash,
                                  reviewed, jobcard, rules_version,
                                  bucket, decided_by, confidence, item_desc)
  values (p_org, p_country, v_code, v_hash, v_rev, v_jc, v_ver,
          bucket, decided_by, confidence, left(coalesce(p_desc, ''), 300))
  on conflict do nothing;

  return next;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_code_category(p_code text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select case
    when upper(btrim(coalesce(p_code,''))) ~ '^310\d{3}'        then 'tyre'
    when upper(btrim(coalesce(p_code,''))) ~ '^TI-GE'           then 'tyre'
    when upper(btrim(coalesce(p_code,''))) ~ '^OL-'             then 'lubricant'
    when upper(btrim(coalesce(p_code,''))) ~ '^15[0-3]\d{3}'    then 'filter'
    when upper(btrim(coalesce(p_code,''))) ~ '^400\d{3}'        then 'spare_part'
    when upper(btrim(coalesce(p_code,''))) ~ '^4(3[0-4])\d{3}'  then 'spare_part'
    when upper(btrim(coalesce(p_code,''))) ~ '^330\d{3}'        then 'spare_part'
    when upper(btrim(coalesce(p_code,''))) ~ '^050\d{3}'        then 'spare_part'
    when upper(btrim(coalesce(p_code,''))) ~ '^030\d{3}'        then 'spare_part'
    when upper(btrim(coalesce(p_code,''))) ~ '^(200|420)\d{3}'  then 'spare_part'
    else null end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_has_any_word(p_text text, p_tokens text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from unnest(p_tokens) t where public.brain_has_word(p_text, t));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_has_tyre_size(p_text text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_text,'') ~* '\y\d{3}/\d{2,3}\s*[rz]?\s*\d{2}(\.\d)?\y'
      or coalesce(p_text,'') ~* '\y\d{2}\.\d{1,2}\s*[-r]\s*\d{2}\y'
      or coalesce(p_text,'') ~* '\y1[12]\.?0?0\s*[-r]\s*\d{2}(\.\d)?\y'
      or coalesce(p_text,'') ~* '\y\d{2}\s*[-r]\s*1[68]\.5\y'
      or coalesce(p_text,'') ~* '\y\d{1,2}\.\d{2}\s*r\s*\d{2}\y'
      or coalesce(p_text,'') ~* '\y\d{3}\s*r\s*\d{2}c?\y';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_has_word(p_text text, p_token text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_text, '') ~* ('(^|[^a-z0-9])' || regexp_replace(coalesce(p_token,''),
         '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '([^a-z0-9]|$)');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_is_lubricant(p_text text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select case
    when public.brain_has_any_word(p_text, public.brain_tokens('oil_part')) then false
    when public.brain_has_any_word(p_text, public.brain_tokens('lubricant')) then true
    -- real grade only: reject a run that continues into another dimension
    else coalesce(p_text,'') ~* '\y\d{1,2}\s?w\s?[-\s]?\s?\d{2,3}\y(?!\s*[*x]\s*\d)'
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_rules_version()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$ select 6 $function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_stopwords()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select array[
    'with','for','and','the','from','type','size','set','kit','new','used','item',
    'part','parts','assy','assembly','unit','pcs','each','high','low','left','right',
    'front','rear','upper','lower','inner','outer','small','large','main','sub',
    'model','series','grade','black','white','blue','green','red','yellow'
  ];
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.brain_tokens(p_kind text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select case p_kind
    when 'accessory' then array[
      'patch','patches','valve','glue','cement','fender','flap','inflat','gauge','soap',
      'chalk','rim','wheel nut','wheel bolt','wheel stud','wheel clamp','wheel set',
      'balanc','weight','spanner','remover','tool','paste','marker','protector','foam',
      'puncture','nozzle','welding machine','wheel barrow','kilomitter','spill',
      'inner tube','tube and flap','tube flap','spacer ring','spider hub','repair kit']
    when 'non_tyre_part' then array[
      'gear box','gearbox','transmission','steering pump','water pump',
      'hydraulic pump','radiator','alternator','starter motor','cylinder head',
      'oring','o ring','o-ring','rubber roll']
    when 'lubricant' then array[
      'engine oil','gear oil','hydraulic oil','compressor oil','transmission oil',
      'brake oil','brake fluid','atf','grease','lubricant','delvac','rimula','voyager',
      'gear fluid','hydraulic fluid',
      'gearbox oil','gear box oil','axle oil','differential oil','diff oil',
      'cooling oil','refrigerant oil',
      'coolant','cooliant','antifreeze','anti freeze','radiator fluid',
      'lubricating','adblue','ad blue','diesel exhaust fluid','def fluid']
    when 'oil_part' then array[
      'filter','seal','gasket','pump','cooler','line','hose','pipe','gauge','sensor',
      'switch','cap','tank','strainer','separator','baffle','injection',
      -- plurals: the matcher is whole-word by design, so these are not implied
      'filters','seals','gaskets','pumps','coolers','lines','hoses','pipes','gauges',
      'sensors','switches','caps','tanks','strainers','separators']
    when 'tyre_brand' then array[
      'roadx','longmarch','long march','rockholder','roadwest','mac royal','drive master',
      'drivemaster','cachland','taiho','v-glory','v glory','fortune','allround','tanova',
      'bossway','ecostar','transking','transtone','double star','wildpeak','priny',
      'roadking','firemax','montana','maxam','tracmax','trackmax','skyfire','sky fire',
      'infinity','tegrys','ericle','zeetex','prille','techking','blackhawk','doublecoin',
      'double coin','westlake','westlike','jinyu','triangle','advance','nison','century',
      'wellplus','formula','aosen','gold dove','superway','kunlun','fulda','rock buster',
      'diamond back','aget','allianz','firestone','bridgestone','michelin','goodyear',
      'dunlop','hankook','kumho','yokohama','pirelli','continental','apollo','mrf','ceat',
      'bkt','otani','annaite','sailun','windforce','joyroad','roadlux','chaoyang','mitas',
      'alliance','itr','tvs','linglong','aeolus']
    else array[]::text[] end;
$function$;
