CREATE OR REPLACE FUNCTION public.broadcast_audience(p_roles text[] DEFAULT '{}'::text[], p_countries text[] DEFAULT '{}'::text[], p_sites text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_out jsonb;
begin
  if not public.app_is_elevated() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;

  select jsonb_build_object(
    'ok', true,
    'total', count(*),
    'with_app', count(*) filter (where has_device),
    'by_role', coalesce((
      select jsonb_agg(jsonb_build_object('role', r.role, 'n', r.n) order by r.n desc, r.role)
        from (select role, count(*) n from (
                select p2.role,
                       p2.id
                  from public.profiles p2
                 where (p2.organisation_id = v_org or p2.org_id = v_org)
                   and coalesce(p2.approved, true) and not coalesce(p2.locked, false)
                   and (coalesce(array_length(p_roles, 1), 0) = 0 or p2.role = any (p_roles))
                   and (coalesce(array_length(p_countries, 1), 0) = 0
                        or p2.country is null or cardinality(p2.country) = 0
                        or p2.country && p_countries)
                   and (coalesce(array_length(p_sites, 1), 0) = 0
                        or p2.sites is null or cardinality(p2.sites) = 0
                        or p2.sites && (p_sites || array['ALL']))
              ) q group by role) r), '[]'::jsonb))
    into v_out
  from (
    select p.id,
           exists (select 1 from public.user_devices d
                    where d.user_id = p.id and not coalesce(d.revoked, false))
             or (p.push_token is not null and btrim(p.push_token) <> '') as has_device
      from public.profiles p
     where (p.organisation_id = v_org or p.org_id = v_org)
       and coalesce(p.approved, true) and not coalesce(p.locked, false)
       and (coalesce(array_length(p_roles, 1), 0) = 0 or p.role = any (p_roles))
       and (coalesce(array_length(p_countries, 1), 0) = 0
            or p.country is null or cardinality(p.country) = 0
            or p.country && p_countries)
       and (coalesce(array_length(p_sites, 1), 0) = 0
            or p.sites is null or cardinality(p.sites) = 0
            or p.sites && (p_sites || array['ALL']))
  ) t;

  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.broadcast_send(p_title text, p_body text, p_title_ar text DEFAULT NULL::text, p_body_ar text DEFAULT NULL::text, p_roles text[] DEFAULT '{}'::text[], p_countries text[] DEFAULT '{}'::text[], p_sites text[] DEFAULT '{}'::text[], p_send_push boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org        uuid := public.app_current_org();
  v_id         uuid;
  v_total      int := 0;
  v_push       int := 0;
  v_event_id   bigint;
  v_recipients jsonb;
  v_title      text := btrim(coalesce(p_title, ''));
  v_body       text := btrim(coalesce(p_body, ''));
  v_title_ar   text := nullif(btrim(coalesce(p_title_ar, '')), '');
  v_body_ar    text := nullif(btrim(coalesce(p_body_ar, '')), '');
  -- What someone whose language we do not know yet should read. Both, when
  -- both were written - never a guess, never a silent drop.
  v_title_both text;
  v_body_both  text;
  v_lang       text;
begin
  if not public.app_is_elevated() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if v_title = '' or v_body = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty');
  end if;

  v_title_both := v_title;
  v_body_both  := case when v_body_ar is null then v_body
                       else v_body || E'\n\n' || coalesce(v_title_ar || E'\n', '') || v_body_ar end;

  insert into public.broadcast_messages
    (organisation_id, title, body, title_ar, body_ar,
     target_roles, target_countries, target_sites, send_push, status)
  values
    (v_org, v_title, v_body, v_title_ar, v_body_ar,
     coalesce(p_roles, '{}'), coalesce(p_countries, '{}'), coalesce(p_sites, '{}'),
     coalesce(p_send_push, true), 'draft')
  returning id into v_id;

  -- Resolve the audience ONCE and reuse it for both channels, so the bell and
  -- the push can never disagree about who was told.
  drop table if exists _bc_aud;
  create temp table _bc_aud on commit drop as
  select p.id,
         -- 'ar' only when we know it AND an Arabic version exists; 'en' when we
         -- know they read English; 'both' when we simply do not know yet.
         case
           when v_title_ar is null then 'en'
           when lower(coalesce(p.language, '')) like 'ar%' then 'ar'
           when lower(coalesce(p.language, '')) like 'en%' then 'en'
           else 'both'
         end as lang,
         coalesce(
           (select d.push_token from public.user_devices d
             where d.user_id = p.id and not coalesce(d.revoked, false)
             order by d.last_seen_at desc nulls last limit 1),
           nullif(btrim(p.push_token), '')
         ) as token
    from public.profiles p
   where (p.organisation_id = v_org or p.org_id = v_org)
     and coalesce(p.approved, true) and not coalesce(p.locked, false)
     and (coalesce(array_length(p_roles, 1), 0) = 0 or p.role = any (p_roles))
     and (coalesce(array_length(p_countries, 1), 0) = 0
          or p.country is null or cardinality(p.country) = 0
          or p.country && p_countries)
     and (coalesce(array_length(p_sites, 1), 0) = 0
          or p.sites is null or cardinality(p.sites) = 0
          or p.sites && (p_sites || array['ALL']));

  select count(*) into v_total from _bc_aud;

  insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
  select a.id, 'broadcast',
         case a.lang when 'ar' then v_title_ar else v_title_both end,
         case a.lang when 'ar' then v_body_ar
                     when 'en' then v_body
                     else v_body_both end,
         'broadcast', v_id
    from _bc_aud a;

  if coalesce(p_send_push, true) then
    -- One queue row per language group, not per person: the edge function takes
    -- a recipient list plus one rendered message.
    for v_lang in select distinct lang from _bc_aud where token is not null
    loop
      select jsonb_agg(jsonb_build_object('user_id', a.id, 'push_token', t.tok))
        into v_recipients
        from _bc_aud a cross join lateral public._user_push_tokens(a.id) t(tok) where a.token is not null and a.lang = v_lang;
      continue when v_recipients is null;

      insert into public.domain_events
        (event_type, entity_type, entity_id, organisation_id, payload, status, processed_at)
      values ('broadcast.sent', 'broadcast', v_id::text, v_org,
              jsonb_build_object('broadcast_id', v_id, 'lang', v_lang), 'processed', now())
      returning id into v_event_id;

      insert into public.workflow_notifications
        (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
      values (v_event_id, v_org, null, 'broadcast.sent',
              jsonb_build_object(
                'event_type', 'broadcast.sent',
                'entity_type', 'broadcast',
                'entity_label', v_title,
                'entity_id', v_id,
                'push', jsonb_build_object(
                  'title', case v_lang when 'ar' then v_title_ar else v_title end,
                  'body',  case v_lang when 'ar' then v_body_ar
                                       when 'en' then v_body
                                       else v_body_both end),
                'recipients', v_recipients),
              jsonb_array_length(v_recipients), 'pending')
      on conflict (event_id) do nothing;

      v_push := v_push + jsonb_array_length(v_recipients);
    end loop;
  end if;

  update public.broadcast_messages
     set status = 'sent', recipient_count = v_total, push_count = v_push, sent_at = now()
   where id = v_id;

  return jsonb_build_object('ok', true, 'id', v_id,
                            'recipients', v_total, 'pushes_queued', v_push);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.calc_cpk(cost numeric, km_fit numeric, km_rem numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select case
    when km_fit  is not null
     and km_rem  is not null
     and km_rem  >  km_fit
     and cost    is not null
     and cost    >  0
    then round(cost::numeric / (km_rem - km_fit), 4)
    else null
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.cancel_elevation(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.jit_elevation_requests%rowtype;
begin
  select * into r from public.jit_elevation_requests where id = p_id for update;
  if not found then raise exception 'Request not found' using errcode = 'P0002'; end if;
  if r.requested_by is distinct from auth.uid() then
    raise exception 'Only the requester can cancel this request' using errcode = '42501';
  end if;
  if r.status <> 'pending' then return jsonb_build_object('ok', false, 'reason', 'not_pending', 'status', r.status); end if;
  update public.jit_elevation_requests set status = 'cancelled', updated_at = now() where id = p_id;
  perform public._jit_audit('jit_elevation_cancel', p_id, jsonb_build_object('status','pending'),
                            jsonb_build_object('status','cancelled'), null);
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'cancelled');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.capture_checklist_template_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_snapshot jsonb;
  v_existing jsonb;
begin
  if new.status <> 'published' then
    return new;
  end if;

  v_snapshot := public.checklist_template_snapshot(new);
  insert into public.checklist_template_revisions
    (organisation_id, template_id, version, snapshot, captured_by)
  values
    (new.organisation_id, new.id, new.version, v_snapshot, auth.uid())
  on conflict (organisation_id, template_id, version) do nothing;

  select r.snapshot into v_existing
  from public.checklist_template_revisions r
  where r.organisation_id = new.organisation_id
    and r.template_id = new.id
    and r.version = new.version;

  if v_existing is distinct from v_snapshot then
    raise exception 'Published checklist version % is immutable; save this as a new version', new.version
      using errcode = '22023';
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.capture_classification_feedback()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_machine record;
begin
  -- Only a human review decision, and only when it says something.
  if NEW.reviewed is not true or NEW.category is null then
    return NEW;
  end if;
  if TG_OP = 'UPDATE'
     and OLD.reviewed is true
     and OLD.category is not distinct from NEW.category then
    return NEW;                       -- nothing about the decision changed
  end if;
  if coalesce(NEW.proposed_from, '') like 'learned:%' then
    return NEW;                       -- the machine's own echo, not a human
  end if;

  select b.bucket, b.decided_by, b.confidence into v_machine
    from public.brain_classify(NEW.item_code, NEW.item_name, null, false) b;

  insert into public.classification_feedback
         (organisation_id, country, item_code, description,
          machine_said, machine_source, machine_conf, human_said, source)
  values (NEW.organisation_id, NEW.country, NEW.item_code, NEW.item_name,
          v_machine.bucket, v_machine.decided_by, v_machine.confidence,
          public.material_category_bucket(NEW.category), 'master_review');

  return NEW;
exception when others then
  -- Feedback is a measurement, never a gate. A failure here must not block a
  -- reviewer from recording their decision.
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.check_duplicate_serials(serials text[])
 RETURNS TABLE(serial_no text, existing_id uuid, existing_date date, existing_site text, existing_brand text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select t.serial_no, t.id, t.issue_date, t.site, t.brand
  from public.tyre_records t
  where t.serial_no = any(serials)
    and (t.organisation_id = public.app_current_org() or public.is_super_admin())
    and (t.country is null
         or (select public.is_super_admin())
         or (select public.app_sees_all_countries())
         or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  order by t.serial_no, t.issue_date desc
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.checklist_approval_age_monitor(p_country text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(template_id uuid, template_name text, country text, site text, approval_stage text, pending_count bigint, oldest_pending_at timestamp with time zone, oldest_age_hours numeric, average_age_hours numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with pending as (
    select
      s.template_id,
      coalesce(s.template_name, t.name, 'Unknown template') as template_name,
      s.country,
      coalesce(nullif(btrim(s.site), ''), 'Unassigned') as site,
      case s.approval_status
        when 'pending_area_manager' then 'area_manager'
        else 'supervisor'
      end as approval_stage,
      case s.approval_status
        when 'pending_area_manager' then coalesce(s.supervisor_at, s.submitted_at, s.created_at)
        else coalesce(s.submitted_at, s.created_at)
      end as pending_at
    from public.checklist_submissions s
    left join public.checklist_templates t on t.id = s.template_id
    where s.approval_status in ('pending', 'pending_area_manager')
      and (p_country is null or lower(s.country) = lower(p_country))
      and (p_template_id is null or s.template_id = p_template_id)
  )
  select
    p.template_id,
    p.template_name,
    p.country,
    p.site,
    p.approval_stage,
    count(*) as pending_count,
    min(p.pending_at) as oldest_pending_at,
    round(extract(epoch from (now() - min(p.pending_at))) / 3600.0, 1) as oldest_age_hours,
    round(avg(extract(epoch from (now() - p.pending_at))) / 3600.0, 1) as average_age_hours
  from pending p
  where p.pending_at is not null
  group by p.template_id, p.template_name, p.country, p.site, p.approval_stage
  order by oldest_age_hours desc, p.template_name, p.site;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.checklist_approval_sla_monitor(p_country text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(template_id uuid, template_name text, country text, site text, approval_stage text, pending_count bigint, oldest_pending_at timestamp with time zone, oldest_age_hours numeric, average_age_hours numeric, target_hours integer, breached_count bigint, oldest_breached boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with policy as (select public.get_checklist_governance_policy() v),
  pending as (
    select s.template_id, coalesce(s.template_name,t.name,'Unknown template') template_name,
      s.country, coalesce(nullif(btrim(s.site),''),'Unassigned') site,
      case when s.approval_status='pending_area_manager' then 'area_manager' else 'supervisor' end approval_stage,
      case when s.approval_status='pending_area_manager' then coalesce(s.supervisor_at,s.submitted_at,s.created_at)
           else coalesce(s.submitted_at,s.created_at) end pending_at,
      case when s.approval_status='pending_area_manager'
        then (policy.v->>'area_manager_approval_sla_hours')::integer
        else (policy.v->>'supervisor_approval_sla_hours')::integer end target_hours
    from public.checklist_submissions s
    left join public.checklist_templates t on t.id=s.template_id
    cross join policy
    where s.approval_status in ('pending','pending_area_manager')
      and (p_country is null or lower(s.country)=lower(p_country))
      and (p_template_id is null or s.template_id=p_template_id)
  )
  select p.template_id,p.template_name,p.country,p.site,p.approval_stage,count(*),min(p.pending_at),
    round(extract(epoch from (now()-min(p.pending_at)))/3600.0,1),
    round(avg(extract(epoch from (now()-p.pending_at)))/3600.0,1),max(p.target_hours),
    count(*) filter (where now() > p.pending_at + make_interval(hours=>p.target_hours)),
    now() > min(p.pending_at) + make_interval(hours=>max(p.target_hours))
  from pending p where p.pending_at is not null
  group by p.template_id,p.template_name,p.country,p.site,p.approval_stage
  order by 12 desc, 8 desc;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.checklist_compliance_monitor(p_from date, p_to date, p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(template_id uuid, template_name text, country text, site text, due_count bigint, completed_count bigint, completed_on_time_count bigint, completed_late_count bigint, pending_count bigint, overdue_count bigint, skipped_count bigint, unlinked_completion_count bigint, exact_evidence_count bigint, evidence_gap_count bigint, compliance_pct numeric, on_time_pct numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    a.template_id,
    coalesce(a.template_name, t.name, 'Unknown template') as template_name,
    a.country,
    coalesce(nullif(btrim(a.site), ''), 'Unassigned') as site,
    count(*) as due_count,
    count(*) filter (where a.status = 'completed') as completed_count,
    count(*) filter (where a.status = 'completed' and a.completed_at::date <= a.due_date) as completed_on_time_count,
    count(*) filter (where a.status = 'completed' and a.completed_at::date > a.due_date) as completed_late_count,
    count(*) filter (where a.status = 'pending' and a.due_date >= current_date) as pending_count,
    count(*) filter (where a.status = 'overdue' or (a.status = 'pending' and a.due_date < current_date)) as overdue_count,
    count(*) filter (where a.status = 'skipped') as skipped_count,
    count(*) filter (where a.status = 'completed' and a.submission_id is null) as unlinked_completion_count,
    count(*) filter (where a.status = 'completed' and s.template_snapshot_status = 'exact') as exact_evidence_count,
    count(*) filter (where a.status = 'completed' and (s.id is null or s.template_snapshot_status <> 'exact')) as evidence_gap_count,
    round(100.0 * count(*) filter (where a.status = 'completed') / nullif(count(*) filter (where a.status <> 'skipped'), 0), 1) as compliance_pct,
    round(100.0 * count(*) filter (where a.status = 'completed' and a.completed_at::date <= a.due_date) / nullif(count(*) filter (where a.status = 'completed'), 0), 1) as on_time_pct
  from public.checklist_assignments a
  left join public.checklist_templates t on t.id = a.template_id
  left join public.checklist_submissions s on s.id = a.submission_id
  where p_from is not null and p_to is not null and p_from <= p_to
    and a.due_date between p_from and p_to
    and (p_country is null or lower(a.country) = lower(p_country))
    and (p_site is null or lower(a.site) = lower(p_site))
    and (p_template_id is null or a.template_id = p_template_id)
  group by a.template_id, coalesce(a.template_name, t.name, 'Unknown template'), a.country,
           coalesce(nullif(btrim(a.site), ''), 'Unassigned')
  order by a.country nulls last, site, template_name;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.checklist_evidence_policy_monitor(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(evidence_policy_status text, submission_count bigint, exception_notes_missing bigint, exception_photos_missing bigint, completion_signatures_missing bigint, gps_missing bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select s.evidence_policy_status, count(*),
    coalesce(sum((s.evidence_policy_gaps->>'exception_notes_missing')::bigint),0),
    coalesce(sum((s.evidence_policy_gaps->>'exception_photos_missing')::bigint),0),
    count(*) filter (where s.evidence_policy_gaps ? 'completion_signature_missing'),
    count(*) filter (where s.evidence_policy_gaps ? 'gps_missing')
  from public.checklist_submissions s
  where (p_from is null or s.created_at >= p_from)
    and (p_to is null or s.created_at < p_to)
  group by s.evidence_policy_status
  order by s.evidence_policy_status;
$function$;
