CREATE OR REPLACE FUNCTION public.classify_parts_consumption()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_val   numeric := public._to_num(NEW.value_amount);
  v_tot   numeric := public._to_num(NEW.total_amount);
  v_sp    numeric := public._to_num(NEW.spare_parts_amount);
  v_ty    numeric := public._to_num(NEW.tyre_amount);
  v_oi    numeric := public._to_num(NEW.oil_amount);
  v_line  numeric;
  v_filled boolean := false;
  v_org   uuid := coalesce(NEW.organisation_id, public.app_current_org());
  v_reviewed text;
  v_jobcard  boolean := false;
  v_brain    record;
begin
  NEW.qty_n := public._to_num(NEW.qty);
  begin NEW.event_date := nullif(btrim(NEW.txn_date), '')::date;
  exception when others then NEW.event_date := NULL; end;

  -- amount basis unchanged: Values, then Total, then the largest split.
  v_line := coalesce(nullif(v_val, 0), nullif(v_tot, 0),
                     nullif(greatest(coalesce(v_sp, 0), coalesce(v_ty, 0), coalesce(v_oi, 0)), 0));
  -- V517 last resort: a machine estimate, only where the ERP sent nothing at all.
  if v_line is null and NEW.filled_cost is not null and NEW.filled_cost > 0 then
    v_line := NEW.filled_cost;
    v_filled := true;
  end if;
  v_line := coalesce(v_line, 0);

  NEW.brand := public.parts_brand(NEW.item_description);

  select m.category into v_reviewed
    from public.material_master m
   where m.organisation_id = v_org
     and m.country = NEW.country
     and m.item_code = upper(btrim(coalesce(NEW.item_code, '')))
     and m.reviewed
   limit 1;

  if coalesce(btrim(NEW.work_order_no), '') <> '' then
    select true into v_jobcard
      from public.tyre_records t
     where t.country = NEW.country
       and upper(btrim(t.job_card)) = upper(btrim(NEW.work_order_no))
     limit 1;
    v_jobcard := coalesce(v_jobcard, false);
  end if;

  select * into v_brain
    from public.brain_classify_cached(v_org, NEW.country, NEW.item_code,
                                      NEW.item_description, v_reviewed, v_jobcard);

  NEW.cost_category      := v_brain.bucket;
  NEW.classified_by      := v_brain.decided_by;
  NEW.classify_confidence:= v_brain.confidence;

  NEW.tyre_cost  := case when v_brain.bucket = 'tyre'  then v_line else 0 end;
  NEW.oil_cost   := case when v_brain.bucket = 'oil'   then v_line else 0 end;
  NEW.spare_cost := case when v_brain.bucket = 'spare' then v_line else 0 end;
  NEW.line_cost  := v_line;

  if NEW.currency is null then
    NEW.currency := public.currency_for_country(NEW.country);
  end if;
  if NEW.site is null and coalesce(btrim(NEW.store_code), '') <> '' then
    NEW.site := coalesce(
      (select m.site from public.store_site_map m
        where m.store_code = NEW.store_code
          and (m.country is null or m.country = NEW.country)
        limit 1),
      upper(btrim(NEW.store_code)));
  end if;
  -- a filled row already carries unit_cost 0, so "only when null" would never
  -- refresh it; recompute it whenever the estimate is what priced the line.
  if (NEW.unit_cost is null or v_filled) and NEW.qty_n is not null and NEW.qty_n > 0 then
    NEW.unit_cost := round(v_line / NEW.qty_n, 4);
  end if;
  if NEW.source_system is null then
    NEW.source_system := 'ERP grid import';
  end if;

  return NEW;
end $function$;
