CREATE OR REPLACE FUNCTION public.commit_expense_import(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_batch administration_imports.expense_batches; v_inserted bigint; v_total bigint; v_replaced bigint:=0; v_result jsonb;
BEGIN
 -- Also serializes legacy/direct writers while the replacement is checked and committed.
 -- Failures or statement timeout roll back deletion, inserts, archive, and receipt together.
 LOCK TABLE public.parts_consumption IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO v_batch FROM administration_imports.expense_batches WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Expense import not found' USING ERRCODE='42501'; END IF;
 IF administration_imports.check_expense_actor(v_batch.country)<>v_batch.organisation_id OR v_batch.actor<>auth.uid() THEN
  RAISE EXCEPTION 'Expense import access denied' USING ERRCODE='42501';
 END IF;
 IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
 IF v_batch.replace_existing AND NOT coalesce(public.app_can_admin_delete(),false) THEN
  RAISE EXCEPTION 'Only administrators may replace expense data' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(sum(jsonb_array_length(rows)),0) INTO v_total FROM administration_imports.expense_chunks WHERE batch_id=p_request_id;
 IF v_total<>v_batch.expected_rows THEN RAISE EXCEPTION 'Expense staging is incomplete' USING ERRCODE='22023'; END IF;
 IF v_batch.replace_existing THEN
  IF administration_imports.expense_baseline(v_batch.organisation_id,v_batch.country)<>v_batch.baseline THEN
   RAISE EXCEPTION 'Stored expense data changed during upload; start a new import' USING ERRCODE='PT409';
  END IF;
  INSERT INTO administration_imports.expense_archive
   SELECT p_request_id,p.id,to_jsonb(p) FROM public.parts_consumption p
   WHERE p.organisation_id=v_batch.organisation_id AND p.country=v_batch.country;
  DELETE FROM public.parts_consumption WHERE organisation_id=v_batch.organisation_id AND country=v_batch.country;
  GET DIAGNOSTICS v_replaced=ROW_COUNT;
 END IF;
 INSERT INTO public.parts_consumption(organisation_id,country,issue_number,work_order_no,txn_date,asset_code,asset_description,asset_type,store_code,cost_center,item_code,qty,item_description,value_amount,spare_parts_amount,tyre_amount,oil_amount,total_amount,source_row)
 SELECT v_batch.organisation_id,v_batch.country,r.issue_number,r.work_order_no,r.txn_date,r.asset_code,r.asset_description,r.asset_type,r.store_code,r.cost_center,r.item_code,r.qty,r.item_description,r.value_amount,r.spare_parts_amount,r.tyre_amount,r.oil_amount,r.total_amount,r.source_row
 FROM administration_imports.expense_chunks c
 CROSS JOIN LATERAL jsonb_to_recordset(c.rows) AS r(issue_number text,work_order_no text,txn_date text,asset_code text,asset_description text,asset_type text,store_code text,cost_center text,item_code text,qty text,item_description text,value_amount text,spare_parts_amount text,tyre_amount text,oil_amount text,total_amount text,source_row text)
 WHERE c.batch_id=p_request_id ORDER BY c.chunk_index;
 GET DIAGNOSTICS v_inserted=ROW_COUNT;
 -- Existing fingerprint trigger may intentionally skip exact duplicates; never call them inserted.
 v_result:=jsonb_build_object('ok',true,'inserted',v_inserted,'skipped',v_total-v_inserted,'failed',0,'replaced',v_replaced,'request_id',p_request_id);
 UPDATE administration_imports.expense_batches SET result=v_result WHERE id=p_request_id;
 RETURN v_result;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.complete_inspection_plans_on_done()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.status is distinct from 'Done' or NEW.inspection_date is null or NEW.asset_no is null then
    return null;
  end if;
  if TG_OP = 'UPDATE' and OLD.status is not distinct from 'Done'
     and OLD.inspection_date is not distinct from NEW.inspection_date
     and OLD.asset_no is not distinct from NEW.asset_no then
    return null;
  end if;
  begin
    update public.inspection_schedules p
       set status = 'Completed'
     where upper(btrim(p.asset_no)) = upper(btrim(NEW.asset_no))
       and p.organisation_id is not distinct from NEW.organisation_id
       and (p.country is null or NEW.country is null or p.country = NEW.country)
       and lower(coalesce(p.status, 'scheduled')) in ('scheduled', 'in progress', '')
       and NEW.inspection_date >= p.scheduled_date - public.inspection_plan_early_days()
       and not exists (
         select 1 from public.inspection_schedules q
         where q.id <> p.id
           and upper(btrim(q.asset_no)) = upper(btrim(p.asset_no))
           and q.organisation_id is not distinct from p.organisation_id
           and (q.country is null or p.country is null or q.country = p.country)
           and lower(coalesce(q.status, '')) not in ('cancelled', 'canceled')
           and q.scheduled_date > p.scheduled_date
           and q.scheduled_date <= NEW.inspection_date
       );
  exception when others then
    null;
  end;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_check_access()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ip inet := public._request_client_ip();
begin
  if not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  if not public._ip_allowlist_on() then
    return jsonb_build_object('allowed', true, 'enabled', false, 'reason', 'disabled', 'ip', host(v_ip));
  end if;
  if v_ip is null then
    return jsonb_build_object('allowed', false, 'enabled', true, 'reason', 'ip_unknown', 'ip', null);
  end if;
  if public._ip_covered(v_ip) then
    return jsonb_build_object('allowed', true, 'enabled', true, 'reason', 'matched', 'ip', host(v_ip));
  end if;
  return jsonb_build_object('allowed', false, 'enabled', true, 'reason', 'not_listed', 'ip', host(v_ip));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_cron_jobs()
 RETURNS TABLE(jobid bigint, jobname text, schedule text, active boolean, last_status text, last_end timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'cron', 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF to_regclass('cron.job') IS NULL THEN
    RETURN;
  END IF;
  IF to_regclass('cron.job_run_details') IS NULL THEN
    RETURN QUERY
      SELECT j.jobid, j.jobname::text, j.schedule::text, j.active,
             NULL::text, NULL::timestamptz
      FROM cron.job j
      ORDER BY j.jobname NULLS LAST, j.jobid;
    RETURN;
  END IF;
  RETURN QUERY
    SELECT j.jobid, j.jobname::text, j.schedule::text, j.active,
           r.status::text AS last_status, r.end_time AS last_end
    FROM cron.job j
    LEFT JOIN LATERAL (
      SELECT d.status, d.end_time
      FROM cron.job_run_details d
      WHERE d.jobid = j.jobid
      ORDER BY d.start_time DESC NULLS LAST, d.runid DESC
      LIMIT 1
    ) r ON true
    ORDER BY j.jobname NULLS LAST, j.jobid;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_flutter_device_versions()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the device install base' using errcode = '42501';
  end if;

  with d as (
    select *
      from public.user_devices
     where coalesce(push_token, '') not like 'ExponentPushToken%'
       and coalesce(push_token, '') not like 'ExpoPushToken%'
  )
  select jsonb_build_object(
    'ok', true,
    'total', (select count(*) from d),
    'active', (select count(*) from d where not coalesce(revoked, false)),
    'revoked', (select count(*) from d where coalesce(revoked, false)),
    'seen_7d', (select count(*) from d where not coalesce(revoked, false) and last_seen_at >= now() - interval '7 days'),
    'seen_30d', (select count(*) from d where not coalesce(revoked, false) and last_seen_at >= now() - interval '30 days'),
    'users', (select count(distinct user_id) from d where not coalesce(revoked, false)),
    'expo_active', (select count(*) from public.user_devices
                     where not coalesce(revoked, false)
                       and (push_token like 'ExponentPushToken%' or push_token like 'ExpoPushToken%')),
    'by_version', coalesce((
      select jsonb_agg(jsonb_build_object(
        'app_version', app_version, 'platform', platform, 'devices', n,
        'last_seen', last_seen, 'seen_30d', seen_30d
      ) order by n desc, app_version)
      from (
        select nullif(btrim(app_version), '') as app_version,
               nullif(btrim(lower(platform)), '') as platform,
               count(*) as n,
               max(last_seen_at) as last_seen,
               count(*) filter (where last_seen_at >= now() - interval '30 days') as seen_30d
          from d
         where not coalesce(revoked, false)
         group by 1, 2
      ) s
    ), '[]'::jsonb)
  ) into v;
  return v;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_forget_device(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.console_known_devices%rowtype;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  delete from public.console_known_devices where id = p_id returning * into v_row;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details, ip_address)
  values (auth.uid(), 'forget_console_device', v_row.admin_id, 'profile',
          jsonb_build_object('device_id', v_row.id, 'ip', host(v_row.ip), 'ua_label', v_row.ua_label),
          public._request_client_ip());
  return jsonb_build_object('ok', true);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_list_known_devices()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', d.id, 'admin_id', d.admin_id,
             'admin_name', coalesce(p.full_name, p.email, d.admin_id::text),
             'ip', host(d.ip), 'ip_source', d.ip_source, 'ua_label', d.ua_label,
             'first_seen', d.first_seen, 'last_seen', d.last_seen, 'login_count', d.login_count)
           order by d.last_seen desc)
      from public.console_known_devices d
      left join public.profiles p on p.id = d.admin_id), '[]'::jsonb);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_mobile_device_versions()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the device install base' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'ok', true,
    'total', (select count(*) from public.user_devices),
    'active', (select count(*) from public.user_devices where not coalesce(revoked, false)),
    'revoked', (select count(*) from public.user_devices where coalesce(revoked, false)),
    'seen_7d', (select count(*) from public.user_devices where not coalesce(revoked, false) and last_seen_at >= now() - interval '7 days'),
    'seen_30d', (select count(*) from public.user_devices where not coalesce(revoked, false) and last_seen_at >= now() - interval '30 days'),
    'users', (select count(distinct user_id) from public.user_devices where not coalesce(revoked, false)),
    'by_version', coalesce((
      select jsonb_agg(jsonb_build_object(
        'app_version', app_version, 'platform', platform, 'devices', n,
        'last_seen', last_seen, 'seen_30d', seen_30d
      ) order by n desc, app_version)
      from (
        select nullif(btrim(app_version), '') as app_version,
               nullif(btrim(lower(platform)), '') as platform,
               count(*) as n,
               max(last_seen_at) as last_seen,
               count(*) filter (where last_seen_at >= now() - interval '30 days') as seen_30d
        from public.user_devices
        where not coalesce(revoked, false)
        group by 1, 2
      ) s
    ), '[]'::jsonb)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.console_record_login_device(p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_ip      inet;
  v_src     text := 'header';
  v_ua      text;
  v_hash    text;
  v_any     boolean;
  v_new_ip  boolean := false;
  v_new_ua  boolean := false;
  v_id      uuid;
  v_who     text;
  v_title   text;
  v_body    text;
  v_alerted int := 0;
  h         json;
begin
  if v_uid is null or not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  v_ip := public._request_client_ip();
  if v_ip is null then
    begin
      v_ip := host(nullif(btrim(coalesce(p_ip, '')), '')::inet)::inet;
      v_src := case when v_ip is null then 'unknown' else 'client' end;
    exception when others then
      v_ip := null; v_src := 'unknown';
    end;
  end if;

  begin
    h := nullif(current_setting('request.headers', true), '')::json;
  exception when others then h := null;
  end;
  v_ua := nullif(btrim(coalesce(h->>'user-agent', '')), '');
  if v_ua is null then v_ua := nullif(btrim(coalesce(p_user_agent, '')), ''); end if;
  v_ua := left(coalesce(v_ua, 'unknown'), 512);
  v_hash := encode(sha256(convert_to(lower(v_ua), 'UTF8')), 'hex');

  select exists (select 1 from public.console_known_devices where admin_id = v_uid) into v_any;
  if v_any then
    v_new_ip := v_ip is not null
      and not exists (select 1 from public.console_known_devices where admin_id = v_uid and ip = v_ip);
    v_new_ua := not exists (select 1 from public.console_known_devices where admin_id = v_uid and ua_hash = v_hash);
  end if;

  insert into public.console_known_devices (admin_id, ip, ip_source, ua_hash, ua_label)
  values (v_uid, v_ip, v_src, v_hash, left(v_ua, 200))
  on conflict on constraint console_known_devices_uniq do update
    set last_seen = now(), login_count = public.console_known_devices.login_count + 1
  returning id into v_id;

  if v_new_ip or v_new_ua then
    select coalesce(full_name, email, v_uid::text) into v_who from public.profiles where id = v_uid;
    v_title := case
      when v_new_ip and v_new_ua then 'Console sign-in from a new device and IP address'
      when v_new_ip then 'Console sign-in from a new IP address'
      else 'Console sign-in from a new device' end;
    v_body := coalesce(v_who, 'Unknown') || ' signed in from '
      || coalesce(host(v_ip), 'an unknown IP') || ' at '
      || to_char(now() at time zone 'Asia/Riyadh', 'DD Mon YYYY HH24:MI') || ' (Riyadh). '
      || 'If this was not them, lock the account and sign it out everywhere.';
    begin
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      select p.id, 'security', v_title, v_body, 'console_known_device', v_id
        from public.profiles p
       where coalesce(p.is_super_admin, false) and not coalesce(p.locked, false);
      get diagnostics v_alerted = row_count;
      insert into public.system_logs (severity, source, module_id, message, user_id, detail)
      values ('warning', 'new_console_device', 'security_audit', v_title || ' by ' || coalesce(v_who, 'unknown'), v_uid,
              jsonb_build_object('ip', host(v_ip), 'ip_source', v_src, 'new_ip', v_new_ip,
                                 'new_device', v_new_ua, 'device_id', v_id, 'user_agent', left(v_ua, 200)));
      insert into public.console_sessions (admin_id, action, target_id, target_type, details, ip_address)
      values (v_uid, 'new_device_login', v_id, 'console_known_device',
              jsonb_build_object('new_ip', v_new_ip, 'new_device', v_new_ua, 'ip_source', v_src), v_ip);
    exception when others then
      null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'seeded', not v_any, 'new_ip', v_new_ip,
                            'new_device', v_new_ua, 'alerted', v_alerted, 'device_id', v_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.convert_repair_request_to_job_card(p_id uuid, p_work_order_no text DEFAULT NULL::text, p_work_type text DEFAULT NULL::text, p_target_completion timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.repair_requests%rowtype;
  v_org uuid := public.app_current_org();
  v_no text; v_id uuid; v_type text;
begin
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if not (public.app_is_elevated() or public.app_user_can('work_orders','create')) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  select * into r from public.repair_requests where id = p_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if r.organisation_id is distinct from v_org then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if r.country is not null and not coalesce(public.app_can_see_country(r.country), false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if r.status = 'converted' and r.work_order_no is not null then
    select w.id into v_id from public.work_orders w where w.work_order_no = r.work_order_no and w.organisation_id = v_org;
    return jsonb_build_object('ok', true, 'already_converted', true, 'work_order_no', r.work_order_no, 'work_order_id', v_id, 'rfr_no', r.rfr_no);
  end if;
  if r.status in ('rejected','cancelled') then
    return jsonb_build_object('ok', false, 'reason', 'not_convertible',
                              'message', 'This request was ' || r.status || ' and cannot become a job card.');
  end if;
  v_type := coalesce(nullif(btrim(coalesce(p_work_type,'')), ''), 'Repair');
  v_no := nullif(btrim(coalesce(p_work_order_no, '')), '');
  if v_no is not null then
    select w.id into v_id from public.work_orders w where w.work_order_no = v_no;
    if v_id is not null then
      if (select w.organisation_id from public.work_orders w where w.id = v_id) is distinct from v_org then
        return jsonb_build_object('ok', false, 'reason', 'forbidden', 'message', 'That job card number belongs to another organisation.');
      end if;
      update public.work_orders
         set rfr_no = coalesce(nullif(btrim(coalesce(rfr_no,'')), ''), r.rfr_no),
             custom_data = coalesce(custom_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
                'raised_by', r.reported_by_name,
                'raised_at', to_char(r.reported_at, 'YYYY-MM-DD HH24:MI'),
                'repair_request_id', r.id::text))
       where id = v_id;
    end if;
  end if;
  if v_id is null then
    v_no := coalesce(v_no, public.generate_work_order_no());
    insert into public.work_orders (
      work_order_no, organisation_id, country, site, asset_no, plate_no, asset_description,
      status, priority, work_type, description, odometer, rfr_no, opened_at, target_completion, created_by, custom_data
    ) values (
      v_no, v_org, r.country, r.site, r.asset_no, r.plate_no, r.asset_description,
      'New', coalesce(r.priority, 'Medium'), v_type, r.description, r.odometer,
      r.rfr_no, coalesce(r.reported_at, now()), p_target_completion, auth.uid(),
      jsonb_strip_nulls(jsonb_build_object(
        'raised_by', r.reported_by_name,
        'raised_at', to_char(r.reported_at, 'YYYY-MM-DD HH24:MI'),
        'repair_request_id', r.id::text))
    ) returning id into v_id;
  end if;
  update public.repair_requests
     set status = 'converted', work_order_no = v_no, converted_at = now(), converted_by = auth.uid()
   where id = r.id;
  return jsonb_build_object('ok', true, 'already_converted', false, 'work_order_no', v_no, 'work_order_id', v_id, 'rfr_no', r.rfr_no);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.correct_vehicle_meter_reading(p_kind text, p_id uuid, p_value numeric, p_reading_date date, p_reason text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE old_row jsonb; new_row jsonb; target_table text; value_column text;
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR
    NOT coalesce((public.vehicle_meter_permissions()->>'canCorrect')::boolean,false) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE='42501';
  END IF;
  IF p_kind NOT IN ('km','hours') OR p_kind IS NULL OR p_value IS NULL OR p_value < 0
    OR p_value::text IN ('NaN','Infinity','-Infinity') OR p_reading_date IS NULL
    OR p_reading_date > current_date + 1 OR length(btrim(coalesce(p_reason,''))) < 3 THEN
    RAISE EXCEPTION 'Invalid correction' USING ERRCODE='22023';
  END IF;
  target_table := CASE WHEN p_kind='km' THEN 'odometer_logs' ELSE 'engine_hours_logs' END;
  value_column := CASE WHEN p_kind='km' THEN 'odometer_km' ELSE 'engine_hours' END;
  EXECUTE format('SELECT to_jsonb(r) FROM public.%I r WHERE id=$1 AND organisation_id=public.app_current_org() FOR UPDATE',target_table)
    INTO old_row USING p_id;
  IF old_row IS NULL THEN RAISE EXCEPTION 'Reading unavailable' USING ERRCODE='42501'; END IF;
  IF coalesce((old_row->>'flagged')::boolean,false) AND
    NOT coalesce((public.vehicle_meter_permissions()->>'canReview')::boolean,false) THEN
    RAISE EXCEPTION 'Admin review required' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vehicle_fleet v
    WHERE v.organisation_id=public.app_current_org() AND v.asset_no=old_row->>'asset_no'
      AND v.country IS NOT DISTINCT FROM old_row->>'country') THEN
    RAISE EXCEPTION 'Vehicle unavailable' USING ERRCODE='42501';
  END IF;
  IF p_reading_date > (now() AT TIME ZONE CASE WHEN old_row->>'country'='UAE' THEN 'Asia/Dubai' WHEN old_row->>'country'='Egypt' THEN 'Africa/Cairo' ELSE 'Asia/Riyadh' END)::date THEN
    RAISE EXCEPTION 'Future reading date' USING ERRCODE='22023';
  END IF;
  IF (old_row->>'updated_at')::timestamptz IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Reading changed; refresh before correcting' USING ERRCODE='PT409';
  END IF;
  EXECUTE format('UPDATE public.%I r SET %I=$1,reading_date=$2,updated_at=clock_timestamp() WHERE id=$3 RETURNING to_jsonb(r)',target_table,value_column)
    INTO new_row USING p_value,p_reading_date,p_id;
  IF p_value < (old_row->>value_column)::numeric AND NOT coalesce((old_row->>'flagged')::boolean,false) THEN
    EXECUTE format('UPDATE public.%I r SET flagged=true,flagged_prev_reading=$2,flag_reason=$3,reviewed=false,reviewed_by=NULL,reviewed_at=NULL WHERE id=$1 RETURNING to_jsonb(r)',target_table)
      INTO new_row USING p_id,(old_row->>value_column)::numeric,'Corrected reading is lower than the original. Awaiting Admin review.';
  END IF;
  IF coalesce((new_row->>'flagged')::boolean,false) AND coalesce((public.vehicle_meter_permissions()->>'canReview')::boolean,false) THEN
    EXECUTE format('UPDATE public.%I r SET reviewed=true,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=$1 RETURNING to_jsonb(r)',target_table)
      INTO new_row USING p_id;
  END IF;
  INSERT INTO public.audit_log(table_name,record_id,action,old_data,new_data,changed_by,organisation_id,details)
    VALUES(target_table,p_id,'UPDATE',old_row,new_row,auth.uid(),public.app_current_org(),jsonb_build_object('channel','Web Manual','reason',left(btrim(p_reason),4000)));
  RETURN new_row;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.correct_wash_record(p_id uuid, p_patch jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare old_row public.wash_records; new_row public.wash_records; patch jsonb; k text; changes int := 0;
begin
  if auth.uid() is null or not public.app_is_elevated() then
    return jsonb_build_object('ok',false,'reason','forbidden');
  end if;
  select * into old_row from public.wash_records where id=p_id and organisation_id=public.app_current_org() for update;
  if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if;
  if nullif(btrim(p_reason),'') is null then raise exception 'A correction reason is required'; end if;
  select coalesce(jsonb_object_agg(key, case when value='""'::jsonb then 'null'::jsonb else value end),'{}'::jsonb)
    into patch from jsonb_each(p_patch) where key = any(array[
    'site','area','asset_no','vehicle_type','wash_date','wash_time','wash_type','bay','washed_by',
    'water_liters','cost','duration_min','status','odometer_km','notes','wash_details']);
  new_row := jsonb_populate_record(old_row,patch);
  perform set_config('app.wash_correction_reason',btrim(p_reason),true);
  update public.wash_records set site=new_row.site, area=new_row.area, asset_no=new_row.asset_no,
    vehicle_type=new_row.vehicle_type, wash_date=new_row.wash_date, wash_time=new_row.wash_time,
    wash_type=new_row.wash_type, bay=new_row.bay, washed_by=new_row.washed_by,
    water_liters=new_row.water_liters, cost=new_row.cost, duration_min=new_row.duration_min,
    status=new_row.status, odometer_km=new_row.odometer_km, notes=new_row.notes, wash_details=new_row.wash_details
    where id=p_id;
  if not found then return jsonb_build_object('ok',false,'reason','forbidden'); end if;
  for k in select jsonb_object_keys(patch) loop
    if (to_jsonb(old_row)->k) is distinct from (to_jsonb(new_row)->k) then
      changes := changes + 1;
    end if;
  end loop;
  perform set_config('app.wash_correction_reason','',true);
  return jsonb_build_object('ok',true,'changed',changes,'record',
    (select to_jsonb(w) from public.wash_records w where w.id=p_id));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.correction_case_open(p_title text, p_metric_id text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb, p_original_value text DEFAULT NULL::text, p_suspected_cause text DEFAULT NULL::text, p_severity text DEFAULT 'medium'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_id uuid; v_no text; v_seq int;
begin

  if public.app_write_country_ok(p_country) is false then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if v_org is null then raise exception 'no organisation context'; end if;
  if coalesce(btrim(p_title),'')='' then raise exception 'title required'; end if;
  select count(*)+1 into v_seq from public.correction_cases where organisation_id=v_org and created_at >= date_trunc('year', now());
  v_no := 'CC-' || to_char(now(),'YYYY') || '-' || lpad(v_seq::text,4,'0');
  insert into public.correction_cases(organisation_id,case_no,title,metric_id,country,dashboard_context,original_value,suspected_cause,severity,status)
  values (v_org,v_no,p_title,p_metric_id,p_country,coalesce(p_context,'{}'::jsonb),p_original_value,p_suspected_cause,
          case when p_severity in ('low','medium','high','critical') then p_severity else 'medium' end,'reported')
  returning id into v_id;
  insert into public.correction_case_events(organisation_id,case_id,event_type,to_status,note)
  values (v_org,v_id,'opened','reported',p_suspected_cause);
  return json_build_object('ok',true,'id',v_id,'case_no',v_no);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.correction_case_transition(p_id uuid, p_to_status text, p_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_from text;
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if p_to_status not in ('reported','investigating','proposed','approved','applied','reconciled','closed','rejected') then
    raise exception 'bad status %', p_to_status; end if;
  select status into v_from from public.correction_cases where id=p_id and organisation_id=v_org;
  if v_from is null then raise exception 'case not found'; end if;
  update public.correction_cases set status=p_to_status, updated_at=now(),
    closed_at = case when p_to_status in ('closed','rejected') then now() else closed_at end
   where id=p_id and organisation_id=v_org;
  insert into public.correction_case_events(organisation_id,case_id,event_type,from_status,to_status,note)
  values (v_org,p_id,'transition',v_from,p_to_status,p_note);
  return json_build_object('ok',true,'id',p_id,'from',v_from,'to',p_to_status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.correction_case_update(p_id uuid, p_patch jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if not exists (select 1 from public.correction_cases where id=p_id and organisation_id=v_org) then raise exception 'case not found'; end if;
  update public.correction_cases set
    owner_id            = coalesce((p_patch->>'owner_id')::uuid, owner_id),
    root_cause_category = coalesce(p_patch->>'root_cause_category', root_cause_category),
    suspected_cause     = coalesce(p_patch->>'suspected_cause', suspected_cause),
    proposed_action     = coalesce(p_patch->>'proposed_action', proposed_action),
    applied_action      = coalesce(p_patch->>'applied_action', applied_action),
    corrected_value     = coalesce(p_patch->>'corrected_value', corrected_value),
    severity            = coalesce(nullif(p_patch->>'severity',''), severity),
    contributing_records= coalesce(p_patch->'contributing_records', contributing_records),
    excluded_records    = coalesce(p_patch->'excluded_records', excluded_records),
    evidence            = coalesce(p_patch->'evidence', evidence),
    updated_at          = now()
   where id=p_id and organisation_id=v_org;
  insert into public.correction_case_events(organisation_id,case_id,event_type,note,detail)
  values (v_org,p_id,'updated',null,p_patch);
  return json_build_object('ok',true,'id',p_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cost_apply_actual_budgets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_uid uuid := auth.uid(); v_n int; v_total numeric;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF NOT public.app_is_org_admin() THEN RAISE EXCEPTION 'Admin only.' USING errcode='42501'; END IF;
  WITH per_asset AS (
    SELECT lower(btrim(asset_no)) AS a, t.country AS c,
           round(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) / greatest(count(distinct date_trunc('month', issue_date)),1)) AS mavg
    FROM tyre_records t
    WHERE btrim(coalesce(asset_no,''))<>'' AND issue_date IS NOT NULL
      AND (v_org IS NULL OR t.organisation_id = v_org)
    GROUP BY 1, 2
  ),
  upd AS (
    UPDATE vehicle_fleet f SET monthly_tyre_budget = p.mavg, updated_at = now()
    FROM per_asset p
    WHERE lower(btrim(f.asset_no)) = p.a AND f.country IS NOT DISTINCT FROM p.c
      AND (v_org IS NULL OR f.organisation_id = v_org)
      AND public.app_write_country_ok(f.country) IS NOT FALSE
    RETURNING p.mavg
  )
  SELECT count(*), coalesce(sum(mavg),0) INTO v_n, v_total FROM upd;
  INSERT INTO import_audit_events (organisation_id, actor, action, detail)
    VALUES (v_org, v_uid, 'budget_from_actuals', jsonb_build_object('vehicles',v_n,'total_monthly',v_total));
  RETURN jsonb_build_object('updated', v_n, 'total_monthly', v_total);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cost_budget_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with org as (select public.app_current_org() as o),
v as (select count(*) n, count(*) filter (where coalesce(monthly_tyre_budget,0)>0) with_b, coalesce(sum(monthly_tyre_budget),0) total_b
      from vehicle_fleet f, org where (org.o is null or f.organisation_id=org.o and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
s as (select coalesce(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)),0) spend,
             greatest(count(distinct date_trunc('month', issue_date)),1) months
      from tyre_records t, org where (org.o is null or t.organisation_id=org.o and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and issue_date is not null),
fr as (select cost_per_tyre as val, count(*) cnt,
              round(100.0*count(*)/nullif((select count(*) from tyre_records t2, org where (org.o is null or t2.organisation_id=org.o and (t2.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t2.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and cost_per_tyre is not null),0)) pct
       from tyre_records t, org
       where (org.o is null or t.organisation_id=org.o and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and cost_per_tyre is not null
       group by 1 order by cnt desc limit 1)
select jsonb_build_object(
  'vehicles',(select n from v), 'with_budget',(select with_b from v),
  'total_monthly_budget',(select total_b from v),
  'actual_avg_monthly_spend',(select round(spend/months) from s),
  'months_covered',(select months from s),
  'flat_rate', case when (select pct from fr) >= 90
    then jsonb_build_object('value',(select val from fr),'records',(select cnt from fr),'pct',(select pct from fr))
    else null end);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.cost_clear_value(p_value numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_uid uuid := auth.uid(); v_n int;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF NOT public.app_is_org_admin() THEN RAISE EXCEPTION 'Admin only.' USING errcode='42501'; END IF;
  IF p_value IS NULL THEN RAISE EXCEPTION 'Value required.'; END IF;
  UPDATE tyre_records t SET cost_per_tyre = NULL
  WHERE t.cost_per_tyre = p_value AND (v_org IS NULL OR t.organisation_id = v_org)
    AND public.app_write_country_ok(t.country) IS NOT FALSE;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  INSERT INTO import_audit_events (organisation_id, actor, action, detail)
    VALUES (v_org, v_uid, 'cost_clear_flat_rate', jsonb_build_object('value',p_value,'records',v_n));
  RETURN jsonb_build_object('cleared', v_n);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cost_convert_line_totals()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_uid uuid := auth.uid(); v_n int; v_total numeric;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF NOT public.app_is_org_admin() THEN RAISE EXCEPTION 'Admin only.' USING errcode='42501'; END IF;
  UPDATE tyre_records t
  SET cost_per_tyre = round(t.cost_per_tyre / t.qty, 2)
  WHERE t.cost_per_tyre IS NOT NULL AND coalesce(t.qty,1) > 1
    AND (v_org IS NULL OR t.organisation_id = v_org)
    AND public.app_write_country_ok(t.country) IS NOT FALSE;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  SELECT coalesce(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)),0) INTO v_total FROM tyre_records t
    WHERE (v_org IS NULL OR t.organisation_id = v_org)
      AND public.app_write_country_ok(t.country) IS NOT FALSE;
  INSERT INTO import_audit_events (organisation_id, actor, action, detail)
    VALUES (v_org, v_uid, 'cost_line_total_conversion', jsonb_build_object('rows_converted',v_n,'new_total_spend',v_total));
  RETURN jsonb_build_object('converted', v_n, 'total_spend', v_total);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cost_set_monthly_budget(p_scope text, p_value text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_uid uuid := auth.uid(); v_n int;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF NOT public.app_is_org_admin() THEN RAISE EXCEPTION 'Admin only.' USING errcode='42501'; END IF;
  IF p_amount IS NULL OR p_amount < 0 THEN RAISE EXCEPTION 'Amount must be >= 0.'; END IF;
  IF p_scope NOT IN ('all','country','site','asset') THEN RAISE EXCEPTION 'Scope must be all|country|site|asset.'; END IF;
  UPDATE vehicle_fleet f SET monthly_tyre_budget = p_amount, updated_at = now()
  WHERE (v_org IS NULL OR f.organisation_id = v_org)
    AND public.app_write_country_ok(f.country) IS NOT FALSE
    AND (p_scope='all'
      OR (p_scope='country' AND lower(btrim(coalesce(f.country,''))) = lower(btrim(coalesce(p_value,''))))
      OR (p_scope='site'    AND lower(btrim(coalesce(f.site,'')))    = lower(btrim(coalesce(p_value,''))))
      OR (p_scope='asset'   AND lower(btrim(f.asset_no))             = lower(btrim(coalesce(p_value,'')))));
  GET DIAGNOSTICS v_n = ROW_COUNT;
  INSERT INTO import_audit_events (organisation_id, actor, action, detail)
    VALUES (v_org, v_uid, 'budget_override', jsonb_build_object('scope',p_scope,'value',p_value,'amount',p_amount,'vehicles',v_n));
  RETURN jsonb_build_object('updated', v_n);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.count_profiles_with_push_token()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when not coalesce(public.app_is_active(), false) then null
    when public.is_super_admin() then
      (select count(*)::integer from public.profiles p
        where p.push_token is not null and p.push_token <> '')
    when coalesce(public.app_is_elevated(), false) then
      (select count(*)::integer from public.profiles p
        where p.push_token is not null and p.push_token <> ''
          and p.organisation_id = public.app_current_org())
    else null
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.count_records_with_extra_fields()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT COUNT(*) FROM tyre_records
  WHERE (tyre_records.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and extra_fields IS NOT NULL AND extra_fields <> '{}'::jsonb;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.cpk_unit_for_asset_type(p_type text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when lower(coalesce(p_type,'')) similar to
      '%(pump|water|treatment|concrete|batching|plaster|grout|slurry|generator|genset|gen set|compressor|excavator|loader|crane|forklift|dozer|grader|roller)%'
      then 'engine_hours'
    else 'km'
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.create_api_key(p_name text, p_scopes text[] DEFAULT ARRAY['read'::text], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_key text;
  v_id  uuid;
BEGIN
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  IF COALESCE(trim(p_name), '') = '' THEN
    RAISE EXCEPTION 'name is required';
  END IF;
  IF p_scopes IS NULL OR array_length(p_scopes, 1) IS NULL
     OR EXISTS (SELECT 1 FROM unnest(p_scopes) s WHERE s NOT IN ('read')) THEN
    RAISE EXCEPTION 'invalid scopes (supported: read)';
  END IF;
  v_key := 'tp_' || encode(gen_random_bytes(24), 'hex');
  INSERT INTO public.api_keys (organisation_id, name, key_prefix, key_hash, scopes, expires_at, created_by)
  VALUES (public.app_current_org(), trim(p_name), left(v_key, 10),
          encode(digest(v_key, 'sha256'), 'hex'), p_scopes, p_expires_at, auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'key', v_key, 'prefix', left(v_key, 10));
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.create_backup_snapshot(p_reason text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
DECLARE v_snap uuid; v_row backups.snapshots%ROWTYPE;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  v_snap := backups._do_snapshot(COALESCE(p_reason,'manual'), auth.uid());
  SELECT * INTO v_row FROM backups.snapshots WHERE id = v_snap;
  RETURN to_jsonb(v_row);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.create_display_token(p_name text, p_template jsonb DEFAULT '{"pages": ["overview"]}'::jsonb, p_refresh_seconds integer DEFAULT 60, p_rotate_seconds integer DEFAULT 15, p_password text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_token text;
  v_id    uuid;
BEGIN
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  IF COALESCE(trim(p_name), '') = '' THEN
    RAISE EXCEPTION 'name is required';
  END IF;

  v_token := 'disp_' || encode(gen_random_bytes(18), 'hex');

  INSERT INTO public.display_tokens
    (organisation_id, name, token, password_hash, template,
     refresh_seconds, rotate_seconds, expires_at, created_by)
  VALUES
    (public.app_current_org(), trim(p_name), v_token,
     CASE WHEN NULLIF(p_password, '') IS NULL THEN NULL
          ELSE crypt(p_password, gen_salt('bf')) END,
     COALESCE(p_template, '{"pages":["overview"]}'::jsonb),
     GREATEST(LEAST(COALESCE(p_refresh_seconds, 60), 3600), 10),
     GREATEST(LEAST(COALESCE(p_rotate_seconds, 15), 600), 5),
     p_expires_at, auth.uid())
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'token', v_token);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.create_report_share(p_name text, p_pages jsonb DEFAULT NULL::jsonb, p_rotate integer DEFAULT 30, p_refresh integer DEFAULT 300, p_password text DEFAULT NULL::text, p_expires timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_token text; v_id uuid; v_org uuid;
BEGIN
  IF NOT public.is_elevated_user() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  v_org := public.app_current_org();
  v_token := 'rpt_' || encode(gen_random_bytes(18), 'hex');
  INSERT INTO public.report_shares (organisation_id, name, token, password_hash, pages, rotate_seconds, refresh_seconds, expires_at)
  VALUES (
    v_org, coalesce(nullif(btrim(p_name), ''), 'Shared report'), v_token,
    CASE WHEN p_password IS NOT NULL AND btrim(p_password) <> '' THEN crypt(p_password, gen_salt('bf')) ELSE NULL END,
    coalesce(p_pages, '["board_kpis","board_trends","board_charts"]'::jsonb),
    greatest(5, least(600, coalesce(p_rotate, 30))),
    greatest(30, least(3600, coalesce(p_refresh, 300))),
    p_expires
  ) RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'token', v_token);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.create_workspace_owner(p_org_name text, p_kind text DEFAULT 'company'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_name      text := btrim(coalesce(p_org_name, ''));
  v_kind      text := lower(btrim(coalesce(p_kind, 'company')));
  v_role      text;
  v_super     boolean;
  v_approved  boolean;
  v_locked    boolean;
  v_owns      boolean;
  v_org_id    uuid;
  v_slug_base text;
  v_slug      text;
  v_email     text;
  v_now       timestamptz := now();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to create a workspace.' USING errcode = '28000';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'A workspace name is required.' USING errcode = '22023';
  END IF;
  IF length(v_name) > 120 THEN
    v_name := left(v_name, 120);
  END IF;

  IF v_kind NOT IN ('individual', 'company') THEN
    v_kind := 'company';
  END IF;

  SELECT role, coalesce(is_super_admin, false), coalesce(approved, false),
         coalesce(locked, false), email
    INTO v_role, v_super, v_approved, v_locked, v_email
    FROM public.profiles
   WHERE id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Your profile is not ready yet. Try again in a moment.'
      USING errcode = 'P0002';
  END IF;

  IF v_super THEN
    RAISE EXCEPTION 'Platform administrators cannot self-serve a workspace.'
      USING errcode = '42501';
  END IF;

  IF v_role = 'Admin' AND v_approved AND NOT v_locked THEN
    RAISE EXCEPTION 'You already own a workspace.' USING errcode = '42710';
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.organisation_memberships
     WHERE user_id = v_uid
       AND lower(coalesce(role, '')) = 'owner'
  ) INTO v_owns;

  IF v_owns THEN
    RAISE EXCEPTION 'You already own a workspace.' USING errcode = '42710';
  END IF;

  v_slug_base := regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g');
  v_slug_base := btrim(v_slug_base, '-');
  IF v_slug_base = '' THEN
    v_slug_base := 'workspace';
  END IF;
  v_slug_base := left(v_slug_base, 40);

  LOOP
    v_slug := v_slug_base || '-' ||
      substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
    BEGIN
      INSERT INTO public.organisations
        (name, slug, settings, plan, active, contact_email, primary_country,
         created_at, updated_at)
      VALUES
        (v_name,
         v_slug,
         jsonb_build_object(
           'kind', v_kind,
           'created_via', 'self_serve_onboarding'
         ),
         'trial',
         true,
         v_email,
         NULL,
         v_now,
         v_now)
      RETURNING id INTO v_org_id;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      NULL;
    END;
  END LOOP;

  INSERT INTO public.organisation_memberships
    (user_id, organisation_id, role)
  VALUES
    (v_uid, v_org_id, 'owner')
  ON CONFLICT (user_id, organisation_id) DO UPDATE SET role = 'owner';

  -- The existing guard blocks all non-super-admin organisation changes. As in
  -- V316, disable only that trigger around this single self-promotion. DDL and
  -- the data changes are transactional, so an exception restores the trigger.
  ALTER TABLE public.profiles DISABLE TRIGGER trg_guard_profile_privileged;

  UPDATE public.profiles
     SET org_id           = v_org_id,
         organisation_id  = v_org_id,
         role             = 'Admin',
         approved         = true,
         updated_at       = v_now
   WHERE id = v_uid;

  ALTER TABLE public.profiles ENABLE TRIGGER trg_guard_profile_privileged;

  INSERT INTO public.org_subscriptions
    (organisation_id, plan_code, status, billing_interval, seats,
     trial_ends_at, current_period_start, current_period_end)
  VALUES
    (v_org_id, 'trial', 'trialing', 'monthly', 1,
     v_now + interval '14 days', v_now, v_now + interval '14 days')
  ON CONFLICT (organisation_id) DO NOTHING;

  RETURN jsonb_build_object(
    'ok', true,
    'organisation_id', v_org_id,
    'slug', v_slug,
    'kind', v_kind,
    'plan_code', 'trial',
    'status', 'trialing'
  );
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_check_upload_gaps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org        uuid;
  v_cov        jsonb;
  a            jsonb;
  v_prev       date;
  v_sent       int := 0;
  v_checked    int := 0;
  v_pushed     int := 0;
  v_push_on    boolean;
  v_recipients jsonb;
  v_event_id   bigint;
  v_title      text;
  v_body       text;
begin
  v_push_on := coalesce(
    lower(btrim(coalesce((select replace(value, '"', '') from public.system_config
                           where key = 'upload_gap_push'), 'true'))) not in ('false','0','off','no'),
    true);

  for v_org in select distinct organisation_id from public.work_orders where organisation_id is not null
  loop
    v_checked := v_checked + 1;
    -- the same function the console panel reads, so the alert can never
    -- disagree with what the page shows
    v_cov := public._upload_coverage_for_org(v_org, 30, null);
    if v_cov is null or (v_cov->>'ok') is distinct from 'true' then continue; end if;

    for a in select * from jsonb_array_elements(coalesce(v_cov->'alerts', '[]'::jsonb))
    loop
      select last_data_date into v_prev
        from public.upload_gap_notices
       where organisation_id = v_org and src = a->>'src';

      -- already told them about this exact gap
      if v_prev is not distinct from (a->>'last_data_date')::date then continue; end if;

      v_title := (a->>'label') || ' has not been uploaded';
      v_body  := 'The last ' || lower(a->>'label') || ' data covers ' || (a->>'last_data_date')
                 || ', which is ' || (a->>'days_since_last')
                 || ' day(s) ago. Upload the missing file, or ignore this if there was genuinely no activity.';

      -- In-app bell, scoped to THIS organisation.
      begin
        insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
        select p.id, 'upload_gap', v_title, v_body, 'import', null
          from public.profiles p
         where p.role in ('Admin', 'Manager', 'Director')
           and coalesce(p.locked, false) = false
           and coalesce(p.approved, true)
           and (p.organisation_id = v_org or p.org_id = v_org);
      exception when others then null;
      end;

      -- Phone push for the same people who have a registered device.
      if v_push_on then
        begin
          select coalesce(jsonb_agg(jsonb_build_object(
                   'user_id', p.id, 'push_token', t.tok, 'role', p.role)), '[]'::jsonb)
            into v_recipients
            from public.profiles p
            cross join lateral public._user_push_tokens(p.id) t(tok)
           where p.role in ('Admin', 'Manager', 'Director')
             and coalesce(p.locked, false) = false
             and coalesce(p.approved, true)
             and (p.organisation_id = v_org or p.org_id = v_org);

          if jsonb_array_length(v_recipients) > 0 then
            insert into public.domain_events
              (event_type, entity_type, entity_id, organisation_id, payload, status, processed_at)
            values
              ('upload.gap_detected', 'import', a->>'src', v_org,
               jsonb_build_object('src', a->>'src', 'label', a->>'label',
                                  'last_data_date', a->>'last_data_date',
                                  'days_since_last', a->>'days_since_last'),
               -- marked processed: this function has already done the routing,
               -- there is no consumer registered for this event type.
               'processed', now())
            returning id into v_event_id;

            insert into public.workflow_notifications
              (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
            values
              (v_event_id, v_org, null, 'upload.gap_detected',
               jsonb_build_object(
                 'event_type', 'upload.gap_detected',
                 'entity_type', 'import',
                 'entity_label', a->>'label',
                 'push', jsonb_build_object('title', v_title, 'body', v_body),
                 'recipients', v_recipients),
               jsonb_array_length(v_recipients), 'pending')
            on conflict (event_id) do nothing;

            v_pushed := v_pushed + 1;
          end if;
        exception when others then null;  -- a push problem must never stop the bell
        end;
      end if;

      insert into public.upload_gap_notices (organisation_id, src, last_data_date, notified_at)
      values (v_org, a->>'src', (a->>'last_data_date')::date, now())
      on conflict (organisation_id, src) do update
        set last_data_date = excluded.last_data_date, notified_at = excluded.notified_at;

      v_sent := v_sent + 1;
    end loop;
  end loop;

  return jsonb_build_object('ok', true, 'orgs_checked', v_checked,
                            'notices_sent', v_sent, 'pushes_queued', v_pushed,
                            'push_enabled', v_push_on);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_check_user_issue_breaches()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_on       text;
  r          record;
  v_targets  uuid[];
  v_to_owner boolean;
  v_hours    int;
  v_issues   int := 0;
  v_notices  int := 0;
  v_title    text := 'A reported problem is past its target time';
  v_body     text;
begin
  select lower(btrim(coalesce(value, ''))) into v_on
    from public.system_config where key = 'user_issue_breach_alerts';
  if v_on in ('false', '"false"', '0', 'off', 'no') then
    return jsonb_build_object('ok', true, 'skipped', 'switched_off');
  end if;

  for r in
    select i.*
      from public.user_issues i
     where i.status in ('new', 'triaged', 'in_progress')
       and i.sla_due_at is not null
       and i.sla_due_at < now()
       and i.sla_breach_notified_at is null
     order by i.sla_due_at
     limit 500
     for update skip locked
  loop
    v_targets := null;
    v_to_owner := false;
    if r.assignee_id is not null then
      select array_agg(p.id) into v_targets
        from public.profiles p
       where p.id = r.assignee_id and not coalesce(p.locked, false);
      v_to_owner := v_targets is not null;
    end if;
    if v_targets is null then
      select array_agg(p.id) into v_targets
        from public.profiles p
       where coalesce(p.is_super_admin, false) and not coalesce(p.locked, false);
    end if;

    v_hours := greatest(0, floor(extract(epoch from (now() - r.sla_due_at)) / 3600)::int);
    v_body := initcap(r.severity) || ' problem reported on ' || coalesce(r.platform, 'web')
      || ' is ' || case when v_hours < 1 then 'less than 1 hour' else v_hours || ' hours' end
      || ' past its target time and is still ' || replace(r.status, '_', ' ') || '. '
      || left(regexp_replace(r.description, '\s+', ' ', 'g'), 140);

    if v_targets is not null then
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      select t, 'warning', v_title, v_body, 'user_issue', r.id from unnest(v_targets) t;
      v_notices := v_notices + coalesce(array_length(v_targets, 1), 0);
    end if;

    update public.user_issues set sla_breach_notified_at = now() where id = r.id;

    insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, to_value, note)
    values (r.id, r.organisation_id, null, 'sla_breach',
            case when v_targets is null then 'nobody'
                 when v_to_owner then 'owner' else 'super_admins' end,
            'Past its target time. '
              || case when v_targets is null then 'No one could be notified.'
                      when v_to_owner then 'The owner was notified.'
                      else 'Super admins were notified.' end);
    v_issues := v_issues + 1;
  end loop;

  return jsonb_build_object('ok', true, 'issues', v_issues, 'notifications', v_notices);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_health_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  v_h jsonb := public._cron_watch_state();
  v_pol jsonb := public._cron_policy();
  v_streak int := (v_pol ->> 'fail_streak')::int;
  v_recover int := (v_pol ->> 'recover_ok')::int;
  j jsonb;
  v_kind text;
  v_detail text;
  v_opened int := 0;
  v_closed int := 0;
  v_state record;
begin
  perform cron.unschedule(jobname)
     from cron.job
    where jobname like 'console-run-now-%'
      and to_timestamp(split_part(jobname, '-', 5)::bigint) < now() - interval '10 minutes';

  if not coalesce((v_pol ->> 'enabled')::boolean, true) or coalesce(v_h ->> 'ok', 'false') <> 'true' then
    return jsonb_build_object('ok', true, 'skipped', true);
  end if;

  for j in select * from jsonb_array_elements(v_h -> 'jobs') loop
    if not coalesce((j ->> 'active')::boolean, false) then continue; end if;
    v_kind := null;
    if coalesce((j ->> 'stuck')::boolean, false) then
      v_kind := 'stuck'; v_detail := 'Running longer than the stuck threshold.';
    elsif coalesce((j ->> 'fail_streak')::int, 0) >= v_streak then
      v_kind := 'failing'; v_detail := (j ->> 'fail_streak') || ' failures in a row.';
    elsif coalesce((j ->> 'overdue')::boolean, false) then
      v_kind := 'missed'; v_detail := 'Did not start within the grace period after its planned time.';
    end if;

    select * into v_state from public.cron_alert_state where jobid = (j ->> 'jobid')::bigint;

    if v_kind is not null then
      if v_state.jobid is null or not v_state.open then
        insert into public.cron_alert_state (jobid, jobname, kind, detail, open, opened_at, closed_at, ok_streak)
        values ((j ->> 'jobid')::bigint, j ->> 'jobname', v_kind, v_detail, true, now(), null, 0)
        on conflict (jobid) do update set jobname = excluded.jobname, kind = excluded.kind, detail = excluded.detail,
          open = true, opened_at = now(), closed_at = null, ok_streak = 0;
        v_opened := v_opened + 1;
        begin
          insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
          select p.id, 'system', 'Scheduled job needs attention: ' || (j ->> 'jobname'),
                 v_detail || ' Open Developer Center to see its runs.', 'cron_job', null
            from public.profiles p
           where coalesce(p.is_super_admin, false) and coalesce(p.approved, false) and not coalesce(p.locked, false);
        exception when others then null;
        end;
      else
        update public.cron_alert_state set ok_streak = 0, kind = v_kind, detail = v_detail where jobid = v_state.jobid;
      end if;
    elsif v_state.jobid is not null and v_state.open then
      if coalesce(j ->> 'last_status', '') = 'succeeded' then
        update public.cron_alert_state set ok_streak = ok_streak + 1 where jobid = v_state.jobid
          returning * into v_state;
        if v_state.ok_streak >= v_recover then
          update public.cron_alert_state set open = false, closed_at = now() where jobid = v_state.jobid;
          v_closed := v_closed + 1;
        end if;
      end if;
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'opened', v_opened, 'closed', v_closed);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_purge_audit_logs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_raw text;
  v_days int;
  v_cutoff timestamptz;
  v_a bigint := 0; v_s bigint := 0; v_c bigint := 0;
begin
  select value into v_raw from public.system_config where key = 'audit_retention_days';
  if v_raw is null then return; end if;
  begin v_days := trunc(v_raw::numeric)::int; exception when others then return; end;
  if v_days is null or v_days < 1 then return; end if;   -- 0 = keep forever

  v_cutoff := now() - make_interval(days => v_days);

  begin delete from public.audit_log_v2 where created_at < v_cutoff; get diagnostics v_a = row_count; exception when others then v_a := -1; end;
  begin delete from public.system_logs  where created_at < v_cutoff; get diagnostics v_s = row_count; exception when others then v_s := -1; end;
  begin delete from public.access_audit where at         < v_cutoff; get diagnostics v_c = row_count; exception when others then v_c := -1; end;

  begin
    insert into public.system_logs(severity, source, message, detail, created_at)
    values ('info', 'retention',
      'Audit log retention purge (keep '||v_days||' days)',
      jsonb_build_object('audit_log_v2', v_a, 'system_logs', v_s, 'access_audit', v_c, 'cutoff', v_cutoff),
      now());
  exception when others then null; end;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_purge_run_history(p_days integer DEFAULT 30, p_batch integer DEFAULT 50000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cut timestamptz := now() - make_interval(days => greatest(coalesce(p_days,30), 14)); v_n int;
begin
  with gone as (
    delete from cron.job_run_details
     where runid in (select runid from cron.job_run_details where start_time < v_cut order by runid limit p_batch)
    returning *)
  insert into _bak.cron_run_details_20261011 select * from gone;
  get diagnostics v_n = row_count;
  return jsonb_build_object('purged', v_n, 'before', v_cut);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_run_backup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
declare v_on text; v_snap uuid; v_bad int; v_skip int; v_rows bigint;
begin
  select value into v_on from public.system_config where key = 'backup_enabled';
  if v_on is not null and lower(btrim(v_on)) in ('false','0','off','no') then
    return;
  end if;

  begin
    v_snap := backups._do_snapshot('nightly', null);
    perform backups._purge(14);

    select count(*) filter (where status = 'error'),
           count(*) filter (where status = 'skipped_too_large'),
           coalesce(sum(row_count) filter (where status = 'ok'), 0)
      into v_bad, v_skip, v_rows
      from backups.snapshot_tables where snapshot_id = v_snap;

    if v_bad > 0 or v_skip > 0 then
      insert into public.system_logs (severity, source, message, detail)
      values ('warning', 'nightly-backup',
              format('Nightly snapshot completed with gaps: %s table(s) failed, %s skipped as too large, %s rows captured.', v_bad, v_skip, v_rows),
              jsonb_build_object('snapshot_id', v_snap, 'failed', v_bad, 'skipped', v_skip, 'rows', v_rows));
    else
      insert into public.system_logs (severity, source, message, detail)
      values ('info', 'nightly-backup',
              format('Nightly snapshot completed: %s rows captured.', v_rows),
              jsonb_build_object('snapshot_id', v_snap, 'rows', v_rows));
    end if;
  exception when others then
    -- A failed backup must never again be silent.
    insert into public.system_logs (severity, source, message, detail)
    values ('critical', 'nightly-backup',
            'Nightly backup FAILED - no snapshot was taken tonight.',
            jsonb_build_object('error', left(sqlerrm, 400), 'sqlstate', sqlstate));
    raise;
  end;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.cron_seal_audit(p_max_days integer DEFAULT 400)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_today date := (now() at time zone 'UTC')::date;
  v_src   text;
  v_start date;
  v_last  date;
  v_min   date;
  v_day   date;
  v_done  int := 0;
  v_out   jsonb := '{}'::jsonb;
  v_n     int;
begin
  foreach v_src in array array['audit_log_v2','access_audit','console_sessions'] loop
    v_n := 0;
    select max(day) into v_last from public.audit_seals where source = v_src;
    if v_last is null then
      if v_src = 'audit_log_v2' then
        select (min(created_at) at time zone 'UTC')::date into v_min from public.audit_log_v2;
      elsif v_src = 'access_audit' then
        select (min(at) at time zone 'UTC')::date into v_min from public.access_audit;
      else
        select (min(created_at) at time zone 'UTC')::date into v_min from public.console_sessions;
      end if;
      v_start := v_min;
    else
      v_start := v_last + 1;
    end if;
    if v_start is not null then
      v_day := v_start;
      while v_day < v_today and v_done < p_max_days loop
        perform public.seal_audit_day(v_src, v_day);
        v_day := v_day + 1; v_done := v_done + 1; v_n := v_n + 1;
      end loop;
    end if;
    v_out := v_out || jsonb_build_object(v_src, v_n);
  end loop;
  if v_done > 0 then
    begin
      insert into public.system_logs (module_id, severity, source, message, detail)
      values ('audit_integrity', 'info', 'cron_seal_audit', 'Audit days sealed', v_out);
    exception when others then null;
    end;
  end if;
  return v_out || jsonb_build_object('total', v_done);
end $function$;
