CREATE OR REPLACE FUNCTION public.data_completeness()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with org as (select public.app_current_org() as o),
t as (
  select count(*) n,
    count(*) filter (where btrim(coalesce(brand,''))<>'') as brand,
    count(*) filter (where btrim(coalesce(site,''))<>'') as site,
    count(*) filter (where btrim(coalesce(position,''))<>'' or btrim(coalesce(tyre_position,''))<>'') as position,
    count(*) filter (where coalesce(total_km,0)>0 or coalesce(km_at_fitment,0)>0 or coalesce(km_at_removal,0)>0) as km,
    count(*) filter (where cost_per_tyre is not null) as cost,
    count(*) filter (where coalesce(nullif(btrim(serial_no),''), nullif(btrim(serial_number),'')) is not null) as serial,
    count(*) filter (where removal_date is not null) as removal,
    count(*) filter (where btrim(coalesce(removal_reason,''))<>'' or btrim(coalesce(reason_for_removal,''))<>'') as removal_reason
  from tyre_records t, org where (org.o is null or t.organisation_id = org.o and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))
),
f as (
  select count(*) n,
    count(*) filter (where btrim(coalesce(vehicle_type,''))<>'') as vtype,
    count(*) filter (where btrim(coalesce(make,''))<>'') as make,
    count(*) filter (where btrim(coalesce(site,''))<>'') as site,
    count(*) filter (where coalesce(current_km,0)>0) as km,
    count(*) filter (where coalesce(monthly_tyre_budget,0)>0) as budget
  from vehicle_fleet v, org where (org.o is null or v.organisation_id = org.o and (v.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(v.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))
)
select jsonb_build_object(
  'tyres', jsonb_build_object('total',(select n from t),
    'brand',(select brand from t),'site',(select site from t),'position',(select position from t),
    'km',(select km from t),'cost',(select cost from t),'serial',(select serial from t),
    'removal',(select removal from t),'removal_reason',(select removal_reason from t)),
  'fleet', jsonb_build_object('total',(select n from f),
    'vehicle_type',(select vtype from f),'make',(select make from f),'site',(select site from f),
    'km',(select km from f),'budget',(select budget from f))
);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.data_link_audit()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with org as (select public.app_current_org() as o),
f as (select lower(btrim(asset_no)) as a from vehicle_fleet v, org where (org.o is null or v.organisation_id = org.o and (v.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(v.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and btrim(coalesce(asset_no,''))<>''),
t as (select count(*) total, count(*) filter (where btrim(coalesce(asset_no,''))<>'' and lower(btrim(asset_no)) not in (select a from f)) orphans, count(*) filter (where btrim(coalesce(asset_no,''))='') blank from tyre_records x, org where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
w as (select count(*) total, count(*) filter (where btrim(coalesce(asset_no,''))<>'' and lower(btrim(asset_no)) not in (select a from f)) orphans, count(*) filter (where btrim(coalesce(asset_no,''))='') blank from work_orders x, org where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
i as (select count(*) total, count(*) filter (where btrim(coalesce(asset_no,''))<>'' and lower(btrim(asset_no)) not in (select a from f)) orphans, count(*) filter (where btrim(coalesce(asset_no,''))='') blank from inspections x, org where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
c as (select count(*) total, count(*) filter (where btrim(coalesce(asset_no,''))<>'' and lower(btrim(asset_no)) not in (select a from f)) orphans, count(*) filter (where btrim(coalesce(asset_no,''))='') blank from corrective_actions x, org where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
a as (select count(*) total, count(*) filter (where btrim(coalesce(asset_no,''))<>'' and lower(btrim(asset_no)) not in (select a from f)) orphans, count(*) filter (where btrim(coalesce(asset_no,''))='') blank from accidents x, org where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))),
missing as (
  select coalesce(jsonb_agg(jsonb_build_object('asset_no', asset, 'records', cnt) order by cnt desc), '[]'::jsonb) as v
  from (
    select btrim(asset_no) as asset, count(*) as cnt
    from tyre_records x, org
    where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and btrim(coalesce(asset_no,''))<>''
      and lower(btrim(asset_no)) not in (select a from f)
    group by 1 order by cnt desc limit 25
  ) z
),
missing_total as (
  select count(distinct lower(btrim(asset_no))) as n
  from tyre_records x, org
  where (org.o is null or x.organisation_id = org.o and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) and btrim(coalesce(asset_no,''))<>''
    and lower(btrim(asset_no)) not in (select a from f)
)
select jsonb_build_object(
  'fleet_assets', (select count(*) from f),
  'tables', jsonb_build_object(
    'tyre_records',       jsonb_build_object('total',(select total from t),'orphans',(select orphans from t),'blank_asset',(select blank from t)),
    'work_orders',        jsonb_build_object('total',(select total from w),'orphans',(select orphans from w),'blank_asset',(select blank from w)),
    'inspections',        jsonb_build_object('total',(select total from i),'orphans',(select orphans from i),'blank_asset',(select blank from i)),
    'corrective_actions', jsonb_build_object('total',(select total from c),'orphans',(select orphans from c),'blank_asset',(select blank from c)),
    'accidents',          jsonb_build_object('total',(select total from a),'orphans',(select orphans from a),'blank_asset',(select blank from a))
  ),
  'missing_assets_count', (select n from missing_total),
  'missing_assets_top', (select v from missing)
);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.data_link_create_missing_assets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_uid uuid := auth.uid(); v_created int;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF NOT public.app_is_org_admin() THEN RAISE EXCEPTION 'Admin only.' USING errcode='42501'; END IF;
  WITH src AS (
    SELECT DISTINCT ON (lower(btrim(t.asset_no)))
      btrim(t.asset_no) AS asset_no, t.country, t.site, t.organisation_id
    FROM tyre_records t
    WHERE btrim(coalesce(t.asset_no,''))<>''
      AND (v_org IS NULL OR t.organisation_id = v_org)
      AND (t.country IS NULL
           OR (select public.is_super_admin())
           OR (select public.app_sees_all_countries())
           OR lower(btrim(t.country)) = ANY (coalesce((select public.app_country_scope()), '{}'::text[])))
      AND NOT EXISTS (SELECT 1 FROM vehicle_fleet v WHERE lower(btrim(v.asset_no)) = lower(btrim(t.asset_no)) AND (v_org IS NULL OR v.organisation_id = v_org))
    ORDER BY lower(btrim(t.asset_no)), t.issue_date DESC NULLS LAST
  ),
  ins AS (
    INSERT INTO vehicle_fleet (asset_no, country, site, organisation_id, is_active, status, notes, created_by)
    SELECT s.asset_no, s.country, s.site, coalesce(s.organisation_id, v_org), true, 'Active',
           'Auto-created from tyre data (Data Intake · linkage repair)', v_uid
    FROM src s
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_created FROM ins;
  INSERT INTO import_audit_events (organisation_id, actor, action, detail)
    VALUES (v_org, v_uid, 'link_repair', jsonb_build_object('created_assets', v_created));
  RETURN jsonb_build_object('created', v_created);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_approval(p_entity_type text, p_entity_id uuid, p_decision text, p_expected_revision bigint, p_expected_stage text, p_operation_id uuid, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text, p_client_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d jsonb; c jsonb; w workflow_instances; req jsonb; accepted jsonb; prev approval_private.decisions; final_stage boolean; domain_decision text; accepted_at timestamptz:=clock_timestamp();
BEGIN
 IF p_decision IS NULL OR p_decision NOT IN ('approved','rejected','returned') OR p_operation_id IS NULL OR p_expected_revision IS NULL OR p_expected_stage IS NULL THEN
  RAISE EXCEPTION 'Decision, reviewed revision, stage and operation ID are required' USING ERRCODE='22023'; END IF;
 d:=approval_private.document(p_entity_type,p_entity_id);
 req:=jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'decision',p_decision,'revision',p_expected_revision,'stage',p_expected_stage,'note',p_note,'signature',p_signature,'captured_at',p_client_captured_at);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_operation_id::text,37));
 SELECT * INTO prev FROM approval_private.decisions WHERE operation_id=p_operation_id;
 IF FOUND THEN
  IF prev.organisation_id<>app_current_org() OR prev.actor_id<>auth.uid() OR prev.request IS DISTINCT FROM req THEN RAISE EXCEPTION 'Operation ID was already used for a different decision' USING ERRCODE='22023'; END IF;
  RETURN prev.result;
 END IF;
 c:=approval_private.context(p_entity_type,d);
 IF (c->>'revision')::bigint<>p_expected_revision OR c->>'stage_token' IS DISTINCT FROM p_expected_stage THEN RAISE EXCEPTION 'Approval changed; review the current revision' USING ERRCODE='PT409'; END IF;
 IF NOT coalesce((c->>CASE WHEN p_decision='returned' THEN 'can_return' ELSE 'can_decide' END)::boolean,false) THEN RAISE EXCEPTION 'You are not eligible to decide this stage' USING ERRCODE='42501'; END IF;
 IF p_decision='approved' AND nullif(btrim(p_signature),'') IS NULL THEN RAISE EXCEPTION 'A signature is required' USING ERRCODE='22023'; END IF;
 IF p_decision IN ('rejected','returned') AND nullif(btrim(p_note),'') IS NULL THEN RAISE EXCEPTION 'A rejection or return reason is required' USING ERRCODE='22023'; END IF;
 domain_decision:=CASE WHEN p_decision='returned' THEN 'rejected' ELSE p_decision END;
 INSERT INTO approval_private.permits VALUES(txid_current(),p_entity_type,p_entity_id);
 IF d->>'approval_workflow_id' IS NOT NULL THEN
  SELECT * INTO w FROM workflow_instances WHERE id=(d->>'approval_workflow_id')::uuid FOR UPDATE;
  final_stage:=p_decision<>'approved' OR w.current_step+1>=jsonb_array_length(w.steps);
  IF final_stage THEN
   IF p_entity_type='inspection' THEN UPDATE inspections SET approval_outcome=p_decision WHERE id=p_entity_id;
   ELSIF p_entity_type='checklist' THEN UPDATE checklist_submissions SET approval_outcome=p_decision WHERE id=p_entity_id; ELSE UPDATE approval_execution_requests SET approval_outcome=p_decision WHERE id=p_entity_id; END IF;
  END IF;
  -- Preserve checklist domain stages: the first policy stage advances an area-manager template.
  IF NOT final_stage AND p_entity_type='checklist' AND d->>'approval_status'='pending' AND coalesce((d#>>'{checklist_templates,require_area_manager}')::boolean,false) THEN
   IF p_entity_type='checklist' THEN PERFORM decide_checklist_approval(p_entity_id,domain_decision,p_note,p_signature); ELSE PERFORM approval_private.execution_decide(p_entity_type,p_entity_id,domain_decision,p_note,p_signature); END IF;
  END IF;
  IF final_stage THEN
   IF p_entity_type='inspection' THEN PERFORM decide_inspection_approval(p_entity_id,domain_decision,p_note,p_signature);
   ELSE
    IF p_decision='approved' AND d->>'approval_status'='pending' AND coalesce((d#>>'{checklist_templates,require_area_manager}')::boolean,false) THEN
     RAISE EXCEPTION 'This checklist requires a separate supervisor and area-manager stage' USING ERRCODE='22023'; END IF;
    IF p_entity_type='checklist' THEN PERFORM decide_checklist_approval(p_entity_id,domain_decision,p_note,p_signature); ELSE PERFORM approval_private.execution_decide(p_entity_type,p_entity_id,domain_decision,p_note,p_signature); END IF;
   END IF;
  END IF;
  INSERT INTO workflow_step_events(instance_id,organisation_id,step_index,step_name,action,actor_id,comment,signature_data,printed_name,device_info)
  VALUES(w.id,w.organisation_id,w.current_step,w.steps->w.current_step->>'name',p_decision,auth.uid(),p_note,p_signature,
   (SELECT coalesce(full_name,username) FROM profiles WHERE id=auth.uid()),jsonb_build_object('operation_id',p_operation_id,'content_revision',p_expected_revision,'client_captured_at',p_client_captured_at,'accepted_at',accepted_at,'represented_actor_id',c->>'represented_actor_id'));
  UPDATE workflow_instances SET current_step=CASE WHEN final_stage THEN current_step ELSE current_step+1 END,
   status=CASE WHEN final_stage THEN p_decision ELSE 'pending' END,last_actor_id=auth.uid(),
   step_started_at=CASE WHEN final_stage THEN step_started_at ELSE accepted_at END,completed_at=CASE WHEN final_stage THEN accepted_at ELSE NULL END WHERE id=w.id;
  IF NOT final_stage THEN PERFORM approval_private.notify_stage(w.id); END IF;
 ELSE
  IF p_entity_type='inspection' THEN UPDATE inspections SET approval_outcome=p_decision WHERE id=p_entity_id;
  ELSIF p_entity_type='checklist' THEN UPDATE checklist_submissions SET approval_outcome=p_decision WHERE id=p_entity_id; ELSE UPDATE approval_execution_requests SET approval_outcome=p_decision WHERE id=p_entity_id; END IF;
  IF p_entity_type='inspection' THEN PERFORM decide_inspection_approval(p_entity_id,domain_decision,p_note,p_signature);
  ELSE IF p_entity_type='checklist' THEN PERFORM decide_checklist_approval(p_entity_id,domain_decision,p_note,p_signature); ELSE PERFORM approval_private.execution_decide(p_entity_type,p_entity_id,domain_decision,p_note,p_signature); END IF; END IF;
 END IF;
 d:=approval_private.document(p_entity_type,p_entity_id); c:=approval_private.context(p_entity_type,d);
 accepted:=jsonb_build_object('ok',true,'decision',p_decision,'status',d->>'approval_status','revision',(c->>'revision')::bigint,
  'stage_token',c->>'stage_token','operation_id',p_operation_id,'accepted_at',accepted_at,'workflow_status',c->>'workflow_status');
 INSERT INTO approval_private.decisions(operation_id,organisation_id,actor_id,entity_type,entity_id,request,result,accepted_at)
 VALUES(p_operation_id,app_current_org(),auth.uid(),p_entity_type,p_entity_id,req,accepted,accepted_at);
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type=p_entity_type AND entity_id=p_entity_id;
 RETURN accepted;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_checklist_approval(p_submission_id uuid, p_decision text, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role      text;
  v_org       uuid;
  v_approver  text;
  v_prev      text;
  v_status    text;
  v_two_stage boolean;
  v_target    text;
  v_both      boolean := false;
begin
  if public.app_cap_revoked('checklists','approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
  v_role := public.get_my_role();
  if not (public.checklist_is_supervisor() or public.checklist_is_area_manager() or public.app_cap_granted('checklists','approve')) then
    raise exception 'Only an approver can decide checklists';
  end if;
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Decision must be approved or rejected.';
  end if;

  v_org := public.app_current_org();

  select cs.approval_status, coalesce(t.require_area_manager, false)
    into v_status, v_two_stage
    from public.checklist_submissions cs
    left join public.checklist_templates t on t.id = cs.template_id
   where cs.id = p_submission_id
     and (cs.organisation_id = v_org or public.is_super_admin())
     and public.app_write_country_ok(cs.country)
     and (cs.site is null or btrim(cs.site) = '' or public.app_can_see_site(cs.site) is not false);

  if v_status is null then
    raise exception 'That checklist no longer exists.';
  end if;

  if v_status not in ('pending', 'pending_area_manager') then
    select coalesce(pr.full_name, pr.username, 'another approver')
      into v_approver
      from public.checklist_submissions cs
      left join public.profiles pr on pr.id = cs.approved_by
     where cs.id = p_submission_id;
    raise exception 'This checklist was already % by %.', v_status, coalesce(v_approver, 'another approver');
  end if;

  select coalesce(full_name, username, 'Approver')
    into v_approver from public.profiles where id = auth.uid();

  if p_decision = 'rejected' then
    v_target := 'rejected';
  elsif v_status = 'pending' and v_two_stage and not public.checklist_is_area_manager() then
    v_target := 'pending_area_manager';
  else
    v_target := 'approved';
    v_both := (v_status = 'pending' and v_two_stage);
  end if;

  if v_target = 'approved' and v_two_stage and not public.checklist_is_area_manager() then
    raise exception 'Only an area manager can give final approval on this checklist.';
  end if;
  if p_decision = 'approved' and coalesce(btrim(p_signature), '') = '' then
    raise exception 'A signature is required to sign off this checklist.';
  end if;

  if v_target = 'pending_area_manager' then
    update public.checklist_submissions
       set approval_status      = v_target,
           supervisor_by        = auth.uid(),
           supervisor_name      = v_approver,
           supervisor_signature = coalesce(p_signature, supervisor_signature),
           supervisor_at        = now(),
           review_note          = p_note
     where id = p_submission_id
       and approval_status = v_status
       and (organisation_id = v_org or public.is_super_admin());
  else
    update public.checklist_submissions
       set approval_status      = v_target,
           supervisor_by        = case when v_both then auth.uid() else supervisor_by end,
           supervisor_name      = case when v_both then v_approver else supervisor_name end,
           supervisor_signature = case when v_both then coalesce(p_signature, supervisor_signature) else supervisor_signature end,
           supervisor_at        = case when v_both then now() else supervisor_at end,
           approved_by          = auth.uid(),
           approver_name        = v_approver,
           approver_signature   = coalesce(p_signature, approver_signature),
           approved_at          = now(),
           review_note          = p_note,
           locked               = (v_target = 'approved')
     where id = p_submission_id
       and approval_status = v_status
       and (organisation_id = v_org or public.is_super_admin());
  end if;

  if not found then
    raise exception 'This checklist was decided by someone else while you were looking at it.';
  end if;

  return jsonb_build_object('ok', true, 'decision', p_decision, 'status', v_target, 'both_steps', v_both);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_classification_rule(p_token text, p_category text, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_token text := lower(btrim(coalesce(p_token, '')));
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_row public.classification_learned_rules;
begin
  if v_org is null then
    raise exception 'No organisation in session' using errcode = '42501';
  end if;
  if public.app_role() not in ('admin', 'manager', 'director')
     and not public.is_super_admin() then
    raise exception 'You do not have permission to decide classification rules'
      using errcode = '42501';
  end if;
  if v_token = '' or coalesce(p_category, '') = '' then
    raise exception 'A token and a category are required' using errcode = '22023';
  end if;
  if v_action not in ('accept', 'reject') then
    raise exception 'Action must be accept or reject' using errcode = '22023';
  end if;

  insert into public.classification_learned_rules
         (organisation_id, token, category, status, decided_by, decided_at, note)
  values (v_org, v_token, p_category,
          case when v_action = 'accept' then 'active' else 'rejected' end,
          auth.uid(), now(), nullif(btrim(coalesce(p_note, '')), ''))
  on conflict (organisation_id, token, category) do update
     set status = excluded.status,
         decided_by = excluded.decided_by,
         decided_at = excluded.decided_at,
         note = coalesce(excluded.note, public.classification_learned_rules.note)
  returning * into v_row;

  return jsonb_build_object('ok', true, 'token', v_row.token,
                            'category', v_row.category, 'status', v_row.status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_handover_approval(p_id uuid, p_approved boolean, p_signature text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org     uuid;
  v_name    text;
  v_status  text;
  v_country text;
  v_target  text;
  v_both    boolean := false;
  v_prev    text;
begin
  if public.app_cap_revoked('handover', 'approve') then
    raise exception 'You are not permitted to approve or decide this handover.' using errcode = '42501';
  end if;

  if not (public.handover_can_sign_supervisor()
          or public.handover_can_sign_incharge()
          or public.app_cap_granted('handover', 'approve')) then
    raise exception 'Only an approver can sign off a vehicle handover.' using errcode = '42501';
  end if;

  v_org := public.app_current_org();
  perform set_config('handover.via', 'decide', true);

  select hr.approval_status, hr.country
    into v_status, v_country
    from public.handover_reports hr
   where hr.id = p_id
     and (hr.organisation_id = v_org or public.is_super_admin())
     and public.app_write_country_ok(hr.country);

  if v_status is null then
    raise exception 'That handover no longer exists.' using errcode = '22023';
  end if;

  if v_status = 'draft' then
    raise exception 'This handover has not been submitted for sign-off yet.' using errcode = '22023';
  end if;

  if v_status not in ('pending_supervisor','pending_incharge') then
    select coalesce(pr.full_name, pr.username, 'another approver')
      into v_prev
      from public.handover_reports hr
      left join public.profiles pr on pr.id = coalesce(hr.incharge_by, hr.supervisor_by)
     where hr.id = p_id;
    raise exception 'This handover was already % by %.', v_status, coalesce(v_prev, 'another approver');
  end if;

  select coalesce(full_name, username, 'Approver')
    into v_name from public.profiles where id = auth.uid();

  if not p_approved then
    if coalesce(btrim(p_note), '') = '' then
      raise exception 'A reason is required to send a handover back.' using errcode = '22023';
    end if;
    if not public.handover_can_sign_supervisor() then
      raise exception 'You do not have permission to send this handover back.' using errcode = '42501';
    end if;
    update public.handover_reports
       set approval_status = 'rejected', review_note = p_note
     where id = p_id and approval_status = v_status
       and (organisation_id = v_org or public.is_super_admin());
    if not found then
      raise exception 'This handover was decided by someone else while you were looking at it.';
    end if;
    return jsonb_build_object('ok', true, 'decision', 'rejected', 'status', 'rejected', 'both_steps', false);
  end if;

  if coalesce(btrim(p_signature), '') = '' then
    raise exception 'A signature is required to sign off this handover.' using errcode = '22023';
  end if;

  if v_status = 'pending_supervisor' then
    if not public.handover_can_sign_supervisor() then
      raise exception 'Only a fleet supervisor can sign off this handover.' using errcode = '42501';
    end if;
    if public.handover_can_sign_incharge() then
      v_target := 'approved';
      v_both   := true;
    else
      v_target := 'pending_incharge';
    end if;
  else
    if not public.handover_can_sign_incharge() then
      raise exception 'Only the fleet incharge can give final approval on this handover.' using errcode = '42501';
    end if;
    v_target := 'approved';
  end if;

  if v_target = 'pending_incharge' then
    update public.handover_reports
       set approval_status      = 'pending_incharge',
           supervisor_by        = auth.uid(),
           supervisor_name      = v_name,
           supervisor_signature = p_signature,
           supervisor_at        = now(),
           review_note          = p_note
     where id = p_id and approval_status = v_status
       and (organisation_id = v_org or public.is_super_admin());
  else
    update public.handover_reports
       set approval_status      = 'approved',
           supervisor_by        = case when v_both then auth.uid()  else supervisor_by        end,
           supervisor_name      = case when v_both then v_name      else supervisor_name      end,
           supervisor_signature = case when v_both then p_signature else supervisor_signature end,
           supervisor_at        = case when v_both then now()       else supervisor_at        end,
           incharge_by          = auth.uid(),
           incharge_name        = v_name,
           incharge_signature   = p_signature,
           incharge_at          = now(),
           review_note          = p_note
     where id = p_id and approval_status = v_status
       and (organisation_id = v_org or public.is_super_admin());
  end if;

  if not found then
    raise exception 'This handover was decided by someone else while you were looking at it.';
  end if;

  return jsonb_build_object('ok', true, 'decision', 'approved', 'status', v_target, 'both_steps', v_both);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_inspection_approval(p_inspection_id uuid, p_decision text, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text; v_org uuid; v_email text; v_prev text; v_approver text; v_status text;
BEGIN
  -- cap-guard:approve
  if public.app_cap_revoked('inspections','approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
  v_role := public.get_my_role();
  -- Area manager, PMV manager, or Tyre Data Collector signs. Admin kept as fallback.
  IF NOT public.is_super_admin() AND NOT public.app_cap_granted('inspections','approve') AND (v_role IS NULL OR v_role NOT IN (
      'Admin','PMV Manager','Workshop Area Manager','Workshop Maintenance Area Manager','Tyre Data Collector')) THEN
    RAISE EXCEPTION 'Only an area manager, a PMV manager, an admin or a tyre data collector can sign off an inspection';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Decision must be approved or rejected.';
  END IF;

  v_org := public.app_current_org();
  v_status := CASE WHEN p_decision = 'approved' THEN 'Done' ELSE 'In Progress' END;

  -- V602 restored (audit 2026-09-30): a pending inspection is never approved
  -- unsigned. A later redefinition had dropped this rule.
  IF p_decision = 'approved' AND coalesce(btrim(p_signature), '') = ''
     AND EXISTS (SELECT 1 FROM public.inspections i WHERE i.id = p_inspection_id
                  AND i.approval_status = 'pending_approval'
                  AND coalesce(btrim(i.approver_signature), '') = '') THEN
    RAISE EXCEPTION 'An inspection approval needs a signature.' USING errcode = '22023';
  END IF;

  SELECT COALESCE(full_name, username, email, 'Approver') INTO v_approver
    FROM public.profiles WHERE id = auth.uid();
  SELECT email INTO v_email FROM public.profiles WHERE id = auth.uid();

  UPDATE public.inspections
     SET approval_status = p_decision, status = v_status, approved_by = auth.uid(),
         approver_email = v_email,
         approver_signature = COALESCE(p_signature, approver_signature),
         approved_at = now()
   WHERE id = p_inspection_id
     AND approval_status = 'pending_approval'
     AND (organisation_id = v_org OR public.is_super_admin())
     -- Country + site boundary (audit 2026-09-30): a DEFINER write must re-check both.
     AND public.app_write_country_ok(country)
     AND (site IS NULL OR btrim(site) = '' OR public.app_can_see_site(site) IS NOT FALSE);

  IF NOT FOUND THEN
    SELECT i.approval_status, COALESCE(pr.full_name, pr.username, 'another approver')
      INTO v_prev, v_approver
      FROM public.inspections i LEFT JOIN public.profiles pr ON pr.id = i.approved_by
     WHERE i.id = p_inspection_id;
    IF v_prev IS NULL THEN
      RAISE EXCEPTION 'That inspection no longer exists.';
    ELSIF v_prev <> 'pending_approval' THEN
      RAISE EXCEPTION 'This inspection was already % by %.', v_prev, v_approver;
    ELSE
      RAISE EXCEPTION 'You do not have access to decide this inspection.';
    END IF;
  END IF;

  IF p_note IS NOT NULL AND btrim(p_note) <> '' THEN
    INSERT INTO public.inspection_audit_log (inspection_id, changed_by, action, new_values)
    VALUES (p_inspection_id, auth.uid(), p_decision || '_note', jsonb_build_object('note', p_note));
  END IF;

  RETURN jsonb_build_object('ok', true, 'decision', p_decision);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.decide_trust_alert(p_id bigint, p_status text, p_note text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from text;
  v_alert_org uuid;
  v_note text := btrim(coalesce(p_note, ''));
begin
  if not (public.is_super_admin() or lower(coalesce(public.app_role(), '')) = 'admin') then
    raise exception 'Only an Admin or super admin can decide a trust alert' using errcode = '42501';
  end if;
  if p_status not in ('open','ack','resolved') then
    raise exception 'Unknown alert status' using errcode = '22023';
  end if;
  if length(v_note) < 3 then
    raise exception 'A reason of at least 3 characters is required' using errcode = '22023';
  end if;
  select status, organisation_id into v_from, v_alert_org
    from public.trust_alerts where id = p_id for update;
  if not found or (v_alert_org is distinct from v_org and not public.is_super_admin()) then
    raise exception 'Alert not found' using errcode = 'P0002';
  end if;
  if v_from = p_status then
    raise exception 'The alert is already in that state' using errcode = '22023';
  end if;
  update public.trust_alerts
     set status = p_status,
         acked_by = case when p_status = 'ack' then auth.uid() else acked_by end,
         acked_at = case when p_status = 'ack' then now() else acked_at end,
         resolved_by = case when p_status = 'resolved' then auth.uid() when p_status = 'open' then null else resolved_by end,
         resolved_at = case when p_status = 'resolved' then now() when p_status = 'open' then null else resolved_at end,
         resolution_note = left(v_note, 1000)
   where id = p_id;
  insert into public.trust_alert_events (alert_id, organisation_id, from_status, to_status, note, actor)
  values (p_id, v_alert_org, v_from, p_status, left(v_note, 1000), auth.uid());
  return json_build_object('ok', true, 'id', p_id, 'from', v_from, 'status', p_status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.default_corrective_action_due_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v jsonb;
  h integer;
begin
  if new.due_date is not null then return new; end if;
  select public.checklist_governance_defaults() || coalesce(to_jsonb(p),'{}'::jsonb)
    into v from public.checklist_governance_policies p
   where p.organisation_id is not distinct from new.organisation_id;
  v := coalesce(v, public.checklist_governance_defaults());
  h := case lower(coalesce(new.priority,'medium'))
    when 'critical' then (v->>'corrective_critical_sla_hours')::integer
    when 'urgent' then (v->>'corrective_critical_sla_hours')::integer
    when 'high' then (v->>'corrective_high_sla_hours')::integer
    when 'low' then (v->>'corrective_low_sla_hours')::integer
    else (v->>'corrective_medium_sla_hours')::integer end;
  new.due_date := (coalesce(new.created_at,now()) + make_interval(hours => h))::date;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.deliver_pending_webhooks()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  d      record;
  r      record;
  v_body text;
  v_sig  text;
  v_req  bigint;
  n_sent int := 0;
  n_done int := 0;
  n_dead int := 0;
BEGIN
  FOR d IN
    SELECT wd.id, wd.subscription_id, wd.attempts, wd.request_id
      FROM public.webhook_deliveries wd
     WHERE wd.status = 'pending' AND wd.request_id IS NOT NULL
  LOOP
    SELECT status_code, error_msg INTO r FROM net._http_response WHERE id = d.request_id;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;
    IF r.status_code BETWEEN 200 AND 299 THEN
      UPDATE public.webhook_deliveries
         SET status = 'delivered', delivered_at = now(),
             response_status = r.status_code, last_error = NULL, request_id = NULL
       WHERE id = d.id;
      UPDATE public.webhook_subscriptions
         SET last_success_at = now(), consecutive_failures = 0
       WHERE id = d.subscription_id;
      n_done := n_done + 1;
    ELSE
      UPDATE public.webhook_deliveries
         SET response_status = r.status_code,
             last_error = left(COALESCE(r.error_msg, 'HTTP ' || COALESCE(r.status_code::text, '?')), 500),
             request_id = NULL,
             status = CASE WHEN d.attempts >= 6 THEN 'failed' ELSE 'pending' END
       WHERE id = d.id;
      UPDATE public.webhook_subscriptions s
         SET last_failure_at = now(),
             consecutive_failures = s.consecutive_failures + 1,
             active = CASE WHEN s.consecutive_failures + 1 >= 20 THEN false ELSE s.active END,
             disabled_reason = CASE WHEN s.consecutive_failures + 1 >= 20
                                    THEN 'Auto-disabled after 20 consecutive failures' END
       WHERE id = d.subscription_id;
      IF d.attempts >= 6 THEN n_dead := n_dead + 1; END IF;
    END IF;
  END LOOP;
  FOR d IN
    SELECT wd.id, wd.payload, wd.attempts, s.url, s.secret, wd.event_type
      FROM public.webhook_deliveries wd
      JOIN public.webhook_subscriptions s ON s.id = wd.subscription_id
     WHERE wd.status = 'pending' AND wd.request_id IS NULL
       AND wd.next_attempt_at <= now() AND wd.attempts < 6 AND s.active
     ORDER BY wd.next_attempt_at
     LIMIT 50
     FOR UPDATE OF wd SKIP LOCKED
  LOOP
    v_body := d.payload::text;
    v_sig  := 'sha256=' || encode(hmac(v_body, d.secret, 'sha256'), 'hex');
    v_req := net.http_post(
      url     := d.url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'User-Agent', 'TyrePulse-Webhooks/1.0',
        'X-TyrePulse-Event', d.event_type,
        'X-TyrePulse-Signature', v_sig),
      body    := d.payload,
      timeout_milliseconds := 10000
    );
    UPDATE public.webhook_deliveries
       SET attempts = d.attempts + 1, request_id = v_req,
           next_attempt_at = now() + make_interval(mins => least(power(2, d.attempts + 1)::int, 60))
     WHERE id = d.id;
    n_sent := n_sent + 1;
  END LOOP;
  RETURN jsonb_build_object('sent', n_sent, 'delivered', n_done, 'dead', n_dead);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.deliver_workflow_notifications()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d        record;
  r        record;
  v_secret text;
  v_req    bigint;
  n_sent   int := 0;
  n_done   int := 0;
  n_dead   int := 0;
BEGIN
  FOR d IN
    SELECT wn.id, wn.attempts, wn.request_id
      FROM public.workflow_notifications wn
     WHERE wn.status = 'pending' AND wn.request_id IS NOT NULL
  LOOP
    SELECT status_code, content, error_msg INTO r
      FROM net._http_response WHERE id = d.request_id;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;
    IF r.status_code BETWEEN 200 AND 299 THEN
      UPDATE public.workflow_notifications
         SET status = 'delivered', delivered_at = now(), response_status = r.status_code,
             result = CASE WHEN r.content IS NULL THEN NULL ELSE (r.content)::jsonb END,
             last_error = NULL, request_id = NULL
       WHERE id = d.id;
      n_done := n_done + 1;
    ELSE
      UPDATE public.workflow_notifications
         SET response_status = r.status_code,
             last_error = left(COALESCE(r.error_msg,
                              'HTTP ' || COALESCE(r.status_code::text, '?')), 500),
             request_id = NULL,
             status = CASE WHEN d.attempts >= 6 THEN 'failed' ELSE 'pending' END
       WHERE id = d.id;
      IF d.attempts >= 6 THEN n_dead := n_dead + 1; END IF;
    END IF;
  END LOOP;
  SELECT value INTO v_secret FROM public.cron_config WHERE name = 'workflow_notify_secret';
  FOR d IN
    SELECT wn.id, wn.payload, wn.attempts
      FROM public.workflow_notifications wn
     WHERE wn.status = 'pending' AND wn.request_id IS NULL
       AND wn.next_attempt_at <= now() AND wn.attempts < 6
     ORDER BY wn.next_attempt_at
     LIMIT 50 FOR UPDATE OF wn SKIP LOCKED
  LOOP
    v_req := net.http_post(
      url     := 'https://staging-project-ref.supabase.co/functions/v1/workflow-notify',
      headers := jsonb_strip_nulls(jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', ('Bearer ' || (select value from public.cron_config where name = 'anon_key')),
        'x-workflow-secret', v_secret)),
      body    := d.payload,
      timeout_milliseconds := 15000
    );
    UPDATE public.workflow_notifications
       SET attempts = d.attempts + 1, request_id = v_req,
           next_attempt_at = now() + make_interval(mins => least(power(2, d.attempts + 1)::int, 60))
     WHERE id = d.id;
    n_sent := n_sent + 1;
  END LOOP;
  RETURN jsonb_build_object('sent', n_sent, 'delivered', n_done, 'dead', n_dead);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.dispatch_accident_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_asset  text;
  v_site   text;
  v_label  text;
BEGIN
  v_asset := COALESCE(NEW.asset_no, OLD.asset_no, 'Unknown asset');
  v_site  := COALESCE(NEW.site,     OLD.site,     '');

  -- A. New accident
  IF TG_OP = 'INSERT' THEN
    PERFORM public.notify_elevated_users(
      'accident',
      'New Accident Reported — ' || v_asset,
      format('Asset %s (%s) | Severity: %s', v_asset, v_site, COALESCE(NEW.severity, 'Unknown')),
      'accident', NEW.id
    );
    RETURN NEW;
  END IF;

  -- B. claim_status changed
  IF TG_OP = 'UPDATE' AND (OLD.claim_status IS DISTINCT FROM NEW.claim_status) THEN
    v_label := CASE NEW.claim_status
      WHEN 'filed'    THEN 'Insurance Claim Filed'
      WHEN 'approved' THEN 'Claim Approved'
      WHEN 'rejected' THEN 'Claim Rejected'
      WHEN 'settled'  THEN 'Claim Settled'
      ELSE                  'Claim Status Updated'
    END;
    PERFORM public.notify_elevated_users(
      CASE WHEN NEW.claim_status IN ('approved','settled') THEN 'success'
           WHEN NEW.claim_status = 'rejected' THEN 'warning' ELSE 'info' END,
      v_label || ' — ' || v_asset,
      format('Asset %s (%s) | %s → %s%s', v_asset, v_site,
        COALESCE(OLD.claim_status,'none'), COALESCE(NEW.claim_status,'none'),
        CASE WHEN NEW.claim_amount IS NOT NULL THEN ' | Amount: ' || NEW.claim_amount ELSE '' END),
      'accident', NEW.id
    );
  END IF;

  -- C. closure_status changed
  IF TG_OP = 'UPDATE' AND (OLD.closure_status IS DISTINCT FROM NEW.closure_status) THEN
    v_label := CASE NEW.closure_status
      WHEN 'pending_closure' THEN 'Closure Requested'
      WHEN 'closed'          THEN 'Accident Closed'
      ELSE                        'Closure Status Changed'
    END;
    PERFORM public.notify_elevated_users(
      CASE WHEN NEW.closure_status = 'closed' THEN 'success' ELSE 'info' END,
      v_label || ' — ' || v_asset,
      format('Asset %s (%s) → %s', v_asset, v_site, NEW.closure_status),
      'accident', NEW.id
    );
  END IF;

  -- D. status → 'Insurance Claim'
  IF TG_OP = 'UPDATE'
     AND (OLD.status IS DISTINCT FROM NEW.status)
     AND NEW.status = 'Insurance Claim'
  THEN
    PERFORM public.notify_elevated_users(
      'warning',
      'Insurance Claim Opened — ' || v_asset,
      format('Asset %s (%s) moved to Insurance Claim.%s', v_asset, v_site,
        CASE WHEN NEW.insurance_claim_no IS NOT NULL THEN ' Claim No: ' || NEW.insurance_claim_no ELSE '' END),
      'accident', NEW.id
    );
  END IF;

  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.driver_fine_register(p_filters jsonb DEFAULT '{}'::jsonb, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE result jsonb; org uuid:=public.app_current_org(); query_text text:=left(coalesce(p_filters->>'search',''),160);
BEGIN
  IF auth.uid() IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false) OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
  IF NOT (coalesce(public.app_user_can('fleet_master','edit'),false) OR private.driver_workspace_is_finance_reviewer() OR coalesce(public.app_user_can('driver_workspace','view'),false)
    OR EXISTS(SELECT 1 FROM public.driver_team_assignments a WHERE auth.uid() IN (a.supervisor_id,a.manager_id) AND a.ends_at IS NULL)) THEN RAISE EXCEPTION 'Staff access required' USING ERRCODE='42501'; END IF;
  IF coalesce(p_filters->>'status','') NOT IN ('','open','settled','cancelled') OR coalesce(p_filters->>'review_stage','') NOT IN ('','driver','supervisor','finance','complete') THEN RAISE EXCEPTION 'Invalid filter' USING ERRCODE='22023'; END IF;
  SELECT jsonb_build_object('rows',coalesce(jsonb_agg(x ORDER BY x->>'due_date',x->>'id'),'[]')) INTO result FROM (
    SELECT jsonb_build_object('id',f.id,'driver_id',f.driver_id,'driver_name',d.driver_name,'employee_id',d.driver_id,'site',f.site,'country',f.country,
      'asset_no',v.asset_no,'authority',f.authority,'notice_reference',f.notice_reference,'incident_at',f.incident_at,'due_date',f.due_date,
      'amount',f.amount,'currency',f.currency,'paid_amount',f.paid_amount,'balance',f.amount-f.paid_amount,'status',f.status,'response_status',f.response_status,
      'review_stage',f.review_stage,'version',f.version,'created_at',f.created_at,'updated_at',f.updated_at,
      'resolution',(SELECT r.resolution FROM public.driver_fine_responses r WHERE r.fine_id=f.id ORDER BY r.signed_at DESC LIMIT 1),
      'signed_at',(SELECT r.signed_at FROM public.driver_fine_responses r WHERE r.fine_id=f.id ORDER BY r.signed_at DESC LIMIT 1),
      'signature_present',EXISTS(SELECT 1 FROM public.driver_fine_responses r WHERE r.fine_id=f.id),
      'last_reviewer',(SELECT p.full_name FROM public.driver_fine_reviews rv JOIN public.profiles p ON p.id=rv.reviewer_id WHERE rv.fine_id=f.id ORDER BY rv.created_at DESC,rv.id DESC LIMIT 1),
      'last_payment_reference',(SELECT rv.details->>'payment_reference' FROM public.driver_fine_reviews rv WHERE rv.fine_id=f.id AND rv.decision='payment' ORDER BY rv.created_at DESC,rv.id DESC LIMIT 1),
      'reminder_count',(SELECT count(*) FROM public.driver_fine_reminders rm WHERE rm.fine_id=f.id),
      'overdue',f.status='open' AND f.due_date<current_date) x
    FROM public.driver_fines f JOIN public.drivers d ON d.id=f.driver_id LEFT JOIN public.vehicle_fleet v ON v.id=f.vehicle_id
    WHERE f.organisation_id=org AND private.driver_workspace_access(f.driver_id) IN ('manager','supervisor','finance','viewer')
      AND (coalesce(p_filters->>'status','')='' OR f.status=p_filters->>'status')
      AND (coalesce(p_filters->>'review_stage','')='' OR f.review_stage=p_filters->>'review_stage')
      AND (NOT coalesce((p_filters->>'overdue')::boolean,false) OR (f.status='open' AND f.due_date<current_date))
      AND (query_text='' OR concat_ws(' ',d.driver_name,d.driver_id,v.asset_no,f.authority,f.notice_reference,f.site) ILIKE '%'||query_text||'%')
    ORDER BY f.due_date NULLS LAST,f.id LIMIT 101 OFFSET p_offset
  ) q;
  RETURN result;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.driver_workspace(p_driver_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ SELECT private.driver_workspace_read(p_driver_id,p_offset) $function$;
