CREATE OR REPLACE FUNCTION public.emit_accident_domain_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := COALESCE(NEW.organisation_id, OLD.organisation_id);
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.emit_domain_event('accident.reported', 'accident', NEW.id::text,
      jsonb_build_object('reference_no',NEW.reference_no,'asset_no',NEW.asset_no,'site',NEW.site,
        'severity',NEW.severity,'status',NEW.status,'workflow_stage',NEW.workflow_stage,
        'incident_date',NEW.incident_date,'driver_name',NEW.driver_name,'organisation_id',NEW.organisation_id),
      v_org, auth.uid());
    RETURN NEW;
  END IF;

  IF NEW.workflow_stage IS DISTINCT FROM OLD.workflow_stage THEN
    PERFORM public.emit_domain_event('accident.stage_changed', 'accident', NEW.id::text,
      jsonb_build_object('from',OLD.workflow_stage,'to',NEW.workflow_stage,'reference_no',NEW.reference_no,
        'asset_no',NEW.asset_no,'site',NEW.site), v_org, auth.uid());
  END IF;
  IF NEW.claim_status IS DISTINCT FROM OLD.claim_status THEN
    PERFORM public.emit_domain_event('accident.claim_changed', 'accident', NEW.id::text,
      jsonb_build_object('claim_status',NEW.claim_status,'reference_no',NEW.reference_no,
        'asset_no',NEW.asset_no,'site',NEW.site), v_org, auth.uid());
  END IF;
  IF NEW.vor IS DISTINCT FROM OLD.vor THEN
    PERFORM public.emit_domain_event('accident.vor_changed', 'accident', NEW.id::text,
      jsonb_build_object('vor',NEW.vor,'reference_no',NEW.reference_no,'asset_no',NEW.asset_no,
        'site',NEW.site), v_org, auth.uid());
  END IF;
  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.emit_domain_event(p_event_type text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb, p_org uuid DEFAULT NULL::uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id bigint;
BEGIN
  INSERT INTO public.domain_events (event_type, entity_type, entity_id, organisation_id, actor_id, payload)
  VALUES (p_event_type, p_entity_type, p_entity_id, p_org, p_actor, COALESCE(p_payload, '{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.enforce_accident_closure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.closure_level = 'fully_closed'
     and OLD.closure_level is distinct from 'fully_closed' then
    if not exists (
      select 1 from public.accident_closure_reviews r
       where r.accident_id = NEW.id
         and r.level       = 'fully_closed'
         and r.decision    = 'approved'
    ) then
      raise exception
        'Cannot set closure_level=fully_closed on case %: no approved fully_closed closure review on record',
        NEW.id using errcode = '42501';
    end if;
  end if;

  if NEW.case_status = 'closed'
     and OLD.case_status is distinct from 'closed' then
    if not exists (
      select 1 from public.accident_closure_reviews r
       where r.accident_id = NEW.id
         and r.level       = 'fully_closed'
         and r.decision    = 'approved'
    ) then
      raise exception
        'Cannot set case_status=closed on case %: closure gate not satisfied (no approved closure review)',
        NEW.id using errcode = '42501';
    end if;
  end if;

  return NEW;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.enforce_plan_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_resource text := TG_ARGV[0];
  v_org uuid;
  v_block boolean := false;
  v_label text;
begin
  begin
    if auth.uid() is null or auth.role() is distinct from 'authenticated' then
      return NEW;
    end if;
    v_org := public.app_current_org();
    if v_org is null then
      return NEW;
    end if;
    if not exists (select 1 from public.org_subscriptions s where s.organisation_id = v_org) then
      return NEW;
    end if;
    if public.org_can_add(v_resource) = false then
      v_block := true;
    end if;
  exception when others then
    return NEW;
  end;

  if v_block then
    v_label := case v_resource when 'api_keys' then 'API keys' else v_resource end;
    raise exception 'Plan limit reached for %. Upgrade your plan to add more.', v_label
      using errcode = 'check_violation',
            hint = 'Your current subscription plan does not allow additional ' || v_label || '. Contact your administrator to upgrade.';
  end if;
  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.enforce_status_change_capability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND public.app_cap_revoked(TG_ARGV[0], 'approve') THEN
    RAISE EXCEPTION 'You are not permitted to change the status for %.', TG_ARGV[0] USING errcode = '42501';
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.erp_batch_promotion_status(p_dataset text, p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid:=public.app_current_org();
begin
  if v_org is null then
    return jsonb_build_object('inserted',0,'updated',0,'exact_duplicates',0,'existing',0,'promoted',false);
  end if;
  return (select jsonb_build_object(
    'inserted',coalesce(sum((action='insert')::int),0),
    'updated',coalesce(sum((action='update')::int),0),
    'exact_duplicates',coalesce(sum((action in ('exact','exists'))::int),0),
    'existing',coalesce(sum((action in ('exact','exists'))::int),0),
    'total',count(*),'promoted',count(*)>0,'promoted_at',max(promoted_at))
  from erp_promote_bak.promotion_log
  where dataset=p_dataset and batch_id=p_batch and organisation_id=v_org);
end
$function$;
