CREATE OR REPLACE FUNCTION public.erp_is_footer(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT lower(coalesce(t,'')) ~ '(grand total|sub total|printed by|printed date|applied filters|employee (id|code))'
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.erp_parse_date(t text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE s text := btrim(coalesce(t,'')); m text[]; mon int;
  months jsonb := '{"jan":1,"feb":2,"mar":3,"apr":4,"may":5,"jun":6,"jul":7,"aug":8,"sep":9,"oct":10,"nov":11,"dec":12}';
  y int;
BEGIN
  IF s = '' THEN RETURN NULL; END IF;
  m := regexp_match(s, '^(\d{4})-(\d{2})-(\d{2})');
  IF m IS NOT NULL THEN BEGIN RETURN make_date(m[1]::int, m[2]::int, m[3]::int); EXCEPTION WHEN others THEN RETURN NULL; END; END IF;
  m := regexp_match(s, '^(\d{1,2})[-/](\d{1,2})[-/](\d{4})');
  IF m IS NOT NULL THEN BEGIN RETURN make_date(m[3]::int, m[2]::int, m[1]::int); EXCEPTION WHEN others THEN RETURN NULL; END; END IF;
  m := regexp_match(lower(s), '^(\d{1,2})[-/]([a-z]{3})[-/](\d{2,4})');
  IF m IS NOT NULL THEN
    mon := (months ->> m[2])::int; IF mon IS NULL THEN RETURN NULL; END IF;
    y := m[3]::int; IF y < 100 THEN y := y + 2000; END IF;
    BEGIN RETURN make_date(y, mon, m[1]::int); EXCEPTION WHEN others THEN RETURN NULL; END;
  END IF;
  RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.erp_parse_ts(t text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
declare
  s text := btrim(coalesce(t, ''));
  v timestamptz;
begin
  if s = '' or upper(s) in ('NULL','N/A','-') then return null; end if;

  -- ISO only: yyyy-mm-dd... . Never let the cast see a dd-mm-yyyy string, or
  -- MDY DateStyle silently swaps day and month.
  if s ~ '^\d{4}-\d{2}-\d{2}' then
    begin return s::timestamptz; exception when others then null; end;
  end if;

  begin v := to_timestamp(s, 'DD-MM-YYYY HH24:MI:SS'); exception when others then v := null; end;
  if v is null then begin v := to_timestamp(s, 'DD/MM/YYYY HH24:MI:SS'); exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD-MM-YYYY HH24:MI');    exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD/MM/YYYY HH24:MI');    exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD-Mon-YYYY HH24:MI');   exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD-Mon-YY HH24:MI');     exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD-MM-YYYY');            exception when others then v := null; end; end if;
  if v is null then begin v := to_timestamp(s, 'DD/MM/YYYY');            exception when others then v := null; end; end if;
  if v is null then begin v := public.erp_parse_date(s)::timestamptz;    exception when others then v := null; end; end if;
  if v is null then return null; end if;

  -- Two-digit year taken literally: '01-06-26' parses to year 26, not 2026.
  if extract(year from v) < 100 then
    v := v + make_interval(years => 2000);
  end if;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.error_group_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    update public.error_group_state
       set status = 'for_review', regressed_at = now(), updated_at = now(),
           note = left(coalesce(note || ' | ', '') || 'Came back after it was closed', 500)
     where group_key = public.system_log_group_key(new.source, new.message, new.error_fingerprint)
       and status in ('resolved', 'fixed_in_code')
       and coalesce(resolved_at, updated_at) < new.created_at;
  exception when others then
    null;
  end;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.escalate_overdue_workflow_steps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  n int := 0;
BEGIN
  FOR r IN
    SELECT wi.id, wi.organisation_id, wi.definition_name, wi.entity_label, wi.entity_type,
           wi.current_step, wi.steps -> wi.current_step AS step
      FROM public.workflow_instances wi
     WHERE wi.status = 'pending'
       AND (wi.steps -> wi.current_step) ? 'sla_hours'
       AND wi.step_started_at
           + make_interval(mins => round((wi.steps -> wi.current_step ->> 'sla_hours')::numeric * 60)::int)
           < now()
       AND NOT EXISTS (
         SELECT 1 FROM public.workflow_step_events se
          WHERE se.instance_id = wi.id
            AND se.step_index = wi.current_step
            AND se.action = 'escalated')
  LOOP
    INSERT INTO public.workflow_step_events
      (instance_id, organisation_id, step_index, step_name, action, comment)
    VALUES
      (r.id, r.organisation_id, r.current_step, r.step ->> 'name', 'escalated',
       'SLA of ' || (r.step ->> 'sla_hours') || 'h exceeded');
    PERFORM public.notify_role_in_org(
      'admin', r.organisation_id, 'escalation',
      'Overdue approval: ' || r.definition_name,
      COALESCE(r.entity_label, r.entity_type) || ' has been waiting at step "' ||
        (r.step ->> 'name') || '" beyond its ' || (r.step ->> 'sla_hours') || 'h SLA.',
      'workflow', r.id);
    PERFORM public.emit_domain_event('workflow.escalated', 'workflow_instance', r.id::text,
      jsonb_build_object('definition', r.definition_name, 'step', r.step ->> 'name',
                         'sla_hours', r.step ->> 'sla_hours'),
      r.organisation_id, NULL);
    n := n + 1;
  END LOOP;
  RETURN jsonb_build_object('escalated', n);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.evaluate_alert_thresholds()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t       record;
  v_count int;
  v_fired int := 0;
  v_op    text;
  v_is_count boolean;
  v_hit   boolean;
  v_sql   text;
BEGIN
  FOR t IN
    SELECT * FROM public.alert_thresholds
     WHERE active
       AND metric IN ('tread_depth','pressure','tyre_age_days','inspection_overdue_days',
                    'open_breakdowns','stock_below_min','overdue_parts_requests','expiring_certifications',
                    'open_corrective_actions','pending_approvals','overdue_work_orders','open_accidents',
                    'pm_overdue','high_risk_tyres')
       AND (last_triggered_at IS NULL OR last_triggered_at < now() - interval '23 hours')
  LOOP
    v_op := CASE t.operator
              WHEN 'lt' THEN '<' WHEN 'lte' THEN '<='
              WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' ELSE '=' END;
    v_count := 0;
    v_is_count := false;
    IF t.metric IN ('tread_depth','pressure') THEN
      EXECUTE format(
        'SELECT count(*) FROM public.inspections
          WHERE created_at > now() - interval ''25 hours''
            AND %I IS NOT NULL AND %I %s $1
            AND ($2 IS NULL OR site = $2)',
        CASE t.metric WHEN 'tread_depth' THEN 'tread_depth' ELSE 'pressure_reading' END,
        CASE t.metric WHEN 'tread_depth' THEN 'tread_depth' ELSE 'pressure_reading' END,
        v_op)
      INTO v_count USING t.threshold, NULLIF(t.site_filter, '');
    ELSIF t.metric = 'tyre_age_days' THEN
      EXECUTE format(
        'SELECT count(*) FROM public.tyre_records
          WHERE issue_date IS NOT NULL
            AND (current_date - issue_date) %s $1
            AND ($2 IS NULL OR site = $2)
            AND ($3 IS NULL OR brand = $3)',
        v_op)
      INTO v_count USING t.threshold::int, NULLIF(t.site_filter, ''), NULLIF(t.brand_filter, '');
    ELSIF t.metric = 'inspection_overdue_days' THEN
      EXECUTE format(
        'SELECT count(*) FROM (
           SELECT asset_no,
                  current_date - max(COALESCE(completed_date, scheduled_date)) AS days_since
             FROM public.inspections
            WHERE asset_no IS NOT NULL
              AND ($2 IS NULL OR site = $2)
            GROUP BY asset_no
         ) x WHERE x.days_since %s $1',
        v_op)
      INTO v_count USING t.threshold::int, NULLIF(t.site_filter, '');
    ELSE
      v_is_count := true;
      v_sql := CASE t.metric
        WHEN 'open_breakdowns' THEN
          'SELECT count(*) FROM public.asset_breakdowns WHERE NOT COALESCE(returned_to_service, false)'
        WHEN 'stock_below_min' THEN
          'SELECT count(*) FROM public.stock_records WHERE min_level IS NOT NULL AND stock_qty IS NOT NULL AND stock_qty <= min_level'
        WHEN 'overdue_parts_requests' THEN
          'SELECT count(*) FROM public.parts_requests WHERE needed_by < now() AND lower(COALESCE(status, '''')) NOT IN (''fulfilled'',''rejected'',''cancelled'')'
        WHEN 'expiring_certifications' THEN
          'SELECT count(*) FROM public.certifications WHERE expiry_date BETWEEN current_date AND current_date + 30 AND lower(COALESCE(status, '''')) <> ''revoked'''
        WHEN 'open_corrective_actions' THEN
          'SELECT count(*) FROM public.corrective_actions WHERE lower(COALESCE(status, '''')) NOT IN (''closed'',''completed'',''cancelled'',''resolved'',''verified'')'
        WHEN 'pending_approvals' THEN
          'SELECT count(*) FROM public.inspections WHERE approval_status = ''pending_approval'''
        WHEN 'overdue_work_orders' THEN
          'SELECT count(*) FROM public.work_orders WHERE target_completion < now() AND public.wo_status_canonical(status) NOT IN (''Completed'',''Closed'',''Cancelled'')'
        WHEN 'open_accidents' THEN
          'SELECT count(*) FROM public.accidents WHERE lower(COALESCE(status, '''')) NOT IN (''closed'',''cancelled'')'
        WHEN 'pm_overdue' THEN
          'SELECT count(*) FROM public.pm_programs WHERE lower(COALESCE(status, '''')) = ''active'' AND next_due < current_date'
        WHEN 'high_risk_tyres' THEN
          'SELECT count(*) FROM public.tyre_records WHERE risk_level IN (''High'',''Critical'')'
      END;
      IF v_sql IS NOT NULL THEN
        EXECUTE v_sql || ' AND ($1::text IS NULL OR site = $1) AND ($2::uuid IS NULL OR organisation_id = $2)'
          INTO v_count USING NULLIF(t.site_filter, ''), t.org_id;
      END IF;
    END IF;
    IF v_is_count THEN
      EXECUTE format('SELECT $1 %s $2', v_op) INTO v_hit USING COALESCE(v_count, 0)::numeric, t.threshold;
    ELSE
      v_hit := COALESCE(v_count, 0) > 0;
    END IF;
    IF COALESCE(v_hit, false) THEN
      IF COALESCE(t.notify_in_app, true) AND t.user_id IS NOT NULL THEN
        INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
        VALUES (t.user_id, 'threshold',
                'Threshold triggered: ' || t.name,
                v_count || ' record(s) matched ' || t.metric || ' ' || t.operator || ' ' || t.threshold ||
                  COALESCE(' at ' || NULLIF(t.site_filter, ''), '') || '.',
                'alert_threshold', t.id);
      END IF;
      UPDATE public.alert_thresholds
         SET triggered_count = COALESCE(triggered_count, 0) + 1, last_triggered_at = now()
       WHERE id = t.id;
      PERFORM public.emit_domain_event('threshold.triggered', 'alert_threshold', t.id::text,
        jsonb_build_object('name', t.name, 'metric', t.metric, 'operator', t.operator,
                           'threshold', t.threshold, 'matched', v_count, 'site_filter', t.site_filter),
        NULL, t.user_id);
      v_fired := v_fired + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('fired', v_fired);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.evaluate_checklist_submission_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v jsonb;
  exception_keys text[];
  missing_notes integer := 0;
  missing_photos integer := 0;
  gaps jsonb := '{}'::jsonb;
begin
  select public.checklist_governance_defaults() || coalesce(to_jsonb(p),'{}'::jsonb)
    into v from public.checklist_governance_policies p
   where p.organisation_id is not distinct from new.organisation_id;
  v := coalesce(v, public.checklist_governance_defaults());

  select coalesce(array_agg(a.key),'{}'::text[]) into exception_keys
  from jsonb_each_text(coalesce(new.answers,'{}'::jsonb)) a
  where lower(btrim(a.value)) = any(array[
    'no','fail','failed','defect','defective','unsafe','not ok','not_ok','non-compliant','noncompliant'
  ]);

  if (v->>'exception_note_required')::boolean then
    select count(*) into missing_notes from unnest(exception_keys) k
     where nullif(btrim(coalesce(new.notes->>k,'')),'') is null;
    if missing_notes > 0 then gaps := gaps || jsonb_build_object('exception_notes_missing',missing_notes); end if;
  end if;
  if (v->>'exception_photo_required')::boolean then
    select count(*) into missing_photos from unnest(exception_keys) k
     where not coalesce(new.photos,'{}'::jsonb) ? k
        or coalesce(new.photos->k,'null'::jsonb) in ('null'::jsonb,'[]'::jsonb,'{}'::jsonb,'""'::jsonb);
    if missing_photos > 0 then gaps := gaps || jsonb_build_object('exception_photos_missing',missing_photos); end if;
  end if;
  if (v->>'completion_signature_required')::boolean
     and nullif(btrim(coalesce(new.signature_data,'')),'') is null then
    gaps := gaps || jsonb_build_object('completion_signature_missing',true);
  end if;
  if (v->>'gps_required')::boolean
     and (new.gps_latitude is null or new.gps_longitude is null) then
    gaps := gaps || jsonb_build_object('gps_missing',true);
  end if;

  new.evidence_policy_gaps := gaps;
  new.evidence_policy_status := case when gaps='{}'::jsonb then 'compliant' else 'gaps' end;
  if gaps <> '{}'::jsonb and v->>'evidence_enforcement'='enforce' then
    raise exception 'Checklist evidence policy is not satisfied: %', gaps using errcode='22023';
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.execute_approved_tyre_change(p_request_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r approval_execution_requests; d jsonb; payload jsonb; result jsonb; stamp timestamptz:=clock_timestamp(); fitted uuid;
BEGIN
 IF p_operation_id IS NULL THEN RAISE EXCEPTION 'Execution operation ID is required' USING ERRCODE='22023'; END IF;
 d:=approval_private.execution_document('tyre_change',p_request_id);
 IF NOT approval_private.can_execute('tyre_change') THEN RAISE EXCEPTION 'Tyre edit permission is required to execute this request' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM approval_execution_requests WHERE id=p_request_id FOR UPDATE;
 IF r.executed_at IS NOT NULL THEN
  IF r.executed_by<>auth.uid() OR r.execution_operation_id<>p_operation_id THEN RAISE EXCEPTION 'This tyre request was already executed' USING ERRCODE='PT409'; END IF;
  RETURN r.execution_result;
 END IF;
 IF r.approval_status<>'approved' OR r.approval_outcome<>'approved' OR NOT EXISTS(SELECT 1 FROM workflow_instances WHERE id=r.approval_workflow_id AND status='approved') THEN
  RAISE EXCEPTION 'Complete approval before executing the tyre change' USING ERRCODE='42501'; END IF;
 IF NOT approval_private.source_matches('tyre_change',r.source_snapshot,d->'current_source_snapshot') THEN RAISE EXCEPTION 'Tyre fitment changed; submit a fresh request' USING ERRCODE='PT409'; END IF;
 payload:=r.payload;
 INSERT INTO approval_private.tyre_execution_permits(transaction_id,request_id,record_id)
 SELECT txid_current(),r.id,nullif(x->>'id','')::uuid FROM jsonb_array_elements(jsonb_build_array(r.source_snapshot->'source_tyre',r.source_snapshot->'destination_tyre')) x WHERE x->>'id' IS NOT NULL;
 INSERT INTO approval_private.tyre_execution_permits(transaction_id,request_id,asset_no,country,position,may_insert)
 VALUES(txid_current(),r.id,upper(btrim(r.asset_no)),r.country,upper(btrim(payload->>'position')),payload->>'action' IN ('install','replace'));
 IF payload->>'action' IN ('install','replace') THEN
  fitted:=public.apply_tyre_change(payload-'action'-'request_reason'); result:=jsonb_build_object('fitment_record_id',fitted);
  INSERT INTO approval_private.tyre_execution_permits(transaction_id,request_id,record_id) VALUES(txid_current(),r.id,fitted);
  UPDATE tyre_records SET size=coalesce(payload->>'size',size),tread_depth=coalesce(nullif(payload->>'tread_depth','')::numeric,tread_depth),photos=coalesce(nullif(payload->'photos','null'::jsonb),photos) WHERE id=fitted;
 ELSIF payload->>'action'='move' THEN result:=public.tyre_move(payload);
 ELSE
  UPDATE tyre_records SET status='Removed',removal_date=(payload->>'date')::date,km_at_removal=nullif(payload->>'km','')::numeric,removal_reason=payload->>'reason' WHERE id=(payload->>'tyre_id')::uuid;
  result:=jsonb_build_object('removed_record_id',payload->>'tyre_id');
 END IF;
 result:=jsonb_build_object('ok',true,'request_id',r.id,'status','executed','result',result,'executed_at',stamp,'operation_id',p_operation_id);
 INSERT INTO approval_private.permits VALUES(txid_current(),'tyre_change',r.id);
 UPDATE approval_execution_requests SET status='executed',executed_at=stamp,executed_by=auth.uid(),execution_operation_id=p_operation_id,execution_result=result WHERE id=r.id;
 DELETE FROM approval_private.permits WHERE transaction_id=txid_current() AND entity_type='tyre_change' AND entity_id=r.id;
 DELETE FROM approval_private.tyre_execution_permits WHERE transaction_id=txid_current() AND request_id=r.id;
 RETURN result;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.expense_building_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF upper(btrim(coalesce(NEW.country,''))) = 'UAE'
     AND upper(btrim(coalesce(NEW.asset_type,''))) IN ('BUILDINGS','BUILDING')
     AND upper(coalesce(NEW.asset_description,'')) NOT LIKE '%WORKSHOP%'
  THEN
    INSERT INTO public.expense_import_rejects
      (organisation_id, uploaded_country, detected_country, reject_reason,
       work_order_no, item_code, item_description, value_amount, source_row)
    VALUES (NEW.organisation_id, NEW.country, NULL, 'uae_building_non_workshop',
            NEW.work_order_no, NEW.item_code, NEW.item_description, NEW.line_cost, NEW.source_row);
    RETURN NULL;
  END IF;
  RETURN NEW;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.expense_cost_status_lines(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_status text DEFAULT NULL::text, p_limit integer DEFAULT NULL::integer)
 RETURNS TABLE(id uuid, country text, currency text, event_date date, issue_number text, work_order_no text, asset_code text, store_code text, site text, item_code text, item_description text, qty numeric, cost_category text, erp_amount numeric, filled_cost numeric, line_cost numeric, cost_status text, dispute_reason text, is_credit boolean, is_repair boolean, is_retread boolean, is_multi_qty boolean, loaded_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with base as (
    select p.*,
           date_trunc('hour', p.created_at) as load_at,
           coalesce(btrim(p.source_row), '') as src,
           md5(concat_ws('|', p.country, p.issue_number, p.work_order_no, p.txn_date, p.asset_code,
                         p.store_code, p.cost_center, p.item_code, p.qty, p.item_description,
                         p.value_amount, p.spare_parts_amount, p.tyre_amount, p.oil_amount,
                         p.total_amount)) as ck,
           md5(concat_ws('|', p.country, p.issue_number, p.work_order_no, p.txn_date, p.asset_code,
                         p.store_code, p.cost_center, p.item_code, p.qty, p.item_description)) as rk,
           coalesce(nullif(public._to_num(p.value_amount), 0), nullif(public._to_num(p.total_amount), 0),
                    nullif(greatest(coalesce(public._to_num(p.spare_parts_amount), 0),
                                    coalesce(public._to_num(p.tyre_amount), 0),
                                    coalesce(public._to_num(p.oil_amount), 0)), 0),
                    nullif(least(coalesce(public._to_num(p.spare_parts_amount), 0),
                                 coalesce(public._to_num(p.tyre_amount), 0),
                                 coalesce(public._to_num(p.oil_amount), 0)), 0)) as erp_amt
      from public.parts_consumption p
     where (p_country is null or p_country = 'All' or p.country = p_country)
       and (p_from is null or p.event_date >= p_from)
       and (p_to is null or p.event_date <= p_to)
  ),
  per_load as (
    select ck, load_at, count(*) as c
      from base group by ck, load_at
  ),
  prior as (
    select ck, load_at,
           coalesce(max(c) over (partition by ck order by load_at
                                 rows between unbounded preceding and 1 preceding), 0) as prior_max
      from per_load
  ),
  revisions as (
    select rk, src
      from base
     where src <> ''
     group by rk, src
    having count(distinct coalesce(value_amount, '')) > 1
        or count(distinct coalesce(tyre_amount, '') || '|' || coalesce(total_amount, '')) > 1
  ),
  marked as (
    select b.*,
           row_number() over (partition by b.ck, b.load_at order by b.id) as rn_in_load,
           pr.prior_max,
           (rv.rk is not null) as is_revision
      from base b
      join prior pr on pr.ck = b.ck and pr.load_at = b.load_at
      left join revisions rv on rv.rk = b.rk and rv.src = b.src
  ),
  classed as (
    select m.*,
           case
             when m.is_revision then 'conflicting_revision'
             when m.rn_in_load <= m.prior_max then 'cross_load_copy'
           end as dispute
      from marked m
  )
  select c.id, c.country, coalesce(c.currency, public.currency_for_country(c.country)),
         c.event_date, c.issue_number, c.work_order_no, c.asset_code, c.store_code, c.site,
         c.item_code, c.item_description, c.qty_n, c.cost_category,
         c.erp_amt, c.filled_cost, coalesce(c.line_cost, 0),
         case
           when c.dispute is not null then 'DISPUTED'
           when coalesce(c.line_cost, 0) = 0
                and (public.parts_cost_is_warranty(c.item_description)
                     or public.tyre_price_is_warranty(c.item_description)) then 'CONFIRMED_ZERO'
           when c.erp_amt is null and c.filled_cost is not null and c.filled_cost > 0 then 'ESTIMATED'
           when coalesce(c.line_cost, 0) = 0 then 'MISSING'
           else 'ACTUAL'
         end,
         c.dispute,
         coalesce(c.line_cost, 0) < 0,
         public.tyre_price_is_repair(c.item_description),
         coalesce(c.item_description, '') ~* '\m(retread|re-tread|recap|remould)',
         coalesce(c.qty_n, 0) > 1,
         c.created_at
    from classed c
   where p_status is null
      or p_status = case
           when c.dispute is not null then 'DISPUTED'
           when coalesce(c.line_cost, 0) = 0
                and (public.parts_cost_is_warranty(c.item_description)
                     or public.tyre_price_is_warranty(c.item_description)) then 'CONFIRMED_ZERO'
           when c.erp_amt is null and c.filled_cost is not null and c.filled_cost > 0 then 'ESTIMATED'
           when coalesce(c.line_cost, 0) = 0 then 'MISSING'
           else 'ACTUAL'
         end
   order by c.event_date desc nulls last, c.id
   limit case when p_limit is null or p_limit <= 0 then null else least(p_limit, 5000) end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.expense_country_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_detected text;
BEGIN
  IF NEW.work_order_no IS NULL OR NEW.country IS NULL THEN RETURN NEW; END IF;
  v_detected := CASE
    WHEN NEW.work_order_no ~* '^\s*RM' THEN 'UAE'
    WHEN NEW.work_order_no ~* '^\s*EG' THEN 'Egypt'
    WHEN NEW.work_order_no ~* '^\s*(AFKR|GCKR)' THEN 'KSA'
  END;
  IF v_detected IS NULL OR v_detected = NEW.country THEN RETURN NEW; END IF;
  INSERT INTO public.expense_import_rejects
    (organisation_id, uploaded_country, detected_country, reject_reason,
     work_order_no, item_code, item_description, value_amount, source_row)
  VALUES (NEW.organisation_id, NEW.country, v_detected, 'country_mismatch',
          NEW.work_order_no, NEW.item_code, NEW.item_description, NEW.line_cost, NEW.source_row);
  RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.expense_import_count(p_country text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_count bigint;
BEGIN
 v_org:=administration_imports.check_expense_actor(p_country);
 SELECT count(*) INTO v_count FROM public.parts_consumption WHERE organisation_id=v_org AND country=p_country;
 RETURN v_count;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.expense_reupload_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prior int;
  v_hash  text;
  v_key   text;
  v_seen  int;
begin
  if coalesce(current_setting('tp.allow_dup_expense', true), '') = 'on' then
    return new;
  end if;
  if new.created_at is not null and new.created_at < now() - interval '1 minute' then
    return new;
  end if;

  v_hash := md5(
      coalesce(new.organisation_id::text, chr(31)) || chr(30) ||
      coalesce(new.country, chr(31))               || chr(30) ||
      coalesce((new.event_date - date '1970-01-01')::text, chr(31)) || chr(30) ||
      coalesce(new.issue_number, chr(31))          || chr(30) ||
      coalesce(new.work_order_no, chr(31))         || chr(30) ||
      coalesce(new.item_code, chr(31))             || chr(30) ||
      coalesce(new.qty::text, chr(31))             || chr(30) ||
      coalesce(new.value_amount::text, chr(31))    || chr(30) ||
      coalesce(new.store_code, chr(31))            || chr(30) ||
      coalesce(new.cost_center, chr(31))
  );

  select count(*) into v_prior
  from public.parts_consumption p
  where p.reupload_hash = v_hash
    and p.created_at < now();

  if v_prior = 0 then
    return new;
  end if;

  v_key := 'tp_expdup.k' || v_hash;
  v_seen := coalesce(nullif(current_setting(v_key, true), ''), '0')::int;

  if v_seen >= v_prior then
    return new;
  end if;

  perform set_config(v_key, (v_seen + 1)::text, true);
  begin
    insert into public.expense_import_rejects
      (organisation_id, uploaded_country, detected_country, work_order_no, item_code,
       item_description, value_amount, source_row, reject_reason)
    values (new.organisation_id, new.country, new.country, new.work_order_no, new.item_code,
            new.item_description, new.value_amount::numeric, new.source_row::text, 'already_stored');
  exception when others then null;
  end;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.expire_jit_elevations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp int := 0; v_lapsed int := 0;
begin
  with ended as (
    update public.jit_elevation_requests
       set status = 'expired', updated_at = now()
     where status = 'approved' and expires_at <= now()
    returning grant_id, expires_at
  ), gone as (
    delete from public.user_access_grants g using ended e
     where g.id = e.grant_id and g.expires_at is not null and g.expires_at <= now()
    returning 1
  )
  select count(*) into v_exp from ended;

  update public.jit_elevation_requests
     set status = 'lapsed', updated_at = now()
   where status = 'pending' and created_at < now() - interval '24 hours';
  get diagnostics v_lapsed = row_count;

  return jsonb_build_object('expired', v_exp, 'lapsed', v_lapsed);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.explain_metric(p_metric_id text, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m public.metric_registry%rowtype;
  v public.metric_versions%rowtype;
  v_src text; v_cnt bigint := null; v_last timestamptz := null;
  v_has_created boolean := false; v_has_country boolean := false;
  v_lineage json := null;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_active() then raise exception 'forbidden' using errcode='42501'; end if;
  select * into m from public.metric_registry where metric_id=p_metric_id;
  if not found then return json_build_object('ok',false,'reason','unknown_metric'); end if;
  select * into v from public.metric_versions where metric_id=p_metric_id
    order by version desc limit 1;

  v_src := m.source_table;
  if v_src is not null then
    select bool_or(column_name='created_at'), bool_or(column_name='country')
      into v_has_created, v_has_country
    from information_schema.columns where table_schema='public' and table_name=v_src;
    if coalesce(v_has_created,false) then
      if coalesce(v_has_country,false) then
        execute format('select count(*), max(created_at) from public.%I where (%L::text is null or %L=''All'' or country=%L)', v_src, p_country, p_country, p_country) into v_cnt, v_last;
      else
        execute format('select count(*), max(created_at) from public.%I', v_src) into v_cnt, v_last;
      end if;
    elsif v_has_country then
      execute format('select count(*), null::timestamptz from public.%I where (%L::text is null or %L=''All'' or country=%L)', v_src, p_country, p_country, p_country) into v_cnt, v_last;
    else
      execute format('select count(*), null::timestamptz from public.%I', v_src) into v_cnt, v_last;
    end if;
  end if;

  if m.lineage_domain is not null then
    begin
      select public.get_figure_lineage(m.lineage_domain, nullif(p_country,'All'), p_from, p_to) into v_lineage;
    exception when others then v_lineage := null; end;
  end if;

  return json_build_object(
    'ok', true,
    'metric', to_jsonb(m),
    'version', case when v.metric_id is null then null else to_jsonb(v) end,
    'freshness', json_build_object(
      'source_table', m.source_table,
      'source_row_count', v_cnt,
      'last_source_update', v_last,
      'last_calculation', now(),
      'refresh_sla', m.refresh_sla),
    'lineage', v_lineage
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.extract_tyre_freetext_candidates(p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid;
  v_found int := 0;
  v_new_serials int := 0;
  v_ins int := 0;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin may run the extractor' using errcode = '42501';
  end if;
  v_org := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);

  drop table if exists _ft_rows;
  create temporary table _ft_rows on commit drop as
  select distinct
    btrim(s."Job Card No", E' \t\r\n')                                            as job_card,
    upper(btrim(coalesce(nullif(btrim(s.asset_no, E' \t\r\n'),'NULL'), s."Asset No"), E' \t\r\n')) as asset_no,
    upper(btrim(s.work_done_desc, E' \t\r\n'))                                    as wd,
    to_date(nullif(btrim(s."Job Card In Date", E' \t\r\n'),''),'DD-MM-YY')        as jc_date
  from public.ksa_country_upload_template_staging s
  where btrim(coalesce(s.srno,'NULL'), E' \t\r\n') = 'NULL'
    and btrim(coalesce(s.tire_pos,'NULL'), E' \t\r\n') = 'NULL'
    and s.work_done_desc is not null
    and (upper(s.work_done_desc) like '%TYRE%' or upper(s.work_done_desc) like '%TIRE%');

  drop table if exists _ft_pairs;
  create temporary table _ft_pairs on commit drop as
  select r.job_card, r.asset_no, r.jc_date, r.wd,
         m[1] as position_text,
         replace(m[2],' ','') as serial_no
  from _ft_rows r,
  lateral regexp_matches(
    r.wd,
    '((?:LH|RH)[A-Z]{1,3}[0-9]?)[^A-Z0-9]{0,4}([A-Z]{2,4} ?[0-9]{4,}[A-Z0-9]{0,4}|[0-9]{2}[A-Z][0-9]{6,}[A-Z0-9]{0,3})',
    'g') m
  -- a puncture repair or an air top-up is not a fitment, whatever codes the
  -- sentence happens to contain
  where r.wd ~ '(CHANG|CHANEG|REPLAC|FIX|FIT|INSTALL|NEW ONE|NEW TYRE)'
    and not (r.wd ~ '(PUNCTURE|AIR PRESSURE|FILLED AIR|INFLAT)'
             and r.wd !~ '(CHANG|CHANEG|REPLAC|NEW ONE|NEW TYRE|FIXED IN|FIX IN)');

  select count(*) into v_found from _ft_pairs;
  select count(distinct p.serial_no) into v_new_serials
    from _ft_pairs p
   where not exists (select 1 from public.tyre_records t
                      where t.country='KSA'
                        and upper(btrim(t.serial_no, E' \t\r\n')) = p.serial_no);

  if p_dry_run then
    return jsonb_build_object(
      'dry_run', true,
      'sentences_scanned', (select count(*) from _ft_rows),
      'pairs_found', v_found,
      'serials_never_seen_before', v_new_serials,
      'note', 'Nothing written. These are proposals for review, never auto-inserted tyre records.');
  end if;

  insert into public.tyre_freetext_candidates
    (organisation_id, country, job_card, asset_no, job_card_date,
     position_text, serial_no, brand_text, source_text, confidence, serial_is_new)
  select
    v_org, 'KSA', p.job_card, p.asset_no, p.jc_date,
    p.position_text, p.serial_no,
    -- a brand word sitting beside the serial, when there is one
    (select b from unnest(array['TRIANGLE','ERACLE','TEGRYS','PIRELLI','BRIDGESTONE','SAILUN',
                               'HANKOOK','ROADX','LONGMARCH','INFINITY','BLACKHAWK','FIREMAX',
                               'DOUBLE COIN','APLUS','ROADWEST']) b
      where position(b in p.wd) > 0 limit 1),
    p.wd,
    -- one position and one serial in the sentence is unambiguous; more than one
    -- pair means the reader has to decide which belongs to which
    case when (select count(*) from _ft_pairs q
                where q.job_card = p.job_card and q.wd = p.wd) = 1
         then 'high' else 'medium' end,
    not exists (select 1 from public.tyre_records t
                 where t.country='KSA'
                   and upper(btrim(t.serial_no, E' \t\r\n')) = p.serial_no)
  from _ft_pairs p
  on conflict (organisation_id, country, job_card, position_text, serial_no) do nothing;

  get diagnostics v_ins = row_count;

  return jsonb_build_object(
    'dry_run', false,
    'pairs_found', v_found,
    'candidates_created', v_ins,
    'serials_never_seen_before', v_new_serials,
    'next_step', 'Review them; a confirmed candidate becomes a tyre record, a rejected one stays as evidence of why.');
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.flag_meter_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prev numeric; v_new numeric; v_unit text;
begin
  begin
    if btrim(coalesce(NEW.asset_no,'')) = '' then return NEW; end if;
    if TG_TABLE_NAME = 'odometer_logs' then
      v_new := NEW.odometer_km; v_unit := 'km';
      if v_new is null then return NEW; end if;
      select vf.current_km into v_prev from public.vehicle_fleet vf
        where btrim(vf.asset_no) = btrim(NEW.asset_no)
          and vf.organisation_id is not distinct from NEW.organisation_id
          and (NEW.country is null or vf.country is null or lower(btrim(vf.country)) = lower(btrim(NEW.country)))
        limit 1;
      if (v_prev is not null and v_prev > 0 and v_new > v_prev * 3 and v_new > v_prev + 20000)
         or (v_prev is null and v_new > 2000000) then
        NEW.flagged := true; NEW.flagged_prev_reading := v_prev;
        NEW.flag_reason := format('Implausible reading (likely an extra digit): %s km against current %s km for asset %s. Saved, not used for the fleet odometer, pending admin review.',
          v_new, coalesce(v_prev::text, 'none'), btrim(NEW.asset_no));
        NEW.reviewed := false; NEW.reviewed_by := null; NEW.reviewed_at := null;
        return NEW;
      end if;
    elsif TG_TABLE_NAME = 'engine_hours_logs' then
      v_new := NEW.engine_hours; v_unit := 'hrs';
      if v_new is null then return NEW; end if;
      select e.engine_hours into v_prev from public.engine_hours_logs e
        where btrim(e.asset_no) = btrim(NEW.asset_no)
          and e.organisation_id is not distinct from NEW.organisation_id
          and e.engine_hours is not null
        order by e.reading_date desc nulls last, e.created_at desc limit 1;
    else return NEW; end if;
    if v_prev is not null and v_new < v_prev then
      NEW.flagged := true; NEW.flagged_prev_reading := v_prev;
      NEW.flag_reason := format('Meter regression: reading %s %s is below current %s %s for asset %s. Accepted, pending admin review.',
        v_new, v_unit, v_prev, v_unit, btrim(NEW.asset_no));
      NEW.reviewed := false; NEW.reviewed_by := null; NEW.reviewed_at := null;
    end if;
    return NEW;
  exception when others then return NEW;
  end;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.fleet_hours_by_asset(p_org uuid, p_country text, p_from date, p_to date)
 RETURNS TABLE(country text, asset_no text, hours_run numeric, readings bigint)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  with m as (
    select e.country, upper(btrim(e.asset_no)) as asset_no,
           e.reading_date as d, e.engine_hours as hm
      from public.engine_hours_logs e
     where e.organisation_id = p_org
       and e.engine_hours > 0 and e.reading_date is not null
       and e.reading_date <= current_date
       and coalesce(btrim(e.asset_no), '') <> ''
       and (p_country is null or e.country = p_country)
       and (p_from is null or e.reading_date >= p_from)
       and (p_to   is null or e.reading_date <= p_to)
  ), spans as (
    select m.country, m.asset_no,
           max(m.hm) - min(m.hm) as hours_run,
           count(*) as readings
      from m group by m.country, m.asset_no
     having count(*) > 1
  )
  select s.country, s.asset_no, s.hours_run, s.readings
    from spans s
   where s.hours_run > 0
     and s.hours_run <= 24 * greatest(1, (coalesce(p_to, current_date) - coalesce(p_from, current_date - 365)));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.fleet_km_by_asset(p_org uuid, p_country text, p_from date, p_to date)
 RETURNS TABLE(country text, asset_no text, km_run numeric, readings bigint)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  with m as (
    select t.country, upper(btrim(t.asset_no)) as asset_no,
           t.fitment_date as d, t.km_at_fitment as km
      from public.tyre_records t
     where t.organisation_id = p_org
       and t.km_at_fitment > 0 and t.fitment_date is not null
       and t.fitment_date <= current_date
       and coalesce(btrim(t.asset_no), '') <> ''
       and (p_country is null or t.country = p_country)
       and (p_from is null or t.fitment_date >= p_from)
       and (p_to   is null or t.fitment_date <= p_to)
    union all
    select t.country, upper(btrim(t.asset_no)),
           t.removal_date, t.km_at_removal
      from public.tyre_records t
     where t.organisation_id = p_org
       and t.km_at_removal > 0 and t.removal_date is not null
       and t.removal_date <= current_date
       and coalesce(btrim(t.asset_no), '') <> ''
       and (p_country is null or t.country = p_country)
       and (p_from is null or t.removal_date >= p_from)
       and (p_to   is null or t.removal_date <= p_to)
  ), spans as (
    select m.country, m.asset_no,
           max(m.km) - min(m.km) as km_run,
           count(*) as readings
      from m group by m.country, m.asset_no
     having count(*) > 1
  )
  select s.country, s.asset_no, s.km_run, s.readings
    from spans s
   where s.km_run > 0
     and s.km_run <= 30000 * greatest(1,
           ceil((coalesce(p_to, current_date) - coalesce(p_from, current_date - 365))::numeric / 30));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.fleet_tyre_km_by_asset(p_org uuid, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(country text, asset_no text, km_run numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.country,
         upper(btrim(t.asset_no)) as asset_no,
         sum(public.tyre_km_life(
               t.km_at_fitment, t.km_at_removal, t.total_km,
               coalesce(nullif(btrim(t.vehicle_type), ''), f.vehicle_type)
         ))::numeric as km_run
    from public.tyre_records t
    left join lateral (
      select vf.vehicle_type
        from public.vehicle_fleet vf
       where vf.organisation_id = t.organisation_id
         and vf.asset_no = t.asset_no
       order by (vf.country = t.country) desc
       limit 1
    ) f on true
   where t.organisation_id = p_org
     and (p_country is null or t.country = p_country)
     and coalesce(btrim(t.asset_no), '') <> ''
     and public.tyre_km_life(
           t.km_at_fitment, t.km_at_removal, t.total_km,
           coalesce(nullif(btrim(t.vehicle_type), ''), f.vehicle_type)
         ) > 0
     and coalesce(t.removal_date, t.issue_date) between coalesce(p_from, current_date - 365)
                                                    and coalesce(p_to, current_date)
   group by 1, 2
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.fx_convert(p_org uuid, p_amount numeric, p_from text, p_to text, p_on date, p_policy text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_amount is null then null
    else p_amount * public.fx_rate_for(p_org, p_from, p_to, p_on, p_policy)
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.fx_coverage(p_to text, p_from date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_policy text := coalesce((select value from public.system_config where key='fx_policy'), 'monthly_avg');
  result jsonb;
begin
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select jsonb_build_object(
    'ok', true,
    'policy', v_policy,
    'target', upper(btrim(coalesce(p_to, ''))),
    'currencies', coalesce(jsonb_agg(x order by x.currency), '[]'::jsonb),
    'complete', bool_and(x.rate is not null)
  ) into result
  from (
    select c.currency,
           public.fx_rate_for(v_org, c.currency, upper(btrim(coalesce(p_to,''))),
                              coalesce(p_to_date, current_date)) as rate
      from (select distinct currency from public.parts_consumption
             where organisation_id = v_org and currency is not null
               and (country is null
                    or (select public.is_super_admin())
                    or (select public.app_sees_all_countries())
                    or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
               and (p_from is null or event_date >= p_from)
               and (p_to_date is null or event_date <= p_to_date)) c
  ) x;

  return result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.fx_rate_for(p_org uuid, p_from text, p_to text, p_on date, p_policy text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_policy text := coalesce(nullif(p_policy, ''),
                            (select value from public.system_config where key = 'fx_policy'),
                            'monthly_avg');
  v_rate numeric;
begin
  if p_from is null or p_to is null then return null; end if;
  -- same currency is the one rate that needs no data
  if upper(btrim(p_from)) = upper(btrim(p_to)) then return 1; end if;
  if p_org is null or p_on is null then return null; end if;

  if v_policy = 'transaction' then
    -- the latest approved rate on or before the transaction date
    select r.rate into v_rate from public.currency_rates r
     where r.organisation_id = p_org and r.approved
       and upper(r.base_currency) = upper(btrim(p_from))
       and upper(r.quote_currency) = upper(btrim(p_to))
       and r.rate_date <= p_on
     order by r.rate_date desc limit 1;

  elsif v_policy = 'closing' then
    -- the latest approved rate in the month being closed
    select r.rate into v_rate from public.currency_rates r
     where r.organisation_id = p_org and r.approved
       and upper(r.base_currency) = upper(btrim(p_from))
       and upper(r.quote_currency) = upper(btrim(p_to))
       and r.rate_date <= (date_trunc('month', p_on) + interval '1 month - 1 day')::date
     order by r.rate_date desc limit 1;

  else -- monthly_avg
    select avg(r.rate) into v_rate from public.currency_rates r
     where r.organisation_id = p_org and r.approved
       and upper(r.base_currency) = upper(btrim(p_from))
       and upper(r.quote_currency) = upper(btrim(p_to))
       and r.rate_date >= date_trunc('month', p_on)::date
       and r.rate_date <  (date_trunc('month', p_on) + interval '1 month')::date;
    if v_rate is null then
      -- fall back to the most recent month that HAS an approved rate, rather
      -- than failing a whole report for one missing month
      select r.rate into v_rate from public.currency_rates r
       where r.organisation_id = p_org and r.approved
         and upper(r.base_currency) = upper(btrim(p_from))
         and upper(r.quote_currency) = upper(btrim(p_to))
         and r.rate_date <= p_on
       order by r.rate_date desc limit 1;
    end if;
  end if;

  return v_rate;  -- NULL when nothing approved covers it
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.gate_pass_blockers(p_asset_no text, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := public.app_current_org();
  v_asset text := btrim(p_asset_no);
  v_country text := NULLIF(btrim(p_country), '');
  v_ca jsonb; v_ty jsonb; v_ins jsonb; v_total int;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN
    RAISE EXCEPTION 'Not authorised.' USING errcode = '42501';
  END IF;
  IF v_asset IS NULL OR v_asset = '' THEN
    RAISE EXCEPTION 'asset_no is required.' USING errcode = '22004';
  END IF;
  IF v_country = 'All' THEN v_country := NULL; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', c.id, 'title', c.title, 'priority', c.priority,
           'status', c.status, 'root_cause', c.root_cause,
           'tyre_serial', c.tyre_serial, 'due_date', c.due_date, 'site', c.site)
         ORDER BY c.due_date NULLS LAST), '[]'::jsonb)
    INTO v_ca
  FROM public.corrective_actions c
  WHERE c.asset_no = v_asset
    AND c.priority = 'High'
    AND COALESCE(c.status, 'Open') NOT IN ('Closed', 'Resolved')
    AND (c.organisation_id IS NULL OR c.organisation_id = v_org)
    AND (v_country IS NULL OR c.country = v_country OR c.country IS NULL)
    AND (c.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(c.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', t.id, 'serial_no', t.serial_no, 'brand', t.brand,
           'risk_level', t.risk_level, 'tread_depth', t.tread_depth,
           'removal_reason', t.removal_reason, 'site', t.site)
         ORDER BY t.serial_no), '[]'::jsonb)
    INTO v_ty
  FROM (
    SELECT DISTINCT ON (tr.serial_no) tr.*
    FROM public.tyre_records tr
    WHERE tr.asset_no = v_asset
      AND (tr.organisation_id IS NULL OR tr.organisation_id = v_org)
      AND (v_country IS NULL OR tr.country = v_country OR tr.country IS NULL)
      AND (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    ORDER BY tr.serial_no, tr.created_at DESC NULLS LAST, tr.id DESC
  ) t
  WHERE t.risk_level = 'Critical';

  -- Open Critical inspections. Valid inspections.status values are
  -- Scheduled/In Progress/Done/Overdue/Cancelled — 'Done'/'Cancelled' are resolved.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', i.id, 'title', i.title, 'inspection_type', i.inspection_type,
           'severity', i.severity, 'status', i.status,
           'tyre_serial', i.tyre_serial, 'inspection_date', i.inspection_date,
           'findings', i.findings, 'site', i.site)
         ORDER BY i.inspection_date DESC NULLS LAST), '[]'::jsonb)
    INTO v_ins
  FROM public.inspections i
  WHERE i.asset_no = v_asset
    AND i.severity = 'Critical'
    AND COALESCE(i.status, '') NOT IN ('Done', 'Cancelled')
    AND (i.organisation_id IS NULL OR i.organisation_id = v_org)
    AND (v_country IS NULL OR i.country = v_country OR i.country IS NULL)
    AND (i.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(i.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));

  v_total := jsonb_array_length(v_ca) + jsonb_array_length(v_ty) + jsonb_array_length(v_ins);

  RETURN jsonb_build_object(
    'asset_no', v_asset, 'country', v_country, 'total', v_total, 'blocked', (v_total > 0),
    'corrective_actions', v_ca, 'tyres', v_ty, 'inspections', v_ins);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.generate_checklist_assignments()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  s             record;
  tpl           record;
  target        text;
  v_uid         uuid := auth.uid();
  v_org         uuid;
  v_made        integer := 0;
  v_rows        integer := 0;
  v_today       date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF v_uid IS NOT NULL THEN
    IF NOT public.app_is_elevated() THEN
      RAISE EXCEPTION 'Permission denied: elevated role required'
        USING errcode = '42501';
    END IF;

    v_org := public.app_current_org();
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'Permission denied: organisation is required'
        USING errcode = '42501';
    END IF;
  END IF;

  FOR s IN
    SELECT cs.*
      FROM public.checklist_schedules cs
     WHERE cs.active
       AND cs.next_due <= v_today
       AND (v_uid IS NULL OR cs.organisation_id = v_org)
       AND (v_uid IS NULL OR public.app_write_country_ok(cs.country))
     ORDER BY cs.next_due, cs.id
     FOR UPDATE SKIP LOCKED
  LOOP
    SELECT ct.id, ct.name, ct.country
      INTO tpl
      FROM public.checklist_templates ct
     WHERE ct.id = s.template_id
       AND ct.organisation_id = s.organisation_id;

    IF tpl.id IS NULL THEN
      CONTINUE;
    END IF;

    IF array_length(s.sites, 1) IS NOT NULL THEN
      FOREACH target IN ARRAY s.sites LOOP
        INSERT INTO public.checklist_assignments
          (organisation_id, country, schedule_id, template_id, template_name,
           site, assignee_role, due_date)
        VALUES
          (s.organisation_id, s.country, s.id, s.template_id, tpl.name,
           target, s.assignee_role, s.next_due)
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_made := v_made + v_rows;
      END LOOP;
    ELSIF array_length(s.asset_nos, 1) IS NOT NULL THEN
      FOREACH target IN ARRAY s.asset_nos LOOP
        INSERT INTO public.checklist_assignments
          (organisation_id, country, schedule_id, template_id, template_name,
           asset_no, assignee_role, due_date)
        VALUES
          (s.organisation_id, s.country, s.id, s.template_id, tpl.name,
           target, s.assignee_role, s.next_due)
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_made := v_made + v_rows;
      END LOOP;
    ELSE
      INSERT INTO public.checklist_assignments
        (organisation_id, country, schedule_id, template_id, template_name,
         assignee_role, due_date)
      VALUES
        (s.organisation_id, s.country, s.id, s.template_id, tpl.name,
         s.assignee_role, s.next_due)
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_made := v_made + v_rows;
    END IF;

    UPDATE public.checklist_schedules
       SET next_due = CASE s.cadence
                        WHEN 'daily'   THEN s.next_due + 1
                        WHEN 'weekly'  THEN s.next_due + 7
                        WHEN 'monthly' THEN
                          (s.next_due + interval '1 month')::date
                        ELSE s.next_due
                      END,
           active = CASE
                      WHEN s.cadence = 'once' THEN false
                      ELSE active
                    END
     WHERE id = s.id;
  END LOOP;

  UPDATE public.checklist_assignments ca
     SET status = 'overdue'
   WHERE ca.status = 'pending'
     AND ca.due_date < v_today
     AND (v_uid IS NULL OR ca.organisation_id = v_org)
     AND (v_uid IS NULL OR public.app_write_country_ok(ca.country));

  RETURN v_made;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.generate_po_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN 'PO-' || to_char(now(), 'YYYY') || '-' ||
         lpad(nextval('po_seq')::text, 5, '0');
END; $function$;
