CREATE OR REPLACE FUNCTION public.get_accident_audit(p_accident_id uuid)
 RETURNS TABLE(id uuid, accident_id uuid, changed_by uuid, actor_name text, changed_at timestamp with time zone, action text, old_values jsonb, new_values jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT a.id, a.accident_id, a.changed_by,
         COALESCE(p.full_name, p.username, 'System') AS actor_name,
         a.changed_at, a.action, a.old_values, a.new_values
    FROM public.accident_audit_log a
    LEFT JOIN public.profiles p ON p.id = a.changed_by
   WHERE a.accident_id = p_accident_id
     -- Mirrors audit_log_select_case_readers: the parent accident is visible to
     -- me, under accidents' own org / country / site / active predicates copied
     -- verbatim from the live policies. is_admin_or_above() is excluded on
     -- purpose: get_my_role() returns Title Case while that helper compares
     -- lowercase, so it is false for everyone today, and it carries no org
     -- scoping - honouring it would arm a cross-org widening later.
     AND EXISTS (
          SELECT 1 FROM public.accidents acc
           WHERE acc.id = p_accident_id
             AND public.app_is_active()
             AND (acc.organisation_id = public.app_current_org()
                  OR public.is_super_admin())
             AND (acc.country IS NULL
                  OR public.is_super_admin()
                  OR public.app_sees_all_countries()
                  OR lower(btrim(acc.country)) = ANY (COALESCE(public.app_country_scope(), '{}'::text[])))
             AND (acc.site IS NULL
                  OR btrim(acc.site) = ''
                  OR public.app_sees_all_sites()
                  OR upper(btrim(acc.site)) = ANY (COALESCE(public.app_site_scope(), '{}'::text[])))
        )
   ORDER BY a.changed_at DESC
   LIMIT 100;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_accident_case_kpis(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scoped as (
    select a.id, a.case_status, a.status, a.closure_level,
           a.reopened_flag, a.is_reopened, a.reopen_count,
           a.created_at, a.incident_date, a.release_date
      from public.accidents a
     where (p_country is null or a.country = p_country)
       and (p_from is null
            or coalesce(a.incident_date, a.created_at::date) >= p_from)
       and (p_to is null
            or coalesce(a.incident_date, a.created_at::date) <= p_to)
  ),
  flagged as (
    select s.*,
      -- isGenuinelyClosed(record)
      (lower(coalesce(s.case_status, '')) = 'closed'
       or lower(coalesce(s.status, '')) = 'closed'
       or lower(coalesce(s.closure_level, '')) = 'fully_closed') as genuinely_closed,
      -- wasReopened(record): reopened_flag OR is_reopened (the permanent audit
      -- twin of the JS `reopened` field) OR case_status='reopened' OR reopen_count>0
      (coalesce(s.reopened_flag, false)
       or coalesce(s.is_reopened, false)
       or lower(coalesce(s.case_status, '')) = 'reopened'
       or coalesce(s.reopen_count, 0) > 0) as reopened
    from scoped s
  ),
  classified as (
    select f.*,
      -- isOpenCase(record): not genuinely closed AND not a terminal status
      -- (TERMINAL_STATUSES = closed | cancelled_duplicate); blank status = open.
      (not f.genuinely_closed
       and lower(coalesce(f.case_status, ''))
             <> all (array['closed','cancelled_duplicate'])) as open_case
    from flagged f
  ),
  -- Time-to-close over genuinely closed cases with a timeable span. The close
  -- stamp is an approved fully_closed closure review's reviewed_at, else the
  -- release_date (only real columns are referenced).
  closable as (
    select c.id,
      coalesce(c.created_at, c.incident_date::timestamptz) as start_ts,
      coalesce(
        (select max(r.reviewed_at)
           from public.accident_closure_reviews r
          where r.accident_id = c.id
            and r.level = 'fully_closed'
            and r.decision = 'approved'),
        c.release_date::timestamptz
      ) as end_ts
    from classified c
    where c.genuinely_closed
  ),
  timed as (
    select extract(epoch from (end_ts - start_ts)) / 86400.0 as days
      from closable
     where start_ts is not null and end_ts is not null and end_ts >= start_ts
  ),
  -- SLA breach over the SLA instances of the in-scope cases. An instance is
  -- TRACKED only if it carries a due date; SATISFIED (cannot breach) when its
  -- state is met/cancelled or it carries a completion stamp; BREACHED when the
  -- engine already marked it, its state is breached, or its due date has passed
  -- while unsatisfied. Un-tracked instances are excluded entirely (not "0% - fine").
  sla as (
    select i.due_at, i.state, i.completed_at, coalesce(i.breached, false) as breached
      from public.accident_sla_instances i
     where i.accident_id in (select id from classified)
       and i.due_at is not null
  ),
  sla_calc as (
    select
      count(*)::int as tracked,
      count(*) filter (
        where breached
           or lower(coalesce(state, '')) = 'breached'
           or (lower(coalesce(state, '')) <> all (array['met','cancelled'])
               and completed_at is null
               and due_at < now())
      )::int as breached
    from sla
  )
  select jsonb_build_object(
    'total',    (select count(*)::int from classified),
    'open',     (select count(*) filter (where open_case)::int from classified),
    'closed',   (select count(*) filter (where genuinely_closed)::int from classified),
    'reopened', (select count(*) filter (where reopened)::int from classified),

    'avg_time_to_close',
      (select case when count(*) = 0 then null
                   else round(avg(days)::numeric, 1) end from timed),
    'median_time_to_close',
      (select case when count(*) = 0 then null
                   else round(percentile_cont(0.5) within group (order by days)::numeric, 1)
              end from timed),
    'longest_time_to_close',
      (select case when count(*) = 0 then null
                   else round(max(days)::numeric, 1) end from timed),
    'time_to_close_measured', (select count(*)::int from timed),

    'sla_tracked',  (select tracked  from sla_calc),
    'sla_breached', (select breached from sla_calc),
    'sla_breach_rate',
      (select case when tracked = 0 then null
                   else round(breached::numeric / tracked, 4) end from sla_calc),

    'reopen_rate',
      (select case when count(*) = 0 then null
                   else round(count(*) filter (where reopened)::numeric / count(*), 4)
              end from classified)
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_accident_case_status_breakdown(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scoped as (
    select a.case_status, a.workflow_stage
      from public.accidents a
     where (p_country is null or a.country = p_country)
  ),
  status_rows as (
    select lower(btrim(case_status)) as token, count(*)::int as value
      from scoped
     where case_status is not null and btrim(case_status) <> ''
     group by lower(btrim(case_status))
  ),
  status_ordered as (
    select token, value
      from status_rows
     order by value desc, token asc
  ),
  stage_rows as (
    select coalesce(nullif(btrim(workflow_stage), ''), 'unrecorded') as stage,
           count(*)::int as value
      from scoped
     group by coalesce(nullif(btrim(workflow_stage), ''), 'unrecorded')
     order by count(*) desc, 1 asc
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object('token', token, 'value', value))
                        from status_ordered), '[]'::jsonb),
    'by_stage', coalesce((select jsonb_agg(jsonb_build_object('stage', stage, 'value', value))
                            from stage_rows), '[]'::jsonb),
    'total', (select count(*)::int from scoped),
    'distinct', (select count(*)::int from status_rows),
    'unrecorded', (select count(*)::int from scoped
                    where case_status is null or btrim(case_status) = ''),
    'top', (select jsonb_build_object('token', token, 'value', value)
              from status_ordered limit 1)
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_accident_portal_snapshot(p_token text, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_share       public.accident_portal_shares%rowtype;
  v_acc         public.accidents%rowtype;
  v_workstreams jsonb;
  v_claim       jsonb;
begin
  if p_token is null or btrim(p_token) = '' then
    return jsonb_build_object('ok', false, 'reason', 'invalid');
  end if;

  select * into v_share
    from public.accident_portal_shares
   where token = p_token;

  -- Unknown token = invalid; explicitly deactivated = revoked; past expiry = expired.
  if v_share.id is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid');
  end if;
  if not v_share.active then
    return jsonb_build_object('ok', false, 'reason', 'revoked');
  end if;
  if v_share.expires_at is not null and v_share.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  -- Password gate (bcrypt), only when the link carries one.
  if v_share.password_hash is not null then
    if p_password is null or btrim(p_password) = ''
       or not public.share_password_ok('accident_portal', v_share.id, p_password, v_share.password_hash) then
      return jsonb_build_object('ok', false, 'reason', 'password');
    end if;
  end if;

  -- The case, scoped ONLY by the org carried on the token row.
  select * into v_acc
    from public.accidents a
   where a.id = v_share.accident_id
     and a.organisation_id = v_share.organisation_id;

  if v_acc.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unavailable');
  end if;

  -- Record the view (best-effort, never blocks the snapshot).
  begin
    update public.accident_portal_shares
       set last_viewed_at = now(), view_count = view_count + 1
     where id = v_share.id;
  exception when others then null;
  end;

  -- Per-workstream status map: {workstream_key: status}. No owners, notes or PII.
  select coalesce(
           jsonb_object_agg(w.workstream_key, w.status)
             filter (where w.workstream_key is not null),
           '{}'::jsonb)
    into v_workstreams
    from public.accident_case_workstreams w
   where w.accident_id = v_share.accident_id;

  -- Claim STATUS summary only (latest claim). Decision token + reference identifiers.
  -- DELIBERATELY no deductible / approved_amount / settlement figures.
  select jsonb_build_object(
           'decision',             c.decision,
           'claim_no',             c.claim_no,
           'insurer',              c.insurer,
           'insurance_applicable', c.insurance_applicable,
           'claim_registered_date', c.claim_registered_date)
    into v_claim
    from public.accident_insurance_claims c
   where c.accident_id = v_share.accident_id
   order by c.created_at desc, c.id desc
   limit 1;

  return jsonb_build_object(
    'ok',             true,
    'reference_no',   v_acc.reference_no,
    'case_no',        v_acc.case_no,
    'incident_date',  v_acc.incident_date,
    'status',         v_acc.status,
    'workflow_stage', v_acc.workflow_stage,
    'case_status',    v_acc.case_status,
    'severity',       v_acc.severity,
    'workstreams',    v_workstreams,
    'claim',          coalesce(v_claim, jsonb_build_object('decision', 'not_required')),
    'generated_at',   now()
  );
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_accident_workstream_bottleneck(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with scoped as (
    select w.accident_id, w.workstream_key, lower(btrim(w.status)) as status
      from public.accident_case_workstreams w
     where (p_country is null or w.country = p_country)
  ),
  stalled as (
    -- Not satisfied: a real, non-empty status that is not in the satisfied set,
    -- carrying a known workstream key (WORKSTREAM_SATISFIED = completed |
    -- not_required | cancelled; blank status is not counted - it is "no row set").
    select accident_id, workstream_key
      from scoped
     where status is not null and status <> ''
       and status <> all (array['completed','not_required','cancelled'])
       and workstream_key is not null and btrim(workstream_key) <> ''
  ),
  by_key as (
    select workstream_key as key, count(distinct accident_id)::int as cases
      from stalled
     group by workstream_key
     order by count(distinct accident_id) desc, workstream_key asc
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'cases', cases))
                        from by_key), '[]'::jsonb),
    -- measured = at least one workstream row exists in scope (matches the JS
    -- rows.length === 0 -> measured:false short-circuit).
    'measured', (select count(*) > 0 from scoped),
    'stalled_cases', (select count(distinct accident_id)::int from stalled),
    'top', (select jsonb_build_object('key', key, 'cases', cases)
              from by_key limit 1)
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_ai_tyre_labelled_findings(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 5000)
 RETURNS TABLE(job_id uuid, inspection_id uuid, asset_no text, tyre_position text, model_version text, prompt_version text, review_status text, reviewer_note text, reviewed_at timestamp with time zone, assessable boolean, recommendation text, defects jsonb, photo_ref text, cost_usd numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
 select j.id, j.inspection_id, i.asset_no, j.tyre_position, j.model_version, j.prompt_version,
        j.review_status, j.reviewer_note, j.reviewed_at,
        case when j.analysis ? 'assessable' then (j.analysis ->> 'assessable')::boolean end,
        j.analysis ->> 'recommendation', coalesce(j.analysis -> 'defects', '[]'::jsonb), j.photo_ref, j.cost_usd
   from public.ai_tyre_inspection_jobs j
   left join public.inspections i on i.id = j.inspection_id
  where j.status = 'completed' and coalesce(j.review_status, 'unreviewed') <> 'unreviewed'
    and (lower(coalesce(public.get_my_role(), '')) in ('admin', 'manager', 'director', 'maintenance supervisor')
         or public.is_super_admin())
    and (p_from is null or j.reviewed_at >= p_from::timestamptz)
    and (p_to is null or j.reviewed_at < (p_to + 1)::timestamptz)
  order by j.reviewed_at desc nulls last, j.id
  limit least(greatest(coalesce(p_limit, 5000), 1), 20000)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_ai_tyre_review_feedback(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(model_version text, prompt_version text, jobs bigint, completed bigint, failed bigint, reviewed bigint, accepted bigint, rejected bigint, corrected bigint, unreviewed bigint, with_reviewer_note bigint, known_cost_usd numeric, unpriced_jobs bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
 select coalesce(j.model_version, 'unknown'), coalesce(j.prompt_version, 'unversioned'),
        count(*),
        count(*) filter (where j.status = 'completed'),
        count(*) filter (where j.status = 'failed'),
        count(*) filter (where j.review_status <> 'unreviewed'),
        count(*) filter (where j.review_status = 'accepted'),
        count(*) filter (where j.review_status = 'rejected'),
        count(*) filter (where j.review_status = 'corrected'),
        count(*) filter (where j.status = 'completed' and j.review_status = 'unreviewed'),
        count(*) filter (where j.review_status <> 'unreviewed' and coalesce(btrim(j.reviewer_note), '') <> ''),
        coalesce(sum(j.cost_usd), 0),
        count(*) filter (where j.cost_usd is null and j.status in ('completed', 'failed') and j.provider_attempts > 0)
   from public.ai_tyre_inspection_jobs j
  where (lower(coalesce(public.get_my_role(), '')) in ('admin', 'manager', 'director', 'maintenance supervisor')
         or public.is_super_admin())
    and (p_from is null or j.created_at >= p_from::timestamptz)
    and (p_to is null or j.created_at < (p_to + 1)::timestamptz)
  group by 1, 2
  order by 3 desc
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_alert_inbox()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_items jsonb := '[]'::jsonb;
  v_sources jsonb;
  r record;
  v_newest date;
  v_scan record;
  v_chk jsonb;
  v_failing text[];
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the alert inbox' using errcode = '42501';
  end if;

  select count(*) n, min(alerted_at) f, max(alerted_at) l,
         count(*) filter (where alerted_at >= now() - interval '30 days') n30
    into r from public.sentry_alert_log;
  if r.n > 0 then
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', 'crash|fatal', 'source', 'crash', 'severity', 'critical',
      'title', r.n || ' fatal Android app crashes',
      'detail', 'Last on ' || to_char(r.l at time zone 'Asia/Riyadh', 'DD Mon') ||
                case when r.n30 = 0 then '. None since.' else '. ' || r.n30 || ' in the last 30 days.' end ||
                ' The same crashes also sit in the error log as critical and are shown once here.',
      'affected', 'Phones, version not recorded', 'first_at', r.f, 'last_at', r.l, 'count', r.n, 'groups', r.n));
  end if;

  for r in
    select severity, count(*) n, min(created_at) f, max(created_at) l,
           count(distinct public.system_log_group_key(source, message, error_fingerprint)) g,
           mode() within group (order by public.system_log_group_key(source, message, error_fingerprint)) top_key
    from public.system_logs
    where not resolved and lower(coalesce(source, '')) <> 'sentry'
    group by severity
  loop
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', 'errors|' || coalesce(r.severity, 'info'), 'source', 'error_log',
      'severity', case r.severity when 'critical' then 'critical' when 'error' then 'medium' when 'warning' then 'low' else 'info' end,
      'title', r.n || ' unresolved ' || case r.severity when 'error' then 'page errors' when 'warning' then 'warnings'
                                                       when 'critical' then 'critical errors' else 'routine info rows' end,
      'detail', 'Most common: ' || coalesce(split_part(r.top_key, '|', 2), 'N/A'),
      'affected', case r.severity when 'error' then 'Web users' else 'Nobody blocked' end,
      'first_at', r.f, 'last_at', r.l, 'count', r.n, 'groups', r.g));
  end loop;

  for r in
    select n.src, n.last_data_date, n.notified_at, f.table_name, f.date_column, f.label
    from public.upload_gap_notices n
    left join public.upload_feeds f on f.src = n.src
    where n.notified_at >= now() - interval '30 days'
  loop
    v_newest := null;
    if r.table_name is not null then
      begin
        execute format('select max(%I)::date from public.%I', r.date_column, r.table_name) into v_newest;
      exception when others then v_newest := null;
      end;
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', 'upload|' || r.src || '|' || r.last_data_date, 'source', 'upload_gap',
      'severity', case when r.src in ('job_cards','expenses') then 'medium' else 'low' end,
      'title', coalesce(r.label, r.src) || ' stopped arriving after ' || to_char(r.last_data_date, 'DD Mon'),
      'detail', case when v_newest is null then 'Newest data could not be checked.'
                     when v_newest > r.last_data_date then 'Newer data has arrived since. Latest is dated ' || to_char(v_newest, 'DD Mon') || '.'
                     else 'No newer data yet.' end,
      'affected', coalesce(r.label, r.src) || ' reports',
      'first_at', r.notified_at, 'last_at', r.notified_at, 'count', 1, 'groups', 1,
      'recovered', coalesce(v_newest > r.last_data_date, false), 'newest_data', v_newest));
  end loop;

  select ran_at, result, failing into v_scan from public.security_scan_runs order by ran_at desc limit 1;
  v_failing := v_scan.failing;
  if v_scan.ran_at is not null then
    for v_chk in select c from jsonb_array_elements(coalesce(v_scan.result->'checks', '[]'::jsonb)) c
                 where c->>'status' = 'fail' or (c->>'id') = any(coalesce(v_failing, '{}'))
    loop
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'key', 'security|' || (v_chk->>'id'), 'source', 'security',
        'severity', case v_chk->>'severity' when 'critical' then 'critical' when 'high' then 'high'
                                            when 'medium' then 'medium' else 'low' end,
        'title', v_chk->>'title',
        'detail', coalesce((select string_agg(x, ', ') from jsonb_array_elements_text(v_chk->'items') x), '') ||
                  coalesce('. Fix: ' || (v_chk->>'fix'), ''),
        'affected', 'Whole platform', 'first_at', v_scan.ran_at, 'last_at', v_scan.ran_at,
        'count', coalesce((v_chk->>'count')::int, 1), 'groups', 1));
    end loop;
  end if;

  for r in select id, source, severity, message, created_at from public.trust_alerts where status = 'open' loop
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', 'trust|' || r.id, 'source', 'trust',
      'severity', case r.severity when 'critical' then 'high' when 'warning' then 'medium' else 'low' end,
      'title', left(r.message, 160), 'detail', 'Data trust check: ' || coalesce(r.source, 'N/A'),
      'affected', 'Reports using this data', 'first_at', r.created_at, 'last_at', r.created_at, 'count', 1, 'groups', 1));
  end loop;

  for r in select id, title, severity, status, started_at from public.platform_incidents where status <> 'resolved' loop
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', 'incident|' || r.id, 'source', 'incident',
      'severity', case r.severity when 'sev1' then 'critical' when 'sev2' then 'high' else 'medium' end,
      'title', r.title, 'detail', 'Incident is ' || r.status,
      'affected', 'See the incident', 'first_at', r.started_at, 'last_at', r.started_at, 'count', 1, 'groups', 1));
  end loop;

  select coalesce(jsonb_agg(i || jsonb_build_object('state', case
            when s.dedup_key is null then 'new'
            when s.state = 'snoozed' and s.snoozed_until <= now() then 'new'
            else s.state end,
          'owner_id', s.owner_id,
          'owner_name', (select coalesce(nullif(p.full_name, ''), public.mask_email_for_console(p.email)) from public.profiles p where p.id = s.owner_id),
          'snoozed_until', s.snoozed_until, 'acknowledged_at', s.acknowledged_at, 'resolved_at', s.resolved_at,
          'note', s.note)), '[]'::jsonb)
    into v_items
    from jsonb_array_elements(v_items) i
    left join public.alert_inbox_state s on s.dedup_key = i->>'key';

  select jsonb_build_object(
    'error_log', (select jsonb_build_object('unresolved', count(*) filter (where not resolved),
                   'critical', count(*) filter (where not resolved and severity = 'critical'),
                   'routine', count(*) filter (where not resolved and severity in ('warning','info'))) from public.system_logs),
    'crash', (select jsonb_build_object('total', count(*), 'last_30d', count(*) filter (where alerted_at >= now() - interval '30 days'),
                   'last_at', max(alerted_at)) from public.sentry_alert_log),
    'upload_gap', (select jsonb_build_object('total', count(*), 'last_30d', count(*) filter (where notified_at >= now() - interval '30 days')) from public.upload_gap_notices),
    'security', (select jsonb_build_object('ran_at', ran_at, 'failing', coalesce(array_length(failing, 1), 0),
                   'critical', critical, 'high', high, 'medium', medium, 'low', low)
                 from public.security_scan_runs order by ran_at desc limit 1),
    'trust', (select jsonb_build_object('open', count(*) filter (where status = 'open'),
                   'resolved', count(*) filter (where status <> 'open'), 'last_resolved_at', max(created_at) filter (where status <> 'open')) from public.trust_alerts),
    'incidents', (select jsonb_build_object('open', count(*) filter (where status <> 'resolved'), 'ever', count(*)) from public.platform_incidents),
    'rules', (select jsonb_build_object('total', count(*), 'active', count(*) filter (where active)) from public.alert_thresholds)
  ) into v_sources;

  return jsonb_build_object('ok', true, 'generated_at', now(), 'sources', v_sources, 'items', v_items);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_asset_disposal_fleet_baseline(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_out jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with d as (
    select asset_no from public.asset_disposals
    where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  cards as (
    select w.asset_no, (d.asset_no is not null) as on_list, w.breakdown_hours, w.work_type,
           case when w.opened_at between '2015-01-01' and now() then w.opened_at
                when w.completed_at between '2015-01-01' and now() then w.completed_at end as work_at
    from public.work_orders w
    left join d on d.asset_no = w.asset_no
    where w.organisation_id = v_org and (p_country is null or w.country = p_country) and (w.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(w.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  per as (
    select asset_no, on_list,
           count(*) cards,
           count(*) filter (where coalesce(breakdown_hours,0) > 0) failures,
           sum(breakdown_hours) filter (where breakdown_hours <= 24*90) hrs,
           count(*) filter (where work_type = 'Preventive Maintenance') pm,
           min(work_at) f, max(work_at) l
    from cards group by 1,2
  ),
  spend as (
    select (d.asset_no is not null) on_list,
           count(distinct w.asset_no) assets, sum(p.line_cost) spend
    from public.parts_consumption p
    join public.work_orders w
      on w.work_order_no = p.work_order_no and w.organisation_id = v_org
     and (p_country is null or w.country = p_country) and (w.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(w.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    left join d on d.asset_no = w.asset_no
    where p.organisation_id = v_org and (p_country is null or p.country = p_country) and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    group by 1
  ),
  side as (
    select p.on_list,
           count(*)::int assets,
           sum(p.cards)::int cards,
           sum(p.failures)::int failures,
           round(sum(p.hrs)) breakdown_hours,
           case when sum(p.cards) > 0
                then round(100.0 * sum(p.pm) / sum(p.cards), 1) end preventive_share_pct,
           round(avg(case when p.l > p.f and (p.l::date - p.f::date) >= 90
                          then p.failures * 365.0 / (p.l::date - p.f::date) end)::numeric, 2)
             avg_failures_per_year,
           round(avg(case when p.l > p.f and (p.l::date - p.f::date) >= 90
                          then greatest(0, 100.0 - (100.0 * p.hrs / ((p.l::date - p.f::date) * 24))) end)::numeric, 1)
             avg_availability_pct,
           case when count(*) > 0 then round(sum(p.hrs) / count(*)) end breakdown_hours_per_asset,
           (select s.spend from spend s where s.on_list = p.on_list) spend,
           (select case when s.assets > 0 then round(s.spend / s.assets) end
              from spend s where s.on_list = p.on_list) spend_per_asset
    from per p group by p.on_list
  )
  select jsonb_build_object(
    'ok', true,
    'country', p_country,
    'on_list',  (select to_jsonb(s) - 'on_list' from side s where s.on_list),
    'rest_of_fleet', (select to_jsonb(s) - 'on_list' from side s where not s.on_list),
    -- Machines on the list are largely parked, and a machine standing still
    -- cannot fail, so their failures-per-year reads lower than the fleet's.
    -- Breakdown hours per asset is the measure idleness does not flatter.
    'idle_confound', true,
    'note', 'Failures per year is depressed for parked machines. Compare breakdown hours per asset instead.'
  ) into v_out;

  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_asset_disposal_register(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_rows jsonb;
  v_totals jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with d as (
    select * from public.asset_disposals
    where organisation_id = v_org and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  joined as (
    select
      d.*,
      f.asset_no          is not null as in_register,
      f.status            as fleet_status,
      f.site              as fleet_site,
      f.vehicle_type      as fleet_vehicle_type,
      f.make              as fleet_make,
      f.model             as fleet_model,
      f.current_km        as fleet_current_km,
      f.model_year        as fleet_model_year,
      f.chassis_no        as chassis_no,
      f.registration_no   as registration_no,
      jc.job_cards,
      jc.last_job_card,
      jc.first_job_card,
      sp.spend,
      ty.tyres_total,
      ty.tyres_active,
      ty.serials
    from d
    left join lateral (
      select f.* from public.vehicle_fleet f
      where f.organisation_id = v_org and f.asset_no = d.asset_no
      order by (f.country = d.country) desc, f.country
      limit 1
    ) f on true
    left join lateral (
      select count(*)::int as job_cards,
             max(w.opened_at)::date as last_job_card,
             min(w.opened_at)::date as first_job_card
      from public.work_orders w
      where w.organisation_id = v_org and w.asset_no = d.asset_no
        and (d.country is null or w.country = d.country)
    ) jc on true
    left join lateral (
      select round(sum(p.line_cost)) as spend
      from public.parts_consumption p
      join public.work_orders w on w.work_order_no = p.work_order_no
      where w.organisation_id = v_org and w.asset_no = d.asset_no
        and (d.country is null or w.country = d.country)
    ) sp on true
    left join lateral (
      select count(*)::int as tyres_total,
             count(*) filter (where t.status = 'Active')::int as tyres_active,
             coalesce(jsonb_agg(jsonb_build_object(
               'serial',   t.serial_no,
               'position', coalesce(nullif(btrim(t.tyre_position),''), t.position),
               'brand',    t.brand,
               'size',     t.size,
               'fitted',   t.issue_date,
               'km',       t.total_km
             ) order by t.tyre_position) filter (where t.status = 'Active'), '[]'::jsonb) as serials
      from public.tyre_records t
      where t.organisation_id = v_org and t.asset_no = d.asset_no
        and (d.country is null or t.country = d.country)
    ) ty on true
  )
  select
    coalesce(jsonb_agg(to_jsonb(j) order by j.disposition, j.asset_type, j.asset_no), '[]'::jsonb),
    jsonb_build_object(
      'assets',            count(*),
      'to_scrap',          count(*) filter (where j.disposition = 'scrap'),
      'to_sell',           count(*) filter (where j.disposition = 'sell'),
      'in_register',       count(*) filter (where j.in_register),
      -- The finding worth reporting: a machine the committee has written off is
      -- still counted as live fleet until somebody changes its status.
      'still_active',      count(*) filter (where j.fleet_status = 'Active'),
      'not_in_register',   count(*) filter (where not j.in_register),
      'approved',          count(*) filter (where j.status = 'approved'),
      'disposed',          count(*) filter (where j.status = 'disposed'),
      'job_cards',         coalesce(sum(j.job_cards), 0),
      'lifetime_spend',    coalesce(sum(j.spend), 0),
      'active_tyres',      coalesce(sum(j.tyres_active), 0),
      -- NULL, not 0, when nobody has valued anything: an unvalued fleet and a
      -- worthless one are different statements.
      'estimated_value',   sum(j.estimated_value),
      'sale_proceeds',     sum(j.sale_proceeds)
    )
  into v_rows, v_totals
  from joined j;

  return jsonb_build_object(
    'ok', true,
    'country', p_country,
    'rows', v_rows,
    'totals', v_totals
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_asset_disposal_reliability(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_out jsonb;
  v_totals jsonb;
  -- A card open longer than this is a parked machine, not a breakdown event.
  c_parked_hours constant numeric := 24 * 90;
  -- The window in which a business date is believable at all.
  c_min_date constant timestamptz := '2015-01-01';
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with d as (
    select asset_no, country, asset_type, model_year, disposition
    from public.asset_disposals
    where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  cards as (
    select d.asset_no, d.asset_type, w.work_order_no, w.work_type, w.status,
           w.breakdown_hours,
           -- opened_at where believable, else completed_at. created_at is only
           -- when the row was uploaded (all of these landed in Jul-Aug 2026) so
           -- it can never stand in for when the work happened.
           case
             when w.opened_at between c_min_date and now() then w.opened_at
             when w.completed_at between c_min_date and now() then w.completed_at
           end as work_at
    from d
    join public.work_orders w
      on w.organisation_id = v_org and w.asset_no = d.asset_no
     and (d.country is null or w.country = d.country)
  ),
  per_asset as (
    select
      c.asset_no,
      count(*)::int                                                          job_cards,
      count(*) filter (where c.work_at is not null)::int                     dated_cards,
      count(c.breakdown_hours)::int                                          hours_cards,
      round(sum(c.breakdown_hours))                                          breakdown_hours_recorded,
      round(sum(c.breakdown_hours) filter (where c.breakdown_hours <= c_parked_hours))
                                                                             breakdown_hours,
      count(*) filter (where c.breakdown_hours > c_parked_hours)::int        parked_cards,
      round(sum(c.breakdown_hours) filter (where c.breakdown_hours > c_parked_hours))
                                                                             parked_hours,
      round(max(c.breakdown_hours))                                          longest_card_hours,
      -- A failure is a card that stopped the machine: it carries breakdown
      -- hours above zero. Type is recorded too but is not the test - the ERP
      -- files most real breakdowns as 'Repair', so counting only 'Emergency'
      -- would find 167 failures where there are far more.
      count(*) filter (where coalesce(c.breakdown_hours,0) > 0)::int         failures,
      count(*) filter (where coalesce(c.breakdown_hours,0) > 0
                         and c.work_at is not null)::int                     dated_failures,
      count(*) filter (where c.work_type = 'Emergency')::int                 emergency_cards,
      count(*) filter (where c.work_type = 'Preventive Maintenance')::int    preventive_cards,
      count(*) filter (where c.work_type = 'Repair')::int                    repair_cards,
      min(c.work_at)                                                         first_dated,
      max(c.work_at)                                                         last_dated,
      min(c.work_at) filter (where coalesce(c.breakdown_hours,0) > 0)        first_failure,
      max(c.work_at) filter (where coalesce(c.breakdown_hours,0) > 0)        last_failure
    from cards c group by c.asset_no
  ),
  spend_year as (
    select d.asset_no, extract(year from p.event_date)::int yr, sum(p.line_cost) cost
    from d
    join public.work_orders w
      on w.organisation_id = v_org and w.asset_no = d.asset_no
     and (d.country is null or w.country = d.country)
    join public.parts_consumption p
      on p.work_order_no = w.work_order_no and p.organisation_id = v_org
    where p.event_date is not null
    group by 1,2
  ),
  spend_roll as (
    select asset_no,
           jsonb_object_agg(yr::text, round(cost) order by yr) by_year,
           round(sum(cost)) total_spend
    from spend_year group by asset_no
  ),
  calc as (
    select
      a.*,
      s.by_year, s.total_spend,
      -- Observed span: only the dated cards can define it.
      case when a.first_dated is not null and a.last_dated is not null
           then greatest(1, (a.last_dated::date - a.first_dated::date))::numeric end observed_days,
      case when a.last_dated is not null
           then (current_date - a.last_dated::date)::int end idle_days
    from per_asset a left join spend_roll s using (asset_no)
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'asset_no',                 c.asset_no,
      'job_cards',                c.job_cards,
      'dated_cards',             c.dated_cards,
      'date_coverage_pct',        case when c.job_cards > 0
                                       then round(100.0 * c.dated_cards / c.job_cards, 1) end,
      'breakdown_hours',          c.breakdown_hours,
      'breakdown_hours_recorded', c.breakdown_hours_recorded,
      'parked_cards',             c.parked_cards,
      'parked_hours',             c.parked_hours,
      'longest_card_hours',       c.longest_card_hours,
      'failures',                 c.failures,
      'dated_failures',           c.dated_failures,
      'emergency_cards',          c.emergency_cards,
      'preventive_cards',         c.preventive_cards,
      'repair_cards',             c.repair_cards,
      -- Running to failure: how little of the work was planned. NULL, not 0,
      -- when there is no work to take a share of.
      'preventive_share_pct',     case when c.job_cards > 0
                                       then round(100.0 * c.preventive_cards / c.job_cards, 1) end,
      'first_seen',               c.first_dated::date,
      'last_seen',                c.last_dated::date,
      'observed_days',            c.observed_days,
      'idle_days',                c.idle_days,
      -- MTBF: mean calendar gap between dated failures. Needs at least two, or
      -- there is no interval to average - one failure returns NULL, not zero.
      'mtbf_days',                case when c.dated_failures >= 2
                                        and c.first_failure is not null
                                        and c.last_failure > c.first_failure
                                       then round((c.last_failure::date - c.first_failure::date)::numeric
                                                  / (c.dated_failures - 1), 1) end,
      'failures_per_year',        case when c.observed_days >= 90 and c.dated_failures > 0
                                       then round(c.dated_failures * 365.0 / c.observed_days, 2) end,
      -- Availability over the observed span, parked cards excluded so a machine
      -- in the yard does not read as 0% available. Floored at 0 because a
      -- negative availability is a data fault, not a measurement.
      'availability_pct',         case when c.observed_days >= 90 and c.breakdown_hours is not null
                                       then greatest(0, round(100.0 - (100.0 * c.breakdown_hours
                                            / (c.observed_days * 24)), 1)) end,
      'spend',                    c.total_spend,
      'spend_by_year',            coalesce(c.by_year, '{}'::jsonb),
      'cost_per_breakdown_hour',  case when c.breakdown_hours > 0 and c.total_spend is not null
                                       then round(c.total_spend / c.breakdown_hours, 2) end,
      'cost_per_failure',         case when c.failures > 0 and c.total_spend is not null
                                       then round(c.total_spend / c.failures) end
    ) order by c.breakdown_hours desc nulls last), '[]'::jsonb),
    jsonb_build_object(
      'assets',                   count(*),
      'job_cards',                sum(c.job_cards),
      'dated_cards',              sum(c.dated_cards),
      'date_coverage_pct',        case when sum(c.job_cards) > 0
                                       then round(100.0 * sum(c.dated_cards) / sum(c.job_cards), 1) end,
      'breakdown_hours',          sum(c.breakdown_hours),
      'breakdown_hours_recorded', sum(c.breakdown_hours_recorded),
      'parked_cards',             sum(c.parked_cards),
      'parked_hours',             sum(c.parked_hours),
      'failures',                 sum(c.failures),
      'emergency_cards',          sum(c.emergency_cards),
      'preventive_cards',         sum(c.preventive_cards),
      'preventive_share_pct',     case when sum(c.job_cards) > 0
                                       then round(100.0 * sum(c.preventive_cards) / sum(c.job_cards), 1) end,
      'spend',                    sum(c.total_spend),
      'parked_threshold_hours',   c_parked_hours
    )
  into v_out, v_totals
  from calc c;

  return jsonb_build_object('ok', true, 'country', p_country,
                            'assets', v_out, 'totals', v_totals);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_asset_master(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 1000)
 RETURNS TABLE(asset_no text, countries text, country_count integer, make text, model text, vehicle_type text, tyres bigint, work_orders bigint, by_country jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  WITH org AS (SELECT public.app_current_org() AS oid),
  fleet AS (
    SELECT asset_no, country FROM public.vehicle_fleet
    WHERE organisation_id = (SELECT oid FROM org) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND asset_no IS NOT NULL
    GROUP BY asset_no, country
  ),
  tr AS (
    SELECT asset_no, country, count(*) AS n FROM public.tyre_records
    WHERE organisation_id = (SELECT oid FROM org) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND asset_no IS NOT NULL GROUP BY asset_no, country
  ),
  wo AS (
    SELECT asset_no, country, count(*) AS n FROM public.work_orders
    WHERE organisation_id = (SELECT oid FROM org) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND asset_no IS NOT NULL GROUP BY asset_no, country
  ),
  ex AS (
    SELECT asset_code AS asset_no, country, round(sum(tyre_cost)) AS c FROM public.parts_consumption
    WHERE organisation_id = (SELECT oid FROM org) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND cost_category = 'tyre' AND asset_code IS NOT NULL
    GROUP BY asset_code, country
  ),
  ident AS (
    SELECT asset_no, max(make) make, max(model) model, max(vehicle_type) vehicle_type
    FROM public.vehicle_fleet WHERE organisation_id = (SELECT oid FROM org) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND asset_no IS NOT NULL
    GROUP BY asset_no
  ),
  per AS (
    SELECT f.asset_no, f.country,
      COALESCE(tr.n,0) AS tyres, COALESCE(wo.n,0) AS work_orders, COALESCE(ex.c,0) AS tyre_expense
    FROM fleet f
    LEFT JOIN tr ON tr.asset_no=f.asset_no AND tr.country=f.country
    LEFT JOIN wo ON wo.asset_no=f.asset_no AND wo.country=f.country
    LEFT JOIN ex ON ex.asset_no=f.asset_no AND ex.country=f.country
  ),
  agg AS (
    SELECT asset_no,
      string_agg(DISTINCT country, ', ' ORDER BY country) AS countries,
      count(DISTINCT country)::int AS country_count,
      sum(tyres)::bigint AS tyres, sum(work_orders)::bigint AS work_orders,
      jsonb_agg(jsonb_build_object('country',country,'tyres',tyres,'work_orders',work_orders,'tyre_expense',tyre_expense)
                ORDER BY country) AS by_country
    FROM per GROUP BY asset_no
  )
  SELECT a.asset_no, a.countries, a.country_count, i.make, i.model, i.vehicle_type,
         a.tyres, a.work_orders, a.by_country
  FROM agg a LEFT JOIN ident i ON i.asset_no = a.asset_no
  WHERE p_search IS NULL OR btrim(p_search) = '' OR a.asset_no ILIKE '%'||btrim(p_search)||'%'
  ORDER BY a.country_count DESC, a.asset_no
  LIMIT greatest(coalesce(p_limit,1000), 1);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_asset_ownership(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 500, p_cross_only boolean DEFAULT false, p_asset text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  -- a country running at least this share of the asset's active months AND cost
  -- lines is the operator; the remainder is a stray or mis-keyed tail
  DOMINANT_SHARE          constant numeric := 0.90;
  -- one shared month is a plausible mid-month handover; two or more is
  -- concurrent operation, which one physical asset cannot do
  CONCURRENT_TOLERATED    constant int := 1;
  v_org    uuid := public.app_current_org();
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_asset  text := nullif(upper(btrim(coalesce(p_asset, ''))), '');
  v_limit  int  := least(greatest(coalesce(p_limit, 500), 1), 5000);
  result   jsonb;
begin
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  with foot as (
    -- one row per asset per country: the operating footprint that decides ownership
    select asset_code,
           country,
           count(*)::int                                              as rows_n,
           count(distinct date_trunc('month', event_date))::int       as months_n,
           min(event_date)                                            as first_date,
           max(event_date)                                            as last_date,
           sum(line_cost)                                             as cost,
           sum(tyre_cost)                                             as tyre_cost
      from public.parts_consumption
     where organisation_id = v_org
       and asset_code is not null
       and btrim(asset_code) <> ''
       and (v_asset is null or asset_code = v_asset)
     group by asset_code, country
  ),
  months as (
    select asset_code,
           date_trunc('month', event_date)::date as m,
           count(distinct country)               as nc
      from public.parts_consumption
     where organisation_id = v_org
       and asset_code is not null
       and btrim(asset_code) <> ''
       and event_date is not null
       and (v_asset is null or asset_code = v_asset)
     group by 1, 2
  ),
  conc as (
    select asset_code, count(*) filter (where nc > 1)::int as concurrent_months
      from months group by asset_code
  ),
  tot as (
    select asset_code,
           count(*)::int  as n_countries,
           sum(rows_n)    as rows_all,
           sum(months_n)  as months_all
      from foot group by asset_code
  ),
  -- the country with the largest footprint, and the country holding it last
  best as (
    select distinct on (asset_code)
           asset_code, country as best_country, rows_n as best_rows, months_n as best_months
      from foot order by asset_code, months_n desc, rows_n desc, country
  ),
  recent as (
    select distinct on (asset_code)
           asset_code, country as recent_country
      from foot order by asset_code, last_date desc, rows_n desc, country
  ),
  prior as (
    select distinct on (asset_code)
           f.asset_code, f.country as prior_country
      from foot f join recent r on r.asset_code = f.asset_code
     where f.country <> r.recent_country
     order by f.asset_code, f.last_date desc, f.rows_n desc, f.country
  ),
  -- context only: never decides ownership (see the header note)
  ident as (
    select asset_no,
           count(distinct upper(btrim(make)))         filter (where make         is not null and btrim(make) <> '')         as n_make,
           count(distinct upper(btrim(vehicle_type))) filter (where vehicle_type is not null and btrim(vehicle_type) <> '') as n_type
      from public.vehicle_fleet
     where organisation_id = v_org and asset_no is not null
     group by asset_no
  ),
  reg as (
    select distinct on (asset_no) asset_no, country as registration_country
      from public.vehicle_fleet
     where organisation_id = v_org and asset_no is not null
       and registration_no is not null and btrim(registration_no) <> ''
     order by asset_no, country
  ),
  decided as (
    select t.asset_code,
           t.n_countries,
           coalesce(c.concurrent_months, 0)                                   as concurrent_months,
           coalesce(b.best_months::numeric / nullif(t.months_all, 0), 0)      as month_share,
           coalesce(b.best_rows::numeric   / nullif(t.rows_all,   0), 0)      as row_share,
           b.best_country, r.recent_country, p.prior_country,
           coalesce(i.n_make, 0) > 1 or coalesce(i.n_type, 0) > 1             as identity_conflict,
           g.registration_country
      from tot t
      join best   b on b.asset_code = t.asset_code
      join recent r on r.asset_code = t.asset_code
      left join prior p on p.asset_code = t.asset_code
      left join conc  c on c.asset_code = t.asset_code
      left join ident i on i.asset_no   = t.asset_code
      left join reg   g on g.asset_no   = t.asset_code
  ),
  ruled as (
    -- the ladder: first match wins
    select d.*,
           case
             when d.n_countries = 1 then 'single_country'
             when d.month_share >= DOMINANT_SHARE and d.row_share >= DOMINANT_SHARE then 'dominant_operator'
             when d.concurrent_months > CONCURRENT_TOLERATED then 'contested_concurrent'
             when d.n_countries = 2 then 'sequential_transfer'
             else 'unknown'
           end as ownership_basis,
           case
             when d.n_countries = 1 then d.best_country
             when d.month_share >= DOMINANT_SHARE and d.row_share >= DOMINANT_SHARE then d.best_country
             when d.concurrent_months > CONCURRENT_TOLERATED then null
             when d.n_countries = 2 then d.recent_country
             else null
           end as owning_country
      from decided d
  ),
  final as (
    select r.*,
           case r.ownership_basis
             when 'single_country'     then 'high'
             when 'dominant_operator'  then 'medium'
             when 'sequential_transfer' then 'medium'
             else 'none'
           end as ownership_confidence
      from ruled r
  ),
  -- per-country money, split by whether the bearing country owns the asset
  money as (
    select f.country,
           public.currency_for_country(f.country)                                                as currency,
           round(sum(f.cost) filter (where n.owning_country is not null
                                       and n.owning_country = f.country), 2)                     as own_asset_cost,
           round(sum(f.cost) filter (where n.owning_country is not null
                                       and n.owning_country <> f.country), 2)                    as foreign_owned_cost,
           round(sum(f.cost) filter (where n.owning_country is null), 2)                         as contested_cost,
           round(sum(f.cost), 2)                                                                 as total_cost,
           count(*) filter (where n.owning_country is not null
                              and n.owning_country <> f.country)::int                            as foreign_owned_assets
      from foot f join final n on n.asset_code = f.asset_code
     group by f.country
  ),
  listed as (
    select n.*
      from final n
     where (v_search is null or n.asset_code ilike '%' || v_search || '%')
       and (not coalesce(p_cross_only, false) or n.n_countries > 1)
     order by n.n_countries desc, n.asset_code
     limit v_limit
  ),
  -- per-country detail for the listed page only, built in ONE grouped pass. A
  -- correlated subquery per asset re-scanned the foot CTE 500 times and cost
  -- ~2.6s; this is ~0.4s for the same payload.
  cty as (
    select f.asset_code,
           jsonb_agg(jsonb_build_object(
             'country', f.country,
             'currency', public.currency_for_country(f.country),
             'cost', round(f.cost, 2),
             'tyre_cost', round(f.tyre_cost, 2),
             'rows', f.rows_n,
             'months_active', f.months_n,
             'first_date', f.first_date,
             'last_date', f.last_date,
             'bears_cost_for_other_country',
               (l.owning_country is not null and l.owning_country <> f.country),
             'is_owner', (l.owning_country is not null and l.owning_country = f.country))
           order by f.cost desc) as js
      from foot f
      join listed l on l.asset_code = f.asset_code
     group by f.asset_code
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    -- the sentence the UI shows verbatim
    'rule', 'A country owns an asset when it is the only country operating it, '
         || 'or it runs at least 90 percent of the asset active months and cost lines, '
         || 'or it is the country holding the asset after a clean handover; when two '
         || 'countries bill the same code in the same month more than once, ownership '
         || 'is reported as unknown rather than guessed.',
    'basis_of_evidence', 'Operating history in the expense ledger. Finance fields '
         || '(purchase value, net book value, asset number) are empty for every asset, '
         || 'and registration exists only in KSA, so neither can decide ownership '
         || 'without favouring one country.',
    'thresholds', jsonb_build_object(
      'dominant_share', DOMINANT_SHARE,
      'concurrent_months_tolerated', CONCURRENT_TOLERATED),
    'summary', jsonb_build_object(
      'assets_total',        (select count(*) from final),
      'cross_country',       (select count(*) from final where n_countries > 1),
      'single_country',      (select count(*) from final where ownership_basis = 'single_country'),
      'dominant_operator',   (select count(*) from final where ownership_basis = 'dominant_operator'),
      'sequential_transfer', (select count(*) from final where ownership_basis = 'sequential_transfer'),
      'contested',           (select count(*) from final where ownership_basis = 'contested_concurrent'),
      'unknown',             (select count(*) from final where owning_country is null),
      'identity_conflicts',  (select count(*) from final where identity_conflict),
      -- per country, each in its OWN currency; never added together
      'by_country', (select coalesce(jsonb_agg(jsonb_build_object(
            'country', country, 'currency', currency,
            'own_asset_cost', own_asset_cost,
            'foreign_owned_cost', foreign_owned_cost,
            'contested_cost', contested_cost,
            'total_cost', total_cost,
            'foreign_owned_assets', foreign_owned_assets) order by country), '[]'::jsonb)
          from money)),
    'assets', (select coalesce(jsonb_agg(jsonb_build_object(
          'asset_no', l.asset_code,
          'owning_country', l.owning_country,
          'ownership_basis', l.ownership_basis,
          'ownership_confidence', l.ownership_confidence,
          'country_count', l.n_countries,
          'concurrent_months', l.concurrent_months,
          'transferred_from', case when l.ownership_basis = 'sequential_transfer'
                                   then l.prior_country else null end,
          'identity_conflict', l.identity_conflict,
          'registration_country', l.registration_country,
          'countries', coalesce(c.js, '[]'::jsonb))
        order by l.n_countries desc, l.asset_code), '[]'::jsonb)
      from listed l left join cty c on c.asset_code = l.asset_code)
  ) into result;

  return result;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_brand_size_cpk(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with base as (
    select
      vt.country,
      upper(regexp_replace(vt.size, '\s+', '', 'g'))          as nsize,
      btrim(vt.size)                                          as raw_size,
      upper(btrim(vt.brand))                                  as nbrand,
      btrim(vt.brand)                                         as raw_brand,
      coalesce(vt.qty, 1)                                     as qty,
      vt.purchase_cost,
      vt.km_known
    from public.v_tyre_lifetime vt
    where vt.organisation_id = public.app_current_org()
      and vt.size is not null and btrim(vt.size) <> ''
      and vt.brand is not null and btrim(vt.brand) <> ''
      and (p_country is null or vt.country = p_country) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (vt.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vt.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and (nullif(btrim(coalesce(p_site, '')), '') is null or (((select public.is_super_admin()) or public.app_can_see_site(p_site) is not false) and exists (select 1 from public.vehicle_fleet f where f.organisation_id = vt.organisation_id and f.country is not distinct from vt.country and upper(btrim(f.asset_no)) = upper(btrim(vt.asset_no)) and upper(btrim(f.site)) = upper(regexp_replace(btrim(p_site), '\s+', ' ', 'g')))))
      and (p_from is null or coalesce(vt.last_fit_date, vt.first_fit_date, vt.last_removal_date) >= p_from)
      and (p_to is null or coalesce(vt.last_fit_date, vt.first_fit_date, vt.last_removal_date) <= p_to)
  ),
  grouped as (
    select
      country,
      nsize,
      mode() within group (order by raw_size)  as size,
      mode() within group (order by raw_brand) as brand,
      count(*)                                                          as tyres,
      round(avg(purchase_cost) filter (where purchase_cost > 0), 2)     as avg_price,
      round(
        percentile_cont(0.5) within group (order by purchase_cost)
          filter (where purchase_cost > 0)::numeric, 2)                 as median_price,
      round(
        sum(km_known * qty) filter (where purchase_cost > 0 and km_known > 0)
          / nullif(sum(qty) filter (where purchase_cost > 0 and km_known > 0), 0)
      )                                                                 as avg_life_km,
      sum(purchase_cost * qty) filter (where purchase_cost > 0 and km_known > 0) as cost,
      sum(km_known      * qty) filter (where purchase_cost > 0 and km_known > 0) as km
    from base
    group by country, nsize, nbrand
    having count(*) filter (where purchase_cost > 0) > 0
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.country, r.size, r.cpk nulls last), '[]'::jsonb)
  from (
    select
      size,
      brand,
      tyres,
      avg_price,
      median_price,
      avg_life_km,
      case when km > 0 then round(cost / km, 5) end as cpk,
      public.currency_for_country(country)          as currency,
      country
    from grouped
  ) r;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_brand_size_cpk_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with base as (
    select
      country,
      -- normalise size for grouping (strip all whitespace, upper) so
      -- '315/80 R 22.5', '315/80R22.5' and '315 /80R22.5' are one bucket.
      upper(regexp_replace(size, '\s+', '', 'g'))          as nsize,
      -- keep a human-readable representative for display.
      btrim(size)                                          as raw_size,
      upper(btrim(brand))                                  as nbrand,
      btrim(brand)                                         as raw_brand,
      cost_per_tyre,
      total_km
    from public.tyre_records
    where organisation_id = public.app_current_org()
      and size is not null and btrim(size) <> ''
      and brand is not null and btrim(brand) <> ''
      and (p_country is null or country = p_country) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and (p_from is null or coalesce(issue_date, fitment_date, removal_date) >= p_from)
      and (p_to is null or coalesce(issue_date, fitment_date, removal_date) <= p_to)
  ),
  grouped as (
    select
      country,
      nsize,
      mode() within group (order by raw_size)  as size,
      mode() within group (order by raw_brand) as brand,
      count(*)                                                    as tyres,
      round(avg(cost_per_tyre) filter (where cost_per_tyre > 0), 2) as avg_price,
      round(
        percentile_cont(0.5) within group (order by cost_per_tyre)
          filter (where cost_per_tyre > 0)::numeric, 2)          as median_price,
      round(avg(total_km) filter (where total_km > 0))           as avg_life_km
    from base
    group by country, nsize, nbrand
    having count(*) filter (where cost_per_tyre > 0) > 0
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.country, r.size, r.cpk nulls last), '[]'::jsonb)
  from (
    select
      size,
      brand,
      tyres,
      avg_price,
      median_price,
      avg_life_km,
      case when avg_life_km > 0 and avg_price is not null
        then round(avg_price / avg_life_km, 5) end as cpk,
      public.currency_for_country(country)         as currency,
      country
    from grouped
  ) r;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_checklist_governance_policy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select public.checklist_governance_defaults() || coalesce(
    (select to_jsonb(p) - array['created_by','updated_by']
       from public.checklist_governance_policies p
      where p.organisation_id is not distinct from public.app_current_org()),
    '{}'::jsonb
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_classification_decisions(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_view text DEFAULT 'moved'::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org   uuid := public.app_current_org();
  v_ctry  text := nullif(btrim(coalesce(p_country, '')), '');
  v_view  text := lower(coalesce(nullif(btrim(p_view), ''), 'moved'));
  v_q     text := nullif(btrim(coalesce(p_search, '')), '');
  v_lim   integer := greatest(1, least(coalesce(p_limit, 200), 1000));
  v_out   jsonb;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if v_ctry ilike 'all' then v_ctry := null; end if;
  if v_view not in ('moved', 'kept', 'unlabelled', 'all') then v_view := 'moved'; end if;

  with base as materialized (
    select
      pc.country, pc.item_code, pc.item_description, pc.line_cost, pc.currency,
      pc.classified_by, pc.classify_confidence,
      case when pc.tyre_cost > 0 then 'tyre'
           when pc.oil_cost  > 0 then 'oil'
           else 'spare' end as ours,
      pc.erp_bucket as erp          -- NULL = the file stated nothing
    from public.parts_consumption pc
    where pc.organisation_id = v_org
      and (v_ctry is null or pc.country = v_ctry) and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and (p_from is null or pc.event_date >= p_from)
      and (p_to   is null or pc.event_date <= p_to)
  ),
  -- Over the WHOLE window, never only the rows the search box left behind, so
  -- the headline cannot quietly describe a different set than it claims to.
  per_country as (
    select country,
      max(currency) as currency,
      count(*) filter (where erp is not null and erp <> ours) as moved_rows,
      round(coalesce(sum(line_cost) filter (where erp is not null and erp <> ours), 0), 2) as moved_value,
      count(*) filter (where erp is not null and erp = ours) as kept_rows,
      round(coalesce(sum(line_cost) filter (where erp is not null and erp = ours), 0), 2) as kept_value,
      count(*) filter (where erp is null) as unlabelled_rows,
      round(coalesce(sum(line_cost) filter (where erp is null), 0), 2) as unlabelled_value,
      count(*) as total_rows,
      round(coalesce(sum(line_cost), 0), 2) as total_value
    from base group by country
  ),
  grouped as (
    select b.country, b.item_code, b.erp, b.ours,
      max(b.item_description) as item_name,
      mode() within group (order by b.classified_by) as decided_by,
      -- the WEAKEST evidence in the group: a code decided partly by the
      -- fallback is exactly what should be reviewed first
      min(b.classify_confidence) as confidence,
      count(*) as rows_n,
      round(sum(b.line_cost), 2) as value_n,
      max(b.currency) as currency
    from base b
    where (v_view = 'all'
           or (v_view = 'moved'      and b.erp is not null and b.erp <> b.ours)
           or (v_view = 'kept'       and b.erp is not null and b.erp =  b.ours)
           or (v_view = 'unlabelled' and b.erp is null))
      and (v_q is null
           or b.item_code ilike '%' || v_q || '%'
           or b.item_description ilike '%' || v_q || '%')
    group by b.country, b.item_code, b.erp, b.ours
    order by abs(sum(b.line_cost)) desc
    limit v_lim
  ),
  ranked as (
    select g.*, row_number() over (order by abs(g.value_n) desc) as rn,
           coalesce(mm.reviewed, false) as reviewed,
           case when mm.reviewed then mm.category end as reviewed_category
    from grouped g
    left join public.material_master mm
      on mm.organisation_id = v_org and mm.country = g.country and mm.item_code = g.item_code
  )
  select jsonb_build_object(
    'ok', true,
    'view', v_view,
    'countries', coalesce((select jsonb_agg(jsonb_build_object(
        'country', country, 'currency', currency,
        'moved_rows', moved_rows, 'moved_value', moved_value,
        'kept_rows', kept_rows, 'kept_value', kept_value,
        'unlabelled_rows', unlabelled_rows, 'unlabelled_value', unlabelled_value,
        'total_rows', total_rows, 'total_value', total_value
      ) order by country) from per_country), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'country', country, 'item_code', item_code, 'item_name', item_name,
        'erp_said', coalesce(erp, 'not stated'), 'we_said', ours,
        'movement', case when erp is null then 'unlabelled'
                         when erp = ours then 'kept' else 'moved' end,
        'decided_by', decided_by, 'confidence', confidence,
        'rows', rows_n, 'value', value_n, 'currency', currency,
        'reviewed', reviewed, 'reviewed_category', reviewed_category
      ) order by rn) from ranked), '[]'::jsonb),
    'limit', v_lim
  ) into v_out;

  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_console_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tu int:=0; v_au int:=0; v_lu int:=0; v_pu int:=0;
  v_to int:=0; v_ao int:=0; v_tt int:=0; v_ti int:=0; v_tv int:=0;
  v_nt int:=0; v_nw int:=0; v_sa int:=0;
  v_org uuid;
begin
  if not coalesce((select public.is_super_admin()), false) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if (select public.is_super_admin()) then
    select count(*) into v_tu from profiles;
    select count(*) into v_au from profiles where approved=true and (locked is null or locked=false);
    select count(*) into v_lu from profiles where locked=true;
    select count(*) into v_pu from profiles where approved=false;
    select count(*) into v_sa from profiles where is_super_admin=true;
    select count(*) into v_nt from profiles where created_at >= now()-interval '1 day';
    select count(*) into v_nw from profiles where created_at >= now()-interval '7 days';
    select count(*) into v_to from organisations;
    select count(*) into v_ao from organisations where active=true;
    begin select count(*) into v_tt from tyres; exception when undefined_table then null; end;
    begin select count(*) into v_ti from inspections; exception when undefined_table then null; end;
    begin select count(*) into v_tv from vehicles; exception when undefined_table then null; end;
  else
    v_org := (select public.app_current_org());
    select count(*) into v_tu from profiles where org_id = v_org;
    select count(*) into v_au from profiles where org_id = v_org and approved=true and (locked is null or locked=false);
    select count(*) into v_lu from profiles where org_id = v_org and locked=true;
    select count(*) into v_pu from profiles where org_id = v_org and approved=false;
    select count(*) into v_sa from profiles where org_id = v_org and is_super_admin=true;
    select count(*) into v_nt from profiles where org_id = v_org and created_at >= now()-interval '1 day';
    select count(*) into v_nw from profiles where org_id = v_org and created_at >= now()-interval '7 days';
    select count(*) into v_to from organisations where id = v_org;
    select count(*) into v_ao from organisations where id = v_org and active=true;
    begin select count(*) into v_ti from inspections where organisation_id = v_org; exception when undefined_table then null; end;
    begin select count(*) into v_tv from vehicle_fleet where organisation_id = v_org; exception when undefined_table then null; end;
  end if;

  return jsonb_build_object(
    'users', jsonb_build_object('total',v_tu,'active',v_au,'locked',v_lu,'pending',v_pu,
                                'super_admins',v_sa,'new_today',v_nt,'new_week',v_nw),
    'organisations', jsonb_build_object('total',v_to,'active',v_ao),
    'assets', jsonb_build_object('tyres',v_tt,'inspections',v_ti,'vehicles',v_tv),
    'generated_at', now()
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_console_users(p_org_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, full_name text, email text, role text, site text, country text, organisation_id uuid, approved boolean, locked boolean, is_super_admin boolean, last_login_at timestamp with time zone, login_count integer, created_at timestamp with time zone, module_overrides jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT
    p.id, p.full_name, COALESCE(p.email, u.email) AS email,
    p.role, p.site, p.country, p.organisation_id,
    p.approved, p.locked, p.is_super_admin,
    p.last_login_at, p.login_count, p.created_at, p.module_overrides
  FROM profiles p
  LEFT JOIN auth.users u ON u.id = p.id
  WHERE
    (p_org_id IS NULL OR p.organisation_id = p_org_id)
    AND (p_search IS NULL OR p_search = ''
         OR p.full_name ILIKE '%' || p_search || '%'
         OR COALESCE(p.email, u.email) ILIKE '%' || p_search || '%'
         OR p.site ILIKE '%' || p_search || '%')
  ORDER BY p.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_control_center_summary(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if v_org is null or not public.app_is_active() or not public.is_super_admin() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;
  return jsonb_build_object('ok', true, 'country', p_country,
    'volumes', jsonb_build_object(
      'expense_rows', (select count(*) from parts_consumption where organisation_id=v_org and (p_country is null or country=p_country)),
      'tyre_rows', (select count(*) from tyre_records where organisation_id=v_org and (p_country is null or country=p_country)),
      'fleet_rows', (select count(*) from vehicle_fleet where organisation_id=v_org and (p_country is null or country=p_country)),
      'work_orders', (select count(*) from work_orders where organisation_id=v_org and (p_country is null or country=p_country))
    ),
    'issues', jsonb_build_array(
      jsonb_build_object('key','orphan_assets','label','Tyres on assets missing from the fleet register','severity','warning',
        'count', (select count(distinct upper(btrim(t.asset_no))) from tyre_records t
                    where t.organisation_id=v_org and (p_country is null or t.country=p_country)
                      and coalesce(btrim(t.asset_no),'')<>''
                      and not exists (select 1 from vehicle_fleet f
                        where f.organisation_id=v_org and upper(btrim(f.asset_no))=upper(btrim(t.asset_no))
                          and (t.country is null or f.country=t.country))),
        'action','recon_orphan_assets'),
      jsonb_build_object('key','brand_gap','label','Tyres with no brand recorded','severity','info',
        'count', (select count(*) from tyre_records where organisation_id=v_org and (p_country is null or country=p_country)
                    and coalesce(btrim(brand),'')=''),
        'action','recon_brand'),
      jsonb_build_object('key','future_removal','label','Tyres with a removal date in the future','severity','critical',
        'count', (select count(*) from tyre_records where organisation_id=v_org and (p_country is null or country=p_country)
                    and removal_date is not null and removal_date > current_date),
        'action','data_reconciliation'),
      jsonb_build_object('key','reversed_dates','label','Tyres removed before they were fitted','severity','critical',
        'count', (select count(*) from tyre_records where organisation_id=v_org and (p_country is null or country=p_country)
                    and removal_date is not null and issue_date is not null and removal_date < issue_date),
        'action','data_reconciliation'),
      jsonb_build_object('key','unpriced_tyres','label','Tyres with no unit cost (weakens CPK)','severity','info',
        'count', (select count(*) from tyre_records where organisation_id=v_org and (p_country is null or country=p_country)
                    and (cost_per_tyre is null or cost_per_tyre=0)),
        'action','tyre_price_backfill'),
      jsonb_build_object('key','unclassified_spend','label','Expense lines filed by the fallback (nothing identified them)','severity','warning',
        'count', (select count(*) from parts_consumption where organisation_id=v_org and (p_country is null or country=p_country)
                    and coalesce(classified_by,'')='default'),
        'action','material_master'),
      jsonb_build_object('key','no_import_uid','label','Expense lines with no import identity (re-import could duplicate)','severity','warning',
        'count', (select count(*) from parts_consumption where organisation_id=v_org and (p_country is null or country=p_country)
                    and import_uid is null),
        'action','import_history')
    ));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_cpk_overview(p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
 SET work_mem TO '24MB'
AS $function$
declare
  -- below this share of window spend, a cost-per-km comparison is coverage
  -- noise rather than a trend
  MIN_COVERAGE constant numeric := 0.25;
  v_org  uuid := public.app_current_org();
  v_to   date := coalesce(p_to, current_date);
  v_from date := coalesce(p_from, coalesce(p_to, current_date) - 364);
  v_len  int;
  v_pf date; v_pt date; v_lf date; v_lt date;
  v_ms date; v_lo date; v_hi date;
  v_cur text; v_countries int;
  result jsonb;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  v_len := (v_to - v_from) + 1;
  v_pt := v_from - 1;
  v_pf := v_pt - (v_len - 1);
  v_lf := (v_from - interval '1 year')::date;
  v_lt := (v_to   - interval '1 year')::date;
  v_ms := (v_to - interval '35 months')::date;
  -- one read of parts_consumption covering every window the payload needs
  v_lo := least(v_from, v_pf, v_lf, v_ms);
  v_hi := greatest(v_to, v_pt, v_lt, v_from);

  select count(distinct country) into v_countries
    from public.parts_consumption
   where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));
  v_cur := case when p_country is null and v_countries > 1 then null
                else public.currency_for_country(coalesce(p_country,
                  (select country from public.parts_consumption
                    where organisation_id = v_org limit 1))) end;

  with pc as materialized (
    select event_date, tyre_cost, spare_cost, oil_cost, line_cost,
           upper(btrim(asset_code)) ac, classified_by,
           site, cost_center, asset_type, asset_code, item_description
      from public.parts_consumption
     where organisation_id = v_org
       and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and (p_site is null or site = p_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and event_date between v_lo and v_hi
  ),
  -- the same fleet_km_by_asset reads _cost_cpk made, one per window
  kmr as materialized (
    select w.k, x.asset_no, x.km_run
      from (values ('current', v_from, v_to), ('previous', v_pf, v_pt), ('last_year', v_lf, v_lt)) w(k, f0, t0)
      cross join lateral public.fleet_km_by_asset(v_org, p_country, w.f0, w.t0) x
     where true and (x.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(x.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  km as (
    select w.k, coalesce(sum(r.km_run),0) km, count(r.asset_no) n
      from (values ('current'), ('previous'), ('last_year')) w(k)
      left join kmr r on r.k = w.k
     group by w.k
  ),
  agg as (
    select
      coalesce(round(sum(tyre_cost)  filter (where event_date between v_from and v_to)),0) c_tyre,
      coalesce(round(sum(spare_cost) filter (where event_date between v_from and v_to)),0) c_spare,
      coalesce(round(sum(oil_cost)   filter (where event_date between v_from and v_to)),0) c_oil,
      coalesce(round(sum(line_cost)  filter (where event_date between v_from and v_to)),0) c_total,
      count(*) filter (where event_date between v_from and v_to) c_lines,
      count(distinct ac) filter (where event_date between v_from and v_to) c_assets,
      coalesce(round(sum(line_cost)  filter (where event_date between v_from and v_to
          and ac in (select asset_no from kmr where k = 'current'))),0) c_matched,
      coalesce(round(sum(tyre_cost)  filter (where event_date between v_pf and v_pt)),0) p_tyre,
      coalesce(round(sum(spare_cost) filter (where event_date between v_pf and v_pt)),0) p_spare,
      coalesce(round(sum(oil_cost)   filter (where event_date between v_pf and v_pt)),0) p_oil,
      coalesce(round(sum(line_cost)  filter (where event_date between v_pf and v_pt)),0) p_total,
      count(*) filter (where event_date between v_pf and v_pt) p_lines,
      count(distinct ac) filter (where event_date between v_pf and v_pt) p_assets,
      coalesce(round(sum(line_cost)  filter (where event_date between v_pf and v_pt
          and ac in (select asset_no from kmr where k = 'previous'))),0) p_matched,
      coalesce(round(sum(tyre_cost)  filter (where event_date between v_lf and v_lt)),0) l_tyre,
      coalesce(round(sum(spare_cost) filter (where event_date between v_lf and v_lt)),0) l_spare,
      coalesce(round(sum(oil_cost)   filter (where event_date between v_lf and v_lt)),0) l_oil,
      coalesce(round(sum(line_cost)  filter (where event_date between v_lf and v_lt)),0) l_total,
      count(*) filter (where event_date between v_lf and v_lt) l_lines,
      count(distinct ac) filter (where event_date between v_lf and v_lt) l_assets,
      coalesce(round(sum(line_cost)  filter (where event_date between v_lf and v_lt
          and ac in (select asset_no from kmr where k = 'last_year'))),0) l_matched
      from pc
  ),
  win as (
    select 'current' k, c_tyre tyre, c_spare spare, c_oil oil, c_total total, c_lines lines, c_assets assets, c_matched matched from agg
    union all
    select 'previous', p_tyre, p_spare, p_oil, p_total, p_lines, p_assets, p_matched from agg
    union all
    select 'last_year', l_tyre, l_spare, l_oil, l_total, l_lines, l_assets, l_matched from agg
  ),
  cpk as (
    select w.k,
      jsonb_build_object('tyre', w.tyre, 'spare', w.spare, 'oil', w.oil, 'total', w.total,
                         'lines', w.lines, 'assets', w.assets) totals,
      jsonb_build_object(
        'km', round(m.km),
        'assets_measured', m.n,
        'spend_matched', w.matched,
        'spend_total', w.total,
        'coverage_pct', case when w.total > 0 then round(w.matched / w.total, 4) end,
        -- null, never zero: an unmeasured fleet has an unknown cost per km
        'cpk', case when m.km > 0 then round(w.matched / m.km, 3) end,
        'comparable', coalesce(case when w.total > 0 then round(w.matched / w.total, 4) end, 0) >= MIN_COVERAGE) cpk
      from win w join km m using (k)
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'currency', v_cur,
    'blended', (v_cur is null),
    'country', p_country,
    'site', p_site,
    'min_coverage', MIN_COVERAGE,
    'windows', jsonb_build_object(
      'current',   jsonb_build_object('from', v_from, 'to', v_to),
      'previous',  jsonb_build_object('from', v_pf,   'to', v_pt),
      'last_year', jsonb_build_object('from', v_lf,   'to', v_lt),
      'days', v_len,
      -- a twelve month range makes these the same dates; say so rather than
      -- drawing the same bar twice
      'previous_is_last_year', (v_pf = v_lf and v_pt = v_lt)),

    'totals', (select jsonb_object_agg(k, totals) from cpk),
    'cpk',    (select jsonb_object_agg(k, cpk) from cpk),

    'monthly', (select coalesce(jsonb_agg(x order by x.m), '[]'::jsonb) from (
        select to_char(date_trunc('month', event_date),'YYYY-MM') m,
               round(sum(tyre_cost)) tyre, round(sum(spare_cost)) spare,
               round(sum(oil_cost)) oil, round(sum(line_cost)) total,
               count(*) lines
          from pc
         where event_date is not null
           and event_date >= v_ms
           and event_date <= v_to
         group by 1) x),

    'by_site', (select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(site::text),''),'Unspecified') label,
               coalesce(round(sum(line_cost) filter (where event_date between v_from and v_to)),0) spend,
               coalesce(round(sum(line_cost) filter (where event_date between v_pf and v_pt)),0) prev_spend,
               count(*) filter (where event_date between v_from and v_to) lines
          from pc
         where (event_date between v_from and v_to or event_date between v_pf and v_pt)
         group by 1
         order by 2 desc, 3 desc, 1
         limit 25) x),
    'by_cost_center', (select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(cost_center::text),''),'Unspecified') label,
               coalesce(round(sum(line_cost) filter (where event_date between v_from and v_to)),0) spend,
               coalesce(round(sum(line_cost) filter (where event_date between v_pf and v_pt)),0) prev_spend,
               count(*) filter (where event_date between v_from and v_to) lines
          from pc
         where (event_date between v_from and v_to or event_date between v_pf and v_pt)
         group by 1
         order by 2 desc, 3 desc, 1
         limit 25) x),
    'by_asset_type', (select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(asset_type::text),''),'Unspecified') label,
               coalesce(round(sum(line_cost) filter (where event_date between v_from and v_to)),0) spend,
               coalesce(round(sum(line_cost) filter (where event_date between v_pf and v_pt)),0) prev_spend,
               count(*) filter (where event_date between v_from and v_to) lines
          from pc
         where (event_date between v_from and v_to or event_date between v_pf and v_pt)
         group by 1
         order by 2 desc, 3 desc, 1
         limit 25) x),
    'by_asset', (select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(asset_code::text),''),'Unspecified') label,
               coalesce(round(sum(line_cost) filter (where event_date between v_from and v_to)),0) spend,
               coalesce(round(sum(line_cost) filter (where event_date between v_pf and v_pt)),0) prev_spend,
               count(*) filter (where event_date between v_from and v_to) lines
          from pc
         where (event_date between v_from and v_to or event_date between v_pf and v_pt)
         group by 1
         order by 2 desc, 3 desc, 1
         limit 25) x),
    'by_item', (select coalesce(jsonb_agg(x order by x.spend desc, x.prev_spend desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(item_description::text),''),'Unspecified') label,
               coalesce(round(sum(line_cost) filter (where event_date between v_from and v_to)),0) spend,
               coalesce(round(sum(line_cost) filter (where event_date between v_pf and v_pt)),0) prev_spend,
               count(*) filter (where event_date between v_from and v_to) lines
          from pc
         where (event_date between v_from and v_to or event_date between v_pf and v_pt)
         group by 1
         order by 2 desc, 3 desc, 1
         limit 25) x),

    'by_evidence', (select coalesce(jsonb_agg(x order by x.spend desc), '[]'::jsonb) from (
        select coalesce(classified_by,'unknown') label, round(sum(line_cost)) spend, count(*) lines
          from pc
         where event_date between v_from and v_to
         group by 1) x)
  ) into result;

  return result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_cpk_overview_multi(p_countries text[] DEFAULT NULL::text[], p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org     uuid := public.app_current_org();
  v_allowed text[];
  v_refused text[] := '{}';
  v_country text;
  v_blocks  jsonb := '[]'::jsonb;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select allowed, refused into v_allowed, v_refused
    from public._scope_split_countries(p_countries);

  foreach v_country in array v_allowed loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'country',  v_country,
      'currency', public.currency_for_country(v_country),
      'result',   public.get_cost_cpk_overview(v_country, p_site, p_from, p_to)));
  end loop;

  return jsonb_build_object(
    'ok', true, 'multi', true, 'generated_at', now(), 'blended', false,
    'requested', to_jsonb(coalesce(p_countries, '{}'::text[])),
    'refused',   to_jsonb(v_refused),
    'countries', v_blocks);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_per_m3(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, date_trunc('month', now())::date);
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
  v_currency text;
  v_cur_n integer := 0;
  v_regions jsonb;
  v_total jsonb;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  select count(distinct pc.currency), min(pc.currency) into v_cur_n, v_currency
  from public.parts_consumption pc
  where pc.organisation_id = v_org and (p_country is null or pc.country = p_country)
    and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    and pc.currency is not null;

  with sreg as (
    select country, upper(btrim(name)) as k, region from public.sites
      where organisation_id = v_org and region is not null and name is not null
    union all
    select country, upper(btrim(site_code)) as k, region from public.sites
      where organisation_id = v_org and region is not null and site_code is not null
  ),
  region_of as (select country, k, min(region) as region from sreg group by country, k),
  station_of as materialized (
    select country, upper(btrim(station)) as k, region
    from public.production_station_map where organisation_id = v_org
  ),
  internal as (
    select coalesce(r.region, 'Unassigned') as region,
           sum(pc.line_cost) as internal_cost, sum(coalesce(pc.tyre_cost, 0)) as tyre_cost
    from public.parts_consumption pc
    left join region_of r on r.country = pc.country and r.k = upper(btrim(pc.site))
    where pc.organisation_id = v_org and (p_country is null or pc.country = p_country)
      and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and pc.event_date between v_from and v_to
    group by 1
  ),
  sco as (
    select coalesce(nullif(btrim(region), ''), 'Unassigned') as region, sum(amount) as sco_cost
    from public.sco_costs
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and period_date between v_from and v_to
    group by 1
  ),
  sany as (
    select coalesce(nullif(btrim(region), ''), 'Unassigned') as region, sum(amount) as sany_cost
    from public.sany_invoices
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and period_date between v_from and v_to
      and coalesce(doc_type, 'summary') <> 'detail'
    group by 1
  ),
  prod as (
    select coalesce(r.region, psm.region, 'Unassigned') as region,
           sum(coalesce(pl.approved_m3, 0)) as production_m3,
           sum(case when pl.approved_m3 is null then coalesce(pl.m3, 0) else 0 end) as unapproved_m3,
           count(*) filter (where pl.approved_m3 is null) as unapproved_loads
    from public.production_logs pl
    left join region_of r on r.country = pl.country and r.k = upper(btrim(pl.site))
    left join station_of psm
           on psm.country = pl.country and psm.k = upper(btrim(pl.station))
    where pl.organisation_id = v_org and (p_country is null or pl.country = p_country)
      and (pl.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pl.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and pl.period_date between v_from and v_to
    group by 1
  ),
  keys as (
    select region from internal union select region from sco
    union select region from sany union select region from prod
  ),
  rows as (
    select k.region,
           coalesce(i.internal_cost, 0) as internal_cost, coalesce(i.tyre_cost, 0) as tyre_cost,
           coalesce(s.sco_cost, 0) as sco_cost, coalesce(y.sany_cost, 0) as sany_cost,
           coalesce(p.production_m3, 0) as production_m3
    from keys k
    left join internal i on i.region = k.region
    left join sco s on s.region = k.region
    left join sany y on y.region = k.region
    left join prod p on p.region = k.region
  ),
  enriched as (
    select region, internal_cost, tyre_cost, sco_cost, sany_cost, production_m3,
           (internal_cost + sco_cost + sany_cost) as grand_total,
           case when production_m3 > 0
                then round((internal_cost + sco_cost + sany_cost) / production_m3, 4) else null end as cost_per_m3
    from rows
  )
  select
    coalesce(jsonb_agg(to_jsonb(e) order by e.grand_total desc), '[]'::jsonb),
    jsonb_build_object(
      'internal_cost', coalesce(sum(internal_cost), 0), 'tyre_cost', coalesce(sum(tyre_cost), 0),
      'sco_cost', coalesce(sum(sco_cost), 0), 'sany_cost', coalesce(sum(sany_cost), 0),
      'production_m3', coalesce(sum(production_m3), 0), 'grand_total', coalesce(sum(grand_total), 0),
      'cost_per_m3', case when coalesce(sum(production_m3), 0) > 0
                          then round(coalesce(sum(grand_total), 0) / sum(production_m3), 4) else null end
    )
  into v_regions, v_total
  from enriched e;

  return jsonb_build_object('ok', true, 'country', p_country, 'currency', case when v_cur_n = 1 then v_currency else null end, 'mixed_currency', (v_cur_n > 1), 'currencies_in_scope', v_cur_n,
    'from', v_from, 'to', v_to, 'regions', v_regions, 'total', v_total);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_per_m3_trend(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
  v_from date := coalesce(p_from, (date_trunc('month', v_to) - interval '11 months')::date);
  v_currency text;
  v_cur_n integer := 0;
  v_rows jsonb;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  select count(distinct pc.currency), min(pc.currency) into v_cur_n, v_currency
  from public.parts_consumption pc
  where pc.organisation_id = v_org and (p_country is null or pc.country = p_country)
    and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    and pc.currency is not null;

  with internal as (
    select date_trunc('month', event_date)::date as m,
           sum(line_cost) as internal_cost, sum(coalesce(tyre_cost, 0)) as tyre_cost
    from public.parts_consumption
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and event_date between v_from and v_to
    group by 1
  ),
  sco as (
    select date_trunc('month', period_date)::date as m, sum(amount) as sco_cost
    from public.sco_costs
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and period_date between v_from and v_to
    group by 1
  ),
  sany as (
    select date_trunc('month', period_date)::date as m, sum(amount) as sany_cost
    from public.sany_invoices
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and period_date between v_from and v_to
      and coalesce(doc_type, 'summary') <> 'detail'
    group by 1
  ),
  prod as (
    select date_trunc('month', period_date)::date as m, sum(coalesce(approved_m3, 0)) as production_m3
    from public.production_logs
    where organisation_id = v_org and (p_country is null or country = p_country)
      and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and period_date between v_from and v_to
    group by 1
  ),
  months as (
    select generate_series(date_trunc('month', v_from), date_trunc('month', v_to), interval '1 month')::date as m
  ),
  joined as (
    select to_char(mo.m, 'YYYY-MM') as month,
           coalesce(i.internal_cost, 0) as internal_cost,
           coalesce(i.tyre_cost, 0) as tyre_cost,
           coalesce(s.sco_cost, 0) as sco_cost,
           coalesce(y.sany_cost, 0) as sany_cost,
           coalesce(p.production_m3, 0) as production_m3,
           (coalesce(i.internal_cost, 0) + coalesce(s.sco_cost, 0) + coalesce(y.sany_cost, 0)) as grand_total,
           case when coalesce(p.production_m3, 0) > 0
                then round((coalesce(i.internal_cost,0)+coalesce(s.sco_cost,0)+coalesce(y.sany_cost,0)) / p.production_m3, 4)
                else null end as cost_per_m3
    from months mo
    left join internal i on i.m = mo.m
    left join sco s on s.m = mo.m
    left join sany y on y.m = mo.m
    left join prod p on p.m = mo.m
    order by mo.m
  )
  select coalesce(jsonb_agg(to_jsonb(joined)), '[]'::jsonb) into v_rows from joined;

  return jsonb_build_object(
    'ok', true, 'country', p_country, 'currency', case when v_cur_n = 1 then v_currency else null end, 'mixed_currency', (v_cur_n > 1), 'currencies_in_scope', v_cur_n,
    'from', v_from, 'to', v_to, 'months', v_rows
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_variance(p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_to date := coalesce(p_to, current_date);
  v_from date := coalesce(p_from, coalesce(p_to, current_date) - 364);
  v_len int; v_pf date; v_pt date; v_cur text; v_countries int;
  v_lim int := least(greatest(coalesce(p_limit, 25), 5), 100);
  result jsonb;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;
  v_len := (v_to - v_from) + 1; v_pt := v_from - 1; v_pf := v_pt - (v_len - 1);
  select count(distinct country) into v_countries from public.parts_consumption
   where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));
  v_cur := case when p_country is null and v_countries > 1 then null
                else public.currency_for_country(coalesce(p_country,
                  (select country from public.parts_consumption where organisation_id = v_org limit 1))) end;
  if v_cur is null then
    return jsonb_build_object('ok', true, 'blended', true, 'currency', null,
      'country', p_country, 'site', p_site, 'generated_at', now(),
      'windows', jsonb_build_object('current', jsonb_build_object('from', v_from, 'to', v_to),
        'previous', jsonb_build_object('from', v_pf, 'to', v_pt), 'days', v_len),
      'totals', null, 'effects', null, 'items', '[]'::jsonb, 'items_tail', null, 'dims', '{}'::jsonb,
      'reason', 'Spend spans more than one currency. Choose a country to decompose the change.');
  end if;
  with base as (
    select coalesce(nullif(btrim(item_code),''),'(no item code)') code,
           event_date, qty_n, line_cost, unit_cost, item_description,
           tyre_cost, spare_cost, oil_cost, (qty_n > 0 and unit_cost is not null) usable
      from public.parts_consumption
     where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and (p_site is null or site = p_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and (event_date between v_from and v_to or event_date between v_pf and v_pt)),
  agg as (
    select code, (array_agg(item_description order by length(coalesce(item_description,'')) desc))[1] label,
      sum(qty_n) filter (where event_date between v_from and v_to and usable) q1,
      sum(line_cost) filter (where event_date between v_from and v_to and usable) s1,
      sum(qty_n) filter (where event_date between v_pf and v_pt and usable) q0,
      sum(line_cost) filter (where event_date between v_pf and v_pt and usable) s0,
      sum(line_cost) filter (where event_date between v_from and v_to and not usable) x1,
      sum(line_cost) filter (where event_date between v_pf and v_pt and not usable) x0,
      count(*) filter (where event_date between v_from and v_to) lines1,
      count(*) filter (where event_date between v_pf and v_pt) lines0,
      sum(tyre_cost) tc, sum(spare_cost) sc, sum(oil_cost) oc
      from base group by code),
  calc as (
    select a.*, coalesce(q0,0) qq0, coalesce(q1,0) qq1, coalesce(s0,0) ss0, coalesce(s1,0) ss1,
      coalesce(x0,0) xx0, coalesce(x1,0) xx1,
      case when coalesce(q0,0) > 0 then s0/q0 end p0, case when coalesce(q1,0) > 0 then s1/q1 end p1,
      (coalesce(q0,0) > 0 and coalesce(q1,0) > 0) in_both from agg a),
  eff as (
    select c.*,
      case when in_both then (qq1 - qq0) * ((p0 + p1) / 2) else 0 end vol_e,
      case when in_both then (p1 - p0) * ((qq0 + qq1) / 2) else 0 end price_e,
      case when not in_both and qq0 = 0 and qq1 > 0 then ss1 else 0 end new_e,
      case when not in_both and qq1 = 0 and qq0 > 0 then -ss0 else 0 end stop_e,
      (xx1 - xx0) undec_e, (ss1 + xx1) - (ss0 + xx0) delta from calc c),
  ranked as (select e.*, row_number() over (order by abs(delta) desc, code) rn from eff e where delta <> 0)
  select jsonb_build_object(
    'ok', true, 'blended', false, 'currency', v_cur, 'country', p_country, 'site', p_site,
    'generated_at', now(), 'limit', v_lim,
    'windows', jsonb_build_object('current', jsonb_build_object('from', v_from, 'to', v_to),
      'previous', jsonb_build_object('from', v_pf, 'to', v_pt), 'days', v_len),
    'totals', jsonb_build_object('current', round(coalesce(sum(ss1 + xx1), 0), 2),
      'previous', round(coalesce(sum(ss0 + xx0), 0), 2), 'delta', round(coalesce(sum(delta), 0), 2),
      'lines_current', coalesce(sum(lines1), 0), 'lines_previous', coalesce(sum(lines0), 0)),
    'effects', jsonb_build_object(
      'price', round(coalesce(sum(price_e), 0), 2), 'volume', round(coalesce(sum(vol_e), 0), 2),
      'new_items', round(coalesce(sum(new_e), 0), 2), 'stopped_items', round(coalesce(sum(stop_e), 0), 2),
      'not_decomposable', round(coalesce(sum(undec_e), 0), 2),
      'items_both', count(*) filter (where in_both),
      'items_new', count(*) filter (where not in_both and qq0 = 0 and qq1 > 0),
      'items_stopped', count(*) filter (where not in_both and qq1 = 0 and qq0 > 0),
      'spend_priced_current', round(coalesce(sum(ss1), 0), 2),
      'spend_priced_previous', round(coalesce(sum(ss0), 0), 2)),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'code', code, 'label', coalesce(label, code),
        'qty_previous', round(qq0, 3), 'qty_current', round(qq1, 3),
        'spend_previous', round(ss0 + xx0, 2), 'spend_current', round(ss1 + xx1, 2),
        'price_previous', round(p0, 4), 'price_current', round(p1, 4),
        'price_effect', round(price_e, 2), 'volume_effect', round(vol_e, 2), 'delta', round(delta, 2),
        'lines_current', lines1, 'lines_previous', lines0,
        'kind', case when in_both then 'both' when qq0 = 0 and qq1 > 0 then 'new'
                     when qq1 = 0 and qq0 > 0 then 'stopped' else 'unpriced' end,
        'bucket', case when coalesce(tc,0) >= greatest(coalesce(sc,0), coalesce(oc,0)) and coalesce(tc,0) > 0 then 'tyre'
                       when coalesce(oc,0) >= coalesce(sc,0) and coalesce(oc,0) > 0 then 'oil'
                       when coalesce(sc,0) > 0 then 'spare' end)
        order by rn) from ranked where rn <= v_lim), '[]'::jsonb),
    'items_tail', (select jsonb_build_object('count', count(*), 'delta', round(coalesce(sum(delta),0),2),
        'price_effect', round(coalesce(sum(price_e),0),2), 'volume_effect', round(coalesce(sum(vol_e),0),2))
        from ranked where rn > v_lim),
    'dims', jsonb_build_object(
      'by_site', public._cost_var_dim(v_org, p_country, p_site, v_from, v_to, v_pf, v_pt, 'site', v_lim),
      'by_cost_center', public._cost_var_dim(v_org, p_country, p_site, v_from, v_to, v_pf, v_pt, 'cost_center', v_lim),
      'by_asset_type', public._cost_var_dim(v_org, p_country, p_site, v_from, v_to, v_pf, v_pt, 'asset_type', v_lim),
      'by_asset', public._cost_var_dim(v_org, p_country, p_site, v_from, v_to, v_pf, v_pt, 'asset_code', v_lim),
      'by_item', public._cost_var_dim(v_org, p_country, p_site, v_from, v_to, v_pf, v_pt, 'item_description', v_lim))
  ) into result from eff;
  return result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cost_variance_multi(p_countries text[] DEFAULT NULL::text[], p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org     uuid := public.app_current_org();
  v_allowed text[];
  v_refused text[] := '{}';
  v_country text;
  v_blocks  jsonb := '[]'::jsonb;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select allowed, refused into v_allowed, v_refused
    from public._scope_split_countries(p_countries);

  foreach v_country in array v_allowed loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'country',  v_country,
      'currency', public.currency_for_country(v_country),
      'result',   public.get_cost_variance(v_country, p_site, p_from, p_to, p_limit)));
  end loop;

  return jsonb_build_object(
    'ok', true, 'multi', true, 'generated_at', now(), 'blended', false,
    'requested', to_jsonb(coalesce(p_countries, '{}'::text[])),
    'refused',   to_jsonb(v_refused),
    'countries', v_blocks);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_costm3_ledger_monthly(p_kind text, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_out jsonb;
BEGIN
  IF p_kind = 'sco' THEN
    WITH rows AS (
      SELECT date_trunc('month', period_date)::date AS month, region, amount
        FROM public.sco_costs
       WHERE (p_country IS NULL OR country = p_country)
         AND (p_from IS NULL OR period_date >= p_from)
         AND (p_to   IS NULL OR period_date <= p_to)
    ),
    regions AS (
      SELECT month, coalesce(nullif(btrim(region), ''), 'Unassigned') AS region,
             count(*) AS entries, round(sum(coalesce(amount, 0))::numeric, 0) AS amount
        FROM rows GROUP BY 1, 2
    ),
    regions_j AS (
      SELECT month, jsonb_agg(jsonb_build_object('region', region, 'entries', entries, 'amount', amount)
               ORDER BY amount DESC) AS regions
        FROM regions GROUP BY month
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'month',   to_char(m.month, 'YYYY-MM'),
             'entries', m.entries,
             'amount',  m.amount,
             'regions', coalesce(r.regions, '[]'::jsonb)
           ) ORDER BY m.month DESC), '[]'::jsonb)
      INTO v_out
      FROM (SELECT month, count(*) AS entries, round(sum(coalesce(amount, 0))::numeric, 0) AS amount
              FROM rows GROUP BY month) m
      LEFT JOIN regions_j r USING (month);

  ELSIF p_kind = 'sany' THEN
    WITH rows AS (
      SELECT date_trunc('month', period_date)::date AS month, region, amount, doc_type
        FROM public.sany_invoices
       WHERE (p_country IS NULL OR country = p_country)
         AND (p_from IS NULL OR period_date >= p_from)
         AND (p_to   IS NULL OR period_date <= p_to)
    ),
    regions AS (
      SELECT month, coalesce(nullif(btrim(region), ''), 'Unassigned') AS region,
             count(*) FILTER (WHERE coalesce(doc_type, 'summary') <> 'detail') AS entries,
             round(sum(coalesce(amount, 0)) FILTER (WHERE coalesce(doc_type, 'summary') <> 'detail')::numeric, 0) AS amount
        FROM rows GROUP BY 1, 2
    ),
    regions_j AS (
      SELECT month, jsonb_agg(jsonb_build_object('region', region, 'entries', entries, 'amount', coalesce(amount, 0))
               ORDER BY coalesce(amount, 0) DESC) AS regions
        FROM regions GROUP BY month
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'month',          to_char(m.month, 'YYYY-MM'),
             'entries',        m.entries,
             'amount',         m.amount,
             'detail_entries', m.detail_entries,
             'regions',        coalesce(r.regions, '[]'::jsonb)
           ) ORDER BY m.month DESC), '[]'::jsonb)
      INTO v_out
      FROM (SELECT month,
                   count(*) FILTER (WHERE coalesce(doc_type, 'summary') <> 'detail') AS entries,
                   count(*) FILTER (WHERE doc_type = 'detail') AS detail_entries,
                   round(coalesce(sum(coalesce(amount, 0)) FILTER (WHERE coalesce(doc_type, 'summary') <> 'detail'), 0)::numeric, 0) AS amount
              FROM rows GROUP BY month) m
      LEFT JOIN regions_j r USING (month);
  ELSE
    RAISE EXCEPTION 'Unknown ledger kind: %', p_kind;
  END IF;

  RETURN coalesce(v_out, '[]'::jsonb);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_country_kpi(p_country text DEFAULT NULL::text)
 RETURNS TABLE(country text, total_records bigint, total_cost numeric, avg_cost_tyre numeric, high_risk_count bigint, high_risk_pct numeric, avg_cpk numeric, sites_count bigint, brands_count bigint, latest_date date, open_actions bigint, overdue_actions bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select
    t.country,
    count(t.id)                                                   as total_records,
    round(sum(t.cost_per_tyre * coalesce(t.qty,1)), 0)            as total_cost,
    round(avg(t.cost_per_tyre), 0)                                as avg_cost_tyre,
    count(*) filter (
      where t.risk_level in ('High','Critical'))                  as high_risk_count,
    round(
      count(*) filter (where t.risk_level in ('High','Critical'))
      ::numeric / nullif(count(t.id),0) * 100, 1)                as high_risk_pct,
    round(avg(
      public.calc_cpk(t.cost_per_tyre, t.km_at_fitment, t.km_at_removal)
    ) filter (
      where public.calc_cpk(t.cost_per_tyre, t.km_at_fitment, t.km_at_removal)
            is not null), 4)                                      as avg_cpk,
    count(distinct t.site)                                        as sites_count,
    count(distinct t.brand)                                       as brands_count,
    max(t.issue_date)                                             as latest_date,
    (select count(*) from public.corrective_actions a
       where (a.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and a.status = 'Open' and (a.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(a.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((a.site)::text is null or btrim((a.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((a.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and (p_country is null or a.country = t.country))        as open_actions,
    (select count(*) from public.corrective_actions a
       where (a.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and a.status  != 'Closed' and (a.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(a.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((a.site)::text is null or btrim((a.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((a.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and a.due_date < current_date
         and (p_country is null or a.country = t.country))        as overdue_actions
  from public.tyre_records t
  where (t.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and (p_country is null or t.country = p_country) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  group by t.country
  order by total_records desc
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_drivers(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_prev_from date DEFAULT NULL::date, p_prev_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_t1  date := coalesce(p_to, current_date);
  v_f1  date := coalesce(p_from, current_date - 365);
  v_t0  date := coalesce(p_prev_to, v_f1 - 1);
  v_f0  date := coalesce(p_prev_from, v_f1 - 1 - (v_t1 - v_f1));
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
begin

  if nullif(btrim(coalesce(p_site, '')), '') is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  return (
    with
    fleet as (
      select f.country, upper(btrim(f.asset_no)) as asset_no,
             public.cpk_unit_for_asset_type(f.vehicle_type) as unit
        from public.vehicle_fleet f
       where f.organisation_id = v_org and (p_country is null or f.country = p_country) and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(f.asset_no), '') <> ''
         and (v_site is null or upper(btrim(f.site)) = v_site)
    ),
    km1 as (select country, upper(btrim(asset_no)) asset_no, km_run    from public.fleet_tyre_km_by_asset(v_org, p_country, v_f1, v_t1) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    km0 as (select country, upper(btrim(asset_no)) asset_no, km_run    from public.fleet_tyre_km_by_asset(v_org, p_country, v_f0, v_t0) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr1 as (select country, upper(btrim(asset_no)) asset_no, hours_run from public.fleet_hours_by_asset(v_org, p_country, v_f1, v_t1) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr0 as (select country, upper(btrim(asset_no)) asset_no, hours_run from public.fleet_hours_by_asset(v_org, p_country, v_f0, v_t0) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    tr as (
      select t.country, upper(btrim(t.asset_no)) asset_no,
             coalesce(nullif(btrim(t.brand), ''), 'Unknown') as brand,
             coalesce(nullif(btrim(t.size),  ''), 'Unknown') as size,
             coalesce(t.issue_date, t.fitment_date) as d,
             coalesce(t.cost_per_tyre, 0) * greatest(coalesce(t.qty, 1), 1) as v,
             greatest(coalesce(t.qty, 1), 1) as q
        from public.tyre_records t
       where t.organisation_id = v_org and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(t.cost_per_tyre, 0) > 0
         and coalesce(t.issue_date, t.fitment_date) is not null
    ),
    cost1 as (select country, asset_no, sum(v) v, sum(q) q from tr where d between v_f1 and v_t1 group by 1, 2),
    cost0 as (select country, asset_no, sum(v) v, sum(q) q from tr where d between v_f0 and v_t0 group by 1, 2),
    ast as (
      select fl.country, fl.asset_no, fl.unit,
             case when fl.unit = 'km' then coalesce(km1.km_run, 0)    else coalesce(hr1.hours_run, 0) end as d1,
             case when fl.unit = 'km' then coalesce(km0.km_run, 0)    else coalesce(hr0.hours_run, 0) end as d0,
             coalesce(c1.v, 0) as v1, coalesce(c0.v, 0) as v0
        from fleet fl
        left join km1 on km1.country = fl.country and km1.asset_no = fl.asset_no
        left join km0 on km0.country = fl.country and km0.asset_no = fl.asset_no
        left join hr1 on hr1.country = fl.country and hr1.asset_no = fl.asset_no
        left join hr0 on hr0.country = fl.country and hr0.asset_no = fl.asset_no
        left join cost1 c1 on c1.country = fl.country and c1.asset_no = fl.asset_no
        left join cost0 c0 on c0.country = fl.country and c0.asset_no = fl.asset_no
    ),
    seg as (
      select country, unit,
             sum(v1) filter (where d1 > 0)               as c1,
             sum(d1) filter (where d1 > 0)               as d1,
             sum(v0) filter (where d0 > 0)               as c0,
             sum(d0) filter (where d0 > 0)               as d0,
             count(*) filter (where d1 > 0)              as matched1,
             count(*) filter (where d0 > 0)              as matched0,
             coalesce(sum(v1) filter (where d1 > 0 and d0 <= 0), 0)  as new_equipment,
             -coalesce(sum(v0) filter (where d0 > 0 and d1 <= 0), 0) as stopped_equipment
        from ast group by country, unit
    ),
    cont as (select country, asset_no, unit from ast where d1 > 0 and d0 > 0),
    grp1 as (
      select t.country, ca.unit, (t.brand || '||' || t.size) as g, sum(t.v) v, sum(t.q) q
        from tr t join cont ca on ca.country = t.country and ca.asset_no = t.asset_no
       where t.d between v_f1 and v_t1 group by 1, 2, 3
    ),
    grp0 as (
      select t.country, ca.unit, (t.brand || '||' || t.size) as g, sum(t.v) v, sum(t.q) q
        from tr t join cont ca on ca.country = t.country and ca.asset_no = t.asset_no
       where t.d between v_f0 and v_t0 group by 1, 2, 3
    ),
    grp as (
      select coalesce(g1.country, g0.country) as country,
             coalesce(g1.unit,    g0.unit)    as unit,
             coalesce(g0.v, 0) v0, coalesce(g0.q, 0) q0,
             coalesce(g1.v, 0) v1, coalesce(g1.q, 0) q1,
             (g0.g is not null) as in0, (g1.g is not null) as in1
        from grp1 g1
        full join grp0 g0 on g0.country = g1.country and g0.unit = g1.unit and g0.g = g1.g
    ),
    grp_eff as (
      select country, unit,
             case when in0 and in1 then (v1 / nullif(q1, 0) - v0 / nullif(q0, 0)) * (q0 + q1) / 2.0 else 0 end as price_c,
             case when in0 and in1 then (q1 - q0) * (v0 / nullif(q0, 0) + v1 / nullif(q1, 0)) / 2.0 else 0 end as vol_c,
             case when in1 and not in0 then v1 when in0 and not in1 then -v0 else 0 end as mix_c
        from grp
    ),
    segc as (
      select country, unit, sum(price_c) price, sum(vol_c) volume, sum(mix_c) mix
        from grp_eff group by country, unit
    )
    select jsonb_build_object(
      'ok', true, 'org', v_org,
      'windows', jsonb_build_object(
        'current',  jsonb_build_object('from', v_f1, 'to', v_t1, 'days', (v_t1 - v_f1) + 1),
        'previous', jsonb_build_object('from', v_f0, 'to', v_t0, 'days', (v_t0 - v_f0) + 1)
      ),
      'segments', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', s.country, 'unit', s.unit, 'currency', coalesce(cc.currency, s.country),
          'c0', round(coalesce(s.c0, 0), 2), 'd0', round(coalesce(s.d0, 0), 1),
          'c1', round(coalesce(s.c1, 0), 2), 'd1', round(coalesce(s.d1, 0), 1),
          'matched_prev', s.matched0, 'matched_now', s.matched1,
          'causes', jsonb_build_object(
            'price', round(coalesce(sc.price, 0), 2), 'volume', round(coalesce(sc.volume, 0), 2),
            'mix', round(coalesce(sc.mix, 0), 2),
            'new_equipment', round(s.new_equipment, 2), 'stopped_equipment', round(s.stopped_equipment, 2)
          )
        ) order by coalesce(s.c1, 0) desc), '[]'::jsonb)
        from seg s
        left join segc sc on sc.country = s.country and sc.unit = s.unit
        left join public.country_currency cc on cc.country = s.country
        where coalesce(s.c1, 0) > 0 or coalesce(s.c0, 0) > 0
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_drivers_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_prev_from date DEFAULT NULL::date, p_prev_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_t1  date := coalesce(p_to, current_date);
  v_f1  date := coalesce(p_from, current_date - 365);
  v_t0  date := coalesce(p_prev_to, v_f1 - 1);
  v_f0  date := coalesce(p_prev_from, v_f1 - 1 - (v_t1 - v_f1));
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  return (
    with
    fleet as (
      select f.country, upper(btrim(f.asset_no)) as asset_no,
             public.cpk_unit_for_asset_type(f.vehicle_type) as unit
        from public.vehicle_fleet f
       where f.organisation_id = v_org and (p_country is null or f.country = p_country) and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(f.asset_no), '') <> ''
    ),
    km1 as (select country, upper(btrim(asset_no)) asset_no, km_run    from public.fleet_tyre_km_by_asset(v_org, p_country, v_f1, v_t1) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    km0 as (select country, upper(btrim(asset_no)) asset_no, km_run    from public.fleet_tyre_km_by_asset(v_org, p_country, v_f0, v_t0) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr1 as (select country, upper(btrim(asset_no)) asset_no, hours_run from public.fleet_hours_by_asset(v_org, p_country, v_f1, v_t1) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr0 as (select country, upper(btrim(asset_no)) asset_no, hours_run from public.fleet_hours_by_asset(v_org, p_country, v_f0, v_t0) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    tr as (
      select t.country, upper(btrim(t.asset_no)) asset_no,
             coalesce(nullif(btrim(t.brand), ''), 'Unknown') as brand,
             coalesce(nullif(btrim(t.size),  ''), 'Unknown') as size,
             coalesce(t.issue_date, t.fitment_date) as d,
             coalesce(t.cost_per_tyre, 0) * greatest(coalesce(t.qty, 1), 1) as v,
             greatest(coalesce(t.qty, 1), 1) as q
        from public.tyre_records t
       where t.organisation_id = v_org and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(t.cost_per_tyre, 0) > 0
         and coalesce(t.issue_date, t.fitment_date) is not null
    ),
    cost1 as (select country, asset_no, sum(v) v, sum(q) q from tr where d between v_f1 and v_t1 group by 1, 2),
    cost0 as (select country, asset_no, sum(v) v, sum(q) q from tr where d between v_f0 and v_t0 group by 1, 2),
    ast as (
      select fl.country, fl.asset_no, fl.unit,
             case when fl.unit = 'km' then coalesce(km1.km_run, 0)    else coalesce(hr1.hours_run, 0) end as d1,
             case when fl.unit = 'km' then coalesce(km0.km_run, 0)    else coalesce(hr0.hours_run, 0) end as d0,
             coalesce(c1.v, 0) as v1, coalesce(c0.v, 0) as v0
        from fleet fl
        left join km1 on km1.country = fl.country and km1.asset_no = fl.asset_no
        left join km0 on km0.country = fl.country and km0.asset_no = fl.asset_no
        left join hr1 on hr1.country = fl.country and hr1.asset_no = fl.asset_no
        left join hr0 on hr0.country = fl.country and hr0.asset_no = fl.asset_no
        left join cost1 c1 on c1.country = fl.country and c1.asset_no = fl.asset_no
        left join cost0 c0 on c0.country = fl.country and c0.asset_no = fl.asset_no
    ),
    seg as (
      select country, unit,
             sum(v1) filter (where d1 > 0)               as c1,
             sum(d1) filter (where d1 > 0)               as d1,
             sum(v0) filter (where d0 > 0)               as c0,
             sum(d0) filter (where d0 > 0)               as d0,
             count(*) filter (where d1 > 0)              as matched1,
             count(*) filter (where d0 > 0)              as matched0,
             coalesce(sum(v1) filter (where d1 > 0 and d0 <= 0), 0)  as new_equipment,
             -coalesce(sum(v0) filter (where d0 > 0 and d1 <= 0), 0) as stopped_equipment
        from ast group by country, unit
    ),
    cont as (select country, asset_no, unit from ast where d1 > 0 and d0 > 0),
    grp1 as (
      select t.country, ca.unit, (t.brand || '||' || t.size) as g, sum(t.v) v, sum(t.q) q
        from tr t join cont ca on ca.country = t.country and ca.asset_no = t.asset_no
       where t.d between v_f1 and v_t1 group by 1, 2, 3
    ),
    grp0 as (
      select t.country, ca.unit, (t.brand || '||' || t.size) as g, sum(t.v) v, sum(t.q) q
        from tr t join cont ca on ca.country = t.country and ca.asset_no = t.asset_no
       where t.d between v_f0 and v_t0 group by 1, 2, 3
    ),
    grp as (
      select coalesce(g1.country, g0.country) as country,
             coalesce(g1.unit,    g0.unit)    as unit,
             coalesce(g0.v, 0) v0, coalesce(g0.q, 0) q0,
             coalesce(g1.v, 0) v1, coalesce(g1.q, 0) q1,
             (g0.g is not null) as in0, (g1.g is not null) as in1
        from grp1 g1
        full join grp0 g0 on g0.country = g1.country and g0.unit = g1.unit and g0.g = g1.g
    ),
    grp_eff as (
      select country, unit,
             case when in0 and in1 then (v1 / nullif(q1, 0) - v0 / nullif(q0, 0)) * (q0 + q1) / 2.0 else 0 end as price_c,
             case when in0 and in1 then (q1 - q0) * (v0 / nullif(q0, 0) + v1 / nullif(q1, 0)) / 2.0 else 0 end as vol_c,
             case when in1 and not in0 then v1 when in0 and not in1 then -v0 else 0 end as mix_c
        from grp
    ),
    segc as (
      select country, unit, sum(price_c) price, sum(vol_c) volume, sum(mix_c) mix
        from grp_eff group by country, unit
    )
    select jsonb_build_object(
      'ok', true, 'org', v_org,
      'windows', jsonb_build_object(
        'current',  jsonb_build_object('from', v_f1, 'to', v_t1, 'days', (v_t1 - v_f1) + 1),
        'previous', jsonb_build_object('from', v_f0, 'to', v_t0, 'days', (v_t0 - v_f0) + 1)
      ),
      'segments', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', s.country, 'unit', s.unit, 'currency', coalesce(cc.currency, s.country),
          'c0', round(coalesce(s.c0, 0), 2), 'd0', round(coalesce(s.d0, 0), 1),
          'c1', round(coalesce(s.c1, 0), 2), 'd1', round(coalesce(s.d1, 0), 1),
          'matched_prev', s.matched0, 'matched_now', s.matched1,
          'causes', jsonb_build_object(
            'price', round(coalesce(sc.price, 0), 2), 'volume', round(coalesce(sc.volume, 0), 2),
            'mix', round(coalesce(sc.mix, 0), 2),
            'new_equipment', round(s.new_equipment, 2), 'stopped_equipment', round(s.stopped_equipment, 2)
          )
        ) order by coalesce(s.c1, 0) desc), '[]'::jsonb)
        from seg s
        left join segc sc on sc.country = s.country and sc.unit = s.unit
        left join public.country_currency cc on cc.country = s.country
        where coalesce(s.c1, 0) > 0 or coalesce(s.c0, 0) > 0
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_hours_source(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_asset text DEFAULT NULL::text, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
  v_rows jsonb; v_hours numeric; v_n integer; v_min numeric; v_max numeric;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_site is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_asset is null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'asset_no', s.asset_no, 'readings', s.readings, 'hours', s.hours_run) order by s.hours_run desc), '[]'::jsonb)
      into v_rows
      from (
        select upper(btrim(e.asset_no)) as asset_no, count(*) as readings,
               max(e.engine_hours) - min(e.engine_hours) as hours_run
          from public.engine_hours_logs e
         where e.organisation_id = v_org and (p_country is null or e.country = p_country) and (e.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(e.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
           and e.engine_hours > 0 and e.reading_date is not null and e.reading_date <= current_date
           and coalesce(btrim(e.asset_no), '') <> '' and e.reading_date between v_from and v_to
           and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from e.country and upper(btrim(f.asset_no)) = upper(btrim(e.asset_no)) and upper(btrim(f.site)) = v_site))
         group by 1 having count(*) > 1
      ) s
      where s.hours_run > 0 and s.hours_run <= 24 * greatest(1, (v_to - v_from));
    return jsonb_build_object('ok', true, 'source', 'engine_hour_readings',
      'basis', 'span = max(engine_hours) - min(engine_hours) over the period readings',
      'from', v_from, 'to', v_to, 'by_asset', v_rows);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'reading_date', e.reading_date, 'engine_hours', e.engine_hours) order by e.reading_date), '[]'::jsonb),
         count(*), min(e.engine_hours), max(e.engine_hours)
    into v_rows, v_n, v_min, v_max
    from public.engine_hours_logs e
   where e.organisation_id = v_org and (p_country is null or e.country = p_country) and (e.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(e.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and upper(btrim(e.asset_no)) = upper(btrim(p_asset))
     and e.engine_hours > 0 and e.reading_date is not null and e.reading_date <= current_date
     and e.reading_date between v_from and v_to
     and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from e.country and upper(btrim(f.asset_no)) = upper(btrim(e.asset_no)) and upper(btrim(f.site)) = v_site));
  v_hours := case when v_n > 1 then v_max - v_min else null end;

  return jsonb_build_object('ok', true, 'source', 'engine_hour_readings',
    'basis', 'span = max(engine_hours) - min(engine_hours) over the period readings',
    'asset_no', upper(btrim(p_asset)), 'from', v_from, 'to', v_to,
    'reading_count', v_n, 'min_hours', v_min, 'max_hours', v_max, 'hours', v_hours, 'readings', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_hours_source_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_asset text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_rows jsonb; v_hours numeric; v_n integer; v_min numeric; v_max numeric;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_asset is null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'asset_no', s.asset_no, 'readings', s.readings, 'hours', s.hours_run) order by s.hours_run desc), '[]'::jsonb)
      into v_rows
      from (
        select upper(btrim(e.asset_no)) as asset_no, count(*) as readings,
               max(e.engine_hours) - min(e.engine_hours) as hours_run
          from public.engine_hours_logs e
         where e.organisation_id = v_org and (p_country is null or e.country = p_country) and (e.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(e.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
           and e.engine_hours > 0 and e.reading_date is not null and e.reading_date <= current_date
           and coalesce(btrim(e.asset_no), '') <> '' and e.reading_date between v_from and v_to
         group by 1 having count(*) > 1
      ) s
      where s.hours_run > 0 and s.hours_run <= 24 * greatest(1, (v_to - v_from));
    return jsonb_build_object('ok', true, 'source', 'engine_hour_readings',
      'basis', 'span = max(engine_hours) - min(engine_hours) over the period readings',
      'from', v_from, 'to', v_to, 'by_asset', v_rows);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'reading_date', e.reading_date, 'engine_hours', e.engine_hours) order by e.reading_date), '[]'::jsonb),
         count(*), min(e.engine_hours), max(e.engine_hours)
    into v_rows, v_n, v_min, v_max
    from public.engine_hours_logs e
   where e.organisation_id = v_org and (p_country is null or e.country = p_country) and (e.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(e.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and upper(btrim(e.asset_no)) = upper(btrim(p_asset))
     and e.engine_hours > 0 and e.reading_date is not null and e.reading_date <= current_date
     and e.reading_date between v_from and v_to;
  v_hours := case when v_n > 1 then v_max - v_min else null end;

  return jsonb_build_object('ok', true, 'source', 'engine_hour_readings',
    'basis', 'span = max(engine_hours) - min(engine_hours) over the period readings',
    'asset_no', upper(btrim(p_asset)), 'from', v_from, 'to', v_to,
    'reading_count', v_n, 'min_hours', v_min, 'max_hours', v_max, 'hours', v_hours, 'readings', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_km_intelligence(p_country text DEFAULT 'KSA'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_site is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  return (
    with
    tk as (select upper(btrim(asset_no)) asset_no, sum(km_run) tyre_km
             from public.fleet_tyre_km_by_asset(v_org, p_country, v_from, v_to) group by 1),
    eh as (select upper(btrim(asset_no)) asset_no, sum(hours_run) eng_hours
             from public.fleet_hours_by_asset(v_org, p_country, v_from, v_to) group by 1),
    fleet as (select upper(btrim(asset_no)) asset_no, nullif(btrim(vehicle_type),'') vt,
                     public.cpk_unit_for_asset_type(vehicle_type) unit
                from public.vehicle_fleet
               where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
                 and coalesce(btrim(asset_no),'')<>''
                 and (v_site is null or upper(btrim(site)) = v_site)),
    m as (select asset_no, odo_km, hour_hours, odo_readings, odo_resets, odo_months
            from public.cpk_asset_meter where organisation_id=v_org and country=coalesce(p_country,'KSA')),
    j as (
      select f.asset_no, f.vt vehicle_type, f.unit,
             coalesce(tk.tyre_km,0) tyre_km, coalesce(eh.eng_hours,0) eng_hours,
             coalesce(m.odo_km,0) odo_km, coalesce(m.hour_hours,0) meter_hours,
             coalesce(m.odo_readings,0) odo_readings, coalesce(m.odo_resets,0) odo_resets,
             coalesce(m.odo_months,0) odo_months
        from fleet f
        left join tk on tk.asset_no=f.asset_no
        left join eh on eh.asset_no=f.asset_no
        left join m  on m.asset_no=f.asset_no
    ),
    scored as (
      select *,
        case when odo_km<=0 then 'none'
             when odo_months>=6 and odo_resets<=2 then 'high'
             when odo_months>=3 then 'medium' else 'low' end odo_confidence,
        case when tyre_km>0 and odo_km>0 then 'both'
             when tyre_km>0 then 'tyre_only'
             when odo_km>0 then 'odo_only' else 'neither' end coverage,
        case when tyre_km>0 and odo_km>0 then round(100.0*odo_km/nullif(tyre_km,0),0) else null end odo_vs_tyre_pct
      from j
    )
    select jsonb_build_object(
      'ok', true, 'country', p_country, 'from', v_from, 'to', v_to,
      'summary', jsonb_build_object(
        'assets', (select count(*) from scored where tyre_km>0 or odo_km>0),
        'tyre_km_assets', (select count(*) from scored where tyre_km>0),
        'odo_km_assets', (select count(*) from scored where odo_km>0),
        'both', (select count(*) from scored where coverage='both'),
        'tyre_only', (select count(*) from scored where coverage='tyre_only'),
        'odo_only', (select count(*) from scored where coverage='odo_only'),
        'tyre_km_total', (select round(sum(tyre_km)) from scored),
        'odo_km_total', (select round(sum(odo_km)) from scored),
        'eng_hours_total', (select round(sum(eng_hours)) from scored),
        'meter_hours_total', (select round(sum(meter_hours)) from scored),
        'odo_high_conf', (select count(*) from scored where odo_confidence='high'),
        'note', 'tyre_km = sum of tyre lives in the period (current CPK basis). odo_km = smoothed vehicle distance from the master odometer (all history). They measure different things; use per-asset reconciliation to judge which to trust.'
      ),
      'per_asset', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'asset_no', asset_no, 'vehicle_type', vehicle_type, 'unit', unit,
          'tyre_km', round(tyre_km), 'odo_km', round(odo_km),
          'eng_hours', round(eng_hours), 'meter_hours', round(meter_hours),
          'odo_readings', odo_readings, 'odo_resets', odo_resets, 'odo_months', odo_months,
          'odo_confidence', odo_confidence, 'coverage', coverage, 'odo_vs_tyre_pct', odo_vs_tyre_pct
        ) order by (tyre_km + odo_km) desc), '[]'::jsonb)
        from scored where tyre_km>0 or odo_km>0
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_km_intelligence_v1_retired(p_country text DEFAULT 'KSA'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
