      'summary', jsonb_build_object(
        'assets', (select count(*) from scored where tyre_km>0 or odo_km>0),
        'tyre_km_assets', (select count(*) from scored where tyre_km>0),
        'odo_km_assets', (select count(*) from scored where odo_km>0),
        'both', (select count(*) from scored where coverage='both'),
        'tyre_only', (select count(*) from scored where coverage='tyre_only'),
        'odo_only', (select count(*) from scored where coverage='odo_only'),
        'tyre_km_total', (select round(sum(tyre_km)) from scored),
        'odo_km_total', (select round(sum(odo_km)) from scored),
        'eng_hours_total', (select round(sum(eng_hours)) from scored),
        'meter_hours_total', (select round(sum(meter_hours)) from scored),
        'odo_high_conf', (select count(*) from scored where odo_confidence='high'),
        'note', 'tyre_km = sum of tyre lives in the period (current CPK basis). odo_km = smoothed vehicle distance from the master odometer (all history). They measure different things; use per-asset reconciliation to judge which to trust.'
      ),
      'per_asset', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'asset_no', asset_no, 'vehicle_type', vehicle_type, 'unit', unit,
          'tyre_km', round(tyre_km), 'odo_km', round(odo_km),
          'eng_hours', round(eng_hours), 'meter_hours', round(meter_hours),
          'odo_readings', odo_readings, 'odo_resets', odo_resets, 'odo_months', odo_months,
          'odo_confidence', odo_confidence, 'coverage', coverage, 'odo_vs_tyre_pct', odo_vs_tyre_pct
        ) order by (tyre_km + odo_km) desc), '[]'::jsonb)
        from scored where tyre_km>0 or odo_km>0
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_km_source(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_asset text DEFAULT NULL::text, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
  v_rows jsonb;
  v_km numeric;
  v_n integer;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_site is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_asset is null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'asset_no', a.asset_no, 'tyres', a.tyres, 'km', a.km) order by a.km desc), '[]'::jsonb)
      into v_rows
      from (
        select upper(btrim(t.asset_no)) as asset_no, count(*) as tyres, sum(t.total_km)::numeric as km
          from public.tyre_records t
         where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
           and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
           and t.total_km is not null and t.total_km > 0
           and coalesce(btrim(t.asset_no), '') <> ''
           and coalesce(t.removal_date, t.issue_date) between v_from and v_to
           and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from t.country and upper(btrim(f.asset_no)) = upper(btrim(t.asset_no)) and upper(btrim(f.site)) = v_site))
         group by 1
      ) a;
    return jsonb_build_object('ok', true, 'source', 'monthly_tyre_consumption',
      'basis', 'sum of each tyre total_km, matched by coalesce(removal_date, issue_date)',
      'from', v_from, 'to', v_to, 'by_asset', v_rows);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'serial_no', t.serial_no, 'position', coalesce(t.tyre_position, t.position),
           'brand', t.brand, 'size', t.size, 'job_card', t.job_card,
           'issue_date', t.issue_date, 'fitment_date', t.fitment_date, 'removal_date', t.removal_date,
           'effective_date', coalesce(t.removal_date, t.issue_date),
           'km_at_fitment', t.km_at_fitment, 'km_at_removal', t.km_at_removal,
           'total_km', t.total_km, 'cost_per_tyre', t.cost_per_tyre, 'data_source', t.data_source
         ) order by coalesce(t.removal_date, t.issue_date) desc), '[]'::jsonb),
         coalesce(sum(t.total_km), 0)::numeric, count(*)
    into v_rows, v_km, v_n
    from public.tyre_records t
   where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
     and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and upper(btrim(t.asset_no)) = upper(btrim(p_asset))
     and t.total_km is not null and t.total_km > 0
     and coalesce(t.removal_date, t.issue_date) between v_from and v_to
     and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from t.country and upper(btrim(f.asset_no)) = upper(btrim(t.asset_no)) and upper(btrim(f.site)) = v_site));

  return jsonb_build_object('ok', true, 'source', 'monthly_tyre_consumption',
    'basis', 'sum of each tyre total_km, matched by coalesce(removal_date, issue_date)',
    'asset_no', upper(btrim(p_asset)), 'from', v_from, 'to', v_to,
    'km', v_km, 'tyre_count', v_n, 'tyres', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_km_source_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_asset text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_rows jsonb;
  v_km numeric;
  v_n integer;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_asset is null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'asset_no', a.asset_no, 'tyres', a.tyres, 'km', a.km) order by a.km desc), '[]'::jsonb)
      into v_rows
      from (
        select upper(btrim(t.asset_no)) as asset_no, count(*) as tyres, sum(t.total_km)::numeric as km
          from public.tyre_records t
         where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
           and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
           and t.total_km is not null and t.total_km > 0
           and coalesce(btrim(t.asset_no), '') <> ''
           and coalesce(t.removal_date, t.issue_date) between v_from and v_to
         group by 1
      ) a;
    return jsonb_build_object('ok', true, 'source', 'monthly_tyre_consumption',
      'basis', 'sum of each tyre total_km, matched by coalesce(removal_date, issue_date)',
      'from', v_from, 'to', v_to, 'by_asset', v_rows);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'serial_no', t.serial_no, 'position', coalesce(t.tyre_position, t.position),
           'brand', t.brand, 'size', t.size, 'job_card', t.job_card,
           'issue_date', t.issue_date, 'fitment_date', t.fitment_date, 'removal_date', t.removal_date,
           'effective_date', coalesce(t.removal_date, t.issue_date),
           'km_at_fitment', t.km_at_fitment, 'km_at_removal', t.km_at_removal,
           'total_km', t.total_km, 'cost_per_tyre', t.cost_per_tyre, 'data_source', t.data_source
         ) order by coalesce(t.removal_date, t.issue_date) desc), '[]'::jsonb),
         coalesce(sum(t.total_km), 0)::numeric, count(*)
    into v_rows, v_km, v_n
    from public.tyre_records t
   where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
     and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and upper(btrim(t.asset_no)) = upper(btrim(p_asset))
     and t.total_km is not null and t.total_km > 0
     and coalesce(t.removal_date, t.issue_date) between v_from and v_to;

  return jsonb_build_object('ok', true, 'source', 'monthly_tyre_consumption',
    'basis', 'sum of each tyre total_km, matched by coalesce(removal_date, issue_date)',
    'asset_no', upper(btrim(p_asset)), 'from', v_from, 'to', v_to,
    'km', v_km, 'tyre_count', v_n, 'tyres', v_rows);
end;
$function$;
