CREATE OR REPLACE FUNCTION public.get_cpk_unit_audit(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
  v_rows jsonb; v_summary jsonb;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_site is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  with km as (
    select upper(btrim(t.asset_no)) as asset_no, t.country, sum(t.total_km)::numeric as km
      from public.tyre_records t
     where t.organisation_id = v_org and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and t.total_km is not null and t.total_km > 0 and coalesce(btrim(t.asset_no),'') <> ''
       and coalesce(t.removal_date, t.issue_date) between v_from and v_to
       and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from t.country and upper(btrim(f.asset_no)) = upper(btrim(t.asset_no)) and upper(btrim(f.site)) = v_site))
     group by 1, 2
  ),
  hrs as (
    select s.asset_no, s.country, s.hours_run as hours from (
      select upper(btrim(e.asset_no)) as asset_no, e.country,
             max(e.engine_hours) - min(e.engine_hours) as hours_run, count(*) c
        from public.engine_hours_logs e
       where e.organisation_id = v_org and (p_country is null or e.country = p_country) and (e.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(e.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((e.site)::text is null or btrim((e.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((e.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and e.engine_hours > 0 and e.reading_date is not null and e.reading_date <= current_date
         and coalesce(btrim(e.asset_no),'') <> '' and e.reading_date between v_from and v_to
         and (v_site is null or exists (select 1 from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not distinct from e.country and upper(btrim(f.asset_no)) = upper(btrim(e.asset_no)) and upper(btrim(f.site)) = v_site))
       group by 1, 2
    ) s where s.c > 1 and s.hours_run > 0 and s.hours_run <= 24 * greatest(1, (v_to - v_from))
  ),
  keys as (
    select asset_no, country from km union select asset_no, country from hrs
  ),
  typed as (
    select k.asset_no, k.country,
           coalesce(
             (select vf.vehicle_type from public.vehicle_fleet vf
               where vf.organisation_id = v_org and upper(btrim(vf.asset_no)) = k.asset_no
                 and (k.country is null or vf.country = k.country)
                 and coalesce(btrim(vf.vehicle_type),'') <> '' limit 1),
             (select mode() within group (order by tr.vehicle_type) from public.tyre_records tr
               where tr.organisation_id = v_org and upper(btrim(tr.asset_no)) = k.asset_no
                 and (k.country is null or tr.country = k.country) and coalesce(btrim(tr.vehicle_type),'') <> '')
           ) as vehicle_type,
           km.km, hrs.hours
      from keys k
      left join km on km.asset_no = k.asset_no and km.country is not distinct from k.country
      left join hrs on hrs.asset_no = k.asset_no and hrs.country is not distinct from k.country
  ),
  audited as (
    select asset_no, country, vehicle_type,
           public.cpk_unit_for_asset_type(vehicle_type) as unit,
           km, hours,
           (km is not null and km > 0) as has_km,
           (hours is not null and hours > 0) as has_hours
      from typed
  ),
  final as (
    select *,
      case public.cpk_unit_for_asset_type(vehicle_type) when 'engine_hours' then 'non_movable' else 'movable' end as side,
      case
        when has_km and has_hours then 'both_present'
        when unit = 'km' and not has_km and has_hours then 'off_unit_only'
        when unit = 'engine_hours' and not has_hours and has_km then 'off_unit_only'
        when unit = 'km' and not has_km then 'used_unit_no_data'
        when unit = 'engine_hours' and not has_hours then 'used_unit_no_data'
        else 'ok'
      end as status
    from audited
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'asset_no', asset_no, 'vehicle_type', vehicle_type, 'unit', unit, 'side', side,
           'km', km, 'hours', hours, 'has_km', has_km, 'has_hours', has_hours, 'status', status)
           order by (status <> 'ok') desc, coalesce(km, hours, 0) desc), '[]'::jsonb),
         jsonb_build_object(
           'assets', count(*),
           'movable', count(*) filter (where side = 'movable'),
           'non_movable', count(*) filter (where side = 'non_movable'),
           'both_present', count(*) filter (where status = 'both_present'),
           'off_unit_only', count(*) filter (where status = 'off_unit_only'),
           'used_unit_no_data', count(*) filter (where status = 'used_unit_no_data'))
    into v_rows, v_summary
    from final;

  return jsonb_build_object('ok', true, 'from', v_from, 'to', v_to,
    'note', 'CPK measures each asset in ONE unit chosen by its type (plant = engine hours, else km). An asset with data on both, or only on the other unit, is flagged so you can see why its CPK looks different.',
    'summary', v_summary, 'assets', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_cpk_unit_audit_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to date := coalesce(p_to, current_date);
  v_rows jsonb; v_summary jsonb;
