     group by 1, 2
  ),
  hrs as (
    select s.asset_no, s.country, s.hours_run as hours from (
      select upper(btrim(e.asset_no)) as asset_no, e.country,
             max(e.engine_hours) - min(e.engine_hours) as hours_run, count(*) c
