CREATE OR REPLACE FUNCTION public.get_daily_job_cards(p_country text DEFAULT NULL::text, p_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_day date := coalesce(p_on, current_date);
  v_cur text;
  result jsonb;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  v_cur := case when p_country is null then null
                else public.currency_for_country(p_country) end;

  with wo as (
    select * from public.work_orders
     where organisation_id = v_org and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and (p_country is null or country = p_country) and (country::text is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       -- Only the rows any output below can use: opened or completed on the
       -- day, or still out of production. Every figure is computed over these
       -- three groups, so narrowing here changes no number; it stops the CTE
       -- materialising every job card the country has ever had.
       and ((opened_at >= v_day and opened_at < v_day + 1)
         or (completed_at >= v_day and completed_at < v_day + 1)
         or (production_out_at is not null and production_in_at is null))
  ), today as (
    select * from wo
     where (opened_at    >= v_day and opened_at    < v_day + 1)
        or (completed_at >= v_day and completed_at < v_day + 1)
  ), still_out as (
    -- left production and not back. No date filter: an asset out since March is
    -- exactly what this panel exists to surface.
    select * from wo
     where production_out_at is not null
       and production_in_at is null
       and coalesce(status, '') not in ('Cancelled')
  ), closed_today as (
    select * from wo
     where completed_at >= v_day and completed_at < v_day + 1
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'day', v_day,
    'country', p_country,
    'currency', v_cur,
    'kpis', jsonb_build_object(
      'opened_today',   (select count(*) from wo where opened_at >= v_day and opened_at < v_day + 1),
      'closed_today',   (select count(*) from closed_today),
      'breakdowns_today',(select count(*) from wo
                           where opened_at >= v_day and opened_at < v_day + 1
                             and work_type = 'Emergency'),
      'scheduled_today',(select count(*) from wo
                           where opened_at >= v_day and opened_at < v_day + 1
                             and work_type = 'Preventive Maintenance'),
      'still_out',      (select count(*) from still_out),
      'still_out_assets',(select count(distinct asset_no) from still_out),
      -- null, not zero, when nothing closed today: an average of no jobs is
      -- unknown, and zero would read as instant turnaround
      'avg_wait_hours', (select round(avg(extract(epoch from (started_at - production_out_at))/3600)::numeric, 2)
                           from closed_today
                          where started_at is not null and production_out_at is not null
                            and started_at >= production_out_at),
      'avg_repair_hours',(select round(avg(extract(epoch from (completed_at - started_at))/3600)::numeric, 2)
                           from closed_today
                          where completed_at is not null and started_at is not null
                            and completed_at >= started_at),
      'longest_out_hours',(select round(max(extract(epoch from (now() - production_out_at))/3600)::numeric, 1)
                             from still_out)
    ),
    -- what is down right now, worst first. This is the actionable list.
    'still_out_list', (select coalesce(jsonb_agg(x order by x.hours_out desc, x.work_order_no asc), '[]'::jsonb) from (
        select work_order_no, asset_no, plate_no, asset_category, site, work_type, status,
               coalesce(description, notes) as complaint,
               round(extract(epoch from (now() - production_out_at))/3600::numeric, 1) as hours_out,
               (started_at is null) as not_started
          from still_out
         order by production_out_at asc, work_order_no asc
         limit 25) x),
    'today_list', (select coalesce(jsonb_agg(x order by x.opened_at desc, x.work_order_no desc), '[]'::jsonb) from (
        select work_order_no, asset_no, plate_no, site, work_type, status,
               coalesce(description, notes) as complaint,
               opened_at, completed_at, breakdown_hours
          from today
         order by opened_at desc nulls last, work_order_no desc
         limit 25) x),
    'by_type', (select coalesce(jsonb_agg(x order by x.n desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(work_type), ''), 'Unspecified') as label, count(*) n
          from today group by 1) x),
    'by_site', (select coalesce(jsonb_agg(x order by x.n desc, x.label), '[]'::jsonb) from (
        select coalesce(nullif(btrim(site), ''), 'Unspecified') as label, count(*) n
          from still_out group by 1) x)
  ) into result;

  return result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_data_trust_overview(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org  uuid := public.app_current_org();
  v_to   date := coalesce(p_to, current_date);
  v_from date := coalesce(p_from, coalesce(p_to, current_date) - 364);
  result jsonb;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  with scope as (
    select distinct country
      from public.parts_consumption
     where organisation_id = v_org
       and coalesce(btrim(country), '') <> ''
       and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  exp_win as (
    select p.country,
           count(*)::bigint                                            as lines,
           coalesce(sum(p.line_cost), 0)                               as spend,
           count(*) filter (
             where coalesce(p.classified_by, 'default') in ('default', 'unknown')
           )::bigint                                                   as lines_default,
           coalesce(sum(p.line_cost) filter (
             where coalesce(p.classified_by, 'default') in ('default', 'unknown')
           ), 0)                                                       as spend_default,
           count(*) filter (where coalesce(btrim(p.currency), '') = '')::bigint
                                                                       as lines_no_currency,
           count(*) filter (where coalesce(btrim(p.item_code), '') = '')::bigint
                                                                       as lines_no_item
      from public.parts_consumption p
     where p.organisation_id = v_org
       and (p_country is null or p.country = p_country) and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and p.event_date between v_from and v_to
     group by p.country
  ),
  exp_all as (
    select p.country,
           count(*)::bigint                                            as lines_total,
           count(*) filter (where p.event_date is null)::bigint        as lines_no_date,
           count(*) filter (where p.import_uid is null)::bigint        as lines_no_uid,
           max(p.event_date)                                           as last_event_date
      from public.parts_consumption p
     where p.organisation_id = v_org
       and (p_country is null or p.country = p_country) and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     group by p.country
  ),
  rev as (
    select p.country, coalesce(sum(p.line_cost), 0) as spend_reviewed
      from public.parts_consumption p
      join public.material_master m
        on m.organisation_id = p.organisation_id
       and m.country         = p.country
       and m.item_code       = p.item_code
       and m.reviewed
     where p.organisation_id = v_org
       and (p_country is null or p.country = p_country) and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and p.event_date between v_from and v_to
     group by p.country
  ),
  fleet_assets as (
    select country, upper(btrim(asset_no)) as a
      from public.vehicle_fleet
     where organisation_id = v_org
       and coalesce(btrim(asset_no), '') <> ''
  ),
  link as (
    select p.country,
           coalesce(sum(p.line_cost) filter (where f.a is not null), 0) as spend_linked,
           count(distinct upper(btrim(p.asset_code)))::bigint           as assets,
           count(distinct upper(btrim(p.asset_code)))
             filter (where f.a is not null)::bigint                     as assets_linked
      from public.parts_consumption p
      left join fleet_assets f
        on f.country = p.country
       and f.a       = upper(btrim(p.asset_code))
     where p.organisation_id = v_org
       and (p_country is null or p.country = p_country) and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and p.event_date between v_from and v_to
       and coalesce(btrim(p.asset_code), '') <> ''
     group by p.country
  ),
  km as (
    select k.country, count(*)::bigint as assets_measured
      from public.fleet_km_by_asset(v_org, p_country, v_from, v_to) k
     group by k.country
  ),
  tyres as (
    select t.country,
           count(*)::bigint                                                as rows_total,
           count(*) filter (where coalesce(btrim(t.brand), '') = '')::bigint
                                                                           as no_brand,
           count(*) filter (where t.cost_per_tyre is null or t.cost_per_tyre <= 0)::bigint
                                                                           as no_unit_cost,
           count(*) filter (where t.fitment_date is null)::bigint          as no_fitment_date,
           count(*) filter (
             where t.km_at_fitment > 0 and t.km_at_removal > 0
           )::bigint                                                       as km_span_both,
           count(*) filter (
             where t.fitment_date > current_date or t.removal_date > current_date
           )::bigint                                                       as future_dated,
           count(*) filter (
             where t.fitment_date is not null and t.removal_date is not null
               and t.removal_date < t.fitment_date
           )::bigint                                                       as removal_before_fitment,
           count(*) filter (
             where t.km_at_fitment > 0 and t.km_at_removal > 0
               and t.km_at_removal < t.km_at_fitment
           )::bigint                                                       as km_backwards
      from public.tyre_records t
     where t.organisation_id = v_org
       and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     group by t.country
  ),
  flt as (
    select v.country,
           count(*)::bigint                                                as rows_total,
           count(*) filter (where coalesce(btrim(v.vehicle_type), '') = '')::bigint
                                                                           as no_vehicle_type,
           count(*) filter (where coalesce(btrim(v.make), '') = '')::bigint
                                                                           as no_make
      from public.vehicle_fleet v
     where v.organisation_id = v_org
       and (p_country is null or v.country = p_country) and (v.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(v.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     group by v.country
  ),
  meters as (
    select s.country,
           (select count(*) from public.odometer_logs o
             where o.organisation_id = v_org and o.country = s.country)::bigint    as odometer_rows,
           (select count(*) from public.engine_hours_logs e
             where e.organisation_id = v_org and e.country = s.country)::bigint    as engine_hours_rows
      from scope s
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'window', jsonb_build_object('from', v_from, 'to', v_to),
    'country', p_country,
    'countries', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'country',  s.country,
          'currency', public.currency_for_country(s.country),
          'measures', jsonb_build_object(
            'expense_lines',              coalesce(w.lines, 0),
            'expense_spend',              round(coalesce(w.spend, 0), 2),
            'expense_lines_default',      coalesce(w.lines_default, 0),
            'expense_spend_default',      round(coalesce(w.spend_default, 0), 2),
            'expense_lines_no_currency',  coalesce(w.lines_no_currency, 0),
            'expense_lines_no_item',      coalesce(w.lines_no_item, 0),
            'expense_spend_reviewed',     round(coalesce(r.spend_reviewed, 0), 2),
            'expense_lines_total',        coalesce(a.lines_total, 0),
            'expense_lines_no_date',      coalesce(a.lines_no_date, 0),
            'expense_lines_no_uid',       coalesce(a.lines_no_uid, 0),
            'expense_last_event_date',    a.last_event_date,
            'expense_days_since',         case when a.last_event_date is null then null
                                               else greatest(0, current_date - a.last_event_date) end,
            'expense_spend_linked',       round(coalesce(l.spend_linked, 0), 2),
            'expense_assets',             coalesce(l.assets, 0),
            'expense_assets_linked',      coalesce(l.assets_linked, 0),
            'km_assets_measured',         coalesce(k.assets_measured, 0),
            'odometer_rows',              coalesce(mt.odometer_rows, 0),
            'engine_hours_rows',          coalesce(mt.engine_hours_rows, 0),
            'tyre_rows',                  coalesce(ty.rows_total, 0),
            'tyre_no_brand',              coalesce(ty.no_brand, 0),
            'tyre_no_unit_cost',          coalesce(ty.no_unit_cost, 0),
            'tyre_no_fitment_date',       coalesce(ty.no_fitment_date, 0),
            'tyre_km_span_both',          coalesce(ty.km_span_both, 0),
            'tyre_future_dated',          coalesce(ty.future_dated, 0),
            'tyre_removal_before_fitment', coalesce(ty.removal_before_fitment, 0),
            'tyre_km_backwards',          coalesce(ty.km_backwards, 0),
            'fleet_rows',                 coalesce(f.rows_total, 0),
            'fleet_no_vehicle_type',      coalesce(f.no_vehicle_type, 0),
            'fleet_no_make',              coalesce(f.no_make, 0)
          )
        ) order by s.country
      )
      from scope s
      left join exp_win w  on w.country  = s.country
      left join exp_all a  on a.country  = s.country
      left join rev     r  on r.country  = s.country
      left join link    l  on l.country  = s.country
      left join km      k  on k.country  = s.country
      left join tyres   ty on ty.country = s.country
      left join flt     f  on f.country  = s.country
      left join meters  mt on mt.country = s.country
    ), '[]'::jsonb)
  ) into result;

  return result;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_diagnostics_feed(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if v_org is null or not public.app_is_active() or not public.is_super_admin() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;
  return jsonb_build_object(
    'ok', true,
    'country', p_country,
    'summary', public.get_control_center_summary(p_country),
    'lineage', public.get_figure_lineage('tyre_cost', p_country, null, null)
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_display_snapshot(p_token text, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  t            public.display_tokens%ROWTYPE;
  v_org        uuid;
  v_kpis       jsonb;
  v_trend      jsonb;
  v_risk       jsonb;
  v_events     jsonb;
  v_branding   jsonb;
BEGIN
  SELECT * INTO t FROM public.display_tokens WHERE token = p_token;

  IF NOT FOUND OR NOT t.active
     OR (t.expires_at IS NOT NULL AND t.expires_at < now()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF t.password_hash IS NOT NULL THEN
    IF p_password IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'password_required');
    ELSIF not public.share_password_ok('display', t.id, p_password, t.password_hash) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_password');
    END IF;
  END IF;

  v_org := t.organisation_id;

  -- Record the view (best-effort, never blocks the snapshot).
  BEGIN
    UPDATE public.display_tokens
       SET last_viewed_at = now(), view_count = view_count + 1
     WHERE id = t.id;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  -- ── Aggregate KPIs (org-scoped, counts only) ──────────────────────────────
  v_kpis := jsonb_build_object(
    'tyres_total',
      (SELECT count(*) FROM public.tyre_records WHERE organisation_id = v_org),
    'spend_30d',
      (SELECT COALESCE(round(sum(COALESCE(cost_per_tyre,0) * COALESCE(qty,1))::numeric, 2), 0)
         FROM public.tyre_records
        WHERE organisation_id = v_org AND issue_date >= current_date - 30),
    'high_risk',
      (SELECT count(*) FROM public.tyre_records
        WHERE organisation_id = v_org AND lower(COALESCE(risk_level,'')) IN ('high','critical')),
    'inspections_30d',
      (SELECT count(*) FROM public.inspections
        WHERE organisation_id = v_org AND created_at >= now() - interval '30 days'),
    'open_workorders',
      (SELECT count(*) FROM public.work_orders
        WHERE organisation_id = v_org
          AND lower(COALESCE(status,'')) NOT IN ('closed','completed','done','cancelled')),
    'open_accidents',
      (SELECT count(*) FROM public.accidents
        WHERE organisation_id = v_org AND COALESCE(closure_status,'open') <> 'closed'),
    'fleet_size',
      (SELECT count(*) FROM public.vehicle_fleet WHERE organisation_id = v_org)
  );

  -- ── 6-month spend trend ───────────────────────────────────────────────────
  SELECT COALESCE(jsonb_agg(jsonb_build_object('month', m, 'spend', s) ORDER BY m), '[]'::jsonb)
    INTO v_trend
    FROM (
      SELECT to_char(date_trunc('month', issue_date), 'YYYY-MM') AS m,
             round(sum(COALESCE(cost_per_tyre,0) * COALESCE(qty,1))::numeric, 2) AS s
        FROM public.tyre_records
       WHERE organisation_id = v_org
         AND issue_date >= date_trunc('month', current_date) - interval '5 months'
       GROUP BY 1
    ) q;

  -- ── Risk breakdown ────────────────────────────────────────────────────────
  SELECT COALESCE(jsonb_agg(jsonb_build_object('level', lvl, 'count', c) ORDER BY c DESC), '[]'::jsonb)
    INTO v_risk
    FROM (
      SELECT COALESCE(NULLIF(trim(risk_level), ''), 'Unclassified') AS lvl, count(*) AS c
        FROM public.tyre_records
       WHERE organisation_id = v_org
       GROUP BY 1
    ) q;

  -- ── Recent activity (event TYPES + counts only, last 24h) ─────────────────
  SELECT COALESCE(jsonb_agg(jsonb_build_object('type', et, 'count', c) ORDER BY c DESC), '[]'::jsonb)
    INTO v_events
    FROM (
      SELECT event_type AS et, count(*) AS c
        FROM public.domain_events
       WHERE organisation_id = v_org AND created_at >= now() - interval '24 hours'
       GROUP BY 1
       LIMIT 12
    ) q;

  -- ── Branding (name + logo + colour) ───────────────────────────────────────
  SELECT jsonb_build_object(
           'name',          o.name,
           'logo_url',      COALESCE(o.settings->'branding'->>'logo_url', o.logo_url),
           'primary_color', o.settings->'branding'->>'primary_color'
         )
    INTO v_branding
    FROM public.organisations o WHERE o.id = v_org;

  RETURN jsonb_build_object(
    'ok',              true,
    'name',            t.name,
    'template',        t.template,
    'refresh_seconds', t.refresh_seconds,
    'rotate_seconds',  t.rotate_seconds,
    'generated_at',    now(),
    'branding',        COALESCE(v_branding, '{}'::jsonb),
    'kpis',            v_kpis,
    'spend_trend',     v_trend,
    'risk_breakdown',  v_risk,
    'recent_activity', v_events
  );
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_downstream_impact(p_asset text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v json;
begin
  if not public.app_is_active() then raise exception 'forbidden' using errcode='42501'; end if;
  with recursive down as (
    select to_asset, 1 lvl from public.lineage_edges where from_asset=p_asset
    union all
    select e.to_asset, d.lvl+1 from public.lineage_edges e join down d on e.from_asset=d.to_asset where d.lvl < 6
  )
  select json_build_object('ok',true,'asset',p_asset,
    'impacted',(select coalesce(json_agg(json_build_object('asset_id',a.asset_id,'kind',a.kind,'name',a.name)),'[]'::json)
                from public.data_assets a where a.asset_id in (select distinct to_asset from down)),
    'counts',(select coalesce(json_object_agg(kind,c),'{}'::json) from
                (select a.kind, count(*) c from public.data_assets a where a.asset_id in (select distinct to_asset from down) group by a.kind) z))
  into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_email_by_identifier(identifier text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_id    text := btrim(identifier);
  v_email text;
begin
  if v_id is null or v_id = '' then
    return null;
  end if;

  -- Username first (exact, case-insensitive)...
  select au.email into v_email
  from auth.users au
  join public.profiles p on p.id = au.id
  where lower(p.username) = lower(v_id)
  limit 1;

  -- ...then employee code.
  if v_email is null then
    select au.email into v_email
    from auth.users au
    join public.profiles p on p.id = au.id
    where lower(p.employee_id) = lower(v_id)
    limit 1;
  end if;

  -- Only a made-up sign-in address is ever handed out. A real email is never
  -- disclosed to an anonymous caller.
  if v_email is null or lower(v_email) not like '%@users.tyrepulse.app' then
    return null;
  end if;

  return v_email;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_error_groups(p_days integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the error groups' using errcode = '42501';
  end if;

  with logs as (
    select l.id, l.severity, l.source, l.message, l.url, l.user_id, l.resolved, l.created_at,
           coalesce(nullif(lower(l.platform), ''),
             case when lower(l.source) = 'sentry' then 'android'
                  when lower(l.source) in ('page','app-root','errorboundary','console') then 'web'
                  else 'background' end) as surface,
           public.system_log_group_key(l.source, l.message, l.error_fingerprint) as gk
    from public.system_logs l
    where p_days is null or l.created_at >= now() - make_interval(days => greatest(p_days, 1))
  ), people as (
    select p.id, coalesce(p.is_super_admin, false) as staff, p.role, p.email
    from public.profiles p
  ), grp as (
    select g.gk,
      count(*) as events,
      count(*) filter (where not g.resolved) as unresolved_events,
      min(g.created_at) as first_seen, max(g.created_at) as last_seen,
      max(case g.severity when 'critical' then 4 when 'error' then 3 when 'warning' then 2 else 1 end) as sev_rank,
      (array_agg(g.message order by g.created_at desc))[1] as sample,
      array_agg(distinct g.source) as sources,
      array_agg(distinct g.surface) as surfaces,
      (array_agg(distinct g.url) filter (where g.url is not null))[1:3] as urls,
      count(distinct g.user_id) as people,
      count(distinct g.user_id) filter (where pp.staff) as staff,
      count(distinct g.user_id) filter (where g.user_id is not null and not coalesce(pp.staff, false)) as customers,
      count(*) filter (where g.user_id is null) as no_user_events
    from logs g left join people pp on pp.id = g.user_id
    where g.gk is not null
    group by g.gk
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'totals', (select jsonb_build_object(
        'rows', count(*),
        'unresolved', count(*) filter (where not resolved),
        'critical', count(*) filter (where not resolved and severity = 'critical'),
        'error', count(*) filter (where not resolved and severity = 'error'),
        'warning', count(*) filter (where not resolved and severity = 'warning'),
        'info', count(*) filter (where not resolved and severity not in ('critical','error','warning')),
        'new_today', count(*) filter (where created_at >= date_trunc('day', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh'),
        'new_today_errors', count(*) filter (where severity in ('critical','error') and created_at >= date_trunc('day', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh'),
        'with_user', count(*) filter (where user_id is not null)
      ) from logs),
    'coverage', (select jsonb_build_object(
        'web_errors', count(*) filter (where surface = 'web' and severity in ('critical','error')),
        'web_errors_with_user', count(*) filter (where surface = 'web' and severity in ('critical','error') and user_id is not null),
        'android_crashes', count(*) filter (where surface = 'android'),
        'android_with_user', count(*) filter (where surface = 'android' and user_id is not null),
        'all_rows', count(*),
        'all_with_user', count(*) filter (where user_id is not null),
        'error_rows', count(*) filter (where severity in ('critical','error')),
        'error_rows_with_user', count(*) filter (where severity in ('critical','error') and user_id is not null)
      ) from logs),
    'customer_accounts', (select count(*) from people where not staff),
    'staff_accounts', (select count(*) from people where staff),
    'accounts', coalesce((select jsonb_agg(a order by (a->>'events')::int desc) from (
        select jsonb_build_object(
          'user_id', g.user_id,
          'email', public.mask_email_for_console(pp.email),
          'role', pp.role, 'staff', coalesce(pp.staff, false),
          'events', count(*), 'groups', count(distinct g.gk), 'last_error', max(g.created_at)) a
        from logs g left join people pp on pp.id = g.user_id
        where g.user_id is not null and g.severity in ('critical','error')
        group by g.user_id, pp.email, pp.role, pp.staff) s), '[]'::jsonb),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', d, 'total', t, 'errors', e) order by d) from (
        select (created_at at time zone 'Asia/Riyadh')::date d, count(*) t,
               count(*) filter (where severity in ('critical','error')) e
        from public.system_logs where created_at >= now() - interval '90 days' group by 1) s), '[]'::jsonb),
    'groups', coalesce((select jsonb_agg(jsonb_build_object(
        'key', grp.gk,
        'severity', case grp.sev_rank when 4 then 'critical' when 3 then 'error' when 2 then 'warning' else 'info' end,
        'sample', left(grp.sample, 300),
        'sources', to_jsonb(grp.sources), 'surfaces', to_jsonb(grp.surfaces), 'urls', coalesce(to_jsonb(grp.urls), '[]'::jsonb),
        'events', grp.events, 'unresolved_events', grp.unresolved_events,
        'first_seen', grp.first_seen, 'last_seen', grp.last_seen,
        'people', grp.people, 'staff', grp.staff, 'customers', grp.customers, 'no_user_events', grp.no_user_events,
        'state', case when s.group_key is null then null else jsonb_build_object(
            'status', s.status, 'owner_id', s.owner_id,
            'owner_name', (select coalesce(nullif(pr.full_name, ''), public.mask_email_for_console(pr.email)) from public.profiles pr where pr.id = s.owner_id),
            'resolved_in_version', s.resolved_in_version, 'note', s.note,
            'notify_when_fixed', s.notify_when_fixed, 'notified_at', s.notified_at,
            'resolved_at', s.resolved_at, 'regressed_at', s.regressed_at, 'updated_at', s.updated_at) end
      ) order by grp.last_seen desc)
      from grp left join public.error_group_state s on s.group_key = grp.gk), '[]'::jsonb)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_by_country(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(country text, tyre numeric, spare numeric, oil numeric, total numeric, lines bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select country,
    round(sum(coalesce(tyre_cost,0))),
    round(sum(coalesce(spare_cost,0))),
    round(sum(coalesce(oil_cost,0))),
    round(sum(coalesce(line_cost,0))),
    count(*)
  from public.parts_consumption
  where organisation_id = (select public.app_current_org()) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    and country is not null and btrim(country) <> ''
    and (p_from is null or event_date >= p_from)
    and (p_to is null or event_date <= p_to)
  group by country
  order by country
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_by_site(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(site text, tyre numeric, spare numeric, oil numeric, total numeric, lines bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  WITH org AS (SELECT public.app_current_org() AS oid)
  SELECT
    COALESCE(m.site, 'Unmapped: ' || pc.store_code) AS site,
    round(COALESCE(sum(pc.tyre_cost), 0))  AS tyre,
    round(COALESCE(sum(pc.spare_cost), 0)) AS spare,
    round(COALESCE(sum(pc.oil_cost), 0))   AS oil,
    round(COALESCE(sum(pc.line_cost), 0))  AS total,
    count(*)::bigint                        AS lines
  FROM public.parts_consumption pc
  LEFT JOIN public.store_site_map m
    ON m.organisation_id = pc.organisation_id
   AND m.country IS NOT DISTINCT FROM pc.country
   AND m.store_code = pc.store_code
  WHERE pc.organisation_id = (SELECT oid FROM org) and ((m.site)::text is null or btrim((m.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((m.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    AND (SELECT oid FROM org) IS NOT NULL
    AND public.app_is_active()
    AND (p_country IS NULL OR pc.country = p_country) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    AND (p_from IS NULL OR pc.event_date >= p_from)
    AND (p_to   IS NULL OR pc.event_date <= p_to)
  GROUP BY COALESCE(m.site, 'Unmapped: ' || pc.store_code)
  ORDER BY total DESC;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_cost_status_summary(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with l as (
    select * from public.expense_cost_status_lines(p_country, p_from, p_to, null, null)
  ),
  by_status as (
    select country, currency, cost_status,
           count(*) as lines,
           round(sum(line_cost), 2) as amount,
           count(*) filter (where cost_category = 'tyre') as tyre_lines,
           round(sum(line_cost) filter (where cost_category = 'tyre'), 2) as tyre_amount
      from l group by 1, 2, 3
  ),
  per_country as (
    select country, currency,
           count(*) as lines,
           round(sum(line_cost), 2) as total,
           count(*) filter (where is_credit) as credit_lines,
           round(sum(line_cost) filter (where is_credit), 2) as credit_amount,
           count(*) filter (where is_repair) as repair_lines,
           round(sum(line_cost) filter (where is_repair), 2) as repair_amount,
           count(*) filter (where is_retread) as retread_lines,
           round(sum(line_cost) filter (where is_retread), 2) as retread_amount,
           count(*) filter (where is_multi_qty) as multi_qty_lines,
           count(*) filter (where dispute_reason = 'cross_load_copy') as copy_lines,
           round(sum(line_cost) filter (where dispute_reason = 'cross_load_copy'), 2) as copy_amount,
           count(*) filter (where dispute_reason = 'conflicting_revision') as revision_lines,
           round(sum(line_cost) filter (where dispute_reason = 'conflicting_revision'), 2) as revision_amount
      from l group by 1, 2
  )
  select jsonb_build_object(
    'ok', true,
    'country', coalesce(p_country, 'All'),
    'from', p_from,
    'to', p_to,
    'countries', coalesce((
      select jsonb_agg(jsonb_build_object(
               'country', c.country, 'currency', c.currency,
               'lines', c.lines, 'total', c.total,
               'credit', jsonb_build_object('lines', c.credit_lines, 'amount', coalesce(c.credit_amount, 0)),
               'repair', jsonb_build_object('lines', c.repair_lines, 'amount', coalesce(c.repair_amount, 0)),
               'retread', jsonb_build_object('lines', c.retread_lines, 'amount', coalesce(c.retread_amount, 0)),
               'multi_qty_lines', c.multi_qty_lines,
               'disputed', jsonb_build_object(
                  'cross_load_copy', jsonb_build_object('lines', c.copy_lines, 'amount', coalesce(c.copy_amount, 0)),
                  'conflicting_revision', jsonb_build_object('lines', c.revision_lines, 'amount', coalesce(c.revision_amount, 0))),
               'statuses', coalesce((
                  select jsonb_object_agg(s.cost_status, jsonb_build_object(
                           'lines', s.lines, 'amount', coalesce(s.amount, 0),
                           'tyre_lines', s.tyre_lines, 'tyre_amount', coalesce(s.tyre_amount, 0)))
                    from by_status s where s.country is not distinct from c.country), '{}'::jsonb))
             order by c.country)
        from per_country c), '[]'::jsonb)
  )
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_period_trend(p_country text DEFAULT 'All'::text, p_grain text DEFAULT 'year'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  -- Bucketing format per grain. Quarter renders as 2024-Q1, exactly as the old
  -- substring(txn_date) arithmetic did.
  v_fmt text := case lower(coalesce(p_grain,'year'))
                  when 'month'   then 'YYYY-MM'
                  when 'quarter' then 'YYYY-"Q"Q'
                  else 'YYYY'
                end;
  v_out jsonb;
begin
  -- Periods come from the typed business date event_date (populated on every
  -- row), not the raw ERP text txn_date: Egypt's export writes txn_date as
  -- '1/31/2022 12:00:00 AM', which the old '^\d{4}-\d{2}' filter discarded, so
  -- every Egypt line (40,680) was missing from Expense Trends. For KSA and UAE
  -- the two agree on every row (measured: 0 month mismatches), so their output
  -- is byte-identical.
  if p_country = 'All' or p_country is null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'country', country, 'period', period, 'currency', currency, 'lines', lines,
      'tyre', tyre, 'spare', spare, 'lubricant', lubricant, 'total', total
    ) order by country, period), '[]'::jsonb)
      into v_out
      from (
        select country, to_char(event_date, v_fmt) period,
               max(nullif(btrim(currency),'')) currency, count(*) lines,
               round(sum(coalesce(tyre_cost,0)),2)  tyre,
               round(sum(coalesce(spare_cost,0)),2) spare,
               round(sum(coalesce(oil_cost,0)),2)   lubricant,
               round(sum(coalesce(line_cost,0)),2)  total
          from public.parts_consumption
         where event_date is not null
         group by 1, 2) g;
  else
    -- A named country is a plain equality so the planner uses the country
    -- index; the old single-statement OR form read every country's rows on
    -- every call (and the multi-country wrapper did that once per country).
    select coalesce(jsonb_agg(jsonb_build_object(
      'country', country, 'period', period, 'currency', currency, 'lines', lines,
      'tyre', tyre, 'spare', spare, 'lubricant', lubricant, 'total', total
    ) order by country, period), '[]'::jsonb)
      into v_out
      from (
        select country, to_char(event_date, v_fmt) period,
               max(nullif(btrim(currency),'')) currency, count(*) lines,
               round(sum(coalesce(tyre_cost,0)),2)  tyre,
               round(sum(coalesce(spare_cost,0)),2) spare,
               round(sum(coalesce(oil_cost,0)),2)   lubricant,
               round(sum(coalesce(line_cost,0)),2)  total
          from public.parts_consumption
         where event_date is not null
           and country = p_country
         group by 1, 2) g;
  end if;
  return v_out;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_period_trend_multi(p_countries text[] DEFAULT NULL::text[], p_grain text DEFAULT 'year'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_allowed text[];
  v_refused text[] := '{}';
  v_country text;
  v_blocks  jsonb := '[]'::jsonb;
begin
  select allowed, refused into v_allowed, v_refused
    from public._scope_split_countries(p_countries);

  foreach v_country in array v_allowed loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'country',  v_country,
      'currency', public.currency_for_country(v_country),
      'result',   public.get_expense_period_trend(v_country, p_grain)));
  end loop;

  return jsonb_build_object(
    'ok', true, 'multi', true, 'generated_at', now(), 'blended', false,
    'requested', to_jsonb(coalesce(p_countries, '{}'::text[])),
    'refused',   to_jsonb(v_refused),
    'countries', v_blocks);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_expense_yearly_trend(p_country text DEFAULT 'All'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with g as (
    select country, to_char(event_date, 'YYYY') yr,
      max(nullif(btrim(currency),'')) currency,
      count(*) lines,
      round(sum(coalesce(tyre_cost,0)),2)  tyre,
      round(sum(coalesce(spare_cost,0)),2) spare,
      round(sum(coalesce(oil_cost,0)),2)   lubricant,
      round(sum(coalesce(line_cost,0)),2)  total
    from public.parts_consumption
    where event_date is not null
      and (p_country = 'All' or p_country is null or country = p_country)
    group by 1, 2
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'country', country, 'year', yr, 'currency', currency, 'lines', lines,
    'tyre', tyre, 'spare', spare, 'lubricant', lubricant, 'total', total
  ) order by country, yr), '[]'::jsonb)
  from g;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_extra_field_stats(p_country text DEFAULT NULL::text)
 RETURNS TABLE(field_key text, record_count bigint, sample_vals text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT
    key AS field_key,
    COUNT(*) AS record_count,
    (ARRAY_AGG(DISTINCT (extra_fields ->> key)))[1:5] AS sample_vals
  FROM tyre_records,
       LATERAL jsonb_object_keys(extra_fields) AS key
  WHERE extra_fields IS NOT NULL
    AND extra_fields <> '{}'::jsonb
    AND (organisation_id = public.app_current_org() OR public.is_super_admin())
    AND (p_country IS NULL OR country = p_country)
    AND (p_country is null or public.app_can_see_country(p_country) is not false)
    AND (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries())
         or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  GROUP BY key
  ORDER BY record_count DESC;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_figure_lineage(p_domain text DEFAULT 'tyre_cost'::text, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, (date_trunc('month', now()) - interval '11 month')::date);
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
  v_pc jsonb; v_tr jsonb; v_vf jsonb; v_sources jsonb; v_imports jsonb;
begin
  if v_org is null or not public.app_is_active() or not public.is_super_admin() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select jsonb_build_object(
    'table', 'parts_consumption', 'role', 'Expense grid (Ramco export)',
    'rows', count(*), 'with_import_uid', count(import_uid),
    'idempotent_pct', case when count(*)>0 then round(100.0*count(import_uid)/count(*),1) else null end,
    'currencies', (select coalesce(jsonb_object_agg(c, n),'{}'::jsonb) from (
        select coalesce(currency,'?') c, count(*) n from parts_consumption
        where organisation_id=v_org and (p_country is null or country=p_country)
          and event_date between v_from and v_to group by 1) q),
    'classification', (select coalesce(jsonb_object_agg(cb, n),'{}'::jsonb) from (
        select coalesce(classified_by,'unknown') cb, count(*) n from parts_consumption
        where organisation_id=v_org and (p_country is null or country=p_country)
          and event_date between v_from and v_to group by 1) q),
    'date_min', min(event_date), 'date_max', max(event_date)
  ) into v_pc
  from parts_consumption
  where organisation_id=v_org and (p_country is null or country=p_country)
    and event_date between v_from and v_to;

  select jsonb_build_object(
    'table','tyre_records','role','Tyre lifecycle records',
    'rows', count(*),
    'with_brand', count(*) filter (where coalesce(btrim(brand),'')<>''),
    'with_fitment_date', count(fitment_date),
    'with_total_km', count(*) filter (where total_km is not null and total_km>0),
    'with_unit_cost', count(*) filter (where cost_per_tyre is not null and cost_per_tyre>0),
    'data_source', (select coalesce(jsonb_object_agg(ds,n),'{}'::jsonb) from (
        select coalesce(data_source,'unknown') ds, count(*) n from tyre_records
        where organisation_id=v_org and (p_country is null or country=p_country) group by 1) q)
  ) into v_tr
  from tyre_records
  where organisation_id=v_org and (p_country is null or country=p_country);

  select jsonb_build_object(
    'table','vehicle_fleet','role','Asset master',
    'rows', count(*),
    'with_type', count(*) filter (where coalesce(btrim(vehicle_type),'')<>''),
    'with_registration', count(*) filter (where coalesce(btrim(registration_no),'')<>''),
    'active', count(*) filter (where is_active is not false)
  ) into v_vf
  from vehicle_fleet
  where organisation_id=v_org and (p_country is null or country=p_country);

  v_sources := case p_domain
    when 'tyre_cost' then jsonb_build_array(v_pc, v_tr)
    when 'cost_per_km' then jsonb_build_array(v_pc, v_tr)
    when 'tyre_life' then jsonb_build_array(v_tr)
    when 'brand_performance' then jsonb_build_array(v_tr, v_pc)
    when 'fleet_register' then jsonb_build_array(v_vf)
    else jsonb_build_array(v_pc, v_tr, v_vf)
  end;

  select coalesce(jsonb_agg(jsonb_build_object(
      'module', b.module, 'file', f.original_filename, 'rows', b.total_rows,
      'imported', b.imported_rows, 'duplicates', b.duplicate_rows,
      'status', b.import_status, 'at', b.created_at,
      'repeat_file', (f.sha256 is not null and (select count(*) from import_files f2
          where f2.organisation_id=v_org and f2.sha256=f.sha256) > 1)
    ) order by b.created_at desc), '[]'::jsonb)
  into v_imports
  from import_batches b
  left join import_files f on f.id = b.file_id
  where b.organisation_id=v_org and (p_country is null or b.country=p_country)
  limit 15;

  return jsonb_build_object('ok', true, 'domain', p_domain, 'country', p_country,
    'from', v_from, 'to', v_to, 'sources', v_sources, 'recent_imports', v_imports);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_fleet_area_map(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_rows jsonb;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'asset_no', asset_no, 'site', site, 'region', region, 'vehicle_type', vehicle_type
         ) order by asset_no), '[]'::jsonb)
    into v_rows
  from (
    select upper(btrim(f.asset_no)) as asset_no,
           nullif(btrim(f.site), '') as site,
           nullif(btrim(s.region), '') as region,
           nullif(btrim(f.vehicle_type), '') as vehicle_type
      from public.vehicle_fleet f
      left join public.sites s
        on s.organisation_id = v_org and s.country = f.country
       and upper(btrim(s.name)) = upper(btrim(f.site))
     where f.organisation_id = v_org and ((f.site)::text is null or btrim((f.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((f.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and (p_country is null or f.country = p_country) and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and coalesce(btrim(f.asset_no), '') <> ''
  ) t;

  return jsonb_build_object('ok', true, 'country', p_country, 'assets', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_fleet_cpk(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org  uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to   date := coalesce(p_to, current_date);
  v_site text := nullif(upper(regexp_replace(btrim(coalesce(p_site, '')), '\s+', ' ', 'g')), '');
begin

  if nullif(btrim(coalesce(p_site, '')), '') is not null and not (public.is_super_admin() or public.app_can_see_site(p_site) is not false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  return (
    with
    km as (select * from public.fleet_tyre_km_by_asset(v_org, p_country, v_from, v_to) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr as (select * from public.fleet_hours_by_asset(v_org, p_country, v_from, v_to) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    cost as (
      select pc.country, upper(btrim(pc.asset_code)) as asset_no,
             sum(coalesce(pc.tyre_cost, 0)) as tyre_cost,
             sum(coalesce(pc.spare_cost, 0) + coalesce(pc.oil_cost, 0)) as maint_cost
        from public.parts_consumption pc
       where pc.organisation_id = v_org and pc.event_date between v_from and v_to
         and (p_country is null or pc.country = p_country) and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(pc.asset_code), '') <> ''
       group by 1, 2
    ),
    fleet as (
      select f.country, upper(btrim(f.asset_no)) as asset_no,
             nullif(btrim(f.vehicle_type), '') as vehicle_type,
             public.cpk_unit_for_asset_type(f.vehicle_type) as unit
        from public.vehicle_fleet f
       where f.organisation_id = v_org and (p_country is null or f.country = p_country) and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(f.asset_no), '') <> ''
         and (v_site is null or upper(btrim(f.site)) = v_site)
    ),
    per_asset as (
      select fl.country, fl.asset_no, fl.vehicle_type, fl.unit,
             coalesce(cc.currency, fl.country) as currency,
             coalesce(km.km_run, 0)   as km,
             coalesce(hr.hours_run, 0) as hours,
             coalesce(c.tyre_cost, 0)  as tyre_cost,
             coalesce(c.maint_cost, 0) as maint_cost,
             coalesce(c.tyre_cost, 0) + coalesce(c.maint_cost, 0) as total_cost,
             case when fl.unit = 'km' then coalesce(km.km_run, 0) else coalesce(hr.hours_run, 0) end as denom
        from fleet fl
        left join km   on km.country = fl.country and km.asset_no = fl.asset_no
        left join hr   on hr.country = fl.country and hr.asset_no = fl.asset_no
        left join cost c on c.country = fl.country and c.asset_no = fl.asset_no
        left join public.country_currency cc on cc.country = fl.country
    ),
    unreg as (
      select c.country, coalesce(cc.currency, c.country) currency,
             sum(c.tyre_cost + c.maint_cost) as unregistered_cost
        from cost c
        left join public.country_currency cc on cc.country = c.country
       where v_site is null and not exists (select 1 from fleet fl where fl.country = c.country and fl.asset_no = c.asset_no)
       group by 1, 2
    )
    select jsonb_build_object(
      'ok', true, 'org', v_org, 'from', v_from, 'to', v_to,
      'per_vehicle', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'asset_no', asset_no, 'vehicle_type', vehicle_type, 'country', country,
          'currency', currency, 'unit', unit,
          'distance_or_hours', round(denom, 1),
          'km', round(km, 1), 'hours', round(hours, 1),
          'tyre_cost', round(tyre_cost, 2), 'maintenance_cost', round(maint_cost, 2),
          'total_cost', round(total_cost, 2),
          'cpk_tyre',  case when denom > 0 then round(tyre_cost / denom, 4) else null end,
          'cpk_total', case when denom > 0 then round(total_cost / denom, 4) else null end
        ) order by total_cost desc), '[]'::jsonb)
        from per_asset where total_cost > 0
      ),
      'by_type', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', g.country, 'currency', g.currency, 'vehicle_type', g.vehicle_type, 'unit', g.unit,
          'assets', g.assets, 'assets_measured', g.assets_measured,
          'tyre_cost', round(g.tyre_cost, 2), 'maintenance_cost', round(g.maint_cost, 2),
          'total_cost', round(g.total_cost, 2), 'distance_or_hours', round(g.denom_sum, 1),
          'cpk_tyre',  case when g.denom_sum > 0 then round(g.matched_tyre / g.denom_sum, 4) else null end,
          'cpk_total', case when g.denom_sum > 0 then round(g.matched_total / g.denom_sum, 4) else null end
        ) order by g.total_cost desc), '[]'::jsonb)
        from (
          select country, currency, vehicle_type, unit,
                 count(*) as assets, count(*) filter (where denom > 0) as assets_measured,
                 sum(tyre_cost) as tyre_cost, sum(maint_cost) as maint_cost, sum(total_cost) as total_cost,
                 sum(denom) as denom_sum,
                 sum(tyre_cost)  filter (where denom > 0) as matched_tyre,
                 sum(total_cost) filter (where denom > 0) as matched_total
            from per_asset where vehicle_type is not null
           group by country, currency, vehicle_type, unit
        ) g
      ),
      'fleet', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', fa.country, 'currency', fa.currency,
          'tyre_cost', round(fa.tyre_all, 2), 'maintenance_cost', round(fa.maint_all, 2),
          'total_cost', round(fa.total_all, 2),
          'unregistered_cost', round(coalesce(u.unregistered_cost, 0), 2),
          'km', jsonb_build_object(
            'total_km', round(fa.km_sum, 1), 'cost_assets', fa.km_cost_assets,
            'measured_assets', fa.km_matched_assets,
            'coverage_pct', case when fa.km_cost_assets > 0 then round(100.0 * fa.km_matched_assets / fa.km_cost_assets, 1) else null end,
            'tyre_cost_matched', round(fa.km_tyre_matched, 2), 'total_cost_matched', round(fa.km_total_matched, 2),
            'cpk_tyre',  case when fa.km_sum > 0 then round(fa.km_tyre_matched / fa.km_sum, 4) else null end,
            'cpk_total', case when fa.km_sum > 0 then round(fa.km_total_matched / fa.km_sum, 4) else null end
          ),
          'hours', jsonb_build_object(
            'total_hours', round(fa.hr_sum, 1), 'cost_assets', fa.hr_cost_assets,
            'measured_assets', fa.hr_matched_assets,
            'coverage_pct', case when fa.hr_cost_assets > 0 then round(100.0 * fa.hr_matched_assets / fa.hr_cost_assets, 1) else null end,
            'tyre_cost_matched', round(fa.hr_tyre_matched, 2), 'total_cost_matched', round(fa.hr_total_matched, 2),
            'cpk_tyre',  case when fa.hr_sum > 0 then round(fa.hr_tyre_matched / fa.hr_sum, 4) else null end,
            'cpk_total', case when fa.hr_sum > 0 then round(fa.hr_total_matched / fa.hr_sum, 4) else null end
          ),
          'all_km', round(fa.km_all, 1), 'all_hours', round(fa.hr_all, 1)
        ) order by fa.country), '[]'::jsonb)
        from (
          select country, currency,
                 sum(tyre_cost) as tyre_all, sum(maint_cost) as maint_all, sum(total_cost) as total_all,
                 sum(km) as km_all, sum(hours) as hr_all,
                 sum(denom)      filter (where unit = 'km') as km_sum,
                 sum(tyre_cost)  filter (where unit = 'km' and denom > 0) as km_tyre_matched,
                 sum(total_cost) filter (where unit = 'km' and denom > 0) as km_total_matched,
                 count(*)        filter (where unit = 'km' and total_cost > 0) as km_cost_assets,
                 count(*)        filter (where unit = 'km' and total_cost > 0 and denom > 0) as km_matched_assets,
                 sum(denom)      filter (where unit = 'engine_hours') as hr_sum,
                 sum(tyre_cost)  filter (where unit = 'engine_hours' and denom > 0) as hr_tyre_matched,
                 sum(total_cost) filter (where unit = 'engine_hours' and denom > 0) as hr_total_matched,
                 count(*)        filter (where unit = 'engine_hours' and total_cost > 0) as hr_cost_assets,
                 count(*)        filter (where unit = 'engine_hours' and total_cost > 0 and denom > 0) as hr_matched_assets
            from per_asset group by country, currency
        ) fa
        left join unreg u on u.country = fa.country
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_fleet_cpk_v1_retired(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org  uuid := public.app_current_org();
  v_from date := coalesce(p_from, current_date - 365);
  v_to   date := coalesce(p_to, current_date);
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  return (
    with
    km as (select * from public.fleet_tyre_km_by_asset(v_org, p_country, v_from, v_to) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    hr as (select * from public.fleet_hours_by_asset(v_org, p_country, v_from, v_to) where true and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
    cost as (
      select pc.country, upper(btrim(pc.asset_code)) as asset_no,
             sum(coalesce(pc.tyre_cost, 0)) as tyre_cost,
             sum(coalesce(pc.spare_cost, 0) + coalesce(pc.oil_cost, 0)) as maint_cost
        from public.parts_consumption pc
       where pc.organisation_id = v_org and pc.event_date between v_from and v_to
         and (p_country is null or pc.country = p_country) and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(pc.asset_code), '') <> ''
       group by 1, 2
    ),
    fleet as (
      select f.country, upper(btrim(f.asset_no)) as asset_no,
             nullif(btrim(f.vehicle_type), '') as vehicle_type,
             public.cpk_unit_for_asset_type(f.vehicle_type) as unit
        from public.vehicle_fleet f
       where f.organisation_id = v_org and (p_country is null or f.country = p_country) and (f.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(f.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
         and coalesce(btrim(f.asset_no), '') <> ''
    ),
    per_asset as (
      select fl.country, fl.asset_no, fl.vehicle_type, fl.unit,
             coalesce(cc.currency, fl.country) as currency,
             coalesce(km.km_run, 0)   as km,
             coalesce(hr.hours_run, 0) as hours,
             coalesce(c.tyre_cost, 0)  as tyre_cost,
             coalesce(c.maint_cost, 0) as maint_cost,
             coalesce(c.tyre_cost, 0) + coalesce(c.maint_cost, 0) as total_cost,
             case when fl.unit = 'km' then coalesce(km.km_run, 0) else coalesce(hr.hours_run, 0) end as denom
        from fleet fl
        left join km   on km.country = fl.country and km.asset_no = fl.asset_no
        left join hr   on hr.country = fl.country and hr.asset_no = fl.asset_no
        left join cost c on c.country = fl.country and c.asset_no = fl.asset_no
        left join public.country_currency cc on cc.country = fl.country
    ),
    unreg as (
      select c.country, coalesce(cc.currency, c.country) currency,
             sum(c.tyre_cost + c.maint_cost) as unregistered_cost
        from cost c
        left join public.country_currency cc on cc.country = c.country
       where not exists (select 1 from fleet fl where fl.country = c.country and fl.asset_no = c.asset_no)
       group by 1, 2
    )
    select jsonb_build_object(
      'ok', true, 'org', v_org, 'from', v_from, 'to', v_to,
      'per_vehicle', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'asset_no', asset_no, 'vehicle_type', vehicle_type, 'country', country,
          'currency', currency, 'unit', unit,
          'distance_or_hours', round(denom, 1),
          'km', round(km, 1), 'hours', round(hours, 1),
          'tyre_cost', round(tyre_cost, 2), 'maintenance_cost', round(maint_cost, 2),
          'total_cost', round(total_cost, 2),
          'cpk_tyre',  case when denom > 0 then round(tyre_cost / denom, 4) else null end,
          'cpk_total', case when denom > 0 then round(total_cost / denom, 4) else null end
        ) order by total_cost desc), '[]'::jsonb)
        from per_asset where total_cost > 0
      ),
      'by_type', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', g.country, 'currency', g.currency, 'vehicle_type', g.vehicle_type, 'unit', g.unit,
          'assets', g.assets, 'assets_measured', g.assets_measured,
          'tyre_cost', round(g.tyre_cost, 2), 'maintenance_cost', round(g.maint_cost, 2),
          'total_cost', round(g.total_cost, 2), 'distance_or_hours', round(g.denom_sum, 1),
          'cpk_tyre',  case when g.denom_sum > 0 then round(g.matched_tyre / g.denom_sum, 4) else null end,
          'cpk_total', case when g.denom_sum > 0 then round(g.matched_total / g.denom_sum, 4) else null end
        ) order by g.total_cost desc), '[]'::jsonb)
        from (
          select country, currency, vehicle_type, unit,
                 count(*) as assets, count(*) filter (where denom > 0) as assets_measured,
                 sum(tyre_cost) as tyre_cost, sum(maint_cost) as maint_cost, sum(total_cost) as total_cost,
                 sum(denom) as denom_sum,
                 sum(tyre_cost)  filter (where denom > 0) as matched_tyre,
                 sum(total_cost) filter (where denom > 0) as matched_total
            from per_asset where vehicle_type is not null
           group by country, currency, vehicle_type, unit
        ) g
      ),
      'fleet', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'country', fa.country, 'currency', fa.currency,
          'tyre_cost', round(fa.tyre_all, 2), 'maintenance_cost', round(fa.maint_all, 2),
          'total_cost', round(fa.total_all, 2),
          'unregistered_cost', round(coalesce(u.unregistered_cost, 0), 2),
          'km', jsonb_build_object(
            'total_km', round(fa.km_sum, 1), 'cost_assets', fa.km_cost_assets,
            'measured_assets', fa.km_matched_assets,
            'coverage_pct', case when fa.km_cost_assets > 0 then round(100.0 * fa.km_matched_assets / fa.km_cost_assets, 1) else null end,
            'tyre_cost_matched', round(fa.km_tyre_matched, 2), 'total_cost_matched', round(fa.km_total_matched, 2),
            'cpk_tyre',  case when fa.km_sum > 0 then round(fa.km_tyre_matched / fa.km_sum, 4) else null end,
            'cpk_total', case when fa.km_sum > 0 then round(fa.km_total_matched / fa.km_sum, 4) else null end
          ),
          'hours', jsonb_build_object(
            'total_hours', round(fa.hr_sum, 1), 'cost_assets', fa.hr_cost_assets,
            'measured_assets', fa.hr_matched_assets,
            'coverage_pct', case when fa.hr_cost_assets > 0 then round(100.0 * fa.hr_matched_assets / fa.hr_cost_assets, 1) else null end,
            'tyre_cost_matched', round(fa.hr_tyre_matched, 2), 'total_cost_matched', round(fa.hr_total_matched, 2),
            'cpk_tyre',  case when fa.hr_sum > 0 then round(fa.hr_tyre_matched / fa.hr_sum, 4) else null end,
            'cpk_total', case when fa.hr_sum > 0 then round(fa.hr_total_matched / fa.hr_sum, 4) else null end
          ),
          'all_km', round(fa.km_all, 1), 'all_hours', round(fa.hr_all, 1)
        ) order by fa.country), '[]'::jsonb)
        from (
          select country, currency,
                 sum(tyre_cost) as tyre_all, sum(maint_cost) as maint_all, sum(total_cost) as total_all,
                 sum(km) as km_all, sum(hours) as hr_all,
                 sum(denom)      filter (where unit = 'km') as km_sum,
                 sum(tyre_cost)  filter (where unit = 'km' and denom > 0) as km_tyre_matched,
                 sum(total_cost) filter (where unit = 'km' and denom > 0) as km_total_matched,
                 count(*)        filter (where unit = 'km' and total_cost > 0) as km_cost_assets,
                 count(*)        filter (where unit = 'km' and total_cost > 0 and denom > 0) as km_matched_assets,
                 sum(denom)      filter (where unit = 'engine_hours') as hr_sum,
                 sum(tyre_cost)  filter (where unit = 'engine_hours' and denom > 0) as hr_tyre_matched,
                 sum(total_cost) filter (where unit = 'engine_hours' and denom > 0) as hr_total_matched,
                 count(*)        filter (where unit = 'engine_hours' and total_cost > 0) as hr_cost_assets,
                 count(*)        filter (where unit = 'engine_hours' and total_cost > 0 and denom > 0) as hr_matched_assets
            from per_asset group by country, currency
        ) fa
        left join unreg u on u.country = fa.country
      )
    )
  );
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_fleet_renewal_signals(p_country text DEFAULT NULL::text)
 RETURNS TABLE(asset_key text, country text, repair_cost_12m jsonb, repair_cost_all jsonb, downtime_hours_12m numeric, job_cards_12m integer, accidents_all integer, accidents_12m integer, last_hours numeric, last_hours_at date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scope as (select nullif(nullif(btrim(p_country), ''), 'All') as c),
  pc as (
    select upper(regexp_replace(p.asset_code, '\s', '', 'g')) k, p.country,
           p.currency, sum(p.line_cost) total,
           sum(p.line_cost) filter (where p.event_date >= current_date - 365) last12
      from parts_consumption p, scope s
     where p.asset_code is not null and btrim(p.asset_code) <> '' and p.currency is not null
       and (s.c is null or p.country = s.c)
     group by 1, 2, 3
  ),
  pcj as (
    select k, country,
           jsonb_object_agg(currency, round(total, 2)) filter (where total is not null) all_j,
           jsonb_object_agg(currency, round(last12, 2)) filter (where last12 is not null and last12 <> 0) m12_j
      from pc group by 1, 2
  ),
  wo as (
    select upper(regexp_replace(w.asset_no, '\s', '', 'g')) k, w.country,
           count(*)::int jc,
           sum(extract(epoch from (w.production_in_at - w.production_out_at)) / 3600)
             filter (where w.production_in_at >= w.production_out_at
                       and w.production_in_at - w.production_out_at < interval '365 days') dt
      from work_orders w, scope s
     where w.asset_no is not null and w.opened_at >= now() - interval '365 days'
       and (s.c is null or w.country = s.c)
     group by 1, 2
  ),
  ac as (
    select upper(regexp_replace(a.asset_no, '\s', '', 'g')) k, a.country,
           count(*)::int n_all,
           count(*) filter (where a.incident_date >= current_date - 365)::int n12
      from accidents a, scope s
     where a.asset_no is not null and (s.c is null or a.country = s.c)
     group by 1, 2
  ),
  eh as (
    select distinct on (1, 2) upper(regexp_replace(e.asset_no, '\s', '', 'g')) k, e.country,
           e.engine_hours h, e.reading_date d
      from engine_hours_logs e, scope s
     where e.asset_no is not null and e.engine_hours is not null
       and (s.c is null or e.country = s.c)
     order by 1, 2, e.reading_date desc, e.id desc
  ),
  keys as (
    select k, country from pcj union select k, country from wo
    union select k, country from ac union select k, country from eh
  )
  select keys.k, keys.country,
         coalesce(pcj.m12_j, '{}'::jsonb), coalesce(pcj.all_j, '{}'::jsonb),
         round(wo.dt::numeric, 1), coalesce(wo.jc, 0),
         coalesce(ac.n_all, 0), coalesce(ac.n12, 0),
         eh.h, eh.d
    from keys
    left join pcj on pcj.k = keys.k and pcj.country is not distinct from keys.country
    left join wo on wo.k = keys.k and wo.country is not distinct from keys.country
    left join ac on ac.k = keys.k and ac.country is not distinct from keys.country
    left join eh on eh.k = keys.k and eh.country is not distinct from keys.country
   order by keys.k, keys.country nulls first
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_inspection_audit(p_inspection_id uuid)
 RETURNS TABLE(id uuid, inspection_id uuid, changed_by uuid, actor_name text, changed_at timestamp with time zone, action text, old_values jsonb, new_values jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT a.id, a.inspection_id, a.changed_by,
         COALESCE(p.full_name, p.username, 'System') AS actor_name,
         a.changed_at, a.action, a.old_values, a.new_values
    FROM public.inspection_audit_log a
    LEFT JOIN public.profiles p ON p.id = a.changed_by
   WHERE a.inspection_id = p_inspection_id
     -- Mirrors inspection_audit_log's own rules: insp_audit_select (role gate)
     -- AND the RESTRICTIVE org isolation, both restated against the audit row.
     AND (public.get_my_role() = ANY (ARRAY['Admin','Manager','Director'])
          OR public.is_super_admin())
     AND (NOT (a.organisation_id IS DISTINCT FROM public.app_current_org())
          OR public.is_super_admin())
   ORDER BY a.changed_at DESC
   LIMIT 200;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_integration_events(p_country text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v json;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  select json_agg(row_to_json(x)) into v from (
    select 'ai' as integration, coalesce(feature,'ai') as event_type, coalesce(status,'success') as status,
           error as error_reason, http_status, latency_ms, created_at as occurred_at, country
    from public.ai_token_logs
    where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    union all
    select 'email', coalesce(report_type,'report'), coalesce(status,'sent'), error, null, null, sent_at, null
    from public.report_send_log
    where organisation_id=v_org
    order by occurred_at desc nulls last
    limit p_limit) x;
  return json_build_object('ok',true,'events',coalesce(v,'[]'::json));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_lineage_graph(p_asset text, p_direction text DEFAULT 'both'::text, p_depth integer DEFAULT 4)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v json;
begin
  if not public.app_is_active() then raise exception 'forbidden' using errcode='42501'; end if;
  with recursive down as (
    select from_asset, to_asset, edge_type, 1 lvl from public.lineage_edges where from_asset=p_asset
    union all
    select e.from_asset, e.to_asset, e.edge_type, d.lvl+1 from public.lineage_edges e join down d on e.from_asset=d.to_asset where d.lvl < p_depth
  ), up as (
    select from_asset, to_asset, edge_type, 1 lvl from public.lineage_edges where to_asset=p_asset
    union all
    select e.from_asset, e.to_asset, e.edge_type, u.lvl+1 from public.lineage_edges e join up u on e.to_asset=u.from_asset where u.lvl < p_depth
  ), edges as (
    select from_asset, to_asset, edge_type from down where p_direction in ('down','both')
    union
    select from_asset, to_asset, edge_type from up where p_direction in ('up','both')
  ), nodeids as (
    select p_asset a union select from_asset from edges union select to_asset from edges
  )
  select json_build_object('ok',true,'root',p_asset,
    'nodes',(select coalesce(json_agg(json_build_object('asset_id',a.asset_id,'kind',a.kind,'name',a.name,'module',a.module)),'[]'::json)
             from public.data_assets a join nodeids n on a.asset_id=n.a),
    'edges',(select coalesce(json_agg(json_build_object('from',from_asset,'to',to_asset,'type',edge_type)),'[]'::json) from edges))
  into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_login_showcase()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := '00000000-0000-0000-0000-000000000001';
  v jsonb;
begin
  select jsonb_build_object(
    'vehicles',        (select count(*) from public.vehicle_fleet f where f.organisation_id = v_org),
    'active_vehicles', (select count(*) from public.vehicle_fleet f where f.organisation_id = v_org and lower(coalesce(f.status,'')) = 'active'),
    'in_workshop',     (select count(distinct w.asset_no) from public.work_orders w
                          where w.organisation_id = v_org
                            and w.production_out_at is not null and w.production_in_at is null
                            and w.opened_at > now() - interval '120 days'),
    'sites',           (select count(*) from public.sites s where s.organisation_id = v_org),
    'users',           (select count(*) from public.profiles p where p.organisation_id = v_org and p.approved is true and coalesce(p.locked,false) = false),
    'countries',       (select coalesce(jsonb_agg(distinct f.country order by f.country), '[]'::jsonb)
                          from public.vehicle_fleet f where f.organisation_id = v_org and f.country is not null),
    'generated_at',    now()
  ) into v;
  return v;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_maint_tyre_split(p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, (date_trunc('month', now()) - interval '11 month')::date);
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
  v_monthly jsonb;
  v_tyre numeric;
  v_maint numeric;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with tyre as (
    select to_char(date_trunc('month', t.issue_date), 'YYYY-MM') as m,
           sum(coalesce(t.cost_per_tyre,0) * (case when coalesce(t.qty,0) = 0 then 1 else t.qty end)) as amt
      from public.tyre_records t
     where t.organisation_id = v_org
       and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and (p_site is null or t.site = p_site) and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and t.issue_date between v_from and v_to
     group by 1
  ),
  pm as (
    select to_char(date_trunc('month', s.service_date), 'YYYY-MM') as m,
           sum(coalesce(s.total_cost,0)) as amt
      from public.pm_service_records s
     where s.organisation_id = v_org
       and (p_country is null or s.country = p_country) and (s.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(s.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and (p_site is null or s.site = p_site) and ((s.site)::text is null or btrim((s.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((s.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and s.service_date between v_from and v_to
     group by 1
  ),
  wo as (
    select to_char(date_trunc('month', timezone('UTC', coalesce(w.completed_at, w.created_at))), 'YYYY-MM') as m,
           sum(coalesce(w.labour_cost,0) + coalesce(w.parts_cost,0)
             + coalesce(w.lubricant_cost,0) + coalesce(w.outside_repair_cost,0)) as amt
      from public.work_orders w
     where w.organisation_id = v_org
       and (p_country is null or w.country = p_country) and (w.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(w.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
       and (p_site is null or w.site = p_site) and ((w.site)::text is null or btrim((w.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((w.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and (timezone('UTC', coalesce(w.completed_at, w.created_at)))::date between v_from and v_to
     group by 1
  ),
  months as (select m from tyre union select m from pm union select m from wo),
  rows as (
    select mo.m, coalesce(t.amt, 0) as tyre, coalesce(p.amt, 0) + coalesce(w.amt, 0) as maintenance
      from months mo
      left join tyre t on t.m = mo.m
      left join pm p on p.m = mo.m
      left join wo w on w.m = mo.m
     where mo.m is not null
  )
  select coalesce(jsonb_agg(jsonb_build_object('m', r.m, 'tyre', round(r.tyre,2), 'maintenance', round(r.maintenance,2)) order by r.m), '[]'::jsonb),
         coalesce(sum(r.tyre), 0), coalesce(sum(r.maintenance), 0)
    into v_monthly, v_tyre, v_maint
    from rows r;

  return jsonb_build_object('ok', true, 'from', v_from, 'to', v_to,
    'monthly', v_monthly,
    'total', jsonb_build_object('tyre', round(v_tyre,2), 'maintenance', round(v_maint,2)));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_maintenance_snapshot(p_site text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE
  v_org uuid := public.app_current_org();
  v_result jsonb;
BEGIN

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  IF v_org IS NULL OR NOT public.app_is_active() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized');
  END IF;

  WITH wo AS (
    SELECT w.work_order_no, w.asset_no, w.site, w.work_type, w.status,
           COALESCE(w.labour_cost,0) + COALESCE(w.parts_cost,0) AS cost,
           w.opened_at::date AS d
    FROM public.work_orders w
    WHERE w.organisation_id = v_org
      AND (p_site IS NULL OR w.site = p_site) and ((w.site)::text is null or btrim((w.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((w.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND (p_country IS NULL OR w.country = p_country) and (w.country::text is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(w.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND (p_from IS NULL OR w.opened_at::date >= p_from)
      AND (p_to   IS NULL OR w.opened_at::date <= p_to)
  ),
  li AS (
    SELECT l.task, l.action
    FROM public.work_order_line_items l
    WHERE l.organisation_id = v_org
      AND (p_site IS NULL OR l.site = p_site) and ((l.site)::text is null or btrim((l.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((l.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND (p_country IS NULL OR l.country = p_country) and (l.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(l.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND (p_from IS NULL OR l.opened_date >= p_from)
      AND (p_to   IS NULL OR l.opened_date <= p_to)
  )
  SELECT jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'kpis', jsonb_build_object(
      'job_cards',        (SELECT count(*) FROM wo),
      'line_items',       (SELECT count(*) FROM li),
      'total_spend',      (SELECT COALESCE(round(sum(cost)),0) FROM wo),
      'avg_job_cost',     (SELECT COALESCE(round(avg(cost)),0) FROM wo WHERE cost>0),
      'tyre_lines',       (SELECT count(*) FROM li WHERE lower(coalesce(task,'')||' '||coalesce(action,'')) LIKE '%tyre%' OR lower(coalesce(task,'')) LIKE '%tire%'),
      'open_jobs',        (SELECT count(*) FROM wo WHERE status NOT IN ('Completed','Cancelled'))
    ),
    'top_tasks', (SELECT COALESCE(jsonb_agg(t),'[]'::jsonb) FROM (
        SELECT task AS label, count(*) AS n FROM li WHERE task IS NOT NULL AND task <> ''
        GROUP BY task ORDER BY count(*) DESC LIMIT 20) t),
    'top_actions', (SELECT COALESCE(jsonb_agg(t),'[]'::jsonb) FROM (
        SELECT action AS label, count(*) AS n FROM li WHERE action IS NOT NULL AND action <> ''
        GROUP BY action ORDER BY count(*) DESC LIMIT 20) t),
    'by_work_type', (SELECT COALESCE(jsonb_agg(t),'[]'::jsonb) FROM (
        SELECT work_type AS label, count(*) AS jobs, COALESCE(round(sum(cost)),0) AS spend
        FROM wo GROUP BY work_type ORDER BY sum(cost) DESC NULLS LAST) t),
    'spend_by_site', (SELECT COALESCE(jsonb_agg(t),'[]'::jsonb) FROM (
        SELECT COALESCE(NULLIF(site,''),'Unspecified') AS label, count(*) AS jobs, COALESCE(round(sum(cost)),0) AS spend
        FROM wo GROUP BY 1 ORDER BY sum(cost) DESC NULLS LAST LIMIT 20) t),
    'spend_by_asset', (SELECT COALESCE(jsonb_agg(t),'[]'::jsonb) FROM (
        SELECT asset_no AS label, count(*) AS jobs, COALESCE(round(sum(cost)),0) AS spend
        FROM wo WHERE asset_no IS NOT NULL AND asset_no <> ''
        GROUP BY asset_no ORDER BY sum(cost) DESC NULLS LAST LIMIT 20) t),
    'monthly_spend', (SELECT COALESCE(jsonb_agg(t ORDER BY t.m),'[]'::jsonb) FROM (
        SELECT to_char(date_trunc('month', d),'YYYY-MM') AS m, COALESCE(round(sum(cost)),0) AS spend
        FROM wo WHERE d IS NOT NULL AND d >= (current_date - interval '12 months')
        GROUP BY 1) t)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_master_file_completeness()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cols text; v json;
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  select string_agg(format(
    'json_build_object(''column'',%L,''ord'',%s,''filled'',count(*) filter (where %I is not null and btrim(%I::text)<>'''' and upper(btrim(%I::text)) not in (''NULL'',''N/A'',''NA'',''-'',''NONE'')))',
    column_name, ordinal_position, column_name, column_name, column_name), ',' order by ordinal_position)
  into v_cols
  from information_schema.columns
  where table_schema='public' and table_name='ksa_country_upload_template_staging';
  execute format('select json_build_object(''ok'',true,''table'',''ksa_country_upload_template_staging'',''total'',count(*),''columns'',json_build_array(%s)) from public.ksa_country_upload_template_staging', v_cols) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_material_issue_summary(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_out jsonb;
begin
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_country is not null and p_country <> 'All' and not coalesce(public.app_can_see_country(p_country), false) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  with scoped as (
    select h.id, h.country, h.store_code, h.doc_type, h.issued_at, h.work_order_no, h.status
      from public.material_issues h
     where h.organisation_id = v_org
       and h.status <> 'cancelled'
       and (p_country is null or p_country = 'All' or h.country = p_country)
       and (p_from is null or h.issued_at::date >= p_from)
       and (p_to is null or h.issued_at::date <= p_to)
       and (h.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries())
            or lower(btrim(h.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
       and (h.site is null or btrim(h.site) = '' or (select public.app_sees_all_sites())
            or upper(btrim(h.site)) = any (coalesce((select public.app_site_scope()), '{}'::text[])))
  ),
  lines as (
    select s.*, l.item_code, l.item_description, l.qty, l.line_cost
      from scoped s join public.material_issue_lines l on l.issue_id = s.id
  ),
  by_country as (
    select l.country, count(distinct l.id) as slips, count(*) as line_count,
           round(coalesce(sum(l.line_cost), 0), 2) as net_value,
           round(coalesce(sum(l.line_cost) filter (where l.doc_type = 'MIS'), 0), 2) as issued_value,
           round(coalesce(sum(l.line_cost) filter (where l.doc_type = 'MRT'), 0), 2) as returned_value,
           count(distinct l.id) filter (where l.doc_type = 'MRT') as return_slips
      from lines l group by l.country
  ),
  by_store as (
    select l.country, coalesce(l.store_code, '(no store)') as store_code, count(distinct l.id) as slips,
           round(coalesce(sum(l.line_cost), 0), 2) as net_value
      from lines l group by 1, 2
  ),
  by_month as (
    select l.country, to_char(l.issued_at, 'YYYY-MM') as month, count(distinct l.id) as slips,
           round(coalesce(sum(l.line_cost), 0), 2) as net_value
      from lines l group by 1, 2
  ),
  top_items as (
    select country, item_code, item_description, qty_total, net_value
      from (
        select l.country,
               coalesce(upper(btrim(l.item_code)), '(no item code)') as item_code,
               max(l.item_description) as item_description,
               round(coalesce(sum(l.qty), 0), 3) as qty_total,
               round(coalesce(sum(l.line_cost), 0), 2) as net_value,
               row_number() over (partition by l.country
                                  order by coalesce(sum(l.line_cost), 0) desc,
                                           coalesce(upper(btrim(l.item_code)), '(no item code)')) as rn
          from lines l group by l.country, coalesce(upper(btrim(l.item_code)), '(no item code)')
      ) t where rn <= 15
  ),
  linkage as (
    select s.country, count(*) as slips,
           count(*) filter (where nullif(btrim(coalesce(s.work_order_no,'')),'') is not null) as slips_with_card,
           count(distinct s.work_order_no) as distinct_cards
      from scoped s group by s.country
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'filters', jsonb_build_object('country', p_country, 'from', p_from, 'to', p_to),
    'currency_note', 'Each country reports in its own currency. Values are never summed across countries.',
    'by_country', coalesce((select jsonb_agg(to_jsonb(b) order by b.country) from by_country b), '[]'::jsonb),
    'by_store', coalesce((select jsonb_agg(to_jsonb(b) order by b.country, b.net_value desc) from by_store b), '[]'::jsonb),
    'by_month', coalesce((select jsonb_agg(to_jsonb(b) order by b.country, b.month) from by_month b), '[]'::jsonb),
    'top_items', coalesce((select jsonb_agg(to_jsonb(t) order by t.country, t.net_value desc) from top_items t), '[]'::jsonb),
    'linkage', coalesce((select jsonb_agg(to_jsonb(l) order by l.country) from linkage l), '[]'::jsonb)
  ) into v_out;
  return coalesce(v_out, jsonb_build_object('ok', true, 'by_country', '[]'::jsonb));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_mobile_analytics(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scope as (
    select p_country as country, p_from as d_from, p_to as d_to,
           nullif(btrim(coalesce(p_site,'')),'') as site
  ),
  t as (
    select r.risk_level, r.brand, r.site, r.cost_per_tyre, r.qty
    from public.tyre_records r, scope s
    where (s.country is null or r.country = s.country or r.country is null)
      and (s.d_from  is null or r.issue_date >= s.d_from)
      and (s.d_to    is null or r.issue_date <= s.d_to)
      and (s.site    is null or r.site = s.site)
  ),
  -- One line's spend, mirroring the web rule: unit price x quantity, and a
  -- missing/zero quantity counts as one tyre rather than as zero money.
  tv as (
    select *, coalesce(cost_per_tyre,0)
             * (case when coalesce(qty,0) > 0 then qty else 1 end) as line_cost
    from t
  ),
  f as (
    select 1 from public.vehicle_fleet v, scope s
    where (s.country is null or v.country = s.country or v.country is null)
      and (s.site    is null or v.site = s.site)
  ),
  i as (
    select 1 from public.inspections n, scope s
    where n.inspection_date >= (current_date - interval '30 days')
      and (s.country is null or n.country = s.country or n.country is null)
      and (s.site    is null or n.site = s.site)
  ),
  a as (
    select 1 from public.corrective_actions ca, scope s
    where coalesce(ca.status,'') not in ('closed','Closed','completed','Completed')
      and (s.country is null or ca.country = s.country or ca.country is null)
      and (s.site    is null or ca.site = s.site)
  ),
  -- Money is only comparable inside one country: SAR, AED and EGP must never be
  -- summed. On the All-countries view every cost below is NULL, and the phone
  -- ranks by volume instead of printing a meaningless blended total.
  single_country as (select (select country from scope) is not null as ok),
  risk_rows as (
    select coalesce(nullif(btrim(coalesce(risk_level,'')),''),'Unknown') as risk,
           count(*) as cnt
    from tv group by 1
  ),
  site_rows as (
    select coalesce(nullif(btrim(coalesce(site,'')),''),'Unknown') as site,
           count(*) as cnt, sum(line_cost) as cost
    from tv group by 1
  ),
  brand_rows as (
    select coalesce(nullif(btrim(coalesce(brand,'')),''),'Unknown') as brand,
           count(*) as cnt, sum(line_cost) as cost
    from tv group by 1
  ),
  site_opts as (
    select distinct nullif(btrim(coalesce(v.site,'')),'') as site
    from public.vehicle_fleet v, scope s
    where (s.country is null or v.country = s.country or v.country is null)
      and nullif(btrim(coalesce(v.site,'')),'') is not null
  )
  select json_build_object(
    'country',         (select country from scope),
    'site',            (select site from scope),
    'from',            (select d_from from scope),
    'to',              (select d_to from scope),
    'tyres_total',     (select count(*) from tv),
    'tyres_critical',  (select count(*) from tv where lower(coalesce(risk_level,'')) = 'critical'),
    'tyres_high',      (select count(*) from tv where lower(coalesce(risk_level,'')) = 'high'),
    'tyre_spend',      (case when (select ok from single_country)
                             then (select coalesce(sum(line_cost),0) from tv) end),
    'vehicles_total',  (select count(*) from f),
    'inspections_30d', (select count(*) from i),
    'open_actions',    (select count(*) from a),
    'by_risk',         coalesce((select json_agg(json_build_object('risk', risk, 'count', cnt)
                                  order by cnt desc) from risk_rows), '[]'::json),
    -- Ranked by cost inside one country, by volume on the All view, so the
    -- ordering always matches the number the phone is able to show.
    'by_site',         coalesce((select json_agg(x) from (
                          select json_build_object(
                            'site', site, 'count', cnt,
                            'cost', case when (select ok from single_country) then cost end) as x,
                            cnt, cost
                          from site_rows
                          order by (case when (select ok from single_country)
                                         then cost else cnt end) desc, cnt desc
                          limit 8) q), '[]'::json),
    'by_brand',        coalesce((select json_agg(x) from (
                          select json_build_object(
                            'brand', brand, 'count', cnt,
                            'cost', case when (select ok from single_country) then cost end) as x,
                            cnt
                          from brand_rows order by cnt desc limit 6) q), '[]'::json),
    'sites',           coalesce((select json_agg(site order by site) from site_opts), '[]'::json),
    'generated_at',    now()
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_my_access_grants()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_object_agg(module_key, effect), '{}'::jsonb)
  FROM (
    SELECT DISTINCT ON (module_key) module_key, effect
    FROM public.user_access_grants
    WHERE user_id = auth.uid() AND capability = 'view'
      AND (expires_at IS NULL OR expires_at > now())
    ORDER BY module_key, (effect = 'revoke') DESC
  ) t;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_my_capabilities()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_object_agg(module_key, caps), '{}'::jsonb)
  FROM (
    SELECT module_key, jsonb_object_agg(capability, effect) AS caps
    FROM (
      SELECT DISTINCT ON (module_key, capability) module_key, capability, effect
      FROM public.user_access_grants
      WHERE user_id = auth.uid()
        AND (expires_at IS NULL OR expires_at > now())
      ORDER BY module_key, capability, (effect = 'revoke') DESC
    ) picked
    GROUP BY module_key
  ) grouped;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_my_role()
 RETURNS text
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role
    FROM public.profiles
   WHERE id     = auth.uid()
     AND locked = false
     AND (approved IS NULL OR approved = true)
   LIMIT 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_my_site()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p.site FROM public.profiles p WHERE p.id = auth.uid() LIMIT 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_notification_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read notification health' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'workflow', (select jsonb_build_object(
        'total', count(*), 'delivered', count(*) filter (where status = 'delivered'),
        'skipped', count(*) filter (where status = 'skipped'),
        'failed', count(*) filter (where status in ('failed','error','dead')),
        'pending', count(*) filter (where status in ('pending','queued','retry')),
        'people', coalesce(sum(recipient_count) filter (where status = 'delivered'), 0),
        'retries', count(*) filter (where attempts > 1),
        'provider_errors', count(*) filter (where last_error is not null),
        'p50_seconds', percentile_cont(0.5) within group (order by extract(epoch from delivered_at - created_at))
                          filter (where delivered_at is not null),
        'p95_seconds', percentile_cont(0.95) within group (order by extract(epoch from delivered_at - created_at))
                          filter (where delivered_at is not null),
        'last_delivered_at', max(delivered_at))
      from public.workflow_notifications where created_at >= now() - interval '30 days'),
    'by_event', coalesce((select jsonb_agg(jsonb_build_object(
        'event_type', event_type, 'family', split_part(event_type, '.', 1), 'status', status,
        'messages', n, 'people', p, 'last_at', l, 'retries', rt, 'errors', er) order by n desc) from (
        select event_type, status, count(*) n, coalesce(sum(recipient_count), 0) p, max(created_at) l,
               count(*) filter (where attempts > 1) rt, count(*) filter (where last_error is not null) er
        from public.workflow_notifications where created_at >= now() - interval '30 days'
        group by 1, 2) s), '[]'::jsonb),
    'bell', (select jsonb_build_object(
        'sent_30d', count(*) filter (where created_at >= now() - interval '30 days'),
        'read_30d', count(*) filter (where created_at >= now() - interval '30 days' and read),
        'sent_all', count(*), 'read_all', count(*) filter (where read)) from public.notifications),
    'bell_by_type', coalesce((select jsonb_agg(jsonb_build_object('type', t, 'sent', n, 'read', r) order by n desc) from (
        select coalesce(type, 'other') t, count(*) n, count(*) filter (where read) r
        from public.notifications where created_at >= now() - interval '30 days' group by 1) s), '[]'::jsonb),
    'my_unread', (select count(*) from public.notifications where user_id = auth.uid() and not coalesce(read, false)),
    'reports', (select jsonb_build_object('sent_30d', count(*) filter (where status in ('sent','success','ok')),
                  'failed_30d', count(*) filter (where status not in ('sent','success','ok')),
                  'total_30d', count(*), 'last_at', max(sent_at))
                from public.report_send_log where sent_at >= now() - interval '30 days'),
    'devices', (select jsonb_build_object(
        'active', count(*) filter (where not coalesce(revoked, false)),
        'total', count(*),
        'seen_7d', count(*) filter (where not coalesce(revoked, false) and last_seen_at >= now() - interval '7 days'),
        'android', count(*) filter (where not coalesce(revoked, false) and lower(platform) = 'android'),
        'ios', count(*) filter (where not coalesce(revoked, false) and lower(platform) = 'ios')) from public.user_devices),
    'by_version', coalesce((select jsonb_agg(jsonb_build_object('version', ver, 'devices', n) order by n desc) from (
        select coalesce(nullif(btrim(app_version), ''), 'Not recorded') ver, count(*) n
        from public.user_devices where not coalesce(revoked, false) group by 1) s), '[]'::jsonb),
    'push_tokens', (select count(distinct user_id) from public.user_devices
                    where not coalesce(revoked, false) and nullif(btrim(push_token), '') is not null),
    'announcements', (select jsonb_build_object('total', count(*),
        'showing', count(*) filter (where active and coalesce(show_from, now()) <= now() and coalesce(show_until, now() + interval '1 second') > now()))
      from public.announcements)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_org_branding(p_org_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org    uuid;
  v_result jsonb;
BEGIN
  v_org := COALESCE(p_org_id, public.app_current_org());
  IF v_org IS NULL THEN RETURN '{}'::jsonb; END IF;
  IF v_org IS DISTINCT FROM public.app_current_org() AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorised to read branding for another organisation';
  END IF;
  SELECT jsonb_build_object(
           'org_id',        o.id,
           'name',          o.name,
           'logo_url',      COALESCE(o.settings->'branding'->>'logo_url', o.logo_url),
           'contact_email', COALESCE(o.settings->'branding'->>'contact_email', o.contact_email)
         ) || COALESCE(o.settings->'branding', '{}'::jsonb)
    INTO v_result
    FROM public.organisations o WHERE o.id = v_org;
  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_organisation_configuration(p_namespace text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(key text, value text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_values jsonb;
begin
  if auth.uid() is null or public.app_is_active() is not true or v_org is null then
    raise exception 'Active organisation membership required.' using errcode='42501';
  end if;
  if p_namespace not in ('settings','app_settings') or p_namespace is null then
    raise exception 'Unknown configuration namespace.' using errcode='22023';
  end if;
  select o.settings -> p_namespace into v_values from public.organisations o where o.id=v_org;
  if not found then raise exception 'Organisation unavailable.' using errcode='42501'; end if;
  return query select e.key,e.value from jsonb_each_text(coalesce(v_values,'{}'::jsonb)) e
    where p_key is null or e.key=p_key order by e.key;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_parts_expense_snapshot(p_site text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE v_org uuid := public.app_current_org(); result jsonb;
BEGIN

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  IF v_org IS NULL OR NOT public.app_is_active() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthorized'); END IF;
  WITH pc AS (
    SELECT * FROM public.parts_consumption
    WHERE organisation_id = v_org
      AND (p_site IS NULL OR store_code = p_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND (p_country IS NULL OR country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND (p_from IS NULL OR event_date >= p_from)
      AND (p_to   IS NULL OR event_date <= p_to)
  )
  SELECT jsonb_build_object(
    'ok', true, 'generated_at', now(),
    'kpis', jsonb_build_object(
      'total_expense', (SELECT COALESCE(round(sum(line_cost)),0) FROM pc),
      'tyre_expense',  (SELECT COALESCE(round(sum(tyre_cost)),0) FROM pc),
      'spare_expense', (SELECT COALESCE(round(sum(spare_cost)),0) FROM pc),
      'oil_expense',   (SELECT COALESCE(round(sum(oil_cost)),0) FROM pc),
      'lines',         (SELECT count(*) FROM pc),
      'tyres_issued',  (SELECT count(*) FROM pc WHERE cost_category='tyre'),
      'reassigned_tyres', (SELECT count(*) FROM pc WHERE cost_category='tyre' AND public._to_num(tyre_amount) IS NULL)
    ),
    'by_category', jsonb_build_array(
      jsonb_build_object('label','Tyres','spend',(SELECT COALESCE(round(sum(tyre_cost)),0) FROM pc)),
      jsonb_build_object('label','Spare Parts','spend',(SELECT COALESCE(round(sum(spare_cost)),0) FROM pc)),
      jsonb_build_object('label','Oil','spend',(SELECT COALESCE(round(sum(oil_cost)),0) FROM pc))),
    'by_asset', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
        SELECT asset_code AS label, round(sum(line_cost)) AS spend, count(*) AS lines
        FROM pc WHERE asset_code IS NOT NULL GROUP BY asset_code ORDER BY sum(line_cost) DESC LIMIT 20) x),
    'by_store', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
        SELECT COALESCE(NULLIF(store_code,''),'Unspecified') AS label, round(sum(line_cost)) AS spend
        FROM pc GROUP BY 1 ORDER BY sum(line_cost) DESC LIMIT 20) x),
    'top_items', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
        SELECT item_description AS label, round(sum(line_cost)) AS spend, count(*) AS n
        FROM pc WHERE item_description IS NOT NULL GROUP BY item_description ORDER BY sum(line_cost) DESC LIMIT 20) x),
    'monthly', (SELECT COALESCE(jsonb_agg(x ORDER BY x.m),'[]'::jsonb) FROM (
        SELECT to_char(date_trunc('month',event_date),'YYYY-MM') AS m,
               round(sum(tyre_cost)) AS tyre, round(sum(spare_cost)) AS spare, round(sum(oil_cost)) AS oil,
               round(sum(line_cost)) AS total
        FROM pc WHERE event_date IS NOT NULL GROUP BY 1) x)
  ) INTO result;
  RETURN result;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_parts_expense_snapshot_multi(p_countries text[] DEFAULT NULL::text[], p_site text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org       uuid := public.app_current_org();
  v_allowed   text[];
  v_refused   text[] := '{}';
  v_country   text;
  v_blocks    jsonb := '[]'::jsonb;
begin

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select allowed, refused into v_allowed, v_refused
    from public._scope_split_countries(p_countries);

  foreach v_country in array v_allowed loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'country',  v_country,
      'currency', public.currency_for_country(v_country),
      'result',   public.get_parts_expense_snapshot(p_site, v_country, p_from, p_to)));
  end loop;

  return jsonb_build_object(
    'ok', true, 'multi', true, 'generated_at', now(),
    'blended', false,
    'requested', to_jsonb(coalesce(p_countries, '{}'::text[])),
    'refused',   to_jsonb(v_refused),
    'countries', v_blocks);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_pipeline_runs(p_country text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v json;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  select json_agg(row_to_json(x)) into v from (
    select 'import' as source, coalesce(module,'import') as job_key, uploader as trigger, import_status as status,
           created_at as started_at, completed_at as finished_at, country,
           total_rows as rows_in, imported_rows as rows_out, skipped_rows as skipped, duplicate_rows as duplicates,
           case when coalesce(error_rows,0)>0 then error_rows||' row errors' else null end as error_reason
    from public.import_batches
    where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    union all
    select 'report', coalesce(report_type,'report'), null, status, sent_at, sent_at, null,
           null, null, null, null, error
    from public.report_send_log
    where organisation_id=v_org
    order by started_at desc nulls last
    limit p_limit) x;
  return json_build_object('ok',true,'runs',coalesce(v,'[]'::json));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_plan_coverage(p_country text DEFAULT NULL::text, p_horizon_days integer DEFAULT 30)
 RETURNS TABLE(site text, active_assets integer, planned_assets integer, inspected_recently integer, never_inspected integer, overdue_assets integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with params as (
    select (now() at time zone 'UTC')::date as today,
           greatest(1, least(coalesce(p_horizon_days, 30), 365)) as horizon
  ),
  fleet as (
    select upper(btrim(f.asset_no)) as asset_key,
           coalesce(nullif(btrim(f.site), ''), 'Not assigned') as site
    from public.vehicle_fleet f
    where coalesce(f.status, 'Active') = 'Active'
      and (p_country is null or p_country = 'All' or f.country = p_country)
      and coalesce(btrim(f.asset_no), '') <> ''
  ),
  last_seen as (
    select upper(btrim(i.asset_no)) as asset_key, max(i.inspection_date) as last_date
    from public.inspections i
    where coalesce(btrim(i.asset_no), '') <> ''
    group by 1
  ),
  planned as (
    select distinct upper(btrim(s.asset_no)) as asset_key
    from public.inspection_schedules s cross join params pa
    where s.scheduled_date between pa.today and pa.today + pa.horizon
      and lower(coalesce(s.status, '')) <> 'cancelled'
      and (p_country is null or p_country = 'All' or s.country is null or s.country = p_country)
  )
  select
    f.site,
    count(*)::integer                                                              as active_assets,
    count(*) filter (where pl.asset_key is not null)::integer                      as planned_assets,
    count(*) filter (where ls.last_date >= pa.today - pa.horizon)::integer         as inspected_recently,
    count(*) filter (where ls.last_date is null)::integer                          as never_inspected,
    count(*) filter (where pl.asset_key is null
                       and (ls.last_date is null or ls.last_date < pa.today - pa.horizon))::integer as overdue_assets
  from fleet f
  cross join params pa
  left join last_seen ls on ls.asset_key = f.asset_key
  left join planned  pl on pl.asset_key = f.asset_key
  group by f.site
  order by 6 desc, 2 desc
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_platform_activity()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v jsonb;
  v_today timestamptz := date_trunc('day', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh';
  v_month timestamptz := date_trunc('month', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh';
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read platform activity' using errcode = '42501';
  end if;

  with acc as (
    select p.id, p.role, coalesce(p.organisation_id, p.org_id) as org,
           coalesce(nullif(array_to_string(p.country, ', '), ''), 'No country set') as country,
           u.last_sign_in_at, u.created_at,
           (select max(d.last_seen_at) from public.user_devices d
             where d.user_id = p.id and not coalesce(d.revoked, false)) as app_seen
    from public.profiles p left join auth.users u on u.id = p.id
  ), act as (
    select *, (last_sign_in_at >= now() - interval '30 days' or app_seen >= now() - interval '30 days') as active30,
              (last_sign_in_at >= now() - interval '7 days' or app_seen >= now() - interval '7 days') as active7
    from acc
  ), daily as (
    select 'expense_lines' m, (created_at at time zone 'Asia/Riyadh')::date d, count(*) n
      from public.parts_consumption where created_at >= now() - interval '60 days' group by 2
    union all select 'job_cards', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from public.work_orders where created_at >= now() - interval '60 days' group by 2
    union all select 'inspections', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from public.inspections where created_at >= now() - interval '60 days' group by 2
    union all select 'meter_readings', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from (select created_at from public.odometer_logs where created_at >= now() - interval '60 days'
            union all select created_at from public.engine_hours_logs where created_at >= now() - interval '60 days') x group by 2
    union all select 'tyre_records', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from public.tyre_records where created_at >= now() - interval '60 days' group by 2
    union all select 'checklists', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from public.checklist_submissions where created_at >= now() - interval '60 days' group by 2
    union all select 'accidents', (created_at at time zone 'Asia/Riyadh')::date, count(*)
      from public.accidents where created_at >= now() - interval '60 days' group by 2
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'accounts', (select count(*) from acc),
    'approved', (select count(*) from public.profiles where coalesce(approved, false)),
    'signed_in', (select jsonb_build_object(
        'd30', count(*) filter (where last_sign_in_at >= now() - interval '30 days'),
        'd7', count(*) filter (where last_sign_in_at >= now() - interval '7 days'),
        'today', count(*) filter (where last_sign_in_at >= v_today),
        'ever', count(*) filter (where last_sign_in_at is not null),
        'never', count(*) filter (where last_sign_in_at is null)) from acc),
    'app_opened', (select jsonb_build_object(
        'd30', count(distinct user_id) filter (where last_seen_at >= now() - interval '30 days'),
        'd7', count(distinct user_id) filter (where last_seen_at >= now() - interval '7 days'),
        'devices', count(*), 'people', count(distinct user_id))
      from public.user_devices where not coalesce(revoked, false)),
    'active', (select jsonb_build_object('d30', count(*) filter (where active30), 'd7', count(*) filter (where active7)) from act),
    'cohort', (select jsonb_build_object(
        'month', to_char(v_month at time zone 'Asia/Riyadh', 'YYYY-MM'),
        'created', count(*) filter (where created_at >= v_month),
        'ever_signed', count(*) filter (where created_at >= v_month and last_sign_in_at is not null),
        'signed_7d', count(*) filter (where created_at >= v_month and last_sign_in_at >= now() - interval '7 days'),
        'never_signed', count(*) filter (where created_at >= v_month and last_sign_in_at is null)) from acc),
    'by_role', coalesce((select jsonb_agg(jsonb_build_object('role', r, 'accounts', n, 'active', a, 'app', ap) order by n desc) from (
        select coalesce(role, 'No role') r, count(*) n, count(*) filter (where active30) a,
               count(*) filter (where app_seen >= now() - interval '30 days') ap
        from act group by 1) s), '[]'::jsonb),
    'by_country', coalesce((select jsonb_agg(jsonb_build_object('country', c, 'accounts', n, 'active', a) order by n desc) from (
        select country c, count(*) n, count(*) filter (where active30) a from act group by 1) s), '[]'::jsonb),
    'by_org', coalesce((select jsonb_agg(jsonb_build_object(
        'org_id', o.id, 'name', o.name, 'created_at', o.created_at,
        'members', (select count(*) from act where act.org = o.id),
        'active30', (select count(*) from act where act.org = o.id and active30),
        'active7', (select count(*) from act where act.org = o.id and active7),
        'expense_lines', (select count(*) from public.parts_consumption x where x.organisation_id = o.id),
        'job_cards', (select count(*) from public.work_orders x where x.organisation_id = o.id),
        'tyre_records', (select count(*) from public.tyre_records x where x.organisation_id = o.id),
        'inspections', (select count(*) from public.inspections x where x.organisation_id = o.id),
        'last_write', greatest(
          (select max(created_at) from public.parts_consumption x where x.organisation_id = o.id),
          (select max(created_at) from public.work_orders x where x.organisation_id = o.id),
          (select max(created_at) from public.inspections x where x.organisation_id = o.id),
          (select max(created_at) from public.tyre_records x where x.organisation_id = o.id))
      ) order by o.created_at) from public.organisations o), '[]'::jsonb),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('module', m, 'day', d, 'n', n) order by d, m) from daily), '[]'::jsonb),
    'ai', (select jsonb_build_object(
        'd30', count(*) filter (where created_at >= now() - interval '30 days'),
        'all', count(*),
        'failed_30d', count(*) filter (where created_at >= now() - interval '30 days' and status is not null and status <> 'success'),
        'cost_30d', coalesce(sum(cost_usd) filter (where created_at >= now() - interval '30 days'), 0),
        'last_at', max(created_at)) from public.ai_token_logs),
    'ai_budget', (select jsonb_build_object('period', period, 'cost_cap_usd', cost_cap_usd, 'token_cap', token_cap,
                    'hard_stop', hard_stop, 'active', active)
                  from public.ai_budgets where active order by updated_at desc nulls last limit 1)
  ) into v;
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_production_monthly(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
WITH rows AS (
  SELECT date_trunc('month', period_date)::date AS month,
         m3, approved_m3, rejected, reason, remarks,
         coalesce(nullif(btrim(site), ''), 'Not stated') AS site
    FROM public.production_logs
   WHERE (p_country IS NULL OR country = p_country)
     AND (p_from IS NULL OR period_date >= p_from)
     AND (p_to   IS NULL OR period_date <= p_to)
     AND (p_reason IS NULL
          OR coalesce(nullif(btrim(reason), ''), '(none)') = p_reason)
),
monthly AS (
  SELECT month,
         count(*) AS loads,
         round(sum(coalesce(m3, 0))::numeric, 1) AS supplied_m3,
         round(sum(coalesce(approved_m3, m3, 0))::numeric, 1) AS approved_m3,
         count(*) FILTER (WHERE rejected) AS rejected_loads,
         round(coalesce(sum(coalesce(m3, 0)) FILTER (WHERE rejected), 0)::numeric, 1) AS rejected_m3
    FROM rows
   GROUP BY month
),
reasons AS (
  SELECT month,
         coalesce(nullif(btrim(reason), ''), 'Unspecified') AS reason,
         count(*) AS loads,
         round(sum(coalesce(m3, 0))::numeric, 1) AS m3,
         (array_agg(DISTINCT nullif(btrim(remarks), ''))
            FILTER (WHERE nullif(btrim(remarks), '') IS NOT NULL))[1:3] AS remarks
    FROM rows
   WHERE rejected OR nullif(btrim(reason), '') IS NOT NULL
   GROUP BY 1, 2
),
reasons_j AS (
  SELECT month,
         jsonb_agg(jsonb_build_object(
           'reason', reason, 'loads', loads, 'm3', m3,
           'remarks', to_jsonb(coalesce(remarks, '{}'::text[]))
         ) ORDER BY loads DESC) AS reasons
    FROM reasons
   GROUP BY month
),
sites AS (
  SELECT month, site,
         count(*) AS loads,
         round(sum(coalesce(approved_m3, m3, 0))::numeric, 1) AS approved_m3,
         round(sum(coalesce(m3, 0))::numeric, 1) AS supplied_m3
    FROM rows
   GROUP BY 1, 2
),
sites_j AS (
  SELECT month,
         jsonb_agg(jsonb_build_object(
           'site', site, 'loads', loads,
           'approved_m3', approved_m3, 'supplied_m3', supplied_m3
         ) ORDER BY approved_m3 DESC) AS sites
    FROM sites
   GROUP BY month
)
SELECT coalesce(jsonb_agg(jsonb_build_object(
         'month',           to_char(m.month, 'YYYY-MM'),
         'loads',           m.loads,
         'supplied_m3',     m.supplied_m3,
         'approved_m3',     m.approved_m3,
         'not_approved_m3', round(m.supplied_m3 - m.approved_m3, 1),
         'rejected_loads',  m.rejected_loads,
         'rejected_m3',     m.rejected_m3,
         'reasons',         coalesce(r.reasons, '[]'::jsonb),
         'sites',           coalesce(s.sites, '[]'::jsonb)
       ) ORDER BY m.month DESC), '[]'::jsonb)
  FROM monthly m
  LEFT JOIN reasons_j r USING (month)
  LEFT JOIN sites_j   s USING (month);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_production_reasons(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'reason', reason, 'loads', loads,
           'rejected_loads', rejected_loads, 'm3', m3
         ) ORDER BY loads DESC), '[]'::jsonb)
    FROM (
      SELECT coalesce(nullif(btrim(reason), ''), '(none)') AS reason,
             count(*) AS loads,
             count(*) FILTER (WHERE rejected) AS rejected_loads,
             round(sum(coalesce(m3, 0))::numeric, 1) AS m3
        FROM public.production_logs
       WHERE (p_country IS NULL OR country = p_country)
         AND (p_from IS NULL OR period_date >= p_from)
         AND (p_to   IS NULL OR period_date <= p_to)
       GROUP BY 1
    ) t;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_production_rejections(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, date_trunc('month', now())::date);
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  return (
    with prod as (
      select coalesce(nullif(btrim(site), ''), 'Not stated') as site,
             coalesce(nullif(btrim(reason), ''), coalesce(nullif(btrim(remarks), ''), 'Not stated')) as reason,
             coalesce(supplied_m3, m3, 0) as supplied,
             coalesce(approved_m3, m3, 0) as approved,
             (rejected or coalesce(approved_m3, m3, 0) < coalesce(supplied_m3, m3, 0)) as is_rejected
        from public.production_logs
       where organisation_id = v_org and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
         and period_date between v_from and v_to
         and (p_reason is null
              or coalesce(nullif(btrim(reason), ''), '(none)') = p_reason)
    ),
    rej as (
      select site, reason, greatest(supplied - approved, 0) as not_approved_m3
        from prod where is_rejected and greatest(supplied - approved, 0) > 0
    )
    select jsonb_build_object(
      'ok', true, 'from', v_from, 'to', v_to,
      'total', jsonb_build_object(
        'supplied_m3', round(coalesce((select sum(supplied) from prod), 0), 2),
        'approved_m3', round(coalesce((select sum(approved) from prod), 0), 2),
        'not_approved_m3', round(coalesce((select sum(not_approved_m3) from rej), 0), 2),
        'rejected_loads', (select count(*) from prod where is_rejected)
      ),
      'by_site', coalesce((select jsonb_agg(jsonb_build_object(
          'site', t.site, 'not_approved_m3', t.na, 'loads', t.loads) order by t.na desc)
          from (select site, round(sum(not_approved_m3),2) na, count(*) loads from rej group by site) t), '[]'::jsonb),
      'by_reason', coalesce((select jsonb_agg(jsonb_build_object(
          'reason', t.reason, 'not_approved_m3', t.na, 'loads', t.loads) order by t.na desc)
          from (select reason, round(sum(not_approved_m3),2) na, count(*) loads from rej group by reason) t), '[]'::jsonb)
    )
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_production_stations(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'station', station, 'site', site, 'mapped', mapped,
           'loads', loads, 'm3', m3,
           'first_day', first_day, 'last_day', last_day
         ) ORDER BY loads DESC), '[]'::jsonb)
    FROM (
      SELECT coalesce(nullif(btrim(p.station), ''), nullif(btrim(p.site), ''), '(blank)') AS station,
             max(p.site) AS site,
             bool_or(m.id IS NOT NULL) AS mapped,
             count(*) AS loads,
             round(sum(coalesce(p.approved_m3, p.m3, 0))::numeric, 1) AS m3,
             min(p.period_date) AS first_day,
             max(p.period_date) AS last_day
        FROM public.production_logs p
        LEFT JOIN public.production_station_map m
               ON m.organisation_id = p.organisation_id
              AND (m.country IS NULL OR m.country = p.country)
              AND upper(btrim(m.station)) = upper(btrim(coalesce(p.station, p.site)))
       WHERE p.organisation_id = public.app_current_org()
         AND (p_country IS NULL OR p.country = p_country)
         AND (p_country is null or public.app_can_see_country(p_country) is not false)
         AND (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries())
              or lower(btrim(p.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((p.site)::text is null or btrim((p.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((p.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       GROUP BY 1
    ) t;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_public_config()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb)
  from public.system_config
  where key = any (array[
    'maintenance_mode','maintenance_message','registration_open','allow_signups',
    'require_approval','app_version','session_timeout_hours','two_factor_required',
    'password_min_length','default_currency','mobile_login_hero',
    'auth_google_enabled','auth_microsoft_enabled','qr_login_enabled'
  ]);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_push_delivery_summary(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_days integer := greatest(1, least(coalesce(p_days, 7), 90));
begin
  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'days', v_days,
      'total', count(*),
      'accepted', count(*) filter (where status = 'accepted'),
      'failed', count(*) filter (where status = 'failed'),
      'invalid_token', count(*) filter (where status = 'invalid_token'),
      'by_channel', coalesce((
        select jsonb_object_agg(channel, n) from (
          select channel, count(*) n from public.push_delivery_receipts
          where created_at >= now() - make_interval(days => v_days) group by channel) c), '{}'::jsonb),
      'top_errors', coalesce((
        select jsonb_agg(jsonb_build_object('error', error, 'count', n)) from (
          select error, count(*) n from public.push_delivery_receipts
          where created_at >= now() - make_interval(days => v_days) and status <> 'accepted' and error is not null
          group by error order by n desc limit 5) e), '[]'::jsonb)
    )
    from public.push_delivery_receipts
    where created_at >= now() - make_interval(days => v_days)
  );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_record_provenance(p_table text, p_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare v_rec jsonb; v_batch jsonb := null; v_uid text; v_org uuid := public.app_current_org();
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if p_table not in ('tyre_records','work_orders','parts_consumption','vehicle_fleet','accidents','inspections','stock_records') then
    raise exception 'unsupported table %', p_table;
  end if;
  execute format('select to_jsonb(t) from public.%I t where t.id=%L', p_table, p_id) into v_rec;
  if v_rec is null then return json_build_object('ok',false,'reason','not_found'); end if;
  if (v_rec ? 'organisation_id') and v_org is not null and (v_rec->>'organisation_id') is distinct from v_org::text then
    return json_build_object('ok',false,'reason','forbidden');
  end if;
  if (v_rec ? 'country') and not (
       (v_rec->>'country') is null
       or public.is_super_admin()
       or public.app_sees_all_countries()
       or lower(btrim(v_rec->>'country')) = any(coalesce(public.app_country_scope(), '{}'::text[]))
     ) then
    return json_build_object('ok',false,'reason','forbidden');
  end if;
  v_uid := v_rec->>'import_uid';
  if v_uid is not null then
    begin
      select to_jsonb(b) into v_batch from public.import_batches b where b.id::text = (v_rec->>'import_batch_id') limit 1;
    exception when others then v_batch := null; end;
  end if;
  return json_build_object('ok',true,'table',p_table,'id',p_id,'record',v_rec,'import_batch',v_batch);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_report_snapshot(p_token text, p_password text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  t public.report_shares%ROWTYPE;
  v_org uuid; v_months text[]; v_company text; v_logo text;
  v_site text := nullif(btrim(p_site),''); v_country text := nullif(btrim(p_country),'');
  v_from date; v_to date; v_cfrom date; v_cto date;
  v_km numeric; v_hours numeric; v_m3 numeric;
  v_tyre_cost numeric; v_maint_cost numeric; v_total_cost numeric;
  result jsonb;
BEGIN
  SELECT * INTO t FROM public.report_shares WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invalid'); END IF;
  IF NOT t.active THEN RETURN jsonb_build_object('ok', false, 'reason', 'revoked'); END IF;
  IF t.expires_at IS NOT NULL AND t.expires_at < now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'expired'); END IF;
  IF t.password_hash IS NOT NULL THEN
    IF p_password IS NULL OR not public.share_password_ok('report', t.id, p_password, t.password_hash) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'password'); END IF;
  END IF;
  v_org := t.organisation_id;

  BEGIN v_from := nullif(btrim(p_from),'')::date; EXCEPTION WHEN others THEN v_from := NULL; END;
  BEGIN v_to   := nullif(btrim(p_to),'')::date;   EXCEPTION WHEN others THEN v_to   := NULL; END;

  SELECT array_agg(to_char(m, 'YYYY-MM') ORDER BY m) INTO v_months
  FROM generate_series(date_trunc('month', now()) - interval '11 months', date_trunc('month', now()), interval '1 month') m;

  SELECT value::text INTO v_company FROM public.settings WHERE key = 'company_name' LIMIT 1;
  v_company := coalesce(nullif(replace(replace(v_company, '"', ''), '\', ''), ''), 'TyrePulse');
  SELECT coalesce(value_text, value::text) INTO v_logo FROM public.system_config WHERE key = 'company_logo' LIMIT 1;
  v_logo := nullif(replace(replace(coalesce(v_logo,''), '"', ''), '\', ''), '');

  v_cfrom := coalesce(v_from, (date_trunc('month', now()) - interval '11 months')::date);
  v_cto   := coalesce(v_to, now()::date);

  SELECT coalesce(sum(delta),0) INTO v_km FROM (
    SELECT max(odometer_km)-min(odometer_km) delta FROM public.odometer_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
      AND odometer_km IS NOT NULL AND reading_date>=v_cfrom AND reading_date<=v_cto
    GROUP BY asset_no HAVING count(*)>=2
  ) d;
  SELECT coalesce(sum(delta),0) INTO v_hours FROM (
    SELECT max(engine_hours)-min(engine_hours) delta FROM public.engine_hours_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
      AND engine_hours IS NOT NULL AND reading_date>=v_cfrom AND reading_date<=v_cto
    GROUP BY asset_no HAVING count(*)>=2
  ) d;
  SELECT coalesce(sum(m3),0) INTO v_m3 FROM public.production_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
      AND period_date>=v_cfrom AND period_date<=v_cto;

  SELECT coalesce(round(sum(cost_per_tyre*coalesce(nullif(qty,0),1))),0) INTO v_tyre_cost
    FROM public.tyre_records
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
      AND issue_date>=v_cfrom AND issue_date<=v_cto;

  v_maint_cost := coalesce((
      SELECT round(coalesce(sum(coalesce(labour_cost,0)+coalesce(parts_cost,0)+coalesce(lubricant_cost,0)+coalesce(outside_repair_cost,0)),0))
      FROM public.work_orders
      WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
        AND coalesce(completed_at,opened_at,created_at)::date>=v_cfrom AND coalesce(completed_at,opened_at,created_at)::date<=v_cto
    ),0)
    + coalesce((
      SELECT round(coalesce(sum(total_cost),0)) FROM public.pm_service_records
      WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)
        AND service_date>=v_cfrom AND service_date<=v_cto
    ),0);
  v_total_cost := coalesce(v_tyre_cost,0) + coalesce(v_maint_cost,0);

  result := jsonb_build_object(
    'ok', true, 'company', v_company, 'logo', v_logo, 'name', t.name, 'generated_at', now(),
    'rotate_seconds', t.rotate_seconds, 'refresh_seconds', t.refresh_seconds, 'pages', t.pages,
    'layout', t.layout,
    'filters', jsonb_build_object('site', v_site, 'country', v_country, 'from', v_from, 'to', v_to),
    'sites', (SELECT COALESCE(jsonb_agg(s ORDER BY s),'[]'::jsonb) FROM (SELECT DISTINCT nullif(btrim(site),'') s FROM public.tyre_records WHERE organisation_id=v_org AND site IS NOT NULL UNION SELECT DISTINCT nullif(btrim(site),'') FROM public.accidents WHERE organisation_id=v_org AND site IS NOT NULL) u WHERE s IS NOT NULL LIMIT 60),
    'countries', (SELECT COALESCE(jsonb_agg(c ORDER BY c),'[]'::jsonb) FROM (SELECT DISTINCT nullif(btrim(country),'') c FROM public.tyre_records WHERE organisation_id=v_org AND country IS NOT NULL) u WHERE c IS NOT NULL LIMIT 30),
    'labels', to_jsonb((SELECT array_agg(to_char(to_date(k,'YYYY-MM'),'Mon YY') ORDER BY k) FROM unnest(v_months) k)),
    'kpis', jsonb_build_object(
      'fleet',            (SELECT count(*) FROM public.vehicle_fleet WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'tyres',            (SELECT count(*) FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to)),
      'tyre_spend',       (SELECT round(coalesce(sum(cost_per_tyre*coalesce(nullif(qty,0),1)),0)) FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to)),
      'accidents',        (SELECT count(*) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'open_accidents',   (SELECT count(*) FROM public.accidents WHERE organisation_id=v_org AND release_date IS NULL AND lower(coalesce(status,'')) NOT IN ('closed','released') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'claims_claimed',   (SELECT round(coalesce(sum(claim_amount),0)) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'claims_recovered', (SELECT round(coalesce(sum(recovered_amount),0)) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'inspections',      (SELECT count(*) FROM public.inspections WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR inspection_date>=v_from) AND (v_to IS NULL OR inspection_date<=v_to)),
      'work_orders_open', (SELECT count(*) FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country))
    ),
    'cost', public._report_cost_block(v_org, v_site, v_country, v_cfrom, v_cto, v_months),
    'breakdowns', jsonb_build_object(
      'severity',        (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(severity),''),'Unspecified') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 6) x),
      'accidents_by_site',(SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'tyres_by_site',   (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, count(*) c FROM public.tyre_records WHERE organisation_id=v_org AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'claim_status',    (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(claim_status),''),'Unspecified') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (claim_amount>0 OR claim_status IS NOT NULL OR insurer IS NOT NULL) AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 6) x)
    ),
    'heatmap', (SELECT COALESCE(jsonb_agg(jsonb_build_object('site',lbl,'severity',sev,'value',c)),'[]'::jsonb) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, coalesce(nullif(btrim(severity),''),'Unspecified') sev, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1,2 ORDER BY 1,2) x),
    'ops', jsonb_build_object(
      'work_orders_open', (SELECT count(*) FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'job_cards_today',  (SELECT count(*) FROM public.work_orders WHERE organisation_id=v_org AND coalesce(opened_at,created_at)::date=current_date AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'tyre_changes_today',(SELECT count(*) FROM public.tyre_records WHERE organisation_id=v_org AND issue_date::date=current_date AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'inspections_today',(SELECT count(*) FROM public.inspections WHERE organisation_id=v_org AND inspection_date::date=current_date AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'accidents_today',  (SELECT count(*) FROM public.accidents WHERE organisation_id=v_org AND incident_date::date=current_date AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'alerts_critical',  (SELECT count(*) FROM public.alerts WHERE organisation_id=v_org AND coalesce(resolved,false)=false AND lower(coalesce(severity,'')) IN ('critical','high') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'pm_overdue',       (SELECT count(*) FROM public.pm_programs WHERE organisation_id=v_org AND status='active' AND next_due IS NOT NULL AND next_due<current_date AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'pm_due_soon',      (SELECT count(*) FROM public.pm_programs WHERE organisation_id=v_org AND status='active' AND next_due IS NOT NULL AND next_due>=current_date AND next_due<=current_date+14 AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'pm_compliance',    (SELECT CASE WHEN count(*) FILTER (WHERE status='active')>0 THEN round(100.0*count(*) FILTER (WHERE status='active' AND (next_due IS NULL OR next_due>=current_date))/count(*) FILTER (WHERE status='active')) ELSE NULL END FROM public.pm_programs WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country)),
      'wo_by_status',     (SELECT COALESCE(jsonb_agg(jsonb_build_object('label',lbl,'value',c)),'[]'::jsonb) FROM (SELECT coalesce(nullif(btrim(status),''),'Unspecified') lbl, count(*) c FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) GROUP BY 1 ORDER BY c DESC LIMIT 6) x),
      'wo_by_site',       (SELECT COALESCE(jsonb_agg(jsonb_build_object('label',lbl,'value',c)),'[]'::jsonb) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, count(*) c FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_country IS NULL OR country=v_country) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'wo_by_type',       (SELECT COALESCE(jsonb_agg(jsonb_build_object('label',lbl,'value',c)),'[]'::jsonb) FROM (SELECT coalesce(nullif(btrim(work_type),''),'Unspecified') lbl, count(*) c FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'wo_trend',         (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(coalesce(opened_at,created_at),'YYYY-MM') k, count(*) v FROM public.work_orders WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) GROUP BY 1) s ON s.k=m.k),
      'wo_heatmap',       (SELECT COALESCE(jsonb_agg(jsonb_build_object('site',lbl,'severity',st,'value',c)),'[]'::jsonb) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, coalesce(nullif(btrim(status),''),'Unspecified') st, count(*) c FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) GROUP BY 1,2 ORDER BY 1,2) x),
      'open_job_cards',   (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (SELECT jsonb_build_object('wo_no',work_order_no,'asset_no',asset_no,'status',status,'site',site,'priority',priority,'work_type',work_type) x FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) ORDER BY coalesce(opened_at,created_at) DESC LIMIT 14) q),
      'pm_due_list',      (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (SELECT jsonb_build_object('name',name,'asset_no',asset_no,'next_due',next_due,'priority',priority) x FROM public.pm_programs WHERE organisation_id=v_org AND status='active' AND next_due IS NOT NULL AND (v_site IS NULL OR site=v_site) AND (v_country IS NULL OR country=v_country) ORDER BY next_due ASC LIMIT 14) q)
    )
  );

  UPDATE public.report_shares SET last_viewed_at = now(), view_count = view_count + 1 WHERE id = t.id;
  RETURN result;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_report_snapshot_authed(p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE
  v_org uuid;
  v_months text[]; v_company text; v_logo text;
  v_site text := nullif(btrim(p_site),''); v_country text := nullif(btrim(p_country),'');
  v_from date; v_to date; v_cfrom date; v_cto date;
  v_km numeric; v_hours numeric; v_m3 numeric;
  v_tyre_cost numeric; v_maint_cost numeric; v_total_cost numeric;
  result jsonb;
BEGIN

  if p_site is not null and btrim(p_site) <> '' and not public.app_can_see_site(p_site) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  v_org := public.app_current_org();
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unavailable');
  END IF;

  BEGIN v_from := nullif(btrim(p_from),'')::date; EXCEPTION WHEN others THEN v_from := NULL; END;
  BEGIN v_to   := nullif(btrim(p_to),'')::date;   EXCEPTION WHEN others THEN v_to   := NULL; END;

  SELECT array_agg(to_char(m, 'YYYY-MM') ORDER BY m) INTO v_months
  FROM generate_series(date_trunc('month', now()) - interval '11 months', date_trunc('month', now()), interval '1 month') m;

  SELECT value::text INTO v_company FROM public.settings WHERE key = 'company_name' LIMIT 1;
  v_company := coalesce(nullif(replace(replace(v_company, '"', ''), '\', ''), ''), 'TyrePulse');
  SELECT coalesce(value_text, value::text) INTO v_logo FROM public.system_config WHERE key = 'company_logo' LIMIT 1;
  v_logo := nullif(replace(replace(coalesce(v_logo,''), '"', ''), '\', ''), '');

  v_cfrom := coalesce(v_from, (date_trunc('month', now()) - interval '11 months')::date);
  v_cto   := coalesce(v_to, now()::date);

  SELECT coalesce(sum(delta),0) INTO v_km FROM (
    SELECT max(odometer_km)-min(odometer_km) delta FROM public.odometer_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND odometer_km IS NOT NULL AND reading_date>=v_cfrom AND reading_date<=v_cto
    GROUP BY asset_no HAVING count(*)>=2
  ) d;
  SELECT coalesce(sum(delta),0) INTO v_hours FROM (
    SELECT max(engine_hours)-min(engine_hours) delta FROM public.engine_hours_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND engine_hours IS NOT NULL AND reading_date>=v_cfrom AND reading_date<=v_cto
    GROUP BY asset_no HAVING count(*)>=2
  ) d;
  SELECT coalesce(sum(m3),0) INTO v_m3 FROM public.production_logs
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND period_date>=v_cfrom AND period_date<=v_cto;

  SELECT coalesce(round(sum(cost_per_tyre*coalesce(nullif(qty,0),1))),0) INTO v_tyre_cost
    FROM public.tyre_records
    WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      AND issue_date>=v_cfrom AND issue_date<=v_cto;

  v_maint_cost := coalesce((
      SELECT round(coalesce(sum(coalesce(labour_cost,0)+coalesce(parts_cost,0)+coalesce(lubricant_cost,0)+coalesce(outside_repair_cost,0)),0))
      FROM public.work_orders
      WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
        AND coalesce(completed_at,opened_at,created_at)::date>=v_cfrom AND coalesce(completed_at,opened_at,created_at)::date<=v_cto
    ),0)
    + coalesce((
      SELECT round(coalesce(sum(total_cost),0)) FROM public.pm_service_records
      WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
        AND service_date>=v_cfrom AND service_date<=v_cto
    ),0);
  v_total_cost := coalesce(v_tyre_cost,0) + coalesce(v_maint_cost,0);

  result := jsonb_build_object(
    'ok', true, 'company', v_company, 'logo', v_logo, 'generated_at', now(),
    'filters', jsonb_build_object('site', v_site, 'country', v_country, 'from', v_from, 'to', v_to),
    'labels', to_jsonb((SELECT array_agg(to_char(to_date(k,'YYYY-MM'),'Mon YY') ORDER BY k) FROM unnest(v_months) k)),
    'kpis', jsonb_build_object(
      'fleet',            (SELECT count(*) FROM public.vehicle_fleet WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))),
      'tyres',            (SELECT count(*) FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to)),
      'tyre_spend',       (SELECT round(coalesce(sum(cost_per_tyre*coalesce(nullif(qty,0),1)),0)) FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to)),
      'accidents',        (SELECT count(*) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'open_accidents',   (SELECT count(*) FROM public.accidents WHERE organisation_id=v_org AND release_date IS NULL AND lower(coalesce(status,'')) NOT IN ('closed','released') AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'claims_claimed',   (SELECT round(coalesce(sum(claim_amount),0)) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'claims_recovered', (SELECT round(coalesce(sum(recovered_amount),0)) FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to)),
      'inspections',      (SELECT count(*) FROM public.inspections WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR inspection_date>=v_from) AND (v_to IS NULL OR inspection_date<=v_to)),
      'work_orders_open', (SELECT count(*) FROM public.work_orders WHERE organisation_id=v_org AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled') AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))
    ),
    'cost', jsonb_build_object(
      'from', v_cfrom, 'to', v_cto,
      'tyre_cost', v_tyre_cost, 'maintenance_cost', v_maint_cost, 'total_cost', v_total_cost,
      'km', round(coalesce(v_km,0)), 'engine_hours', round(coalesce(v_hours,0),1), 'm3', round(coalesce(v_m3,0),1),
      'cost_per_km',   CASE WHEN coalesce(v_km,0)>0    THEN round(v_total_cost/v_km,2)    ELSE NULL END,
      'cost_per_hour', CASE WHEN coalesce(v_hours,0)>0 THEN round(v_total_cost/v_hours,2) ELSE NULL END,
      'cost_per_m3',   CASE WHEN coalesce(v_m3,0)>0    THEN round(v_total_cost/v_m3,2)    ELSE NULL END,
      'tyre_cpk',      CASE WHEN coalesce(v_km,0)>0    THEN round(v_tyre_cost/v_km,2)     ELSE NULL END,
      'trend', jsonb_build_object(
        'total', (SELECT jsonb_agg(round(coalesce(tt.v,0)+coalesce(ww.v,0)+coalesce(pp.v,0)) ORDER BY m.k) FROM unnest(v_months) m(k)
          LEFT JOIN (SELECT to_char(issue_date,'YYYY-MM') k, sum(cost_per_tyre*coalesce(nullif(qty,0),1)) v FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) tt ON tt.k=m.k
          LEFT JOIN (SELECT to_char(coalesce(completed_at,opened_at,created_at),'YYYY-MM') k, sum(coalesce(labour_cost,0)+coalesce(parts_cost,0)+coalesce(lubricant_cost,0)+coalesce(outside_repair_cost,0)) v FROM public.work_orders WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) ww ON ww.k=m.k
          LEFT JOIN (SELECT to_char(service_date,'YYYY-MM') k, sum(total_cost) v FROM public.pm_service_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) pp ON pp.k=m.k),
        'm3', (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(period_date,'YYYY-MM') k, sum(m3) v FROM public.production_logs WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k)
      )
    ),
    'trends', jsonb_build_object(
      'tyre_spend',       (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(issue_date,'YYYY-MM') k, sum(cost_per_tyre*coalesce(nullif(qty,0),1)) v FROM public.tyre_records WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k),
      'accidents',        (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(incident_date,'YYYY-MM') k, count(*) v FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k),
      'claims_claimed',   (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(incident_date,'YYYY-MM') k, sum(claim_amount) v FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k),
      'claims_recovered', (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(incident_date,'YYYY-MM') k, sum(recovered_amount) v FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k),
      'inspections',      (SELECT jsonb_agg(coalesce(s.v,0) ORDER BY m.k) FROM unnest(v_months) m(k) LEFT JOIN (SELECT to_char(inspection_date,'YYYY-MM') k, count(*) v FROM public.inspections WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) GROUP BY 1) s ON s.k=m.k)
    ),
    'breakdowns', jsonb_build_object(
      'severity',        (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(severity),''),'Unspecified') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 6) x),
      'accidents_by_site',(SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'tyres_by_site',   (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(site),''),'Unassigned') lbl, count(*) c FROM public.tyre_records WHERE organisation_id=v_org AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_from IS NULL OR issue_date>=v_from) AND (v_to IS NULL OR issue_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 8) x),
      'claim_status',    (SELECT jsonb_agg(jsonb_build_object('label',lbl,'value',c)) FROM (SELECT coalesce(nullif(btrim(claim_status),''),'Unspecified') lbl, count(*) c FROM public.accidents WHERE organisation_id=v_org AND (claim_amount>0 OR claim_status IS NOT NULL OR insurer IS NOT NULL) AND (v_site IS NULL OR site=v_site) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND (v_country IS NULL OR country=v_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim((country)::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND (v_from IS NULL OR incident_date>=v_from) AND (v_to IS NULL OR incident_date<=v_to) GROUP BY 1 ORDER BY c DESC LIMIT 6) x)
    )
  );

  RETURN result;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_report_tyre_maintenance(p_token text, p_password text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE
  t public.report_shares%ROWTYPE;
  v_org uuid;
  v_site text := nullif(btrim(p_site),'');
  v_country text := nullif(btrim(p_country),'');
  v_from date; v_to date;
  result jsonb;
BEGIN
  SELECT * INTO t FROM public.report_shares WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invalid'); END IF;
  IF NOT t.active THEN RETURN jsonb_build_object('ok', false, 'reason', 'revoked'); END IF;
  IF t.expires_at IS NOT NULL AND t.expires_at < now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'expired'); END IF;
  IF t.password_hash IS NOT NULL THEN
    IF p_password IS NULL OR not public.share_password_ok('report', t.id, p_password, t.password_hash) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'password'); END IF;
  END IF;
  v_org := t.organisation_id;
  BEGIN v_from := nullif(btrim(p_from),'')::date; EXCEPTION WHEN others THEN v_from := NULL; END;
  BEGIN v_to   := nullif(btrim(p_to),'')::date;   EXCEPTION WHEN others THEN v_to   := NULL; END;

  WITH tr AS (
    SELECT status, removal_reason, position, site, cost_per_tyre, total_km, brand
    FROM public.tyre_records
    WHERE organisation_id = v_org
      AND (v_site IS NULL OR site = v_site)
      AND (v_country IS NULL OR country = v_country)
  ),
  wo AS (
    SELECT work_type, status, site, COALESCE(labour_cost,0)+COALESCE(parts_cost,0) AS cost, opened_at::date d
    FROM public.work_orders
    WHERE organisation_id = v_org
      AND (v_site IS NULL OR site = v_site)
      AND (v_country IS NULL OR country = v_country)
      AND (v_from IS NULL OR opened_at::date >= v_from)
      AND (v_to   IS NULL OR opened_at::date <= v_to)
  ),
  li AS (
    SELECT task FROM public.work_order_line_items
    WHERE organisation_id = v_org
      AND (v_site IS NULL OR site = v_site)
      AND (v_country IS NULL OR country = v_country)
      AND (v_from IS NULL OR opened_date >= v_from)
      AND (v_to   IS NULL OR opened_date <= v_to)
  )
  SELECT jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'company', coalesce(nullif(replace(replace((SELECT value::text FROM public.settings WHERE key='company_name' LIMIT 1),'"',''),'\',''),''),'TyrePulse'),
    'name', t.name,
    'tyre_failure', jsonb_build_object(
      'active',  (SELECT count(*) FROM tr WHERE status='Active'),
      'removed', (SELECT count(*) FROM tr WHERE status='Removed'),
      'total',   (SELECT count(*) FROM tr),
      'avg_cpk', (SELECT round(avg(cost_per_tyre/nullif(total_km,0))::numeric,3) FROM tr WHERE cost_per_tyre>0 AND total_km>1000),
      'avg_life_km', (SELECT round(avg(total_km)) FROM tr WHERE total_km>0),
      'reasons', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
          SELECT removal_reason AS label, count(*) AS n FROM tr WHERE status='Removed' AND removal_reason IS NOT NULL
            AND NOT (regexp_replace(lower(removal_reason), '[^a-z0-9]', '', 'g') = ANY (coalesce(
              (SELECT array_agg(regexp_replace(lower(bt), '[^a-z0-9]', '', 'g'))
                 FROM unnest(public.brain_tokens('tyre_brand') || ARRAY['rock holder','vglory']) bt),
              '{}'::text[])))
          GROUP BY removal_reason ORDER BY count(*) DESC LIMIT 12) x),
      'by_position', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(position,''),'Unknown') AS label, count(*) AS n FROM tr WHERE status='Removed'
          GROUP BY 1 ORDER BY count(*) DESC LIMIT 14) x)
    ),
    'maintenance', jsonb_build_object(
      'job_cards',   (SELECT count(*) FROM wo),
      'line_items',  (SELECT count(*) FROM li),
      'total_spend', (SELECT COALESCE(round(sum(cost)),0) FROM wo),
      'open_jobs',   (SELECT count(*) FROM wo WHERE status NOT IN ('Completed','Cancelled')),
      'by_work_type', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
          SELECT work_type AS label, count(*) AS jobs, COALESCE(round(sum(cost)),0) AS spend
          FROM wo GROUP BY work_type ORDER BY sum(cost) DESC NULLS LAST) x),
      'spend_by_site', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(site,''),'Unspecified') AS label, COALESCE(round(sum(cost)),0) AS spend
          FROM wo GROUP BY 1 ORDER BY sum(cost) DESC NULLS LAST LIMIT 12) x),
      'top_tasks', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
          SELECT task AS label, count(*) AS n FROM li WHERE task IS NOT NULL AND task<>''
          GROUP BY task ORDER BY count(*) DESC LIMIT 12) x),
      'monthly_spend', (SELECT COALESCE(jsonb_agg(x ORDER BY x.m),'[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', d),'YYYY-MM') AS m, COALESCE(round(sum(cost)),0) AS spend
          FROM wo WHERE d IS NOT NULL AND d >= (current_date - interval '12 months') GROUP BY 1) x)
    )
  ) INTO result;

  UPDATE public.report_shares SET view_count = COALESCE(view_count,0)+1, last_viewed_at = now() WHERE id = t.id;
  RETURN result;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_sany_delay_candidates(p_country text DEFAULT 'KSA'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_min_days numeric DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_from date := coalesce(p_from, (date_trunc('month', now()) - interval '11 months')::date);
  v_to date := coalesce(p_to, (date_trunc('month', now()) + interval '1 month - 1 day')::date);
  v_min_hours numeric := coalesce(p_min_days, 5) * 24;
  v_rows jsonb;
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  with cand as (
    select
      wo.asset_no,
      wo.site,
      wo.work_order_no,
      wo.work_type,
      wo.work_location,
      wo.production_out_at,
      wo.production_in_at,
      round(extract(epoch from (wo.production_in_at - wo.production_out_at)) / 3600.0, 1) as downtime_hours,
      wo.breakdown_hours,
      round(coalesce(extract(epoch from (wo.production_in_at - wo.production_out_at)) / 3600.0, 0) * 43, 2) as penalty_est
    from public.work_orders wo
    where wo.organisation_id = v_org and ((wo.site)::text is null or btrim((wo.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((wo.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      and (p_country is null or wo.country = p_country) and (wo.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(wo.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and wo.production_out_at is not null
      and wo.production_in_at is not null
      and wo.production_in_at > wo.production_out_at
      and wo.production_out_at::date between v_from and v_to
      and extract(epoch from (wo.production_in_at - wo.production_out_at)) / 3600.0 > v_min_hours
    order by downtime_hours desc
    limit 500
  )
  select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) into v_rows from cand c;

  return jsonb_build_object('ok', true, 'country', p_country, 'from', v_from, 'to', v_to,
    'min_days', coalesce(p_min_days, 5), 'rate_per_hour', 43, 'candidates', v_rows);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_schedule_adherence(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(id uuid, asset_no text, site text, country text, scheduled_date date, inspection_time text, inspection_type text, priority text, raw_status text, notes text, team text, plan_ref text, grace_days integer, assigned_to uuid, assigned_name text, inspector_name text, vehicle_type text, matched_inspection_id uuid, matched_date date, matched_status text, matched_inspector text, plan_state text, days_late integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with bounds as (
    select
      coalesce(p_from, (now() at time zone 'UTC')::date - 30) as d_from,
      coalesce(p_to,   (now() at time zone 'UTC')::date + 30) as d_to,
      (now() at time zone 'UTC')::date                        as today
  ),
  fleet as materialized (
    select v.id, v.country, v.site, v.vehicle_type, upper(btrim(v.asset_no)) as asset_key
    from public.vehicle_fleet v
  ),
  plans as (
    select s.*, b.today
    from public.inspection_schedules s cross join bounds b
    where s.scheduled_date between b.d_from and b.d_to
      and (p_country is null or p_country = 'All' or s.country is null or s.country = p_country)
  )
  select
    p.id,
    p.asset_no,
    coalesce(p.site, f.site)                      as site,
    p.country,
    p.scheduled_date,
    p.inspection_time,
    p.inspection_type,
    p.priority,
    p.status                                      as raw_status,
    p.notes,
    p.team,
    p.plan_ref,
    coalesce(p.grace_days, 2)                     as grace_days,
    p.assigned_to,
    pr.full_name                                  as assigned_name,
    p.inspector_name,
    f.vehicle_type,
    m.id                                          as matched_inspection_id,
    m.inspection_date                             as matched_date,
    m.status                                      as matched_status,
    m.inspector                                   as matched_inspector,
    public.inspection_plan_state(p.scheduled_date, p.grace_days, p.status, m.status, p.today) as plan_state,
    case
      when m.inspection_date is not null then greatest(0, (m.inspection_date - p.scheduled_date))::integer
      when p.today > p.scheduled_date then (p.today - p.scheduled_date)::integer
      else 0
    end                                           as days_late
  from plans p
  left join lateral public.inspection_plan_best_match(p.id) m on true
  left join public.profiles pr on pr.id = p.assigned_to
  left join lateral (
    select f.site, f.vehicle_type
    from fleet f
    where f.asset_key = upper(btrim(p.asset_no))
    order by (f.country is not distinct from p.country) desc, f.id
    limit 1
  ) f on true
  order by p.scheduled_date asc, p.asset_no asc
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_sentry_config_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_super boolean; v_tok text; v_org text; v_region text; v_proj text; v_mail text; v_en text;
BEGIN
  SELECT COALESCE(is_super_admin,false) INTO v_super FROM public.profiles WHERE id = auth.uid();
  IF v_super IS NOT TRUE THEN RAISE EXCEPTION 'Only a super admin can view Sentry settings.' USING errcode='42501'; END IF;
  SELECT value INTO v_tok    FROM public.cron_config WHERE name='sentry_auth_token';
  SELECT value INTO v_org    FROM public.cron_config WHERE name='sentry_org';
  SELECT value INTO v_region FROM public.cron_config WHERE name='sentry_region_url';
  SELECT value INTO v_proj   FROM public.cron_config WHERE name='sentry_project';
  SELECT value INTO v_mail   FROM public.cron_config WHERE name='sentry_alert_email';
  SELECT value INTO v_en     FROM public.cron_config WHERE name='sentry_alerts_enabled';
  RETURN jsonb_build_object(
    'configured', (v_tok IS NOT NULL AND length(v_tok) > 0),
    'org', COALESCE(v_org,'shah-profile'),
    'region_url', COALESCE(v_region,'https://de.sentry.io'),
    'project', COALESCE(v_proj,''),
    'alert_email', COALESCE(v_mail,''),
    'alerts_enabled', (v_en = 'true')
  );
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_site_operating_cost(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_result jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with lines as materialized (
    select
      pc.line_cost, pc.currency, pc.country,
      pc.tyre_cost, pc.spare_cost, pc.oil_cost,
      nullif(btrim(pc.site), '')             as store_site,
      upper(btrim(coalesce(w.asset_no, ''))) as asset_no,
      nullif(btrim(f.site), '')              as asset_site
    from public.parts_consumption pc
    left join public.work_orders w
      on w.work_order_no = pc.work_order_no
    left join lateral (
      select vf.site
      from public.vehicle_fleet vf
      where upper(btrim(vf.asset_no)) = upper(btrim(w.asset_no))
        and (vf.country is null or vf.country = pc.country)
      order by (vf.country = pc.country) desc nulls last
      limit 1
    ) f on true
    where pc.organisation_id = v_org and ((f.site)::text is null or btrim((f.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((f.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      and (p_country is null or pc.country = p_country) and (pc.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and (p_from is null or pc.event_date >= p_from)
      and (p_to   is null or pc.event_date <= p_to)
  ),
  cov as (
    select count(*) lines, count(*) filter (where asset_site is not null) resolved
    from lines
  ),
  site_rows as (
    select jsonb_build_object(
             'site',     coalesce(asset_site, 'Not linked to an asset'),
             'country',  country,
             'currency', max(currency),
             'total',    round(sum(line_cost), 2),
             'tyre',     round(sum(coalesce(tyre_cost, 0)), 2),
             'spare',    round(sum(coalesce(spare_cost, 0)), 2),
             'oil',      round(sum(coalesce(oil_cost, 0)), 2),
             'lines',    count(*),
             'assets',   count(distinct nullif(asset_no, '')),
             'resolved', asset_site is not null) r,
           sum(line_cost) ord
    from lines group by asset_site, country
  ),
  store_rows as (
    select jsonb_build_object(
             'store',    coalesce(store_site, 'Not recorded'),
             'country',  country,
             'currency', max(currency),
             'total',    round(sum(line_cost), 2),
             'lines',    count(*)) r,
           sum(line_cost) ord
    from lines group by store_site, country
  )
  select jsonb_build_object(
    'ok', true,
    'coverage', (select jsonb_build_object(
        'lines', lines, 'resolved', resolved, 'unresolved', lines - resolved,
        'pct', case when lines > 0 then round(100.0 * resolved / lines, 1) end)
      from cov),
    'by_site',  coalesce((select jsonb_agg(r order by ord desc) from site_rows), '[]'::jsonb),
    'by_store', coalesce((select jsonb_agg(r order by ord desc) from store_rows), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_site_operating_cost_multi(p_countries text[] DEFAULT NULL::text[], p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org     uuid := public.app_current_org();
  v_allowed text[];
  v_refused text[] := '{}';
  v_country text;
  v_blocks  jsonb := '[]'::jsonb;
begin
  -- The parent gates on the org alone; app_is_active is added here because a
  -- wrapper may only ever be stricter than what it wraps, never looser.
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select allowed, refused into v_allowed, v_refused
    from public._scope_split_countries(p_countries);

  foreach v_country in array v_allowed loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'country',  v_country,
      'currency', public.currency_for_country(v_country),
      'result',   public.get_site_operating_cost(v_country, p_from, p_to)));
  end loop;

  return jsonb_build_object(
    'ok', true, 'multi', true, 'generated_at', now(), 'blended', false,
    'requested', to_jsonb(coalesce(p_countries, '{}'::text[])),
    'refused',   to_jsonb(v_refused),
    'countries', v_blocks);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_subscription_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org      uuid := public.app_current_org();
  v_sub      public.org_subscriptions%ROWTYPE;
  v_plan     public.subscription_plans%ROWTYPE;
  v_vehicles bigint := 0;
  v_users    bigint := 0;
  v_api_keys bigint := 0;
BEGIN
  SELECT * INTO v_sub FROM public.org_subscriptions
   WHERE organisation_id IS NOT DISTINCT FROM v_org ORDER BY created_at LIMIT 1;
  SELECT * INTO v_plan FROM public.subscription_plans WHERE code = COALESCE(v_sub.plan_code, 'trial');
  IF to_regclass('public.vehicle_fleet') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.vehicle_fleet WHERE $1 IS NULL OR organisation_id IS NULL OR organisation_id = $1'
      INTO v_vehicles USING v_org;
  END IF;
  IF to_regclass('public.profiles') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.profiles WHERE $1 IS NULL OR org_id IS NULL OR org_id = $1'
      INTO v_users USING v_org;
  END IF;
  IF to_regclass('public.api_keys') IS NOT NULL THEN
    EXECUTE 'SELECT count(*) FROM public.api_keys WHERE $1 IS NULL OR organisation_id IS NULL OR organisation_id = $1'
      INTO v_api_keys USING v_org;
  END IF;
  RETURN jsonb_build_object(
    'organisation_id', v_org,
    'subscription', CASE WHEN v_sub.id IS NULL THEN
        jsonb_build_object('plan_code','trial','status','trialing','billing_interval','monthly',
          'seats',1,'cancel_at_period_end',false,'trial_ends_at', NULL,'current_period_end', NULL,'provisioned', false)
      ELSE
        jsonb_build_object('id', v_sub.id,'plan_code', v_sub.plan_code,'status', v_sub.status,
          'billing_interval', v_sub.billing_interval,'seats', v_sub.seats,
          'cancel_at_period_end', v_sub.cancel_at_period_end,'trial_ends_at', v_sub.trial_ends_at,
          'current_period_start', v_sub.current_period_start,'current_period_end', v_sub.current_period_end,'provisioned', true)
      END,
    'plan', to_jsonb(v_plan),
    'usage', jsonb_build_object('vehicles', v_vehicles,'users', v_users,'api_keys', v_api_keys),
    'limits', jsonb_build_object('vehicles', v_plan.max_vehicles,'users', v_plan.max_users,
      'api_keys', v_plan.max_api_keys,'storage_gb', v_plan.max_storage_gb),
    'generated_at', now());
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_brand_size_mix(p_country text DEFAULT NULL::text)
 RETURNS TABLE(country text, brand text, size text, tyres bigint, active bigint, last_fitted date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select t.country,
         upper(regexp_replace(btrim(t.brand), '\s+', ' ', 'g')) as brand,
         upper(regexp_replace(t.size, '\s', '', 'g')) as size,
         count(*) as tyres,
         count(*) filter (where t.status ilike 'active') as active,
         max(t.issue_date)::date as last_fitted
  from public.tyre_records t
  where coalesce(btrim(t.brand), '') <> '' and coalesce(btrim(t.size), '') <> ''
    and (p_country is null or t.country = p_country)
  group by 1, 2, 3
  order by tyres desc, 1, 2, 3
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_consumption(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_to   date;
  v_from date;
  v_cal_days int;
  v_result jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  v_to   := least(coalesce(p_to, current_date), current_date);
  v_from := coalesce(p_from, v_to - 89);
  if v_from > v_to then
    return jsonb_build_object('ok', false, 'reason', 'empty_period');
  end if;
  v_cal_days := (v_to - v_from) + 1;

  with fitments as materialized (
    select
      t.issue_date,
      upper(btrim(coalesce(t.asset_no, ''))) as asset_no,
      t.country,
      t.created_at::date                     as upload_day,
      coalesce(nullif(btrim(f.site), ''), nullif(btrim(t.site), ''))                 as site,
      coalesce(nullif(btrim(f.vehicle_type), ''), nullif(btrim(t.vehicle_type), '')) as vehicle_type,
      greatest(coalesce(t.qty, 1), 1) as tyres,
      case when not public.tyre_serial_is_strong(t.serial_no) then 'unidentified'
           when pv.asset_no is null then 'new'
           when pv.asset_no = upper(regexp_replace(coalesce(t.asset_no, ''), '\s+', '', 'g')) then 'refit_same'
           else 'transferred' end as kind
    from public.tyre_records t
    left join lateral (
      select vf.site, vf.vehicle_type
      from public.vehicle_fleet vf
      where vf.organisation_id = t.organisation_id
        and vf.asset_no = upper(btrim(coalesce(t.asset_no, '')))
        and (vf.country is null or vf.country = t.country)
      order by (vf.country = t.country) desc nulls last
      limit 1
    ) f on true
    left join lateral (
      select upper(regexp_replace(coalesce(e.asset_no, ''), '\s+', '', 'g')) as asset_no
      from public.tyre_records e
      where public.tyre_serial_is_strong(t.serial_no)
        and e.organisation_id = t.organisation_id
        and e.country is not distinct from t.country
        and upper(btrim(e.serial_no)) = upper(btrim(t.serial_no))
        and e.id <> t.id
        and (coalesce(e.issue_date, e.fitment_date) < t.issue_date
             or (coalesce(e.issue_date, e.fitment_date) = t.issue_date and (e.created_at, e.id) < (t.created_at, t.id)))
      order by coalesce(e.issue_date, e.fitment_date) desc, e.created_at desc, e.id desc
      limit 1
    ) pv on true
    where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and t.issue_date >= v_from
      and t.issue_date <= v_to
  ),
  undated as (
    select count(*) n from public.tyre_records t
    where t.organisation_id = v_org and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      and (p_country is null or t.country = p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and t.issue_date is null
  ),
  by_day as (
    select issue_date d, count(*) n from fitments group by 1
  ),
  totals as (
    select
      (select count(*) from fitments)                          as fitments,
      (select count(*) from by_day)                            as active_days,
      (select count(distinct asset_no) from fitments
         where asset_no <> '')                                 as assets,
      (select count(distinct upload_day) from fitments)        as upload_days,
      (select count(distinct issue_date) from fitments)        as fit_days,
      (select count(*) from fitments
         where upload_day = issue_date)                        as same_day
  ),
  months as (
    select
      to_char(date_trunc('month', d), 'YYYY-MM') as m,
      sum(n)::int   as n,
      count(*)::int as active_days,
      (least((date_trunc('month', d) + interval '1 month - 1 day')::date, v_to)
       - greatest(date_trunc('month', d)::date, v_from) + 1)::int as cal_days
    from by_day
    group by date_trunc('month', d)
  ),
  kind_rows as (
    select kind, count(*)::int as fitments, sum(tyres)::int as tyres from fitments group by kind
  ),
  weeks as (
    select (issue_date - extract(dow from issue_date)::int) as wk,
           count(*)::int as fitments,
           (sum(tyres) filter (where kind = 'new'))::int as new_tyres,
           (sum(tyres) filter (where kind in ('refit_same', 'transferred')))::int as reused,
           (sum(tyres) filter (where kind = 'unidentified'))::int as unidentified
    from fitments group by 1
  ),
  month_kinds as (
    select to_char(date_trunc('month', issue_date), 'YYYY-MM') as m,
           (sum(tyres) filter (where kind = 'new'))::int as new_tyres,
           (sum(tyres) filter (where kind in ('refit_same', 'transferred')))::int as reused,
           (sum(tyres) filter (where kind = 'unidentified'))::int as unidentified
    from fitments group by 1
  ),
  site_rows as (
    select coalesce(site, 'Not linked to a site') as k, count(*)::int n,
           count(distinct asset_no) filter (where asset_no <> '')::int assets,
           (site is not null) as resolved
    from fitments group by site
  ),
  class_rows as (
    select coalesce(vehicle_type, 'Class not recorded') as k, count(*)::int n,
           count(distinct asset_no) filter (where asset_no <> '')::int assets,
           (vehicle_type is not null) as resolved
    from fitments group by vehicle_type
  )
  select jsonb_build_object(
    'ok', true,
    'from', v_from,
    'to', v_to,
    'country', p_country,
    'calendar_days', v_cal_days,
    'fitments',    (select fitments from totals),
    'active_days', (select active_days from totals),
    'assets',      (select assets from totals),
    'undated',     (select n from undated),
    'batch_check', jsonb_build_object(
        'upload_days',  (select upload_days from totals),
        'fit_days',     (select fit_days from totals),
        'same_day',     (select same_day from totals)),
    'by_day', coalesce((select jsonb_agg(jsonb_build_object('d', d, 'n', n) order by d)
                        from by_day), '[]'::jsonb),
    'by_month', coalesce((select jsonb_agg(jsonb_build_object(
                            'm', m, 'n', n, 'active_days', active_days, 'cal_days', cal_days)
                          order by m) from months), '[]'::jsonb),
    'by_site', coalesce((select jsonb_agg(jsonb_build_object(
                            'k', k, 'n', n, 'assets', assets, 'resolved', resolved)
                          order by n desc) from site_rows), '[]'::jsonb),
    'by_class', coalesce((select jsonb_agg(jsonb_build_object(
                            'k', k, 'n', n, 'assets', assets, 'resolved', resolved)
                          order by n desc) from class_rows), '[]'::jsonb),
    'tyres', (select coalesce(sum(tyres), 0)::int from fitments),
    'new_tyres', (select coalesce(sum(tyres) filter (where kind = 'new'), 0)::int from fitments),
    'by_kind', coalesce((select jsonb_object_agg(kind, jsonb_build_object('fitments', fitments, 'tyres', tyres)) from kind_rows), '{}'::jsonb),
    'by_week', coalesce((select jsonb_agg(jsonb_build_object('week_start', wk, 'week_end', wk + 6,
        'fitments', fitments, 'new_tyres', coalesce(new_tyres, 0), 'reused', coalesce(reused, 0),
        'unidentified', coalesce(unidentified, 0)) order by wk) from weeks), '[]'::jsonb),
    'by_month_kind', coalesce((select jsonb_agg(jsonb_build_object('m', m, 'new_tyres', coalesce(new_tyres, 0),
        'reused', coalesce(reused, 0), 'unidentified', coalesce(unidentified, 0)) order by m) from month_kinds), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_consumption_v2(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
 SET enable_nestloop TO 'off'
AS $function$
declare
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_site text := nullif(upper(btrim(coalesce(p_site, ''))), '');
  v_to date;
  v_from date;
  v_qtd date;
  v_ytd date;
  v_base date;
  v_result jsonb;
  v_org uuid := public.app_current_org();
begin
  if v_org is null then return jsonb_build_object('ok', false, 'reason', 'no_org'); end if;
  if v_country = 'All' then v_country := null; end if;
  if v_country is not null and public.app_can_see_country(v_country) is false then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  v_to := least(coalesce(p_to, current_date), current_date);
  v_from := coalesce(p_from, v_to - 89);
  if v_from > v_to then
    return jsonb_build_object('ok', false, 'reason', 'empty_period');
  end if;
  v_qtd := date_trunc('quarter', v_to)::date;
  v_ytd := date_trunc('year', v_to)::date;
  v_base := (least(v_from, v_ytd) - interval '1 year')::date;
  with periods(name, f, t) as (
    values ('selected',      v_from, v_to),
           ('selected_prev', (v_from - interval '1 year')::date, (v_to - interval '1 year')::date),
           ('qtd',           v_qtd, v_to),
           ('qtd_prev',      (v_qtd - interval '1 year')::date, (v_to - interval '1 year')::date),
           ('ytd',           v_ytd, v_to),
           ('ytd_prev',      (v_ytd - interval '1 year')::date, (v_to - interval '1 year')::date)
  ),
  fleet as materialized (
    select distinct on (v.organisation_id, upper(btrim(v.asset_no)), v.country)
           v.organisation_id, upper(btrim(v.asset_no)) as asset, v.country, v.site, v.vehicle_type
    from public.vehicle_fleet v
    where v.asset_no is not null and v.organisation_id = v_org
    order by v.organisation_id, upper(btrim(v.asset_no)), v.country, v.id
  ),
  fl as (
    select l.id, l.country, l.tyre_key, l.strong, l.fit_date, l.removal_date, l.status,
           upper(regexp_replace(coalesce(l.asset_no, ''), '\s+', '', 'g')) as asset,
           upper(btrim(coalesce(l.position, ''))) as wheel,
           upper(btrim(coalesce(l.serial_no, ''))) as serial,
           greatest(coalesce(l.qty, 1), 1)::int as tyres,
           nullif(upper(btrim(coalesce(l.brand, ''))), '') as brand,
           nullif(upper(regexp_replace(coalesce(l.size, ''), '\s+', '', 'g')), '') as size,
           coalesce(nullif(btrim(coalesce(fc.vehicle_type, fn.vehicle_type)), ''), nullif(btrim(l.vehicle_type), '')) as vehicle_type,
           coalesce(nullif(upper(btrim(coalesce(fc.site, fn.site))), ''), nullif(upper(btrim(l.site)), '')) as site,
           nullif(btrim(tr.supplier), '') as supplier,
           lag(upper(regexp_replace(coalesce(l.asset_no, ''), '\s+', '', 'g'))) over w as prev_asset,
           lag(upper(btrim(coalesce(l.position, '')))) over w as prev_wheel,
           lag(l.fit_date) over w as prev_date,
           row_number() over w as seq
    from public.v_tyre_lifetime_fitments l
    join public.tyre_records tr on tr.id = l.id
    left join fleet fc on fc.organisation_id = l.organisation_id
      and fc.asset = upper(btrim(coalesce(l.asset_no, ''))) and fc.country = l.country
    left join fleet fn on fn.organisation_id = l.organisation_id
      and fn.asset = upper(btrim(coalesce(l.asset_no, ''))) and fn.country is null
    where l.organisation_id = v_org
      and (v_country is null or l.country = v_country)
    window w as (partition by l.tyre_key order by l.fit_date nulls first, l.id)
  ),
  wk as (
    select fl.*,
           case when not strong then coalesce(country, '') || '|' || asset || '|' || wheel || '|' || coalesce(fit_date::text, '') || '|' || serial end as weak_key
    from fl
    where (v_site is null or fl.site = v_site)
      and (fl.fit_date >= v_base or fl.removal_date >= v_base)
  ),
  ev as (
    select wk.*,
           case when not strong and row_number() over (partition by weak_key order by id) > 1 then 'duplicate_entry'
                when not strong then 'unidentified'
                when seq = 1 then 'new'
                when prev_asset = asset and prev_wheel = wheel and prev_date is not distinct from fit_date then 'duplicate_entry'
                when prev_asset = asset and prev_wheel <> wheel then 'rotation'
                when prev_asset = asset then 'reinstalled'
                else 'transferred' end as kind
    from wk
  ),
  weak as (
    select weak_key, fit_date, max(tyres) as tyres from ev where weak_key is not null group by 1, 2
  ),
  rj as (
    select returned_at as d from public.retread_jobs
    where returned_at is not null and organisation_id = v_org and (v_country is null or country = v_country)
      and (v_site is null or upper(btrim(site)) = v_site)
    union all
    select event_date from public.tyre_service_events
    where event_type ilike '%retread%' and event_date is not null and organisation_id = v_org
      and (v_country is null or country = v_country) and (v_site is null or upper(btrim(site)) = v_site)
  ),
  wr as (
    select removal_date as d from public.warranty_claims
    where removal_date is not null and organisation_id = v_org and coalesce(claim_status, '') not ilike 'reject%'
      and (v_country is null or country = v_country) and (v_site is null or upper(btrim(site)) = v_site)
    union all
    select ev.fit_date from public.tyre_price_backfill_log b join ev on ev.id = b.tyre_id
    where b.source = 'warranty' and coalesce(b.new_cost, 0) = 0
  ),
  summ as (
    select p.name, p.f, p.t,
      coalesce(sum(e.tyres) filter (where e.fit_date between p.f and p.t and e.kind <> 'duplicate_entry'), 0) as installations,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind <> 'duplicate_entry') as installation_rows,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind = 'new') as new_fitments,
      coalesce(sum(e.tyres) filter (where e.fit_date between p.f and p.t and e.kind in ('rotation', 'reinstalled', 'transferred')), 0) as reused,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind = 'rotation') as rotations,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind = 'reinstalled') as reinstalled,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind = 'transferred') as transfers,
      count(*) filter (where e.fit_date between p.f and p.t and e.kind = 'duplicate_entry') as duplicate_entries,
      coalesce(sum(e.tyres) filter (where e.fit_date between p.f and p.t and e.kind = 'unidentified'), 0) as unidentified_rows_tyres,
      count(*) filter (where e.removal_date between p.f and p.t) as removal_events,
      count(distinct coalesce(e.weak_key, e.tyre_key)) filter (where e.removal_date between p.f and p.t) as removed_tyres,
      count(distinct coalesce(e.weak_key, e.tyre_key)) filter (where e.removal_date between p.f and p.t and e.status ilike 'scrap%') as scrapped
    from periods p cross join ev e
    group by p.name, p.f, p.t
  ),
  summ2 as (
    select s.*,
      (select coalesce(sum(w.tyres), 0) from weak w where w.fit_date between s.f and s.t) as unidentified_physical,
      (select count(*) from rj where rj.d between s.f and s.t) as retreaded,
      (select count(*) from wr where wr.d between s.f and s.t) as warranty_replacements
    from summ s
  ),
  dims as (
    select d.dim, coalesce(d.k, 'Not recorded') as k, (d.k is not null) as resolved,
      coalesce(sum(e.tyres) filter (where e.fit_date between v_from and v_to and e.kind <> 'duplicate_entry'), 0) as installations,
      count(*) filter (where e.fit_date between v_from and v_to and e.kind = 'new') as physical_new,
      coalesce(sum(e.tyres) filter (where e.fit_date between v_from and v_to and e.kind in ('rotation', 'reinstalled', 'transferred')), 0) as reused,
      count(distinct coalesce(e.weak_key, e.tyre_key)) filter (where e.removal_date between v_from and v_to) as removed_tyres
    from ev e
    cross join lateral (values ('site', e.site), ('brand', e.brand), ('size', e.size),
                               ('supplier', e.supplier), ('vehicle_type', e.vehicle_type)) d(dim, k)
    where (e.fit_date between v_from and v_to) or (e.removal_date between v_from and v_to)
    group by d.dim, coalesce(d.k, 'Not recorded'), (d.k is not null)
  )
  select jsonb_build_object(
    'ok', true, 'version', 2, 'country', v_country, 'site', v_site,
    'from', v_from, 'to', v_to,
    'periods', (select jsonb_object_agg(name, jsonb_build_object(
        'from', f, 'to', t,
        'installations', installations, 'installation_rows', installation_rows,
        'physical_consumed', new_fitments + unidentified_physical,
        'physical_new', new_fitments, 'physical_unidentified', unidentified_physical,
        'new_fitments', new_fitments, 'reused', reused, 'rotations', rotations,
        'reinstalled', reinstalled, 'transfers', transfers,
        'duplicate_entries', duplicate_entries,
        'unidentified_installations', unidentified_rows_tyres,
        'removal_events', removal_events, 'removed', removed_tyres, 'scrapped', scrapped,
        'retreaded', retreaded, 'warranty_replacements', warranty_replacements)) from summ2),
    'breakdowns', coalesce((select jsonb_object_agg(dim, rows) from (
        select dim, jsonb_agg(jsonb_build_object('k', k, 'resolved', resolved,
          'installations', installations, 'physical_new', physical_new,
          'reused', reused, 'removed', removed_tyres) order by installations desc, k) as rows
        from dims group by dim) x), '{}'::jsonb),
    'undated_fitments', (select count(*) from fl where fl.fit_date is null
                         and (v_site is null or fl.site = v_site)),
    'undated_scrapped', (select count(distinct tyre_key) from fl where fl.status ilike 'scrap%'
                         and fl.removal_date is null and (v_site is null or fl.site = v_site)),
    'supplier_recorded', (select count(*) from fl where fl.supplier is not null)
  ) into v_result;
  return v_result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_cost_by_asset(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(asset_code text, tyre_cost numeric, lines bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT asset_code,
         round(sum(tyre_cost))::numeric AS tyre_cost,
         count(*)::bigint AS lines
  FROM public.parts_consumption
  WHERE organisation_id = public.app_current_org() and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    AND public.app_is_active()
    AND cost_category = 'tyre'
    AND (p_country IS NULL OR country = p_country) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    AND (p_from IS NULL OR event_date >= p_from)
    AND (p_to   IS NULL OR event_date <= p_to)
    AND asset_code IS NOT NULL
  GROUP BY asset_code
  HAVING round(sum(tyre_cost)) <> 0
  ORDER BY sum(tyre_cost) DESC, asset_code;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_evidence_audit(p_country text DEFAULT NULL::text, p_from date DEFAULT '2025-01-01'::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_from date := coalesce(p_from, date '2025-01-01');
  v_to date := least(coalesce(p_to, current_date), current_date);
  v_out jsonb;
begin
  if v_country = 'All' then v_country := null; end if;

  with e as (
    select * from public.v_tyre_fitment_evidence
    where v_country is null or country = v_country
  ),
  baseline as (
    select coalesce(jsonb_object_agg(country, b), '{}'::jsonb) j from (
      select country, jsonb_build_object(
        'legacy_fitments', count(*) filter (where era = 'legacy'),
        'legacy_active', count(*) filter (where era = 'legacy' and active),
        'modern_fitments', count(*) filter (where era = 'modern'),
        'undated_fitments', count(*) filter (where era = 'undated'),
        'modern_blank_serial', count(*) filter (where era = 'modern' and coalesce(btrim(serial_no), '') = ''),
        'modern_serial_not_verified', count(*) filter (where era = 'modern' and not strong),
        'modern_fitment_km_missing', count(*) filter (where era = 'modern' and km_at_fitment is null),
        'modern_removed_no_removal_km', count(*) filter (where era = 'modern' and not active and km_at_removal is null)
      ) b
      from e group by country
    ) x
  ),
  classes as (
    select coalesce(jsonb_object_agg(country, c), '{}'::jsonb) j from (
      select country, jsonb_object_agg(evidence_class, n) c from (
        select country, evidence_class, count(*) n from e
        where era = 'modern' and fit_date between v_from and v_to
        group by 1, 2
      ) y group by country
    ) x
  ),
  flags as (
    select coalesce(jsonb_object_agg(country, c), '{}'::jsonb) j from (
      select country, jsonb_object_agg(reason, n) c from (
        select country, reason, count(*) n
        from e, unnest(reasons) reason
        where era = 'modern' and fit_date between v_from and v_to
        group by 1, 2
      ) y group by country
    ) x
  ),
  legacy as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', l.id, 'country', l.country, 'asset_no', l.asset_no, 'position', l."position",
      'serial_no', l.serial_no, 'fit_date', l.fit_date, 'km_at_fitment', l.km_at_fitment,
      'cost_per_tyre', l.cost_per_tyre,
      'next_wheel_fit_date', nw.fit_date, 'next_wheel_serial', nw.serial_no,
      'serial_next_fit_date', ns.fit_date, 'serial_next_asset', ns.asset_no, 'serial_next_position', ns."position",
      'finding', case when ns.id is not null then 'serial_refitted_later'
                      when nw.id is not null then 'superseded_on_wheel'
                      else 'no_later_evidence' end,
      'proposed_action', case
        when ns.id is not null or nw.id is not null then 'close_fitment_on_or_before_next_fit_date'
        else 'keep_original_mark_current_status_unverified' end
    ) order by l.country, l.asset_no, l."position"), '[]'::jsonb) j
    from e l
    left join lateral (
      select n.id, n.fit_date, n.serial_no from e n
      where n.country = l.country and n.id <> l.id
        and upper(btrim(n.asset_no)) = upper(btrim(l.asset_no))
        and upper(btrim(coalesce(n."position", ''))) = upper(btrim(coalesce(l."position", '')))
        and n.fit_date > l.fit_date
      order by n.fit_date, n.id limit 1) nw on true
    left join lateral (
      select n.id, n.fit_date, n.asset_no, n."position" from e n
      where l.strong and n.tyre_key = l.tyre_key and n.id <> l.id and n.fit_date > l.fit_date
      order by n.fit_date, n.id limit 1) ns on true
    where l.era = 'legacy' and l.active
  ),
  fit_m as (
    select country, date_trunc('month', fit_date)::date mo,
      count(*) fitments,
      count(*) filter (where strong and fit_seq = 1) new_physical,
      count(*) filter (where strong and fit_seq > 1) refits,
      count(*) filter (where not strong) unidentified,
      count(*) filter (where evidence_class = 'DUPLICATE') duplicate_copies
    from e where era = 'modern' and fit_date between v_from and v_to
    group by 1, 2
  ),
  rem_m as (
    select country, date_trunc('month', removal_date)::date mo,
      count(*) removals,
      count(*) filter (where status ilike 'scrap%') scrapped
    from e where removal_date between v_from and v_to
    group by 1, 2
  ),
  grid_m as (
    select country, date_trunc('month', event_date)::date mo,
      sum(greatest(coalesce(public._to_num(qty::text), 1), 0)) issued_qty,
      sum(tyre_cost) tyre_cost,
      max(currency) currency
    from public.parts_consumption
    where tyre_cost > 0 and event_date between v_from and v_to
      and (v_country is null or country = v_country)
    group by 1, 2
  ),
  monthly as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'country', k.country, 'month', k.mo,
      'fitments', coalesce(fm.fitments, 0), 'new_physical', coalesce(fm.new_physical, 0),
      'refits', coalesce(fm.refits, 0), 'unidentified', coalesce(fm.unidentified, 0),
      'duplicate_copies', coalesce(fm.duplicate_copies, 0),
      'removals', coalesce(rm.removals, 0), 'scrapped', coalesce(rm.scrapped, 0),
      'grid_issued_qty', gm.issued_qty, 'grid_tyre_cost', round(gm.tyre_cost, 2), 'currency', gm.currency
    ) order by k.country, k.mo), '[]'::jsonb) j
    from (
      select country, mo from fit_m union select country, mo from rem_m union select country, mo from grid_m
    ) k
    left join fit_m fm on fm.country = k.country and fm.mo = k.mo
    left join rem_m rm on rm.country = k.country and rm.mo = k.mo
    left join grid_m gm on gm.country = k.country and gm.mo = k.mo
  )
  select jsonb_build_object(
    'ok', true,
    'from', v_from, 'to', v_to, 'country', v_country,
    'generated_at', now(),
    'baseline', (select j from baseline),
    'classes', (select j from classes),
    'flags', (select j from flags),
    'legacy_active', (select j from legacy),
    'monthly', (select j from monthly)
  ) into v_out;

  return v_out;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_exceptions(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
with act as (
  select t.id, t.country, upper(regexp_replace(coalesce(t.asset_no, ''), '\s+', '', 'g')) asset,
         upper(btrim(coalesce(t.tyre_position, t.position, ''))) pos, upper(btrim(t.serial_no)) serial,
         coalesce(t.issue_date, t.fitment_date) d, t.cost_per_tyre
  from public.tyre_records t
  where public.tyre_status_is_active(t.status) and (p_country is null or t.country = p_country)
), same_vehicle as (
  select country, asset, serial, count(*) n, count(distinct d) dates,
         jsonb_agg(jsonb_build_object('id', id, 'position', pos, 'date', d, 'cost', cost_per_tyre) order by d nulls first, pos) rows
  from act where public.tyre_serial_is_strong(serial)
  group by 1, 2, 3 having count(*) > 1
), priced_twice as (
  select country, upper(btrim(serial_no)) serial,
         jsonb_agg(jsonb_build_object('id', id, 'asset', asset_no, 'date', issue_date, 'cost', cost_per_tyre)) rows
  from public.tyre_records
  where public.tyre_serial_is_strong(serial_no) and coalesce(cost_per_tyre, 0) > 0
    and (p_country is null or country = p_country)
  group by 1, 2 having count(*) > 1
), weak as (
  select country, serial, count(*) n from act
  where serial is not null and serial <> '' and not public.tyre_serial_is_strong(serial)
  group by 1, 2
), remark as (
  select country, serial, count(*) n from act
  where public.tyre_serial_is_strong(serial) and serial ~ '[\s(]'
  group by 1, 2
), reviews as (
  select count(*) n from public.stg_monthly_tyres_audit a
  where a.action = 'rejected' and a.reason like 'replacement_needs_review:%' and a.resolved_at is null
    and (p_country is null or a.country = p_country)
)
select jsonb_build_object(
  'counts', jsonb_build_object(
    'rotation_not_closed', (select count(*) from same_vehicle where dates > 1),
    'same_day_double_entry', (select count(*) from same_vehicle where dates <= 1),
    'serial_priced_twice', (select count(*) from priced_twice),
    'weak_serial_active', (select coalesce(sum(n), 0) from weak),
    'serial_with_remark', (select coalesce(sum(n), 0) from remark),
    'import_reviews_open', (select n from reviews)),
  'same_vehicle', (select coalesce(jsonb_agg(jsonb_build_object('country', country, 'asset', asset, 'serial', serial,
      'kind', case when dates > 1 then 'rotation_not_closed' else 'same_day_double_entry' end, 'rows', rows)
      order by country, asset), '[]'::jsonb) from same_vehicle),
  'priced_twice', (select coalesce(jsonb_agg(jsonb_build_object('country', country, 'serial', serial, 'rows', rows)), '[]'::jsonb) from priced_twice),
  'weak_serials', (select coalesce(jsonb_agg(jsonb_build_object('country', country, 'serial', serial, 'rows', n) order by n desc), '[]'::jsonb)
                   from (select * from weak order by n desc limit 300) w),
  'serials_with_remark', (select coalesce(jsonb_agg(jsonb_build_object('country', country, 'serial', serial, 'rows', n)), '[]'::jsonb)
                   from (select * from remark limit 300) r));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_exceptions_v2(p_country text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_rot jsonb; v_rot_ok boolean := false;
  v_limit int := least(greatest(coalesce(p_limit, 100), 1), 1000);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_out jsonb;
begin
  if p_status is not null and p_status not in ('open', 'accepted', 'rejected', 'deferred') then
    raise exception 'Unknown review status' using errcode = '22023';
  end if;
  if p_kind is null or p_kind = 'rotation_not_closed' then
    begin
      v_rot := public.tyre_close_rotations(true, p_country);
      v_rot_ok := true;
    exception when others then
      v_rot := null; v_rot_ok := false;
    end;
  end if;
  with ex as (
    select * from public._tyre_exception_rows(p_country, case when p_kind = 'rotation_not_closed' then '__none__' else p_kind end)
    union all
    select 'rotation_not_closed|' || upper(btrim(coalesce(x->>'country', ''))) || '|' || upper(regexp_replace(coalesce(x->>'asset', ''), '\s+', '', 'g'))
             || '|' || upper(btrim(coalesce(x->>'serial', ''))) || '|' || coalesce(x->>'from_position', ''),
      'rotation_not_closed', x->>'country', '{}'::uuid[], x->>'serial', x->>'asset', x->>'from_position',
      'Tyre moved to ' || coalesce(x->>'to_position', '?') || ' on ' || coalesce(x->>'rotated_on', '?') || ' but is still open on ' || coalesce(x->>'from_position', '?'),
      'Rotation closer would close the earlier position (dry run only; a person runs it)',
      null::numeric, null::numeric, x
    from jsonb_array_elements(case when v_rot_ok then coalesce(v_rot->'rows', '[]'::jsonb) else '[]'::jsonb end) x
  ),
  prot as materialized (
    select r.exception_key, r.record_ids from public.tyre_exception_refs r where r.ref_kind = 'protected'
  ), prot_ids as materialized (
    select distinct u.id from prot, unnest(prot.record_ids) as u(id)
  ), rv as materialized (
    select v.exception_key, v.status, v.note, v.reviewed_by_name, v.reviewed_at from public.tyre_exception_reviews v
  ), cur as materialized (
    select x.country, public.currency_for_country(x.country) as currency from (select distinct ex.country from ex) x
  ), j as (
    select ex.*, coalesce(rv.status, 'open') as status, rv.note, rv.reviewed_by_name, rv.reviewed_at,
           (pk.exception_key is not null
             or (ex.kind in ('uncertain_previous_tyre', 'price_assigned_twice')
                 and exists (select 1 from unnest(ex.record_ids) as e(id) join prot_ids pi on pi.id = e.id))) as protected,
           cur.currency
    from ex
    left join rv on rv.exception_key = ex.exception_key
    left join prot pk on pk.exception_key = ex.exception_key
    left join cur on cur.country is not distinct from ex.country
  ), f as (
    select * from j where (p_kind is null or j.kind = p_kind) and (p_status is null or j.status = p_status)
  )
  select jsonb_build_object(
    'counts', (select coalesce(jsonb_agg(c order by c.kind, c.country), '[]'::jsonb) from (
        select kind, country, count(*) as n,
               count(*) filter (where status = 'open') as open, count(*) filter (where status = 'accepted') as accepted,
               count(*) filter (where status = 'rejected') as rejected, count(*) filter (where status = 'deferred') as deferred,
               count(*) filter (where protected) as protected
        from j group by kind, country) c),
    'total', (select count(*) from f),
    'rotation_available', v_rot_ok or (p_kind is not null and p_kind <> 'rotation_not_closed'),
    'rows', (select coalesce(jsonb_agg(to_jsonb(p) order by p.kind, p.country, p.exception_key), '[]'::jsonb) from (
        select * from f order by f.kind, f.country, f.exception_key limit v_limit offset v_offset) p),
    'limit', v_limit, 'offset', v_offset)
  into v_out;
  return v_out;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_filter_options(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select jsonb_build_object(
    'sites', coalesce(
      (select jsonb_agg(v order by v)
         from (select distinct t.site as v
                 from public.tyre_records t
                where t.site is not null
                  and btrim(t.site) <> ''
                  and (p_country is null or p_country = 'All'
                       or t.country = p_country or t.country is null)
              ) s),
      '[]'::jsonb),
    'brands', coalesce(
      (select jsonb_agg(v order by v)
         from (select distinct t.brand as v
                 from public.tyre_records t
                where t.brand is not null
                  and btrim(t.brand) <> ''
                  and (p_country is null or p_country = 'All'
                       or t.country = p_country or t.country is null)
              ) b),
      '[]'::jsonb)
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_gap_overview(p_country text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare v_org uuid := public.app_current_org(); v_total int; v_bb int; v_bs int; v_br int; v_rb int; v_rs int;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  select count(*),
         count(*) filter (where brand is null or btrim(brand)=''),
         count(*) filter (where size is null or btrim(size)=''),
         count(*) filter (where removal_reason is null or btrim(removal_reason)='')
    into v_total, v_bb, v_bs, v_br
  from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));

  select count(distinct upper(btrim(t.serial_no))) into v_rb
  from public.tyre_records t
  where t.organisation_id=v_org and (p_country is null or t.country=p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    and (t.brand is null or btrim(t.brand)='') and t.serial_no is not null and btrim(t.serial_no)<>''
    and (exists (select 1 from public.tyre_records u where u.organisation_id=v_org and upper(btrim(u.serial_no))=upper(btrim(t.serial_no)) and u.brand is not null and btrim(u.brand)<>'')
      or exists (select 1 from public.ksa_country_upload_template_staging m where upper(btrim(m.tyre_brand)) not in ('NULL','N/A','NA','-','NONE','') and (upper(btrim(m.srno))=upper(btrim(t.serial_no)) or upper(btrim(m.old_serialno))=upper(btrim(t.serial_no)))));

  select count(distinct upper(btrim(t.serial_no))) into v_rs
  from public.tyre_records t
  where t.organisation_id=v_org and (p_country is null or t.country=p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    and (t.size is null or btrim(t.size)='') and t.serial_no is not null and btrim(t.serial_no)<>''
    and (exists (select 1 from public.tyre_records u where u.organisation_id=v_org and upper(btrim(u.serial_no))=upper(btrim(t.serial_no)) and u.size is not null and btrim(u.size)<>'')
      or exists (select 1 from public.ksa_country_upload_template_staging m where upper(btrim(m.tire_size)) not in ('NULL','N/A','NA','-','NONE','') and (upper(btrim(m.srno))=upper(btrim(t.serial_no)) or upper(btrim(m.old_serialno))=upper(btrim(t.serial_no)))));

  return json_build_object('ok',true,'total',v_total,'fields', json_build_array(
    json_build_object('field','brand','label','Brand','total',v_total,'blank',v_bb,'recoverable',v_rb),
    json_build_object('field','size','label','Size','total',v_total,'blank',v_bs,'recoverable',v_rs),
    json_build_object('field','removal_reason','label','Removal reason','total',v_total,'blank',v_br,'recoverable',null)
  ));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_lifecycle_event_counts(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with e as (
    select country, event_type, ambiguous_reason from public.v_tyre_lifecycle_events
    where p_country is null or country = p_country
  ), by_type as (
    select country, event_type, count(*) n from e group by 1, 2
  ), by_reason as (
    select country, ambiguous_reason, count(*) n from e where event_type = 'AMBIGUOUS' group by 1, 2
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'country', c.country,
           'by_type', (select jsonb_object_agg(t.event_type, t.n) from by_type t where t.country is not distinct from c.country),
           'ambiguous', coalesce((select jsonb_object_agg(r.ambiguous_reason, r.n) from by_reason r where r.country is not distinct from c.country), '{}'::jsonb)
         ) order by c.country), '[]'::jsonb)
  from (select distinct country from e) c
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_lifetime_cpk(p_country text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
with base as materialized (
  select * from public.v_tyre_lifetime
),
t as (
  select l.*,
         case when not l.is_active
                   and (p_from is null or coalesce(l.last_removal_date, l.last_fit_date) >= p_from)
                   and (p_to is null or coalesce(l.last_removal_date, l.last_fit_date) <= p_to) then 'final'
              when l.is_active and (p_to is null or l.first_fit_date is null or l.first_fit_date <= p_to) then 'provisional'
         end as bucket,
         (coalesce(l.purchase_cost, 0) > 0 and coalesce(l.km_known, 0) > 0) as measurable
  from base l
  where (p_country is null or l.country = p_country)
    and (p_site is null or upper(btrim(l.site)) = upper(btrim(p_site)))
),
b as (select * from t where bucket is not null),
stats as (
  select country, bucket,
         count(*) as tyres, sum(qty) as physical_tyres,
         count(*) filter (where measurable) as measurable,
         sum(purchase_cost * qty) filter (where measurable) as purchase_cost,
         sum(full_cost * qty) filter (where measurable) as full_cost,
         sum(km_known * qty) filter (where measurable) as km,
         sum(repair_cost) as repair_cost, sum(retread_cost) as retread_cost, sum(recovery) as recovery,
         jsonb_build_object(
           'complete', count(*) filter (where km_coverage = 'complete'),
           'partial',  count(*) filter (where km_coverage = 'partial'),
           'none',     count(*) filter (where km_coverage = 'none')) as km_coverage,
         jsonb_build_object(
           'ACTUAL', count(*) filter (where purchase_cost_status = 'ACTUAL'),
           'ESTIMATED', count(*) filter (where purchase_cost_status = 'ESTIMATED'),
           'CONFIRMED_ZERO', count(*) filter (where purchase_cost_status = 'CONFIRMED_ZERO'),
           'DISPUTED', count(*) filter (where purchase_cost_status = 'DISPUTED'),
           'MISSING', count(*) filter (where purchase_cost_status = 'MISSING')) as cost_status,
         sum(purchase_cost * qty) filter (where measurable and purchase_cost_status = 'ESTIMATED') as estimated_cost_in_cpk,
         count(*) filter (where fitments > 1) as refitted_tyres,
         count(*) filter (where overlapping_fitments > 0) as tyres_with_overlap
  from b group by country, bucket
),
grp as (
  select country, dim, key,
         count(*) as tyres,
         sum(km_known * qty) as km,
         case when sum(km_known * qty) > 0 then round(sum(purchase_cost * qty) / sum(km_known * qty), 6) end as cpk_purchase,
         case when sum(km_known * qty) > 0 then round(sum(full_cost * qty) / sum(km_known * qty), 6) end as cpk_full
  from (
    select country, 'brand' as dim, coalesce(nullif(upper(btrim(brand)), ''), '(none)') as key, qty, km_known, purchase_cost, full_cost from b where bucket = 'final' and measurable
    union all
    select country, 'size', coalesce(nullif(upper(regexp_replace(size, '\s+', '', 'g')), ''), '(none)'), qty, km_known, purchase_cost, full_cost from b where bucket = 'final' and measurable
    union all
    select country, 'vehicle_type', coalesce(nullif(upper(btrim(vehicle_type)), ''), '(none)'), qty, km_known, purchase_cost, full_cost from b where bucket = 'final' and measurable
  ) x group by country, dim, key
),
unlinked as (
  select country, count(*) as lines, round(sum(tyre_cost), 2) as amount
  from public.parts_consumption
  where coalesce(tyre_cost, 0) > 0 and item_description ~* '(repair|retread|re-tread|resol|vulcan)'
    and (p_country is null or country = p_country)
    and (p_from is null or event_date >= p_from) and (p_to is null or event_date <= p_to)
  group by country
)
select jsonb_build_object(
  'definition', jsonb_build_object(
    'kpi', 'physical_tyre_lifetime_cpk',
    'purchase_cpk', 'first verified purchase price of each physical tyre / validated cumulative km of all its fitments',
    'full_cpk', '(purchase + linked repairs + linked retreads - issued warranty credit) / validated cumulative km',
    'weighting', 'total cost / total km over measurable tyres (T8); never an average of ratios',
    'final', 'tyre no longer active, last fitment ended in the window',
    'provisional', 'tyre still active: life so far, not final',
    'site', 'site of the latest fitment (not historical attribution)'),
  'countries', coalesce((
    select jsonb_agg(jsonb_build_object(
      'country', c.country,
      'final', (select to_jsonb(s) - 'country' - 'bucket'
                       || jsonb_build_object(
                          'cpk_purchase', case when s.km > 0 then round(s.purchase_cost / s.km, 6) end,
                          'cpk_full', case when s.km > 0 then round(s.full_cost / s.km, 6) end)
                from stats s where s.country is not distinct from c.country and s.bucket = 'final'),
      'provisional', (select to_jsonb(s) - 'country' - 'bucket'
                       || jsonb_build_object(
                          'cpk_purchase', case when s.km > 0 then round(s.purchase_cost / s.km, 6) end,
                          'cpk_full', case when s.km > 0 then round(s.full_cost / s.km, 6) end)
                from stats s where s.country is not distinct from c.country and s.bucket = 'provisional'),
      'by_brand', (select coalesce(jsonb_agg(to_jsonb(g) - 'country' - 'dim' order by g.km desc nulls last), '[]'::jsonb)
                   from grp g where g.country is not distinct from c.country and g.dim = 'brand'),
      'by_size', (select coalesce(jsonb_agg(to_jsonb(g) - 'country' - 'dim' order by g.km desc nulls last), '[]'::jsonb)
                  from grp g where g.country is not distinct from c.country and g.dim = 'size'),
      'by_vehicle_type', (select coalesce(jsonb_agg(to_jsonb(g) - 'country' - 'dim' order by g.km desc nulls last), '[]'::jsonb)
                          from grp g where g.country is not distinct from c.country and g.dim = 'vehicle_type'),
      'unlinked_repair_lines', (select jsonb_build_object('lines', u.lines, 'amount', u.amount)
                                from unlinked u where u.country is not distinct from c.country))
      order by c.country)
    from (select distinct country from b) c), '[]'::jsonb));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_tyre_running_life(p_country text DEFAULT NULL::text, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_asset text DEFAULT NULL::text, p_due_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
with targets_m as materialized (select size, vehicle_type, country, target_km, target_hours from tyre_life_targets), active as (
  select t.id, t.country, t.site, t.asset_no, t.serial_no, t.tyre_position,
         t.brand, t.size, t.issue_date, t.km_at_fitment,
         f.current_km, coalesce(f.vehicle_type, t.vehicle_type) as vehicle_type
  from tyre_records t
  left join vehicle_fleet f
    on f.country = t.country and f.asset_no = t.asset_no
   and f.organisation_id = t.organisation_id
  where t.status = 'Active'
    and (p_country is null or t.country = p_country)
    -- Pure filter. Asset codes are canonical UPPER (V490), so an exact match is
    -- the whole rule; no normalising, no fuzzy match, no judgement.
    and (p_asset is null or t.asset_no = p_asset)
),
removed as (
  select t.country, t.size, t.total_km,
         coalesce(t.vehicle_type, f.vehicle_type) as vehicle_type,
         case when t.removal_date is not null and t.issue_date is not null
               and t.removal_date > t.issue_date
              then t.removal_date - t.issue_date end as life_days
  from tyre_records t
  left join vehicle_fleet f
    on f.country = t.country and f.asset_no = t.asset_no
   and f.organisation_id = t.organisation_id
  where coalesce(t.status,'') <> 'Active'
    and t.total_km between 1000 and 400000
    and t.size is not null
    and (p_country is null or t.country = p_country)
  -- NOTE: p_asset is deliberately NOT applied here. This is the fleet baseline
  -- the expected life is measured from; narrowing it to one asset would change
  -- that asset's expected life depending on how you asked for it.
),
base_size as (
  select country, public.tyre_size_key(size) as size_key, round(avg(total_km)) as avg_km, count(*) as sample,
         round(avg(life_days)) as avg_days, count(life_days) as day_sample
  from removed group by 1,2
),
base_type as (
  select country, public.tyre_size_key(size) as size_key, vehicle_type, round(avg(total_km)) as avg_km, count(*) as sample,
         round(avg(life_days)) as avg_days, count(life_days) as day_sample
  from removed where vehicle_type is not null group by 1,2,3
),
-- MATERIALIZED IS LOAD-BEARING (V577). Every CTE below this one is referenced exactly
-- once, so Postgres INLINES them, and inlining copies an expression into each place it
-- is referenced. hours_run reads the two correlated engine_hours subqueries 3x each,
-- rem_hours/used_hours_pct read hours_run 5x, and is_due plus the final `select *` read
-- those again - about 16 re-executions of both subqueries per row over 3,518 rows.
-- Barrier here: each subquery runs once per row, everything downstream reads a
-- tuplestore column. 4,675 ms -> 1,177 ms, results byte-identical.
-- DO NOT REMOVE THIS KEYWORD.
enriched as materialized (
  select a.*,
         bs.avg_km as size_avg_km, bs.sample as size_sample,
         bs.avg_days as size_avg_days, bs.day_sample as size_day_sample,
         bt.avg_km as type_avg_km, bt.sample as type_sample,
         bt.avg_days as type_avg_days, bt.day_sample as type_day_sample,
         tg.target_km, tg.target_hours,
         public.cpk_unit_for_asset_type(a.vehicle_type) as unit,
         (select e.engine_hours from engine_hours_logs e
           where e.asset_no = a.asset_no and e.country = a.country
             and a.issue_date is not null and e.reading_date <= a.issue_date
           order by e.reading_date desc limit 1) as hours_at_fitment,
         (select e.engine_hours from engine_hours_logs e
           where e.asset_no = a.asset_no and e.country = a.country
           order by e.reading_date desc limit 1) as current_hours,
         case when a.km_at_fitment is not null and a.km_at_fitment > 1
               and a.current_km is not null and a.current_km > a.km_at_fitment
              then a.current_km - a.km_at_fitment end as km_run,
         case when a.issue_date is not null and a.issue_date <= current_date
              then current_date - a.issue_date end as days_on
  from active a
  left join base_size bs on bs.country = a.country and bs.size_key = public.tyre_size_key(a.size)
  left join base_type bt on bt.country = a.country and bt.size_key = public.tyre_size_key(a.size)
                        and bt.vehicle_type = a.vehicle_type and bt.sample >= 3
  left join lateral (
    select t.target_km, t.target_hours from targets_m t
    where (t.size is null or public.tyre_size_key(t.size) = public.tyre_size_key(a.size))
      and (t.vehicle_type is null or t.vehicle_type = a.vehicle_type)
      and (t.country is null or t.country = a.country)
    order by ((t.size is not null)::int + (t.vehicle_type is not null)::int) desc,
             (t.vehicle_type is not null) desc,
             (t.country is not null) desc
    limit 1
  ) tg on true
),
hours_calc as (
  select e.*,
         case when e.hours_at_fitment is not null and e.current_hours is not null
               and e.current_hours > e.hours_at_fitment
              then round(e.current_hours - e.hours_at_fitment) end as hours_run
  from enriched e
),
final as (
  select e.*,
         coalesce(e.target_km, e.type_avg_km, e.size_avg_km) as expected_km,
         case when e.target_km is not null then 'manual'
              when e.type_avg_km is not null then 'measured_type'
              when e.size_avg_km is not null then 'measured_size' end as life_basis,
         case when e.target_km is not null then null
              when e.type_avg_km is not null then e.type_sample
              else e.size_sample end as life_sample,
         coalesce(e.type_avg_days, e.size_avg_days) as expected_days,
         case when e.type_avg_days is not null then e.type_day_sample else e.size_day_sample end as day_sample
  from hours_calc e
),
-- MIRROR OF bandFor() IN src/lib/tyreRunningLife.js. The three figures below are
-- DUE_SOON_KM 10000 / DUE_SOON_HOURS 500 / LIFE_USED_DUE_PCT 90, exported there
-- as named constants and pinned by src/test/tyreRunningLifeBands.test.js.
-- CHANGE BOTH TOGETHER.
-- Judged on km when there is a km remaining; an hours-only tyre falls through to
-- its hours target. A row with neither is 'unknown' and is NOT due.
judged as (
  select f.*,
         case when f.km_run is not null and f.expected_km is not null
              then greatest(f.expected_km - f.km_run, 0) end as rem_km,
         case when f.km_run is not null and f.expected_km is not null and f.expected_km > 0
              then least(round(f.km_run * 100.0 / f.expected_km), 999) end as used_km_pct,
         case when f.hours_run is not null and f.target_hours is not null
              then greatest(round(f.target_hours - f.hours_run), 0) end as rem_hours,
         case when f.hours_run is not null and f.target_hours is not null and f.target_hours > 0
              then least(round(f.hours_run * 100.0 / f.target_hours), 999) end as used_hours_pct
  from final f
),
banded as (
  select j.*,
         -- WHICHEVER BUDGET RUNS OUT FIRST. Each side is judged against its
         -- own limits and the tyre is due when either is spent; reading one
         -- side first hid every tyre spent on the other. Thresholds mirror
         -- DUE_SOON_KM / DUE_SOON_HOURS / LIFE_USED_DUE_PCT in
         -- src/lib/tyreRunningLife.js - change both together.
         case
           when j.rem_km is null and j.rem_hours is null then false
           else coalesce(j.rem_km = 0 or j.rem_km < least(10000, case when j.expected_km > 0 then j.expected_km * 0.1 else 10000 end)
                         or (j.used_km_pct is not null and j.used_km_pct >= 90), false)
             or coalesce(j.rem_hours = 0 or j.rem_hours < least(500, case when j.target_hours > 0 then j.target_hours * 0.1 else 500 end)
                         or (j.used_hours_pct is not null and j.used_hours_pct >= 90), false)
         end as is_due
  from judged j
),
scoped as (
  select * from banded where (not coalesce(p_due_only, false)) or is_due
)
select jsonb_build_object(
  'ok', true,
  'generated_at', now(),
  'country', p_country,
  'asset', p_asset,
  'due_only', coalesce(p_due_only, false),
  'rows', coalesce((
    select jsonb_agg(jsonb_build_object(
      'serial_no', serial_no,
      'asset_no', asset_no,
      'position', tyre_position,
      'vehicle_type', vehicle_type,
      'unit', unit,
      'site', site,
      'country', country,
      'brand', brand,
      'size', size,
      'fitted_on', issue_date,
      'days_on', days_on,
      'expected_days', expected_days,
      'day_sample', day_sample,
      'remaining_days', case when days_on is not null and expected_days is not null
                             then greatest(expected_days - days_on, 0) end,
      'km_at_fitment', km_at_fitment,
      'current_km', current_km,
      'km_run', km_run,
      'hours_at_fitment', hours_at_fitment,
      'current_hours', current_hours,
      'hours_run', hours_run,
      'expected_life_km', expected_km,
      'expected_life_hours', target_hours,
      'remaining_hours', rem_hours,
      'hours_used_pct', used_hours_pct,
      'life_basis', life_basis,
      'life_sample', life_sample,
      'remaining_km', rem_km,
      'life_used_pct', used_km_pct
    ) order by rem_km asc nulls last, asset_no, tyre_position)
    -- The order lives INSIDE the sliced subquery: ordering only in jsonb_agg
    -- makes page 2 an arbitrary set (the V523 lesson).
    from (select * from scoped
            order by rem_km asc nulls last, asset_no, tyre_position
            limit coalesce(p_limit, 6000) offset coalesce(p_offset, 0)) e), '[]'::jsonb),
  -- total is the count of the FILTERED set, so the client's paging loop stops
  -- at the right place for a filtered read.
  'total', (select count(*) from scoped)
);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_unplanned_assets(p_country text DEFAULT NULL::text, p_horizon_days integer DEFAULT 30, p_site text DEFAULT NULL::text, p_limit integer DEFAULT 300)
 RETURNS TABLE(asset_no text, site text, vehicle_type text, country text, last_inspected date, days_since integer, total_unplanned integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with params as (
    select (now() at time zone 'UTC')::date as today,
           greatest(1, least(coalesce(p_horizon_days, 30), 365)) as horizon,
           greatest(1, least(coalesce(p_limit, 300), 2000))      as cap
  ),
  fleet as (
    select upper(btrim(f.asset_no)) as asset_key,
           btrim(f.asset_no)        as asset_no,
           coalesce(nullif(btrim(f.site), ''), 'Not assigned') as site,
           f.vehicle_type, f.country
    from public.vehicle_fleet f
    where coalesce(f.status, 'Active') = 'Active'
      and (p_country is null or p_country = 'All' or f.country = p_country)
      and (p_site is null or p_site = '' or upper(btrim(f.site)) = upper(btrim(p_site)))
      and coalesce(btrim(f.asset_no), '') <> ''
  ),
  last_seen as (
    select upper(btrim(i.asset_no)) as asset_key, max(i.inspection_date) as last_date
    from public.inspections i
    where coalesce(btrim(i.asset_no), '') <> ''
    group by 1
  ),
  planned as (
    select distinct upper(btrim(s.asset_no)) as asset_key
    from public.inspection_schedules s cross join params pa
    where s.scheduled_date between pa.today and pa.today + pa.horizon
      and lower(coalesce(s.status, '')) <> 'cancelled'
      and (p_country is null or p_country = 'All' or s.country is null or s.country = p_country)
  ),
  gap as (
    select f.asset_no, f.site, f.vehicle_type, f.country,
           ls.last_date,
           case when ls.last_date is null then null else (pa.today - ls.last_date)::integer end as days_since
    from fleet f
    cross join params pa
    left join last_seen ls on ls.asset_key = f.asset_key
    left join planned  pl on pl.asset_key = f.asset_key
    where pl.asset_key is null
  )
  select g.asset_no, g.site, g.vehicle_type, g.country, g.last_date, g.days_since,
         (select count(*) from gap)::integer as total_unplanned
  from gap g
  order by (g.last_date is null) desc, g.days_since desc nulls last, g.asset_no
  limit (select cap from params)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_upload_coverage(p_days integer DEFAULT 30, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;
  return public._upload_coverage_for_org(v_org, p_days, p_country);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_upload_coverage_detail(p_days integer DEFAULT 30, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  return public._upload_coverage_detail_for_org(
    public.app_current_org(), p_days,
    case when coalesce(btrim(p_country), '') in ('', 'All') then null else btrim(p_country) end);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_user_email_by_id(user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'auth', 'public'
AS $function$
  select u.email
  from auth.users u
  join public.profiles p on p.id = u.id
  where u.id = user_id
    and (
      user_id = auth.uid()
      or (
        coalesce(public.app_is_active(), false)
        and (
          public.is_super_admin()
          or (coalesce(public.app_is_elevated(), false)
              and p.organisation_id = public.app_current_org())
        )
      )
    )
  limit 1
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_user_issue_logs(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v public.user_issues%rowtype;
  v_out jsonb;
begin
  if not public._user_issue_admin() then
    raise exception 'Only an administrator can read linked errors' using errcode = '42501';
  end if;
  select * into v from public.user_issues where id = p_id;
  if not found or (not public.is_super_admin() and v.organisation_id is distinct from public.app_current_org()) then
    return '[]'::jsonb;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', l.id, 'created_at', l.created_at, 'severity', l.severity, 'source', l.source,
           'message', left(l.message, 500), 'reference_id', l.reference_id, 'url', l.url,
           'screen', l.screen, 'platform', l.platform, 'app_version', l.app_version,
           'error_fingerprint', l.error_fingerprint) order by l.created_at desc), '[]'::jsonb)
    into v_out
    from public.system_logs l
   where l.id = any (v.linked_log_ids);
  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_user_issue_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can read the problem summary' using errcode = '42501';
  end if;

  with i as (select * from public.user_issues),
  fr as (
    select extract(epoch from (first_response_at - created_at)) / 3600.0 as h
      from i where first_response_at is not null and first_response_at >= created_at),
  fx as (
    select extract(epoch from (resolved_at - created_at)) / 3600.0 as h
      from i where status = 'fixed' and resolved_at is not null and resolved_at >= created_at)
  select jsonb_build_object(
    'generated_at', now(),
    'total', (select count(*) from i),
    'open', (select count(*) from i where status in ('new', 'triaged', 'in_progress', 'waiting_user')),
    'by_status', coalesce((select jsonb_object_agg(status, n) from
        (select status, count(*) n from i group by status) s), '{}'::jsonb),
    'by_severity', coalesce((select jsonb_object_agg(severity, n) from
        (select severity, count(*) n from i group by severity) s), '{}'::jsonb),
    'by_platform', coalesce((select jsonb_object_agg(platform, n) from
        (select platform, count(*) n from i group by platform) s), '{}'::jsonb),
    'median_first_response_hours',
        (select round((percentile_cont(0.5) within group (order by h))::numeric, 2) from fr),
    'first_response_measured', (select count(*) from fr),
    'median_fix_hours',
        (select round((percentile_cont(0.5) within group (order by h))::numeric, 2) from fx),
    'fix_measured', (select count(*) from fx),
    'breaches_7d', (select count(*) from i
        where sla_due_at is not null
          and sla_due_at >= now() - interval '7 days' and sla_due_at <= now()
          and (resolved_at is null or resolved_at > sla_due_at)
          and status <> 'waiting_user'),
    'breach_alerts_7d', (select count(*) from i where sla_breach_notified_at >= now() - interval '7 days'),
    'open_past_target', (select count(*) from i
        where status in ('new', 'triaged', 'in_progress') and sla_due_at < now())
  ) into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_user_module_permissions(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID; v_role TEXT; v_org_id UUID; v_perms JSONB := '{}'; rec RECORD;
BEGIN
  v_uid := COALESCE(p_user_id, auth.uid());
  SELECT role, organisation_id INTO v_role, v_org_id FROM profiles WHERE id = v_uid;
  FOR rec IN SELECT module_key, enabled FROM module_permissions WHERE org_id IS NULL AND role = v_role
  LOOP v_perms := v_perms || jsonb_build_object(rec.module_key, rec.enabled); END LOOP;
  IF v_org_id IS NOT NULL THEN
    FOR rec IN SELECT module_key, enabled FROM module_permissions WHERE org_id = v_org_id AND role = v_role
    LOOP v_perms := v_perms || jsonb_build_object(rec.module_key, rec.enabled); END LOOP;
  END IF;
  RETURN v_perms;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_work_order_insights(p_country text DEFAULT NULL::text, p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scoped as (
    select w.id, w.work_order_no, w.asset_no, w.site, w.country, w.priority, w.work_type,
           w.opened_at, w.completed_at, w.target_completion, w.total_cost,
           w.production_out_at, w.started_at, w.production_in_at,
           public.wo_status_canonical(w.status) as canon
    from public.work_orders w
    where (p_country is null or p_country = 'All' or w.country = p_country)
      and (p_from is null or w.opened_at >= p_from::timestamptz)
      and (p_to   is null or w.opened_at <= (p_to || 'T23:59:59.999Z')::timestamptz)
  ),
  f as (select *, canon in ('Completed','Cancelled') as is_closed from scoped),
  gaps as (
    select
      case when started_at > production_out_at and started_at - production_out_at <= interval '90 days' then extract(epoch from started_at - production_out_at)/3600 end as g_sched,
      case when completed_at > started_at and completed_at - started_at <= interval '90 days' then extract(epoch from completed_at - started_at)/3600 end as g_ws,
      case when production_in_at > completed_at and production_in_at - completed_at <= interval '90 days' then extract(epoch from production_in_at - completed_at)/3600 end as g_rel
    from f
  )
  select jsonb_build_object(
    'by_month', coalesce((select jsonb_agg(jsonb_build_object('month', m, 'opened', o, 'completed', c) order by m)
      from (select to_char(date_trunc('month', opened_at), 'YYYY-MM') m, count(*) o,
                   count(*) filter (where canon = 'Completed') c
              from f where opened_at is not null group by 1) t), '[]'::jsonb),
    'by_site', coalesce((select jsonb_agg(jsonb_build_object('label', label, 'n', n, 'open', o) order by n desc, label)
      from (select coalesce(nullif(btrim(site),''),'Not recorded') label, count(*) n,
                   count(*) filter (where not is_closed) o
              from f group by 1 order by count(*) desc, 1 limit 8) s), '[]'::jsonb),
    'cost_by_country', coalesce((select jsonb_agg(jsonb_build_object('country', c, 'cost', v, 'n', n) order by c)
      from (select coalesce(country,'Not recorded') c, sum(coalesce(total_cost,0)) v, count(*) n
              from f group by 1) k), '[]'::jsonb),
    'attention', coalesce((select jsonb_agg(to_jsonb(a)) from (
        select id, work_order_no, asset_no, site, priority, canon as status, opened_at, target_completion,
               (target_completion is not null and target_completion < now()) as overdue
          from f where not is_closed
         order by (target_completion is not null and target_completion < now()) desc,
                  case priority when 'Critical' then 0 when 'High' then 1 when 'Medium' then 2 else 3 end,
                  opened_at asc nulls last, id
         limit 8) a), '[]'::jsonb),
    'open_total', (select count(*) from f where not is_closed),
    'flow', jsonb_build_object(
      'scheduling_hours', (select percentile_cont(0.5) within group (order by g_sched) from gaps where g_sched is not null),
      'scheduling_n',     (select count(g_sched) from gaps),
      'workshop_hours',   (select percentile_cont(0.5) within group (order by g_ws) from gaps where g_ws is not null),
      'workshop_n',       (select count(g_ws) from gaps),
      'release_hours',    (select percentile_cont(0.5) within group (order by g_rel) from gaps where g_rel is not null),
      'release_n',        (select count(g_rel) from gaps))
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_work_order_stats(p_country text DEFAULT NULL::text, p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  with scoped as (
    select w.status, w.work_type, w.total_cost, w.opened_at,
           w.completed_at, w.target_completion,
           public.wo_status_canonical(w.status) as canon
    from public.work_orders w
    where (p_country is null or p_country = 'All' or w.country = p_country)
      and (p_from is null or w.opened_at >= p_from::timestamptz)
      and (p_to   is null or w.opened_at <= (p_to || 'T23:59:59.999Z')::timestamptz)
  ),
  flagged as (
    select *,
      (canon in ('Completed','Cancelled'))                        as is_closed,
      floor(extract(epoch from (coalesce(completed_at, now()) - opened_at)) / 86400.0) as days_open
    from scoped
  )
  select jsonb_build_object(
    'total',           (select count(*) from flagged),
    'open',            (select count(*) from flagged where canon = 'New'),
    'in_progress',     (select count(*) from flagged where canon = 'In Progress'),
    'waiting_parts',   (select count(*) from flagged where canon = 'Waiting for Parts'),
    'overdue',         (select count(*) from flagged
                         where target_completion is not null
                           and not is_closed
                           and target_completion < now()),
    'completed_today', (select count(*) from flagged
                         where completed_at is not null
                           and (completed_at at time zone 'utc')::date
                               = (now() at time zone 'utc')::date),
    'total_cost',      (select coalesce(sum(coalesce(total_cost,0)),0) from flagged),
    'avg_days_open',   coalesce((select round(avg(days_open))
                                   from flagged where not is_closed), 0),
    'by_type',         coalesce((select jsonb_agg(jsonb_build_object('label', label, 'n', n)
                                   order by n desc, label)
                                   from (select coalesce(work_type,'') as label, count(*) as n
                                           from flagged group by 1
                                          order by count(*) desc, 1 limit 8) t), '[]'::jsonb),
    'by_status',       coalesce((select jsonb_agg(jsonb_build_object('label', label, 'n', n)
                                   order by n desc, label)
                                   from (select canon as label, count(*) as n
                                           from flagged group by 1) s), '[]'::jsonb)
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_work_orders_page(p_country text DEFAULT NULL::text, p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_sort text DEFAULT 'opened_at'::text, p_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_q       text := nullif(btrim(coalesce(p_search,'')), '');
  v_sort    text := case when p_sort in ('work_order_no','asset_no','work_type','priority',
                                         'status','technician_name','opened_at',
                                         'target_completion','total_cost')
                         then p_sort else 'opened_at' end;
  v_asc     boolean := lower(coalesce(p_dir,'')) = 'asc';
  v_lim     integer := greatest(1, least(coalesce(p_limit, 20), 200));
  v_off     integer := greatest(0, coalesce(p_offset, 0));
  v_all_c   boolean := (p_country is null or p_country = 'All');
  v_from    timestamptz := p_from::timestamptz;
  v_to      timestamptz := (p_to || 'T23:59:59.999Z')::timestamptz;
  v_out     jsonb;
begin
  -- The scope is materialised NARROW (id + the one sort key). The old body
  -- materialised w.* for every matching row and spilled ~27 MB to temp per call.
  with scoped as materialized (
    select w.id,
      case v_sort
        when 'total_cost'        then w.total_cost
        when 'opened_at'         then extract(epoch from w.opened_at)::numeric
        when 'target_completion' then extract(epoch from w.target_completion)::numeric
      end as sort_num,
      case v_sort
        when 'work_order_no'   then w.work_order_no
        when 'asset_no'        then w.asset_no
        when 'work_type'       then w.work_type
        when 'priority'        then w.priority
        when 'status'          then public.wo_status_canonical(w.status)
        when 'technician_name' then w.technician_name
      end as sort_text
    from public.work_orders w
    where (v_all_c or w.country = p_country)
      and (v_from is null or w.opened_at >= v_from)
      and (v_to   is null or w.opened_at <= v_to)
      and (p_priority is null or p_priority = 'All' or w.priority  = p_priority)
      and (p_type     is null or p_type     = 'All' or w.work_type = p_type)
      and (p_status   is null or p_status   = 'All'
           or public.wo_status_canonical(w.status) = p_status)
      and (v_q is null or (
            w.work_order_no  ilike '%' || v_q || '%'
         or w.asset_no        ilike '%' || v_q || '%'
         or w.tyre_serial     ilike '%' || v_q || '%'
         or w.description     ilike '%' || v_q || '%'
         or w.technician_name ilike '%' || v_q || '%'))
  ),
  page as (
    select s.id, s.sort_num, s.sort_text
    from scoped s
    order by
      case when v_asc     then s.sort_num  end asc  nulls last,
      case when not v_asc then s.sort_num  end desc nulls last,
      case when v_asc     then s.sort_text end asc  nulls last,
      case when not v_asc then s.sort_text end desc nulls last,
      s.id                        -- sort keys are NOT unique; without this a page
                                  -- boundary inside a tie group skips or repeats rows
    limit  v_lim
    offset v_off
  )
  select jsonb_build_object(
    'total', (select count(*) from scoped),
    'rows',  coalesce((
      select jsonb_agg(
               to_jsonb(w) || jsonb_build_object('canon', public.wo_status_canonical(w.status))
               order by
                 case when v_asc     then p.sort_num  end asc  nulls last,
                 case when not v_asc then p.sort_num  end desc nulls last,
                 case when v_asc     then p.sort_text end asc  nulls last,
                 case when not v_asc then p.sort_text end desc nulls last,
                 p.id)
      from page p
      join public.work_orders w on w.id = p.id), '[]'::jsonb)
  ) into v_out;
  return v_out;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.get_workshop_snapshot(p_token text, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  t public.report_shares%ROWTYPE;
  v_org uuid; v_company text;
  v_today date := current_date;
  k_working int; k_available int; k_waiting_parts int; k_waiting_approval int;
  k_waiting_tools int; k_waiting_vehicle int; k_on_break int; k_training int;
  k_on_duty int; k_absent int;
  k_open int; k_overdue int; k_vor int; k_done_today int;
  v_util numeric;
  v_jobs_by_status jsonb; v_open_cards jsonb; v_vor_list jsonb; v_alerts jsonb;
  result jsonb;
BEGIN
  -- Validate the share token EXACTLY like get_report_snapshot.
  SELECT * INTO t FROM public.report_shares WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invalid'); END IF;
  IF NOT t.active THEN RETURN jsonb_build_object('ok', false, 'reason', 'revoked'); END IF;
  IF t.expires_at IS NOT NULL AND t.expires_at < now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'expired'); END IF;
  IF t.password_hash IS NOT NULL THEN
    IF p_password IS NULL OR not public.share_password_ok('report', t.id, p_password, t.password_hash) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'password'); END IF;
  END IF;
  v_org := t.organisation_id;

  SELECT value::text INTO v_company FROM public.settings WHERE key = 'company_name' LIMIT 1;
  v_company := coalesce(nullif(replace(replace(coalesce(v_company,''), '"', ''), '\', ''), ''), 'TyrePulse');

  -- Technician roster + derived live status (defensive: any missing table degrades to zeros).
  -- No PII leaves this block: only aggregate COUNTS are kept.
  BEGIN
    WITH roster AS (
      SELECT id AS user_id FROM public.profiles
      WHERE organisation_id = v_org
        AND lower(coalesce(role,'')) IN ('tyre man','tyre_man','inspector','technician','mechanic','foreman','maintenance supervisor')
    ),
    att AS (
      SELECT DISTINCT user_id FROM public.workshop_attendance
      WHERE organisation_id = v_org AND check_in::date = v_today
    ),
    last_ev AS (
      SELECT DISTINCT ON (user_id) user_id, event_type, reason_code
      FROM public.tech_activity_events
      WHERE organisation_id = v_org AND at >= v_today
        AND event_type NOT IN ('request_assistance','report_problem')
      ORDER BY user_id, at DESC
    ),
    universe AS (
      SELECT user_id FROM roster
      UNION SELECT user_id FROM att
      UNION SELECT user_id FROM last_ev
    ),
    tech AS (
      SELECT u.user_id,
        CASE
          WHEN le.event_type IS NULL AND a.user_id IS NULL THEN 'absent'
          WHEN le.event_type = 'check_out' THEN 'off_duty'
          WHEN le.event_type IN ('start_job','resume_job') THEN 'working'
          WHEN le.event_type = 'start_break' THEN 'on_break'
          WHEN le.event_type = 'training' THEN 'training'
          WHEN le.event_type = 'request_parts' THEN 'waiting_parts'
          WHEN le.event_type = 'waiting_tools' THEN 'waiting_tools'
          WHEN le.event_type = 'waiting_approval' THEN 'waiting_approval'
          WHEN le.event_type = 'waiting_vehicle' THEN 'waiting_vehicle'
          WHEN le.event_type = 'pause_job' THEN
            CASE lower(coalesce(le.reason_code,''))
              WHEN 'parts' THEN 'waiting_parts'
              WHEN 'tools' THEN 'waiting_tools'
              WHEN 'approval' THEN 'waiting_approval'
              WHEN 'vehicle' THEN 'waiting_vehicle'
              WHEN 'break' THEN 'on_break'
              ELSE 'available' END
          ELSE 'available'
        END AS status
      FROM universe u
      LEFT JOIN last_ev le ON le.user_id = u.user_id
      LEFT JOIN att a ON a.user_id = u.user_id
    )
    SELECT
      count(*) FILTER (WHERE status='working'),
      count(*) FILTER (WHERE status='available'),
      count(*) FILTER (WHERE status='waiting_parts'),
      count(*) FILTER (WHERE status='waiting_approval'),
      count(*) FILTER (WHERE status='waiting_tools'),
      count(*) FILTER (WHERE status='waiting_vehicle'),
      count(*) FILTER (WHERE status='on_break'),
      count(*) FILTER (WHERE status='training'),
      count(*) FILTER (WHERE status NOT IN ('off_duty','absent')),
      count(*) FILTER (WHERE status='absent')
    INTO k_working,k_available,k_waiting_parts,k_waiting_approval,k_waiting_tools,k_waiting_vehicle,k_on_break,k_training,k_on_duty,k_absent
    FROM tech;
  EXCEPTION WHEN others THEN
    k_working:=0;k_available:=0;k_waiting_parts:=0;k_waiting_approval:=0;k_waiting_tools:=0;k_waiting_vehicle:=0;k_on_break:=0;k_training:=0;k_on_duty:=0;k_absent:=0;
  END;

  -- Utilization: simple productive-vs-onduty ratio from today's event intervals.
  -- Each event opens an interval until the next event (or now); classify by the
  -- opening event. Honest NULL when there is no on-duty time recorded today.
  BEGIN
    WITH ev AS (
      SELECT event_type,
        extract(epoch from (coalesce(lead(at) OVER (PARTITION BY user_id ORDER BY at), now()) - at))/60.0 AS mins
      FROM public.tech_activity_events
      WHERE organisation_id = v_org AND at >= v_today
        AND event_type NOT IN ('request_assistance','report_problem')
    )
    SELECT CASE WHEN sum(mins) FILTER (WHERE event_type NOT IN ('check_out','start_break','training')) > 0
      THEN round(100.0 * coalesce(sum(mins) FILTER (WHERE event_type IN ('start_job','resume_job')),0)
        / sum(mins) FILTER (WHERE event_type NOT IN ('check_out','start_break','training')))
      ELSE NULL END
    INTO v_util FROM ev;
  EXCEPTION WHEN others THEN v_util := NULL; END;

  -- Job-card KPIs.
  BEGIN
    SELECT
      count(*) FILTER (WHERE lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')),
      count(*) FILTER (WHERE target_completion IS NOT NULL AND target_completion < now() AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')),
      count(*) FILTER (WHERE vor = true AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')),
      count(*) FILTER (WHERE lower(coalesce(status,'')) IN ('completed','closed','done') AND completed_at::date = v_today)
    INTO k_open,k_overdue,k_vor,k_done_today
    FROM public.work_orders WHERE organisation_id = v_org;
  EXCEPTION WHEN others THEN k_open:=0;k_overdue:=0;k_vor:=0;k_done_today:=0; END;

  BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object('label',lbl,'value',c)),'[]'::jsonb)
    INTO v_jobs_by_status FROM (
      SELECT coalesce(nullif(btrim(status),''),'Unspecified') lbl, count(*) c
      FROM public.work_orders WHERE organisation_id = v_org
        AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')
      GROUP BY 1 ORDER BY c DESC LIMIT 8) x;
  EXCEPTION WHEN others THEN v_jobs_by_status := '[]'::jsonb; END;

  BEGIN
    SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) INTO v_open_cards FROM (
      SELECT jsonb_build_object('wo_no',work_order_no,'asset_no',asset_no,'status',status,'priority',priority,'site',site) x
      FROM public.work_orders WHERE organisation_id = v_org
        AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')
      ORDER BY coalesce(opened_at,created_at) DESC LIMIT 14) q;
  EXCEPTION WHEN others THEN v_open_cards := '[]'::jsonb; END;

  BEGIN
    SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) INTO v_vor_list FROM (
      SELECT jsonb_build_object('asset_no',asset_no,'site',site,'since',vor_since) x
      FROM public.work_orders WHERE organisation_id = v_org AND vor = true
        AND lower(coalesce(status,'')) NOT IN ('completed','closed','done','cancelled')
      ORDER BY vor_since ASC NULLS LAST LIMIT 14) q;
  EXCEPTION WHEN others THEN v_vor_list := '[]'::jsonb; END;

  -- Safety / operations alerts, derived from the aggregate counts (NO PII).
  v_alerts := '[]'::jsonb;
  IF coalesce(k_vor,0) > 0 THEN v_alerts := v_alerts || jsonb_build_object('level','critical','message', k_vor || ' vehicle(s) off road'); END IF;
  IF coalesce(k_overdue,0) > 0 THEN v_alerts := v_alerts || jsonb_build_object('level','warning','message', k_overdue || ' job(s) past target time'); END IF;
  IF coalesce(k_waiting_parts,0) > 0 THEN v_alerts := v_alerts || jsonb_build_object('level','warning','message', k_waiting_parts || ' technician(s) waiting for parts'); END IF;
  IF coalesce(k_waiting_approval,0) > 0 THEN v_alerts := v_alerts || jsonb_build_object('level','info','message', k_waiting_approval || ' technician(s) waiting for approval'); END IF;
  IF coalesce(k_absent,0) > 0 THEN v_alerts := v_alerts || jsonb_build_object('level','info','message', k_absent || ' rostered technician(s) not checked in'); END IF;

  result := jsonb_build_object(
    'ok', true, 'company', v_company, 'generated_at', now(),
    'rotate_seconds', t.rotate_seconds, 'refresh_seconds', t.refresh_seconds,
    'kpis', jsonb_build_object(
      'open_jobs', coalesce(k_open,0),
      'overdue_jobs', coalesce(k_overdue,0),
      'vehicles_off_road', coalesce(k_vor,0),
      'jobs_completed_today', coalesce(k_done_today,0),
      'working', coalesce(k_working,0),
      'available', coalesce(k_available,0),
      'waiting_parts', coalesce(k_waiting_parts,0),
      'waiting_approval', coalesce(k_waiting_approval,0),
      'on_break', coalesce(k_on_break,0),
      'absent', coalesce(k_absent,0),
      'on_duty', coalesce(k_on_duty,0),
      'utilization', v_util
    ),
    'jobs_by_status', v_jobs_by_status,
    'open_job_cards', v_open_cards,
    'vor_list', v_vor_list,
    'safety_alerts', v_alerts
  );

  UPDATE public.report_shares SET last_viewed_at = now(), view_count = view_count + 1 WHERE id = t.id;
  RETURN result;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_access_policy_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rpc boolean := coalesce(current_setting('app.access_policy_rpc', true), '') = 'on';
        v_cur text;
begin
  if v_rpc then return coalesce(NEW, OLD); end if;
  if TG_OP = 'DELETE' then
    if OLD.key = 'console_ip_allowlist_enabled' then
      raise exception 'The console IP allowlist can only be changed from Console, Access Policies.' using errcode = '42501';
    end if;
    return OLD;
  end if;
  if TG_OP = 'INSERT' then
    if NEW.key = 'console_ip_allowlist_enabled' then
      select value into v_cur from public.system_config where key = 'console_ip_allowlist_enabled';
      if v_cur is null or v_cur is distinct from NEW.value then
        raise exception 'The console IP allowlist can only be changed from Console, Access Policies.' using errcode = '42501';
      end if;
    end if;
    return NEW;
  end if;
  if (OLD.key = 'console_ip_allowlist_enabled' or NEW.key = 'console_ip_allowlist_enabled')
     and (NEW.key is distinct from OLD.key or NEW.value is distinct from OLD.value) then
    raise exception 'The console IP allowlist can only be changed from Console, Access Policies.' using errcode = '42501';
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_administration_record_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false)
     OR public.app_current_org() IS NULL THEN
    RAISE EXCEPTION 'Active organisation membership required.' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    NEW.created_by := auth.uid(); NEW.created_at := now();
  ELSIF NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.organisation_id IS DISTINCT FROM OLD.organisation_id THEN
    RAISE EXCEPTION 'Record ownership and creation identity are immutable.' USING ERRCODE='42501';
  END IF;
  IF TG_TABLE_NAME='ocr_scans' THEN
    IF TG_OP='INSERT' OR NEW.review_status IS DISTINCT FROM OLD.review_status
       OR NEW.corrected_value IS DISTINCT FROM OLD.corrected_value THEN
      NEW.reviewed_by := CASE WHEN NEW.review_status IN ('confirmed','rejected') THEN auth.uid()::text ELSE NULL END;
    ELSE NEW.reviewed_by := OLD.reviewed_by;
    END IF;
  ELSIF TG_TABLE_NAME='onboarding_tasks' THEN
    IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.completed_at := CASE WHEN NEW.status='completed' THEN now() ELSE NULL END;
    ELSE NEW.completed_at := OLD.completed_at;
    END IF;
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_checklist_approval_stages()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_two_stage boolean;
  v_blocking  jsonb;
  v_bad       text;
begin
  if new.approval_status is not distinct from old.approval_status then return new; end if;

  select coalesce(t.require_area_manager, false), t.option_sets #> '{legend,blocking}'
    into v_two_stage, v_blocking
    from public.checklist_templates t where t.id = new.template_id;
  v_two_stage := coalesce(v_two_stage, false);

  if new.approval_status = 'rejected' then
    if not public.checklist_is_supervisor() then
      raise exception 'You do not have permission to reject this checklist' using errcode = '42501';
    end if;
    return new;
  end if;

  if new.approval_status = 'pending_area_manager' then
    if not v_two_stage then
      raise exception 'This checklist does not use an area-manager stage' using errcode = '22023';
    end if;
    if not public.checklist_is_supervisor() then
      raise exception 'Only a supervisor can sign off this checklist' using errcode = '42501';
    end if;
    if coalesce(btrim(new.supervisor_name), '') = ''
       or coalesce(btrim(new.supervisor_signature), '') = '' then
      raise exception 'A supervisor name and signature are required' using errcode = '22023';
    end if;
    new.supervisor_by := coalesce(new.supervisor_by, auth.uid());
    new.supervisor_at := coalesce(new.supervisor_at, now());
    return new;
  end if;

  if new.approval_status = 'approved' then
    if v_blocking is not null and jsonb_typeof(v_blocking) = 'array' then
      select string_agg(distinct a.value, ', ') into v_bad
        from jsonb_each_text(coalesce(new.answers, '{}'::jsonb)) a
       where jsonb_exists(v_blocking, a.value);
      if v_bad is not null then
        raise exception 'This checklist still has items marked "%". It cannot be closed until they are corrected or re-marked.', v_bad
          using errcode = '22023';
      end if;
    end if;

    if v_two_stage then
      if coalesce(btrim(coalesce(new.supervisor_signature, old.supervisor_signature)), '') = '' then
        raise exception 'A supervisor must sign off before the area manager can approve' using errcode = '22023';
      end if;
      if not public.checklist_is_area_manager() then
        raise exception 'Only an area manager can give final approval' using errcode = '42501';
      end if;
    elsif not public.checklist_is_supervisor() then
      raise exception 'You do not have permission to approve this checklist' using errcode = '42501';
    end if;

    if coalesce(btrim(new.approver_name), '') = ''
       or coalesce(btrim(new.approver_signature), '') = '' then
      raise exception 'An approver name and signature are required' using errcode = '22023';
    end if;
    new.approved_by := coalesce(new.approved_by, auth.uid());
    new.approved_at := coalesce(new.approved_at, now());
    return new;
  end if;

  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_checklist_assignment_skip()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status = 'skipped' and old.status is distinct from 'skipped' then
    if nullif(btrim(new.skip_reason), '') is null then
      raise exception 'A reason is required to skip a checklist assignment'
        using errcode = '22023';
    end if;
    new.skip_reason := btrim(new.skip_reason);
    new.skipped_by := auth.uid();
    new.skipped_at := now();
  elsif old.status = 'skipped' and (
    new.skip_reason is distinct from old.skip_reason
    or new.skipped_by is distinct from old.skipped_by
    or new.skipped_at is distinct from old.skipped_at
  ) then
    raise exception 'Checklist skip evidence is immutable'
      using errcode = '22023';
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_checklist_schedule_governance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.checklist_governance_policies;
begin
  if new.end_date is not null and new.next_due > new.end_date then
    new.active := false;
  end if;
  select * into p from public.checklist_governance_policies
   where organisation_id is not distinct from new.organisation_id;
  if new.pilot then
    if p.organisation_id is null or not p.pilot_enabled then
      raise exception 'Enable and configure the checklist pilot before creating a pilot schedule'
        using errcode='22023';
    end if;
    if p.pilot_country is not null and lower(coalesce(new.country,'')) <> lower(p.pilot_country) then
      raise exception 'Pilot schedule country must match the governance policy' using errcode='22023';
    end if;
    if not (p.pilot_site = any(new.sites)) then
      raise exception 'Pilot schedule must include the configured pilot site' using errcode='22023';
    end if;
    if new.start_date < p.pilot_start_date
       or (p.pilot_end_date is not null and coalesce(new.end_date,new.start_date) > p.pilot_end_date) then
      raise exception 'Pilot schedule dates must stay inside the configured pilot window' using errcode='22023';
    end if;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_checklist_submission_template_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.template_revision_id is distinct from old.template_revision_id
     or new.template_snapshot is distinct from old.template_snapshot
     or new.template_snapshot_status is distinct from old.template_snapshot_status
     or new.template_snapshot_captured_at is distinct from old.template_snapshot_captured_at then
    raise exception 'Checklist template evidence is immutable'
      using errcode = '22023';
  end if;
  return new;
end;
$function$;
