CREATE OR REPLACE FUNCTION public.guard_dual_control_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rpc boolean := coalesce(current_setting('app.dual_control_rpc', true), '') = 'on';
