CREATE OR REPLACE FUNCTION public.guard_handover_approval_stages()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(current_setting('handover.via', true), '') <> 'decide'
     and auth.uid() is not null
     and not public.is_super_admin() then
    if old.approval_status = 'approved' then
      raise exception 'An approved handover cannot be changed.' using errcode = '42501';
    end if;
    if old.approval_status = 'pending_incharge' then
      raise exception 'A handover the supervisor has signed cannot be changed until the fleet incharge decides.' using errcode = '42501';
    end if;
    if new.supervisor_name is distinct from old.supervisor_name
       or new.supervisor_signature is distinct from old.supervisor_signature
       or new.supervisor_at is distinct from old.supervisor_at
       or new.supervisor_by is distinct from old.supervisor_by
       or new.incharge_name is distinct from old.incharge_name
       or new.incharge_signature is distinct from old.incharge_signature
       or new.incharge_at is distinct from old.incharge_at
       or new.incharge_by is distinct from old.incharge_by
       or new.review_note is distinct from old.review_note
       or new.document_no is distinct from old.document_no then
      raise exception 'Sign-off details are recorded through the sign-off step only.' using errcode = '42501';
    end if;
    if new.approval_status is distinct from old.approval_status
       and not (coalesce(old.approval_status, 'pending_supervisor') in ('draft', 'pending_supervisor', 'rejected')
                and new.approval_status in ('draft', 'pending_supervisor')) then
      raise exception 'A handover is signed off through the sign-off step only.' using errcode = '42501';
    end if;
  end if;

  if new.approval_status is not distinct from old.approval_status then
    return new;
  end if;

  if new.approval_status in ('draft','pending_supervisor') then
    return new;
  end if;

  if new.approval_status = 'rejected' then
    if not public.handover_can_sign_supervisor() then
      raise exception 'You do not have permission to send this handover back.' using errcode = '42501';
    end if;
    return new;
  end if;

  if new.approval_status = 'pending_incharge' then
    if not public.handover_can_sign_supervisor() then
      raise exception 'Only a fleet supervisor can sign off this handover.' using errcode = '42501';
    end if;
    if coalesce(btrim(new.supervisor_signature), '') = '' then
      raise exception 'A supervisor signature is required.' using errcode = '22023';
    end if;
    new.supervisor_by := coalesce(new.supervisor_by, auth.uid());
    new.supervisor_at := coalesce(new.supervisor_at, now());
    return new;
  end if;

  if new.approval_status = 'approved' then
    if not public.handover_can_sign_incharge() then
      raise exception 'Only the fleet incharge can give final approval on this handover.' using errcode = '42501';
    end if;
    if coalesce(btrim(coalesce(new.supervisor_signature, old.supervisor_signature)), '') = '' then
      raise exception 'A supervisor must sign off before the fleet incharge can approve.' using errcode = '22023';
    end if;
    if coalesce(btrim(coalesce(new.incharge_signature, old.incharge_signature)), '') = '' then
      raise exception 'A fleet incharge signature is required.' using errcode = '22023';
    end if;
    new.incharge_by := coalesce(new.incharge_by, auth.uid());
    new.incharge_at := coalesce(new.incharge_at, now());
    return new;
  end if;

  raise exception 'That is not a valid handover sign-off transition.' using errcode = '22023';
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_handover_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_super_admin() then
    return new;
  end if;

  if coalesce(new.approval_status, 'pending_supervisor') not in ('draft', 'pending_supervisor') then
    raise exception 'A new handover starts as a draft or waits for supervisor sign-off.' using errcode = '42501';
  end if;

  if new.supervisor_name is not null or new.supervisor_signature is not null
     or new.supervisor_at is not null or new.supervisor_by is not null
     or new.incharge_name is not null or new.incharge_signature is not null
     or new.incharge_at is not null or new.incharge_by is not null
     or new.review_note is not null then
    raise exception 'Sign-off details cannot be supplied when a handover is created.' using errcode = '42501';
  end if;

  new.document_no := null;
  return new;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_import_batch_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE elevated boolean := coalesce(public.get_my_role() IN ('Admin','Manager','Director') OR public.is_super_admin(),false);
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) THEN
    RAISE EXCEPTION 'Active membership required.' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.approval_status IS NULL OR NEW.approval_status NOT IN ('draft','pending_approval') OR NEW.approver IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'New batches must be submitted before approval.' USING ERRCODE='42501';
    END IF;
  ELSE
    IF NEW.uploader IS DISTINCT FROM OLD.uploader OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.organisation_id IS DISTINCT FROM OLD.organisation_id THEN
      RAISE EXCEPTION 'Batch ownership is immutable.' USING ERRCODE='42501';
    END IF;
    IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
      IF OLD.import_status IN ('committing','committed') THEN
        RAISE EXCEPTION 'An importing batch cannot change approval.' USING ERRCODE='23514';
      END IF;
      IF NEW.approval_status IN ('approved','rejected') THEN
        IF NOT elevated THEN RAISE EXCEPTION 'Only elevated reviewers may decide imports.' USING ERRCODE='42501'; END IF;
        IF NOT coalesce(OLD.approval_status IN ('draft','pending_approval'),false) THEN
          RAISE EXCEPTION 'This batch already has an approval decision.' USING ERRCODE='23514';
        END IF;
        NEW.approver := auth.uid(); NEW.approved_at := now();
      ELSIF NEW.approval_status='pending_approval' AND OLD.approval_status='draft' THEN
        NEW.approver := NULL; NEW.approved_at := NULL;
      ELSE RAISE EXCEPTION 'Invalid approval transition.' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.approver IS DISTINCT FROM OLD.approver OR NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
      RAISE EXCEPTION 'Approval identity can only change with a decision.' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_import_reviewed_contents()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b public.import_batches%ROWTYPE; batch_id uuid;
BEGIN
  IF TG_OP='UPDATE' AND NEW.batch_id IS DISTINCT FROM OLD.batch_id THEN
    RAISE EXCEPTION 'A staged row cannot move between batches.' USING ERRCODE='42501';
  END IF;
  batch_id := CASE WHEN TG_OP='DELETE' THEN OLD.batch_id ELSE NEW.batch_id END;
  SELECT * INTO b FROM public.import_batches WHERE id=batch_id FOR UPDATE;
  IF NOT FOUND OR b.organisation_id IS DISTINCT FROM public.app_current_org()
     OR NOT coalesce(public.app_is_active(),false) THEN
    RAISE EXCEPTION 'Import batch is unavailable in your organisation.' USING ERRCODE='42501';
  END IF;
  IF NOT coalesce(b.approval_status IN ('draft','pending_approval'),false) OR b.import_status IN ('committing','committed','reversed')
     OR NOT coalesce(public.import_user_can_commit_country(b.country),false) THEN
    -- Definer commit/enrichment functions may record outcomes, but even they
    -- cannot rewrite the reviewed source values or add/delete reviewed rows.
    IF TG_OP='UPDATE' AND current_user <> 'authenticated'
       AND b.approval_status='approved'
       AND coalesce(public.import_user_can_commit_country(b.country),false)
       AND (to_jsonb(NEW)-ARRAY['processed_at','target_record_id','target_module','dup_status','validation_status'])
           IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['processed_at','target_record_id','target_module','dup_status','validation_status']) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Approved import contents are immutable. Create a corrected batch for review.' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_import_reviewed_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF (OLD.approval_status='approved' OR OLD.import_status IN ('committing','committed','reversed')) AND EXISTS(
    SELECT 1 FROM unnest(ARRAY['module','country','site','project','company_id','file_id','mapping_profile_id','mapping_profile_version','date_format','timezone','source_currency','unit_system']) k
    WHERE to_jsonb(OLD)->k IS DISTINCT FROM to_jsonb(NEW)->k
  ) THEN
    RAISE EXCEPTION 'Approved import context is immutable. Create a corrected batch for review.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_last_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_others integer;
begin
  if TG_OP = 'DELETE' then
    if coalesce(OLD.is_super_admin, false) and coalesce(OLD.locked, false) = false then
      select count(*) into v_others from public.profiles
        where id <> OLD.id and coalesce(is_super_admin, false) and coalesce(locked, false) = false;
      if v_others = 0 then
        raise exception 'Cannot remove the last super admin.' using errcode = '42501';
      end if;
    end if;
    if OLD.role = 'Admin' and coalesce(OLD.locked, false) = false and coalesce(OLD.approved, true) then
      select count(*) into v_others from public.profiles
        where id <> OLD.id and role = 'Admin' and org_id is not distinct from OLD.org_id
          and coalesce(locked, false) = false and coalesce(approved, true);
      if v_others = 0 then
        raise exception 'Cannot remove the last administrator of this organisation.' using errcode = '42501';
      end if;
    end if;
    return OLD;
  end if;

  -- UPDATE: last super-admin demotion / lock
  if coalesce(OLD.is_super_admin, false) and coalesce(OLD.locked, false) = false
     and (coalesce(NEW.is_super_admin, false) = false or coalesce(NEW.locked, false) = true) then
    select count(*) into v_others from public.profiles
      where id <> OLD.id and coalesce(is_super_admin, false) and coalesce(locked, false) = false;
    if v_others = 0 then
      raise exception 'Cannot demote or lock the last super admin.' using errcode = '42501';
    end if;
  end if;

  -- UPDATE: last org-Admin demotion / lock / unapprove
  if OLD.role = 'Admin' and coalesce(OLD.locked, false) = false and coalesce(OLD.approved, true)
     and (NEW.role is distinct from 'Admin' or coalesce(NEW.locked, false) = true or coalesce(NEW.approved, true) = false) then
    select count(*) into v_others from public.profiles
      where id <> OLD.id and role = 'Admin' and org_id is not distinct from OLD.org_id
        and coalesce(locked, false) = false and coalesce(approved, true);
    if v_others = 0 then
      raise exception 'Cannot demote, lock or unapprove the last administrator of this organisation.' using errcode = '42501';
    end if;
  end if;

  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_organisation_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('authenticated','anon') and (
    old.settings->'settings' is distinct from new.settings->'settings' or
    old.settings->'app_settings' is distinct from new.settings->'app_settings'
  ) then raise exception 'Use the audited configuration operation.' using errcode='42501'; end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_profile_privileged_cols()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Nothing privileged changed -> allow (self-service edits, updated_at, etc.)
  if NEW.role            is not distinct from OLD.role
     and NEW.approved    is not distinct from OLD.approved
     and NEW.locked      is not distinct from OLD.locked
     and NEW.is_super_admin is not distinct from OLD.is_super_admin
     and NEW.country     is not distinct from OLD.country
     and NEW.site        is not distinct from OLD.site
     and NEW.org_id      is not distinct from OLD.org_id
     and NEW.organisation_id is not distinct from OLD.organisation_id
     and not (auth.uid() is not null and (
              NEW.sites            is distinct from OLD.sites
           or NEW.countries        is distinct from OLD.countries
           or NEW.web_access       is distinct from OLD.web_access
           or NEW.module_overrides is distinct from OLD.module_overrides
           or NEW.employee_id      is distinct from OLD.employee_id
           or NEW.email            is distinct from OLD.email
           or NEW.username         is distinct from OLD.username)) then
    return NEW;
  end if;

  -- Super admin may change anything.
  if public.is_super_admin() then
    return NEW;
  end if;

  -- Self-service username change (web Settings page). Allowed for the row
  -- owner when it is the ONLY guarded change and the new name is not another
  -- person's employee id (login identifier squatting).
  if public.get_my_role() is distinct from 'Admin'
     and NEW.id = auth.uid()
     and NEW.username is distinct from OLD.username
     and NEW.role            is not distinct from OLD.role
     and NEW.approved        is not distinct from OLD.approved
     and NEW.locked          is not distinct from OLD.locked
     and NEW.is_super_admin  is not distinct from OLD.is_super_admin
     and NEW.country         is not distinct from OLD.country
     and NEW.site            is not distinct from OLD.site
     and NEW.org_id          is not distinct from OLD.org_id
     and NEW.organisation_id is not distinct from OLD.organisation_id
     and NEW.sites            is not distinct from OLD.sites
     and NEW.countries        is not distinct from OLD.countries
     and NEW.web_access       is not distinct from OLD.web_access
     and NEW.module_overrides is not distinct from OLD.module_overrides
     and NEW.employee_id      is not distinct from OLD.employee_id
     and NEW.email            is not distinct from OLD.email then
    if exists (select 1 from public.profiles p
                where p.id <> NEW.id
                  and nullif(btrim(coalesce(p.employee_id, '')), '') is not null
                  and lower(btrim(p.employee_id)) = lower(btrim(coalesce(NEW.username, '')))) then
      raise exception 'That username is already in use.' using errcode = '23505';
    end if;
    return NEW;
  end if;

  -- Only an Admin may change any privileged column at all.
  if public.get_my_role() is distinct from 'Admin' then
    raise exception 'Not authorized to change role, approval, lock, country, site or organisation.'
      using errcode = '42501';
  end if;

  -- A non-super Admin may NEVER grant/revoke super-admin status.
  if NEW.is_super_admin is distinct from OLD.is_super_admin then
    raise exception 'Only a super admin can change super-admin status.'
      using errcode = '42501';
  end if;

  -- A non-super Admin may NEVER move a user between organisations.
  if NEW.org_id is distinct from OLD.org_id
     or NEW.organisation_id is distinct from OLD.organisation_id then
    raise exception 'Only a super admin can change a user''s organisation.'
      using errcode = '42501';
  end if;

  -- A non-super Admin may only manage users within their OWN organisation.
  if OLD.org_id is distinct from public.app_current_org() then
    raise exception 'Not authorized to manage a user in another organisation.'
      using errcode = '42501';
  end if;

  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_recovery_contact_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy text := nullif(current_setting('request.jwt.claim.role', true), '');
  v_claims text := nullif(current_setting('request.jwt.claims', true), '');
  v_json   text;
  request_role text;
begin
  if v_claims is not null then
    begin
      v_json := nullif(v_claims::jsonb ->> 'role', '');
    exception when others then
      -- claims present but unreadable: treat as an API caller that is not the service
      v_json := 'unknown';
    end;
  end if;
  request_role := coalesce(v_json, v_legacy);

  -- No request role at all = not an API request (migration, scheduled job).
  -- Through the API only the service role (the verification service) may
  -- change the recovery contact columns. If the two claim styles disagree the
  -- change is refused unless both say service_role.
  if (request_role is not null or v_legacy is not null)
     and not (
       coalesce(v_json, 'service_role') = 'service_role'
       and coalesce(v_legacy, 'service_role') = 'service_role'
     )
     and (
       new.recovery_email is distinct from old.recovery_email
       or new.recovery_email_verified_at is distinct from old.recovery_email_verified_at
       or new.recovery_phone is distinct from old.recovery_phone
       or new.recovery_phone_verified_at is distinct from old.recovery_phone_verified_at
     ) then
    raise exception 'recovery contacts must be changed through the verification service'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_support_ticket_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE triage boolean := coalesce(public.get_my_role() IN ('Admin','Manager','Director') OR public.is_super_admin(),false);
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false)
     OR public.app_current_org() IS NULL THEN
    RAISE EXCEPTION 'Active organisation membership required.' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    NEW.created_by := auth.uid(); NEW.created_at := now();
    NEW.status := 'open'; NEW.admin_response := NULL;
    NEW.responded_by := NULL; NEW.responded_at := NULL; NEW.resolved_at := NULL;
  ELSE
    IF NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.organisation_id IS DISTINCT FROM OLD.organisation_id
       OR NEW.country IS DISTINCT FROM OLD.country
       OR NEW.created_by_name IS DISTINCT FROM OLD.created_by_name
       OR NEW.created_by_email IS DISTINCT FROM OLD.created_by_email THEN
      RAISE EXCEPTION 'Ticket ownership and reporter identity are immutable.' USING ERRCODE='42501';
    END IF;
    IF NOT triage AND (NEW.status IS DISTINCT FROM OLD.status
       OR NEW.admin_response IS DISTINCT FROM OLD.admin_response
       OR NEW.responded_by IS DISTINCT FROM OLD.responded_by
       OR NEW.responded_at IS DISTINCT FROM OLD.responded_at
       OR NEW.resolved_at IS DISTINCT FROM OLD.resolved_at) THEN
      RAISE EXCEPTION 'Only a support administrator may respond or change ticket status.' USING ERRCODE='42501';
    END IF;
    IF NEW.admin_response IS DISTINCT FROM OLD.admin_response THEN
      NEW.responded_by := auth.uid(); NEW.responded_at := now();
    ELSE
      NEW.responded_by := OLD.responded_by; NEW.responded_at := OLD.responded_at;
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.resolved_at := CASE WHEN NEW.status IN ('resolved','closed') THEN now() ELSE NULL END;
    ELSE NEW.resolved_at := OLD.resolved_at;
    END IF;
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_tyre_active_fitment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_asset text; v_pos text; v_cnt int;
begin
  if auth.uid() is null then return new; end if;
  if not public.tyre_status_is_active(new.status) then return new; end if;
  v_asset := nullif(upper(btrim(coalesce(new.asset_no, new.asset_number))), '');
  v_pos   := nullif(upper(btrim(coalesce(new.tyre_position, new.position))), '');
  if v_asset is null or v_pos is null or v_pos = '0' then return new; end if;
  select count(*) into v_cnt from public.tyre_records t
  where t.id <> new.id
    and t.organisation_id is not distinct from new.organisation_id
    and coalesce(t.country, '') = coalesce(new.country, '')
    and nullif(upper(btrim(coalesce(t.asset_no, t.asset_number))), '') = v_asset
    and nullif(upper(btrim(coalesce(t.tyre_position, t.position))), '') = v_pos
    and public.tyre_status_is_active(t.status);
  if v_cnt > 0 then
    raise exception 'Position % on asset % already has an active tyre. Remove or move it first.', v_pos, v_asset
      using errcode = '23505';
  end if;
  return new;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.guard_wash_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    if auth.uid() is not null then
      if new.created_by is not null and new.created_by <> auth.uid() then
        raise exception 'Wash creator must match the signed-in user' using errcode = '42501';
      end if;
      new.created_by := auth.uid();
    end if;
    new.entry_name := null; new.entry_username := null;
    select p.full_name, p.username into new.entry_name, new.entry_username
      from public.profiles p where p.id = new.created_by and p.organisation_id = new.organisation_id;
    new.completed_by := null; new.completed_at := null;
    if new.status = 'Completed' then
      new.completed_by := new.created_by; new.completed_at := now();
    end if;
  else
    if new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at
      or new.captured_at is distinct from old.captured_at then
      raise exception 'Original wash attribution cannot be changed' using errcode = '42501';
    end if;
    new.entry_name := old.entry_name; new.entry_username := old.entry_username;
    new.completed_by := old.completed_by; new.completed_at := old.completed_at;
    if new.status = 'Completed' and old.status is distinct from 'Completed' then
      new.completed_by := auth.uid(); new.completed_at := now();
    end if;
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- Sign-up metadata is written by the client: only a known country is honoured,
  -- anything else (or nothing) falls back to the default.
  v_region text := case upper(btrim(coalesce(new.raw_user_meta_data->>'region','')))
                     when 'KSA' then 'KSA'
                     when 'UAE' then 'UAE'
                     when 'EGYPT' then 'Egypt'
                     else 'KSA' end;
  v_req    text;
  v_approved boolean := false;
begin
  select value into v_req from public.system_config where key = 'require_approval';
  -- Default = require approval (pending). Only an explicit off value auto-approves.
  if v_req is not null and lower(btrim(v_req)) in ('false','0','off','no') then
    v_approved := true;
  end if;

  insert into public.profiles (id, username, full_name, role, region, employee_id, email,
                               org_id, organisation_id, country, approved)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'username', split_part(new.email, '@', 1)),
    new.raw_user_meta_data->>'full_name',
    'Reporter',
    v_region,
    nullif(new.raw_user_meta_data->>'employee_id',''),
    new.email,
    '00000000-0000-0000-0000-000000000001',
    '00000000-0000-0000-0000-000000000001',
    ARRAY[v_region],
    v_approved
  )
  on conflict (id) do nothing;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.handover_can_sign_incharge()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
