CREATE OR REPLACE FUNCTION public.holding_consolidated_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_parent uuid := public.app_current_org(); v_role text := public.get_my_role(); v_ids uuid[]; v_subs jsonb; v_total jsonb;
BEGIN
  IF v_parent IS NULL THEN RETURN jsonb_build_object('error','no_org'); END IF;
  IF v_role IS NULL OR v_role NOT IN ('Admin','Manager','Director') THEN RETURN jsonb_build_object('error','forbidden'); END IF;
  SELECT array_agg(id) INTO v_ids FROM public.organisations WHERE id = v_parent OR parent_organisation_id = v_parent;
  WITH org_ids AS (SELECT unnest(v_ids) AS oid),
  kpi AS (
    SELECT org.id::text AS tenant_id, org.name AS name, org.logo_url AS logo_url, (org.id = v_parent) AS is_hq,
      (SELECT count(*) FROM public.vehicle_fleet vf WHERE vf.organisation_id = o.oid and (vf.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vf.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(vf.is_active, true)) AS vehicles,
      (SELECT count(*) FROM public.tyre_records tr WHERE tr.organisation_id = o.oid and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))) AS tyres,
      (SELECT count(*) FROM public.alerts a WHERE a.organisation_id = o.oid and (a.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(a.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(a.resolved, false) = false) AS open_alerts,
      (SELECT count(*) FROM public.alerts a WHERE a.organisation_id = o.oid and (a.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(a.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(a.resolved, false) = false AND a.severity = 'critical') AS critical_alerts,
      (SELECT count(*) FROM public.tyre_records tr WHERE tr.organisation_id = o.oid and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND tr.tread_depth IS NOT NULL AND tr.tread_depth < 3) AS low_tread,
      (SELECT COALESCE(sum(po.total_amount), 0) FROM public.purchase_orders po WHERE po.organisation_id = o.oid and (po.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(po.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND po.created_at >= now() - interval '30 days' AND COALESCE(po.status,'') <> 'cancelled') AS spend_30d
    FROM org_ids o JOIN public.organisations org ON org.id = o.oid
  ),
  scored AS (SELECT k.*, GREATEST(0, 100 - (low_tread * 5) - (critical_alerts * 10)) AS fleet_health_score FROM kpi k)
  SELECT jsonb_agg(to_jsonb(scored) ORDER BY is_hq DESC, fleet_health_score ASC),
    jsonb_build_object('vehicles', COALESCE(sum(vehicles),0), 'tyres', COALESCE(sum(tyres),0), 'alerts', COALESCE(sum(open_alerts),0), 'critical_alerts', COALESCE(sum(critical_alerts),0), 'low_tread', COALESCE(sum(low_tread),0), 'spend_30d', COALESCE(sum(spend_30d),0))
  INTO v_subs, v_total FROM scored;
  RETURN jsonb_build_object('parent_id', v_parent, 'subsidiary_count', (SELECT count(*) FROM public.organisations WHERE parent_organisation_id = v_parent), 'grand_total', COALESCE(v_total,'{}'::jsonb), 'subsidiaries', COALESCE(v_subs,'[]'::jsonb));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.holding_link_subsidiary(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_parent uuid := public.app_current_org(); v_role text := public.get_my_role(); v_child public.organisations%ROWTYPE;
BEGIN
  IF v_parent IS NULL THEN RETURN jsonb_build_object('error','no_org'); END IF;
  IF v_role IS NULL OR v_role NOT IN ('Admin','Director') THEN RETURN jsonb_build_object('error','forbidden'); END IF;
  SELECT * INTO v_child FROM public.organisations WHERE slug = p_slug;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','not_found'); END IF;
  IF v_child.id = v_parent THEN RETURN jsonb_build_object('error','cannot_link_self'); END IF;
  IF v_child.parent_organisation_id IS NOT NULL THEN RETURN jsonb_build_object('error','already_linked'); END IF;
  IF NOT COALESCE(v_child.holding_link_optin, false) THEN RETURN jsonb_build_object('error','consent_required'); END IF;
  IF EXISTS (SELECT 1 FROM public.organisations WHERE id = v_parent AND parent_organisation_id = v_child.id) THEN RETURN jsonb_build_object('error','would_create_cycle'); END IF;
  UPDATE public.organisations SET parent_organisation_id = v_parent, updated_at = now() WHERE id = v_child.id;
  RETURN jsonb_build_object('ok', true, 'linked', v_child.id, 'name', v_child.name);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.holding_subsidiaries()
 RETURNS TABLE(id uuid, name text, slug text, logo_url text, active boolean, country text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT o.id, o.name, o.slug, o.logo_url, o.active, o.primary_country FROM public.organisations o WHERE o.parent_organisation_id = public.app_current_org() ORDER BY o.name;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.holding_unlink_subsidiary(p_child uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_parent uuid := public.app_current_org(); v_role text := public.get_my_role(); v_rows int;
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('Admin','Director') THEN RETURN jsonb_build_object('error','forbidden'); END IF;
  UPDATE public.organisations SET parent_organisation_id = NULL, updated_at = now() WHERE id = p_child AND parent_organisation_id = v_parent;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RETURN jsonb_build_object('error','not_a_subsidiary'); END IF;
  RETURN jsonb_build_object('ok', true, 'unlinked', p_child);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_batch_country(p_batch_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT country FROM public.import_batches WHERE id = p_batch_id
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_changed_supplied_patch(p_live jsonb, p_uploaded jsonb, p_allowed text[])
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(u.key, u.value), '{}'::jsonb)
  from jsonb_each(coalesce(p_uploaded, '{}'::jsonb)) u
  where u.key = any(coalesce(p_allowed, array[]::text[]))
    and not public.import_jsonb_blank(u.value)
    and not public.import_exact_supplied_match(
      coalesce(p_live, '{}'::jsonb),
      jsonb_build_object(u.key, u.value),
      p_allowed
    );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_commit_batch(p_batch_id uuid, p_max_rows integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  b          public.import_batches%ROWTYPE;
  r          public.import_rows%ROWTYPE;
  v_uid      uuid := auth.uid();
  v_org      uuid := public.app_current_org();
  v_target   text;
  v_tcols    text[];
  v_cols     text;
  v_enriched jsonb;
  v_data     jsonb;
  v_custom   jsonb;
  v_new_id   text;
  v_existing jsonb;
  v_child_count int := 0;
  v_exact_dups int := 0;
  v_inserted int := 0;
  v_skipped  int := 0;
  v_failed   int := 0;
  v_merged   int := 0;
  v_errors   jsonb := '[]'::jsonb;
  v_msg      text;

  v_limit     int := CASE WHEN p_max_rows IS NULL OR p_max_rows <= 0
                          THEN NULL ELSE LEAST(p_max_rows, 10000) END;
  v_remaining int := 0;
  v_total_ins int := 0;

  v_cost_fields text[];
  v_merge_on    boolean := false;
  v_override_tx jsonb := '{}'::jsonb;
  v_override_cd jsonb := '{}'::jsonb;
  v_absorbed    uuid[] := ARRAY[]::uuid[];
  v_children    jsonb := '{}'::jsonb;

  grp          record;
  mem          record;
  v_kv         record;
  v_primary_id uuid;
  v_primary_d  jsonb;
  v_primary_c  jsonb;
  v_best       int;
  v_score      int;
  v_merged_d   jsonb;
  v_merged_c   jsonb;
  v_lines      jsonb;
  v_count      int;
  v_child_ids  jsonb;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN
    RAISE EXCEPTION 'Not authorised.' USING errcode = '42501';
  END IF;

  SELECT * INTO b FROM public.import_batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Import batch not found.'; END IF;

  IF v_uid IS NULL OR v_org IS NULL OR NOT coalesce(public.app_is_active(),false) OR b.organisation_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'Cross-organisation commit denied.' USING errcode = '42501';
  END IF;
  IF NOT public.import_user_can_commit_country(b.country) THEN
    RAISE EXCEPTION 'Cross-country commit denied: you are not assigned to country %.', b.country USING errcode = '42501';
  END IF;
  IF b.approval_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'Batch is not approved (status: %).', b.approval_status;
  END IF;
  IF b.import_status = 'committed' THEN
    RETURN jsonb_build_object('status','already_committed','inserted',0,'remaining',0);
  END IF;

  
  IF b.import_status='reversed' THEN RAISE EXCEPTION 'A reversed batch cannot be resumed.' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM public.import_rows WHERE batch_id=p_batch_id AND organisation_id IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'Staging ownership does not match the batch.' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.import_rows WHERE batch_id=p_batch_id AND action='insert'
    AND validation_status IN ('ready','warning') AND processed_at IS NULL
    AND NOT public.import_site_scope_ok(coalesce(nullif(transformed_data,'{}'::jsonb),mapped_data)->>'site')) THEN
    RAISE EXCEPTION 'An imported site is outside your scope.' USING ERRCODE='42501';
  END IF;
  v_target := public.import_target_table(b.module);
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Commit is not supported for module "%" yet.', b.module;
  END IF;

  v_cost_fields := public.import_cost_fields(b.module);
  v_merge_on    := v_cost_fields IS NOT NULL;

  IF v_merge_on THEN
    FOR grp IN
      SELECT s.nk, array_agg(s.id ORDER BY s.source_row_no, s.id) AS ids
      FROM (
        SELECT ir.id, ir.source_row_no,
               public.import_merge_key(
                 b.module,
                 COALESCE(NULLIF(ir.transformed_data, '{}'::jsonb), ir.mapped_data)
               ) AS nk
        FROM public.import_rows ir
        WHERE ir.batch_id = p_batch_id
          AND ir.action = 'insert'
          AND ir.validation_status IN ('ready','warning')
          AND ir.processed_at IS NULL
      ) s
      WHERE s.nk IS NOT NULL
      GROUP BY s.nk
      HAVING count(*) > 1
    LOOP
      v_primary_id := NULL;
      v_best       := -1;
      v_lines      := '[]'::jsonb;
      v_count      := 0;
      FOR mem IN
        SELECT ir.id, ir.source_row_no,
               COALESCE(NULLIF(ir.transformed_data, '{}'::jsonb), ir.mapped_data) AS d,
               COALESCE(ir.custom_data, '{}'::jsonb) AS c,
               COALESCE(ir.raw_source_data, '{}'::jsonb) AS raw
        FROM public.import_rows ir
        WHERE ir.id = ANY(grp.ids)
        ORDER BY ir.source_row_no, ir.id
      LOOP
        v_count := v_count + 1;
        IF jsonb_typeof(mem.c -> 'line_items') = 'array'
           AND jsonb_array_length(mem.c -> 'line_items') > 0 THEN
          v_lines := v_lines || (mem.c -> 'line_items');
        ELSE
          v_lines := v_lines || jsonb_build_array(mem.raw);
        END IF;

        v_score := public.import_cost_score(b.module, mem.d);
        IF v_score > v_best THEN
          v_best       := v_score;
          v_primary_id := mem.id;
          v_primary_d  := mem.d;
          v_primary_c  := mem.c;
        END IF;
      END LOOP;

      v_merged_d  := v_primary_d;
      v_merged_c  := v_primary_c;
      v_child_ids := '[]'::jsonb;
      FOR mem IN
        SELECT ir.id,
               COALESCE(NULLIF(ir.transformed_data, '{}'::jsonb), ir.mapped_data) AS d,
               COALESCE(ir.custom_data, '{}'::jsonb) AS c
        FROM public.import_rows ir
        WHERE ir.id = ANY(grp.ids) AND ir.id <> v_primary_id
        ORDER BY ir.source_row_no, ir.id
      LOOP
        FOR v_kv IN SELECT key, value FROM jsonb_each(mem.d) LOOP
          IF v_kv.key = ANY(v_cost_fields) THEN CONTINUE; END IF;
          IF public.import_jsonb_blank(v_merged_d -> v_kv.key)
             AND NOT public.import_jsonb_blank(v_kv.value) THEN
            v_merged_d := jsonb_set(v_merged_d, ARRAY[v_kv.key], v_kv.value, true);
          END IF;
        END LOOP;

        FOR v_kv IN SELECT key, value FROM jsonb_each(mem.c) LOOP
          IF v_kv.key = ANY(v_cost_fields) THEN CONTINUE; END IF;
          IF v_kv.key IN ('line_items','line_count','merged_row_count','cross_file_merged') THEN
            CONTINUE;
          END IF;
          IF public.import_jsonb_blank(v_merged_c -> v_kv.key)
             AND NOT public.import_jsonb_blank(v_kv.value) THEN
            v_merged_c := jsonb_set(v_merged_c, ARRAY[v_kv.key], v_kv.value, true);
          END IF;
        END LOOP;

        v_child_ids := v_child_ids || to_jsonb(mem.id::text);
        v_absorbed  := v_absorbed || mem.id;
      END LOOP;

      v_merged_c := v_merged_c || jsonb_build_object(
                      'line_items',       v_lines,
                      'line_count',       jsonb_array_length(v_lines),
                      'merged_row_count', v_count,
                      'cross_file_merged', true);

      v_override_tx := jsonb_set(v_override_tx, ARRAY[v_primary_id::text], v_merged_d, true);
      v_override_cd := jsonb_set(v_override_cd, ARRAY[v_primary_id::text], v_merged_c, true);
      v_children    := jsonb_set(v_children,    ARRAY[v_primary_id::text], v_child_ids, true);
    END LOOP;
  END IF;

  SELECT array_agg(c.column_name::text) INTO v_tcols
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name = v_target
    AND c.is_generated = 'NEVER'
    AND c.identity_generation IS NULL;

  FOR r IN
    SELECT * FROM public.import_rows
    WHERE batch_id = p_batch_id
      AND action = 'insert'
      AND validation_status IN ('ready','warning')
      AND processed_at IS NULL
      AND id <> ALL(v_absorbed)
    ORDER BY source_row_no, id
    LIMIT v_limit
  LOOP
    IF v_override_tx ? r.id::text THEN
      v_data   := v_override_tx -> r.id::text;
      v_custom := v_override_cd -> r.id::text;
    ELSE
      v_data   := COALESCE(NULLIF(r.transformed_data, '{}'::jsonb), r.mapped_data);
      v_custom := r.custom_data;
    END IF;

    -- target_record_id is only a preview candidate at this point. Re-read
    -- it in this organisation and verify every uploaded target field.
    IF r.target_record_id IS NOT NULL THEN
      v_existing := NULL;
      EXECUTE format(
        'SELECT to_jsonb(t) FROM public.%I AS t WHERE t.id::text = $1 AND t.organisation_id = $2 AND t.country IS NOT DISTINCT FROM $3 AND public.import_site_scope_ok(to_jsonb(t)->>''site'') LIMIT 1',
        v_target)
      USING r.target_record_id, v_org, b.country INTO v_existing;

      IF v_existing IS NOT NULL
         AND public.import_exact_supplied_match(v_existing, v_data, v_tcols) THEN
        v_child_count := 0;
        UPDATE public.import_rows
          SET target_module = b.module, processed_at = now(), dup_status = 'duplicate'
          WHERE id = r.id;

        IF v_children ? r.id::text THEN
          v_child_count := jsonb_array_length(v_children -> r.id::text);
          UPDATE public.import_rows
            SET target_record_id = r.target_record_id,
                target_module = b.module, processed_at = now(), dup_status = 'duplicate'
            WHERE id IN (
              SELECT (jsonb_array_elements_text(v_children -> r.id::text))::uuid
            );
        END IF;

        v_skipped := v_skipped + 1 + v_child_count;
        v_exact_dups := v_exact_dups + 1 + v_child_count;
        INSERT INTO public.import_row_issues (row_id, severity, issue_code, message)
          VALUES (r.id, 'warning', 'EXACT_LIVE_DUPLICATE',
                  'Every supplied value matches the live record; exact duplicate dropped.');
        CONTINUE;
      ELSE
        -- The live row changed after preview (or disappeared). Do not trust
        -- the stale candidate; continue through the normal insert path.
        UPDATE public.import_rows SET target_record_id = NULL WHERE id = r.id;
      END IF;
    END IF;

    v_enriched := v_data
                  || jsonb_build_object('organisation_id', v_org, 'country', b.country,
                                        'created_by', v_uid, 'uploaded_by', v_uid)
                  || CASE WHEN v_custom IS NOT NULL AND v_custom <> '{}'::jsonb
                          THEN jsonb_build_object('custom_data', v_custom)
                          ELSE '{}'::jsonb END;

    SELECT string_agg(quote_ident(k), ', ') INTO v_cols
    FROM jsonb_object_keys(v_enriched) k
    WHERE k = ANY(v_tcols);

    IF v_cols IS NULL THEN
      v_skipped := v_skipped + 1;
      UPDATE public.import_rows
        SET target_module = b.module, processed_at = now()
        WHERE id = r.id;
      INSERT INTO public.import_row_issues (row_id, severity, issue_code, message)
        VALUES (r.id, 'warning', 'COMMIT_SKIPPED',
                'No mapped column matches the target table; row was not imported.');
      CONTINUE;
    END IF;

    BEGIN
      EXECUTE format(
        'INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(null::public.%I, $1) AS rec RETURNING id::text',
        v_target, v_cols, v_cols, v_target)
      USING v_enriched INTO v_new_id;

      UPDATE public.import_rows
        SET target_record_id = v_new_id, target_module = b.module, processed_at = now()
        WHERE id = r.id;
      v_inserted := v_inserted + 1;

      IF v_children ? r.id::text THEN
        UPDATE public.import_rows
          SET target_record_id = v_new_id,
              target_module     = b.module,
              processed_at      = now(),
              dup_status        = 'duplicate'
          WHERE id IN (
            SELECT (jsonb_array_elements_text(v_children -> r.id::text))::uuid
          );
        v_merged := v_merged + jsonb_array_length(v_children -> r.id::text);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_msg := SQLERRM;
      UPDATE public.import_rows SET validation_status = 'error' WHERE id = r.id;
      INSERT INTO public.import_row_issues (row_id, severity, issue_code, message)
        VALUES (r.id, 'error', 'COMMIT_FAILED', v_msg);
      IF jsonb_array_length(v_errors) < 20 THEN
        v_errors := v_errors || jsonb_build_object('row', r.source_row_no, 'message', v_msg);
      END IF;
    END;
  END LOOP;

  SELECT count(*) INTO v_remaining
  FROM public.import_rows
  WHERE batch_id = p_batch_id
    AND action = 'insert'
    AND validation_status IN ('ready','warning')
    AND processed_at IS NULL;

  v_total_ins := COALESCE(b.imported_rows, 0) + v_inserted;

  UPDATE public.import_batches
    SET import_status = CASE WHEN v_remaining > 0 THEN 'committing'
                             WHEN v_total_ins > 0 OR v_exact_dups > 0 THEN 'committed'
                             ELSE 'failed' END,
        imported_rows = COALESCE(imported_rows,0) + v_inserted,
        skipped_rows  = COALESCE(skipped_rows,0)  + v_skipped,
        error_rows    = COALESCE(error_rows,0)    + v_failed,
        completed_at  = CASE WHEN v_remaining > 0 THEN completed_at ELSE now() END
    WHERE id = p_batch_id;

  INSERT INTO public.import_audit_events (organisation_id, batch_id, actor, action, detail)
    VALUES (v_org, p_batch_id, v_uid, 'commit',
            jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped,
                               'failed', v_failed, 'merged', v_merged, 'exact_duplicates', v_exact_dups,
                               'remaining', v_remaining, 'max_rows', v_limit,
                               'target', v_target));

  RETURN jsonb_build_object(
    'status',   CASE WHEN v_remaining > 0 THEN 'partial'
                     WHEN v_total_ins > 0 OR v_exact_dups > 0 THEN 'committed'
                     WHEN v_failed > 0 THEN 'failed'
                     ELSE 'nothing_to_commit' END,
    'inserted', v_inserted,
    'skipped',  v_skipped,
    'exact_duplicates', v_exact_dups,
    'not_eligible', coalesce((
      select jsonb_object_agg(z.k, z.n) from (
        select coalesce(ir.action, 'unset') || '/' || coalesce(ir.validation_status, 'unset') as k,
               count(*) as n
        from public.import_rows ir
        where ir.batch_id = p_batch_id
          and not (ir.action = 'insert' and ir.validation_status in ('ready', 'warning'))
        group by 1
      ) z), '{}'::jsonb),
    'failed',   v_failed,
    'merged',   v_merged,
    'remaining', v_remaining,
    'errors',   v_errors,
    'target',   v_target);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_cost_fields(p_module text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_module
    WHEN 'workorder' THEN ARRAY['tyre_cost','total_cost','parts_cost','labour_cost']
    WHEN 'accident'  THEN ARRAY['claim_amount','claim_approved_amount','repair_cost']
    WHEN 'warranty'  THEN ARRAY['credit_amount']
    ELSE NULL
  END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_cost_score(p_module text, p_d jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
           count(*) FILTER (WHERE NOT public.import_jsonb_blank(p_d -> f)),
           0)::int
  FROM unnest(COALESCE(public.import_cost_fields(p_module), ARRAY[]::text[])) AS f;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_enrich_batch(p_batch_id uuid, p_max_rows integer DEFAULT NULL::integer, p_after_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  b public.import_batches%ROWTYPE; r public.import_rows%ROWTYPE;
  v_uid uuid:=auth.uid(); v_org uuid:=public.app_current_org();
  v_target text; v_key text; v_live_id text; v_live jsonb; v_data jsonb; v_patch jsonb;
  v_set text; v_enriched int:=0; v_skipped int:=0; v_nomatch int:=0;
  v_ecols text[]; k text; v_limit int:=CASE WHEN p_max_rows IS NULL OR p_max_rows<=0 THEN NULL ELSE least(p_max_rows,5000) END;
  v_scanned int:=0; v_last_id uuid:=p_after_id; v_done boolean;
BEGIN
  IF v_uid IS NULL OR v_org IS NULL OR NOT coalesce(public.app_is_active(),false)
     OR NOT coalesce(public.is_elevated_user(),false) THEN
    RAISE EXCEPTION 'Only an active elevated reviewer can refresh imported records.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO b FROM public.import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR b.organisation_id IS DISTINCT FROM v_org OR NOT coalesce(public.import_user_can_commit_country(b.country),false) THEN
    RAISE EXCEPTION 'Import batch is outside your scope.' USING ERRCODE='42501';
  END IF;
  IF b.approval_status IS DISTINCT FROM 'approved' OR b.import_status='reversed' THEN
    RAISE EXCEPTION 'Only an approved batch can refresh live records.' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.import_rows WHERE batch_id=p_batch_id AND organisation_id IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'Staging ownership does not match the batch.' USING ERRCODE='42501';
  END IF;
  v_target:=public.import_target_table(b.module);
  IF v_target IS NULL THEN RAISE EXCEPTION 'Enrich not supported for module %',b.module; END IF;
  SELECT array_agg(c.column_name::text) INTO v_ecols FROM information_schema.columns c
  WHERE c.table_schema='public' AND c.table_name=v_target AND c.is_generated='NEVER' AND c.identity_generation IS NULL
    AND c.column_name NOT IN ('id','organisation_id','country','created_by','created_at','uploaded_by','updated_by','upload_batch_id');
  FOR r IN SELECT * FROM public.import_rows WHERE batch_id=p_batch_id AND action='update'
    AND validation_status IN ('ready','warning') AND processed_at IS NULL
    AND (p_after_id IS NULL OR id>p_after_id) ORDER BY id LIMIT v_limit LOOP
    v_scanned:=v_scanned+1;v_last_id:=r.id;
    v_data:=coalesce(nullif(r.transformed_data,'{}'::jsonb),r.mapped_data)||jsonb_build_object('country',b.country);
    IF NOT public.import_site_scope_ok(v_data->>'site') THEN
      RAISE EXCEPTION 'An imported site is outside your scope.' USING ERRCODE='42501';
    END IF;
    v_key:=public.import_natural_key(b.module,v_data);
    IF v_key IS NULL THEN v_skipped:=v_skipped+1;CONTINUE;END IF;
    EXECUTE format('SELECT id::text,to_jsonb(t) FROM public.%I t WHERE public.import_natural_key($1,to_jsonb(t))=$2 AND t.organisation_id=$3 AND t.country IS NOT DISTINCT FROM $4 AND public.import_site_scope_ok(to_jsonb(t)->>''site'') ORDER BY t.id LIMIT 1 FOR UPDATE',v_target)
      INTO v_live_id,v_live USING b.module,v_key,v_org,b.country;
    IF v_live_id IS NULL THEN v_nomatch:=v_nomatch+1;CONTINUE;END IF;
    v_patch:='{}'::jsonb;
    FOREACH k IN ARRAY coalesce(v_ecols,'{}'::text[]) LOOP
      IF NOT(v_data?k) OR public.import_jsonb_blank(v_data->k) THEN CONTINUE;END IF;
      IF public.import_exact_supplied_match(v_live,jsonb_build_object(k,v_data->k),v_ecols) THEN CONTINUE;END IF;
      v_patch:=v_patch||jsonb_build_object(k,v_data->k);
    END LOOP;
    IF v_patch='{}'::jsonb THEN
      UPDATE public.import_rows SET target_record_id=v_live_id,target_module=b.module,processed_at=now(),dup_status='duplicate' WHERE id=r.id;
      v_skipped:=v_skipped+1;CONTINUE;
    END IF;
    SELECT string_agg(format('%I=(jsonb_populate_record(t,$1)).%I',kk,kk),', ') INTO v_set FROM jsonb_object_keys(v_patch) kk;
    EXECUTE format('UPDATE public.%I t SET %s WHERE id::text=$2 AND organisation_id=$3 AND country IS NOT DISTINCT FROM $4 AND public.import_site_scope_ok(to_jsonb(t)->>''site'')',v_target,v_set)
      USING v_patch,v_live_id,v_org,b.country;
    UPDATE public.import_rows SET target_record_id=v_live_id,target_module=b.module,processed_at=now(),dup_status='enriched' WHERE id=r.id;
    v_enriched:=v_enriched+1;
  END LOOP;
  v_done:=(v_limit IS NULL) OR v_scanned<v_limit;
  INSERT INTO public.import_audit_events(organisation_id,batch_id,actor,action,detail) VALUES(v_org,p_batch_id,v_uid,'enrich',
    jsonb_build_object('enriched',v_enriched,'skipped',v_skipped,'no_match',v_nomatch,'scanned',v_scanned,'done',v_done,'target',v_target));
  RETURN jsonb_build_object('enriched',v_enriched,'skipped',v_skipped,'no_match',v_nomatch,'scanned',v_scanned,'done',v_done,'last_id',CASE WHEN v_scanned>0 THEN v_last_id::text ELSE NULL END);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_exact_supplied_match(p_live jsonb, p_uploaded jsonb, p_target_columns text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when count(*) = 0 then false else bool_and(
    case
      when public.import_jsonb_blank(p_live -> u.key)
       and public.import_jsonb_blank(u.value) then true
      when public.import_jsonb_blank(p_live -> u.key)
        or public.import_jsonb_blank(u.value) then false
      when jsonb_typeof(u.value) = 'string' then
        lower(btrim(p_live ->> u.key)) = lower(btrim(u.value #>> '{}'))
      else (p_live -> u.key) = u.value
    end
  ) end
  from jsonb_each(coalesce(p_uploaded, '{}'::jsonb)) as u(key, value)
  where u.key = any(coalesce(p_target_columns, array[]::text[]));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_existing_keys(p_module text, p_country text)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org    uuid := public.app_current_org();
  v_target text := public.import_target_table(p_module);
  v_key    text;
  v_guard  text;
  v_country_predicate text := '($2 is null or country is not distinct from $2)'
    || ' and (country is null or (select public.is_super_admin())'
    || ' or (select public.app_sees_all_countries())'
    || ' or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), ''{}''::text[])))';
begin
  if p_country is not null and public.app_can_see_country(p_country) is false then return; end if;
  if v_target is null then return; end if;

  if p_module = 'fleet' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(asset_no,'''')))';
  elsif p_module = 'tyre' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(serial_no,'''')))';
  elsif p_module = 'stock' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(site,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(description,'''')))';
  elsif p_module = 'accident' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || '
          || 'lower(btrim(coalesce(nullif(btrim(coalesce(insurance_claim_no,'''')),''''), police_report_no, '''')))';
  elsif p_module = 'inspection' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(asset_no,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(inspection_type,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(inspection_date::text,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(inspector,'''')))';
  elsif p_module = 'workorder' then
    v_key := 'lower(btrim(coalesce(work_order_no,'''')))';
    v_country_predicate := 'true';
  elsif p_module = 'warranty' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(serial_number,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(claim_no,'''')))';
  elsif p_module = 'gatepass' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(asset_no,''''))) '
          || '|| chr(1) || lower(btrim(coalesce(pass_date::text,'''')))';
  elsif p_module = 'supplier' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || '
          || 'lower(btrim(coalesce(nullif(btrim(coalesce(supplier_code,'''')),''''), supplier_name, '''')))';
  elsif p_module = 'driver' then
    v_key := 'lower(btrim(coalesce(country,''''))) || chr(1) || lower(btrim(coalesce(driver_id,'''')))';
  else
    return;
  end if;

  if p_module = 'stock' then
    v_guard := '(btrim(coalesce(site,'''')) <> '''' or btrim(coalesce(description,'''')) <> '''')';
  elsif p_module = 'tyre' then
    v_guard := 'btrim(coalesce(serial_no,'''')) <> ''''';
  elsif p_module = 'accident' then
    v_guard := '(btrim(coalesce(insurance_claim_no,'''')) <> '''' or btrim(coalesce(police_report_no,'''')) <> '''')';
  elsif p_module = 'workorder' then
    v_guard := 'btrim(coalesce(work_order_no,'''')) <> ''''';
  elsif p_module = 'warranty' then
    v_guard := 'btrim(coalesce(serial_number,'''')) <> ''''';
  elsif p_module = 'supplier' then
    v_guard := '(btrim(coalesce(supplier_code,'''')) <> '''' or btrim(coalesce(supplier_name,'''')) <> '''')';
  elsif p_module = 'driver' then
    v_guard := 'btrim(coalesce(driver_id,'''')) <> ''''';
  else
    v_guard := 'btrim(coalesce(asset_no,'''')) <> ''''';
  end if;

  return query execute format(
    $q$
      select distinct %s as k
      from public.%I
      where (organisation_id is null or organisation_id = $1)
        and %s
        and %s
    $q$, v_key, v_target, v_country_predicate, v_guard)
  using v_org, p_country;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_jsonb_blank(p_v jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT p_v IS NULL
      OR jsonb_typeof(p_v) = 'null'
      OR (jsonb_typeof(p_v) = 'string' AND btrim(p_v #>> '{}') = '');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_jsonb_pick(p_source jsonb, p_keys text[])
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(k, p_source -> k), '{}'::jsonb)
  from unnest(coalesce(p_keys, array[]::text[])) k;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_merge_key(p_module text, p_d jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  c   text := lower(btrim(coalesce(p_d ->> 'country', '')));
  id1 text;
  id2 text;
begin
  case p_module
    when 'workorder' then
      id1 := lower(btrim(coalesce(p_d ->> 'work_order_no', '')));
      if id1 = '' then return null; end if;
      return id1;

    when 'accident' then
      id1 := lower(btrim(coalesce(
               nullif(btrim(coalesce(p_d ->> 'insurance_claim_no', '')), ''),
               p_d ->> 'police_report_no', '')));
      if id1 = '' then return null; end if;
      return c || chr(1) || id1;

    when 'warranty' then
      id1 := lower(btrim(coalesce(p_d ->> 'serial_number', '')));
      id2 := lower(btrim(coalesce(p_d ->> 'claim_no', '')));
      if id2 = '' and id1 = '' then return null; end if;
      return c || chr(1) || id1 || chr(1) || id2;

    else
      return null;
  end case;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_natural_key(p_module text, p_d jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT lower(btrim(coalesce(p_d->>'country',''))) || chr(1) || CASE p_module
    WHEN 'fleet'      THEN nullif(lower(btrim(coalesce(p_d->>'asset_no',''))),'')
    WHEN 'tyre'       THEN nullif(lower(btrim(coalesce(p_d->>'serial_no',''))),'')
    WHEN 'stock'      THEN nullif(lower(btrim(coalesce(p_d->>'site','')))||chr(1)||lower(btrim(coalesce(p_d->>'description',''))), chr(1))
    WHEN 'accident'   THEN nullif(lower(btrim(coalesce(nullif(btrim(coalesce(p_d->>'insurance_claim_no','')),''), p_d->>'police_report_no',''))),'')
    WHEN 'inspection' THEN nullif(lower(btrim(coalesce(p_d->>'asset_no',''))),'')||chr(1)||lower(btrim(coalesce(p_d->>'inspection_type','')))||chr(1)||lower(btrim(coalesce(p_d->>'inspection_date','')))||chr(1)||lower(btrim(coalesce(p_d->>'inspector','')))
    WHEN 'workorder'  THEN nullif(lower(btrim(coalesce(p_d->>'work_order_no',''))),'')
    WHEN 'warranty'   THEN nullif(lower(btrim(coalesce(p_d->>'serial_number','')))||chr(1)||lower(btrim(coalesce(p_d->>'claim_no',''))), chr(1))
    WHEN 'gatepass'   THEN nullif(lower(btrim(coalesce(p_d->>'asset_no',''))),'')||chr(1)||lower(btrim(coalesce(p_d->>'pass_date','')))
    WHEN 'supplier'   THEN nullif(lower(btrim(coalesce(nullif(btrim(coalesce(p_d->>'supplier_code','')),''), p_d->>'supplier_name',''))),'')
    WHEN 'driver'     THEN nullif(lower(btrim(coalesce(p_d->>'driver_id',''))),'')
    ELSE NULL END
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_reprocess_row(p_row_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b public.import_batches%ROWTYPE;r public.import_rows%ROWTYPE;batch uuid;org uuid:=public.app_current_org();
BEGIN
  IF auth.uid() IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false) THEN
    RAISE EXCEPTION 'Active organisation membership required.' USING ERRCODE='42501';
  END IF;
  SELECT batch_id INTO batch FROM public.import_rows WHERE id=p_row_id AND organisation_id=org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Staged row not found in your scope.' USING ERRCODE='42501';END IF;
  SELECT * INTO b FROM public.import_batches WHERE id=batch FOR UPDATE;
  IF NOT FOUND OR b.organisation_id IS DISTINCT FROM org OR NOT coalesce(public.import_user_can_commit_country(b.country),false)
     OR NOT coalesce(b.approval_status IN ('draft','pending_approval'),false) OR b.import_status IN ('committing','committed') THEN
    RAISE EXCEPTION 'Only an unapproved batch in your scope can be reprocessed.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO r FROM public.import_rows WHERE id=p_row_id AND batch_id=batch AND organisation_id=org FOR UPDATE;
  IF NOT FOUND OR r.target_record_id IS NOT NULL OR r.processed_at IS NOT NULL THEN
    RAISE EXCEPTION 'A linked or processed row cannot be reset.' USING ERRCODE='42501';
  END IF;
  IF NOT public.import_site_scope_ok(coalesce(nullif(r.transformed_data,'{}'::jsonb),r.mapped_data)->>'site') THEN
    RAISE EXCEPTION 'Staged row site is outside your scope.' USING ERRCODE='42501';
  END IF;
  UPDATE public.import_rows SET validation_status='pending',processed_at=NULL WHERE id=p_row_id;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_reverse_batch(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '120s'
AS $function$
declare
  b public.import_batches%rowtype;
  r public.import_rows%rowtype;
  v_org uuid := public.app_current_org();
  v_target text;
  v_deleted int := 0;
  v_skipped int := 0;
  v_hit int := 0;
begin
  if auth.uid() is null or v_org is null or not coalesce(public.app_is_active(),false) or not coalesce(public.app_can_admin_delete(),false) then
    raise exception 'Import reversal requires Admin or Super Admin.' using errcode = '42501';
  end if;
  select * into b from public.import_batches where id = p_batch_id FOR UPDATE;
  if not found then raise exception 'Import batch not found.'; end if;
  if b.organisation_id is distinct from v_org then
    raise exception 'Cross-organisation reversal denied.' using errcode = '42501';
  end if;
  if not coalesce(public.app_write_country_ok(b.country),false) then
    raise exception 'Cross-country reversal denied: you are not assigned to country %.', b.country using errcode = '42501';
  end if;
  
  IF EXISTS(SELECT 1 FROM public.import_rows WHERE batch_id=p_batch_id AND organisation_id IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'Staging ownership does not match the batch.' USING ERRCODE='42501';
  END IF;
  v_target := public.import_target_table(b.module);
  if v_target is null then raise exception 'No target table for module "%".', b.module; end if;
  
  for r in select * from public.import_rows where batch_id = p_batch_id and target_record_id is not null loop
    -- Exact duplicates and enriched rows existed before this import. Never
    -- delete them as if this batch created them.
    IF r.action IS DISTINCT FROM 'insert' OR r.dup_status IN ('duplicate','enriched') THEN
      v_skipped:=v_skipped+1;CONTINUE;
    END IF;
    execute format(
      'delete from public.%I t where id::text = $1 and organisation_id = $2 and country IS NOT DISTINCT FROM $3 and public.import_site_scope_ok(to_jsonb(t)->>''site'')',
      v_target
    ) using r.target_record_id, v_org, b.country;
    get diagnostics v_hit = row_count;
    if v_hit > 0 then
      update public.import_rows set target_record_id = null, processed_at = null where id = r.id;
      v_deleted := v_deleted + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;
  update public.import_batches
     set import_status = 'reversed', imported_rows = 0, completed_at = now()
   where id = p_batch_id;
  insert into public.import_audit_events (organisation_id, batch_id, actor, action, detail)
  values (v_org, p_batch_id, auth.uid(), 'reverse',
          jsonb_build_object('deleted', v_deleted, 'skipped', v_skipped, 'target', v_target));
  return jsonb_build_object('status', 'reversed', 'deleted', v_deleted, 'skipped', v_skipped);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_site_scope_ok(p_site text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT nullif(btrim(p_site),'') IS NULL OR coalesce(public.app_sees_all_sites(),false)
   OR coalesce(upper(btrim(p_site))=ANY(coalesce(public.app_site_scope(),'{}'::text[])),false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_target_table(p_module text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT (jsonb_build_object(
    'fleet','vehicle_fleet', 'tyre','tyre_records', 'stock','stock_records',
    'accident','accidents', 'inspection','inspections', 'workorder','work_orders',
    'warranty','warranty_claims', 'gatepass','gate_passes',
    'supplier','suppliers', 'driver','drivers'
  )) ->> p_module;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_user_can_commit_country(p_country text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    p_country IS NULL
    OR public.is_super_admin()
    OR EXISTS (
         SELECT 1 FROM public.profiles pr
         WHERE pr.id = auth.uid()
           AND ( p_country = ANY(pr.country) OR 'All' = ANY(pr.country) )
       );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.import_verify_landing(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  b public.import_batches%ROWTYPE; target text; org uuid:=public.app_current_org();
  expected integer:=0; landed integer:=0;
BEGIN
  IF auth.uid() IS NULL OR org IS NULL OR NOT coalesce(public.app_is_active(),false) THEN
    RAISE EXCEPTION 'Active organisation membership required.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO b FROM public.import_batches WHERE id=p_batch_id;
  IF NOT FOUND OR b.organisation_id IS DISTINCT FROM org OR NOT coalesce(public.import_user_can_commit_country(b.country),false) THEN
    RAISE EXCEPTION 'Import batch not found in your scope.' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.import_rows WHERE batch_id=p_batch_id AND organisation_id IS DISTINCT FROM org) THEN
    RAISE EXCEPTION 'Staging ownership does not match the import batch. Reconciliation is required.' USING ERRCODE='42501';
  END IF;
  target:=public.import_target_table(b.module);
  IF target IS NULL THEN RAISE EXCEPTION 'Unknown import destination.' USING ERRCODE='22023'; END IF;
  SELECT count(DISTINCT target_record_id) INTO expected FROM public.import_rows
    WHERE batch_id=p_batch_id AND target_record_id IS NOT NULL;
  EXECUTE format('SELECT count(DISTINCT r.target_record_id) FROM public.import_rows r JOIN public.%I t ON t.id::text=r.target_record_id AND t.organisation_id=$2 AND t.country IS NOT DISTINCT FROM $3 WHERE r.batch_id=$1 AND r.organisation_id=$2 AND r.target_record_id IS NOT NULL',target)
    INTO landed USING p_batch_id,org,b.country;
  -- This verifies destination existence and scope, not field equality or
  -- module-specific business correctness. A missing/foreign row remains dangling.
  RETURN jsonb_build_object('batch_id',p_batch_id,'module',b.module,'target_table',target,
    'status',b.import_status,'expected_distinct',expected,'landed_distinct',landed,
    'dangling',greatest(expected-landed,0),'scope_verified',true,'verified_at',now());
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.incident_change_severity(p_id uuid, p_severity text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_to text := lower(btrim(coalesce(p_severity, '')));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_inc public.platform_incidents%rowtype;
  v_upd uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can change incident severity' using errcode = '42501';
  end if;
  if v_to not in ('sev1', 'sev2', 'sev3', 'sev4') then
    raise exception 'Unknown severity' using errcode = '22023';
  end if;
  if char_length(v_reason) < 5 or char_length(v_reason) > 500 then
    raise exception 'A reason of 5 to 500 characters is required' using errcode = '22023';
  end if;
  select * into v_inc from public.platform_incidents where id = p_id for update;
  if not found then
    raise exception 'Incident not found' using errcode = 'P0002';
  end if;
  if v_inc.status = 'resolved' then
    raise exception 'A resolved incident cannot be re-graded' using errcode = '22023';
  end if;
  if v_inc.severity = v_to then
    return jsonb_build_object('ok', false, 'reason', 'unchanged');
  end if;
  update public.platform_incidents set severity = v_to where id = p_id;
  insert into public.platform_incident_updates (incident_id, status, message, author)
  values (p_id, v_inc.status,
          'Severity changed from ' || upper(v_inc.severity) || ' to ' || upper(v_to) || '. Reason: ' || v_reason,
          auth.uid())
  returning id into v_upd;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'incident_severity', p_id, 'platform_incident',
          jsonb_build_object('from', v_inc.severity, 'to', v_to, 'reason', v_reason, 'update_id', v_upd));
  return jsonb_build_object('ok', true, 'from', v_inc.severity, 'to', v_to);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.incident_reassign_commander(p_id uuid, p_user uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid    uuid := auth.uid();
  v_inc    public.platform_incidents%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_to     record;
  v_from_name text;
  v_to_name   text;
  v_upd    uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can reassign an incident' using errcode = '42501';
  end if;
  if char_length(v_reason) < 5 or char_length(v_reason) > 500 then
    raise exception 'A reason of 5 to 500 characters is required' using errcode = '22023';
  end if;
  select * into v_inc from public.platform_incidents where id = p_id for update;
  if not found then raise exception 'Incident not found' using errcode = 'P0002'; end if;

  select id, coalesce(full_name, email) as name, coalesce(is_super_admin, false) as sup,
         coalesce(locked, false) as locked
    into v_to from public.profiles where id = p_user;
  if not found then raise exception 'That user does not exist' using errcode = 'P0002'; end if;
  if not v_to.sup or v_to.locked then
    raise exception 'The commander must be an unlocked super admin' using errcode = '22023';
  end if;
  if v_inc.commander is not distinct from p_user then
    raise exception 'That person is already the commander' using errcode = '22023';
  end if;

  select coalesce(full_name, email) into v_from_name from public.profiles where id = v_inc.commander;
  v_to_name := v_to.name;

  update public.platform_incidents
     set commander = p_user,
         acknowledged_at = coalesce(acknowledged_at, now())
   where id = p_id;

  insert into public.platform_incident_updates (incident_id, status, message, author)
  values (p_id, v_inc.status,
          left('Commander changed from ' || coalesce(v_from_name, 'nobody') || ' to '
               || coalesce(v_to_name, 'a super admin') || '. Reason: ' || v_reason, 4000),
          v_uid)
  returning id into v_upd;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'incident_reassign_commander', p_id, 'platform_incident',
          jsonb_build_object('from', v_inc.commander, 'to', p_user, 'reason', v_reason, 'update_id', v_upd));

  if p_user is distinct from v_uid then
    begin
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      values (p_user, 'security', 'You are now incident commander: ' || v_inc.title,
              left('Reason: ' || v_reason, 500), 'platform_incident', p_id);
    exception when others then null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'id', p_id, 'from', v_inc.commander, 'to', p_user, 'update_id', v_upd);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.incident_save_postmortem(p_id uuid, p_summary text, p_root_cause text, p_actions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_inc     public.platform_incidents%rowtype;
  v_summary text := btrim(coalesce(p_summary, ''));
  v_root    text := btrim(coalesce(p_root_cause, ''));
  v_in      jsonb := coalesce(p_actions, '[]'::jsonb);
  v_actions jsonb := '[]'::jsonb;
  v_el      jsonb;
  v_text    text;
  v_due     text;
  v_first   boolean;
  v_upd     uuid;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then
    raise exception 'Only a super admin can write a postmortem' using errcode = '42501';
  end if;
  select * into v_inc from public.platform_incidents where id = p_id for update;
  if not found then raise exception 'Incident not found' using errcode = 'P0002'; end if;
  if v_inc.status <> 'resolved' then
    raise exception 'A postmortem can only be written once the incident is resolved' using errcode = '22023';
  end if;
  if char_length(v_summary) < 10 or char_length(v_summary) > 8000 then
    raise exception 'A summary of 10 to 8000 characters is required' using errcode = '22023';
  end if;
  if char_length(v_root) < 5 or char_length(v_root) > 4000 then
    raise exception 'A root cause of 5 to 4000 characters is required' using errcode = '22023';
  end if;
  if jsonb_typeof(v_in) <> 'array' then
    raise exception 'Actions must be a list' using errcode = '22023';
  end if;
  if jsonb_array_length(v_in) > 50 then
    raise exception 'A postmortem can carry at most 50 actions' using errcode = '22023';
  end if;

  for v_el in select value from jsonb_array_elements(v_in) loop
    if jsonb_typeof(v_el) <> 'object' then
      raise exception 'Each action must be an object' using errcode = '22023';
    end if;
    v_text := btrim(coalesce(v_el->>'action', ''));
    if v_text = '' then continue; end if;
    if char_length(v_text) > 500 then
      raise exception 'An action must be 500 characters or fewer' using errcode = '22023';
    end if;
    v_due := nullif(btrim(coalesce(v_el->>'due', '')), '');
    if v_due is not null and v_due !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'An action due date must be YYYY-MM-DD' using errcode = '22023';
    end if;
    v_actions := v_actions || jsonb_build_array(jsonb_build_object(
      'action', v_text,
      'owner', nullif(left(btrim(coalesce(v_el->>'owner', '')), 200), ''),
      'due', v_due,
      'done', case when jsonb_typeof(v_el->'done') = 'boolean' then (v_el->>'done')::boolean else false end));
  end loop;

  v_first := v_inc.postmortem_at is null;

  update public.platform_incidents
     set postmortem_summary = v_summary,
         postmortem_root_cause = v_root,
         postmortem_actions = v_actions,
         postmortem_at = now(),
         postmortem_by = v_uid
   where id = p_id;

  insert into public.platform_incident_updates (incident_id, status, message, author)
  values (p_id, 'resolved',
          case when v_first then 'Postmortem recorded.' else 'Postmortem updated.' end
            || ' ' || jsonb_array_length(v_actions) || ' follow-up action'
            || case when jsonb_array_length(v_actions) = 1 then '' else 's' end || '.',
          v_uid)
  returning id into v_upd;

  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (v_uid, 'incident_save_postmortem', p_id, 'platform_incident',
          jsonb_build_object('first', v_first, 'actions', jsonb_array_length(v_actions), 'update_id', v_upd));

  return jsonb_build_object('ok', true, 'id', p_id, 'first', v_first,
                            'actions', jsonb_array_length(v_actions), 'update_id', v_upd);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.incident_status_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select p_from = p_to or case p_from
    when 'investigating' then p_to in ('identified','monitoring','resolved')
    when 'identified'    then p_to in ('investigating','monitoring','resolved')
    when 'monitoring'    then p_to in ('investigating','identified','resolved')
    when 'resolved'      then p_to in ('investigating')
    else false end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.inspection_plan_best_match(p_plan_id uuid)
 RETURNS TABLE(id uuid, inspection_date date, status text, inspector text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select i.id, i.inspection_date, i.status, i.inspector
  from public.inspection_schedules p
  join public.inspections i
    on upper(btrim(i.asset_no)) = upper(btrim(p.asset_no))
   and i.organisation_id is not distinct from p.organisation_id
   and (i.country is null or p.country is null or i.country = p.country)
   and i.inspection_date >= p.scheduled_date - public.inspection_plan_early_days()
  where p.id = p_plan_id
    and not exists (
      select 1 from public.inspection_schedules q
      where q.id <> p.id
        and upper(btrim(q.asset_no)) = upper(btrim(p.asset_no))
        and q.organisation_id is not distinct from p.organisation_id
        and (q.country is null or p.country is null or q.country = p.country)
        and lower(coalesce(q.status, '')) not in ('cancelled', 'canceled')
        and q.scheduled_date > p.scheduled_date
        and q.scheduled_date <= i.inspection_date
    )
  order by (lower(coalesce(i.status, '')) = 'done') desc,
           abs(i.inspection_date - p.scheduled_date) asc, i.inspection_date asc, i.id asc
  limit 1
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.inspection_plan_early_days()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$ select 7 $function$;
-- @@
CREATE OR REPLACE FUNCTION public.inspection_plan_state(p_scheduled_date date, p_grace_days integer, p_status text, p_matched_status text, p_today date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when lower(coalesce(p_status, '')) = 'cancelled' then 'Cancelled'
    when p_matched_status is null and p_scheduled_date is null then 'Upcoming'
    when lower(coalesce(p_matched_status, '')) = 'done' then 'Done'
    when p_matched_status is not null then 'Started'
    when p_today > p_scheduled_date + make_interval(days => coalesce(p_grace_days, 2)) then 'Missed'
    when p_today >= p_scheduled_date then 'Due'
    else 'Upcoming'
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.is_admin_or_above()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT get_my_role() IN ('admin','manager','director');
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.is_approved_and_unlocked()
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT approved = true AND COALESCE(locked, false) = false
     FROM profiles WHERE id = auth.uid()),
    false
  )
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.is_elevated_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = auth.uid()
       AND lower(regexp_replace(COALESCE(role,''), '\s+', '_', 'g')) IN ('admin','manager','director')
  );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select p.is_super_admin from public.profiles p
                   where p.id = auth.uid() and p.locked = false), false)
     and (
       coalesce(auth.jwt() ->> 'aal', '') = 'aal2'
       or not exists (select 1 from auth.mfa_factors f
                      where f.user_id = auth.uid() and f.status = 'verified')
     );
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.jobcard_period(p_job text)
 RETURNS TABLE(mm integer, yy integer)
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT substring(g FROM 1 FOR 2)::int AS mm,
         2000 + substring(g FROM 3 FOR 2)::int AS yy
  FROM (SELECT (regexp_match(btrim(coalesce(p_job, '')), '(\d{4})\s*$'))[1] AS g) x
  WHERE x.g IS NOT NULL AND substring(x.g FROM 1 FOR 2)::int BETWEEN 1 AND 12;
$function$;
