CREATE OR REPLACE FUNCTION public.list_backup_snapshots(p_limit integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public,backups'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT COALESCE(jsonb_agg(s ORDER BY s.taken_at DESC),'[]'::jsonb) INTO v FROM (
    SELECT sn.id, sn.reason, sn.taken_at, sn.taken_by, sn.table_count, sn.total_rows,
      (SELECT COALESCE(jsonb_agg(jsonb_build_object('table_name',st.table_name,'row_count',st.row_count) ORDER BY st.table_name),'[]'::jsonb)
         FROM backups.snapshot_tables st WHERE st.snapshot_id = sn.id) AS tables
    FROM backups.snapshots sn ORDER BY sn.taken_at DESC LIMIT GREATEST(1,p_limit)
  ) s;
  RETURN v;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_profile_directory(p_ids uuid[] DEFAULT NULL::uuid[], p_search text DEFAULT NULL::text, p_limit integer DEFAULT 500, p_offset integer DEFAULT 0, p_roles text[] DEFAULT NULL::text[], p_active_only boolean DEFAULT false)
 RETURNS TABLE(id uuid, full_name text, username text, employee_id text, role text, country text[], sites text[], site text, approved boolean, locked boolean, org_id uuid, organisation_id uuid, avatar_url text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select public.app_current_org()                  as org,
           public.is_super_admin()                   as is_super,
           coalesce(public.app_is_active(), false)   as active
  ),
  term as (
    select nullif(
      replace(replace(replace(btrim(coalesce(p_search, '')), '\', '\\'), '%', '\%'), '_', '\_'),
      '') as t
  )
  select p.id, p.full_name, p.username, p.employee_id, p.role,
         p.country, p.sites, p.site, p.approved, p.locked,
         p.org_id, p.organisation_id, p.avatar_url
  from public.profiles p
  cross join me
  cross join term
  where me.active
    and (me.is_super or (me.org is not null and p.organisation_id = me.org))
    and (p_ids is null or p.id = any (p_ids))
    and (p_roles is null or p.role = any (p_roles))
    and (not coalesce(p_active_only, false)
         or (coalesce(p.approved, false) and not coalesce(p.locked, false)))
    and (term.t is null
         or p.full_name   ilike '%' || term.t || '%'
         or p.username    ilike '%' || term.t || '%'
         or p.employee_id ilike '%' || term.t || '%')
  order by p.full_name nulls last, p.id
  limit least(greatest(coalesce(p_limit, 500), 1), 1000)
  offset greatest(coalesce(p_offset, 0), 0)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_profile_private(p_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(id uuid, notes text, has_push_token boolean, push_token_updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select public.app_current_org()                 as org,
           public.is_super_admin()                  as is_super,
           coalesce(public.app_is_active(), false)  as active,
           coalesce(public.app_is_elevated(), false) as elevated
  )
  select p.id, p.notes,
         (p.push_token is not null and p.push_token <> '') as has_push_token,
         p.push_token_updated_at
  from public.profiles p
  cross join me
  where me.active
    and (me.is_super or (me.elevated and me.org is not null and p.organisation_id = me.org))
    and (p_ids is null or p.id = any (p_ids))
  order by p.id
  limit 1000
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_scrapped_tyres(p_search text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_q   text := nullif(btrim(coalesce(p_search, '')), '');
  v_lim int  := least(greatest(coalesce(p_limit, 500), 1), 2000);
  result jsonb;
begin
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null or not public.app_is_active() then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  with marked as (
    select m.serial, m.reason, m.created_at as scrapped_at, m.created_by,
           coalesce(m.country, '') as mark_country
      from public.tyre_status_marks m
     where m.mark_type = 'scrap'
       and m.organisation_id = v_org
  ), rec as (
    select distinct on (upper(btrim(t.serial_no)))
           t.id, t.serial_no, t.asset_no, t.tyre_position, t.brand, t.size, t.site,
           t.country, t.cost_per_tyre, t.issue_date, t.removal_date, t.status,
           t.removal_reason, t.job_card, t.total_km, t.km_at_fitment, t.km_at_removal,
           t.tread_depth, t.vehicle_type as tyre_vehicle_type
      from public.tyre_records t
     where t.organisation_id = v_org
       and nullif(btrim(coalesce(t.serial_no, '')), '') is not null
     order by upper(btrim(t.serial_no)), t.issue_date desc nulls last, t.created_at desc nulls last
  ), joined as (
    select coalesce(m.serial, upper(btrim(r.serial_no))) as serial,
           r.id as tyre_record_id,
           r.asset_no, r.tyre_position, r.brand, r.size, r.site,
           coalesce(nullif(m.mark_country, ''), r.country) as country,
           r.cost_per_tyre, r.issue_date, r.removal_date, r.removal_reason,
           r.job_card, r.tread_depth,
           public.tyre_km_life(r.km_at_fitment, r.km_at_removal, r.total_km, r.tyre_vehicle_type) as km_run,
           coalesce(m.reason, r.removal_reason) as reason,
           m.scrapped_at, m.created_by,
           (m.serial is not null) as marked
      from marked m
      full outer join rec r on upper(btrim(r.serial_no)) = m.serial
     where m.serial is not null
        or coalesce(r.status, '') = 'Scrapped'
  ), enriched as (
    select j.*,
           coalesce(nullif(btrim(p.full_name), ''), p.username, p.email) as scrapped_by_name,
           w.status      as job_card_status,
           w.work_type   as job_card_type,
           left(coalesce(nullif(btrim(w.description), ''), nullif(btrim(w.notes), '')), 120) as job_card_complaint,
           w.opened_at::date as job_card_opened,
           v.vehicle_type, v.make, v.model,
           d.status as disposal_status
      from joined j
      left join public.profiles p on p.id = j.created_by
      left join public.work_orders w
        on w.organisation_id = v_org and w.work_order_no = j.job_card
      left join lateral (
        select f.vehicle_type, f.make, f.model
          from public.vehicle_fleet f
         where f.organisation_id = v_org
           and f.asset_no = j.asset_no
           and (j.country is null or f.country is null or f.country = j.country)
         order by (f.country = j.country) desc nulls last
         limit 1
      ) v on true
      left join public.tyre_disposals d on d.tyre_record_id = j.tyre_record_id
  ), visible as (
    select * from enriched
     where (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
       and (v_q is null
            or serial   ilike '%' || v_q || '%'
            or coalesce(asset_no, '')         ilike '%' || v_q || '%'
            or coalesce(brand, '')            ilike '%' || v_q || '%'
            or coalesce(reason, '')           ilike '%' || v_q || '%'
            or coalesce(job_card, '')         ilike '%' || v_q || '%'
            or coalesce(scrapped_by_name, '') ilike '%' || v_q || '%')
  )
  select jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'total',              (select count(*) from visible),
    'marked_total',       (select count(*) from visible where marked),
    'unattributed_total', (select count(*) from visible where not marked),
    'linked', jsonb_build_object(
      'with_job_card', (select count(*) from visible where job_card is not null),
      'with_cost',     (select count(*) from visible where cost_per_tyre is not null),
      'with_km',       (select count(*) from visible where km_run is not null),
      'with_disposal', (select count(*) from visible where disposal_status is not null)),
    'search',  v_q,
    'country', p_country,
    'truncated', (select count(*) from visible) > v_lim,
    'rows', (select coalesce(jsonb_agg(to_jsonb(x) order by x.scrapped_at desc nulls last, x.serial), '[]'::jsonb)
               from (select * from visible
                      order by scrapped_at desc nulls last, serial
                      limit v_lim) x)
  ) into result;

  return result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_tyre_import_reviews(p_country text DEFAULT NULL::text, p_include_resolved boolean DEFAULT false, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if v_org is null or not public.app_is_elevated() then
    raise exception 'You do not have permission to review tyre imports' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(row_to_json(z) order by z.logged_at desc) from (
      select a.id, a.logged_at, a.country, a.reason, a.resolution, a.resolved_at,
             a.payload->>'veh_no' as asset_no, a.payload->>'tyre_position' as position,
             a.payload->>'tyre_no' as serial_no, a.payload->>'tyre_fix_date' as fitment_date,
             a.payload->>'fixed_km' as fitment_km, a.payload->>'job_card_no' as job_card,
             t.serial_no as current_serial, coalesce(t.issue_date, t.fitment_date) as current_fitment_date,
             t.km_at_fitment as current_fitment_km
      from public.stg_monthly_tyres_audit a
      left join public.tyre_records t on t.id = a.tyre_record_id
      where a.reason like 'replacement_needs_review%'
        and coalesce(a.organisation_id, '00000000-0000-0000-0000-000000000001'::uuid) = v_org
        and (p_include_resolved or a.resolved_at is null)
        and (nullif(btrim(coalesce(p_country, '')), '') is null or lower(p_country) = 'all'
             or public.normalize_country(a.country) = public.normalize_country(p_country))
        and (a.country is null or public.app_can_see_country(public.normalize_country(a.country)))
      order by a.logged_at desc
      limit greatest(1, least(coalesce(p_limit, 500), 2000))) z), '[]'::jsonb);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_tyre_replacement_batches(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if v_org is null or not public.app_is_elevated() then
    raise exception 'You do not have permission to view tyre replacements' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(row_to_json(z) order by z.last_at desc) from (
    select batch_id, source, min(country) as country, count(*) as rows_closed,
           count(*) filter (where undone_at is not null) as rows_undone, max(created_at) as last_at
    from public.tyre_replacement_log where organisation_id = v_org
      and (public.is_super_admin() or batch_id not in (
            select x.batch_id from public.tyre_replacement_log x
            left join public.tyre_records t on t.id = x.tyre_id
            where x.organisation_id = v_org and x.batch_id is not null
              and (   (x.country is not null and public.app_can_see_country(x.country) is not true) or (t.id is not null and t.country is not null and public.app_can_see_country(t.country) is not true) or (t.id is not null and nullif(btrim(coalesce(t.site, '')), '') is not null and public.app_can_see_site(t.site) is not true))))
    group by batch_id, source order by max(created_at) desc
    limit greatest(1, least(coalesce(p_limit, 50), 500))) z), '[]'::jsonb);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.list_upload_feed_candidates()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_out jsonb;
begin
  if not public.is_super_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x.already desc, x.table_name), '[]'::jsonb)
    into v_out
  from (
    select t.table_name,
           exists (select 1 from public.upload_feeds f where f.table_name = t.table_name) as already,
           (select coalesce(jsonb_agg(c.column_name order by c.column_name), '[]'::jsonb)
              from information_schema.columns c
             where c.table_schema = 'public' and c.table_name = t.table_name
               and c.data_type in ('date', 'timestamp with time zone', 'timestamp without time zone')
           ) as date_columns,
           (select coalesce(jsonb_agg(c.column_name order by c.column_name), '[]'::jsonb)
              from information_schema.columns c
             where c.table_schema = 'public' and c.table_name = t.table_name
               and c.column_name in ('site', 'location', 'store_code', 'branch')
           ) as site_columns,
           (select n_live_tup from pg_stat_user_tables s
             where s.schemaname = 'public' and s.relname = t.table_name) as approx_rows
      from information_schema.tables t
     where t.table_schema = 'public' and t.table_type = 'BASE TABLE'
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = t.table_name
                      and c.column_name = 'organisation_id')
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = t.table_name
                      and c.column_name = 'country')
       and exists (select 1 from information_schema.columns c
                    where c.table_schema = 'public' and c.table_name = t.table_name
                      and c.data_type in ('date', 'timestamp with time zone', 'timestamp without time zone'))
  ) x;

  return jsonb_build_object('ok', true, 'tables', v_out);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.lock_inspection_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role    text;
  allowed   text[] := ARRAY['approval_status','approver_email','approver_signature',
                            'approved_at','approved_by','locked','locked_at',
                            'completed_date','linked_action_id','approval_revision','approval_workflow_id','approval_policy_required','approval_outcome'];
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'Done' AND NEW.locked IS NOT TRUE THEN
      NEW.locked := true; NEW.locked_at := now();
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = 'Done' AND (OLD.status IS DISTINCT FROM 'Done') AND NEW.locked IS NOT TRUE THEN
    NEW.locked := true; NEW.locked_at := now();
  END IF;

  IF OLD.locked IS TRUE THEN
    SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
    IF lower(btrim(COALESCE(v_role,''))) NOT IN ('admin','manager','director')
       AND NOT COALESCE(public.is_super_admin(), false) THEN
      IF (to_jsonb(OLD) - allowed) IS DISTINCT FROM (to_jsonb(NEW) - allowed) THEN
        RAISE EXCEPTION 'This inspection checklist is locked and cannot be edited.';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_access_audit_generic()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity text; v_target uuid; v_before jsonb; v_after jsonb;
  v_reason text := nullif(btrim(coalesce(current_setting('app.access_reason', true), '')), '');
BEGIN
  IF TG_TABLE_NAME = 'user_access_grants' THEN
    v_entity := 'grant'; v_target := COALESCE(NEW.user_id, OLD.user_id);
  ELSIF TG_TABLE_NAME = 'module_permissions' THEN
    v_entity := 'module_perm'; v_target := NULL;
  ELSIF TG_TABLE_NAME = 'custom_roles' THEN
    v_entity := 'custom_role'; v_target := NULL;
  ELSE
    v_entity := TG_TABLE_NAME; v_target := NULL;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_before := to_jsonb(OLD); v_after := NULL;
  ELSIF TG_OP = 'INSERT' THEN
    v_before := NULL; v_after := to_jsonb(NEW);
  ELSE
    v_before := to_jsonb(OLD); v_after := to_jsonb(NEW);
  END IF;
  INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
  VALUES (auth.uid(), public.access_audit_actor_email(), TG_OP, v_target, v_entity, v_before, v_after, left(v_reason, 500));
  RETURN NULL;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_access_audit_profiles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_email text := public.access_audit_actor_email(); v_actor uuid := auth.uid();
  v_reason text := left(nullif(btrim(coalesce(current_setting('app.access_reason', true), '')), ''), 500);
BEGIN
  IF OLD.role IS DISTINCT FROM NEW.role THEN
    INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
    VALUES (v_actor, v_email, TG_OP, NEW.id, 'role', jsonb_build_object('role', OLD.role), jsonb_build_object('role', NEW.role), v_reason);
  END IF;
  IF OLD.country IS DISTINCT FROM NEW.country THEN
    INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
    VALUES (v_actor, v_email, TG_OP, NEW.id, 'country', jsonb_build_object('country', to_jsonb(OLD.country)), jsonb_build_object('country', to_jsonb(NEW.country)), v_reason);
  END IF;
  IF OLD.locked IS DISTINCT FROM NEW.locked THEN
    INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
    VALUES (v_actor, v_email, TG_OP, NEW.id, 'lock', jsonb_build_object('locked', OLD.locked), jsonb_build_object('locked', NEW.locked), v_reason);
  END IF;
  IF OLD.approved IS DISTINCT FROM NEW.approved THEN
    INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
    VALUES (v_actor, v_email, TG_OP, NEW.id, 'approve', jsonb_build_object('approved', OLD.approved), jsonb_build_object('approved', NEW.approved), v_reason);
  END IF;
  IF OLD.is_super_admin IS DISTINCT FROM NEW.is_super_admin THEN
    INSERT INTO public.access_audit (actor, actor_email, action, target_user, entity, before, after, reason)
    VALUES (v_actor, v_email, TG_OP, NEW.id, 'super_admin', jsonb_build_object('is_super_admin', OLD.is_super_admin), jsonb_build_object('is_super_admin', NEW.is_super_admin), v_reason);
  END IF;
  RETURN NULL;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_accident_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
  v_old    JSONB;
  v_new    JSONB;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_action := CASE
      WHEN OLD.status IS DISTINCT FROM NEW.status THEN 'status_change'
      ELSE 'field_update'
    END;
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    IF v_old IS DISTINCT FROM v_new THEN
      INSERT INTO public.accident_audit_log
        (accident_id, changed_by, action, old_values, new_values)
      VALUES
        (NEW.id, auth.uid(), v_action, v_old, v_new);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    -- captured by the generic audit_log_v2 trigger; inserting here would violate
    -- accident_audit_log's FK to a now-deleted accident.
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_accident_part_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.accident_audit_log (accident_id, changed_by, action, old_values, new_values)
    VALUES (NEW.accident_id, auth.uid(), 'part_added', NULL, to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN
      INSERT INTO public.accident_audit_log (accident_id, changed_by, action, old_values, new_values)
      VALUES (NEW.accident_id, auth.uid(), 'part_updated', to_jsonb(OLD), to_jsonb(NEW));
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    -- Only log a genuine single-part removal. When the whole accident is being
    -- deleted, the cascade removes its parts and the accident row no longer
    -- exists, so inserting here would violate accident_audit_log's FK.
    IF EXISTS (SELECT 1 FROM public.accidents WHERE id = OLD.accident_id) THEN
      INSERT INTO public.accident_audit_log (accident_id, changed_by, action, old_values, new_values)
      VALUES (OLD.accident_id, auth.uid(), 'part_removed', to_jsonb(OLD), NULL);
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_client_error(p_severity text, p_source text, p_message text, p_module_id text DEFAULT NULL::text, p_detail jsonb DEFAULT NULL::jsonb, p_reference_id text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_device text DEFAULT NULL::text, p_screen text DEFAULT NULL::text, p_fingerprint text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_msg     text := left(btrim(coalesce(p_message, '')), 2000);
  v_sev     text := lower(btrim(coalesce(p_severity, 'error')));
  v_detail  jsonb := p_detail;
  v_bucket  timestamptz := date_trunc('minute', now());
  v_ip      text;
  v_key     text;
  v_n       int;
  v_global  int;
begin
  if v_msg = '' then return false; end if;

  if v_sev not in ('info', 'warning', 'error', 'critical') then v_sev := 'error'; end if;
  if v_uid is null and v_sev = 'critical' then v_sev := 'error'; end if;

  if v_detail is not null
     and (jsonb_typeof(v_detail) <> 'object' or pg_column_size(v_detail) > 4096) then
    v_detail := jsonb_build_object('truncated', true);
  end if;

  if v_uid is not null then
    v_key := 'u:' || v_uid::text;
  else
    begin
      select coalesce(nullif(h ->> 'cf-connecting-ip', ''),
                      nullif(btrim(split_part(h ->> 'x-forwarded-for', ',', 1)), ''),
                      nullif(h ->> 'x-real-ip', ''),
                      'unknown')
        into v_ip
        from (select current_setting('request.headers', true)::jsonb as h) s;
    exception when others then
      v_ip := 'unknown';
    end;
    v_key := 'a:' || left(coalesce(v_ip, 'unknown'), 64);
  end if;

  insert into public.client_error_rate as r (rkey, bucket, n) values (v_key, v_bucket, 1)
  on conflict (rkey, bucket) do update set n = r.n + 1
  returning r.n into v_n;

  if v_uid is null then
    insert into public.client_error_rate as r (rkey, bucket, n) values ('a:*', v_bucket, 1)
    on conflict (rkey, bucket) do update set n = r.n + 1
    returning r.n into v_global;
    if v_n > 10 or v_global > 60 then return false; end if;
  elsif v_n > 30 then
    return false;
  end if;

  delete from public.client_error_rate where bucket < now() - interval '10 minutes';

  insert into public.system_logs
    (organisation_id, module_id, severity, source, message, detail, reference_id, url, user_id, user_email,
     platform, app_version, device, screen, error_fingerprint)
  values
    (public.app_current_org(),
     nullif(left(btrim(coalesce(p_module_id, '')), 100), ''),
     v_sev,
     nullif(left(btrim(coalesce(p_source, '')), 200), ''),
     v_msg,
     coalesce(v_detail, '{}'::jsonb),
     nullif(left(btrim(coalesce(p_reference_id, '')), 100), ''),
     nullif(left(btrim(coalesce(p_url, '')), 1000), ''),
     v_uid,
     null,
     case when lower(btrim(coalesce(p_platform, ''))) in ('web', 'flutter', 'expo')
          then lower(btrim(p_platform)) end,
     nullif(left(btrim(coalesce(p_app_version, '')), 40), ''),
     nullif(left(btrim(coalesce(p_device, '')), 200), ''),
     nullif(left(btrim(coalesce(p_screen, '')), 300), ''),
     nullif(left(btrim(coalesce(p_fingerprint, '')), 300), ''));
  return true;
exception when others then
  return false;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_console_action(p_action text, p_target_id uuid DEFAULT NULL::uuid, p_target_type text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is not null and not public.is_super_admin() then
    raise exception 'Permission denied: super admin required' using errcode = '42501';
  end if;
  insert into console_sessions(admin_id,action,target_id,target_type,details)
  values(auth.uid(),p_action,p_target_id,p_target_type,p_details) returning id into v_id;
  return v_id;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_console_event(p_action text, p_target_id text DEFAULT NULL::text, p_target_type text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_target_text text := nullif(btrim(p_target_id), '');
  v_target_uuid uuid;
  v_details     jsonb := coalesce(p_details, '{}'::jsonb);
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Permission denied: super admin required'
      USING errcode = '42501';
  END IF;

  IF v_target_text IS NOT NULL THEN
    BEGIN
      v_target_uuid := v_target_text::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      v_target_uuid := NULL;
      v_details := v_details ||
        jsonb_build_object('target_id_text', v_target_text);
    END;
  END IF;

  INSERT INTO public.console_sessions
    (admin_id, action, target_id, target_type, details)
  VALUES
    (auth.uid(), p_action, v_target_uuid, p_target_type, v_details);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_inspection_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_old    jsonb;
  v_new    jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- captured by the generic audit_log_v2 trigger; inserting here would violate
    -- inspection_audit_log's FK to a now-deleted inspection.
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    v_action := 'created';
    v_new    := to_jsonb(NEW) - 'inspector_signature' - 'approver_signature';
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD) - 'inspector_signature' - 'approver_signature';
    v_new := to_jsonb(NEW) - 'inspector_signature' - 'approver_signature';
    IF v_old = v_new THEN RETURN NEW; END IF;
    v_action := CASE
      WHEN NEW.approval_status = 'approved'  AND OLD.approval_status != 'approved'  THEN 'approved'
      WHEN NEW.approval_status = 'rejected'  AND OLD.approval_status != 'rejected'  THEN 'rejected'
      WHEN NEW.approval_status = 'pending_approval' THEN 'submitted_for_approval'
      ELSE 'updated'
    END;
  END IF;

  INSERT INTO public.inspection_audit_log (inspection_id, changed_by, action, old_values, new_values)
  VALUES (COALESCE(NEW.id, OLD.id), auth.uid(), v_action, v_old, v_new);

  RETURN COALESCE(NEW, OLD);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_rfid_tag_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text; v_name text; v_from text; v_to text;
begin
  select coalesce(nullif(btrim(full_name), ''), username) into v_name from public.profiles where id = auth.uid();
  if tg_op = 'INSERT' then
    insert into public.rfid_tag_events (organisation_id, country, tag_row_id, tag_id, action,
      to_asset_no, to_tyre_serial, to_status, to_site, actor_id, actor_name)
    values (new.organisation_id, new.country, new.id, new.tag_id, 'registered',
      new.asset_no, new.tyre_serial, new.status, new.site, auth.uid(), v_name);
    return new;
  elsif tg_op = 'DELETE' then
    insert into public.rfid_tag_events (organisation_id, country, tag_row_id, tag_id, action,
      from_asset_no, from_tyre_serial, from_status, from_site, actor_id, actor_name)
    values (old.organisation_id, old.country, old.id, old.tag_id, 'deleted',
      old.asset_no, old.tyre_serial, old.status, old.site, auth.uid(), v_name);
    return old;
  end if;
  if new.tag_id is not distinct from old.tag_id and new.asset_no is not distinct from old.asset_no
     and new.tyre_serial is not distinct from old.tyre_serial and new.status is not distinct from old.status
     and new.site is not distinct from old.site and new.notes is not distinct from old.notes then
    return new;
  end if;
  v_from := coalesce(nullif(btrim(old.asset_no), ''), nullif(btrim(old.tyre_serial), ''));
  v_to := coalesce(nullif(btrim(new.asset_no), ''), nullif(btrim(new.tyre_serial), ''));
  if new.status = 'retired' and old.status is distinct from 'retired' then v_action := 'retired';
  elsif old.status = 'retired' and new.status is distinct from 'retired' then v_action := 'reactivated';
  elsif v_from is null and v_to is not null then v_action := 'assigned';
  elsif v_from is not null and v_to is null then v_action := 'unassigned';
  elsif v_from is distinct from v_to then v_action := 'reassigned';
  elsif new.site is distinct from old.site then v_action := 'moved';
  else v_action := 'edited';
  end if;
  insert into public.rfid_tag_events (organisation_id, country, tag_row_id, tag_id, action,
    from_asset_no, to_asset_no, from_tyre_serial, to_tyre_serial, from_status, to_status, from_site, to_site, actor_id, actor_name)
  values (new.organisation_id, new.country, new.id, new.tag_id, v_action,
    old.asset_no, new.asset_no, old.tyre_serial, new.tyre_serial, old.status, new.status, old.site, new.site, auth.uid(), v_name);
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.log_vehicle_ops_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.ops_status is null then return new; end if;
  elsif new.ops_status is not distinct from old.ops_status then
    return new;
  end if;
  insert into public.vehicle_ops_status_events
    (organisation_id, vehicle_id, asset_no, country, site, old_status, new_status, note, changed_by, changed_at)
  values
    (new.organisation_id, new.id, new.asset_no, new.country, new.site,
     case when tg_op = 'UPDATE' then old.ops_status end, new.ops_status, new.ops_status_note,
     auth.uid(), now());
  return new;
exception when others then
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.login_attempt_status(p_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key text := lower(btrim(coalesce(p_identifier, '')));
  v_max int := public._login_max_attempts();
  v_win int := public._login_window_minutes();
  r public.login_attempts%rowtype;
  v_used int := 0;
begin
  if v_max = 0 or v_key = '' then
    return jsonb_build_object('enabled', v_max <> 0, 'locked', false);
  end if;
  select * into r from public.login_attempts where identifier = v_key;
  if found and r.locked_until is not null and r.locked_until > now() then
    return jsonb_build_object('enabled', true, 'locked', true,
      'retry_after_seconds', greatest(0, ceil(extract(epoch from (r.locked_until - now())))::int));
  end if;
  if found and r.window_started_at > now() - make_interval(mins => v_win) then
    v_used := r.attempt_count;
  end if;
  return jsonb_build_object('enabled', true, 'locked', false,
    'remaining', greatest(0, v_max - v_used));
exception when others then
  return jsonb_build_object('enabled', false, 'locked', false);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.mark_checklist_form_reviewed(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_row public.checklist_templates;
begin
  if not (public.get_my_role() = any (array['Admin','Manager','Director','Maintenance Supervisor']) or public.is_super_admin()) then
    raise exception 'You do not have permission to review checklist forms' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(full_name), ''), username, email) into v_name from public.profiles where id = auth.uid();
  update public.checklist_templates
     set last_reviewed_at = now(), last_reviewed_by = auth.uid(), last_reviewed_name = v_name,
         form_approved_by = coalesce(form_approved_by, auth.uid()),
         form_approved_name = coalesce(form_approved_name, v_name),
         form_approved_at = case when form_approved_name is null then now() else form_approved_at end
   where id = p_template_id and organisation_id is not distinct from public.app_current_org()
  returning * into v_row;
  if not found then raise exception 'Checklist form not found' using errcode = 'P0002'; end if;
  return jsonb_build_object('ok', true, 'last_reviewed_at', v_row.last_reviewed_at, 'last_reviewed_name', v_row.last_reviewed_name);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.mark_notification_read(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.notifications SET read = true WHERE id = p_id AND user_id = auth.uid();
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.mask_email_for_console(p_email text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  select case
    when p_email is null or position('@' in p_email) = 0 then null
    else left(split_part(p_email, '@', 1), 1) || '***@' || split_part(p_email, '@', 2)
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.master_clean_token(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(
           upper(regexp_replace(btrim(coalesce(p,''), E' \t\r\n'), '\s+', ' ', 'g')),
           ''
         )
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.master_clean_value(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when public.master_clean_token(p) in ('NULL','N/A','NA','-','#N/A') then null
    else public.master_clean_token(p)
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.master_parse_date(p text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v text := public.master_clean_value(p); d date;
begin
  if v is null then return null; end if;
  begin d := public.erp_parse_date(v); exception when others then d := null; end;
  if d is not null then return d; end if;
  if v ~ '^\d{1,2}-\d{1,2}-\d{2}$' then
    begin return to_date(v, 'DD-MM-YY'); exception when others then return null; end;
  end if;
  if v ~ '^\d{1,2}/\d{1,2}/\d{2}$' then
    begin return to_date(v, 'DD/MM/YY'); exception when others then return null; end;
  end if;
  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.match_inspection_findings(query_embedding public.vector, match_count integer DEFAULT 10, filter_site text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, inspection_id uuid, asset_no text, site text, content text, similarity double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT
    ie.id,
    ie.inspection_id,
    ie.asset_no,
    coalesce(ie.site, i.site) AS site,
    ie.content,
    1 - (ie.embedding OPERATOR(public.<=>) query_embedding) AS similarity
  FROM public.inspection_embeddings ie
  JOIN public.inspections i ON i.id = ie.inspection_id
  WHERE ie.embedding IS NOT NULL
    AND i.organisation_id = (SELECT public.app_current_org())
    AND (
      i.country IS NULL
      OR (SELECT public.app_is_org_admin())
      OR (SELECT public.app_sees_all_countries())
      OR lower(btrim(i.country)) = ANY (
        coalesce((SELECT public.app_country_scope()), '{}'::text[])
      )
    )
    AND (
      filter_site IS NULL
      OR ie.site = filter_site
      OR (ie.site IS NULL AND i.site = filter_site)
    )
  ORDER BY ie.embedding OPERATOR(public.<=>) query_embedding
  LIMIT least(greatest(coalesce(match_count, 10), 1), 100);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.match_knowledge_documents(query_embedding public.vector, match_count integer DEFAULT 5, filter_doc_type text DEFAULT NULL::text, filter_site text DEFAULT NULL::text, filter_org uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, document_id uuid, title text, version integer, status text, content text, doc_type text, site text, page_from integer, page_to integer, chunk_index integer, effective_from date, review_due date, similarity double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select kd.id,
         coalesce(p.id, kd.id)                       as document_id,
         coalesce(p.title, kd.title)                 as title,
         coalesce(p.version, kd.version)             as version,
         coalesce(p.status, kd.status)               as status,
         kd.content,
         coalesce(p.doc_type, kd.doc_type)           as doc_type,
         coalesce(p.site, kd.site)                   as site,
         kd.page_from,
         kd.page_to,
         kd.chunk_index,
         coalesce(p.effective_from, kd.effective_from) as effective_from,
         coalesce(p.review_due, kd.review_due)       as review_due,
         1 - (kd.embedding <=> query_embedding)      as similarity
  from public.knowledge_documents kd
  left join public.knowledge_documents p
         on p.id = kd.chunk_of and p.organisation_id = kd.organisation_id
  where kd.embedding is not null
    and not (kd.chunk_of is null and coalesce(kd.chunk_count, 0) > 0)
    and (kd.chunk_of is null or p.id is not null)
    and kd.organisation_id = coalesce(filter_org, public.app_current_org())
    and (filter_org is null
         or public.app_current_org() is null
         or filter_org = public.app_current_org()
         or public.is_super_admin())
    and coalesce(p.status, kd.status) = 'approved'
    and (coalesce(p.effective_from, kd.effective_from) is null
         or coalesce(p.effective_from, kd.effective_from) <= current_date)
    and (coalesce(p.expires_at, kd.expires_at) is null
         or coalesce(p.expires_at, kd.expires_at) > current_date)
    and (filter_doc_type is null or coalesce(p.doc_type, kd.doc_type) = filter_doc_type)
    and (filter_site is null or coalesce(p.site, kd.site) = filter_site)
  order by kd.embedding <=> query_embedding
  limit least(greatest(match_count, 1), 20);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_category_bucket(p_category text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_category
    when 'tyre'      then 'tyre'
    when 'lubricant' then 'oil'
    when 'fuel'      then 'oil'
    else 'spare'
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_category_for(p_country text, p_item_code text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Only a REVIEWED decision is authoritative. NULL means "fall back to the patterns".
  select m.category
    from public.material_master m
   where m.organisation_id = coalesce(public.app_current_org(),
                                      '00000000-0000-0000-0000-000000000001'::uuid)
     and m.country = p_country
     and (p_country is null or public.app_can_see_country(p_country) is not false)
     and m.item_code = upper(btrim(coalesce(p_item_code, '')))
     and m.reviewed
   limit 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_issue_cascade_doctype()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.doc_type is distinct from old.doc_type then
    update public.material_issue_lines set doc_type = new.doc_type
     where issue_id = new.id and doc_type is distinct from new.doc_type;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_issue_line_stamp_doctype()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_doc text;
begin
  select h.doc_type into v_doc from public.material_issues h where h.id = new.issue_id;
  if v_doc is null then
    raise exception 'Material issue % does not exist', new.issue_id using errcode = '23503';
  end if;
  new.doc_type := v_doc;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_issue_mint_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.doc_type := upper(btrim(coalesce(new.doc_type, 'MIS')));
  if nullif(btrim(coalesce(new.issue_number, '')), '') is null then
    new.issue_number := public.next_material_issue_no(new.organisation_id, new.country, new.doc_type, new.issued_at);
  else
    new.issue_number := upper(btrim(new.issue_number));
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_master_coverage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_out jsonb;
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  v_org := coalesce(v_org, '00000000-0000-0000-0000-000000000001'::uuid);

  select jsonb_build_object(
    'codes_total',       count(*),
    'codes_reviewed',    count(*) filter (where reviewed),
    'codes_conflicting', count(*) filter (where conflicting),
    'codes_unclassified',count(*) filter (where category = 'unclassified'),
    'value_total',       round(coalesce(sum(txn_value), 0), 2),
    'value_reviewed',    round(coalesce(sum(txn_value) filter (where reviewed), 0), 2),
    -- null, not 0, when there is no money to divide by: an honest "not measurable"
    'reviewed_value_share', case
      when coalesce(sum(txn_value), 0) > 0
        then round(100.0 * coalesce(sum(txn_value) filter (where reviewed), 0) / sum(txn_value), 1)
      else null end
  ) into v_out
  from public.material_master
  where organisation_id = v_org and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])));

  return coalesce(v_out, '{}'::jsonb);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_master_derive()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org       uuid := public.app_current_org();
  v_inserted  bigint := 0;
  v_updated   bigint := 0;
  v_conflicts bigint := 0;
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  v_org := coalesce(v_org, '00000000-0000-0000-0000-000000000001'::uuid);

  with src as (
    select p.country,
           upper(btrim(p.item_code)) as item_code,
           p.item_description,
           case
             when p.cost_category = 'tyre'  then 'tyre'
             when p.cost_category = 'oil'   then 'lubricant'
             when p.cost_category = 'spare' then 'spare_part'
             when public.parts_is_tyre(p.item_description) then 'tyre'
             when public.parts_is_oil(p.item_description)  then 'lubricant'
             else 'spare_part'
           end as category,
           coalesce(p.line_cost, 0) as line_cost
      from public.parts_consumption p
     where p.organisation_id = v_org
       and coalesce(btrim(p.item_code), '') <> ''
       and p.country is not null
       -- V566: derive only over countries this caller may write.
       and (p.country is null
            or (select public.is_super_admin())
            or (select public.app_sees_all_countries())
            or lower(btrim(p.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  cat as (
    select country, item_code, category, n,
           row_number() over (partition by country, item_code order by n desc, category asc) as rk,
           count(*) over (partition by country, item_code) as distinct_cats
      from (select country, item_code, category, count(*) as n
              from src group by country, item_code, category) c
  ),
  nm as (
    select country, item_code, item_description, n,
           row_number() over (partition by country, item_code
                              order by n desc, item_description asc) as rk
      from (select country, item_code, item_description, count(*) as n
              from src where coalesce(btrim(item_description), '') <> ''
             group by country, item_code, item_description) d
  ),
  tot as (
    select country, item_code, count(*) as rows_n, round(sum(line_cost), 2) as value_n
      from src group by country, item_code
  ),
  proposal as (
    select t.country, t.item_code, nm.item_description as item_name, cat.category,
           (cat.distinct_cats > 1) as conflicting, t.rows_n, t.value_n
      from tot t
      join cat on cat.country = t.country and cat.item_code = t.item_code and cat.rk = 1
      left join nm on nm.country = t.country and nm.item_code = t.item_code and nm.rk = 1
  ),
  ins as (
    insert into public.material_master
      (organisation_id, country, item_code, item_name, category, brand, conflicting,
       proposed_from, txn_rows, txn_value)
    select v_org, pr.country, pr.item_code, pr.item_name, pr.category,
           public.parts_brand(pr.item_name), pr.conflicting,
           case when pr.conflicting then 'majority of conflicting rows' else 'transactions' end,
           pr.rows_n, pr.value_n
      from proposal pr
    on conflict (organisation_id, country, item_code) do update
       set item_name     = case when public.material_master.reviewed
                                then public.material_master.item_name
                                else excluded.item_name end,
           category      = case when public.material_master.reviewed
                                then public.material_master.category
                                else excluded.category end,
           brand         = case when public.material_master.reviewed
                                then public.material_master.brand
                                else excluded.brand end,
           conflicting   = excluded.conflicting,
           proposed_from = case when public.material_master.reviewed
                                then public.material_master.proposed_from
                                else excluded.proposed_from end,
           txn_rows      = excluded.txn_rows,
           txn_value     = excluded.txn_value
    returning (xmax = 0) as was_insert, conflicting
  )
  select count(*) filter (where was_insert),
         count(*) filter (where not was_insert),
         count(*) filter (where conflicting)
    into v_inserted, v_updated, v_conflicts
    from ins;

  insert into public.system_logs (severity, source, message, detail)
  values ('info', 'material-master',
          format('Material master refreshed: %s new, %s updated, %s conflicting',
                 v_inserted, v_updated, v_conflicts),
          jsonb_build_object('inserted', v_inserted, 'updated', v_updated,
                             'conflicting', v_conflicts));

  return jsonb_build_object('ok', true, 'inserted', v_inserted, 'updated', v_updated,
                            'conflicting', v_conflicts);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_master_set(p_country text, p_item_code text, p_category text, p_subcategory text DEFAULT NULL::text, p_brand text DEFAULT NULL::text, p_uom text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_reviewed boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org  uuid := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_code text := upper(btrim(coalesce(p_item_code, '')));
  v_ctry text := nullif(btrim(coalesce(p_country, '')), '');
  v_row  public.material_master;
begin

  if p_country is not null and not public.app_write_country_ok(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if v_code = '' then
    raise exception 'An item code is required.' using errcode = '22023';
  end if;
  if v_ctry is null then
    raise exception 'A country is required: the same item code means different things in different countries.'
      using errcode = '22023';
  end if;
  if p_category is not null and p_category not in
     ('tyre','spare_part','filter','lubricant','fuel','consumable','service','labour',
      'capital','unclassified') then
    raise exception 'Unknown category.' using errcode = '22023';
  end if;

  insert into public.material_master
    (organisation_id, country, item_code, category, subcategory, brand, uom, notes,
     reviewed, reviewed_by, reviewed_at)
  values (v_org, v_ctry, v_code, coalesce(p_category, 'unclassified'), p_subcategory,
     p_brand, p_uom, p_notes, coalesce(p_reviewed, true),
     case when coalesce(p_reviewed, true) then auth.uid() end,
     case when coalesce(p_reviewed, true) then now() end)
  on conflict (organisation_id, country, item_code) do update
     set category    = coalesce(p_category, public.material_master.category),
         subcategory = coalesce(p_subcategory, public.material_master.subcategory),
         brand       = coalesce(p_brand, public.material_master.brand),
         uom         = coalesce(p_uom, public.material_master.uom),
         notes       = coalesce(p_notes, public.material_master.notes),
         reviewed    = coalesce(p_reviewed, true),
         reviewed_by = case when coalesce(p_reviewed, true) then auth.uid()
                            else public.material_master.reviewed_by end,
         reviewed_at = case when coalesce(p_reviewed, true) then now()
                            else public.material_master.reviewed_at end
  returning * into v_row;

  return to_jsonb(v_row);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_master_set_bulk(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org       uuid := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_uid       uuid := auth.uid();
  v_item      jsonb;
  v_code      text;
  v_ctry      text;
  v_cat       text;
  v_confirmed int := 0;
  v_skipped   int := 0;
  v_errors    jsonb := '[]'::jsonb;
begin
  if not public.app_is_elevated() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' then
    raise exception 'Expected an array of items.' using errcode = '22023';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_code := upper(btrim(coalesce(v_item->>'item_code', '')));
    v_ctry := nullif(btrim(coalesce(v_item->>'country', '')), '');
    v_cat  := nullif(btrim(coalesce(v_item->>'category', '')), '');

    -- Same rules as material_master_set. A country is required because the same
    -- code means different things in different countries.
    if v_code = '' or v_ctry is null then
      v_skipped := v_skipped + 1;
      if jsonb_array_length(v_errors) < 25 then
        v_errors := v_errors || jsonb_build_object(
          'item_code', v_code, 'reason', 'missing item code or country');
      end if;
      continue;
    end if;
    -- V566 COUNTRY GUARD. The country is caller-supplied, so it is judged by
    -- what this caller may WRITE (V555 helper = the table's own write rule).
    -- Refusal reuses this function's OWN per-item skip path, so a mixed batch
    -- still confirms the items the caller is entitled to.
    if not public.app_write_country_ok(v_ctry) then
      v_skipped := v_skipped + 1;
      if jsonb_array_length(v_errors) < 25 then
        v_errors := v_errors || jsonb_build_object(
          'item_code', v_code, 'reason', 'country outside your scope: ' || v_ctry);
      end if;
      continue;
    end if;
    if v_cat is not null and v_cat not in
       ('tyre','spare_part','filter','lubricant','fuel','consumable','service','labour',
        'capital','unclassified') then
      v_skipped := v_skipped + 1;
      if jsonb_array_length(v_errors) < 25 then
        v_errors := v_errors || jsonb_build_object(
          'item_code', v_code, 'reason', 'unknown category ' || v_cat);
      end if;
      continue;
    end if;

    -- Confirm AS THE CURRENT CATEGORY when none is supplied: coalesce keeps the
    -- category already on the row, so "confirm as shown" changes nothing but the
    -- reviewed stamp. A category is only written when the caller sends one.
    insert into public.material_master
      (organisation_id, country, item_code, category, reviewed, reviewed_by, reviewed_at)
    values (v_org, v_ctry, v_code, coalesce(v_cat, 'unclassified'), true, v_uid, now())
    on conflict (organisation_id, country, item_code) do update
       set category    = coalesce(v_cat, public.material_master.category),
           reviewed    = true,
           reviewed_by = v_uid,
           reviewed_at = now();

    v_confirmed := v_confirmed + 1;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'confirmed', v_confirmed,
    'skipped', v_skipped,
    'errors', v_errors);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.material_master_sync_flags()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  NEW.item_code    := upper(btrim(NEW.item_code));
  NEW.is_tyre      := (NEW.category = 'tyre');
  NEW.is_lubricant := (NEW.category = 'lubricant');
  NEW.is_fuel      := (NEW.category = 'fuel');
  NEW.is_service   := (NEW.category in ('service','labour'));
  NEW.is_capital   := (NEW.category = 'capital');
  NEW.is_spare     := (NEW.category in ('spare_part','filter','consumable'));
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.modules_record_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reason text := nullif(left(coalesce(current_setting('app.module_reason', true), ''), 500), '');
begin
  if NEW.status is distinct from OLD.status or NEW.maintenance_until is distinct from OLD.maintenance_until then
    insert into public.module_status_history(module_id, old_status, new_status, old_until, new_until, note, changed_by, reason)
    values (NEW.module_id, OLD.status, NEW.status, OLD.maintenance_until, NEW.maintenance_until, NEW.maintenance_note, auth.uid(), v_reason);
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.modules_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.status is distinct from OLD.status or NEW.maintenance_until is distinct from OLD.maintenance_until or NEW.maintenance_note is distinct from OLD.maintenance_note then
    NEW.updated_by := coalesce(auth.uid(), NEW.updated_by); NEW.last_updated := now();
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.my_admin_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN public.is_super_admin() THEN 'super_admin'
    ELSE COALESCE((SELECT admin_role FROM public.admin_users WHERE user_id = auth.uid() AND active), 'viewer')
  END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.my_elevation_requests()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc), '[]'::jsonb)
    from (select id, module_key, capability, requested_minutes, granted_minutes, reason, status,
                 decision_note, decided_at, starts_at, expires_at, revoked_at, revoke_reason, created_at
            from public.jit_elevation_requests
           where target_user_id = auth.uid() or requested_by = auth.uid()
           order by created_at desc limit 200) r;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.next_accident_reference(p_org uuid, p_year text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v int;
begin
  if p_year !~ '^\d{4}$' then
    raise exception 'invalid year' using errcode = '22023';
  end if;
  if auth.uid() is not null and not public.is_super_admin()
     and p_org is distinct from public.app_current_org() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('accident_ref|' || coalesce(p_org::text, '') || '|' || p_year));
  select coalesce(max(substring(reference_no from '^ACC-' || p_year || '-(\d+)$')::int), 0) + 1
    into v
    from public.accidents
   where organisation_id is not distinct from p_org
     and reference_no like 'ACC-' || p_year || '-%';
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.next_checklist_document_no(p_org uuid, p_prefix text, p_asset_no text, p_year integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_seq integer; v_asset text;
begin
  if p_org is null or coalesce(btrim(p_prefix),'') = '' then return null; end if;
  v_asset := upper(btrim(coalesce(p_asset_no,'')));
  if v_asset = '' then v_asset := 'GEN'; end if;

  insert into public.checklist_doc_counters (organisation_id, prefix, asset_no, year, seq)
  values (p_org, upper(btrim(p_prefix)), v_asset, p_year, 1)
  on conflict (organisation_id, prefix, asset_no, year)
  do update set seq = public.checklist_doc_counters.seq + 1, updated_at = now()
  returning seq into v_seq;

  return upper(btrim(p_prefix)) || '-' || v_asset || '-' || p_year::text
         || '-' || lpad(v_seq::text, 4, '0');
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.next_material_issue_no(p_org uuid, p_country text, p_doc_type text DEFAULT 'MIS'::text, p_when timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc text := upper(btrim(coalesce(p_doc_type, 'MIS')));
  v_prefix text; v_width integer; v_period text; v_seq integer;
begin
  if p_org is null then return null; end if;
  if v_doc not in ('MIS','MRT') then v_doc := 'MIS'; end if;
  select upper(btrim(c.entity_prefix)), c.seq_width into v_prefix, v_width
    from public.material_issue_number_config c
   where c.organisation_id = p_org
     and lower(btrim(c.country)) = lower(btrim(coalesce(p_country, '')))
     and c.doc_type = v_doc;
  if v_prefix is null then v_prefix := 'GC'; v_width := 4; end if;
  v_period := to_char(coalesce(p_when, now()), 'MMYY');
  insert into public.material_issue_counters (organisation_id, country, doc_type, prefix, period_key, seq)
  values (p_org, upper(btrim(coalesce(p_country, ''))), v_doc, v_prefix, v_period, 1)
  on conflict (organisation_id, country, doc_type, prefix, period_key)
  do update set seq = public.material_issue_counters.seq + 1, updated_at = now()
  returning seq into v_seq;
  return v_prefix || '/' || v_doc || '/' || lpad(v_seq::text, v_width, '0') || '/' || v_period;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.next_rfr_no(p_org uuid, p_country text, p_when timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prefix text; v_mode text; v_width integer; v_period text; v_seq integer;
begin
  if p_org is null then return null; end if;
  select upper(btrim(c.entity_prefix)), c.period_mode, c.seq_width
    into v_prefix, v_mode, v_width
    from public.repair_request_number_config c
   where c.organisation_id = p_org
     and lower(btrim(c.country)) = lower(btrim(coalesce(p_country, '')));
  if v_prefix is null then
    v_prefix := 'GC'; v_mode := 'month'; v_width := 4;
  end if;
  v_period := case when v_mode = 'year' then to_char(coalesce(p_when, now()), 'YY')
                   else to_char(coalesce(p_when, now()), 'MMYY') end;
  insert into public.repair_request_counters (organisation_id, country, prefix, period_key, seq)
  values (p_org, upper(btrim(coalesce(p_country, ''))), v_prefix, v_period, 1)
  on conflict (organisation_id, country, prefix, period_key)
  do update set seq = public.repair_request_counters.seq + 1, updated_at = now()
  returning seq into v_seq;
  return v_prefix || '/RFR/' || lpad(v_seq::text, v_width, '0') || '/' || v_period;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_asset_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.asset_code IS NOT NULL THEN
    NEW.asset_code := upper(regexp_replace(NEW.asset_code, '\s+', '', 'g'));
    IF NEW.asset_code = '' THEN NEW.asset_code := NULL; END IF;
  END IF;
  RETURN NEW;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_asset_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.asset_no IS NOT NULL THEN
    NEW.asset_no := upper(regexp_replace(NEW.asset_no, '\s+', '', 'g'));
    IF NEW.asset_no = '' THEN NEW.asset_no := NULL; END IF;
  END IF;
  RETURN NEW;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_brand(raw text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select coalesce(
    (select canonical from public.brand_aliases
      where alias = lower(trim(raw)) limit 1),
    initcap(trim(raw))
  )
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_country(raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when raw is null or btrim(raw) = '' then null
    else case upper(btrim(raw))
      when 'KSA'                    then 'KSA'
      when 'SA'                     then 'KSA'
      when 'SAUDI'                  then 'KSA'
      when 'SAUDI ARABIA'           then 'KSA'
      when 'UAE'                    then 'UAE'
      when 'AE'                     then 'UAE'
      when 'UNITED ARAB EMIRATES'   then 'UAE'
      when 'DUBAI'                  then 'UAE'
      when 'ABU DHABI'              then 'UAE'
      when 'EGYPT'                  then 'Egypt'
      when 'EG'                     then 'Egypt'
      when 'CAIRO'                  then 'Egypt'
      else btrim(raw)  -- preserve unknown country verbatim; never force 'KSA'
    end
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_profiles_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.role IS NULL THEN
    NEW.role := 'Reporter';
    RETURN NEW;
  END IF;

  CASE lower(trim(NEW.role))
    WHEN 'schedule'        THEN NEW.role := 'Reporter';
    WHEN 'schedules'       THEN NEW.role := 'Reporter';
    WHEN 'schedule_report' THEN NEW.role := 'Reporter';
    WHEN 'schaule'         THEN NEW.role := 'Reporter';
    WHEN 'schdule'         THEN NEW.role := 'Reporter';
    ELSE NULL;
  END CASE;

  IF NEW.role <> ALL (ARRAY['Admin','Manager','Director','Reporter','Inspector',
                            'Tyre Man','Driver','Integration Admin','Data Engineer','Automation']::text[])
     AND NOT EXISTS (SELECT 1 FROM public.custom_roles c WHERE c.name = NEW.role) THEN
    NEW.role := 'Reporter';
  END IF;

  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_report_schedules_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if NEW.report_type is null then
    NEW.report_type := 'inspection';
  else
    case lower(trim(NEW.report_type))
      when 'schedule' then NEW.report_type := 'inspection';
      when 'schedules' then NEW.report_type := 'inspection';
      when 'schaule' then NEW.report_type := 'inspection';
      when 'schdule' then NEW.report_type := 'inspection';
      when 'schedule_report' then NEW.report_type := 'inspection';
      else null;
    end case;
  end if;

  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_site(raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select initcap(trim(regexp_replace(raw, '\s+', ' ', 'g')))
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_site()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_canon text;
begin
  if new.site is null then return new; end if;
  new.site := upper(btrim(regexp_replace(new.site, '\s+', ' ', 'g')));
  select a.canonical into v_canon from public.site_aliases a where a.alias = new.site;
  if v_canon is not null then
    new.site := v_canon;
  elsif new.site ~ '[_-]ST$' then
    new.site := regexp_replace(new.site, '[_-]ST$', '');
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_site_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_canon text;
begin
  if new.name is null then return new; end if;
  new.name := upper(regexp_replace(btrim(new.name), '\s+', ' ', 'g'));
  select a.canonical into v_canon from public.site_aliases a where a.alias = new.name;
  if v_canon is not null then
    new.name := v_canon;
  elsif new.name ~ '[_-]ST$' then
    new.name := regexp_replace(new.name, '[_-]ST$', '');
  end if;

  if tg_op = 'INSERT' and exists (
    select 1 from public.sites s
    where s.organisation_id is not distinct from new.organisation_id
      and s.country is not distinct from new.country
      and upper(s.name) = upper(new.name)
  ) then
    return null;
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.normalize_tyre_brand()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.brand is not null then
    new.brand := public.tyre_brand_canonical(new.brand);
  end if;
  return new;
end $function$;
