  IF NEW.vehicle_type IS NOT NULL THEN
    NEW.vehicle_type := upper(btrim(regexp_replace(NEW.vehicle_type, '\s+', ' ', 'g')));
    IF NEW.vehicle_type = '' THEN NEW.vehicle_type := NULL; END IF;
