CREATE OR REPLACE FUNCTION public.notify_role_in_org(p_role text, p_org uuid, p_type text, p_title text, p_body text, p_entity_type text DEFAULT 'workflow'::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
  SELECT id, p_type, p_title, p_body, p_entity_type, p_entity_id
    FROM public.profiles
   WHERE lower(regexp_replace(COALESCE(role, ''), '\s+', '_', 'g')) = lower(p_role)
     AND COALESCE(locked, false) = false
     AND (approved IS NULL OR approved = true)
     AND (p_org IS NULL OR organisation_id = p_org);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.notify_submission_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE requestor uuid; kind text; label text; title_text text; body_text text; token text; event_id bigint;
BEGIN
 IF NEW.approval_status NOT IN ('approved','rejected') THEN RETURN NEW; END IF;
 kind:=CASE WHEN TG_TABLE_NAME='inspections' THEN 'inspection' ELSE 'checklist' END;
 requestor:=nullif(CASE WHEN kind='inspection' THEN to_jsonb(NEW)->>'created_by' ELSE to_jsonb(NEW)->>'submitted_by' END,'')::uuid;
 IF requestor IS NULL OR requestor=NEW.approved_by THEN RETURN NEW; END IF;
 label:=coalesce(nullif(NEW.asset_no,''),nullif(NEW.title,''),'your submission');
 title_text:=initcap(kind)||CASE WHEN NEW.approval_status='approved' THEN ' approved' WHEN NEW.approval_outcome='returned' THEN ' returned for correction' ELSE ' rejected' END;
 body_text:='Your '||kind||' for '||label||CASE WHEN NEW.approval_status='approved' THEN ' was approved.' WHEN NEW.approval_outcome='returned' THEN ' was returned. Please review and resubmit.' ELSE ' was rejected. Review the decision history for the reason.' END;
 BEGIN
  INSERT INTO notifications(user_id,type,title,body,entity_type,entity_id) VALUES(requestor,'approval_decision',title_text,body_text,kind,NEW.id);
 EXCEPTION WHEN OTHERS THEN NULL; END;
 BEGIN
  SELECT min(tk) INTO token FROM profiles pr CROSS JOIN LATERAL public._user_push_tokens(pr.id) tk WHERE pr.id=requestor AND pr.org_id=NEW.organisation_id;
  IF nullif(btrim(token),'') IS NOT NULL THEN
   INSERT INTO domain_events(event_type,entity_type,entity_id,organisation_id,actor_id,payload,status,processed_at)
   VALUES('approval.decision_notification',kind,NEW.id::text,NEW.organisation_id,auth.uid(),jsonb_build_object('outcome',coalesce(NEW.approval_outcome,NEW.approval_status)),'processed',clock_timestamp()) RETURNING id INTO event_id;
   INSERT INTO workflow_notifications(event_id,organisation_id,instance_id,event_type,payload,recipient_count,status)
   VALUES(event_id,NEW.organisation_id,NULL,'workflow.step_advanced',jsonb_build_object('event_type','workflow.step_advanced','instance_id',NULL,
    'definition_name',initcap(kind)||' decision','entity_type',kind,'entity_label',label,'step_name',title_text,
    'recipients',(SELECT jsonb_agg(jsonb_build_object('user_id',requestor,'push_token',tk)) FROM public._user_push_tokens(requestor) tk)),(SELECT count(*)::int FROM public._user_push_tokens(requestor)),'pending');
  END IF;
 EXCEPTION WHEN OTHERS THEN NULL; END;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.notify_workshop_parts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if tg_op = 'INSERT' then
      perform public.notify_elevated_users(
        'parts_request', 'New parts request',
        coalesce('Parts requested for ' || nullif(new.asset_no,''), 'A new parts request was raised'),
        'parts_request', new.id);
    elsif tg_op = 'UPDATE' and new.status is distinct from old.status
          and new.requested_by is not null
          and new.status in ('approved','issued','fulfilled','rejected') then
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      values (
        new.requested_by, 'parts_request',
        case new.status
          when 'approved'  then 'Parts approved'
          when 'issued'    then 'Parts issued'
          when 'fulfilled' then 'Parts fulfilled'
          when 'rejected'  then 'Parts request rejected'
        end,
        coalesce(nullif(new.part_name,'') || ' for ' || nullif(new.asset_no,''), 'Your parts request was updated'),
        'parts_request', new.id);
    end if;
  exception when others then
    -- never block the parts_requests write on a notification failure
    null;
  end;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.notify_workshop_qc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if new.qc_status is distinct from old.qc_status
       and new.qc_status = 'failed'
       and new.assigned_owner_id is not null then
      insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
      values (
        new.assigned_owner_id, 'work_order', 'QC failed - rework required',
        coalesce('Job ' || nullif(new.work_order_no,'') || ' failed inspection', 'A job you own failed QC'),
        'work_order', new.id);
    end if;
  exception when others then
    null;
  end;
  return new;
end;
$function$;
