CREATE OR REPLACE FUNCTION public.ops_finding_reviews_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' and (new.status is distinct from old.status or new.note is distinct from old.note) then
    new.reviewed_at := now();
    new.reviewed_by := auth.uid();
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.org_can_add(p_resource text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_over jsonb := public.get_subscription_overview();
  v_limit numeric;
  v_usage numeric;
BEGIN
  v_limit := NULLIF(v_over -> 'limits' ->> p_resource, '')::numeric;
  IF v_limit IS NULL THEN RETURN true; END IF;
  v_usage := COALESCE((v_over -> 'usage' ->> p_resource)::numeric, 0);
  RETURN v_usage < v_limit;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.owner_data_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb;
  vt int; vto int; vtb int; vtc int; vtd int; vtw int; vtp int;
  wt int; woo int; pt int; pco int; lio int;
  empt jsonb; cur jsonb; issues jsonb;
  rel_score numeric; dq_score numeric; br_score numeric; health numeric;
  k text; ec int; empties text[] := '{}';
begin
  if not public.is_super_admin() then
    raise exception 'owner_data_audit: super-admin only';
  end if;

  -- tyres
  select count(*) into vt from tyre_records;
  select count(*) into vto from tyre_records t
    where t.asset_no is not null and upper(btrim(t.asset_no)) not in
      (select distinct upper(btrim(asset_no)) from vehicle_fleet where asset_no is not null);
  select count(*) into vtb from tyre_records where brand is null or btrim(brand)='';
  select count(*) into vtc from tyre_records where coalesce(cost_per_tyre,0)=0;
  select count(*) into vtd from (select serial_no,country from tyre_records
     where serial_no is not null and btrim(serial_no)<>'' group by 1,2 having count(*)>1) x;
  select count(*) into vtw from (select coalesce(serial_no,serial_number,tyre_serial) s from tyre_records
     where status ilike 'active' and coalesce(serial_no,serial_number,tyre_serial) is not null
     group by 1 having count(distinct upper(btrim(asset_no)))>1) a;
  select count(*) into vtp from (select upper(btrim(asset_no)) a, upper(btrim(coalesce(position,tyre_position))) p
     from tyre_records where status ilike 'active' and asset_no is not null and coalesce(position,tyre_position) is not null
     group by 1,2 having count(*)>1) b;

  -- work orders / parts / line items
  select count(*) into wt from work_orders;
  select count(*) into woo from work_orders w where w.asset_no is not null and upper(btrim(w.asset_no)) not in
     (select distinct upper(btrim(asset_no)) from vehicle_fleet where asset_no is not null);
  select count(*) into pt from parts_consumption;
  select count(*) into pco from parts_consumption p where p.asset_code is not null and upper(btrim(p.asset_code)) not in
     (select distinct upper(btrim(asset_no)) from vehicle_fleet where asset_no is not null);
  select count(*) into lio from work_order_line_items li where li.work_order_no is not null
     and not exists (select 1 from work_orders w where w.work_order_no=li.work_order_no);

  -- empty key domain tables (feed KPIs but hold 0 rows)
  foreach k in array array['odometer_logs','engine_hours_logs','production_logs','pm_programs','pm_service_records',
     'stock_records','drivers','suppliers','warranty_claims','tyre_service_events','tyre_rotations','tpms_readings']
  loop
    execute format('select count(*) from public.%I', k) into ec;
    if ec = 0 then empties := empties || k; end if;
  end loop;
  empt := to_jsonb(empties);

  -- per-country currency panel (NEVER blended: each country in its own currency)
  select jsonb_agg(jsonb_build_object('country',country,'currency',
      case country when 'KSA' then 'SAR' when 'UAE' then 'AED' when 'Egypt' then 'EGP' else '?' end,
      'expense_rows',n,'expense_total',round(tot)))
    into cur
  from (select country, count(*) n, sum(case when value_amount ~ '^-?[0-9.]+$' then value_amount::numeric else 0 end) tot
        from parts_consumption group by country) s;

  -- scores
  rel_score := greatest(0, 100 - ( (100.0*vto/nullif(vt,0)) + (100.0*woo/nullif(wt,0)) + (100.0*pco/nullif(pt,0)) )/3.0);
  dq_score  := greatest(0, 100 - ( (100.0*vtb/nullif(vt,0)) + (100.0*vtc/nullif(vt,0)) )/2.0);
  br_score  := greatest(0, 100 - least(100, (vtw+vtp)*2 + vtd*0.5));
  health    := round( rel_score*0.4 + dq_score*0.35 + br_score*0.25 );

  -- prioritized issue list
  issues := jsonb_build_array();
  if pco > 0 then issues := issues || jsonb_build_object('severity','Critical','module','Cost / Expense',
     'tables','parts_consumption -> vehicle_fleet','columns','asset_code',
     'issue',pco||' of '||pt||' expense lines ('||round(100.0*pco/nullif(pt,0),1)||'%) reference an asset_code not in the fleet master',
     'impact','65% of SAR/AED/EGP spend cannot be attributed to a known asset; per-asset CPK/cost is understated or wrong',
     'fix','Build an asset_code<->asset_no crosswalk (store/cost-center vocab differs from asset_no) and backfill; add a validation flag on import','priority',1); end if;
  if woo > 0 then issues := issues || jsonb_build_object('severity','High','module','Work Orders',
     'tables','work_orders -> vehicle_fleet','columns','asset_no',
     'issue',woo||' of '||wt||' work orders ('||round(100.0*woo/nullif(wt,0),1)||'%) point to an asset not in the fleet master',
     'impact','Per-asset maintenance cost and downtime KPIs miss ~39% of jobs','fix','Backfill missing assets into vehicle_fleet from the ERP asset master; enforce asset existence on import','priority',2); end if;
  if vto > 0 then issues := issues || jsonb_build_object('severity','High','module','Tyres',
     'tables','tyre_records -> vehicle_fleet','columns','asset_no',
     'issue',vto||' of '||vt||' tyres ('||round(100.0*vto/nullif(vt,0),1)||'%) are fitted to an asset not in the fleet master',
     'impact','Tyre-per-vehicle views and fleet CPK drop these tyres','fix','Backfill orphan assets (recon_backfill_all_orphan_assets already exists)','priority',2); end if;
  if vtw > 0 then issues := issues || jsonb_build_object('severity','High','module','Tyres (business rule)',
     'tables','tyre_records','columns','serial_no/asset_no/status',
     'issue',vtw||' tyre serials are marked ACTIVE on more than one asset at the same time',
     'impact','Violates "one tyre active once"; inflates active-tyre counts and double-books lifecycle','fix','Keep only the latest fitment active per serial; mark earlier as removed/scrapped','priority',2); end if;
  if vtp > 0 then issues := issues || jsonb_build_object('severity','High','module','Tyres (business rule)',
     'tables','tyre_records','columns','asset_no/position/status',
     'issue',vtp||' vehicle positions carry more than one ACTIVE tyre',
     'impact','Violates "one position, one tyre"; double-counts fitted tyres','fix','Deduplicate to the latest fitment per (asset, position)','priority',2); end if;
  if vtc > 0 then issues := issues || jsonb_build_object('severity','High','module','Tyres / CPK',
     'tables','tyre_records','columns','cost_per_tyre',
     'issue',vtc||' of '||vt||' tyres ('||round(100.0*vtc/nullif(vt,0),1)||'%) have no cost',
     'impact','CPK and tyre-spend KPIs are uncomputable/understated for ~half the fleet','fix','Backfill cost from the parts grid (backfill_tyre_prices_from_grid) + tyre expense import','priority',2); end if;
  if vtb > 0 then issues := issues || jsonb_build_object('severity','Medium','module','Tyres',
     'tables','tyre_records','columns','brand',
     'issue',vtb||' of '||vt||' tyres ('||round(100.0*vtb/nullif(vt,0),1)||'%) have no brand',
     'impact','Brand CPK / vendor comparison boards are blank or biased','fix','Upload stg_tyre_brand backfill (UAE/Egypt) already flagged open','priority',3); end if;
  if array_length(empties,1) > 0 then issues := issues || jsonb_build_object('severity','Medium','module','Empty domain tables',
     'tables',array_to_string(empties,', '),'columns','(whole table)',
     'issue',array_length(empties,1)||' KPI-feeding tables hold 0 rows',
     'impact','Meter/CPK-per-km, PM, stock, vendor, warranty and service-event dashboards render empty','fix','Load meter/production/PM/stock data or hide those modules until data exists','priority',3); end if;
  if vtd > 0 then issues := issues || jsonb_build_object('severity','Medium','module','Tyres (data quality)',
     'tables','tyre_records','columns','serial_no',
     'issue',vtd||' serial+country groups are duplicated',
     'impact','Possible double-count; some are legitimate re-fitments','fix','Review via Data Reconciliation; merge byte-identical duplicates only','priority',3); end if;

  v := jsonb_build_object(
    'generated_at', now(),
    'health_score', health,
    'sub_scores', jsonb_build_object('relationship',round(rel_score),'data_quality',round(dq_score),'business_rules',round(br_score)),
    'tyres', jsonb_build_object('total',vt,'orphan_asset',vto,'orphan_pct',round(100.0*vto/nullif(vt,0),1),
        'missing_brand',vtb,'missing_cost',vtc,'dup_serial_country',vtd,'active_twice',vtw,'position_conflict',vtp),
    'work_orders', jsonb_build_object('total',wt,'orphan_asset',woo,'orphan_pct',round(100.0*woo/nullif(wt,0),1),'line_items_orphan',lio),
    'parts_consumption', jsonb_build_object('total',pt,'orphan_asset_code',pco,'orphan_pct',round(100.0*pco/nullif(pt,0),1)),
    'empty_key_tables', empt,
    'currency_panel', cur,
    'issues', issues
  );
  return v;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_brand(p_desc text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(initcap(coalesce((regexp_match(lower(coalesce(p_desc,'')),
    '\m(double coin|triangle|ling ?long|aeolus|jinyu|bridgestone|firestone|michelin|goodyear|hankook|dunlop|yokohama|pirelli|continental|kumho|maxxis|infinity|otani|advance|annaite|sailun|westlake|windforce|skyfire|century|rock buster|diamond back|gold dove|bkt|itr|amberstone|kapsen|techking|boto|hilo|apollo|mrf|ceat|giti|gt radial|roadlux|long ?march|double ?star|samson|armour|deestone|camso|solideal|marcher|superhawk|fullrun|transking|copartner|hifly|goform|rockstone)\M'))[1],'')),'')
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_cost_fill(p_country text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_batch uuid := gen_random_uuid();
  v_out jsonb;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'not_allowed');
  end if;
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;

  create temporary table if not exists _fill_candidates (
    line_id uuid, country text, item_code text, amount numeric, sample_size int
  ) on commit drop;
  delete from _fill_candidates;

  insert into _fill_candidates
  with evidence as (
    select p.country, p.item_code,
           count(*) n,
           (percentile_cont(0.5) within group (order by p.line_cost / p.qty_n))::numeric med_unit
      from public.parts_consumption p
     where p.organisation_id = v_org
       and p.line_cost > 0
       and coalesce(p.qty_n, 0) > 0
       and p.filled_cost is null
       and coalesce(btrim(p.item_code), '') <> ''
     group by 1, 2
  )
  select z.id, z.country, z.item_code,
         round(e.med_unit * greatest(coalesce(z.qty_n, 1), 1), 2),
         e.n
    from public.parts_consumption z
    join evidence e
      on e.country = z.country
     and e.item_code = z.item_code
   where z.organisation_id = v_org
     and (p_country is null or z.country = p_country)
     and (z.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(z.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
     and coalesce(z.line_cost, 0) = 0
     and z.filled_cost is null
     and coalesce(btrim(z.item_code), '') <> ''
     and not public.parts_cost_is_warranty(z.item_description)
     and e.med_unit > 0;

  select jsonb_build_object(
           'ok', true,
           'dry_run', p_dry_run,
           'batch', case when p_dry_run then null else v_batch end,
           'by_country', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'country', c.country, 'lines', c.n, 'value', c.v,
                      'currency', public.currency_for_country(c.country)) order by c.country)
               from (select country, count(*) n, round(sum(amount), 2) v
                       from _fill_candidates group by 1) c), '[]'::jsonb),
           'lines', (select count(*) from _fill_candidates))
    into v_out;

  if p_dry_run then
    return v_out;
  end if;

  insert into public.parts_cost_fill_log
    (batch_id, line_id, organisation_id, country, item_code, filled_amount, basis, sample_size)
  select v_batch, line_id, v_org, country, item_code, amount, 'item_code_median', sample_size
    from _fill_candidates;

  update public.parts_consumption p
     set filled_cost = c.amount,
         filled_cost_basis = 'item_code_median'
    from _fill_candidates c
   where p.id = c.line_id
     and (p.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(p.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])));

  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_cost_fill_undo(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_n int;
begin
  if not public.app_is_elevated() then
    return jsonb_build_object('ok', false, 'reason', 'not_allowed');
  end if;
  update public.parts_consumption p
     set filled_cost = null, filled_cost_basis = null
    from public.parts_cost_fill_log l
   where l.batch_id = p_batch and l.line_id = p.id and p.organisation_id = v_org
     and public.app_write_country_ok(p.country) is not false;
  get diagnostics v_n = row_count;
  delete from public.parts_cost_fill_log l
   where l.batch_id = p_batch and l.organisation_id = v_org
     and exists (select 1 from public.parts_consumption p
                  where p.id = l.line_id
                    and public.app_write_country_ok(p.country) is not false);
  return jsonb_build_object('ok', true, 'reverted', v_n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_cost_is_warranty(p_desc text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_desc, '') ~*
    '(warrant|warrent|warent|waranty|gaurantee|guarantee|free of charge|free issue|foc\M|no charge|zero charge|complimentary)'
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_import_uid(p_country text, p_source_row text, p_issue text, p_wo text, p_item_code text, p_item_desc text, p_qty text, p_value text, p_txn_date text, p_asset text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(btrim(p_source_row), '') = '' then null
    else md5(
      coalesce(upper(btrim(p_country)), '') || '|' || btrim(p_source_row) || '|' ||
      coalesce(btrim(p_issue), '')     || '|' || coalesce(btrim(p_wo), '')       || '|' ||
      coalesce(btrim(p_item_code), '') || '|' || coalesce(btrim(p_item_desc), '') || '|' ||
      coalesce(btrim(p_qty), '')       || '|' || coalesce(btrim(p_value), '')     || '|' ||
      coalesce(btrim(p_txn_date), '')  || '|' || coalesce(btrim(p_asset), '')
    )
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_import_uid(p_country text, p_source_row text, p_issue text, p_wo text, p_item_code text, p_item_desc text, p_qty text, p_value text, p_txn_date text, p_asset text, p_store text DEFAULT NULL::text, p_cost_centre text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(btrim(p_source_row), '') = '' then null
    else md5(
      coalesce(upper(btrim(p_country)), '') || '|' || btrim(p_source_row)            || '|' ||
      coalesce(btrim(p_issue), '')     || '|' || coalesce(btrim(p_wo), '')           || '|' ||
      coalesce(btrim(p_item_code), '') || '|' || coalesce(btrim(p_item_desc), '')    || '|' ||
      coalesce(btrim(p_qty), '')       || '|' || coalesce(btrim(p_value), '')        || '|' ||
      coalesce(btrim(p_txn_date), '')  || '|' || coalesce(btrim(p_asset), '')        || '|' ||
      -- site separation: a store / cost centre is part of WHICH expense this is.
      coalesce(upper(btrim(p_store)), '') || '|' || coalesce(upper(btrim(p_cost_centre)), '')
    )
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_is_oil(p_desc text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p_desc is null then false else (
    lower(p_desc) ~ '(engine oil|gear oil|hydraulic oil|hyd oil|transmission oil|\matf\M|brake fluid|grease|coolant|anti ?freeze|adblue|lubric|\mdef\M)'
    and lower(p_desc) !~ '(filter|\mseal\M|\mpump\M|cooler|\mpipe\M|gasket|element|\mhose\M|pressure|sensor|switch)'
  ) end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.parts_is_tyre(p_desc text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p_desc is null then false else (
    lower(p_desc) ~ '[0-9]{3}\s*/\s*[0-9]{2}\s*r?\s*[0-9]{2}(\.[0-9])?'          -- 315/80R22.5
    or lower(p_desc) ~ '[0-9]{4}\s*r\s*[0-9]{2}'                                 -- 1200R24
    or lower(p_desc) ~ '[0-9]{2}\.[0-9]{1,2}\s*[-r]\s*[0-9]{2}'                  -- 23.5R25 / 12.00R24 / 23.5-25
    or ( lower(p_desc) ~ '\m(tyre|tire)\M'
         and lower(p_desc) !~ '(valve|patch|glue|tube|flap|solution|repair kit|wax|soap|paste|cement|remover|lever|gauge|protector|marker|chalk|spray|\mrim\M|wheel nut|\mstud\M)' )
    or lower(p_desc) ~ '\m(double coin|triangle|ling ?long|aeolus|jinyu|bridgestone|firestone|michelin|goodyear|hankook|dunlop|yokohama|pirelli|continental|kumho|maxxis|infinity|otani|advance|annaite|sailun|westlake|windforce|skyfire|century|rock buster|diamond back|gold dove|\mbkt\M|\mitr\M|amberstone|kapsen|techking|\mboto\M|\mhilo\M|apollo|\mmrf\M|\mceat\M|giti|gt radial|roadlux|long ?march|double ?star|samson|armour|deestone|camso|solideal|marcher|superhawk|fullrun|transking|copartner|hifly|goform|rockstone)\M'
  ) end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.post_stock_movement(p_stock_id uuid, p_type text, p_qty numeric, p_reason text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_org uuid := public.app_current_org();
  v_rec public.stock_records%ROWTYPE; v_dir int; v_type text := lower(btrim(p_type));
  v_qty numeric := p_qty; v_before numeric; v_change numeric; v_after numeric; v_status text; v_mov_id uuid;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN RAISE EXCEPTION 'Not authorised.' USING errcode='42501'; END IF;
  IF p_stock_id IS NULL THEN RAISE EXCEPTION 'stock_id is required.' USING errcode='22004'; END IF;
  v_dir := public.stock_movement_direction(v_type);
  IF v_dir IS NULL THEN RAISE EXCEPTION 'Unknown movement_type "%".', p_type USING errcode='22023'; END IF;
  IF v_qty IS NULL OR v_qty <= 0 THEN RAISE EXCEPTION 'Quantity must be a positive magnitude (got %).', p_qty USING errcode='22023'; END IF;

  SELECT * INTO v_rec FROM public.stock_records WHERE id = p_stock_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stock record % not found.', p_stock_id USING errcode='P0002'; END IF;
  IF v_rec.organisation_id IS NOT NULL AND v_rec.organisation_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'Cross-organisation stock movement denied.' USING errcode='42501'; END IF;
  IF NOT public.app_write_country_ok(v_rec.country) THEN
    RAISE EXCEPTION 'Cross-country stock movement denied.' USING errcode='42501'; END IF;

  v_before := COALESCE(v_rec.stock_qty, 0);
  v_change := v_dir * v_qty;
  v_after  := v_before + v_change;
  IF v_after < 0 THEN
    IF NOT (v_type = 'adjustment_down' AND public.app_is_elevated()) THEN
      RAISE EXCEPTION 'Movement would drive stock negative (before=%, change=%, after=%). Only an elevated adjustment_down may override.',
        v_before, v_change, v_after USING errcode='23514';
    END IF;
  END IF;

  INSERT INTO public.stock_movements
    (stock_id, site, description, movement_type, qty_before, qty_change, qty_after, reason, reference_no, created_by, organisation_id)
  VALUES
    (p_stock_id, v_rec.site, v_rec.description, v_type, v_before, v_change, v_after,
     NULLIF(btrim(p_reason),''), NULLIF(btrim(p_reference),''), v_uid, COALESCE(v_rec.organisation_id, v_org))
  RETURNING id INTO v_mov_id;

  v_status := CASE
    WHEN v_after <= COALESCE(v_rec.critical_level, 0) THEN 'Critical'
    WHEN v_after <= COALESCE(v_rec.min_level, 0)      THEN 'Low'
    ELSE 'OK' END;

  UPDATE public.stock_records
    SET stock_qty = v_after, stock_status = v_status, updated_by = v_uid, updated_at = now()
    WHERE id = p_stock_id;

  PERFORM public.record_audit_event('stock_movement','stock_movements', v_mov_id::text,
    jsonb_build_object('stock_id', p_stock_id, 'qty_before', v_before),
    jsonb_build_object('stock_id', p_stock_id, 'movement_type', v_type, 'qty_change', v_change,
      'qty_after', v_after, 'stock_status', v_status,
      'reason', NULLIF(btrim(p_reason),''), 'reference_no', NULLIF(btrim(p_reference),'')));

  RETURN jsonb_build_object('status','posted','movement_id',v_mov_id,'stock_id',p_stock_id,
    'qty_before',v_before,'qty_change',v_change,'qty_after',v_after,'stock_status',v_status);
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.prevent_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  raise exception 'Audit records are immutable.' using errcode = '42501';
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.preview_learned_rule(p_token text, p_category text, p_limit integer DEFAULT 50)
 RETURNS TABLE(item_code text, item_description text, country text, lines bigint, value numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select pc.item_code, min(pc.item_description) as item_description, pc.country,
         count(*) as lines, round(coalesce(sum(pc.line_cost), 0), 2) as value
  from public.parts_consumption pc
  where pc.organisation_id = public.app_current_org()
    and (pc.country is null
         or (select public.is_super_admin())
         or (select public.app_sees_all_countries())
         or lower(btrim(pc.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
    and pc.classified_by = 'default'
    and public.brain_has_any_word(pc.item_description, array[lower(btrim(p_token))])
    and not public.learned_rule_vetoed(pc.item_description, p_category)
  group by pc.item_code, pc.country
  order by value desc
  limit greatest(1, coalesce(p_limit, 50));
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_daily_km()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_asset   text;
  v_km      numeric;
  v_date    date;
  v_country text;
  v_site    text;
  v_org     uuid;
  v_existing uuid;
BEGIN
  -- 1. Resolve the asset from whichever alias the sheet used (canonical UPPER, V337).
  v_asset := upper(btrim(coalesce(
    nullif(btrim(NEW.asset_code), ''),
    nullif(btrim(NEW.asset_no), ''),
    nullif(btrim(NEW.asset), ''),
    nullif(btrim(NEW.equipment_no), '')
  )));

  -- 2. Resolve the km value from whichever alias the sheet used.
  v_km := coalesce(
    public.daily_km_num(NEW.kms),
    public.daily_km_num(NEW.km),
    public.daily_km_num(NEW.odometer),
    public.daily_km_num(NEW.odometer_km),
    public.daily_km_num(NEW.reading)
  );

  -- 3. Skip footer / blank / unusable rows silently (GRAND TOTAL etc).
  IF v_asset IS NULL OR v_asset = '' OR v_km IS NULL OR v_km <= 0
     OR public.erp_is_footer(v_asset) THEN
    RETURN NULL;
  END IF;

  -- 4. Date: any alias, else today. erp_parse_date handles DD-MM-YYYY / DD-Mon-YY.
  v_date := coalesce(
    public.erp_parse_date(nullif(btrim(NEW.date), '')),
    public.erp_parse_date(nullif(btrim(NEW.reading_date), '')),
    public.erp_parse_date(nullif(btrim(NEW.txn_date), '')),
    current_date
  );

  v_country := nullif(btrim(NEW.country), '');
  v_site    := nullif(btrim(NEW.site), '');

  -- 5. Fill country/site from the fleet register when the sheet omits them, but
  --    ONLY when the asset is unambiguous (a vehicle can legitimately exist in
  --    more than one country after a transfer - never guess in that case).
  IF v_country IS NULL THEN
    SELECT f.country INTO v_country FROM public.vehicle_fleet f
    WHERE f.asset_no = v_asset GROUP BY f.country HAVING count(*) >= 1
    LIMIT 2;
    IF (SELECT count(DISTINCT f.country) FROM public.vehicle_fleet f WHERE f.asset_no = v_asset) <> 1 THEN
      v_country := nullif(btrim(NEW.country), '');
    END IF;
  END IF;

  IF v_site IS NULL THEN
    SELECT max(f.site) INTO v_site FROM public.vehicle_fleet f
    WHERE f.asset_no = v_asset
      AND (v_country IS NULL OR f.country = v_country);
  END IF;

  -- 6. Org: the Table Editor / dashboard importer has no profile, so
  --    app_current_org() is NULL there and the row would be invisible under RLS.
  --    Fall back to the tenant that owns this data (same rule as V290).
  v_org := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);

  -- 7. Merge on (org, asset, date): re-uploading a corrected sheet updates the
  --    reading instead of creating a duplicate for that day.
  SELECT o.id INTO v_existing FROM public.odometer_logs o
  WHERE o.organisation_id = v_org AND o.asset_no = v_asset AND o.reading_date = v_date
  ORDER BY o.created_at DESC LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE public.odometer_logs
       SET odometer_km = v_km,
           site        = coalesce(v_site, site),
           country     = coalesce(v_country, country),
           notes       = coalesce(nullif(btrim(NEW.notes), ''), notes),
           source      = 'Daily KM import',
           updated_at  = now()
     WHERE id = v_existing;
  ELSE
    INSERT INTO public.odometer_logs
      (organisation_id, country, asset_no, odometer_km, reading_date, source, site, notes)
    VALUES
      (v_org, v_country, v_asset, v_km, v_date, 'Daily KM import', v_site,
       nullif(btrim(NEW.notes), ''));
  END IF;

  -- Pure pipe: nothing is stored in daily_km.
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_domain_events(p_batch integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ev          public.domain_events%ROWTYPE;
  c           record;
  v_ok        boolean;
  v_err       text;
  n_processed int := 0;
  n_failed    int := 0;
BEGIN
  FOR ev IN
    SELECT * FROM public.domain_events
     WHERE status = 'pending'
     ORDER BY id
     LIMIT GREATEST(p_batch, 1)
     FOR UPDATE SKIP LOCKED
  LOOP
    v_ok  := true;
    v_err := NULL;
    FOR c IN
      SELECT consumer FROM public.event_consumers
       WHERE enabled
         AND (event_types IS NULL OR ev.event_type = ANY (event_types))
       ORDER BY consumer
    LOOP
      BEGIN
        EXECUTE format('SELECT public.%I($1)', c.consumer) USING ev;
      EXCEPTION WHEN OTHERS THEN
        v_ok  := false;
        v_err := left(COALESCE(v_err || ' | ', '') || c.consumer || ': ' || SQLERRM, 2000);
      END;
    END LOOP;
    IF v_ok THEN
      UPDATE public.domain_events
         SET status = 'processed', processed_at = now(), last_error = NULL
       WHERE id = ev.id;
      n_processed := n_processed + 1;
    ELSE
      UPDATE public.domain_events
         SET attempts   = ev.attempts + 1,
             last_error = v_err,
             status     = CASE WHEN ev.attempts + 1 >= 5 THEN 'failed' ELSE 'pending' END,
             processed_at = CASE WHEN ev.attempts + 1 >= 5 THEN now() ELSE NULL END
       WHERE id = ev.id;
      n_failed := n_failed + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('processed', n_processed, 'failed', n_failed);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_expenses_country()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_country text := TG_ARGV[0];
  v_src     text;
  v_uid     text;
  v_org     uuid;
begin
  if public.erp_is_footer(NEW."Item Description") or public.erp_is_footer(NEW."Work Order Number") then
    return null;
  end if;
  if coalesce(btrim(NEW."Item Description"), '') = ''
     and coalesce(btrim(NEW."Values"), '') = '' then
    return null;
  end if;

  v_org := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_src := nullif(btrim(coalesce(nullif(btrim(NEW."#"), ''), NEW.source_row)), '');

  -- Site aware: store + cost centre are part of which expense this is, so one
  -- site's line can never be mistaken for another site's.
  v_uid := public.parts_import_uid(v_country, v_src, NEW."Issue Number",
             NEW."Work Order Number", NEW."Itemcode", NEW."Item Description",
             NEW."Qty", NEW."Values", NEW."Transaction Type", NEW."Asset Code",
             NEW."Store Code", NEW."Cost Center");

  insert into public.parts_consumption
    (organisation_id, country, issue_number, work_order_no, txn_date, asset_code,
     asset_description, asset_type, store_code, cost_center, item_code, qty,
     item_description, value_amount, spare_parts_amount, tyre_amount, oil_amount,
     total_amount, source_row, import_uid)
  values (v_org, v_country, NEW."Issue Number", NEW."Work Order Number",
     NEW."Transaction Type", NEW."Asset Code", NEW."Asset Description", NEW."Asset Type",
     NEW."Store Code", NEW."Cost Center", NEW."Itemcode", NEW."Qty",
     NEW."Item Description", NEW."Values", NEW."Spare Parts", NEW."Trye", NEW."Oil",
     NEW."Total Parts Consumption", v_src, v_uid)
  on conflict do nothing;

  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_expenses_import()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.erp_is_footer(NEW."Item Description") or public.erp_is_footer(NEW."Work Order Number") then return null; end if;
  if coalesce(btrim(NEW."Item Description"),'')='' and coalesce(btrim(NEW."Values"),'')='' then return null; end if;
  insert into public.parts_consumption
    (organisation_id, country, issue_number, work_order_no, txn_date, asset_code, asset_description,
     asset_type, store_code, cost_center, item_code, qty, item_description,
     value_amount, spare_parts_amount, tyre_amount, oil_amount, total_amount, source_row)
  values (coalesce(public.app_current_org(),'00000000-0000-0000-0000-000000000001'::uuid),
     nullif(btrim(NEW."Country"),''), NEW."Issue Number", NEW."Work Order Number", NEW."Transaction Type",
     NEW."Asset Code", NEW."Asset Description", NEW."Asset Type", NEW."Store Code", NEW."Cost Center",
     NEW."Itemcode", NEW."Qty", NEW."Item Description", NEW."Values", NEW."Spare Parts", NEW."Trye",
     NEW."Oil", NEW."Total Parts Consumption", NEW."#");
  return null;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_assets()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(btrim(NEW.asset_no),'')='' OR public.erp_is_footer(NEW.asset_no) OR public.erp_is_footer(NEW.asset_desc) THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM public.vehicle_fleet v WHERE lower(btrim(v.asset_no))=lower(btrim(NEW.asset_no))
       AND v.country IS NOT DISTINCT FROM NEW.country) THEN RETURN NULL; END IF;
  INSERT INTO public.vehicle_fleet
    (country, asset_no, model, make, registration_no, chassis_no, serial_no, vehicle_type, site,
     arabic_location, status, asset_shift, current_km, current_hours, driver_licence_issue,
     driver_licence_expiry, mvip_issue, mvip_expiry, insurance_type, insurance_name, insurance_start,
     insurance_expiry, insurance_value, operating_card_no, operating_card_issue, operating_card_expiry,
     model_year, useful_life, operation_start_date, purchase_value, net_book_value, monthly_depreciation,
     fa_asset_number, asset_remarks, asset_extra)
  VALUES (NEW.country, NEW.asset_no, NEW.asset_desc, NEW.brand, NEW.plate_no, NEW.chassis_no, NEW.serial_no,
     NEW.asset_type, NEW.asset_location, NEW.arabic_location, NEW.asset_status, NEW.asset_shift,
     public._to_num(NEW.km), public._to_num(NEW.hour), public.erp_parse_date(NEW.driver_issue_date),
     public.erp_parse_date(NEW.driver_expiry_date), public.erp_parse_date(NEW.mvip_issue_date),
     public.erp_parse_date(NEW.mvip_expiry_date), NEW.insurance_type, NEW.insurance_name,
     public.erp_parse_date(NEW.insurance_start_date), public.erp_parse_date(NEW.insurance_expire_date),
     public._to_num(NEW.insurance_value), NEW.operating_card_no, public.erp_parse_date(NEW.operating_card_issue_date),
     public.erp_parse_date(NEW.operating_card_expiry_date), public._to_num(NEW.model_year)::int, NEW.useful_life,
     public.erp_parse_date(NEW.operation_start_date), public._to_num(NEW.purchase_value),
     public._to_num(NEW.net_book_value), public._to_num(NEW.monthly_depreciation_value), NEW.fa_asset_number,
     NEW.remarks, jsonb_strip_nulls(to_jsonb(NEW) - 'id' - 'organisation_id'));
  RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_complaints()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE outd date;
BEGIN
  IF public.erp_is_footer(NEW.veh_no) OR public.erp_is_footer(NEW.jc_no) THEN RETURN NULL; END IF;
  IF coalesce(btrim(NEW.jc_no),'')='' AND coalesce(btrim(NEW.veh_no),'')='' THEN RETURN NULL; END IF;
  IF NEW.jc_no IS NOT NULL AND EXISTS (
     SELECT 1 FROM public.work_orders w WHERE lower(btrim(w.work_order_no))=lower(btrim(NEW.jc_no))
       AND w.country IS NOT DISTINCT FROM NEW.country) THEN RETURN NULL; END IF;
  outd := public.erp_parse_date(NEW.vehicle_out_date);
  INSERT INTO public.work_orders
    (country, work_order_no, asset_no, work_type, status, priority, vor, description, notes,
     site, workshop_name, technician_name, odometer, opened_at, completed_at, custom_data)
  VALUES (NEW.country, NEW.jc_no, NEW.veh_no, 'Repair',
     CASE WHEN outd IS NOT NULL THEN 'Completed' ELSE 'In Progress' END, 'Medium', 'false',
     left(coalesce(NEW.complaints, NEW.reason_of_repair,''),1000),
     left(concat_ws(' | ', NULLIF(NEW.job_done_description,''), NULLIF(NEW.qc_remarks,'')),1500),
     NEW.location, NEW.workshop_location, NEW.driver_name, public._to_num(NEW.km_hr),
     public.erp_parse_date(NEW.vehicle_in_date), outd,
     jsonb_strip_nulls(jsonb_build_object('source','Vehicle Complaints History','make',NEW.make,
        'capacity',NEW.capacity,'std_hrs',NEW.std_hrs,'manpow_hrs',NEW.manpow_hrs,'total_bd_hrs',NEW.total_bd_hrs,
        'reason_of_repair',NEW.reason_of_repair,'tracking_category',NEW.tracking_category)));
  RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_job_cards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  j jsonb := to_jsonb(NEW);
  v_org uuid := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_country text := public._stg_pick(j, 'country');
  v_jc      text := public._stg_pick(j, 'Job Card No');
  v_prod_out timestamptz; v_ws_in timestamptz; v_ws_out timestamptz;
  v_prod_in timestamptz; v_target timestamptz;
  v_status text; v_type text; v_bd numeric; v_closed boolean;
  v_wait_p numeric; v_wait_m numeric; v_mp_hrs numeric; v_extra jsonb;
begin
  if v_jc is null then return null; end if;
  if public.erp_is_footer(coalesce(public._stg_pick(j,'RFR Number'),'') || ' ' || v_jc) then return null; end if;

  v_prod_out := public.erp_parse_ts(public._stg_pick(j,'Production Out'));
  v_ws_in    := public.erp_parse_ts(public._stg_pick(j,'Workshop In'));
  v_ws_out   := public.erp_parse_ts(public._stg_pick(j,'Workshop Out'));
  v_prod_in  := public.erp_parse_ts(public._stg_pick(j,'Production In'));
  v_target   := public.erp_parse_ts(public._stg_pick(j,'Excepted Job Date/Time'));

  v_status := initcap(coalesce(public._stg_pick(j,'Status'),''));
  if v_status not in ('Open','In Progress','Awaiting Parts','Completed','Closed','Cancelled') then
    v_status := case when v_prod_in is not null or v_ws_out is not null then 'Completed' else 'Open' end;
  end if;

  v_type := lower(coalesce(public._stg_pick(j,'Type'),''));
  v_type := case
    when v_type like '%break%'   then 'Emergency'
    when v_type like '%schedul%' then 'Preventive Maintenance'
    when v_type like '%general%' or v_type like '%repair%' then 'Repair'
    when v_type like '%servic%'  then 'Service'
    when v_type like '%tyre%' or v_type like '%tire%' then 'Tyre Change'
    when v_type like '%inspect%' then 'Inspection'
    else 'Other' end;

  v_closed := (v_prod_in is not null or v_ws_out is not null);
  v_bd     := case when v_closed then public._to_num(public._stg_pick(j,'Total Breakdown hours')) end;
  v_wait_p := case when v_closed then coalesce(
                 public._to_num(public._stg_pick(j,'Waiting Part Hrs')),
                 public._to_num(public._stg_pick(j,'Waiting Parts Hrs'))) end;
  v_wait_m := case when v_closed then coalesce(
                 public._to_num(public._stg_pick(j,'Waiting Manpower Hrs')),
                 public._to_num(public._stg_pick(j,'Waiting Manpower Hours'))) end;
  v_mp_hrs := case when v_closed then coalesce(
                 public._to_num(public._stg_pick(j,'Manpower H')),
                 public._to_num(public._stg_pick(j,'Manpower Hrs'))) end;

  v_extra := jsonb_strip_nulls(jsonb_build_object(
    'erp_reported_cost', jsonb_strip_nulls(jsonb_build_object(
        'spare_parts',  public._to_num(public._stg_pick(j,'Spare Parts')),
        'tyre',         public._to_num(public._stg_pick(j,'Tyre')),
        'oil',          public._to_num(public._stg_pick(j,'Oil')),
        'others',       public._to_num(public._stg_pick(j,'Others')),
        'manpower',     public._to_num(public._stg_pick(j,'Manpower Cost')),
        'total_parts',  public._to_num(public._stg_pick(j,'Total Parts Consumption')),
        'total_repair', public._to_num(public._stg_pick(j,'Total Repair Cost')))),
    'erp_hours', jsonb_strip_nulls(jsonb_build_object(
        'breakdown',        public._to_num(public._stg_pick(j,'Total Breakdown hours')),
        'waiting_parts',    coalesce(public._to_num(public._stg_pick(j,'Waiting Part Hrs')),
                                     public._to_num(public._stg_pick(j,'Waiting Parts Hrs'))),
        'waiting_manpower', coalesce(public._to_num(public._stg_pick(j,'Waiting Manpower Hrs')),
                                     public._to_num(public._stg_pick(j,'Waiting Manpower Hours'))),
        'manpower',         coalesce(public._to_num(public._stg_pick(j,'Manpower H')),
                                     public._to_num(public._stg_pick(j,'Manpower Hrs'))))),
    'raised_by', public._stg_pick(j,'RFR Created By'),
    'raised_at', public._stg_pick(j,'RFR Created Date'),
    'card_by',   public._stg_pick(j,'Job Card Created By'),
    'card_at',   public._stg_pick(j,'Job Card Created Date'),
    'erp_type',            public._stg_pick(j,'Type'),
    'erp_breakdown_hours', public._to_num(public._stg_pick(j,'Total Breakdown hours')),
    'still_open',          not v_closed,
    'mr_no',               public._stg_pick(j,'MR NO'),
    'sco_no',              public._stg_pick(j,'SCO NO'),
    'asset_description',   public._stg_pick(j,'Asset Description'),
    'truck_category',      public._stg_pick(j,'Truck Category'),
    'head_tail',           public._stg_pick(j,'Head/Tail')));

  insert into public.work_orders (
    organisation_id, country, work_order_no, rfr_no, source_row,
    asset_no, plate_no, asset_category, site, work_location, scope,
    status, work_type, description, notes,
    opened_at, started_at, completed_at, target_completion,
    production_out_at, production_in_at,
    breakdown_hours, standard_hours,
    waiting_parts_hours, waiting_manpower_hours, manpower_hours, mr_no, sco_no, asset_description, truck_category, head_tail, custom_data)
  values (
    v_org, v_country, v_jc,
    public._stg_pick(j,'RFR Number'),
    public._stg_pick(j,'#'),
    upper(public._stg_pick(j,'Asset Code')),
    public._stg_pick(j,'Plate No'),
    public._stg_pick(j,'Asset Category'),
    public._stg_pick(j,'Location'),
    public._stg_pick(j,'Work Location'),
    public._stg_pick(j,'Scope'),
    v_status, v_type,
    public._stg_pick(j,'Production Complaint'),
    public._stg_pick(j,'Job Repair Description'),
    coalesce(v_prod_out, v_ws_in, now()), v_ws_in, v_ws_out, v_target,
    v_prod_out, v_prod_in,
    v_bd, public._to_num(public._stg_pick(j,'STD. Hours')),
    v_wait_p, v_wait_m, v_mp_hrs, public._stg_pick(j,'MR NO'), public._stg_pick(j,'SCO NO'), public._stg_pick(j,'Asset Description'), public._stg_pick(j,'Truck Category'), public._stg_pick(j,'Head/Tail'), v_extra)
  on conflict (work_order_no) do update set
    country = excluded.country, rfr_no = excluded.rfr_no, source_row = excluded.source_row,
    asset_no = coalesce(excluded.asset_no, work_orders.asset_no),
    plate_no = coalesce(excluded.plate_no, work_orders.plate_no),
    asset_category = coalesce(excluded.asset_category, work_orders.asset_category),
    site = coalesce(excluded.site, work_orders.site),
    work_location = coalesce(excluded.work_location, work_orders.work_location),
    scope = coalesce(excluded.scope, work_orders.scope),
    status = excluded.status, work_type = excluded.work_type,
    description = coalesce(excluded.description, work_orders.description),
    notes = coalesce(excluded.notes, work_orders.notes),
    opened_at = coalesce(excluded.opened_at, work_orders.opened_at),
    started_at = coalesce(excluded.started_at, work_orders.started_at),
    completed_at = coalesce(excluded.completed_at, work_orders.completed_at),
    target_completion = coalesce(excluded.target_completion, work_orders.target_completion),
    production_out_at = coalesce(excluded.production_out_at, work_orders.production_out_at),
    production_in_at = coalesce(excluded.production_in_at, work_orders.production_in_at),
    breakdown_hours = excluded.breakdown_hours,
    standard_hours = coalesce(excluded.standard_hours, work_orders.standard_hours),
    waiting_parts_hours = excluded.waiting_parts_hours,
    waiting_manpower_hours = excluded.waiting_manpower_hours,
    manpower_hours = excluded.manpower_hours,
    mr_no             = coalesce(excluded.mr_no,             work_orders.mr_no),
    sco_no            = coalesce(excluded.sco_no,            work_orders.sco_no),
    asset_description = coalesce(excluded.asset_description, work_orders.asset_description),
    truck_category    = coalesce(excluded.truck_category,    work_orders.truck_category),
    head_tail         = coalesce(excluded.head_tail,         work_orders.head_tail),
    custom_data = coalesce(work_orders.custom_data,'{}'::jsonb) || excluded.custom_data,
    updated_at = now();

  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_monthly_tyres()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rd date; fd date; tmp_d date;
  fkm numeric; rkm numeric; fhr numeric; rhr numeric; tmp_n numeric;
  v_tyre_record_id uuid;
  v_payload jsonb;
  v_live jsonb;
  v_incoming jsonb;
  v_patch jsonb;
  v_close jsonb;
  v_cols text[] := array[
    'asset_no','job_card','vehicle_type','size','position','tyre_position','issue_date',
    'km_at_fitment','hrs_at_fitment','removal_date','km_at_removal','hrs_at_removal',
    'total_km','total_hrs','removal_reason','status','brand'
  ];
begin
  v_payload := to_jsonb(new);

  if public.erp_is_footer(new.job_card_no) or public.erp_is_footer(new.veh_no) then
    insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload)
    values (new.country, new.organisation_id, 'rejected', 'footer_row', v_payload);
    return null;
  end if;

  if coalesce(btrim(new.tyre_no),'')='' and coalesce(btrim(new.veh_no),'')='' then
    insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload)
    values (new.country, new.organisation_id, 'rejected', 'blank_tyre_and_vehicle', v_payload);
    return null;
  end if;

  fd := public.erp_parse_date(new.tyre_fix_date);
  rd := public.erp_parse_date(new.tyre_removed_date);
  fkm := public._to_num(new.fixed_km); rkm := public._to_num(new.removed_km);
  fhr := public._to_num(new.fixed_hrs); rhr := public._to_num(new.removed_hrs);

  if fd is not null and rd is not null and rd < fd then tmp_d:=fd; fd:=rd; rd:=tmp_d; end if;
  if fkm is not null and rkm is not null and rkm < fkm then tmp_n:=fkm; fkm:=rkm; rkm:=tmp_n; end if;
  if fhr is not null and rhr is not null and rhr < fhr then tmp_n:=fhr; fhr:=rhr; rhr:=tmp_n; end if;

  v_incoming := jsonb_strip_nulls(jsonb_build_object(
    'asset_no', new.veh_no, 'job_card', new.job_card_no, 'vehicle_type', new.veh_type,
    'size', new.item_tyre, 'position', new.tyre_position, 'tyre_position', new.tyre_position,
    'issue_date', fd, 'km_at_fitment', fkm, 'hrs_at_fitment', fhr,
    'removal_date', rd, 'km_at_removal', rkm, 'hrs_at_removal', rhr,
    'total_km', public._to_num(new.total_km), 'total_hrs', public._to_num(new.total_hrs),
    'removal_reason', new.reason, 'status', case when rd is not null then 'Removed' else 'Active' end,
    'brand', nullif(btrim(new.brand),'')
  ));

  select t.id, to_jsonb(t) into v_tyre_record_id, v_live
  from public.tyre_records t
  where lower(btrim(t.serial_no)) = lower(btrim(new.tyre_no))
    and t.country is not distinct from new.country
    and t.issue_date is not distinct from fd
    and coalesce(lower(btrim(t.job_card)),'') = coalesce(lower(btrim(new.job_card_no)),'')
    and coalesce(lower(btrim(t.position)),'') = coalesce(lower(btrim(new.tyre_position)),'')
  order by t.created_at
  limit 1;

  if v_tyre_record_id is not null then
    v_patch := public.import_changed_supplied_patch(v_live, v_incoming, v_cols);
    if v_patch = '{}'::jsonb then
      insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload, tyre_record_id)
      values (new.country, new.organisation_id, 'rejected', 'exact_duplicate', v_payload, v_tyre_record_id);
      return null;
    end if;

    update public.tyre_records t set
      asset_no = coalesce(v_patch->>'asset_no', t.asset_no),
      job_card = coalesce(v_patch->>'job_card', t.job_card),
      vehicle_type = coalesce(v_patch->>'vehicle_type', t.vehicle_type),
      size = coalesce(v_patch->>'size', t.size),
      position = coalesce(v_patch->>'position', t.position),
      tyre_position = coalesce(v_patch->>'tyre_position', t.tyre_position),
      issue_date = coalesce((v_patch->>'issue_date')::date, t.issue_date),
      km_at_fitment = coalesce((v_patch->>'km_at_fitment')::numeric, t.km_at_fitment),
      hrs_at_fitment = coalesce((v_patch->>'hrs_at_fitment')::numeric, t.hrs_at_fitment),
      removal_date = coalesce((v_patch->>'removal_date')::date, t.removal_date),
      km_at_removal = coalesce((v_patch->>'km_at_removal')::numeric, t.km_at_removal),
      hrs_at_removal = coalesce((v_patch->>'hrs_at_removal')::numeric, t.hrs_at_removal),
      total_km = coalesce((v_patch->>'total_km')::numeric, t.total_km),
      total_hrs = coalesce((v_patch->>'total_hrs')::numeric, t.total_hrs),
      removal_reason = coalesce(v_patch->>'removal_reason', t.removal_reason),
      status = coalesce(v_patch->>'status', t.status),
      brand = coalesce(v_patch->>'brand', t.brand)
    where t.id = v_tyre_record_id;

    insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload, tyre_record_id)
    values (new.country, new.organisation_id, 'accepted', 'updated_changed_values', v_payload, v_tyre_record_id);
    return null;
  end if;

  -- 20261109090000: an incoming CURRENT fitment replaces the tyre on that
  -- wheel. Close it when the evidence is clear; otherwise hold for review.
  if rd is null then
    v_close := public._tyre_close_replaced(
      coalesce(new.organisation_id, '00000000-0000-0000-0000-000000000001'::uuid),
      public.normalize_country(new.country), new.veh_no, new.tyre_position, new.tyre_no,
      fd, fkm, fhr, 'stg_monthly_tyres', gen_random_uuid(), false);
    if coalesce(v_close->>'status', '') not in ('closed', 'no_previous', 'not_applicable') then
      insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload, tyre_record_id)
      values (new.country, new.organisation_id, 'rejected',
              'replacement_needs_review:' || coalesce(v_close->>'status', 'unknown'),
              v_payload, nullif(v_close->>'tyre_id', '')::uuid);
      return null;
    end if;
    perform public._tyre_close_serial_elsewhere(coalesce(new.organisation_id, '00000000-0000-0000-0000-000000000001'::uuid),
      public.normalize_country(new.country), new.veh_no, new.tyre_no, fd, 'stg_monthly_tyres', gen_random_uuid(), false);
  end if;

  insert into public.tyre_records
    (country, serial_no, asset_no, job_card, vehicle_type, size, position, tyre_position,
     issue_date, km_at_fitment, hrs_at_fitment, removal_date, km_at_removal, hrs_at_removal,
     total_km, total_hrs, removal_reason, status, brand, extra_fields)
  values (new.country, new.tyre_no, new.veh_no, new.job_card_no, new.veh_type, new.item_tyre,
     new.tyre_position, new.tyre_position, fd, fkm, fhr, rd, rkm, rhr,
     public._to_num(new.total_km), public._to_num(new.total_hrs),
     new.reason, case when rd is not null then 'Removed' else 'Active' end,
     nullif(btrim(new.brand),''),
     jsonb_strip_nulls(jsonb_build_object('job_card',new.job_card_no,'fixed_km',new.fixed_km,'removed_km',new.removed_km,'reason',new.reason)))
  returning id into v_tyre_record_id;

  insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload, tyre_record_id)
  values (new.country, new.organisation_id, 'accepted', 'inserted', v_payload, v_tyre_record_id);
  return null;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_open_wo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org      uuid;
  v_existing uuid;
begin
  if coalesce(btrim(NEW.job_card_no), '') = ''
     or public.erp_is_footer(NEW.location)
     or public.erp_is_footer(NEW.job_card_no) then
    return null;
  end if;

  v_org := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);

  select o.id into v_existing
    from public.open_work_orders o
   where o.organisation_id is not distinct from v_org
     and o.country is not distinct from NEW.country
     and lower(btrim(o.job_card_no)) = lower(btrim(NEW.job_card_no))
   order by o.created_at desc
   limit 1;

  if v_existing is not null then
    update public.open_work_orders
       set location      = NEW.location,
           job_card_type = NEW.job_card_type,
           jc_status     = NEW.jc_status,
           job_card_date = public.erp_parse_date(NEW.job_card_date),
           open_time     = NEW.jc_open_time,
           asset_type    = NEW.asset_type,
           asset_no      = NEW.asset_no,
           days_open     = public._to_num(NEW.no_of_days_jc_open),
           complaint     = NEW.complaint
     where id = v_existing;
  else
    insert into public.open_work_orders
      (organisation_id, country, job_card_no, location, job_card_type, jc_status,
       job_card_date, open_time, asset_type, asset_no, days_open, complaint)
    values (v_org, NEW.country, NEW.job_card_no, NEW.location, NEW.job_card_type,
       NEW.jc_status, public.erp_parse_date(NEW.job_card_date), NEW.jc_open_time,
       NEW.asset_type, NEW.asset_no, public._to_num(NEW.no_of_days_jc_open),
       NEW.complaint);
  end if;

  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_parts_grid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.erp_is_footer(NEW.item_description) OR public.erp_is_footer(NEW.work_order_number) THEN RETURN NULL; END IF;
  IF coalesce(btrim(NEW.item_description),'')='' AND coalesce(btrim(NEW.value_amt),'')='' THEN RETURN NULL; END IF;
  INSERT INTO public.parts_consumption
    (country, issue_number, work_order_no, txn_date, asset_code, asset_description, asset_type,
     store_code, cost_center, item_code, qty, item_description, value_amount, spare_parts_amount,
     tyre_amount, oil_amount, total_amount, source_row)
  VALUES (NEW.country, NEW.issue_number, NEW.work_order_number, NEW.transaction_date, NEW.asset_code,
     NEW.asset_description, NEW.asset_type, NEW.store_code, NEW.cost_center, NEW.itemcode, NEW.qty,
     NEW.item_description, NEW.value_amt, NEW.spare_parts, NEW.trye, NEW.oil, NEW.total_parts, NEW.source_row);
  RETURN NULL;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_tyre_brand()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(btrim(NEW.serial),'')='' or coalesce(btrim(NEW.brand),'')='' then return null; end if;
  update public.tyre_records t
     set brand = btrim(NEW.brand)
   where t.country is not distinct from NEW.country
     and lower(btrim(t.serial_no)) = lower(btrim(NEW.serial))
     and (t.brand is null or t.brand='');
  return null;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.process_stg_wo_lines()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid; v_src int;
begin
  if public.erp_is_footer(NEW.work_order_no) then return null; end if;
  if coalesce(btrim(NEW.work_order_no),'')='' then return null; end if;
  v_org := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_src := nullif(regexp_replace(coalesce(NEW.source_row,''),'[^0-9-]','','g'),'')::int;
  -- idempotent: skip an identical line already loaded for this card in this country
  if exists (
     select 1 from public.work_order_line_items l
     where l.organisation_id = v_org
       and l.country is not distinct from NEW.country
       and lower(btrim(l.work_order_no)) = lower(btrim(NEW.work_order_no))
       and l.source_row is not distinct from v_src
       and coalesce(l.task,'') = coalesce(NEW.task,'')
       and coalesce(l.action,'') = coalesce(NEW.action,'')
  ) then return null; end if;
  insert into public.work_order_line_items
    (organisation_id, country, work_order_no, asset_no, site, opened_date,
     work_type, task, detail, action, qty, source_row)
  values (v_org, NEW.country, NEW.work_order_no, NEW.asset_no, NEW.site,
     public.erp_parse_date(NEW.opened_date), NEW.work_type, NEW.task, NEW.detail,
     NEW.action, public._to_num(NEW.qty), v_src);
  return null;
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.promote_erp_assets(p_batch uuid, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public._erp_promote_guard_c('erp_asset_import', p_batch);
  r record; v_country text; v_asset text; v_new_id uuid; v_live_id uuid;
  v_live jsonb; v_incoming jsonb; v_patch jsonb; v_before jsonb; v_set text;
  v_ins jsonb := '{}'::jsonb;
  v_skip int := 0; v_ins_tot int := 0; v_updated int := 0; v_exact int := 0;
  v_cols text[] := array[
    'site','make','vehicle_type','model_year','current_km','current_hours','status',
    'operator_name','insurance_type','insurance_name','insurance_start','insurance_expiry',
    'operating_card_no','operating_card_issue','operating_card_expiry','driver_licence_issue',
    'driver_licence_expiry','purchase_value','net_book_value','monthly_depreciation',
    'operation_start_date','fa_asset_number','asset_remarks','registration_no','asset_extra'
  ];
begin
  for r in
    select s.* from public.erp_asset_import s
    where s.batch_id=p_batch and s.organisation_id=v_org
      and not exists (select 1 from erp_promote_bak.promotion_log l where l.source_staging_id=s.id)
    order by s.source_row
  loop
    v_asset := nullif(upper(btrim(coalesce(r.asset_no,''))), '');
    if v_asset is null then v_skip:=v_skip+1; continue; end if;
    v_country := coalesce(public.normalize_country(r.country), public._erp_country_from_prefix(v_asset), 'KSA');
    -- V567: the V559 batch guard inspects the DECLARED country and skips rows
    -- whose country is NULL; the country actually WRITTEN is DERIVED above from
    -- the asset / job-card prefix, so a NULL-country staged row walked past it.
    -- Scope the value that is about to be written.
    if not public.app_write_country_ok(v_country) then
      raise exception 'Cross-country promotion denied (%).', v_country using errcode='42501';
    end if;
    v_incoming := jsonb_strip_nulls(jsonb_build_object(
      'site',r.site,'make',r.make,'vehicle_type',r.asset_type,'model_year',r.model_year,
      'current_km',r.current_km,'current_hours',r.hour_meter,
      'status',case when nullif(btrim(coalesce(r.status,'')),'') is null then null
        when r.status ~* 'inactive|retire|dispos' then 'Inactive' else 'Active' end,
      'operator_name',r.operator,'insurance_type',r.insurance_type,'insurance_name',r.insurance_name,
      'insurance_start',r.insurance_start,'insurance_expiry',r.insurance_end,
      'operating_card_no',r.operating_card_no,'operating_card_issue',r.card_issue_date,
      'operating_card_expiry',r.card_expiry_date,'driver_licence_issue',r.licence_issue,
      'driver_licence_expiry',r.licence_expiry,'purchase_value',r.purchase_value,
      'net_book_value',r.net_book_value,'monthly_depreciation',r.monthly_dep,
      'operation_start_date',r.opr_start_date,'fa_asset_number',r.finance_asset_no,
      'asset_remarks',r.remarks,'registration_no',r.plate_no,
      'asset_extra',nullif(jsonb_strip_nulls(jsonb_build_object('capacity',r.capacity,'shift',r.shift,
        'second_user',r.second_user,'age_of_asset',r.age_of_asset,'org_ou',r.org_ou)),'{}'::jsonb)
    ));

    select f.id,to_jsonb(f) into v_live_id,v_live from public.vehicle_fleet f
    where f.organisation_id=v_org and coalesce(f.country,'')=coalesce(v_country,'')
      and upper(btrim(f.asset_no))=v_asset limit 1;

    if v_live_id is not null then
      v_patch := public.import_changed_supplied_patch(v_live,v_incoming,v_cols);
      if v_patch='{}'::jsonb then v_exact:=v_exact+1; else v_updated:=v_updated+1; end if;
      if not p_dry_run then
        if v_patch <> '{}'::jsonb then
          v_before := public.import_jsonb_pick(v_live, array(select jsonb_object_keys(v_patch)));
          select string_agg(format('%I=(jsonb_populate_record(t,$1)).%I',k,k),', ')
            into v_set from jsonb_object_keys(v_patch) k;
          execute format('update public.vehicle_fleet t set %s where id=$2',v_set) using v_patch,v_live_id;
        end if;
        insert into erp_promote_bak.promotion_log
          (dataset,batch_id,organisation_id,master_table,master_id,source_staging_id,action,detail)
        values ('asset',p_batch,v_org,'vehicle_fleet',v_live_id,r.id,
          case when v_patch='{}'::jsonb then 'exact' else 'update' end,
          case when v_patch='{}'::jsonb then '{}'::jsonb else jsonb_build_object('before',v_before,'after',v_patch) end);
        update public.erp_asset_import set promoted_at=now(),promoted_by=auth.uid() where id=r.id;
      end if;
      continue;
    end if;

    v_ins := jsonb_set(v_ins,array[v_country],to_jsonb(coalesce((v_ins->>v_country)::int,0)+1),true);
    v_ins_tot:=v_ins_tot+1;
    if not p_dry_run then
      insert into public.vehicle_fleet
        (organisation_id,asset_no,country,region,site,make,vehicle_type,model_year,current_km,current_hours,
         status,operator_name,insurance_type,insurance_name,insurance_start,insurance_expiry,
         operating_card_no,operating_card_issue,operating_card_expiry,driver_licence_issue,
         driver_licence_expiry,purchase_value,net_book_value,monthly_depreciation,operation_start_date,
         fa_asset_number,asset_remarks,registration_no,asset_extra)
      values (v_org,v_asset,v_country,v_country,r.site,r.make,r.asset_type,r.model_year,r.current_km,r.hour_meter,
        case when r.status ~* 'inactive|retire|dispos' then 'Inactive' else 'Active' end,
        r.operator,r.insurance_type,r.insurance_name,r.insurance_start,r.insurance_end,r.operating_card_no,
        r.card_issue_date,r.card_expiry_date,r.licence_issue,r.licence_expiry,r.purchase_value,r.net_book_value,
        r.monthly_dep,r.opr_start_date,r.finance_asset_no,r.remarks,r.plate_no,
        jsonb_strip_nulls(jsonb_build_object('import','erp_asset','erp_batch',p_batch::text,
          'source_row',r.source_row,'capacity',r.capacity,'shift',r.shift,'second_user',r.second_user,
          'age_of_asset',r.age_of_asset,'org_ou',r.org_ou))) returning id into v_new_id;
      insert into erp_promote_bak.promotion_log
        (dataset,batch_id,organisation_id,master_table,master_id,source_staging_id,action)
      values ('asset',p_batch,v_org,'vehicle_fleet',v_new_id,r.id,'insert');
      update public.erp_asset_import set promoted_at=now(),promoted_by=auth.uid() where id=r.id;
    end if;
  end loop;
  return jsonb_build_object('dataset','asset','batch_id',p_batch,'dry_run',p_dry_run,
    'to_insert_total',v_ins_tot,'to_insert_by_country',v_ins,'updated',v_updated,
    'exact_duplicates',v_exact,'skipped_no_asset_no',v_skip);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.promote_erp_tyre_changes(p_batch uuid, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; v_org uuid := public._erp_promote_guard_c('erp_tyre_change_import', p_batch);
  v_country text; v_asset text; v_pos text; v_status text; v_removal date;
  v_active_conflict boolean; v_new_id uuid; v_live_id uuid;
  v_live jsonb; v_incoming jsonb; v_patch jsonb; v_before jsonb; v_set text;
  v_ins_active int:=0; v_ins_old int:=0; v_updated int:=0; v_exact int:=0;
  v_skip_key int:=0; v_conflicts int:=0; v_by_country jsonb:='{}'::jsonb;
  v_cols text[] := array['brand','size','job_card','site','removal_date','km_at_fitment',
    'km_at_removal','hrs_at_fitment','hrs_at_removal','total_km','status'];
begin
  for r in
    with cand as (
      select s.*,nullif(lower(btrim(coalesce(s.asset_no,''))),'') g_asset,
        nullif(lower(btrim(coalesce(s.tire_pos,''))),'') g_pos
      from public.erp_tyre_change_import s
      where s.batch_id=p_batch and s.organisation_id=v_org
        and not exists(select 1 from erp_promote_bak.promotion_log l where l.source_staging_id=s.id)
    )
    select c.*,row_number() over(partition by c.g_asset,c.g_pos
      order by (c.fix_date is null) desc,c.fix_date,c.source_row) rn,
      count(*) over(partition by c.g_asset,c.g_pos) grp_n
    from cand c order by c.source_row
  loop
    if nullif(btrim(coalesce(r.serial_no,'')),'') is null
       or nullif(btrim(coalesce(r.asset_no,'')),'') is null then v_skip_key:=v_skip_key+1; continue; end if;
    v_asset:=upper(btrim(r.asset_no));
    v_pos:=nullif(upper(btrim(coalesce(r.tire_pos,''))),'');
    v_country:=coalesce(public.normalize_country(r.country),public._erp_country_from_prefix(coalesce(v_asset,r.job_card)),'KSA');
    -- V567: the V559 batch guard inspects the DECLARED country and skips rows
    -- whose country is NULL; the country actually WRITTEN is DERIVED above from
    -- the asset / job-card prefix, so a NULL-country staged row walked past it.
    -- Scope the value that is about to be written.
    if not public.app_write_country_ok(v_country) then
      raise exception 'Cross-country promotion denied (%).', v_country using errcode='42501';
    end if;
    v_removal:=case when r.remove_date is null then null when r.fix_date is null then r.remove_date
      when r.remove_date>=r.fix_date then r.remove_date else null end;

    select t.id,to_jsonb(t) into v_live_id,v_live from public.tyre_records t
    where t.organisation_id=v_org and coalesce(t.country,'')=coalesce(v_country,'')
      and lower(btrim(coalesce(t.serial_no,'')))=lower(btrim(r.serial_no))
      and upper(btrim(coalesce(t.asset_no,t.asset_number,'')))=v_asset
      and coalesce(nullif(upper(btrim(coalesce(t.tyre_position,t.position,''))),''),'')=coalesce(v_pos,'')
      and t.issue_date is not distinct from r.fix_date
    order by t.created_at limit 1;

    if v_live_id is not null then
      v_status:=case when v_removal is not null then 'Removed' else coalesce(v_live->>'status','Active') end;
      v_incoming:=jsonb_strip_nulls(jsonb_build_object('brand',r.tyre_brand,'size',r.tyre_size,
        'job_card',r.job_card,'site',r.site,'removal_date',v_removal,'km_at_fitment',r.fix_km,
        'km_at_removal',r.remove_km,'hrs_at_fitment',r.fix_hour,'hrs_at_removal',r.remove_hour,
        'total_km',r.total_km,'status',v_status));
      v_patch:=public.import_changed_supplied_patch(v_live,v_incoming,v_cols);
      if v_patch='{}'::jsonb then v_exact:=v_exact+1; else v_updated:=v_updated+1; end if;
      if not p_dry_run then
        if v_patch<>'{}'::jsonb then
          v_before:=public.import_jsonb_pick(v_live,array(select jsonb_object_keys(v_patch)));
          select string_agg(format('%I=(jsonb_populate_record(t,$1)).%I',k,k),', ')
            into v_set from jsonb_object_keys(v_patch) k;
          execute format('update public.tyre_records t set %s where id=$2',v_set) using v_patch,v_live_id;
        end if;
        insert into erp_promote_bak.promotion_log
          (dataset,batch_id,organisation_id,master_table,master_id,source_staging_id,action,detail)
        values ('change',p_batch,v_org,'tyre_records',v_live_id,r.id,
          case when v_patch='{}'::jsonb then 'exact' else 'update' end,
          case when v_patch='{}'::jsonb then '{}'::jsonb else jsonb_build_object('before',v_before,'after',v_patch) end);
        update public.erp_tyre_change_import set promoted_at=now(),promoted_by=auth.uid() where id=r.id;
      end if;
      continue;
    end if;

    v_active_conflict:=false;
    if v_pos is not null and v_pos<>'0' then
      select exists(select 1 from public.tyre_records t where t.organisation_id=v_org
        and coalesce(t.country,'')=coalesce(v_country,'')
        and upper(btrim(coalesce(t.asset_no,t.asset_number,'')))=v_asset
        and coalesce(nullif(upper(btrim(coalesce(t.tyre_position,t.position,''))),''),'')=v_pos
        and public.tyre_status_is_active(t.status)) into v_active_conflict;
    end if;
    v_status:=case when r.rn=r.grp_n and v_removal is null and not v_active_conflict then 'Active' else 'Removed' end;
    if v_status='Active' then v_ins_active:=v_ins_active+1; else v_ins_old:=v_ins_old+1; end if;
    if v_active_conflict and v_removal is null and r.rn=r.grp_n then v_conflicts:=v_conflicts+1; end if;
    v_by_country:=jsonb_set(v_by_country,array[v_country],to_jsonb(coalesce((v_by_country->>v_country)::int,0)+1),true);
    if not p_dry_run then
      begin
        insert into public.tyre_records
          (organisation_id,country,region,serial_no,asset_no,tyre_position,position,brand,size,job_card,
           site,issue_date,removal_date,km_at_fitment,km_at_removal,hrs_at_fitment,hrs_at_removal,
           total_km,status,data_source,upload_batch_id,qty,extra_fields)
        values (v_org,v_country,v_country,r.serial_no,v_asset,r.tire_pos,r.tire_pos,r.tyre_brand,
          r.tyre_size,r.job_card,r.site,r.fix_date,v_removal,r.fix_km,r.remove_km,r.fix_hour,
          r.remove_hour,r.total_km,v_status,'upload',p_batch,1,
          jsonb_strip_nulls(jsonb_build_object('import','erp_tyre_change','erp_batch',p_batch::text,
            'source_row',r.source_row,'old_serial_no',r.old_serial_no,'old_tyre_brand',r.old_tyre_brand,
            'version',r.version))) returning id into v_new_id;
      exception when unique_violation then
        insert into public.tyre_records
          (organisation_id,country,region,serial_no,asset_no,tyre_position,position,brand,size,job_card,
           site,issue_date,removal_date,km_at_fitment,km_at_removal,hrs_at_fitment,hrs_at_removal,
           total_km,status,data_source,upload_batch_id,qty,extra_fields)
        values (v_org,v_country,v_country,r.serial_no,v_asset,r.tire_pos,r.tire_pos,r.tyre_brand,
          r.tyre_size,r.job_card,r.site,r.fix_date,v_removal,r.fix_km,r.remove_km,r.fix_hour,
          r.remove_hour,r.total_km,'Removed','upload',p_batch,1,
          jsonb_strip_nulls(jsonb_build_object('import','erp_tyre_change','erp_batch',p_batch::text,
            'source_row',r.source_row,'old_serial_no',r.old_serial_no,'old_tyre_brand',r.old_tyre_brand,
            'version',r.version,'downgraded','active fitment already present'))) returning id into v_new_id;
        v_conflicts:=v_conflicts+1;
      end;
      insert into erp_promote_bak.promotion_log
        (dataset,batch_id,organisation_id,master_table,master_id,source_staging_id,action)
      values ('change',p_batch,v_org,'tyre_records',v_new_id,r.id,'insert');
      update public.erp_tyre_change_import set promoted_at=now(),promoted_by=auth.uid() where id=r.id;
    end if;
  end loop;
  return jsonb_build_object('dataset','change','batch_id',p_batch,'dry_run',p_dry_run,
    'to_insert_active',v_ins_active,'to_insert_old',v_ins_old,'to_insert_total',v_ins_active+v_ins_old,
    'to_insert_by_country',v_by_country,'updated',v_updated,'exact_duplicates',v_exact,
    'already_present',v_exact,'skipped_no_key',v_skip_key,'active_position_conflicts',v_conflicts);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.promote_erp_tyre_expense(p_batch uuid, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; v_org uuid := public._erp_promote_guard_c('erp_tyre_expense_import', p_batch);
  v_country text; v_asset text; v_qty numeric; v_value numeric; v_desc text; v_code text; v_uid text; v_new_id uuid;
  v_ins_tot int := 0; v_existing int := 0; v_skip int := 0; v_by_country jsonb := '{}'::jsonb;
begin
  for r in
    select s.* from public.erp_tyre_expense_import s
    where s.batch_id = p_batch and s.organisation_id = v_org
      and not exists (select 1 from erp_promote_bak.promotion_log l where l.source_staging_id = s.id)
    order by s.source_row
  loop
    v_qty := coalesce(r.quantity, 1);
    if v_qty is null or v_qty <= 0 then v_qty := 1; end if;
    v_value := case when r.unit_cost is null then null else round(r.unit_cost * v_qty, 4) end;
    if v_value is null or v_value = 0 then v_skip := v_skip + 1; continue; end if;
    v_asset := nullif(upper(btrim(coalesce(r.asset_no,''))),'');
    v_country := coalesce(public.normalize_country(r.country),
      public._erp_country_from_prefix(coalesce(v_asset, r.job_card)), 'KSA');
    -- V567: the V559 batch guard inspects the DECLARED country and skips rows
    -- whose country is NULL; the country actually WRITTEN is DERIVED above from
    -- the asset / job-card prefix, so a NULL-country staged row walked past it.
    -- Scope the value that is about to be written.
    if not public.app_write_country_ok(v_country) then
      raise exception 'Cross-country promotion denied (%).', v_country using errcode='42501';
    end if;
    v_desc := nullif(btrim(concat_ws(' ', r.tyre_brand, r.tyre_size, 'TYRE')), '');
    if v_desc is null then v_desc := 'TYRE PURCHASE'; end if;
    v_code := coalesce(nullif(btrim(r.po_no),''), nullif(btrim(r.invoice_no),''),
                       'TYRE-' || coalesce(nullif(btrim(r.serial_no),''), r.source_row::text));
    v_uid := coalesce(public.parts_import_uid(v_country, r.source_row::text, coalesce(r.invoice_no,''),
      coalesce(r.job_card,''), v_code, v_desc, v_qty::text, v_value::text,
      coalesce(r.purchase_date::text,''), coalesce(v_asset,''), null, null),
      md5('erp_tyre_expense|' || r.id::text));
    if p_dry_run then
      if exists (select 1 from public.parts_consumption p where p.organisation_id = v_org and p.import_uid = v_uid) then
        v_existing := v_existing + 1; continue;
      end if;
    end if;
    if not p_dry_run then
      insert into public.parts_consumption (
        organisation_id, country, txn_date, event_date, work_order_no, asset_code,
        item_code, item_description, qty, value_amount, unit_cost, currency,
        supplier, source_row, import_uid, source_system, store_code, cost_center
      ) values (
        v_org, v_country, r.purchase_date::text, r.purchase_date, r.job_card, v_asset,
        v_code, v_desc, v_qty::text, v_value::text, r.unit_cost, r.currency,
        r.supplier, r.source_row::text, v_uid, 'ERP tyre expense import', null, null
      )
      on conflict (organisation_id, import_uid) where import_uid is not null do nothing
      returning id into v_new_id;
      if v_new_id is null then
        v_existing := v_existing + 1;
        insert into erp_promote_bak.promotion_log (dataset, batch_id, organisation_id, master_table, master_id, source_staging_id, action)
          values ('expense', p_batch, v_org, 'parts_consumption', null, r.id, 'exists');
        update public.erp_tyre_expense_import set promoted_at = now(), promoted_by = auth.uid() where id = r.id;
        continue;
      end if;
      insert into erp_promote_bak.promotion_log (dataset, batch_id, organisation_id, master_table, master_id, source_staging_id, action)
        values ('expense', p_batch, v_org, 'parts_consumption', v_new_id, r.id, 'insert');
      update public.erp_tyre_expense_import set promoted_at = now(), promoted_by = auth.uid() where id = r.id;
    end if;
    v_ins_tot := v_ins_tot + 1;
    v_by_country := jsonb_set(v_by_country, array[v_country], jsonb_build_object(
      'count', coalesce((v_by_country#>>array[v_country,'count'])::int,0) + 1,
      'value', round(coalesce((v_by_country#>>array[v_country,'value'])::numeric,0) + v_value, 2),
      'currency', coalesce(r.currency, public.currency_for_country(v_country))
    ), true);
  end loop;
  return jsonb_build_object('dataset','expense', 'batch_id', p_batch, 'dry_run', p_dry_run,
    'to_insert_total', v_ins_tot, 'by_country', v_by_country,
    'already_present', v_existing, 'skipped_no_cost', v_skip);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.promote_erp_undo(p_dataset text, p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid:=public._erp_promote_guard();
  v_deleted int:=0; v_restored int:=0; v_set text; x record;
  v_staging text:=case p_dataset when 'asset' then 'erp_asset_import'
    when 'change' then 'erp_tyre_change_import' when 'expense' then 'erp_tyre_expense_import' else null end;
begin
  if v_staging is null then raise exception 'Unknown dataset %',p_dataset using errcode='22023'; end if;

  for x in select * from erp_promote_bak.promotion_log l
    where l.dataset=p_dataset and l.batch_id=p_batch and l.organisation_id=v_org
      and l.action='update' and l.master_id is not null and l.detail ? 'before'
    order by l.promoted_at desc
  loop
    select string_agg(format('%I=(jsonb_populate_record(t,$1)).%I',k,k),', ')
      into v_set from jsonb_object_keys(x.detail->'before') k;
    if v_set is not null then
      if x.master_table='vehicle_fleet' then
        execute format('update public.vehicle_fleet t set %s where id=$2 and public.app_write_country_ok(t.country) is not false',v_set)
          using x.detail->'before',x.master_id;
      elsif x.master_table='tyre_records' then
        execute format('update public.tyre_records t set %s where id=$2 and public.app_write_country_ok(t.country) is not false',v_set)
          using x.detail->'before',x.master_id;
      end if;
      v_restored:=v_restored+1;
    end if;
  end loop;

  if p_dataset='asset' then
    delete from public.vehicle_fleet f using erp_promote_bak.promotion_log l
    where l.dataset='asset' and l.batch_id=p_batch and l.organisation_id=v_org
      and l.action='insert' and l.master_table='vehicle_fleet' and f.id=l.master_id
      and public.app_write_country_ok(f.country) is not false;
    get diagnostics v_deleted=row_count;
  elsif p_dataset='change' then
    delete from public.tyre_records t using erp_promote_bak.promotion_log l
    where l.dataset='change' and l.batch_id=p_batch and l.organisation_id=v_org
      and l.action='insert' and l.master_table='tyre_records' and t.id=l.master_id
      and public.app_write_country_ok(t.country) is not false;
    get diagnostics v_deleted=row_count;
  elsif p_dataset='expense' then
    delete from public.parts_consumption p using erp_promote_bak.promotion_log l
    where l.dataset='expense' and l.batch_id=p_batch and l.organisation_id=v_org
      and l.action='insert' and l.master_table='parts_consumption' and p.id=l.master_id
      and public.app_write_country_ok(p.country) is not false;
    get diagnostics v_deleted=row_count;
  end if;

  -- V567: scope the staging un-stamp to rows this caller could actually undo.
  execute format('update public.%I s set promoted_at=null,promoted_by=null
    from erp_promote_bak.promotion_log l where l.dataset=$1 and l.batch_id=$2
      and l.organisation_id=$3 and l.source_staging_id=s.id
      and public.app_write_country_ok(s.country) is not false',v_staging)
    using p_dataset,p_batch,v_org;
  -- V567: keep each country''s own undo ledger. Entries whose staging row has
  -- since been deleted are still cleared, preserving the prior cleanup.
  execute format('delete from erp_promote_bak.promotion_log l
     where l.dataset=$1 and l.batch_id=$2 and l.organisation_id=$3
       and (exists (select 1 from public.%I s where s.id = l.source_staging_id
                      and public.app_write_country_ok(s.country) is not false)
            or not exists (select 1 from public.%I s where s.id = l.source_staging_id))',
    v_staging, v_staging)
    using p_dataset,p_batch,v_org;
  return jsonb_build_object('dataset',p_dataset,'batch_id',p_batch,'deleted',v_deleted,'restored',v_restored);
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.propose_classification_rules(p_min_support integer DEFAULT 4, p_min_precision numeric DEFAULT 0.85, p_min_lift numeric DEFAULT 1.5, p_limit integer DEFAULT 40)
 RETURNS TABLE(token text, category text, support integer, precision_pct numeric, base_rate_pct numeric, lift numeric, affects_lines bigint, affects_value numeric, sample text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with org as (select public.app_current_org() as id),
reviewed as (
  select item_code, category, lower(coalesce(item_name, '')) as descr
  from public.material_master
  where organisation_id = (select id from org)
    and reviewed is true and category is not null
),
base as (
  select category, count(*)::numeric / nullif((select count(*) from reviewed), 0) as rate
  from reviewed group by category
),
words as (
  select r.category, w.token
  from reviewed r,
       lateral unnest(regexp_split_to_array(regexp_replace(r.descr, '[^a-z0-9 ]', ' ', 'g'), '\s+')) as w(token)
  where length(w.token) >= 4
    and w.token <> all (public.brain_stopwords())
    and w.token !~ '^[0-9]+$'
),
per_token     as (select token, count(*) as n from words group by token),
per_token_cat as (select token, category, count(*) as n from words group by token, category),
scored as (
  -- Lift, NOT frequency. 89.6% of reviewed items are spare_part, so scoring on how
  -- often a word appears just relearns the majority class - measured, it produced
  -- `with`, `water`, `rear` and `fuel` all claiming spare_part at lift 1.12.
  select ptc.token, ptc.category, ptc.n::int as support,
         round(100.0 * ptc.n / pt.n, 1) as precision_pct,
         round(100.0 * b.rate, 1) as base_rate_pct,
         round((ptc.n::numeric / pt.n) / nullif(b.rate, 0), 2) as lift
  from per_token_cat ptc
  join per_token pt using (token)
  join base b on b.category = ptc.category
  where ptc.n >= p_min_support
    and (ptc.n::numeric / pt.n) >= p_min_precision
    and (ptc.n::numeric / pt.n) / nullif(b.rate, 0) >= p_min_lift
),
fresh as (
  -- A token already decided - accepted OR REJECTED - never comes back. The
  -- rejection half is what makes this learn from the user rather than nag them.
  select s.* from scored s
  where not exists (
    select 1 from public.classification_learned_rules lr
    where lr.organisation_id = (select id from org)
      and lr.token = s.token and lr.category = s.category)
),
-- ONE pass: collapse the unidentified spend to distinct descriptions first,
-- then tokenise those once. Per-candidate subqueries over 217k rows with a regex
-- each timed out at 60s; this returns in well under a second.
unidentified as materialized (
  select lower(coalesce(item_description, '')) as descr,
         count(*) as lines, coalesce(sum(line_cost), 0) as value,
         min(item_description) as sample
  from public.parts_consumption
  where organisation_id = (select id from org) and classified_by = 'default'
  group by 1
),
uni_tokens as materialized (
  select w.token, u.descr, u.lines, u.value, u.sample
  from unidentified u,
       lateral unnest(regexp_split_to_array(regexp_replace(u.descr, '[^a-z0-9 ]', ' ', 'g'), '\s+')) as w(token)
  where length(w.token) >= 4
),
-- Impact is counted only over rows the rule may actually claim. A vetoed row is
-- not impact; counting it would advertise a saving the rule will never make.
impact as (
  select t.token, f.category,
         sum(t.lines) as lines, sum(t.value) as value, min(t.sample) as sample
  from uni_tokens t
  join fresh f on f.token = t.token
  where not public.learned_rule_vetoed(t.descr, f.category)
  group by t.token, f.category
)
select f.token, f.category, f.support, f.precision_pct, f.base_rate_pct, f.lift,
       i.lines as affects_lines, round(i.value, 2) as affects_value, i.sample
from fresh f
join impact i on i.token = f.token and i.category = f.category
order by i.value desc nulls last, f.lift desc
limit p_limit;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.propose_production_station_sites(p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_out jsonb;
begin
  if v_org is null then
    return jsonb_build_object('ok', false, 'reason', 'no_org');
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  with prod as (
    select station, site as row_site,
           coalesce(nullif(btrim(project_name),''),'') proj,
           coalesce(nullif(btrim(customer_name),''),'') cust,
           coalesce(approved_m3, m3, 0) m3
    from public.production_logs
    where organisation_id = v_org
      and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
      and coalesce(nullif(btrim(station),''),'') <> ''
  ),
  station_tot as (
    select station, count(*) loads, sum(m3) m3,
           count(*) filter (where proj <> '') with_project
    from prod group by station
  ),
  -- Already named: the station's OWN ROWS carry a registered site. Reading the
  -- rows rather than the station text picks up every alias site_aliases has
  -- already resolved (Dhaban to DHAHBAN, Metro to RIY-MET, Laheq Island to LAHEQ).
  named as (
    select p.station, s.name site, s.region, count(*) n,
           row_number() over (partition by p.station order by count(*) desc) rk
    from prod p
    join public.sites s
      on s.organisation_id = v_org
     and (p_country is null or s.country = p_country) and (s.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(s.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
     and upper(btrim(s.name)) = upper(btrim(p.row_site))
    group by p.station, s.name, s.region
  ),
  proj as (
    select station, proj, cust, sum(m3) m3
    from prod where proj <> '' or cust <> ''
    group by station, proj, cust
  ),
  kw as (
    select site, region, keyword, weight from public.site_match_keywords
    where organisation_id = v_org and active
      and (p_country is null or country = p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  hit as (
    select p.station, k.site, k.region as kw_region, k.keyword, p.proj,
           p.m3, p.m3 * k.weight as score
    from proj p join kw k
      on upper(p.proj) like '%' || upper(k.keyword) || '%'
      or upper(p.cust) like '%' || upper(k.keyword) || '%'
  ),
  specific as (
    select h.*,
           h.site is not null and exists (
             select 1 from hit h2
             where h2.station = h.station and h2.site is not null and h2.site <> h.site
               and upper(h2.site) like upper(h.site) || '%'
               and length(h2.site) > length(h.site)
           ) as superseded
    from hit h
  ),
  site_cand as (
    select station, site,
           sum(score) filter (where not superseded) score,
           sum(m3) filter (where not superseded) matched_m3,
           string_agg(distinct keyword, ', ') keywords,
           (array_agg(distinct proj order by proj))[1:3] evidence
    from specific where site is not null
    group by station, site
    having sum(score) filter (where not superseded) > 0
  ),
  site_rank as (
    select c.*, sum(c.score) over (partition by c.station) total,
           row_number() over (partition by c.station order by c.score desc) rk
    from site_cand c
  ),
  region_vote as (
    select s.station,
           coalesce(s.kw_region, (select st.region from public.sites st
                                  where st.organisation_id = v_org
                                    and (p_country is null or st.country = p_country) and (st.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(st.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
                                    and upper(btrim(st.name)) = upper(btrim(s.site))
                                  limit 1)) region,
           s.score
    from specific s where not s.superseded
  ),
  region_cand as (
    select station, region, sum(score) score
    from region_vote where region is not null group by station, region
  ),
  region_rank as (
    select c.*, sum(c.score) over (partition by c.station) total,
           row_number() over (partition by c.station order by c.score desc) rk
    from region_cand c
  ),
  agg as (
    select t.station, t.loads, t.m3, t.with_project,
           (select site from named n where n.station = t.station and n.rk = 1) named_site,
           (select region from named n where n.station = t.station and n.rk = 1) named_region,
           m.site mapped_site,
           (select site from site_rank r where r.station = t.station and r.rk = 1) lead_site,
           (select site from site_rank r where r.station = t.station and r.rk = 2) second_site,
           (select score from site_rank r where r.station = t.station and r.rk = 1) lead_score,
           (select score from site_rank r where r.station = t.station and r.rk = 2) second_score,
           (select matched_m3 from site_rank r where r.station = t.station and r.rk = 1) lead_m3,
           (select keywords from site_rank r where r.station = t.station and r.rk = 1) lead_kw,
           (select total from site_rank r where r.station = t.station and r.rk = 1) site_total,
           (select region from region_rank r where r.station = t.station and r.rk = 1) lead_region,
           (select score from region_rank r where r.station = t.station and r.rk = 1) region_score,
           (select total from region_rank r where r.station = t.station and r.rk = 1) region_total,
           (select jsonb_agg(jsonb_build_object(
                     'site', r.site, 'score', round(r.score),
                     'share', case when r.total > 0 then round(100.0*r.score/r.total,1) end,
                     'matched_m3', round(r.matched_m3),
                     'keywords', r.keywords, 'evidence', to_jsonb(r.evidence)) order by r.score desc)
            from site_rank r where r.station = t.station and r.rk <= 4) candidates
    from station_tot t
    left join public.production_station_map m
           on m.organisation_id = v_org and m.station = t.station
          and (p_country is null or m.country = p_country) and (m.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(m.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  )
  select jsonb_agg(jsonb_build_object(
           'station', a.station, 'loads', a.loads, 'm3', round(a.m3),
           'with_project', a.with_project,
           'status', case when a.named_site is not null then 'named'
                          when a.mapped_site is not null then 'mapped'
                          when a.lead_site is not null or a.lead_region is not null then 'proposed'
                          else 'no_evidence' end,
           'named_site', a.named_site,
           'mapped_site', a.mapped_site,
           'proposed_site', a.lead_site,
           'site_share', case when a.site_total > 0 then round(100.0*a.lead_score/a.site_total,1) end,
           'matched_m3', round(a.lead_m3),
           'keywords', a.lead_kw,
           'runner_up', a.second_site,
           'site_confidence', case
             when a.lead_site is null then 'none'
             when a.site_total > 0 and a.lead_score >= 0.60*a.site_total
              and (a.second_score is null or a.lead_score >= 2*a.second_score)
              and a.lead_m3 >= 500 then 'high'
             when a.site_total > 0 and a.lead_score >= 0.45*a.site_total then 'medium'
             else 'low' end,
           'proposed_region', coalesce(a.named_region, a.lead_region),
           'region_share', case when a.region_total > 0 then round(100.0*a.region_score/a.region_total,1) end,
           'region_confidence', case
             when a.named_region is not null then 'high'
             when a.lead_region is null then 'none'
             when a.region_total > 0 and a.region_score >= 0.80*a.region_total then 'high'
             when a.region_total > 0 and a.region_score >= 0.60*a.region_total then 'medium'
             else 'low' end,
           'candidates', coalesce(a.candidates, '[]'::jsonb)
         ) order by a.m3 desc)
  into v_out from agg a;

  return jsonb_build_object('ok', true, 'country', p_country,
                            'stations', coalesce(v_out, '[]'::jsonb));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.provision_approved_driver_account(p_user_id uuid, p_actor_id uuid, p_organisation_id uuid, p_employee_id text, p_full_name text, p_country text, p_position text, p_iqama text, p_batch_id text, p_preserve_profile boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  actor public.profiles%ROWTYPE; account public.profiles%ROWTYPE;
  driver public.drivers%ROWTYPE; marker text; linked boolean := false;
  found_link uuid; old_claims text; old_sub text; import_details jsonb;
BEGIN
  SELECT * INTO actor FROM public.profiles WHERE id=p_actor_id;
  IF NOT FOUND OR actor.role<>'Admin' OR NOT coalesce(actor.approved,false)
     OR coalesce(actor.locked,false) OR actor.org_id IS DISTINCT FROM p_organisation_id THEN
    RAISE EXCEPTION 'Active administrator in the target organisation required' USING ERRCODE='42501';
  END IF;
  IF p_employee_id IS NULL OR p_employee_id !~ '^[0-9]{3,30}$'
     OR nullif(btrim(p_full_name),'') IS NULL OR nullif(btrim(p_position),'') IS NULL
     OR p_country IS DISTINCT FROM 'KSA' OR nullif(btrim(p_batch_id),'') IS NULL THEN
    RAISE EXCEPTION 'Verified employee ID, name, position, KSA and import batch required' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organisation_id::text||':'||p_employee_id,0));
  SELECT * INTO account FROM public.profiles WHERE id=p_user_id FOR UPDATE;
  IF NOT FOUND OR account.org_id IS DISTINCT FROM p_organisation_id
     OR account.organisation_id IS DISTINCT FROM p_organisation_id
     OR btrim(account.employee_id) IS DISTINCT FROM p_employee_id THEN
    RAISE EXCEPTION 'Account identity or organisation mismatch' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE btrim(employee_id)=p_employee_id AND id<>p_user_id) THEN
    RAISE EXCEPTION 'Employee ID matches more than one account' USING ERRCODE='23505';
  END IF;
  IF NOT p_preserve_profile THEN
    marker:=CASE WHEN private.driver_import_matches_batch(p_user_id,p_batch_id) THEN p_batch_id ELSE NULL END;
    IF marker IS DISTINCT FROM p_batch_id OR account.username IS DISTINCT FROM p_employee_id THEN
      RAISE EXCEPTION 'Only accounts created by this import may be updated' USING ERRCODE='42501';
    END IF;
    old_claims:=current_setting('request.jwt.claims',true);
    old_sub:=current_setting('request.jwt.claim.sub',true);
    PERFORM set_config('request.jwt.claim.sub',p_actor_id::text,true);
    PERFORM set_config('request.jwt.claims',
      (coalesce(nullif(old_claims,''),'{}')::jsonb||jsonb_build_object('sub',p_actor_id::text))::text,true);
    UPDATE public.profiles SET role='Driver',approved=true,locked=false,
      country=ARRAY['KSA'],countries=ARRAY['KSA'],region='KSA',
      site=NULL,sites=ARRAY[]::text[],full_name=btrim(p_full_name)
      WHERE id=p_user_id;
    PERFORM set_config('request.jwt.claim.sub',coalesce(old_sub,''),true);
    PERFORM set_config('request.jwt.claims',coalesce(old_claims,''),true);
  END IF;
  IF (SELECT count(*) FROM public.drivers WHERE organisation_id=p_organisation_id AND btrim(driver_id)=p_employee_id)>1 THEN
    RAISE EXCEPTION 'Employee ID matches more than one driver record' USING ERRCODE='23505';
  END IF;
  SELECT * INTO driver FROM public.drivers WHERE organisation_id=p_organisation_id AND btrim(driver_id)=p_employee_id FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.drivers(driver_id,driver_name,country,organisation_id,created_by,custom_data)
    VALUES(p_employee_id,btrim(p_full_name),p_country,p_organisation_id,p_actor_id,
      jsonb_build_object('position',btrim(p_position),'employee_iqama',nullif(btrim(p_iqama),''),'import_batch',p_batch_id))
    RETURNING * INTO driver;
  ELSIF driver.country IS DISTINCT FROM p_country THEN
    RAISE EXCEPTION 'Existing driver country mismatch' USING ERRCODE='42501';
  END IF;
  -- The independently deployed fines workspace owns this table. Provisioning
  -- remains resumable before that rollout and never fabricates its schema.
  IF to_regclass('public.driver_account_links') IS NOT NULL THEN
    EXECUTE 'SELECT user_id FROM public.driver_account_links WHERE driver_id=$1' INTO found_link USING driver.id;
    IF found_link IS NOT NULL AND found_link<>p_user_id THEN
      RAISE EXCEPTION 'Driver already linked to another account' USING ERRCODE='23505';
    END IF;
    EXECUTE 'INSERT INTO public.driver_account_links(driver_id,user_id,organisation_id,linked_by)
      VALUES($1,$2,$3,$4) ON CONFLICT(driver_id) DO NOTHING'
      USING driver.id,p_user_id,p_organisation_id,p_actor_id;
    linked:=true;
  END IF;
  import_details:=jsonb_build_object('event','driver_account_provisioned','batch_id',p_batch_id,'user_id',p_user_id,'driver_id',driver.id,
    'profile_preserved',p_preserve_profile,'workspace_linked',linked,'country',p_country);
  IF NOT EXISTS(SELECT 1 FROM public.audit_log WHERE table_name='drivers' AND record_id=driver.id
      AND action='INSERT' AND audit_log.details @> import_details) THEN
    INSERT INTO public.audit_log(table_name,record_id,action,changed_by,user_id,organisation_id,details)
      VALUES('drivers',driver.id,'INSERT',p_actor_id,p_actor_id,p_organisation_id,import_details);
  END IF;
  RETURN import_details;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.qr_login_approve(p_id uuid, p_secret text, p_approve boolean DEFAULT true, p_match text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare r public.qr_login_requests;
begin
  if auth.uid() is null or not public.is_approved_and_unlocked() then
    raise exception 'Sign in on the phone first' using errcode = '42501';
  end if;
  if p_approve and (public.is_super_admin() or lower(coalesce(public.app_role(), '')) = 'admin') then
    return jsonb_build_object('ok', false, 'reason', 'admin');
  end if;
  select * into r from public.qr_login_requests
   where id = p_id and secret_hash = encode(digest(coalesce(p_secret,''), 'sha256'), 'hex')
   for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;
  if r.status <> 'pending' then return jsonb_build_object('ok', false, 'reason', r.status); end if;
  if r.expires_at < now() then
    update public.qr_login_requests set status = 'expired' where id = r.id;
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  if p_approve and (r.match_code is null or coalesce(btrim(p_match), '') <> r.match_code) then
    update public.qr_login_requests set status = 'denied', approved_at = now() where id = r.id;
    return jsonb_build_object('ok', false, 'reason', 'mismatch');
  end if;
  update public.qr_login_requests
     set status = case when p_approve then 'approved' else 'denied' end,
         approved_by = case when p_approve then auth.uid() end,
         approved_at = now(),
         expires_at = now() + interval '2 minutes'
   where id = r.id;
  return jsonb_build_object('ok', true, 'status', case when p_approve then 'approved' else 'denied' end);
end $function$;
-- @@
