-- @@
CREATE OR REPLACE FUNCTION public.qr_login_peek(p_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare r public.qr_login_requests; o1 text; o2 text;
begin
  if auth.uid() is null or not public.is_approved_and_unlocked() then
    raise exception 'Sign in on the phone first' using errcode = '42501';
  end if;
  select * into r from public.qr_login_requests
   where id = p_id and secret_hash = encode(digest(coalesce(p_secret,''), 'sha256'), 'hex');
  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;
  if r.status <> 'pending' or r.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', case when r.status = 'pending' then 'expired' else r.status end);
  end if;
  loop o1 := (10 + floor(random() * 90))::int::text; exit when o1 <> r.match_code; end loop;
  loop o2 := (10 + floor(random() * 90))::int::text; exit when o2 <> r.match_code and o2 <> o1; end loop;
  return jsonb_build_object('ok', true,
    'user_agent', r.user_agent, 'ip', r.start_ip,
    'age_seconds', greatest(0, extract(epoch from now() - r.created_at))::int,
    'options', (select jsonb_agg(x order by random()) from unnest(array[r.match_code, o1, o2]) x));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.qr_login_purge()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.qr_login_requests
   where (status <> 'consumed' and created_at < now() - interval '1 hour')
      or created_at < now() - interval '30 days';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.qr_login_start(p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_scan    text := encode(gen_random_bytes(24), 'hex');
  v_browser text := encode(gen_random_bytes(24), 'hex');
  v_match   text := (10 + floor(random() * 90))::int::text;
  v_ip      text := public._qr_client_ip();
  v_id uuid;
begin
  if coalesce((select btrim(value, '"') from public.system_config where key = 'qr_login_enabled'), 'false') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', 'disabled');
  end if;
  if v_ip is not null and (select count(*) from public.qr_login_requests
       where start_ip = v_ip and created_at > now() - interval '1 minute') >= 10 then
    return jsonb_build_object('ok', false, 'reason', 'busy');
  end if;
  if (select count(*) from public.qr_login_requests where created_at > now() - interval '1 minute') > 2000 then
    return jsonb_build_object('ok', false, 'reason', 'busy');
  end if;
  insert into public.qr_login_requests (secret_hash, browser_hash, match_code, start_ip, user_agent)
  values (encode(digest(v_scan, 'sha256'), 'hex'), encode(digest(v_browser, 'sha256'), 'hex'),
          v_match, v_ip, left(p_user_agent, 300))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'secret', v_scan, 'browser_secret', v_browser,
    'match_code', v_match, 'expires_at', now() + interval '2 minutes');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.qr_login_status(p_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare r public.qr_login_requests;
begin
  select * into r from public.qr_login_requests
   where id = p_id and browser_hash is not null
     and browser_hash = encode(digest(coalesce(p_secret,''), 'sha256'), 'hex');
  if not found then return jsonb_build_object('status', 'invalid'); end if;
  if r.status in ('pending','approved') and r.expires_at < now() then
    update public.qr_login_requests set status = 'expired' where id = r.id;
    return jsonb_build_object('status', 'expired');
  end if;
  return jsonb_build_object('status', r.status);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.raise_checklist_corrective_actions(p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_n integer := 0; v_sheets integer := 0; v_k integer;
begin
  if not (public.app_is_elevated() or public.checklist_is_supervisor()) then
    raise exception 'You do not have permission to raise corrective actions' using errcode = '42501';
  end if;
  for r in select s.id from public.checklist_submissions s
            where s.organisation_id is not distinct from public.app_current_org()
              and (s.country is null or public.app_can_see_country(s.country) is not false)
  loop
    v_k := public._raise_checklist_corrective_actions(r.id, p_dry_run);
    if v_k > 0 then v_n := v_n + v_k; v_sheets := v_sheets + 1; end if;
  end loop;
  return jsonb_build_object('ok', true, 'dry_run', p_dry_run, 'actions', v_n, 'checklists', v_sheets);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reclassify_from_master(p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org   uuid := coalesce(public.app_current_org(), '00000000-0000-0000-0000-000000000001'::uuid);
  v_out   jsonb;
  v_n     bigint := 0;
  v_batch uuid := gen_random_uuid();
begin
  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  -- re-entrant: dry run then apply in one transaction is the expected usage.
  drop table if exists _recl;

  create temp table _recl on commit drop as
  select p.id, p.country, upper(btrim(p.item_code)) as item_code,
         p.cost_category as now_cat, p.line_cost,
         case public.material_category_bucket(m.category)
           when 'tyre' then 'tyre' when 'oil' then 'oil' else 'spare' end as new_cat
    from public.parts_consumption p
    join public.material_master m
      on m.organisation_id = p.organisation_id
     and m.country = p.country
     and m.item_code = upper(btrim(p.item_code))
     and m.reviewed
   where p.organisation_id = v_org;

  select jsonb_build_object(
    'rows_matched_reviewed_items', count(*),
    'rows_that_change',            count(*) filter (where now_cat <> new_cat),
    'moves', coalesce((
      select jsonb_agg(x) from (
        select now_cat as from_bucket, new_cat as to_bucket, country,
               count(*) as rows, round(sum(line_cost), 2) as value
          from _recl where now_cat <> new_cat
         group by now_cat, new_cat, country
         order by sum(line_cost) desc
      ) x), '[]'::jsonb),
    'dry_run', coalesce(p_dry_run, true)
  ) into v_out from _recl;

  if not coalesce(p_dry_run, true) then
    -- record the before-state FIRST so the batch can be put back
    insert into public.reclassify_log
      (batch_id, organisation_id, row_id, country, item_code, old_category, new_category, line_cost)
    select v_batch, v_org, r.id, r.country, r.item_code, r.now_cat, r.new_cat, r.line_cost
      from _recl r where r.now_cat <> r.new_cat;

    update public.parts_consumption p
       set cost_category = r.new_cat,
           tyre_cost  = case when r.new_cat = 'tyre'  then p.line_cost else 0 end,
           oil_cost   = case when r.new_cat = 'oil'   then p.line_cost else 0 end,
           spare_cost = case when r.new_cat = 'spare' then p.line_cost else 0 end
      from _recl r
     where p.id = r.id and r.now_cat <> r.new_cat;
    get diagnostics v_n = row_count;

    insert into public.system_logs (severity, source, message, detail)
    values ('warning', 'material-master',
            format('Re-classified %s transaction(s) from reviewed master decisions', v_n),
            v_out || jsonb_build_object('batch_id', v_batch));

    v_out := v_out || jsonb_build_object('rows_updated', v_n, 'batch_id', v_batch);
  end if;

  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reclassify_revert(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n bigint := 0;
begin
  if not public.is_super_admin() then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  update public.parts_consumption p
     set cost_category = l.old_category,
         tyre_cost  = case when l.old_category = 'tyre'  then p.line_cost else 0 end,
         oil_cost   = case when l.old_category = 'oil'   then p.line_cost else 0 end,
         spare_cost = case when l.old_category = 'spare' then p.line_cost else 0 end
    from public.reclassify_log l
   where l.batch_id = p_batch_id and l.reverted_at is null and p.id = l.row_id;
  get diagnostics v_n = row_count;

  update public.reclassify_log
     set reverted_at = now()
   where batch_id = p_batch_id and reverted_at is null;

  insert into public.system_logs (severity, source, message, detail)
  values ('info', 'material-master',
          format('Reverted %s re-classified transaction(s)', v_n),
          jsonb_build_object('batch_id', p_batch_id, 'reverted', v_n));

  return jsonb_build_object('ok', true, 'reverted', v_n, 'batch_id', p_batch_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_backfill_all_orphan_assets()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_n integer := 0;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  WITH ins AS (
    INSERT INTO vehicle_fleet (asset_no, vehicle_type, country, organisation_id)
    SELECT tr.asset_no, max(tr.vehicle_type), max(tr.country), v_org
      FROM tyre_records tr
     WHERE tr.organisation_id = v_org AND COALESCE(tr.asset_no,'') <> ''
       AND (tr.country IS NULL
            OR (select public.is_super_admin())
            OR (select public.app_sees_all_countries())
            OR lower(btrim(tr.country)) = ANY (coalesce((select public.app_country_scope()), '{}'::text[])))
       AND NOT EXISTS (SELECT 1 FROM vehicle_fleet vf WHERE vf.asset_no = tr.asset_no AND vf.organisation_id = v_org)
     GROUP BY tr.asset_no
    RETURNING 1)
  SELECT count(*) INTO v_n FROM ins;
  RETURN v_n;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_backfill_asset(p_asset_no text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_id uuid;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  IF COALESCE(p_asset_no,'') = '' THEN RAISE EXCEPTION 'asset_no required.'; END IF;
  SELECT id INTO v_id FROM vehicle_fleet WHERE asset_no = p_asset_no AND organisation_id = v_org
    AND (country IS NULL
         OR (select public.is_super_admin())
         OR (select public.app_sees_all_countries())
         OR lower(btrim(country)) = ANY (coalesce((select public.app_country_scope()), '{}'::text[]))) LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  INSERT INTO vehicle_fleet (asset_no, vehicle_type, country, organisation_id)
  SELECT p_asset_no, max(vehicle_type), max(country), v_org
    FROM tyre_records WHERE asset_no = p_asset_no AND organisation_id = v_org
      AND (country IS NULL
           OR (select public.is_super_admin())
           OR (select public.app_sees_all_countries())
           OR lower(btrim(country)) = ANY (coalesce((select public.app_country_scope()), '{}'::text[])))
   HAVING count(*) > 0
  RETURNING id INTO v_id;
  -- V566: without the HAVING, max() over an EMPTY set still returns ONE all-NULL
  -- row, so this INSERT always fired and "backfill an orphan" was really "create
  -- any asset you name", country NULL, visible in every country's register.
  -- Refusal is a RAISE because the caller's screen reports success from the
  -- absence of an error; a NULL return would have printed "1 asset added".
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Not permitted: that asset has no tyre records in a country you can write.'
      USING errcode = '42501';
  END IF;
  RETURN v_id;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_data_quality_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v jsonb;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  SELECT COALESCE(jsonb_agg(obj ORDER BY obj->>'country'), '[]'::jsonb) INTO v FROM (
    SELECT jsonb_build_object(
      'country', c.country,
      'tyres', (SELECT count(*) FROM tyre_records tr WHERE tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(tr.country,'') = c.country),
      'tyres_no_brand', (SELECT count(*) FROM tyre_records tr WHERE tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(tr.country,'') = c.country AND COALESCE(NULLIF(btrim(tr.brand),''),'') = ''),
      'tyres_no_serial', (SELECT count(*) FROM tyre_records tr WHERE tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(tr.country,'') = c.country AND COALESCE(NULLIF(btrim(tr.serial_no),''),'') = ''),
      'wo', (SELECT count(*) FROM work_orders wo WHERE wo.organisation_id = v_org and (wo.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(wo.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(wo.country,'') = c.country),
      'wo_total', (SELECT count(*) FROM work_orders wo WHERE wo.organisation_id = v_org and (wo.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(wo.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(wo.country,'') = c.country),
      'wo_linked', (SELECT count(*) FROM work_orders wo WHERE wo.organisation_id = v_org and (wo.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(wo.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(wo.country,'') = c.country
                     AND EXISTS (SELECT 1 FROM vehicle_fleet vf WHERE vf.organisation_id = v_org and (vf.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vf.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND vf.asset_no = wo.asset_no AND COALESCE(vf.country,'') = c.country)),
      'tyres_linked', (SELECT count(*) FROM tyre_records tr WHERE tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(tr.country,'') = c.country
                        AND EXISTS (SELECT 1 FROM vehicle_fleet vf WHERE vf.organisation_id = v_org and (vf.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vf.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND vf.asset_no = tr.asset_no AND COALESCE(vf.country,'') = c.country)),
      'fleet', (SELECT count(*) FROM vehicle_fleet vf WHERE vf.organisation_id = v_org and (vf.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vf.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(vf.country,'') = c.country)
    ) AS obj
    FROM (SELECT DISTINCT COALESCE(country,'') AS country FROM tyre_records WHERE organisation_id = v_org) c
  ) z;
  RETURN v;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_duplicate_key_tyres()
 RETURNS TABLE(serial_no text, asset_no text, issue_date date, country text, copies bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
  IF NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not permitted.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT t.serial_no, t.asset_no, t.issue_date, t.country, count(*) AS copies
    FROM public.tyre_records t
   WHERE (t.organisation_id = v_org and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) OR public.is_super_admin())
     AND t.serial_no IS NOT NULL
   GROUP BY t.serial_no, t.asset_no, t.issue_date, t.country
  HAVING count(*) > 1
   ORDER BY count(*) DESC;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_duplicate_tyres()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v jsonb;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY row_obj->>'serial_no'), '[]'::jsonb) INTO v FROM (
    SELECT jsonb_build_object(
      'serial_no', min(serial_no), 'asset_no', min(asset_no), 'row_count', count(*),
      'keep_id',   (array_agg(id ORDER BY created_at DESC NULLS LAST))[1],
      'remove_ids',(array_agg(id ORDER BY created_at DESC NULLS LAST))[2:]
    ) AS row_obj
    FROM (
      SELECT id, serial_no, asset_no, created_at,
             (to_jsonb(t) - 'id' - 'created_at' - 'updated_at') AS body
      FROM tyre_records t WHERE organisation_id = v_org and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    ) s
    GROUP BY body HAVING count(*) > 1
  ) z;
  RETURN v;
END $function$;
