CREATE OR REPLACE FUNCTION public.recon_jobcard_mismatch_summary()
 RETURNS TABLE(country text, mismatches bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
  IF NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not permitted.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT m.country::text AS country, count(*)::bigint AS mismatches
  FROM public.v_jobcard_date_mismatch m
  WHERE m.organisation_id = v_org and (m.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(m.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) OR public.is_super_admin()
  GROUP BY m.country
  ORDER BY m.country;
END $function$;
