CREATE OR REPLACE FUNCTION public.recon_jobcard_mismatches(p_limit integer DEFAULT 1000)
 RETURNS TABLE(id uuid, work_order_no text, opened_at timestamp with time zone, country text, site text, jobcard_month integer, jobcard_year integer, opened_month integer, opened_year integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
  IF NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not permitted.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT m.id,
         m.work_order_no::text,
         m.opened_at,
         m.country::text,
         m.site::text,
