CREATE OR REPLACE FUNCTION public.recon_merge_duplicate(p_keep_id uuid, p_remove_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v_body jsonb; v_n integer := 0;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  IF p_keep_id IS NULL OR p_remove_ids IS NULL OR array_length(p_remove_ids,1) IS NULL THEN RETURN 0; END IF;
  SELECT (to_jsonb(t) - 'id' - 'created_at' - 'updated_at') INTO v_body
    FROM tyre_records t WHERE id = p_keep_id AND organisation_id = v_org AND public.app_write_country_ok(t.country) IS NOT FALSE;
  IF v_body IS NULL THEN RAISE EXCEPTION 'Keep row not found in your organisation.'; END IF;
  IF EXISTS (
    SELECT 1 FROM tyre_records t
     WHERE t.id = ANY(p_remove_ids)
       AND (t.organisation_id <> v_org OR (to_jsonb(t) - 'id' - 'created_at' - 'updated_at') IS DISTINCT FROM v_body)
  ) THEN
    RAISE EXCEPTION 'Refused: a selected row is not identical to the kept row (not a true duplicate).' USING errcode='42501';
  END IF;
  DELETE FROM tyre_records WHERE id = ANY(p_remove_ids) AND id <> p_keep_id AND organisation_id = v_org AND public.app_write_country_ok(country) IS NOT FALSE;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_orphan_assets()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v jsonb;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY row_obj->>'asset_no'), '[]'::jsonb) INTO v FROM (
    SELECT jsonb_build_object('asset_no', tr.asset_no, 'vehicle_type', max(tr.vehicle_type),
             'country', max(tr.country), 'tyre_count', count(*)) AS row_obj
    FROM tyre_records tr
    WHERE tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((tr.site)::text is null or btrim((tr.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((tr.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND COALESCE(tr.asset_no,'') <> ''
      AND NOT EXISTS (SELECT 1 FROM vehicle_fleet vf WHERE vf.asset_no = tr.asset_no AND vf.organisation_id = v_org and (vf.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(vf.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))))
    GROUP BY tr.asset_no
  ) z;
  RETURN v;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_resolve_duplicate_key(p_serial text, p_asset text, p_issue_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org      uuid := public.app_current_org();
  v_total    integer := 0;
  v_distinct integer := 0;
  v_keep_id  uuid;
  v_deleted  integer := 0;
BEGIN
  IF NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not permitted.' USING errcode = '42501';
  END IF;

  SELECT count(*),
         count(DISTINCT (to_jsonb(t.*) - 'id' - 'created_at' - 'updated_at'))
    INTO v_total, v_distinct
    FROM public.tyre_records t
   WHERE t.organisation_id = v_org
     AND public.app_write_country_ok(t.country) IS NOT FALSE
     AND t.serial_no    IS NOT DISTINCT FROM p_serial
     AND t.asset_no     IS NOT DISTINCT FROM p_asset
     AND t.issue_date   IS NOT DISTINCT FROM p_issue_date;

  IF v_total < 2 THEN
    RETURN jsonb_build_object('resolved', false, 'reason', 'not_found');
  END IF;

  IF v_distinct > 1 THEN
    RETURN jsonb_build_object('resolved', false, 'reason', 'differs');
  END IF;

  SELECT t.id
    INTO v_keep_id
    FROM public.tyre_records t
   WHERE t.organisation_id = v_org
     AND public.app_write_country_ok(t.country) IS NOT FALSE
     AND t.serial_no    IS NOT DISTINCT FROM p_serial
     AND t.asset_no     IS NOT DISTINCT FROM p_asset
     AND t.issue_date   IS NOT DISTINCT FROM p_issue_date
   ORDER BY t.created_at DESC NULLS LAST, t.id DESC
   LIMIT 1;

  DELETE FROM public.tyre_records t
   WHERE t.organisation_id = v_org
     AND public.app_write_country_ok(t.country) IS NOT FALSE
     AND t.serial_no    IS NOT DISTINCT FROM p_serial
     AND t.asset_no     IS NOT DISTINCT FROM p_asset
     AND t.issue_date   IS NOT DISTINCT FROM p_issue_date
     AND t.id <> v_keep_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object('resolved', true, 'deleted', v_deleted);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_serial_conflicts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org(); v jsonb;
BEGIN
  IF NOT public.app_is_elevated() THEN RAISE EXCEPTION 'Not permitted.' USING errcode='42501'; END IF;
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY row_obj->>'serial_no'), '[]'::jsonb) INTO v FROM (
    SELECT jsonb_build_object('serial_no', serial_no, 'asset_count', count(DISTINCT asset_no),
      'rows', jsonb_agg(jsonb_build_object('id', id, 'asset_no', asset_no, 'status', status, 'created_at', created_at) ORDER BY created_at)) AS row_obj
    FROM tyre_records
    WHERE organisation_id = v_org and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) AND COALESCE(serial_no,'') <> ''
    GROUP BY serial_no HAVING count(DISTINCT asset_no) > 1
  ) z;
  RETURN v;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.recon_serial_multi_asset()
 RETURNS TABLE(serial_no text, country text, asset_count bigint, assets text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
  IF NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not permitted.' USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT tr.serial_no::text AS serial_no,
         tr.country::text AS country,
         count(DISTINCT tr.asset_no)::bigint AS asset_count,
         string_agg(DISTINCT tr.asset_no, ', ') AS assets
  FROM public.tyre_records tr
  WHERE (tr.organisation_id = v_org and (tr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(tr.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) OR public.is_super_admin())
     and ((tr.site)::text is null or btrim((tr.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((tr.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[]))) AND tr.serial_no IS NOT NULL
  GROUP BY tr.serial_no, tr.country
  HAVING count(DISTINCT tr.asset_no) > 1
  ORDER BY count(DISTINCT tr.asset_no) DESC;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reconcile_inspection_plans(p_org uuid, p_asset text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_asset is null or btrim(p_asset) = '' then return; end if;
  with plans as (
    select s.id, s.status, s.completed_inspection_id,
           (select m.id from public.inspection_plan_best_match(s.id) m
             where lower(coalesce(m.status, '')) = 'done') as done_id
    from public.inspection_schedules s
    where upper(btrim(s.asset_no)) = upper(btrim(p_asset))
      and s.organisation_id is not distinct from p_org
      and lower(coalesce(s.status, '')) not in ('cancelled', 'canceled')
  )
  update public.inspection_schedules s
     set status = case when p.done_id is not null then 'Completed' else 'Scheduled' end,
         completed_inspection_id = p.done_id
    from plans p
   where s.id = p.id
     and (
       (p.done_id is not null and (
          lower(coalesce(p.status, 'scheduled')) in ('scheduled', 'in progress', '')
          or (p.completed_inspection_id is not null and p.completed_inspection_id <> p.done_id)))
       or (p.done_id is null and p.completed_inspection_id is not null)
     );
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reconcile_plans_on_inspection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if TG_OP in ('INSERT', 'UPDATE') then
      perform public.reconcile_inspection_plans(NEW.organisation_id, NEW.asset_no);
    end if;
    if TG_OP in ('UPDATE', 'DELETE') and (TG_OP = 'DELETE'
        or OLD.asset_no is distinct from NEW.asset_no
        or OLD.organisation_id is distinct from NEW.organisation_id) then
      perform public.reconcile_inspection_plans(OLD.organisation_id, OLD.asset_no);
    end if;
  exception when others then
    begin
      insert into public.system_logs (organisation_id, module_id, severity, source, message, detail)
      values (coalesce(NEW.organisation_id, OLD.organisation_id), 'inspection_planner', 'error',
              'reconcile_plans_on_inspection', 'Plan status could not be reconciled', jsonb_build_object('sqlstate', SQLSTATE));
    exception when others then null;
    end;
  end;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reconcile_plans_on_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if pg_trigger_depth() > 1 then return null; end if;
  begin
    if TG_OP in ('INSERT', 'UPDATE') then
      perform public.reconcile_inspection_plans(NEW.organisation_id, NEW.asset_no);
    end if;
    if TG_OP in ('UPDATE', 'DELETE') and (TG_OP = 'DELETE'
        or OLD.asset_no is distinct from NEW.asset_no
        or OLD.organisation_id is distinct from NEW.organisation_id) then
      perform public.reconcile_inspection_plans(OLD.organisation_id, OLD.asset_no);
    end if;
  exception when others then
    begin
      insert into public.system_logs (organisation_id, module_id, severity, source, message, detail)
      values (coalesce(NEW.organisation_id, OLD.organisation_id), 'inspection_planner', 'error',
              'reconcile_plans_on_schedule', 'Plan status could not be reconciled', jsonb_build_object('sqlstate', SQLSTATE));
    exception when others then null;
    end;
  end;
  return null;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.record_ai_tyre_depth(p_inspection_id uuid, p_position text, p_source text, p_original numeric, p_minimum numeric, p_inner numeric, p_center numeric, p_outer numeric, p_odometer numeric DEFAULT NULL::numeric, p_serial text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_org uuid; v_result uuid;
begin
 if auth.uid() is null or not app_user_can('inspections','edit') then
  raise exception 'Not authorized' using errcode='42501';
 end if;
 if p_position is null or length(trim(p_position)) not between 1 and 80 then
  raise exception 'Invalid position';
 end if;
 if p_source not in ('manual_gauge','digital_gauge','calibrated_device')
 or p_original is null or p_original<=0 or p_original>100
 or p_minimum is null or p_minimum<0 or p_minimum>=p_original
 or (p_inner is null and p_center is null and p_outer is null)
 or (p_inner is not null and (p_inner<0 or p_inner>p_original))
 or (p_center is not null and (p_center<0 or p_center>p_original))
 or (p_outer is not null and (p_outer<0 or p_outer>p_original))
 or (p_odometer is not null and p_odometer<0) then
  raise exception 'Invalid physical tread measurement';
 end if;
 select organisation_id into v_org from public.inspections
 where id=p_inspection_id and organisation_id=app_current_org();
 if v_org is null then raise exception 'Inspection not found in organization' using errcode='42501'; end if;
 -- RPC is invoker and requires a tightly scoped write policy below.
 insert into public.ai_tyre_depth_measurements
 (organisation_id,inspection_id,tyre_position,source,original_mm,minimum_mm,
 inner_mm,center_mm,outer_mm,odometer_km,tyre_serial,measured_at,recorded_by)
 values (v_org,p_inspection_id,trim(p_position),p_source,p_original,p_minimum,
 p_inner,p_center,p_outer,p_odometer,nullif(trim(p_serial),''),now(),auth.uid())
 returning id into v_result;
 return v_result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.record_audit_event(p_action text, p_table text, p_record_id text, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_email text; v_site text; v_country text; v_id uuid;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN
    RAISE EXCEPTION 'Not authorised.' USING errcode = '42501'; END IF;
  IF p_action IS NULL OR btrim(p_action) = '' THEN
    RAISE EXCEPTION 'Audit action is required.' USING errcode = '22004'; END IF;
  SELECT p.email, p.site, (p.country)[1] INTO v_email, v_site, v_country
    FROM public.profiles p WHERE p.id = v_uid;
  INSERT INTO public.audit_log_v2
    (user_id, user_email, action, table_name, record_id, old_data, new_data, site, country)
  VALUES (v_uid, v_email, p_action, p_table, p_record_id, p_old, p_new, v_site, v_country)
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.record_login_failure(p_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key text := lower(btrim(coalesce(p_identifier, '')));
  v_max int := public._login_max_attempts();
  v_win int := public._login_window_minutes();
  v_lock int := public._login_lock_minutes();
  r public.login_attempts%rowtype;
  v_count int;
  v_locked_until timestamptz := null;
begin
  if v_max = 0 or v_key = '' then
    return jsonb_build_object('enabled', v_max <> 0, 'locked', false);
  end if;
  if not public._login_identifier_exists(v_key) then
    -- Do not create rows for non-existent identifiers (no enumeration surface).
    return jsonb_build_object('enabled', true, 'locked', false);
  end if;

  select * into r from public.login_attempts where identifier = v_key for update;
  if not found then
    v_count := 1;
    insert into public.login_attempts(identifier, attempt_count, window_started_at, updated_at)
      values (v_key, 1, now(), now());
  elsif r.window_started_at > now() - make_interval(mins => v_win) and (r.locked_until is null or r.locked_until <= now()) then
    v_count := r.attempt_count + 1;
    update public.login_attempts set attempt_count = v_count, updated_at = now() where identifier = v_key;
  elsif r.locked_until is not null and r.locked_until > now() then
    -- Already locked; keep the lock.
    return jsonb_build_object('enabled', true, 'locked', true,
      'retry_after_seconds', greatest(0, ceil(extract(epoch from (r.locked_until - now())))::int));
  else
    -- Window expired: start a fresh window.
    v_count := 1;
    update public.login_attempts set attempt_count = 1, window_started_at = now(), locked_until = null, updated_at = now()
      where identifier = v_key;
  end if;

  if v_count >= v_max then
    v_locked_until := now() + make_interval(mins => v_lock);
    update public.login_attempts set locked_until = v_locked_until, updated_at = now() where identifier = v_key;
    return jsonb_build_object('enabled', true, 'locked', true,
      'retry_after_seconds', v_lock * 60);
  end if;
  return jsonb_build_object('enabled', true, 'locked', false,
    'remaining', greatest(0, v_max - v_count));
exception when others then
  return jsonb_build_object('enabled', false, 'locked', false);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.record_pm_service(p_program_id uuid, p_service_date date DEFAULT CURRENT_DATE, p_meter_reading numeric DEFAULT NULL::numeric, p_performed_by text DEFAULT NULL::text, p_workshop text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_tasks_done jsonb DEFAULT '[]'::jsonb, p_parts_used jsonb DEFAULT '[]'::jsonb, p_parts_cost numeric DEFAULT NULL::numeric, p_labour_cost numeric DEFAULT NULL::numeric, p_findings text DEFAULT NULL::text, p_outcome text DEFAULT 'completed'::text, p_work_order_no text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan           public.pm_programs%ROWTYPE;
  v_rec            public.pm_service_records%ROWTYPE;
  v_next_due       date;
  v_next_due_meter numeric;
  v_svc_date       date := COALESCE(p_service_date, current_date);
  v_outcome        text := COALESCE(NULLIF(btrim(p_outcome), ''), 'completed');
BEGIN
  SELECT * INTO v_plan FROM public.pm_programs WHERE id = p_program_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PM program not found';
  END IF;

  IF v_plan.organisation_id IS DISTINCT FROM public.app_current_org() THEN
    RAISE EXCEPTION 'Not authorized for this organisation';
  END IF;
  IF public.get_my_role() NOT IN ('Admin','Manager','Director') THEN
    RAISE EXCEPTION 'Not authorized to record a service';
  END IF;
  IF NOT public.app_write_country_ok(v_plan.country) THEN
    RAISE EXCEPTION 'Cross-country service record denied.' USING errcode = '42501';
  END IF;

  IF v_outcome NOT IN ('completed','partial','deferred','failed') THEN
    RAISE EXCEPTION 'Invalid outcome: %', v_outcome;
  END IF;

  v_next_due := v_plan.next_due;
  IF v_plan.interval_value IS NOT NULL AND v_plan.interval_value > 0 THEN
    IF v_plan.interval_type = 'days' THEN
      v_next_due := v_svc_date + make_interval(days => v_plan.interval_value::int);
    ELSIF v_plan.interval_type = 'months' THEN
      v_next_due := v_svc_date + make_interval(months => v_plan.interval_value::int);
    END IF;
  END IF;

  v_next_due_meter := v_plan.next_due_meter;
  IF v_plan.meter_source <> 'none'
     AND v_plan.meter_interval IS NOT NULL AND v_plan.meter_interval > 0
     AND p_meter_reading IS NOT NULL THEN
    IF v_plan.last_done_meter IS NOT NULL AND p_meter_reading < v_plan.last_done_meter THEN
      RAISE EXCEPTION 'Meter reading % is below the last recorded reading %',
        p_meter_reading, v_plan.last_done_meter;
    END IF;
    v_next_due_meter := p_meter_reading + v_plan.meter_interval;
  END IF;

  INSERT INTO public.pm_service_records (
    organisation_id, country, pm_program_id, asset_no, service_date,
    meter_reading, meter_type, performed_by, workshop, site,
    tasks_done, parts_used, parts_cost, labour_cost, findings, outcome,
    next_due, next_due_meter, work_order_no, notes
  ) VALUES (
    v_plan.organisation_id, v_plan.country, v_plan.id, v_plan.asset_no, v_svc_date,
    p_meter_reading, v_plan.meter_source, p_performed_by, p_workshop, COALESCE(p_site, v_plan.site),
    COALESCE(p_tasks_done, '[]'::jsonb), COALESCE(p_parts_used, '[]'::jsonb),
    p_parts_cost, p_labour_cost, p_findings, v_outcome,
    v_next_due, v_next_due_meter, p_work_order_no, p_notes
  ) RETURNING * INTO v_rec;

  UPDATE public.pm_programs SET
    last_done       = v_svc_date,
    last_done_meter = COALESCE(p_meter_reading, last_done_meter),
    next_due        = v_next_due,
    next_due_meter  = v_next_due_meter,
    updated_at      = now()
  WHERE id = p_program_id
  RETURNING * INTO v_plan;

  RETURN json_build_object('record', row_to_json(v_rec), 'program', row_to_json(v_plan));
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.record_release(p_version text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if not (public.is_super_admin() or public.app_role()='Admin') then raise exception 'forbidden' using errcode='42501'; end if;
  if coalesce(btrim(p_version),'')='' then raise exception 'version required'; end if;
  insert into public.releases (version, notes) values (p_version, p_notes) returning id into v_id;
  return json_build_object('ok',true,'id',v_id);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reference_asset_options(p_country text DEFAULT NULL::text)
 RETURNS TABLE(asset_no text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT a AS asset_no FROM (
    SELECT DISTINCT btrim(asset_no) AS a, country FROM public.vehicle_fleet WHERE btrim(coalesce(asset_no,'')) <> '' AND organisation_id = public.app_current_org() and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(asset_no), country FROM public.tyre_records  WHERE btrim(coalesce(asset_no,'')) <> '' AND organisation_id = public.app_current_org() and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(asset_no), country FROM public.inspections   WHERE btrim(coalesce(asset_no,'')) <> '' AND organisation_id = public.app_current_org() and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  ) u
  WHERE (p_country IS NULL OR p_country IN ('All','') OR u.country IS NULL OR u.country = p_country)
    AND (p_country is null or p_country in ('All','') or public.app_can_see_country(p_country) is not false)
    AND (u.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries())
         or lower(btrim(u.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  GROUP BY a
  ORDER BY a;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reference_site_options(p_country text DEFAULT NULL::text)
 RETURNS TABLE(name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  SELECT s AS name FROM (
    SELECT DISTINCT btrim(site) AS s, country FROM public.vehicle_fleet      WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.tyre_records       WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.inspections        WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.accidents          WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.work_orders        WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.corrective_actions WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(site), country FROM public.gate_passes        WHERE btrim(coalesce(site,'')) <> '' AND organisation_id = (select public.app_current_org()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    UNION SELECT DISTINCT btrim(name), country FROM public.sites              WHERE btrim(coalesce(name,'')) <> '' AND coalesce(active,true) AND organisation_id = (select public.app_current_org()) and ((name)::text is null or btrim((name)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((name)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  ) u
  WHERE (p_country IS NULL OR p_country IN ('All','') OR u.country IS NULL OR u.country = p_country)
    AND (p_country is null or p_country in ('All','') or public.app_can_see_country(p_country) is not false)
    AND (u.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries())
         or lower(btrim(u.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
  GROUP BY s
  ORDER BY s;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.register_user_device(p_push_token text, p_platform text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF p_push_token IS NULL OR btrim(p_push_token) = '' THEN
    RAISE EXCEPTION 'push token required';
  END IF;

  INSERT INTO public.user_devices AS d
    (user_id, organisation_id, push_token, platform, device_id, app_version,
     last_seen_at, revoked)
  VALUES
    (v_uid, public.app_current_org(), btrim(p_push_token), p_platform, p_device_id,
     p_app_version, now(), false)
  ON CONFLICT (push_token) DO UPDATE
    SET user_id         = v_uid,
        organisation_id = public.app_current_org(),
        platform        = COALESCE(EXCLUDED.platform, d.platform),
        device_id       = COALESCE(EXCLUDED.device_id, d.device_id),
        app_version     = COALESCE(EXCLUDED.app_version, d.app_version),
        last_seen_at    = now(),
        revoked         = false
  RETURNING d.id INTO v_id;

  UPDATE public.profiles
     SET push_token = btrim(p_push_token),
         push_token_updated_at = now()
   WHERE id = v_uid;

  RETURN v_id;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reject_accident_closure(p_accident_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name      text;
  v_requester uuid;
  v_closure_status text;
BEGIN
  -- cap-guard:approve
  if public.app_cap_revoked('accidents','approve') then
    raise exception 'You are not permitted to approve or decide this record.' using errcode = '42501';
  end if;
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'Only Admin, Manager or Director can reject closures';
  END IF;

  -- V570: tenant wall. Refuses a case outside the caller's org/country/site.
  PERFORM public._accident_rpc_context(p_accident_id);

  SELECT COALESCE(full_name, username, 'Reviewer') INTO v_name FROM public.profiles WHERE id = auth.uid();
  -- Lock the current case state before deciding or creating audit/notifications.
  SELECT close_requested_by, closure_status
    INTO v_requester, v_closure_status
    FROM public.accidents
   WHERE id = p_accident_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Incident % not found.', p_accident_id USING ERRCODE = 'P0002';
  END IF;
  -- Recheck scope after waiting for any concurrent case update.
  PERFORM public._accident_rpc_context(p_accident_id);
  IF v_closure_status IS DISTINCT FROM 'pending_closure' THEN
    RAISE EXCEPTION 'Accident closure is no longer pending review.'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.accidents
     SET closure_status          = 'open',
         closure_rejected_reason = p_reason
   WHERE id = p_accident_id;

  INSERT INTO public.accident_remarks (accident_id, author_id, author_name, remark, remark_type)
  VALUES (p_accident_id, auth.uid(), v_name,
          'Closure rejected' || CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN ': ' || p_reason ELSE '' END,
          'closure_rejected');

  IF v_requester IS NOT NULL AND v_requester <> auth.uid() THEN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    VALUES (v_requester, 'closure_rejected', 'Closure rejected',
            'Your accident closure was rejected by ' || v_name ||
            CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN ': ' || p_reason ELSE '' END,
            'accident', p_accident_id);
  END IF;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reject_pending_upload(p_upload_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org      uuid;
  v_prev     text;
  v_reviewer text;
BEGIN
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'Only Admin, Manager or Director can reject uploads';
  END IF;

  v_org := public.app_current_org();

  UPDATE public.pending_uploads
     SET status        = 'rejected',
         import_status  = 'rejected',
         review_note    = p_reason,
         reviewed_by    = auth.uid(),
         reviewed_at    = now()
   WHERE id = p_upload_id
     AND status = 'pending'
     AND (organisation_id IS NULL
          OR organisation_id = v_org
          OR public.is_super_admin());

  IF NOT FOUND THEN
    SELECT status,
           COALESCE(pr.full_name, pr.username, 'another reviewer')
      INTO v_prev, v_reviewer
      FROM public.pending_uploads pu
      LEFT JOIN public.profiles pr ON pr.id = pu.reviewed_by
     WHERE pu.id = p_upload_id;

    IF v_prev IS NULL THEN
      RAISE EXCEPTION 'That upload no longer exists.';
    ELSIF v_prev <> 'pending' THEN
      RAISE EXCEPTION 'This upload was already % by %.', v_prev, v_reviewer;
    ELSE
      RAISE EXCEPTION 'You do not have access to reject this upload.';
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'status', 'rejected');
END;
$function$;
-- @@
