CREATE OR REPLACE FUNCTION public.repair_request_mint_rfr()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if nullif(btrim(coalesce(new.rfr_no, '')), '') is null then
    new.rfr_no := public.next_rfr_no(new.organisation_id, new.country, new.reported_at);
  else
    new.rfr_no := upper(btrim(new.rfr_no));
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.repair_request_stamp_acknowledged()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status = 'acknowledged' then
      new.acknowledged_at := now();
      new.acknowledged_by := auth.uid();
    else
      new.acknowledged_at := null;
      new.acknowledged_by := null;
    end if;
    return new;
  end if;
  if old.acknowledged_at is not null then
    new.acknowledged_at := old.acknowledged_at;
    new.acknowledged_by := old.acknowledged_by;
    return new;
  end if;
  if new.status = 'acknowledged' and old.status is distinct from 'acknowledged' then
    new.acknowledged_at := now();
    new.acknowledged_by := auth.uid();
  else
    new.acknowledged_at := old.acknowledged_at;
    new.acknowledged_by := old.acknowledged_by;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.replace_open_work_orders(p_country text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_country  text := nullif(btrim(p_country), '');
  v_org      uuid := public.app_current_org();
  v_rows     jsonb;
  v_deleted  integer := 0;
  v_inserted integer := 0;
begin
  if not coalesce(public.app_is_elevated(), false) then
    raise exception 'Not permitted to replace the open job card list' using errcode = '42501';
  end if;
  if v_country is null then
    raise exception 'A country is required to replace the open job card list' using errcode = '22023';
  end if;
  if v_org is null then
    -- No tenant in context (e.g. a service_role call with no profile). A tenant-scoped
    -- replace is impossible without one, so refuse rather than touch every org's rows.
    raise exception 'No organisation in context to replace the open job card list' using errcode = '42501';
  end if;
  if public.app_can_see_country(v_country) is not true then
    raise exception 'Not permitted for country %', v_country using errcode = '42501';
  end if;

  -- Force the country onto every row and drop the auto-managed columns so the
  -- table defaults / stamp-org trigger apply (a jsonb null would override them).
  v_rows := (
    select coalesce(jsonb_agg(
             (elem - 'id' - 'created_at' - 'updated_at' - 'organisation_id')
             || jsonb_build_object('country', v_country)
           ), '[]'::jsonb)
    from jsonb_array_elements(case when jsonb_typeof(p_rows) = 'array' then p_rows else '[]'::jsonb end) elem
    where jsonb_typeof(elem) = 'object'
  );

  -- Atomic snapshot replace for THIS tenant's rows in THIS country only. DEFINER
  -- bypasses RLS, so the organisation predicate is what keeps the delete inside the
  -- caller's tenant; other orgs' and null-country rows are untouched.
  delete from public.open_work_orders where organisation_id = v_org and country = v_country;
  get diagnostics v_deleted = row_count;

  insert into public.open_work_orders
    (organisation_id, job_card_no, location, job_card_type, jc_status, job_card_date,
     open_time, asset_type, asset_no, days_open, complaint, country)
  select v_org, r.job_card_no, r.location, r.job_card_type, r.jc_status, r.job_card_date,
         r.open_time, r.asset_type, r.asset_no, r.days_open, r.complaint, v_country
  from jsonb_populate_recordset(null::public.open_work_orders, v_rows) r
  where coalesce(btrim(r.job_card_no), '') <> '';
  get diagnostics v_inserted = row_count;

  return jsonb_build_object('ok', true, 'deleted', v_deleted, 'inserted', v_inserted);
exception
  when unique_violation or serialization_failure then
    -- Never 40001: PostgREST retries it forever. PT409 -> a clean HTTP 409 and
    -- the whole transaction (delete + insert) rolls back, keeping the old list.
    raise exception 'The open job card list changed while saving; upload it again'
      using errcode = 'PT409';
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_asset_metrics(p_country text DEFAULT 'All'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  WITH f AS (
    SELECT
      COALESCE(asset_no,'Unknown') AS asset_no,
      (COALESCE(cost_per_tyre,0) * COALESCE(qty,1))::numeric AS cost,
      risk_level, brand, site, category, issue_date
    FROM public.tyre_records
    WHERE (tyre_records.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and (p_country = 'All' OR p_country IS NULL OR country = p_country OR country IS NULL) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND (p_from IS NULL OR issue_date >= p_from)
      AND (p_to   IS NULL OR issue_date <= p_to)
  ), g AS (
    SELECT
      asset_no,
      count(*) cnt,
      sum(cost) total_cost,
      count(*) FILTER (WHERE risk_level = 'High') high_risk,
      count(*) FILTER (WHERE risk_level IN ('High','Critical')) high_or_crit,
      min(issue_date) first_seen,
      max(issue_date) last_seen,
      array_remove(array_agg(DISTINCT brand), NULL) brands,
      array_remove(array_agg(DISTINCT site), NULL) sites,
      array_remove(array_agg(DISTINCT category), NULL) categories,
      GREATEST( (max(issue_date) - min(issue_date))::numeric / 30.0, 0) span_raw
    FROM f GROUP BY asset_no
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'assetNo', asset_no,
    'count', cnt,
    'totalCost', total_cost,
    'highRiskCount', high_risk,
    'highOrCriticalCount', high_or_crit,
    'firstSeen', first_seen,
    'lastSeen', last_seen,
    'brands', to_jsonb(brands),
    'sites', to_jsonb(sites),
    'categories', to_jsonb(categories),
    'spanMonths', CASE WHEN span_raw > 0 THEN span_raw ELSE 1 END,
    'failureFreqPerMonth', CASE WHEN span_raw > 0 THEN cnt / span_raw ELSE cnt END
  ) ORDER BY cnt DESC), '[]')
  FROM g;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_asset_overview(p_country text DEFAULT 'All'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  WITH f AS (
    SELECT
      COALESCE(asset_no,'Unknown') AS asset_no,
      site, country,
      (km_at_removal IS NULL) AS is_active,
      risk_level,
      COALESCE(tread_depth, 0)::numeric AS td,
      (COALESCE(cost_per_tyre,0) * COALESCE(qty,1))::numeric AS cost,
      issue_date
    FROM public.tyre_records
    WHERE (tyre_records.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and (p_country = 'All' OR p_country IS NULL OR country = p_country OR country IS NULL) and (p_country is null or p_country = 'All' or public.app_can_see_country(p_country)) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  ),
  s AS (
    SELECT *,
      CASE WHEN td >= 6 THEN 100 WHEN td >= 4 THEN 70 WHEN td >= 2 THEN 40 ELSE 10 END AS tread_pts,
      CASE risk_level WHEN 'Low' THEN 100 WHEN 'Medium' THEN 70 WHEN 'High' THEN 40 WHEN 'Critical' THEN 10 ELSE 50 END AS risk_pts
    FROM f
  ),
  g AS (
    SELECT
      asset_no,
      max(site) site, max(country) country,
      count(*) total_tyres,
      count(*) FILTER (WHERE is_active) active_tyres,
      sum(cost) total_cost,
      sum(cost) FILTER (WHERE issue_date >= date_trunc('year', CURRENT_DATE)) ytd_cost,
      max(issue_date) latest_date,
      avg(tread_pts) FILTER (WHERE is_active) tread_active,
      avg(risk_pts)  FILTER (WHERE is_active) risk_active,
      avg(tread_pts) tread_all,
      avg(risk_pts)  risk_all,
      min(CASE risk_level WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 WHEN 'Low' THEN 4 ELSE 9 END)
        FILTER (WHERE is_active) worst_active_ord,
      min(CASE risk_level WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 WHEN 'Low' THEN 4 ELSE 9 END) worst_all_ord
    FROM s GROUP BY asset_no
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'asset_no', asset_no,
    'site', site,
    'country', country,
    'total_tyres', total_tyres,
    'active_tyres', active_tyres,
    'total_cost', total_cost,
    'ytd_cost', COALESCE(ytd_cost,0),
    'latest_date', latest_date,
    'worst_risk', (CASE COALESCE(NULLIF(worst_active_ord,9), worst_all_ord)
                     WHEN 1 THEN 'Critical' WHEN 2 THEN 'High' WHEN 3 THEN 'Medium' WHEN 4 THEN 'Low' ELSE NULL END),
    'health_score', ROUND(
      (COALESCE(CASE WHEN active_tyres>0 THEN tread_active ELSE tread_all END,0) * 0.4) +
      (COALESCE(CASE WHEN active_tyres>0 THEN risk_active  ELSE risk_all  END,0) * 0.4) +
      ((CASE
          WHEN latest_date IS NULL THEN 0
          WHEN (CURRENT_DATE - latest_date) <= 7  THEN 100
          WHEN (CURRENT_DATE - latest_date) <= 14 THEN 80
          WHEN (CURRENT_DATE - latest_date) <= 30 THEN 60
          WHEN (CURRENT_DATE - latest_date) <= 60 THEN 30
          ELSE 0 END) * 0.2)
    )
  ) ORDER BY total_tyres DESC), '[]')
  FROM g;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_country_metrics(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  WITH f AS (
    SELECT COALESCE(country,'KSA') AS country,
      (COALESCE(cost_per_tyre,0) * COALESCE(qty,1))::numeric AS cost,
      risk_level, brand, site, cost_per_tyre, km_at_fitment, km_at_removal
    FROM public.tyre_records
    WHERE (p_from IS NULL OR issue_date >= p_from)
      AND (p_to   IS NULL OR issue_date <= p_to)
      AND (organisation_id IS NULL OR organisation_id = public.app_current_org() OR public.app_is_org_admin()) and ((site)::text is null or btrim((site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND public.app_can_see_country(country)
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'country', country, 'count', cnt, 'totalCost', total_cost,
    'highRiskPct', CASE WHEN cnt>0 THEN (high_risk::numeric/cnt)*100 ELSE 0 END,
    'avgCpk', avg_cpk, 'brandCount', brand_count, 'siteCount', site_count,
    'avgCostPerTyre', CASE WHEN cnt>0 THEN total_cost/cnt ELSE 0 END
  ) ORDER BY total_cost DESC), '[]')
  FROM (
    SELECT country, count(*) cnt, sum(cost) total_cost,
      count(*) FILTER (WHERE risk_level IN ('High','Critical')) high_risk,
      count(DISTINCT brand) brand_count, count(DISTINCT site) site_count,
      avg(cost_per_tyre / NULLIF(km_at_removal - km_at_fitment,0))
        FILTER (WHERE cost_per_tyre > 0 AND km_at_removal > km_at_fitment) avg_cpk
    FROM f GROUP BY country
  ) g;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_country_trends(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(country text, month date, cnt bigint, cost numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
  select coalesce(r.country,'KSA') as country,
         date_trunc('month', r.issue_date)::date as month,
         count(*) as cnt,
         coalesce(sum(coalesce(r.cost_per_tyre,0) * coalesce(r.qty,1)),0)::numeric as cost
  from public.tyre_records r
  where r.issue_date is not null
    and (p_from is null or r.issue_date >= p_from)
    and (p_to   is null or r.issue_date <= p_to)
    and (r.organisation_id is null or r.organisation_id = public.app_current_org() or public.app_is_org_admin()) and ((r.site)::text is null or btrim((r.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((r.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
    and public.app_can_see_country(r.country)
  group by 1, 2
  order by 2, 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_exec_digest(p_org uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with anchor as (
  select coalesce(max(issue_date), current_date) + 1 as a
  from tyre_records t where (p_org is null or t.organisation_id = p_org)
),
d as (
  select (a - p_days) as c_from, a as c_to,
         (a - 2*p_days) as p_from, (a - p_days) as p_to
  from anchor
),
tyr_c as (
  select count(*) as cnt, coalesce(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)),0) as spend,
    count(*) filter (where risk_level in ('High','Critical')) as high_risk,
    coalesce(sum(cost_per_tyre) filter (where coalesce(total_km,0)>0),0) as cpk_cost,
    coalesce(sum(total_km) filter (where coalesce(total_km,0)>0),0) as cpk_km
  from tyre_records t, d where t.issue_date >= d.c_from and t.issue_date < d.c_to and (p_org is null or t.organisation_id = p_org)
),
tyr_p as (
  select count(*) as cnt, coalesce(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)),0) as spend,
    count(*) filter (where risk_level in ('High','Critical')) as high_risk
  from tyre_records t, d where t.issue_date >= d.p_from and t.issue_date < d.p_to and (p_org is null or t.organisation_id = p_org)
),
rem_c as (select count(*) as cnt from tyre_records t, d where t.removal_date >= d.c_from and t.removal_date < d.c_to and (p_org is null or t.organisation_id = p_org)),
tyr_all as (
  select count(*) as cnt, coalesce(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)),0) as spend,
    count(*) filter (where risk_level in ('High','Critical')) as high_risk,
    count(*) filter (where risk_level = 'Critical') as critical,
    coalesce(sum(cost_per_tyre) filter (where coalesce(total_km,0)>0),0) as cpk_cost,
    coalesce(sum(total_km) filter (where coalesce(total_km,0)>0),0) as cpk_km,
    count(*) filter (where removal_date is not null) as removals,
    count(*) filter (where cost_per_tyre is null) as missing_cost,
    min(issue_date) as first_date, max(issue_date) as last_date
  from tyre_records t where (p_org is null or t.organisation_id = p_org)
),
top_brand as (select coalesce(jsonb_agg(jsonb_build_object('label',brand,'value',round(spend)) order by spend desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(brand),''),'(unknown)') as brand, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 order by spend desc limit 5) x),
top_site as (select coalesce(jsonb_agg(jsonb_build_object('label',site,'value',round(spend)) order by spend desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(site),''),'(unknown)') as site, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 order by spend desc limit 5) x),
top_reason as (select coalesce(jsonb_agg(jsonb_build_object('label',reason,'value',cnt) order by cnt desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(coalesce(reason_for_removal,removal_reason)),''),'(unspecified)') as reason, count(*) as cnt from tyre_records t where t.removal_date is not null and (p_org is null or t.organisation_id=p_org) group by 1 order by cnt desc limit 5) x),
wo as (select count(*) filter (where status not in ('Completed','Closed','Cancelled')) as open_cnt, count(*) filter (where status not in ('Completed','Closed','Cancelled') and target_completion < now()) as overdue_cnt, coalesce(sum(total_cost),0) as cost_total, coalesce(sum(breakdown_hours),0) as breakdown_total, count(*) as total_cnt from work_orders w where (p_org is null or w.organisation_id=p_org)),
ca as (select count(*) filter (where coalesce(closed_at,resolved_at) is null) as open_cnt, count(*) filter (where coalesce(closed_at,resolved_at) is null and due_date < now()) as overdue_cnt from corrective_actions c where (p_org is null or c.organisation_id=p_org)),
acc as (select count(*) as cnt, coalesce(sum(coalesce(repair_cost,estimated_damage_cost,0)),0) as cost from accidents a where (p_org is null or a.organisation_id=p_org)),
insp as (select count(*) as total, count(*) filter (where coalesce(completed_date,inspection_date) >= (select c_from from d)) as recent from inspections i where (p_org is null or i.organisation_id=p_org)),
rca as (select count(*) as cnt from rca_records r where (p_org is null or r.organisation_id=p_org)),
fleet as (select count(*) filter (where coalesce(is_active,true)) as active_cnt, coalesce(sum(monthly_tyre_budget),0) as monthly_budget from vehicle_fleet v where (p_org is null or v.organisation_id=p_org)),
dup as (select count(*) as cnt from (select coalesce(nullif(serial_no,''),serial_number) as s from tyre_records t where (p_org is null or t.organisation_id=p_org) and coalesce(nullif(serial_no,''),serial_number) is not null group by 1 having count(*)>1) z),
mtrend as (select coalesce(jsonb_agg(jsonb_build_object('label',ym,'value',round(spend),'count',cnt) order by ym),'[]'::jsonb) as v from (select to_char(date_trunc('month',issue_date),'YYYY-MM') as ym, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend, count(*) as cnt from tyre_records t, anchor where t.issue_date >= (anchor.a - interval '6 months') and (p_org is null or t.organisation_id=p_org) group by 1 order by 1) x),
worst as (select coalesce(jsonb_agg(jsonb_build_object('label',asset,'value',round(spend),'count',cnt) order by spend desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(asset_no),''),'(unassigned)') as asset, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend, count(*) as cnt from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 order by spend desc limit 5) x),
bypos as (select coalesce(jsonb_agg(jsonb_build_object('label',pos,'value',cnt) order by cnt desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(coalesce(position,tyre_position)),''),'(unknown)') as pos, count(*) as cnt from tyre_records t where t.removal_date is not null and (p_org is null or t.organisation_id=p_org) group by 1 order by cnt desc limit 6) x),
bycat as (select coalesce(jsonb_agg(jsonb_build_object('label',cat,'value',round(spend),'count',cnt) order by spend desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(category),''),'(uncategorised)') as cat, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend, count(*) as cnt from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 order by spend desc limit 6) x),
byctry as (select coalesce(jsonb_agg(jsonb_build_object('label',ctry,'value',round(spend),'count',cnt) order by spend desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(country),''),'(none)') as ctry, sum(coalesce(cost_per_tyre,0)*coalesce(qty,1)) as spend, count(*) as cnt from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 order by spend desc limit 6) x),
proj as (select case when max(issue_date)-min(issue_date) >= 30 then round(sum(coalesce(cost_per_tyre,0)*coalesce(qty,1))::numeric / greatest(max(issue_date)-min(issue_date)+1,1) * 365) else null end as annual from tyre_records t where (p_org is null or t.organisation_id=p_org)),
brel as (select coalesce(jsonb_agg(jsonb_build_object('label',brand,'value',cnt,'risk_pct',risk_pct) order by risk_pct desc, cnt desc),'[]'::jsonb) as v from (select coalesce(nullif(trim(brand),''),'(unknown)') as brand, count(*) as cnt, round(100.0*count(*) filter (where risk_level in ('High','Critical'))/nullif(count(*),0)) as risk_pct from tyre_records t where (p_org is null or t.organisation_id=p_org) group by 1 having count(*)>=3 order by risk_pct desc nulls last, cnt desc limit 5) x)
select jsonb_build_object(
  'period_days',p_days,'win_from',(select c_from from d),'win_to',(select c_to from d),
  'win',jsonb_build_object('tyres',jsonb_build_object('cur',(select cnt from tyr_c),'prev',(select cnt from tyr_p)),'spend',jsonb_build_object('cur',(select spend from tyr_c),'prev',(select spend from tyr_p)),'high_risk',jsonb_build_object('cur',(select high_risk from tyr_c),'prev',(select high_risk from tyr_p)),'removals',(select cnt from rem_c),'inspections',(select recent from insp)),
  'all',jsonb_build_object('tyres',(select cnt from tyr_all),'spend',(select spend from tyr_all),'high_risk',(select high_risk from tyr_all),'critical',(select critical from tyr_all),'removals',(select removals from tyr_all),'cpk',case when (select cpk_km from tyr_all)>0 then round((select cpk_cost from tyr_all)/(select cpk_km from tyr_all),3) else null end,'first_date',(select first_date from tyr_all),'last_date',(select last_date from tyr_all)),
  'wo_open',(select open_cnt from wo),'wo_overdue',(select overdue_cnt from wo),'wo_total',(select total_cnt from wo),'wo_cost',(select cost_total from wo),'breakdown_hours',(select breakdown_total from wo),
  'ca_open',(select open_cnt from ca),'ca_overdue',(select overdue_cnt from ca),'accidents',(select cnt from acc),'accident_cost',(select cost from acc),'inspections',(select total from insp),'rca',(select cnt from rca),'fleet_active',(select active_cnt from fleet),'monthly_budget',(select monthly_budget from fleet),'missing_cost',(select missing_cost from tyr_all),'dup_serials',(select cnt from dup),
  'top_brands',(select v from top_brand),'top_sites',(select v from top_site),'top_removal_reasons',(select v from top_reason),
  'monthly_trend',(select v from mtrend),'worst_assets',(select v from worst),'by_position',(select v from bypos),'by_category',(select v from bycat),'by_country',(select v from byctry),'projected_annual_spend',(select annual from proj),'brand_reliability',(select v from brel)
);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_org_tyre_spend(p_org uuid, p_from date DEFAULT NULL::date)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(SUM(COALESCE(r.cost_per_tyre,0) * COALESCE(r.qty,1)),0)::numeric
  FROM public.tyre_records r
  WHERE (r.organisation_id = p_org OR (p_org IS NULL AND r.organisation_id IS NULL))
    AND (p_from IS NULL OR r.issue_date >= p_from);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_send_log_set_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organisation_id IS NULL AND NEW.schedule_id IS NOT NULL THEN
    SELECT org_id INTO NEW.organisation_id FROM public.report_schedules WHERE id = NEW.schedule_id;
  END IF;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.report_tyre_summary(p_country text DEFAULT 'All'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
begin
  if p_country is not null and p_country <> 'All' and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  return (

  WITH f AS (
    SELECT r.asset_no, r.risk_level, r.site, r.brand, r.category, r.issue_date,
           (COALESCE(r.cost_per_tyre,0) * COALESCE(r.qty,1))::numeric AS cost
    FROM public.tyre_records r
    WHERE (r.organisation_id = (select public.app_current_org()) or (select public.is_super_admin())) and (p_country = 'All' OR p_country IS NULL OR r.country = p_country OR r.country IS NULL) and (r.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(r.country)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((r.site)::text is null or btrim((r.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((r.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
      AND (p_from IS NULL OR r.issue_date >= p_from)
      AND (p_to   IS NULL OR r.issue_date <= p_to)
  ),
  agg AS (
    SELECT count(*) total_records,
           count(DISTINCT asset_no) FILTER (WHERE asset_no IS NOT NULL) distinct_assets,
           COALESCE(sum(cost),0) total_cost,
           count(*) FILTER (WHERE risk_level='Critical') crit,
           count(*) FILTER (WHERE risk_level='High') high,
           count(*) FILTER (WHERE risk_level='Medium') med,
           count(*) FILTER (WHERE risk_level='Low') low,
           count(*) FILTER (WHERE risk_level IN ('Critical','High')) high_risk,
           count(DISTINCT asset_no) FILTER (WHERE risk_level IN ('Critical','High') AND asset_no IS NOT NULL) v_alerts
    FROM f
  ),
  by_site AS (
    SELECT site, count(*) cnt, sum(cost) cost, count(DISTINCT asset_no) vehicles,
           count(*) FILTER (WHERE risk_level IN ('Critical','High')) alerts,
           count(*) FILTER (WHERE risk_level='Low') good
    FROM f WHERE site IS NOT NULL GROUP BY site
  ),
  by_cat AS (SELECT category, count(*) c FROM f WHERE category IS NOT NULL GROUP BY category),
  by_brand AS (SELECT brand, count(*) c, sum(cost) cost FROM f WHERE brand IS NOT NULL GROUP BY brand),
  by_month AS (
    SELECT date_trunc('month', issue_date) m, count(*) c, sum(cost) cost
    FROM f WHERE issue_date >= (date_trunc('month', COALESCE(p_to, CURRENT_DATE)) - interval '5 months')
    GROUP BY 1
  )
  SELECT jsonb_build_object(
    'total_records', a.total_records, 'distinct_assets', a.distinct_assets, 'total_cost', a.total_cost,
    'critical', a.crit, 'high', a.high, 'medium', a.med, 'low', a.low,
    'high_risk', a.high_risk, 'vehicles_with_alerts', a.v_alerts,
    'risk_breakdown', (SELECT jsonb_agg(jsonb_build_object('level',level,'count',c) ORDER BY c DESC) FROM (
        SELECT 'Critical' level, a.crit c UNION ALL SELECT 'High', a.high UNION ALL
        SELECT 'Medium', a.med UNION ALL SELECT 'Low', a.low
        UNION ALL SELECT 'Unknown', (a.total_records - a.crit - a.high - a.med - a.low)
      ) t WHERE c > 0),
    'top_sites', (SELECT COALESCE(jsonb_agg(jsonb_build_object('site',site,'count',cnt,'cost',cost) ORDER BY cnt DESC),'[]')
                    FROM (SELECT site,cnt,cost FROM by_site ORDER BY cnt DESC LIMIT 12) t),
    'cost_by_site', (SELECT COALESCE(jsonb_agg(jsonb_build_object('site',site,'cost',cost) ORDER BY cost DESC),'[]')
                    FROM (SELECT site,cost FROM by_site ORDER BY cost DESC LIMIT 10) t),
    'site_breakdown', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'name',site,'vehicles',vehicles,'records',cnt,'alerts',alerts,
                        'compliance', CASE WHEN cnt>0 THEN round((good::numeric/cnt)*100) ELSE 0 END) ORDER BY cnt DESC),'[]')
                    FROM (SELECT * FROM by_site ORDER BY cnt DESC LIMIT 10) t),
    'category_breakdown', (SELECT COALESCE(jsonb_agg(jsonb_build_object('category',category,'count',c) ORDER BY c DESC),'[]')
                    FROM (SELECT category,c FROM by_cat ORDER BY c DESC LIMIT 12) t),
    'top_brands', (SELECT COALESCE(jsonb_agg(jsonb_build_object('brand',brand,'count',c,'cost',cost) ORDER BY c DESC),'[]')
                    FROM (SELECT brand,c,cost FROM by_brand ORDER BY c DESC LIMIT 10) t),
    'monthly_trend', (SELECT COALESCE(jsonb_agg(jsonb_build_object('month',to_char(m,'Mon YY'),'count',c,'cost',cost) ORDER BY m),'[]') FROM by_month)
  )
  FROM agg a
  );
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.request_accident_closure(p_accident_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name  text;
  v_asset text;
  v_ctx   record;
BEGIN
  -- V570: tenant wall. Refuses a case outside the caller's org/country/site.
  SELECT * INTO v_ctx FROM public._accident_rpc_context(p_accident_id);

  SELECT COALESCE(full_name, username, 'User') INTO v_name FROM public.profiles WHERE id = auth.uid();
  SELECT asset_no INTO v_asset FROM public.accidents WHERE id = p_accident_id;

  UPDATE public.accidents
     SET closure_status     = 'pending_closure',
         close_requested_by = auth.uid(),
         close_requested_at = now(),
         close_request_note = p_note
   WHERE id = p_accident_id;

  INSERT INTO public.accident_remarks (accident_id, author_id, author_name, remark, remark_type)
  VALUES (p_accident_id, auth.uid(), v_name,
          'Requested closure' || CASE WHEN p_note IS NOT NULL AND p_note <> '' THEN ': ' || p_note ELSE '' END,
          'closure_request');

  INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
  SELECT p.id, 'closure_request',
         'Accident closure requested',
         'Asset ' || COALESCE(v_asset,'—') || ' closure submitted by ' || v_name || ' — review & approve.',
         'accident', p_accident_id
    FROM public.profiles p
   WHERE lower(regexp_replace(COALESCE(p.role,''), '\s+', '_', 'g')) IN ('admin','manager','director')
     AND p.id <> auth.uid()
     AND p.org_id = v_ctx.org;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.request_elevation(p_module_key text, p_capability text, p_minutes integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_org uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_key text := lower(btrim(coalesce(p_module_key, '')));
  v_cap text := lower(btrim(coalesce(p_capability, '')));
  v_id uuid;
begin
  if v_uid is null then raise exception 'Sign in required' using errcode = '42501'; end if;
  if public.is_super_admin() then
    raise exception 'Super admins already hold every capability' using errcode = '22023';
  end if;
  if p_minutes is null or p_minutes < 5 or p_minutes > 480 then
    raise exception 'Duration must be between 5 minutes and 8 hours' using errcode = '22023';
  end if;
  if length(v_reason) < 10 then
    raise exception 'A reason of at least 10 characters is required' using errcode = '22023';
  end if;
  v_org := public._jit_validate_target(v_uid, v_key, v_cap);

  if exists (select 1 from public.jit_elevation_requests
              where target_user_id = v_uid and module_key = v_key and capability = v_cap and status = 'pending') then
    raise exception 'You already have a pending request for that capability' using errcode = '23505';
  end if;

  insert into public.jit_elevation_requests (organisation_id, target_user_id, requested_by, module_key,
                                             capability, requested_minutes, reason)
  values (v_org, v_uid, v_uid, v_key, v_cap, p_minutes, left(v_reason, 1000))
  returning id into v_id;

  perform public._jit_audit('jit_elevation_request', v_id, null,
    jsonb_build_object('module_key', v_key, 'capability', v_cap, 'minutes', p_minutes), v_reason);

  begin
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    select p.id, 'security', 'Elevation request waiting',
           coalesce((select coalesce(full_name, email) from public.profiles where id = v_uid), 'A user')
             || ' asks for ' || v_cap || ' on ' || v_key || ' for ' || p_minutes || ' minutes.',
           'jit_elevation', v_id
      from public.profiles p where coalesce(p.is_super_admin,false) and not coalesce(p.locked,false);
  exception when others then null;
  end;

  return jsonb_build_object('ok', true, 'id', v_id, 'status', 'pending');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.request_password_reset(p_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id   text := btrim(coalesce(p_identifier, ''));
  v_user record;
  v_req  uuid;
begin
  if v_id = '' or length(v_id) > 254 then
    return jsonb_build_object('ok', true);
  end if;

  select p.id, p.full_name, p.username, coalesce(p.organisation_id, p.org_id) as org
    into v_user
    from public.profiles p
    left join auth.users au on au.id = p.id
   where p.approved and not coalesce(p.locked, false)
     and (lower(p.username) = lower(v_id)
          or lower(p.employee_id) = lower(v_id)
          or lower(au.email) = lower(v_id))
   limit 1;

  if v_user.id is null then
    return jsonb_build_object('ok', true);
  end if;

  if exists (select 1 from public.password_reset_requests r
              where r.user_id = v_user.id and r.status = 'pending'
                and r.requested_at > now() - interval '1 hour') then
    return jsonb_build_object('ok', true);
  end if;

  insert into public.password_reset_requests (user_id, organisation_id)
  values (v_user.id, v_user.org)
  returning id into v_req;

  begin
    insert into public.notifications (user_id, type, title, body, entity_type)
    select a.id, 'password_reset_request',
           'Password reset requested',
           coalesce(v_user.full_name, v_user.username, 'A user')
             || coalesce(' (' || v_user.username || ')', '')
             || ' cannot sign in and asked for a new password. Set one in Console > Users.',
           'password_reset_request'
      from public.profiles a
     where a.approved and not coalesce(a.locked, false)
       and (a.is_super_admin
            or (a.role = 'Admin' and coalesce(a.organisation_id, a.org_id) = v_user.org));
  exception when others then null;
  end;

  return jsonb_build_object('ok', true);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.request_tyre_change_approval(p_vehicle_id uuid, p_change jsonb, p_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE snapshot jsonb; p jsonb:=p_change; r approval_execution_requests; action text:=p_change->>'action';
BEGIN
 IF p_operation_id IS NULL OR nullif(btrim(p_reason),'') IS NULL OR action IS NULL OR action NOT IN ('install','replace','remove','move') THEN RAISE EXCEPTION 'Action, operation ID and reason are required' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p)<>'object' OR (p-ARRAY['action','position','removed_record_id','serial_no','brand','size','tread_depth','photos','km_at_fitment','cost_per_tyre','issue_date','fitment_date','removal_reason','km_at_removal','removal_date','tyre_id','reason','km','date','to_asset_no','to_position'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Unsupported tyre-change field' USING ERRCODE='22023'; END IF;
 IF p->'photos' IS NOT NULL AND jsonb_typeof(p->'photos') NOT IN ('array','null') THEN RAISE EXCEPTION 'Photos must be an array' USING ERRCODE='22023'; END IF;
 IF action IN ('install','replace') AND (nullif(btrim(p->>'position'),'') IS NULL OR nullif(btrim(p->>'serial_no'),'') IS NULL) THEN RAISE EXCEPTION 'A tyre position and serial number are required' USING ERRCODE='22023'; END IF;
 IF action='replace' AND nullif(p->>'removed_record_id','') IS NULL THEN RAISE EXCEPTION 'Replacement requires the currently fitted tyre' USING ERRCODE='22023'; END IF;
 IF action='install' AND nullif(p->>'removed_record_id','') IS NOT NULL THEN RAISE EXCEPTION 'Use replacement when removing a fitted tyre' USING ERRCODE='22023'; END IF;
 IF action IN ('remove','move') AND nullif(p->>'tyre_id','') IS NULL THEN RAISE EXCEPTION 'Source tyre is required' USING ERRCODE='22023'; END IF;
 IF action='move' AND nullif(btrim(p->>'to_position'),'') IS NULL THEN RAISE EXCEPTION 'Destination position is required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each_text(p) x WHERE x.key IN ('km','km_at_fitment','km_at_removal','cost_per_tyre','tread_depth') AND x.value IS NOT NULL AND x.value::numeric<0) THEN RAISE EXCEPTION 'Meters, tread depth and cost cannot be negative' USING ERRCODE='22023'; END IF;
 snapshot:=approval_private.tyre_source(p_vehicle_id,p);
 IF NOT approval_private.can_execute('tyre_change') THEN RAISE EXCEPTION 'Tyre edit permission is required to request execution' USING ERRCODE='42501'; END IF;
 IF action IN ('install','replace') AND snapshot->'destination_tyre'<>'null'::jsonb THEN RAISE EXCEPTION 'Destination position is occupied' USING ERRCODE='22023'; END IF;
 IF action='replace' AND upper(btrim(coalesce(snapshot#>>'{source_tyre,tyre_position}',snapshot#>>'{source_tyre,position}'))) IS DISTINCT FROM upper(btrim(p->>'position')) THEN RAISE EXCEPTION 'Removed tyre does not match the selected position' USING ERRCODE='22023'; END IF;
 p:=p||jsonb_build_object('asset_no',snapshot#>>'{vehicle,asset_no}','country',snapshot#>>'{vehicle,country}','site',snapshot#>>'{vehicle,site}','request_reason',p_reason);
 IF action IN ('install','replace') THEN p:=p||jsonb_build_object('issue_date',coalesce(p->>'issue_date',p->>'fitment_date',current_date::text),'removal_date',coalesce(p->>'removal_date',current_date::text)); END IF;
 IF action='remove' THEN p:=p||jsonb_build_object('date',coalesce(p->>'date',current_date::text),'reason',coalesce(nullif(p->>'reason',''),p_reason)); END IF;
 SELECT * INTO r FROM approval_execution_requests WHERE operation_id=p_operation_id;
 IF FOUND THEN
  IF r.submitted_by<>auth.uid() OR r.vehicle_id IS DISTINCT FROM p_vehicle_id OR r.payload IS DISTINCT FROM p THEN RAISE EXCEPTION 'Operation ID already used for a different request' USING ERRCODE='22023'; END IF;
  RETURN to_jsonb(r);
 END IF;
 INSERT INTO approval_execution_requests(organisation_id,entity_type,vehicle_id,asset_no,country,site,title,payload,source_snapshot,operation_id,submitted_by)
 VALUES((snapshot#>>'{vehicle,organisation_id}')::uuid,'tyre_change',p_vehicle_id,p->>'asset_no',p->>'country',p->>'site',initcap(action)||' tyre on '||(p->>'asset_no'),p,snapshot,p_operation_id,auth.uid()) RETURNING * INTO r;
 SELECT * INTO r FROM approval_execution_requests WHERE id=r.id;
 RETURN to_jsonb(r);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.request_work_order_approval(p_work_order_id uuid, p_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w work_orders; r approval_execution_requests;
BEGIN
 IF p_operation_id IS NULL OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'An operation ID and request reason are required' USING ERRCODE='22023'; END IF;
 SELECT * INTO w FROM work_orders WHERE id=p_work_order_id AND organisation_id=app_current_org() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Work order unavailable' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope('work_order',w.organisation_id,w.country,w.site);
 IF NOT approval_private.can_execute('work_order') THEN RAISE EXCEPTION 'Work-order edit permission is required to request execution' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM approval_execution_requests WHERE operation_id=p_operation_id;
 IF FOUND THEN
  IF r.submitted_by<>auth.uid() OR r.work_order_id IS DISTINCT FROM w.id OR r.payload->>'reason' IS DISTINCT FROM p_reason THEN RAISE EXCEPTION 'Operation ID already used for a different request' USING ERRCODE='22023'; END IF;
  RETURN work_order_approval_context(w.id);
 END IF;
 IF w.started_at IS NOT NULL OR lower(w.status) NOT IN ('open','new','draft','pending') THEN RAISE EXCEPTION 'Approval must be requested before work starts' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM approval_execution_requests WHERE work_order_id=w.id AND (approval_status='pending' OR (approval_status='approved' AND approval_private.source_matches('work_order',source_snapshot,to_jsonb(w))))) THEN RAISE EXCEPTION 'An active request already exists for this work order' USING ERRCODE='22023'; END IF;
 INSERT INTO approval_execution_requests(organisation_id,entity_type,work_order_id,asset_no,country,site,title,payload,source_snapshot,operation_id,submitted_by)
 VALUES(w.organisation_id,'work_order',w.id,w.asset_no,w.country,w.site,'Work order '||w.work_order_no,
 jsonb_build_object('work_order_id',w.id,'reason',p_reason),to_jsonb(w),p_operation_id,auth.uid());
 RETURN work_order_approval_context(w.id);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reserve_recovery_challenge(p_challenge jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_requester text := p_challenge->>'requester_hash';
  v_destination text := p_challenge->>'destination_hash';
  v_key text;
  v_count integer;
begin
  if coalesce(v_requester, '') = '' or coalesce(v_destination, '') = '' then
    raise exception 'Missing recovery rate-limit identity';
  end if;
  for v_key in select distinct k from unnest(array['recovery-requester:' || v_requester,
      'recovery-destination:' || v_destination]) as keys(k) order by k loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_key, 0));
  end loop;
  select count(*) into v_count from public.password_recovery_challenges
    where created_at >= clock_timestamp() - interval '15 minutes'
      and (requester_hash = v_requester or destination_hash = v_destination);
  if v_count >= 5 then return false; end if;
  insert into public.password_recovery_challenges
    (id, user_id, purpose, channel, destination_hash, code_hash, requester_hash, expires_at)
  values ((p_challenge->>'id')::uuid, (p_challenge->>'user_id')::uuid,
    p_challenge->>'purpose', p_challenge->>'channel', v_destination,
    p_challenge->>'code_hash', v_requester, clock_timestamp() + interval '10 minutes');
  return true;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reserve_work_order_stock(p_work_order_id uuid, p_lines jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.reserve_work_order_stock_internal(p_work_order_id, p_lines, p_idempotency_key)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.reset_login_attempts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  delete from public.login_attempts la
  using public.profiles p, auth.users au
  where p.id = v_uid and au.id = v_uid
    and la.identifier in (lower(btrim(p.username)), lower(btrim(p.employee_id)), lower(btrim(au.email)));
exception when others then
  return;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.resolve_approvers(p_entity_type text, p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(level integer, approver_user_id uuid, approver_role text, escalate_after_days integer, specificity integer, rule_id uuid)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select m.level, m.approver_user_id, m.approver_role, m.escalate_after_days,
         (m.match_country is not null)::int + (m.match_site is not null)::int
       + (m.match_role is not null)::int + (m.match_user_id is not null)::int as specificity,
         m.id
  from public.approval_matrix m
  where m.active
    and m.entity_type = p_entity_type
    and (m.match_country is null or m.match_country = p_country)
    and (m.match_site    is null or m.match_site    = p_site)
    and (m.match_role    is null or m.match_role    = p_role)
    and (m.match_user_id is null or m.match_user_id = p_user_id)
  order by m.level, specificity desc, m.created_at;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.resolve_error_groups(p_keys text[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int := 0;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can resolve errors' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required to resolve error groups' using errcode = '22023';
  end if;
  if p_keys is null or cardinality(p_keys) = 0 then
    return jsonb_build_object('ok', true, 'resolved', 0);
  end if;
  if cardinality(p_keys) > 500 then
    raise exception 'Resolve at most 500 groups at a time' using errcode = '22023';
  end if;

  insert into public.error_group_state as s (group_key, status, note, resolved_at, updated_at, updated_by)
  select distinct k, 'resolved', left(p_reason, 500), now(), now(), auth.uid()
  from unnest(p_keys) k where nullif(btrim(k), '') is not null
  on conflict (group_key) do update set status = 'resolved', note = left(p_reason, 500),
    resolved_at = now(), updated_at = now(), updated_by = auth.uid();
  get diagnostics v_n = row_count;

  perform public.log_console_event('error_groups_resolve', null, 'error_group',
    jsonb_build_object('count', v_n, 'reason', p_reason));
  return jsonb_build_object('ok', true, 'resolved', v_n);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.resolve_production_station()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_site text;
begin
  if NEW.station is null or btrim(NEW.station) = '' then
    NEW.station := nullif(btrim(NEW.site), '');
  end if;
  if NEW.station is null then return NEW; end if;

  select m.site into v_site
    from public.production_station_map m
   where m.organisation_id = coalesce(NEW.organisation_id, public.app_current_org())
     and (m.country is null or m.country = NEW.country)
     and upper(btrim(m.station)) = upper(btrim(NEW.station))
   limit 1;

  NEW.site := coalesce(v_site, NEW.station);
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.resolve_system_logs(p_module text DEFAULT NULL::text, p_severity text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer; v_org uuid := public.app_current_org();
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT (public.is_super_admin() OR public.get_my_role() = 'Admin') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  UPDATE public.system_logs SET resolved = true, resolved_by = auth.uid(), resolved_at = now()
  WHERE resolved = false
    AND (organisation_id IS NOT DISTINCT FROM v_org)
    AND (p_module IS NULL OR module_id = p_module)
    AND (p_severity IS NULL OR severity = p_severity);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.resolve_tyre_import_review(p_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  a public.stg_monthly_tyres_audit%rowtype;
  p jsonb; v_country text; v_fd date; v_next date; v_res jsonb; v_batch uuid := gen_random_uuid(); v_id uuid;
begin
  if v_org is null or not public.app_is_elevated() then
    raise exception 'You do not have permission to resolve tyre imports' using errcode = '42501';
  end if;
  select * into a from public.stg_monthly_tyres_audit where id = p_id for update;
  if not found or a.reason not like 'replacement_needs_review%' then
    return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if coalesce(a.organisation_id, '00000000-0000-0000-0000-000000000001'::uuid) <> v_org then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if a.resolved_at is not null then return jsonb_build_object('ok', false, 'reason', 'already_resolved'); end if;
  p := a.payload;
  v_country := public.normalize_country(coalesce(a.country, p->>'country'));
  if v_country is not null and not public.app_can_see_country(v_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  v_fd := public.erp_parse_date(p->>'tyre_fix_date');

  if p_action = 'dismiss' then
    null;
  elsif p_action = 'make_current' then
    v_res := public._tyre_close_replaced(v_org, v_country, p->>'veh_no', p->>'tyre_position', p->>'tyre_no',
      v_fd, public._to_num(p->>'fixed_km'), public._to_num(p->>'fixed_hrs'), 'admin_review', v_batch, false, true);
    if v_res->>'status' not in ('closed', 'no_previous') then
      return jsonb_build_object('ok', false, 'reason', v_res->>'status'); end if;
    perform public._tyre_close_serial_elsewhere(v_org, v_country, p->>'veh_no', p->>'tyre_no', v_fd, 'admin_review', v_batch, false);
    insert into public.tyre_records (organisation_id, country, serial_no, asset_no, job_card, vehicle_type, size, position, tyre_position,
       issue_date, km_at_fitment, hrs_at_fitment, status, brand, extra_fields)
    values (v_org, v_country, p->>'tyre_no', p->>'veh_no', p->>'job_card_no', p->>'veh_type', p->>'item_tyre', p->>'tyre_position', p->>'tyre_position',
       v_fd, public._to_num(p->>'fixed_km'), public._to_num(p->>'fixed_hrs'), 'Active', nullif(btrim(p->>'brand'), ''),
       jsonb_build_object('resolved_from_review', p_id))
    returning id into v_id;
  elsif p_action = 'add_as_history' then
    select min(coalesce(t.issue_date, t.fitment_date)) into v_next from public.tyre_records t
    where t.organisation_id = v_org and coalesce(t.country, '') = coalesce(v_country, '')
      and upper(regexp_replace(coalesce(t.asset_no, ''), '\s+', '', 'g')) = upper(regexp_replace(coalesce(p->>'veh_no', ''), '\s+', '', 'g'))
      and upper(btrim(coalesce(t.tyre_position, t.position, ''))) = upper(btrim(coalesce(p->>'tyre_position', '')))
      and coalesce(t.issue_date, t.fitment_date) > v_fd;
    if v_next is null then return jsonb_build_object('ok', false, 'reason', 'no_later_fitment_use_make_current'); end if;
    insert into public.tyre_records (organisation_id, country, serial_no, asset_no, job_card, vehicle_type, size, position, tyre_position,
       issue_date, km_at_fitment, hrs_at_fitment, removal_date, status, brand, extra_fields)
    values (v_org, v_country, p->>'tyre_no', p->>'veh_no', p->>'job_card_no', p->>'veh_type', p->>'item_tyre', p->>'tyre_position', p->>'tyre_position',
       v_fd, public._to_num(p->>'fixed_km'), public._to_num(p->>'fixed_hrs'), v_next, 'Removed', nullif(btrim(p->>'brand'), ''),
       jsonb_build_object('resolved_from_review', p_id, 'removal_inferred_from_next_fitment', true))
    returning id into v_id;
  else
    return jsonb_build_object('ok', false, 'reason', 'unknown_action');
  end if;

  update public.stg_monthly_tyres_audit set resolved_at = now(), resolved_by = auth.uid(), resolution = p_action where id = p_id;
  return jsonb_build_object('ok', true, 'action', p_action, 'tyre_id', v_id, 'batch_id', v_batch);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.restamp_pending_upload_country(p_upload_id uuid, p_country text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org      uuid;
  v_rows     jsonb;
  v_new      jsonb;
  v_prev     text;
BEGIN
  IF NOT public.is_elevated_user() THEN
    RAISE EXCEPTION 'Only Admin, Manager or Director can edit an upload';
  END IF;
  IF p_country IS NULL OR btrim(p_country) = '' THEN
    RAISE EXCEPTION 'A country is required.';
  END IF;

  -- V567: p_country was accepted unchecked, so a country-scoped reviewer could
  -- re-stamp a whole batch - header AND every row - into a country they are not
  -- assigned to, and then approve it into the master table.
  IF NOT public.app_write_country_ok(p_country) THEN
    RAISE EXCEPTION 'Cross-country restamp denied: you are not assigned to country %.', p_country
      USING errcode = '42501';
  END IF;

  v_org := public.app_current_org();

  SELECT rows INTO v_rows
    FROM public.pending_uploads
   WHERE id = p_upload_id
     AND status = 'pending'
     AND (organisation_id IS NULL OR organisation_id = v_org OR public.is_super_admin())
   FOR UPDATE;

  IF NOT FOUND THEN
    SELECT status INTO v_prev FROM public.pending_uploads WHERE id = p_upload_id;
    IF v_prev IS NULL THEN
      RAISE EXCEPTION 'That upload no longer exists.';
    ELSIF v_prev <> 'pending' THEN
      RAISE EXCEPTION 'This upload was already decided and can no longer be edited.';
    ELSE
      RAISE EXCEPTION 'You do not have access to edit this upload.';
    END IF;
  END IF;

  IF v_rows IS NULL OR jsonb_typeof(v_rows) <> 'array' THEN
    v_new := '[]'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(elem || jsonb_build_object('country', p_country)), '[]'::jsonb)
      INTO v_new
      FROM jsonb_array_elements(v_rows) elem;
  END IF;

  UPDATE public.pending_uploads
     SET rows = v_new, country = p_country
   WHERE id = p_upload_id;

  RETURN jsonb_build_object('ok', true, 'country', p_country);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.retread_jobs_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  new.casing_serial := upper(btrim(new.casing_serial));
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.reverse_legacy_upload(p_batch_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid:=public.app_current_org(); v_country text; v_count integer; v_result jsonb; v_old administration_imports.upload_reversals;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL OR NOT coalesce(public.app_is_active(),false)
   OR NOT coalesce(public.app_can_admin_delete(),false) THEN
  RAISE EXCEPTION 'Only active administrators may reverse an upload' USING ERRCODE='42501';
 END IF;
 IF p_batch_id IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 3 AND 2000 THEN
  RAISE EXCEPTION 'A reversal reason is required' USING ERRCODE='22023';
 END IF;
 -- Serialize destination writers as well as two reviewers. Locks are released on failure.
 LOCK TABLE public.tyre_records IN SHARE ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_batch_id::text,0));
 SELECT * INTO v_old FROM administration_imports.upload_reversals WHERE batch_id=p_batch_id;
 IF FOUND THEN
  IF v_old.organisation_id<>v_org OR NOT coalesce(public.app_write_country_ok(v_old.country),false) THEN
   RAISE EXCEPTION 'Upload access denied' USING ERRCODE='42501';
  END IF;
  RETURN v_old.result;
 END IF;
 PERFORM 1 FROM public.upload_history WHERE batch_id=p_batch_id FOR UPDATE;
 IF NOT FOUND OR EXISTS (
  SELECT 1 FROM public.upload_history h
   WHERE h.batch_id=p_batch_id AND (h.organisation_id IS DISTINCT FROM v_org OR nullif(btrim(h.country),'') IS NULL
     OR NOT coalesce(public.app_write_country_ok(h.country),false))
 ) THEN RAISE EXCEPTION 'Upload ownership or country cannot be verified' USING ERRCODE='42501'; END IF;
 SELECT min(country) INTO v_country FROM public.upload_history WHERE batch_id=p_batch_id;
 IF EXISTS(SELECT 1 FROM public.upload_history WHERE batch_id=p_batch_id AND country<>v_country)
  OR EXISTS(SELECT 1 FROM public.tyre_records WHERE upload_batch_id=p_batch_id AND (organisation_id IS DISTINCT FROM v_org OR country IS DISTINCT FROM v_country)) THEN
  RAISE EXCEPTION 'Upload has conflicting tenant or country rows; administrator reconciliation required' USING ERRCODE='42501';
 END IF;
 IF EXISTS(SELECT 1 FROM public.cleaning_log c JOIN public.tyre_records t ON t.id=c.tyre_record_id WHERE t.upload_batch_id=p_batch_id)
  OR EXISTS(SELECT 1 FROM public.tyre_disposals d JOIN public.tyre_records t ON t.id=d.tyre_record_id WHERE t.upload_batch_id=p_batch_id) THEN
  RAISE EXCEPTION 'This batch has cleaning or disposal activity. Resolve dependent records before reversal.' USING ERRCODE='23503';
 END IF;
 SELECT count(*) INTO v_count FROM public.tyre_records WHERE upload_batch_id=p_batch_id;
 v_result:=jsonb_build_object('ok',true,'removed',v_count,'batch_id',p_batch_id);
 INSERT INTO administration_imports.upload_reversals(batch_id,organisation_id,actor,country,reason,result)
 VALUES(p_batch_id,v_org,auth.uid(),v_country,btrim(p_reason),v_result);
 INSERT INTO administration_imports.upload_reversal_rows
 SELECT p_batch_id,t.id,to_jsonb(t) FROM public.tyre_records t WHERE t.upload_batch_id=p_batch_id;
 DELETE FROM public.tyre_records WHERE upload_batch_id=p_batch_id;
 UPDATE public.upload_history SET reversed_at=now(),reversed_by=auth.uid(),reversed_count=v_count WHERE batch_id=p_batch_id;
 INSERT INTO public.audit_log_v2(user_id,action,table_name,record_id,org_id,country,record_count,new_values)
 VALUES(auth.uid(),'DELETE','tyre_records',p_batch_id::text,v_org,v_country,v_count,
 jsonb_build_object('reason',btrim(p_reason),'batch_id',p_batch_id,'history_retained',true,'archived_rows',v_count));
 RETURN v_result;
END $function$;
