CREATE OR REPLACE FUNCTION public.revoke_user_access_grant(p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target uuid;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only an active Super Admin can change access grants.' USING ERRCODE='42501';
  END IF;
  SELECT user_id INTO target FROM public.user_access_grants WHERE id=p_id;
  IF target IS NULL THEN RETURN; END IF;
  PERFORM 1 FROM public.profiles WHERE id=target FOR UPDATE;
  DELETE FROM public.user_access_grants WHERE id=p_id;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.revoke_user_device(p_push_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF p_push_token IS NULL OR btrim(p_push_token) = '' THEN
    RETURN;
  END IF;

  UPDATE public.user_devices
     SET revoked = true,
         last_seen_at = now()
   WHERE user_id = v_uid
     AND push_token = btrim(p_push_token);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.revoke_user_sessions(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
declare
  v_count integer := 0;
begin
  if p_user is null then
    return 0;
  end if;
  delete from auth.sessions where user_id = p_user;
  get diagnostics v_count = row_count;
  delete from auth.refresh_tokens where user_id = p_user::text;
  return v_count;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.rule_condition_passes(p_payload jsonb, p_cond jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actual text := p_payload ->> (p_cond ->> 'field');
  v_expect text := p_cond ->> 'value';
  v_op     text := p_cond ->> 'operator';
  v_a      numeric;
  v_b      numeric;
BEGIN
  IF v_actual IS NULL THEN RETURN false; END IF;
  IF v_op IN ('lt','lte','gt','gte') THEN
    BEGIN
      v_a := v_actual::numeric;
      v_b := v_expect::numeric;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    RETURN CASE v_op
      WHEN 'lt'  THEN v_a <  v_b
      WHEN 'lte' THEN v_a <= v_b
      WHEN 'gt'  THEN v_a >  v_b
      WHEN 'gte' THEN v_a >= v_b
    END;
  ELSIF v_op = 'eq' THEN
    RETURN lower(v_actual) = lower(COALESCE(v_expect, ''));
  ELSIF v_op = 'neq' THEN
    RETURN lower(v_actual) <> lower(COALESCE(v_expect, ''));
  ELSIF v_op = 'contains' THEN
    RETURN v_actual ILIKE '%' || COALESCE(v_expect, '') || '%';
  END IF;
  RETURN false;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.run_quality_checks(p_country text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_run uuid := gen_random_uuid(); c bigint;
  procedure_note text;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if v_org is null then raise exception 'no organisation context'; end if;

  -- helper inline via repeated pattern
  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and (brand is null or btrim(brand)=''));
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_brand_gap',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s tyres missing brand', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_brand_gap';

  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and (size is null or btrim(size)=''));
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_size_gap',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s tyres missing size', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_size_gap';

  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and status ilike '%remov%' and (removal_reason is null or btrim(removal_reason)=''));
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_removal_reason_gap',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s removed tyres with no reason', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_removal_reason_gap';

  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and coalesce(cost_per_tyre,0)=0);
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_unpriced',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s tyres with no price', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_unpriced';

  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and removal_date > current_date);
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_future_removal',v_run,p_country, case when c=0 then 'pass' else 'fail' end, c, c, r.severity, format('%s tyres with a future removal date', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_future_removal';

  c := (select count(*) from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and removal_date is not null and issue_date is not null and removal_date < issue_date);
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_reversed_dates',v_run,p_country, case when c=0 then 'pass' else 'fail' end, c, c, r.severity, format('%s tyres with removal before fitment', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_reversed_dates';

  c := (select count(*) from public.tyre_records t where t.organisation_id=v_org and (p_country is null or t.country=p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and t.asset_no is not null and btrim(t.asset_no)<>''
        and not exists (select 1 from public.vehicle_fleet f where f.organisation_id=v_org and upper(btrim(f.asset_no))=upper(btrim(t.asset_no)) and (t.country is null or f.country=t.country)));
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'tyre_orphan_asset',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s tyres whose asset is not in the fleet', c), r.source_ref from public.quality_rules r where r.rule_key='tyre_orphan_asset';

  c := (select count(*) from public.parts_consumption where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and import_uid is null);
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'spend_no_import_uid',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s expense lines with no import key', c), r.source_ref from public.quality_rules r where r.rule_key='spend_no_import_uid';

  c := (select count(*) from public.parts_consumption where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and coalesce(classify_confidence,0) <= 0.30);
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'spend_unclassified',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s expense lines filed by the low-confidence default', c), r.source_ref from public.quality_rules r where r.rule_key='spend_unclassified';

  c := (select count(*) from public.vehicle_fleet where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and (vehicle_type is null or btrim(vehicle_type)=''));
  insert into public.quality_results(organisation_id,rule_key,run_id,country,status,measured_value,failure_count,severity,message,drilldown)
  select v_org,'fleet_missing_type',v_run,p_country, case when c=0 then 'pass' else 'warn' end, c, c, r.severity, format('%s vehicles with no type', c), r.source_ref from public.quality_rules r where r.rule_key='fleet_missing_type';

  return json_build_object('ok',true,'run_id',v_run,'checked_at',now(),
    'results',(select json_agg(row_to_json(x)) from (
      select rule_key,status,measured_value,severity,message,drilldown from public.quality_results where run_id=v_run order by (status='fail') desc, measured_value desc) x));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.run_reconciliation(p_country text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_run timestamptz := now();
  e numeric; a numeric; d numeric; n int;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if v_org is null then raise exception 'no organisation context'; end if;

  -- 1) Work-order cost components vs total
  select coalesce(sum(total_cost),0), coalesce(sum(coalesce(labour_cost,0)+coalesce(parts_cost,0)),0)
    into e, a from public.work_orders where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])));
  d := coalesce(e,0)-coalesce(a,0);
  insert into public.reconciliation_runs(organisation_id,recon_key,label,country,expected_value,actual_value,difference,unit,status,affected_count,drilldown,run_at)
  values (v_org,'wo_cost_components','Work-order total vs labour+parts',p_country,e,a,d,'SAR', case when abs(coalesce(d,0))<0.01 then 'balanced' else 'variance' end, 0,'/work-orders',v_run);

  -- 2) Tyre asset link (orphans)
  select count(distinct upper(btrim(asset_no))) into e from public.tyre_records where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and asset_no is not null and btrim(asset_no)<>'';
  select count(distinct upper(btrim(t.asset_no))) into a from public.tyre_records t where t.organisation_id=v_org and (p_country is null or t.country=p_country) and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[]))) and t.asset_no is not null and btrim(t.asset_no)<>''
    and exists (select 1 from public.vehicle_fleet f where f.organisation_id=v_org and upper(btrim(f.asset_no))=upper(btrim(t.asset_no)));
  d := coalesce(e,0)-coalesce(a,0);
  insert into public.reconciliation_runs(organisation_id,recon_key,label,country,expected_value,actual_value,difference,unit,status,affected_count,drilldown,run_at)
  values (v_org,'fleet_asset_link','Tyre assets present in the fleet register',p_country,e,a,d,'assets', case when coalesce(d,0)=0 then 'balanced' else 'variance' end, coalesce(d,0)::int,'/data-reconciliation',v_run);

  -- 3) Production supplied vs approved m3
  begin
    select coalesce(sum(supplied_m3),0), coalesce(sum(approved_m3),0) into e, a from public.production_logs where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])));
    d := coalesce(e,0)-coalesce(a,0);
    insert into public.reconciliation_runs(organisation_id,recon_key,label,country,expected_value,actual_value,difference,unit,status,affected_count,drilldown,run_at)
    values (v_org,'production_supplied_vs_approved','Supplied vs approved production',p_country,e,a,d,'m3', case when abs(coalesce(d,0))<0.01 then 'balanced' else 'variance' end, 0,'/production-m3',v_run);
  exception when others then null; end;

  return json_build_object('ok',true,'run_at',v_run,
    'runs',(select json_agg(row_to_json(x)) from (
      select recon_key,label,expected_value,actual_value,difference,unit,status,drilldown from public.reconciliation_runs where organisation_id=v_org and run_at=v_run) x));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.save_access_control_matrix(p_view_changes jsonb DEFAULT '[]'::jsonb, p_capability_envelope text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_role text; v_super boolean := false;
  v_item jsonb; v_target_role text; v_module text; v_enabled boolean;
  v_count integer := 0; v_old text; v_envelope jsonb;
begin
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if v_uid is null or public.app_current_org() is null or not coalesce(public.app_is_active(),false) then raise exception 'Active organisation membership required.' using errcode = '42501'; end if;
  select role, coalesce(is_super_admin, false) into v_role, v_super
    from public.profiles where id = v_uid
      and coalesce(approved, true) = true and coalesce(locked, false) = false;
  if v_super is not true then raise exception 'Only a Super Admin can change access control.' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_view_changes, '[]'::jsonb)) <> 'array' then
    raise exception 'p_view_changes must be a JSON array.' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(coalesce(p_view_changes, '[]'::jsonb)) loop
    v_target_role := nullif(btrim(v_item ->> 'role'), '');
    v_module := nullif(btrim(v_item ->> 'module_key'), '');
    if v_target_role is null or v_module is null or length(v_target_role) > 100
       or length(v_module) > 160 or not (v_item ? 'enabled')
       or jsonb_typeof(v_item -> 'enabled') <> 'boolean' then
      raise exception 'Invalid role permission change.' using errcode = '22023';
    end if;
    v_enabled := (v_item ->> 'enabled')::boolean;
    if v_target_role = 'Admin' then v_enabled := true; end if;
    update public.module_permissions set enabled = v_enabled, updated_by = v_uid, updated_at = now()
      where org_id is null and role = v_target_role and module_key = v_module;
    if not found then
      insert into public.module_permissions(module_key, role, org_id, enabled, updated_by, updated_at)
      values (v_module, v_target_role, null, v_enabled, v_uid, now());
    end if;
    v_count := v_count + 1;
  end loop;

  if p_capability_envelope is not null then
    begin v_envelope := p_capability_envelope::jsonb;
    exception when others then raise exception 'Capability settings must be valid JSON.' using errcode = '22023'; end;
    if jsonb_typeof(v_envelope) <> 'object'
       or jsonb_typeof(coalesce(v_envelope -> 'overrides', '{}'::jsonb)) <> 'object' then
      raise exception 'Invalid capability settings envelope.' using errcode = '22023';
    end if;
    select settings->'app_settings'->>'permission_overrides' into v_old from public.organisations where id=public.app_current_org() for update;
    perform public.save_organisation_configuration('app_settings',jsonb_build_array(jsonb_build_object('key','permission_overrides','value',p_capability_envelope)));
    if v_old is distinct from p_capability_envelope then
      insert into public.access_audit(actor, actor_email, action, entity, before, after)
      values (v_uid, public.access_audit_actor_email(), 'UPDATE', 'capability_matrix',
        jsonb_build_object('value', case when v_old is null then null else v_old::jsonb end),
        jsonb_build_object('value', v_envelope, 'reason', nullif(btrim(p_reason), '')));
    end if;
  end if;
  return jsonb_build_object('view_changes', v_count, 'capabilities_saved', p_capability_envelope is not null);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.save_checklist_governance_policy(p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_role text := public.get_my_role();
  v jsonb := public.checklist_governance_defaults() || coalesce(p_policy, '{}'::jsonb);
  v_row public.checklist_governance_policies;
begin
  if auth.uid() is null or v_org is null then
    raise exception 'An authenticated organisation is required' using errcode = '42501';
  end if;
  if not public.is_super_admin() and v_role <> all(array[
    'Admin','Director','PMV Manager','Workshop Area Manager',
    'Workshop Maintenance Area Manager'
  ]) then
    raise exception 'Checklist governance requires an authorised manager' using errcode = '42501';
  end if;

  insert into public.checklist_governance_policies as p (
    organisation_id, industry_profile, timezone,
    pilot_enabled, pilot_country, pilot_site, pilot_start_date, pilot_end_date,
    supervisor_approval_sla_hours, area_manager_approval_sla_hours,
    corrective_critical_sla_hours, corrective_high_sla_hours,
    corrective_medium_sla_hours, corrective_low_sla_hours,
    evidence_enforcement, exception_note_required, exception_photo_required,
    completion_signature_required, gps_required,
    submission_retention_months, evidence_retention_months, audit_retention_months,
    retention_disposition, created_by, updated_by
  ) values (
    v_org, coalesce(nullif(btrim(v->>'industry_profile'),''),'general'), coalesce(nullif(btrim(v->>'timezone'),''),'UTC'),
    coalesce((v->>'pilot_enabled')::boolean,false), nullif(btrim(v->>'pilot_country'),''),
    nullif(btrim(v->>'pilot_site'),''), (v->>'pilot_start_date')::date,
    (v->>'pilot_end_date')::date,
    (v->>'supervisor_approval_sla_hours')::integer,
    (v->>'area_manager_approval_sla_hours')::integer,
    (v->>'corrective_critical_sla_hours')::integer,
    (v->>'corrective_high_sla_hours')::integer,
    (v->>'corrective_medium_sla_hours')::integer,
    (v->>'corrective_low_sla_hours')::integer,
    v->>'evidence_enforcement', (v->>'exception_note_required')::boolean,
    (v->>'exception_photo_required')::boolean,
    (v->>'completion_signature_required')::boolean, (v->>'gps_required')::boolean,
    (v->>'submission_retention_months')::integer,
    (v->>'evidence_retention_months')::integer,
    (v->>'audit_retention_months')::integer, v->>'retention_disposition',
    auth.uid(), auth.uid()
  )
  on conflict (organisation_id) do update set
    industry_profile=excluded.industry_profile, timezone=excluded.timezone,
    pilot_enabled=excluded.pilot_enabled, pilot_country=excluded.pilot_country,
    pilot_site=excluded.pilot_site, pilot_start_date=excluded.pilot_start_date,
    pilot_end_date=excluded.pilot_end_date,
    supervisor_approval_sla_hours=excluded.supervisor_approval_sla_hours,
    area_manager_approval_sla_hours=excluded.area_manager_approval_sla_hours,
    corrective_critical_sla_hours=excluded.corrective_critical_sla_hours,
    corrective_high_sla_hours=excluded.corrective_high_sla_hours,
    corrective_medium_sla_hours=excluded.corrective_medium_sla_hours,
    corrective_low_sla_hours=excluded.corrective_low_sla_hours,
    evidence_enforcement=excluded.evidence_enforcement,
    exception_note_required=excluded.exception_note_required,
    exception_photo_required=excluded.exception_photo_required,
    completion_signature_required=excluded.completion_signature_required,
    gps_required=excluded.gps_required,
    submission_retention_months=excluded.submission_retention_months,
    evidence_retention_months=excluded.evidence_retention_months,
    audit_retention_months=excluded.audit_retention_months,
    retention_disposition=excluded.retention_disposition,
    updated_by=auth.uid(), updated_at=now()
  returning p.* into v_row;
  return to_jsonb(v_row) - array['created_by','updated_by'];
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.save_organisation_configuration(p_namespace text, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid:=public.app_current_org(); v_role text:=public.get_my_role();
  v_before jsonb; v_after jsonb; v_patch jsonb; v_count int;
begin
  if auth.uid() is null or public.app_is_active() is not true or v_org is null then
    raise exception 'Active organisation membership required.' using errcode='42501';
  end if;
  if p_namespace is null or p_namespace not in ('settings','app_settings') or
     jsonb_typeof(p_values) is distinct from 'array' then
    raise exception 'Invalid configuration.' using errcode='22023';
  end if;
  v_count:=jsonb_array_length(p_values);
  if v_count<1 or v_count>100 or octet_length(p_values::text)>1048576 then
    raise exception 'Configuration size is invalid.' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_values) e where
    jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(e->'key') is distinct from 'string'
    or length(btrim(e->>'key'))=0 or length(e->>'key')>200
    or jsonb_typeof(e->'value') is distinct from 'string'
    or (e - 'key' - 'value') <> '{}'::jsonb) then
    raise exception 'Each configuration entry requires a key and string value.' using errcode='22023';
  end if;
  if (select count(distinct e->>'key') from jsonb_array_elements(p_values) e)<>v_count then
    raise exception 'Duplicate configuration keys.' using errcode='22023';
  end if;
  if public.is_super_admin() is not true and coalesce(v_role,'')<>'Admin' and not (
    coalesce(v_role,'') in ('Integration Admin','Automation') and p_namespace='app_settings'
    and not exists(select 1 from jsonb_array_elements(p_values) e where e->>'key'<>'erp_connection')
  ) then raise exception 'Administrator access required.' using errcode='42501'; end if;
  -- Browser endpoint configuration must never hold signing credentials.
  if p_namespace='app_settings' and exists (
    select 1 from jsonb_array_elements(p_values) e where e->>'key'='webhook_endpoints'
    and exists(select 1 from jsonb_array_elements((e->>'value')::jsonb) endpoint
      where nullif(endpoint->>'secret','') is not null)
  ) then raise exception 'Webhook signing credentials require server-managed storage.' using errcode='22023'; end if;
  select coalesce(o.settings,'{}'::jsonb) into v_before from public.organisations o where o.id=v_org for update;
  if not found then raise exception 'Organisation unavailable.' using errcode='42501'; end if;
  select jsonb_object_agg(e->>'key',e->'value') into v_patch from jsonb_array_elements(p_values) e;
  v_after:=jsonb_set(v_before,array[p_namespace],coalesce(v_before->p_namespace,'{}'::jsonb)||v_patch,true);
  if v_after is distinct from v_before then
    update public.organisations set settings=v_after,updated_at=now() where id=v_org;
    insert into public.audit_log(table_name,record_id,action,old_data,new_data,changed_by,organisation_id,details)
    values('organisations',v_org,'UPDATE',jsonb_build_object(p_namespace,v_before->p_namespace),
      jsonb_build_object(p_namespace,v_after->p_namespace),auth.uid(),v_org,
      jsonb_build_object('operation','tenant_configuration','namespace',p_namespace));
  end if;
  return jsonb_build_object('saved',v_count);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.save_stock_entry(p_request_id uuid, p_country text, p_site text, p_mode text, p_reference text, p_notes text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_org uuid:=app_current_org(); v_uid uuid:=auth.uid(); l jsonb; d jsonb; meta jsonb; r stock_records%ROWTYPE;
 req stock_entry_requests%ROWTYPE; fingerprint text; out jsonb:='[]'; seen text[]:='{}'; key text;
 qty numeric; before_qty integer; after_qty integer; change_qty integer; status text; movement uuid;
BEGIN
 IF v_uid IS NULL OR v_org IS NULL OR (is_approved_and_unlocked() IS NOT TRUE) OR (app_user_can('stock','view') IS NOT TRUE) THEN RAISE EXCEPTION 'Stock access is required.' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR nullif(btrim(p_country),'') IS NULL OR p_country='All' OR (app_write_country_ok(p_country) IS NOT TRUE)
 OR nullif(btrim(p_site),'') IS NULL OR NOT (coalesce(app_sees_all_sites(),false) OR upper(btrim(p_site))=ANY(coalesce(app_site_scope(),'{}'::text[]))) THEN RAISE EXCEPTION 'Choose a permitted country and site.' USING ERRCODE='42501'; END IF;
 IF p_mode NOT IN ('count','receipt') OR p_mode IS NULL OR jsonb_typeof(p_lines) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid entry.' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_lines) NOT BETWEEN 1 AND 100 OR length(coalesce(p_notes,''))>1000 OR length(coalesce(p_reference,''))>200
 OR (p_mode='receipt' AND nullif(btrim(p_reference),'') IS NULL) THEN RAISE EXCEPTION 'Check item count and receipt reference.' USING ERRCODE='22023'; END IF;
 fingerprint:=md5(jsonb_build_array(p_country,btrim(p_site),p_mode,p_reference,p_notes,p_lines)::text);
 INSERT INTO stock_entry_requests(id,organisation_id,country,site,created_by,payload_hash) VALUES(p_request_id,v_org,p_country,btrim(p_site),v_uid,fingerprint) ON CONFLICT DO NOTHING;
 SELECT * INTO req FROM stock_entry_requests WHERE id=p_request_id FOR UPDATE;
 IF req.organisation_id IS DISTINCT FROM v_org OR req.created_by IS DISTINCT FROM v_uid OR req.payload_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'This request identifier was already used. Review the entry again.' USING ERRCODE='23505'; END IF;
 IF req.result IS NOT NULL THEN RETURN req.result||jsonb_build_object('replayed',true); END IF;
 -- Serialise new-item identity creation in this store. Row locks and expected
 -- versions also protect against the older movement/count writers.
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text||p_country||upper(btrim(p_site)),0));
 FOR l IN SELECT value FROM jsonb_array_elements(p_lines) ORDER BY coalesce(value->>'stock_id',value->>'source_id',value->>'name') LOOP
  IF coalesce(l->>'quantity','') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'Enter a whole quantity.' USING ERRCODE='22023'; END IF;
  qty:=(l->>'quantity')::numeric;
  IF qty>2147483647 OR (p_mode='receipt' AND qty=0) THEN RAISE EXCEPTION 'Quantity is outside the allowed range.' USING ERRCODE='22023'; END IF;
  IF l->>'unit' IS NULL OR l->>'unit' NOT IN ('PCS','SET','PAIR','BOX','KG','L') THEN RAISE EXCEPTION 'Confirm the unit of measure.' USING ERRCODE='22023'; END IF;
  r:=NULL;
  IF nullif(l->>'stock_id','') IS NOT NULL THEN
   IF (app_user_can('stock','edit') IS NOT TRUE) THEN RAISE EXCEPTION 'Stock edit permission is required.' USING ERRCODE='42501'; END IF;
   SELECT * INTO r FROM stock_records WHERE id=(l->>'stock_id')::uuid FOR UPDATE;
   IF r.id IS NULL OR r.organisation_id IS DISTINCT FROM v_org OR r.country IS DISTINCT FROM p_country OR upper(btrim(r.site)) IS DISTINCT FROM upper(btrim(p_site)) THEN RAISE EXCEPTION 'Stock item is outside this store.' USING ERRCODE='42501'; END IF;
   IF (l->>'expected_qty')::integer IS DISTINCT FROM r.stock_qty OR (l->>'expected_updated_at')::timestamptz IS DISTINCT FROM r.updated_at THEN RAISE EXCEPTION 'Stock changed while you were counting. Refresh and review the latest balance.' USING ERRCODE='PT409'; END IF;
   meta:=coalesce(r.custom_data->'stock_item','{}');
   IF nullif(meta->>'unit','') IS NOT NULL AND meta->>'unit'<>l->>'unit' THEN RAISE EXCEPTION 'The recorded unit cannot be changed during a count.' USING ERRCODE='22023'; END IF;
   key:='stock:'||r.id;
  ELSE
   IF (app_user_can('stock','create') IS NOT TRUE) THEN RAISE EXCEPTION 'Stock create permission is required.' USING ERRCODE='42501'; END IF;
   IF l->>'source'='manual' THEN
    IF l->>'kind' IS NULL OR l->>'kind' NOT IN ('tyre','rim','accessory') OR nullif(btrim(l->>'name'),'') IS NULL OR l->>'name' ~* '\m(filter|lubricant|coolant|engine oil|hydraulic oil|labour|labor|service|fitting charge)\M' OR length(l->>'name')>500 OR length(coalesce(l->>'code',''))>100 THEN RAISE EXCEPTION 'Check the manual item details.' USING ERRCODE='22023'; END IF;
    d:=l||jsonb_build_object('key',CASE WHEN nullif(btrim(l->>'code'),'') IS NOT NULL THEN 'code:'||upper(btrim(l->>'code')) ELSE 'manual:'||md5(upper(jsonb_build_array(btrim(l->>'name'),l->>'brand',l->>'size',l->>'kind')::text)) END);
   ELSE d:=stock_entry_resolve(l->>'source',l->>'source_id',p_country,p_site);
   END IF;
   IF d IS NULL THEN RAISE EXCEPTION 'This MIS/DTR item is unavailable in your scope. Search again.' USING ERRCODE='42501'; END IF;
   IF coalesce(l->>'condition','') NOT IN ('New','Serviceable','Retread','Unspecified') OR length(coalesce(l->>'bin',''))>80 THEN RAISE EXCEPTION 'Check condition and bin.' USING ERRCODE='22023'; END IF;
   key:=(d->>'key')||'|'||coalesce(l->>'condition','Unspecified')||'|'||upper(btrim(coalesce(l->>'bin','')));
   IF EXISTS(SELECT 1 FROM stock_records s WHERE s.organisation_id=v_org AND s.country=p_country AND upper(btrim(s.site))=upper(btrim(p_site)) AND
    (s.custom_data->'stock_item'->>'key'=key OR (s.custom_data->'stock_item' IS NULL AND lower(btrim(s.description))=lower(btrim(d->>'name'))))) THEN
    RAISE EXCEPTION 'This item already has a stock record. Select it from Existing stock and review its balance.' USING ERRCODE='23505'; END IF;
   meta:=jsonb_build_object('key',key,'code',d->>'code','kind',d->>'kind','unit',l->>'unit','condition',l->>'condition','bin',btrim(coalesce(l->>'bin','')),'source',d);
   INSERT INTO stock_records(organisation_id,country,region,site,description,brand,tyre_size,stock_qty,min_level,critical_level,custom_data,updated_by)
    VALUES(v_org,p_country,p_country,btrim(p_site),d->>'name',coalesce(d->>'brand',l->>'brand'),coalesce(d->>'size',l->>'size'),0,0,0,jsonb_build_object('stock_item',meta),v_uid) RETURNING * INTO r;
  END IF;
  IF key=ANY(seen) THEN RAISE EXCEPTION 'Duplicate item in this batch.' USING ERRCODE='23505'; END IF;
  seen:=array_append(seen,key);
  IF EXISTS(SELECT 1 FROM workflow_instances w WHERE w.organisation_id=v_org AND w.entity_type='stock_issue' AND w.entity_id=r.id::text AND w.status IN ('pending','in_review','returned','approved')) THEN
   RAISE EXCEPTION 'An approval workflow protects this stock record.' USING ERRCODE='PT423'; END IF;
  before_qty:=coalesce(r.stock_qty,0); after_qty:=CASE WHEN p_mode='count' THEN qty::integer ELSE before_qty+qty::integer END;
  change_qty:=after_qty-before_qty;
  status:=CASE WHEN after_qty<=coalesce(r.critical_level,0) THEN 'Critical' WHEN after_qty<=coalesce(r.min_level,0) THEN 'Low' ELSE 'OK' END;
  INSERT INTO stock_movements(stock_id,site,description,movement_type,qty_before,qty_change,qty_after,reason,reference_no,created_by,organisation_id)
   VALUES(r.id,r.site,r.description,CASE WHEN p_mode='count' THEN 'stocktake' ELSE 'receipt' END,before_qty,change_qty,after_qty,
    concat_ws(': ',CASE WHEN p_mode='count' THEN 'Physical stock count' ELSE 'Stock receipt' END,nullif(btrim(p_notes),'')),coalesce(nullif(btrim(p_reference),''),'COUNT-'||p_request_id::text),v_uid,v_org) RETURNING id INTO movement;
  UPDATE stock_records SET stock_qty=after_qty,stock_status=status,custom_data=jsonb_set(coalesce(custom_data,'{}'),'{stock_item}',meta||jsonb_build_object('unit',l->>'unit')),
   updated_by=v_uid,updated_at=clock_timestamp(),last_counted_at=CASE WHEN p_mode='count' THEN clock_timestamp() ELSE last_counted_at END WHERE id=r.id;
  PERFORM record_audit_event('stock_quick_entry','stock_records',r.id::text,jsonb_build_object('qty_before',before_qty),jsonb_build_object('request_id',p_request_id,'movement_id',movement,'mode',p_mode,'qty_after',after_qty,'source',meta->'source'));
  out:=out||jsonb_build_array(jsonb_build_object('stock_id',r.id,'movement_id',movement,'qty_before',before_qty,'qty_after',after_qty,'qty_change',change_qty));
 END LOOP;
 UPDATE stock_entry_requests SET result=jsonb_build_object('status','posted','request_id',p_request_id,'items',out) WHERE id=p_request_id RETURNING result INTO d;
 RETURN d;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.save_vehicle_meter_readings(p_vehicle_id uuid, p_reading_date date, p_km numeric, p_hours numeric, p_request_id uuid, p_expected_km numeric, p_expected_hours numeric, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.vehicle_fleet%ROWTYPE;
  o public.odometer_logs%ROWTYPE;
  h public.engine_hours_logs%ROWTYPE;
  last_km numeric; last_hours numeric;
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR
     NOT coalesce((public.vehicle_meter_permissions()->>'canSave')::boolean,false) THEN
    RAISE EXCEPTION 'Not permitted' USING ERRCODE = '42501';
  END IF;
  IF p_request_id IS NULL OR p_reading_date IS NULL OR p_reading_date > current_date + 1
     OR (p_km IS NULL AND p_hours IS NULL)
     OR p_km < 0 OR p_hours < 0
     OR p_km::text IN ('NaN','Infinity','-Infinity')
     OR p_hours::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'Invalid meter reading' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v FROM public.vehicle_fleet
    WHERE id = p_vehicle_id AND organisation_id = public.app_current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle unavailable' USING ERRCODE = '42501'; END IF;
  PERFORM private.refresh_web_meter_vehicle(p_vehicle_id);
  SELECT * INTO v FROM public.vehicle_fleet WHERE id=p_vehicle_id;
  IF p_reading_date > (now() AT TIME ZONE CASE WHEN v.country='UAE' THEN 'Asia/Dubai' WHEN v.country='Egypt' THEN 'Africa/Cairo' ELSE 'Asia/Riyadh' END)::date THEN
    RAISE EXCEPTION 'Future reading date' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(*) FROM public.vehicle_fleet WHERE organisation_id = v.organisation_id
      AND asset_no = v.asset_no AND country IS NOT DISTINCT FROM v.country) <> 1 THEN
    RAISE EXCEPTION 'Ambiguous vehicle identity' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO o FROM public.odometer_logs WHERE client_uuid = 'web_' || p_request_id || '_km';
  SELECT * INTO h FROM public.engine_hours_logs WHERE client_uuid = 'web_' || p_request_id || '_hours';
  IF o.id IS NOT NULL OR h.id IS NOT NULL THEN
    IF (p_km IS NOT NULL AND (o.id IS NULL OR o.odometer_km IS DISTINCT FROM p_km OR o.reading_date IS DISTINCT FROM p_reading_date
        OR o.asset_no IS DISTINCT FROM v.asset_no OR o.organisation_id IS DISTINCT FROM v.organisation_id OR o.country IS DISTINCT FROM v.country))
      OR (p_hours IS NOT NULL AND (h.id IS NULL OR h.engine_hours IS DISTINCT FROM p_hours OR h.reading_date IS DISTINCT FROM p_reading_date
        OR h.asset_no IS DISTINCT FROM v.asset_no OR h.organisation_id IS DISTINCT FROM v.organisation_id OR h.country IS DISTINCT FROM v.country))
      OR (p_km IS NULL AND o.id IS NOT NULL) OR (p_hours IS NULL AND h.id IS NOT NULL) THEN
      RAISE EXCEPTION 'Request already used' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object('odometer',to_jsonb(o),'hours',to_jsonb(h),'vehicle',jsonb_build_object('id',v.id,'current_km',v.current_km,'current_engine_hours',v.current_engine_hours,'updated_at',v.updated_at));
  END IF;

  SELECT odometer_km INTO last_km FROM public.odometer_logs WHERE asset_no=v.asset_no
    AND organisation_id=v.organisation_id AND country IS NOT DISTINCT FROM v.country
    ORDER BY reading_date DESC NULLS LAST, created_at DESC,id DESC LIMIT 1;
  last_km := greatest(v.current_km,last_km);
  SELECT engine_hours INTO last_hours FROM public.engine_hours_logs WHERE asset_no=v.asset_no
    AND organisation_id=v.organisation_id AND country IS NOT DISTINCT FROM v.country
    ORDER BY reading_date DESC NULLS LAST,created_at DESC,id DESC LIMIT 1;
  last_hours := greatest(last_hours,v.current_engine_hours,v.current_hours);
  IF (p_km IS NOT NULL AND p_expected_km IS DISTINCT FROM last_km)
    OR (p_hours IS NOT NULL AND p_expected_hours IS DISTINCT FROM last_hours) THEN
    RAISE EXCEPTION 'Meter changed; refresh before saving' USING ERRCODE = 'PT409';
  END IF;

  IF p_km IS NOT NULL THEN
    INSERT INTO public.odometer_logs(asset_no,organisation_id,country,site,reading_date,odometer_km,source,notes,created_by,client_uuid)
      VALUES(v.asset_no,v.organisation_id,v.country,v.site,p_reading_date,p_km,'Web Manual',left(p_notes,4000),auth.uid(),'web_'||p_request_id||'_km') RETURNING * INTO o;
    -- Set the web review flag from this tenant/country's locked baseline,
    -- rather than the legacy trigger's broader historical lookup.
    UPDATE public.odometer_logs SET flagged=coalesce(p_km<last_km,false),
      flagged_prev_reading=CASE WHEN p_km<last_km THEN last_km ELSE NULL END,
      flag_reason=CASE WHEN p_km<last_km THEN format('Reading %s km is below last %s km. Awaiting Admin review.',p_km,last_km) ELSE NULL END,
      reviewed=false,reviewed_by=NULL,reviewed_at=NULL
      WHERE id=o.id RETURNING * INTO o;
    INSERT INTO public.audit_log(table_name,record_id,action,new_data,changed_by,organisation_id,details)
      VALUES('odometer_logs',o.id,'INSERT',to_jsonb(o),auth.uid(),v.organisation_id,jsonb_build_object('channel','Web Manual'));
  END IF;
  IF p_hours IS NOT NULL THEN
    INSERT INTO public.engine_hours_logs(asset_no,organisation_id,country,site,reading_date,engine_hours,source,notes,created_by,client_uuid)
      VALUES(v.asset_no,v.organisation_id,v.country,v.site,p_reading_date,p_hours,'Web Manual',left(p_notes,4000),auth.uid(),'web_'||p_request_id||'_hours') RETURNING * INTO h;
    -- Set the web review flag from this tenant/country's locked baseline,
    -- rather than the legacy trigger's broader historical lookup.
    UPDATE public.engine_hours_logs SET flagged=coalesce(p_hours<last_hours,false),
      flagged_prev_reading=CASE WHEN p_hours<last_hours THEN last_hours ELSE NULL END,
      flag_reason=CASE WHEN p_hours<last_hours THEN format('Reading %s hours is below last %s hours. Awaiting Admin review.',p_hours,last_hours) ELSE NULL END,
      reviewed=false,reviewed_by=NULL,reviewed_at=NULL
      WHERE id=h.id RETURNING * INTO h;
    PERFORM private.refresh_web_meter_vehicle(v.id);
    INSERT INTO public.audit_log(table_name,record_id,action,new_data,changed_by,organisation_id,details)
      VALUES('engine_hours_logs',h.id,'INSERT',to_jsonb(h),auth.uid(),v.organisation_id,jsonb_build_object('channel','Web Manual'));
  END IF;
  SELECT * INTO v FROM public.vehicle_fleet WHERE id=p_vehicle_id;
  RETURN jsonb_build_object('odometer',to_jsonb(o),'hours',to_jsonb(h),'vehicle',jsonb_build_object('id',v.id,'current_km',v.current_km,'current_engine_hours',v.current_engine_hours,'updated_at',v.updated_at));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.scan_data_trust(p_country text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_q json; v_run uuid; v_new int := 0; v_max timestamptz;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if v_org is null then raise exception 'no organisation context'; end if;

  v_q := public.run_quality_checks(p_country);
  v_run := (v_q->>'run_id')::uuid;
  insert into public.trust_alerts (organisation_id, source, ref_key, severity, country, message)
  select v_org, 'quality', qr.rule_key, qr.severity, qr.country, qr.message
  from public.quality_results qr
  where qr.run_id = v_run and qr.status = 'fail'
    and (qr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(qr.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
    and not exists (select 1 from public.trust_alerts a where a.organisation_id=v_org and a.source='quality' and a.ref_key=qr.rule_key and a.status='open');
  get diagnostics v_new = row_count;

  perform public.run_reconciliation(p_country);
  select max(run_at) into v_max from public.reconciliation_runs where organisation_id=v_org;
  insert into public.trust_alerts (organisation_id, source, ref_key, severity, country, message)
  select v_org, 'reconciliation', rr.recon_key, 'warning', rr.country,
         format('%s variance: expected %s, actual %s (diff %s %s)', rr.label, rr.expected_value, rr.actual_value, rr.difference, rr.unit)
  from public.reconciliation_runs rr
  where rr.organisation_id=v_org and rr.run_at = v_max and rr.status='variance'
    and (rr.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(rr.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
    and not exists (select 1 from public.trust_alerts a where a.organisation_id=v_org and a.source='reconciliation' and a.ref_key=rr.recon_key and a.status='open');

  return json_build_object('ok',true,'new_quality_alerts',v_new,
    'open_alerts',(select count(*) from public.trust_alerts where organisation_id=v_org and status='open'));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.scan_due_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_people integer := 0;
  v_items integer := 0;
  n integer;
begin
  for r in select * from due_alert_rules where enabled and cardinality(recipient_roles) > 0 loop
    with items as (
      select * from _due_items(r.rule_key, r.lead_days, r.lookback_days)
    ),
    pairs as (
      select i.entity_key, i.label, i.stage, p.id as uid
        from items i
        join profiles p
          on p.approved and not coalesce(p.locked, false)
         and p.role = any (r.recipient_roles)
         and (i.org is null or p.org_id = i.org or p.organisation_id = i.org)
         and (p.is_super_admin or p.role = 'Admin'
              or i.country is null
              or exists (select 1 from unnest(coalesce(p.country, '{}')) c
                          where lower(btrim(c)) in ('all', lower(btrim(i.country)))))
         and (p.is_super_admin or p.role = 'Admin'
              or i.site is null or btrim(i.site) = ''
              or exists (select 1 from unnest(coalesce(p.sites, '{}')) s
                          where upper(btrim(s)) in ('ALL', '*', upper(btrim(i.site)))))
       where not exists (select 1 from due_alert_notices x
                          where x.rule_key = r.rule_key and x.entity_key = i.entity_key
                            and x.stage = i.stage and x.user_id = p.id)
    ),
    logged as (
      insert into due_alert_notices (rule_key, entity_key, stage, user_id)
      select r.rule_key, entity_key, stage, uid from pairs
      on conflict do nothing
      returning 1
    ),
    agg as (
      select uid, stage,
             r.label || case when stage like 'overdue%' then ' overdue'
                             when stage like 'critical%' then ' critical'
                             when stage like 'low%' then ' running low'
                             when stage like 'missing%' then ' not recorded'
                             else ' due soon' end
               || ' (' || count(*) || ')' as title,
             (array_to_string((array_agg(label order by label))[1:5], ', ')
               || case when count(*) > 5 then ' and ' || (count(*) - 5) || ' more' else '' end) as body
        from pairs
       group by uid, stage
    ),
    sent as (
      insert into notifications (user_id, type, title, body, entity_type)
      select uid, 'due_' || r.rule_key, title, body, r.rule_key from agg
      returning 1
    ),
    tokens as (
      select a.uid, a.title, a.body, t.recips,
             (select coalesce(p.org_id, p.organisation_id) from profiles p where p.id = a.uid) as org
        from agg a
        cross join lateral (
          select coalesce(jsonb_agg(jsonb_build_object('user_id', a.uid, 'push_token', k.tok)), '[]'::jsonb) as recips
            from public._user_push_tokens(a.uid) k(tok)
        ) t
       where jsonb_array_length(t.recips) > 0
    ),
    ev as (
      insert into domain_events (event_type, entity_type, entity_id, organisation_id, payload, status, processed_at)
      select 'due.alert', r.rule_key, tk.uid::text, tk.org,
             jsonb_build_object('event_type', 'due.alert', 'entity_type', r.rule_key,
               'push', jsonb_build_object('title', tk.title, 'body', tk.body),
               'recipients', tk.recips),
             'processed', clock_timestamp()
        from tokens tk
      returning id, organisation_id, payload
    ),
    pushed as (
      insert into workflow_notifications (event_id, organisation_id, event_type, payload, recipient_count, status)
      select e.id, e.organisation_id, 'due.alert', e.payload, jsonb_array_length(e.payload->'recipients'), 'pending'
        from ev e
      returning 1
    )
    select (select count(*) from sent), (select count(*) from logged) into n, v_items;
    v_people := v_people + coalesce(n, 0);
  end loop;
  return jsonb_build_object('notifications', v_people);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.scrap_tyre_by_serial(p_serial text, p_reason text DEFAULT NULL::text, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_s   text := upper(btrim(coalesce(p_serial, '')));
  v_prior jsonb; v_n int; v_tot int; v_ok int; v_ctry text;
begin
  if p_country is not null and not public.app_write_country_ok(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_s = '' then
    raise exception 'Serial number is required' using errcode = '22023';
  end if;
  if v_org is null or not public.tyre_scrap_allowed() then
    raise exception 'You do not have permission to scrap a tyre' using errcode = '42501';
  end if;

  select count(*),
         count(*) filter (where t.country is null or public.app_write_country_ok(t.country)),
         min(t.country) filter (where t.country is not null)
    into v_tot, v_ok, v_ctry
    from public.tyre_records t
   where upper(btrim(t.serial_no)) = v_s and t.organisation_id = v_org;

  if v_tot = 0 then
    return jsonb_build_object('ok', false, 'reason', 'not_found', 'serial', v_s); end if;
  if v_ok = 0 then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;

  select coalesce(jsonb_object_agg(t.id::text, coalesce(t.status, 'Active')), '{}'::jsonb)
    into v_prior
    from public.tyre_records t
   where upper(btrim(t.serial_no)) = v_s
     and t.organisation_id = v_org
     and coalesce(t.status, '') <> 'Scrapped'
     and (t.country is null or public.app_write_country_ok(t.country));

  insert into public.tyre_status_marks
    (serial, mark_type, reason, country, created_by, created_at, organisation_id, prior_status)
  values (v_s, 'scrap', nullif(btrim(coalesce(p_reason, '')), ''),
          coalesce(v_ctry, nullif(btrim(coalesce(p_country, '')), '')), auth.uid(), now(), v_org, v_prior)
  on conflict (serial, mark_type) do update
    set reason     = excluded.reason,
        created_by = excluded.created_by,
        created_at = excluded.created_at,
        country    = coalesce(excluded.country, tyre_status_marks.country),
        prior_status = case
          when tyre_status_marks.prior_status is null
            or tyre_status_marks.prior_status = '{}'::jsonb
          then excluded.prior_status
          else tyre_status_marks.prior_status end;

  update public.tyre_records
     set status = 'Scrapped'
   where upper(btrim(serial_no)) = v_s
     and organisation_id = v_org and (country is null or public.app_write_country_ok(country));
  get diagnostics v_n = row_count;

  perform public._log_scrap_action('tyre_scrap', v_s, v_prior,
    jsonb_build_object('reason', nullif(btrim(coalesce(p_reason, '')), ''), 'rows', v_n),
    nullif(btrim(coalesce(p_country, '')), ''));

  if v_n = 0 then
    return jsonb_build_object('ok', false, 'reason', 'forbidden', 'serial', v_s, 'updated', 0); end if;
  return jsonb_build_object('ok', true, 'serial', v_s, 'updated', v_n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.search_fleet_assets(p_query text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_site text DEFAULT NULL::text, p_limit integer DEFAULT 40, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_limit  int := least(greatest(coalesce(p_limit, 40), 1), 200);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_q      text := nullif(btrim(coalesce(p_query, '')), '');
  -- escape the LIKE wildcards so a stray % does not match the whole fleet
  v_like   text;
  v_total  bigint;
  v_rows   jsonb;
begin
  v_like := case when v_q is null then null
                 else '%' || replace(replace(replace(lower(v_q), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;

  with matched as (
    select f.*
      from public.vehicle_fleet f
     where (p_country is null or p_country = 'All' or f.country = p_country or f.country is null)
       and (p_site is null or f.site = p_site)
       and (
         v_like is null
         or lower(coalesce(f.asset_no, ''))        like v_like escape '\'
         or lower(coalesce(f.fleet_number, ''))    like v_like escape '\'
         or lower(coalesce(f.make, ''))            like v_like escape '\'
         or lower(coalesce(f.model, ''))           like v_like escape '\'
         or lower(coalesce(f.vehicle_type, ''))    like v_like escape '\'
         or lower(coalesce(f.registration_no, '')) like v_like escape '\'
         or lower(coalesce(f.operator_name, ''))   like v_like escape '\'
         or lower(coalesce(f.site, ''))            like v_like escape '\'
       )
  )
  select count(*) into v_total from matched;

  with matched as (
    select f.*
      from public.vehicle_fleet f
     where (p_country is null or p_country = 'All' or f.country = p_country or f.country is null)
       and (p_site is null or f.site = p_site)
       and (
         v_like is null
         or lower(coalesce(f.asset_no, ''))        like v_like escape '\'
         or lower(coalesce(f.fleet_number, ''))    like v_like escape '\'
         or lower(coalesce(f.make, ''))            like v_like escape '\'
         or lower(coalesce(f.model, ''))           like v_like escape '\'
         or lower(coalesce(f.vehicle_type, ''))    like v_like escape '\'
         or lower(coalesce(f.registration_no, '')) like v_like escape '\'
         or lower(coalesce(f.operator_name, ''))   like v_like escape '\'
         or lower(coalesce(f.site, ''))            like v_like escape '\'
       )
     -- asset_no is unique per (org, country) but NOT globally, so id breaks the
     -- tie: ordering a paged read on a non-unique key drops or repeats rows at
     -- a page boundary.
     order by f.asset_no, f.id
     limit v_limit offset v_offset
  )
  select coalesce(jsonb_agg(to_jsonb(m) - 'organisation_id' - 'created_by' - 'asset_extra'), '[]'::jsonb)
    into v_rows from matched m;

  return jsonb_build_object(
    'ok', true,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows,
    -- the caller does not have to work out whether another page exists
    'has_more', (v_offset + v_limit) < v_total);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.secure_import_batch_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_file_org uuid; v_file_country text;
begin
  if auth.uid() is null or not public.app_is_active() or v_org is null then
    raise exception 'Active organisation membership required.' using errcode = '42501';
  end if;
  if not public.import_user_can_commit_country(new.country) then
    raise exception 'Country scope denied.' using errcode = '42501';
  end if;
  if new.file_id is not null then
    select organisation_id, country into v_file_org, v_file_country
      from public.import_files where id = new.file_id;
    if not found or v_file_org is distinct from v_org
       or v_file_country is distinct from new.country then
      raise exception 'The source file and batch must share organisation and country.' using errcode = '23514';
    end if;
  end if;
  new.organisation_id := v_org;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid(); new.uploader := auth.uid();
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.secure_import_file_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org();
begin
  if auth.uid() is null or not public.app_is_active() or v_org is null then
    raise exception 'Active organisation membership required.' using errcode = '42501';
  end if;
  new.organisation_id := v_org;
  new.created_by := auth.uid();
  if new.storage_path is null
     or split_part(new.storage_path, '/', 1) <> v_org::text then
    raise exception 'Storage path must belong to the current organisation.' using errcode = '42501';
  end if;
  if not public.import_user_can_commit_country(new.country) then
    raise exception 'Country scope denied.' using errcode = '42501';
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.sentry_alert_to_incident()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_on     text;
  v_level  text := lower(btrim(coalesce(new.level, 'fatal')));
  v_title  text := left(btrim(coalesce(nullif(btrim(new.title), ''), 'Fatal crash')), 160);
  v_ref    text := new.issue_id;
  v_label  text := coalesce(nullif(btrim(new.short_id), ''), new.issue_id);
  v_msg    text;
  v_inc    uuid;
  v_status text;
  v_new    boolean := false;
begin
  select lower(btrim(coalesce(value, 'true'))) into v_on from public.system_config where key = 'sentry_auto_incidents';
  if coalesce(v_on, 'true') not in ('true', '1', 'yes', 'on', '"true"') then
    return new;
  end if;
  if v_level not in ('fatal', '') then
    return new;
  end if;

  begin
    v_msg := left('Sentry reported a new fatal crash ' || v_label || ': ' || v_title
               || coalesce(' (' || new.permalink || ')', '') || '.', 4000);

    select id, status into v_inc, v_status
      from public.platform_incidents
     where source_type = 'sentry' and source_ref = v_ref and status <> 'resolved'
     order by started_at desc limit 1;

    if v_inc is null then
      select id, status into v_inc, v_status
        from public.platform_incidents
       where source_type = 'sentry' and status <> 'resolved'
         and started_at >= now() - interval '6 hours'
       order by started_at desc limit 1;
    end if;

    if v_inc is not null then
      insert into public.platform_incident_updates (incident_id, status, message, author)
      values (v_inc, v_status, v_msg, null);
    else
      insert into public.platform_incidents
        (title, severity, impact, affected_modules, started_at, source_type, source_ref, created_by)
      values
        (left('Fatal crash: ' || v_title, 200), 'sev2',
         'Opened automatically from Sentry. Check the crash report for the affected screens and devices.',
         '{}', coalesce(least(new.first_seen, now()), now()), 'sentry', v_ref, null)
      returning id into v_inc;
      v_new := true;

      insert into public.platform_incident_updates (incident_id, status, message, author)
      values (v_inc, 'investigating', v_msg, null);

      begin
        insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
        select p.id, 'security',
               'SEV2 incident opened: Fatal crash',
               'Sentry reported ' || v_label || ': ' || v_title || '. Opened automatically at '
                 || to_char(now() at time zone 'Asia/Riyadh', 'DD Mon YYYY HH24:MI') || ' (Riyadh).',
               'platform_incident', v_inc
          from public.profiles p
         where coalesce(p.is_super_admin, false) and not coalesce(p.locked, false);
      exception when others then null;
      end;
    end if;

    insert into public.console_sessions (admin_id, action, target_id, target_type, details)
    values (null, case when v_new then 'incident_open' else 'incident_update' end, v_inc, 'platform_incident',
            jsonb_build_object('actor', 'system:sentry', 'source_type', 'sentry', 'source_ref', v_ref,
                               'short_id', new.short_id, 'grouped', not v_new));
  exception when others then
    begin
      insert into public.system_logs (organisation_id, severity, source, module_id, message, detail)
      values (null, 'warning', 'sentry', 'incident_signal',
              'Could not open an incident for a Sentry crash',
              jsonb_build_object('issue_id', v_ref, 'sqlstate', sqlstate));
    exception when others then null;
    end;
  end;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_alert_state(p_keys text[], p_action text, p_owner uuid DEFAULT NULL::uuid, p_snooze_hours integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int := 0; v_state text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can change alerts' using errcode = '42501';
  end if;
  if p_action not in ('acknowledge','snooze','resolve','assign','reopen') then
    raise exception 'That alert action is not recognised' using errcode = '22023';
  end if;
  if p_action = 'resolve' and length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required to resolve alerts' using errcode = '22023';
  end if;
  if p_action = 'snooze' and (p_snooze_hours is null or p_snooze_hours < 1 or p_snooze_hours > 720) then
    raise exception 'Snooze for between 1 hour and 30 days' using errcode = '22023';
  end if;
  if p_keys is null or cardinality(p_keys) = 0 then return jsonb_build_object('ok', true, 'changed', 0); end if;
  if cardinality(p_keys) > 200 then raise exception 'Change at most 200 alerts at a time' using errcode = '22023'; end if;

  v_state := case p_action when 'acknowledge' then 'acknowledged' when 'snooze' then 'snoozed'
                           when 'resolve' then 'resolved' when 'reopen' then 'new' else null end;

  insert into public.alert_inbox_state as s (dedup_key, source, state, owner_id, snoozed_until, acknowledged_at,
                                             resolved_at, note, updated_at, updated_by)
  select k, split_part(k, '|', 1), coalesce(v_state, 'acknowledged'),
         case when p_action = 'assign' then p_owner end,
         case when p_action = 'snooze' then now() + make_interval(hours => p_snooze_hours) end,
         case when p_action in ('acknowledge','assign') then now() end,
         case when p_action = 'resolve' then now() end,
         nullif(left(btrim(coalesce(p_reason, '')), 500), ''), now(), auth.uid()
  from (select distinct k from unnest(p_keys) k where nullif(btrim(k), '') is not null) x
  on conflict (dedup_key) do update set
    state = coalesce(v_state, s.state),
    owner_id = case when p_action = 'assign' then p_owner else s.owner_id end,
    snoozed_until = case when p_action = 'snooze' then now() + make_interval(hours => p_snooze_hours)
                         when p_action in ('reopen','resolve') then null else s.snoozed_until end,
    acknowledged_at = case when p_action in ('acknowledge','assign') then coalesce(s.acknowledged_at, now())
                           when p_action = 'reopen' then null else s.acknowledged_at end,
    resolved_at = case when p_action = 'resolve' then now() when p_action = 'reopen' then null else s.resolved_at end,
    note = coalesce(nullif(left(btrim(coalesce(p_reason, '')), 500), ''), s.note),
    updated_at = now(), updated_by = auth.uid();
  get diagnostics v_n = row_count;

  perform public.log_console_event('alert_' || p_action, null, 'alert',
    jsonb_build_object('count', v_n, 'keys', to_jsonb(p_keys[1:20]), 'owner_id', p_owner,
                       'snooze_hours', p_snooze_hours, 'reason', p_reason));
  return jsonb_build_object('ok', true, 'changed', v_n, 'state', v_state);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_app_settings_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_error_group_state(p_key text, p_status text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_version text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_notify boolean DEFAULT NULL::boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old public.error_group_state;
  v_status text;
  v_notified int := 0;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;
  if not public.is_super_admin() then
    raise exception 'Only a super admin can triage errors' using errcode = '42501';
  end if;
  if nullif(btrim(p_key), '') is null then
    raise exception 'Choose an error group first' using errcode = '22023';
  end if;
  if p_status is not null and p_status not in ('for_review','reviewed','fixed_in_code','resolved','ignored','routine') then
    raise exception 'That status is not recognised' using errcode = '22023';
  end if;
  if p_status in ('resolved','ignored') and length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required to resolve or ignore an error group' using errcode = '22023';
  end if;

  select * into v_old from public.error_group_state where group_key = p_key;
  v_status := coalesce(p_status, v_old.status, 'for_review');
  if p_owner is not null and p_status is null and v_status = 'for_review' then v_status := 'reviewed'; end if;

  insert into public.error_group_state as s (group_key, status, owner_id, resolved_in_version, note, notify_when_fixed,
                                             resolved_at, updated_at, updated_by)
  values (p_key, v_status, p_owner, nullif(btrim(p_version), ''), nullif(btrim(p_note), ''), coalesce(p_notify, false),
          case when v_status = 'resolved' then now() end, now(), auth.uid())
  on conflict (group_key) do update set
    status = v_status,
    owner_id = coalesce(p_owner, s.owner_id),
    resolved_in_version = coalesce(nullif(btrim(p_version), ''), s.resolved_in_version),
    note = coalesce(nullif(btrim(p_note), ''), s.note),
    notify_when_fixed = coalesce(p_notify, s.notify_when_fixed),
    resolved_at = case when v_status = 'resolved' then now() when v_status in ('for_review','reviewed') then null else s.resolved_at end,
    updated_at = now(), updated_by = auth.uid();

  if v_status = 'resolved' and coalesce(p_notify, v_old.notify_when_fixed, false)
     and (v_old.notified_at is null) then
    insert into public.notifications (user_id, type, title, body, entity_type)
    select distinct l.user_id, 'system', 'A problem you hit has been fixed',
      'An error you ran into has been fixed' ||
        coalesce(' in version ' || nullif(btrim(coalesce(p_version, v_old.resolved_in_version)), ''), '') ||
        '. Reload the app to get the fix.',
      'error_group'
    from public.system_logs l
    where l.user_id is not null
      and public.system_log_group_key(l.source, l.message, l.error_fingerprint) = p_key;
    get diagnostics v_notified = row_count;
    update public.error_group_state set notified_at = now() where group_key = p_key;
  end if;

  perform public.log_console_event('error_group_state', null, 'error_group',
    jsonb_build_object('group_key', left(p_key, 300), 'from', v_old.status, 'to', v_status,
      'owner_id', p_owner, 'version', p_version, 'notify', p_notify, 'reason', p_reason, 'notified', v_notified));

  return jsonb_build_object('ok', true, 'status', v_status, 'notified', v_notified);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_inspection_schedules_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_module_permissions(p_changes jsonb, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := auth.uid();
  v_role text;
  v_super boolean;
  rec    jsonb;
  v_n    integer := 0;
  v_mod  text; v_r text; v_en boolean;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  SELECT role, coalesce(is_super_admin,false) INTO v_role, v_super FROM profiles WHERE id = v_uid;
  IF v_super IS NOT TRUE THEN RAISE EXCEPTION 'Only a Super Admin can change module access.' USING errcode = '42501';
  END IF;
  IF jsonb_typeof(p_changes) <> 'array' THEN
    RAISE EXCEPTION 'p_changes must be a JSON array of {role, module_key, enabled}.';
  END IF;

  FOR rec IN SELECT * FROM jsonb_array_elements(p_changes)
  LOOP
    v_r   := rec->>'role';
    v_mod := rec->>'module_key';
    v_en  := (rec->>'enabled')::boolean;
    IF v_r IS NULL OR v_mod IS NULL OR v_en IS NULL THEN CONTINUE; END IF;
    -- never let a non-Admin edit strip the Admin role's access
    IF v_r = 'Admin' THEN v_en := true; END IF;

    UPDATE module_permissions
      SET enabled = v_en, updated_by = v_uid, updated_at = now()
      WHERE org_id IS NULL AND role = v_r AND module_key = v_mod;
    IF NOT FOUND THEN
      INSERT INTO module_permissions (module_key, role, org_id, enabled, updated_by, updated_at)
      VALUES (v_mod, v_r, NULL, v_en, v_uid, now());
    END IF;
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_org_branding(p_org_id uuid, p_branding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org      uuid;
  v_old      jsonb;
  v_clean    jsonb;
  v_theme    text;
  v_logos    jsonb;
  v_logo_url text;
  v_merged   jsonb;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN
    RAISE EXCEPTION 'Account not approved or is locked';
  END IF;
  IF NOT public.app_is_org_admin() THEN
    RAISE EXCEPTION 'Only an organisation admin or super admin may edit branding';
  END IF;

  v_org := COALESCE(p_org_id, public.app_current_org());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'No target organisation';
  END IF;
  IF v_org IS DISTINCT FROM public.app_current_org() AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not authorised to edit branding for another organisation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organisations WHERE id = v_org) THEN
    RAISE EXCEPTION 'Organisation % does not exist', v_org;
  END IF;

  p_branding := COALESCE(p_branding, '{}'::jsonb);

  IF NOT public._is_hex_color(p_branding->>'primary_color')
     OR NOT public._is_hex_color(p_branding->>'secondary_color')
     OR NOT public._is_hex_color(p_branding->>'accent_color') THEN
    RAISE EXCEPTION 'Colours must be #RRGGBB hex values';
  END IF;

  v_theme := p_branding->>'report_theme';
  IF v_theme IS NOT NULL AND v_theme NOT IN ('light','dark') THEN
    RAISE EXCEPTION 'report_theme must be light or dark';
  END IF;

  SELECT settings->'branding' INTO v_old FROM public.organisations WHERE id = v_org;
  v_old := COALESCE(v_old, '{}'::jsonb);

  IF p_branding ? 'logos' THEN
    v_logos := public._clean_brand_logos(p_branding->'logos');
  ELSE
    v_logos := COALESCE(v_old->'logos', '{}'::jsonb);
  END IF;

  v_logo_url := NULLIF(btrim(p_branding->>'logo_url'), '');
  IF v_logo_url IS NULL AND (v_logos ? 'report_cover') THEN
    v_logo_url := CASE
      WHEN (v_logos->>'report_cover') ~ '^[a-z0-9-]{1,64}$'
        THEN '/brand/library/' || (v_logos->>'report_cover') || '.png'
      ELSE v_logos->>'report_cover'
    END;
  END IF;

  v_clean := jsonb_strip_nulls(jsonb_build_object(
    'legal_name',      NULLIF(trim(p_branding->>'legal_name'), ''),
    'display_name',    NULLIF(trim(p_branding->>'display_name'), ''),
    'primary_color',   p_branding->>'primary_color',
    'secondary_color', p_branding->>'secondary_color',
    'accent_color',    p_branding->>'accent_color',
    'logo_url',        v_logo_url,
    'report_theme',    v_theme,
    'footer_text',     NULLIF(trim(p_branding->>'footer_text'), ''),
    'disclaimer',      NULLIF(trim(p_branding->>'disclaimer'), ''),
    'address',         NULLIF(trim(p_branding->>'address'), ''),
    'contact_email',   NULLIF(trim(p_branding->>'contact_email'), ''),
    'contact_phone',   NULLIF(trim(p_branding->>'contact_phone'), ''),
    'website',         NULLIF(trim(p_branding->>'website'), '')
  ));

  v_merged := v_clean
              || jsonb_build_object('logos', v_logos)
              || jsonb_build_object('updated_at', now(), 'updated_by', auth.uid());

  UPDATE public.organisations
     SET settings      = jsonb_set(COALESCE(settings, '{}'::jsonb), '{branding}', v_merged, true),
         logo_url      = COALESCE(v_clean->>'logo_url', logo_url),
         contact_email = COALESCE(v_clean->>'contact_email', contact_email),
         updated_at    = now()
   WHERE id = v_org;

  BEGIN
    PERFORM public.record_audit_event(
      'org_branding_update', 'organisations', v_org::text,
      COALESCE(v_old, '{}'::jsonb), v_merged);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN v_merged;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_scrap_reason(p_serial text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_s   text := upper(btrim(coalesce(p_serial, '')));
  v_old text;
begin
  if v_s = '' then
    raise exception 'Serial number is required' using errcode = '22023';
  end if;
  if v_org is null or not public.tyre_scrap_allowed() then
    raise exception 'You do not have permission to edit a scrap reason' using errcode = '42501';
  end if;

  select reason into v_old from public.tyre_status_marks
   where upper(btrim(serial)) = v_s and mark_type = 'scrap' and organisation_id = v_org and (country is null or public.app_write_country_ok(country));

  update public.tyre_status_marks
     set reason = nullif(btrim(coalesce(p_reason, '')), '')
   where upper(btrim(serial)) = v_s and mark_type = 'scrap' and organisation_id = v_org and (country is null or public.app_write_country_ok(country));

  perform public._log_scrap_action('tyre_scrap_reason', v_s,
    jsonb_build_object('reason', v_old),
    jsonb_build_object('reason', nullif(btrim(coalesce(p_reason, '')), '')), null);

  return jsonb_build_object('ok', true, 'serial', v_s);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_sentry_config(p_token text DEFAULT NULL::text, p_org text DEFAULT NULL::text, p_region_url text DEFAULT NULL::text, p_project text DEFAULT NULL::text, p_alert_email text DEFAULT NULL::text, p_alerts_enabled boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_super boolean;
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  SELECT COALESCE(is_super_admin,false) INTO v_super FROM public.profiles WHERE id = auth.uid();
  IF v_super IS NOT TRUE THEN RAISE EXCEPTION 'Only a super admin can configure Sentry.' USING errcode='42501'; END IF;

  IF NULLIF(btrim(p_region_url), '') IS NOT NULL
     AND lower(btrim(p_region_url)) !~ '^https://([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)*sentry\.io/?$' THEN
    RAISE EXCEPTION 'The Sentry region address must be https://sentry.io or a sentry.io subdomain' USING errcode = '22023';
  END IF;

  IF p_token IS NOT NULL AND length(btrim(p_token)) > 0 THEN
    INSERT INTO public.cron_config(name,value) VALUES ('sentry_auth_token', btrim(p_token))
      ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  END IF;
  INSERT INTO public.cron_config(name,value) VALUES ('sentry_org', COALESCE(NULLIF(btrim(p_org),''),'shah-profile'))
    ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  INSERT INTO public.cron_config(name,value) VALUES ('sentry_region_url', COALESCE(NULLIF(btrim(p_region_url),''),'https://de.sentry.io'))
    ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  INSERT INTO public.cron_config(name,value) VALUES ('sentry_project', COALESCE(btrim(p_project),''))
    ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  IF p_alert_email IS NOT NULL THEN
    INSERT INTO public.cron_config(name,value) VALUES ('sentry_alert_email', btrim(p_alert_email))
      ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  END IF;
  IF p_alerts_enabled IS NOT NULL THEN
    INSERT INTO public.cron_config(name,value) VALUES ('sentry_alerts_enabled', CASE WHEN p_alerts_enabled THEN 'true' ELSE 'false' END)
      ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value;
  END IF;
  PERFORM public._console_audit('set_sentry_config', NULL, 'sentry', jsonb_build_object(
    'token_changed', (p_token IS NOT NULL AND length(btrim(p_token)) > 0),
    'org', COALESCE(NULLIF(btrim(p_org),''),'shah-profile'),
    'region_url', COALESCE(NULLIF(btrim(p_region_url),''),'https://de.sentry.io'),
    'project', COALESCE(btrim(p_project),''),
    'alert_email_changed', (p_alert_email IS NOT NULL),
    'alerts_enabled', p_alerts_enabled));
  RETURN jsonb_build_object('ok', true);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_stock_count(p_stock_id uuid, p_count numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := public.app_current_org();
  v_rec public.stock_records%ROWTYPE;
  v_before numeric; v_change numeric; v_after numeric; v_status text; v_mov_id uuid;
BEGIN
  IF NOT public.is_approved_and_unlocked() THEN
    RAISE EXCEPTION 'Not authorised.' USING errcode = '42501';
  END IF;
  IF p_stock_id IS NULL THEN
    RAISE EXCEPTION 'stock_id is required.' USING errcode = '22004';
  END IF;
  IF p_count IS NULL OR p_count < 0 THEN
    RAISE EXCEPTION 'Count must be zero or positive (got %).', p_count USING errcode = '22023';
  END IF;

  SELECT * INTO v_rec FROM public.stock_records WHERE id = p_stock_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stock record % not found.', p_stock_id USING errcode = 'P0002';
  END IF;
  IF v_rec.organisation_id IS NOT NULL AND v_rec.organisation_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'Cross-organisation stock update denied.' USING errcode = '42501';
  END IF;
  IF NOT public.app_write_country_ok(v_rec.country) THEN
    RAISE EXCEPTION 'Cross-country stock update denied.' USING errcode = '42501';
  END IF;

  v_before := COALESCE(v_rec.stock_qty, 0);
  v_after  := floor(p_count);
  v_change := v_after - v_before;

  v_status := CASE
    WHEN v_after <= COALESCE(v_rec.critical_level, 0) THEN 'Critical'
    WHEN v_after <= COALESCE(v_rec.min_level, 0)      THEN 'Low'
    ELSE 'OK' END;

  IF v_change <> 0 THEN
    INSERT INTO public.stock_movements
      (stock_id, site, description, movement_type, qty_before, qty_change, qty_after,
       reason, reference_no, created_by, organisation_id)
    VALUES
      (p_stock_id, v_rec.site, v_rec.description, 'stocktake', v_before, v_change, v_after,
       NULLIF(btrim(p_reason), ''), NULL, v_uid, COALESCE(v_rec.organisation_id, v_org))
    RETURNING id INTO v_mov_id;
  END IF;

  UPDATE public.stock_records
     SET stock_qty = v_after, stock_status = v_status, updated_by = v_uid, updated_at = now()
   WHERE id = p_stock_id;

  PERFORM public.record_audit_event('stock_count', 'stock_records', p_stock_id::text,
    jsonb_build_object('qty_before', v_before),
    jsonb_build_object('movement_type', 'stocktake', 'qty_change', v_change,
      'qty_after', v_after, 'stock_status', v_status, 'reason', NULLIF(btrim(p_reason), '')));

  RETURN jsonb_build_object('status', 'counted', 'movement_id', v_mov_id, 'stock_id', p_stock_id,
    'qty_before', v_before, 'qty_change', v_change, 'qty_after', v_after, 'stock_status', v_status);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_store_site_map(p_country text, p_store_code text, p_site text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.app_current_org();
BEGIN
  IF v_org IS NULL OR NOT public.app_is_elevated() THEN
    RAISE EXCEPTION 'Not authorized to edit the store to site map.';
  END IF;
  IF NULLIF(BTRIM(p_country), '') IS NULL THEN
    -- A NULL country is a WILDCARD: classify_parts_consumption resolves a site with
    -- (m.country IS NULL OR m.country = NEW.country), so such a row decides the site
    -- for EVERY country. Creating one is a write against all of them.
    IF NOT (public.is_super_admin() OR public.app_sees_all_countries()) THEN
      RAISE EXCEPTION 'A store mapping must name a country.'
        USING errcode = '42501';
    END IF;
  ELSIF public.app_write_country_ok(BTRIM(p_country)) IS FALSE THEN
    RAISE EXCEPTION 'You do not have permission to map a store in that country.'
      USING errcode = '42501';
  END IF;
  IF p_store_code IS NULL OR BTRIM(p_store_code) = '' THEN
    RAISE EXCEPTION 'A store code is required.';
  END IF;
  IF p_site IS NULL OR BTRIM(p_site) = '' THEN
    RAISE EXCEPTION 'A site is required.';
  END IF;

  INSERT INTO public.store_site_map (organisation_id, country, store_code, site, created_by)
  VALUES (v_org, NULLIF(BTRIM(p_country), ''), BTRIM(p_store_code), BTRIM(p_site), auth.uid())
  ON CONFLICT (organisation_id, country, store_code)
  DO UPDATE SET site = EXCLUDED.site, updated_at = now();
END; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_tyre_exception_review(p_key text, p_kind text, p_country text, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_uid uuid := auth.uid();
  v_name text;
  v_old text;
begin
  if v_uid is null or not (public.is_super_admin() or (v_org is not null and public.app_is_elevated())) then
    raise exception 'You do not have permission to review tyre exceptions' using errcode = '42501';
  end if;
  if v_org is null then
    raise exception 'Your account has no organisation' using errcode = '42501';
  end if;
  if p_status not in ('open', 'accepted', 'rejected', 'deferred') then
    raise exception 'Unknown review status' using errcode = '22023';
  end if;
  if p_kind not in ('invalid_serial', 'duplicate_active', 'missing_readings', 'invalid_reading', 'missing_site', 'conflicting_dates',
                    'overlapping_fitment', 'price_missing', 'price_assigned_twice', 'price_incorrect', 'uncertain_previous_tyre',
                    'rotation_not_closed', 'unlinked_repair_retread', 'duplicate_expense') then
    raise exception 'Unknown exception kind' using errcode = '22023';
  end if;
  if p_key is null or split_part(p_key, '|', 1) <> p_kind or length(p_key) > 400 then
    raise exception 'Exception key does not match its kind' using errcode = '22023';
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    raise exception 'Country not in your scope' using errcode = '42501';
  end if;
  if length(coalesce(p_note, '')) > 2000 then
    raise exception 'Note is too long' using errcode = '22023';
  end if;
  if exists (select 1 from public.tyre_exception_refs r where r.ref_kind = 'protected' and r.exception_key = p_key)
     or (p_kind = 'price_assigned_twice' and upper(p_key) like '%|K507B403860') then
    raise exception 'This exception is protected and stays open until the owner authorises a change' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(p.full_name), ''), p.email) into v_name from public.profiles p where p.id = v_uid;
  select status into v_old from public.tyre_exception_reviews where organisation_id = v_org and exception_key = p_key;
  insert into public.tyre_exception_reviews (organisation_id, country, exception_key, kind, status, note, reviewed_by, reviewed_by_name, reviewed_at)
  values (v_org, p_country, p_key, p_kind, p_status, nullif(btrim(p_note), ''), v_uid, v_name, now())
  on conflict (organisation_id, exception_key) do update
    set status = excluded.status, note = excluded.note, reviewed_by = excluded.reviewed_by,
        reviewed_by_name = excluded.reviewed_by_name, reviewed_at = excluded.reviewed_at;
  insert into public.tyre_exception_review_events (organisation_id, country, exception_key, kind, old_status, new_status, note, actor, actor_name)
  values (v_org, p_country, p_key, p_kind, coalesce(v_old, 'open'), p_status, nullif(btrim(p_note), ''), v_uid, v_name);
  return jsonb_build_object('ok', true, 'key', p_key, 'status', p_status, 'previous', coalesce(v_old, 'open'));
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_user_access_grant(p_user_id uuid, p_module_key text, p_capability text DEFAULT 'view'::text, p_effect text DEFAULT 'grant'::text, p_note text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_id uuid; v_org uuid;
BEGIN
  perform set_config('app.access_reason', coalesce(nullif(btrim(coalesce(p_reason, p_note, '')), ''), ''), true);
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF auth.uid() IS NULL OR NOT coalesce(public.app_is_active(),false) OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only an active Super Admin can change access grants.' USING ERRCODE='42501';
  END IF;
  IF p_effect IS NULL OR p_effect NOT IN ('grant','revoke') OR nullif(btrim(p_module_key),'') IS NULL THEN
    RAISE EXCEPTION 'A module and grant/revoke effect are required.' USING ERRCODE='22023';
  END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at<=now() THEN RAISE EXCEPTION 'Grant expiry must be in the future.' USING ERRCODE='22023'; END IF;
  SELECT org_id INTO v_org FROM public.profiles WHERE id=p_user_id FOR UPDATE;
  IF NOT FOUND OR v_org IS NULL THEN RAISE EXCEPTION 'Target user requires an organisation.' USING ERRCODE='42501'; END IF;
  IF left(p_module_key,7)='mobile:' THEN
    -- A fresh ID prevents an installed client's cleanup of old grant IDs from
    -- deleting a newer concurrent override. Other clients retain existing semantics.
    DELETE FROM public.user_access_grants WHERE user_id=p_user_id AND module_key=p_module_key AND capability=coalesce(p_capability,'view');
  END IF;
  INSERT INTO public.user_access_grants(org_id,user_id,module_key,capability,effect,granted_by,note,expires_at)
    VALUES(v_org,p_user_id,p_module_key,coalesce(p_capability,'view'),p_effect,auth.uid(),p_note,p_expires_at)
  ON CONFLICT(user_id,module_key,capability,effect) DO UPDATE
    SET note=EXCLUDED.note,expires_at=EXCLUDED.expires_at,granted_by=auth.uid(),created_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.set_user_issue_status(p_id uuid, p_status text, p_fixed_in_version text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v       public.user_issues%rowtype;
  v_uid   uuid := auth.uid();
  v_st    text := lower(btrim(coalesce(p_status, '')));
  v_ver   text := nullif(left(btrim(coalesce(p_fixed_in_version, '')), 40), '');
  v_note  text := nullif(left(btrim(coalesce(p_note, '')), 2000), '');
  v_notified boolean := false;
begin
  v := public._user_issue_for_admin(p_id);
  if v_st not in ('new', 'triaged', 'in_progress', 'waiting_user', 'fixed', 'closed', 'wont_fix') then
    raise exception 'Unknown status' using errcode = '22023';
  end if;
  if v_st = 'fixed' and coalesce(v_ver, v.fixed_in_version) is null then
    raise exception 'Say which app version has the fix' using errcode = '22023';
  end if;

  update public.user_issues set
    status = v_st,
    fixed_in_version = coalesce(v_ver, fixed_in_version),
    first_response_at = coalesce(first_response_at, now()),
    resolved_at = case when v_st in ('fixed', 'closed', 'wont_fix') then coalesce(resolved_at, now()) else null end,
    updated_at = now()
  where id = v.id;

  if v_st is distinct from v.status then
    insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, from_value, to_value)
    values (v.id, v.organisation_id, v_uid, 'status', v.status, v_st);
  end if;
  if v_note is not null then
    insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, note)
    values (v.id, v.organisation_id, v_uid, 'comment', v_note);
  end if;
  if v_ver is not null and v_ver is distinct from v.fixed_in_version then
    insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, from_value, to_value)
    values (v.id, v.organisation_id, v_uid, 'fixed_version', v.fixed_in_version, v_ver);
  end if;

  if v_st = 'fixed' and v.status is distinct from 'fixed' and v.reporter_id is not null then
    insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
    values (v.reporter_id, 'success', 'Your problem was fixed',
            'Your problem was fixed in version ' || coalesce(v_ver, v.fixed_in_version)
              || '. Please update the app to get the fix.',
            'user_issue', v.id);
    v_notified := true;
  end if;

  return jsonb_build_object('ok', true, 'status', v_st, 'notified', v_notified);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.share_password_ok(p_kind text, p_share_id uuid, p_password text, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  r         public.share_password_attempts%rowtype;
  v_max     constant integer  := 10;
  v_window  constant interval := interval '15 minutes';
  v_lock    constant interval := interval '15 minutes';
begin
  if p_hash is null then
    return true;
  end if;
  if p_share_id is null or p_password is null or btrim(p_password) = '' then
    return false;
  end if;

  select * into r
    from public.share_password_attempts
   where kind = p_kind and share_id = p_share_id;

  if r.locked_until is not null and r.locked_until > now() then
    return false;
  end if;

  if crypt(p_password, p_hash) = p_hash then
    if r.share_id is not null and (r.failed_count > 0 or r.locked_until is not null) then
      update public.share_password_attempts
         set failed_count = 0, locked_until = null, window_started_at = now()
       where kind = p_kind and share_id = p_share_id;
    end if;
    return true;
  end if;

  insert into public.share_password_attempts as a
         (kind, share_id, failed_count, window_started_at, last_failed_at)
  values (p_kind, p_share_id, 1, now(), now())
  on conflict (kind, share_id) do update
     set failed_count = case when a.window_started_at < now() - v_window then 1
                             else a.failed_count + 1 end,
         window_started_at = case when a.window_started_at < now() - v_window then now()
                                  else a.window_started_at end,
         last_failed_at = now(),
         locked_until = case
           when (case when a.window_started_at < now() - v_window then 1
                      else a.failed_count + 1 end) >= v_max
           then now() + v_lock else null end;
  return false;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.sso_password_login_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_uid uuid := auth.uid(); v_org uuid; v_email text; v_dom text; v_amr jsonb;
begin
  if v_uid is null then return jsonb_build_object('allowed', true, 'reason', 'no_session'); end if;
  if public.is_super_admin() then return jsonb_build_object('allowed', true, 'reason', 'super_admin_exempt'); end if;
  v_amr := coalesce(auth.jwt()->'amr', '[]'::jsonb);
  if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(v_amr) = 'array' then v_amr else '[]'::jsonb end) e
              where coalesce(e->>'method', '') like 'sso%') then
    return jsonb_build_object('allowed', true, 'reason', 'sso_session');
  end if;
  select coalesce(p.organisation_id, p.org_id) into v_org from public.profiles p where p.id = v_uid;
  select lower(u.email) into v_email from auth.users u where u.id = v_uid;
  v_dom := nullif(split_part(coalesce(v_email, ''), '@', 2), '');
  if v_org is null or v_dom is null then return jsonb_build_object('allowed', true, 'reason', 'not_applicable'); end if;
  if v_dom = any(public._sso_enforced_domains(v_org)) then
    return jsonb_build_object('allowed', false, 'reason', 'sso_required');
  end if;
  return jsonb_build_object('allowed', true, 'reason', 'not_required');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.stage_expense_import(p_request_id uuid, p_chunk integer, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_batch administration_imports.expense_batches; v_previous jsonb;
BEGIN
 SELECT * INTO v_batch FROM administration_imports.expense_batches WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Expense import not found' USING ERRCODE='42501'; END IF;
 IF administration_imports.check_expense_actor(v_batch.country)<>v_batch.organisation_id OR v_batch.actor<>auth.uid() THEN
  RAISE EXCEPTION 'Expense import access denied' USING ERRCODE='42501';
 END IF;
 IF p_chunk IS NULL OR p_chunk<0 OR p_chunk>=(v_batch.expected_rows+199)/200
    OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_rows)<>least(200,v_batch.expected_rows-p_chunk*200)
    OR pg_column_size(p_rows)>1048576 THEN
  RAISE EXCEPTION 'Invalid expense import chunk' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) r WHERE jsonb_typeof(r)<>'object'
    OR (r ? 'country' AND r->>'country' IS DISTINCT FROM v_batch.country)
    OR nullif(btrim(r->>'item_description'),'') IS NULL) THEN
  RAISE EXCEPTION 'Every expense row needs a description and the selected country' USING ERRCODE='22023';
 END IF;
 SELECT rows INTO v_previous FROM administration_imports.expense_chunks WHERE batch_id=p_request_id AND chunk_index=p_chunk;
 IF FOUND THEN
  IF v_previous<>p_rows THEN RAISE EXCEPTION 'Expense chunk retry differs from original' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('ok',true);
 END IF;
 IF v_batch.result IS NOT NULL THEN RAISE EXCEPTION 'Import already completed' USING ERRCODE='PT409'; END IF;
 INSERT INTO administration_imports.expense_chunks VALUES(p_request_id,p_chunk,p_rows);
 RETURN jsonb_build_object('ok',true);
END $function$;
