CREATE OR REPLACE FUNCTION public.stamp_budget_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' then
    if new.status = 'Approved' then
      new.approved_by := auth.uid();
      new.approved_at := now();
    else
      new.approved_by := null;
      new.approved_at := null;
    end if;
  elsif new.status is distinct from old.status then
    if new.status = 'Approved' then
      new.approved_by := auth.uid();
      new.approved_at := now();
    else
      new.approved_by := null;
      new.approved_at := null;
    end if;
  else
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.stamp_checklist_document_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prefix text;
begin
  if new.document_no is not null and btrim(new.document_no) <> '' then return new; end if;
  if new.template_id is null then return new; end if;
  select t.doc_prefix into v_prefix from public.checklist_templates t where t.id = new.template_id;
  if coalesce(btrim(v_prefix),'') = '' then return new; end if;
  new.document_no := public.next_checklist_document_no(
    new.organisation_id, v_prefix, new.asset_no,
    extract(year from coalesce(new.submitted_at, now()))::int
  );
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stamp_checklist_form_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  if new.status = 'published'
     and (tg_op = 'INSERT' or old.status is distinct from 'published' or new.version is distinct from old.version) then
    select coalesce(nullif(btrim(full_name), ''), username, email) into v_name from public.profiles where id = auth.uid();
    if auth.uid() is not null then
      new.form_approved_by := auth.uid();
      new.form_approved_name := v_name;
      new.last_reviewed_by := auth.uid();
      new.last_reviewed_name := v_name;
    end if;
    new.form_approved_at := now();
    new.last_reviewed_at := now();
    new.form_effective_date := current_date;
    if new.form_revision is null or new.form_revision ~ '^v[0-9]+$' then
      new.form_revision := 'v' || new.version;
    end if;
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.stamp_checklist_submission_template_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_template public.checklist_templates;
  v_revision public.checklist_template_revisions;
begin
  if new.template_snapshot is not null then
    raise exception 'Checklist template evidence is stamped by the server'
      using errcode = '42501';
  end if;
  if new.template_id is null then
    new.template_snapshot_status := 'missing_revision';
    return new;
  end if;

  select * into v_template
  from public.checklist_templates
  where id = new.template_id
    and organisation_id is not distinct from new.organisation_id;

  if not found then
    new.template_snapshot_status := 'missing_revision';
    return new;
  end if;

  new.template_version := coalesce(new.template_version, v_template.version);
  select * into v_revision
  from public.checklist_template_revisions
  where organisation_id = new.organisation_id
    and template_id = new.template_id
    and version = new.template_version;

  if found then
    new.template_revision_id := v_revision.id;
    new.template_snapshot := v_revision.snapshot;
    new.template_snapshot_status := 'exact';
    new.template_snapshot_captured_at := now();
  else
    new.template_revision_id := null;
    new.template_snapshot := null;
    new.template_snapshot_status := 'missing_revision';
    new.template_snapshot_captured_at := null;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stamp_handover_document_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.document_no is null and new.id is not null then
    new.document_no := 'HND-' || upper(left(replace(new.id::text, '-', ''), 8));
  end if;
  return new;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stamp_import_default_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_setting text := nullif(btrim(coalesce(current_setting('tp.import_org', true), '')), '');
  v_org uuid;
begin
  if new.organisation_id is not null then
    return new;
  end if;
  if v_setting is not null then
    begin
      v_org := v_setting::uuid;
    exception when invalid_text_representation then
      raise exception 'tp.import_org is not a valid uuid' using errcode = 'PT409';
    end;
    if not exists (select 1 from public.organisations o where o.id = v_org) then
      raise exception 'tp.import_org does not name an existing organisation' using errcode = 'PT409';
    end if;
    new.organisation_id := v_org;
  elsif coalesce((select value from public.system_config where key = 'single_tenant_mode'), 'false') = 'true' then
    new.organisation_id := '00000000-0000-0000-0000-000000000001'::uuid;
  else
    raise exception 'Import refused: organisation_id is null, tp.import_org is not set and single_tenant_mode is off' using errcode = 'PT409';
  end if;
  return new;
end
$function$;
