CREATE OR REPLACE FUNCTION public.stamp_reviewed_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status IN ('under_review','closed') THEN
    NEW.reviewed_by := auth.uid();
    NEW.reviewed_at := NOW();
  END IF;
  RETURN NEW;
