CREATE OR REPLACE FUNCTION public.start_workflow(p_definition_id uuid, p_entity_type text, p_entity_id text DEFAULT NULL::text, p_entity_label text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.get_my_role() IS NULL THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  RETURN public._workflow_launch(p_definition_id, p_entity_type, p_entity_id,
                                 p_entity_label, p_context, auth.uid(), NULL);
