CREATE OR REPLACE FUNCTION public.stock_entry_resolve(p_source text, p_id text, p_country text, p_site text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d jsonb; v_org uuid:=app_current_org(); v_all boolean:=coalesce(app_sees_all_sites(),false); v_sites text[]:=coalesce(app_site_scope(),'{}'::text[]);
BEGIN
 IF p_source='material' THEN
  SELECT jsonb_build_object('source','material','source_id',m.id,'code',m.item_code,'name',m.item_name,
   'kind',coalesce(stock_item_kind(m.item_name),CASE WHEN m.reviewed AND m.category='tyre' THEN 'tyre' END),
   'brand',m.brand,'unit',m.uom,'reviewed',m.reviewed,'label','MIS / ERP catalogue') INTO d
  FROM material_master m WHERE m.id=p_id::uuid AND m.organisation_id=v_org AND m.country=p_country;
 ELSIF p_source='mis' THEN
  SELECT jsonb_build_object('source','mis','source_id',m.id,'code',m.item_code,'name',m.item_description,
   'kind',stock_item_kind(m.item_description),'brand',m.brand,'unit',m.uom,'reference',m.issue_number,'date',m.txn_date,'label','MIS / ERP') INTO d
  FROM parts_consumption m WHERE m.id=p_id::uuid AND m.organisation_id=v_org AND m.country=p_country
   AND (v_all OR upper(btrim(m.cost_center))=ANY(v_sites)
    OR upper(btrim(m.site))=ANY(v_sites) OR upper(btrim(m.store_code))=ANY(v_sites));
 ELSIF p_source='dtr' THEN
  SELECT jsonb_build_object('source','dtr','source_id',t.id,'code','','name',coalesce(nullif(btrim(t.description),''),concat_ws(' ',t.brand,t.size,'tyre')),
   'kind','tyre','brand',t.brand,'size',t.size,'reference',coalesce(nullif(t.job_card,''),nullif(t.mis_number,''),t.id::text),
   'date',t.issue_date,'label','DTR / tyre record') INTO d
  FROM tyre_records t WHERE t.id=p_id::uuid AND t.organisation_id=v_org AND t.country=p_country AND upper(btrim(t.site))=upper(btrim(p_site))
   AND (stock_item_kind(t.description)='tyre' OR nullif(btrim(t.size),'') IS NOT NULL);
 END IF;
 IF d IS NULL OR d->>'kind' IS NULL OR nullif(btrim(d->>'name'),'') IS NULL THEN RETURN NULL; END IF;
 RETURN d || jsonb_build_object('key',CASE WHEN nullif(btrim(d->>'code'),'') IS NOT NULL
  THEN 'code:'||upper(btrim(d->>'code')) ELSE 'dtr:'||md5(upper(concat_ws('|',d->>'name',d->>'brand',d->>'size'))) END);
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stock_item_kind(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT CASE
 WHEN p_name ~* '\m(filter|lubricant|coolant|engine oil|hydraulic oil|labour|labor|service|fitting charge)\M' THEN NULL
 WHEN p_name ~* '\m(valve|tube|flap|patch|repair kit|nut|stud|glue|cement|gauge|lever|inflator|balancing weight|bead sealer|tyre paste|tire paste|tyre soap|tire soap)\M' AND
  (p_name ~* '\m(tyre|tire|wheel|rim)\M' OR p_name ~* '[0-9]{3}[[:space:]]*/[[:space:]]*[0-9]{2}[[:space:]]*r?[[:space:]]*[0-9]{2}|[0-9]{2}\.[0-9]{1,2}[[:space:]]*[-r][[:space:]]*[0-9]{2}|[0-9]{4}[[:space:]]*r[[:space:]]*[0-9]{2}') THEN 'accessory'
 WHEN p_name ~* '\m(rim|wheel disc)\M' THEN 'rim'
 WHEN p_name ~* '\m(tyre|tire)\M|[0-9]{3}[[:space:]]*/[[:space:]]*[0-9]{2}[[:space:]]*r?[[:space:]]*[0-9]{2}|[0-9]{2}\.[0-9]{1,2}[[:space:]]*[-r][[:space:]]*[0-9]{2}|[0-9]{4}[[:space:]]*r[[:space:]]*[0-9]{2}' THEN 'tyre'
 ELSE NULL END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stock_item_suggestions(p_country text, p_site text, p_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE q text:=regexp_replace(upper(coalesce(p_query,'')),'[^A-Z0-9]','','g'); r record; d jsonb; out jsonb:='[]'; seen text[]:='{}'; v_org uuid:=app_current_org(); v_all boolean:=coalesce(app_sees_all_sites(),false); v_sites text[]:=coalesce(app_site_scope(),'{}'::text[]);
BEGIN
 IF auth.uid() IS NULL OR (is_approved_and_unlocked() IS NOT TRUE) OR v_org IS NULL OR (app_user_can('stock','view') IS NOT TRUE) THEN RAISE EXCEPTION 'Stock access is required.' USING ERRCODE='42501'; END IF;
 IF nullif(btrim(p_country),'') IS NULL OR p_country='All' OR (app_write_country_ok(p_country) IS NOT TRUE)
  OR nullif(btrim(p_site),'') IS NULL OR NOT (v_all OR upper(btrim(p_site))=ANY(v_sites)) THEN
  RAISE EXCEPTION 'Choose a permitted country and site.' USING ERRCODE='42501'; END IF;
 IF length(q)<2 THEN RETURN out; END IF;
 IF length(q)>80 THEN RAISE EXCEPTION 'Search is too long.' USING ERRCODE='22023'; END IF;
 FOR r IN
  (SELECT 'material' AS src,m.id::text AS id FROM material_master m
   WHERE m.organisation_id=v_org AND m.country=p_country
   AND (stock_item_kind(m.item_name) IS NOT NULL OR (m.reviewed AND m.category='tyre'))
   AND regexp_replace(upper(concat_ws(' ',m.item_code,m.item_name,m.brand)),'[^A-Z0-9]','','g') LIKE '%'||q||'%'
   ORDER BY m.reviewed DESC,m.item_code,m.id LIMIT 40)
  UNION ALL
  (SELECT 'mis',m.id::text FROM parts_consumption m WHERE m.organisation_id=v_org AND m.country=p_country
   AND stock_item_kind(m.item_description) IS NOT NULL
   AND (v_all OR upper(btrim(m.cost_center))=ANY(v_sites) OR upper(btrim(m.site))=ANY(v_sites) OR upper(btrim(m.store_code))=ANY(v_sites))
   AND regexp_replace(upper(concat_ws(' ',m.item_code,m.item_description,m.brand)),'[^A-Z0-9]','','g') LIKE '%'||q||'%'
   ORDER BY m.txn_date DESC,m.id LIMIT 60)
  UNION ALL
  (SELECT 'dtr',t.id::text FROM tyre_records t WHERE t.organisation_id=v_org AND t.country=p_country AND upper(btrim(t.site))=upper(btrim(p_site))
   AND (stock_item_kind(t.description)='tyre' OR nullif(btrim(t.size),'') IS NOT NULL)
   AND regexp_replace(upper(concat_ws(' ',t.description,t.brand,t.size)),'[^A-Z0-9]','','g') LIKE '%'||q||'%'
   ORDER BY t.issue_date DESC,t.id LIMIT 40)
 LOOP
  d:=stock_entry_resolve(r.src,r.id,p_country,p_site);
  IF d IS NOT NULL AND NOT (d->>'key'=ANY(seen)) THEN out:=out||jsonb_build_array(d); seen:=array_append(seen,d->>'key'); END IF;
  EXIT WHEN jsonb_array_length(out)>=40;
 END LOOP;
 RETURN out;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stock_movement_direction(p_type text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE lower(btrim(p_type))
    WHEN 'receipt' THEN 1 WHEN 'return' THEN 1 WHEN 'transfer_in' THEN 1 WHEN 'adjustment_up' THEN 1
    WHEN 'in' THEN 1 WHEN 'reorder' THEN 1 WHEN 'initial' THEN 1
    WHEN 'issue' THEN -1 WHEN 'transfer_out' THEN -1 WHEN 'scrap' THEN -1 WHEN 'adjustment_down' THEN -1
    WHEN 'out' THEN -1
    ELSE NULL END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.stock_status_derive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.stock_status := case
    when coalesce(new.stock_qty, 0) <= coalesce(new.critical_level, 0) then 'Critical'
    when coalesce(new.stock_qty, 0) <= coalesce(new.min_level, 0)      then 'Low'
    else 'OK'
  end;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.storage_object_in_my_org(p_owner uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.app_current_org() IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_owner AND p.organisation_id = public.app_current_org());
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.submit_user_issue(p_description text, p_category text, p_severity text DEFAULT 'medium'::text, p_platform text DEFAULT 'web'::text, p_app_version text DEFAULT NULL::text, p_device text DEFAULT NULL::text, p_os text DEFAULT NULL::text, p_page text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_prof  public.profiles%rowtype;
  v_org   uuid;
  v_desc  text := btrim(coalesce(p_description, ''));
  v_cat   text := lower(btrim(coalesce(p_category, '')));
  v_sev   text := lower(btrim(coalesce(p_severity, 'medium')));
  v_plat  text := lower(btrim(coalesce(p_platform, 'web')));
  v_ref   text := nullif(left(btrim(coalesce(p_reference_id, '')), 100), '');
  v_logs  uuid[];
  v_recent int;
  v_id    uuid;
  v_due   timestamptz;
begin
  if v_uid is null then
    raise exception 'Please sign in to report a problem' using errcode = '42501';
  end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or coalesce(v_prof.locked, false) then
    raise exception 'Your account cannot report problems' using errcode = '42501';
  end if;
  v_org := coalesce(v_prof.org_id, v_prof.organisation_id);
  if v_org is null then
    raise exception 'Your account is not linked to a company' using errcode = '42501';
  end if;

  if length(v_desc) < 5 then
    raise exception 'Please describe the problem in a few words' using errcode = '22023';
  end if;
  if length(v_desc) > 2000 then
    raise exception 'The description is too long (2000 characters at most)' using errcode = '22023';
  end if;
  if v_cat not in ('bug', 'data_wrong', 'slow', 'access', 'other') then
    raise exception 'Unknown problem type' using errcode = '22023';
  end if;
  if v_sev not in ('low', 'medium', 'high', 'critical') then v_sev := 'medium'; end if;
  if v_plat not in ('web', 'flutter', 'expo') then v_plat := 'web'; end if;

  select count(*) into v_recent from public.user_issues
   where reporter_id = v_uid and created_at > now() - interval '1 hour';
  if v_recent >= 20 then
    raise exception 'Too many reports in the last hour. Please try again later' using errcode = '54000';
  end if;

  select coalesce(array_agg(id), '{}') into v_logs from (
    select id from public.system_logs
     where user_id = v_uid
       and (created_at > now() - interval '30 minutes'
            or (v_ref is not null and reference_id = v_ref and created_at > now() - interval '24 hours'))
     order by created_at desc
     limit 10) s;

  v_due := now() + case v_sev
    when 'critical' then interval '4 hours'
    when 'high' then interval '1 day'
    else interval '5 days' end;

  insert into public.user_issues
    (organisation_id, country, site, reporter_id, platform, app_version, device, os, page_or_screen,
     description, category, severity, reference_id, linked_log_ids, sla_due_at)
  values
    (v_org,
     case when v_prof.country is not null and array_length(v_prof.country, 1) = 1 then v_prof.country[1] end,
     nullif(btrim(coalesce(v_prof.site, '')), ''),
     v_uid, v_plat,
     nullif(left(btrim(coalesce(p_app_version, '')), 40), ''),
     nullif(left(btrim(coalesce(p_device, '')), 200), ''),
     nullif(left(btrim(coalesce(p_os, '')), 120), ''),
     nullif(left(btrim(coalesce(p_page, '')), 300), ''),
     v_desc, v_cat, v_sev, v_ref, v_logs, v_due)
  returning id into v_id;

  insert into public.user_issue_events (issue_id, organisation_id, actor_id, event_type, to_value)
  values (v_id, v_org, v_uid, 'created', 'new');

  return jsonb_build_object('ok', true, 'id', v_id, 'linked_logs', coalesce(array_length(v_logs, 1), 0));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_accident_parts_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_accident uuid := COALESCE(NEW.accident_id, OLD.accident_id);
BEGIN
  UPDATE public.accidents
     SET parts_cost = COALESCE((
       SELECT SUM(total_cost) FROM public.accident_parts WHERE accident_id = v_accident
     ), 0)
   WHERE id = v_accident;
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_action_item_to_corrective()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_target text;
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if new.source is null or new.source not like 'corrective:%' then return new; end if;
  if new.status is not distinct from old.status then return new; end if;

  begin
    v_id := substr(new.source, length('corrective:') + 1)::uuid;
    v_target := case
      when new.status in ('resolved', 'dismissed') then 'Closed'
      when new.status = 'open' then 'Open'
      else 'In Progress' end;

    update public.corrective_actions
       set status = v_target,
           closed_at = case when v_target = 'Closed' then coalesce(closed_at, now()) else null end,
           closed_by = case when v_target = 'Closed' then coalesce(closed_by, auth.uid()) else null end
     where id = v_id
       and organisation_id is not distinct from new.organisation_id
       and status is distinct from v_target;
  exception when others then
    insert into public.system_logs (organisation_id, module_id, severity, source, message, detail)
    values (new.organisation_id, 'action_center', 'error', 'sync_action_item_to_corrective',
            'Action Center status could not be copied to the corrective action',
            jsonb_build_object('action_item_id', new.id, 'sqlstate', sqlstate, 'error', sqlerrm));
  end;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_asset_current_km()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.odometer_km is null or btrim(coalesce(NEW.asset_no,'')) = '' then
    return NEW;
  end if;
  if coalesce(NEW.flagged, false) and coalesce(NEW.flag_reason, '') like 'Implausible reading%' then
    return NEW;
  end if;
  update public.vehicle_fleet vf
     set current_km = NEW.odometer_km, updated_at = now()
   where btrim(vf.asset_no) = btrim(NEW.asset_no)
     and vf.organisation_id is not distinct from NEW.organisation_id
     and (NEW.country is null or vf.country is null
          or lower(btrim(vf.country)) = lower(btrim(NEW.country)))
     and (vf.current_km is null or NEW.odometer_km >= vf.current_km);
  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_corrective_to_action_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source text := 'corrective:' || new.id::text;
  v_item public.action_items%rowtype;
  v_target text;
  v_severity text;
  v_category text;
begin
  if pg_trigger_depth() > 1 then return new; end if;

  v_target := case new.status when 'In Progress' then 'in_progress'
                              when 'Closed' then 'resolved' else 'open' end;
  v_severity := case new.priority when 'High' then 'high' when 'Low' then 'low' else 'medium' end;
  v_category := case new.source_type when 'inspection' then 'inspection'
                                     when 'checklist' then 'inspection'
                                     when 'accident' then 'safety' else 'maintenance' end;

  begin
    select * into v_item from public.action_items
     where source = v_source
       and organisation_id is not distinct from new.organisation_id
     limit 1;

    if not found then
      insert into public.action_items
        (organisation_id, title, category, source, asset_no, severity, assigned_to,
         site, country, due_date, status, impact, notes, resolution)
      values
        (new.organisation_id, left(coalesce(nullif(btrim(new.title), ''), 'Corrective action'), 300),
         v_category, v_source, new.asset_no, v_severity, new.assigned_to,
         new.site, new.country, new.due_date::date, v_target,
         left(split_part(coalesce(new.description, ''), E'\n', 1), 4000),
         left(new.root_cause, 8000),
         case when v_target = 'resolved' then 'Closed in Corrective Actions' end);
      return new;
    end if;

    update public.action_items
       set title = left(coalesce(nullif(btrim(new.title), ''), title), 300),
           severity = v_severity,
           asset_no = new.asset_no,
           assigned_to = coalesce(new.assigned_to, assigned_to),
           site = new.site,
           due_date = new.due_date::date
     where id = v_item.id;

    if v_target = 'resolved' and v_item.status not in ('resolved', 'dismissed') then
      if v_item.status in ('open', 'acknowledged', 'blocked') then
        update public.action_items set status = 'in_progress' where id = v_item.id;
      end if;
      update public.action_items
         set status = 'resolved',
             resolution = coalesce(nullif(btrim(resolution), ''), 'Closed in Corrective Actions')
       where id = v_item.id;
    elsif v_target = 'in_progress' and v_item.status in ('open', 'acknowledged', 'resolved') then
      update public.action_items set status = 'in_progress' where id = v_item.id;
    elsif v_target = 'open' and v_item.status <> 'open' then
      perform set_config('tp.action_sync', 'on', true);
      update public.action_items set status = 'open' where id = v_item.id;
      perform set_config('tp.action_sync', '', true);
    end if;
  exception when others then
    insert into public.system_logs (organisation_id, module_id, severity, source, message, detail)
    values (new.organisation_id, 'action_center', 'error', 'sync_corrective_to_action_item',
            'Corrective action could not be mirrored into the Action Center',
            jsonb_build_object('corrective_action_id', new.id, 'sqlstate', sqlstate, 'error', sqlerrm));
  end;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_ksa_kms_to_meter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_asset text;
  v_country text := 'KSA';
  v_reading_date date;
  v_odo numeric;
  v_org uuid;
begin
  v_asset := btrim(coalesce(NEW."Asset name", ''));
  v_reading_date := NEW.created_at::date;
  v_odo := nullif(
    regexp_replace(
      replace(btrim(coalesce(NEW."Odo value end", '')), ',', ''),
      '[^0-9\.]',
      '',
      'g'
    ),
    ''
  )::numeric;

  if v_asset = '' or v_odo is null then
    return NEW;
  end if;

  insert into public.odometer_logs (
    country, asset_no, odometer_km, reading_date, source, notes
  )
  select
    v_country,
    v_asset,
    v_odo,
    v_reading_date,
    'ksa_kms_upload',
    'Synced from public.ksa_kms'
  where not exists (
    select 1
    from public.odometer_logs o
    where o.asset_no = v_asset
      and o.reading_date = v_reading_date
      and o.source = 'ksa_kms_upload'
  );

  select coalesce(
           (
             select c.organisation_id
             from public.cpk_asset_meter c
             where c.country = v_country
               and c.asset_no = v_asset
             limit 1
           ),
           (
             select min(c2.organisation_id)
             from public.cpk_asset_meter c2
           ),
           '00000000-0000-0000-0000-000000000001'::uuid
         )
    into v_org;

  insert into public.cpk_asset_meter (
    organisation_id,
    country,
    asset_no,
    odo_km,
    hour_hours,
    odo_readings,
    hm_readings,
    odo_resets,
    hm_resets,
    first_date,
    last_date,
    refreshed_at,
    odo_months,
    hm_months
  )
  with o as (
    select
      ol.organisation_id,
      ol.country,
      ol.asset_no,
      ol.reading_date,
      ol.created_at,
      ol.odometer_km,
      lag(ol.odometer_km) over (
        partition by ol.organisation_id, ol.country, ol.asset_no
        order by ol.reading_date, ol.created_at
      ) as prev_odo
    from public.odometer_logs ol
    where ol.country = v_country
      and ol.asset_no = v_asset
      and ol.odometer_km is not null
  ),
  h as (
    select
      eh.organisation_id,
      eh.country,
      eh.asset_no,
      eh.reading_date,
      eh.created_at,
      eh.engine_hours,
      lag(eh.engine_hours) over (
        partition by eh.organisation_id, eh.country, eh.asset_no
        order by eh.reading_date, eh.created_at
      ) as prev_hm
    from public.engine_hours_logs eh
    where eh.country = v_country
      and eh.asset_no = v_asset
      and eh.engine_hours is not null
  ),
  odo_last as (
    select odometer_km
    from o
    order by reading_date desc, created_at desc
    limit 1
  ),
  hm_last as (
    select engine_hours
    from h
    order by reading_date desc, created_at desc
    limit 1
  ),
  agg as (
    select
      v_org as organisation_id,
      v_country as country,
      v_asset as asset_no,
      (select odometer_km from odo_last) as odo_km,
      (select engine_hours from hm_last) as hour_hours,
      (select count(*) from o)::int as odo_readings,
      (select count(*) from h)::int as hm_readings,
      (select count(*) from o where prev_odo is not null and odometer_km < prev_odo)::int as odo_resets,
      (select count(*) from h where prev_hm is not null and engine_hours < prev_hm)::int as hm_resets,
      least(
        coalesce((select min(reading_date) from o), '9999-12-31'::date),
        coalesce((select min(reading_date) from h), '9999-12-31'::date)
      ) as first_date,
      greatest(
        coalesce((select max(reading_date) from o), '0001-01-01'::date),
        coalesce((select max(reading_date) from h), '0001-01-01'::date)
      ) as last_date,
      now() as refreshed_at,
      (select count(distinct date_trunc('month', reading_date)) from o)::int as odo_months,
      (select count(distinct date_trunc('month', reading_date)) from h)::int as hm_months
  )
  select
    organisation_id,
    country,
    asset_no,
    odo_km,
    hour_hours,
    odo_readings,
    hm_readings,
    odo_resets,
    hm_resets,
    nullif(first_date, '9999-12-31'::date),
    nullif(last_date, '0001-01-01'::date),
    refreshed_at,
    odo_months,
    hm_months
  from agg
  on conflict (organisation_id, country, asset_no)
  do update set
    odo_km = excluded.odo_km,
    hour_hours = excluded.hour_hours,
    odo_readings = excluded.odo_readings,
    hm_readings = excluded.hm_readings,
    odo_resets = excluded.odo_resets,
    hm_resets = excluded.hm_resets,
    first_date = excluded.first_date,
    last_date = excluded.last_date,
    refreshed_at = excluded.refreshed_at,
    odo_months = excluded.odo_months,
    hm_months = excluded.hm_months;

  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.sync_profile_org_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.org_id is null and NEW.organisation_id is not null then
    NEW.org_id := NEW.organisation_id;
  elsif NEW.organisation_id is null and NEW.org_id is not null then
    NEW.organisation_id := NEW.org_id;
  elsif NEW.org_id is not null and NEW.organisation_id is not null
        and NEW.org_id is distinct from NEW.organisation_id then
    NEW.organisation_id := NEW.org_id;
  end if;
  return NEW;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.system_config_read_level(p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_key in (
      'console_ip_allowlist_enabled','dual_control_enabled','max_login_attempts',
      'api_key_max_age_days','audit_retention_days','data_retention_months',
      'backup_enabled','backup_max_table_rows',
      'cron_alert_enabled','cron_alert_fail_streak','cron_alert_grace_min',
      'cron_alert_recover_ok','cron_alert_stuck_min',
      'sentry_auto_incidents','tenant_export_retention_days','max_users_per_org',
      'user_issue_breach_alerts','alert_email',
      'ai_model','ai_rate_limit_per_min','ai_cache_ttl_hours'
    ) then 'super'
    when p_key in (
      'accident_email_to','accident_email_cc','accident_email_subject_prefix',
      'support_email','digest_frequency'
    ) then 'elevated'
    else 'all'
  end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.system_config_record_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text := nullif(left(coalesce(current_setting('app.config_reason', true), ''), 500), '');
begin
  if TG_OP = 'INSERT' then
    insert into public.system_config_history(key, action, old_value, new_value, changed_by, reason)
    values (NEW.key, 'insert', null, NEW.value, auth.uid(), v_reason);
    return NEW;
  elsif TG_OP = 'UPDATE' then
    if NEW.value is distinct from OLD.value or NEW.key is distinct from OLD.key then
      insert into public.system_config_history(key, action, old_value, new_value, changed_by, reason)
      values (NEW.key, 'update', OLD.value, NEW.value, auth.uid(), v_reason);
    end if;
    return NEW;
  else
    insert into public.system_config_history(key, action, old_value, new_value, changed_by, reason)
    values (OLD.key, 'delete', OLD.value, null, auth.uid(), v_reason);
    return OLD;
  end if;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.system_config_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if TG_OP = 'INSERT' or NEW.value is distinct from OLD.value then
    NEW.updated_by := coalesce(auth.uid(), NEW.updated_by);
    NEW.updated_at := now();
  end if;
  return NEW;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.system_log_group_key(p_source text, p_message text, p_fingerprint text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  select case
    when nullif(btrim(p_fingerprint), '') is not null then p_fingerprint
    else (
      select case when m = '' then null
        else left(regexp_replace(lower(coalesce(p_source, 'app')), '\s+', ' ', 'g'), 60) || '|' || left(m, 240) end
      from (
        select btrim(regexp_replace(
          regexp_replace(
            regexp_replace(
              regexp_replace(
                regexp_replace(
                  regexp_replace(
                    regexp_replace(
                      regexp_replace(lower(coalesce(p_message, '')),
                        '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '<id>', 'g'),
                      '"[^"]{0,200}"', '<q>', 'g'),
                    '''[^'']{0,200}''', '<q>', 'g'),
                  '`[^`]{0,200}`', '<q>', 'g'),
                '\m0x[0-9a-f]+\M', '<n>', 'g'),
              '\m[0-9a-f]{16,}\M', '<id>', 'g'),
            '[0-9]+(\.[0-9]+)?', '<n>', 'g'),
          '\s+', ' ', 'g')) as m
      ) x
    )
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$;
