CREATE OR REPLACE FUNCTION public.tp_broadcast_message_sender()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if new.sent_by is null then new.sent_by := auth.uid(); end if;
 return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tp_notify_action_assignee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tokens jsonb;
  v_event bigint;
  v_title text;
begin
  if new.assigned_user_id is null
     or (tg_op = 'UPDATE' and new.assigned_user_id is not distinct from old.assigned_user_id) then
    return new;
  end if;
  if not exists (
     select 1 from public.profiles p
     where p.id = new.assigned_user_id
       and (p.organisation_id = new.organisation_id or p.org_id = new.organisation_id)
       and coalesce(p.approved,true) and not coalesce(p.locked,false)
  ) then return new; end if;
  v_title := 'Task assigned: ' || left(new.title,90);
  insert into public.notifications(user_id,type,title,body,entity_type,entity_id)
  values(new.assigned_user_id,'action_assigned',v_title,
      coalesce(new.recommended_action,'Open your tasks to review this assignment.'),
      'action_item',new.id);
  select jsonb_agg(jsonb_build_object('user_id',new.assigned_user_id,'push_token', t.tok))
    into v_tokens from public._user_push_tokens(new.assigned_user_id) t(tok);
  if v_tokens is not null and jsonb_array_length(v_tokens) > 0 then
     insert into public.domain_events(event_type,entity_type,entity_id,organisation_id,payload,status,processed_at)
     values('action.assigned','action_item',new.id::text,new.organisation_id,
       jsonb_build_object('action_id',new.id,'assignee',new.assigned_user_id),'processed',now())
     returning id into v_event;
     insert into public.workflow_notifications(event_id,organisation_id,instance_id,event_type,payload,recipient_count,status)
     values(v_event,new.organisation_id,null,'action.assigned',
       jsonb_build_object('event_type','action.assigned','entity_type','action_item',
         'entity_id',new.id,'entity_label',new.title,
         'push',jsonb_build_object('title',v_title,'body',coalesce(new.recommended_action,'Open your tasks to review this assignment.')),
         'recipients',v_tokens),jsonb_array_length(v_tokens),'pending');
  end if;
  return new;
end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tp_record_broadcast_recipient()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.type = 'broadcast' and new.entity_type='broadcast' and new.entity_id is not null and new.user_id is not null then
  insert into public.broadcast_recipient_receipts(broadcast_id,recipient_id)
  select b.id,new.user_id from public.broadcast_messages b join public.profiles p on p.id=new.user_id
  where b.id=new.entity_id and (p.organisation_id=b.organisation_id or p.org_id=b.organisation_id)
  on conflict(broadcast_id,recipient_id) do nothing;
 end if;
 return new;
end $function$;
