CREATE OR REPLACE FUNCTION public.transfer_stock_entry(p_request_id uuid, p_from uuid, p_to uuid, p_qty integer, p_expected_from integer, p_expected_to integer, p_notes text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a stock_records%ROWTYPE; b stock_records%ROWTYPE; req stock_entry_requests%ROWTYPE; h text; ma jsonb; mb jsonb; v_result jsonb;
BEGIN
 IF auth.uid() IS NULL OR app_current_org() IS NULL OR (is_approved_and_unlocked() IS NOT TRUE) OR (app_user_can('stock','edit') IS NOT TRUE) THEN RAISE EXCEPTION 'Stock edit permission is required.' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_from IS NULL OR p_to IS NULL OR p_from=p_to OR p_qty IS NULL OR p_qty<=0 OR length(coalesce(p_notes,''))>1000 THEN RAISE EXCEPTION 'Check transfer items and quantity.' USING ERRCODE='22023'; END IF;
 PERFORM id FROM stock_records WHERE id IN (p_from,p_to) ORDER BY id FOR UPDATE;
 SELECT * INTO a FROM stock_records WHERE id=p_from; SELECT * INTO b FROM stock_records WHERE id=p_to;
 IF a.id IS NULL OR b.id IS NULL OR a.organisation_id IS DISTINCT FROM app_current_org() OR b.organisation_id IS DISTINCT FROM app_current_org()
 OR a.country IS NULL OR b.country IS NULL OR nullif(btrim(a.site),'') IS NULL OR nullif(btrim(b.site),'') IS NULL OR a.country IS DISTINCT FROM b.country OR (app_write_country_ok(a.country) IS NOT TRUE) OR (app_write_country_ok(b.country) IS NOT TRUE)
 OR NOT (coalesce(app_sees_all_sites(),false) OR (upper(btrim(a.site))=ANY(coalesce(app_site_scope(),'{}'::text[])) AND upper(btrim(b.site))=ANY(coalesce(app_site_scope(),'{}'::text[])))) THEN RAISE EXCEPTION 'Transfer items are outside your scope.' USING ERRCODE='42501'; END IF;
 IF upper(btrim(a.site))=upper(btrim(b.site)) THEN RAISE EXCEPTION 'Choose different source and destination sites.' USING ERRCODE='22023'; END IF;
 h:=md5(jsonb_build_array('transfer',p_from,p_to,p_qty,p_expected_from,p_expected_to,p_notes)::text);
 INSERT INTO stock_entry_requests(id,organisation_id,country,site,created_by,payload_hash) VALUES(p_request_id,app_current_org(),a.country,a.site,auth.uid(),h) ON CONFLICT DO NOTHING;
 SELECT * INTO req FROM stock_entry_requests WHERE id=p_request_id FOR UPDATE;
 IF req.organisation_id IS DISTINCT FROM app_current_org() OR req.created_by IS DISTINCT FROM auth.uid() OR req.payload_hash IS DISTINCT FROM h THEN RAISE EXCEPTION 'Transfer request identifier was already used.' USING ERRCODE='23505'; END IF;
 IF req.result IS NOT NULL THEN RETURN req.result||jsonb_build_object('replayed',true); END IF;
 ma:=coalesce(a.custom_data->'stock_item','{}'); mb:=coalesce(b.custom_data->'stock_item','{}');
 IF coalesce(ma->>'unit','')<>coalesce(mb->>'unit','') OR coalesce(ma->>'condition','Unspecified')<>coalesce(mb->>'condition','Unspecified')
 OR (CASE WHEN nullif(ma->>'code','') IS NOT NULL AND nullif(mb->>'code','') IS NOT NULL THEN upper(ma->>'code')<>upper(mb->>'code')
 ELSE regexp_replace(upper(coalesce(a.description,'')),'[^A-Z0-9]','','g')<>regexp_replace(upper(coalesce(b.description,'')),'[^A-Z0-9]','','g')
  OR coalesce(a.brand,'')<>coalesce(b.brand,'') OR coalesce(a.tyre_size,'')<>coalesce(b.tyre_size,'') END) THEN
 RAISE EXCEPTION 'Select the same item, condition and unit at the destination.' USING ERRCODE='22023'; END IF;
 IF a.stock_qty IS DISTINCT FROM p_expected_from OR b.stock_qty IS DISTINCT FROM p_expected_to THEN RAISE EXCEPTION 'Stock changed. Refresh and review the transfer.' USING ERRCODE='PT409'; END IF;
 IF p_qty>a.stock_qty OR b.stock_qty::bigint+p_qty>2147483647 THEN RAISE EXCEPTION 'Insufficient stock or quantity outside the allowed range.' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM workflow_instances WHERE organisation_id=app_current_org() AND entity_type IN ('tyre_transfer','stock_issue') AND entity_id IN (p_from::text,p_to::text) AND status IN ('pending','in_review','returned','approved')) THEN RAISE EXCEPTION 'An approval workflow protects this transfer.' USING ERRCODE='PT423'; END IF;
 INSERT INTO stock_movements(stock_id,site,description,movement_type,qty_before,qty_change,qty_after,reason,reference_no,created_by,organisation_id) VALUES
 (a.id,a.site,a.description,'transfer_out',a.stock_qty,-p_qty,a.stock_qty-p_qty,concat('Transfer to ',b.site,': ',p_notes),'TRANSFER-'||p_request_id::text,auth.uid(),app_current_org()),
 (b.id,b.site,b.description,'transfer_in',b.stock_qty,p_qty,b.stock_qty+p_qty,concat('Transfer from ',a.site,': ',p_notes),'TRANSFER-'||p_request_id::text,auth.uid(),app_current_org());
 UPDATE stock_records SET stock_qty=stock_qty+CASE WHEN id=p_from THEN -p_qty ELSE p_qty END,
  stock_status=CASE WHEN stock_qty+CASE WHEN id=p_from THEN -p_qty ELSE p_qty END<=coalesce(critical_level,0) THEN 'Critical' WHEN stock_qty+CASE WHEN id=p_from THEN -p_qty ELSE p_qty END<=coalesce(min_level,0) THEN 'Low' ELSE 'OK' END,
  updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id IN (p_from,p_to);
 PERFORM record_audit_event('stock_transfer','stock_records',p_from::text,jsonb_build_object('from_qty',a.stock_qty,'to_qty',b.stock_qty),jsonb_build_object('from_id',p_from,'to_id',p_to,'qty',p_qty,'request_id',p_request_id));
 v_result:=jsonb_build_object('status','posted','from_stock_id',p_from,'to_stock_id',p_to,'qty',p_qty);
 UPDATE stock_entry_requests SET result=v_result WHERE id=p_request_id;
 RETURN v_result;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.trg_audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb; v_new jsonb; v_diff_old jsonb; v_diff_new jsonb;
  v_email text; v_role text; v_org uuid; v_rid text; v_uid uuid;
  v_actor text; v_detail text; v_label text; v_site text; v_country text;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSE v_old := to_jsonb(OLD);
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT COALESCE(jsonb_object_agg(o.key, o.value), '{}'::jsonb),
           COALESCE(jsonb_object_agg(o.key, v_new -> o.key), '{}'::jsonb)
      INTO v_diff_old, v_diff_new
      FROM jsonb_each(v_old) o
     WHERE v_new -> o.key IS DISTINCT FROM o.value;
    IF v_diff_old = '{}'::jsonb THEN RETURN NULL; END IF;
  ELSE
    v_diff_old := v_old; v_diff_new := v_new;
  END IF;
  v_uid := auth.uid();
  IF v_uid IS NOT NULL THEN
    SELECT email, role INTO v_email, v_role FROM public.profiles WHERE id = v_uid;
    v_actor := 'user'; v_detail := NULL;
  ELSE
    v_label := NULLIF(btrim(coalesce(current_setting('app.actor_label', true), '')), '');
    IF current_user IN ('service_role', 'postgres', 'supabase_admin', 'supabase_auth_admin') THEN
      v_actor := 'service';
    ELSE
      v_actor := 'unknown';
    END IF;
    v_detail := current_user || coalesce(' / ' || v_label, '');
    v_email := coalesce(v_label, v_actor || ':' || current_user);
    v_role := NULL;
  END IF;
  v_org  := NULLIF(COALESCE(v_new ->> 'organisation_id', v_old ->> 'organisation_id'), '')::uuid;
  v_rid  := COALESCE(v_new ->> 'id', v_old ->> 'id');
  v_site := NULLIF(btrim(COALESCE(v_new ->> 'site', v_old ->> 'site', '')), '');
  -- V579: country from the FULL record (never the diff), so country isolation applies to the log.
  v_country := NULLIF(btrim(COALESCE(v_new ->> 'country', v_old ->> 'country', '')), '');
  INSERT INTO public.audit_log_v2
    (user_id, user_email, user_role, org_id, action, table_name, record_id,
     old_values, new_values, actor_type, actor_detail, site, country)
  VALUES
    (v_uid, v_email, v_role, v_org, 'db.' || lower(TG_OP), TG_TABLE_NAME, v_rid,
     v_diff_old, v_diff_new, v_actor, v_detail, v_site, v_country);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.trg_emit_domain_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row     jsonb;
  v_payload jsonb;
BEGIN
  v_row := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  SELECT COALESCE(jsonb_object_agg(k, v_row -> k), '{}'::jsonb)
    INTO v_payload
    FROM unnest(string_to_array(TG_ARGV[2], ',')) AS k
   WHERE v_row ? k;
  PERFORM public.emit_domain_event(
    TG_ARGV[0], TG_ARGV[1], v_row ->> 'id', v_payload,
    NULLIF(v_row ->> 'organisation_id', '')::uuid, auth.uid()
  );
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.trg_emit_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old     jsonb := to_jsonb(OLD);
  v_new     jsonb := to_jsonb(NEW);
  v_col     text  := TG_ARGV[2];
  v_payload jsonb;
BEGIN
  IF (v_old ->> v_col) IS NOT DISTINCT FROM (v_new ->> v_col) THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(jsonb_object_agg(k, v_new -> k), '{}'::jsonb)
    INTO v_payload
    FROM unnest(string_to_array(COALESCE(TG_ARGV[3], ''), ',')) AS k
   WHERE v_new ? k;
  v_payload := v_payload
    || jsonb_build_object('old_' || v_col, v_old ->> v_col, 'new_' || v_col, v_new ->> v_col);
  PERFORM public.emit_domain_event(
    TG_ARGV[0], TG_ARGV[1], v_new ->> 'id', v_payload,
    NULLIF(v_new ->> 'organisation_id', '')::uuid, auth.uid()
  );
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_brand_canonical(raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
           when upper(btrim(regexp_replace(coalesce(raw,''), '\s+', ' ', 'g')))
                in ('', 'NULL', 'N/A', 'NA', '-', '--', 'NONE', 'UNKNOWN', '#N/A', '.')
           then null
           else upper(btrim(regexp_replace(raw, '\s+', ' ', 'g')))
         end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_change_approval_context(p_vehicle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v vehicle_fleet; r approval_execution_requests; items jsonb:='[]'; snapshot jsonb; can_execute boolean; enabled boolean;
BEGIN
 SELECT * INTO v FROM vehicle_fleet WHERE id=p_vehicle_id AND organisation_id=app_current_org();
 IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle unavailable' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope('tyre_change',v.organisation_id,v.country,v.site);
 enabled:=approval_private.enforced('tyre_change',v.organisation_id);
 FOR r IN SELECT * FROM approval_execution_requests WHERE vehicle_id=v.id ORDER BY created_at DESC,id DESC LIMIT 100 LOOP
  can_execute:=false;
  IF r.approval_status='approved' AND r.executed_at IS NULL THEN
   BEGIN snapshot:=approval_private.tyre_source(v.id,r.payload); can_execute:=approval_private.can_execute('tyre_change') AND approval_private.source_matches('tyre_change',r.source_snapshot,snapshot);
   EXCEPTION WHEN SQLSTATE '40001' OR SQLSTATE 'PT409' THEN can_execute:=false; END;
  END IF;
  items:=items||jsonb_build_array(to_jsonb(r)||jsonb_build_object('action',r.payload->>'action','status',CASE WHEN r.executed_at IS NOT NULL THEN 'executed' ELSE coalesce(r.approval_outcome,r.approval_status) END,'can_execute',can_execute));
 END LOOP;
 RETURN jsonb_build_object('mode',CASE WHEN enabled OR jsonb_array_length(items)>0 THEN 'enforced' ELSE 'legacy' END,'can_submit',approval_private.can_execute('tyre_change'),'vehicle',to_jsonb(v),'requests',items);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_close_rotations(p_dry_run boolean DEFAULT true, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_batch uuid := gen_random_uuid();
  r record; v_n int := 0; v_list jsonb := '[]'::jsonb;
begin
  if not (public.is_super_admin() or (v_org is not null and public.app_is_elevated())) then
    raise exception 'You do not have permission to close rotations' using errcode = '42501';
  end if;
  if p_country is not null and not public.app_can_see_country(p_country) then
    raise exception 'Country not in your scope' using errcode = '42501';
  end if;
  for r in
    select e.id old_id, e.country, e.asset_no, upper(btrim(coalesce(e.tyre_position, e.position, ''))) old_pos,
           e.serial_no, e.removal_date, e.km_at_removal, e.total_km, e.hrs_at_removal, e.total_hrs, e.status, e.extra_fields,
           l.id new_id, upper(btrim(coalesce(l.tyre_position, l.position, ''))) new_pos,
           coalesce(l.issue_date, l.fitment_date) new_date, e.organisation_id
    from public.tyre_records e
    join public.tyre_records l
      on l.id <> e.id and l.organisation_id is not distinct from e.organisation_id
     and l.country is not distinct from e.country
     and upper(regexp_replace(coalesce(l.asset_no, ''), '\s+', '', 'g')) = upper(regexp_replace(coalesce(e.asset_no, ''), '\s+', '', 'g'))
     and upper(btrim(l.serial_no)) = upper(btrim(e.serial_no))
     and upper(btrim(coalesce(l.tyre_position, l.position, ''))) <> upper(btrim(coalesce(e.tyre_position, e.position, '')))
     and coalesce(l.issue_date, l.fitment_date) > coalesce(e.issue_date, e.fitment_date)
    where public.tyre_status_is_active(e.status) and public.tyre_status_is_active(l.status)
      and public.tyre_serial_is_strong(e.serial_no)
      and (public.is_super_admin() or e.organisation_id = v_org)
      and (public.is_super_admin() or (public.app_can_see_country(e.country) and public.app_can_see_site(e.site)))
      and (p_country is null or e.country = p_country)
      and not exists (
        select 1 from public.tyre_records z
        where z.organisation_id is not distinct from e.organisation_id and z.country is not distinct from e.country
          and upper(btrim(z.serial_no)) = upper(btrim(e.serial_no))
          and upper(regexp_replace(coalesce(z.asset_no, ''), '\s+', '', 'g')) = upper(regexp_replace(coalesce(e.asset_no, ''), '\s+', '', 'g'))
          and public.tyre_status_is_active(z.status)
          and (coalesce(z.issue_date, z.fitment_date) > coalesce(l.issue_date, l.fitment_date)
               or (coalesce(z.issue_date, z.fitment_date) = coalesce(l.issue_date, l.fitment_date) and z.id <> l.id)))
  loop
    v_n := v_n + 1;
    v_list := v_list || jsonb_build_array(jsonb_build_object('country', r.country, 'asset', r.asset_no, 'serial', r.serial_no,
      'from_position', r.old_pos, 'to_position', r.new_pos, 'rotated_on', r.new_date));
    if not p_dry_run then
      insert into public.tyre_replacement_log (organisation_id, batch_id, tyre_id, country, asset_no, position, old_serial, new_serial,
        replaced_on, old_values, new_values, source)
      values (r.organisation_id, v_batch, r.old_id, r.country, r.asset_no, r.old_pos, r.serial_no, r.serial_no, r.new_date,
        jsonb_build_object('removal_date', r.removal_date, 'km_at_removal', r.km_at_removal, 'total_km', r.total_km, 'hrs_at_removal', r.hrs_at_removal, 'total_hrs', r.total_hrs,
          'status', r.status, 'extra_fields', r.extra_fields),
        jsonb_build_object('removal_date', r.new_date, 'status', 'Removed', 'rotated_to', r.new_pos), 'rotation_close');
      update public.tyre_records t set removal_date = r.new_date, status = 'Removed',
        extra_fields = coalesce(t.extra_fields, '{}'::jsonb) || jsonb_build_object('rotated_to', r.new_pos, 'rotated_on', r.new_date, 'rotation_batch', v_batch)
      where t.id = r.old_id;
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'dry_run', p_dry_run, 'batch_id', case when p_dry_run then null else v_batch end,
    'rotations', v_n, 'rows', v_list);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_audit_apply(p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_batch uuid := gen_random_uuid(); v_n int; v_km_before numeric; v_km_after numeric;
begin
  if not (public.app_role() in ('admin') or public.is_super_admin()) then
    raise exception 'Only an Admin can apply financial corrections' using errcode = '42501';
  end if;
  select coalesce(sum(coalesce(t.km_at_fitment,0) + coalesce(t.km_at_removal,0) + coalesce(t.total_km,0)), 0) into v_km_before
  from public.tyre_records t join public.tyre_cost_audit_findings f on f.tyre_id = t.id
  where f.id = any(p_ids);

  with todo as (
    select f.id fid, f.tyre_id, f.class, f.original_cost, f.proposed_cost
    from public.tyre_cost_audit_findings f
    join public.tyre_records tr on tr.id = f.tyre_id
    where f.id = any(p_ids) and f.status = 'approved'
      and (f.organisation_id = public.app_current_org() or public.is_super_admin())
      and tr.organisation_id = f.organisation_id
      and tr.country is not distinct from f.country
      and (tr.country is null or public.app_can_see_country(tr.country) is not false)
      and (
        (f.class in ('exact_match', 'same_month_item_match') and exists (
          select 1 from public.parts_consumption p
          where p.id::text = f.source_line_id
            and p.organisation_id = f.organisation_id and p.country = f.country
            and p.qty_n > 0 and p.line_cost > 0
            and round(p.line_cost / p.qty_n, 2) = f.proposed_cost
            and to_char(p.event_date, 'YYYY-MM') = f.month
            and upper(regexp_replace(coalesce(p.item_code,''), '\s+', '', 'g')) = coalesce(f.item_code, '')
            and public.tyre_cost_line_kind(p.item_description) = 'tyre'))
        or (f.class = 'priced_estimate_not_verified' and exists (
          select 1 from public.tyre_price_backfill_log l
          where l.tyre_id = f.tyre_id and l.source = 'comparable' and l.new_cost = f.original_cost)))
    for update of f),
  upd as (
    update public.tyre_records t
       set cost_per_tyre = case when d.class = 'priced_estimate_not_verified' then null else d.proposed_cost end
      from todo d
     where t.id = d.tyre_id
       and t.cost_per_tyre is not distinct from d.original_cost
       and (d.class = 'priced_estimate_not_verified' or (d.proposed_cost > 0 and coalesce(t.cost_per_tyre, 0) <= 0))
    returning t.id, d.fid, d.original_cost, t.cost_per_tyre new_cost, t.country, t.serial_no, d.class),
  log as (
    insert into public.tyre_cost_corrections (organisation_id, batch_id, tyre_id, country, serial_no, old_cost, new_cost, reason, created_by)
    select public.app_current_org(), v_batch, u.id, u.country, u.serial_no, u.original_cost, u.new_cost,
           case when u.class = 'priced_estimate_not_verified' then 'cost_audit_estimate_reverted_to_pending' else 'cost_audit_' || u.class end,
           auth.uid()
    from upd u returning tyre_id)
  update public.tyre_cost_audit_findings f set status = 'applied', applied_batch = v_batch, applied_at = now()
  from upd u where f.id = u.fid;
  get diagnostics v_n = row_count;

  select coalesce(sum(coalesce(t.km_at_fitment,0) + coalesce(t.km_at_removal,0) + coalesce(t.total_km,0)), 0) into v_km_after
  from public.tyre_records t join public.tyre_cost_audit_findings f on f.tyre_id = t.id where f.id = any(p_ids);
  if v_km_after <> v_km_before then
    raise exception 'Kilometres changed during a price correction; nothing was applied' using errcode = 'P0001';
  end if;
  return jsonb_build_object('ok', true, 'applied', v_n, 'batch', v_batch, 'undo', 'select public.tyre_cost_correction_undo(''' || v_batch || ''')');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_audit_classify(p_country text, p_from date, p_to date)
 RETURNS TABLE(tyre_id uuid, country text, site text, asset_no text, serial_no text, job_card text, month text, current_cost numeric, currency text, class text, proposed_cost numeric, source_line_id text, item_code text, confidence text, reason text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
with t as materialized (
  select r.id, r.country, r.cost_per_tyre cost, btrim(r.job_card) jc, coalesce(r.issue_date, r.fitment_date) d,
         to_char(coalesce(r.issue_date, r.fitment_date), 'YYYY-MM') m,
         nullif(regexp_replace(upper(coalesce(r.size,'')), '[^0-9A-Z]', '', 'g'), '') sz,
         nullif(upper(btrim(r.brand)), '') brand, r.serial_no, r.site, r.asset_no,
         (select l.source from public.tyre_price_backfill_log l where l.tyre_id = r.id order by l.created_at desc limit 1) bf_source
  from public.tyre_records r
  where coalesce(r.issue_date, r.fitment_date) between p_from and p_to
    and (p_country::text is null or r.country = p_country::text)),
dup as (
  select upper(btrim(serial_no)) s, country from public.tyre_records
  where cost_per_tyre > 0 and public.tyre_serial_is_strong(serial_no)
  group by 1, 2 having count(*) > 1),
ol as materialized (
  select p.id, p.country, btrim(p.work_order_no) jc, upper(regexp_replace(coalesce(p.item_code,''), '\s+', '', 'g')) item,
         to_char(p.event_date, 'YYYY-MM') m, p.item_description dsc, p.qty_n q, p.line_cost v,
         public.tyre_cost_line_kind(p.item_description) k
  from public.parts_consumption p
  where btrim(p.work_order_no) in (select jc from t where coalesce(jc,'') <> '')
    and p.event_date >= (p_from::date - 120)),
own as (
  select o.*, case when o.k = 'tyre' and o.q > 0 and o.v > 0 then round(o.v / o.q, 2) end up
  from ol o where o.k in ('tyre', 'mixed', 'warranty')),
idx as (
  select p.country, upper(regexp_replace(coalesce(p.item_code,''), '\s+', '', 'g')) item, to_char(p.event_date, 'YYYY-MM') m,
         count(distinct round(p.line_cost / p.qty_n, 2)) n_prices, min(round(p.line_cost / p.qty_n, 2)) price, min(p.id::text) src
  from public.parts_consumption p
  where p.cost_category = 'tyre' and p.qty_n > 0 and p.line_cost > 0 and coalesce(p.item_code,'') <> ''
    and p.event_date between (p_from::date - 31) and (p_to::date + 31)
    and public.tyre_cost_line_kind(p.item_description) = 'tyre'
  group by 1, 2, 3),
a as (
  select t.*,
    exists (select 1 from public.warranty_claims w where upper(btrim(w.serial_number)) = upper(btrim(t.serial_no)) and coalesce(btrim(t.serial_no),'') <> '') claim,
    exists (select 1 from dup where dup.s = upper(btrim(t.serial_no)) and dup.country = t.country) dup_price,
    bool_or(o.k = 'warranty') w_line, bool_or(o.k = 'mixed') mixed,
    count(distinct o.item) filter (where o.up is not null and o.item <> '') n_items,
    count(distinct o.up) filter (where o.up is not null and o.m = t.m) n_p_same,
    min(o.up) filter (where o.up is not null and o.m = t.m) p_same,
    min(o.id::text) filter (where o.up is not null and o.m = t.m) src_same,
    min(o.dsc) filter (where o.up is not null and o.m = t.m) dsc_same,
    min(o.item) filter (where o.up is not null and o.m = t.m) item_same,
    count(*) filter (where o.up is not null) n_priced,
    min(o.m) filter (where o.up is not null) m_other,
    bool_or(o.up is not null and abs(o.up - t.cost) <= greatest(0.01, t.cost * 0.005)) cost_matches,
    count(*) filter (where o.k = 'tyre' and o.up is null) n_zero,
    count(distinct o.item) filter (where o.k = 'tyre' and o.up is null and o.item <> '') n_zero_items,
    min(o.item) filter (where o.k = 'tyre' and o.up is null and o.item <> '') zero_item,
    min(o.dsc) filter (where o.k = 'tyre' and o.up is null) zero_dsc
  from t left join own o on o.country = t.country and o.jc = t.jc and coalesce(t.jc,'') <> ''
  group by t.id, t.country, t.cost, t.jc, t.d, t.m, t.sz, t.brand, t.serial_no, t.site, t.asset_no, t.bf_source),
b as (
  select a.*, i.n_prices ix_n, i.price ix_price, i.src ix_src
  from a left join idx i on i.country = a.country and i.item = a.zero_item and i.m = a.m and a.n_zero_items = 1),
s as (
  select b.*,
    (case when coalesce(b.dsc_same, b.zero_dsc) is null then false
      when b.sz is not null and coalesce(b.dsc_same, b.zero_dsc) ~* '\y\d{3}/\d{2,3}\s*[rz]?\s*\d{2}(\.\d)?\y|\y\d{2}\.\d{1,2}\s*[-r]\s*\d{2}\y|\y1[12]\.?0?0\s*[-r]\s*\d{2}(\.\d)?\y|\y\d{2}\s*[-r]\s*1[68]\.5\y|\y\d{1,2}\.\d{2}\s*r\s*\d{2}\y|\y\d{3}\s*r\s*\d{2}c?\y'
           and position(b.sz in regexp_replace(upper(coalesce(b.dsc_same, b.zero_dsc)), '[^0-9A-Z]', '', 'g')) = 0 then true
      when b.brand is not null and exists (select 1 from unnest(public.brain_tokens('tyre_brand')) bt(tok)
             where upper(coalesce(b.dsc_same, b.zero_dsc)) ~ ('(^|[^A-Z])' || regexp_replace(upper(bt.tok), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '([^A-Z]|$)'))
           and not exists (select 1 from unnest(public.brain_tokens('tyre_brand')) bt(tok)
             where upper(coalesce(b.dsc_same, b.zero_dsc)) ~ ('(^|[^A-Z])' || regexp_replace(upper(bt.tok), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '([^A-Z]|$)')
               and (position(upper(bt.tok) in b.brand) > 0 or position(b.brand in upper(bt.tok)) > 0)) then true
      else false end) spec_bad
  from b)
select s.id tyre_id, s.country, s.site, s.asset_no, s.serial_no, s.jc job_card, s.m as month, s.cost as current_cost,
  public.currency_for_country(s.country) currency,
  case
    when s.cost < 0 then 'invalid_cost'
    when s.claim or coalesce(s.w_line, false) then 'excluded_warranty'
    when s.cost > 0 and s.dup_price then 'duplicate_price'
    when s.cost > 0 and s.bf_source = 'comparable' then 'priced_estimate_not_verified'
    when s.cost > 0 and s.n_priced = 0 then 'priced_no_source'
    when s.cost > 0 and coalesce(s.cost_matches, false) then 'priced_verified'
    when s.cost > 0 then 'priced_unreconciled'
    when coalesce(s.mixed, false) then 'mixed_tyre_tube'
    when s.n_items > 1 or s.n_p_same > 1 then 'conflict'
    when s.n_p_same = 1 and s.spec_bad then 'spec_mismatch'
    when s.n_p_same = 1 then 'exact_match'
    when s.n_priced > 0 then 'month_mismatch'
    when s.n_zero_items = 1 and s.ix_n > 1 then 'conflict'
    when s.n_zero_items = 1 and s.ix_n = 1 and s.spec_bad then 'spec_mismatch'
    when s.n_zero_items = 1 and s.ix_n = 1 then 'same_month_item_match'
    when s.n_zero > 0 then 'zero_line_uncertain'
    else 'unresolved' end class,
  case
    when coalesce(s.cost, 0) <= 0 and not (s.claim or coalesce(s.w_line, false)) and not coalesce(s.mixed, false)
         and not (s.n_items > 1 or s.n_p_same > 1) and s.n_p_same = 1 and not s.spec_bad then s.p_same
    when coalesce(s.cost, 0) <= 0 and not (s.claim or coalesce(s.w_line, false)) and not coalesce(s.mixed, false)
         and s.n_items <= 1 and s.n_p_same = 0 and s.n_priced = 0 and s.n_zero_items = 1 and s.ix_n = 1 and not s.spec_bad then s.ix_price
  end proposed_cost,
  coalesce(s.src_same, s.ix_src) source_line_id,
  coalesce(s.item_same, s.zero_item) item_code,
  case when s.n_p_same = 1 and s.sz is not null then 'high' when s.n_p_same = 1 then 'medium' when s.ix_n = 1 then 'medium' end confidence,
  case
    when s.cost < 0 then 'Negative cost ' || s.cost
    when s.claim then 'Warranty claim record exists for this serial'
    when coalesce(s.w_line, false) then 'Warranty wording on its own job card line'
    when s.cost > 0 and s.dup_price then 'Same strong serial carries a purchase price on another row'
    when s.cost > 0 and s.bf_source = 'comparable' then 'Price came from a median of other tyres of the same brand and size in earlier months, not a transaction'
    when s.cost > 0 and s.n_priced = 0 then 'No tyre line on its job card to confirm the stored price'
    when s.cost > 0 and coalesce(s.cost_matches, false) then 'Matches its own job card line'
    when s.cost > 0 then 'Stored ' || s.cost || ' differs from its own job card line'
    when coalesce(s.mixed, false) then 'Its job card line combines tyre and tube; split before pricing'
    when s.n_items > 1 or s.n_p_same > 1 then s.n_items || ' item codes / ' || s.n_p_same || ' prices on its job card in ' || s.m
    when s.n_p_same = 1 and s.spec_bad then 'Source line size or brand differs from the tyre (' || coalesce(s.sz, '?') || ', ' || coalesce(s.brand, '?') || ')'
    when s.n_p_same = 1 then 'Own job card line ' || coalesce(s.item_same, '(no item code)') || ' in ' || s.m || ': value / qty = ' || s.p_same
    when s.n_priced > 0 then 'Own line is in ' || coalesce(s.m_other, '?') || ', tyre is in ' || s.m || '; cross-month prices are not used'
    when s.n_zero_items = 1 and s.ix_n > 1 then 'Item ' || s.zero_item || ' has ' || s.ix_n || ' different prices in ' || s.m
    when s.n_zero_items = 1 and s.ix_n = 1 and s.spec_bad then 'Same-month price found but size or brand differs'
    when s.n_zero_items = 1 and s.ix_n = 1 then 'Own line ' || s.zero_item || ' issued at zero; same item priced ' || s.ix_price || ' in ' || s.m
    when s.n_zero > 0 then 'Own tyre line issued at zero; warranty not proven and no same-month price'
    when coalesce(s.jc, '') = '' then 'No job card to trace a price'
    else 'Its job card has no tyre line' end reason
from s
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_audit_decide(p_ids uuid[], p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  if not (public.app_is_elevated() or public.is_super_admin()) then
    raise exception 'Only Admin, Manager or Director can decide a cost correction' using errcode = '42501';
  end if;
  if p_decision not in ('approved', 'rejected') then raise exception 'Decision must be approved or rejected' using errcode = '22023'; end if;
  if p_decision = 'rejected' and coalesce(btrim(p_note), '') = '' then raise exception 'A rejection needs a reason' using errcode = '22023'; end if;
  update public.tyre_cost_audit_findings f set status = p_decision, decided_by = auth.uid(), decided_at = now(), decision_note = p_note
  where f.id = any(p_ids) and f.status = 'proposed'
    and (f.organisation_id = public.app_current_org() or public.is_super_admin())
    and public.app_can_see_country(f.country) is not false
    and (p_decision = 'rejected' or f.class in ('exact_match', 'same_month_item_match', 'priced_estimate_not_verified'));
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'decided', v_n, 'skipped', coalesce(array_length(p_ids, 1), 0) - v_n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_audit_scan(p_country text DEFAULT NULL::text, p_from date DEFAULT '2025-01-01'::date, p_to date DEFAULT CURRENT_DATE, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if not public.app_is_elevated() and not public.is_super_admin() then
    raise exception 'Only Admin, Manager or Director can run the tyre cost audit' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to then raise exception 'Invalid date range' using errcode = '22023'; end if;
  with c as materialized (select * from public.tyre_cost_audit_classify(p_country, p_from, p_to)),
  ins as (
    insert into public.tyre_cost_audit_findings (organisation_id, tyre_id, country, site, asset_no, serial_no, job_card, month, class,
      original_cost, proposed_cost, currency, item_code, source_line_id, confidence, reasons, dedupe_key)
    select public.app_current_org(), c.tyre_id, c.country, c.site, c.asset_no, c.serial_no, c.job_card, c.month, c.class,
      c.current_cost, c.proposed_cost, c.currency, c.item_code, c.source_line_id, c.confidence, jsonb_build_array(c.reason),
      c.tyre_id::text || '|' || c.class || '|' || coalesce(c.proposed_cost::text, '') || '|' || coalesce(c.source_line_id, '')
    from c where not p_dry_run and c.class not in ('priced_verified', 'priced_no_source')
    on conflict (organisation_id, dedupe_key) where status in ('proposed','approved') do nothing
    returning 1)
  select jsonb_build_object('ok', true, 'dry_run', p_dry_run, 'from', p_from, 'to', p_to, 'country', p_country,
    'checked', (select count(*) from c),
    'by_country_class', (select coalesce(jsonb_agg(x), '[]') from (select country, class, count(*) n, sum(proposed_cost) proposed, min(currency) currency from c group by 1,2 order by 1,2) x),
    'new_findings', case when p_dry_run then null else (select count(*) from ins) end,
    'price_source_note', 'Prices come from ERP store-issue lines (parts_consumption). No invoice, GRN or PO records exist in the database.')
  into v;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_correction_undo(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int; v_skipped int;
begin
  if not public.is_super_admin() then
    raise exception 'Only a super admin can undo a cost correction' using errcode = '42501';
  end if;
  with restored as (
    update public.tyre_records t set cost_per_tyre = c.old_cost
    from public.tyre_cost_corrections c
    where c.batch_id = p_batch and c.undone_at is null and t.id = c.tyre_id
      and t.cost_per_tyre is not distinct from c.new_cost
    returning c.id
  )
  update public.tyre_cost_corrections c set undone_at = now() from restored r where c.id = r.id;
  get diagnostics v_n = row_count;
  select count(*) into v_skipped from public.tyre_cost_corrections where batch_id = p_batch and undone_at is null;
  return jsonb_build_object('ok', true, 'restored', v_n, 'skipped_changed_since', v_skipped);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_cost_line_kind(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select (case
  when public.tyre_price_is_warranty(p_text) then 'warranty'
  when public.tyre_price_is_repair(p_text) then 'repair'
  when p_text ~* '(^|[^a-z])(tyres?|tires?)([^a-z]|$)' and p_text ~* '(^|[^a-z])((inner\s*)?tubes?|flaps?)([^a-z]|$)'
       and p_text ~* '((^|[^a-z])(with|and|incl\w*)([^a-z]|$)|[+&])' then 'mixed'
  when p_text ~* '(^|[^a-z])(inner\s*)?tubes?([^a-z]|$)' then 'tube'
  when p_text ~* '(^|[^a-z])flaps?([^a-z]|$)' then 'flap'
  when p_text ~* '(^|[^a-z])valves?([^a-z]|$)' then 'valve'
  when p_text ~* '(fitting|mounting|dismount|labou?r|service charge|alignment|balanc|installation)'
       and not (p_text ~* '\y\d{3}/\d{2,3}\s*[rz]?\s*\d{2}(\.\d)?\y|\y\d{2}\.\d{1,2}\s*[-r]\s*\d{2}\y|\y1[12]\.?0?0\s*[-r]\s*\d{2}(\.\d)?\y|\y\d{2}\s*[-r]\s*1[68]\.5\y|\y\d{1,2}\.\d{2}\s*r\s*\d{2}\y|\y\d{3}\s*r\s*\d{2}c?\y') then 'service'
  when p_text ~* '(^|[^a-z])(tyres?|tires?)([^a-z]|$)'
       or p_text ~* '\y\d{3}/\d{2,3}\s*[rz]?\s*\d{2}(\.\d)?\y|\y\d{2}\.\d{1,2}\s*[-r]\s*\d{2}\y|\y1[12]\.?0?0\s*[-r]\s*\d{2}(\.\d)?\y|\y\d{2}\s*[-r]\s*1[68]\.5\y|\y\d{1,2}\.\d{2}\s*r\s*\d{2}\y|\y\d{3}\s*r\s*\d{2}c?\y' then 'tyre'
  else 'other' end)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_disposals_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_failure_analyses_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin new.updated_at := now(); return new; end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_import_reconcile(p_rows jsonb, p_country text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_batch uuid := gen_random_uuid();
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  r jsonb; v_res jsonb; v_status text; v_moved int := 0;
  v_counts jsonb := '{}'::jsonb; v_review jsonb := '[]'::jsonb;
begin
  if v_org is null then raise exception 'No organisation in session' using errcode = '42501'; end if;
  if not public.app_is_elevated() then
    raise exception 'You do not have permission to reconcile tyre replacements' using errcode = '42501';
  end if;
  if v_country is not null and lower(v_country) = 'all' then v_country := null; end if;
  if v_country is null then return jsonb_build_object('ok', false, 'reason', 'country_required'); end if;
  v_country := public.normalize_country(v_country);
  if not public.app_can_see_country(v_country) then return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if jsonb_typeof(p_rows) is distinct from 'array' then return jsonb_build_object('ok', false, 'reason', 'rows_must_be_array'); end if;
  for r in
    select e from jsonb_array_elements(p_rows) e
    where nullif(btrim(coalesce(e->>'removal_date', '')), '') is null
    order by (e->>'issue_date') nulls last
  loop
    begin
      v_res := public._tyre_close_replaced(v_org, v_country, r->>'asset_no', coalesce(r->>'tyre_position', r->>'position'),
        r->>'serial_no', nullif(r->>'issue_date', '')::date,
        public._to_num(r->>'km_at_fitment'), public._to_num(r->>'hrs_at_fitment'), 'erp_intake', v_batch, p_dry_run, false);
      if v_res->>'status' in ('closed', 'no_previous', 'not_applicable', 'would_close') then
        v_moved := v_moved + public._tyre_close_serial_elsewhere(v_org, v_country, r->>'asset_no', r->>'serial_no',
          nullif(r->>'issue_date', '')::date, 'erp_intake', v_batch, p_dry_run);
      end if;
    exception when others then
      v_res := jsonb_build_object('status', 'error', 'message', sqlerrm);
    end;
    v_status := v_res->>'status';
    v_counts := jsonb_set(v_counts, array[v_status], to_jsonb(coalesce((v_counts->>v_status)::int, 0) + 1));
    -- Held rows go to the same admin review list as the staging pipe, in the
    -- staging payload shape so resolve_tyre_import_review can act on them.
    if not p_dry_run and (v_status like 'ambiguous%' or v_status = 'error') then
      insert into public.stg_monthly_tyres_audit(country, organisation_id, action, reason, payload, tyre_record_id)
      values (v_country, v_org, 'rejected', 'replacement_needs_review:' || v_status,
        jsonb_strip_nulls(jsonb_build_object('source', 'erp_intake', 'country', v_country,
          'veh_no', r->>'asset_no', 'tyre_position', coalesce(r->>'tyre_position', r->>'position'),
          'tyre_no', r->>'serial_no', 'tyre_fix_date', r->>'issue_date', 'fixed_km', r->>'km_at_fitment',
          'fixed_hrs', r->>'hrs_at_fitment', 'job_card_no', r->>'job_card', 'veh_type', r->>'vehicle_type',
          'item_tyre', r->>'size', 'brand', r->>'brand')),
        nullif(v_res->>'tyre_id', '')::uuid);
    end if;
    if (v_status like 'ambiguous%' or v_status in ('error', 'same_tyre'))  then
      v_review := v_review || jsonb_build_array(jsonb_build_object('asset_no', r->>'asset_no',
        'position', coalesce(r->>'tyre_position', r->>'position'), 'serial_no', r->>'serial_no',
        'issue_date', r->>'issue_date', 'status', v_status));
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'dry_run', p_dry_run, 'batch_id', case when p_dry_run then null else v_batch end,
    'counts', v_counts, 'moved_from_other_vehicle', v_moved, 'review', (select coalesce(jsonb_agg(q.e), '[]'::jsonb) from (select e from jsonb_array_elements(v_review) e limit 200) q),
    'review_total', jsonb_array_length(v_review), 'held', v_review);
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_km_life(p_fit numeric, p_rem numeric, p_total numeric, p_vehicle_type text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when v.km is not null and v.km <= public.tyre_life_km_cap(p_vehicle_type) then v.km end
  from (select case
    when p_fit > 1 and p_rem > p_fit then p_rem - p_fit
    when p_fit > 1 and p_total > 0 then p_total
    when p_fit = 1 then null
    when p_fit = 0 and p_total > 0 then p_total
    when p_fit = 0 and p_rem > 0 then p_rem
    when p_fit is null and p_total > 0 then p_total
  end as km) v
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_learn_confirm(p_match_type text, p_match_value text, p_target_field text, p_target_value text, p_country text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text, p_dry_run boolean DEFAULT true)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_fact uuid; v_batch uuid := gen_random_uuid();
  v_matched int := 0; v_filled int := 0;
  v_col text := p_target_field;
  v_pred text; v_mv text := btrim(p_match_value); v_tv text := btrim(p_target_value);
  v_fact_country text := p_country;
  v_scope text[];
begin

  if p_country is not null and not public.app_write_country_ok(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if v_org is null then raise exception 'no organisation context'; end if;
  if p_match_type not in ('serial','alias') then raise exception 'bad match_type %', p_match_type; end if;
  if p_target_field not in ('brand','size') then raise exception 'bad target_field %', p_target_field; end if;
  if coalesce(v_mv,'')='' or coalesce(v_tv,'')='' then raise exception 'match_value and target_value are required'; end if;

  if p_match_type='serial' then
    v_pred := format('upper(btrim(serial_no))=upper(btrim(%L)) and (%I is null or btrim(%I)='''')', v_mv, v_col, v_col);
  else
    v_pred := format('upper(btrim(%I))=upper(btrim(%L)) and coalesce(upper(btrim(%I)),'''') <> upper(btrim(%L))', v_col, v_mv, v_col, v_tv);
  end if;

  execute format('select count(*) from public.tyre_records where organisation_id=%L and (%L::text is null or country=%L) and (country is null or public.app_write_country_ok(country)) and %s',
                 v_org, p_country, p_country, v_pred) into v_matched;

  if p_dry_run then
    return json_build_object('ok',true,'dry_run',true,'matched',v_matched,'filled',0);
  end if;

  -- V555: the immediate update was scoped by V550, the RULE was not. A fact
  -- row is replayed on every later write by apply_tyre_learned_facts, so a
  -- country-less rule authored by a country-scoped user brands another
  -- country's tyres days later. Stamp it, or refuse rather than guess.
  if v_fact_country is null
     and not (public.is_super_admin() or public.app_sees_all_countries()) then
    select array_agg(x) into v_scope
      from public.profiles pr, unnest(pr.country) x
     where pr.id = auth.uid() and x is not null and btrim(x) <> '';
    if v_scope is null or cardinality(v_scope) = 0 then
      return json_build_object('ok',false,'reason','forbidden');
    elsif cardinality(v_scope) = 1 then
      v_fact_country := v_scope[1];
    else
      return json_build_object('ok',false,'reason','country_required');
    end if;
  end if;

  insert into public.tyre_learned_facts(organisation_id,country,match_type,match_value,target_field,target_value,source)
  values (v_org,v_fact_country,p_match_type,v_mv,p_target_field,v_tv,coalesce(p_source,'manual'))
  on conflict (organisation_id, coalesce(country,''), match_type, target_field, upper(btrim(match_value)))
  do update set target_value=excluded.target_value, active=true, source=excluded.source, updated_at=now(), confirmed_by=auth.uid()
  returning id into v_fact;

  execute format($f$
    with tgt as (select id, (%I)::text oldv from public.tyre_records
                 where organisation_id=%L and (%L::text is null or country=%L) and (country is null or public.app_write_country_ok(country)) and %s),
         upd as (update public.tyre_records t set %I=%L from tgt where t.id=tgt.id returning t.id)
    insert into public.tyre_learn_apply_log(organisation_id,batch_id,fact_id,tyre_record_id,target_field,old_value,new_value)
    select %L, %L, %L, tgt.id, %L, tgt.oldv, %L from tgt
  $f$, v_col, v_org, p_country, p_country, v_pred, v_col, v_tv, v_org, v_batch, v_fact, p_target_field, v_tv);
  get diagnostics v_filled = row_count;

  return json_build_object('ok',true,'dry_run',false,'fact_id',v_fact,'batch_id',v_batch,'matched',v_matched,'filled',v_filled);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_learn_suggestions(p_country text DEFAULT NULL::text, p_limit integer DEFAULT 200, p_field text DEFAULT 'brand'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v json;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return json_build_object('ok', false, 'reason', 'forbidden'); end if;
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  if p_field not in ('brand','size') then raise exception 'unsupported field %', p_field; end if;

  if p_field='brand' then
    with blanks as (
      select id, country, serial_no, upper(btrim(serial_no)) uk from public.tyre_records
      where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
        and (brand is null or btrim(brand)='') and serial_no is not null and btrim(serial_no)<>''),
    self as (
      select b.uk, mode() within group (order by upper(btrim(t.brand))) val
      from blanks b join public.tyre_records t on t.organisation_id=v_org and upper(btrim(t.serial_no))=b.uk
        and t.brand is not null and btrim(t.brand)<>'' group by b.uk),
    master as (
      select upper(btrim(s.k)) uk, mode() within group (order by upper(btrim(regexp_replace(s.v,'[\t\r\n ]+',' ','g')))) val
      from (select srno k, tyre_brand v from public.ksa_country_upload_template_staging where tyre_brand is not null and upper(btrim(tyre_brand)) not in ('NULL','N/A','NA','-','NONE','')
            union all select old_serialno k, tyre_brand v from public.ksa_country_upload_template_staging where tyre_brand is not null and upper(btrim(tyre_brand)) not in ('NULL','N/A','NA','-','NONE',''))s
      where s.k is not null and btrim(s.k)<>'' and upper(btrim(s.k)) in (select uk from blanks) group by upper(btrim(s.k)))
    select json_agg(row_to_json(x)) into v from (
      select b.uk serial_key, min(b.serial_no) serial_no, min(b.country) country, count(*) rows,
             coalesce(self.val, master.val) suggested_value,
             case when self.val is not null then 'self' when master.val is not null then 'master' end source
      from blanks b left join self on self.uk=b.uk left join master on master.uk=b.uk
      where coalesce(self.val, master.val) is not null
      group by b.uk, self.val, master.val order by count(*) desc limit p_limit) x;
  else
    with blanks as (
      select id, country, serial_no, upper(btrim(serial_no)) uk from public.tyre_records
      where organisation_id=v_org and (p_country is null or country=p_country) and (country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[])))
        and (size is null or btrim(size)='') and serial_no is not null and btrim(serial_no)<>''),
    self as (
      select b.uk, mode() within group (order by upper(btrim(t.size))) val
      from blanks b join public.tyre_records t on t.organisation_id=v_org and upper(btrim(t.serial_no))=b.uk
        and t.size is not null and btrim(t.size)<>'' group by b.uk),
    master as (
      select upper(btrim(s.k)) uk, mode() within group (order by upper(btrim(regexp_replace(s.v,'[\t\r\n ]+',' ','g')))) val
      from (select srno k, tire_size v from public.ksa_country_upload_template_staging where tire_size is not null and upper(btrim(tire_size)) not in ('NULL','N/A','NA','-','NONE','')
            union all select old_serialno k, tire_size v from public.ksa_country_upload_template_staging where tire_size is not null and upper(btrim(tire_size)) not in ('NULL','N/A','NA','-','NONE',''))s
      where s.k is not null and btrim(s.k)<>'' and upper(btrim(s.k)) in (select uk from blanks) group by upper(btrim(s.k)))
    select json_agg(row_to_json(x)) into v from (
      select b.uk serial_key, min(b.serial_no) serial_no, min(b.country) country, count(*) rows,
             coalesce(self.val, master.val) suggested_value,
             case when self.val is not null then 'self' when master.val is not null then 'master' end source
      from blanks b left join self on self.uk=b.uk left join master on master.uk=b.uk
      where coalesce(self.val, master.val) is not null
      group by b.uk, self.val, master.val order by count(*) desc limit p_limit) x;
  end if;
  return json_build_object('ok',true,'field',p_field,'suggestions',coalesce(v,'[]'::json));
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_learn_undo(p_batch_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid := public.app_current_org(); v_restored int := 0; r record;
begin
  if not public.app_is_elevated() then raise exception 'forbidden' using errcode='42501'; end if;
  update public.tyre_learned_facts set active=false, updated_at=now()
   where organisation_id=v_org and public.app_write_country_ok(country) is not false and id in (
     select distinct fact_id from public.tyre_learn_apply_log where batch_id=p_batch_id and organisation_id=v_org and fact_id is not null);
  for r in select l.tyre_record_id, l.target_field, l.old_value from public.tyre_learn_apply_log l
           where l.batch_id=p_batch_id and l.organisation_id=v_org
             and exists (select 1 from public.tyre_records t
                          where t.id = l.tyre_record_id
                            and public.app_write_country_ok(t.country) is not false) loop
    execute format('update public.tyre_records set %I=%L where id=%L and organisation_id=%L and public.app_write_country_ok(country) is not false',
                   r.target_field, r.old_value, r.tyre_record_id, v_org);
    v_restored := v_restored + 1;
  end loop;
  delete from public.tyre_learn_apply_log l where l.batch_id=p_batch_id and l.organisation_id=v_org
    and exists (select 1 from public.tyre_records t
                 where t.id = l.tyre_record_id
                   and public.app_write_country_ok(t.country) is not false);
  return json_build_object('ok',true,'restored',v_restored);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_life_km_cap(p_vehicle_type text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when upper(coalesce(p_vehicle_type,'')) like '%MIXER%'  then 80000
    when upper(coalesce(p_vehicle_type,'')) like '%PUMP%'   then 56000
    when upper(coalesce(p_vehicle_type,'')) like '%LOADER%' then 15000
    else 100000
  end::numeric
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_move(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_id  uuid := nullif(p->>'tyre_id','')::uuid;
  v_to_asset text := nullif(upper(btrim(p->>'to_asset_no')), '');
  v_to_pos   text := nullif(upper(btrim(p->>'to_position')), '');
  v_km numeric := nullif(p->>'km','')::numeric;
  v_src public.tyre_records%rowtype;
  v_dest_id uuid; v_from_asset text; v_from_pos text;
begin
  if public.app_cap_revoked('tyre_records','edit') then
    raise exception 'Not authorised to move tyres.' using errcode = '42501'; end if;
  if not public.is_approved_and_unlocked() then
    raise exception 'Not authorised.' using errcode = '42501'; end if;
  if v_id is null then raise exception 'tyre_id is required.' using errcode = '22004'; end if;
  select * into v_src from public.tyre_records where id = v_id for update;
  if not found then raise exception 'Tyre % not found.', v_id using errcode = 'P0002'; end if;
  if v_src.organisation_id is not null and v_src.organisation_id is distinct from v_org then
    raise exception 'Cross-organisation move denied.' using errcode = '42501'; end if;
  if v_src.country is not null and not public.app_write_country_ok(v_src.country) then
    raise exception 'Cross-country move denied.' using errcode = '42501'; end if;
  v_from_asset := nullif(upper(btrim(coalesce(v_src.asset_no, v_src.asset_number))), '');
  v_from_pos   := nullif(upper(btrim(coalesce(v_src.tyre_position, v_src.position))), '');
  v_to_asset   := coalesce(v_to_asset, v_from_asset);
  if v_to_pos is null then raise exception 'to_position is required.' using errcode = '22004'; end if;
  select id into v_dest_id from public.tyre_records
  where id <> v_id
    and organisation_id is not distinct from v_src.organisation_id
    and coalesce(country,'') = coalesce(v_src.country,'')
    and nullif(upper(btrim(coalesce(asset_no, asset_number))), '') = v_to_asset
    and nullif(upper(btrim(coalesce(tyre_position, position))), '') = v_to_pos
    and public.tyre_status_is_active(status)
  for update limit 1;
  update public.tyre_records set position = null, tyre_position = null where id = v_id;
  if v_dest_id is not null then
    update public.tyre_records
       set position = v_from_pos, tyre_position = v_from_pos,
           asset_no = case when v_to_asset is distinct from v_from_asset then v_from_asset else asset_no end,
           status = 'Active', removal_date = null, km_at_removal = null
     where id = v_dest_id;
  end if;
  update public.tyre_records
     set position = v_to_pos, tyre_position = v_to_pos, asset_no = v_to_asset,
         km_at_fitment = coalesce(v_km, km_at_fitment),
         status = 'Active', removal_date = null, km_at_removal = null
   where id = v_id;
  perform public.record_audit_event('tyre_move', 'tyre_records', v_id::text,
    jsonb_build_object('asset_no', v_from_asset, 'position', v_from_pos),
    jsonb_build_object('asset_no', v_to_asset, 'position', v_to_pos, 'swapped_with', v_dest_id));
  return jsonb_build_object('moved', v_id, 'swapped_with', v_dest_id);
end; $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_one_price_per_tyre()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(new.cost_per_tyre, 0) > 0 and public.tyre_serial_is_strong(new.serial_no)
     and exists (
       select 1 from public.tyre_records e
       where e.organisation_id is not distinct from new.organisation_id
         and coalesce(e.country, '') = coalesce(public.normalize_country(new.country), '')
         and upper(btrim(e.serial_no)) = upper(btrim(new.serial_no))
         and e.cost_per_tyre > 0
         and (public.tyre_size_key_loose(e.size) is null or public.tyre_size_key_loose(new.size) is null
              or public.tyre_size_key_loose(e.size) = public.tyre_size_key_loose(new.size))) then
    new.extra_fields := coalesce(new.extra_fields, '{}'::jsonb)
      || jsonb_build_object('repeat_purchase_price', new.cost_per_tyre,
                            'repeat_purchase_note', 'tyre already priced on an earlier fitment; charged once');
    new.cost_per_tyre := null;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_price_backfill(p_dry_run boolean DEFAULT true, p_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_batch uuid := gen_random_uuid();
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_result jsonb;
begin

  if p_country is not null and not public.app_can_see_country(p_country) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden'); end if;
  if v_org is null then
    raise exception 'No organisation in session' using errcode = '42501';
  end if;
  if not public.app_is_elevated() then
    raise exception 'You do not have permission to change tyre prices'
      using errcode = '42501';
  end if;
  if v_country is not null and lower(v_country) = 'all' then v_country := null; end if;

  drop table if exists _tyre_price_fill;

  create temp table _tyre_price_fill as
  with need as (
    select t.id, t.country, t.job_card, upper(btrim(coalesce(t.asset_no, ''))) as asset_no,
           t.serial_no, t.issue_date,
           upper(btrim(coalesce(t.brand, ''))) as brand,
           upper(btrim(coalesce(t.size, ''))) as size,
           t.cost_per_tyre as old_cost,
           -- 20261109090000: this physical tyre is already priced on another
           -- fitment row, so an estimate here would charge its purchase twice.
           (coalesce(btrim(t.serial_no), '') <> '' and exists (
              select 1 from public.tyre_records e
              where e.organisation_id = v_org and e.id <> t.id
                and e.country is not distinct from t.country
                and upper(btrim(e.serial_no)) = upper(btrim(t.serial_no))
                and e.cost_per_tyre > 0)) as refit_of_priced
    from public.tyre_records t
    where t.organisation_id = v_org
      and (t.cost_per_tyre is null or t.cost_per_tyre = 0)
      and (v_country is null or t.country = v_country)
      and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])))
  ),
  grid as (
    select pc.country, pc.work_order_no,
           upper(btrim(coalesce(pc.asset_code, ''))) as asset_code,
           sum(pc.tyre_cost) as total_value,
           sum(public._to_num(pc.qty)) as total_qty
    from public.parts_consumption pc
    where pc.organisation_id = v_org
      and pc.tyre_cost > 0
      and not public.tyre_price_is_repair(pc.item_description)
      and not public.tyre_price_is_warranty(pc.item_description)
      and (v_country is null or pc.country = v_country)
    group by 1, 2, 3
    having sum(public._to_num(pc.qty)) > 0
  ),
  warranty as (
    select distinct pc.country, pc.work_order_no,
           upper(btrim(coalesce(pc.asset_code, ''))) as asset_code
    from public.parts_consumption pc
    where pc.organisation_id = v_org
      and public.tyre_price_is_warranty(pc.item_description)
      and (v_country is null or pc.country = v_country)
  ),
  known as (
    select t.country,
           upper(btrim(coalesce(t.brand, ''))) as brand,
           upper(btrim(coalesce(t.size, ''))) as size,
           t.issue_date, t.cost_per_tyre
    from public.tyre_records t
    where t.organisation_id = v_org
      and t.cost_per_tyre > 0
      and t.issue_date is not null
      and coalesce(btrim(t.brand), '') <> ''
      and coalesce(btrim(t.size), '') <> ''
      -- A price this process wrote is a derivation, not evidence. Without this
      -- a second run prices from the first run's guesses.
      and not exists (
        select 1 from public.tyre_price_backfill_log l
        where l.organisation_id = v_org and l.tyre_id = t.id)
  )
  select n.id, n.country, n.asset_no, n.serial_no, n.old_cost,
         case
           when w.work_order_no is not null then 0::numeric
           when g.work_order_no is not null then round(g.total_value / g.total_qty, 2)
           else c.price
         end as new_cost,
         case
           when w.work_order_no is not null then 'warranty'
           when g.work_order_no is not null then 'own_jobcard'
           else 'comparable'
         end as source,
         c.samples
  from need n
  left join warranty w
    on w.country = n.country and w.work_order_no = n.job_card and w.asset_code = n.asset_no
  left join grid g
    on g.country = n.country and g.work_order_no = n.job_card and g.asset_code = n.asset_no
  left join lateral (
    select round(percentile_cont(0.5) within group (order by k.cost_per_tyre)::numeric, 2) as price,
           count(*)::int as samples
    from known k
    where k.country = n.country
      and k.brand = n.brand and k.size = n.size
      and n.brand <> '' and n.size <> ''
      and (n.issue_date is null or k.issue_date <= n.issue_date)
  ) c on true
  where (w.work_order_no is not null)
     or (g.work_order_no is not null and g.total_value / g.total_qty > 0 and not n.refit_of_priced)
     or (c.price is not null and c.price > 0 and not n.refit_of_priced);

  select jsonb_build_object(
    'ok', true,
    'dry_run', p_dry_run,
    'batch_id', case when p_dry_run then null else v_batch end,
    'country', coalesce(v_country, 'All'),
    'rows', (select count(*) from _tyre_price_fill),
    'by_source', coalesce((
      select jsonb_object_agg(source, n)
      from (select source, count(*) as n from _tyre_price_fill group by source) s),
      '{}'::jsonb),
    'by_country', coalesce((
      select jsonb_object_agg(country, detail)
      from (
        select coalesce(country, 'Unknown') as country,
               jsonb_build_object(
                 'rows', count(*),
                 'value', round(sum(new_cost), 2),
                 'median_price', round(percentile_cont(0.5)
                                       within group (order by new_cost)::numeric, 2),
                 'by_source', (
                   select jsonb_object_agg(s2.source, jsonb_build_object(
                            'rows', s2.n, 'value', s2.v, 'median_price', s2.m))
                   from (
                     select f2.source, count(*) as n,
                            round(sum(f2.new_cost), 2) as v,
                            round(percentile_cont(0.5)
                                  within group (order by f2.new_cost)::numeric, 2) as m
                     from _tyre_price_fill f2
                     where coalesce(f2.country, 'Unknown') = coalesce(f.country, 'Unknown')
                     group by f2.source
                   ) s2)
               ) as detail
        from _tyre_price_fill f
        group by coalesce(country, 'Unknown'), f.country
      ) k), '{}'::jsonb),
    'sample', coalesce((
      select jsonb_agg(jsonb_build_object(
               'country', country, 'asset_no', asset_no, 'serial_no', serial_no,
               'was', old_cost, 'now', new_cost, 'source', source, 'samples', samples))
      from (select * from _tyre_price_fill order by new_cost desc limit 25) t), '[]'::jsonb)
  ) into v_result;

  if p_dry_run then
    return v_result;
  end if;

  insert into public.tyre_price_backfill_log
         (organisation_id, batch_id, tyre_id, country, asset_no, serial_no,
          old_cost, new_cost, source, samples)
  select v_org, v_batch, id, country, asset_no, serial_no,
         old_cost, new_cost, source, samples
  from _tyre_price_fill;

  update public.tyre_records t
     set cost_per_tyre = f.new_cost
    from _tyre_price_fill f
   where t.id = f.id
     and t.organisation_id = v_org
     and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country)) = any (coalesce((select public.app_country_scope()), '{}'::text[])));

  return v_result;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_price_backfill_undo(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  n integer := 0;
begin
  if not public.app_is_elevated() then
    raise exception 'You do not have permission to change tyre prices'
      using errcode = '42501';
  end if;
  if p_batch_id is null then
    raise exception 'Which batch?' using errcode = '22023';
  end if;

  -- Restores the exact prior value, including NULL. Deriving it again would give
  -- whatever the rules say today, which is not what the row held.
  update public.tyre_records t
     set cost_per_tyre = l.old_cost
    from public.tyre_price_backfill_log l
   where l.organisation_id = v_org
     and l.batch_id = p_batch_id
     and t.id = l.tyre_id
     and t.organisation_id = v_org
     and public.app_write_country_ok(t.country) is not false;
  get diagnostics n = row_count;

  delete from public.tyre_price_backfill_log l
   where l.organisation_id = v_org and l.batch_id = p_batch_id
     and exists (select 1 from public.tyre_records t
                  where t.id = l.tyre_id
                    and public.app_write_country_ok(t.country) is not false);

  return jsonb_build_object('ok', true, 'batch_id', p_batch_id, 'restored', n);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_price_coverage()
 RETURNS TABLE(country text, tyres bigint, priced bigint, missing bigint, coverage_pct numeric, filled_by_backfill bigint, missing_no_brand_or_size bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.country,
         count(*) as tyres,
         count(*) filter (where t.cost_per_tyre > 0) as priced,
         count(*) filter (where t.cost_per_tyre is null or t.cost_per_tyre = 0) as missing,
         round(100.0 * count(*) filter (where t.cost_per_tyre > 0)
               / nullif(count(*), 0), 1) as coverage_pct,
         count(*) filter (where exists (
           select 1 from public.tyre_price_backfill_log l
           where l.tyre_id = t.id and l.organisation_id = t.organisation_id)) as filled_by_backfill,
         -- The reason the remainder cannot be filled: with no brand or size there
         -- is nothing to compare against, which is a data gap, not a bug.
         count(*) filter (where (t.cost_per_tyre is null or t.cost_per_tyre = 0)
                            and (coalesce(btrim(t.brand), '') = ''
                              or coalesce(btrim(t.size), '') = '')) as missing_no_brand_or_size
  from public.tyre_records t
  where t.organisation_id = public.app_current_org() and (t.country is null or (select public.is_super_admin()) or (select public.app_sees_all_countries()) or lower(btrim(t.country::text)) = any(coalesce((select public.app_country_scope()), '{}'::text[]))) and ((t.site)::text is null or btrim((t.site)::text) = '' or (select public.is_super_admin()) or (select public.app_sees_all_sites()) or upper(btrim((t.site)::text)) = any(coalesce((select public.app_site_scope()), '{}'::text[])))
  group by t.country
  order by count(*) desc;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_price_is_repair(p_text text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  -- Whole-word, because substring matching is what once made "Shell RIMula"
  -- match "rim". Plurals are listed, never implied.
  select coalesce(p_text, '') ~*
    '\y(repair|repairs|repairing|puncture|punctures|patch|patches|patching|vulcaniz\w*|vulcanis\w*|retread|retreads|remould|remold)\y';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_price_is_warranty(p_text text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_text, '') ~*
    '\y(warranty|warrantee|guarantee|free of charge|no charge|zero charge|f\.o\.c|foc|replacement claim|under claim)\y';
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tyre_records_master_process()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.country is null or trim(new.country) = '' then
    new.country := public.normalize_country(new.region);
  else
    new.country := public.normalize_country(new.country);
  end if;

  if new.qty is null or new.qty < 1 then
    new.qty := 1;
  end if;

  -- NO default cost: keep the actual per-row price; leave blank when the source had none.

  -- A 0 arriving on INSERT is an import blank (unchanged behaviour). On UPDATE a
  -- stored 0 that is not being changed is the owner-approved factory fitment
  -- value and must survive (20261109090000).
  if new.km_at_fitment = 0
     and (tg_op = 'INSERT' or old.km_at_fitment is distinct from 0) then
    new.km_at_fitment := null;
  end if;
  if new.km_at_removal = 0
     and (tg_op = 'INSERT' or old.km_at_removal is distinct from 0) then
    new.km_at_removal := null;
  end if;

  if new.km_at_fitment is not null
  and new.km_at_removal is not null
  and new.km_at_fitment > new.km_at_removal then
    declare tmp numeric;
    begin
      tmp := new.km_at_fitment;
      new.km_at_fitment := new.km_at_removal;
      new.km_at_removal := tmp;
    end;
  end if;

  return new;
end;
$function$;
