-- @@
CREATE OR REPLACE FUNCTION public.valid_wash_details(d jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare item jsonb; field text; checklist jsonb;
begin
  if d is null then return true; end if;
  if jsonb_typeof(d) <> 'object' or octet_length(d::text) > 40000
    or d->>'version' is distinct from '1'
    or coalesce(d->>'chemical_status','') not in ('not_recorded','none','used')
    or jsonb_typeof(d->'chemicals') is distinct from 'array' then return false; end if;
  -- OPTIONAL: a missing `checklist` means nothing was recorded and is read as
  -- an empty list. Present but not an array is still rejected.
  if d ? 'checklist' and jsonb_typeof(d->'checklist') is distinct from 'array' then return false; end if;
  checklist := coalesce(d->'checklist', '[]'::jsonb);
  if jsonb_array_length(d->'chemicals') > 10 or jsonb_array_length(checklist) > 30
    or (d->>'chemical_status' <> 'used' and jsonb_array_length(d->'chemicals') <> 0)
    or (d->>'chemical_status' = 'used' and jsonb_array_length(d->'chemicals') = 0)
    then return false; end if;
  for item in select value from jsonb_array_elements(d->'chemicals') loop
    if jsonb_typeof(item) <> 'object' or coalesce(length(btrim(item->>'name')),0) not between 1 and 160
      or coalesce(length(item->>'manufacturer'),0) > 160
      or coalesce(length(item->>'dilution'),0) > 120
      or coalesce(length(item->>'quantity'),0) > 40
      or coalesce(length(item->>'unit'),0) > 20
      or coalesce(length(item->>'sds_url'),0) > 1000
      or (coalesce(item->>'sds_url','') <> '' and item->>'sds_url' !~ '^https://[^[:space:]]+$')
      then return false; end if;
    foreach field in array array['name','manufacturer','quantity','unit','dilution','sds_url'] loop
      if item ? field and jsonb_typeof(item->field) <> 'string' then return false; end if;
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(checklist) loop
    if jsonb_typeof(item) <> 'object' or coalesce(length(btrim(item->>'label')),0) not between 1 and 200
      or coalesce(item->>'result','') not in ('not_checked','pass','fail','na')
      or coalesce(length(item->>'note'),0) > 1000
      or (item->>'result' = 'fail' and coalesce(length(btrim(item->>'note')),0) = 0)
      then return false; end if;
    foreach field in array array['label','result','note'] loop
      if item ? field and jsonb_typeof(item->field) <> 'string' then return false; end if;
    end loop;
  end loop;
  return true;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.validate_business_rule(p_trigger_type text, p_event_types text[], p_conditions jsonb, p_actions jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  c jsonb;
  a jsonb;
  v_has_emit boolean := false;
  v_listens_rule boolean := false;
BEGIN
  IF p_trigger_type <> 'event' THEN RETURN false; END IF;
  IF p_event_types IS NULL OR array_length(p_event_types, 1) IS NULL THEN RETURN false; END IF;
  IF p_conditions IS NULL OR jsonb_typeof(p_conditions) <> 'array'
     OR jsonb_array_length(p_conditions) > 10 THEN
    RETURN false;
  END IF;
  FOR c IN SELECT * FROM jsonb_array_elements(p_conditions) LOOP
    IF jsonb_typeof(c) <> 'object'
       OR COALESCE(trim(c ->> 'field'), '') = ''
       OR COALESCE(c ->> 'operator', '') NOT IN ('lt','lte','gt','gte','eq','neq','contains')
       OR NOT (c ? 'value') THEN
      RETURN false;
    END IF;
  END LOOP;
  IF p_actions IS NULL OR jsonb_typeof(p_actions) <> 'array'
     OR jsonb_array_length(p_actions) = 0 OR jsonb_array_length(p_actions) > 5 THEN
    RETURN false;
  END IF;
  FOR a IN SELECT * FROM jsonb_array_elements(p_actions) LOOP
    IF jsonb_typeof(a) <> 'object' THEN RETURN false; END IF;
    CASE a ->> 'type'
      WHEN 'notify_role' THEN
        IF lower(COALESCE(a ->> 'role', '')) NOT IN ('admin','manager','director') THEN
          RETURN false;
        END IF;
      WHEN 'emit_event' THEN
        IF COALESCE(trim(a ->> 'event_type'), '') = '' THEN RETURN false; END IF;
        v_has_emit := true;
      ELSE
        RETURN false;
    END CASE;
  END LOOP;
  SELECT bool_or(t LIKE 'rule.%') INTO v_listens_rule FROM unnest(p_event_types) t;
  IF v_has_emit AND COALESCE(v_listens_rule, false) THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.validate_workflow_steps(p_steps jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  s          jsonb;
  v_role     text;
  v_assignee text;
  v_cond     jsonb;
  v_op       text;
  v_bool_keys text[] := ARRAY[
    'require_signature','require_photo','require_gps',
    'require_comment_on_return','allow_return','optional'
  ];
  k text;
BEGIN
  IF p_steps IS NULL OR jsonb_typeof(p_steps) <> 'array'
     OR jsonb_array_length(p_steps) = 0
     OR jsonb_array_length(p_steps) > 30 THEN
    RETURN false;
  END IF;

  FOR s IN SELECT * FROM jsonb_array_elements(p_steps) LOOP
    IF jsonb_typeof(s) <> 'object'
       OR COALESCE(trim(s ->> 'name'), '') = '' THEN
      RETURN false;
    END IF;

    v_assignee := lower(COALESCE(NULLIF(trim(s ->> 'assignee_type'), ''), 'role'));
    IF v_assignee NOT IN ('role','user') THEN
      RETURN false;
    END IF;

    IF v_assignee = 'user' THEN
      IF COALESCE(trim(s ->> 'approver_user_id'), '') = ''
         OR (s ->> 'approver_user_id') !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    ELSE
      v_role := lower(regexp_replace(COALESCE(s ->> 'approver_role', ''), '\s+', '_', 'g'));
      IF v_role NOT IN (
        'admin','manager','director','tyre_man','inspector','store_keeper',
        'fleet_supervisor','workshop_manager','procurement','finance','gm',
        'operations_manager'
      ) THEN
        RETURN false;
      END IF;
    END IF;

    IF s ? 'approver_user_id' AND s ->> 'approver_user_id' IS NOT NULL
       AND (s ->> 'approver_user_id') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN false;
    END IF;

    IF s ? 'sla_hours' AND s ->> 'sla_hours' IS NOT NULL
       AND (s ->> 'sla_hours') !~ '^\d+(\.\d+)?$' THEN
      RETURN false;
    END IF;

    FOREACH k IN ARRAY v_bool_keys LOOP
      IF s ? k AND jsonb_typeof(s -> k) NOT IN ('boolean','null') THEN
        RETURN false;
      END IF;
    END LOOP;

    IF s ? 'condition' AND jsonb_typeof(s -> 'condition') = 'object' THEN
      v_cond := s -> 'condition';
      v_op   := v_cond ->> 'op';
      IF COALESCE(trim(v_cond ->> 'field'), '') = ''
         OR v_op IS NULL
         OR v_op NOT IN ('=','!=','>','>=','<','<=')
         OR NOT (v_cond ? 'value') THEN
        RETURN false;
      END IF;
    ELSIF s ? 'condition' AND jsonb_typeof(s -> 'condition') NOT IN ('null') THEN
      RETURN false;
    END IF;
  END LOOP;

  RETURN true;
END;
$function$;
