CREATE OR REPLACE FUNCTION public.vehicle_reservation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_name text;
  v_elevated boolean := (auth.uid() is null) or coalesce(public.app_is_elevated(), false) or coalesce(public.is_super_admin(), false);
begin
  if v_uid is not null then
    select full_name into v_name from public.profiles where id = v_uid;
  end if;

  if tg_op = 'INSERT' then
    if new.status = 'approved' and not v_elevated then
      raise exception 'Only a manager can create an approved reservation.' using errcode = '42501';
    end if;
    if new.status = 'approved' then
      new.approved_by_id := coalesce(new.approved_by_id, v_uid);
      new.approved_at := coalesce(new.approved_at, now());
      new.approved_by := coalesce(nullif(btrim(new.approved_by), ''), v_name);
    end if;
    if new.status = 'out' then new.actual_pickup_at := coalesce(new.actual_pickup_at, now()); end if;
    if new.status = 'returned' then new.actual_return_at := coalesce(new.actual_return_at, now()); end if;
    return new;
  end if;

  if new.approved_by_id is distinct from old.approved_by_id and new.status is not distinct from old.status then
    new.approved_by_id := old.approved_by_id;
  end if;

  if new.status is distinct from old.status then
    if new.status = 'approved' then
      if not v_elevated then
        raise exception 'Only a manager can approve a reservation.' using errcode = '42501';
      end if;
      new.approved_by_id := v_uid;
      new.approved_at := now();
      new.approved_by := coalesce(v_name, nullif(btrim(new.approved_by), ''));
      new.rejected_at := null; new.rejected_by_id := null; new.rejected_reason := null;
    elsif new.status = 'out' then
      new.actual_pickup_at := coalesce(new.actual_pickup_at, now());
    elsif new.status = 'returned' then
      new.actual_return_at := coalesce(new.actual_return_at, now());
    end if;
  end if;

  if new.rejected_at is distinct from old.rejected_at and new.rejected_at is not null then
    if not v_elevated then
      raise exception 'Only a manager can reject a reservation.' using errcode = '42501';
    end if;
    if nullif(btrim(coalesce(new.rejected_reason, '')), '') is null then
      raise exception 'A reason is needed to reject a reservation.' using errcode = '22023';
    end if;
    new.rejected_by_id := v_uid;
    new.rejected_at := now();
    new.status := 'cancelled';
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.vehicle_reservation_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_name text;
  v_type text;
  v_changed text[];
begin
  if v_uid is not null then select full_name into v_name from public.profiles where id = v_uid; end if;
  if tg_op = 'INSERT' then
    insert into public.vehicle_reservation_events (organisation_id, country, reservation_id, event_type, to_status, actor_id, actor_name)
    values (new.organisation_id, new.country, new.id, 'created', new.status, v_uid, v_name);
    return new;
  end if;

  if new.rejected_at is distinct from old.rejected_at and new.rejected_at is not null then
    v_type := 'rejected';
  elsif new.status is distinct from old.status then
    v_type := case new.status when 'approved' then 'approved' when 'out' then 'checked_out' when 'returned' then 'returned' else 'status' end;
  end if;

  select array_agg(n.key order by n.key) into v_changed
  from jsonb_each(to_jsonb(new)) n
  join jsonb_each(to_jsonb(old)) o on o.key = n.key
  where n.value is distinct from o.value
    and n.key not in ('updated_at', 'status', 'approved_at', 'approved_by_id', 'rejected_at', 'rejected_by_id', 'actual_pickup_at', 'actual_return_at');

  if v_type is not null then
    insert into public.vehicle_reservation_events (organisation_id, country, reservation_id, event_type, from_status, to_status, detail, actor_id, actor_name)
    values (new.organisation_id, new.country, new.id, v_type, old.status, new.status,
      jsonb_strip_nulls(jsonb_build_object('reason', new.rejected_reason, 'odometer_out', case when v_type = 'checked_out' then new.odometer_out end,
        'odometer_in', case when v_type = 'returned' then new.odometer_in end, 'fields', to_jsonb(v_changed))),
      v_uid, v_name);
  elsif v_changed is not null then
    insert into public.vehicle_reservation_events (organisation_id, country, reservation_id, event_type, from_status, to_status, detail, actor_id, actor_name)
    values (new.organisation_id, new.country, new.id, 'edited', old.status, new.status, jsonb_build_object('fields', to_jsonb(v_changed)), v_uid, v_name);
  end if;
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.version_published_checklist_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status = 'published'
     and new.version = old.version
     and (
       new.name is distinct from old.name
       or new.description is distinct from old.description
       or new.category is distinct from old.category
       or new.country is distinct from old.country
       or new.require_signature is distinct from old.require_signature
       or new.require_approval is distinct from old.require_approval
       or new.require_area_manager is distinct from old.require_area_manager
       or new.scored is distinct from old.scored
       or new.pass_threshold is distinct from old.pass_threshold
       or new.assignee_roles is distinct from old.assignee_roles
       or new.doc_prefix is distinct from old.doc_prefix
       or new.min_interval_days is distinct from old.min_interval_days
       or new.name_i18n is distinct from old.name_i18n
       or new.description_i18n is distinct from old.description_i18n
       or new.option_sets is distinct from old.option_sets
       or new.fields is distinct from old.fields
     ) then
    new.version := old.version + 1;
  end if;
  return new;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.warranty_claim_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.claim_status := coalesce(nullif(btrim(new.claim_status), ''), 'Submitted');
  if new.claim_status not in ('Submitted','Under Review','Approved','Rejected','Credit Issued','Closed') then
    raise exception 'Unknown warranty claim status: %', new.claim_status using errcode = '23514';
  end if;
  if new.claim_status = 'Rejected' and nullif(btrim(coalesce(new.rejection_reason, '')), '') is null then
    raise exception 'A rejected claim needs the supplier''s rejection reason' using errcode = '23514';
  end if;
  if new.claim_status = 'Credit Issued' and (coalesce(new.credit_amount, 0) <= 0 or new.credit_date is null) then
    raise exception 'A credited claim needs the credit amount and the credit date' using errcode = '23514';
  end if;
  if new.claim_status in ('Approved','Rejected','Credit Issued') and new.decision_date is null then
    new.decision_date := current_date;
  end if;
  new.updated_at := now();
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.warranty_claim_log_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
begin
  if tg_op = 'UPDATE' and new.claim_status is not distinct from old.claim_status then
    return new;
  end if;
  select coalesce(nullif(btrim(p.full_name), ''), p.username)
    into v_name from public.profiles p where p.id = auth.uid();
  insert into public.warranty_claim_events
    (claim_id, organisation_id, from_status, to_status, note, changed_by, changed_by_name)
  values
    (new.id, new.organisation_id,
     case when tg_op = 'UPDATE' then old.claim_status end,
     new.claim_status,
     case when new.claim_status = 'Rejected' then new.rejection_reason
          when new.claim_status = 'Credit Issued' then 'Credit ' || new.credit_amount::text
          else null end,
     auth.uid(), v_name);
  return new;
exception when others then
  return new;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.wash_entry_people(p_ids uuid[])
 RETURNS TABLE(id uuid, full_name text, username text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select distinct p.id, p.full_name, p.username from public.profiles p
  join public.wash_records w on w.created_by = p.id and w.organisation_id = p.organisation_id
  where w.id = any(p_ids) and cardinality(p_ids) <= 500;
$function$;
