CREATE OR REPLACE FUNCTION public.wo_status_canonical(p_raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when btrim(coalesce(p_raw, '')) = '' then ''
    else coalesce(
      case regexp_replace(regexp_replace(regexp_replace(lower(btrim(coalesce(p_raw, ''))), '[\s\-/]+', '_', 'g'), '_+', '_', 'g'), '^_|_$', '', 'g')
        when 'new' then 'New' when 'open' then 'New'
        when 'created' then 'New' when 'raised' then 'New'
        when 'awaiting_assignment' then 'Awaiting Assignment'
        when 'unassigned' then 'Awaiting Assignment'
        when 'pending_assignment' then 'Awaiting Assignment'
        when 'assigned' then 'Assigned' when 'allocated' then 'Assigned'
        when 'in_progress' then 'In Progress' when 'inprogress' then 'In Progress'
        when 'started' then 'In Progress' when 'working' then 'In Progress'
        when 'wip' then 'In Progress'
        when 'waiting_for_parts' then 'Waiting for Parts'
        when 'waiting_parts' then 'Waiting for Parts'
        when 'awaiting_parts' then 'Waiting for Parts'
        when 'parts' then 'Waiting for Parts'
        when 'waiting_for_approval' then 'Waiting for Approval'
        when 'waiting_approval' then 'Waiting for Approval'
        when 'awaiting_approval' then 'Waiting for Approval'
        when 'pending_approval' then 'Waiting for Approval'
        when 'approval' then 'Waiting for Approval'
        when 'quality_inspection' then 'Quality Inspection'
        when 'qc' then 'Quality Inspection'
        when 'qc_inspection' then 'Quality Inspection'
        when 'quality_check' then 'Quality Inspection'
        when 'inspection' then 'Quality Inspection'
        when 'awaiting_inspection' then 'Quality Inspection'
        when 'completed' then 'Completed' when 'complete' then 'Completed'
        when 'done' then 'Completed' when 'closed' then 'Completed'
        when 'finished' then 'Completed'
        when 'overdue' then 'Overdue'
        when 'cancelled' then 'Cancelled' when 'canceled' then 'Cancelled'
        when 'void' then 'Cancelled' when 'voided' then 'Cancelled'
        when 'on_hold' then 'On Hold' when 'hold' then 'On Hold'
        when 'paused' then 'On Hold' when 'suspended' then 'On Hold'
        else null
      end,
      btrim(coalesce(p_raw, '')))
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.work_order_approval_context(p_work_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w work_orders; r approval_execution_requests; c jsonb; enabled boolean; can_start boolean;
BEGIN
 SELECT * INTO w FROM work_orders WHERE id=p_work_order_id AND organisation_id=app_current_org() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Work order unavailable' USING ERRCODE='42501'; END IF;
 PERFORM approval_private.assert_scope('work_order',w.organisation_id,w.country,w.site);
 enabled:=approval_private.enforced('work_order',w.organisation_id);
 SELECT * INTO r FROM approval_execution_requests WHERE work_order_id=w.id ORDER BY created_at DESC,id DESC LIMIT 1;
 enabled:=enabled OR r.id IS NOT NULL;
 IF r.id IS NOT NULL THEN c:=approval_review_context('work_order',r.id); END IF;
 can_start:=NOT enabled OR (r.approval_status='approved' AND r.approval_outcome='approved' AND approval_private.source_matches('work_order',r.source_snapshot,to_jsonb(w)));
 RETURN jsonb_build_object('mode',CASE WHEN enabled THEN 'enforced' ELSE 'legacy' END,'can_submit',approval_private.can_execute('work_order') AND w.started_at IS NULL AND lower(w.status) IN ('open','new','draft','pending') AND (r.id IS NULL OR r.approval_status='rejected' OR (r.approval_status='approved' AND NOT approval_private.source_matches('work_order',r.source_snapshot,to_jsonb(w)))),
 'can_execute',approval_private.can_execute('work_order') AND (coalesce(can_start,false) OR w.execution_approval_id IS NOT NULL OR (w.started_at IS NOT NULL AND w.execution_approval_id IS NULL)),
 'request_id',r.id,'review',c,'work_order',to_jsonb(w));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workflow_act(p_instance_id uuid, p_action text, p_comment text DEFAULT NULL::text, p_signature_data text DEFAULT NULL::text, p_printed_name text DEFAULT NULL::text, p_photo_urls text[] DEFAULT NULL::text[], p_gps jsonb DEFAULT NULL::jsonb, p_device_info jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst      public.workflow_instances%ROWTYPE;
  v_role      text;
  v_step      jsonb;
  v_next_idx  int;
  v_next      jsonb;
  v_prev_idx  int;
  v_step_user text;
BEGIN
  v_role := lower(regexp_replace(COALESCE(public.get_my_role(), ''), '\s+', '_', 'g'));
  IF v_role = '' THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  IF p_action NOT IN ('approve','reject','return') THEN
    RAISE EXCEPTION 'invalid action %', p_action;
  END IF;
  SELECT * INTO v_inst FROM public.workflow_instances
   WHERE id = p_instance_id FOR UPDATE;
  IF NOT FOUND OR v_inst.status NOT IN ('pending','in_review','returned') THEN
    RAISE EXCEPTION 'workflow instance not found or already completed';
  END IF;
  IF v_inst.organisation_id IS NOT NULL AND v_inst.organisation_id <> public.app_current_org() THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  v_step := v_inst.steps -> v_inst.current_step;
  v_step_user := v_step ->> 'approver_user_id';
  IF lower(COALESCE(v_step ->> 'assignee_type', 'role')) = 'user'
     AND COALESCE(v_step_user, '') <> '' THEN
    IF v_role <> 'admin' AND auth.uid()::text <> v_step_user THEN
      RAISE EXCEPTION 'this step is assigned to a specific user';
    END IF;
  ELSE
    IF v_role <> 'admin'
       AND v_role <> lower(regexp_replace(COALESCE(v_step ->> 'approver_role',''), '\s+', '_', 'g')) THEN
      RAISE EXCEPTION 'this step requires role %', v_step ->> 'approver_role';
    END IF;
  END IF;
  IF p_action = 'approve' THEN
    IF COALESCE((v_step ->> 'require_signature')::boolean, false)
       AND COALESCE(trim(p_signature_data), '') = '' THEN
      RAISE EXCEPTION 'signature is required for this step';
    END IF;
    IF COALESCE((v_step ->> 'require_photo')::boolean, false)
       AND (p_photo_urls IS NULL OR array_length(p_photo_urls, 1) IS NULL) THEN
      RAISE EXCEPTION 'at least one photo is required for this step';
    END IF;
    IF COALESCE((v_step ->> 'require_gps')::boolean, false)
       AND (p_gps IS NULL OR NOT (p_gps ? 'lat') OR NOT (p_gps ? 'lng')) THEN
      RAISE EXCEPTION 'GPS location is required for this step';
    END IF;
  END IF;
  IF p_action = 'return' THEN
    IF COALESCE((v_step ->> 'allow_return')::boolean, true) = false THEN
      RAISE EXCEPTION 'this step does not allow return';
    END IF;
    IF COALESCE(trim(p_comment), '') = '' THEN
      RAISE EXCEPTION 'a comment is required to return for correction';
    END IF;
    v_prev_idx := GREATEST(v_inst.current_step - 1, 0);
    INSERT INTO public.workflow_step_events
      (instance_id, organisation_id, step_index, step_name, action, actor_id,
       comment, signature_data, printed_name, photo_urls, gps, device_info)
    VALUES
      (v_inst.id, v_inst.organisation_id, v_inst.current_step, v_step ->> 'name',
       'returned', auth.uid(), p_comment, p_signature_data, p_printed_name,
       p_photo_urls, p_gps, p_device_info);
    UPDATE public.workflow_instances
       SET status = 'returned', current_step = v_prev_idx,
           returned_to_step = v_prev_idx, last_actor_id = auth.uid(), step_started_at = now()
     WHERE id = v_inst.id;
    IF v_inst.started_by IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
      VALUES (v_inst.started_by, 'approval',
              'Returned for correction: ' || v_inst.definition_name,
              COALESCE(v_inst.entity_label, v_inst.entity_type) ||
                ' was returned at step "' || (v_step ->> 'name') || '": ' || p_comment,
              'workflow', v_inst.id);
    END IF;
    PERFORM public.emit_domain_event('workflow.returned', 'workflow_instance', v_inst.id::text,
      jsonb_build_object('definition', v_inst.definition_name, 'step', v_step ->> 'name',
                         'returned_to_step', v_prev_idx, 'comment', p_comment,
                         'entity_type', v_inst.entity_type, 'entity_id', v_inst.entity_id),
      v_inst.organisation_id, auth.uid());
    RETURN jsonb_build_object('status', 'returned', 'current_step', v_prev_idx);
  END IF;
  INSERT INTO public.workflow_step_events
    (instance_id, organisation_id, step_index, step_name, action, actor_id,
     comment, signature_data, printed_name, photo_urls, gps, device_info)
  VALUES
    (v_inst.id, v_inst.organisation_id, v_inst.current_step, v_step ->> 'name',
     CASE p_action WHEN 'approve' THEN 'approved' ELSE 'rejected' END, auth.uid(),
     p_comment, p_signature_data, p_printed_name, p_photo_urls, p_gps, p_device_info);
  IF p_action = 'reject' THEN
    UPDATE public.workflow_instances
       SET status = 'rejected', completed_at = now(), last_actor_id = auth.uid()
     WHERE id = v_inst.id;
    IF v_inst.started_by IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
      VALUES (v_inst.started_by, 'approval',
              'Rejected: ' || v_inst.definition_name,
              COALESCE(v_inst.entity_label, v_inst.entity_type) || ' was rejected at step "' ||
                (v_step ->> 'name') || '"' || COALESCE(': ' || p_comment, '.'),
              'workflow', v_inst.id);
    END IF;
    PERFORM public.emit_domain_event('workflow.rejected', 'workflow_instance', v_inst.id::text,
      jsonb_build_object('definition', v_inst.definition_name, 'step', v_step ->> 'name',
                         'comment', p_comment, 'entity_type', v_inst.entity_type,
                         'entity_id', v_inst.entity_id),
      v_inst.organisation_id, auth.uid());
    RETURN jsonb_build_object('status', 'rejected');
  END IF;
  v_next_idx := public._workflow_next_runnable_step(v_inst.steps, v_inst.current_step, v_inst.context);
  IF v_next_idx IS NULL THEN
    UPDATE public.workflow_instances
       SET status = 'approved', completed_at = now(), last_actor_id = auth.uid()
     WHERE id = v_inst.id;
    IF v_inst.started_by IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
      VALUES (v_inst.started_by, 'approval',
              'Approved: ' || v_inst.definition_name,
              COALESCE(v_inst.entity_label, v_inst.entity_type) || ' completed all approval steps.',
              'workflow', v_inst.id);
    END IF;
    PERFORM public.emit_domain_event('workflow.approved', 'workflow_instance', v_inst.id::text,
      jsonb_build_object('definition', v_inst.definition_name, 'entity_type', v_inst.entity_type,
                         'entity_id', v_inst.entity_id),
      v_inst.organisation_id, auth.uid());
    RETURN jsonb_build_object('status', 'approved');
  END IF;
  v_next := v_inst.steps -> v_next_idx;
  UPDATE public.workflow_instances
     SET current_step = v_next_idx, step_started_at = now(),
         status = 'in_review', last_actor_id = auth.uid()
   WHERE id = v_inst.id;
  INSERT INTO public.workflow_step_events
    (instance_id, organisation_id, step_index, step_name, action, actor_id)
  VALUES
    (v_inst.id, v_inst.organisation_id, v_next_idx, v_next ->> 'name', 'started', auth.uid());
  IF lower(COALESCE(v_next ->> 'assignee_type','role')) = 'user'
     AND COALESCE(v_next ->> 'approver_user_id','') <> '' THEN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    VALUES ((v_next ->> 'approver_user_id')::uuid, 'approval',
            'Approval required: ' || v_inst.definition_name,
            COALESCE(v_inst.entity_label, v_inst.entity_type) ||
              ' advanced to step "' || (v_next ->> 'name') || '".',
            'workflow', v_inst.id);
  ELSE
    PERFORM public.notify_role_in_org(
      regexp_replace(COALESCE(v_next ->> 'approver_role',''), '\s+', '_', 'g'),
      v_inst.organisation_id, 'approval',
      'Approval required: ' || v_inst.definition_name,
      COALESCE(v_inst.entity_label, v_inst.entity_type) || ' advanced to step "' ||
        (v_next ->> 'name') || '".',
      'workflow', v_inst.id);
  END IF;
  PERFORM public.emit_domain_event('workflow.step_advanced', 'workflow_instance', v_inst.id::text,
    jsonb_build_object('definition', v_inst.definition_name, 'step', v_next ->> 'name',
                       'step_index', v_next_idx),
    v_inst.organisation_id, auth.uid());
  RETURN jsonb_build_object('status', 'in_review', 'current_step', v_next_idx,
                            'step', v_next ->> 'name');
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workflow_act(p_instance_id uuid, p_action text, p_comment text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.workflow_act(p_instance_id, p_action, p_comment,
                             NULL, NULL, NULL::text[], NULL::jsonb, NULL::jsonb);
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workflow_cancel(p_instance_id uuid, p_comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.workflow_instances%ROWTYPE;
  v_role text := lower(regexp_replace(COALESCE(public.get_my_role(), ''), '\s+', '_', 'g'));
BEGIN
  SELECT * INTO v_inst FROM public.workflow_instances WHERE id = p_instance_id FOR UPDATE;
  IF NOT FOUND OR v_inst.status <> 'pending' THEN
    RAISE EXCEPTION 'workflow instance not found or already completed';
  END IF;
  IF v_role <> 'admin' AND v_inst.started_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'only the initiator or an admin can cancel';
  END IF;
  IF v_inst.organisation_id IS NOT NULL AND v_inst.organisation_id <> public.app_current_org() THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  UPDATE public.workflow_instances SET status = 'cancelled', completed_at = now() WHERE id = v_inst.id;
  INSERT INTO public.workflow_step_events
    (instance_id, organisation_id, step_index, step_name, action, actor_id, comment)
  VALUES
    (v_inst.id, v_inst.organisation_id, v_inst.current_step,
     v_inst.steps -> v_inst.current_step ->> 'name', 'cancelled', auth.uid(), p_comment);
  PERFORM public.emit_domain_event('workflow.cancelled', 'workflow_instance', v_inst.id::text,
    jsonb_build_object('definition', v_inst.definition_name, 'comment', p_comment),
    v_inst.organisation_id, auth.uid());
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workflow_step_condition_passes(p_step jsonb, p_context jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cond   jsonb;
  v_field  text;
  v_op     text;
  v_raw    jsonb;
  v_actual jsonb;
  v_a_num  numeric;
  v_e_num  numeric;
  v_numeric boolean;
BEGIN
  IF p_step IS NULL OR NOT (p_step ? 'condition')
     OR jsonb_typeof(p_step -> 'condition') <> 'object' THEN
    RETURN true;
  END IF;
  v_cond  := p_step -> 'condition';
  v_field := v_cond ->> 'field';
  v_op    := v_cond ->> 'op';
  v_raw   := v_cond -> 'value';
  IF v_field IS NULL OR v_op IS NULL THEN
    RETURN true;
  END IF;
  IF p_context IS NULL OR NOT (p_context ? v_field)
     OR jsonb_typeof(p_context -> v_field) = 'null' THEN
    RETURN false;
  END IF;
  v_actual := p_context -> v_field;
  v_numeric := (v_actual ->> 0 IS NOT NULL);
  BEGIN
    v_a_num := (v_actual #>> '{}')::numeric;
    v_e_num := (v_raw    #>> '{}')::numeric;
    v_numeric := true;
  EXCEPTION WHEN others THEN
    v_numeric := false;
  END;
  IF v_numeric THEN
    RETURN CASE v_op
      WHEN '='  THEN v_a_num =  v_e_num
      WHEN '!=' THEN v_a_num <> v_e_num
      WHEN '>'  THEN v_a_num >  v_e_num
      WHEN '>=' THEN v_a_num >= v_e_num
      WHEN '<'  THEN v_a_num <  v_e_num
      WHEN '<=' THEN v_a_num <= v_e_num
      ELSE false
    END;
  ELSE
    RETURN CASE v_op
      WHEN '='  THEN (v_actual #>> '{}') =  (v_raw #>> '{}')
      WHEN '!=' THEN (v_actual #>> '{}') <> (v_raw #>> '{}')
      WHEN '>'  THEN (v_actual #>> '{}') >  (v_raw #>> '{}')
      WHEN '>=' THEN (v_actual #>> '{}') >= (v_raw #>> '{}')
      WHEN '<'  THEN (v_actual #>> '{}') <  (v_raw #>> '{}')
      WHEN '<=' THEN (v_actual #>> '{}') <= (v_raw #>> '{}')
      ELSE false
    END;
  END IF;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workforce_assignment_classify()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
 NEW.task_type=nullif(lower(regexp_replace(btrim(NEW.task_type),'\s+',' ','g')),'');
 NEW.vehicle_type=nullif(upper(regexp_replace(btrim(NEW.vehicle_type),'\s+',' ','g')),'');
 IF TG_OP='INSERT' THEN
   NEW.assignee_role=coalesce(nullif(btrim(NEW.assignee_role),''),(SELECT p.role FROM public.profiles p WHERE p.id=NEW.assigned_to));
 END IF;
 RETURN NEW;
END $function$;
