CREATE OR REPLACE FUNCTION public.workforce_cert_normalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.cert_type:=lower(regexp_replace(btrim(NEW.cert_type),'\s+',' ','g')); RETURN NEW; END $function$;
