CREATE OR REPLACE FUNCTION public.workforce_correct_daily_entry(p_entry_id uuid, p_patch jsonb, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_uid uuid := auth.uid(); v_org uuid := public.app_current_org();
 v_key text := btrim(coalesce(p_idempotency_key,'')); v_reason text := btrim(coalesce(p_reason,''));
 e public.workforce_daily_entries; r public.workforce_daily_reports; prior public.workforce_daily_entry_corrections;
 v_allowed text[] := ARRAY['title','details','deliverable','category','started_at','ended_at','blocked_reason','assignment_id'];
 v_bad text; v_new jsonb; v_id uuid; v_out public.workforce_daily_entries;
BEGIN
 IF v_uid IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'Sign in required' USING ERRCODE='42501'; END IF;
 IF char_length(v_key) NOT BETWEEN 8 AND 100 THEN
   RAISE EXCEPTION 'A valid idempotency key is required' USING ERRCODE='22023'; END IF;

 SELECT * INTO prior FROM public.workforce_daily_entry_corrections WHERE corrected_by=v_uid AND idempotency_key=v_key;
 IF FOUND THEN
   IF prior.entry_id IS DISTINCT FROM p_entry_id OR prior.patch IS DISTINCT FROM coalesce(p_patch,'{}'::jsonb) THEN
     RAISE EXCEPTION 'Idempotency key already used for a different correction' USING ERRCODE='22023'; END IF;
   RETURN jsonb_build_object('ok',true,'replayed',true,'correction_id',prior.id,'entry_id',prior.entry_id,
     'original',prior.original,'corrected',prior.corrected);
 END IF;

 IF NOT public.workforce_is_manager() THEN
   RAISE EXCEPTION 'Only a manager can correct recorded activity' USING ERRCODE='42501'; END IF;
 IF char_length(v_reason) NOT BETWEEN 5 AND 1000 THEN
   RAISE EXCEPTION 'A correction reason is required' USING ERRCODE='22023'; END IF;
 IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR p_patch='{}'::jsonb THEN
   RAISE EXCEPTION 'Nothing to correct' USING ERRCODE='22023'; END IF;
 SELECT k INTO v_bad FROM jsonb_object_keys(p_patch) k WHERE k <> ALL(v_allowed) LIMIT 1;
 IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'Field cannot be corrected: %', v_bad USING ERRCODE='22023'; END IF;

 SELECT * INTO e FROM public.workforce_daily_entries WHERE id=p_entry_id AND organisation_id=v_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Activity not found' USING ERRCODE='42501'; END IF;
 IF e.employee_id=v_uid THEN
   RAISE EXCEPTION 'You cannot correct your own recorded activity' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.workforce_daily_reports WHERE id=e.report_id FOR UPDATE;
 IF r.status NOT IN ('submitted','returned') THEN
   RAISE EXCEPTION 'Only submitted or returned reports can be corrected' USING ERRCODE='42501'; END IF;

 v_new := to_jsonb(e) || p_patch;
 INSERT INTO public.workforce_daily_entry_corrections(organisation_id,entry_id,report_id,employee_id,original,patch,corrected,
   reason,corrected_by,idempotency_key)
 VALUES (e.organisation_id,e.id,e.report_id,e.employee_id,to_jsonb(e),p_patch,v_new,v_reason,v_uid,v_key)
 RETURNING id INTO v_id;

 UPDATE public.workforce_daily_entries SET
   title = CASE WHEN p_patch ? 'title' THEN btrim(p_patch->>'title') ELSE title END,
   details = CASE WHEN p_patch ? 'details' THEN coalesce(p_patch->>'details','') ELSE details END,
   deliverable = CASE WHEN p_patch ? 'deliverable' THEN p_patch->>'deliverable' ELSE deliverable END,
   category = CASE WHEN p_patch ? 'category' THEN p_patch->>'category' ELSE category END,
   started_at = CASE WHEN p_patch ? 'started_at' THEN (p_patch->>'started_at')::timestamptz ELSE started_at END,
   ended_at = CASE WHEN p_patch ? 'ended_at' THEN (p_patch->>'ended_at')::timestamptz ELSE ended_at END,
   blocked_reason = CASE WHEN p_patch ? 'blocked_reason' THEN p_patch->>'blocked_reason' ELSE blocked_reason END,
   assignment_id = CASE WHEN p_patch ? 'assignment_id' THEN (p_patch->>'assignment_id')::uuid ELSE assignment_id END,
   correction_count = correction_count+1, last_corrected_at = now(), last_corrected_by = v_uid
 WHERE id=e.id RETURNING * INTO v_out;

 RETURN jsonb_build_object('ok',true,'replayed',false,'correction_id',v_id,'entry_id',e.id,
   'original',to_jsonb(e),'corrected',to_jsonb(v_out));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workforce_duration_estimate(p_task_type text, p_vehicle_type text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_min_minutes numeric DEFAULT 1, p_max_minutes numeric DEFAULT 10080)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE t text; v text; r text; tiers jsonb;
BEGIN
 IF NOT public.workforce_is_manager() THEN RAISE EXCEPTION 'Managers only' USING ERRCODE='42501'; END IF;
 t:=nullif(lower(regexp_replace(btrim(p_task_type),'\s+',' ','g')),'');
 v:=nullif(upper(regexp_replace(btrim(p_vehicle_type),'\s+',' ','g')),'');
 r:=nullif(btrim(p_role),'');
 IF t IS NULL THEN
   RETURN jsonb_build_object('task_type',NULL,'vehicle_type',v,'role',r,'min_minutes',p_min_minutes,'max_minutes',p_max_minutes,'tiers','[]'::jsonb);
 END IF;
 WITH base AS (
   SELECT d.active_minutes::float8 AS m,d.vehicle_type AS vt,d.assignee_role AS ar
   FROM public.workforce_assignment_durations d
   WHERE d.task_type=t AND d.active_minutes BETWEEN p_min_minutes AND p_max_minutes
 ), tiers(tier,use_v,use_r,ord) AS (
   VALUES ('task_vehicle_role',true,true,1),('task_vehicle',true,false,2),('task_role',false,true,3),('task',false,false,4)
 )
 SELECT jsonb_agg(jsonb_build_object('tier',s.tier,'n',s.n,'p25',s.p25,'median',s.med,'p75',s.p75,'p90',s.p90) ORDER BY s.ord) INTO tiers
 FROM (
   SELECT tr.tier,tr.ord,count(b.m) AS n,
          round((percentile_cont(0.25) WITHIN GROUP (ORDER BY b.m))::numeric,1) AS p25,
          round((percentile_cont(0.5)  WITHIN GROUP (ORDER BY b.m))::numeric,1) AS med,
          round((percentile_cont(0.75) WITHIN GROUP (ORDER BY b.m))::numeric,1) AS p75,
          round((percentile_cont(0.9)  WITHIN GROUP (ORDER BY b.m))::numeric,1) AS p90
   FROM tiers tr LEFT JOIN base b
     ON (NOT tr.use_v OR (v IS NOT NULL AND b.vt=v)) AND (NOT tr.use_r OR (r IS NOT NULL AND b.ar=r))
   GROUP BY tr.tier,tr.ord
 ) s;
 RETURN jsonb_build_object('task_type',t,'vehicle_type',v,'role',r,'min_minutes',p_min_minutes,'max_minutes',p_max_minutes,'tiers',coalesce(tiers,'[]'::jsonb));
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workforce_employee_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cur uuid; v_depth int:=0;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.profile_id AND p.organisation_id=NEW.organisation_id) THEN
   RAISE EXCEPTION 'Employee must belong to this organisation' USING ERRCODE='42501'; END IF;
 IF NEW.supervisor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.supervisor_id AND p.organisation_id=NEW.organisation_id) THEN
   RAISE EXCEPTION 'Supervisor must belong to this organisation' USING ERRCODE='42501'; END IF;
 v_cur:=NEW.supervisor_id;
 WHILE v_cur IS NOT NULL AND v_depth<50 LOOP
   IF v_cur=NEW.profile_id THEN RAISE EXCEPTION 'This supervisor would create a reporting loop' USING ERRCODE='23514'; END IF;
   SELECT e.supervisor_id INTO v_cur FROM public.workforce_employees e WHERE e.profile_id=v_cur;
   v_depth:=v_depth+1;
 END LOOP;
 NEW.sites:=ARRAY(SELECT DISTINCT upper(btrim(s)) FROM unnest(coalesce(NEW.sites,'{}')) s WHERE nullif(btrim(s),'') IS NOT NULL ORDER BY 1);
 NEW.designation:=btrim(NEW.designation);
 IF NEW.employment_status<>'temporarily_unavailable' THEN NEW.unavailable_until:=NULL; END IF;
 IF TG_OP='UPDATE' THEN
   IF NEW.organisation_id IS DISTINCT FROM OLD.organisation_id OR NEW.profile_id IS DISTINCT FROM OLD.profile_id THEN
     RAISE EXCEPTION 'Employee identity is immutable' USING ERRCODE='42501'; END IF;
   NEW.updated_at:=now(); NEW.updated_by:=auth.uid();
 END IF;
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workforce_employee_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 INSERT INTO public.workforce_employee_history(organisation_id,profile_id,changed_by,old_values,new_values)
 VALUES(NEW.organisation_id,NEW.profile_id,auth.uid(),
  CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD)-'updated_at'-'updated_by' END, to_jsonb(NEW)-'updated_at'-'updated_by');
 RETURN NULL;
END $function$;
