CREATE OR REPLACE FUNCTION public.workforce_task_type_normalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
 NEW.task_type:=lower(regexp_replace(btrim(NEW.task_type),'\s+',' ','g'));
 NEW.required_cert_type:=nullif(lower(regexp_replace(btrim(NEW.required_cert_type),'\s+',' ','g')),'');
 NEW.required_skill_id:=nullif(btrim(NEW.required_skill_id),'');
 RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workforce_team_analytics(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_site text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
 WITH w AS (
  SELECT a.* FROM public.workforce_assignments a
  WHERE (p_from IS NULL OR a.created_at>=p_from) AND (p_to IS NULL OR a.created_at<p_to+1)
    AND (nullif(btrim(p_site),'') IS NULL OR upper(btrim(a.site))=upper(btrim(p_site)))),
 e AS (SELECT ev.* FROM public.workforce_assignment_events ev JOIN w ON w.id=ev.assignment_id),
 blk AS (
  SELECT b.assignment_id, coalesce(b.reason_code,'not_recorded') AS reason, b.effective_at AS start_at,
         nx.effective_at AS end_at, w.status AS cur_status
  FROM e b JOIN w ON w.id=b.assignment_id
  LEFT JOIN LATERAL (
    SELECT x.effective_at FROM e x
    WHERE x.assignment_id=b.assignment_id AND x.to_status<>'blocked'
      AND (x.effective_at,x.occurred_at,x.id)>(b.effective_at,b.occurred_at,b.id)
    ORDER BY x.effective_at,x.occurred_at,x.id LIMIT 1) nx ON true
  WHERE b.action='block'),
 blk2 AS (
  SELECT assignment_id, reason,
         CASE WHEN end_at IS NOT NULL THEN 'closed' WHEN cur_status='blocked' THEN 'open' ELSE 'unmeasured' END AS state,
         CASE WHEN end_at IS NOT NULL THEN extract(epoch FROM (end_at-start_at))/60.0
              WHEN cur_status='blocked' THEN greatest(0,extract(epoch FROM (now()-start_at))/60.0) END AS minutes
  FROM blk),
 f AS (
  SELECT w.id, w.assigned_to, nullif(upper(btrim(w.site)),'') AS site_key, w.status,
         (w.due_at<now() AND w.status NOT IN ('verified','cancelled')) AS overdue_open,
         (w.status='verified' AND w.operational_record_id IS NOT NULL) AS verified_with_record,
         (w.status='verified' AND w.operational_record_table IS NOT NULL AND w.operational_record_id IS NULL) AS verified_missing_record,
         (w.override_reason IS NOT NULL) AS overridden,
         w.estimated_minutes::float8 AS est,
         CASE WHEN w.status='verified' THEN d.active_minutes::float8 END AS act,
         (SELECT count(*) FROM e WHERE e.assignment_id=w.id AND e.action='return') AS returns,
         (SELECT count(*) FROM e WHERE e.assignment_id=w.id AND e.action='reassign') AS reassigns,
         (SELECT sum(minutes) FROM blk2 WHERE blk2.assignment_id=w.id AND state='closed') AS blocked_closed_minutes
  FROM w LEFT JOIN public.workforce_assignment_durations d ON d.assignment_id=w.id),
 g AS (
  SELECT grp, key_profile, key_site,
   count(*) AS assigned,
   count(*) FILTER (WHERE status IN ('assigned','acknowledged')) AS awaiting_start,
   count(*) FILTER (WHERE status='in_progress') AS active,
   count(*) FILTER (WHERE status='blocked') AS blocked,
   count(*) FILTER (WHERE status='submitted') AS submitted,
   count(*) FILTER (WHERE status='verified') AS verified,
   count(*) FILTER (WHERE status='cancelled') AS cancelled,
   count(*) FILTER (WHERE overdue_open) AS overdue_open,
   sum(returns) AS rework_returns,
   count(*) FILTER (WHERE verified_with_record) AS verified_with_record,
   count(*) FILTER (WHERE verified_missing_record) AS verified_missing_record,
   count(*) FILTER (WHERE overridden) AS override_count,
   sum(reassigns) AS reassignments,
   count(act) AS timed_n,
   count(*) FILTER (WHERE status='verified' AND act IS NULL) AS verified_untimed,
   round(avg(act)::numeric,1) AS avg_active_minutes,
   round((percentile_cont(0.5) WITHIN GROUP (ORDER BY act))::numeric,1) AS median_active_minutes,
   count(*) FILTER (WHERE act IS NOT NULL AND est IS NOT NULL) AS est_n,
   sum(est) FILTER (WHERE act IS NOT NULL AND est IS NOT NULL) AS est_sum,
   sum(act) FILTER (WHERE act IS NOT NULL AND est IS NOT NULL) AS act_sum,
   sum(blocked_closed_minutes) AS blocked_closed_minutes
  FROM (
    SELECT 'employee' AS grp, f.assigned_to AS key_profile, NULL::text AS key_site, f.* FROM f
    UNION ALL SELECT 'site', NULL::uuid, f.site_key, f.* FROM f
    UNION ALL SELECT 'all', NULL::uuid, NULL::text, f.* FROM f) x
  GROUP BY grp, key_profile, key_site),
 gj AS (
  SELECT grp, key_profile, key_site, assigned, jsonb_build_object(
   'assigned',assigned,'awaiting_start',awaiting_start,'active',active,'blocked',blocked,'submitted',submitted,
   'verified',verified,'cancelled',cancelled,'overdue_open',overdue_open,'rework_returns',rework_returns,
   'rework_rate',CASE WHEN verified+rework_returns>0 THEN round(rework_returns::numeric/(verified+rework_returns),4) END,
   'verified_with_record',verified_with_record,'verified_missing_record',verified_missing_record,
   'override_count',override_count,'reassignments',reassignments,
   'timed_verified',timed_n,'verified_untimed',verified_untimed,
   'avg_active_minutes',avg_active_minutes,'median_active_minutes',median_active_minutes,
   'estimate_vs_actual',jsonb_build_object('n',est_n,
      'estimated_minutes',CASE WHEN est_n>0 THEN round(est_sum::numeric,1) END,
      'actual_minutes',CASE WHEN est_n>0 THEN round(act_sum::numeric,1) END,
      'actual_to_estimate',CASE WHEN est_n>0 AND est_sum>0 THEN round((act_sum/est_sum)::numeric,3) END),
   'blocked_minutes_closed',CASE WHEN blocked_closed_minutes IS NOT NULL THEN round(blocked_closed_minutes::numeric,1) END) AS j
  FROM g),
 q AS (
  SELECT a.id, coalesce((SELECT max(x.effective_at) FROM public.workforce_assignment_events x WHERE x.assignment_id=a.id AND x.action='complete'),a.updated_at) AS submitted_at,
         NOT EXISTS(SELECT 1 FROM public.workforce_assignment_events x WHERE x.assignment_id=a.id AND x.action='complete') AS fallback
  FROM public.workforce_assignments a
  WHERE a.status='submitted' AND (nullif(btrim(p_site),'') IS NULL OR upper(btrim(a.site))=upper(btrim(p_site))))
 SELECT jsonb_build_object(
  'window',jsonb_build_object('from',p_from,'to',p_to,'site',nullif(upper(btrim(p_site)),''),'basis','assignment created_at'),
  'totals',coalesce((SELECT j FROM gj WHERE grp='all'),jsonb_build_object('assigned',0)),
  'per_employee',coalesce((SELECT jsonb_agg(j||jsonb_build_object('profile_id',key_profile) ORDER BY assigned DESC,key_profile) FROM gj WHERE grp='employee'),'[]'::jsonb),
  'per_site',coalesce((SELECT jsonb_agg(j||jsonb_build_object('site',key_site) ORDER BY assigned DESC,key_site NULLS LAST) FROM gj WHERE grp='site'),'[]'::jsonb),
  'blocker_minutes_by_reason',coalesce((SELECT jsonb_agg(jsonb_build_object('reason',reason,
      'episodes',n,'closed_episodes',nc,'closed_minutes',CASE WHEN nc>0 THEN round(cm::numeric,1) END,
      'open_episodes',no,'open_minutes',CASE WHEN no>0 THEN round(om::numeric,1) END,
      'unmeasured_episodes',nu) ORDER BY coalesce(cm,0)+coalesce(om,0) DESC, reason)
    FROM (SELECT reason,count(*) n,count(*) FILTER (WHERE state='closed') nc,sum(minutes) FILTER (WHERE state='closed') cm,
                 count(*) FILTER (WHERE state='open') no,sum(minutes) FILTER (WHERE state='open') om,
                 count(*) FILTER (WHERE state='unmeasured') nu
          FROM blk2 GROUP BY reason) r),'[]'::jsonb),
  'rework_rate',(SELECT j->'rework_rate' FROM gj WHERE grp='all'),
  'verification_queue',jsonb_build_object('scope','current_all_dates','count',(SELECT count(*) FROM q),
      'oldest_age_hours',(SELECT round((extract(epoch FROM (now()-min(submitted_at)))/3600.0)::numeric,1) FROM q),
      'aged_from_last_update',(SELECT count(*) FROM q WHERE fallback)),
  'reassignments',(SELECT count(*) FROM e WHERE action='reassign'),
  'override_count',(SELECT count(*) FROM w WHERE override_reason IS NOT NULL),
  'coverage',jsonb_build_object(
      'assignments',(SELECT count(*) FROM w),
      'verified',(SELECT count(*) FROM f WHERE status='verified'),
      'verified_timed',(SELECT count(act) FROM f),
      'verified_untimed',(SELECT count(*) FROM f WHERE status='verified' AND act IS NULL),
      'estimate_pairs',(SELECT count(*) FROM f WHERE act IS NOT NULL AND est IS NOT NULL),
      'events',(SELECT count(*) FROM e)),
  'data_freshness',jsonb_build_object('latest_change',(SELECT max(updated_at) FROM w),
      'latest_event',(SELECT max(occurred_at) FROM e),'generated_at',now()))
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_actor_name()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(nullif(btrim(full_name), ''), nullif(btrim(username), ''), 'System')
    from public.profiles where id = auth.uid()
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_asset_key(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(upper(regexp_replace(coalesce(p, ''), '\s', '', 'g')), '')
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_asset_list(p_assets text[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(cardinality(p_assets), 0) = 0 then ''
    when cardinality(p_assets) <= 5 then array_to_string(p_assets, ', ')
    else array_to_string(p_assets[1:5], ', ') || ' and ' || (cardinality(p_assets) - 5)::text || ' more'
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_attachment_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if TG_OP = 'INSERT' then
    NEW.uploaded_by := auth.uid();
    NEW.uploaded_by_name := coalesce(public.workshop_status_actor_name(), 'System');
    NEW.uploaded_at := now();
    NEW.deleted_at := null; NEW.deleted_by := null;
    select r.organisation_id, r.country, r.site, r.asset_no
      into NEW.organisation_id, NEW.country, NEW.site, NEW.asset_no
      from public.workshop_status_records r where r.id = NEW.record_id;
    if NEW.country is null then
      raise exception 'Attachment must belong to a workshop record' using errcode = '23503';
    end if;
    return NEW;
  end if;
  NEW.uploaded_by := OLD.uploaded_by;
  NEW.uploaded_by_name := OLD.uploaded_by_name;
  NEW.uploaded_at := OLD.uploaded_at;
  NEW.record_id := OLD.record_id;
  NEW.organisation_id := OLD.organisation_id;
  NEW.country := OLD.country;
  NEW.storage_path := OLD.storage_path;
  if NEW.deleted_at is distinct from OLD.deleted_at then
    NEW.deleted_by := case when NEW.deleted_at is null then null else auth.uid() end;
    if NEW.deleted_at is not null then NEW.deleted_at := now(); end if;
  else
    NEW.deleted_by := OLD.deleted_by;
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_breakdown_for(p_org uuid, p_country text, p_asset text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when count(*) = 1 then (array_agg(b.id))[1] end
    from public.asset_breakdowns b
   where b.organisation_id = p_org
     and b.country is not distinct from p_country
     and upper(regexp_replace(b.asset_no, '\s', '', 'g')) = upper(regexp_replace(p_asset, '\s', '', 'g'))
     and coalesce(b.returned_to_service, false) = false
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_can(p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := lower(btrim(coalesce(p_action, '')));
begin
  if not coalesce(public.app_is_active(), false) then return false; end if;
  if not (v_action = any (array[
      'view', 'view_removed', 'view_uploads', 'view_activity', 'view_reports', 'view_audit',
      'update', 'upload', 'confirm', 'assign', 'disposition', 'export',
      'archive', 'restore', 'soft_delete', 'configure', 'permanent_delete'])) then
    return false;
  end if;
  if coalesce(public.is_super_admin(), false) then return true; end if;
  if v_action = 'permanent_delete' then return false; end if;
  if v_action = 'view' then return coalesce(public.workshop_status_can_view(), false); end if;
  -- Loop 17: a daily file is country-wide, so staging or confirming one needs the whole site scope.
  if v_action in ('upload', 'confirm')
     and not coalesce(public.app_sees_all_sites(), false) then
    return false;
  end if;
  return coalesce(public.workshop_status_can_view(), false)
     and coalesce(public.app_user_can('daily_ops:workshop:' || v_action, 'view'), false);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_can_view()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(public.app_is_active(), false)
     and (public.is_super_admin() or public.app_user_can('daily_ops:workshop', 'view'))
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_cancel_upload(p_upload_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_up public.workshop_status_uploads%rowtype;
begin
  if not (coalesce(public.workshop_status_can('upload'), false) or coalesce(public.workshop_status_can('confirm'), false)) then
    raise exception 'You do not have permission to cancel a workshop upload' using errcode = '42501';
  end if;
  select * into v_up from public.workshop_status_uploads where id = p_upload_id for update;
  if not found or v_org is null or v_up.organisation_id <> v_org then
    raise exception 'Upload not found' using errcode = 'P0002';
  end if;
  if v_up.status <> 'previewed' then
    raise exception 'upload_not_previewed: this upload is % and cannot be cancelled', v_up.status
      using errcode = 'P0001';
  end if;
  if not coalesce(public.is_super_admin(), false)
     and public.app_can_see_country(v_up.country) is false then
    raise exception 'You do not have access to the workshop report of this country' using errcode = '42501';
  end if;
  perform set_config('workshop.source', 'excel', true);
  perform set_config('workshop.upload_id', v_up.id::text, true);
  update public.workshop_status_uploads set status = 'cancelled' where id = v_up.id;
  insert into public.workshop_status_events (organisation_id, country, upload_id, event_type, source, details)
  values (v_org, v_up.country, v_up.id, 'upload_cancelled', 'excel',
          jsonb_build_object('file_name', v_up.file_name));
  return jsonb_build_object('upload_id', v_up.id, 'status', 'cancelled');
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_cmp(p_field text, p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_value is null then null
    when p_field = 'site' then
      nullif(btrim(regexp_replace(upper(btrim(regexp_replace(replace(p_value, chr(160), ' '), '\s+', ' ', 'g'))),
                                  '[-_]ST$', '')), '')
    else nullif(lower(btrim(regexp_replace(replace(p_value, chr(160), ' '), '\s+', ' ', 'g'))), '')
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_confirm_upload(p_upload_id uuid, p_acknowledge_duplicate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_up public.workshop_status_uploads%rowtype;
  v_country text;
  v_prior text[];
  v_active text[] := '{}';
  v_closed text[];
  s record;
  r public.workshop_status_records%rowtype;
  v_data jsonb;
  v_reg text; v_jc text; v_cat text; v_site text; v_dept text; v_comp text; v_diag text;
  v_ooc date; v_days integer; v_etr text; v_note text; v_rem text;
  v_changed boolean;
  v_fields text[];
  v_vehicle uuid;
  v_new_id uuid;
  v_reason text;
  v_closed_row jsonb;
  v_new_ids uuid[] := '{}'; v_upd_ids uuid[] := '{}'; v_same_ids uuid[] := '{}'; v_rem_ids uuid[] := '{}';
  v_n_closed integer; v_n_invalid integer; v_n_dup integer; v_n_prev integer; v_n_after integer;
  v_summary jsonb;
  v_kept_ids uuid[] := '{}';
begin
  if not coalesce(public.workshop_status_can('confirm'), false) then
    raise exception 'You do not have permission to confirm the workshop report' using errcode = '42501';
  end if;

  select * into v_up from public.workshop_status_uploads where id = p_upload_id for update;
  if not found or v_org is null or v_up.organisation_id <> v_org then
    raise exception 'Upload not found' using errcode = 'P0002';
  end if;
  if v_up.status <> 'previewed' then
    raise exception 'upload_not_previewed: this upload is % and cannot be confirmed', v_up.status
      using errcode = 'P0001';
  end if;
  v_country := v_up.country;
  if not coalesce(public.is_super_admin(), false)
     and public.app_can_see_country(v_country) is false then
    raise exception 'You do not have access to the workshop report of this country' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtext('workshop_status:' || v_org::text || ':' || v_country));

  if v_up.duplicate_of_upload_id is not null and not coalesce(p_acknowledge_duplicate, false) then
    raise exception 'duplicate_file: this file was already uploaded' using errcode = 'P0001';
  end if;

  if exists (select 1 from public.workshop_status_uploads u
              where u.organisation_id = v_org and u.country = v_country and u.id <> v_up.id
                and u.status = 'confirmed' and u.confirmed_at > v_up.uploaded_at) then
    raise exception 'stale_preview: another upload for this country was confirmed after this preview'
      using errcode = 'P0001';
  end if;

  if v_up.report_date is not null and exists (
       select 1 from public.workshop_status_uploads u
        where u.organisation_id = v_org and u.country = v_country and u.id <> v_up.id
          and u.status = 'confirmed' and u.report_date > v_up.report_date) then
    raise exception 'older_file: a newer daily file for this country is already confirmed'
      using errcode = 'P0001';
  end if;

  perform set_config('workshop.source', 'excel', true);
  perform set_config('workshop.upload_id', v_up.id::text, true);
  perform set_config('workshop.reason', '', true);
  perform set_config('workshop.suppress_fields', '', true);

  select coalesce(array_agg(public.workshop_status_asset_key(asset_no)), '{}'), count(*)::int
    into v_prior, v_n_prev
    from public.workshop_status_records
   where organisation_id = v_org and country = v_country and current_active and deleted_at is null;

  select coalesce(array_agg(distinct asset_no) filter (where asset_no is not null), '{}')
    into v_closed
    from public.workshop_status_upload_rows
   where upload_id = v_up.id and outcome = 'closed';

  for s in
    select distinct on (public.workshop_status_asset_key(ur.asset_no))
           public.workshop_status_asset_key(ur.asset_no) as asset, ur.data, ur.row_number, ur.id
      from public.workshop_status_upload_rows ur
     where ur.upload_id = v_up.id and ur.outcome in ('new', 'changed', 'unchanged')
       and public.workshop_status_asset_key(ur.asset_no) is not null
     order by public.workshop_status_asset_key(ur.asset_no), ur.row_number nulls last, ur.created_at, ur.id
  loop
    v_active := v_active || s.asset;
    v_data := coalesce(s.data, '{}'::jsonb);
    v_reg  := public.workshop_status_jtext(v_data, 'reg_no');
    v_jc   := public.workshop_status_jtext(v_data, 'job_card_ref');
    v_cat  := public.workshop_status_jtext(v_data, 'vehicle_category');
    v_site := public.workshop_status_jtext(v_data, 'site');
    v_dept := public.workshop_status_jtext(v_data, 'department');
    v_comp := public.workshop_status_jtext(v_data, 'complaint');
    v_diag := public.workshop_status_jtext(v_data, 'diagnostics');
    v_ooc  := public.workshop_status_jdate(v_data ->> 'ooc_since');
    v_days := public.workshop_status_jint(v_data ->> 'excel_down_days');
    v_etr  := public.workshop_status_jtext(v_data, 'excel_expected_release');
    v_note := public.workshop_status_jtext(v_data, 'excel_status_note');
    v_rem  := public.workshop_status_jtext(v_data, 'source_remarks');

    select * into r from public.workshop_status_records
     where organisation_id = v_org and country = v_country and current_active and deleted_at is null
       and public.workshop_status_asset_key(asset_no) = s.asset
     order by id limit 1
     for update;

    if found then
      v_fields := array_remove(array[
        case when public.workshop_status_cmp('reg_no', r.reg_no) is distinct from public.workshop_status_cmp('reg_no', v_reg) then 'reg_no' end,
        case when public.workshop_status_cmp('job_card_ref', r.job_card_ref) is distinct from public.workshop_status_cmp('job_card_ref', v_jc) then 'job_card_ref' end,
        case when public.workshop_status_cmp('vehicle_category', r.vehicle_category) is distinct from public.workshop_status_cmp('vehicle_category', v_cat) then 'vehicle_category' end,
        case when public.workshop_status_cmp('site', r.site) is distinct from public.workshop_status_cmp('site', v_site) then 'site' end,
        case when public.workshop_status_cmp('department', r.department) is distinct from public.workshop_status_cmp('department', v_dept) then 'department' end,
        case when public.workshop_status_cmp('complaint', r.complaint) is distinct from public.workshop_status_cmp('complaint', v_comp) then 'complaint' end,
        case when public.workshop_status_cmp('diagnostics', r.diagnostics) is distinct from public.workshop_status_cmp('diagnostics', v_diag) then 'diagnostics' end,
        case when r.ooc_since is distinct from v_ooc then 'ooc_since' end,
        case when public.workshop_status_cmp('excel_expected_release', r.excel_expected_release) is distinct from public.workshop_status_cmp('excel_expected_release', v_etr) then 'excel_expected_release' end,
        case when public.workshop_status_cmp('excel_status_note', r.excel_status_note) is distinct from public.workshop_status_cmp('excel_status_note', v_note) then 'excel_status_note' end,
        case when public.workshop_status_cmp('source_remarks', r.source_remarks) is distinct from public.workshop_status_cmp('source_remarks', v_rem) then 'source_remarks' end
      ], null);
      v_changed := cardinality(v_fields) > 0;

      if v_changed then
        update public.workshop_status_records set
          reg_no = v_reg, job_card_ref = v_jc, vehicle_category = v_cat, site = v_site,
          department = v_dept, complaint = v_comp, diagnostics = v_diag, ooc_since = v_ooc,
          excel_down_days = v_days, excel_expected_release = v_etr, excel_status_note = v_note,
          source_remarks = v_rem, excel_data = v_data, excel_updated_at = now(),
          last_seen_upload_id = v_up.id, last_seen_at = now()
         where id = r.id;
        insert into public.workshop_status_events
          (organisation_id, country, record_id, upload_id, event_type, source, details)
        values (v_org, v_country, r.id, v_up.id, 'excel_updated', 'excel',
                jsonb_build_object('fields', to_jsonb(v_fields), 'row_number', s.row_number,
                  'message', 'Vehicle details refreshed from the Daily Workshop Excel upload.'));
        v_upd_ids := v_upd_ids || r.id;
      else
        perform set_config('workshop.source', '', true);
        perform set_config('workshop.suppress_fields', 'excel_down_days', true);
        update public.workshop_status_records set
          excel_down_days = v_days, excel_data = v_data,
          last_seen_upload_id = v_up.id, last_seen_at = now()
         where id = r.id;
        perform set_config('workshop.suppress_fields', '', true);
        perform set_config('workshop.source', 'excel', true);
        v_same_ids := v_same_ids || r.id;
      end if;
    else
      select case when count(*) = 1 then (array_agg(f.id))[1] end into v_vehicle
        from public.vehicle_fleet f
       where f.organisation_id = v_org and f.country is not distinct from v_country
         and public.workshop_status_asset_key(f.asset_no) = s.asset;

      insert into public.workshop_status_records
        (organisation_id, country, asset_no, vehicle_id, asset_breakdown_id,
         reg_no, job_card_ref, vehicle_category, site, department, complaint, diagnostics,
         ooc_since, excel_down_days, excel_expected_release, excel_status_note, source_remarks,
         excel_data, excel_updated_at, current_active, daily_report_status,
         first_seen_upload_id, last_seen_upload_id, last_seen_at)
      values
        (v_org, v_country, s.asset, v_vehicle, public.workshop_status_breakdown_for(v_org, v_country, s.asset),
         v_reg, v_jc, v_cat, v_site, v_dept, v_comp, v_diag,
         v_ooc, v_days, v_etr, v_note, v_rem,
         v_data, now(), true, 'active',
         v_up.id, v_up.id, now())
      returning id into v_new_id;
      v_new_ids := v_new_ids || v_new_id;
    end if;
  end loop;

  for r in
    select * from public.workshop_status_records
     where organisation_id = v_org and country = v_country and current_active and deleted_at is null
       and not (public.workshop_status_asset_key(asset_no) = any (v_active))
     order by asset_no, id
     for update
  loop
    if v_up.report_date is not null and r.last_manual_update_at is not null
       and public.workshop_status_local_day(r.last_manual_update_at, r.country) > v_up.report_date
       and not (public.workshop_status_asset_key(r.asset_no) = any (v_closed)) then
      insert into public.workshop_status_events
        (organisation_id, country, site, record_id, asset_no, upload_id, event_type, reason, source, details)
      values (v_org, v_country, r.site, r.id, r.asset_no, v_up.id, 'excel_updated', 'kept_newer_manual_update', 'excel',
              jsonb_build_object('kept', true, 'report_date', v_up.report_date,
                'last_manual_update_at', r.last_manual_update_at,
                'message', 'Kept in the current workshop report: it was updated in TyrePulse after the date of this Excel file, so the older file does not release it.'));
      v_kept_ids := v_kept_ids || r.id;
      continue;
    end if;
    if public.workshop_status_asset_key(r.asset_no) = any (v_closed) then
      v_reason := 'listed_as_closed';
      select jsonb_build_object('row_number', ur.row_number, 'section', ur.section,
                                'job_card_ref', ur.data ->> 'job_card_ref')
        into v_closed_row
        from public.workshop_status_upload_rows ur
       where ur.upload_id = v_up.id and ur.outcome = 'closed'
         and ur.asset_no = public.workshop_status_asset_key(r.asset_no)
       order by ur.row_number nulls last, ur.id limit 1;
    else
      v_reason := 'missing_from_upload';
      v_closed_row := null;
    end if;

    perform set_config('workshop.reason', v_reason, true);
    update public.workshop_status_records set
      current_active = false,
      daily_report_status = 'removed_from_current_report',
      removed_at = now(),
      removed_by_upload_id = v_up.id,
      removed_reason = v_reason,
      previous_current_stage = r.current_stage,
      previous_delay_reason = r.delay_reason,
      previous_responsible_user_id = r.responsible_user_id
     where id = r.id;

    insert into public.workshop_status_events
      (organisation_id, country, site, record_id, asset_no, upload_id, event_type, reason, source, details)
    values (v_org, v_country, r.site, r.id, r.asset_no, v_up.id, 'removed', v_reason, 'excel',
            jsonb_strip_nulls(jsonb_build_object(
              'reason', v_reason,
              'closed_row', v_closed_row,
              'message', case when v_reason = 'listed_as_closed'
                then 'Vehicle removed from current workshop report because it was listed under closed details in the Excel.'
                else 'Vehicle removed from current workshop report because it was not present in the latest confirmed Excel upload.' end)));
    v_rem_ids := v_rem_ids || r.id;
  end loop;
  perform set_config('workshop.reason', '', true);

  select count(*)::int into v_n_closed
    from public.workshop_status_upload_rows ur
   where ur.upload_id = v_up.id and ur.outcome = 'closed'
     and ur.asset_no is not null
     and not (ur.asset_no = any (v_active)) and not (ur.asset_no = any (v_prior));
  select (count(*) filter (where outcome = 'invalid'))::int,
         (count(*) filter (where outcome = 'duplicate'))::int
    into v_n_invalid, v_n_dup
    from public.workshop_status_upload_rows where upload_id = v_up.id;
  v_n_dup := v_n_dup + (
    select count(*)::int from public.workshop_status_upload_rows
     where upload_id = v_up.id and outcome in ('new', 'changed', 'unchanged')
       and public.workshop_status_asset_key(asset_no) is not null) - cardinality(v_active);

  select count(*)::int into v_n_after
    from public.workshop_status_records
   where organisation_id = v_org and country = v_country and current_active and deleted_at is null;

  update public.workshop_status_uploads set
    status = 'confirmed',
    new_count = cardinality(v_new_ids),
    updated_count = cardinality(v_upd_ids),
    unchanged_count = cardinality(v_same_ids),
    removed_count = cardinality(v_rem_ids),
    closed_count = v_n_closed,
    invalid_count = v_n_invalid,
    duplicate_count = v_n_dup,
    previous_active_count = v_n_prev,
    kept_count = cardinality(v_kept_ids),
    duplicate_acknowledged = (v_up.duplicate_of_upload_id is not null and coalesce(p_acknowledge_duplicate, false))
   where id = v_up.id;

  v_summary := jsonb_build_object(
    'upload_id', v_up.id,
    'new', cardinality(v_new_ids),
    'updated', cardinality(v_upd_ids),
    'unchanged', cardinality(v_same_ids),
    'removed', cardinality(v_rem_ids),
    'closed', v_n_closed,
    'invalid', v_n_invalid,
    'duplicate', v_n_dup,
    'previous_active', v_n_prev,
    'active_after', v_n_after,
    'kept', cardinality(v_kept_ids));

  insert into public.workshop_status_events (organisation_id, country, upload_id, event_type, source, details)
  values (v_org, v_country, v_up.id, 'upload_confirmed', 'excel',
          v_summary || jsonb_build_object(
            'duplicate_acknowledged', (v_up.duplicate_of_upload_id is not null and coalesce(p_acknowledge_duplicate, false)),
            'duplicate_of_upload_id', v_up.duplicate_of_upload_id,
            'record_ids', jsonb_build_object('new', to_jsonb(v_new_ids), 'updated', to_jsonb(v_upd_ids),
                                             'unchanged', to_jsonb(v_same_ids), 'removed', to_jsonb(v_rem_ids), 'kept', to_jsonb(v_kept_ids))));

  return v_summary;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_event_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  raise exception 'Workshop status history cannot be changed or deleted'
    using errcode = '42501';
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_event_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  NEW.actor_id   := auth.uid();
  NEW.actor_name := coalesce(public.workshop_status_actor_name(), 'System');
  NEW.created_at := now();
  if NEW.record_id is not null and (NEW.country is null or NEW.site is null or NEW.asset_no is null) then
    select coalesce(NEW.country, r.country), coalesce(NEW.site, r.site), coalesce(NEW.asset_no, r.asset_no)
      into NEW.country, NEW.site, NEW.asset_no
      from public.workshop_status_records r where r.id = NEW.record_id;
  end if;
  if NEW.country is null and NEW.upload_id is not null then
    select u.country into NEW.country from public.workshop_status_uploads u where u.id = NEW.upload_id;
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_jdate(p text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p is null or btrim(p) !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  return btrim(p)::date;
exception when others then
  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_jint(p text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p is null or btrim(p) !~ '^-?\d{1,9}(\.\d+)?$' then return null; end if;
  return round(btrim(p)::numeric)::integer;
exception when others then
  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_jtext(p_data jsonb, p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(p_data ->> p_key), '')
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_local_day(p_ts timestamp with time zone, p_country text)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select (p_ts at time zone case lower(btrim(coalesce(p_country, '')))
            when 'uae' then 'Asia/Dubai'
            when 'egypt' then 'Africa/Cairo'
            else 'Asia/Riyadh' end)::date
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_log_export(p_report text, p_country text DEFAULT NULL::text, p_format text DEFAULT 'xlsx'::text, p_rows integer DEFAULT 0, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_report  text := lower(btrim(coalesce(p_report, '')));
  v_format  text := lower(btrim(coalesce(p_format, '')));
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_rows    integer := greatest(0, least(coalesce(p_rows, 0), 1000000));
  v_label   text;
  v_id      uuid;
begin
  if auth.uid() is null or not public.workshop_status_can('export') then
    raise exception 'You do not have permission to export the workshop report.' using errcode = '42501';
  end if;

  v_label := case v_report
    when 'active'   then 'Active vehicles'
    when 'report'   then 'Workshop status report'
    when 'activity' then 'Activity log'
    when 'workload' then 'Team workload'
    when 'released' then 'Released vehicles'
    when 'history'  then 'Vehicle history'
    when 'uploads'  then 'Upload rows'
    else null end;
  if v_label is null then
    raise exception 'Unknown workshop export.' using errcode = '22023';
  end if;
  if v_format not in ('xlsx', 'pdf') then
    raise exception 'Unknown export format.' using errcode = '22023';
  end if;

  if v_country = 'All' then v_country := null; end if;
  if v_country is not null and public.app_can_see_country(v_country) is false then
    raise exception 'You do not have access to that country.' using errcode = '42501';
  end if;

  if p_filters is null or jsonb_typeof(p_filters) <> 'object' or length(p_filters::text) > 4096 then
    p_filters := '{}'::jsonb;
  end if;

  insert into public.workshop_status_events (country, event_type, source, reason, details)
  values (
    v_country,
    'export',
    'manual',
    v_label || ', ' || case v_format when 'pdf' then 'PDF' else 'Excel' end
      || ', ' || v_rows || case v_rows when 1 then ' row' else ' rows' end
      || case when v_country is null then ', all countries' else ', ' || v_country end,
    jsonb_build_object('report', v_report, 'format', v_format, 'rows', v_rows, 'filters', p_filters)
  )
  returning id into v_id;

  return v_id;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_manual_vocab(p_kind text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_kind
    when 'stage' then array[
      'Newly Reported', 'Waiting for Diagnosis', 'Diagnosis in Progress', 'Repair in Progress',
      'Waiting', 'Waiting for Parts', 'Waiting for Approval', 'Waiting for Manpower',
      'Waiting for External Vendor', 'External Repair', 'Testing', 'Road Test',
      'QC / Inspection', 'Ready for Release', 'Operational Hold']
    when 'delay' then array[
      'Waiting for Spare Parts', 'Spare Parts Not Available', 'MR Pending', 'PO Pending',
      'Supplier Delivery Pending', 'Waiting for Manpower', 'Technician Not Available',
      'Specialist Technician Required', 'Waiting for Workshop Bay', 'Waiting for Tools / Equipment',
      'Waiting for External Vendor', 'Sent to External Workshop', 'Waiting for Diagnosis',
      'Repair in Progress', 'Waiting for Approval', 'Waiting for Budget Approval',
      'Waiting for Vehicle Recovery / Towing', 'Waiting for Site to Release Vehicle',
      'Waiting for Testing', 'Waiting for Road Test', 'Waiting for QC / Inspection',
      'Accident Repair', 'Warranty Claim', 'Major Engine Repair', 'Major Gearbox Repair',
      'Electrical Issue', 'Hydraulic Issue', 'Tyre Related', 'Body Repair',
      'No Operator / Driver', 'Operational Hold', 'Other']
    when 'parts' then array[
      'Not Required', 'Required', 'Checking Store', 'Available in Store', 'MR Pending',
      'MR Raised', 'MR Approved', 'PO Pending', 'PO Issued', 'Supplier Confirmed',
      'In Transit', 'Partially Received', 'Received', 'Not Available',
      'Alternative Part Under Review']
    else '{}'::text[]
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_my_permissions()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_object_agg(a, public.workshop_status_can(a))
    from unnest(array[
      'view', 'view_removed', 'view_uploads', 'view_activity', 'view_reports', 'view_audit',
      'update', 'upload', 'confirm', 'assign', 'disposition', 'export',
      'archive', 'restore', 'soft_delete', 'configure', 'permanent_delete']) as a
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notice_candidates(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p record;
  v_scope jsonb;
  v_out jsonb := '[]'::jsonb;
begin
  for p in
    select pr.id
      from public.profiles pr
     where (pr.organisation_id = p_org or pr.org_id = p_org)
       and coalesce(pr.approved, false) and not coalesce(pr.locked, false)
       and (coalesce(pr.is_super_admin, false) or pr.role = 'Admin'
            or exists (select 1 from public.module_permissions mp
                        where mp.role = pr.role and mp.module_key = 'daily_ops:workshop' and mp.enabled)
            or exists (select 1 from public.user_access_grants g
                        where g.user_id = pr.id and g.module_key like 'daily_ops:workshop%' and g.effect = 'grant'))
     order by pr.id
  loop
    v_scope := public.workshop_status_recipient_scope(p.id);
    if v_scope is not null and coalesce((v_scope ->> 'view')::boolean, false) then
      v_out := v_out || jsonb_build_array(v_scope);
    end if;
  end loop;
  return v_out;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notice_send(p_org uuid, p_user uuid, p_kind text, p_title text, p_body text, p_entity_type text, p_entity_id uuid, p_link text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tokens jsonb := '[]'::jsonb;
  v_event bigint;
begin
  insert into public.notifications (user_id, type, title, body, entity_type, entity_id)
  values (p_user, p_kind, p_title, p_body, p_entity_type, p_entity_id);

  if public.workshop_status_notify_config('workshop_status_push', 'true') <> 'false' then
    begin
      if to_regprocedure('public._user_push_tokens(uuid)') is not null then
        execute $q$select coalesce(jsonb_agg(jsonb_build_object('user_id', $1, 'push_token', t.tok)), '[]'::jsonb)
                     from public._user_push_tokens($1) as t(tok)$q$
          into v_tokens using p_user;
      else
        select coalesce(jsonb_agg(jsonb_build_object('user_id', p.id, 'push_token', btrim(p.push_token))), '[]'::jsonb)
          into v_tokens
          from public.profiles p
         where p.id = p_user and nullif(btrim(p.push_token), '') is not null;
      end if;
      if jsonb_array_length(v_tokens) > 0 then
        insert into public.domain_events (event_type, entity_type, entity_id, organisation_id, payload, status, processed_at)
        values ('workshop_status.notice', coalesce(p_entity_type, 'workshop_status'), p_entity_id::text, p_org,
                jsonb_build_object('kind', p_kind, 'user_id', p_user), 'processed', clock_timestamp())
        returning id into v_event;
        insert into public.workflow_notifications
          (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
        values (v_event, p_org, null, 'workshop_status.notice',
                jsonb_build_object(
                  'event_type', 'workshop_status.notice',
                  'entity_type', p_entity_type,
                  'entity_id', p_entity_id,
                  'link', p_link,
                  'push', jsonb_build_object('title', p_title, 'body', p_body),
                  'recipients', v_tokens),
                jsonb_array_length(v_tokens), 'pending');
      end if;
    exception when others then
      null; -- the bell row stands; a push failure never undoes it.
    end;
  end if;
  return true;
exception when others then
  return false;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notify_config(p_key text, p_default text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  begin
    execute 'select value::text from public.system_config where key = $1' into v using p_key;
  exception when others then
    v := null;
  end;
  v := nullif(btrim(btrim(coalesce(v, '')), '"'), '');
  return coalesce(v, p_default);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notify_scan(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tz text := public.workshop_status_notify_config('workshop_status_timezone', 'Asia/Riyadh');
  v_wait int; v_eta int; v_deadline int;
  v_local timestamp; v_today date; v_hour int;
  v_org uuid;
  v_cands jsonb;
  v_new jsonb;
  g record;
  v_title text; v_body text; v_link text; v_entity_type text; v_entity uuid;
  v_sent int := 0;
begin
  if public.workshop_status_notify_config('workshop_status_notifications', 'true') = 'false' then
    return jsonb_build_object('sent', 0, 'disabled', true);
  end if;
  begin v_wait := public.workshop_status_notify_config('workshop_status_wait_days', '7')::int;
  exception when others then v_wait := 7; end;
  begin v_eta := public.workshop_status_notify_config('workshop_status_eta_days', '3')::int;
  exception when others then v_eta := 3; end;
  begin v_deadline := public.workshop_status_notify_config('workshop_status_update_deadline_hour', '10')::int;
  exception when others then v_deadline := 10; end;
  begin v_local := p_now at time zone v_tz;
  exception when others then v_tz := 'Asia/Riyadh'; v_local := p_now at time zone v_tz; end;
  v_today := v_local::date;
  v_hour := extract(hour from v_local)::int;

  for v_org in
    select distinct organisation_id from public.workshop_status_records
     where current_active and deleted_at is null
    union
    select distinct organisation_id from public.workshop_status_uploads
     where status = 'previewed' and uploaded_at < p_now - interval '30 minutes'
  loop
    v_cands := public.workshop_status_notice_candidates(v_org);
    if jsonb_array_length(v_cands) = 0 then continue; end if;

    with cand as (
      select (e ->> 'user_id')::uuid as uid, e as scope from jsonb_array_elements(v_cands) e
    ),
    recs as (
      select r.*,
             coalesce(
               case when r.ooc_since is not null and r.ooc_since <= v_today then v_today - r.ooc_since end,
               case when r.excel_down_days >= 0 then r.excel_down_days end,
               v_today - (r.first_seen_at at time zone v_tz)::date) as days_down,
             public.workshop_status_wait_category(r.current_stage, r.delay_reason) as wait_cat
        from public.workshop_status_records r
       where r.organisation_id = v_org and r.current_active and r.deleted_at is null
    ),
    conds as (
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_update_missing' as kind,
             v_today::text as period, 'responsible' as audience
        from recs
       where v_hour >= v_deadline
         and (last_manual_update_at is null or (last_manual_update_at at time zone v_tz)::date < v_today)
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_waiting_long', 'once', 'responsible'
        from recs where wait_cat is not null and days_down >= v_wait
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_long_down', 'once', 'responsible'
        from recs where wait_cat is null and days_down >= v_wait
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_release_today', v_today::text, 'responsible'
        from recs where expected_release_date = v_today
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_release_overdue',
             expected_release_date::text, 'responsible'
        from recs where expected_release_date < v_today
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_no_responsible', 'once', 'assigners'
        from recs where responsible_user_id is null
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_missing_eta', 'once', 'responsible'
        from recs where expected_release_date is null and nullif(btrim(coalesce(excel_expected_release, '')), '') is null
                    and days_down >= v_eta
      union all
      select id, asset_no, country, site, responsible_user_id, 'workshop_status_ready_release', 'once', 'assigners'
        from recs where current_stage = 'Ready for Release'
    ),
    owner_ok as (
      select cd.*, exists (select 1 from cand x where x.uid = cd.responsible_user_id
                            and public.workshop_status_scope_allows(x.scope, cd.country, cd.site)) as owner_sees
        from conds cd
    ),
    targets as (
      select o.id as subject_id, o.asset_no, o.kind, o.period, o.responsible_user_id as uid
        from owner_ok o where o.audience = 'responsible' and o.owner_sees
      union
      select o.id, o.asset_no, o.kind, o.period, x.uid
        from owner_ok o join cand x
          on coalesce((x.scope ->> 'assign')::boolean, false)
         and public.workshop_status_scope_allows(x.scope, o.country, o.site)
       where o.audience = 'assigners' or not o.owner_sees
      union
      select u.id, null, 'workshop_status_upload_review', 'once', x.uid
        from public.workshop_status_uploads u join cand x
          on coalesce((x.scope ->> 'confirm')::boolean, false)
         and public.workshop_status_scope_allows(x.scope, u.country, null)
       where u.organisation_id = v_org and u.status = 'previewed'
         and u.uploaded_at < p_now - interval '30 minutes'
    ),
    ins as (
      insert into public.workshop_status_notices (organisation_id, user_id, kind, subject_id, period)
      select v_org, t.uid, t.kind, t.subject_id, t.period from targets t
      on conflict do nothing
      returning user_id, kind, subject_id
    )
    select coalesce(jsonb_agg(jsonb_build_object(
             'user_id', g2.user_id, 'kind', g2.kind, 'ids', g2.ids, 'assets', g2.assets)), '[]'::jsonb)
      into v_new
      from (
        select ins.user_id, ins.kind,
               to_jsonb(array_agg(ins.subject_id order by t.asset_no nulls last, ins.subject_id)) as ids,
               to_jsonb(array_remove(array_agg(distinct t.asset_no), null)) as assets
          from ins
          join (select distinct subject_id, kind, asset_no from targets) t
            on t.subject_id = ins.subject_id and t.kind = ins.kind
         group by ins.user_id, ins.kind
      ) g2;

    for g in
      select (e ->> 'user_id')::uuid as uid, e ->> 'kind' as kind,
             array(select jsonb_array_elements_text(e -> 'ids'))::uuid[] as ids,
             array(select jsonb_array_elements_text(e -> 'assets') order by 1) as assets
        from jsonb_array_elements(v_new) e
    loop
      v_title := case g.kind
        when 'workshop_status_upload_review' then 'Workshop upload waiting for confirmation'
        when 'workshop_status_update_missing' then cardinality(g.ids) || ' workshop '
             || case when cardinality(g.ids) = 1 then 'vehicle has' else 'vehicles have' end || ' no update today'
        when 'workshop_status_waiting_long' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle' else 'vehicles' end
             || ' waiting for parts, manpower or approval for ' || v_wait || '+ days'
        when 'workshop_status_long_down' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle' else 'vehicles' end
             || ' down for ' || v_wait || '+ days'
        when 'workshop_status_release_today' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle' else 'vehicles' end || ' expected to be released today'
        when 'workshop_status_release_overdue' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle is' else 'vehicles are' end || ' past the expected release date'
        when 'workshop_status_no_responsible' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle has' else 'vehicles have' end || ' no responsible person'
        when 'workshop_status_missing_eta' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle has' else 'vehicles have' end || ' no expected release date'
        when 'workshop_status_ready_release' then cardinality(g.ids) || ' '
             || case when cardinality(g.ids) = 1 then 'vehicle is' else 'vehicles are' end || ' ready for release'
        else 'Workshop Status' end;
      v_body := case g.kind
        when 'workshop_status_upload_review' then
          'A daily workshop upload was previewed but not confirmed. Review it and confirm or cancel.'
        when 'workshop_status_update_missing' then
          'Update today: ' || public.workshop_status_asset_list(g.assets) || '.'
        else public.workshop_status_asset_list(g.assets) || '.' end;

      if g.kind = 'workshop_status_upload_review' then
        v_entity_type := 'workshop_status_upload'; v_entity := g.ids[1];
        v_link := '/daily-ops/workshop?tab=upload';
      elsif cardinality(g.ids) = 1 then
        v_entity_type := 'workshop_status_record'; v_entity := g.ids[1];
        v_link := '/daily-ops/workshop?record=' || g.ids[1]::text;
      else
        v_entity_type := 'workshop_status'; v_entity := null;
        v_link := '/daily-ops/workshop?focus=' || case g.kind
          when 'workshop_status_update_missing' then 'not_today'
          when 'workshop_status_waiting_long' then 'over7'
          when 'workshop_status_long_down' then 'over7'
          when 'workshop_status_release_today' then 'expected_today'
          when 'workshop_status_no_responsible' then 'unassigned'
          when 'workshop_status_ready_release' then 'ready'
          else 'mine' end;
      end if;

      if public.workshop_status_notice_send(v_org, g.uid, g.kind, v_title, v_body, v_entity_type, v_entity, v_link) then
        v_sent := v_sent + 1;
      else
        -- Not delivered: release the claim (re-key the period) so the next run tries again.
        update public.workshop_status_notices
           set period = period || ':undelivered:' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS')
         where organisation_id = v_org and user_id = g.uid and kind = g.kind and subject_id = any (g.ids)
           and created_at = now();
      end if;
    end loop;
  end loop;

  return jsonb_build_object('sent', v_sent);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notify_upload(p_upload_id uuid, p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_up public.workshop_status_uploads%rowtype;
  v_new uuid[]; v_upd uuid[]; v_rem uuid[]; v_active uuid[];
  v_cands jsonb;
  c jsonb;
  v_uid uuid;
  v_mine text[]; v_mine_ids uuid[]; v_mine_new int; v_mine_chg int;
  v_un text[]; v_un_ids uuid[];
  v_rel text[]; v_rel_mine text[];
  v_kind text; v_title text; v_body text; v_parts text[];
  v_entity_type text; v_entity uuid; v_link text;
  v_sent int := 0;
begin
  if public.workshop_status_notify_config('workshop_status_notifications', 'true') = 'false' then
    return jsonb_build_object('sent', 0, 'disabled', true);
  end if;
  select * into v_up from public.workshop_status_uploads where id = p_upload_id;
  if not found or v_up.status <> 'confirmed' then return jsonb_build_object('sent', 0); end if;

  v_new := coalesce(array(select jsonb_array_elements_text(p_details -> 'record_ids' -> 'new'))::uuid[], '{}');
  v_upd := coalesce(array(select jsonb_array_elements_text(p_details -> 'record_ids' -> 'updated'))::uuid[], '{}');
  v_rem := coalesce(array(select jsonb_array_elements_text(p_details -> 'record_ids' -> 'removed'))::uuid[], '{}');
  v_active := v_new || v_upd
    || coalesce(array(select jsonb_array_elements_text(p_details -> 'record_ids' -> 'unchanged'))::uuid[], '{}');
  if cardinality(v_active) = 0 and cardinality(v_rem) = 0 then return jsonb_build_object('sent', 0); end if;

  v_cands := public.workshop_status_notice_candidates(v_up.organisation_id);

  for c in select e from jsonb_array_elements(v_cands) e loop
    v_uid := (c ->> 'user_id')::uuid;

    -- Vehicles this person is responsible for and may update.
    select coalesce(array_agg(r.asset_no order by r.asset_no), '{}'),
           coalesce(array_agg(r.id order by r.asset_no), '{}'),
           count(*) filter (where r.id = any (v_new))::int,
           count(*) filter (where r.id = any (v_upd))::int
      into v_mine, v_mine_ids, v_mine_new, v_mine_chg
      from public.workshop_status_records r
     where r.id = any (v_active) and r.current_active and r.deleted_at is null
       and r.responsible_user_id = v_uid
       and coalesce((c ->> 'update')::boolean, false)
       and public.workshop_status_scope_allows(c, r.country, r.site);

    -- Vehicles with nobody responsible, for people who may assign.
    select coalesce(array_agg(r.asset_no order by r.asset_no), '{}'),
           coalesce(array_agg(r.id order by r.asset_no), '{}')
      into v_un, v_un_ids
      from public.workshop_status_records r
     where r.id = any (v_active) and r.current_active and r.deleted_at is null
       and r.responsible_user_id is null
       and coalesce((c ->> 'assign')::boolean, false)
       and public.workshop_status_scope_allows(c, r.country, r.site);

    -- Released (left the file): named only to someone who may see released
    -- vehicles; the previous responsible person, or anyone who may assign.
    select coalesce(array_agg(r.asset_no order by r.asset_no), '{}'),
           coalesce(array_agg(r.asset_no order by r.asset_no)
                      filter (where r.previous_responsible_user_id = v_uid), '{}')
      into v_rel, v_rel_mine
      from public.workshop_status_records r
     where r.id = any (v_rem) and r.deleted_at is null
       and coalesce((c ->> 'view_removed')::boolean, false)
       and (r.previous_responsible_user_id = v_uid or coalesce((c ->> 'assign')::boolean, false))
       and public.workshop_status_scope_allows(c, r.country, r.site);

    if cardinality(v_mine) = 0 and cardinality(v_un) = 0 and cardinality(v_rel) = 0 then continue; end if;

    v_parts := '{}';
    if cardinality(v_mine) > 0 then
      v_kind := 'workshop_status_upload_mine';
      v_title := 'Workshop report ' || coalesce(v_up.country, '') || ': ' || cardinality(v_mine)
                 || case when cardinality(v_mine) = 1 then ' vehicle needs your update today'
                         else ' vehicles need your update today' end;
      v_parts := v_parts || ('Assigned to you: ' || public.workshop_status_asset_list(v_mine)
        || case when v_mine_new + v_mine_chg > 0
                then ' (' || concat_ws(', ',
                       case when v_mine_new > 0 then v_mine_new || ' new' end,
                       case when v_mine_chg > 0 then v_mine_chg || ' changed' end) || ')'
                else '' end || '.');
    elsif cardinality(v_un) > 0 then
      v_kind := 'workshop_status_upload_unassigned';
      v_title := 'Workshop report ' || coalesce(v_up.country, '') || ': ' || cardinality(v_un)
                 || case when cardinality(v_un) = 1 then ' vehicle has no responsible person'
                         else ' vehicles have no responsible person' end;
    else
      v_kind := 'workshop_status_upload_released';
      v_title := 'Workshop report ' || coalesce(v_up.country, '') || ': ' || cardinality(v_rel)
                 || case when cardinality(v_rel) = 1 then ' vehicle released' else ' vehicles released' end;
    end if;
    if cardinality(v_un) > 0 then
      v_parts := v_parts || ('No responsible person: ' || public.workshop_status_asset_list(v_un) || '.');
    end if;
    if cardinality(v_rel) > 0 then
      v_parts := v_parts || ('Released from the daily file: '
        || public.workshop_status_asset_list(case when cardinality(v_rel_mine) > 0 then v_rel_mine else v_rel end) || '.');
    end if;
    v_body := array_to_string(v_parts, ' ');

    -- Deep link: the exact vehicle when there is one, else the filtered list.
    if v_kind = 'workshop_status_upload_mine' and cardinality(v_mine_ids) = 1 then
      v_entity_type := 'workshop_status_record'; v_entity := v_mine_ids[1];
      v_link := '/daily-ops/workshop?record=' || v_mine_ids[1]::text;
    elsif v_kind = 'workshop_status_upload_unassigned' and cardinality(v_un_ids) = 1 then
      v_entity_type := 'workshop_status_record'; v_entity := v_un_ids[1];
      v_link := '/daily-ops/workshop?record=' || v_un_ids[1]::text;
    else
      v_entity_type := 'workshop_status_upload'; v_entity := v_up.id;
      v_link := case v_kind
        when 'workshop_status_upload_mine' then '/daily-ops/workshop?focus=mine'
        when 'workshop_status_upload_unassigned' then '/daily-ops/workshop?focus=unassigned'
        else '/daily-ops/workshop?tab=removed' end;
    end if;

    -- One notice per person per upload. The ledger rows and the bell row
    -- commit together: when the send fails the subtransaction rolls the
    -- ledger back too, so a later run can still tell this person.
    begin
      insert into public.workshop_status_notices (organisation_id, user_id, kind, subject_id, period)
      values (v_up.organisation_id, v_uid, 'workshop_status_upload', v_up.id, 'upload')
      on conflict do nothing;
      if found then
        -- The assigners were just told about these unassigned vehicles: the
        -- scan must not tell them again.
        insert into public.workshop_status_notices (organisation_id, user_id, kind, subject_id, period)
        select v_up.organisation_id, v_uid, 'workshop_status_no_responsible', x, 'once' from unnest(v_un_ids) x
        on conflict do nothing;
        if not public.workshop_status_notice_send(v_up.organisation_id, v_uid, v_kind, v_title, v_body,
                                                  v_entity_type, v_entity, v_link) then
          raise exception 'workshop notice not delivered';
        end if;
        v_sent := v_sent + 1;
      end if;
    exception when others then
      null;
    end;
  end loop;
  return jsonb_build_object('sent', v_sent);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_notify_upload_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.workshop_status_notify_upload(NEW.upload_id, NEW.details);
  exception when others then
    null; -- a notification problem must never undo the confirmed upload.
  end;
  return null;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_recipient_scope(p_uid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub text := coalesce(current_setting('request.jwt.claim.sub', true), '');
  v_claims text := coalesce(current_setting('request.jwt.claims', true), '');
  v jsonb;
begin
  if p_uid is null then return null; end if;
  begin
    perform set_config('request.jwt.claim.sub', p_uid::text, true);
    perform set_config('request.jwt.claims',
      jsonb_build_object('sub', p_uid::text, 'role', 'authenticated')::text, true);
    v := jsonb_build_object(
      'user_id', p_uid,
      'view', coalesce(public.workshop_status_can('view'), false),
      'update', coalesce(public.workshop_status_can('update'), false),
      'assign', coalesce(public.workshop_status_can('assign'), false),
      'confirm', coalesce(public.workshop_status_can('confirm'), false),
      'view_removed', coalesce(public.workshop_status_can('view_removed'), false),
      'super', coalesce(public.is_super_admin(), false),
      'all_countries', coalesce(public.app_sees_all_countries(), false),
      'countries', to_jsonb(coalesce(public.app_country_scope(), '{}'::text[])),
      'all_sites', coalesce(public.app_sees_all_sites(), false),
      'sites', to_jsonb(coalesce(public.app_site_scope(), '{}'::text[])));
    perform set_config('request.jwt.claim.sub', v_sub, true);
    perform set_config('request.jwt.claims', v_claims, true);
  exception when others then
    v := null;
  end;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_record_action(p_record_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_disposition text DEFAULT NULL::text, p_remarks text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_disp text := nullif(btrim(coalesce(p_disposition, '')), '');
  v_remarks text := nullif(btrim(coalesce(p_remarks, '')), '');
  v_perm text;
  v_r public.workshop_status_records%rowtype;
  v_event text;
  v_details jsonb;
  v_out jsonb;
begin
  v_perm := case v_action
    when 'disposition' then 'disposition'
    when 'restore' then 'restore'
    when 'archive' then 'archive'
    when 'unarchive' then 'archive'
    when 'soft_delete' then 'soft_delete'
    when 'undelete' then 'soft_delete'
    when 'permanent_delete' then 'permanent_delete'
  end;
  if v_perm is null then
    raise exception 'Unknown action' using errcode = '22023';
  end if;
  if not coalesce(public.workshop_status_can(v_perm), false) then
    raise exception 'You do not have permission to do this' using errcode = '42501';
  end if;
  if v_org is null and not coalesce(public.is_super_admin(), false) then
    raise exception 'Your account is not linked to an organisation' using errcode = '42501';
  end if;
  if p_record_id is null then
    raise exception 'Choose a vehicle' using errcode = '22023';
  end if;

  select * into v_r from public.workshop_status_records where id = p_record_id for update;
  if not found
     or (v_r.organisation_id is distinct from v_org and not coalesce(public.is_super_admin(), false))
     or not (
       coalesce(public.is_super_admin(), false)
       or v_r.country is null
       or coalesce(public.app_sees_all_countries(), false)
       or lower(btrim(v_r.country)) = any (coalesce(public.app_country_scope(), '{}'::text[])))
     or not (
       coalesce(public.is_super_admin(), false)
       or v_r.site is null or btrim(v_r.site) = ''
       or coalesce(public.app_sees_all_sites(), false)
       or upper(btrim(v_r.site)) = any (coalesce(public.app_site_scope(), '{}'::text[])))
     or (v_r.deleted_at is not null and not coalesce(public.workshop_status_can('soft_delete'), false)) then
    raise exception 'Workshop vehicle not found' using errcode = 'P0002';
  end if;

  if p_expected_updated_at is not null and v_r.updated_at is distinct from p_expected_updated_at then
    raise exception 'record_changed: this vehicle was updated by someone else' using errcode = 'PT409';
  end if;

  if v_r.current_active then
    raise exception 'This vehicle is still in the active report' using errcode = '22023';
  end if;

  if v_action <> 'disposition' then
    if v_reason is null or length(v_reason) < 5 then
      raise exception 'Enter a reason (at least 5 characters)' using errcode = '22023';
    end if;
    if length(v_reason) > 1000 then
      raise exception 'The reason is too long (1000 characters at most)' using errcode = '22023';
    end if;
  end if;

  if v_action in ('disposition', 'restore', 'archive', 'unarchive', 'soft_delete')
     and v_r.deleted_at is not null then
    raise exception 'This record is deleted. Undelete it first' using errcode = '22023';
  end if;
  if v_action in ('undelete', 'permanent_delete') and v_r.deleted_at is null then
    raise exception 'This record is not deleted' using errcode = '22023';
  end if;
  if v_action in ('restore', 'archive') and v_r.archived_at is not null then
    raise exception 'This record is archived. Unarchive it first' using errcode = '22023';
  end if;
  if v_action = 'unarchive' and v_r.archived_at is null then
    raise exception 'This record is not archived' using errcode = '22023';
  end if;

  if v_action = 'disposition' then
    if v_disp is null or not (v_disp = any (array[
        'repair_completed', 'returned_to_operation', 'transferred_site', 'sent_external_workshop',
        'vehicle_sold', 'vehicle_scrapped', 'wrong_entry', 'duplicate_entry', 'other'])) then
      raise exception 'Choose a final disposition from the list' using errcode = '22023';
    end if;
    if v_disp = 'other' and v_remarks is null then
      raise exception 'Remarks are required when the disposition is Other' using errcode = '22023';
    end if;
    if length(v_remarks) > 2000 then
      raise exception 'The remarks are too long (2000 characters at most)' using errcode = '22023';
    end if;
    if v_disp is not distinct from v_r.final_disposition
       and v_remarks is not distinct from v_r.final_disposition_remarks then
      return jsonb_build_object('ok', true, 'changed', 0);
    end if;
  end if;

  if v_action = 'restore' and exists (
      select 1 from public.workshop_status_records x
       where x.organisation_id = v_r.organisation_id
         and x.country is not distinct from v_r.country
         and x.asset_no = v_r.asset_no
         and x.current_active and x.deleted_at is null
         and x.id <> v_r.id) then
    raise exception 'This vehicle is already in the active report' using errcode = '23505';
  end if;

  perform set_config('workshop.source', 'manual', true);
  perform set_config('workshop.upload_id', '', true);
  perform set_config('workshop.reason', coalesce(v_reason, ''), true);
  perform set_config('workshop.suppress_fields', '', true);

  if v_action = 'permanent_delete' then
    delete from public.workshop_status_records where id = v_r.id;
    return jsonb_build_object('ok', true, 'changed', 1, 'deleted', true, 'record_id', v_r.id);
  end if;

  if v_action = 'disposition' then
    update public.workshop_status_records
       set final_disposition = v_disp, final_disposition_remarks = v_remarks
     where id = v_r.id;
    v_event := 'final_disposition';
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'disposition', v_disp, 'remarks', v_remarks,
      'previous_disposition', v_r.final_disposition));
  elsif v_action = 'restore' then
    update public.workshop_status_records
       set current_active = true,
           daily_report_status = 'restored',
           final_disposition = null,
           final_disposition_remarks = null
     where id = v_r.id;
    v_event := 'restored';
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'message', 'Vehicle restored to the active workshop report.',
      'removed_at', v_r.removed_at,
      'removed_by_upload_id', v_r.removed_by_upload_id,
      'removed_reason', v_r.removed_reason,
      'cleared_disposition', v_r.final_disposition));
  elsif v_action = 'archive' then
    update public.workshop_status_records
       set archived_at = now(), archive_reason = v_reason, daily_report_status = 'archived'
     where id = v_r.id;
    v_event := 'archived';
  elsif v_action = 'unarchive' then
    update public.workshop_status_records
       set archived_at = null, archive_reason = null,
           daily_report_status = 'removed_from_current_report'
     where id = v_r.id;
    v_event := 'unarchived';
  elsif v_action = 'soft_delete' then
    update public.workshop_status_records
       set deleted_at = now(), delete_reason = v_reason
     where id = v_r.id;
    v_event := 'soft_deleted';
  elsif v_action = 'undelete' then
    update public.workshop_status_records
       set deleted_at = null, delete_reason = null
     where id = v_r.id;
    v_event := 'undeleted';
  end if;

  insert into public.workshop_status_events
    (organisation_id, country, site, record_id, asset_no, event_type, source, reason, details)
  values (v_r.organisation_id, v_r.country, v_r.site, v_r.id, v_r.asset_no, v_event, 'manual',
          v_reason, coalesce(v_details, '{}'::jsonb));

  select to_jsonb(r) into v_out from public.workshop_status_records r where r.id = v_r.id;
  return jsonb_build_object('ok', true, 'changed', 1, 'record', v_out);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_record_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source text := public.workshop_status_setting_source();
  v_upload uuid := public.workshop_status_setting_upload();
  v_reason text := public.workshop_status_setting('reason');
  v_suppress text[] := coalesce(string_to_array(replace(coalesce(public.workshop_status_setting('suppress_fields'), ''), ' ', ''), ','), '{}');
  v_fields text[] := array[
    'reg_no', 'job_card_ref', 'vehicle_category', 'site', 'department', 'complaint',
    'diagnostics', 'ooc_since', 'excel_down_days', 'excel_expected_release',
    'excel_status_note', 'source_remarks', 'vehicle_id', 'asset_breakdown_id',
    'current_stage', 'delay_reason', 'detailed_reason', 'work_done', 'action_taken',
    'next_action', 'parts_status', 'mr_number', 'po_number', 'responsible_user_id',
    'supporting_user_id', 'expected_part_date', 'expected_release_date', 'blocker',
    'remarks', 'current_active', 'daily_report_status', 'final_disposition',
    'final_disposition_remarks', 'archived_at', 'deleted_at'];
  v_old jsonb; v_new jsonb; f text;
begin
  if TG_OP = 'DELETE' then
    insert into public.workshop_status_events
      (organisation_id, country, site, record_id, asset_no, upload_id, event_type, source, reason, details)
    values (OLD.organisation_id, OLD.country, OLD.site, OLD.id, OLD.asset_no, v_upload,
            'permanently_deleted', v_source, v_reason, jsonb_build_object('record', to_jsonb(OLD)));
    return OLD;
  end if;
  if TG_OP = 'INSERT' then
    insert into public.workshop_status_events
      (organisation_id, country, site, record_id, asset_no, upload_id, event_type, source, reason, details)
    values (NEW.organisation_id, NEW.country, NEW.site, NEW.id, NEW.asset_no, v_upload,
            'added', v_source, v_reason,
            jsonb_build_object('message', case when v_source = 'excel'
              then 'Vehicle added through Daily Workshop Excel upload.'
              else 'Vehicle added to the workshop report.' end));
    return NEW;
  end if;
  v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  foreach f in array v_fields loop
    if f = any (v_suppress) then continue; end if;
    if (v_old -> f) is distinct from (v_new -> f) then
      insert into public.workshop_status_events
        (organisation_id, country, site, record_id, asset_no, upload_id, event_type,
         field_name, old_value, new_value, source, reason)
      values (NEW.organisation_id, NEW.country, NEW.site, NEW.id, NEW.asset_no, v_upload,
              'field_change', f, v_old ->> f, v_new ->> f, v_source, v_reason);
    end if;
  end loop;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_record_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ctx boolean := public.workshop_status_setting('source') is not null;
  v_source text := public.workshop_status_setting_source();
  v_uid uuid := auth.uid();
  v_name text := coalesce(public.workshop_status_actor_name(), 'System');
begin
  if TG_OP = 'INSERT' then
    NEW.first_seen_by := v_uid;
    NEW.first_seen_at := now();
    NEW.created_at := now();
    NEW.updated_at := now();
    NEW.last_updated_by := v_uid;
    NEW.last_updated_by_name := v_name;
    NEW.last_update_source := v_source;
    NEW.last_manual_update_at := case when v_source = 'manual' then now() end;
    NEW.final_disposition_by := case when NEW.final_disposition is not null then v_uid end;
    NEW.final_disposition_by_name := case when NEW.final_disposition is not null then v_name end;
    NEW.final_disposition_at := case when NEW.final_disposition is not null then now() end;
    NEW.removed_by_user_id := case when NEW.removed_at is not null then v_uid end;
    NEW.archived_by := case when NEW.archived_at is not null then v_uid end;
    NEW.deleted_by := case when NEW.deleted_at is not null then v_uid end;
    return NEW;
  end if;
  if NEW.id <> OLD.id or NEW.organisation_id <> OLD.organisation_id
     or NEW.country <> OLD.country or NEW.asset_no <> OLD.asset_no
     or NEW.first_seen_upload_id is distinct from OLD.first_seen_upload_id
     or NEW.first_seen_at <> OLD.first_seen_at
     or NEW.first_seen_by is distinct from OLD.first_seen_by
     or NEW.created_at <> OLD.created_at then
    raise exception 'The identity of a workshop record cannot be changed' using errcode = '42501';
  end if;
  NEW.updated_at := now();
  if v_ctx then
    NEW.last_updated_by := v_uid;
    NEW.last_updated_by_name := v_name;
    NEW.last_update_source := v_source;
    NEW.last_manual_update_at := case when v_source = 'manual' then now() else OLD.last_manual_update_at end;
  else
    NEW.last_updated_by := OLD.last_updated_by;
    NEW.last_updated_by_name := OLD.last_updated_by_name;
    NEW.last_update_source := OLD.last_update_source;
    NEW.last_manual_update_at := OLD.last_manual_update_at;
  end if;
  if NEW.final_disposition is distinct from OLD.final_disposition
     or NEW.final_disposition_remarks is distinct from OLD.final_disposition_remarks then
    NEW.final_disposition_by := case when NEW.final_disposition is null then null else v_uid end;
    NEW.final_disposition_by_name := case when NEW.final_disposition is null then null else v_name end;
    NEW.final_disposition_at := case when NEW.final_disposition is null then null else now() end;
  else
    NEW.final_disposition_by := OLD.final_disposition_by;
    NEW.final_disposition_by_name := OLD.final_disposition_by_name;
    NEW.final_disposition_at := OLD.final_disposition_at;
  end if;
  if NEW.removed_at is distinct from OLD.removed_at then
    NEW.removed_by_user_id := case when NEW.removed_at is null then null else v_uid end;
  else
    NEW.removed_by_user_id := OLD.removed_by_user_id;
  end if;
  if NEW.archived_at is distinct from OLD.archived_at then
    NEW.archived_by := case when NEW.archived_at is null then null else v_uid end;
  else
    NEW.archived_by := OLD.archived_by;
  end if;
  if NEW.deleted_at is distinct from OLD.deleted_at then
    NEW.deleted_by := case when NEW.deleted_at is null then null else v_uid end;
  else
    NEW.deleted_by := OLD.deleted_by;
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_scope_allows(p_scope jsonb, p_country text, p_site text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (p_country is null
       or coalesce((p_scope ->> 'super')::boolean, false)
       or coalesce((p_scope ->> 'all_countries')::boolean, false)
       or lower(btrim(p_country)) in (select jsonb_array_elements_text(coalesce(p_scope -> 'countries', '[]'::jsonb))))
    and
    (p_site is null or btrim(p_site) = ''
       or coalesce((p_scope ->> 'all_sites')::boolean, false)
       or upper(btrim(p_site)) in (select jsonb_array_elements_text(coalesce(p_scope -> 'sites', '[]'::jsonb)))),
    false)
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_setting(p_key text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(coalesce(current_setting('workshop.' || p_key, true), '')), '')
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_setting_source()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when s in ('excel', 'manual', 'system') then s else 'system' end
    from (select public.workshop_status_setting('source') as s) x
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_setting_upload()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when s ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then s::uuid end
    from (select public.workshop_status_setting('upload_id') as s) x
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_stage_upload(p_country text, p_file_name text, p_file_hash text, p_file_size bigint, p_sheet_name text, p_report_date date, p_header_map jsonb, p_unmapped text[], p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_hash text := nullif(btrim(coalesce(p_file_hash, '')), '');
  v_rows jsonb := coalesce(p_rows, '[]'::jsonb);
  v_n integer;
  v_bad text;
  v_dup record;
  v_id uuid;
  v_no bigint;
  v_prev integer;
begin
  if not coalesce(public.workshop_status_can('upload'), false) then
    raise exception 'You do not have permission to upload the workshop report' using errcode = '42501';
  end if;
  if v_org is null then
    raise exception 'Your account is not linked to an organisation' using errcode = '42501';
  end if;
  if v_country is null then
    raise exception 'Choose the country this workshop report belongs to' using errcode = '22023';
  end if;
  if not coalesce(public.is_super_admin(), false)
     and public.app_can_see_country(v_country) is false then
    raise exception 'You do not have access to the workshop report of this country' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_file_name, '')), '') is null then
    raise exception 'The file name is missing' using errcode = '22023';
  end if;
  if jsonb_typeof(v_rows) <> 'array' then
    raise exception 'The upload rows must be a list' using errcode = '22023';
  end if;
  v_n := jsonb_array_length(v_rows);
  if v_n > 5000 then
    raise exception 'The upload has % rows; the limit is 5000', v_n using errcode = '22023';
  end if;
  select e ->> 'outcome' into v_bad
    from jsonb_array_elements(v_rows) e
   where coalesce(e ->> 'outcome', '') not in
         ('new', 'changed', 'unchanged', 'removed', 'closed', 'invalid', 'duplicate')
   limit 1;
  if found then
    raise exception 'Unknown row outcome: %', coalesce(v_bad, '(blank)') using errcode = '22023';
  end if;

  perform set_config('workshop.source', 'excel', true);
  perform set_config('workshop.reason', '', true);

  select null::uuid as id, null::bigint as upload_no, null::timestamptz as uploaded_at,
         null::text as uploaded_by_name, null::text as status into v_dup;
  if v_hash is not null then
    select u.id, u.upload_no, u.uploaded_at, u.uploaded_by_name, u.status into v_dup
      from public.workshop_status_uploads u
     where u.organisation_id = v_org and u.file_hash = v_hash
       and u.status in ('confirmed', 'previewed')
     order by (u.status = 'confirmed') desc, u.uploaded_at desc, u.upload_no desc
     limit 1;
  end if;

  select count(*)::int into v_prev
    from public.workshop_status_records r
   where r.organisation_id = v_org and r.country = v_country
     and r.current_active and r.deleted_at is null;

  insert into public.workshop_status_uploads
    (organisation_id, country, file_name, file_hash, file_size_bytes, sheet_name, report_date,
     status, header_map, unmapped_headers, previous_active_count, duplicate_of_upload_id,
     total_rows, new_count, updated_count, unchanged_count, removed_count, closed_count,
     invalid_count, duplicate_count)
  select v_org, v_country, btrim(p_file_name), v_hash, p_file_size, nullif(btrim(coalesce(p_sheet_name, '')), ''),
         p_report_date, 'previewed', coalesce(p_header_map, '{}'::jsonb), coalesce(p_unmapped, '{}'),
         v_prev, v_dup.id,
         count(*) filter (where e ->> 'outcome' <> 'removed'),
         count(*) filter (where e ->> 'outcome' = 'new'),
         count(*) filter (where e ->> 'outcome' = 'changed'),
         count(*) filter (where e ->> 'outcome' = 'unchanged'),
         count(*) filter (where e ->> 'outcome' = 'removed'),
         count(*) filter (where e ->> 'outcome' = 'closed'),
         count(*) filter (where e ->> 'outcome' = 'invalid'),
         count(*) filter (where e ->> 'outcome' = 'duplicate')
    from jsonb_array_elements(v_rows) e
  returning id, upload_no into v_id, v_no;

  perform set_config('workshop.upload_id', v_id::text, true);

  insert into public.workshop_status_upload_rows
    (upload_id, row_number, section, asset_no, site, outcome, data, raw, changes, errors, record_id)
  select v_id,
         public.workshop_status_jint(e ->> 'row_number'),
         public.workshop_status_jtext(e, 'section'),
         public.workshop_status_asset_key(e ->> 'asset_no'),
         public.workshop_status_jtext(e, 'site'),
         e ->> 'outcome',
         case when jsonb_typeof(e -> 'data') = 'object' then e -> 'data' else '{}'::jsonb end,
         case when jsonb_typeof(e -> 'raw') = 'object' then e -> 'raw' else '{}'::jsonb end,
         case when jsonb_typeof(e -> 'changes') = 'object' then e -> 'changes' else '{}'::jsonb end,
         case when jsonb_typeof(e -> 'errors') = 'array'
              then array(select jsonb_array_elements_text(e -> 'errors')) else '{}'::text[] end,
         case when (e ->> 'record_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (e ->> 'record_id')::uuid end
    from jsonb_array_elements(v_rows) with ordinality as t(e, ord)
   order by ord;

  insert into public.workshop_status_events (organisation_id, country, upload_id, event_type, source, details)
  values (v_org, v_country, v_id, 'upload_previewed', 'excel',
          jsonb_build_object('file_name', btrim(p_file_name), 'rows', v_n,
                             'duplicate_of_upload_id', v_dup.id));

  return jsonb_build_object(
    'upload_id', v_id,
    'upload_no', v_no,
    'duplicate_of', case when v_dup.id is null then null else jsonb_build_object(
      'id', v_dup.id, 'upload_no', v_dup.upload_no, 'uploaded_at', v_dup.uploaded_at,
      'uploaded_by_name', v_dup.uploaded_by_name, 'status', v_dup.status) end);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_update_record(p_record_id uuid, p_patch jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid := public.app_current_org();
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb);
  v_allowed text[] := array[
    'current_stage', 'delay_reason', 'detailed_reason', 'work_done', 'action_taken',
    'next_action', 'parts_status', 'mr_number', 'po_number', 'responsible_user_id',
    'supporting_user_id', 'expected_part_date', 'expected_release_date', 'blocker', 'remarks'];
  v_text_fields text[] := array['detailed_reason', 'work_done', 'action_taken', 'next_action',
    'blocker', 'remarks'];
  v_ref_fields text[] := array['mr_number', 'po_number'];
  v_r public.workshop_status_records%rowtype;
  v_old jsonb;
  v_new jsonb;
  v_key text;
  v_raw text;
  v_val text;
  v_date date;
  v_changed text[] := '{}';
  v_out jsonb;
begin
  if not coalesce(public.workshop_status_can('update'), false) then
    raise exception 'You do not have permission to update workshop vehicles' using errcode = '42501';
  end if;
  if v_org is null then
    raise exception 'Your account is not linked to an organisation' using errcode = '42501';
  end if;
  if p_record_id is null then
    raise exception 'Choose a vehicle to update' using errcode = '22023';
  end if;
  if jsonb_typeof(v_patch) <> 'object' then
    raise exception 'The update must be a set of named fields' using errcode = '22023';
  end if;

  select k into v_key from jsonb_object_keys(v_patch) k where not (k = any (v_allowed)) limit 1;
  if found then
    raise exception 'This field cannot be changed here: %', v_key using errcode = '22023';
  end if;

  select * into v_r from public.workshop_status_records where id = p_record_id for update;
  if not found or v_r.organisation_id <> v_org or not v_r.current_active or v_r.deleted_at is not null
     or not (
       coalesce(public.is_super_admin(), false)
       or v_r.country is null
       or coalesce(public.app_sees_all_countries(), false)
       or lower(btrim(v_r.country)) = any (coalesce(public.app_country_scope(), '{}'::text[])))
     or not (
       v_r.site is null or btrim(v_r.site) = ''
       or coalesce(public.app_sees_all_sites(), false)
       or upper(btrim(v_r.site)) = any (coalesce(public.app_site_scope(), '{}'::text[]))) then
    raise exception 'Workshop vehicle not found' using errcode = 'P0002';
  end if;

  if p_expected_updated_at is not null and v_r.updated_at is distinct from p_expected_updated_at then
    raise exception 'record_changed: this vehicle was updated by someone else' using errcode = 'PT409';
  end if;

  v_old := to_jsonb(v_r);
  v_new := v_old;

  foreach v_key in array v_allowed loop
    continue when not (v_patch ? v_key);
    v_raw := case when jsonb_typeof(v_patch -> v_key) = 'null' then null else v_patch ->> v_key end;
    v_val := nullif(btrim(coalesce(v_raw, '')), '');

    if v_key = 'current_stage' and v_val is not null
       and not (v_val = any (public.workshop_status_manual_vocab('stage'))) then
      raise exception 'Choose a current stage from the list' using errcode = '22023';
    elsif v_key = 'delay_reason' and v_val is not null
       and not (v_val = any (public.workshop_status_manual_vocab('delay'))) then
      raise exception 'Choose a delay reason from the list' using errcode = '22023';
    elsif v_key = 'parts_status' and v_val is not null
       and not (v_val = any (public.workshop_status_manual_vocab('parts'))) then
      raise exception 'Choose a parts status from the list' using errcode = '22023';
    elsif v_key = any (v_text_fields) and length(v_val) > 4000 then
      raise exception 'The text is too long (4000 characters at most)' using errcode = '22023';
    elsif v_key = any (v_ref_fields) and length(v_val) > 100 then
      raise exception 'The reference number is too long (100 characters at most)' using errcode = '22023';
    elsif v_key in ('expected_part_date', 'expected_release_date') and v_val is not null then
      begin
        if v_val !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'bad'; end if;
        v_date := v_val::date;
      exception when others then
        raise exception 'Enter a valid date (yyyy-mm-dd)' using errcode = '22023';
      end;
      if v_date < date '2000-01-01' or v_date > date '2100-12-31' then
        raise exception 'Enter a realistic date' using errcode = '22023';
      end if;
      v_val := v_date::text;
    elsif v_key in ('responsible_user_id', 'supporting_user_id') and v_val is not null then
      if v_val !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise exception 'Choose a person from the list' using errcode = '22023';
      end if;
      v_val := lower(v_val);
    end if;

    v_new := jsonb_set(v_new, array[v_key], coalesce(to_jsonb(v_val), 'null'::jsonb));
    if (v_old -> v_key) is distinct from (v_new -> v_key) then
      v_changed := v_changed || v_key;
    end if;
  end loop;

  if (v_patch ? 'delay_reason' or v_patch ? 'detailed_reason')
     and (v_new ->> 'delay_reason') = 'Other'
     and nullif(btrim(coalesce(v_new ->> 'detailed_reason', '')), '') is null then
    raise exception 'A detailed reason is required when the delay reason is Other' using errcode = '22023';
  end if;

  if array_length(v_changed, 1) is null then
    return jsonb_build_object('ok', true, 'changed', 0, 'fields', '[]'::jsonb);
  end if;

  if ('responsible_user_id' = any (v_changed) or 'supporting_user_id' = any (v_changed))
     and not coalesce(public.workshop_status_can('assign'), false) then
    raise exception 'You do not have permission to assign workshop vehicles' using errcode = '42501';
  end if;
  foreach v_key in array array['responsible_user_id', 'supporting_user_id'] loop
    continue when not (v_key = any (v_changed)) or (v_new ->> v_key) is null;
    if not exists (select 1 from public.profiles p
                    where p.id = (v_new ->> v_key)::uuid
                      and p.organisation_id = v_org
                      and coalesce(p.approved, false)
                      and not coalesce(p.locked, false)) then
      raise exception 'Choose an approved person from your organisation' using errcode = '22023';
    end if;
  end loop;

  perform set_config('workshop.source', 'manual', true);
  perform set_config('workshop.upload_id', '', true);
  perform set_config('workshop.reason', '', true);
  perform set_config('workshop.suppress_fields', '', true);

  update public.workshop_status_records set
    current_stage         = v_new ->> 'current_stage',
    delay_reason          = v_new ->> 'delay_reason',
    detailed_reason       = v_new ->> 'detailed_reason',
    work_done             = v_new ->> 'work_done',
    action_taken          = v_new ->> 'action_taken',
    next_action           = v_new ->> 'next_action',
    parts_status          = v_new ->> 'parts_status',
    mr_number             = v_new ->> 'mr_number',
    po_number             = v_new ->> 'po_number',
    responsible_user_id   = (v_new ->> 'responsible_user_id')::uuid,
    supporting_user_id    = (v_new ->> 'supporting_user_id')::uuid,
    expected_part_date    = (v_new ->> 'expected_part_date')::date,
    expected_release_date = (v_new ->> 'expected_release_date')::date,
    blocker               = v_new ->> 'blocker',
    remarks               = v_new ->> 'remarks'
  where id = v_r.id;

  insert into public.workshop_status_events
    (organisation_id, country, site, record_id, asset_no, event_type, source, details)
  values (v_r.organisation_id, v_r.country, v_r.site, v_r.id, v_r.asset_no, 'manual_update', 'manual',
          jsonb_build_object('changed_fields', to_jsonb(v_changed), 'changed', array_length(v_changed, 1)));

  select to_jsonb(r)
         || jsonb_build_object(
              'last_updated_at', r.updated_at,
              'responsible_user_name', (select coalesce(nullif(btrim(p.full_name), ''), p.username)
                                          from public.profiles p where p.id = r.responsible_user_id),
              'supporting_user_name', (select coalesce(nullif(btrim(p.full_name), ''), p.username)
                                         from public.profiles p where p.id = r.supporting_user_id))
    into v_out
    from public.workshop_status_records r where r.id = v_r.id;

  return jsonb_build_object('ok', true, 'changed', array_length(v_changed, 1),
                            'fields', to_jsonb(v_changed), 'record', v_out);
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_upload_row_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  select u.organisation_id, u.country into NEW.organisation_id, NEW.country
    from public.workshop_status_uploads u where u.id = NEW.upload_id;
  NEW.created_at := now();
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_upload_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if TG_OP = 'INSERT' then
    NEW.uploaded_by := auth.uid();
    NEW.uploaded_by_name := coalesce(public.workshop_status_actor_name(), 'System');
    NEW.uploaded_at := now();
    NEW.confirmed_by := null; NEW.confirmed_by_name := null; NEW.confirmed_at := null;
    NEW.cancelled_by := null; NEW.cancelled_at := null;
    return NEW;
  end if;
  NEW.uploaded_by := OLD.uploaded_by;
  NEW.uploaded_by_name := OLD.uploaded_by_name;
  NEW.uploaded_at := OLD.uploaded_at;
  NEW.organisation_id := OLD.organisation_id;
  NEW.country := OLD.country;
  NEW.file_hash := OLD.file_hash;
  if OLD.status in ('confirmed', 'cancelled') and NEW.status is distinct from OLD.status then
    raise exception 'A % upload cannot change status', OLD.status using errcode = '42501';
  end if;
  if NEW.status = 'confirmed' and OLD.status is distinct from 'confirmed' then
    NEW.confirmed_by := auth.uid();
    NEW.confirmed_by_name := coalesce(public.workshop_status_actor_name(), 'System');
    NEW.confirmed_at := now();
  else
    NEW.confirmed_by := OLD.confirmed_by;
    NEW.confirmed_by_name := OLD.confirmed_by_name;
    NEW.confirmed_at := OLD.confirmed_at;
  end if;
  if NEW.status = 'cancelled' and OLD.status is distinct from 'cancelled' then
    NEW.cancelled_by := auth.uid();
    NEW.cancelled_at := now();
  else
    NEW.cancelled_by := OLD.cancelled_by;
    NEW.cancelled_at := OLD.cancelled_at;
  end if;
  return NEW;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.workshop_status_wait_category(p_stage text, p_delay text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_delay in ('Waiting for Spare Parts', 'Spare Parts Not Available', 'MR Pending', 'PO Pending',
                     'Supplier Delivery Pending') or p_stage = 'Waiting for Parts' then 'parts'
    when p_delay in ('Waiting for Manpower', 'Technician Not Available', 'Specialist Technician Required')
         or p_stage = 'Waiting for Manpower' then 'manpower'
    when p_delay in ('Waiting for Approval', 'Waiting for Budget Approval')
         or p_stage = 'Waiting for Approval' then 'approval'
  end
$function$;
-- @@
CREATE OR REPLACE FUNCTION workforce_internal.assignment_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_tokens jsonb; v_event bigint;
BEGIN
  INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
  VALUES(NEW.assigned_to,'info','New work assignment',left(NEW.title,240),
         'workforce_assignment',NEW.id);
  BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'user_id', NEW.assigned_to, 'push_token', tok)), '[]'::jsonb)
      INTO v_tokens FROM public._user_push_tokens(NEW.assigned_to) tok;
    IF jsonb_array_length(v_tokens)>0 THEN
      INSERT INTO public.domain_events(
        event_type,entity_type,entity_id,organisation_id,actor_id,payload,status)
      VALUES('workforce.assignment_push','workforce_assignment',NEW.id::text,
             NEW.organisation_id,NEW.assigned_by,
             jsonb_build_object('assignment_id',NEW.id),'processed')
      RETURNING id INTO v_event;
      INSERT INTO public.workflow_notifications(
        event_id,organisation_id,instance_id,event_type,payload,
        recipient_count,status)
      VALUES(v_event,NEW.organisation_id,NULL,'workforce.assignment_push',
             jsonb_build_object(
               'event_type','workforce.assignment_push',
               'entity_type','workforce_assignment',
               'entity_id',NEW.id,
               'link','/workforce-daily',
               'push',jsonb_build_object('title','New work assignment',
                                        'body',left(NEW.title,240)),
               'recipients',v_tokens),
             jsonb_array_length(v_tokens),'pending');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Workforce assignment push could not be enqueued';
  END;
  RETURN NEW;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION workforce_internal.assignment_reassign_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_tokens jsonb; v_event bigint;
BEGIN
  BEGIN
    INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
    VALUES(NEW.assigned_to,'info','Work handed over to you',left(NEW.title,240),'workforce_assignment',NEW.id);
    IF OLD.assigned_to IS NOT NULL THEN
      INSERT INTO public.notifications(user_id,type,title,body,entity_type,entity_id)
      VALUES(OLD.assigned_to,'info','Work reassigned to a colleague',left(NEW.title,240),'workforce_assignment',NEW.id);
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',NEW.assigned_to,'push_token',tok)),'[]'::jsonb)
      INTO v_tokens FROM public._user_push_tokens(NEW.assigned_to) tok;
    IF jsonb_array_length(v_tokens)>0 THEN
      INSERT INTO public.domain_events(event_type,entity_type,entity_id,organisation_id,actor_id,payload,status)
      VALUES('workforce.assignment_push','workforce_assignment',NEW.id::text,NEW.organisation_id,auth.uid(),
             jsonb_build_object('assignment_id',NEW.id,'reassigned',true),'processed')
      RETURNING id INTO v_event;
      INSERT INTO public.workflow_notifications(event_id,organisation_id,instance_id,event_type,payload,recipient_count,status)
      VALUES(v_event,NEW.organisation_id,NULL,'workforce.assignment_push',
             jsonb_build_object('event_type','workforce.assignment_push','entity_type','workforce_assignment',
               'entity_id',NEW.id,'link','/workforce-daily',
               'push',jsonb_build_object('title','Work handed over to you','body',left(NEW.title,240)),
               'recipients',v_tokens),
             jsonb_array_length(v_tokens),'pending');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Workforce reassignment notification could not be enqueued';
  END;
  RETURN NEW;
END $function$;
